var strongsGreekDictionary = {"G1615":{"strongs_def":" to complete fully","derivation":"from G1537 (ἐκ) and G5055 (τελέω);","translit":"ekteléō","lemma":"ἐκτελέω","kjv_def":"finish","pron":"ek-tel-eh'-o","pos":"Verb","thayer":"<ol><li>to finish, complete</li></ol>","xlit":"ekteléō"},"G2274":{"strongs_def":" to make worse, i.e. vanquish (literally or figuratively); by implication, to rate lower","derivation":"from the same as G2276 (ἥττον);","translit":"hēttáō","lemma":"ἡττάω","kjv_def":"be inferior, overcome","pron":"hayt-tah'-o","pos":"Verb","thayer":"<ol><li>to make less, inferior, to overcome<ol type='a'><li>to be made inferior</li><li>to overcome, worsted, to be conquered by one, forced to yield to one</li><li>to hold a thing inferior, set below</li></ol></li></ol>","xlit":"hēttáō"},"G4533":{"derivation":"of Hebrew origin (H08012);","strongs_def":" Salmon, an Israelite","kjv_def":"Salmon","translit":"Salmṓn","lemma":"Σαλμών","pron":"sal-mone'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Salmon = \"raiment: a garment\"</p><ol><li>the father of Boaz in the genealogy of Christ</li></ol>","xlit":"Salmṓn"},"G5073":{"lemma":"τετραπλόος","translit":"tetraplóos","kjv_def":"fourfold","strongs_def":" quadruple","derivation":"from G5064 (τέσσαρες) and a derivative of the base of G4118 (πλεῖστος);","pron":"tet-rap-lo'-os","pos":"Adjective","thayer":"<ol><li>quadruple, fourfold</li></ol>","xlit":"tetraplóos"},"G3892":{"strongs_def":" transgression","derivation":"from the same as G3891 (παρανομέω);","translit":"paranomía","lemma":"παρανομία","kjv_def":"iniquity","pron":"par-an-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>breach of law, transgression, wickedness</li></ol>","xlit":"paranomía"},"G2928":{"lemma":"κρύπτω","translit":"krýptō","kjv_def":"hide (self), keep secret, secret(-ly)","strongs_def":" to conceal (properly, by covering)","derivation":"a primary verb;","pron":"kroop'-to","pos":"Verb","thayer":"<ol><li>to hide, conceal, to be hid</li><li>escape notice</li><li>metaphorically to conceal (that it may not become known)</li></ol>","xlit":"krýptō"},"G1966":{"kjv_def":"following, next","translit":"epioûsa","lemma":"ἐπιοῦσα","derivation":"feminine singular participle of a comparative of G1909 (ἐπί) and (to go);","strongs_def":" supervening, i.e. (G2250 (ἡμέρα) or G3571 (νύξ) being expressed or implied) the ensuing day or night","pron":"ep-ee-oo'-sah","thayer":"<ol><li>to come upon, approach<ol type='a'><li>of time, to come on, be at hand, next, following, on the following day</li></ol></li></ol>","xlit":"epioûsa"},"G1716":{"kjv_def":"spit (upon)","translit":"emptýō","lemma":"ἐμπτύω","derivation":"from G1722 (ἐν) and G4429 (πτύω);","strongs_def":" to spit at or on","pron":"emp-too'-o","pos":"Verb","thayer":"<ol><li>to spit upon</li></ol>","xlit":"emptýō"},"G4641":{"translit":"sklērokardía","lemma":"σκληροκαρδία","kjv_def":"hardness of heart","strongs_def":" hard-heartedness, i.e. (specially), destitution of (spiritual) perception","derivation":"feminine of a compound of G4642 (σκληρός) and G2588 (καρδία);","pron":"sklay-rok-ar-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>hardness of heart</li></ol>","xlit":"sklērokardía"},"G506":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G5293 (ὑποτάσσω);","strongs_def":" unsubdued, i.e. insubordinate (in fact or temper)","kjv_def":"disobedient, that is not put under, unruly","translit":"anypótaktos","lemma":"ἀνυπότακτος","pron":"an-oo-pot'-ak-tos","pos":"Adjective","thayer":"<ol><li>not made subject, unsubjected</li><li>that cannot be subjected to control, disobedient, unruly, refractory</li></ol>","xlit":"anypótaktos"},"G4181":{"derivation":"adverb from a compound of G4183 (πολύς) and G3313 (μέρος);","strongs_def":" in many portions, i.e. variously as to time and agency (piecemeal)","kjv_def":"at sundry times","lemma":"πολυμερῶς","translit":"polymerōs","pron":"pol-oo-mer'-oce","pos":"Adverb","thayer":"<ol><li>by many portions, by many times and in many ways</li></ol>","xlit":"polymerōs"},"G2577":{"derivation":"apparently a primary verb;","strongs_def":" properly, to toil, i.e. (by implication) to tire (figuratively, faint, sicken)","kjv_def":"faint, sick, be wearied","lemma":"κάμνω","translit":"kámnō","pron":"kam'-no","pos":"Verb","thayer":"<ol><li>to grow weary, be weary</li><li>to be sick</li></ol>","xlit":"kámnō"},"G3634":{"kjv_def":"so (as), such as, what (manner of), which","lemma":"οἷος","translit":"hoîos","derivation":"probably akin to G3588 (ὁ), G3739 (ὅς), and G3745 (ὅσος);","strongs_def":" such or what sort of (as a correlation or exclamation); especially the neuter (adverbially) with negative, not so","pron":"hoy'-os","thayer":"<ol><li>what sort of, what manner of, such as</li></ol>","xlit":"hoîos"},"G605":{"derivation":"from G600 (ἀποκαθίστημι);","strongs_def":" reconstitution","kjv_def":"restitution","lemma":"ἀποκατάστασις","translit":"apokatástasis","pron":"ap-ok-at-as'-tas-is","pos":"Noun Feminine","thayer":"<ol><li>restoration<ol type='a'><li>of a true theocracy</li><li>of the perfect state before the fall</li></ol></li></ol>","xlit":"apokatástasis"},"G5125":{"translit":"toútois","lemma":"τούτοις","kjv_def":"such, them, there(-in, -with), these, this, those","strongs_def":" to (for, in, with or by) these (persons or things)","derivation":"dative case plural masculine or neuter of G3778 (οὗτος);","pron":"too'-toice","thayer":"<ol><li>these</li></ol>","xlit":"toútois"},"G2258":{"kjv_def":"+ agree, be, X have (+ charge of), hold, use, was(-t), were","lemma":"ἦν","translit":"ēn","derivation":"imperfect of G1510 (εἰμί);","strongs_def":" I (thou, etc.) was (wast or were)","pron":"ane","pos":"Verb","thayer":"<ol><li>I was, etc.</li></ol>","xlit":"ēn"},"G2704":{"translit":"kataphtheírō","lemma":"καταφθείρω","kjv_def":"--corrupt, utterly perish","strongs_def":" to spoil entirely, i.e. (literally) to destroy; or (figuratively) to deprave; ","derivation":"from G2596 (κατά) and G5351 (φθείρω);","pron":"kat-af-thi'-ro","pos":"Verb","thayer":"<ol><li>to corrupt, deprave<ol type='a'><li>corrupted in mind</li></ol><li>to destroy<ol type='a'><li>to be destroyed, to perish</li></ol></li></ol>","xlit":"kataphtheírō"},"G424":{"derivation":"from G303 (ἀνά) and G2064 (ἔρχομαι);","strongs_def":" to ascend","kjv_def":"go up","lemma":"ἀνέρχομαι","translit":"anérchomai","pron":"an-erkh'-om-ahee","pos":"Verb","thayer":"<ol><li>to go up</li><li>to go up to a higher place: to Jerusalem</li></ol>","xlit":"anérchomai"},"G5309":{"kjv_def":"be highminded","translit":"hypsēlophronéō","lemma":"ὑψηλοφρονέω","derivation":"from a compound of G5308 (ὑψηλός) and G5424 (φρήν);","strongs_def":" to be lofty in mind, i.e. arrogant","pron":"hoop-say-lo-fron-eh'-o","pos":"Verb","thayer":"<ol><li>to be high minded, proud</li></ol>","xlit":"hypsēlophronéō"},"G1484":{"kjv_def":"Gentile, heathen, nation, people","lemma":"ἔθνος","translit":"éthnos","derivation":"probably from G1486 (ἔθω);","strongs_def":" a race (as of the same habit), i.e. a tribe; specially, a foreign (non-Jewish) one (usually, by implication, pagan)","pron":"eth'-nos","pos":"Noun Neuter","thayer":"<ol><li>a multitude (whether of men or of beasts) associated or living together<ol type='a'><li>a company, troop, swarm</li></ol><li>a multitude of individuals of the same nature or genus<ol type='a'><li>the human family</li></ol><li>a tribe, nation, people group</li><li>in the OT, foreign nations not worshipping the true God, pagans, Gentiles</li><li>Paul uses the term for Gentile Christians</li></ol>","xlit":"éthnos"},"G2256":{"translit":"hēmiṓrion","lemma":"ἡμιώριον","kjv_def":"half an hour","strongs_def":" a half-hour","derivation":"from the base of G2255 (ἥμισυ) and G5610 (ὥρα);","pron":"hay-mee-o'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>half an hour</li></ol>","xlit":"hēmiṓrion"},"G3691":{"strongs_def":" keen; by analogy, rapid","derivation":"probably akin to the base of G188 (ἀκμήν) (\"acid\");","translit":"oxýs","lemma":"ὀξύς","kjv_def":"sharp, swift","pron":"oz-oos'","pos":"Adjective","thayer":"<ol><li>sharp</li><li>swift, quick</li></ol>","xlit":"oxýs"},"G908":{"lemma":"βάπτισμα","translit":"báptisma","kjv_def":"baptism","strongs_def":" baptism (technically or figuratively)","derivation":"from G907 (βαπτίζω);","pron":"bap'-tis-mah","pos":"Noun Neuter","thayer":"<ol><li>immersion, submersion<ol type='a'><li>of calamities and afflictions with which one is quite overwhelmed</li><li>of John's baptism, that purification rite by which men on confessing their sins were bound to spiritual reformation, obtained the pardon of their past sins and became qualified for the benefits of the Messiah's kingdom soon to be set up. This was valid Christian baptism, as this was the only baptism the apostles received and it is not recorded anywhere that they were ever rebaptised after Pentecost.</li><li>of Christian baptism; a rite of immersion in water ascommanded by Christ, by which one after confessing his sins and professing his faith in Christ, having been born again by the Holy Spirit unto a new life, identifies publicly with the fellowship of Christ and the church.</li></ol></li></ol>","xlit":"báptisma"},"G1604":{"strongs_def":" completion","derivation":"from G1603 (ἐκπληρόω);","lemma":"ἐκπλήρωσις","translit":"ekplḗrōsis","kjv_def":"accomplishment","pron":"ek-play'-ro-sis","pos":"Noun Feminine","thayer":"<ol><li>a completing, fulfilment</li></ol>","xlit":"ekplḗrōsis"},"G2594":{"strongs_def":" to be strong, i.e. (figuratively) steadfast (patient)","derivation":"from a derivative of G2904 (κράτος) (transposed);","translit":"karteréō","lemma":"καρτερέω","kjv_def":"endure","pron":"kar-ter-eh'-o","pos":"Verb","thayer":"<ol><li>to be steadfast</li></ol>","xlit":"karteréō"},"G13":{"lemma":"Ἄγαβος","translit":"Ágabos","kjv_def":"Agabus","strongs_def":" Agabus, an Israelite","derivation":"of Hebrew origin (compare H02285);","pron":"ag'-ab-os","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Agabus = \"locust\"</p><ol><li>a Christian prophet</li></ol>","xlit":"Ágabos"},"G2660":{"kjv_def":"prick","lemma":"κατανύσσω","translit":"katanýssō","derivation":"from G2596 (κατά) and G3572 (νύσσω);","strongs_def":" to pierce thoroughly, i.e. (figuratively) to agitate violently (\"sting to the quick\")","pron":"kat-an-oos'-so","pos":"Verb","thayer":"<ol><li>to prick, pierce</li><li>metaphorically to pain the mind sharply, agitate it vehemently<ol type='a'><li>especially of the emotion of sorrow</li></ol></li></ol>","xlit":"katanýssō"},"G5508":{"translit":"Chíos","lemma":"Χίος","kjv_def":"Chios","strongs_def":" Chios, an island in the Mediterranean","derivation":"of uncertain derivation;","pron":"khee'-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Chios = \"snowy\"</p><ol><li>is an island in the Aegean, between Samos and Lesbos, not far from the shore of Lydia</li></ol>","xlit":"Chíos"},"G4270":{"lemma":"προγράφω","translit":"prográphō","kjv_def":"before ordain, evidently set forth, write (afore, aforetime)","strongs_def":" to write previously; figuratively, to announce, prescribe","derivation":"from G4253 (πρό) and G1125 (γράφω);","pron":"prog-raf'-o","pos":"Verb","thayer":"<ol><li>to write before (of time)<ol type='a'><li>of old set forth or designated before hand (in the scriptures of the OT)</li></ol><li>to depict or portray openly<ol type='a'><li>to write before the eyes of all who can read</li><li>to depict, portray, paint, before the eyes</li></ol></li></ol>","xlit":"prográphō"},"G3712":{"translit":"orguiá","lemma":"ὀργυιά","kjv_def":"fathom","strongs_def":" a stretch of the arms, i.e. a fathom","derivation":"from G3713 (ὀρέγομαι);","pron":"org-wee-ah'","pos":"Noun Feminine","thayer":"<ol><li>fathom, the distance across the breast from the tip of one middle finger to the tip of the other when the arms are outstretched, 5 to 6 feet (2 m)</li></ol>","xlit":"orguiá"},"G968":{"strongs_def":" a step, i.e. foot-breath; by implication, a rostrum, i.e. a tribunal","derivation":"from the base of G939 (βάσις);","translit":"bēma","lemma":"βῆμα","kjv_def":"judgment-seat, set (foot) on, throne","pron":"bay'-ma","pos":"Noun Neuter","thayer":"<ol><li>a step, pace, the space which a foot covers, a foot-breath</li><li>a raised place mounted by steps<ol type='a'><li>a platform, tribune<ol><li>of the official seat of a judge</li><li>of the judgment seat of Christ</li><li>Herod built a structure resembling a throne at Caesarea, from which he viewed the games and made speeches to the people</li></ol></li></ol></li></ol>","xlit":"bēma"},"G3546":{"derivation":"from G3543 (νομίζω);","strongs_def":" what is reckoned as of value (after the Latin numisma), i.e. current coin","kjv_def":"money","lemma":"νόμισμα","translit":"nómisma","pron":"nom'-is-mah","pos":"Noun Neuter","thayer":"<ol><li>anything received and sanctioned by usage or law</li><li>money, (current) coin, legal tender</li></ol>","xlit":"nómisma"},"G4237":{"strongs_def":" a garden plot, i.e. (by implication, of regular beds) a row (repeated in plural by Hebraism, to indicate an arrangement)","derivation":"perhaps from (a leek, and so an onion-patch);","lemma":"πρασιά","translit":"prasiá","kjv_def":"in ranks","pron":"pras-ee-ah'","pos":"Noun Feminine","thayer":"<ol><li>a plot of ground, a garden bed</li><li>Hebrew idiom, i.e. they reclined in ranks or divisions, so that several ranks formed, as it were separate plots</li></ol>","xlit":"prasiá"},"G2583":{"lemma":"κανών","translit":"kanṓn","kjv_def":"line, rule","strongs_def":" a rule (\"canon\"), i.e. (figuratively) a standard (of faith and practice); by implication, a boundary, i.e. (figuratively) a sphere (of activity)","derivation":"from (a straight reed, i.e. rod);","pron":"kan-ohn'","pos":"Noun Masculine","thayer":"<ol><li>a rod or straight piece of rounded wood to which any thing is fastened to keep it straight<ol type='a'><li>used for various purposes<ol><li>a measuring rod, rule</li><li>a carpenter's line or measuring tape</li><li>the measure of a leap, as in the Olympic games</li></ol></li></ol><li>a definitely bounded or fixed space within the limits of which one's power of influence is confined<ol type='a'><li>the province assigned one</li><li>one's sphere of activity</li></ol><li>metaphorically any rule or standard, a principle or law of investigating, judging, living, acting</li></ol>","xlit":"kanṓn"},"G1588":{"kjv_def":"chosen, elect","translit":"eklektós","lemma":"ἐκλεκτός","derivation":"from G1586 (ἐκλέγομαι);","strongs_def":" select; by implication, favorite","pron":"ek-lek-tos'","pos":"Adjective","thayer":"<ol><li>picked out, chosen<ol type='a'><li>chosen by God<ol><li>to obtain salvation through Christ<ol type='a'><li>Christians are called \"chosen or elect\" of God</li></ol><li>the Messiah in called \"elect\" , as appointed by God to the most exalted office conceivable</li><li>choice, select, i.e. the best of its kind or class, excellence preeminent: applied to certain individual Christians</li></ol></li></ol></li></ol>","xlit":"eklektós"},"G5134":{"derivation":"from the base of (to wound;","strongs_def":" akin to the base of G2352 (θραύω), G5147 (τρίβος), G5149 (τρίζω), etc.); a wound","kjv_def":"wound","translit":"traûma","lemma":"τραῦμα","pron":"trow'-mah","pos":"Neuter","thayer":"<ol><li>a wound</li></ol>","xlit":"traûma"},"G1179":{"strongs_def":" the ten-city region; the Decapolis, a district in Syria","derivation":"from G1176 (δέκα) and G4172 (πόλις);","translit":"Dekápolis","lemma":"Δεκάπολις","kjv_def":"Decapolis","pron":"dek-ap'-ol-is","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Decapolis = \"ten cities\"</p><ol><li>a track of land so called from the ten cities that were in it<ol type='a'><li>according to Pliny, these cities were: Damascus, Opoton, Philadelphia, Raphana, Scythopolis, Gadara, Hippondion, Pella, Galasa, and Canatha (Gill)</li></ol></li></ol>","xlit":"Dekápolis"},"G453":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G3539 (νοιέω);","strongs_def":" unintelligent; by implication, sensual","kjv_def":"fool(-ish), unwise","translit":"anóētos","lemma":"ἀνόητος","pron":"an-o'-ay-tos","pos":"Adjective","thayer":"<ol><li>not understood, unintelligible</li><li>not understanding, unwise, foolish</li></ol>","xlit":"anóētos"},"G2949":{"derivation":"from (to swell (with young), i.e. bend, curve);","strongs_def":" a billow (as bursting or toppling)","kjv_def":"wave","lemma":"κῦμα","translit":"kŷma","pron":"koo'-mah","pos":"Noun Neuter","thayer":"<ol><li>a wave (swell) especially of the sea or of a lake<ol type='a'><li>of impulse and restless men, tossed to and fro by their raging passions</li></ol></li></ol>","xlit":"kŷma"},"G3782":{"derivation":"from G3784 (ὀφείλω);","strongs_def":" indebtedness, i.e. (concretely) a sum owed; figuratively, obligation, i.e. (conjugal) duty","kjv_def":"debt, due","translit":"opheilḗ","lemma":"ὀφειλή","pron":"of-i-lay'","pos":"Noun Feminine","thayer":"<ol><li>that which is owed</li><li>a debt</li><li>metaphorically dues: specifically of conjugal duty</li></ol>","xlit":"opheilḗ"},"G4131":{"lemma":"πλήκτης","translit":"plḗktēs","kjv_def":"striker","strongs_def":" a smiter, i.e. pugnacious (quarrelsome)","derivation":"from G4141 (πλήσσω);","pron":"plake'-tace","pos":"Noun Masculine","thayer":"<ol><li>bruiser, ready for a blow</li><li>a pugnacious, contentious, quarrelsome person</li></ol>","xlit":"plḗktēs"},"G527":{"strongs_def":" soft","derivation":"of uncertain derivation;","translit":"apalós","lemma":"ἀπαλός","kjv_def":"tender","pron":"ap-al-os'","pos":"Adjective","thayer":"<ol><li>tender<ol type='a'><li>of a branch of a tree that is full of sap</li></ol></li></ol>","xlit":"apalós"},"G3094":{"translit":"Magdalēnḗ","lemma":"Μαγδαληνή","kjv_def":"Magdalene","strongs_def":" a female Magdalene, i.e. inhabitant of Magdala","derivation":"feminine of a derivative of G3093 (Μαγδαλά);","pron":"mag-dal-ay-nay'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Magdalene = \"a tower\"</p><ol><li>a name given to Mary Magdalene, identifying her as from Magdala</li></ol>","xlit":"Magdalēnḗ"},"G4831":{"kjv_def":"follower together","translit":"symmimētḗs","lemma":"συμμιμητής","derivation":"from a presumed compound of G4862 (σύν) and G3401 (μιμέομαι);","strongs_def":" a co-imitator, i.e. fellow votary","pron":"soom-mim-ay-tace'","pos":"Noun Masculine","thayer":"<ol><li>an imitator of others</li></ol>","xlit":"symmimētḗs"},"G5385":{"derivation":"from G5386 (φιλόσοφος);","strongs_def":" \"philosophy\", i.e. (specially), Jewish sophistry","kjv_def":"philosophy","lemma":"φιλοσοφία","translit":"philosophía","pron":"fil-os-of-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>love of wisdom<ol type='a'><li>used either of zeal for or skill in any art or science, any branch of knowledge. Used once in the NT of the theology, or rather theosophy, of certain Jewish Christian ascetics, which busied itself with refined and speculative enquiries into the nature and classes of angels, into the ritual of the Mosaic law and the regulations of Jewish tradition respecting practical life</li></ol></li></ol>","xlit":"philosophía"},"G3779":{"kjv_def":"after that, after (in) this manner, as, even (so), for all that, like(-wise), no more, on this fashion(-wise), so (in like manner), thus, what","lemma":"οὕτω","translit":"hoútō","derivation":"adverb from G3778 (οὗτος);","strongs_def":" in this way (referring to what precedes or follows)","pron":"hoo'-to","pos":"Adverb","thayer":"<ol><li>in this manner, thus, so</li></ol>","xlit":"hoútō"},"G4403":{"derivation":"feminine of (hindmost);","strongs_def":" the stern of a ship","kjv_def":"hinder part, stern","lemma":"πρύμνα","translit":"prýmna","pron":"proom'-nah","pos":"Noun Feminine","thayer":"<ol><li>the stern or hinder part of the ship</li></ol>","xlit":"prýmna"},"G2448":{"kjv_def":"Judah","translit":"Ioudá","lemma":"Ἰουδά","derivation":"of Hebrew origin (H03063 or perhaps H03194);","strongs_def":" Judah (i.e. Jehudah or Juttah), a part of (or place in) Palestine","pron":"ee-oo-dah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Judah = \"he shall be praised\"</p><ol><li>the fourth son of the patriarch Jacob</li><li>the tribe that were the offspring of Judah</li><li>the region occupied by the tribe</li><li>a city of the tribe of Judah, conjectured to be Hebron, which was a city assigned to the priests and located in the hill country, and the native place of John the Baptist according to Jewish tradition</li></ol>","xlit":"Ioudá"},"G4209":{"derivation":"of Latin origin;","strongs_def":" the \"purple\" mussel, i.e. (by implication) the red-blue color itself, and finally a garment dyed with it","kjv_def":"purple","lemma":"πορφύρα","translit":"porphýra","pron":"por-foo'-rah","pos":"Noun Feminine","thayer":"<ol><li>the purple fish, a species of shell fish or mussel</li><li>a fabric coloured with purple dye, a garment made from purple cloth</li></ol>","xlit":"porphýra"},"G5614":{"kjv_def":"hosanna","lemma":"ὡσαννά","translit":"hōsanná","derivation":"of Hebrew origin (H03467 and H04994);","strongs_def":" oh save!; hosanna (i.e. hoshia-na), an exclamation of adoration","pron":"ho-san-nah'","thayer":"<ol><li>hosanna</li><li>be propitious</li></ol>","xlit":"hōsanná"},"G4974":{"derivation":"neuter of a presumed derivative probably of the same as (a ball, \"sphere\";","strongs_def":" compare the feminine , a hammer); the ankle (as globular)","kjv_def":"ancle bone","lemma":"σφυρόν","translit":"sphyrón","pron":"sfoo-ron'","pos":"Noun Neuter","thayer":"<ol><li>the ankle</li></ol>","xlit":"sphyrón"},"G698":{"kjv_def":"Areopagite","translit":"Areopagítēs","lemma":"Ἀρεοπαγίτης","derivation":"from G697 (Ἄρειος Πάγος);","strongs_def":" an Areopagite or member of the court held on Mars' Hill","pron":"ar-eh-op-ag-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a member of the court of Areopagus, an Areopagite</li></ol>","xlit":"Areopagítēs"},"G3840":{"kjv_def":"on every side, round about","translit":"pántothen","lemma":"πάντοθεν","derivation":"adverb (of source) from G3956 (πᾶς);","strongs_def":" from (i.e. on) all sides","pron":"pan-toth'-en","pos":"Adverb","thayer":"<ol><li>from all sides, from every quarter</li></ol>","xlit":"pántothen"},"G4833":{"kjv_def":"make conformable unto","translit":"symmorphóō","lemma":"συμμορφόω","derivation":"from G4832 (σύμμορφος);","strongs_def":" to render like, i.e. (figuratively) to assimilate","pron":"soom-mor-fo'-o","pos":"Verb","thayer":"<ol><li>to be conformed to, receive the same form as</li></ol>","xlit":"symmorphóō"},"G1145":{"translit":"dakrýō","lemma":"δακρύω","kjv_def":"weep","strongs_def":" to shed tears","derivation":"from G1144 (δάκρυ);","pron":"dak-roo'-o","pos":"Verb","thayer":"<ol><li>to weep, shed tears</li></ol>","xlit":"dakrýō"},"G2018":{"translit":"epiphérō","lemma":"ἐπιφέρω","kjv_def":"add, bring (against), take","strongs_def":" to bear upon (or further), i.e. adduce (personally or judicially (accuse, inflict)), superinduce","derivation":"from G1909 (ἐπί) and G5342 (φέρω);","pron":"ep-ee-fer'-o","pos":"Verb","thayer":"<ol><li>to bring upon, bring forward<ol type='a'><li>used of accusers</li></ol><li>to lay upon, to inflict</li><li>to bring upon, i.e. in addition, to add, increase</li><li>to put upon, cast upon, impose</li></ol>","xlit":"epiphérō"},"G3106":{"translit":"makarízō","lemma":"μακαρίζω","kjv_def":"call blessed, count happy","strongs_def":" to beatify, i.e. pronounce (or esteem) fortunate","derivation":"from G3107 (μακάριος);","pron":"mak-ar-id'-zo","pos":"Verb","thayer":"<ol><li>to pronounce blessed</li></ol>","xlit":"makarízō"},"G2776":{"strongs_def":" the head (as the part most readily taken hold of), literally or figuratively","derivation":"from the primary (in the sense of seizing);","lemma":"κεφαλή","translit":"kephalḗ","kjv_def":"head","pron":"kef-al-ay'","pos":"Noun Feminine","thayer":"<ol><li>the head, both of men and often of animals. Since the loss of the head destroys life, this word is used in the phrases relating to capital and extreme punishment.</li><li>metaphorically anything supreme, chief, prominent<ol type='a'><li>of persons, master lord: of a husband in relation to his wife</li><li>of Christ: the Lord of the husband and of the Church</li><li>of things: the corner stone</li></ol></li></ol>","xlit":"kephalḗ"},"G3871":{"strongs_def":" to cover alongside, i.e. veil (figuratively)","derivation":"from G3844 (παρά) and G2572 (καλύπτω);","translit":"parakalýptō","lemma":"παρακαλύπτω","kjv_def":"hide","pron":"par-ak-al-oop'-to","pos":"Verb","thayer":"<ol><li>to cover over, cover up, hide, conceal</li></ol>","xlit":"parakalýptō"},"G4438":{"strongs_def":" to box (with the fist), i.e. contend (as a boxer) at the games (figuratively)","derivation":"from a derivative of the same as G4435 (πυγμή);","translit":"pyktéō","lemma":"πυκτέω","kjv_def":"fight","pron":"pook-te-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a boxer, to box</li></ol>","xlit":"pyktéō"},"G3699":{"lemma":"ὅπου","translit":"hópou","kjv_def":"in what place, where(-as, -soever), whither (+ soever)","strongs_def":" what(-ever) where, i.e. at whichever spot","derivation":"from G3739 (ὅς) and G4225 (πού);","pron":"hop'-oo","thayer":"<ol><li>where, whereas</li></ol>","xlit":"hópou"},"G18":{"lemma":"ἀγαθός","translit":"agathós","kjv_def":"benefit, good(-s, things), well","strongs_def":" \"good\" (in any sense, often as noun)","derivation":"a primary word;","pron":"ag-ath-os'","pos":"Adjective","thayer":"<ol><li>of good constitution or nature</li><li>useful, salutary</li><li>good, pleasant, agreeable, joyful, happy</li><li>excellent, distinguished</li><li>upright, honourable</li></ol>","xlit":"agathós"},"G2426":{"kjv_def":"sufficiency","translit":"hikanótēs","lemma":"ἱκανότης","derivation":"from G2425 (ἱκανός);","strongs_def":" ability","pron":"hik-an-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>sufficient, ability or competency to do a thing</li></ol>","xlit":"hikanótēs"},"G457":{"kjv_def":"X open","lemma":"ἄνοιξις","translit":"ánoixis","derivation":"from G455 (ἀνοίγω);","strongs_def":" opening (throat)","pron":"an'-oix-is","pos":"Noun Feminine","thayer":"<ol><li>an opening</li></ol>","xlit":"ánoixis"},"G4249":{"strongs_def":" to saw in two","derivation":"a strengthened form of a primary prio (to saw);","translit":"prízō","lemma":"πρίζω","kjv_def":"saw asunder","pron":"prid'-zo","pos":"Verb","thayer":"<ol><li>to saw, to cut in two with a saw</li></ol>","xlit":"prízō"},"G4285":{"strongs_def":" to lead the way for others, i.e. show deference","derivation":"from G4253 (πρό) and G2233 (ἡγέομαι);","translit":"proēgéomai","lemma":"προηγέομαι","kjv_def":"prefer","pron":"pro-ay-geh'-om-ahee","pos":"Verb","thayer":"<ol><li>to go before and show the way, to go before and lead, to go before as a leader</li></ol>","xlit":"proēgéomai"},"G1324":{"derivation":"prolongation from G1364 (δίς);","strongs_def":" double, i.e. twin; Didymus, a Christian","kjv_def":"Didymus","lemma":"Δίδυμος","translit":"Dídymos","pron":"did'-oo-mos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Didymus = \"two fold or twain\"</p><ol><li>a surname for the apostle Thomas</li></ol>","xlit":"Dídymos"},"G3683":{"derivation":"from a derivative of G3685 (ὀνίνημι) and G5411 (φόρος);","strongs_def":" profit-bearer; Onesiphorus, a Christian","kjv_def":"Onespiphorus","lemma":"Ὀνησίφορος","translit":"Onēsíphoros","pron":"on-ay-sif'-or-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Onesiphorus = \"bringing profit\"</p><ol><li>the name of a certain Christian in <a class='bible' href='#b55.1.16-18'>2Ti 1:16-18</a>, <a class='bible' href='#b55.4.19'>2Ti 4:19</a></li></ol>","xlit":"Onēsíphoros"},"G4786":{"strongs_def":" to commingle, i.e. (figuratively) to combine or assimilate","derivation":"from G4862 (σύν) and G2767 (κεράννυμι);","lemma":"συγκεράννυμι","translit":"synkeránnymi","kjv_def":"mix with, temper together","pron":"soong-ker-an'-noo-mee","pos":"Verb","thayer":"<ol><li>to mix together, commingle</li><li>to unite<ol type='a'><li>caused the several parts to combine into an organic structure, which is the body</li><li>to unite one thing to another</li></ol></li></ol>","xlit":"synkeránnymi"},"G4204":{"strongs_def":" a strumpet; figuratively, an idolater","derivation":"feminine of G4205 (πόρνος);","lemma":"πόρνη","translit":"pórnē","kjv_def":"harlot, whore","pos":"Noun Feminine","xlit":"pórnē"},"G4568":{"derivation":"of Hebrew origin (H05429);","strongs_def":" a certain measure for things dry","kjv_def":"measure","lemma":"σάτον","translit":"sáton","pron":"sat'-on","pos":"Noun Neuter","thayer":"<ol><li>a kind of dry measure, 3 gallons (14 litres)</li></ol>","xlit":"sáton"},"G4603":{"kjv_def":"(of) iron","lemma":"σιδήρεος","translit":"sidḗreos","derivation":"from G4604 (σίδηρος);","strongs_def":" made of iron","pron":"sid-ay'-reh-os","pos":"Adjective","thayer":"<ol><li>made of iron</li></ol>","xlit":"sidḗreos"},"G1533":{"kjv_def":"bring (in), lead into","lemma":"εἰσφέρω","translit":"eisphérō","derivation":"from G1519 (εἰς) and G5342 (φέρω);","strongs_def":" to carry inward (literally or figuratively)","pron":"ice-fer'-o","pos":"Verb","thayer":"<ol><li>to bring into, in or to</li><li>to lead into</li></ol>","xlit":"eisphérō"},"G3028":{"lemma":"λῆμψις","translit":"lēmpsis","kjv_def":"receiving","strongs_def":" receipt (the act)","derivation":"from G2983 (λαμβάνω);","pron":"lape'-sis","pos":"Noun Feminine","thayer":"<ol><li>a receiving</li></ol>","xlit":"lēmpsis"},"G1750":{"lemma":"ἐνειλέω","translit":"eneiléō","kjv_def":"wrap in","strongs_def":" to enwrap","derivation":"from G1772 (ἔννομος) and the base of G1507 (εἱλίσσω);","pron":"en-i-leh'-o","pos":"Verb","thayer":"<ol><li>to roll in, wind up</li></ol>","xlit":"eneiléō"},"G2876":{"translit":"kórax","lemma":"κόραξ","kjv_def":"raven","strongs_def":" a crow (from its voracity)","derivation":"perhaps from G2880 (κορέννυμι);","pron":"kor'-ax","pos":"Noun Masculine","thayer":"<ol><li>a raven</li></ol>","xlit":"kórax"},"G2779":{"kjv_def":"garden","translit":"kēpos","lemma":"κῆπος","derivation":"of uncertain affinity;","strongs_def":" a garden","pron":"kay'-pos","pos":"Noun Masculine","thayer":"<ol><li>a garden</li></ol>","xlit":"kēpos"},"G925":{"kjv_def":"overcharge","lemma":"βαρύνω","translit":"barýnō","derivation":"from G926 (βαρύς);","strongs_def":" to burden (figuratively)","pron":"bar-oo'-no","pos":"Verb","thayer":"<ol><li>to weigh down, overcharge</li></ol>","xlit":"barýnō"},"G5109":{"derivation":"another form of G5038 (τεῖχος);","strongs_def":" a wall","kjv_def":"wall","translit":"toîchos","lemma":"τοῖχος","pron":"toy'-khos","pos":"Noun Masculine","thayer":"<ol><li>a wall (of a house)</li></ol>","xlit":"toîchos"},"G2817":{"strongs_def":" heirship, i.e. (concretely) a patrimony or (genitive case) a possession","derivation":"from G2818 (κληρονόμος);","translit":"klēronomía","lemma":"κληρονομία","kjv_def":"inheritance","pron":"klay-ron-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>an inheritance, property received (or to be received) by inheritance</li><li>what is given to one as a possession<ol type='a'><li>the eternal blessedness of the consummated kingdom of God which is to be expected after the visible return of Christ</li><li>the share which an individual will have in that eternal blessedness</li></ol></li></ol>","xlit":"klēronomía"},"G3832":{"lemma":"πανοικί","translit":"panoikí","kjv_def":"with all his house","strongs_def":" with the whole family","derivation":"adverb from G3956 (πᾶς) and G3624 (οἶκος);","pron":"pan-oy-kee'","pos":"Adverb","thayer":"<ol><li>with all (his) house, with (his) whole family</li></ol>","xlit":"panoikí"},"G2055":{"kjv_def":"goat","lemma":"ἐρίφιον","translit":"eríphion","derivation":"from G2056 (ἔριφος);","strongs_def":" a kidling, i.e. (genitive case) goat (symbolically, wicked person)","pron":"er-if'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a kid, a young goat</li></ol>","xlit":"eríphion"},"G4925":{"kjv_def":"build together","translit":"synoikodoméō","lemma":"συνοικοδομέω","derivation":"from G4862 (σύν) and G3618 (οἰκοδομέω);","strongs_def":" to construct, i.e. (passively) to compose (in company with other Christians, figuratively)","pron":"soon-oy-kod-om-eh'-o","pos":"Verb","thayer":"<ol><li>to build together<ol type='a'><li>to build together or with others</li><li>to put together or construct by building, out of several things to build up one whole<ol><li>of the human body</li></ol></li></ol></li></ol>","xlit":"synoikodoméō"},"G4356":{"kjv_def":"receiving","translit":"próslēpsis","lemma":"πρόσληψις","derivation":"from G4355 (προσλαμβάνω);","strongs_def":" admission","pron":"pros'-lape-sis","pos":"Noun Feminine","thayer":"<ol><li>a receiving: into the kingdom of God</li></ol>","xlit":"próslēpsis"},"G5503":{"derivation":"feminine of a presumed derivative apparently from the base of G5490 (χάσμα) through the idea of deficiency;","strongs_def":" a widow (as lacking a husband), literally or figuratively","kjv_def":"widow","translit":"chḗra","lemma":"χήρα","pron":"khay'-rah","pos":"Noun Feminine","thayer":"<ol><li>a widow</li><li>metaphorically a city stripped of its inhabitants and riches is represented under the figure of a widow</li></ol>","xlit":"chḗra"},"G2820":{"kjv_def":"obtain an inheritance","lemma":"κληρόω","translit":"klēróō","derivation":"from G2819 (κλῆρος);","strongs_def":" to allot, i.e. (figuratively) to assign (a privilege)","pron":"klay-ro-o","pos":"Verb","thayer":"<ol><li>to cast lots, determine by lot</li><li>to choose by lot</li><li>to allot, assign by lot<ol type='a'><li>on to another as a possession</li></ol><li>in NT: to make a lot, i.e. a heritage, private possession</li></ol>","xlit":"klēróō"},"G91":{"translit":"adikéō","lemma":"ἀδικέω","kjv_def":"hurt, injure, be an offender, be unjust, (do, suffer, take) wrong","strongs_def":" to be unjust, i.e. (actively) do wrong (morally, socially or physically)","derivation":"from G94 (ἄδικος);","pron":"ad-ee-keh'-o","pos":"Verb","thayer":"<ol><li>absolutely<ol type='a'><li>to act unjustly or wickedly, to sin</li><li>to be a criminal, to have violated the laws in some way</li><li>to do wrong</li><li>to do hurt</li></ol><li>transitively<ol type='a'><li>to do some wrong or sin in some respect</li><li>to wrong some one, act wickedly towards him</li><li>to hurt, damage, harm</li></ol></li></ol>","xlit":"adikéō"},"G1077":{"strongs_def":" birthday ceremonies","derivation":"neuter plural of a derivative of G1078 (γένεσις);","lemma":"γενέσια","translit":"genésia","kjv_def":"birthday","pron":"ghen-es'-ee-ah","pos":"Noun Neuter","thayer":"<ol><li>a birthday celebration, a birthday feast<ol type='a'><li>the earlier Greeks used this word of funeral commemorations, a festival commemorative of a deceased friend</li></ol></li></ol>","xlit":"genésia"},"G42":{"lemma":"ἁγιωσύνη","translit":"hagiōsýnē","kjv_def":"holiness","strongs_def":" sacredness (i.e. properly, the quality)","derivation":"from G40 (ἅγιος);","pron":"hag-ee-o-soo'-nay","pos":"Noun Feminine","thayer":"<ol><li>majesty, holiness</li><li>moral purity</li></ol>","xlit":"hagiōsýnē"},"G4368":{"derivation":"feminine of a derivative of G4291 (προΐστημι);","strongs_def":" a patroness, i.e. assistant","kjv_def":"succourer","translit":"prostátis","lemma":"προστάτις","pron":"pros-tat'-is","pos":"Noun Feminine","thayer":"<ol><li>a woman set over others</li><li>a female guardian, protectress, patroness, caring for the affairs of others and aiding them with her resources</li></ol>","xlit":"prostátis"},"G2700":{"kjv_def":"thrust through","lemma":"κατατοξεύω","translit":"katatoxeúō","derivation":"from G2596 (κατά) and a derivative of G5115 (τόξον);","strongs_def":" to shoot down with an arrow or other missile","pron":"kat-at-ox-yoo'-o","pos":"Verb","thayer":"<ol><li>to shoot down or thrust through with an arrow</li></ol>","xlit":"katatoxeúō"},"G2164":{"derivation":"from G2095 (εὖ) and G5409 (φορέω);","strongs_def":" to bear well, i.e. be fertile","kjv_def":"bring forth abundantly","translit":"euphoréō","lemma":"εὐφορέω","pron":"yoo-for-eh'-o","pos":"Verb","thayer":"<ol><li>to be fertile, bring forth plentifully</li></ol>","xlit":"euphoréō"},"G5279":{"kjv_def":"put in mind, remember, bring to (put in) remembrance","translit":"hypomimnḗskō","lemma":"ὑπομιμνήσκω","derivation":"from G5259 (ὑπό) and G3403 (μιμνήσκω);","strongs_def":" to remind quietly, i.e. suggest to the (middle voice, one's own) memory","pron":"hoop-om-im-nace'-ko","pos":"Verb","thayer":"<ol><li>to cause one to remember, bring to remembrance, recall to mind: to another</li><li>to put one in remembrance, admonish, of something</li><li>to be reminded, to remember</li></ol>","xlit":"hypomimnḗskō"},"G5077":{"strongs_def":" to incinerate, i.e. consume","derivation":"from (ashes);","lemma":"τεφρόω","translit":"tephróō","kjv_def":"turn to ashes","pron":"tef-ro'-o","pos":"Verb","thayer":"<ol><li>reduce to ashes</li></ol>","xlit":"tephróō"},"G1456":{"kjv_def":"dedication","lemma":"ἐγκαίνια","translit":"enkaínia","derivation":"neuter plural of a presumed compound from G1722 (ἐν) and G2537 (καινός);","strongs_def":" innovatives, i.e. (specially) renewal (of religious services after the Antiochian interruption)","pron":"eng-kah'-ee-nee-ah","pos":"Noun Neuter","thayer":"<ol><li>dedication, consecration<ol type='a'><li>in particular the annual feast celebrated eight days beginning in the 25th of Chislev (middle of our December), instituted by Judas Maccabaeus [164 BC] in memory of the cleansing of the temple from the pollution of Antiochus Epiphanes</li></ol></li></ol>","xlit":"enkaínia"},"G4693":{"kjv_def":"cave, den","lemma":"σπήλαιον","translit":"spḗlaion","derivation":"neuter of a presumed derivative of (a grotto);","strongs_def":" a cavern; by implication, a hiding-place or resort","pron":"spay'-lah-yon","pos":"Noun Neuter","thayer":"<ol><li>a cave, den</li></ol>","xlit":"spḗlaion"},"G5437":{"translit":"phygḗ","lemma":"φυγή","kjv_def":"flight","strongs_def":" a fleeing, i.e. escape","derivation":"from G5343 (φεύγω);","pron":"foog-ay'","pos":"Noun Feminine","thayer":"<ol><li>flight</li></ol>","xlit":"phygḗ"},"G670":{"strongs_def":" to unload","derivation":"from G575 (ἀπό) and the middle voice of G5412 (φορτίζω);","lemma":"ἀποφορτίζομαι","translit":"apophortízomai","kjv_def":"unlade","pron":"ap-of-or-tid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to lay down a load, unlade, discharge<ol type='a'><li>of sailors lightening ship during a storm to avoid shipwreck</li></ol></li></ol>","xlit":"apophortízomai"},"G4133":{"strongs_def":" moreover (besides), i.e. albeit, save that, rather, yet","derivation":"from G4119 (πλείων);","translit":"plḗn","lemma":"πλήν","kjv_def":"but (rather), except, nevertheless, notwithstanding, save, than","pron":"plane","pos":"Adverb","thayer":"<ol><li>moreover, besides, but, nevertheless</li><li>besides, except, but</li></ol>","xlit":"plḗn"},"G4191":{"strongs_def":" more evil","derivation":"comparative of G4190 (πονηρός);","translit":"ponēróteros","lemma":"πονηρότερος","kjv_def":"more wicked","pron":"pon-ay-rot'-er-os","pos":"Adjective","thayer":"<ol><li>more evil</li></ol>","xlit":"ponēróteros"},"G4378":{"derivation":"from a comparative of G4314 (πρός) and (to pour);","strongs_def":" a shedding forth, i.e. affusion","kjv_def":"sprinkling","lemma":"πρόσχυσις","translit":"próschysis","pron":"pros'-khoo-sis","pos":"Noun Feminine","thayer":"<ol><li>a pouring or sprinkling upon, affusion</li></ol>","xlit":"próschysis"},"G4259":{"kjv_def":"porch","lemma":"προαύλιον","translit":"proaúlion","derivation":"neuter of a presumed compound of G4253 (πρό) and G833 (αὐλή);","strongs_def":" a forecourt, i.e. vestibule (alley-way)","pron":"pro-ow'-lee-on","pos":"Noun Neuter","thayer":"<ol><li>fore-court, porch</li></ol>","xlit":"proaúlion"},"G359":{"derivation":"from G360 (ἀναλύω);","strongs_def":" departure","kjv_def":"departure","translit":"análysis","lemma":"ἀνάλυσις","pron":"an-al'-oo-sis","pos":"Noun Feminine","thayer":"<ol><li>an unloosing (as of things woven)</li><li>a dissolving (into separate parts)</li><li>departure<ol type='a'><li>a metaphor drawn from loosing from moorings preparatory to setting sail</li></ol></li></ol>","xlit":"análysis"},"G5546":{"kjv_def":"Christian","translit":"Christianós","lemma":"Χριστιανός","derivation":"from G5547 (Χριστός);","strongs_def":" a Christian, i.e. follower of Christ","pron":"khris-tee-an-os'","pos":"Noun Masculine","thayer":"<ol><li>Christian, a follower of Christ</li></ol>","xlit":"Christianós"},"G2867":{"derivation":"from (dust;","strongs_def":" by analogy, lime); to whitewash","kjv_def":"whiten","lemma":"κονιάω","translit":"koniáō","pron":"kon-ee-ah'-o","pos":"Verb","thayer":"<ol><li>to cover with lime, plaster over, whitewash<ol type='a'><li>the Jews were accustomed to whitewash the entrances to their sepulchres, as a warning against defilement by touching them</li><li>term applied to a hypocrite who conceals his malice under an outward assumption of piety</li></ol></li></ol>","xlit":"koniáō"},"G2494":{"lemma":"Ἰωνάν","translit":"Iōnán","kjv_def":"Jonan","strongs_def":" Jonan, an Israelite","derivation":"probably for G2491 (Ἰωάννης) or G2495 (Ἰωνᾶς);","pron":"ee-o-nan'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jonan = \"Jehovah is a gracious giver\"</p><ol><li>one of the ancestors of Christ</li></ol>","xlit":"Iōnán"},"G2743":{"lemma":"καυτηριάζω","translit":"kautēriázō","kjv_def":"sear with a hot iron","strongs_def":" to brand (\"cauterize\"), i.e. (by implication) to render unsensitive (figuratively)","derivation":"from a derivative of G2545 (καίω);","pron":"kow-tay-ree-ad'-zo","pos":"Verb","thayer":"<ol><li>to mark by branding, to brand, branded with their own consciences<ol type='a'><li>whose souls are branded with the marks of sin</li><li>who carry about with them the perpetual consciousness of sin</li></ol><li>seared</li><li>in a medical sense, to cauterise, remover by cautery</li></ol>","xlit":"kautēriázō"},"G5343":{"strongs_def":" to run away (literally or figuratively); by implication, to shun; by analogy, to vanish","derivation":"apparently a primary verb;","translit":"pheúgō","lemma":"φεύγω","kjv_def":"escape, flee (away)","pron":"fyoo'-go","pos":"Verb","thayer":"<ol><li>to flee away, seek safety by flight</li><li>metaphorically to flee (to shun or avoid by flight) something abhorrent, especially vices</li><li>to be saved by flight, to escape safely out of danger</li><li>poetically, to flee away, vanish</li></ol>","xlit":"pheúgō"},"G5475":{"strongs_def":" copper (the substance, or some implement or coin made of it)","derivation":"perhaps from G5465 (χαλάω) through the idea of hollowing out as a vessel (this metal being chiefly used for that purpose);","lemma":"χαλκός","translit":"chalkós","kjv_def":"brass, money","pron":"khal-kos'","pos":"Noun Masculine","thayer":"<ol><li>brass</li><li>what is made of brass, money, coins of brass (also of silver and gold)</li></ol>","xlit":"chalkós"},"G783":{"derivation":"from G782 (ἀσπάζομαι);","strongs_def":" a greeting (in person or by letter)","kjv_def":"greeting, salutation","translit":"aspasmós","lemma":"ἀσπασμός","pron":"as-pas-mos'","pos":"Noun Masculine","thayer":"<ol><li>a salutation, either oral or written</li></ol>","xlit":"aspasmós"},"G5351":{"kjv_def":"corrupt (self), defile, destroy","lemma":"φθείρω","translit":"phtheírō","derivation":"probably strengthened from (to pine or waste);","strongs_def":" properly, to shrivel or wither, i.e. to spoil (by any process) or (generally) to ruin (especially figuratively, by moral influences, to deprave)","pron":"fthi'-ro","pos":"Verb","thayer":"<ol><li>to corrupt, to destroy<ol type='a'><li>in the opinion of the Jews, the temple was corrupted or \"destroyed\" when anyone defiled or in the slightest degree damaged anything in it, or if its guardians neglected their duties</li><li>to lead away a Christian church from that state of knowledge and holiness in which it ought to abide</li><li>to be destroyed, to perish</li><li>in an ethical sense, to corrupt, deprave</li></ol></li></ol>","xlit":"phtheírō"},"G5431":{"lemma":"φροντίζω","translit":"phrontízō","kjv_def":"be careful","strongs_def":" to exercise thought, i.e. be anxious","derivation":"from a derivative of G5424 (φρήν);","pron":"fron-tid'-zo","pos":"Verb","thayer":"<ol><li>to think, to be careful</li><li>to be thoughtful or anxious</li></ol>","xlit":"phrontízō"},"G4856":{"derivation":"from G4859 (σύμφωνος);","strongs_def":" to be harmonious, i.e. (figuratively) to accord (be suitable, concur) or stipulate (by compact)","kjv_def":"agree (together, with)","lemma":"συμφωνέω","translit":"symphōnéō","pron":"soom-fo-neh'-o","pos":"Verb","thayer":"<ol><li>to agree together</li><li>to agree with one in making a bargain, to make an agreement, to bargain</li></ol>","xlit":"symphōnéō"},"G1856":{"kjv_def":"drive out, thrust in","translit":"exōthéō","lemma":"ἐξωθέω","derivation":"from G1537 (ἐκ) and (to push);","strongs_def":" to expel; by implication, to propel","pron":"ex-o-theh'-o","pos":"Verb","thayer":"<ol><li>to thrust out</li><li>expel from one's abode</li><li>to propel, drive</li></ol>","xlit":"exōthéō"},"G531":{"strongs_def":" not passing away, i.e. untransferable (perpetual)","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3845 (παραβαίνω);","lemma":"ἀπαράβατος","translit":"aparábatos","kjv_def":" unchangeable","pron":"ap-ar-ab'-at-os","pos":"Adjective","thayer":"<ol><li>unviolated, not to be violated, inviolable</li><li>unchangeable and therefore not liable to pass to a successor</li></ol>","xlit":"aparábatos"},"G4652":{"kjv_def":"dark, full of darkness","lemma":"σκοτεινός","translit":"skoteinós","derivation":"from G4655 (σκότος);","strongs_def":" opaque, i.e. (figuratively) benighted","pron":"skot-i-nos'","pos":"Adjective","thayer":"<ol><li>full of darkness, covered with darkness</li></ol>","xlit":"skoteinós"},"G1887":{"derivation":"from G1909 (ἐπί) and G839 (αὔριον);","strongs_def":" occurring on the succeeding day, i.e. (G2250 (ἡμέρα) being implied) to-morrow","kjv_def":"day following, morrow, next day (after)","translit":"epaúrion","lemma":"ἐπαύριον","pron":"ep-ow'-ree-on","pos":"Adverb","thayer":"<ol><li>on the morrow, the next day</li></ol>","xlit":"epaúrion"},"G1234":{"derivation":"from G1223 (διά) and G1111 (γογγύζω);","strongs_def":" to complain throughout a crowd","kjv_def":"murmur","lemma":"διαγογγύζω","translit":"diagongýzō","pron":"dee-ag-ong-good'-zo","pos":"Verb","thayer":"<ol><li>to murmur<ol type='a'><li>either of a whole crowd, or among one another</li><li>always used of many indignantly complaining</li></ol></li></ol>","xlit":"diagongýzō"},"G100":{"kjv_def":"abundance","lemma":"ἁδρότης","translit":"hadrótēs","derivation":"from (stout);","strongs_def":" plumpness, i.e. (figuratively) liberality","pron":"had-rot'-ace","pos":"Noun Feminine","thayer":"<ol><li>bountiful collection, great abundance</li><li>thickness, ripeness, fulness, especially of the body</li></ol>","xlit":"hadrótēs"},"G899":{"kjv_def":"deep(-ness, things), depth","lemma":"βάθος","translit":"báthos","derivation":"from the same as G901 (βαθύς);","strongs_def":" profundity, i.e. (by implication) extent; (figuratively) mystery","pron":"bath'-os","pos":"Noun Neuter","thayer":"<ol><li>depth, height<ol type='a'><li>of \"the deep\" sea</li><li>metaphorically<ol><li>deep, extreme, poverty</li><li>of the deep things of God</li></ol></li></ol></li></ol>","xlit":"báthos"},"G1089":{"strongs_def":" to taste; by implication, to eat; figuratively, to experience (good or ill)","derivation":"a primary verb;","translit":"geúomai","lemma":"γεύομαι","kjv_def":"eat, taste","pron":"ghyoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to taste, to try the flavour of</li><li>to taste<ol type='a'><li>i.e. perceive the flavour of, partake of, enjoy</li><li>to feel, make trial of, experience</li></ol><li>to take food, eat, to take nourishment, eat</li></ol>","xlit":"geúomai"},"G3176":{"kjv_def":"exceeding great","translit":"mégistos","lemma":"μέγιστος","derivation":"superlative of G3173 (μέγας);","strongs_def":" greatest or very great","pron":"meg'-is-tos","pos":"Adjective","thayer":"<ol><li>greatest, very great</li></ol>","xlit":"mégistos"},"G4273":{"strongs_def":" a surrender","derivation":"from G4272 (προδίδωμι) (in the sense of giving forward into another's (the enemy's) hands);","lemma":"προδότης","translit":"prodótēs","kjv_def":"betrayer, traitor","pron":"prod-ot'-ace","pos":"Noun Masculine","thayer":"<ol><li>a betrayer, traitor</li></ol>","xlit":"prodótēs"},"G2025":{"kjv_def":"anoint","translit":"epichríō","lemma":"ἐπιχρίω","derivation":"from G1909 (ἐπί) and G5548 (χρίω);","strongs_def":" to smear over","pron":"ep-ee-khree'-o","pos":"Verb","thayer":"<ol><li>to spread on, anoint anything upon anything</li></ol>","xlit":"epichríō"},"G2408":{"derivation":"of Hebrew origin (H03414);","strongs_def":" Hieremias (i.e. Jermijah), an Israelite","kjv_def":"Jeremiah","lemma":"Ἱερεμίας","translit":"Hieremías","pron":"hee-er-em-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jeremiah = \"whom Jehovah has appointed\"</p><ol><li>the son of Hilkiah of the priests that were in Anathoth. He was called very young (B.C. 626) to the prophetic office, and prophesied 42 years. He probably died in Egypt.</li></ol>","xlit":"Hieremías"},"G784":{"derivation":"from G1 (Α) (as a negative particle) and G4695 (σπιλόω);","strongs_def":" unblemished (physically or morally)","kjv_def":"without spot, unspotted","translit":"áspilos","lemma":"ἄσπιλος","pron":"as'-pee-los","pos":"Adjective","thayer":"<ol><li>spotless</li><li>metaphorically<ol type='a'><li>free from censure, irreproachable</li><li>free from vice, unsullied</li></ol></li></ol>","xlit":"áspilos"},"G4549":{"translit":"Saoúl","lemma":"Σαούλ","kjv_def":"Saul","strongs_def":" Saul (i.e. Shaul), the Jewish name of Paul","derivation":"of Hebrew origin (H07586);","pron":"sah-ool'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Saul = \"desired\"</p><ol><li>the Jewish name of the apostle Paul</li><li>the son of Kish and the first king of Israel</li></ol>","xlit":"Saoúl"},"G4481":{"kjv_def":"Remphan","translit":"Rhemphán","lemma":"Ῥεμφάν","derivation":"by incorrect transliteration for a word of Hebrew origin (H03594);","strongs_def":" Remphan (i.e. Kijun), an Egyptian idol","pron":"hrem-fan'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Remphan = \"the shrunken (as lifeless)\"</p><ol><li>the name of an idol worshipped secretly by the Israelites in the wilderness</li></ol>","xlit":"Rhemphán"},"G3717":{"kjv_def":"straight, upright","translit":"orthós","lemma":"ὀρθός","derivation":"probably from the base of G3735 (ὄρος);","strongs_def":" right (as rising), i.e. (perpendicularly) erect (figuratively, honest), or (horizontally) level or direct","pron":"or-thos'","pos":"Adjective","thayer":"<ol><li>straight, erect<ol type='a'><li>upright</li><li>straight, not crooked</li></ol></li></ol>","xlit":"orthós"},"G4869":{"derivation":"from G4862 (σύν) and G164 (αἰχμάλωτος);","strongs_def":" a co-captive","kjv_def":"fellowprisoner","translit":"synaichmálōtos","lemma":"συναιχμάλωτος","pron":"soon-aheekh-mal'-o-tos","pos":"Noun Masculine","thayer":"<ol><li>a fellow prisoner</li></ol>","xlit":"synaichmálōtos"},"G3171":{"kjv_def":"greatly","translit":"megálōs","lemma":"μεγάλως","derivation":"adverb from G3173 (μέγας);","strongs_def":" much","pron":"meg-al'-oce","pos":"Adverb","thayer":"<ol><li>greatly</li></ol>","xlit":"megálōs"},"G4284":{"kjv_def":"be better","lemma":"προέχομαι","translit":"proéchomai","derivation":"middle voice from G4253 (πρό) and G2192 (ἔχω);","strongs_def":" to hold oneself before others, i.e. (figuratively) to excel","pron":"pro-ekh-om-ahee","pos":"Verb","thayer":"<ol><li>to have before or in advance of another, to have pre-eminence over another, to excel, surpass</li><li>to surpass in excellencies which can be passed to one's credit</li></ol>","xlit":"proéchomai"},"G87":{"lemma":"ἀδιάκριτος","translit":"adiákritos","kjv_def":"without partiality","strongs_def":" properly, undistinguished, i.e. (actively) impartial","derivation":"from G1 (Α) (as a negative particle) and a derivative of G1252 (διακρίνω);","pron":"ad-ee-ak'-ree-tos","pos":"Adjective","thayer":"<ol><li>undistinguished, unintelligible</li><li>without dubiousness, ambiguity or uncertainty</li></ol>","xlit":"adiákritos"},"G343":{"strongs_def":" to unveil","derivation":"from G303 (ἀνά) (in the sense of reversal) and G2572 (καλύπτω);","lemma":"ἀνακαλύπτω","translit":"anakalýptō","kjv_def":"open, (un-)taken away","pron":"an-ak-al-oop'-to","pos":"Verb","thayer":"<ol><li>to unveil or uncover (by drawing back a veil)</li></ol>","xlit":"anakalýptō"},"G5283":{"derivation":"from G5282 (ὑπονοέω);","strongs_def":" suspicion","kjv_def":"surmising","lemma":"ὑπόνοια","translit":"hypónoia","pron":"hoop-on'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>a surmising</li></ol>","xlit":"hypónoia"},"G4648":{"kjv_def":"consider, take heed, look at (on), mark","lemma":"σκοπέω","translit":"skopéō","derivation":"from G4649 (σκοπός);","strongs_def":" to take aim at (spy), i.e. (figuratively) regard","pron":"skop-eh'-o","pos":"Verb","thayer":"<ol><li>to look at, observe, contemplate</li><li>to mark</li><li>to fix one's eyes upon, direct one's attention to, any one</li><li>to look to, take heed to thyself</li></ol>","xlit":"skopéō"},"G2778":{"derivation":"of Latin origin;","strongs_def":" properly, an enrollment (\"census\"), i.e. (by implication) a tax","kjv_def":"tribute","lemma":"κῆνσος","translit":"kēnsos","pron":"kane'-sos","pos":"Noun Masculine","thayer":"<ol><li>census (among the Romans, denoting a register and valuation of property in accordance with which taxes were paid), in the NT the tax or tribute levied on individuals and to be paid yearly. (our capitation or poll tax)</li><li>the coin with which the tax is paid, tribute money</li></ol>","xlit":"kēnsos"},"G980":{"derivation":"from G979 (βίος);","strongs_def":" to spend existence","kjv_def":"live","lemma":"βιόω","translit":"bióō","pron":"bee-o'-o","pos":"Verb","thayer":"<ol><li>to spend life, live</li></ol>","xlit":"bióō"},"G820":{"translit":"átimos","lemma":"ἄτιμος","kjv_def":"despised, without honour, less honourable (comparative degree)","strongs_def":" (negatively) unhonoured or (positively) dishonoured","derivation":"from G1 (Α) (as a negative particle) and G5092 (τιμή);","pron":"at'-ee-mos","pos":"Adjective","thayer":"<ol><li>without honour, unhonoured, dishonoured</li><li>base, of less esteem</li></ol>","xlit":"átimos"},"G3836":{"kjv_def":"from every quarter","lemma":"πανταχόθεν","translit":"pantachóthen","derivation":"adverb (of source) from G3837 (πανταχοῦ);","strongs_def":" from all directions","pron":"pan-takh-oth'-en","pos":"Adverb","thayer":"<ol><li>from all sides, from every quarter</li></ol>","xlit":"pantachóthen"},"G1025":{"kjv_def":"babe, (young) child, infant","translit":"bréphos","lemma":"βρέφος","derivation":"of uncertain affinity;","strongs_def":" an infant (properly, unborn) literally or figuratively","pron":"bref'-os","pos":"Noun Neuter","thayer":"<ol><li>an unborn child, embryo, a foetus</li><li>a new-born child, an infant, a babe</li></ol>","xlit":"bréphos"},"G4491":{"derivation":"apparently a primary word;","strongs_def":" a \"root\" (literally or figuratively)","kjv_def":"root","translit":"rhíza","lemma":"ῥίζα","pron":"hrid'-zah","pos":"Noun Feminine","thayer":"<ol><li>a root</li><li>that which like a root springs from a root, a sprout, shoot</li><li>metaphorically offspring, progeny</li></ol>","xlit":"rhíza"},"G5064":{"derivation":"a plural number;","strongs_def":" four","kjv_def":"four","lemma":"τέσσαρες","translit":"téssares","pron":"tes'-sar-es","pos":"Adjective","thayer":"<ol><li>four</li></ol>","xlit":"téssares"},"G242":{"kjv_def":"leap, spring up","lemma":"ἅλλομαι","translit":"hállomai","derivation":"middle voice of apparently a primary verb;","strongs_def":" to jump; figuratively, to gush","pron":"hal'-lom-ahee","pos":"Verb","thayer":"<ol><li>to leap</li><li>to spring up, gush up: of water</li></ol>","xlit":"hállomai"},"G1109":{"strongs_def":" a knower","derivation":"from G1097 (γινώσκω);","translit":"gnṓstēs","lemma":"γνώστης","kjv_def":"expert","pron":"gnoce'-tace","pos":"Noun Masculine","thayer":"<ol><li>an expert, a connoisseur</li></ol>","xlit":"gnṓstēs"},"G1318":{"kjv_def":"taught, which … teacheth","translit":"didaktós","lemma":"διδακτός","derivation":"from G1321 (διδάσκω);","strongs_def":" (subjectively) instructed, or (objectively) communicated by teaching","pron":"did-ak-tos'","pos":"Adjective","thayer":"<ol><li>that can be taught</li><li>taught, instructed by one</li><li>teachings, precepts</li></ol>","xlit":"didaktós"},"G2473":{"derivation":"from G2470 (ἴσος) and G5590 (ψυχή);","strongs_def":" of similar spirit","kjv_def":"likeminded","translit":"isópsychos","lemma":"ἰσόψυχος","pron":"ee-sop'-soo-khos","pos":"Adjective","thayer":"<ol><li>equal in soul</li></ol>","xlit":"isópsychos"},"G938":{"kjv_def":"queen","lemma":"βασίλισσα","translit":"basílissa","derivation":"feminine from G936 (βασιλεύω);","strongs_def":" a queen","pron":"bas-il'-is-sah","pos":"Noun Feminine","thayer":"<ol><li>queen</li></ol>","xlit":"basílissa"},"G4986":{"derivation":"from the base of G4982 (σώζω) and G3962 (πατήρ);","strongs_def":" of a safe father; Sopatrus, a Christian","kjv_def":"Sopater","translit":"Sṓpatros","lemma":"Σώπατρος","pron":"so'-pat-ros","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sopater = \"saviour of his father\"</p><ol><li>the son of Pyrhus of Berea, a companion of Paul</li></ol>","xlit":"Sṓpatros"},"G2226":{"derivation":"neuter of a derivative of G2198 (ζάω);","strongs_def":" a live thing, i.e. an animal","kjv_def":"beast","lemma":"ζῶον","translit":"zōon","pron":"dzo'-on","pos":"Noun Neuter","thayer":"<ol><li>a living being</li><li>an animal, brute, beast</li></ol>","xlit":"zōon"},"G5302":{"strongs_def":" to be later, i.e. (by implication) to be inferior; generally, to fall short (be deficient)","derivation":"from G5306 (ὕστερος);","lemma":"ὑστερέω","translit":"hysteréō","kjv_def":"come behind (short), be destitute, fail, lack, suffer need, (be in) want, be the worse","pron":"hoos-ter-eh'-o","pos":"Verb","thayer":"<ol><li>behind<ol type='a'><li>to come late or too tardily<ol><li>to be left behind in the race and so fail to reach the goal, to fall short of the end</li><li>metaphorically fail to become a partaker, fall back from</li></ol><li>to be inferior in power, influence and rank<ol><li>of the person: to be inferior to</li></ol><li>to fail, be wanting</li><li>to be in want of, lack</li></ol><li>to suffer want, to be devoid of, to lack (be inferior) in excellence, worth</li></ol>","xlit":"hysteréō"},"G2264":{"derivation":"compound of (a \"hero\") and G1491 (εἶδος);","strongs_def":" heroic; Herod, the name of four Jewish kings","kjv_def":"Herod","translit":"Hērṓdēs","lemma":"Ἡρώδης","pron":"hay-ro'-dace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Herod = \"heroic\"</p><ol><li>the name of a royal family that flourished among the Jews in the times of Christ and the Apostles. Herod the Great was the son of Antipater of Idumaea. Appointed king of Judaea B.C. 40 by the Roman Senate at the suggestion of Antony and with the consent of Octavian, he at length overcame the great opposition which the country made to him and took possession of the kingdom B.C. 37; and after the battle of Actium, he was confirmed by Octavian, whose favour he ever enjoyed. He was brave and skilled in war, learned and sagacious; but also extremely suspicious and cruel. Hence he destroyed the entire royal family of Hasmonaeans, put to death many of the Jews that opposed his government, and proceeded to kill even his dearly beloved wife Mariamne of the Hasmonaean line and his two sons she had borne him. By these acts of bloodshed, and especially by his love and imitation of Roman customs and institutions and by the burdensome taxes imposed upon his subjects, he so alienated the Jews that he was unable to regain their favour by his splendid restoration of the temple and other acts of munificence. He died in the 70th year of his age, the 37th year of his reign, the 4th before the Dionysian era. In his closing years John the Baptist and Christ were born; Matthew narrates that he commanded all the male children under two years old in Bethlehem to be slain.</li><li>Herod surnamed \"Antipas\" , was the son of Herod the Great and Malthace, a Samaritan woman. After the death of his father he was appointed by the Romans tetrarch of Galilee and Peraea. His first wife was the daughter of Aretas, king of Arabia; but he subsequently repudiated her and took to himself Herodias, the wife of his brother Herod Philip; and in consequence Aretas, his father-in-law, made war against him and conquered him. He cast John the Baptist into prison because John had rebuked him for this unlawful connection; and afterwards, at the instigation of Herodias, he ordered him to be beheaded. Induced by her, too, he went to Rome to obtain from the emperor the title of king. But in consequence of the accusations brought against him by Herod Agrippa I, Caligula banished him (A.D. 39) to Lugdunum in Gaul, where he seems to have died. He was light minded, sensual and vicious.</li><li>Herod Agrippa I was the son of Aristobulus and Berenice, and grandson of Herod the Great. After various changes in fortune, he gained the favour of Caligula and Claudius to such a degree that he gradually obtained the government of all of Palestine, with the title of king. He died at Caesarea, A.D. 44, at the age of 54, in the seventh [or the 4th, reckoning from the extension of his dominions by Claudius] year of his reign, just after having ordered James the apostle, son of Zebedee, to be slain, and Peter to be cast into prison: <a class='bible' href='#b44.12.21'>Act 12:21</a></li><li>(Herod) Agrippa II, son of Herod Agrippa I. When his father died he was a youth of seventeen. In A.D. 48 he received from Claudius Caesar the government of Chalcis, with the right of appointing the Jewish high priests, together with the care and oversight of the temple at Jerusalem. Four years later Claudius took from him Chalcis and gave him instead a larger domain, of Batanaea, Trachonitis, and Gaulanitis, with the title of king. To those reigns Nero, in A.D. 53, added Tiberias and Taricheae and Peraean Julias, with fourteen neighbouring villages. He is mentioned in Acts 25 and 26. In the Jewish war, although he strove in vain to restrain the fury of the seditious and bellicose populace, he did not desert to the Roman side. After the fall of Jerusalem, he was vested with praetorian rank and kept the kingdom entire until his death, which took place in the third year of the emperor Trajan [the 73rd year of his life, and the 52nd of his reign]. He was the last representative of the Herodian dynasty.</li></ol>","xlit":"Hērṓdēs"},"G185":{"translit":"akéraios","lemma":"ἀκέραιος","kjv_def":"harmless, simple","strongs_def":" unmixed, i.e. (figuratively) innocent","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G2767 (κεράννυμι);","pron":"ak-er'-ah-yos","pos":"Adjective","thayer":"<ol><li>unmixed, pure as in wines or metals</li><li>of the mind, without a mixture of evil, free from guile, innocent, simple</li></ol>","xlit":"akéraios"},"G2892":{"kjv_def":"watch","translit":"koustōdía","lemma":"κουστωδία","derivation":"of Latin origin;","strongs_def":" \"custody\", i.e. a Roman sentry","pron":"koos-to-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>guard: used of Roman soldiers guarding the sepulchre of Christ</li></ol>","xlit":"koustōdía"},"G2935":{"derivation":"from G2932 (κτάομαι);","strongs_def":" an owner","kjv_def":"possessor","lemma":"κτήτωρ","translit":"ktḗtōr","pron":"ktay'-tore","pos":"Noun Masculine","thayer":"<ol><li>a possessor</li></ol>","xlit":"ktḗtōr"},"G4308":{"kjv_def":"foresee, see before","lemma":"προοράω","translit":"prooráō","derivation":"from G4253 (πρό) and G3708 (ὁράω);","strongs_def":" to behold in advance, i.e. (actively) to notice (another) previously, or (middle voice) to keep in (one's own) view","pron":"pro-or-ah'-o","pos":"Verb","thayer":"<ol><li>to see before (whether as respects place or time)</li><li>to keep before one's eye's</li><li>metaphorically to be mindful of one always</li></ol>","xlit":"prooráō"},"G1730":{"lemma":"ἔνδειγμα","translit":"éndeigma","kjv_def":"manifest token","strongs_def":" an indication (concretely)","derivation":"from G1731 (ἐνδείκνυμι);","pron":"en'-dighe-mah","pos":"Noun Neuter","thayer":"<ol><li>token, evidence, proof</li></ol>","xlit":"éndeigma"},"G1085":{"lemma":"γένος","translit":"génos","kjv_def":"born, country(-man), diversity, generation, kind(-red), nation, offspring, stock","strongs_def":" \"kin\" (abstract or concrete, literal or figurative, individual or collective)","derivation":"from G1096 (γίνομαι);","pron":"ghen'-os","pos":"Noun Neuter","thayer":"<ol><li>kindred<ol type='a'><li>offspring</li><li>family</li><li>stock, tribe, nation<ol><li>i.e. nationality or descent from a particular people</li></ol><li>the aggregate of many individuals of the same nature, kind, sort</li></ol></li></ol>","xlit":"génos"},"G371":{"kjv_def":"unworthily","lemma":"ἀναξίως","translit":"anaxíōs","derivation":"adverb from G370 (ἀνάξιος);","strongs_def":" irreverently","pron":"an-ax-ee'-oce","pos":"Adverb","thayer":"<ol><li>in an unworthy manner</li></ol>","xlit":"anaxíōs"},"G3590":{"kjv_def":"eighth","translit":"ógdoos","lemma":"ὄγδοος","derivation":"from G3638 (ὀκτώ);","strongs_def":" the eighth","pron":"og'-do-os","pos":"Adjective","thayer":"<ol><li>the eighth</li></ol>","xlit":"ógdoos"},"G2544":{"kjv_def":"nevertheless, though","lemma":"καίτοιγε","translit":"kaítoige","derivation":"from G2543 (καίτοι) and G1065 (γέ);","strongs_def":" and yet indeed, i.e. although really","pron":"kah'-ee-toyg-eh","thayer":"<ol><li>and yet, thought</li></ol>","xlit":"kaítoige"},"G4165":{"strongs_def":" to tend as a shepherd of (figuratively, superviser)","derivation":"from G4166 (ποιμήν);","translit":"poimaínō","lemma":"ποιμαίνω","kjv_def":"feed (cattle), rule","pron":"poy-mah'-ee-no","pos":"Verb","thayer":"<ol><li>to feed, to tend a flock, keep sheep<ol type='a'><li>to rule, govern<ol><li>of rulers</li><li>to furnish pasture for food</li><li>to nourish</li><li>to cherish one's body, to serve the body</li><li>to supply the requisites for the soul's need</li></ol></li></ol></li></ol>","xlit":"poimaínō"},"G680":{"kjv_def":"touch","lemma":"ἅπτομαι","translit":"háptomai","derivation":"reflexive of G681 (ἅπτω);","strongs_def":" properly, to attach oneself to, i.e. to touch (in many implied relations)","pron":"hap'-tom-ahee","pos":"Verb","thayer":"<ol><li>to fasten one's self to, adhere to, cling to<ol type='a'><li>to touch</li><li>of carnal intercourse with a women or cohabitation</li><li>of levitical practice of having no fellowship with heathen practices. Things not to be touched appear to be both women and certain kinds of food, so celibacy and abstinence of certain kinds of food and drink are recommended.</li><li>to touch, assail anyone</li></ol></li></ol>","xlit":"háptomai"},"G1711":{"kjv_def":"merchandise","lemma":"ἐμπορία","translit":"emporía","derivation":"feminine from G1713 (ἔμπορος);","strongs_def":" traffic","pron":"em-por-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>trade, merchandise</li></ol>","xlit":"emporía"},"G2146":{"kjv_def":"make a fair show","translit":"euprosōpéō","lemma":"εὐπροσωπέω","derivation":"from a compound of G2095 (εὖ) and G4383 (πρόσωπον);","strongs_def":" to be of good countenance, i.e. (figuratively) to make a display","pron":"yoo-pros-o-peh'-o","pos":"Verb","thayer":"<ol><li>to make a fair show</li><li>to please</li></ol>","xlit":"euprosōpéō"},"G1686":{"strongs_def":" to whelm on, i.e. wet (a part of the person, etc.) by contact with a fluid","derivation":"from G1722 (ἐν) and G911 (βάπτω);","lemma":"ἐμβάπτω","translit":"embáptō","kjv_def":"dip","pron":"em-bap'-to","pos":"Verb","thayer":"<ol><li>to dip in</li></ol>","xlit":"embáptō"},"G4942":{"kjv_def":"dissemble with","translit":"synypokrínomai","lemma":"συνυποκρίνομαι","derivation":"from G4862 (σύν) and G5271 (ὑποκρίνομαι);","strongs_def":" to act hypocritically in concert with","pron":"soon-oo-pok-rin'-om-ahee","pos":"Verb","thayer":"<ol><li>to dissemble with</li><li>to act hypocritically with</li></ol>","xlit":"synypokrínomai"},"G1738":{"strongs_def":" in the right, i.e. equitable","derivation":"from G1722 (ἐν) and G1349 (δίκη);","translit":"éndikos","lemma":"ἔνδικος","kjv_def":"just","pron":"en'-dee-kos","pos":"Adjective","thayer":"<ol><li>according to right, righteous, just</li></ol>","xlit":"éndikos"},"G3954":{"strongs_def":" all out-spokenness, i.e. frankness, bluntness, publicity; by implication, assurance","derivation":"from G3956 (πᾶς) and a derivative of G4483 (ῥέω);","lemma":"παῤῥησία","translit":"parrhēsía","kjv_def":"bold (X -ly, -ness, -ness of speech), confidence, X freely, X openly, X plainly(-ness)","pron":"par-rhay-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>freedom in speaking, unreservedness in speech<ol type='a'><li>openly, frankly, i.e without concealment</li><li>without ambiguity or circumlocution</li><li>without the use of figures and comparisons</li></ol><li>free and fearless confidence, cheerful courage, boldness, assurance</li><li>the deportment by which one becomes conspicuous or secures publicity</li></ol>","xlit":"parrhēsía"},"G4471":{"kjv_def":"Rama","lemma":"Ῥαμᾶ","translit":"Rhamâ","derivation":"of Hebrew origin (H07414);","strongs_def":" Rama (i.e. Ramah), a place in Palestine","pron":"hram-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Ramah = \"a hill\"</p><ol><li>a town of the tribe of Benjamin, situated about 5 miles (8 km) north of Jerusalem on the road to Bethel</li></ol>","xlit":"Rhamâ"},"G1942":{"lemma":"ἐπικάλυμα","translit":"epikályma","kjv_def":"cloke","strongs_def":" a covering, i.e. (figuratively) pretext","derivation":"from G1943 (ἐπικαλύπτω);","pron":"ep-ee-kal'-oo-mah","pos":"Noun Neuter","thayer":"<ol><li>a covering, veil</li><li>metaphorically a pretext, cloak</li></ol>","xlit":"epikályma"},"G4485":{"derivation":"from G4486 (ῥήγνυμι);","strongs_def":" something torn, i.e. a fragment (by implication and abstractly, a fall)","kjv_def":"ruin","translit":"rhēgma","lemma":"ῥῆγμα","pron":"hrayg'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been broken or rent asunder<ol type='a'><li>a fracture, breach, cleft</li><li>rent clothes</li><li>fall, ruin</li></ol></li></ol>","xlit":"rhēgma"},"G4775":{"kjv_def":"sit with","lemma":"συγκάθημαι","translit":"synkáthēmai","derivation":"from G4862 (σύν) and G2521 (κάθημαι);","strongs_def":" to seat oneself in company with","pron":"soong-kath'-ay-mahee","pos":"Verb","thayer":"<ol><li>to sit together, to sit with one another</li></ol>","xlit":"synkáthēmai"},"G1764":{"strongs_def":" to place on hand, i.e. (reflexively) impend, (participle) be instant","derivation":"from G1722 (ἐν) and G2476 (ἵστημι);","lemma":"ἐνίστημι","translit":"enístēmi","kjv_def":"come, be at hand, present","pron":"en-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place in or among, to put in</li><li>to be upon, impend, threaten</li><li>close at hand</li><li>present</li></ol>","xlit":"enístēmi"},"G127":{"strongs_def":" bashfulness, i.e. (towards men), modesty or (towards God) awe","derivation":"perhaps from G1 (Α) (as a negative particle) and G1492 (εἴδω) (through the idea of downcast eyes);","lemma":"αἰδώς","translit":"aidṓs","kjv_def":"reverence, shamefacedness","pron":"ahee-doce'","pos":"Noun Feminine","thayer":"<ol><li>a sense of shame or honour, modesty, bashfulness, reverence, regard for others, respect</li></ol>","xlit":"aidṓs"},"G5610":{"strongs_def":" an \"hour\" (literally or figuratively)","derivation":"apparently a primary word;","translit":"hṓra","lemma":"ὥρα","kjv_def":"day, hour, instant, season, X short, (even-)tide, (high) time","pron":"ho'-rah","pos":"Noun Feminine","thayer":"<ol><li>a certain definite time or season fixed by natural law and returning with the revolving year<ol type='a'><li>of the seasons of the year, spring, summer, autumn, winter</li></ol><li>the daytime (bounded by the rising and setting of the sun), a day</li><li>a twelfth part of the day-time, an hour, (the twelve hours of the day are reckoned from the rising to the setting of the sun)</li><li>any definite time, point of time, moment</li></ol>","xlit":"hṓra"},"G2299":{"translit":"theá","lemma":"θεά","kjv_def":"goddess","strongs_def":" a female deity","derivation":"feminine of G2316 (θεός);","pron":"theh-ah'","pos":"Noun Feminine","thayer":"<ol><li>a goddess</li></ol>","xlit":"theá"},"G2345":{"derivation":"a prolonged form of an obsolete primary (to finger);","strongs_def":" to manipulate, i.e. have to do with; by implication, to injure","kjv_def":"handle, touch","translit":"thingánō","lemma":"θιγγάνω","pron":"thing-gan'-o","pos":"Verb","thayer":"<ol><li>to touch, handle<ol type='a'><li>to do violence to, injury</li></ol></li></ol>","xlit":"thingánō"},"G106":{"kjv_def":"unleavened (bread)","lemma":"ἄζυμος","translit":"ázymos","derivation":"from G1 (Α) (as a negative particle) and G2219 (ζύμη);","strongs_def":" unleavened, i.e. (figuratively) uncorrupted; (in the neutral plural) specially (by implication) the Passover week","pron":"ad'-zoo-mos","pos":"Adjective","thayer":"<ol><li>unfermented, free from leaven or yeast<ol type='a'><li>of the unleavened loaves used in the paschal feast of the Jews</li><li>metaphorically free from faults or the \"leaven of iniquity\"</li></ol></li></ol>","xlit":"ázymos"},"G1169":{"strongs_def":" timid, i.e. (by implication) faithless","derivation":"from (dread);","lemma":"δειλός","translit":"deilós","kjv_def":"fearful","pron":"di-los'","pos":"Adjective","thayer":"<ol><li>timid, fearful</li></ol>","xlit":"deilós"},"G1370":{"derivation":"from a derivative of G1364 (δίς) and G4714 (στάσις);","strongs_def":" disunion, i.e. (figuratively) dissension","kjv_def":"division, sedition","translit":"dichostasía","lemma":"διχοστασία","pron":"dee-khos-tas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>dissension, division</li></ol>","xlit":"dichostasía"},"G1147":{"strongs_def":" a finger","derivation":"probably from G1176 (δέκα);","translit":"dáktylos","lemma":"δάκτυλος","kjv_def":"finger","pron":"dak'-too-los","pos":"Noun Masculine","thayer":"<ol><li>a finger</li></ol>","xlit":"dáktylos"},"G4862":{"lemma":"σύν","translit":"sýn","kjv_def":"beside, with","strongs_def":" with or together (but much closer than G3326 (μετά) or G3844 (παρά)), i.e. by association, companionship, process, resemblance, possession, instrumentality, addition, etc.","derivation":"a primary preposition denoting union;","pron":"soon","pos":"Preposition","thayer":"<ol><li>with</li></ol>","xlit":"sýn"},"G1704":{"lemma":"ἐμπεριπατέω","translit":"emperipatéō","kjv_def":"walk in","strongs_def":" to perambulate on a place, i.e. (figuratively) to be occupied among persons","derivation":"from G1722 (ἐν) and G4043 (περιπατέω);","pron":"em-per-ee-pat-eh'-o","pos":"Verb","thayer":"<ol><li>to go about in, walk in</li></ol>","xlit":"emperipatéō"},"G4031":{"kjv_def":"+ come by","translit":"perikratḗs","lemma":"περικρατής","derivation":"from G4012 (περί) and G2904 (κράτος);","strongs_def":" strong all around, i.e. a master (manager)","pron":"per-ee-krat-ace'","pos":"Adjective","thayer":"<ol><li>having power over a thing</li></ol>","xlit":"perikratḗs"},"G1578":{"kjv_def":"avoid, eschew, go out of the way","lemma":"ἐκκλίνω","translit":"ekklínō","derivation":"from G1537 (ἐκ) and G2827 (κλίνω);","strongs_def":" to deviate, i.e. (absolutely) to shun (literally or figuratively), or (relatively) to decline (from piety)","pron":"ek-klee'-no","pos":"Verb","thayer":"<ol><li>to turn aside, deviate (from the right way and course)</li><li>to turn (one's self) away, to turn away from, keep aloof from one's society</li><li>to shun one</li></ol>","xlit":"ekklínō"},"G533":{"translit":"aparnéomai","lemma":"ἀπαρνέομαι","kjv_def":"deny","strongs_def":" to deny utterly, i.e. disown, abstain","derivation":"from G575 (ἀπό) and G720 (ἀρνέομαι);","pron":"ap-ar-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to deny<ol type='a'><li>to affirm that one has no acquaintance or connection with someone</li><li>to forget one's self, lose sight of one's self and one's own interests</li></ol></li></ol>","xlit":"aparnéomai"},"G1884":{"strongs_def":" to avail for, i.e. help","derivation":"from G1909 (ἐπί) and G714 (ἀρκέω);","translit":"eparkéō","lemma":"ἐπαρκέω","kjv_def":"relieve","pron":"ep-ar-keh'-o","pos":"Verb","thayer":"<ol><li>to avail or be strong enough for<ol type='a'><li>to ward off or drive away, a thing for another's advantage<ol><li>a thing from anyone, to defend</li></ol><li>to aid, give assistance, relieve<ol><li>to give aid from one's own resources</li></ol></li></ol></li></ol>","xlit":"eparkéō"},"G5589":{"kjv_def":"crumb","lemma":"ψιχίον","translit":"psichíon","derivation":"diminutive from a derivative of the base of G5567 (ψάλλω) (meaning a crumb);","strongs_def":" a little bit or morsel","pron":"psikh-ee'-on","pos":"Noun Neuter","thayer":"<ol><li>a little morsel, a crumb</li></ol>","xlit":"psichíon"},"G3424":{"derivation":"from G3425 (μόγις) and G2980 (λαλέω);","strongs_def":" hardly talking, i.e. dumb (tongue-tied)","kjv_def":"having an impediment in his speech","translit":"mogilálos","lemma":"μογιλάλος","pron":"mog-il-al'-os","pos":"Adjective","thayer":"<ol><li>speaking with difficulty</li></ol>","xlit":"mogilálos"},"G652":{"lemma":"ἀπόστολος","translit":"apóstolos","kjv_def":"apostle, messenger, he that is sent","strongs_def":" a delegate; specially, an ambassador of the Gospel; officially a commissioner of Christ (\"apostle\") (with miraculous powers)","derivation":"from G649 (ἀποστέλλω);","pron":"ap-os'-tol-os","pos":"Noun Masculine","thayer":"<ol><li>a delegate, messenger, one sent forth with orders<ol type='a'><li>specifically applied to the twelve apostles of Christ</li><li>in a broader sense applied to other eminent Christian teachers<ol><li>of Barnabas</li><li>of Timothy and Silvanus</li></ol></li></ol></li></ol>","xlit":"apóstolos"},"G3715":{"kjv_def":"lust","lemma":"ὄρεξις","translit":"órexis","derivation":"from G3713 (ὀρέγομαι);","strongs_def":" excitement of the mind, i.e. longing after","pron":"or'-ex-is","pos":"Noun Feminine","thayer":"<ol><li>desire, longing, craving for</li><li>eager desire, lust, appetite<ol type='a'><li>used both in a good and a bad sense, as well of natural and lawful and even of proper cravings (of appetite for food), also of corrupt and unlawful desires</li></ol></li></ol>","xlit":"órexis"},"G3636":{"kjv_def":"grievous, slothful","translit":"oknērós","lemma":"ὀκνηρός","derivation":"from G3635 (ὀκνέω);","strongs_def":" tardy, i.e. indolent; (figuratively) irksome","pron":"ok-nay-ros'","pos":"Adjective","thayer":"<ol><li>sluggish, slothful, backward</li></ol>","xlit":"oknērós"},"G4185":{"derivation":"from G4183 (πολύς) and G5056 (τέλος);","strongs_def":" extremely expensive","kjv_def":"costly, very precious, of great price","translit":"polytelḗs","lemma":"πολυτελής","pron":"pol-oo-tel-ace'","pos":"Adjective","thayer":"<ol><li>precious<ol type='a'><li>requiring very great outlay, very costly</li><li>excellent, of surpassing value</li></ol></li></ol>","xlit":"polytelḗs"},"G4281":{"derivation":"from G4253 (πρό) and G2064 (ἔρχομαι) (including its alternate);","strongs_def":" to go onward, precede (in place or time)","kjv_def":"go before (farther, forward), outgo, pass on","lemma":"προέρχομαι","translit":"proérchomai","pron":"pro-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go forward, go on</li><li>to go before<ol type='a'><li>to go before, precede</li><li>to go before, in the advance of another</li></ol></li></ol>","xlit":"proérchomai"},"G1535":{"kjv_def":"if, or, whether","lemma":"εἴτε","translit":"eíte","derivation":"from G1487 (εἰ) and G5037 (τέ);","strongs_def":" if too","pron":"i'-teh","pos":"Conjunction","thayer":"<ol><li>if ... if</li><li>whether ... or</li></ol>","xlit":"eíte"},"G2456":{"strongs_def":" Julia, a Christian woman","derivation":"feminine of the same as G2457 (Ἰούλιος);","translit":"Ioulía","lemma":"Ἰουλία","kjv_def":"Julia","pron":"ee-oo-lee'-ah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Julia = \"soft haired\"</p><ol><li>a Christian woman</li></ol>","xlit":"Ioulía"},"G1955":{"derivation":"from G1956 (ἐπιλύω);","strongs_def":" explanation, i.e. application","kjv_def":"interpretation","lemma":"ἐπίλυσις","translit":"epílysis","pron":"ep-il'-oo-sis","pos":"Noun Feminine","thayer":"<ol><li>a loosening, unloosing</li><li>metaphorically interpretation</li></ol>","xlit":"epílysis"},"G2994":{"translit":"Laodikeús","lemma":"Λαοδικεύς","kjv_def":"Laodicean","strongs_def":" a Laodicean, i.e. inhabitant of Laodicia","derivation":"from G2993 (Λαοδίκεια);","pron":"lah-od-ik-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a Laodicean, an inhabitant of Laodicea</li></ol>","xlit":"Laodikeús"},"G2198":{"strongs_def":" to live (literally or figuratively)","derivation":"a primary verb;","lemma":"ζάω","translit":"záō","kjv_def":"life(-time), (a-)live(-ly), quick","pron":"dzah'-o","pos":"Verb","thayer":"<ol><li>to live, breathe, be among the living (not lifeless, not dead)</li><li>to enjoy real life<ol type='a'><li>to have true life and worthy of the name</li><li>active, blessed, endless in the kingdom of God</li></ol><li>to live, i.e. pass life, in the manner of the living and acting<ol type='a'><li>of mortals or character</li></ol><li>living water, having vital power in itself and exerting the same upon the soul</li><li>metaphorically to be in full vigour<ol type='a'><li>to be fresh, strong, efficient</li><li>as adjective active, powerful, efficacious</li></ol></li></ol>","xlit":"záō"},"G1571":{"kjv_def":"purge (out)","lemma":"ἐκκαθαίρω","translit":"ekkathaírō","derivation":"from G1537 (ἐκ) and G2508 (καθαίρω);","strongs_def":" to cleanse thoroughly","pron":"ek-kath-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to cleanse out, clean thoroughly, to cleanse</li></ol>","xlit":"ekkathaírō"},"G3370":{"kjv_def":"Mede","translit":"Mēdos","lemma":"Μῆδος","derivation":"of foreign origin (compare H04074);","strongs_def":" a Median, or inhabitant of Media","pron":"may'-dos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mede or Media = \"middle land\"</p><ol><li>a Mede, a native or inhabitant of Media, a well known region of Asia whose chief city was Ecbatana</li></ol>","xlit":"Mēdos"},"G4685":{"strongs_def":" to draw","derivation":"a primary verb;","lemma":"σπάω","translit":"spáō","kjv_def":"draw (out)","pron":"spah'-o","pos":"Verb","thayer":"<ol><li>to draw</li><li>to draw (one's sword)</li></ol>","xlit":"spáō"},"G3542":{"strongs_def":" pasture, i.e. (the act) feeding (figuratively, spreading of a gangrene), or (the food) pasturage","derivation":"feminine from the same as G3551 (νόμος);","translit":"nomḗ","lemma":"νομή","kjv_def":"X eat, pasture","pron":"nom-ay'","pos":"Noun Feminine","thayer":"<ol><li>pasturage, fodder, food<ol type='a'><li>fig. he shall not want the needful supplies for the true life</li></ol><li>growth, increase<ol type='a'><li>of evils spreading like a gangrene</li><li>of ulcers</li><li>of a conflagration</li></ol></li></ol>","xlit":"nomḗ"},"G5024":{"translit":"tautá","lemma":"ταὐτά","kjv_def":"even thus, (manner) like, so","strongs_def":" in the same way","derivation":"neuter plural of G3588 (ὁ) and G846 (αὐτός) as adverb;","pron":"tow-tah'","thayer":"<ol><li>even, thus, in the same way</li></ol>","xlit":"tautá"},"G2141":{"strongs_def":" (intransitively) to be good for passing through, i.e. (figuratively) have pecuniary means","derivation":"from a compound of G2090 (ἑτοιμάζω) and the base of G4197 (πορεία);","lemma":"εὐπορέω","translit":"euporéō","kjv_def":"ability","pron":"yoo-por-eh'-o","pos":"Verb","thayer":"<ol><li>to be well off, have means</li></ol>","xlit":"euporéō"},"G3982":{"strongs_def":" to convince (by argument, true or false); by analogy, to pacify or conciliate (by other fair means); reflexively or passively, to assent (to evidence or authority), to rely (by inward certainty)","derivation":"a primary verb;","translit":"peíthō","lemma":"πείθω","kjv_def":"agree, assure, believe, have confidence, be (wax) conflent, make friend, obey, persuade, trust, yield","pron":"pi'-tho","pos":"Verb","thayer":"<ol><li>persuade<ol type='a'><li>to persuade, i.e. to induce one by words to believe</li><li>to make friends of, to win one's favour, gain one's good will, or to seek to win one, strive to please one</li><li>to tranquillise</li><li>to persuade unto, i.e. move or induce one to persuasion to do something</li></ol><li>be persuaded<ol type='a'><li>to be persuaded, to suffer one's self to be persuaded; to be induced to believe: to have faith: in a thing<ol><li>to believe</li><li>to be persuaded of a thing concerning a person</li></ol><li>to listen to, obey, yield to, comply with</li></ol><li>to trust, have confidence, be confident</li></ol>","xlit":"peíthō"},"G2597":{"strongs_def":" to descend (literally or figuratively)","derivation":"from G2596 (κατά) and the base of G939 (βάσις);","lemma":"καταβαίνω","translit":"katabaínō","kjv_def":"come (get, go, step) down, fall (down)","pron":"kat-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to go down, come down, descend<ol type='a'><li>the place from which one has come down from</li><li>to come down<ol><li>as from the temple at Jerusalem, from the city of Jerusalem</li><li>of celestial beings coming down to earth</li></ol><li>to be cast down</li></ol><li>of things<ol type='a'><li>to come (i.e. be sent) down</li><li>to come (i.e. fall) down<ol><li>from the upper regions of the air</li></ol></li></ol><li>metaphorically to (go, i.e.) be cast down to the lowest state of wretchedness and shame</li></ol>","xlit":"katabaínō"},"G11":{"kjv_def":"Abraham","translit":"Abraám","lemma":"Ἀβραάμ","derivation":"of Hebrew origin (H085);","strongs_def":" Abraham, the Hebrew patriarch","pron":"ab-rah-am'","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Abraham = \"father of a multitude\"</p><ol><li>the son of Terah and the founder of the Jewish nation</li></ol>","xlit":"Abraám"},"G2441":{"strongs_def":" clothing","derivation":"from G2439 (ἱματίζω);","lemma":"ἱματισμός","translit":"himatismós","kjv_def":"apparel (X -led), array, raiment, vesture","pron":"him-at-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>clothing, apparel</li></ol>","xlit":"himatismós"},"G5240":{"derivation":"from G5228 (ὑπέρ) and the alternate form of G1632 (ἐκχέω);","strongs_def":" to pour out over, i.e. (passively) to overflow","kjv_def":"run over","lemma":"ὑπερεκχύνω","translit":"hyperekchýnō","pron":"hoop-er-ek-khoo'-no","pos":"Verb","thayer":"<ol><li>to pour out beyond measure</li><li>to overflow, run over</li></ol>","xlit":"hyperekchýnō"},"G4187":{"kjv_def":"in divers manners","lemma":"πολυτρόπως","translit":"polytrópōs","derivation":"adverb from a compound of G4183 (πολύς) and G5158 (τρόπος);","strongs_def":" in many ways, i.e. variously as to method or form","pron":"pol-oot-rop'-oce","pos":"Adverb","thayer":"<ol><li>in many manners</li></ol>","xlit":"polytrópōs"},"G3975":{"translit":"pachýnō","lemma":"παχύνω","kjv_def":"wax gross","strongs_def":" to thicken, i.e. (by implication) to fatten (figuratively, stupefy or render callous)","derivation":"from a derivative of G4078 (πήγνυμι) (meaning thick);","pron":"pakh-oo'-no","pos":"Verb","thayer":"<ol><li>to make thick, to make fat, fatten</li><li>metaphorically to make stupid (to render the soul dull or callous)</li></ol>","xlit":"pachýnō"},"G3743":{"strongs_def":" piously","derivation":"adverb from G3741 (ὅσιος);","translit":"hosíōs","lemma":"ὁσίως","kjv_def":"holily","pron":"hos-ee-oce'","pos":"Adverb","thayer":"<ol><li>piously, holily</li></ol>","xlit":"hosíōs"},"G1881":{"derivation":"middle voice from G1909 (ἐπί) and G450 (ἀνίστημι);","strongs_def":" to stand up on, i.e. (figuratively) to attack","kjv_def":"rise up against","lemma":"ἐπανίσταμαι","translit":"epanístamai","pron":"ep-an-is'-tam-ahee","pos":"Verb","thayer":"<ol><li>to cause to rise up against, to raise up against</li></ol>","xlit":"epanístamai"},"G3166":{"kjv_def":"boast great things","lemma":"μεγαλαυχέω","translit":"megalauchéō","derivation":"from a compound of G3173 (μέγας) and (to boast;","strongs_def":" akin to G837 (αὐξάνω) and G2744 (καυχάομαι)); to talk big, i.e. be grandiloquent (arrogant, egotistic)","pron":"meg-al-ow-kheh'-o","pos":"Verb","thayer":"<ol><li>to be grandiloquent</li><li>to boast great things, to bear one's self loftily in speech or action</li></ol>","xlit":"megalauchéō"},"G4728":{"lemma":"στενός","translit":"stenós","kjv_def":"strait","strongs_def":" narrow (from obstacles standing close about)","derivation":"probably from the base of G2476 (ἵστημι);","pron":"sten-os'","pos":"Adjective","thayer":"<ol><li>narrow, strait</li></ol>","xlit":"stenós"},"G1132":{"kjv_def":"nakedness","lemma":"γυμνότης","translit":"gymnótēs","derivation":"from G1131 (γυμνός);","strongs_def":" nudity (absolute or comparative)","pron":"goom-not'-ace","pos":"Noun Feminine","thayer":"<ol><li>nakedness of the body</li></ol>","xlit":"gymnótēs"},"G1781":{"lemma":"ἐντέλλομαι","translit":"entéllomai","kjv_def":"(give) charge, (give) command(-ments), injoin","strongs_def":" to enjoin","derivation":"from G1722 (ἐν) and the base of G5056 (τέλος);","pron":"en-tel'-lom-ahee","pos":"Verb","thayer":"<ol><li>to order, command to be done, enjoin</li></ol>","xlit":"entéllomai"},"G376":{"translit":"anápēros","lemma":"ἀνάπηρος","kjv_def":"maimed","strongs_def":" crippled","derivation":"from G303 (ἀνά) (in the sense of intensity) and (maimed);","pron":"an-ap'-ay-ros","pos":"Adjective","thayer":"<ol><li>disabled in the limbs, maimed, crippled</li><li>injured in, or bereft of, some member of the body</li></ol>","xlit":"anápēros"},"G3065":{"derivation":"contracted from Latin Lucanus;","strongs_def":" Lucas, a Christian","kjv_def":"Lucas, Luke","translit":"Loukâs","lemma":"Λουκᾶς","pron":"loo-kas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Luke or Lucus = \"light-giving\"</p><ol><li>a Gentile Christian, the companion of Paul in preaching the gospel and on his many journeys; he was a physician and author of the book of Luke and Acts in the NT</li></ol>","xlit":"Loukâs"},"G5588":{"derivation":"from the same as G5587 (ψιθυρισμός);","strongs_def":" a secret calumniator","kjv_def":"whisperer","lemma":"ψιθυριστής","translit":"psithyristḗs","pron":"psith-oo-ris-tace'","pos":"Noun Masculine","thayer":"<ol><li>a whisperer, secret slanderer, detractor</li></ol>","xlit":"psithyristḗs"},"G5190":{"translit":"Tychikós","lemma":"Τυχικός","kjv_def":"Tychicus","strongs_def":" fortuitous, i.e. fortunate; Tychicus, a Christian","derivation":"from a derivative of G5177 (τυγχάνω);","pron":"too-khee-kos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tychicus = \"fateful\"</p><ol><li>an Asiatic Christian, friend and companion of the apostle Paul</li></ol>","xlit":"Tychikós"},"G2787":{"derivation":"of uncertain derivation;","strongs_def":" a box, i.e. the sacred ark and that of Noah","kjv_def":"ark","translit":"kibōtós","lemma":"κιβωτός","pron":"kib-o-tos'","pos":"Noun Feminine","thayer":"<ol><li>a wooden chest or box</li><li>in the NT the ark of the covenant, in the temple at Jerusalem</li><li>of Noah's vessel built in the form of an ark</li></ol>","xlit":"kibōtós"},"G1431":{"derivation":"from G1435 (δῶρον);","strongs_def":" a gratuity","kjv_def":"gift","lemma":"δωρεά","translit":"dōreá","pron":"do-reh-ah'","pos":"Noun Feminine","thayer":"<ol><li>a gift</li></ol>","xlit":"dōreá"},"G1984":{"kjv_def":"the office of a \"bishop\", bishoprick, visitation","translit":"episkopḗ","lemma":"ἐπισκοπή","derivation":"from G1980 (ἐπισκέπτομαι);","strongs_def":" inspection (for relief); by implication, superintendence; specially, the Christian \"episcopate\"","pron":"ep-is-kop-ay'","pos":"Noun Feminine","thayer":"<ol><li>investigation, inspection, visitation<ol type='a'><li>that act by which God looks into and searches out the ways, deeds character, of men, in order to adjudge them their lot accordingly, whether joyous or sad</li><li>oversight<ol><li>overseership, office, charge, the office of an elder</li><li>the overseer or presiding officers of a Christian church</li></ol></li></ol></li></ol>","xlit":"episkopḗ"},"G1243":{"kjv_def":"difference, diversity","translit":"diaíresis","lemma":"διαίρεσις","derivation":"from G1244 (διαιρέω);","strongs_def":" a distinction or (concretely) variety","pron":"dee-ah'-ee-res-is","pos":"Noun Feminine","thayer":"<ol><li>division, distribution</li><li>distinction, difference<ol type='a'><li>in particular, a distinction arising from a different distribution to different persons</li></ol></li></ol>","xlit":"diaíresis"},"G79":{"strongs_def":" a sister (naturally or ecclesiastically)","derivation":"feminine of G80 (ἀδελφός);","translit":"adelphḗ","lemma":"ἀδελφή","kjv_def":"sister","pron":"ad-el-fay'","pos":"Noun Feminine","thayer":"<ol><li>a full, own sister</li><li>one connected by the tie of the Christian religion</li></ol>","xlit":"adelphḗ"},"G256":{"derivation":"of Hebrew origin (compare H02501);","strongs_def":" Alphæus, an Israelite","kjv_def":"Alpheus","translit":"Alphaîos","lemma":"Ἀλφαῖος","pron":"al-fah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Alphaeus = \"changing\"</p><ol><li>The father of Levi the publican (<a class='bible' href='#b41.2.14'>Mar 2:14</a>)</li><li>The father of James the less, so called, one of the apostles</li></ol>","xlit":"Alphaîos"},"G2803":{"lemma":"Κλαυδία","translit":"Klaudía","kjv_def":"Claudia","strongs_def":" Claudia, a Christian woman","derivation":"feminine of G2804 (Κλαύδιος);","pron":"klow-dee'-ah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Claudia = \"lame\"</p><ol><li>a Christian woman</li></ol>","xlit":"Klaudía"},"G5229":{"translit":"hyperaíromai","lemma":"ὑπεραίρομαι","kjv_def":"exalt self, be exalted above measure","strongs_def":" to raise oneself over, i.e. (figuratively) to become haughty","derivation":"middle voice from G5228 (ὑπέρ) and G142 (αἴρω);","pron":"hoop-er-ah'-ee-rom-ahee","pos":"Verb","thayer":"<ol><li>to lift or raise up over some thing</li><li>to lift one's self up, be exalted, be haughty</li><li>to carry one's self haughtily to, behave insolently towards one</li></ol>","xlit":"hyperaíromai"},"G3846":{"kjv_def":"arrive, compare","translit":"parabállō","lemma":"παραβάλλω","derivation":"from G3844 (παρά) and G906 (βάλλω);","strongs_def":" to throw alongside, i.e. (reflexively) to reach a place, or (figuratively) to liken","pron":"par-ab-al'-lo","pos":"Verb","thayer":"<ol><li>to throw before, cast to (as fodder for horses)</li><li>to put one thing by the side of another for the sake of comparison, to compare, liken</li><li>to put one's self, betake one's self into a place or to a person</li></ol>","xlit":"parabállō"},"G835":{"derivation":"middle voice from G833 (αὐλή);","strongs_def":" to pass the night (properly, in the open air)","kjv_def":"abide, lodge","lemma":"αὐλίζομαι","translit":"aulízomai","pron":"ow-lid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to lodge in the court-yard, especially at night<ol type='a'><li>of flocks and shepherds</li></ol><li>to pass the night in the open air</li><li>to pass the night, lodge</li></ol>","xlit":"aulízomai"},"G2231":{"strongs_def":" government, i.e. (in time) official term","derivation":"from G2232 (ἡγεμών);","translit":"hēgemonía","lemma":"ἡγεμονία","kjv_def":"reign","pron":"hayg-em-on-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>chief command, rule, sovereignty<ol type='a'><li>of the reign of a Roman emperor</li></ol></li></ol>","xlit":"hēgemonía"},"G2045":{"kjv_def":"search","lemma":"ἐρευνάω","translit":"ereunáō","derivation":"apparently from G2046 (ἐρέω) (through the idea of inquiry);","strongs_def":" to seek, i.e. (figuratively) to investigate","pron":"er-yoo-nah'-o","pos":"Verb","thayer":"<ol><li>to search, examine into</li></ol>","xlit":"ereunáō"},"G4318":{"translit":"prosagōgḗ","lemma":"προσαγωγή","kjv_def":"access","strongs_def":" admission","derivation":"from G4317 (προσάγω) (compare G72 (ἀγωγή));","pron":"pros-ag-ogue-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act of bringing to, a moving to</li><li>access, approach<ol type='a'><li>to God, i.e. that relationship with God whereby we are acceptable to him and have assurance that he is favourably disposed towards him</li></ol></li></ol>","xlit":"prosagōgḗ"},"G2107":{"kjv_def":"desire, good pleasure (will), X seem good","translit":"eudokía","lemma":"εὐδοκία","derivation":"from a presumed compound of G2095 (εὖ) and the base of G1380 (δοκέω);","strongs_def":" satisfaction, i.e. (subjectively) delight, or (objectively) kindness, wish, purpose","pron":"yoo-dok-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>will, choice<ol type='a'><li>good will, kindly intent, benevolence</li></ol><li>delight, pleasure, satisfaction</li><li>desire<ol type='a'><li>for delight in any absent thing easily produces longing for it</li></ol></li></ol>","xlit":"eudokía"},"G4894":{"derivation":"from G4862 (σύν) and G1492 (εἴδω);","strongs_def":" to see completely; used (like its primary) only in two past tenses, respectively meaning to understand or become aware, and to be conscious or (clandestinely) informed of","kjv_def":"consider, know, be privy, be ware of","translit":"syneídō","lemma":"συνείδω","pron":"soon-i'-do","pos":"Verb","thayer":"<ol><li>to see (have seen) together with others</li><li>to see (have seen) in one's mind with one's self<ol type='a'><li>to understand, perceive, comprehend</li></ol><li>to know with another</li><li>to know in one's mind or with one's self, to be conscience of</li></ol>","xlit":"syneídō"},"G3454":{"kjv_def":"fable","lemma":"μῦθος","translit":"mŷthos","derivation":"perhaps from the same as G3453 (μυέω) (through the idea of tuition);","strongs_def":" a tale, i.e. fiction (\"myth\")","pron":"moo'-thos","pos":"Noun Masculine","thayer":"<ol><li>a speech, word, saying</li><li>a narrative, story<ol type='a'><li>a true narrative</li><li>a fiction, a fable<ol><li>an invention, a falsehood</li></ol></li></ol></li></ol>","xlit":"mŷthos"},"G1467":{"kjv_def":"can(-not) contain, be temperate","translit":"enkrateúomai","lemma":"ἐγκρατεύομαι","derivation":"middle voice from G1468 (ἐγκρατής);","strongs_def":" to exercise self-restraint (in diet and chastity)","pron":"eng-krat-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to be self-controlled, continent<ol type='a'><li>to exhibit self-government, conduct, one's self temperately</li><li>in a figure drawn from athletes, who in preparing themselves for the games abstained from unwholesome food, wine, and sexual indulgence</li></ol></li></ol>","xlit":"enkrateúomai"},"G3864":{"derivation":"from G3844 (παρά) and G2281 (θάλασσα);","strongs_def":" along the sea, i.e. maritime (lacustrine)","kjv_def":"upon the sea coast","lemma":"παραθαλάσσιος","translit":"parathalássios","pron":"par-ath-al-as'-see-os","pos":"Adjective","thayer":"<ol><li>besides the sea, by the sea</li></ol>","xlit":"parathalássios"},"G711":{"strongs_def":" best counselling; Aristoboulus, a Christian","derivation":"from the same as G712 (ἄριστον) and G1012 (βουλή);","lemma":"Ἀριστόβουλος","translit":"Aristóboulos","kjv_def":"Aristobulus","pron":"ar-is-tob'-oo-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aristobulus = \"the best councillor\"</p><ol><li>a certain Christian</li></ol>","xlit":"Aristóboulos"},"G609":{"derivation":"from G575 (ἀπό) and G2875 (κόπτω);","strongs_def":" to amputate; reflexively (by irony) to mutilate (the privy parts)","kjv_def":"cut off","translit":"apokóptō","lemma":"ἀποκόπτω","pron":"ap-ok-op'-to","pos":"Verb","thayer":"<ol><li>to cut off, amputate</li></ol>","xlit":"apokóptō"},"G2718":{"kjv_def":"come (down), depart, descend, go down, land","lemma":"κατέρχομαι","translit":"katérchomai","derivation":"from G2596 (κατά) and G2064 (ἔρχομαι) (including its alternate);","strongs_def":" to come (or go) down (literally or figuratively)","pron":"kat-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come down, go down<ol type='a'><li>of one who goes from a higher to a lower locality</li><li>of those who come to a place by a ship</li></ol></li></ol>","xlit":"katérchomai"},"G4649":{"strongs_def":" perhaps akin to G4626 (σκάπτω) through the idea of concealment; compare G4629 (σκέπασμα)); a watch (sentry or scout), i.e. (by implication) a goal","derivation":"from (to peer about (\"skeptic\");","lemma":"σκοπός","translit":"skopós","kjv_def":"mark","pron":"skop-os'","pos":"Noun Masculine","thayer":"<ol><li>an observer, a watchman</li><li>the distant mark looked at, the goal or end one has in view</li></ol>","xlit":"skopós"},"G2335":{"derivation":"from the same as G2334 (θεωρέω);","strongs_def":" spectatorship, i.e. (concretely) a spectacle","kjv_def":"sight","translit":"theōría","lemma":"θεωρία","pron":"theh-o-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a viewing, beholding</li><li>that which is viewed, a spectacle, sight</li></ol>","xlit":"theōría"},"G2665":{"kjv_def":"vail","translit":"katapétasma","lemma":"καταπέτασμα","derivation":"from a compound of G2596 (κατά) and a congener of G4072 (πέτομαι);","strongs_def":" something spread thoroughly, i.e. (specially) the door screen (to the Most Holy Place) in the Jewish Temple","pron":"kat-ap-et'-as-mah","pos":"Noun Neuter","thayer":"<ol><li>a veil spread out, a curtain<ol type='a'><li>the name given to the two curtains in the temple at Jerusalem, one of them at the entrance to the temple separated the Holy Place from the outer court, the other veiled the Holy of Holies from the Holy Place</li></ol></li></ol>","xlit":"katapétasma"},"G5544":{"lemma":"χρηστότης","translit":"chrēstótēs","kjv_def":"gentleness, good(-ness), kindness","strongs_def":" usefulness, i.e. morally, excellence (in character or demeanor)","derivation":"from G5543 (χρηστός);","pron":"khray-stot'-ace","pos":"Noun Feminine","thayer":"<ol><li>moral goodness, integrity</li><li>benignity, kindness</li></ol>","xlit":"chrēstótēs"},"G1451":{"translit":"engýs","lemma":"ἐγγύς","kjv_def":"from , at hand, near, nigh (at hand, unto), ready","strongs_def":" akin to the base of G43 (ἀγκάλη)); near (literally or figuratively, of place or time)","derivation":"from a primary verb (to squeeze or throttle;","pron":"eng-goos'","pos":"Adverb","thayer":"<ol><li>near, of place and position<ol type='a'><li>near</li><li>those who are near access to God<ol><li>Jews, as opposed to those who are alien from God and his blessings</li><li>The Rabbis used the term \"to make nigh\" as equivalent to \"to make a proselyte\"</li></ol></li></ol><li>of time<ol type='a'><li>of times imminent and soon to come pass</li></ol></li></ol>","xlit":"engýs"},"G4357":{"kjv_def":"abide still, be with, cleave unto, continue in (with)","translit":"prosménō","lemma":"προσμένω","derivation":"from G4314 (πρός) and G3306 (μένω);","strongs_def":" to stay further, i.e. remain in a place, with a person; figuratively, to adhere to, persevere in","pron":"pros-men'-o","pos":"Verb","thayer":"<ol><li>to remain with, to continue with one</li><li>to hold fast to: the grace of God received in the Gospel</li><li>to remain still, tarry, stay</li></ol>","xlit":"prosménō"},"G5587":{"translit":"psithyrismós","lemma":"ψιθυρισμός","kjv_def":"whispering","strongs_def":" by implication, a slander; probably akin to G5574 (ψεύδομαι)); whispering, i.e. secret detraction","derivation":"from a derivative of (a whisper;","pron":"psith-oo-ris-mos'","pos":"Masculine Neuter","thayer":"<ol><li>a whispering, i.e. secret slandering</li><li>of the magical murmuring of a charmer of snakes</li></ol>","xlit":"psithyrismós"},"G1991":{"derivation":"from G1909 (ἐπί) and G4741 (στηρίζω);","strongs_def":" to support further, i.e. reestablish","kjv_def":"confirm, strengthen","lemma":"ἐπιστηρίζω","translit":"epistērízō","pron":"ep-ee-stay-rid'-zo","pos":"Verb","thayer":"<ol><li>to establish besides, strengthen more</li><li>to render more firm, confirm</li></ol>","xlit":"epistērízō"},"G5044":{"kjv_def":"bring up children","translit":"teknotrophéō","lemma":"τεκνοτροφέω","derivation":"from a compound of G5043 (τέκνον) and G5142 (τρέφω);","strongs_def":" to be a childrearer, i.e. fulfil the duties of a female parent","pron":"tek-not-rof-eh'-o","pos":"Verb","thayer":"<ol><li>to bring up children</li></ol>","xlit":"teknotrophéō"},"G4750":{"kjv_def":"edge, face, mouth","translit":"stóma","lemma":"στόμα","derivation":"probably strengthened from a presumed derivative of the base of G5114 (τομώτερος);","strongs_def":" the mouth (as if a gash in the face); by implication, language (and its relations); figuratively, an opening (in the earth); specially, the front or edge (of a weapon)","pron":"stom'-a","pos":"Noun Neuter","thayer":"<ol><li>the mouth, as part of the body: of man, of animals, of fish, etc.<ol type='a'><li>since thoughts of a man's soul find verbal utterance by his mouth, the \"heart\" or \"soul\" and the mouth are distinguished</li></ol><li>the edge of a sword</li></ol>","xlit":"stóma"},"G2078":{"lemma":"ἔσχατος","translit":"éschatos","kjv_def":"ends of, last, latter end, lowest, uttermost","strongs_def":" farthest, final (of place or time)","derivation":"a superlative probably from G2192 (ἔχω) (in the sense of contiguity);","pron":"es'-khat-os","pos":"Adjective","thayer":"<ol><li>extreme<ol type='a'><li>last in time or in place</li><li>last in a series of places</li><li>last in a temporal succession</li></ol><li>the last<ol type='a'><li>last, referring to time</li><li>of space, the uttermost part, the end, of the earth</li><li>of rank, grade of worth, last, i.e. lowest</li></ol></li></ol>","xlit":"éschatos"},"G2177":{"kjv_def":"leap on","translit":"ephállomai","lemma":"ἐφάλλομαι","derivation":"from G1909 (ἐπί) and G242 (ἅλλομαι);","strongs_def":" to spring upon","pron":"ef-al'-lom-ahee","pos":"Verb","thayer":"<ol><li>to leap upon, spring upon</li></ol>","xlit":"ephállomai"},"G3033":{"kjv_def":"Libya","translit":"Libýē","lemma":"Λιβύη","derivation":"probably from G3047 (λίψ);","strongs_def":" Libye, a region of Africa","pron":"lib-oo'-ay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Libya = \"afflicted or weeping\"</p><ol><li>a large region of northern Africa, bordering Egypt. In that portion of it which had Cyrene for its capital and was thence called Libya Cyrenaica.</li></ol>","xlit":"Libýē"},"G2019":{"strongs_def":" to call at something, i.e. exclaim","derivation":"from G1909 (ἐπί) and G5455 (φωνέω);","lemma":"ἐπιφωνέω","translit":"epiphōnéō","kjv_def":"cry (against), give a shout","pron":"ep-ee-fo-neh'-o","pos":"Verb","thayer":"<ol><li>to call out to, shout</li></ol>","xlit":"epiphōnéō"},"G402":{"lemma":"ἀναχωρέω","translit":"anachōréō","kjv_def":"depart, give place, go (turn) aside, withdraw self","strongs_def":" to retire","derivation":"from G303 (ἀνά) and G5562 (χωρέω);","pron":"an-akh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to go back, return</li><li>to withdraw<ol type='a'><li>so as to leave a room</li><li>of those who through fear seek some other place, or shun sight</li></ol></li></ol>","xlit":"anachōréō"},"G3498":{"kjv_def":"dead","translit":"nekrós","lemma":"νεκρός","derivation":"from an apparently primary (a corpse);","strongs_def":" dead (literally or figuratively; also as noun)","pron":"nek-ros'","pos":"Adjective","thayer":"<ol><li>properly<ol type='a'><li>one that has breathed his last, lifeless</li><li>deceased, departed, one whose soul is in heaven or hell</li><li>destitute of life, without life, inanimate</li></ol><li>metaphorically<ol type='a'><li>spiritually dead<ol><li>destitute of a life that recognises and is devoted to God, because given up to trespasses and sins</li><li>inactive as respects doing right</li></ol><li>destitute of force or power, inactive, inoperative</li></ol></li></ol>","xlit":"nekrós"},"G2224":{"lemma":"ζώννυμι","translit":"zṓnnymi","kjv_def":"gird","strongs_def":" to bind about (especially with a belt)","derivation":"from G2223 (ζώνη);","pron":"dzone'-noo-mi","pos":"Verb","thayer":"<ol><li>to gird</li><li>to gird one's self</li></ol>","xlit":"zṓnnymi"},"G5040":{"kjv_def":"little children","translit":"tekníon","lemma":"τεκνίον","derivation":"diminutive of G5043 (τέκνον);","strongs_def":" an infant, i.e. (plural figuratively) darlings (Christian converts)","pron":"tek-nee'-on","pos":"Noun Neuter","thayer":"<ol><li>a little child</li><li>in the NT used as a term of kindly address by teachers to their disciples</li></ol>","xlit":"tekníon"},"G293":{"lemma":"ἀμφίβληστρον","translit":"amphíblēstron","kjv_def":"net","strongs_def":" a (fishing) net (as thrown about the fish)","derivation":"from a compound of the base of G297 (ἀμφότερος) and G906 (βάλλω);","pron":"am-fib'-lace-tron","pos":"Noun Neuter","thayer":"<ol><li>anything thrown around one to impede his motions, as chains, a garment, a net for fishing</li></ol>","xlit":"amphíblēstron"},"G3655":{"translit":"ómbros","lemma":"ὄμβρος","kjv_def":"shower","strongs_def":" a thunder storm","derivation":"of uncertain affinity;","pron":"om'-bros","pos":"Noun Masculine","thayer":"<ol><li>a shower<ol type='a'><li>a violent storm, accompanied by high wind with thunder and lightning</li></ol></li></ol>","xlit":"ómbros"},"G499":{"derivation":"neuter of a compound of G473 (ἀντί) and G5179 (τύπος);","strongs_def":" corresponding (\"antitype\"), i.e. a representative, counterpart","kjv_def":"(like) figure (whereunto)","lemma":"ἀντίτυπον","translit":"antítypon","pron":"an-teet'-oo-pon","pos":"Adjective","thayer":"<ol><li>a thing formed after some pattern</li><li>a thing resembling another, its counterpart<ol type='a'><li>something in the Messianic times which answers to the type, as baptism corresponds to the deluge (<a class='bible' href='#b60.3.21'>1Pe 3:21</a>)</li></ol></li></ol>","xlit":"antítypon"},"G599":{"strongs_def":" to die off (literally or figuratively)","derivation":"from G575 (ἀπό) and G2348 (θνήσκω);","lemma":"ἀποθνήσκω","translit":"apothnḗskō","kjv_def":"be dead, death, die, lie a-dying, be slain (X with)","pron":"ap-oth-nace'-ko","pos":"Verb","thayer":"<ol><li>to die<ol type='a'><li>of the natural death of man</li><li>of the violent death of man or animals</li><li>to perish by means of something</li><li>of trees which dry up, of seeds which rot when planted</li><li>of eternal death, to be subject to eternal misery in hell</li></ol></li></ol>","xlit":"apothnḗskō"},"G4205":{"derivation":"from (to sell;","strongs_def":" akin to the base of G4097 (πιπράσκω)); a (male) prostitute (as venal), i.e. (by analogy) a debauchee (libertine)","kjv_def":"fornicator, whoremonger","translit":"pórnos","lemma":"πόρνος","pron":"por'-nos","pos":"Noun Masculine","thayer":"<ol><li>a man who prostitutes his body to another's lust for hire</li><li>a male prostitute</li><li>a man who indulges in unlawful sexual intercourse, a fornicator</li></ol>","xlit":"pórnos"},"G1274":{"derivation":"from G1223 (διά) and (to effect);","strongs_def":" to accomplish thoroughly","kjv_def":"finish","translit":"dianýō","lemma":"διανύω","pron":"dee-an-oo'-o","pos":"Verb","thayer":"<ol><li>to accomplish fully, bring quite to an end, finish</li></ol>","xlit":"dianýō"},"G219":{"derivation":"from G220 (ἀλέκτωρ) and G5456 (φωνή);","strongs_def":" cock-crow, i.e. the third night-watch","kjv_def":"cockcrowing","translit":"alektorophōnía","lemma":"ἀλεκτοροφωνία","pron":"al-ek-tor-of-o-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the crowing of a cock or rooster, cock-crowing<ol type='a'><li>used of the third watch of the night</li></ol></li></ol>","xlit":"alektorophōnía"},"G3455":{"kjv_def":"roar","translit":"mykáomai","lemma":"μυκάομαι","derivation":"from a presumed derivative of ( to \"moo\");","strongs_def":" to bellow (roar)","pron":"moo-kah'-om-ahee","pos":"Verb","thayer":"<ol><li>to low, bellow, properly of horned cattle</li><li>to roar, of a lion</li></ol>","xlit":"mykáomai"},"G687":{"derivation":"a form of G686 (ἄρα), denoting an interrogation to which a negative answer is presumed","kjv_def":"therefore","lemma":"ἆρα","translit":"âra","pron":"ar'-ah","thayer":"<ol><li>a Greek interrogative particle that implies anxiety or impatience on the part of the questioner</li></ol>","xlit":"âra"},"G811":{"kjv_def":"riotous","translit":"asṓtōs","lemma":"ἀσώτως","derivation":"adverb from the same as G810 (ἀσωτία);","strongs_def":" dissolutely","pron":"as-o'-toce","pos":"Adverb","thayer":"<ol><li>dissolutely, profligately</li></ol>","xlit":"asṓtōs"},"G444":{"translit":"ánthrōpos","lemma":"ἄνθρωπος","kjv_def":"certain, man","strongs_def":" from G3700 (ὀπτάνομαι)); man-faced, i.e. a human being","derivation":"from G435 (ἀνήρ) and (the countenance;","pron":"anth'-ro-pos","pos":"Noun Masculine","thayer":"<ol><li>a human being, whether male or female<ol type='a'><li>generically, to include all human individuals</li><li>to distinguish man from beings of a different order<ol><li>of animals and plants</li><li>of from God and Christ</li><li>of the angels</li></ol><li>with the added notion of weakness, by which man is led into a mistake or prompted to sin</li><li>with the adjunct notion of contempt or disdainful pity</li><li>with reference to two fold nature of man, body and soul</li><li>with reference to the two fold nature of man, the corrupt and the truly Christian man, conformed to the nature of God</li><li>with reference to sex, a male</li></ol><li>indefinitely, someone, a man, one</li><li>in the plural, people</li><li>joined with other words, merchantman</li></ol>","xlit":"ánthrōpos"},"G2947":{"strongs_def":" compare G2945 (κύκλῳ), G1507 (εἱλίσσω)); to roll about","derivation":"from the base of G2949 (κῦμα) (through the idea of circularity;","lemma":"κυλιόω","translit":"kylióō","kjv_def":"wallow","pron":"koo-lee-o'-o","pos":"Verb","thayer":"<ol><li>a rolling, wallowing</li><li>to roll itself in mud</li><li>to wallowing in the mire</li></ol>","xlit":"kylióō"},"G2316":{"lemma":"θεός","translit":"theós","kjv_def":"X exceeding, God, god(-ly, -ward)","strongs_def":" figuratively, a magistrate; by Hebraism, very","derivation":"of uncertain affinity; a deity, especially (with G3588 (ὁ)) the supreme Divinity;","pron":"theh'-os","pos":"Noun Masculine","thayer":"<ol><li>a god or goddess, a general name of deities or divinities</li><li>the Godhead, trinity<ol type='a'><li>God the Father, the first person in the trinity</li><li>Christ, the second person of the trinity</li><li>Holy Spirit, the third person in the trinity</li></ol><li>spoken of the only and true God<ol type='a'><li>refers to the things of God</li><li>his counsels, interests, things due to him</li></ol><li>whatever can in any respect be likened unto God, or resemble him in any way<ol type='a'><li>God's representative or viceregent<ol><li>of magistrates and judges</li></ol></li></ol></li></ol>","xlit":"theós"},"G1339":{"kjv_def":"go further, be parted, after the space of","translit":"diḯstēmi","lemma":"διΐστημι","derivation":"from G1223 (διά) and G2476 (ἵστημι);","strongs_def":" to stand apart, i.e. (reflexively) to remove, intervene","pron":"dee-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place separately, put asunder, disjoin</li><li>to stand apart, to part, depart</li></ol>","xlit":"diḯstēmi"},"G5521":{"strongs_def":" \"gall\" or bile, i.e. (by analogy) poison or an anodyne (wormwood, poppy, etc.)","derivation":"feminine of an equivalent perhaps akin to the same as 5514 (from the greenish hue);","lemma":"χολή","translit":"cholḗ","kjv_def":"gall","pron":"khol-ay'","pos":"Noun Feminine","thayer":"<ol><li>bile, gall</li><li>in the OT used of other bitter things<ol type='a'><li>wormwood</li><li>possibly myrrh</li></ol></li></ol>","xlit":"cholḗ"},"G2154":{"strongs_def":" well indicated, i.e. (figuratively) significant","derivation":"from G2095 (εὖ) and the base of G4591 (σημαίνω);","lemma":"εὔσημος","translit":"eúsēmos","kjv_def":"easy to be understood","pron":"yoo'-say-mos","pos":"Adjective","thayer":"<ol><li>well marked, clear and definite, distinct</li></ol>","xlit":"eúsēmos"},"G4238":{"strongs_def":" to \"practise\", i.e. perform repeatedly or habitually (thus differing from G4160 (ποιέω), which properly refers to a single act); by implication, to execute, accomplish, etc.; specially, to collect (dues), fare (personally)","derivation":"a primary verb;","translit":"prássō","lemma":"πράσσω","kjv_def":"commit, deeds, do, exact, keep, require, use arts","pron":"pras'-so","pos":"Verb","thayer":"<ol><li>to exercise, practise, to be busy with, carry on<ol type='a'><li>to undertake, to do</li></ol><li>to accomplish, perform<ol type='a'><li>to commit, perpetrate</li></ol><li>to manage public affairs, transact public business<ol type='a'><li>to exact tribute, revenue, debts</li></ol><li>to act</li></ol>","xlit":"prássō"},"G4592":{"kjv_def":"miracle, sign, token, wonder","translit":"sēmeîon","lemma":"σημεῖον","derivation":"neuter of a presumed derivative of the base of G4591 (σημαίνω);","strongs_def":" an indication, especially ceremonially or supernaturally","pron":"say-mi'-on","pos":"Noun Neuter","thayer":"<ol><li>a sign, mark, token<ol type='a'><li>that by which a person or a thing is distinguished from others and is known</li><li>a sign, prodigy, portent, i.e. an unusual occurrence, transcending the common course of nature<ol><li>of signs portending remarkable events soon to happen</li><li>of miracles and wonders by which God authenticates the men sent by him, or by which men prove that the cause they are pleading is God's</li></ol></li></ol></li></ol>","xlit":"sēmeîon"},"G4756":{"kjv_def":"host","lemma":"στρατιά","translit":"stratiá","derivation":"feminine of a derivative of (an army;","strongs_def":" from the base of G4766 (στρώννυμι), as encamped); camp-likeness, i.e. an army, i.e. (figuratively) the angels, the celestial luminaries","pron":"strat-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>an army, band of soldiers</li><li>in the NT, the hosts of heaven<ol type='a'><li>troops of angels</li><li>the heavenly bodies, stars of heaven (so called on account of their number and their order)</li></ol></li></ol>","xlit":"stratiá"},"G4579":{"strongs_def":" to rock (vibrate, properly, sideways or to and fro), i.e. (generally) to agitate (in any direction; cause to tremble); figuratively, to throw into a tremor (of fear or concern)","derivation":"apparently a primary verb;","lemma":"σείω","translit":"seíō","kjv_def":"move, quake, shake","pron":"si'-o","pos":"Verb","thayer":"<ol><li>to shake, agitate, cause to tremble<ol type='a'><li>of men, to be thrown into a tremor, to quake for fear</li><li>metaphorically to agitate the mind</li></ol></li></ol>","xlit":"seíō"},"G73":{"derivation":"from G71 (ἄγω);","strongs_def":" properly, a place of assembly (as if led), i.e. (by implication) a contest (held there); figuratively, an effort or anxiety","kjv_def":"conflict, contention, fight, race","lemma":"ἀγών","translit":"agṓn","pron":"ag-one'","pos":"Noun Masculine","thayer":"<ol><li>an assembly<ol type='a'><li>a place of assembly: especially an assembly met to see games</li><li>the place of contest, the arena or stadium</li></ol><li>the assembly of the Greeks at their national games<ol type='a'><li>hence the contest for a prize at their games</li><li>generally, any struggle or contest</li><li>a battle</li><li>an action at law, trial</li></ol></li></ol>","xlit":"agṓn"},"G2390":{"kjv_def":"heal, make whole","lemma":"ἰάομαι","translit":"iáomai","derivation":"middle voice of apparently a primary verb;","strongs_def":" to cure (literally or figuratively)","pron":"ee-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to cure, heal</li><li>to make whole<ol type='a'><li>to free from errors and sins, to bring about (one's) salvation</li></ol></li></ol>","xlit":"iáomai"},"G5601":{"strongs_def":" Obed, an Israelite","derivation":"of Hebrew origin (H05744);","translit":"Ōbḗd","lemma":"Ὠβήδ","kjv_def":"Obed","pron":"o-bade'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Obed = \"serving\"</p><ol><li>the grandfather of king David</li></ol>","xlit":"Ōbḗd"},"G555":{"strongs_def":" divestment","derivation":"from G554 (ἀπεκδύομαι);","translit":"apékdysis","lemma":"ἀπέκδυσις","kjv_def":"putting off","pron":"ap-ek'-doo-sis","pos":"Noun Feminine","thayer":"<ol><li>a putting off, laying aside</li></ol>","xlit":"apékdysis"},"G5405":{"kjv_def":"Phenice","translit":"Phoînix","lemma":"Φοῖνιξ","derivation":"probably the same as G5404 (φοῖνιξ);","strongs_def":" Phœnix, a place in Crete","pron":"foy'-nix","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Phenice = \"palm tree\"</p><ol><li>the name of a haven in Crete on the south coast</li></ol>","xlit":"Phoînix"},"G4575":{"derivation":"from G4573 (σεβάζομαι);","strongs_def":" venerable (august), i.e. (as noun) a title of the Roman Emperor, or (as adjective) imperial","kjv_def":"Augustus(-')","translit":"sebastós","lemma":"σεβαστός","pron":"seb-as-tos'","pos":"Adjective","thayer":"<ol><li>reverend, venerable</li><li>the title of the Roman emperors<ol type='a'><li>Augustan, i,e, taking its name from the emperor</li><li>a title of honour which used to be given certain legions, or cohorts, or battalions, \"for valour\"</li></ol></li></ol>","xlit":"sebastós"},"G2311":{"lemma":"θεμελιόω","translit":"themelióō","kjv_def":"(lay the) found(- ation), ground, settle","strongs_def":" to lay a basis for, i.e. (literally) erect, or (figuratively) consolidate","derivation":"from G2310 (θεμέλιος);","pron":"them-el-ee-o'-o","pos":"Verb","thayer":"<ol><li>to lay the foundation, to found</li><li>to make stable, establish</li></ol>","xlit":"themelióō"},"G740":{"strongs_def":" bread (as raised) or a loaf","derivation":"from G142 (αἴρω);","lemma":"ἄρτος","translit":"ártos","kjv_def":"(shew-)bread, loaf","pron":"ar'-tos","pos":"Noun Masculine","thayer":"<ol><li>food composed of flour mixed with water and baked<ol type='a'><li>the Israelites made it in the form of an oblong or round cake, as thick as one's thumb, and as large as a plate or platter hence it was not to be cut but broken</li><li>loaves were consecrated to the Lord</li><li>of the bread used at the love-feasts and at the Lord's Table</li></ol><li>food of any kind</li></ol>","xlit":"ártos"},"G5202":{"kjv_def":"drink water","lemma":"ὑδροποτέω","translit":"hydropotéō","derivation":"from a compound of G5204 (ὕδωρ) and a derivative of G4095 (πίνω);","strongs_def":" to be a water-drinker, i.e. to abstain from vinous beverages","pron":"hoo-drop-ot-eh'-o","pos":"Verb","thayer":"<ol><li>to drink water, be a drinker of water</li></ol>","xlit":"hydropotéō"},"G1477":{"strongs_def":" a support, i.e. (figuratively) basis","derivation":"from a derivative of G1476 (ἑδραῖος);","translit":"hedraíōma","lemma":"ἑδραίωμα","kjv_def":"ground","pron":"hed-rah'-yo-mah","pos":"Noun Neuter","thayer":"<ol><li>a stay, prop, support</li></ol>","xlit":"hedraíōma"},"G5533":{"strongs_def":" a loan-ower, i.e. indebted person","derivation":"from a derivative of G5531 (χράω) and G3781 (ὀφειλέτης);","translit":"chreōpheilétēs","lemma":"χρεωφειλέτης","kjv_def":"debtor","pron":"khreh-o-fi-let'-ace","pos":"Noun Masculine","thayer":"<ol><li>a debtor</li></ol>","xlit":"chreōpheilétēs"},"G487":{"kjv_def":"ransom","translit":"antílytron","lemma":"ἀντίλυτρον","derivation":"from G473 (ἀντί) and G3083 (λύτρον);","strongs_def":" a redemption-price","pron":"an-til'-oo-tron","pos":"Noun Neuter","thayer":"<ol><li>what is given in exchange for another as the price of his redemption, ransom</li></ol>","xlit":"antílytron"},"G3116":{"strongs_def":" with long (enduring) temper, i.e. leniently","derivation":"adverb of a compound of G3117 (μακρός) and G2372 (θυμός);","translit":"makrothymṓs","lemma":"μακροθυμώς","kjv_def":"patiently","pron":"mak-roth-oo-moce'","pos":"Adverb","thayer":"<ol><li>with longanimity, i.e. patiently</li></ol>","xlit":"makrothymṓs"},"G3613":{"derivation":"neuter of a presumed derivative of G3611 (οἰκέω) (equivalent to G3612 (οἴκημα));","strongs_def":" a residence (literally or figuratively)","kjv_def":"habitation, house","translit":"oikētḗrion","lemma":"οἰκητήριον","pron":"oy-kay-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a dwelling place, habitation<ol type='a'><li>of the body as a dwelling place for the spirit</li></ol></li></ol>","xlit":"oikētḗrion"},"G220":{"kjv_def":"cock","translit":"aléktōr","lemma":"ἀλέκτωρ","derivation":"from (to ward off);","strongs_def":" a cock or male fowl","pron":"al-ek'-tore","pos":"Noun Masculine","thayer":"<ol><li>a cock, or male of any bird, a rooster</li></ol>","xlit":"aléktōr"},"G5615":{"translit":"hōsaútōs","lemma":"ὡσαύτως","kjv_def":"even so, likewise, after the same (in like) manner","strongs_def":" as thus, i.e. in the same way","derivation":"from G5613 (ὡς) and an adverb from G846 (αὐτός);","pron":"ho-sow'-toce","pos":"Adverb","thayer":"<ol><li>in like manner, likewise</li></ol>","xlit":"hōsaútōs"},"G597":{"strongs_def":" to treasure away","derivation":"from G575 (ἀπό) and G2343 (θησαυρίζω);","translit":"apothēsaurízō","lemma":"ἀποθησαυρίζω","kjv_def":"lay up in store","pron":"ap-oth-ay-sow-rid'-zo","pos":"Verb","thayer":"<ol><li>to put away, lay by in store, to treasure away</li><li>to store up abundance for future use</li></ol>","xlit":"apothēsaurízō"},"G5115":{"strongs_def":" a bow (apparently as the simplest fabric)","derivation":"from the base of G5088 (τίκτω);","lemma":"τόξον","translit":"tóxon","kjv_def":"bow","pron":"tox'-on","pos":"Noun Neuter","thayer":"<ol><li>a bow</li></ol>","xlit":"tóxon"},"G631":{"derivation":"middle voice from G575 (ἀπό) and (to squeeze, knead, smear);","strongs_def":" to scrape away","kjv_def":"wipe off","translit":"apomássomai","lemma":"ἀπομάσσομαι","pron":"ap-om-as'-som-ahee","pos":"Verb","thayer":"<ol><li>to wipe off</li><li>to wipe off one's self, to wipe of for one's self</li></ol>","xlit":"apomássomai"},"G4740":{"kjv_def":"stedfastness","translit":"stērigmós","lemma":"στηριγμός","derivation":"from G4741 (στηρίζω);","strongs_def":" stability (figuratively)","pron":"stay-rig-mos'","pos":"Noun Masculine","thayer":"<ol><li>firm condition, steadfastness: of mind</li></ol>","xlit":"stērigmós"},"G5582":{"translit":"pseûsma","lemma":"ψεῦσμα","kjv_def":"lie","strongs_def":" a fabrication, i.e. falsehood","derivation":"from G5574 (ψεύδομαι);","pron":"psyoos'-mah","pos":"Noun Neuter","thayer":"<ol><li>a falsehood, a lie</li><li>the perfidy by which a man by sinning breaks faith with God</li></ol>","xlit":"pseûsma"},"G3993":{"translit":"pénēs","lemma":"πένης","kjv_def":"poor","strongs_def":" starving, i.e. indigent","derivation":"from a primary (to toil for daily subsistence);","pron":"pen'-ace","pos":"Adjective","thayer":"<ol><li>poor</li></ol>","xlit":"pénēs"},"G2887":{"strongs_def":" orderly, i.e. decorous","derivation":"from G2889 (κόσμος) (in its primary sense);","translit":"kósmios","lemma":"κόσμιος","kjv_def":"of good behaviour, modest","pron":"kos'-mee-os","pos":"Adjective","thayer":"<ol><li>well arranged, seemly, modest</li></ol>","xlit":"kósmios"},"G2170":{"strongs_def":" well favored, i.e. (by implication) grateful","derivation":"from G2095 (εὖ) and a derivative of G5483 (χαρίζομαι);","translit":"eucháristos","lemma":"εὐχάριστος","kjv_def":"thankful","pron":"yoo-khar'-is-tos","pos":"Adjective","thayer":"<ol><li>mindful of favours, grateful, thankful</li><li>pleasing, agreeable</li><li>acceptable to others, winning, liberal, beneficent</li></ol>","xlit":"eucháristos"},"G4115":{"kjv_def":"make broad, enlarge","translit":"platýnō","lemma":"πλατύνω","derivation":"from G4116 (πλατύς);","strongs_def":" to widen (literally or figuratively)","pron":"plat-oo'-no","pos":"Verb","thayer":"<ol><li>to make broad, enlarge</li><li>be enlarged in heart, i.e. to welcome and embrace you in love</li></ol>","xlit":"platýnō"},"G4850":{"lemma":"συμπρεσβύτερος","translit":"sympresbýteros","kjv_def":"presbyter, also an elder","strongs_def":" a co-presbyter","derivation":"from G4862 (σύν) and G4245 (πρεσβύτερος);","pron":"soom-pres-boo'-ter-os","pos":"Noun Masculine","thayer":"<ol><li>a fellow elder</li></ol>","xlit":"sympresbýteros"},"G2848":{"strongs_def":" a kernel of seed","derivation":"apparently a primary word;","translit":"kókkos","lemma":"κόκκος","kjv_def":"corn, grain","pron":"kok'-kos","pos":"Noun Masculine","thayer":"<ol><li>a grain</li></ol>","xlit":"kókkos"},"G3807":{"strongs_def":" a boy-leader, i.e. a servant whose office it was to take the children to school; (by implication, (figuratively) a tutor (\"pædagogue\"))","derivation":"from G3816 (παῖς) and a reduplicated form of G71 (ἄγω);","translit":"paidagōgós","lemma":"παιδαγωγός","kjv_def":" instructor, schoolmaster","pron":"pahee-dag-o-gos'","pos":"Noun Masculine","thayer":"<ol><li>a tutor, i.e. a guardian and guide of boys. Among the Greeks and the Romans the name was applied to trustworthy slaves who were charged with the duty of supervising the life and morals of boys belonging to the better class. The boys were not allowed so much as to step out of the house without them before arriving at the age of manhood.</li></ol>","xlit":"paidagōgós"},"G3944":{"lemma":"παροίχομαι","translit":"paroíchomai","kjv_def":"past","strongs_def":" to escape along, i.e. be gone","derivation":"from G3844 (παρά) and (to depart);","pron":"par-oy'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go by, pass by</li></ol>","xlit":"paroíchomai"},"G936":{"strongs_def":" to rule (literally or figuratively)","derivation":"from G935 (βασιλεύς);","lemma":"βασιλεύω","translit":"basileúō","kjv_def":"king, reign","pron":"bas-il-yoo'-o","pos":"Verb","thayer":"<ol><li>to be king, to exercise kingly power, to reign<ol type='a'><li>of the governor of a province</li><li>of the rule of the Messiah</li><li>of the reign of Christians in the millennium</li></ol><li>metaphorically to exercise the highest influence, to control</li></ol>","xlit":"basileúō"},"G165":{"strongs_def":" properly, an age; by extension, perpetuity (also past); by implication, the world; specially (Jewish) a Messianic period (present or future)","derivation":"from the same as G104 (ἀεί);","lemma":"αἰών","translit":"aiṓn","kjv_def":"age, course, eternal, (for) ever(-more), (n-)ever, (beginning of the , while the) world (began, without end)","pron":"ahee-ohn'","pos":"Noun Masculine","thayer":"<ol><li>for ever, an unbroken age, perpetuity of time, eternity</li><li>the worlds, universe</li><li>period of time, age</li></ol>","xlit":"aiṓn"},"G4600":{"lemma":"σιαγών","translit":"siagṓn","kjv_def":"cheek","strongs_def":" the jaw-bone, i.e. (by implication) the cheek or side of the face","derivation":"of uncertain derivation;","pron":"see-ag-one'","pos":"Noun Feminine","thayer":"<ol><li>the jaw, the jaw bone</li></ol>","xlit":"siagṓn"},"G1323":{"strongs_def":" a double drachma (didrachm)","derivation":"from G1364 (δίς) and G1406 (δραχμή);","translit":"dídrachmon","lemma":"δίδραχμον","kjv_def":"tribute","pron":"did'-rakh-mon","pos":"Noun Neuter","thayer":"<ol><li>a didrachmon or double drachma, a silver coin equal to two Attic drachmas or one Alexandrian, or one half a shekel</li></ol>","xlit":"dídrachmon"},"G4109":{"lemma":"πλάξ","translit":"pláx","kjv_def":"table","strongs_def":" a moulding-board, i.e. flat surface (\"plate\", or tablet, literally or figuratively)","derivation":"from G4111 (πλάσσω);","pron":"plax","pos":"Noun Feminine","thayer":"<ol><li>a flat thing, broad tablet, plane, level surface (as of the sea)</li></ol>","xlit":"pláx"},"G2287":{"strongs_def":" death-bearing, i.e. fatal","derivation":"from (the feminine form of) G2288 (θάνατος) and G5342 (φέρω);","lemma":"θανατήφορος","translit":"thanatḗphoros","kjv_def":"deadly","pron":"than-at-ay'-for-os","pos":"Adjective","thayer":"<ol><li>death bringing, deadly</li></ol>","xlit":"thanatḗphoros"},"G1360":{"translit":"dióti","lemma":"διότι","kjv_def":"because (that), for, therefore","strongs_def":" on the very account that, or inasmuch as","derivation":"from G1223 (διά) and G3754 (ὅτι);","pron":"dee-ot'-ee","pos":"Conjunction","thayer":"<ol><li>on this account that, because</li><li>for</li></ol>","xlit":"dióti"},"G1259":{"kjv_def":"reconcile","translit":"diallássō","lemma":"διαλλάσσω","derivation":"from G1223 (διά) and G236 (ἀλλάσσω);","strongs_def":" to change thoroughly, i.e. (mentally) to conciliate","pron":"dee-al-las'-so","pos":"Verb","thayer":"<ol><li>to change</li><li>to change the mind of anyone, to reconcile</li><li>to be reconciled, to renew friendship with one</li></ol>","xlit":"diallássō"},"G2933":{"strongs_def":" an acquirement, i.e. estate","derivation":"from G2932 (κτάομαι);","translit":"ktēma","lemma":"κτῆμα","kjv_def":"possession","pron":"ktay'-mah","pos":"Noun Neuter","thayer":"<ol><li>a possession<ol type='a'><li>of property, lands, estates</li></ol></li></ol>","xlit":"ktēma"},"G469":{"kjv_def":"reward","translit":"antapódosis","lemma":"ἀνταπόδοσις","derivation":"from G467 (ἀνταποδίδωμι);","strongs_def":" requital (properly, the act)","pron":"an-tap-od'-os-is","pos":"Noun Feminine","thayer":"<ol><li>recompence, to reward or repay someone</li></ol>","xlit":"antapódosis"},"G3834":{"kjv_def":"(cunning) craftiness, subtilty","translit":"panourgía","lemma":"πανουργία","derivation":"from G3835 (πανοῦργος);","strongs_def":" adroitness, i.e. (in a bad sense) trickery or sophistry","pron":"pan-oorg-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>craftiness, cunning</li><li>a specious or false wisdom</li><li>in a good sense, prudence, skill, in undertaking and carrying on affairs</li></ol>","xlit":"panourgía"},"G5078":{"strongs_def":" art (as productive), i.e. (specially), a trade, or (generally) skill","derivation":"from the base of G5088 (τίκτω);","translit":"téchnē","lemma":"τέχνη","kjv_def":"art, craft, occupation","pron":"tekh'-nay","pos":"Noun Feminine","thayer":"<ol><li>of the plastic art</li><li>of a trade</li></ol>","xlit":"téchnē"},"G4212":{"derivation":"multiplicative from G4214 (πόσος);","strongs_def":" how many times","kjv_def":"how oft(-en)","translit":"posákis","lemma":"ποσάκις","pron":"pos-ak'-is","pos":"Adverb","thayer":"<ol><li>how often</li></ol>","xlit":"posákis"},"G3951":{"kjv_def":"stir up","translit":"parotrýnō","lemma":"παροτρύνω","derivation":"from G3844 (παρά) and (to spur);","strongs_def":" to urge along, i.e. stimulate (to hostility)","pron":"par-ot-roo'-no","pos":"Verb","thayer":"<ol><li>to incite, stir up</li></ol>","xlit":"parotrýnō"},"G1099":{"strongs_def":" sweet (i.e. not bitter nor salt)","derivation":"of uncertain affinity;","translit":"glykýs","lemma":"γλυκύς","kjv_def":"sweet, fresh","pron":"gloo-koos'","pos":"Adjective","thayer":"<ol><li>sweet</li></ol>","xlit":"glykýs"},"G866":{"strongs_def":" unavaricious","derivation":"from G1 (Α) (as a negative particle) and G5366 (φιλάργυρος);","translit":"aphilárgyros","lemma":"ἀφιλάργυρος","kjv_def":"without covetousness, not greedy of filthy lucre","pron":"af-il-ar'-goo-ros","pos":"Adjective","thayer":"<ol><li>not loving money, not avaricious</li></ol>","xlit":"aphilárgyros"},"G4612":{"strongs_def":" a semicinctium or half-girding, i.e. narrow covering (apron)","derivation":"of Latin origin;","translit":"simikínthion","lemma":"σιμικίνθιον","kjv_def":"apron","pron":"sim-ee-kin'-thee-on","pos":"Noun Neuter","thayer":"<ol><li>a narrow apron, or linen covering, which workmen and servants were accustomed to wear</li></ol>","xlit":"simikínthion"},"G308":{"translit":"anablépō","lemma":"ἀναβλέπω","kjv_def":"look (up), see, receive sight","strongs_def":" to look up; by implication, to recover sight","derivation":"from G303 (ἀνά) and G991 (βλέπω);","pron":"an-ab-lep'-o","pos":"Verb","thayer":"<ol><li>to look up</li><li>to recover (lost) sight</li></ol>","xlit":"anablépō"},"G4289":{"translit":"próthymos","lemma":"πρόθυμος","kjv_def":"ready, willing","strongs_def":" forward in spirit, i.e. predisposed; neuter (as noun) alacrity","derivation":"from G4253 (πρό) and G2372 (θυμός);","pron":"proth'-oo-mos","pos":"Adjective","thayer":"<ol><li>ready, willing</li></ol>","xlit":"próthymos"},"G1957":{"lemma":"ἐπιμαρτυρέω","translit":"epimartyréō","kjv_def":"testify","strongs_def":" to attest further, i.e. corroborate","derivation":"from G1909 (ἐπί) and G3140 (μαρτυρέω);","pron":"ep-ee-mar-too-reh'-o","pos":"Verb","thayer":"<ol><li>to bear witness to, establish by testimony</li></ol>","xlit":"epimartyréō"},"G4611":{"derivation":"of Hebrew origin (H07975);","strongs_def":" Siloam (i.e. Shiloach), a pool of Jerusalem","kjv_def":"Siloam","lemma":"Σιλωάμ","translit":"Silōám","pron":"sil-o-am'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Siloam = \"sent\"</p><ol><li>the Pool of Siloam, a fountain of water in Jerusalem, also called Shiloah in <a class='bible' href='#b23.8.6'>Isa 8:6</a></li><li>the Tower of Siloam, may have been a tower near or over the Pool of Siloam, which fell down killing 18 men; very likely they were purifying themselves. (Gill)</li></ol>","xlit":"Silōám"},"G5212":{"translit":"hyméteros","lemma":"ὑμέτερος","kjv_def":"your (own)","strongs_def":" yours, i.e. pertaining to you","derivation":"from G5210 (ὑμεῖς);","pron":"hoo-met'-er-os","thayer":"<ol><li>you, yours<ol type='a'><li>to be possessed by you</li><li>to be allocated by you</li><li>proceeding from you</li></ol></li></ol>","xlit":"hyméteros"},"G4565":{"lemma":"Σάρων","translit":"Sárōn","kjv_def":"Saron","strongs_def":" Saron (i.e. Sharon), a district of Palestine","derivation":"of Hebrew origin (H08289);","pron":"sar'-one","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sharon = \"plain or level\"</p><ol><li>a level region extending from Caesarea of Palestine as far as Joppa, abounding in good pasture and famous for its fertility</li></ol>","xlit":"Sárōn"},"G1649":{"translit":"élenxis","lemma":"ἔλεγξις","kjv_def":"rebuke","strongs_def":" refutation, i.e. reproof","derivation":"from G1651 (ἐλέγχω);","pron":"el'-eng-xis","pos":"Noun Feminine","thayer":"<ol><li>refutation, rebuke</li></ol>","xlit":"élenxis"},"G4011":{"kjv_def":"Perga","translit":"Pérgē","lemma":"Πέργη","derivation":"probably from the same as G4010 (Πέργαμος);","strongs_def":" a tower; Perga, a place in Asia Minor","pron":"perg'-ay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Perga = \"earthy\"</p><ol><li>a town in Pamphylia, on the river Cestius, at a distance of 7 miles</li></ol>","xlit":"Pérgē"},"G2706":{"lemma":"καταφρονέω","translit":"kataphronéō","kjv_def":"despise","strongs_def":" to think against, i.e. disesteem","derivation":"from G2596 (κατά) and G5426 (φρονέω);","pron":"kat-af-ron-eh'-o","pos":"Verb","thayer":"<ol><li>to contemn, despise, disdain, think little or nothing of</li></ol>","xlit":"kataphronéō"},"G4297":{"lemma":"προκοπή","translit":"prokopḗ","kjv_def":"furtherance, profit","strongs_def":" progress, i.e. advancement (subjectively or objectively)","derivation":"from G4298 (προκόπτω);","pron":"prok-op-ay'","xlit":"prokopḗ"},"G5243":{"derivation":"from G5244 (ὑπερήφανος);","strongs_def":" haughtiness","kjv_def":"pride","lemma":"ὑπερηφανία","translit":"hyperēphanía","pron":"hoop-er-ay-fan-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>pride, haughtiness, arrogance</li><li>the character of one who, with a swollen estimate of his own powers or merits, looks down on others and even treats them with insolence and contempt</li></ol>","xlit":"hyperēphanía"},"G4459":{"translit":"pōs","lemma":"πῶς","kjv_def":"how, after (by) what manner (means), that","strongs_def":" an interrogative particle of manner; in what way? (sometimes the question is indirect, how?); also as exclamation, how much!","derivation":"adverb from the base of G4226 (ποῦ);","pron":"poce","thayer":"<ol><li>how, in what way</li></ol>","xlit":"pōs"},"G5455":{"kjv_def":"call (for), crow, cry","lemma":"φωνέω","translit":"phōnéō","derivation":"from G5456 (φωνή);","strongs_def":" to emit a sound (animal, human or instrumental); by implication, to address in words or by name, also in imitation","pron":"fo-neh'-o","pos":"Verb","thayer":"<ol><li>to sound, emit a sound, to speak<ol type='a'><li>of a cock: to crow</li><li>of men: to cry, cry out, cry aloud, speak with a loud voice</li></ol><li>to call, to call one's self, either by one's own voice or though another</li><li>to send for, summon<ol type='a'><li>to call out of (i.e. bid one to quit a place and come to one</li><li>to invite</li><li>to address, accost, call by a name</li></ol></li></ol>","xlit":"phōnéō"},"G1499":{"strongs_def":" if also (or even)","derivation":"from G1487 (εἰ) and G2532 (καί);","translit":"ei kaí","lemma":"εἰ καί","kjv_def":"if (that), though","pron":"i kahee","pos":"Conjunction","thayer":"<ol><li>even, if, although</li></ol>","xlit":"ei kaí"},"G4262":{"derivation":"from G4263 (πρόβατον);","strongs_def":" relating to sheep, i.e. (a gate) through which they were led into Jerusalem","kjv_def":"sheep (market)","translit":"probatikós","lemma":"προβατικός","pron":"prob-at-ik-os'","pos":"Adjective","thayer":"<ol><li>pertaining to sheep</li><li>the sheep gate</li></ol>","xlit":"probatikós"},"G3007":{"lemma":"λείπω","translit":"leípō","kjv_def":"be destitute (wanting), lack","strongs_def":" to leave, i.e. (intransitively or passively) to fail or be absent","derivation":"a primary verb;","pron":"li'-po","pos":"Verb","thayer":"<ol><li>to leave, leave behind, forsake, to be left behind<ol type='a'><li>to lag, be inferior</li><li>to be destitute of, to lack</li></ol><li>to be wanting, to fail</li></ol>","xlit":"leípō"},"G3891":{"strongs_def":" to be opposed to law, i.e. to transgress","derivation":"from a compound of G3844 (παρά) and G3551 (νόμος);","lemma":"παρανομέω","translit":"paranoméō","kjv_def":"contrary to law","pron":"par-an-om-eh'-o","pos":"Verb","thayer":"<ol><li>to act contrary to the law, to break the law</li></ol>","xlit":"paranoméō"},"G3756":{"derivation":"a primary word;","strongs_def":" the absolute negative (compare G3361 (μή)) adverb; no or not","kjv_def":"+ long, nay, neither, never, no (X man), none, (can-)not, + nothing, + special, un(-worthy), when, + without, + yet but","lemma":"οὐ","translit":"ou","pron":"oo","thayer":"<ol><li>no, not; in direct questions expecting an affirmative answer</li></ol>","xlit":"ou"},"G861":{"strongs_def":" incorruptibility; genitive, unending existence; (figuratively) genuineness","derivation":"from G862 (ἄφθαρτος);","lemma":"ἀφθαρσία","translit":"aphtharsía","kjv_def":"immortality, incorruption, sincerity","pron":"af-thar-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>incorruption, perpetuity</li><li>purity, sincerity, incorrupt</li></ol>","xlit":"aphtharsía"},"G1326":{"kjv_def":"arise, awake, raise, stir up","translit":"diegeírō","lemma":"διεγείρω","derivation":"from G1223 (διά) and G1453 (ἐγείρω);","strongs_def":" to wake fully; i.e. arouse (literally or figuratively)","pron":"dee-eg-i'-ro","pos":"Verb","thayer":"<ol><li>to wake up, awaken, arouse (from sleep)<ol type='a'><li>of the sea, which begins to be agitated, to rise</li><li>metaphorically<ol><li>to arouse the mind</li><li>stir up, render active</li></ol></li></ol></li></ol>","xlit":"diegeírō"},"G2197":{"strongs_def":" Zacharias (i.e. Zechariah), the name of two Israelites","derivation":"of Hebrew origin (H02148);","translit":"Zacharías","lemma":"Ζαχαρίας","kjv_def":"Zacharias","pron":"dzakh-ar-ee'-as","pos":"Noun Masculine","thayer":"<ol><li>the father of John the Baptist</li><li>son of Barachias, who was slain by the Jews between the altar and the temple</li></ol>","xlit":"Zacharías"},"G2548":{"kjv_def":"and him (other, them), even he, him also, them (also), (and) they","translit":"kakeînos","lemma":"κἀκεῖνος","derivation":"from G2532 (καί) and G1565 (ἐκεῖνος);","strongs_def":" likewise that (or those)","pron":"kak-i'-nos","xlit":"kakeînos"},"G2989":{"strongs_def":" to beam, i.e. radiate brilliancy (literally or figuratively)","derivation":"a primary verb;","lemma":"λάμπω","translit":"lámpō","kjv_def":"give light, shine","pron":"lam'-po","pos":"Verb","thayer":"<ol><li>to shine</li></ol>","xlit":"lámpō"},"G2932":{"kjv_def":"obtain, possess, provide, purchase","lemma":"κτάομαι","translit":"ktáomai","derivation":"a primary verb;","strongs_def":" to get, i.e. acquire (by any means; own)","pron":"ktah'-om-ahee","pos":"Verb","thayer":"<ol><li>to acquire, get, or procure a thing for one's self, to possess<ol type='a'><li>to marry a wife</li></ol></li></ol>","xlit":"ktáomai"},"G471":{"derivation":"from G473 (ἀντί) and G2036 (ἔπω);","strongs_def":" to refute or deny","kjv_def":"gainsay, say against","lemma":"ἀντέπω","translit":"antépō","pron":"an-tep'-o","pos":"Verb","thayer":"<ol><li>to speak against, gainsay</li></ol>","xlit":"antépō"},"G5458":{"lemma":"φωστήρ","translit":"phōstḗr","kjv_def":"light","strongs_def":" an illuminator, i.e. (concretely) a luminary, or (abstractly) brilliancy","derivation":"from G5457 (φῶς);","pron":"foce-tare'","pos":"Noun Masculine","thayer":"<ol><li>that which gives light, an illuminator<ol type='a'><li>of the stars, sun and moon</li></ol><li>light, brightness</li></ol>","xlit":"phōstḗr"},"G1123":{"strongs_def":" inscribed (figuratively)","derivation":"from G1125 (γράφω);","lemma":"γραπτός","translit":"graptós","kjv_def":"written","pron":"grap-tos'","pos":"Adjective","thayer":"<ol><li>written</li></ol>","xlit":"graptós"},"G2680":{"translit":"kataskeuázō","lemma":"κατασκευάζω","kjv_def":"build, make, ordain, prepare","strongs_def":" to prepare thoroughly (properly, by external equipment; whereas G2090 (ἑτοιμάζω) refers rather to internal fitness); by implication, to construct, create","derivation":"from G2596 (κατά) and a derivative of G4632 (σκεῦος);","pron":"kat-ask-yoo-ad'-zo","pos":"Verb","thayer":"<ol><li>to furnish, equip, prepare, make ready<ol type='a'><li>of one who makes anything ready for a person or thing</li><li>of builders, to construct, erect, with the included idea of adorning and equipping with all things necessary</li></ol></li></ol>","xlit":"kataskeuázō"},"G5386":{"derivation":"from G5384 (φίλος) and G4680 (σοφός);","strongs_def":" fond of wise things, i.e. a \"philosopher\"","kjv_def":"philosopher","lemma":"φιλόσοφος","translit":"philósophos","pron":"fil-os'-of-os","pos":"Noun Masculine","thayer":"<ol><li>a philosopher, one given to the pursuit of wisdom or learning</li><li>in a narrower sense, one who investigates and discusses the cause of things and the highest good</li></ol>","xlit":"philósophos"},"G4432":{"derivation":"from G4433 (πτωχεύω);","strongs_def":" beggary, i.e. indigence (literally or figuratively)","kjv_def":"poverty","translit":"ptōcheía","lemma":"πτωχεία","pron":"pto-khi'-ah","pos":"Noun Feminine","thayer":"<ol><li>beggary</li><li>in the NT poverty<ol type='a'><li>the condition of one destitute of riches and abundance</li></ol></li></ol>","xlit":"ptōcheía"},"G5057":{"kjv_def":"publican","translit":"telṓnēs","lemma":"τελώνης","derivation":"from G5056 (τέλος) and G5608 (ὠνέομαι);","strongs_def":" a tax-farmer, i.e. collector of public revenue","pron":"tel-o'-nace","pos":"Noun Masculine","thayer":"<ol><li>a renter or farmer of taxes<ol type='a'><li>among the Romans, usually a man of equestrian rank</li></ol><li>a tax gatherer, collector of taxes or tolls, one employed by a publican or farmer general in the collection of taxes. The tax collectors were as a class, detested not only by the Jews, but by other nations also, both on account of their employment and of the harshness, greed, and deception, with which they did their job.</li></ol>","xlit":"telṓnēs"},"G4158":{"kjv_def":"garment down to the foot","lemma":"ποδήρης","translit":"podḗrēs","derivation":"from G4228 (πούς) and another element of uncertain affinity;","strongs_def":" a dress (G2066 (ἐσθής) implied) reaching the ankles","pron":"pod-ay'-race","pos":"Adjective","thayer":"<ol><li>reaching to the feet</li><li>a garment reaching to the ankles, coming down to the feet</li></ol>","xlit":"podḗrēs"},"G3669":{"lemma":"ὁμοίωσις","translit":"homoíōsis","kjv_def":"similitude","strongs_def":" assimilation, i.e. resemblance","derivation":"from G3666 (ὁμοιόω);","pron":"hom-oy'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>a making like</li><li>likeness: after the likeness of God</li></ol>","xlit":"homoíōsis"},"G1723":{"derivation":"from G1722 (ἐν) and a derivative of G43 (ἀγκάλη);","strongs_def":" to take in one's arms, i.e. embrace","kjv_def":"take up in arms","translit":"enankalízomai","lemma":"ἐναγκαλίζομαι","pron":"en-ang-kal-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to take into one's arms, embrace</li></ol>","xlit":"enankalízomai"},"G199":{"strongs_def":" exactly","derivation":"adverb from the same as G196 (ἀκριβέστατος);","lemma":"ἀκριβῶς","translit":"akribōs","kjv_def":"circumspectly, diligently, perfect(-ly)","pron":"ak-ree-boce'","pos":"Adverb","thayer":"<ol><li>exactly, accurately, diligently</li></ol>","xlit":"akribōs"},"G4835":{"derivation":"from G4841 (συμπάσχω);","strongs_def":" having a fellow-feeling (\"sympathetic\"), i.e. (by implication) mutually commiserative","kjv_def":"having compassion one of another","lemma":"συμπαθής","translit":"sympathḗs","pron":"soom-path-ace'","pos":"Adjective","thayer":"<ol><li>suffering or feeling the like with another, sympathetic</li></ol>","xlit":"sympathḗs"},"G2036":{"derivation":"a primary verb (used only in the definite past tense, the others being borrowed from G2046 (ἐρέω), G4483 (ῥέω), and G5346 (φημί));","strongs_def":" to speak or say (by word or writing)","kjv_def":"answer, bid, bring word, call, command, grant, say (on), speak, tell","translit":"épō","lemma":"ἔπω","pron":"ep'-o","pos":"Verb","thayer":"<ol><li>to speak, say</li></ol>","xlit":"épō"},"G2618":{"derivation":"from G2596 (κατά) and G2545 (καίω);","strongs_def":" to burn down (to the ground), i.e. consume wholly","kjv_def":"burn (up, utterly)","translit":"katakaíō","lemma":"κατακαίω","pron":"kat-ak-ah'-ee-o","pos":"Verb","thayer":"<ol><li>to burn up, consume by fire</li></ol>","xlit":"katakaíō"},"G205":{"strongs_def":" properly (in the plural) the top of the heap, i.e. (by implication) best of the booty","derivation":"from G206 (ἄκρον) and (a heap);","lemma":"ἀκροθίνιον","translit":"akrothínion","kjv_def":"spoils","pron":"ak-roth-in'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>top of the heap, the first fruits<ol type='a'><li>best of the spoils or crops</li></ol><li>the Greeks customarily selected from the topmost part of the heaps and offered this to the gods</li></ol>","xlit":"akrothínion"},"G4462":{"derivation":"of Chaldee origin;","strongs_def":" corresponding to G4461 (ῥαββί)","kjv_def":"Lord, Rabboni","lemma":"ῥαββονί","translit":"rhabboní","pron":"hrab-bon-ee'","pos":"Noun Masculine","thayer":"<ol><li>master, chief, prince</li><li>Rabboni is a title of honour Mary used to address Jesus</li></ol>","xlit":"rhabboní"},"G264":{"kjv_def":"for your faults, offend, sin, trespass","translit":"hamartánō","lemma":"ἁμαρτάνω","derivation":"perhaps from G1 (Α) (as a negative particle) and the base of G3313 (μέρος);","strongs_def":" properly, to miss the mark (and so not share in the prize), i.e. (figuratively) to err, especially (morally) to sin","pron":"ham-ar-tan'-o","pos":"Verb","thayer":"<ol><li>to be without a share in</li><li>to miss the mark</li><li>to err, be mistaken</li><li>to miss or wander from the path of uprightness and honour, to do or go wrong</li><li>to wander from the law of God, violate God's law, sin</li></ol>","xlit":"hamartánō"},"G30":{"lemma":"ἀγγεῖον","translit":"angeîon","kjv_def":"vessel","strongs_def":" compare the base of G43 (ἀγκάλη)); a receptacle","derivation":"from (a pail, perhaps as bent;","pron":"ang-eye'-on","pos":"Noun Neuter","thayer":"<ol><li>a vessel, receptacle, a pail, a reservoir</li></ol>","xlit":"angeîon"},"G724":{"derivation":"from G726 (ἁρπάζω);","strongs_def":" pillage (properly abstract)","kjv_def":"extortion, ravening, spoiling","lemma":"ἁρπαγή","translit":"harpagḗ","pron":"har-pag-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act of plundering, robbery</li><li>plunder spoil</li></ol>","xlit":"harpagḗ"},"G5472":{"translit":"chalkēdṓn","lemma":"χαλκηδών","kjv_def":"chalcedony","strongs_def":" copper-like, i.e. \"chalcedony\"","derivation":"from G5475 (χαλκός) and perhaps G1491 (εἶδος);","pron":"khal-kay-dohn'","pos":"Noun Masculine","thayer":"<ol><li>chalcedony is a precious stone of misty grey colour, clouded with blue, yellow, or purple</li></ol>","xlit":"chalkēdṓn"},"G1053":{"lemma":"Γαλατία","translit":"Galatía","kjv_def":"Galatia","strongs_def":" Galatia, a region of Asia","derivation":"of foreign origin;","pron":"gal-at-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Galatia = \"land of the Galli, Gauls\"</p><ol><li>the Roman province of Galatia my be roughly described as the central region of the peninsula of Asia Minor, bounded on the north by Bithynia and Paphlagonia; on the east by Pontus; on the south by Cappadocia and Lycaonia; on the west by Phrygia</li></ol>","xlit":"Galatía"},"G2252":{"derivation":"a prolonged form of G2258 (ἦν);","strongs_def":" I was","kjv_def":"be, was","lemma":"ἤμην","translit":"ḗmēn","pron":"ay'-mane","pos":"Adverb","thayer":"<ol><li>truly, assuredly</li></ol>","xlit":"ḗmēn"},"G5184":{"derivation":"of Hebrew origin (H06865): Tyrus (i.e. Tsor), a place in Palestine","kjv_def":"Tyre","translit":"Týros","lemma":"Τύρος","pron":"too'-ros","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tyre = \"a rock\"</p><ol><li>a Phoenician city on the Mediterranean, very ancient, large, splendid, flourishing in commerce, and powerful by land and sea</li></ol>","xlit":"Týros"},"G855":{"strongs_def":" non-manifested, i.e. invisible","derivation":"from G1 (Α) (as a negative particle) and a derivative of G5316 (φαίνω);","lemma":"ἄφαντος","translit":"áphantos","kjv_def":"vanished out of sight","pron":"af'-an-tos","pos":"Adjective","thayer":"<ol><li>taken out of sight, made invisible</li></ol>","xlit":"áphantos"},"G170":{"kjv_def":"lack opportunity","lemma":"ἀκαιρέομαι","translit":"akairéomai","derivation":"from a compound of G1 (Α) (as a negative particle) and G2540 (καιρός) (meaning unseasonable);","strongs_def":" to be inopportune (for oneself), i.e. to fail of a proper occasion","pron":"ak-ahee-reh'-om-ahee","pos":"Verb","thayer":"<ol><li>to lack opportunity</li></ol>","xlit":"akairéomai"},"G1718":{"derivation":"from G1717 (ἐμφανής);","strongs_def":" to exhibit (in person) or disclose (by words)","kjv_def":"appear, declare (plainly), inform, (will) manifest, shew, signify","lemma":"ἐμφανίζω","translit":"emphanízō","pron":"em-fan-id'-zo","pos":"Verb","thayer":"<ol><li>to manifest, exhibit to view</li><li>to show one's self, come to view, appear, be manifest</li><li>to indicate, disclose, declare, make known</li></ol>","xlit":"emphanízō"},"G537":{"strongs_def":" absolutely all or (singular) every one","derivation":"from G1 (Α) (as a particle of union) and G3956 (πᾶς);","lemma":"ἅπας","translit":"hápas","kjv_def":"all (things), every (one), whole","pron":"hap'-as","pos":"Adjective","thayer":"<ol><li>quite, all, the whole, all together, all</li></ol>","xlit":"hápas"},"G398":{"lemma":"ἀναφαίνω","translit":"anaphaínō","kjv_def":"(should) appear, discover","strongs_def":" to show, i.e. (reflexively) appear, or (passively) to have pointed out","derivation":"from G303 (ἀνά) and G5316 (φαίνω);","pron":"an-af-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to bring to light, hold up to view, show</li><li>to appear, be made apparent</li></ol>","xlit":"anaphaínō"},"G4415":{"translit":"prōtotókia","lemma":"πρωτοτόκια","kjv_def":"birthright","strongs_def":" primogeniture (as a privilege)","derivation":"from G4416 (πρωτότοκος);","pron":"pro-tot-ok'-ee-ah","pos":"Noun Neuter","thayer":"<ol><li>the right or advantages of the first born son</li></ol>","xlit":"prōtotókia"},"G5413":{"derivation":"diminutive of G5414 (φόρτος);","strongs_def":" an invoice (as part of freight), i.e. (figuratively) a task or service","kjv_def":"burden","translit":"phortíon","lemma":"φορτίον","pron":"for-tee'-on","pos":"Noun Neuter","thayer":"<ol><li>a burden, load<ol type='a'><li>of the freight or lading of a ship</li></ol><li>metaphorically<ol type='a'><li>of burdensome rites</li><li>of the obligations Christ lays upon his followers, and styles a \"burden\" by way of the contrast to the precepts of the Pharisees, the observance of which was most oppressive</li><li>faults of the conscience which oppress the soul</li></ol></li></ol>","xlit":"phortíon"},"G4007":{"derivation":"from the base of G4008 (πέραν);","strongs_def":" an enclitic particle significant of abundance (thoroughness), i.e. emphasis; much, very or ever","kjv_def":"(whom-)soever","lemma":"περ","translit":"per","pron":"per","thayer":"<ol><li>however much, very much, altogether, indeed</li></ol>","xlit":"per"},"G2646":{"kjv_def":" guestchamber, inn","lemma":"κατάλυμα","translit":"katályma","derivation":"from G2647 (καταλύω);","strongs_def":" properly, a dissolution (breaking up of a journey), i.e. (by implication) a lodging-place","pron":"kat-al'-oo-mah","pos":"Noun Neuter","thayer":"<ol><li>an inn, lodging place</li><li>an eating room, dining room</li></ol>","xlit":"katályma"},"G4029":{"derivation":"from G4012 (περί) and G2749 (κεῖμαι);","strongs_def":" to lie all around, i.e. inclose, encircle, hamper (literally or figuratively)","kjv_def":"be bound (compassed) with, hang about","translit":"períkeimai","lemma":"περίκειμαι","pron":"per-ik'-i-mahee","pos":"Verb","thayer":"<ol><li>to lie around</li><li>to be compassed with, have round one</li></ol>","xlit":"períkeimai"},"G1713":{"kjv_def":"merchant","translit":"émporos","lemma":"ἔμπορος","derivation":"from G1722 (ἐν) and the base of G4198 (πορεύομαι);","strongs_def":" a (wholesale) tradesman","pron":"em'-por-os","pos":"Noun Masculine","thayer":"<ol><li>one on a journey, whether by sea or by land, especially for trade</li><li>a merchant as opposed to a retailer or petty tradesman</li></ol>","xlit":"émporos"},"G2823":{"strongs_def":" an earthen pot used for baking in","derivation":"of uncertain derivation;","translit":"klíbanos","lemma":"κλίβανος","kjv_def":"oven","pron":"klib'-an-os","pos":"Noun Masculine","thayer":"<ol><li>a clibanus, an earthen vessel for baking bread. It was broader at the bottom than above at the orifice, and when sufficiently heated by a fire kindled within, the dough was baked by being spread upon the outside. [But according to others, the dough was baked by being placed inside and the fire or coals outside, the vessel being perforated with small holes that the heat might better penetrate.]</li><li>a furnace, oven</li></ol>","xlit":"klíbanos"},"G4938":{"strongs_def":" concussion or utter fracture (properly, concretely), i.e. complete ruin","derivation":"from G4937 (συντρίβω);","lemma":"σύντριμμα","translit":"sýntrimma","kjv_def":"destruction","pron":"soon-trim'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is broken or shattered, a fracture</li><li>calamity, ruin, destruction</li></ol>","xlit":"sýntrimma"},"G5605":{"strongs_def":" to experience the pains of parturition (literally or figuratively)","derivation":"from G5604 (ὠδίν);","translit":"ōdínō","lemma":"ὠδίνω","kjv_def":"travail in (birth)","pron":"o-dee'-no","pos":"Verb","thayer":"<ol><li>to feel the pains of child birth, to travail</li></ol>","xlit":"ōdínō"},"G485":{"kjv_def":"contradiction, gainsaying, strife","lemma":"ἀντιλογία","translit":"antilogía","derivation":"from a derivative of G483 (ἀντιλέγω);","strongs_def":" dispute, disobedience","pron":"an-tee-log-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>gainsaying, contradiction</li><li>opposition, rebellion</li></ol>","xlit":"antilogía"},"G4292":{"kjv_def":"provoke","translit":"prokaléomai","lemma":"προκαλέομαι","derivation":"middle voice from G4253 (πρό) and G2564 (καλέω);","strongs_def":" to call forth to oneself (challenge), i.e. (by implication) to irritate","pron":"prok-al-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to call forth</li><li>to call forth to one's self<ol type='a'><li>especially to challenge to a combat or contest with one</li></ol><li>to provoke, to irritate</li></ol>","xlit":"prokaléomai"},"G1142":{"kjv_def":"devil","lemma":"δαίμων","translit":"daímōn","derivation":"from (to distribute fortunes);","strongs_def":" a dæmon or supernatural spirit (of a bad nature)","pron":"dah'-ee-mown","pos":"Noun","thayer":"<ol><li>a god, a goddess<ol type='a'><li>an inferior deity, whether good or bad</li></ol><li>in the NT, an evil spirit</li></ol>","xlit":"daímōn"},"G1775":{"kjv_def":"unity","lemma":"ἑνότης","translit":"henótēs","derivation":"from G1520 (εἷς);","strongs_def":" oneness, i.e. (figuratively) unanimity","pron":"hen-ot-ace'","pos":"Noun Feminine","thayer":"<ol><li>unity</li><li>unanimity, agreement</li></ol>","xlit":"henótēs"},"G684":{"kjv_def":"damnable(-nation), destruction, die, perdition, X perish, pernicious ways, waste","lemma":"ἀπώλεια","translit":"apṓleia","derivation":"from a presumed derivative of G622 (ἀπόλλυμι);","strongs_def":" ruin or loss (physical, spiritual or eternal)","pron":"ap-o'-li-a","pos":"Noun Feminine","thayer":"<ol><li>destroying, utter destruction<ol type='a'><li>of vessels</li></ol><li>a perishing, ruin, destruction<ol type='a'><li>of money</li><li>the destruction which consists of eternal misery in hell</li></ol></li></ol>","xlit":"apṓleia"},"G2979":{"strongs_def":" to recalcitrate","derivation":"from adverb (heelwise);","translit":"laktízō","lemma":"λακτίζω","kjv_def":"kick","pron":"lak-tid'-zo","pos":"Verb","thayer":"<ol><li>to kick, strike with the heel</li></ol>","xlit":"laktízō"},"G1087":{"lemma":"γερουσία","translit":"gerousía","kjv_def":"senate","strongs_def":" the eldership, i.e. (collectively) the Jewish Sanhedrin","derivation":"from G1088 (γέρων);","pron":"gher-oo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>a senate, council of elders<ol type='a'><li>to denote the chief council of nations or cities</li><li>the Sanhedrin</li></ol></li></ol>","xlit":"gerousía"},"G5100":{"kjv_def":"a (kind of), any (man, thing, thing at all), certain (thing), divers, he (every) man, one (X thing), ought, + partly, some (man, -body, - thing, -what), (+ that no-)thing, what(-soever), X wherewith, whom(-soever), whose(-soever)","lemma":"τὶς","translit":"tìs","derivation":"an enclitic indefinite pronoun;","strongs_def":" some or any person or object","pron":"tis","thayer":"<ol><li>a certain, a certain one</li><li>some, some time, a while</li></ol>","xlit":"tìs"},"G2839":{"lemma":"κοινός","translit":"koinós","kjv_def":"common, defiled, unclean, unholy","strongs_def":" common, i.e. (literally) shared by all or several, or (ceremonially) profane","derivation":"probably from G4862 (σύν);","pron":"koy-nos'","pos":"Adjective","thayer":"<ol><li>common</li><li>common, i.e. ordinary, belonging to generality<ol type='a'><li>by the Jews, unhallowed, profane, Levitically unclean</li></ol></li></ol>","xlit":"koinós"},"G5215":{"derivation":"apparently from a simpler (obsolete) form of (to celebrate;","strongs_def":" probably akin to G103 (ᾄδω); compare H05667); a \"hymn\" or religious ode (one of the Psalms)","kjv_def":"hymn","translit":"hýmnos","lemma":"ὕμνος","pron":"hoom'-nos","pos":"Noun Masculine","thayer":"<ol><li>a song in the praise of gods, heroes, conquerors</li><li>a sacred song, hymn</li></ol>","xlit":"hýmnos"},"G5204":{"kjv_def":"water","lemma":"ὕδωρ","translit":"hýdōr","derivation":"from the base of G5205 (ὑετός);","strongs_def":" water (as if rainy) literally or figuratively","pron":"hoo'-dore","pos":"Noun Neuter","thayer":"<ol><li>water<ol type='a'><li>of water in rivers, in fountains, in pools</li><li>of the water of the deluge</li><li>of water in any of the earth's repositories</li><li>of water as the primary element, out of and through which the world that was before the deluge, arose and was compacted</li><li>of the waves of the sea</li><li>fig. used of many peoples</li></ol></li></ol>","xlit":"hýdōr"},"G5488":{"strongs_def":" Charrhan (i.e. Charan), a place in Mesopotamia","derivation":"of Hebrew origin (H02771);","translit":"Charrhán","lemma":"Χαῤῥάν","kjv_def":"Charran","pron":"khar-hran'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Haran = \"a mountaineer\"</p><ol><li>a city in Mesopotamia, of great antiquity and made famous by the defeat of Crassus</li></ol>","xlit":"Charrhán"},"G2904":{"derivation":"perhaps a primary word;","strongs_def":" vigor (\"great\") (literally or figuratively)","kjv_def":"dominion, might(-ily), power, strength","lemma":"κράτος","translit":"krátos","pron":"krat'-os","pos":"Noun Neuter","thayer":"<ol><li>force, strength</li><li>power, might: mighty with great power<ol type='a'><li>a mighty deed, a work of power</li></ol><li>dominion</li></ol>","xlit":"krátos"},"G841":{"kjv_def":"contentment, sufficiency","lemma":"αὐτάρκεια","translit":"autárkeia","derivation":"from G842 (αὐτάρκης);","strongs_def":" self-satisfaction, i.e. (abstractly) contentedness, or (concretely) a competence","pron":"ow-tar'-ki-ah","pos":"Noun Feminine","thayer":"<ol><li>a perfect condition of life in which no aid or support is needed</li><li>sufficiency of the necessities of life</li><li>a mind contented with its lot, contentment</li></ol>","xlit":"autárkeia"},"G3724":{"strongs_def":" to mark out or bound (\"horizon\"), i.e. (figuratively) to appoint, decree, specify","derivation":"from G3725 (ὅριον);","translit":"horízō","lemma":"ὁρίζω","kjv_def":"declare, determine, limit, ordain","pron":"hor-id'-zo","pos":"Verb","thayer":"<ol><li>to define<ol type='a'><li>to mark out the boundaries or limits (of any place or thing)<ol><li>that which has been determined, acc. to appointment, decree</li><li>to ordain, determine, appoint</li></ol></li></ol></li></ol>","xlit":"horízō"},"G1258":{"kjv_def":"language, tongue","lemma":"διάλεκτος","translit":"diálektos","derivation":"from G1256 (διαλέγομαι);","strongs_def":" a (mode of) discourse, i.e. \"dialect\"","pron":"dee-al'-ek-tos","pos":"Noun Feminine","thayer":"<ol><li>conversation, speech, discourse, language</li><li>the tongue or language peculiar to any people</li></ol>","xlit":"diálektos"},"G3108":{"strongs_def":" beatification, i.e. attribution of good fortune","derivation":"from G3106 (μακαρίζω);","lemma":"μακαρισμός","translit":"makarismós","kjv_def":"blessedness","pron":"mak-ar-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>declaration of blessedness</li><li>to utter a declaration of blessedness upon one</li><li>to pronounce one blessed</li></ol>","xlit":"makarismós"},"G1478":{"kjv_def":"Ezekias","translit":"Ezekías","lemma":"Ἐζεκίας","derivation":"of Hebrew origin (H02396);","strongs_def":" Ezekias (i.e. Hezekeiah), an Israelite","pron":"ed-zek-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Hezekiah = \"the might of Jehovah\"</p><ol><li>the twelfth king of Judah</li></ol>","xlit":"Ezekías"},"G3863":{"kjv_def":"provoke to emulation (jealousy)","lemma":"παραζηλόω","translit":"parazēlóō","derivation":"from G3844 (παρά) and G2206 (ζηλόω);","strongs_def":" to stimulate alongside, i.e. excite to rivalry","pron":"par-ad-zay-lo'-o","pos":"Verb","thayer":"<ol><li>to provoke to<ol type='a'><li>to provoke to jealously or rivalry</li><li>to provoke to anger</li></ol></li></ol>","xlit":"parazēlóō"},"G619":{"translit":"apólausis","lemma":"ἀπόλαυσις","kjv_def":"enjoy(-ment)","strongs_def":" full enjoyment","derivation":"from a comparative of G575 (ἀπό) and (to enjoy);","pron":"ap-ol'-ow-sis","pos":"Noun Feminine","thayer":"<ol><li>enjoyment</li></ol>","xlit":"apólausis"},"G2885":{"kjv_def":"adorn, garnish, trim","lemma":"κοσμέω","translit":"kosméō","derivation":"from G2889 (κόσμος);","strongs_def":" to put in proper order, i.e. decorate (literally or figuratively); specially, to snuff (a wick)","pron":"kos-meh'-o","pos":"Verb","thayer":"<ol><li>to put in order, arrange, make ready, prepare</li><li>to ornament, adore</li><li>metaphorically to embellish with honour, gain honour</li></ol>","xlit":"kosméō"},"G4670":{"lemma":"Σόδομα","translit":"Sódoma","kjv_def":"Sodom","strongs_def":" Sodoma (i.e. Sedom), a place in Palestine","derivation":"plural of Hebrew origin (H05467);","pron":"sod'-om-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sodom = \"burning\"</p><ol><li>a city destroyed by the Lord raining fire and brimstone on it</li><li>metaphorically Jerusalem <a class='bible' href='#b66.11.8'>Rev 11:8</a></li></ol>","xlit":"Sódoma"},"G5292":{"kjv_def":"subjection","lemma":"ὑποταγή","translit":"hypotagḗ","derivation":"from G5293 (ὑποτάσσω);","strongs_def":" subordination","pron":"hoop-ot-ag-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act of subjecting</li><li>obedience, subjection</li></ol>","xlit":"hypotagḗ"},"G5435":{"strongs_def":" Phrygia, a region of Asia Minor","derivation":"probably of foreign origin;","lemma":"Φρυγία","translit":"Phrygía","kjv_def":"Phrygia","pron":"froog-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Phrygia = \"dry, barren\"</p><ol><li>a region in Asia Minor bounded by Bithynia, Galatia, Lycaonia, Pisidia, Lydia, Mysia and it contained the cities of Laodicea, Hierapolis, and Colosse</li></ol>","xlit":"Phrygía"},"G1668":{"strongs_def":" an ulcer (as if drawn together)","derivation":"probably from G1670 (ἑλκύω);","lemma":"ἕλκος","translit":"hélkos","kjv_def":"sore","pron":"hel'-kos","pos":"Noun Neuter","thayer":"<ol><li>a wound, especially a wound producing a discharge pus</li><li>a sore, an ulcer</li></ol>","xlit":"hélkos"},"G1888":{"strongs_def":" in theft itself, i.e. (by analogy) in actual crime","derivation":"from G1909 (ἐπί) and G846 (αὐτός) and (the dative case singular of) a derivative of (a thief);","translit":"epautophṓrōi","lemma":"ἐπαυτοφώρῳ","kjv_def":"in the very act","pron":"ep-ow-tof-o'-ro","pos":"Adverb","thayer":"<ol><li>in the act</li><li>caught in the act of theft</li><li>caught in the act of perpetuating any other crime</li></ol>","xlit":"epautophṓrōi"},"G1403":{"derivation":"from G1209 (δέχομαι);","strongs_def":" a reception, i.e. convivial entertainment","kjv_def":"feast","translit":"dochḗ","lemma":"δοχή","pron":"dokh-ay'","pos":"Noun Feminine","thayer":"<ol><li>a feast, banquet</li></ol>","xlit":"dochḗ"},"G3897":{"derivation":"neuter of a compound of G3844 (παρά) and the base of G4139 (πλησίον) (as adverb);","strongs_def":" close by, i.e. (figuratively) almost","kjv_def":"nigh unto","lemma":"παραπλήσιον","translit":"paraplḗsion","pron":"par-ap-lay'-see-on","pos":"Adjective","thayer":"<ol><li>near to, almost to</li></ol>","xlit":"paraplḗsion"},"G883":{"lemma":"Ἀχαϊκός","translit":"Achaïkós","kjv_def":"Achaicus","strongs_def":" an Achaian; Achaicus, a Christian","derivation":"from G882 (Ἀχαΐα);","pron":"ach-ah-ee-kos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Achaicus = \"belonging to Achaia\"</p><ol><li>the name of a Christian in Corinth</li></ol>","xlit":"Achaïkós"},"G1006":{"derivation":"a prolonged form of a primary verb (compare G977 (βιβρώσκω), G1016 (βοῦς));","strongs_def":" to pasture; by extension to, fodder; reflexively, to graze","kjv_def":"feed, keep","translit":"bóskō","lemma":"βόσκω","pron":"bos'-ko","pos":"Verb","thayer":"<ol><li>to feed<ol type='a'><li>portraying the duty of a Christian teacher to promote in every way the spiritual welfare of the members of the church</li></ol></li></ol>","xlit":"bóskō"},"G514":{"derivation":"probably from G71 (ἄγω);","strongs_def":" deserving, comparable or suitable (as if drawing praise)","kjv_def":"due reward, meet, (un-)worthy","lemma":"ἄξιος","translit":"áxios","pron":"ax'-ee-os","pos":"Adjective","thayer":"<ol><li>weighing, having weight, having the weight of another thing of like value, worth as much</li><li>befitting, congruous, corresponding to a thing</li><li>of one who has merited anything worthy<ol type='a'><li>both in a good and a bad sense</li></ol></li></ol>","xlit":"áxios"},"G4313":{"strongs_def":" to precede (as guide or herald)","derivation":"from G4253 (πρό) and G4198 (πορεύομαι);","translit":"proporeúomai","lemma":"προπορεύομαι","kjv_def":"go before","pron":"prop-or-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to send before, to make to precede</li><li>to go before one<ol type='a'><li>of a leader</li><li>of a messenger or a herald</li></ol></li></ol>","xlit":"proporeúomai"},"G1189":{"kjv_def":"beseech, pray (to), make request","lemma":"δέομαι","translit":"déomai","derivation":"middle voice of G1210 (δέω);","strongs_def":" to beg (as binding oneself), i.e. petition","pron":"deh'-om-ahee","pos":"Verb","thayer":"<ol><li>to want, lack</li><li>to desire, long for</li><li>to ask, beg<ol type='a'><li>the thing asked for</li><li>to pray, make supplications</li></ol></li></ol>","xlit":"déomai"},"G1136":{"strongs_def":" Gog, a symbolic name for some future Antichrist","derivation":"of Hebrew origin (H01463);","lemma":"Γώγ","translit":"Gṓg","kjv_def":"Gog","pron":"gogue","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gog = \"mountain\"</p><ol><li>the king of the land of Magog who will come from the north and attack the land of Israel</li></ol>","xlit":"Gṓg"},"G3126":{"kjv_def":"mammon","lemma":"μαμμωνᾶς","translit":"mammōnâs","derivation":"of Chaldee origin (confidence, i.e. wealth, personified);","strongs_def":" mammonas, i.e. avarice (deified)","pron":"mam-mo-nas'","pos":"Noun Masculine","thayer":"<ol><li>mammon</li><li>treasure</li><li>riches (where it is personified and opposed to God)</li></ol>","xlit":"mammōnâs"},"G1344":{"translit":"dikaióō","lemma":"δικαιόω","kjv_def":"free, justify(-ier), be righteous","strongs_def":" to render (i.e. show or regard as) just or innocent","derivation":"from G1342 (δίκαιος);","pron":"dik-ah-yo'-o","pos":"Verb","thayer":"<ol><li>to render righteous or such he ought to be</li><li>to show, exhibit, evince, one to be righteous, such as he is and wishes himself to be considered</li><li>to declare, pronounce, one to be just, righteous, or such as he ought to be</li></ol>","xlit":"dikaióō"},"G3994":{"kjv_def":"mother in law, wife's mother","lemma":"πενθερά","translit":"pentherá","derivation":"feminine of G3995 (πενθερός);","strongs_def":" a wife's mother","pron":"pen-ther-ah'","pos":"Noun Feminine","thayer":"<ol><li>mother-in-law, a wife's mother</li></ol>","xlit":"pentherá"},"G5552":{"translit":"chrýseos","lemma":"χρύσεος","kjv_def":"of gold, golden","strongs_def":" made of gold","derivation":"from G5557 (χρυσός);","pron":"khroo'-seh-os","pos":"Adjective","thayer":"<ol><li>golden</li><li>made of gold</li><li>overlaid or covered with gold</li></ol>","xlit":"chrýseos"},"G1224":{"translit":"diabaínō","lemma":"διαβαίνω","kjv_def":"come over, pass (through)","strongs_def":" to cross","derivation":"from G1223 (διά) and the base of G939 (βάσις);","pron":"dee-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to pass through, cross over</li></ol>","xlit":"diabaínō"},"G2038":{"kjv_def":"commit, do, labor for, minister about, trade (by), work","lemma":"ἐργάζομαι","translit":"ergázomai","derivation":"middle voice from G2041 (ἔργον);","strongs_def":" to toil (as a task, occupation, etc.), (by implication) effect, be engaged in or with, etc.","pron":"er-gad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to work, labour, do work</li><li>to trade, to make gains by trading, \"do business\"</li><li>to do, work out<ol type='a'><li>exercise, perform, commit</li><li>to cause to exist, produce</li></ol><li>to work for, earn by working, to acquire</li></ol>","xlit":"ergázomai"},"G1666":{"lemma":"Ἐλισσαῖος","translit":"Elissaîos","kjv_def":"Elissæus","strongs_def":" Elissæus, an Israelite","derivation":"of Hebrew origin (H0477);","pron":"el-is-sah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eliseus or Elisha = \"God his salvation\"</p><ol><li>a distinguished OT prophet, the disciple, companion, and successor of Elijah</li></ol>","xlit":"Elissaîos"},"G3977":{"kjv_def":"plain","lemma":"πεδινός","translit":"pedinós","derivation":"from a derivative of G4228 (πούς) (meaning the ground);","strongs_def":" level (as easy for the feet)","pron":"ped-ee-nos'","pos":"Adjective","thayer":"<ol><li>level, plain</li></ol>","xlit":"pedinós"},"G1481":{"strongs_def":" the governor (not king) of a district","derivation":"from G1484 (ἔθνος) and G746 (ἀρχή);","lemma":"ἐθνάρχης","translit":"ethnárchēs","kjv_def":"ethnarch","pron":"eth-nar'-khace","pos":"Noun Masculine","thayer":"<ol><li>an ethnarch, one set over a people as ruler, but without the authority and name of a king</li></ol>","xlit":"ethnárchēs"},"G3202":{"kjv_def":"complainer","translit":"mempsímoiros","lemma":"μεμψίμοιρος","derivation":"from a presumed derivative of G3201 (μέμφομαι) and (fate;","strongs_def":" akin to the base of G3313 (μέρος)); blaming fate, i.e. querulous (discontented)","pron":"mem-psim'-oy-ros","pos":"Adjective","thayer":"<ol><li>complaining of one's lot, querulous, discontented</li></ol>","xlit":"mempsímoiros"},"G1506":{"translit":"eilikrinḗs","lemma":"εἰλικρινής","kjv_def":"pure, sincere","strongs_def":" judged by sunlight, i.e. tested as genuine (figuratively)","derivation":"from (the sun's ray) and G2919 (κρίνω);","pron":"i-lik-ree-nace'","pos":"Adjective","thayer":"<ol><li>pure, sincere, unsullied</li><li>found pure when unfolded and examined by the sun's light</li></ol>","xlit":"eilikrinḗs"},"G2515":{"kjv_def":"seat","lemma":"καθέδρα","translit":"kathédra","derivation":"from G2596 (κατά) and the same as G1476 (ἑδραῖος);","strongs_def":" a bench (literally or figuratively)","pron":"kath-ed'-rah","pos":"Noun Feminine","thayer":"<ol><li>a chair, a seat<ol type='a'><li>used of the exalted seat occupied by men of eminent rank or influence, as teachers and judges</li></ol></li></ol>","xlit":"kathédra"},"G1195":{"translit":"desmeúō","lemma":"δεσμεύω","kjv_def":" bind","strongs_def":" to be a binder (captor), i.e. to enchain (a prisoner), to tie on (a load)","derivation":"from a (presumed) derivative of G1196 (δεσμέω);","pron":"des-myoo'-o","pos":"Verb","thayer":"<ol><li>to put in chains</li><li>to bind up, bind together</li></ol>","xlit":"desmeúō"},"G1480":{"translit":"ethízō","lemma":"ἐθίζω","kjv_def":"custom","strongs_def":" to accustom, i.e. (neuter passive participle) customary","derivation":"from G1485 (ἔθος);","pron":"eth-id'-zo","pos":"Verb","thayer":"<ol><li>to accustomed, usage, custom</li></ol>","xlit":"ethízō"},"G4060":{"kjv_def":"bestow upon, hedge round about, put about (on, upon), set about","translit":"peritíthēmi","lemma":"περιτίθημι","derivation":"from G4012 (περί) and G5087 (τίθημι);","strongs_def":" to place around; by implication, to present","pron":"per-ee-tith'-ay-mee","pos":"Verb","thayer":"<ol><li>to place around, set about</li><li>to put on a garment</li><li>to put or bind a thing around another</li><li>to present, to bestow, confer, a thing upon one</li></ol>","xlit":"peritíthēmi"},"G3888":{"kjv_def":"comfort","translit":"paramythéomai","lemma":"παραμυθέομαι","derivation":"from G3844 (παρά) and the middle voice of a derivative of G3454 (μῦθος);","strongs_def":" to relate near, i.e. (by implication) encourage, console","pron":"par-am-oo-theh'-om-ahee","pos":"Verb","thayer":"<ol><li>to speak to, address one, whether by way of admonition and incentive, or to calm and console<ol type='a'><li>to encourage, console</li></ol></li></ol>","xlit":"paramythéomai"},"G3190":{"derivation":"of uncertain origin;","strongs_def":" Meleas, an Israelite","kjv_def":"Meleas","lemma":"Μελεᾶς","translit":"Meleâs","pron":"mel-eh-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Melea = \"my dear friend: object of care\"</p><ol><li>the son of Joseph in the genealogy of Christ</li></ol>","xlit":"Meleâs"},"G5555":{"lemma":"χρυσόλιθος","translit":"chrysólithos","kjv_def":"chrysolite","strongs_def":" gold-stone, i.e. a yellow gem (\"chrysolite\")","derivation":"from G5557 (χρυσός) and G3037 (λίθος);","pron":"khroo-sol'-ee-thos","pos":"Noun Masculine","thayer":"<ol><li>chrysolite is a precious stone of golden colour</li></ol>","xlit":"chrysólithos"},"G2314":{"strongs_def":" an opponent of deity","derivation":"from G2316 (θεός) and G3164 (μάχομαι);","translit":"theomáchos","lemma":"θεομάχος","kjv_def":"to fight against God","pron":"theh-om'-akh-os","pos":"Adjective","thayer":"<ol><li>fighting against God, resisting God</li></ol>","xlit":"theomáchos"},"G3438":{"derivation":"from G3306 (μένω);","strongs_def":" a staying, i.e. residence (the act or the place)","kjv_def":"abode, mansion","lemma":"μονή","translit":"monḗ","pron":"mon-ay'","pos":"Noun Feminine","thayer":"<ol><li>a staying, abiding, dwelling, abode</li><li>to make an (one's) abode</li><li>metaphorically of the God the Holy Spirit indwelling believers</li></ol>","xlit":"monḗ"},"G3837":{"strongs_def":" universally","derivation":"genitive case (as adverb of place) of a presumed derivative of G3956 (πᾶς);","translit":"pantachoû","lemma":"πανταχοῦ","kjv_def":"in all places, everywhere","pron":"pan-takh-oo'","pos":"Adverb","thayer":"<ol><li>everywhere</li></ol>","xlit":"pantachoû"},"G2826":{"kjv_def":"bed","lemma":"κλινίδιον","translit":"klinídion","derivation":"neuter of a presumed derivative of G2825 (κλίνη);","strongs_def":" a pallet or little couch","pron":"klin-id'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a small bed, a couch</li></ol>","xlit":"klinídion"},"G5054":{"kjv_def":"death","lemma":"τελευτή","translit":"teleutḗ","derivation":"from G5053 (τελευτάω);","strongs_def":" decease","pron":"tel-yoo-tay'","pos":"Noun Feminine","thayer":"<ol><li>the end of life, decease, death</li></ol>","xlit":"teleutḗ"},"G1988":{"derivation":"from G1909 (ἐπί) and a presumed derivative of G2476 (ἵστημι);","strongs_def":" an appointee over, i.e. commander (teacher)","kjv_def":"master","lemma":"ἐπιστάτης","translit":"epistátēs","pron":"ep-is-tat'-ace","pos":"Noun Masculine","thayer":"<ol><li>any sort of superintendent or overseer</li></ol>","xlit":"epistátēs"},"G3476":{"kjv_def":"Naasson","lemma":"Ναασσών","translit":"Naassṓn","derivation":"of Hebrew origin (H05177);","strongs_def":" Naasson (i.e. Nachshon), an Israelite","pron":"nah-as-sone'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nahshon = \"enchanter\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Naassṓn"},"G1842":{"derivation":"from G1537 (ἐκ) and G3645 (ὀλοθρεύω);","strongs_def":" to extirpate","kjv_def":"destroy","lemma":"ἐξολοθρεύω","translit":"exolothreúō","pron":"ex-ol-oth-ryoo'-o","pos":"Verb","thayer":"<ol><li>to destroy out of its place, destroy utterly, to extirpate</li></ol>","xlit":"exolothreúō"},"G121":{"translit":"áthōos","lemma":"ἄθωος","kjv_def":"innocent","strongs_def":" not guilty","derivation":"from G1 (Α) (as a negative particle) and probably a derivative of G5087 (τίθημι) (meaning a penalty);","pron":"ath'-o-os","pos":"Adjective","thayer":"<ol><li>not guilty, innocent, unpunished</li></ol>","xlit":"áthōos"},"G2926":{"strongs_def":" a hidden place, i.e. cellar (\"crypt\")","derivation":"feminine of G2927 (κρυπτός);","lemma":"κρύπτη","translit":"krýptē","kjv_def":"secret","pron":"kroop-tay'","pos":"Noun Feminine","thayer":"<ol><li>crypt, a covered way, vault, cellar</li></ol>","xlit":"krýptē"},"G5414":{"strongs_def":" something carried, i.e. the cargo of a ship","derivation":"from G5342 (φέρω);","translit":"phórtos","lemma":"φόρτος","kjv_def":"lading","pron":"for'-tos","pos":"Noun Masculine","thayer":"<ol><li>a load, burden<ol type='a'><li>of a ship</li></ol></li></ol>","xlit":"phórtos"},"G863":{"derivation":"from G575 (ἀπό) and (to send;","strongs_def":" an intensive form of , to go); to send forth, in various applications (as follow)","kjv_def":"cry, forgive, forsake, lay aside, leave, let (alone, be, go, have), omit, put (send) away, remit, suffer, yield up","translit":"aphíēmi","lemma":"ἀφίημι","pron":"af-ee'-ay-mee","pos":"Verb","thayer":"<ol><li>to send away<ol type='a'><li>to bid going away or depart<ol><li>of a husband divorcing his wife</li></ol><li>to send forth, yield up, to expire</li><li>to let go, let alone, let be<ol><li>to disregard</li><li>to leave, not to discuss now, (a topic)<ol type='a'><li>of teachers, writers and speakers</li></ol><li>to omit, neglect</li></ol><li>to let go, give up a debt, forgive, to remit</li><li>to give up, keep no longer</li></ol><li>to permit, allow, not to hinder, to give up a thing to a person</li><li>to leave, go way from one<ol type='a'><li>in order to go to another place</li><li>to depart from any one</li><li>to depart from one and leave him to himself so that all mutual claims are abandoned</li><li>to desert wrongfully</li><li>to go away leaving something behind</li><li>to leave one by not taking him as a companion</li><li>to leave on dying, leave behind one</li><li>to leave so that what is left may remain, leave remaining</li><li>abandon, leave destitute</li></ol></li></ol>","xlit":"aphíēmi"},"G3102":{"lemma":"μαθήτρια","translit":"mathḗtria","kjv_def":"disciple","strongs_def":" a female pupil","derivation":"feminine from G3101 (μαθητής);","pron":"math-ay'-tree-ah","pos":"Noun Feminine","thayer":"<ol><li>a female disciple</li><li>a Christian woman <a class='bible' href='#b44.9.36'>Act 9:36</a></li></ol>","xlit":"mathḗtria"},"G5316":{"derivation":"prolongation for the base of G5457 (φῶς);","strongs_def":" to lighten (shine), i.e. show (transitive or intransitive, literal or figurative)","kjv_def":" appear, seem, be seen, shine, X think","translit":"phaínō","lemma":"φαίνω","pron":"fah'-ee-no","pos":"Verb","thayer":"<ol><li>to bring forth into the light, cause to shine, shed light</li><li>shine<ol type='a'><li>to shine, be bright or resplendent</li><li>to become evident, to be brought forth into the light, come to view, appear<ol><li>of growing vegetation, to come to light</li><li>to appear, be seen</li><li>exposed to view</li></ol><li>to meet the eyes, strike the sight, become clear or manifest<ol><li>to be seen, appear</li></ol><li>to appear to the mind, seem to one's judgment or opinion</li></ol></li></ol>","xlit":"phaínō"},"G3552":{"translit":"noséō","lemma":"νοσέω","kjv_def":"dote","strongs_def":" to be sick, i.e. (by implication, of a diseased appetite) to hanker after (figuratively, to harp upon)","derivation":"from G3554 (νόσος);","pron":"nos-eh'-o","pos":"Verb","thayer":"<ol><li>to be sick</li><li>metaphorically of any ailment of the mind<ol type='a'><li>to be taken with such an interest in a thing as amounts to a disease, to have a morbid fondness for</li></ol></li></ol>","xlit":"noséō"},"G2797":{"strongs_def":" Cis (i.e. Kish), an Israelite","derivation":"of Hebrew origin (H07027);","lemma":"Κίς","translit":"Kís","kjv_def":"Cis","pron":"kis","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Kish = \"a snare\"</p><ol><li>the father of Saul, the first king of Israel</li></ol>","xlit":"Kís"},"G2538":{"derivation":"from G2537 (καινός);","strongs_def":" renewal (figuratively)","kjv_def":"newness","lemma":"καινότης","translit":"kainótēs","pron":"kahee-not'-ace","pos":"Noun Feminine","thayer":"<ol><li>newness<ol type='a'><li>in the new state of life in which the Holy Spirit places us so as to produce a new state which is eternal life</li></ol></li></ol>","xlit":"kainótēs"},"G3154":{"lemma":"ματαιόω","translit":"mataióō","kjv_def":"become vain","strongs_def":" to render (passively, become) foolish, i.e. (morally) wicked or (specially), idolatrous","derivation":"from G3152 (μάταιος);","pron":"mat-ah-yo'-o","pos":"Verb","thayer":"<ol><li>to make empty, vain, foolish</li></ol>","xlit":"mataióō"},"G184":{"strongs_def":" corresponding to H02506 and H01818); Akeldama, a place near Jerusalem","derivation":"of Chaldee origin (meaning field of blood;","translit":"Akeldamá","lemma":"Ἀκελδαμά","kjv_def":"Aceldama","pron":"ak-el-dam-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Aceldama = \"Field of Blood\"</p><ol><li>a field purchased with Judas's betrayal money, located near Jerusalem</li></ol>","xlit":"Akeldamá"},"G2681":{"translit":"kataskēnóō","lemma":"κατασκηνόω","kjv_def":"lodge, rest","strongs_def":" to camp down, i.e. haunt; figuratively, to remain","derivation":"from G2596 (κατά) and G4637 (σκηνόω);","pron":"kat-as-kay-no'-o","pos":"Verb","thayer":"<ol><li>to pitch one's tent, to fix one's abode, to dwell</li></ol>","xlit":"kataskēnóō"},"G2492":{"strongs_def":" Job (i.e. Ijob), a patriarch","derivation":"of Hebrew origin (H0347);","translit":"Iṓb","lemma":"Ἰώβ","kjv_def":"Job","pron":"ee-obe'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Job = \"the cry of woe\" or \"I will exclaim\"</p><ol><li>a man known for his piety and, consistency and fortitude in the endurance of trials. His experiences are related in the OT book bearing his name.</li></ol>","xlit":"Iṓb"},"G5065":{"kjv_def":"fourteenth","lemma":"τεσσαρεσκαιδέκατος","translit":"tessareskaidékatos","derivation":"from G5064 (τέσσαρες) and G2532 (καί) and G1182 (δέκατος);","strongs_def":" fourteenth","pron":"tes-sar-es-kahee-dek'-at-os","pos":"Adjective","thayer":"<ol><li>the fourteenth</li></ol>","xlit":"tessareskaidékatos"},"G3679":{"derivation":"from G3681 (ὄνειδος);","strongs_def":" to defame, i.e. rail at, chide, taunt","kjv_def":"cast in teeth, (suffer) reproach, revile, upbraid","translit":"oneidízō","lemma":"ὀνειδίζω","pron":"on-i-did'-zo","pos":"Verb","thayer":"<ol><li>to reproach, upbraid, revile<ol type='a'><li>of deserved reproach</li><li>of undeserved reproach, to revile</li><li>to upbraid, cast (favours received) in one's teeth</li></ol></li></ol>","xlit":"oneidízō"},"G1510":{"derivation":"the first person singular present indicative; a prolonged form of a primary and defective verb;","strongs_def":" I exist (used only when emphatic)","kjv_def":"am, have been, X it is I, was","translit":"eimí","lemma":"εἰμί","pron":"i-mee'","pos":"Verb","thayer":"<ol><li>to be, to exist, to happen, to be present</li></ol>","xlit":"eimí"},"G3363":{"derivation":"i.e. G2443 (ἵνα) and G3361 (μή);","strongs_def":" in order (or so) that not","kjv_def":"albeit not, lest, that, no(-t, (-thing))","lemma":"ἵνα μή","translit":"hína mḗ","pron":"hin'-ah may","pos":"Conjunction","thayer":"<ol><li>lest, that ... not</li></ol>","xlit":"hína mḗ"},"G540":{"strongs_def":" fatherless, i.e. of unrecorded paternity","derivation":"from G1 (Α) (as a negative particle) and G3962 (πατήρ);","translit":"apátōr","lemma":"ἀπάτωρ","kjv_def":"without father","pron":"ap-at'-ore","pos":"Noun Masculine","thayer":"<ol><li>whose father is not recorded in the genealogies</li></ol>","xlit":"apátōr"},"G2476":{"strongs_def":" to stand (transitively or intransitively), used in various applications (literally or figuratively)","derivation":"a prolonged form of a primary (of the same meaning, and used for it in certain tenses);","lemma":"ἵστημι","translit":"hístēmi","kjv_def":"abide, appoint, bring, continue, covenant, establish, hold up, lay, present, set (up), stanch, stand (by, forth, still, up)","pron":"his'-tay-mee","pos":"Verb","thayer":"<ol><li>to cause or make to stand, to place, put, set<ol type='a'><li>to bid to stand by, [set up]<ol><li>in the presence of others, in the midst, before judges, before members of the Sanhedrin</li><li>to place</li></ol><li>to make firm, fix establish<ol><li>to cause a person or a thing to keep his or its place</li><li>to stand, be kept intact (of family, a kingdom), to escape in safety</li><li>to establish a thing, cause it to stand<ol type='a'><li>to uphold or sustain the authority or force of anything</li></ol></li></ol><li>to set or place in a balance<ol><li>to weigh: money to one (because in very early times before the introduction of coinage, the metals used to be weighed)</li></ol></li></ol><li>to stand<ol type='a'><li>to stand by or near<ol><li>to stop, stand still, to stand immovable, stand firm<ol type='a'><li>of the foundation of a building</li></ol></li></ol><li>to stand<ol><li>continue safe and sound, stand unharmed, to stand ready or prepared</li><li>to be of a steadfast mind</li><li>of quality, one who does not hesitate, does not waiver</li></ol></li></ol></li></ol>","xlit":"hístēmi"},"G5238":{"derivation":"from G5228 (ὑπέρ) and the neuter plural of G1565 (ἐκεῖνος);","strongs_def":" above those parts, i.e. still farther","kjv_def":"beyond","lemma":"ὑπερέκεινα","translit":"hyperékeina","pron":"hoop-er-ek'-i-nah","pos":"Adverb","thayer":"<ol><li>beyond: the regions lying beyond the country of one's residence</li></ol>","xlit":"hyperékeina"},"G5609":{"derivation":"apparently a primary word;","strongs_def":" an \"egg\"","kjv_def":"egg","lemma":"ὠόν","translit":"ōón","pron":"o-on'","pos":"Noun Neuter","thayer":"<ol><li>an egg</li></ol>","xlit":"ōón"},"G4540":{"lemma":"Σαμάρεια","translit":"Samáreia","kjv_def":"Samaria","strongs_def":" Samaria (i.e. Shomeron), a city and region of Palestine","derivation":"of Hebrew origin (H08111);","pron":"sam-ar'-i-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Samaria = \"guardianship\"</p><ol><li>a territory in Palestine, which had Samaria as its capital</li></ol>","xlit":"Samáreia"},"G563":{"derivation":"adverb from a compound of G1 (Α) (as a negative participle) and a presumed derivative of G4049 (περισπάω);","strongs_def":" undistractedly, i.e. free from (domestic) solicitude","kjv_def":"without distraction","lemma":"ἀπερισπάστως","translit":"aperispástōs","pron":"ap-er-is-pas-toce'","pos":"Adverb","thayer":"<ol><li>without distraction, without solicitude or anxiety or care</li></ol>","xlit":"aperispástōs"},"G5162":{"strongs_def":" a nourisher, i.e. nurse","derivation":"from G5142 (τρέφω);","translit":"trophós","lemma":"τροφός","kjv_def":"nurse","pron":"trof-os'","pos":"Noun Feminine","thayer":"<ol><li>a nurse</li></ol>","xlit":"trophós"},"G1459":{"derivation":"from G1722 (ἐν) and G2641 (καταλείπω);","strongs_def":" to leave behind in some place, i.e. (in a good sense) let remain over, or (in a bad sense) to desert","kjv_def":"forsake, leave","lemma":"ἐγκαταλείπω","translit":"enkataleípō","pron":"eng-kat-al-i'-po","pos":"Verb","thayer":"<ol><li>abandon, desert<ol type='a'><li>leave in straits, leave helpless</li><li>totally abandoned, utterly forsaken</li></ol><li>to leave behind among, to leave surviving</li></ol>","xlit":"enkataleípō"},"G1496":{"kjv_def":"idolater","translit":"eidōlolátrēs","lemma":"εἰδωλολάτρης","derivation":"from G1497 (εἴδωλον) and the base of G3000 (λατρεύω);","strongs_def":" an image- (servant or) worshipper (literally or figuratively)","pron":"i-do-lol-at'-race","pos":"Noun Masculine","thayer":"<ol><li>a worshipper of false gods, a idolater<ol type='a'><li>used of any one even Christian, participant in any way in the worship of the heathen, especially one who attends their sacrificial feasts and eats of the remains of offered victims</li></ol><li>a covetous man as a worshipper of Mammon</li></ol>","xlit":"eidōlolátrēs"},"G3440":{"strongs_def":" merely","derivation":"neuter of G3441 (μόνος) as adverb;","translit":"mónon","lemma":"μόνον","kjv_def":"alone, but, only","pron":"mon'-on","pos":"Adverb Neuter","thayer":"<ol><li>only, alone, but</li></ol>","xlit":"mónon"},"G2785":{"kjv_def":"whale","translit":"kētos","lemma":"κῆτος","derivation":"probably from the base of G5490 (χάσμα);","strongs_def":" a huge fish (as gaping for prey)","pron":"kay'-tos","pos":"Noun Neuter","thayer":"<ol><li>a sea monster, whale, huge fish</li></ol>","xlit":"kētos"},"G1697":{"derivation":"of Hebrew origin (H02544);","strongs_def":" Emmor (i.e. Chamor), a Canaanite","kjv_def":"Emmor","translit":"Emmór","lemma":"Ἐμμόρ","pron":"em-mor'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Emmor = \"an ass\"</p><ol><li>the father of Sychem, <a class='bible' href='#b44.7.16'>Act 7:16</a></li></ol>","xlit":"Emmór"},"G4468":{"kjv_def":"mischief","translit":"rhaidiourgía","lemma":"ῥᾳδιουργία","derivation":"from the same as G4467 (ῥᾳδιούργημα);","strongs_def":" recklessness, i.e. (by extension) malignity","pron":"hrad-ee-oorg-ee'-a","pos":"Noun Feminine","thayer":"<ol><li>ease in doing, faculty</li><li>levity or easiness in thinking or acting<ol type='a'><li>love of a lazy effeminate life</li></ol><li>unscrupulous, cunning, mischief</li></ol>","xlit":"rhaidiourgía"},"G1293":{"lemma":"διαστολή","translit":"diastolḗ","kjv_def":"difference, distinction","strongs_def":" a variation","derivation":"from G1291 (διαστέλλομαι);","pron":"dee-as-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a distinction, difference<ol type='a'><li>of the different sounds musical instruments make</li></ol></li></ol>","xlit":"diastolḗ"},"G4347":{"derivation":"from G4314 (πρός) and G2853 (κολλάω);","strongs_def":" to glue to, i.e. (figuratively) to adhere","kjv_def":"cleave, join (self)","lemma":"προσκολλάω","translit":"proskolláō","pron":"pros-kol-lah'-o","pos":"Verb","thayer":"<ol><li>to glue upon, glue to</li><li>to join one's self to closely, cleave to, stick to</li></ol>","xlit":"proskolláō"},"G1355":{"strongs_def":" on which very account","derivation":"from G1352 (διό) and G4007 (περ);","translit":"dióper","lemma":"διόπερ","kjv_def":"wherefore","pron":"dee-op'-er","pos":"Conjunction","thayer":"<ol><li>on which very account</li></ol>","xlit":"dióper"},"G2697":{"kjv_def":"possession","lemma":"κατάσχεσις","translit":"katáschesis","derivation":"from G2722 (κατέχω);","strongs_def":" a holding down, i.e. occupancy","pron":"kat-as'-khes-is","pos":"Noun Feminine","thayer":"<ol><li>a holding back, hindering</li><li>a holding fast, possession</li></ol>","xlit":"katáschesis"},"G3997":{"derivation":"strengthened from the alternate of G3958 (πάσχω);","strongs_def":" grief","kjv_def":"mourning, sorrow","translit":"pénthos","lemma":"πένθος","pron":"pen'-thos","pos":"Noun Neuter","thayer":"<ol><li>mourning</li></ol>","xlit":"pénthos"},"G4020":{"derivation":"from G4012 (περί) and G2038 (ἐργάζομαι);","strongs_def":" to work all around, i.e. bustle about (meddle)","kjv_def":"be a busybody","translit":"periergázomai","lemma":"περιεργάζομαι","pron":"per-ee-er-gad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to bustle about uselessly, to busy one's self about trifling, needless, useless matters<ol type='a'><li>used apparently of a person officiously inquisitive about other's affairs</li></ol></li></ol>","xlit":"periergázomai"},"G1118":{"strongs_def":" a parent","derivation":"from the base of G1096 (γίνομαι);","lemma":"γονεύς","translit":"goneús","kjv_def":"parent","pron":"gon-yooce'","pos":"Noun Masculine","thayer":"<ol><li>fathers, parent, the parents</li></ol>","xlit":"goneús"},"G1044":{"strongs_def":" an ulcer (\"gangrene\")","derivation":"from (to gnaw);","lemma":"γάγγραινα","translit":"gángraina","kjv_def":"canker","pron":"gang'-grahee-nah","pos":"Noun Feminine","thayer":"<ol><li>a gangrene, a disease by which any part of the body suffering from inflammation becomes so corrupted that, unless a remedy be seasonably applied, the evil continually spreads, attacks other parts, and at last eats away the bones</li></ol>","xlit":"gángraina"},"G2895":{"derivation":"probably of foreign origin;","strongs_def":" a mattress","kjv_def":"bed","lemma":"κράββατος","translit":"krábbatos","pron":"krab'-bat-os","pos":"Noun Masculine","thayer":"<ol><li>a pallet, camp bed (a rather simple bed holding only one person)</li></ol>","xlit":"krábbatos"},"G4837":{"derivation":"from G4862 (σύν) and G3870 (παρακαλέω);","strongs_def":" to console jointly","kjv_def":"comfort together","translit":"symparakaléō","lemma":"συμπαρακαλέω","pron":"soom-par-ak-al-eh'-o","pos":"Verb","thayer":"<ol><li>to call upon or invite or exhort at the same time or together</li><li>to strengthen (comfort) with others</li></ol>","xlit":"symparakaléō"},"G949":{"lemma":"βέβαιος","translit":"bébaios","kjv_def":"firm, of force, stedfast, sure","strongs_def":" stable (literally or figuratively)","derivation":"from the base of G939 (βάσις) (through the idea of basality);","pron":"beb'-ah-yos","pos":"Adjective","thayer":"<ol><li>stable, fast, firm</li><li>metaphorically sure, trusty</li></ol>","xlit":"bébaios"},"G63":{"kjv_def":"abide in the field","lemma":"ἀγραυλέω","translit":"agrauléō","derivation":"from G68 (ἀγρός) and G832 (αὐλέω) (in the sense of G833 (αὐλή));","strongs_def":" to camp out","pron":"ag-row-leh'-o","pos":"Verb","thayer":"<ol><li>to live in the fields, be under the open sky, even at night</li></ol>","xlit":"agrauléō"},"G3924":{"derivation":"from G3844 (παρά) and G1622 (ἐκτός);","strongs_def":" near outside, i.e. besides","kjv_def":"except, saving, without","lemma":"παρεκτός","translit":"parektós","pron":"par-ek-tos'","pos":"Adverb","thayer":"<ol><li>except, with the exception of (a thing)</li><li>besides</li></ol>","xlit":"parektós"},"G3069":{"strongs_def":" Lydda (i.e. Lod), a place in Palestine","derivation":"of Hebrew origin (H03850);","translit":"Lýdda","lemma":"Λύδδα","kjv_def":"Lydda","pron":"lud'-dah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Lydda = \"strife\"</p><ol><li>a town is 9 miles (15 km) from Joppa, and is the first town on the northernmost of the two roads between that place and Jerusalem</li></ol>","xlit":"Lýdda"},"G1004":{"kjv_def":"mire","lemma":"βόρβορος","translit":"bórboros","derivation":"of uncertain derivation;","strongs_def":" mud","pron":"bor'-bor-os","pos":"Noun Masculine","thayer":"<ol><li>dung, mire</li></ol>","xlit":"bórboros"},"G68":{"lemma":"ἀγρός","translit":"agrós","kjv_def":"country, farm, piece of ground, land","strongs_def":" a field (as a drive for cattle); genitive case, the country; specially, a farm, i.e. hamlet","derivation":"from G71 (ἄγω);","pron":"ag-ros'","pos":"Noun Masculine","thayer":"<ol><li>land<ol type='a'><li>the field, the country</li><li>a piece of land, bit of tillage</li><li>the farms, country seats, neighbouring hamlets</li></ol></li></ol>","xlit":"agrós"},"G4326":{"strongs_def":" to require additionally, i.e. want further","derivation":"from G4314 (πρός) and G1189 (δέομαι);","translit":"prosdéomai","lemma":"προσδέομαι","kjv_def":"need","pron":"pros-deh'-om-ahee","pos":"Verb","thayer":"<ol><li>to want besides, need in addition</li></ol>","xlit":"prosdéomai"},"G2499":{"kjv_def":"Jose","lemma":"Ἰωσή","translit":"Iōsḗ","derivation":"genitive case of G2500 (Ἰωσῆς);","strongs_def":" Jose, an Israelite","pron":"ee-o-say'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jose = \"he will be sustained of Jehovah\"</p><ol><li>the son of Eliezer, in the genealogy of Jesus Christ</li></ol>","xlit":"Iōsḗ"},"G1980":{"strongs_def":" to inspect, i.e. (by implication) to select; by extension, to go to see, relieve","derivation":"middle voice from G1909 (ἐπί) and the base of G4649 (σκοπός);","translit":"episképtomai","lemma":"ἐπισκέπτομαι","kjv_def":"look out, visit","pron":"ep-ee-skep'-tom-ahee","pos":"Verb","thayer":"<ol><li>to look upon or after, to inspect, examine with the eyes<ol type='a'><li>in order to see how he is, i.e. to visit, go to see one<ol><li>the poor and afflicted, the sick</li></ol><li>to look upon in order to help or to benefit<ol><li>to look after, have care for, provide for: of God</li></ol><li>to look (about) for, look out (one to choose, employ, etc.)</li></ol></li></ol>","xlit":"episképtomai"},"G5374":{"lemma":"Φιλιππήσιος","translit":"Philippḗsios","kjv_def":"Philippian","strongs_def":" a Philippesian (Philippian), i.e. native of Philippi","derivation":"from G5375 (Φίλιπποι);","pron":"fil-ip-pay'-see-os","pos":"Noun Masculine","thayer":"<ol><li>a resident of the town of Philippi</li></ol>","xlit":"Philippḗsios"},"G5075":{"kjv_def":"(be) tetrarch","translit":"tetrarchéō","lemma":"τετραρχέω","derivation":"from G5076 (τετράρχης);","strongs_def":" to be a tetrarch","pron":"tet-rar-kheh'-o","pos":"Verb","thayer":"<ol><li>to be a governor of a tetrarchy, be tetrarch of a region</li></ol>","xlit":"tetrarchéō"},"G5081":{"kjv_def":"clearly","translit":"tēlaugōs","lemma":"τηλαυγῶς","derivation":"adverb from a compound of a derivative of G5056 (τέλος) and G827 (αὐγή);","strongs_def":" in a far-shining manner, i.e. plainly","pron":"tay-low-goce'","pos":"Adverb","thayer":"<ol><li>at a distance and clearly</li></ol>","xlit":"tēlaugōs"},"G4329":{"derivation":"from G4328 (προσδοκάω);","strongs_def":" apprehension (of evil); by implication, infliction anticipated","kjv_def":"expectation, looking after","lemma":"προσδοκία","translit":"prosdokía","pron":"pros-dok-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>expectation (whether good or evil)</li></ol>","xlit":"prosdokía"},"G3752":{"lemma":"ὅταν","translit":"hótan","kjv_def":"as long (soon) as, that, + till, when(-soever), while","strongs_def":" whenever (implying hypothesis or more or less uncertainty); also causatively (conjunctionally) inasmuch as","derivation":"from G3753 (ὅτε) and G302 (ἄν);","pron":"hot'-an","thayer":"<ol><li>when, whenever, as long as, as soon as</li></ol>","xlit":"hótan"},"G4811":{"translit":"sykophantéō","lemma":"συκοφαντέω","kjv_def":"accuse falsely, take by false accusation","strongs_def":" to be a fig-informer (reporter of the law forbidding the exportation of figs from Greece), \"sycophant\", i.e. (genitive and by extension) to defraud (exact unlawfully, extort)","derivation":"from a compound of G4810 (σῦκον) and a derivative of G5316 (φαίνω);","pron":"soo-kof-an-teh'-o","pos":"Verb","thayer":"<ol><li>to accuse wrongfully, to calumniate, to attack by malicious devices</li><li>to exact money wrongfully<ol type='a'><li>to extort from, defraud</li></ol></li></ol>","xlit":"sykophantéō"},"G3311":{"translit":"merismós","lemma":"μερισμός","kjv_def":"dividing asunder, gift","strongs_def":" a separation or distribution","derivation":"from G3307 (μερίζω);","pron":"mer-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a division, partition<ol type='a'><li>distribution (of various kinds)</li></ol><li>a separation<ol type='a'><li>so far as to cleave asunder or separate</li></ol></li></ol>","xlit":"merismós"},"G3414":{"derivation":"of Latin origin;","strongs_def":" a mna (i.e. mina), a certain weight","kjv_def":" pound","translit":"mnâ","lemma":"μνᾶ","pron":"mnah","pos":"Noun Feminine","thayer":"<ol><li>in the OT, a weight of 300 shekels was one pound</li><li>In the NT, a weight and sum of money equal to 100 drachmae, one talent was 100 pounds, a pound equalled 10 1/3 oz. (300 gm)</li></ol>","xlit":"mnâ"},"G663":{"strongs_def":" (figuratively) decisiveness, i.e. rigor","derivation":"from the base of G664 (ἀποτόμως);","lemma":"ἀποτομία","translit":"apotomía","kjv_def":"severity","pron":"ap-ot-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>severity, roughness, rigour</li></ol>","xlit":"apotomía"},"G4331":{"kjv_def":"come nigh","translit":"prosengízō","lemma":"προσεγγίζω","derivation":"from G4314 (πρός) and G1448 (ἐγγίζω);","strongs_def":" to approach near","pron":"pros-eng-ghid'-zo","pos":"Verb","thayer":"<ol><li>to approach unto</li></ol>","xlit":"prosengízō"},"G4967":{"kjv_def":"slaughter","lemma":"σφαγή","translit":"sphagḗ","derivation":"from G4969 (σφάζω);","strongs_def":" butchery (of animals for food or sacrifice, or (figuratively) of men (destruction))","pron":"sfag-ay'","pos":"Noun Feminine","thayer":"<ol><li>slaughter<ol type='a'><li>of sheep destined for slaughter</li><li>of day of destruction</li></ol></li></ol>","xlit":"sphagḗ"},"G1413":{"kjv_def":"of great authority, mighty, potentate","translit":"dynástēs","lemma":"δυνάστης","derivation":"from G1410 (δύναμαι);","strongs_def":" a ruler or officer","pron":"doo-nas'-tace","pos":"Noun Masculine","thayer":"<ol><li>a prince, a potentate</li><li>a courtier, high officer, royal minister of great authority</li></ol>","xlit":"dynástēs"},"G2615":{"kjv_def":"bring into bondage","translit":"katadoulóō","lemma":"καταδουλόω","derivation":"from G2596 (κατά) and G1402 (δουλόω);","strongs_def":" to enslave utterly","pron":"kat-ad-oo-lo'-o","pos":"Verb","thayer":"<ol><li>to bring into bondage, enslave</li><li>to enslave to one's self, bring into bondage to one's self</li></ol>","xlit":"katadoulóō"},"G3672":{"kjv_def":"without controversy","lemma":"ὁμολογουμένως","translit":"homologouménōs","derivation":"adverb of present passive participle of G3670 (ὁμολογέω);","strongs_def":" confessedly","pron":"hom-ol-og-ow-men'-oce","pos":"Adverb","thayer":"<ol><li>by consent of all, confessedly, without controversy</li></ol>","xlit":"homologouménōs"},"G2271":{"kjv_def":"quietness, silence","translit":"hēsychía","lemma":"ἡσυχία","derivation":"feminine of G2272 (ἡσύχιος);","strongs_def":" (as noun) stillness, i.e. desistance from bustle or language","pron":"hay-soo-khee'-ah","pos":"Noun Feminine","thayer":"<ol><li>quietness<ol type='a'><li>description of the life of one who stays at home doing his own work, and does not officiously meddle with the affairs of others</li></ol><li>silence</li></ol>","xlit":"hēsychía"},"G1225":{"kjv_def":"accuse","lemma":"διαβάλλω","translit":"diabállō","derivation":"from G1223 (διά) and G906 (βάλλω);","strongs_def":" (figuratively) to traduce","pron":"dee-ab-al'-lo","pos":"Verb","thayer":"<ol><li>to throw over or across, to send over</li><li>to traduce, calumniate, slander, accuse, defame</li></ol>","xlit":"diabállō"},"G1051":{"translit":"gála","lemma":"γάλα","kjv_def":"milk","strongs_def":" milk (figuratively)","derivation":"of uncertain affinity;","pron":"gal'-ah","pos":"Noun Neuter","thayer":"<ol><li>milk</li><li>a metaphorically for the less difficult Christian truths</li></ol>","xlit":"gála"},"G762":{"strongs_def":" not extinguished, i.e. (by implication) perpetual","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4570 (σβέννυμι);","translit":"ásbestos","lemma":"ἄσβεστος","kjv_def":"not to be quenched, unquenchable","pron":"as'-bes-tos","pos":"Adjective","thayer":"<ol><li>unquenched, unquenchable<ol type='a'><li>of eternal hell fire to punish the damned</li></ol></li></ol>","xlit":"ásbestos"},"G4496":{"kjv_def":"cast (down, out), scatter abroad, throw","translit":"rhíptō","lemma":"ῥίπτω","derivation":"a primary verb (perhaps rather akin to the base of G4474 (ῥαπίζω), through the idea of sudden motion);","strongs_def":" to fling (properly, with a quick toss, thus differing from G906 (βάλλω), which denotes a deliberate hurl; and from (see in G1614 (ἐκτείνω)), which indicates an extended projection); by qualification, to deposit (as if a load); by extension, to disperse","pron":"hrip'-to","pos":"Verb","thayer":"<ol><li>to cast, throw</li><li>throw down</li><li>to cast forward or before</li><li>to set down (with the suggestion of haste and want of care)</li><li>to throw to the ground, prostrate</li></ol>","xlit":"rhíptō"},"G305":{"derivation":"from G303 (ἀνά) and the base of G939 (βάσις);","strongs_def":" to go up (literally or figuratively)","kjv_def":"arise, ascend (up), climb (go, grow, rise, spring) up, come (up)","translit":"anabaínō","lemma":"ἀναβαίνω","pron":"an-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>ascend<ol type='a'><li>to go up</li><li>to rise, mount, be borne up, spring up</li></ol></li></ol>","xlit":"anabaínō"},"G3421":{"derivation":"from a derivative of G3420 (μνήμη);","strongs_def":" to exercise memory, i.e. recollect; by implication, to punish; also to rehearse","kjv_def":"make mention; be mindful, remember","translit":"mnēmoneúō","lemma":"μνημονεύω","pron":"mnay-mon-yoo'-o","pos":"Verb","thayer":"<ol><li>to be mindful of, to remember, to call to mind<ol type='a'><li>to think of and feel for a person or thing</li><li>to hold in memory, keep in mind</li></ol><li>to make mention of</li></ol>","xlit":"mnēmoneúō"},"G782":{"derivation":"from G1 (Α) (as a particle of union) and a presumed form of G4685 (σπάω);","strongs_def":" to enfold in the arms, i.e. (by implication) to salute, (figuratively) to welcome","kjv_def":"embrace, greet, salute, take leave","lemma":"ἀσπάζομαι","translit":"aspázomai","pron":"as-pad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to draw to one's self<ol type='a'><li>to salute one, greet, bid welcome, wish well to</li><li>to receive joyfully, welcome</li></ol></li></ol>","xlit":"aspázomai"},"G4461":{"kjv_def":"Master, Rabbi","translit":"rhabbí","lemma":"ῥαββί","derivation":"of Hebrew origin (H07227 with pronominal suffix);","strongs_def":" my master, i.e Rabbi, as an official title of honor","pron":"hrab-bee'","pos":"Noun Masculine","thayer":"<ol><li>my great one, my honourable sir</li><li>Rabbi, a title used by the Jews to address their teachers (and also honour them when not addressing them)</li></ol>","xlit":"rhabbí"},"G4141":{"derivation":"apparently another form of G4111 (πλάσσω) (through the idea of flattening out);","strongs_def":" to pound, i.e. (figuratively) to inflict with (calamity)","kjv_def":"smite","translit":"plḗssō","lemma":"πλήσσω","pron":"place'-so","pos":"Verb","thayer":"<ol><li>to strike, smite</li></ol>","xlit":"plḗssō"},"G4544":{"translit":"Sámos","lemma":"Σάμος","kjv_def":"Samos","strongs_def":" Samus, an island of the Mediterranean","derivation":"of uncertain affinity;","pron":"sam'-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Samos = \"a sandy bluff\"</p><ol><li>an island off that part of Asia Minor where Ionia touches Caria</li></ol>","xlit":"Sámos"},"G1439":{"translit":"eáō","lemma":"ἐάω","kjv_def":"commit, leave, let (alone), suffer","strongs_def":" to let be, i.e. permit or leave alone","derivation":"of uncertain affinity;","pron":"eh-ah'-o","pos":"Verb","thayer":"<ol><li>to allow, permit, let</li><li>to allow one to do as he wishes, not to restrain, to let alone</li><li>to give up, let go, leave</li></ol>","xlit":"eáō"},"G4547":{"lemma":"σανδάλιον","translit":"sandálion","kjv_def":"sandal","strongs_def":" of uncertain origin); a slipper or sole-pad","derivation":"neuter of a derivative of (a \"sandal\";","pron":"san-dal'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a sandal, a sole made of wood or leather, covering the bottom of the foot and bound on with thongs</li></ol>","xlit":"sandálion"},"G4088":{"kjv_def":"bitterness","lemma":"πικρία","translit":"pikría","derivation":"from G4089 (πικρός);","strongs_def":" acridity (especially poison), literally or figuratively","pron":"pik-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>bitter gall<ol type='a'><li>extreme wickedness</li><li>a bitter root, and so producing a bitter fruit</li><li>metaphorically bitterness, bitter hatred</li></ol></li></ol>","xlit":"pikría"},"G1019":{"kjv_def":"be slack, tarry","translit":"bradýnō","lemma":"βραδύνω","derivation":"from G1021 (βραδύς);","strongs_def":" to delay","pron":"brad-oo'-no","pos":"Verb","thayer":"<ol><li>to delay, be slow<ol type='a'><li>to render slowly, retard</li><li>to be long, to tarry, loiter</li></ol></li></ol>","xlit":"bradýnō"},"G5014":{"kjv_def":"humiliation, be made low, low estate, vile","translit":"tapeínōsis","lemma":"ταπείνωσις","derivation":"from G5013 (ταπεινόω);","strongs_def":" depression (in rank or feeling)","pron":"tap-i'-no-sis","pos":"Noun Feminine","thayer":"<ol><li>lowness, low estate</li><li>metaphorically<ol type='a'><li>spiritual abasement, leading one to perceive and lament his (moral) littleness and guilt</li></ol></li></ol>","xlit":"tapeínōsis"},"G1369":{"strongs_def":" to make apart, i.e. sunder (figuratively, alienate)","derivation":"from a derivative of G1364 (δίς);","lemma":"διχάζω","translit":"dicházō","kjv_def":"set at variance","pron":"dee-khad'-zo","pos":"Verb","thayer":"<ol><li>to cut into two parts, cleave asunder, sever</li></ol>","xlit":"dicházō"},"G1341":{"kjv_def":"righteous judgment","lemma":"δικαιοκρισία","translit":"dikaiokrisía","derivation":"from G1342 (δίκαιος) and G2920 (κρίσις);","strongs_def":" a just sentence","pron":"dik-ah-yok-ris-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>righteous judgment</li></ol>","xlit":"dikaiokrisía"},"G162":{"derivation":"from G164 (αἰχμάλωτος);","strongs_def":" to capture (like G163 (αἰχμαλωτίζω))","kjv_def":"lead captive","translit":"aichmalōteúō","lemma":"αἰχμαλωτεύω","pron":"aheekh-mal-o-tew'-o","pos":"Verb","thayer":"<ol><li>to make captive, take captive, capture</li></ol>","xlit":"aichmalōteúō"},"G2595":{"derivation":"from (to wither);","strongs_def":" a dry twig or straw","kjv_def":"mote","lemma":"κάρφος","translit":"kárphos","pron":"kar'-fos","pos":"Noun Neuter","thayer":"<ol><li>a dry stalk or twig, a straw</li><li>chaff</li></ol>","xlit":"kárphos"},"G1209":{"kjv_def":"accept, receive, take","translit":"déchomai","lemma":"δέχομαι","derivation":"middle voice of a primary verb;","strongs_def":" to receive (in various applications, literally or figuratively)","pron":"dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to take with the hand<ol type='a'><li>to take hold of, take up</li></ol><li>to take up, receive<ol type='a'><li>used of a place receiving one</li><li>to receive or grant access to, a visitor, not to refuse intercourse or friendship<ol><li>to receive hospitality</li><li>to receive into one's family to bring up or educate</li></ol><li>of the thing offered in speaking, teaching, instructing<ol><li>to receive favourably, give ear to, embrace, make one's own, approve, not to reject</li></ol><li>to receive. i.e. to take upon one's self, sustain, bear, endure</li></ol><li>to receive, get<ol type='a'><li>to learn</li></ol></li></ol>","xlit":"déchomai"},"G3893":{"derivation":"from G3844 (παρά) and G4087 (πικραίνω);","strongs_def":" to embitter alongside, i.e. (figuratively) to exasperate","kjv_def":"provoke","translit":"parapikraínō","lemma":"παραπικραίνω","pron":"par-ap-ik-rah'-ee-no","pos":"Verb","thayer":"<ol><li>to provoke, exasperate</li><li>to rouse to indignation</li></ol>","xlit":"parapikraínō"},"G718":{"strongs_def":" to joint, i.e. (figuratively) to woo (reflexively, to betroth)","derivation":"from G719 (ἁρμός);","lemma":"ἁρμόζω","translit":"harmózō","kjv_def":"espouse","pron":"har-mod'-zo","pos":"Verb","thayer":"<ol><li>to join, to fit together<ol type='a'><li>of carpenter's, fastening together beams and planks to build houses, ships, etc.</li></ol><li>to betroth a daughter to any one<ol type='a'><li>to join to one's self, i.e. to marry the daughter of any one</li><li>to betroth, to give one in marriage to any one</li></ol></li></ol>","xlit":"harmózō"},"G5402":{"strongs_def":" probably akin to the base of G5457 (φῶς)); Phœbe, a Christian woman","derivation":"feminine of (bright;","lemma":"Φοίβη","translit":"Phoíbē","kjv_def":"Phebe","pron":"foy'-bay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Phoebe = \"radiant\"</p><ol><li>a deaconess of the church at Cenchrea, near Corinth</li></ol>","xlit":"Phoíbē"},"G4558":{"translit":"Sárepta","lemma":"Σάρεπτα","kjv_def":"Sarepta","strongs_def":" Sarepta (i.e. Tsarephath), a place in Palestine","derivation":"of Hebrew origin (H06886);","pron":"sar'-ep-tah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sarepta = \"smelting\"</p><ol><li>the Greek name for Zarephath, a Phoenician town between Tyre and Sidon, but nearer Sidon</li></ol>","xlit":"Sárepta"},"G3940":{"strongs_def":" foreign residence","derivation":"from G3941 (πάροικος);","lemma":"παροικία","translit":"paroikía","kjv_def":"sojourning, X as strangers","pron":"par-oy-kee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a dwelling near or with one</li><li>a sojourning, dwelling in a strange land</li><li>metaphorically the life of a man here on earth is likened to a sojourning</li></ol>","xlit":"paroikía"},"G4244":{"lemma":"πρεσβυτέριον","translit":"presbytérion","kjv_def":"(estate of) elder(-s), presbytery","strongs_def":" the order of elders, i.e. (specially), Israelite Sanhedrin or Christian \"presbytery\"","derivation":"neuter of a presumed derivative of G4245 (πρεσβύτερος);","pron":"pres-boo-ter'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>body of elders, presbytery, senate, council<ol type='a'><li>of the Jewish elders</li><li>of the elders of any body (assembly) of Christians</li></ol></li></ol>","xlit":"presbytérion"},"G3768":{"kjv_def":"hitherto not, (no…) as yet, not yet","lemma":"οὔπω","translit":"oúpō","derivation":"from G3756 (οὐ) and G4452 (-πω);","strongs_def":" not yet","pron":"oo'-po","pos":"Adverb","thayer":"<ol><li>not yet</li></ol>","xlit":"oúpō"},"G2833":{"translit":"knḗthō","lemma":"κνήθω","kjv_def":"X itching","strongs_def":" to scratch, i.e. (by implication) to tickle","derivation":"from a primary (to scrape);","pron":"knay'-tho","pos":"Verb","thayer":"<ol><li>to scratch, tickle, make to itch</li><li>to itch</li><li>desirous of hearing something pleasant</li></ol>","xlit":"knḗthō"},"G1869":{"kjv_def":"exalt self, poise (lift, take) up","lemma":"ἐπαίρω","translit":"epaírō","derivation":"from G1909 (ἐπί) and G142 (αἴρω);","strongs_def":" to raise up (literally or figuratively)","pron":"ep-ahee'-ro","pos":"Verb","thayer":"<ol><li>to lift up, raise up, raise on high</li><li>metaphorically to be lifted up with pride, to exalt one's self</li></ol>","xlit":"epaírō"},"G2194":{"lemma":"Ζαβουλών","translit":"Zaboulṓn","kjv_def":"Zabulon","strongs_def":" Zabulon (i.e. Zebulon), a region of Palestine","derivation":"of Hebrew origin (H02074);","pron":"dzab-oo-lone'","pos":"Noun Masculine","thayer":"<ol><li>the tenth of the sons of Jacob</li><li>the tribe of Zebulun</li></ol>","xlit":"Zaboulṓn"},"G206":{"lemma":"ἄκρον","translit":"ákron","kjv_def":"one end… other, tip, top, uttermost participle ","strongs_def":" the extremity","derivation":"neuter of an adjective probably akin to the base of G188 (ἀκμήν);","pron":"ak'-ron","pos":"Adjective","thayer":"<ol><li>the farthest bounds, uttermost parts, end, highest, extreme<ol type='a'><li>of the earth</li><li>of heaven</li></ol></li></ol>","xlit":"ákron"},"G4520":{"strongs_def":" a \"sabbatism\", i.e. (figuratively) the repose of Christianity (as a type of heaven)","derivation":"from a derivative of G4521 (σάββατον);","lemma":"σαββατισμός","translit":"sabbatismós","kjv_def":"rest","pron":"sab-bat-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a keeping sabbath</li><li>the blessed rest from toils and troubles looked for in the age to come by the true worshippers of God and true Christians</li></ol>","xlit":"sabbatismós"},"G4207":{"kjv_def":"afar off","translit":"pórrhōthen","lemma":"πόῤῥωθεν","derivation":"from G4206 (πόῤῥω) with adverbial enclitic of source;","strongs_def":" from far, or (by implication) at a distance, i.e. distantly","pron":"por'-rho-then","pos":"Adverb","thayer":"<ol><li>from afar, afar off</li></ol>","xlit":"pórrhōthen"},"G5096":{"derivation":"from G5092 (τιμή);","strongs_def":" valuable; Timon, a Christian","kjv_def":"Timon","lemma":"Τίμων","translit":"Tímōn","pron":"tee'-mone","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Timon = \"honourable\"</p><ol><li>one of the seven deacons of the church at Jerusalem</li></ol>","xlit":"Tímōn"},"G3092":{"strongs_def":" Maath, an Israelite","derivation":"probably of Hebrew origin;","lemma":"Μαάθ","translit":"Maáth","kjv_def":"Maath","pron":"mah-ath'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Maath = \"small\"</p><ol><li>the son of Mattathias in the genealogy of Jesus Christ</li></ol>","xlit":"Maáth"},"G5256":{"lemma":"ὑπηρετέω","translit":"hypēretéō","kjv_def":"minister (unto), serve","strongs_def":" to be a subordinate, i.e. (by implication) subserve","derivation":"from G5257 (ὑπηρέτης);","pron":"hoop-ay-ret-eh'-o","pos":"Verb","thayer":"<ol><li>to act as a rower, to row</li><li>to minister, render services</li></ol>","xlit":"hypēretéō"},"G2074":{"kjv_def":"Esrom","translit":"Esrṓm","lemma":"Ἐσρώμ","derivation":"of Hebrew origin (H02696);","strongs_def":" Esrom (i.e. Chetsron), an Israelite","pron":"es-rome","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Esrom or Hezron or Hesron = \"enclosed\"</p><ol><li>the son of Reuben, and ancestor of the Hezronites</li></ol>","xlit":"Esrṓm"},"G4409":{"strongs_def":" to be first (in rank or influence)","derivation":"from G4413 (πρῶτος);","lemma":"πρωτεύω","translit":"prōteúō","kjv_def":"have the preeminence","pron":"prote-yoo'-o","pos":"Verb","thayer":"<ol><li>to be first, hold the first place</li></ol>","xlit":"prōteúō"},"G1035":{"strongs_def":" (abstractly) eating (literally or figuratively); by extension (concretely) food (literally or figuratively)","derivation":"from the base of G977 (βιβρώσκω);","translit":"brōsis","lemma":"βρῶσις","kjv_def":"eating, food, meat","pron":"bro'-sis","pos":"Noun Feminine","thayer":"<ol><li>act of eating<ol type='a'><li>in a wider sense, corrosion</li></ol><li>that which is eaten, food, ailment<ol type='a'><li>of the soul's food, either which refreshes the soul, or nourishes and supports it</li></ol></li></ol>","xlit":"brōsis"},"G771":{"strongs_def":" a scruple of conscience","derivation":"from G770 (ἀσθενέω);","lemma":"ἀσθένημα","translit":"asthénēma","kjv_def":"infirmity","pron":"as-then'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>infirmity<ol type='a'><li>of error arising from weakness of mind</li></ol></li></ol>","xlit":"asthénēma"},"G1600":{"derivation":"from G1537 (ἐκ) and a form of G4072 (πέτομαι);","strongs_def":" to fly out, i.e. (by analogy) to extend","kjv_def":"stretch forth","translit":"ekpetánnymi","lemma":"ἐκπετάννυμι","pron":"ek-pet-an'-noo-mee","pos":"Verb","thayer":"<ol><li>to spread out, stretch forth</li></ol>","xlit":"ekpetánnymi"},"G1733":{"kjv_def":"eleven","translit":"héndeka","lemma":"ἕνδεκα","derivation":"from (the neuter of) G1520 (εἷς) and G1176 (δέκα);","strongs_def":" one and ten, i.e. eleven","pron":"hen'-dek-ah","pos":"Noun","thayer":"<ol><li>eleven<ol type='a'><li>of the eleven disciples alive after the death of Judas</li></ol></li></ol>","xlit":"héndeka"},"G1454":{"translit":"égersis","lemma":"ἔγερσις","kjv_def":"resurrection","strongs_def":" a resurgence (from death)","derivation":"from G1453 (ἐγείρω);","pron":"eg'-er-sis","pos":"Noun Feminine","thayer":"<ol><li>a rousing, excitation</li><li>a rising up</li><li>resurrection from the dead</li></ol>","xlit":"égersis"},"G1345":{"translit":"dikaíōma","lemma":"δικαίωμα","kjv_def":"judgment, justification, ordinance, righteousness","strongs_def":" an equitable deed; by implication, a statute or decision","derivation":"from G1344 (δικαιόω);","pron":"dik-ah'-yo-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been deemed right so as to have force of law<ol type='a'><li>what has been established, and ordained by law, an ordinance</li><li>a judicial decision, sentence<ol><li>of God<ol type='a'><li>either the favourable judgment by which he acquits man and declares them acceptable to Him</li><li>unfavourable: sentence of condemnation</li></ol></li></ol></li></ol><li>a righteous act or deed</li></ol>","xlit":"dikaíōma"},"G2016":{"translit":"epiphanḗs","lemma":"ἐπιφανής","kjv_def":"notable","strongs_def":" conspicuous, i.e. (figuratively) memorable","derivation":"from G2014 (ἐπιφαίνω);","pron":"ep-if-an-ace'","pos":"Adjective","thayer":"<ol><li>conspicuous, manifest, illustrious</li></ol>","xlit":"epiphanḗs"},"G987":{"kjv_def":"(speak) blaspheme(-er, -mously, -my), defame, rail on, revile, speak evil","translit":"blasphēméō","lemma":"βλασφημέω","derivation":"from G989 (βλάσφημος);","strongs_def":" to vilify; specially, to speak impiously","pron":"blas-fay-meh'-o","pos":"Verb","thayer":"<ol><li>to speak reproachfully, rail at, revile, calumniate, blaspheme</li><li>to be evil spoken of, reviled, railed at</li></ol>","xlit":"blasphēméō"},"G5547":{"derivation":"from G5548 (χρίω);","strongs_def":" anointed, i.e. the Messiah, an epithet of Jesus","kjv_def":"Christ","translit":"Christós","lemma":"Χριστός","pron":"khris-tos'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Christ = \"anointed\"</p><ol><li>Christ was the Messiah, the Son of God</li><li>anointed</li></ol>","xlit":"Christós"},"G1753":{"kjv_def":"operation, strong, (effectual) working","lemma":"ἐνέργεια","translit":"enérgeia","derivation":"from G1756 (ἐνεργής);","strongs_def":" efficiency (\"energy\")","pron":"en-erg'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>working, efficiency<ol type='a'><li>in the NT used only of superhuman power, whether of God or of the Devil</li></ol></li></ol>","xlit":"enérgeia"},"G2521":{"derivation":"from G2596 (κατά);","strongs_def":" and (to sit; akin to the base of G1476 (ἑδραῖος)); to sit down; figuratively, to remain, reside","kjv_def":"dwell, sit (by, down)","lemma":"κάθημαι","translit":"káthēmai","pron":"kath'-ay-mahee","pos":"Verb","thayer":"<ol><li>to sit down, seat one's self</li><li>to sit, be seated, of a place occupied<ol type='a'><li>to have a fixed abode, to dwell</li></ol></li></ol>","xlit":"káthēmai"},"G1301":{"derivation":"from G1223 (διά) and G5083 (τηρέω);","strongs_def":" to watch thoroughly, i.e. (positively and transitively) to observe strictly, or (negatively and reflexively) to avoid wholly","kjv_def":"keep","translit":"diatēréō","lemma":"διατηρέω","pron":"dee-at-ay-reh'-o","pos":"Verb","thayer":"<ol><li>to keep continually or carefully</li></ol>","xlit":"diatēréō"},"G859":{"kjv_def":"deliverance, forgiveness, liberty, remission","translit":"áphesis","lemma":"ἄφεσις","derivation":"from G863 (ἀφίημι);","strongs_def":" freedom; (figuratively) pardon","pron":"af'-es-is","pos":"Noun Feminine","thayer":"<ol><li>release from bondage or imprisonment</li><li>forgiveness or pardon, of sins (letting them go as if they had never been committed), remission of the penalty</li></ol>","xlit":"áphesis"},"G1146":{"strongs_def":" a finger-ring","derivation":"from G1147 (δάκτυλος);","translit":"daktýlios","lemma":"δακτύλιος","kjv_def":"ring","pron":"dak-too'-lee-os","pos":"Noun Masculine","thayer":"<ol><li>a ring (on the finger)</li></ol>","xlit":"daktýlios"},"G2042":{"derivation":"from a presumed prolonged form of G2054 (ἔρις);","strongs_def":" to stimulate (especially to anger)","kjv_def":"provoke","translit":"erethízō","lemma":"ἐρεθίζω","pron":"er-eth-id'-zo","pos":"Verb","thayer":"<ol><li>to stir up, excite, stimulate, to provoke</li></ol>","xlit":"erethízō"},"G346":{"strongs_def":" to sum up","derivation":"from G303 (ἀνά) and G2775 (κεφαλαιόω) (in its original sense);","translit":"anakephalaíomai","lemma":"ἀνακεφαλαίομαι","kjv_def":"briefly comprehend, gather together in one","pron":"an-ak-ef-al-ah'-ee-om-ahee","pos":"Verb","thayer":"<ol><li>to sum up (again), to repeat summarily, to condense into a summary</li></ol>","xlit":"anakephalaíomai"},"G2869":{"translit":"kopázō","lemma":"κοπάζω","kjv_def":"cease","strongs_def":" to tire, i.e. (figuratively) to relax","derivation":"from G2873 (κόπος);","pron":"kop-ad'-zo","pos":"Verb","thayer":"<ol><li>to grow weary or tired</li><li>to cease from violence, cease raging</li></ol>","xlit":"kopázō"},"G1217":{"translit":"dēmiourgós","lemma":"δημιουργός","kjv_def":"maker","strongs_def":" a worker for the people, i.e. mechanic (spoken of the Creator)","derivation":"from G1218 (δῆμος) and G2041 (ἔργον);","pron":"day-me-oor-gos'","pos":"Noun Masculine","thayer":"<ol><li>a workman for the public</li><li>the author of any work, an artisan, framer, builder</li></ol>","xlit":"dēmiourgós"},"G2449":{"derivation":"feminine of G2453 (Ἰουδαῖος) (with G1093 (γῆ) implied);","strongs_def":" the Judæan land (i.e. Judæa), a region of Palestine","kjv_def":"Judæa","lemma":"Ἰουδαία","translit":"Ioudaía","pron":"ee-oo-dah'-yah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Judaea = \"he shall be praised\"</p><ol><li>in a narrower sense, to the southern portion of Palestine lying on this side of the Jordan and the Dead Sea, to distinguish it from Samaria, Galilee, Peraea, and Idumaea</li><li>in a broader sense, referring to all Palestine</li></ol>","xlit":"Ioudaía"},"G625":{"derivation":"probably from the same as G624 (Ἀπολλωνία);","strongs_def":" Apollos, an Israelite","kjv_def":"Apollos","translit":"Apollōs","lemma":"Ἀπολλῶς","pron":"ap-ol-loce'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Apollos = \" given by Apollo\"</p><ol><li>a learned Jew from Alexandria and mighty in the scriptures who became a Christian and a teacher of Christianity</li></ol>","xlit":"Apollōs"},"G2693":{"strongs_def":" to strew down, i.e. (by implication) to prostrate (slay)","derivation":"from G2596 (κατά) and G4766 (στρώννυμι);","translit":"katastrṓnnymi","lemma":"καταστρώννυμι","kjv_def":"overthrow","pron":"kat-as-trone'-noo-mee","pos":"Verb","thayer":"<ol><li>to strew over (the ground)</li><li>to prostrate, slay, (compare to lay low)</li></ol>","xlit":"katastrṓnnymi"},"G2329":{"kjv_def":"heat","lemma":"θέρμη","translit":"thérmē","derivation":"from the base of G2330 (θέρος);","strongs_def":" warmth","pron":"ther'-may","pos":"Noun Feminine","thayer":"<ol><li>heat</li></ol>","xlit":"thérmē"},"G1651":{"kjv_def":"convict, convince, tell a fault, rebuke, reprove","lemma":"ἐλέγχω","translit":"elénchō","derivation":"of uncertain affinity;","strongs_def":" to confute, admonish","pron":"el-eng'-kho","pos":"Verb","thayer":"<ol><li>to convict, refute, confute<ol type='a'><li>generally with a suggestion of shame of the person convicted</li><li>by conviction to bring to the light, to expose</li></ol><li>to find fault with, correct<ol type='a'><li>by word<ol><li>to reprehend severely, chide, admonish, reprove</li><li>to call to account, show one his fault, demand an explanation</li></ol><li>by deed<ol><li>to chasten, to punish</li></ol></li></ol></li></ol>","xlit":"elénchō"},"G1390":{"derivation":"from the base of G1325 (δίδωμι);","strongs_def":" a present","kjv_def":"gift","translit":"dóma","lemma":"δόμα","pron":"dom'-ah","pos":"Noun Neuter","thayer":"<ol><li>a gift</li></ol>","xlit":"dóma"},"G2591":{"translit":"Kárpos","lemma":"Κάρπος","kjv_def":"Carpus","strongs_def":" Carpus, probably a Christian","derivation":"perhaps for G2590 (καρπός);","pron":"kar'-pos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Carpus = \"fruit\"</p><ol><li>a Christian at Troas</li></ol>","xlit":"Kárpos"},"G2044":{"kjv_def":"utter","translit":"ereúgomai","lemma":"ἐρεύγομαι","derivation":"of uncertain affinity;","strongs_def":" to belch, i.e. (figuratively) to speak out","pron":"er-yoog'-om-ahee","pos":"Verb","thayer":"<ol><li>to spit or spew out</li><li>to be emptied, discharge itself, used of streams<ol type='a'><li>to empty, discharge, cast forth, used of rivers and waters</li></ol><li>to pour forth words, to speak out, utter</li></ol>","xlit":"ereúgomai"},"G3517":{"translit":"Nēreús","lemma":"Νηρεύς","kjv_def":"Nereus","strongs_def":" Nereus, a Christian","derivation":"apparently from a derivative of the base of G3491 (ναῦς) (meaning wet);","pron":"nare-yoos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nereus = \"lump\"</p><ol><li>a Christian at Rome saluted by Paul</li></ol>","xlit":"Nēreús"},"G283":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G3392 (μιαίνω);","strongs_def":" unsoiled, i.e. (figuratively) pure","kjv_def":"undefiled","translit":"amíantos","lemma":"ἀμίαντος","pron":"am-ee'-an-tos","pos":"Adjective","thayer":"<ol><li>not defiled, unsoiled<ol type='a'><li>free from that by which the nature of a thing is deformed and debased, or its force and vigour impaired</li></ol></li></ol>","xlit":"amíantos"},"G3589":{"strongs_def":" ten times eight","derivation":"from G3590 (ὄγδοος);","translit":"ogdoḗkonta","lemma":"ὀγδοήκοντα","kjv_def":"fourscore","pron":"og-do-ay'-kon-tah","pos":"Noun","thayer":"<ol><li>eighty</li></ol>","xlit":"ogdoḗkonta"},"G3403":{"translit":"mimnḗskō","lemma":"μιμνήσκω","kjv_def":"be mindful, remember","strongs_def":" to remind, i.e. (middle voice) to recall to mind","derivation":"a prolonged form of G3415 (μνάομαι) (from which some of the tenses are borrowed);","pron":"mim-nace'-ko","pos":"Verb","thayer":"<ol><li>to remind<ol type='a'><li>to be recalled or to return to one's mind, to remind one's self of, to remember</li><li>to be recalled to mind, to be remembered, had in remembrance</li><li>to remember a thing</li><li>be mindful of</li></ol></li></ol>","xlit":"mimnḗskō"},"G1669":{"translit":"helkóō","lemma":"ἑλκόω","kjv_def":"full of sores","strongs_def":" to cause to ulcerate, i.e. (passively) be ulcerous","derivation":"from G1668 (ἕλκος);","pron":"hel-ko'-o","pos":"Verb","thayer":"<ol><li>to make sore, cause to ulcerate</li><li>to be ulcerated</li><li>full of sores</li></ol>","xlit":"helkóō"},"G1117":{"lemma":"γόμος","translit":"gómos","kjv_def":"burden, merchandise","strongs_def":" a load (as filling), i.e. (specially) a cargo, or (by extension) wares","derivation":"from G1073 (γέμω);","pron":"gom'-os","pos":"Noun Masculine","thayer":"<ol><li>a lading or freight of a ship, cargo, merchandise conveyed in a ship</li><li>any merchandise</li></ol>","xlit":"gómos"},"G1857":{"strongs_def":" exterior","derivation":"comparative of G1854 (ἔξω);","translit":"exṓteros","lemma":"ἐξώτερος","kjv_def":"outer","pron":"ex-o'-ter-os","pos":"Adjective","thayer":"<ol><li>outer</li></ol>","xlit":"exṓteros"},"G135":{"strongs_def":" an obscure saying (\"enigma\"), i.e. (abstractly) obscureness","derivation":"from a derivative of G136 (αἶνος) (in its primary sense);","lemma":"αἴνιγμα","translit":"aínigma","kjv_def":"X darkly","pron":"ah'-ee-nig-ma","pos":"Noun Neuter","thayer":"<ol><li>an obscure saying, enigma, riddle</li><li>an obscure thing</li></ol>","xlit":"aínigma"},"G2058":{"derivation":"from the same as G2059 (ἑρμηνεύω);","strongs_def":" translation","kjv_def":"interpretation","translit":"hermēneía","lemma":"ἑρμηνεία","pron":"her-may-ni'-ah","pos":"Noun Feminine","thayer":"<ol><li>interpretation<ol type='a'><li>of what has been spoken more or less obscurely by others</li></ol></li></ol>","xlit":"hermēneía"},"G1071":{"strongs_def":" laughter (as a mark of gratification)","derivation":"from G1070 (γελάω);","lemma":"γέλως","translit":"gélōs","kjv_def":"laughter","pron":"ghel'-os","pos":"Noun Masculine","thayer":"<ol><li>laughter</li></ol>","xlit":"gélōs"},"G1601":{"derivation":"from G1537 (ἐκ) and G4098 (πίπτω);","strongs_def":" to drop away; specially, be driven out of one's course; figuratively, to lose, become inefficient","kjv_def":"be cast, fail, fall (away, off), take none effect","translit":"ekpíptō","lemma":"ἐκπίπτω","pron":"ek-pip'-to","pos":"Verb","thayer":"<ol><li>to fall out of, to fall down from, to fall off</li><li>metaphorically<ol type='a'><li>to fall from a thing, to lose it</li><li>to perish, to fall<ol><li>to fall from a place from which one cannot keep</li><li>fall from a position</li><li>to fall powerless, to fall to the ground, be without effect<ol type='a'><li>of the divine promise of salvation</li></ol></li></ol></li></ol></li></ol>","xlit":"ekpíptō"},"G544":{"kjv_def":"not believe, disobedient, obey not, unbelieving","translit":"apeithéō","lemma":"ἀπειθέω","derivation":"from G545 (ἀπειθής);","strongs_def":" to disbelieve (wilfully and perversely)","pron":"ap-i-theh'-o","pos":"Verb","thayer":"<ol><li>not to allow one's self to be persuaded<ol type='a'><li>to refuse or withhold belief</li><li>to refuse belief and obedience</li></ol><li>not to comply with</li></ol>","xlit":"apeithéō"},"G564":{"kjv_def":"uncircumcised","translit":"aperítmētos","lemma":"ἀπερίτμητος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G4059 (περιτέμνω);","strongs_def":" uncircumcised (figuratively)","pron":"ap-er-eet'-may-tos","pos":"Adjective","thayer":"<ol><li>uncircumcised<ol type='a'><li>metaphorically those whose heart and ears are covered, i.e. whose soul and senses are closed to divine admonition</li></ol></li></ol>","xlit":"aperítmētos"},"G4355":{"kjv_def":"receive, take (unto)","lemma":"προσλαμβάνω","translit":"proslambánō","derivation":"from G4314 (πρός) and G2983 (λαμβάνω);","strongs_def":" to take to oneself, i.e. use (food), lead (aside), admit (to friendship or hospitality)","pron":"pros-lam-ban'-o","pos":"Verb","thayer":"<ol><li>to take to, take in addition, to take to one's self<ol type='a'><li>to take as one's companion</li><li>to take by the hand in order to lead aside</li><li>to take or receive into one's home, with the collateral idea of kindness</li><li>to receive, i.e. grant one access to one's heart<ol><li>to take into friendship and intercourse</li></ol><li>to take to one's self, to take: i.e. food</li></ol></li></ol>","xlit":"proslambánō"},"G54":{"lemma":"ἁγνότης","translit":"hagnótēs","kjv_def":"pureness","strongs_def":" cleanness (the state), i.e. (figuratively) blamelessness","derivation":"from G53 (ἁγνός);","pron":"hag-not'-ace","pos":"Noun Feminine","thayer":"<ol><li>purity, chastity, uprightness of life</li></ol>","xlit":"hagnótēs"},"G4790":{"derivation":"from G4862 (σύν) and G2841 (κοινωνέω);","strongs_def":" to share in company with, i.e. co-participate in","kjv_def":"communicate (have fellowship) with, be partaker of","lemma":"συγκοινωνέω","translit":"synkoinōnéō","pron":"soong-koy-no-neh'-o","pos":"Verb","thayer":"<ol><li>to become a partaker together with others, or to have fellowship with a thing</li></ol>","xlit":"synkoinōnéō"},"G4488":{"derivation":"probably of Hebrew origin (apparently for H07509);","strongs_def":" Resa (i.e. Rephajah), an Israelite","kjv_def":"Rhesa","lemma":"Ῥησά","translit":"Rhēsá","pron":"hray-sah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Rhesa = \"head\"</p><ol><li>the son of Zerubbabel in the genealogy of Christ</li></ol>","xlit":"Rhēsá"},"G441":{"strongs_def":" man-courting, i.e. fawning","derivation":"from G444 (ἄνθρωπος) and G700 (ἀρέσκω);","translit":"anthrōpáreskos","lemma":"ἀνθρωπάρεσκος","kjv_def":"men-pleaser","pron":"anth-ro-par'-es-kos","pos":"Adjective","thayer":"<ol><li>studying to please man, courting the favour of men</li></ol>","xlit":"anthrōpáreskos"},"G354":{"strongs_def":" ascension","derivation":"from G353 (ἀναλαμβάνω);","translit":"análēpsis","lemma":"ἀνάληψις","kjv_def":"taking up","pron":"an-al'-ape-sis","pos":"Noun Feminine","thayer":"<ol><li>a taking up</li></ol>","xlit":"análēpsis"},"G4047":{"strongs_def":" acquisition (the act or the thing); by extension, preservation","derivation":"from G4046 (περιποιέομαι);","lemma":"περιποίησις","translit":"peripoíēsis","kjv_def":"obtain(-ing), peculiar, purchased, possession, saving","pron":"per-ee-poy'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>a preserving, a preservation</li><li>possession, one's own property</li><li>an obtaining</li></ol>","xlit":"peripoíēsis"},"G3990":{"kjv_def":"behead","translit":"pelekízō","lemma":"πελεκίζω","derivation":"from a derivative of G4141 (πλήσσω) (meaning an axe);","strongs_def":" to chop off (the head), i.e. truncate","pron":"pel-ek-id'-zo","pos":"Verb","thayer":"<ol><li>to cut off with an axe, to behead</li></ol>","xlit":"pelekízō"},"G4412":{"strongs_def":" firstly (in time, place, order, or importance)","derivation":"neuter of G4413 (πρῶτος) as adverb (with or without G3588 (ὁ));","lemma":"πρῶτον","translit":"prōton","kjv_def":"before, at the beginning, chiefly (at, at the) first (of all)","pron":"pro'-ton","pos":"Adverb","thayer":"<ol><li>first in time or place<ol type='a'><li>in any succession of things or persons</li></ol><li>first in rank<ol type='a'><li>influence, honour</li><li>chief</li><li>principal</li></ol><li>first, at the first</li></ol>","xlit":"prōton"},"G2998":{"strongs_def":" to quarry","derivation":"from the same as the first part of G2991 (λαξευτός) and the base of G5114 (τομώτερος);","lemma":"λατομέω","translit":"latoméō","kjv_def":"hew","pron":"lat-om-eh'-o","pos":"Verb","thayer":"<ol><li>to cut stones, to hew out stones</li></ol>","xlit":"latoméō"},"G574":{"kjv_def":"--liberally","lemma":"ἁπλῶς","translit":"haplōs","derivation":"adverb from G573 (ἁπλοῦς) (in the objective sense of G572 (ἁπλότης));","strongs_def":" bountifully; ","pron":"hap-loce'","pos":"Adverb","thayer":"<ol><li>simply, openly, frankly, sincerely</li></ol>","xlit":"haplōs"},"G1870":{"derivation":"from G1909 (ἐπί) and G153 (αἰσχύνομαι);","strongs_def":" to feel shame for something","kjv_def":"be ashamed","lemma":"ἐπαισχύνομαι","translit":"epaischýnomai","pron":"ep-ahee-skhoo'-nom-ahee","pos":"Verb","thayer":"<ol><li>to be ashamed</li></ol>","xlit":"epaischýnomai"},"G3566":{"lemma":"νυμφίος","translit":"nymphíos","kjv_def":"bridegroom","strongs_def":" a bride-groom (literally or figuratively)","derivation":"from G3565 (νύμφη);","pron":"noom-fee'-os","pos":"Noun Masculine","thayer":"<ol><li>a bridegroom</li></ol>","xlit":"nymphíos"},"G2656":{"strongs_def":" to nod down (towards), i.e. (by analogy) to make signs to","derivation":"from G2596 (κατά) and G3506 (νεύω);","translit":"kataneúō","lemma":"κατανεύω","kjv_def":"beckon","pron":"kat-an-yoo'-o","pos":"Verb","thayer":"<ol><li>to nod to, make a sign</li><li>to indicate to another by a nod or sign what one wishes him to do</li></ol>","xlit":"kataneúō"},"G2022":{"kjv_def":"--to pour upon:--pour in","translit":"epichéō","lemma":"ἐπιχέω","derivation":"from G1909 (ἐπί) and (to pour);","strongs_def":" ","pron":"ep-ee-kheh'-o","pos":"Verb","thayer":"<ol><li>to pour upon</li></ol>","xlit":"epichéō"},"G5135":{"kjv_def":"wound","lemma":"τραυματίζω","translit":"traumatízō","derivation":"from G5134 (τραῦμα);","strongs_def":" to inflict a wound","pron":"trow-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to wound</li></ol>","xlit":"traumatízō"},"G4499":{"kjv_def":"Rhodes","translit":"Rhódos","lemma":"Ῥόδος","derivation":"probably from (a rose);","strongs_def":" Rhodus, an island of the Mediterranean","pron":"hrod'-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Rhodes = \"rosy\"</p><ol><li>a well known island of the Cyclades opposite Caria and Lycia, with a Rhodes as the capital city</li></ol>","xlit":"Rhódos"},"G3104":{"strongs_def":" Mainan, an Israelite","derivation":"probably of Hebrew origin;","translit":"Maïnán","lemma":"Μαϊνάν","kjv_def":"Mainan","pron":"mahee-nan'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Menan = \"soothsayer: enchanted\"</p><ol><li>one of the ancestors of Joseph in the genealogy of Jesus Christ</li></ol>","xlit":"Maïnán"},"G5543":{"strongs_def":" employed, i.e. (by implication) useful (in manner or morals)","derivation":"from G5530 (χράομαι);","lemma":"χρηστός","translit":"chrēstós","kjv_def":"better, easy, good(-ness), gracious, kind","pron":"khrase-tos'","pos":"Adjective","thayer":"<ol><li>fit, fit for use, useful<ol type='a'><li>virtuous, good</li></ol><li>manageable<ol type='a'><li>mild, pleasant (as opp. to harsh, hard sharp, bitter)</li><li>of things: more pleasant, of people, kind, benevolent</li></ol></li></ol>","xlit":"chrēstós"},"G258":{"kjv_def":"fox","lemma":"ἀλώπηξ","translit":"alṓpēx","derivation":"of uncertain derivation;","strongs_def":" a fox, i.e. (figuratively) a cunning person","pron":"al-o'-pakes","pos":"Noun Feminine","thayer":"<ol><li>a fox</li><li>metaphorically a sly or crafty man</li></ol>","xlit":"alṓpēx"},"G3442":{"kjv_def":"with one eye","lemma":"μονόφθαλμος","translit":"monóphthalmos","derivation":"from G3441 (μόνος) and G3788 (ὀφθαλμός);","strongs_def":" one-eyed","pron":"mon-of'-thal-mos","pos":"Adjective","thayer":"<ol><li>deprived of one eye, having one eye</li></ol>","xlit":"monóphthalmos"},"G1868":{"strongs_def":" laudation; concretely, a commendable thing","derivation":"from G1909 (ἐπί) and the base of G134 (αἰνέω);","lemma":"ἔπαινος","translit":"épainos","kjv_def":"praise","pron":"ep'-ahee-nos","xlit":"épainos"},"G1356":{"strongs_def":" sky-fallen (i.e. an aerolite)","derivation":"from the alternate of G2203 (Ζεύς) and the alternate of G4098 (πίπτω);","lemma":"διοπετής","translit":"diopetḗs","kjv_def":"which fell down from Jupiter","pron":"dee-op-et'-ace","pos":"Adjective","thayer":"<ol><li>fallen from Zeus, i.e. from heaven</li><li>an image of the Ephesian Artemis which was supposed to have fallen from heaven</li></ol>","xlit":"diopetḗs"},"G1693":{"lemma":"ἐμμαίνομαι","translit":"emmaínomai","kjv_def":"be mad against","strongs_def":" to rave on, i.e. rage at","derivation":"from G1722 (ἐν) and G3105 (μαίνομαι);","pron":"em-mah'-ee-nom-ahee","pos":"Verb","thayer":"<ol><li>to rage against one</li></ol>","xlit":"emmaínomai"},"G3503":{"translit":"neótēs","lemma":"νεότης","kjv_def":"youth","strongs_def":" newness, i.e. youthfulness","derivation":"from G3501 (νέος);","pron":"neh-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>youth, youthful age</li></ol>","xlit":"neótēs"},"G4867":{"derivation":"from G4862 (σύν) and (to hoard);","strongs_def":" to convene","kjv_def":"call (gather) together","lemma":"συναθροίζω","translit":"synathroízō","pron":"soon-ath-royd'-zo","pos":"Verb","thayer":"<ol><li>to gather together with others</li><li>to assemble</li><li>to be gathered together, i.e. to come together</li></ol>","xlit":"synathroízō"},"G1795":{"strongs_def":" to enstamp, i.e. engrave","derivation":"from G1722 (ἐν) and a derivative of G5179 (τύπος);","lemma":"ἐντυπόω","translit":"entypóō","kjv_def":"engrave","pron":"en-too-po'-o","pos":"Verb","thayer":"<ol><li>to engrave, imprint (a figure)</li></ol>","xlit":"entypóō"},"G2568":{"translit":"Kaloì Liménes","lemma":"Καλοὶ Λιμένες","kjv_def":"fair havens","strongs_def":" Good Harbors, i.e. Fairhaven, a bay of Crete","derivation":"plural of G2570 (καλός) and G3040 (λιμήν);","pron":"kal-oy' lee-men'-es","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Fair Havens = \"goodly ports\"</p><ol><li>a bay of Crete, near the city Lasaea, so called because it had a good harbour</li></ol>","xlit":"Kaloì Liménes"},"G1705":{"strongs_def":"to fill in (up), i.e. (by implication) to satisfy (literally or figuratively)","derivation":"from G1722 (ἐν) and the base of G4118 (πλεῖστος);","translit":"empíplēmi","lemma":"ἐμπίπλημι","kjv_def":"fill","pron":"em-pip'-lay-mee","pos":"Verb","thayer":"<ol><li>to fill up, fill full</li><li>to take one's fill of, glut one's desire for, satisfy, satiate</li></ol>","xlit":"empíplēmi"},"G384":{"translit":"anaskeuázō","lemma":"ἀνασκευάζω","kjv_def":"subvert","strongs_def":" properly, to pack up (baggage), i.e. (by implication, and figuratively) to upset","derivation":"from G303 (ἀνά) (in the sense of reversal) and a derivative of G4632 (σκεῦος);","pron":"an-ask-yoo-ad'-zo","pos":"Verb","thayer":"<ol><li>to pack up baggage in order to carry it away to another place<ol type='a'><li>to move one's furniture (when setting out for some other place)</li></ol><li>of an enemy<ol type='a'><li>dismantling, plundering</li></ol><li>of a place<ol type='a'><li>to overthrow, ravage destroy towns lands etc.</li></ol><li>to turn away violently from a right state, to unsettle, subvert</li></ol>","xlit":"anaskeuázō"},"G3854":{"strongs_def":" to become near, i.e. approach (have arrived); by implication, to appear publicly","derivation":"from G3844 (παρά) and G1096 (γίνομαι);","translit":"paragínomai","lemma":"παραγίνομαι","kjv_def":"come, go, be present","pron":"par-ag-in'-om-ahee","pos":"Verb","thayer":"<ol><li>to be present, to come near, approach</li><li>to come forth, make one's public appearance</li></ol>","xlit":"paragínomai"},"G4034":{"derivation":"from G4012 (περί) and G2989 (λάμπω);","strongs_def":" to illuminate all around, i.e. invest with a halo","kjv_def":"shine round about","lemma":"περιλάμπω","translit":"perilámpō","pron":"per-ee-lam'-po","pos":"Verb","thayer":"<ol><li>to shine around</li></ol>","xlit":"perilámpō"},"G2878":{"lemma":"κορβᾶν","translit":"korbân","kjv_def":"Corban, treasury","strongs_def":" a votive offering and the offering; a consecrated present (to the Temple fund); by extension (the latter term) the Treasury itself, i.e. the room where the contribution boxes stood","derivation":"of Hebrew and Chaldee origin respectively (H07133);","pron":"kor-ban'","pos":"Noun Masculine","thayer":"<ol><li>a gift offered (or to be offered) to God</li><li>the sacred treasury</li></ol>","xlit":"korbân"},"G192":{"kjv_def":"excess, incontinency","translit":"akrasía","lemma":"ἀκρασία","derivation":"from G193 (ἀκρατής);","strongs_def":" want of self-restraint","pron":"ak-ras-ee'-a","pos":"Noun Feminine","thayer":"<ol><li>want of self-control, incontinence, intemperance</li></ol>","xlit":"akrasía"},"G139":{"strongs_def":" properly, a choice, i.e. (specially) a party or (abstractly) disunion","derivation":"from G138 (αἱρέομαι);","translit":"haíresis","lemma":"αἵρεσις","kjv_def":"heresy (which is the Greek word itself), sect","pron":"hah'-ee-res-is","pos":"Noun Feminine","thayer":"<ol><li>act of taking, capture: e.g. storming a city</li><li>choosing, choice</li><li>that which is chosen</li><li>a body of men following their own tenets (sect or party)<ol type='a'><li>of the Sadducees</li><li>of the Pharisees</li><li>of the Christians</li></ol><li>dissensions arising from diversity of opinions and aims</li></ol>","xlit":"haíresis"},"G1511":{"translit":"eînai","lemma":"εἶναι","kjv_def":"am, was","strongs_def":" to exist","derivation":"present infinitive from G1510 (εἰμί);","pron":"i'-nahee","pos":"Verb","thayer":"<ol><li>to be, to exist, to happen, to be present</li></ol>","xlit":"eînai"},"G2627":{"lemma":"κατακλυσμός","translit":"kataklysmós","kjv_def":"flood","strongs_def":" an inundation","derivation":"from G2626 (κατακλύζω);","pron":"kat-ak-looce-mos'","pos":"Noun Masculine","thayer":"<ol><li>inundation, deluge<ol type='a'><li>of Noah's deluge</li></ol></li></ol>","xlit":"kataklysmós"},"G228":{"strongs_def":" truthful","derivation":"from G227 (ἀληθής);","lemma":"ἀληθινός","translit":"alēthinós","kjv_def":"true","pron":"al-ay-thee-nos'","pos":"Adjective","thayer":"<ol><li>that which has not only the name and resemblance, but the real nature corresponding to the name, in every respect corresponding to the idea signified by the name, real, true genuine<ol type='a'><li>opposite to what is fictitious, counterfeit, imaginary, simulated or pretended</li><li>it contrasts realities with their semblances</li><li>opposite to what is imperfect defective, frail, uncertain</li></ol><li>true, veracious, sincere</li></ol>","xlit":"alēthinós"},"G3818":{"kjv_def":"Pacatiana","translit":"Pakatianḗ","lemma":"Πακατιανή","derivation":"feminine of an adjective of uncertain derivation;","strongs_def":" Pacatianian, a section of Phrygia","pron":"pak-at-ee-an-ay'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Phrygia = \"dry, barren\"</p><ol><li>in the 4th century after Christ, Phrygia was divided into Phrygia Salutaris and Phrygia Pacatiana; Laodicea was a city in the latter</li></ol>","xlit":"Pakatianḗ"},"G3898":{"derivation":"adverb from the same as G3897 (παραπλήσιον);","strongs_def":" in a manner near by, i.e. (figuratively) similarly","kjv_def":"likewise","translit":"paraplēsíōs","lemma":"παραπλησίως","pron":"par-ap-lay-see'-oce","pos":"Adverb","thayer":"<ol><li>similarly, in like manner, in the same way</li></ol>","xlit":"paraplēsíōs"},"G4945":{"lemma":"συνωμοσία","translit":"synōmosía","kjv_def":"comspiracy","strongs_def":" a swearing together, i.e. (by implication) a plot","derivation":"from a compound of G4862 (σύν) and G3660 (ὀμνύω);","pron":"soon-o-mos-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a swearing together</li><li>a conspiracy</li></ol>","xlit":"synōmosía"},"G4252":{"derivation":"diminutive of G4251 (Πρίσκα);","strongs_def":" Priscilla (i.e. little Prisca), a Christian woman","kjv_def":"Priscilla","translit":"Prískilla","lemma":"Πρίσκιλλα","pron":"pris'-cil-lah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Priscilla = \"ancient\"</p><ol><li>a Christian woman, the wife of Aquila</li></ol>","xlit":"Prískilla"},"G973":{"strongs_def":" a forcer, i.e. (figuratively) energetic","derivation":"from G971 (βιάζω);","lemma":"βιαστής","translit":"biastḗs","kjv_def":"violent","pron":"bee-as-tace'","pos":"Noun Masculine","thayer":"<ol><li>strong, forceful</li><li>using force, violent</li></ol>","xlit":"biastḗs"},"G2425":{"derivation":"from ( or , akin to G2240 (ἥκω)) (to arrive);","strongs_def":" competent (as if coming in season), i.e. ample (in amount) or fit (in character)","kjv_def":"able, + content, enough, good, great, large, long (while), many, meet, much, security, sore, sufficient, worthy","translit":"hikanós","lemma":"ἱκανός","pron":"hik-an-os'","pos":"Adjective","thayer":"<ol><li>sufficient<ol type='a'><li>many enough, enough</li><li>sufficient in ability, i.e. meet, fit</li></ol></li></ol>","xlit":"hikanós"},"G884":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G5483 (χαρίζομαι);","strongs_def":" thankless, i.e. ungrateful","kjv_def":"unthankful","translit":"acháristos","lemma":"ἀχάριστος","pron":"ach-ar'-is-tos","pos":"Adjective","thayer":"<ol><li>ungracious<ol type='a'><li>unpleasing</li><li>unthankful</li></ol></li></ol>","xlit":"acháristos"},"G3063":{"lemma":"λοιπόν","translit":"loipón","kjv_def":"besides, finally, furthermore, (from) henceforth, moreover, now, + it remaineth, then","strongs_def":" something remaining (adverbially)","derivation":"neuter singular of the same as G3062 (λοιποί);","pron":"loy-pon'","pos":"Adverb Neuter","thayer":"<ol><li>remaining, the rest<ol type='a'><li>hereafter, for the future, henceforth</li><li>at last, already</li><li>for the rest, besides, moreover</li></ol></li></ol>","xlit":"loipón"},"G3540":{"lemma":"νόημα","translit":"nóēma","kjv_def":"device, mind, thought","strongs_def":" a perception, i.e. purpose, or (by implication) the intellect, disposition, itself","derivation":"from G3539 (νοιέω);","pron":"no'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a mental perception, thought</li><li>an evil purpose</li><li>that which thinks, the mind, thoughts or purposes</li></ol>","xlit":"nóēma"},"G5599":{"derivation":"a primary interjection;","strongs_def":" as a sign of the vocative case, O; as a note of exclamation, oh","kjv_def":"O","translit":"ō","lemma":"ὦ","pron":"o","thayer":"<ol><li>the interjection, O!</li></ol>","xlit":"ō"},"G3099":{"translit":"Madián","lemma":"Μαδιάν","kjv_def":"Madian","strongs_def":" Madian (i.e. Midian), a region of Arabia","derivation":"of Hebrew origin (H04080);","pron":"mad-ee-on'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Madian or Midian = \"contention: strife\"</p><ol><li>a land near the Red Sea, and took its name from one of the sons of Abraham by Keturah</li></ol>","xlit":"Madián"},"G5250":{"kjv_def":"be exceeding abundant","lemma":"ὑπερπλεονάζω","translit":"hyperpleonázō","derivation":"from G5228 (ὑπέρ) and G4121 (πλεονάζω);","strongs_def":" to superabound","pron":"hoop-er-pleh-on-ad'-zo","pos":"Verb","thayer":"<ol><li>to be exceedingly abundant</li><li>to overflow</li><li>to possess in excess</li></ol>","xlit":"hyperpleonázō"},"G3967":{"derivation":"from G3962 (πατήρ);","strongs_def":" paternal, i.e. ancestral","kjv_def":"of fathers","translit":"patrikós","lemma":"πατρικός","pron":"pat-ree-kos'","pos":"Adjective","thayer":"<ol><li>paternal, ancestral, handed down by or received from one's fathers</li></ol>","xlit":"patrikós"},"G2263":{"lemma":"ἤρεμος","translit":"ḗremos","kjv_def":"quiet","strongs_def":" tranquil","derivation":"perhaps by transposition from G2048 (ἔρημος) (through the idea of stillness);","pron":"ay'-rem-os","pos":"Adjective","thayer":"<ol><li>quiet, tranquil</li></ol>","xlit":"ḗremos"},"G4667":{"derivation":"the same as G4666 (σμύρνα);","strongs_def":" Smyrna, a place in Asia Minor","kjv_def":"Smyrna","lemma":"Σμύρνα","translit":"Smýrna","pron":"smoor'-nah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Smyrna = \"myrrh\"</p><ol><li>an Ionian city of Asia Minor, on the Aegean Sea, 40 miles (65 km) north of Ephesus</li></ol>","xlit":"Smýrna"},"G4390":{"strongs_def":" to run forward, i.e. outstrip, precede","derivation":"from G4253 (πρό) and G5143 (τρέχω) (including its alternate);","translit":"protréchō","lemma":"προτρέχω","kjv_def":"outrun, run before","pron":"prot-rekh'-o","pos":"Verb","thayer":"<ol><li>to run before, to outrun</li></ol>","xlit":"protréchō"},"G4954":{"derivation":"from G4862 (σύν) and G4983 (σῶμα);","strongs_def":" of a joint body, i.e. (figuratively) a fellow-member of the Christian community","kjv_def":"of the same body","lemma":"σύσσωμος","translit":"sýssōmos","pron":"soos'-so-mos","pos":"Adjective","thayer":"<ol><li>belonging to the same body</li><li>metaphorically to the same church</li></ol>","xlit":"sýssōmos"},"G2037":{"derivation":"from (to love);","strongs_def":" beloved; Erastus, a Christian","kjv_def":"Erastus","lemma":"Ἔραστος","translit":"Érastos","pron":"er'-as-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Erastus = \"beloved\"</p><ol><li>a companion of the apostle Paul</li><li>the chamberlain or rather the public treasurer, of Corinth</li></ol>","xlit":"Érastos"},"G953":{"kjv_def":"profane","translit":"bebēlóō","lemma":"βεβηλόω","derivation":"from G952 (βέβηλος);","strongs_def":" to desecrate","pron":"beb-ay-lo'-o","pos":"Verb","thayer":"<ol><li>to profane, desecrate</li></ol>","xlit":"bebēlóō"},"G3019":{"strongs_def":" a Levite, i.e. descendant of Levi","derivation":"from G3017 (Λευΐ);","translit":"Leuḯtēs","lemma":"Λευΐτης","kjv_def":"Levite","pron":"lyoo-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>one of the tribe of Levi</li><li>in a narrower sense those were called Levites who, not being of the family of Aaron, for whom alone the priesthood was reserved, served as assistants to the priests. It was their duty to keep the sacred utensils and the temple clean, to provide the sacred loaves, to open and shut the gates of the temple, to sing the sacred hymns in the temple, and to do many other things.</li></ol>","xlit":"Leuḯtēs"},"G4524":{"kjv_def":"Sadoc","lemma":"Σαδώκ","translit":"Sadṓk","derivation":"of Hebrew origin (H06659);","strongs_def":" Sadoc (i.e. Tsadok), an Israelite","pron":"sad-oke'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sadoc = \"just\"</p><ol><li>a descendant of Zerubbabel in the genealogy of Christ</li></ol>","xlit":"Sadṓk"},"G1068":{"derivation":"of Chaldee origin (compare H01660 and H08081);","strongs_def":" oil-press; Gethsemane, a garden near Jerusalem","kjv_def":"Gethsemane","lemma":"Γεθσημανῆ","translit":"Gethsēmanē","pron":"gheth-say-man-ay'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gethsemane = \"an oil press\"</p><ol><li>the name of a place at the foot of the Mount of Olives, beyond the torrent Kidron</li></ol>","xlit":"Gethsēmanē"},"G627":{"strongs_def":" a plea (\"apology\")","derivation":"from the same as G626 (ἀπολογέομαι);","lemma":"ἀπολογία","translit":"apología","kjv_def":"answer (for self), clearing of self, defence","pron":"ap-ol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>verbal defence, speech in defence</li><li>a reasoned statement or argument</li></ol>","xlit":"apología"},"G5372":{"lemma":"Φίλητος","translit":"Phílētos","kjv_def":"Philetus","strongs_def":" amiable; Philetus, an opposer of Christianity","derivation":"from G5368 (φιλέω);","pron":"fil-ay-tos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Philetus = \"beloved\"</p><ol><li>a heretic and a disciple of Hymenaeus</li></ol>","xlit":"Phílētos"},"G3825":{"kjv_def":"again","lemma":"πάλιν","translit":"pálin","derivation":"probably from the same as G3823 (πάλη) (through the idea of oscillatory repetition);","strongs_def":" (adverbially) anew, i.e. (of place) back, (of time) once more, or (conjunctionally) furthermore or on the other hand","pron":"pal'-in","pos":"Adverb","thayer":"<ol><li>anew, again<ol type='a'><li>renewal or repetition of the action</li><li>again, anew</li></ol><li>again, i.e. further, moreover</li><li>in turn, on the other hand</li></ol>","xlit":"pálin"},"G3436":{"lemma":"μολυσμός","translit":"molysmós","kjv_def":"filthiness","strongs_def":" a stain; i.e. (figuratively) immorality","derivation":"from G3435 (μολύνω);","pron":"mol-oos-mos'","pos":"Noun Masculine","thayer":"<ol><li>defilement, an action by which anything is defiled</li></ol>","xlit":"molysmós"},"G3939":{"lemma":"παροικέω","translit":"paroikéō","kjv_def":"sojourn in, be a stranger","strongs_def":" to dwell near, i.e. reside as a foreigner","derivation":"from G3844 (παρά) and G3611 (οἰκέω);","pron":"par-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell beside (one) or in one's neighbourhood, to live near</li><li>in the NT, to be or dwell in a place as a stranger, to sojourn</li></ol>","xlit":"paroikéō"},"G848":{"translit":"hautoû","lemma":"αὑτοῦ","kjv_def":"her (own), (of) him(-self), his (own), of it, thee, their (own), them(-selves), they","strongs_def":" self (in some oblique case or reflexively, relation)","derivation":"contracted for G1438 (ἑαυτοῦ);","pron":"how-too'","thayer":"<ol><li>of himself, themself, them</li></ol>","xlit":"hautoû"},"G5524":{"strongs_def":" to be a dance-leader, i.e. (generally) to furnish","derivation":"from a compound of G5525 (χορός) and G71 (ἄγω);","lemma":"χορηγέω","translit":"chorēgéō","kjv_def":"give, minister","pron":"khor-ayg-eh'-o","pos":"Verb","thayer":"<ol><li>to be a chorus leader, lead a chorus</li><li>to furnish the chorus at one's own expense</li><li>to procure and supply all things necessary to fit out a chorus</li><li>to supply, furnish abundantly</li></ol>","xlit":"chorēgéō"},"G3528":{"kjv_def":"conquer, overcome, prevail, get the victory","lemma":"νικάω","translit":"nikáō","derivation":"from G3529 (νίκη);","strongs_def":" to subdue (literally or figuratively)","pron":"nik-ah'-o","pos":"Verb","thayer":"<ol><li>to conquer<ol type='a'><li>to carry off the victory, come off victorious<ol><li>of Christ, victorious over all His foes</li><li>of Christians, that hold fast their faith even unto death against the power of their foes, and temptations and persecutions</li><li>when one is arraigned or goes to law, to win the case, maintain one's cause</li></ol></li></ol></li></ol>","xlit":"nikáō"},"G1719":{"derivation":"from G1722 (ἐν) and G5401 (φόβος);","strongs_def":" in fear, i.e. alarmed","kjv_def":"affrighted, afraid, tremble","translit":"émphobos","lemma":"ἔμφοβος","pron":"em'-fob-os","pos":"Adjective","thayer":"<ol><li>thrown into fear, terrified, affrighted</li></ol>","xlit":"émphobos"},"G5239":{"strongs_def":" to extend inordinately","derivation":"from G5228 (ὑπέρ) and G1614 (ἐκτείνω);","lemma":"ὑπερεκτείνω","translit":"hyperekteínō","kjv_def":"stretch beyond","pron":"hoop-er-ek-ti'-no","pos":"Verb","thayer":"<ol><li>to extend beyond the prescribed bounds, stretch out beyond measure, stretch out overmuch</li></ol>","xlit":"hyperekteínō"},"G3610":{"derivation":"from G3611 (οἰκέω);","strongs_def":" a fellow resident, i.e. menial domestic","kjv_def":"(household) servant","lemma":"οἰκέτης","translit":"oikétēs","pron":"oy-ket'-ace","pos":"Noun Masculine","thayer":"<ol><li>one who lives in the same house as another, spoken of all who are under the authority of one and the same householder<ol type='a'><li>a servant, a domestic</li></ol></li></ol>","xlit":"oikétēs"},"G3148":{"kjv_def":"plague, scourging","translit":"mástix","lemma":"μάστιξ","derivation":"probably from the base of G3145 (μασσάομαι) (through the idea of contact);","strongs_def":" a whip (literally, the Roman flagellum for criminals; figuratively, a disease)","pron":"mas'-tix","pos":"Noun Feminine","thayer":"<ol><li>a whip, scourge</li><li>metaphorically a scourge, plague<ol type='a'><li>a calamity, misfortune, especially sent by God to discipline or punish</li></ol></li></ol>","xlit":"mástix"},"G3380":{"strongs_def":" not yet","derivation":"from G3361 (μή) and G4452 (-πω);","translit":"mḗpō","lemma":"μήπω","kjv_def":"not yet","pron":"may'-po","pos":"Adverb","thayer":"<ol><li>not yet</li></ol>","xlit":"mḗpō"},"G3433":{"kjv_def":"hardly, scarce(-ly), + with much work","lemma":"μόλις","translit":"mólis","derivation":"probably by variation for G3425 (μόγις);","strongs_def":" with difficulty","pron":"mol'-is","pos":"Adverb","thayer":"<ol><li>with difficulty, hardly</li><li>not easily, i.e. scarcely, very rarely</li></ol>","xlit":"mólis"},"G2676":{"translit":"katártisis","lemma":"κατάρτισις","kjv_def":"perfection","strongs_def":" thorough equipment (subjectively)","derivation":"from G2675 (καταρτίζω);","pron":"kat-ar'-tis-is","pos":"Noun Feminine","thayer":"<ol><li>a strengthening, perfecting of the soul<ol type='a'><li>a training, disciplining, instructing</li></ol></li></ol>","xlit":"katártisis"},"G4818":{"derivation":"from G4862 (σύν) and G3076 (λυπέω);","strongs_def":" to afflict jointly, i.e. (passive) sorrow at (on account of) someone","kjv_def":"be grieved","lemma":"συλλυπέω","translit":"syllypéō","pron":"sool-loop-eh'-o","pos":"Verb","thayer":"<ol><li>to affect with grief together</li><li>give with one's self</li></ol>","xlit":"syllypéō"},"G2276":{"kjv_def":"less, worse","lemma":"ἥττον","translit":"hḗtton","derivation":"neuter of comparative of (slightly) used for that of G2556 (κακός);","strongs_def":" worse (as noun); by implication, less (as adverb)","pron":"hate'-ton","pos":"Adjective","thayer":"<ol><li>inferior</li><li>less</li></ol>","xlit":"hḗtton"},"G4947":{"strongs_def":" Syria (i.e. Tsyria or Tyre), a region of Asia","derivation":"probably of Hebrew origin (H06865);","translit":"Syría","lemma":"Συρία","kjv_def":"Syria","pron":"soo-ree'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Syria = \"exalted\"</p><ol><li>a region of Asia bounded on the north by Taurus and Amanus ranges, on the east by the Euphrates and Arabia, on the south by Palestine, and the west by Phoenicia and the Mediterranean</li></ol>","xlit":"Syría"},"G5280":{"strongs_def":" a reminding or (reflexively) recollection","derivation":"from G5279 (ὑπομιμνήσκω);","translit":"hypómnēsis","lemma":"ὑπόμνησις","kjv_def":"remembrance","pron":"hoop-om'-nay-sis","pos":"Noun Feminine","thayer":"<ol><li>a reminding</li><li>remembrance</li></ol>","xlit":"hypómnēsis"},"G2738":{"translit":"kaûma","lemma":"καῦμα","kjv_def":"heat","strongs_def":" properly, a burn (concretely), but used (abstractly) of a glow","derivation":"from G2545 (καίω);","pron":"kow'-mah","pos":"Noun Neuter","thayer":"<ol><li>heat<ol type='a'><li>of painful and burning heat</li></ol></li></ol>","xlit":"kaûma"},"G4190":{"translit":"ponērós","lemma":"πονηρός","kjv_def":"bad, evil, grievous, harm, lewd, malicious, wicked(-ness)","strongs_def":" hurtful, i.e. evil (properly, in effect or influence, and thus differing from G2556 (κακός), which refers rather to essential character, as well as from G4550 (σαπρός), which indicates degeneracy from original virtue); figuratively, calamitous; also (passively) ill, i.e. diseased; but especially (morally) culpable, i.e. derelict, vicious, facinorous; neuter (singular) mischief, malice, or (plural) guilt; masculine (singular) the devil, or (plural) sinners","derivation":"from a derivative of G4192 (πόνος);","pron":"pon-ay-ros'","pos":"Adjective","thayer":"<ol><li>full of labours, annoyances, hardships<ol type='a'><li>pressed and harassed by labours</li><li>bringing toils, annoyances, perils; of a time full of peril to Christian faith and steadfastness; causing pain and trouble</li></ol><li>bad, of a bad nature or condition<ol type='a'><li>in a physical sense: diseased or blind</li><li>in an ethical sense: evil wicked, bad</li></ol></li></ol>","xlit":"ponērós"},"G5368":{"strongs_def":" to be a friend to (fond of (an individual or an object)), i.e. have affection for (denoting personal attachment, as a matter of sentiment or feeling; while G25 (ἀγαπάω) is wider, embracing especially the judgment and the deliberate assent of the will as a matter of principle, duty and propriety: the two thus stand related very much as G2309 (θέλω) and G1014 (βούλομαι), or as G2372 (θυμός) and G3563 (νοῦς) respectively; the former being chiefly of the heart and the latter of the head); specially, to kiss (as a mark of tenderness)","derivation":"from G5384 (φίλος);","lemma":"φιλέω","translit":"philéō","kjv_def":"kiss, love","pron":"fil-eh'-o","pos":"Verb","thayer":"<ol><li>to love<ol type='a'><li>to approve of</li><li>to like</li><li>sanction</li><li>to treat affectionately or kindly, to welcome, befriend</li></ol><li>to show signs of love<ol type='a'><li>to kiss</li></ol><li>to be fond of doing<ol type='a'><li>be wont, use to do</li></ol></li></ol>","xlit":"philéō"},"G1033":{"derivation":"from the base of G977 (βιβρώσκω);","strongs_def":" food (literally or figuratively), especially (ceremonially) articles allowed or forbidden by the Jewish law","kjv_def":"meat, victuals","lemma":"βρῶμα","translit":"brōma","pron":"bro'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is eaten, food</li></ol>","xlit":"brōma"},"G243":{"strongs_def":" \"else,\" i.e. different (in many applications)","derivation":"a primary word;","lemma":"ἄλλος","translit":"állos","kjv_def":"more, one (another), (an-, some an-)other(-s, -wise)","pron":"al'-los","pos":"Adjective","thayer":"<ol><li>another, other</li></ol>","xlit":"állos"},"G1319":{"strongs_def":" instruction (the function or the information)","derivation":"from G1320 (διδάσκαλος);","translit":"didaskalía","lemma":"διδασκαλία","kjv_def":"doctrine, learning, teaching","pron":"did-as-kal-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>teaching, instruction</li><li>teaching<ol type='a'><li>that which is taught, doctrine</li><li>teachings, precepts</li></ol></li></ol>","xlit":"didaskalía"},"G4136":{"strongs_def":" entire confidence","derivation":"from G4135 (πληροφορέω);","lemma":"πληροφορία","translit":"plērophoría","kjv_def":"(full) assurance","pron":"play-rof-or-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>full assurance, most certain confidence</li></ol>","xlit":"plērophoría"},"G1277":{"kjv_def":"sail over","lemma":"διαπλέω","translit":"diapléō","derivation":"from G1223 (διά) and G4126 (πλέω);","strongs_def":" to sail through","pron":"dee-ap-leh'-o","pos":"Verb","thayer":"<ol><li>to sail across</li></ol>","xlit":"diapléō"},"G4319":{"translit":"prosaitéō","lemma":"προσαιτέω","kjv_def":"beg","strongs_def":" to ask repeatedly (importune), i.e. solicit","derivation":"from G4314 (πρός) and G154 (αἰτέω);","pron":"pros-ahee-teh'-o","pos":"Verb","thayer":"<ol><li>to ask for in addition</li><li>to approach one with supplications</li><li>to ask alms</li></ol>","xlit":"prosaitéō"},"G2727":{"strongs_def":" to sound down into the ears, i.e. (by implication) to indoctrinate (\"catechize\") or (genitive case) to apprise of","derivation":"from G2596 (κατά) and G2279 (ἦχος);","translit":"katēchéō","lemma":"κατηχέω","kjv_def":"inform, instruct, teach","pron":"kat-ay-kheh'-o","pos":"Verb","thayer":"<ol><li>to sound towards, sound down upon, resound<ol type='a'><li>to charm with resounding sound, to fascinate</li></ol><li>to teach orally, to instruct</li><li>to inform by word of mouth<ol type='a'><li>to be orally informed</li></ol></li></ol>","xlit":"katēchéō"},"G4247":{"strongs_def":" an old woman","derivation":"feminine of G4246 (πρεσβύτης);","lemma":"πρεσβῦτις","translit":"presbŷtis","kjv_def":"aged woman","pron":"pres-boo'-tis","pos":"Noun Feminine","thayer":"<ol><li>an aged woman</li></ol>","xlit":"presbŷtis"},"G3393":{"derivation":"from G3392 (μιαίνω) (\"miasma\");","strongs_def":" (morally) foulness (properly, the effect)","kjv_def":"pollution","translit":"míasma","lemma":"μίασμα","pron":"mee'-as-mah","pos":"Noun Neuter","thayer":"<ol><li>that which defiles, defilement</li><li>metaphorically, vices the foulness of which contaminates one in his intercourse with the ungodly mass of mankind</li></ol>","xlit":"míasma"},"G1192":{"derivation":"from G1194 (δέρω);","strongs_def":" a hide","kjv_def":"skin","lemma":"δέρμα","translit":"dérma","pron":"der'-mah","pos":"Noun Neuter","thayer":"<ol><li>a skin, hide, leather</li></ol>","xlit":"dérma"},"G3361":{"strongs_def":" (adverb) not, (conjunction) lest; also (as an interrogative implying a negative answer (whereas G3756 (οὐ) expects an affirmative one)) whether","derivation":"a primary particle of qualified negation (whereas G3756 (οὐ) expresses an absolute denial);","translit":"mḗ","lemma":"μή","kjv_def":"any but (that), X forbear, + God forbid, + lack, lest, neither, never, no (X wise in), none, nor, (can-)not, nothing, that not, un(-taken), without","pron":"may","thayer":"<ol><li>no, not lest</li></ol>","xlit":"mḗ"},"G281":{"kjv_def":"amen, verily","lemma":"ἀμήν","translit":"amḗn","derivation":"of Hebrew origin (H0543);","strongs_def":" properly, firm, i.e. (figuratively) trustworthy; adverbially, surely (often as interjection, so be it)","pron":"am-ane'","thayer":"<ol><li>firm<ol type='a'><li>metaphorically faithful</li></ol><li>verily, amen<ol type='a'><li>at the beginning of a discourse - surely, truly, of a truth</li><li>at the end - so it is, so be it, may it be fulfilled. It was a custom, which passed over from the synagogues to the Christian assemblies, that when he who had read or discoursed, had offered up solemn prayer to God, the others responded Amen, and thus made the substance of what was uttered their own.</li></ol></li></ol>","xlit":"amḗn"},"G3504":{"kjv_def":"novice","translit":"neóphytos","lemma":"νεόφυτος","derivation":"from G3501 (νέος) and a derivative of G5453 (φύω);","strongs_def":" newly planted, i.e. (figuratively) a young convert (\"neophyte\")","pron":"neh-of'-oo-tos","pos":"Adjective","thayer":"<ol><li>newly planted<ol type='a'><li>a new convert, neophyte (one who has recently become a Christian)</li></ol></li></ol>","xlit":"neóphytos"},"G2151":{"kjv_def":"show piety, worship","translit":"eusebéō","lemma":"εὐσεβέω","derivation":"from G2152 (εὐσεβής);","strongs_def":" to be pious, i.e. (towards God) to worship, or (towards parents) to respect (support)","pron":"yoo-seb-eh'-o","pos":"Verb","thayer":"<ol><li>to act piously or reverently<ol type='a'><li>towards God, one's country, magistrates, relations, and all to whom dutiful regard or reverence is due</li></ol></li></ol>","xlit":"eusebéō"},"G2508":{"kjv_def":"purge","lemma":"καθαίρω","translit":"kathaírō","derivation":"from G2513 (καθαρός);","strongs_def":" to cleanse, i.e. (specially) to prune; figuratively, to expiate","pron":"kath-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to cleanse, of filth impurity, etc<ol type='a'><li>to prune trees and vines from useless shoots</li><li>metaphorically from guilt, to expiate</li></ol></li></ol>","xlit":"kathaírō"},"G225":{"translit":"alḗtheia","lemma":"ἀλήθεια","kjv_def":"true, X truly, truth, verity","strongs_def":" truth","derivation":"from G227 (ἀληθής);","pron":"al-ay'-thi-a","pos":"Noun Feminine","thayer":"<ol><li>objectively<ol type='a'><li>what is true in any matter under consideration<ol><li>truly, in truth, according to truth</li><li>of a truth, in reality, in fact, certainly</li></ol><li>what is true in things appertaining to God and the duties of man, moral and religious truth<ol><li>in the greatest latitude</li><li>the true notions of God which are open to human reason without his supernatural intervention</li></ol><li>the truth as taught in the Christian religion, respecting God and the execution of his purposes through Christ, and respecting the duties of man, opposing alike to the superstitions of the Gentiles and the inventions of the Jews, and the corrupt opinions and precepts of false teachers even among Christians</li></ol><li>subjectively<ol type='a'><li>truth as a personal excellence<ol><li>that candour of mind which is free from affection, pretence, simulation, falsehood, deceit</li></ol></li></ol></li></ol>","xlit":"alḗtheia"},"G4933":{"derivation":"from G4862 (σύν) and G5083 (τηρέω);","strongs_def":" to keep closely together, i.e. (by implication) to conserve (from ruin); mentally, to remember (and obey)","kjv_def":"keep, observe, preserve","translit":"syntēréō","lemma":"συντηρέω","pron":"soon-tay-reh'-o","pos":"Verb","thayer":"<ol><li>to preserve (a thing from perishing or being lost)</li><li>to keep within one's self, keep in mind (a thing, lest it be forgotten)</li></ol>","xlit":"syntēréō"},"G3952":{"derivation":"from the present participle of G3918 (πάρειμι);","strongs_def":" a being near, i.e. advent (often, return; specially, of Christ to punish Jerusalem, or finally the wicked); (by implication) physically, aspect","kjv_def":"coming, presence","translit":"parousía","lemma":"παρουσία","pron":"par-oo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>presence</li><li>the coming, arrival, advent<ol type='a'><li>the future visible return from heaven of Jesus, to raise the dead, hold the last judgment, and set up formally and gloriously the kingdom of God</li></ol></li></ol>","xlit":"parousía"},"G618":{"strongs_def":" to receive (specially, in full, or as a host); also to take aside","derivation":"from G575 (ἀπό) and G2983 (λαμβάνω);","lemma":"ἀπολαμβάνω","translit":"apolambánō","kjv_def":"receive, take","pron":"ap-ol-am-ban'-o","pos":"Verb","thayer":"<ol><li>to receive<ol type='a'><li>of what is due or promised</li></ol><li>to take again or back, to recover<ol type='a'><li>to receive by way of retribution</li></ol><li>to take from others, take apart or aside</li><li>to receive any one hospitably</li></ol>","xlit":"apolambánō"},"G638":{"derivation":"from G575 (ἀπό) and G4155 (πνίγω);","strongs_def":" to stifle (by drowning or overgrowth)","kjv_def":"choke","lemma":"ἀποπνίγω","translit":"apopnígō","pron":"ap-op-nee'-go","pos":"Verb","thayer":"<ol><li>to choke<ol type='a'><li>to suffocate with water, drown</li></ol></li></ol>","xlit":"apopnígō"},"G1492":{"derivation":"a primary verb;","strongs_def":" used only in certain past tenses, the others being borrowed from the equivalent G3700 (ὀπτάνομαι) and G3708 (ὁράω); properly, to see (literally or figuratively); by implication, (in the perfect tense only) to know","kjv_def":"be aware, behold, X can (+ not tell), consider, (have) know(-ledge), look (on), perceive, see, be sure, tell, understand, wish, wot","lemma":"εἴδω","translit":"eídō","pron":"i'-do","pos":"Verb","thayer":"<ol><li>to see<ol type='a'><li>to perceive with the eyes</li><li>to perceive by any of the senses</li><li>to perceive, notice, discern, discover</li><li>to see<ol><li>i.e. to turn the eyes, the mind, the attention to anything</li><li>to pay attention, observe</li><li>to see about something<ol type='a'><li>i.e. to ascertain what must be done about it</li></ol><li>to inspect, examine</li><li>to look at, behold</li></ol><li>to experience any state or condition</li><li>to see, i.e. have an interview with, to visit</li></ol><li>to know<ol type='a'><li>to know of anything</li><li>to know, i.e. get knowledge of, understand, perceive<ol><li>of any fact</li><li>the force and meaning of something which has definite meaning</li><li>to know how, to be skilled in</li></ol><li>to have regard for one, cherish, pay attention to (<a class='bible' href='#b52.5.12'>1Th 5:12</a>)</li></ol></li></ol>","xlit":"eídō"},"G4067":{"kjv_def":"offscouring","lemma":"περίψωμα","translit":"perípsōma","derivation":"from a comparative of G4012 (περί) and (to rub);","strongs_def":" something brushed all around, i.e. off-scrapings (figuratively, scum)","pron":"per-ip'-say-mah","pos":"Noun Neuter","thayer":"<ol><li>what is wiped off</li><li>dirt rubbed off</li><li>off scouring, scrapings</li></ol>","xlit":"perípsōma"},"G933":{"lemma":"βασίλειον","translit":"basíleion","kjv_def":"king's court","strongs_def":" a palace","derivation":"neuter of G934 (βασίλειος);","pron":"bas-il'-i-on","pos":"Noun Neuter","thayer":"<ol><li>the royal palace</li></ol>","xlit":"basíleion"},"G1162":{"strongs_def":" a petition","derivation":"from G1189 (δέομαι);","translit":"déēsis","lemma":"δέησις","kjv_def":"prayer, request, supplication","pron":"deh'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>need, indigence, want, privation, penury</li><li>a seeking, asking, entreating, entreaty to God or to man</li></ol>","xlit":"déēsis"},"G1989":{"translit":"epistéllō","lemma":"ἐπιστέλλω","kjv_def":"write (a letter, unto)","strongs_def":" to enjoin (by writing), i.e. (genitive case) to communicate by letter (for any purpose)","derivation":"from G1909 (ἐπί) and G4724 (στέλλω);","pron":"ep-ee-stel'-lo","pos":"Verb","thayer":"<ol><li>to send one a message, command</li><li>to write a letter</li><li>to enjoin by letter, to write instructions</li></ol>","xlit":"epistéllō"},"G183":{"strongs_def":" unrestrainable","derivation":"from G1 (Α) (as a negative particle) and a derivative of G2722 (κατέχω);","translit":"akatáschetos","lemma":"ἀκατάσχετος","kjv_def":"unruly","pron":"ak-at-as'-khet-os","pos":"Adjective","thayer":"<ol><li>that can not be restrained</li></ol>","xlit":"akatáschetos"},"G5083":{"strongs_def":" perhaps akin to G2334 (θεωρέω)); to guard (from loss or injury, properly, by keeping the eye upon; and thus differing from G5442 (φυλάσσω), which is properly to prevent escaping; and from G2892 (κουστωδία), which implies a fortress or full military lines of apparatus), i.e. to note (a prophecy; figuratively, to fulfil a command); by implication, to detain (in custody; figuratively, to maintain); by extension, to withhold (for personal ends; figuratively, to keep unmarried); by extension, to withhold (for personal ends; figuratively, to keep unmarried)","derivation":"from (a watch;","lemma":"τηρέω","translit":"tēréō","kjv_def":"hold fast, keep(- er), (pre-, re-)serve, watch","pron":"tay-reh'-o","pos":"Verb","thayer":"<ol><li>to attend to carefully, take care of<ol type='a'><li>to guard</li><li>metaphorically to keep, one in the state in which he is</li><li>to observe</li><li>to reserve: to undergo something</li></ol></li></ol>","xlit":"tēréō"},"G982":{"lemma":"βιωτικός","translit":"biōtikós","kjv_def":"of (pertaining to, things that pertain to) this life","strongs_def":" relating to the present existence","derivation":"from a derivative of G980 (βιόω);","pron":"bee-o-tee-kos'","pos":"Adjective","thayer":"<ol><li>pertaining to life and the affairs of this life</li></ol>","xlit":"biōtikós"},"G3750":{"kjv_def":"smelling","translit":"ósphrēsis","lemma":"ὄσφρησις","derivation":"from a derivative of G3605 (ὄζω);","strongs_def":" smell (the sense)","pron":"os'-fray-sis","pos":"Noun Feminine","thayer":"<ol><li>a sense of smell, smelling</li></ol>","xlit":"ósphrēsis"},"G1517":{"kjv_def":"make peace","lemma":"εἰρηνοποιέω","translit":"eirēnopoiéō","derivation":"from G1518 (εἰρηνοποιός);","strongs_def":" to be a peace-maker, i.e. (figuratively) to harmonize","pron":"i-ray-nop-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to make peace, establish harmony</li></ol>","xlit":"eirēnopoiéō"},"G2364":{"derivation":"apparently a primary word (compare \"daughter\");","strongs_def":" a female child, or (by Hebraism) descendant (or inhabitant)","kjv_def":"daughter","translit":"thygátēr","lemma":"θυγάτηρ","pron":"thoo-gat'-air","pos":"Noun Feminine","thayer":"<ol><li>a daughter<ol type='a'><li>a daughter of God<ol><li>acceptable to God, rejoicing in God's peculiar care and protection</li></ol><li>with the name of a place, city, or region<ol><li>denotes collectively all its inhabitants and citizens</li></ol><li>a female descendant</li></ol></li></ol>","xlit":"thygátēr"},"G2899":{"derivation":"of uncertain derivation;","strongs_def":" a margin, i.e. (specially), a fringe or tassel","kjv_def":"border, hem","lemma":"κράσπεδον","translit":"kráspedon","pron":"kras'-ped-on","pos":"Noun Neuter","thayer":"<ol><li>the extremity or prominent part of a thing, edge, skirt, margin<ol type='a'><li>the fringe of a garment</li><li>in the NT a little appendage hanging down from the edge of the mantle or cloak, made of twisted wool</li><li>a tassel, tuft: the Jews had such appendages attached to their mantles to remind them of the law</li></ol></li></ol>","xlit":"kráspedon"},"G1406":{"lemma":"δραχμή","translit":"drachmḗ","kjv_def":"piece (of silver)","strongs_def":" a drachma or (silver) coin (as handled)","derivation":"from G1405 (δράσσομαι);","pron":"drakh-may'","pos":"Noun Feminine","thayer":"<ol><li>a drachma, a Greek silver coin about the same weight as a Roman denarius</li></ol>","xlit":"drachmḗ"},"G4283":{"lemma":"προευαγγελίζομαι","translit":"proeuangelízomai","kjv_def":"preach before the gospel","strongs_def":" to announce glad news in advance","derivation":"middle voice from G4253 (πρό) and G2097 (εὐαγγελίζω);","pron":"pro-yoo-ang-ghel-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to announce or promise glad tidings beforehand</li></ol>","xlit":"proeuangelízomai"},"G948":{"strongs_def":" to be disgusted, i.e. (by implication) detest (especially of idolatry)","derivation":"from a (presumed) derivative of (to stink);","translit":"bdelýssō","lemma":"βδελύσσω","kjv_def":"abhor, abominable","pron":"bdel-oos'-so","pos":"Verb","thayer":"<ol><li>to render foul, to cause to be abhorred</li><li>abominable</li><li>to turn one's self away from on account of the stench</li><li>metaphorically to abhor, detest</li></ol>","xlit":"bdelýssō"},"G3531":{"derivation":"from G3532 (Νικόλαος);","strongs_def":" a Nicolaite, i.e. adherent of Nicolaus","kjv_def":"Nicolaitane","translit":"Nikolaḯtēs","lemma":"Νικολαΐτης","pron":"nik-ol-ah-ee'-tace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nicolaitans = \"destruction of people\"</p><ol><li>a sect mentioned in <a class='bible' href='#b66.2.6'>Rev 2:6</a>,<a class='bible' href='#b66.2.15'>Rev 2:15</a>, who were charged with holding the error of Balaam, casting a stumbling block before the church of God by upholding the liberty of eating things sacrificed to idols as well as committing fornication</li></ol>","xlit":"Nikolaḯtēs"},"G5362":{"strongs_def":" fond of man, i.e. affectionate as a wife","derivation":"from G5384 (φίλος) and G435 (ἀνήρ);","lemma":"φίλανδρος","translit":"phílandros","kjv_def":"love their husbands","pron":"fil'-an-dros","pos":"Adjective","thayer":"<ol><li>loving her husband</li></ol>","xlit":"phílandros"},"G4019":{"strongs_def":" to bind around one, i.e. enwrap","derivation":"from G4012 (περί) and G1210 (δέω);","lemma":"περιδέω","translit":"peridéō","kjv_def":"bind about","pron":"per-ee-deh'-o","pos":"Verb","thayer":"<ol><li>to bind around, tie over</li></ol>","xlit":"peridéō"},"G2977":{"kjv_def":"privily, secretly","translit":"láthra","lemma":"λάθρα","derivation":"adverb from G2990 (λανθάνω);","strongs_def":" privately","pron":"lath'-rah","pos":"Adverb","thayer":"<ol><li>secretly</li></ol>","xlit":"láthra"},"G5000":{"derivation":"of Chaldee origin (compare H06646);","strongs_def":" the gazelle; Tabitha (i.e. Tabjetha), a Christian female","kjv_def":"Tabitha","lemma":"Ταβιθά","translit":"Tabithá","pron":"tab-ee-thah'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tabitha = \"female gazelle\"</p><ol><li>the name of the woman that Peter raised from the dead</li></ol>","xlit":"Tabithá"},"G4665":{"kjv_def":"emerald","lemma":"σμάραγδος","translit":"smáragdos","derivation":"of uncertain derivation;","strongs_def":" the emerald or green gem so called","pron":"smar'-ag-dos","pos":"Noun Feminine","thayer":"<ol><li>a transparent precious stone noted especially for its light green colour</li></ol>","xlit":"smáragdos"},"G4423":{"strongs_def":" alarm","derivation":"from G4422 (πτοέω);","translit":"ptóēsis","lemma":"πτόησις","kjv_def":"amazement","pron":"pto'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>to be afraid of with terror</li></ol>","xlit":"ptóēsis"},"G3164":{"kjv_def":"fight, strive","translit":"máchomai","lemma":"μάχομαι","derivation":"middle voice of an apparently primary verb;","strongs_def":" to war, i.e. (figuratively) to quarrel, dispute","pron":"makh'-om-ahee","pos":"Verb","thayer":"<ol><li>to fight<ol type='a'><li>of armed combatants, or those who engage in a hand to hand struggle</li><li>of those who engage in a war of words, to quarrel, wrangle, dispute</li><li>of those who contend at law for property and privileges</li></ol></li></ol>","xlit":"máchomai"},"G4102":{"strongs_def":" persuasion, i.e. credence; moral conviction (of religious truth, or the truthfulness of God or a religious teacher), especially reliance upon Christ for salvation; abstractly, constancy in such profession; by extension, the system of religious (Gospel) truth itself","derivation":"from G3982 (πείθω);","translit":"pístis","lemma":"πίστις","kjv_def":"assurance, belief, believe, faith, fidelity","pron":"pis'-tis","pos":"Noun Feminine","thayer":"<ol><li>conviction of the truth of anything, belief; in the NT of a conviction or belief respecting man's relationship to God and divine things, generally with the included idea of trust and holy fervour born of faith and joined with it<ol type='a'><li>relating to God<ol><li>the conviction that God exists and is the creator and ruler of all things, the provider and bestower of eternal salvation through Christ</li></ol><li>relating to Christ<ol><li>a strong and welcome conviction or belief that Jesus is the Messiah, through whom we obtain eternal salvation in the kingdom of God</li></ol><li>the religious beliefs of Christians</li><li>belief with the predominate idea of trust (or confidence) whether in God or in Christ, springing from faith in the same</li></ol><li>fidelity, faithfulness<ol type='a'><li>the character of one who can be relied on</li></ol></li></ol>","xlit":"pístis"},"G3979":{"kjv_def":"a- (on) foot","translit":"pezēi","lemma":"πεζῇ","derivation":"dative case feminine of a derivative of G4228 (πούς) (as adverb);","strongs_def":" foot-wise, i.e. by walking","pron":"ped-zay'","pos":"Adverb","thayer":"<ol><li>on foot (as opposed to riding)</li><li>by land (as opposed to going by sea)</li></ol>","xlit":"pezēi"},"G3346":{"kjv_def":"carry over, change, remove, translate, turn","lemma":"μετατίθημι","translit":"metatíthēmi","derivation":"from G3326 (μετά) and G5087 (τίθημι);","strongs_def":" to transfer, i.e. (literally) transport, (by implication) exchange, (reflexively) change sides, or (figuratively) pervert","pron":"met-at-ith'-ay-mee","pos":"Verb","thayer":"<ol><li>to transpose (two things, one of which is put in place of the other)<ol type='a'><li>to transfer</li><li>to change</li><li>to transfer one's self or suffer one's self to be transferred<ol><li>to go or pass over</li><li>to fall away or desert from one person or thing to another</li></ol></li></ol></li></ol>","xlit":"metatíthēmi"},"G4149":{"strongs_def":" wealth (as fulness), i.e. (literally) money, possessions, or (figuratively) abundance, richness, (specially), valuable bestowment","derivation":"from the base of G4130 (πλήθω);","translit":"ploûtos","lemma":"πλοῦτος","kjv_def":"riches","pron":"ploo'-tos","pos":"Noun Masculine","thayer":"<ol><li>riches, wealth<ol type='a'><li>abundance of external possessions</li><li>fulness, abundance, plenitude</li><li>a good, i.e. that with which one is enriched</li></ol></li></ol>","xlit":"ploûtos"},"G3002":{"kjv_def":"Lebbæus","translit":"Lebbaîos","lemma":"Λεββαῖος","derivation":"of uncertain origin;","strongs_def":" Lebbæus, a Christian","pron":"leb-bah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lebbaeus = \"a man of heart\"</p><ol><li>one name of Jude, who was one of the twelve apostles</li></ol>","xlit":"Lebbaîos"},"G4303":{"strongs_def":" to be a witness in advance i.e. predict","derivation":"from G4253 (πρό) and G3143 (μαρτύρομαι);","lemma":"προμαρτύρομαι","translit":"promartýromai","kjv_def":"testify beforehand","pron":"prom-ar-too'-rom-ahee","pos":"Verb","thayer":"<ol><li>antetestor</li><li>to testify beforehand<ol type='a'><li>to make known, predict</li></ol></li></ol>","xlit":"promartýromai"},"G5495":{"strongs_def":" the hand (literally or figuratively (power); especially (by Hebraism) a means or instrument)","derivation":"perhaps from the base of G5494 (χειμών) in the sense of its congener the base of G5490 (χάσμα) (through the idea of hollowness for grasping);","lemma":"χείρ","translit":"cheír","kjv_def":"hand","pron":"khire","pos":"Noun Feminine","thayer":"<ol><li>by the help or agency of any one, by means of any one</li><li>fig. applied to God symbolising his might, activity, power<ol type='a'><li>in creating the universe</li><li>in upholding and preserving (God is present protecting and aiding one)</li><li>in punishing</li><li>in determining and controlling the destinies of men</li></ol></li></ol>","xlit":"cheír"},"G1889":{"strongs_def":" Epaphras, a Christian","derivation":"contracted from G1891 (Ἐπαφρόδιτος);","translit":"Epaphrâs","lemma":"Ἐπαφρᾶς","kjv_def":"Epaphras","pron":"ep-af-ras'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Epaphras = \"lovely\"</p><ol><li>a Christian man mentioned in Paul's epistles</li></ol>","xlit":"Epaphrâs"},"G226":{"kjv_def":"speak (tell) the truth","translit":"alētheúō","lemma":"ἀληθεύω","derivation":"from G227 (ἀληθής);","strongs_def":" to be true (in doctrine and profession)","pron":"al-ayth-yoo'-o","pos":"Verb","thayer":"<ol><li>to speak or tell the truth<ol type='a'><li>to teach the truth</li><li>to profess the truth</li></ol></li></ol>","xlit":"alētheúō"},"G3560":{"lemma":"νουθετέω","translit":"nouthetéō","kjv_def":"admonish, warn","strongs_def":" to put in mind, i.e. (by implication) to caution or reprove gently","derivation":"from the same as G3559 (νουθεσία);","pron":"noo-thet-eh'-o","pos":"Verb","thayer":"<ol><li>to admonish, warn, exhort</li></ol>","xlit":"nouthetéō"},"G4071":{"derivation":"neuter of a derivative of G4072 (πέτομαι);","strongs_def":" a flying animal, i.e. bird","kjv_def":"bird, fowl","lemma":"πετεινόν","translit":"peteinón","pron":"pet-i-non'","pos":"Noun Neuter","thayer":"<ol><li>flying, winged</li><li>flying or winged animals, birds<ol type='a'><li>the birds of the heaven, i.e. flying in the heaven (air)</li></ol></li></ol>","xlit":"peteinón"},"G435":{"lemma":"ἀνήρ","translit":"anḗr","kjv_def":"fellow, husband, man, sir","strongs_def":" a man (properly as an individual male)","derivation":"a primary word (compare G444 (ἄνθρωπος));","pron":"an'-ayr","pos":"Noun Masculine","thayer":"<ol><li>with reference to sex<ol type='a'><li>of a male</li><li>of a husband</li><li>of a betrothed or future husband</li></ol><li>with reference to age, and to distinguish an adult man from a boy</li><li>any male</li><li>used generically of a group of both men and women</li></ol>","xlit":"anḗr"},"G500":{"strongs_def":" an opponent of the Messiah","derivation":"from G473 (ἀντί) and G5547 (Χριστός);","translit":"antíchristos","lemma":"ἀντίχριστος","kjv_def":"antichrist","pron":"an-tee'-khris-tos","pos":"Noun Masculine","thayer":"<ol><li>the adversary of the Messiah</li></ol>","xlit":"antíchristos"},"G3781":{"strongs_def":" an ower, i.e. person indebted; figuratively, a delinquent; morally, a transgressor (against God)","derivation":"from G3784 (ὀφείλω);","translit":"opheilétēs","lemma":"ὀφειλέτης","kjv_def":"debtor, which owed, sinner","pron":"of-i-let'-ace","pos":"Noun Masculine","thayer":"<ol><li>one who owes another, a debtor<ol type='a'><li>one held by some obligation, bound by some duty</li><li>one who has not yet made amends to whom he has injured:<ol><li>one who owes God penalty or whom God can demand punishment as something due, i.e. a sinner</li></ol></li></ol></li></ol>","xlit":"opheilétēs"},"G2120":{"strongs_def":" a favorable occasion","derivation":"from G2121 (εὔκαιρος);","translit":"eukairía","lemma":"εὐκαιρία","kjv_def":"opportunity","pron":"yoo-kahee-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>seasonable time, opportunity</li></ol>","xlit":"eukairía"},"G581":{"translit":"apogenómenos","lemma":"ἀπογενόμενος","kjv_def":"being dead","strongs_def":" absent, i.e. deceased (figuratively, renounced)","derivation":"past participle of a compound of G575 (ἀπό) and G1096 (γίνομαι);","pron":"ap-og-en-om'-en-os","pos":"Verb","thayer":"<ol><li>to be removed from, depart</li><li>to die, to die to anything</li></ol>","xlit":"apogenómenos"},"G4260":{"derivation":"from G4253 (πρό) and the base of G939 (βάσις);","strongs_def":" to walk forward, i.e. advance (literally, or in years)","kjv_def":"+ be of a great age, go farther (on), be well stricken","lemma":"προβαίνω","translit":"probaínō","pron":"prob-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to go forwards, go on</li></ol>","xlit":"probaínō"},"G1683":{"lemma":"ἐμαυτοῦ","translit":"emautoû","kjv_def":"me, mine own (self), myself","strongs_def":" of myself so likewise the dative case , and accusative case ","derivation":"genitive case compound of G1700 (ἐμοῦ) and G846 (αὐτός);","pron":"em-ow-too'","thayer":"<ol><li>I, me, myself etc.</li></ol>","xlit":"emautoû"},"G5348":{"strongs_def":" to be beforehand, i.e. anticipate or precede; by extension, to have arrived at","derivation":"apparently a primary verb;","lemma":"φθάνω","translit":"phthánō","kjv_def":"(already) attain, come, prevent","pron":"fthan'-o","pos":"Verb","thayer":"<ol><li>to come before, precede, anticipate</li><li>to come to, arrive at</li><li>to reach, attain to</li></ol>","xlit":"phthánō"},"G1251":{"derivation":"middle voice from G1223 (διά) and G191 (ἀκούω);","strongs_def":" to hear throughout, i.e. patiently listen (to a prisoner's plea)","kjv_def":"hear","lemma":"διακούομαι","translit":"diakoúomai","pron":"dee-ak-oo'-om-ahee","pos":"Verb","thayer":"<ol><li>to hear one through, hear to the end, hear with care, hear fully</li></ol>","xlit":"diakoúomai"},"G4454":{"kjv_def":"colt","translit":"pōlos","lemma":"πῶλος","derivation":"apparently a primary word;","strongs_def":" a \"foal\" or \"filly\", i.e. (specially), a young ass","pron":"po'-los","pos":"Noun Masculine","thayer":"<ol><li>a colt, the young of a horse</li><li>a young creature<ol type='a'><li>of a young ass</li><li>an ass's colt</li></ol></li></ol>","xlit":"pōlos"},"G3995":{"strongs_def":" a wife's father","derivation":"of uncertain affinity;","lemma":"πενθερός","translit":"pentherós","kjv_def":"father in law","pron":"pen-ther-os'","pos":"Noun Masculine","thayer":"<ol><li>father-in-law, a wife's father</li></ol>","xlit":"pentherós"},"G4768":{"derivation":"from the same as G4767 (στυγνητός);","strongs_def":" to render gloomy, i.e. (by implication) glower (be overcast with clouds, or sombreness of speech)","kjv_def":"lower, be sad","translit":"stygnázō","lemma":"στυγνάζω","pron":"stoog-nad'-zo","pos":"Verb","thayer":"<ol><li>to be sad, sorrowful</li><li>metaphorically of the sky covered with clouds</li></ol>","xlit":"stygnázō"},"G69":{"translit":"agrypnéō","lemma":"ἀγρυπνέω","kjv_def":"watch","strongs_def":" to be sleepless, i.e. keep awake","derivation":"ultimately from G1 (Α) (as negative particle) and G5258 (ὕπνος);","pron":"ag-roop-neh'-o","pos":"Verb","thayer":"<ol><li>to be sleepless, keep awake, watch</li><li>to be circumspect, attentive, ready</li></ol>","xlit":"agrypnéō"},"G4322":{"kjv_def":"supply","lemma":"προσαναπληρόω","translit":"prosanaplēróō","derivation":"from G4314 (πρός) and G378 (ἀναπληρόω);","strongs_def":" to fill up further, i.e. furnish fully","pron":"pros-an-ap-lay-ro'-o","pos":"Verb","thayer":"<ol><li>to fill up by adding to</li></ol>","xlit":"prosanaplēróō"},"G299":{"translit":"ámōmos","lemma":"ἄμωμος","kjv_def":"without blame (blemish, fault, spot), faultless, unblamable","strongs_def":" unblemished (literally or figuratively)","derivation":"from G1 (Α) (as a negative particle) and G3470 (μῶμος);","pron":"am'-o-mos","pos":"Adjective","thayer":"<ol><li>without blemish<ol type='a'><li>as a sacrifice without spot or blemish</li></ol><li>morally: without blemish, faultless, unblameable</li></ol>","xlit":"ámōmos"},"G3011":{"derivation":"from a derivative of G2992 (λαός) and G2041 (ἔργον);","strongs_def":" a public servant, i.e. a functionary in the Temple or Gospel, or (genitive case) a worshipper (of God) or benefactor (of man)","kjv_def":"minister(-ed)","lemma":"λειτουργός","translit":"leitourgós","pron":"li-toorg-os'","pos":"Noun Masculine","thayer":"<ol><li>a public minister, a servant of the state</li><li>a minister, servant<ol type='a'><li>so of military labourers</li><li>of the temple<ol><li>of one busied with holy things</li><li>of a priest</li></ol><li>of the servants of a king</li></ol></li></ol>","xlit":"leitourgós"},"G5254":{"derivation":"from G5259 (ὑπό) and G2192 (ἔχω);","strongs_def":" to hold oneself under, i.e. endure with patience","kjv_def":"suffer","translit":"hypéchō","lemma":"ὑπέχω","pron":"hoop-ekh'-o","pos":"Verb","thayer":"<ol><li>to hold under, to put under, place underneath</li><li>metaphorically to sustain, undergo<ol type='a'><li>suffer punishment</li></ol></li></ol>","xlit":"hypéchō"},"G3425":{"derivation":"adverb from a primary (toil);","strongs_def":" with difficulty","kjv_def":"hardly","translit":"mógis","lemma":"μόγις","pron":"mog'-is","pos":"Adverb","thayer":"<ol><li>hardly, with difficulty</li></ol>","xlit":"mógis"},"G138":{"kjv_def":"choose","translit":"hairéomai","lemma":"αἱρέομαι","derivation":"probably akin to G142 (αἴρω);","strongs_def":" to take for oneself, i.e. to prefer","pron":"hahee-reh'-om-ahee","pos":"Verb","thayer":"<ol><li>to take for oneself, to prefer, choose</li><li>to choose by vote, elect to office</li></ol>","xlit":"hairéomai"},"G377":{"strongs_def":" to fall back, i.e. lie down, lean back","derivation":"from G303 (ἀνά) and G4098 (πίπτω);","translit":"anapíptō","lemma":"ἀναπίπτω","kjv_def":"lean, sit down (to meat)","pron":"an-ap-ip'-to","pos":"Verb","thayer":"<ol><li>to lie back, lie down</li><li>to recline at a table, to sit back</li></ol>","xlit":"anapíptō"},"G3157":{"derivation":"of Hebrew origin (H04977);","strongs_def":" Matthan (i.e. Mattan), an Israelite","kjv_def":"Matthan","lemma":"Ματθάν","translit":"Matthán","pron":"mat-than'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Matthan = \"gift\"</p><ol><li>one of Christ's ancestors</li></ol>","xlit":"Matthán"},"G1829":{"lemma":"ἐξέραμα","translit":"exérama","kjv_def":"vomit","strongs_def":" vomit, i.e. food disgorged","derivation":"from a comparative of G1537 (ἐκ) and a presumed (to spue);","pron":"ex-er'-am-ah","pos":"Noun Neuter","thayer":"<ol><li>vomit</li><li>what is cast out by vomiting</li></ol>","xlit":"exérama"},"G4159":{"strongs_def":" from which (as interrogative) or what (as relative) place, state, source or cause","derivation":"from the base of G4213 (πόσις) with enclitic adverb of origin;","translit":"póthen","lemma":"πόθεν","kjv_def":"whence","pron":"poth'-en","pos":"Adverb","thayer":"<ol><li>of place: from where, from what condition</li><li>of origin or source: from what author or giver</li><li>of cause: how is that?, how can that be?</li></ol>","xlit":"póthen"},"G5594":{"derivation":"a primary verb;","strongs_def":" to breathe (voluntarily but gently, thus differing on the one hand from G4154 (πνέω), which denotes properly a forcible respiration; and on the other from the base of G109 (ἀήρ), which refers properly to an inanimate breeze), i.e. (by implication, of reduction of temperature by evaporation) to chill (figuratively)","kjv_def":"wax cold","lemma":"ψύχω","translit":"psýchō","pron":"psoo'-kho","pos":"Verb","thayer":"<ol><li>to breathe, blow, cool by blowing</li><li>to be made or grow cool or cold</li><li>metaphorically of waning love</li></ol>","xlit":"psýchō"},"G3034":{"kjv_def":"stone","lemma":"λιθάζω","translit":"litházō","derivation":"from G3037 (λίθος);","strongs_def":" to lapidate","pron":"lith-ad'-zo","pos":"Verb","thayer":"<ol><li>to overwhelm or pelt with stones<ol type='a'><li>of stoning, a Jewish mode of punishment</li></ol><li>to pelt one with stones, in order either to wound or kill him</li></ol>","xlit":"litházō"},"G3894":{"strongs_def":" irritation","derivation":"from G3893 (παραπικραίνω);","lemma":"παραπικρασμός","translit":"parapikrasmós","kjv_def":"provocation","pron":"par-ap-ik-ras-mos'","pos":"Noun Masculine","thayer":"<ol><li>provocation</li></ol>","xlit":"parapikrasmós"},"G3622":{"kjv_def":"dispensation, stewardship","translit":"oikonomía","lemma":"οἰκονομία","derivation":"from G3623 (οἰκονόμος);","strongs_def":" administration (of a household or estate); specially, a (religious) \"economy\"","pron":"oy-kon-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the management of a household or of household affairs<ol type='a'><li>specifically, the management, oversight, administration, of other's property</li><li>the office of a manager or overseer, stewardship</li><li>administration, dispensation</li></ol></li></ol>","xlit":"oikonomía"},"G3847":{"strongs_def":" violation","derivation":"from G3845 (παραβαίνω);","translit":"parábasis","lemma":"παράβασις","kjv_def":"breaking, transgression","pron":"par-ab'-as-is","pos":"Noun Feminine","thayer":"<ol><li>a going over</li><li>metaphorically a disregarding, violating<ol type='a'><li>of the Mosaic law</li><li>the breach of a definite, promulgated, ratified law</li><li>to create transgressions, i.e. that sins might take on the character of transgressions, and thereby the consciousness of sin be intensified and the desire for redemption be aroused</li></ol></li></ol>","xlit":"parábasis"},"G2811":{"translit":"kléos","lemma":"κλέος","kjv_def":"glory","strongs_def":" renown (as if being called)","derivation":"from a shorter form of G2564 (καλέω);","pron":"kleh'-os","pos":"Noun Neuter","thayer":"<ol><li>rumour, report</li><li>glory, praise</li></ol>","xlit":"kléos"},"G1452":{"lemma":"ἐγγύτερον","translit":"engýteron","kjv_def":"nearer","strongs_def":" nearer","derivation":"neuter of the comparative of G1451 (ἐγγύς);","pron":"eng-goo'-ter-on","pos":"Adverb Neuter","thayer":"<ol><li>nearer</li></ol>","xlit":"engýteron"},"G1140":{"translit":"daimónion","lemma":"δαιμόνιον","kjv_def":"devil, god","strongs_def":" a dæmonic being; by extension a deity","derivation":"neuter of a derivative of G1142 (δαίμων);","pron":"dahee-mon'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>the divine power, deity, divinity</li><li>a spirit, a being inferior to God, superior to men</li><li>evil spirits or the messengers and ministers of the devil</li></ol>","xlit":"daimónion"},"G3792":{"translit":"ochlopoiéō","lemma":"ὀχλοποιέω","kjv_def":"gather a company","strongs_def":" to make a crowd, i.e. raise a public disturbance","derivation":"from G3793 (ὄχλος) and G4160 (ποιέω);","pron":"okh-lop-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to collect a crowd, gather the people together</li></ol>","xlit":"ochlopoiéō"},"G3650":{"kjv_def":"all, altogether, every whit, + throughout, whole","lemma":"ὅλος","translit":"hólos","derivation":"a primary word;","strongs_def":" \"whole\" or \"all\", i.e. complete (in extent, amount, time or degree), especially (neuter) as noun or adverb","pron":"hol'-os","pos":"Adjective","thayer":"<ol><li>all, whole, completely</li></ol>","xlit":"hólos"},"G3146":{"strongs_def":" to flog (literally or figuratively)","derivation":"from G3148 (μάστιξ);","lemma":"μαστιγόω","translit":"mastigóō","kjv_def":"scourge","pron":"mas-tig-o'-o","pos":"Verb","thayer":"<ol><li>to scourge</li></ol>","xlit":"mastigóō"},"G245":{"derivation":"from G243 (ἄλλος);","strongs_def":" another's, i.e. not one's own; by extension foreign, not akin, hostile","kjv_def":"alien, (an-)other (man's, men's), strange(-r)","lemma":"ἀλλότριος","translit":"allótrios","pron":"al-lot'-ree-os","pos":"Adjective","thayer":"<ol><li>belonging to another</li><li>foreign, strange, not of one's own family, alien, an enemy</li></ol>","xlit":"allótrios"},"G2573":{"derivation":"adverb from G2570 (καλός);","strongs_def":" well (usually morally)","kjv_def":"(in a) good (place), honestly, + recover, (full) well","lemma":"καλῶς","translit":"kalōs","pron":"kal-oce'","pos":"Adverb","thayer":"<ol><li>beautifully, finely, excellently, well<ol type='a'><li>rightly, so that there shall be no room for blame, well, truly</li><li>excellently, nobly, commendably</li><li>honourably, in honour<ol><li>in a good place, comfortable</li></ol><li>to speak well of one, to do good</li><li>to be well (of those recovering health)</li></ol></li></ol>","xlit":"kalōs"},"G3643":{"derivation":"from a compound of G3641 (ὀλίγος) and (\"care\");","strongs_def":" to have little regard for, i.e. to disesteem","kjv_def":"despise","lemma":"ὀλιγωρέω","translit":"oligōréō","pron":"ol-ig-o-reh'-o","pos":"Verb","thayer":"<ol><li>to care little for, regard lightly, make small account</li></ol>","xlit":"oligōréō"},"G4330":{"derivation":"from G4314 (πρός) and G1439 (ἐάω);","strongs_def":" to permit further progress","kjv_def":"suffer","translit":"proseáō","lemma":"προσεάω","pron":"pros-eh-ah'-o","pos":"Verb","thayer":"<ol><li>to permit one to approach or arrive</li></ol>","xlit":"proseáō"},"G1557":{"kjv_def":"(a-, re-)venge(-ance), punishment","translit":"ekdíkēsis","lemma":"ἐκδίκησις","derivation":"from G1556 (ἐκδικέω);","strongs_def":" vindication, retribution","pron":"ek-dik'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>a revenging, vengeance, punishment</li></ol>","xlit":"ekdíkēsis"},"G2173":{"derivation":"from G2095 (εὖ) and G5543 (χρηστός);","strongs_def":" easily used, i.e. useful","kjv_def":"profitable, meet for use","lemma":"εὔχρηστος","translit":"eúchrēstos","pron":"yoo'-khrays-tos","pos":"Adjective","thayer":"<ol><li>easy to make use of, useful</li></ol>","xlit":"eúchrēstos"},"G3386":{"kjv_def":"how much more","translit":"mḗtige","lemma":"μήτιγε","derivation":"from G3385 (μήτι) and G1065 (γέ);","strongs_def":" not at all then, i.e. not to say (the rather still)","pron":"may'-tig-eh","thayer":"<ol><li>to say nothing of, not to mention<ol type='a'><li>much less</li><li>much more, much rather</li></ol></li></ol>","xlit":"mḗtige"},"G4012":{"lemma":"περί","translit":"perí","kjv_def":"(there-)about, above, against, at, on behalf of, X and his company, which concern, (as) concerning, for, X how it will go with, ((there-, where-)) of, on, over, pertaining (to), for sake, X (e-)state, (as) touching, (where-)by (in), with","strongs_def":" properly, through (all over), i.e. around; figuratively with respect to; used in various applications, of place, cause or time (with the genitive case denoting the subject or occasion or superlative point; with the accusative case the locality, circuit, matter, circumstance or general period)","derivation":"from the base of G4008 (πέραν);","pron":"per-ee'","pos":"Preposition","thayer":"<ol><li>about, concerning, on account of, because of, around, near</li></ol>","xlit":"perí"},"G1001":{"derivation":"from G1002 (βολίς);","strongs_def":" to heave the lead","kjv_def":"sound","translit":"bolízō","lemma":"βολίζω","pron":"bol-id'-zo","pos":"Verb","thayer":"<ol><li>to heave the lead, take a sounding<ol type='a'><li>a line and plummet with which mariners sound the depth of the sea</li></ol></li></ol>","xlit":"bolízō"},"G2601":{"translit":"katabibázō","lemma":"καταβιβάζω","kjv_def":"bring (thrust) down","strongs_def":" to cause to go down, i.e. precipitate","derivation":"from G2596 (κατά) and a derivative of the base of G939 (βάσις);","pron":"kat-ab-ib-ad'-zo","pos":"Verb","thayer":"<ol><li>to cause to go down</li><li>to bring down</li><li>to cast down, thrust down</li></ol>","xlit":"katabibázō"},"G2638":{"lemma":"καταλαμβάνω","translit":"katalambánō","kjv_def":"apprehend, attain, come upon, comprehend, find, obtain, perceive, (over-)take","strongs_def":" to take eagerly, i.e. seize, possess, etc. (literally or figuratively)","derivation":"from G2596 (κατά) and G2983 (λαμβάνω);","pron":"kat-al-am-ban'-o","pos":"Verb","thayer":"<ol><li>to lay hold of<ol type='a'><li>to lay hold of so as to make one's own, to obtain, attain to, to make one's own, to take into one's self, appropriate</li><li>to seize upon, take possession of<ol><li>of evils overtaking one, of the last day overtaking the wicked with destruction, of a demon about to torment one</li><li>in a good sense, of Christ by his holy power and influence laying hold of the human mind and will, in order to prompt and govern it</li></ol><li>to detect, catch</li><li>to lay hold of with the mind<ol><li>to understand, perceive, learn, comprehend</li></ol></li></ol></li></ol>","xlit":"katalambánō"},"G3802":{"lemma":"παγιδεύω","translit":"pagideúō","kjv_def":"entangle","strongs_def":" to ensnare (figuratively)","derivation":"from G3803 (παγίς);","pron":"pag-id-yoo'-o","pos":"Verb","thayer":"<ol><li>to ensnare, entrap<ol type='a'><li>of birds</li></ol><li>metaphorically of the attempt to elicit from one some remark which can be turned into an accusation against him</li></ol>","xlit":"pagideúō"},"G2679":{"derivation":"from G2596 (κατά) and G4626 (σκάπτω);","strongs_def":" to undermine, i.e. (by implication) destroy","kjv_def":"dig down, ruin","translit":"kataskáptō","lemma":"κατασκάπτω","pron":"kat-as-kap'-to","pos":"Verb","thayer":"<ol><li>to dig under, dig down, demolish, destroy</li></ol>","xlit":"kataskáptō"},"G5612":{"strongs_def":" to \"roar\"","derivation":"middle voice of an apparently primary verb;","lemma":"ὠρύομαι","translit":"ōrýomai","kjv_def":"roar","pron":"o-roo'-om-ahee","pos":"Verb","thayer":"<ol><li>to roar, to howl (of a lion, wolf, dog, and other beasts)<ol type='a'><li>of men, to raise a loud and inarticulate cry: either of grief, or of joy</li></ol><li>to sing with a loud voice</li></ol>","xlit":"ōrýomai"},"G796":{"kjv_def":"lightning, bright shining","translit":"astrapḗ","lemma":"ἀστραπή","derivation":"from G797 (ἀστράπτω);","strongs_def":" lightning; by analogy, glare","pron":"as-trap-ay'","pos":"Noun Feminine","thayer":"<ol><li>lightning<ol type='a'><li>of the gleam of a lamp</li></ol></li></ol>","xlit":"astrapḗ"},"G2985":{"derivation":"from G2989 (λάμπω);","strongs_def":" a \"lamp\" or flambeau","kjv_def":"lamp, light, torch","lemma":"λαμπάς","translit":"lampás","pron":"lam-pas'","pos":"Noun Feminine","thayer":"<ol><li>a torch</li><li>a lamp, the flame of which is fed with oil</li></ol>","xlit":"lampás"},"G2012":{"translit":"epítropos","lemma":"ἐπίτροπος","kjv_def":"steward, tutor","strongs_def":" a commissioner, i.e. domestic manager, guardian","derivation":"from G1909 (ἐπί) and G5158 (τρόπος) (in the sense of G2011 (ἐπιτροπή));","pron":"ep-it'-rop-os","pos":"Noun Masculine","thayer":"<ol><li>one to whose care or honour anything has been instructed<ol type='a'><li>a curator, a guardian</li><li>a steward or manager of a household, or of lands<ol><li>overseer</li></ol><li>one who has the care and tutelage of children, either where the father is dead (a guardian of minors), or where the father is still alive</li></ol></li></ol>","xlit":"epítropos"},"G1458":{"strongs_def":" to call in (as a debt or demand), i.e. bring to account (charge, criminate, etc.)","derivation":"from G1722 (ἐν) and G2564 (καλέω);","lemma":"ἐγκαλέω","translit":"enkaléō","kjv_def":"accuse, call in question, implead, lay to the charge","pron":"eng-kal-eh'-o","pos":"Verb","thayer":"<ol><li>to come forward as accuser against, bring charge against</li><li>to be accused</li></ol>","xlit":"enkaléō"},"G4453":{"strongs_def":" to barter (as a pedlar), i.e. to sell","derivation":"probably ultimately from (to be busy, to trade);","translit":"pōléō","lemma":"πωλέω","kjv_def":"sell, whatever is sold","pron":"po-leh'-o","pos":"Verb","thayer":"<ol><li>to barter, to sell</li><li>sellers</li></ol>","xlit":"pōléō"},"G2383":{"strongs_def":" Jairus (i.e. Jair), an Israelite","derivation":"of Hebrew origin (H02971);","translit":"Iáeiros","lemma":"Ἰάειρος","kjv_def":"Jairus","pron":"ee-ah'-i-ros","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jairus = \"whom God enlightens\"</p><ol><li>a ruler of a synagogue, probably near the western shore of the Sea of Galilee</li></ol>","xlit":"Iáeiros"},"G5462":{"derivation":"from G5461 (φωτίζω);","strongs_def":" illumination (figuratively)","kjv_def":"light","translit":"phōtismós","lemma":"φωτισμός","pron":"fo-tis-mos'","pos":"Noun Masculine","thayer":"<ol><li>the act of enlightening, illumination</li><li>brightness, bright light</li></ol>","xlit":"phōtismós"},"G3642":{"strongs_def":" little-spirited, i.e. faint-hearted","derivation":"from G3641 (ὀλίγος) and G6590;","translit":"oligópsychos","lemma":"ὀλιγόψυχος","kjv_def":"feebleminded","pron":"ol-ig-op'-soo-khos","pos":"Adjective","thayer":"<ol><li>fainthearted</li></ol>","xlit":"oligópsychos"},"G1073":{"kjv_def":"be full","translit":"gémō","lemma":"γέμω","derivation":"a primary verb;","strongs_def":" to swell out, i.e. be full","pron":"ghem'-o","pos":"Verb","thayer":"<ol><li>to be full, filled, full</li></ol>","xlit":"gémō"},"G2210":{"translit":"zēmióō","lemma":"ζημιόω","kjv_def":"be cast away, receive damage, lose, suffer loss","strongs_def":" to injure, i.e. (reflexively or passively) to experience detriment","derivation":"from G2209 (ζημία);","pron":"dzay-mee-o'-o","pos":"Verb","thayer":"<ol><li>to affect with damage, do damage to</li><li>to sustain damage, to receive injury, suffer loss</li></ol>","xlit":"zēmióō"},"G4934":{"translit":"syntíthemai","lemma":"συντίθεμαι","kjv_def":"agree, assent, covenant","strongs_def":" to place jointly, i.e. (figuratively) to consent (bargain, stipulate), concur","derivation":"middle voice from G4862 (σύν) and G5087 (τίθημι);","pron":"soon-tith'-em-ahee","pos":"Verb","thayer":"<ol><li>to put together with, to place together, to join together<ol type='a'><li>to place in one's mind<ol><li>to resolve, determine</li><li>to make an arrangement, to engage</li></ol><li>to assent to, to agree to</li></ol></li></ol>","xlit":"syntíthemai"},"G2421":{"strongs_def":" Jessæ (i.e. Jishai), an Israelite","derivation":"of Hebrew origin (H03448);","lemma":"Ἰεσσαί","translit":"Iessaí","kjv_def":"Jesse","pron":"es-es-sah'-ee","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jesse = \"wealthy\"</p><ol><li>the father of David the king</li></ol>","xlit":"Iessaí"},"G851":{"kjv_def":"cut (smite) off, take away","lemma":"ἀφαιρέω","translit":"aphairéō","derivation":"from G575 (ἀπό) and G138 (αἱρέομαι);","strongs_def":" to remove (literally or figuratively)","pron":"af-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to take from, take away, remove, carry off</li><li>to cut off</li></ol>","xlit":"aphairéō"},"G2893":{"lemma":"κουφίζω","translit":"kouphízō","kjv_def":"lighten","strongs_def":" to unload","derivation":"from (light in weight);","pron":"koo-fid'-zo","pos":"Verb","thayer":"<ol><li>to be light</li><li>to lighten<ol type='a'><li>a ship by throwing the cargo overboard</li></ol></li></ol>","xlit":"kouphízō"},"G601":{"kjv_def":"reveal","lemma":"ἀποκαλύπτω","translit":"apokalýptō","derivation":"from G575 (ἀπό) and G2572 (καλύπτω);","strongs_def":" to take off the cover, i.e. disclose","pron":"ap-ok-al-oop'-to","pos":"Verb","thayer":"<ol><li>to uncover, lay open what has been veiled or covered up<ol type='a'><li>disclose, make bare</li></ol><li>to make known, make manifest, disclose what before was unknown</li></ol>","xlit":"apokalýptō"},"G1330":{"kjv_def":"come, depart, go (about, abroad, everywhere, over, through, throughout), pass (by, over, through, throughout), pierce through, travel, walk through","lemma":"διέρχομαι","translit":"diérchomai","derivation":"from G1223 (διά) and G2064 (ἔρχομαι);","strongs_def":" to traverse (literally)","pron":"dee-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go through, pass through<ol type='a'><li>to go, walk, journey, pass through a place</li><li>to travel the road which leads through a place, go, pass, travel through a region</li></ol><li>to go different places<ol type='a'><li>of people, to go abroad</li><li>of a report, to spread, go abroad</li></ol></li></ol>","xlit":"diérchomai"},"G4883":{"derivation":"from G4862 (σύν) and a derivative of a compound of G719 (ἁρμός) and G3004 (λέγω) (in its original sense of laying);","strongs_def":" to render close-jointed together, i.e. organize compactly","kjv_def":"be fitly framed (joined) together","translit":"synarmologéō","lemma":"συναρμολογέω","pron":"soon-ar-mol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to join closely together</li><li>to frame together<ol type='a'><li>parts of a building</li><li>the members of the body</li></ol></li></ol>","xlit":"synarmologéō"},"G5569":{"translit":"pseudádelphos","lemma":"ψευδάδελφος","kjv_def":"false brethren","strongs_def":" a spurious brother, i.e. pretended associate","derivation":"from G5571 (ψευδής) and G80 (ἀδελφός);","pron":"psyoo-dad'-el-fos","pos":"Noun Masculine","thayer":"<ol><li>a false brother</li><li>one who ostentatiously professes to be a Christian, but is destitute of Christian knowledge and piety</li></ol>","xlit":"pseudádelphos"},"G2724":{"lemma":"κατηγορία","translit":"katēgoría","kjv_def":"accusation (X -ed)","strongs_def":" a complaint (\"category\"), i.e. criminal charge","derivation":"from G2725 (κατήγορος);","pron":"kat-ay-gor-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>accusation, charge</li></ol>","xlit":"katēgoría"},"G5339":{"derivation":"of uncertain affinity;","strongs_def":" to be chary of, i.e. (subjectively) to abstain or (objectively) to treat leniently","kjv_def":"forbear, spare","lemma":"φείδομαι","translit":"pheídomai","pron":"fi'-dom-ahee","pos":"Verb","thayer":"<ol><li>to spare</li><li>to abstain</li></ol>","xlit":"pheídomai"},"G4628":{"lemma":"σκέλος","translit":"skélos","kjv_def":"leg","strongs_def":" through the idea of leanness); the leg (as lank)","derivation":"apparently from (to parch;","pron":"skel'-os","pos":"Noun Neuter","thayer":"<ol><li>the leg, from the hip to the toes inclusive</li></ol>","xlit":"skélos"},"G4699":{"strongs_def":" a \"sponge\"","derivation":"perhaps of foreign origin;","lemma":"σπόγγος","translit":"spóngos","kjv_def":"spunge","pron":"spong'-gos","pos":"Noun Masculine","thayer":"<ol><li>sponge</li></ol>","xlit":"spóngos"},"G4502":{"translit":"Rhoubḗn","lemma":"Ῥουβήν","kjv_def":"Reuben","strongs_def":" Ruben (i.e. Reuben), an Israelite","derivation":"of Hebrew origin (H07205);","pron":"hroo-bane'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Reuben = \"behold a son\"</p><ol><li>Jacob's firstborn child by Leah</li></ol>","xlit":"Rhoubḗn"},"G2639":{"strongs_def":" to lay down, i.e. (figuratively) to enrol","derivation":"from G2596 (κατά) and G3004 (λέγω) (in its original meaning);","translit":"katalégō","lemma":"καταλέγω","kjv_def":"take into the number","pron":"kat-al-eg'-o","pos":"Verb","thayer":"<ol><li>to lay down, to lie down</li><li>to narrate at length, recount, set forth</li><li>to set down in a list or register, to enrol<ol type='a'><li>of soldiers</li><li>of those widows who held a prominent place in the church and exercised a certain superintendence over the rest of the women, and had charge of the widows and orphans supported at the public expense</li></ol></li></ol>","xlit":"katalégō"},"G5511":{"kjv_def":"robe","translit":"chlamýs","lemma":"χλαμύς","derivation":"of uncertain derivation;","strongs_def":" a military cloak","pron":"khlam-ooce'","pos":"Noun Feminine","thayer":"<ol><li>a chalamys, an outer garment usually worn over the tunic</li><li>a kind of short cloak worn by soldiers, military officers, magistrates, kings, emperors</li></ol>","xlit":"chlamýs"},"G2934":{"lemma":"κτῆνος","translit":"ktēnos","kjv_def":"beast","strongs_def":" property, i.e. (specially) a domestic animal","derivation":"from G2932 (κτάομαι);","pron":"ktay'-nos","pos":"Noun Neuter","thayer":"<ol><li>a beast<ol type='a'><li>especially a beast of burden</li><li>used for four legged animals as opposed to fishes and birds</li></ol></li></ol>","xlit":"ktēnos"},"G294":{"derivation":"from the base of G297 (ἀμφότερος) and (to invest);","strongs_def":" to enrobe","kjv_def":"clothe","translit":"amphiénnymi","lemma":"ἀμφιέννυμι","pron":"am-fee-en'-noo-mee","pos":"Verb","thayer":"<ol><li>to put on, to clothe</li></ol>","xlit":"amphiénnymi"},"G53":{"kjv_def":"chaste, clean, pure","lemma":"ἁγνός","translit":"hagnós","derivation":"from the same as G40 (ἅγιος);","strongs_def":" properly, clean, i.e. (figuratively) innocent, modest, perfect","pron":"hag-nos'","pos":"Adjective","thayer":"<ol><li>exciting reverence, venerable, sacred</li><li>pure<ol type='a'><li>pure from carnality, chaste, modest</li><li>pure from every fault, immaculate</li><li>clean</li></ol></li></ol>","xlit":"hagnós"},"G729":{"strongs_def":" unsewed, i.e. of a single piece","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of the same as G4476 (ῥαφίς);","lemma":"ἄῤῥαφος","translit":"árrhaphos","kjv_def":"without seam","pron":"ar'-hhraf-os","pos":"Noun Masculine","thayer":"<ol><li>not sewed together, without a seam</li></ol>","xlit":"árrhaphos"},"G1394":{"lemma":"δόσις","translit":"dósis","kjv_def":"gift, giving","strongs_def":" a giving; by implication, (concretely) a gift","derivation":"from the base of G1325 (δίδωμι);","pron":"dos'-is","pos":"Noun Feminine","thayer":"<ol><li>a giving</li><li>a gift</li></ol>","xlit":"dósis"},"G4782":{"derivation":"from G4862 (σύν) and G2597 (καταβαίνω);","strongs_def":" to descend in company with","kjv_def":"go down with","lemma":"συγκαταβαίνω","translit":"synkatabaínō","pron":"soong-kat-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to go down with<ol type='a'><li>of those who descend from a high place to a lower place as from Jerusalem to Caesarea</li></ol></li></ol>","xlit":"synkatabaínō"},"G259":{"lemma":"ἅλωσις","translit":"hálōsis","strongs_def":" capture, be taken. ","derivation":"from a collateral form of G138 (αἱρέομαι);","pron":"hal'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>a catching, capture, to be taken</li></ol>","xlit":"hálōsis"},"G255":{"kjv_def":"unprofitable","lemma":"ἀλυσιτελής","translit":"alysitelḗs","derivation":"from G1 (Α) (as a negative particle) and the base of G3081 (λυσιτελεῖ);","strongs_def":" gainless, i.e. (by implication) pernicious","pron":"al-oo-sit-el-ace'","pos":"Adjective","thayer":"<ol><li>unprofitable, hurtful, pernicious</li></ol>","xlit":"alysitelḗs"},"G4073":{"strongs_def":" a (mass of) rock (literally or figuratively)","derivation":"feminine of the same as G4074 (Πέτρος);","lemma":"πέτρα","translit":"pétra","kjv_def":"rock","pron":"pet'-ra","pos":"Noun Feminine","thayer":"<ol><li>a rock, cliff or ledge<ol type='a'><li>a projecting rock, crag, rocky ground</li><li>a rock, a large stone</li><li>metaphorically a man like a rock, by reason of his firmness and strength of soul</li></ol></li></ol>","xlit":"pétra"},"G1388":{"derivation":"from an obsolete primary verb, (probably meaning to decoy;","strongs_def":" compare G1185 (δελεάζω)); a trick (bait), i.e. (figuratively) wile","kjv_def":"craft, deceit, guile, subtilty","lemma":"δόλος","translit":"dólos","pron":"dol'-os","pos":"Masculine Neuter","thayer":"<ol><li>craft, deceit, guile</li></ol>","xlit":"dólos"},"G189":{"strongs_def":" hearing (the act, the sense or the thing heard)","derivation":"from G191 (ἀκούω);","lemma":"ἀκοή","translit":"akoḗ","kjv_def":"audience, ear, fame, which ye heard, hearing, preached, report, rumor","pron":"ak-o-ay'","pos":"Noun Feminine","thayer":"<ol><li>the sense of hearing</li><li>the organ of hearing, the ear</li><li>the thing heard<ol type='a'><li>instruction, namely oral<ol><li>of preaching the gospel</li></ol><li>hearsay, report or rumour</li></ol></li></ol>","xlit":"akoḗ"},"G2983":{"translit":"lambánō","lemma":"λαμβάνω","kjv_def":"accept, + be amazed, assay, attain, bring, X when I call, catch, come on (X unto), + forget, have, hold, obtain, receive (X after), take (away, up)","strongs_def":" while G138 (αἱρέομαι) is more violent, to seize or remove))","derivation":"a prolonged form of a primary verb, which is use only as an alternate in certain tenses; to take (in very many applications, literally and figuratively (properly objective or active, to get hold of; whereas G1209 (δέχομαι) is rather subjective or passive, to have offered to one;","pron":"lam-ban'-o","pos":"Verb","thayer":"<ol><li>to take<ol type='a'><li>to take with the hand, lay hold of, any person or thing in order to use it<ol><li>to take up a thing to be carried</li><li>to take upon one's self</li></ol><li>to take in order to carry away<ol><li>without the notion of violence, i,e to remove, take away</li></ol><li>to take what is one's own, to take to one's self, to make one's own<ol><li>to claim, procure, for one's self<ol type='a'><li>to associate with one's self as companion, attendant</li></ol><li>of that which when taken is not let go, to seize, to lay hold of, apprehend</li><li>to take by craft (our catch, used of hunters, fisherman, etc.), to circumvent one by fraud</li><li>to take to one's self, lay hold upon, take possession of, i.e. to appropriate to one's self</li><li>catch at, reach after, strive to obtain</li><li>to take a thing due, to collect, gather (tribute)</li></ol><li>to take<ol><li>to admit, receive</li><li>to receive what is offered</li><li>not to refuse or reject</li><li>to receive a person, give him access to one's self<ol type='a'><li>to regard any one's power, rank, external circumstances, and on that account to do some injustice or neglect something</li></ol></li></ol><li>to take, to choose, select</li><li>to take beginning, to prove anything, to make a trial of, to experience</li></ol><li>to receive (what is given), to gain, get, obtain, to get back</li></ol>","xlit":"lambánō"},"G964":{"derivation":"of Chaldee origin (compare H01004 and H02617);","strongs_def":" house of kindness; Beth-esda, a pool in Jerusalem","kjv_def":"Bethesda","lemma":"Βηθεσδά","translit":"Bēthesdá","pron":"bay-thes-dah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethesda = \"house of mercy\" or \"flowing water\"</p><ol><li>the name of a pool near the sheep-gate at Jerusalem, whose waters had curative powers</li></ol>","xlit":"Bēthesdá"},"G1709":{"kjv_def":"breathe","lemma":"ἐμπνέω","translit":"empnéō","derivation":"from G1722 (ἐν) and G4154 (πνέω);","strongs_def":" to inhale, i.e. (figuratively) to be animated by (bent upon)","pron":"emp-neh'-o","pos":"Verb","thayer":"<ol><li>to breathe in or on</li><li>to inhale<ol type='a'><li>threatenings and slaughter were so to speak the element from which he drew his breath</li></ol></li></ol>","xlit":"empnéō"},"G2773":{"lemma":"κερματιστής","translit":"kermatistḗs","kjv_def":"changer of money","strongs_def":" a handler of coins, i.e. money-broker","derivation":"from a derivative of G2772 (κέρμα);","pron":"ker-mat-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>a money changer, money broker</li></ol>","xlit":"kermatistḗs"},"G2156":{"kjv_def":"decently, honestly","lemma":"εὐσχημόνως","translit":"euschēmónōs","derivation":"adverb from G2158 (εὐσχήμων);","strongs_def":" decorously","pron":"yoo-skhay-mon'-ose","pos":"Adverb","thayer":"<ol><li>in a seemly manner, decently</li></ol>","xlit":"euschēmónōs"},"G2458":{"kjv_def":"Junias","translit":"Iouniâs","lemma":"Ἰουνιᾶς","derivation":"of Latin origin;","strongs_def":" Junias, a Christian","pron":"ee-oo-nee'-as","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Junia = \"youthful\"</p><ol><li>a Christian woman at Rome, mentioned by Paul as one of his kinsfolk and fellow prisoners</li></ol>","xlit":"Iouniâs"},"G2871":{"kjv_def":"slaughter","lemma":"κοπή","translit":"kopḗ","derivation":"from G2875 (κόπτω);","strongs_def":" cutting, i.e. carnage","pron":"kop-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act of cutting, a cut</li><li>a cutting in pieces, slaughter</li></ol>","xlit":"kopḗ"},"G635":{"strongs_def":" to lead astray (figuratively); passively, to stray (from truth)","derivation":"from G575 (ἀπό) and G4105 (πλανάω);","translit":"apoplanáō","lemma":"ἀποπλανάω","kjv_def":"err, seduce","pron":"ap-op-lan-ah'-o","pos":"Verb","thayer":"<ol><li>to cause to go astray</li><li>to lead away from the truth to error</li><li>to go astray, stray away from</li></ol>","xlit":"apoplanáō"},"G2760":{"strongs_def":" a centurion, i.e. captain of one hundred soldiers","derivation":"of Latin origin;","lemma":"κεντυρίων","translit":"kentyríōn","kjv_def":"centurion","pron":"ken-too-ree'-ohn","pos":"Noun Masculine","thayer":"<ol><li>centurion, an officer in the Roman army</li></ol>","xlit":"kentyríōn"},"G5426":{"strongs_def":" to exercise the mind, i.e. entertain or have a sentiment or opinion; by implication, to be (mentally) disposed (more or less earnestly in a certain direction); intensively, to interest oneself in (with concern or obedience)","derivation":"from G5424 (φρήν);","lemma":"φρονέω","translit":"phronéō","kjv_def":"set the affection on, (be) care(-ful), (be like-, + be of one, + be of the same, + let this) mind(-ed), regard, savour, think","pron":"fron-eh'-o","pos":"Verb","thayer":"<ol><li>to have understanding, be wise</li><li>to feel, to think<ol type='a'><li>to have an opinion of one's self, think of one's self, to be modest, not let one's opinion (though just) of himself exceed the bounds of modesty</li><li>to think or judge what one's opinion is</li><li>to be of the same mind, i.e. agreed together, cherish the same views, be harmonious</li></ol><li>to direct one's mind to a thing, to seek, to strive for<ol type='a'><li>to seek one's interest or advantage</li><li>to be of one's party, side with him (in public affairs)</li></ol></li></ol>","xlit":"phronéō"},"G2917":{"kjv_def":"avenge, condemned, condemnation, damnation, + go to law, judgment","lemma":"κρίμα","translit":"kríma","derivation":"from G2919 (κρίνω);","strongs_def":" a decision (the function or the effect, for or against (\"crime\"))","pron":"kree'-mah","pos":"Noun Neuter","thayer":"<ol><li>a decree, judgments</li><li>judgment<ol type='a'><li>condemnation of wrong, the decision (whether severe or mild) which one passes on the faults of others</li><li>in a forensic sense<ol><li>the sentence of a judge</li><li>the punishment with which one is sentenced</li><li>condemnatory sentence, penal judgment, sentence</li></ol></li></ol><li>a matter to be judicially decided, a lawsuit, a case in court</li></ol>","xlit":"kríma"},"G2519":{"strongs_def":" a guide, i.e. (figuratively) a teacher","derivation":"from a compound of G2596 (κατά) and G2233 (ἡγέομαι);","lemma":"καθηγητής","translit":"kathēgētḗs","kjv_def":"master","pron":"kath-ayg-ay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a guide</li><li>a master, teacher</li></ol>","xlit":"kathēgētḗs"},"G2212":{"derivation":"of uncertain affinity;","strongs_def":" to seek (literally or figuratively); specially, (by Hebraism) to worship (God), or (in a bad sense) to plot (against life)","kjv_def":"be (go) about, desire, endeavour, enquire (for), require, (X will) seek (after, for, means)","lemma":"ζητέω","translit":"zētéō","pron":"dzay-teh'-o","pos":"Verb","thayer":"<ol><li>to seek in order to find<ol type='a'><li>to seek a thing</li><li>to seek [in order to find out] by thinking, meditating, reasoning, to enquire into</li><li>to seek after, seek for, aim at, strive after</li></ol><li>to seek, i.e. require, demand<ol type='a'><li>to crave, demand something from someone</li></ol></li></ol>","xlit":"zētéō"},"G4179":{"kjv_def":"manifold more","translit":"pollaplasíōn","lemma":"πολλαπλασίων","derivation":"from G4183 (πολύς) and probably a derivative of G4120 (πλέκω);","strongs_def":" manifold, i.e. (neuter as noun) very much more","pron":"pol-lap-las-ee'-ohn","pos":"Adverb","thayer":"<ol><li>manifold, much, more</li></ol>","xlit":"pollaplasíōn"},"G2010":{"translit":"epitrépō","lemma":"ἐπιτρέπω","kjv_def":"give leave (liberty, license), let, permit, suffer","strongs_def":" to turn over (transfer), i.e. allow","derivation":"from G1909 (ἐπί) and the base of G5157 (τροπή);","pron":"ep-ee-trep'-o","pos":"Verb","thayer":"<ol><li>to turn to, transfer, commit, instruct</li><li>to permit, allow, give leave</li></ol>","xlit":"epitrépō"},"G4859":{"lemma":"σύμφωνος","translit":"sýmphōnos","kjv_def":" consent","strongs_def":" sounding together (alike), i.e. (figuratively) accordant (neuter as noun, agreement)","derivation":"from G4862 (σύν) and G5456 (φωνή);","pron":"soom'-fo-nos","pos":"Adjective","thayer":"<ol><li>harmonious, accordant, agreeing</li><li>thing agreed upon, compact</li></ol>","xlit":"sýmphōnos"},"G2410":{"lemma":"Ἱεριχώ","translit":"Hierichṓ","kjv_def":"Jericho","strongs_def":" Jericho, a place in Palestine","derivation":"of Hebrew origin (H03405);","pron":"hee-er-ee-kho'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Jericho = \"place of fragrance\"</p><ol><li>a noted city, abounding in balsam, honey, cyprus, myrobalanus, roses and other fragrant products. It was near the north shore of the Dead Sea in the tribe of Benjamin, between Jerusalem and the Jordan River</li></ol>","xlit":"Hierichṓ"},"G4413":{"kjv_def":"before, beginning, best, chief(-est), first (of all), former","translit":"prōtos","lemma":"πρῶτος","derivation":"contracted superlative of G4253 (πρό);","strongs_def":" foremost (in time, place, order or importance)","pron":"pro'-tos","pos":"Adjective","thayer":"<ol><li>first in time or place<ol type='a'><li>in any succession of things or persons</li></ol><li>first in rank<ol type='a'><li>influence, honour</li><li>chief</li><li>principal</li></ol><li>first, at the first</li></ol>","xlit":"prōtos"},"G1346":{"lemma":"δικαίως","translit":"dikaíōs","kjv_def":"justly, (to) righteously(-ness)","strongs_def":" equitably","derivation":"adverb from G1342 (δίκαιος);","pron":"dik-ah'-yoce","pos":"Adverb","thayer":"<ol><li>just, agreeably to right</li><li>properly, as is right</li><li>uprightly, agreeable to the law of rectitude</li></ol>","xlit":"dikaíōs"},"G5403":{"lemma":"Φοινίκη","translit":"Phoiníkē","kjv_def":"Phenice, Phenicia","strongs_def":" palm-country; Phœnice (or Phœnicia), a region of Palestine","derivation":"from G5404 (φοῖνιξ);","pron":"foy-nee'-kay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Phenicia = \"land of palm trees\"</p><ol><li>a territory of the province of Syria, situated on the coast of the Mediterranean between the river Eleutherus and the promontory of Carmel, some 30 miles (50 km) long and 3 (5 km) broad</li></ol>","xlit":"Phoiníkē"},"G4983":{"kjv_def":"bodily, body, slave","lemma":"σῶμα","translit":"sōma","derivation":"from G4982 (σώζω);","strongs_def":" the body (as a sound whole), used in a very wide application, literally or figuratively","pron":"so'-mah","pos":"Noun Neuter","thayer":"<ol><li>the body both of men or animals<ol type='a'><li>a dead body or corpse</li><li>the living body<ol><li>of animals</li></ol></li></ol><li>the bodies of planets and of stars (heavenly bodies)</li><li>is used of a (large or small) number of men closely united into one society, or family as it were; a social, ethical, mystical body<ol type='a'><li>so in the NT of the church</li></ol><li>that which casts a shadow as distinguished from the shadow itself</li></ol>","xlit":"sōma"},"G4605":{"derivation":"of Hebrew origin (H06721);","strongs_def":" Sidon (i.e. Tsidon), a place in Palestine","kjv_def":"Sidon","translit":"Sidṓn","lemma":"Σιδών","pron":"sid-one'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sidon or Zidon = \"hunting\"</p><ol><li>an ancient and wealthy city of Phoenicia, on the east coast of the Mediterranean Sea, less than 20 miles (30 km) north of Tyre</li></ol>","xlit":"Sidṓn"},"G5150":{"kjv_def":"three months","translit":"trímēnon","lemma":"τρίμηνον","derivation":"neuter of a compound of G5140 (τρεῖς) and G3376 (μήν) as noun;","strongs_def":" a three months' space","pron":"trim'-ay-non","pos":"Adjective","thayer":"<ol><li>of three months</li><li>a space of three months</li></ol>","xlit":"trímēnon"},"G2880":{"lemma":"κορέννυμι","translit":"korénnymi","kjv_def":"eat enough, full","strongs_def":" to cram, i.e. glut or sate","derivation":"a primary verb;","pron":"kor-en'-noo-mee","pos":"Verb","thayer":"<ol><li>to satiate, sate, satisfy</li></ol>","xlit":"korénnymi"},"G1687":{"derivation":"from G1722 (ἐν) and a presumed derivative of the base of G939 (βάσις);","strongs_def":" equivalent to G1684 (ἐμβαίνω); to intrude on (figuratively)","kjv_def":"intrude into","lemma":"ἐμβατεύω","translit":"embateúō","pron":"em-bat-yoo'-o","pos":"Verb","thayer":"<ol><li>to enter, to frequent, haunt<ol type='a'><li>often of the gods frequenting favourite sports</li><li>often to come into possession of a thing</li><li>to invade, make hostile incursion into</li></ol><li>to enter<ol type='a'><li>to go into details in narrating</li><li>to investigate, search into, scrutinise minutely</li></ol></li></ol>","xlit":"embateúō"},"G261":{"derivation":"from G1 (Α) (as a negative particle) and G3129 (μανθάνω);","strongs_def":" ignorant","kjv_def":"unlearned","translit":"amathḗs","lemma":"ἀμαθής","pron":"am-ath-ace'","pos":"Adjective","thayer":"<ol><li>unlearned, ignorant</li></ol>","xlit":"amathḗs"},"G1918":{"kjv_def":"marry","lemma":"ἐπιγαμβρεύω","translit":"epigambreúō","derivation":"from G1909 (ἐπί) and a derivative of G1062 (γάμος);","strongs_def":" to form affinity with, i.e. (specially) in a levirate way","pron":"ep-ee-gam-bryoo'-o","pos":"Verb","thayer":"<ol><li>to be related to by marriage, enter into affinity with<ol type='a'><li>become any one's father-in-law or son-in-law</li><li>to marry the widow of a brother who has died childless</li></ol></li></ol>","xlit":"epigambreúō"},"G803":{"derivation":"from G804 (ἀσφαλής);","strongs_def":" security (literally or figuratively)","kjv_def":"certainty, safety","lemma":"ἀσφάλεια","translit":"aspháleia","pron":"as-fal'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>firmness, stability</li><li>certainty, undoubted truth</li><li>security from enemies and dangers, safety</li></ol>","xlit":"aspháleia"},"G3016":{"lemma":"λεπτόν","translit":"leptón","kjv_def":"mite","strongs_def":" something scaled (light), i.e. a small coin","derivation":"neuter of a derivative of the same as G3013 (λεπίς);","pron":"lep-ton'","pos":"Adjective","thayer":"<ol><li>thin, small</li><li>a small brass coin, equivalent to the eighth part of an \"as\" , worth about a 1/5 of a cent</li></ol>","xlit":"leptón"},"G758":{"lemma":"ἄρχων","translit":"árchōn","kjv_def":"chief (ruler), magistrate, prince, ruler","strongs_def":" a first (in rank or power)","derivation":"present participle of G757 (ἄρχω);","pron":"ar'-khone","pos":"Noun Masculine","thayer":"<ol><li>a ruler, commander, chief, leader</li></ol>","xlit":"árchōn"},"G3845":{"translit":"parabaínō","lemma":"παραβαίνω","kjv_def":"(by) transgress(-ion)","strongs_def":" to go contrary to, i.e. violate a command","derivation":"from G3844 (παρά) and the base of G939 (βάσις);","pron":"par-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to go by the side of</li><li>to go past or pass over without touching a thing</li><li>to overstep, neglect, violate, transgress</li><li>so to go past as to turn aside from<ol type='a'><li>to depart, leave, be turned from</li></ol><li>one who abandons his trust</li></ol>","xlit":"parabaínō"},"G3594":{"strongs_def":" to show the way (literally or figuratively (teach))","derivation":"from G3595 (ὁδηγός);","lemma":"ὁδηγέω","translit":"hodēgéō","kjv_def":"guide, lead","pron":"hod-ayg-eh'-o","pos":"Verb","thayer":"<ol><li>to be a guide, lead on one's way, to guide</li><li>to be a guide or a teacher<ol type='a'><li>to give guidance to</li></ol></li></ol>","xlit":"hodēgéō"},"G447":{"lemma":"ἀνίημι","translit":"aníēmi","kjv_def":"forbear, leave, loose","strongs_def":" to let up, i.e. (literally) slacken or (figuratively) desert, desist from","derivation":"from G303 (ἀνά) and (to send);","pron":"an-ee'-ay-mee","pos":"Verb","thayer":"<ol><li>to send back, relax, loosen</li><li>to give up, omit, calm</li><li>to leave, not to uphold, to let sink</li></ol>","xlit":"aníēmi"},"G4663":{"derivation":"of uncertain derivation;","strongs_def":" a grub, maggot or earth-worm","kjv_def":"worm","lemma":"σκώληξ","translit":"skṓlēx","pron":"sko'-lakes","pos":"Noun Masculine","thayer":"<ol><li>a worm, spec. that kind which preys upon dead bodies</li></ol>","xlit":"skṓlēx"},"G5301":{"kjv_def":"hyssop","translit":"hýssōpos","lemma":"ὕσσωπος","derivation":"of foreign origin (H0231);","strongs_def":" \"hyssop\"","pron":"hoos'-so-pos","pos":"Noun Feminine","thayer":"<ol><li>hyssop</li><li>a plant used by the Hebrews in their ritual sprinklings</li></ol>","xlit":"hýssōpos"},"G1367":{"kjv_def":"two thousand","lemma":"δισχίλιοι","translit":"dischílioi","derivation":"from G1364 (δίς) and G5507 (χίλιοι);","strongs_def":" two thousand","pron":"dis-khil'-ee-oy","pos":"Adjective","thayer":"<ol><li>two thousand</li></ol>","xlit":"dischílioi"},"G240":{"lemma":"ἀλλήλων","translit":"allḗlōn","kjv_def":"each other, mutual, one another, (the other), (them-, your-)selves, (selves) together (sometimes with G3326 (μετά) or G4314 (πρός))","strongs_def":" one another","derivation":"Genitive plural from G243 (ἄλλος) reduplicated;","pron":"al-lay'-lone","thayer":"<ol><li>one another, reciprocally, mutually</li></ol>","xlit":"allḗlōn"},"G309":{"lemma":"ἀνάβλεψις","translit":"anáblepsis","kjv_def":"recovery of sight","strongs_def":" restoration of sight","derivation":"from G308 (ἀναβλέπω);","pron":"an-ab'-lep-sis","pos":"Noun Feminine","thayer":"<ol><li>recovery of sight</li></ol>","xlit":"anáblepsis"},"G4907":{"strongs_def":" a mental putting together, i.e. intelligence or (concretely) the intellect","derivation":"from G4920 (συνίημι);","translit":"sýnesis","lemma":"σύνεσις","kjv_def":"knowledge, understanding","pron":"soon'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a running together, a flowing together with</li><li>knowledge<ol type='a'><li>understanding</li><li>the understanding, i.e the mind so far forth as it understands</li></ol></li></ol>","xlit":"sýnesis"},"G1476":{"derivation":"from a derivative of (to sit);","strongs_def":" sedentary, i.e. (by implication) immovable","kjv_def":"settled, stedfast","lemma":"ἑδραῖος","translit":"hedraîos","pron":"hed-rah'-yos","pos":"Adjective","thayer":"<ol><li>sitting, sedentary</li><li>firm, immovable, steadfast</li></ol>","xlit":"hedraîos"},"G3304":{"derivation":"from G3203 and G3767 (οὖν) and G1065 (γέ);","strongs_def":" so then at least","kjv_def":"nay but, yea doubtless (rather, verily)","lemma":"μενοῦνγε","translit":"menoûnge","pron":"men-oon'-geh","thayer":"<ol><li>nay surely, nay rather</li></ol>","xlit":"menoûnge"},"G706":{"strongs_def":" a number (as reckoned up)","derivation":"from G142 (αἴρω);","lemma":"ἀριθμός","translit":"arithmós","kjv_def":"number","pron":"ar-ith-mos'","pos":"Noun Masculine","thayer":"<ol><li>a fixed and definite number</li><li>an indefinite number, a multitude</li></ol>","xlit":"arithmós"},"G237":{"derivation":"from G243 (ἄλλος);","strongs_def":" from elsewhere","kjv_def":"some other way","lemma":"ἀλλαχόθεν","translit":"allachóthen","pron":"al-lakh-oth'-en","pos":"Adverb","thayer":"<ol><li>from another place</li></ol>","xlit":"allachóthen"},"G1083":{"strongs_def":" nativity","derivation":"from G1080 (γεννάω);","translit":"génnēsis","lemma":"γέννησις","kjv_def":"birth","pron":"ghen'-nay-sis","pos":"Adjective","thayer":"<ol><li>begat, engendering</li><li>nativity, birth</li></ol>","xlit":"génnēsis"},"G1188":{"kjv_def":"right (hand, side)","lemma":"δεξιός","translit":"dexiós","derivation":"from G1209 (δέχομαι);","strongs_def":" the right side or (feminine) hand (as that which usually takes)","pron":"dex-ee-os'","pos":"Adjective","thayer":"<ol><li>the right, the right hand</li><li>metaphorically<ol type='a'><li>a place of honour or authority</li></ol></li></ol>","xlit":"dexiós"},"G2802":{"kjv_def":"Clauda","translit":"Klaúdē","lemma":"Κλαύδη","derivation":"of uncertain derivation;","strongs_def":" Claude, an island near Crete","pron":"klow'-day","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Clauda = \"lame\"</p><ol><li>a small island nearly due west of Cape Malta on the south coast</li></ol>","xlit":"Klaúdē"},"G4875":{"derivation":"middle from G4862 (σύν) and G373 (ἀναπαύω);","strongs_def":" to recruit oneself in company with","kjv_def":"refresh with","translit":"synanapaúomai","lemma":"συναναπαύομαι","pron":"soon-an-ap-ow'-om-ahee","pos":"Verb","thayer":"<ol><li>to take rest together with</li><li>to sleep together with, to lie with<ol type='a'><li>of a husband and wife</li><li>metaphorically to rest or refresh one's spirits with one (i.e. to give and get refreshment by mutual intercourse)</li></ol></li></ol>","xlit":"synanapaúomai"},"G3533":{"kjv_def":"Nicopolis","lemma":"Νικόπολις","translit":"Nikópolis","derivation":"from G3534 (νῖκος) and G4172 (πόλις);","strongs_def":" victorious city; Nicopolis, a place in Macedonia","pron":"nik-op'-ol-is","pos":"Noun Location","thayer":"<ol><li>There were many cities by this name, - in Armenia, Pontus, Cilicia, Epirus, Thrace - which were generally built or had there name changed, by some conqueror to commemorate a victory. The one in <a class='bible' href='#b56.3.12'>Tit 3:12</a> seems to refer to the city was built by Augustus in memory of the battle of Actium on a promontory of Epirius. The one in the subscription of Titus seems to refer to Thracian Nicopolis, founded by Trojan on the river Nestus, since he calls it the city of Macedonia.</li></ol>","xlit":"Nikópolis"},"G1151":{"strongs_def":" a heifer (as tame)","derivation":"probably from the base of G1150 (δαμάζω);","lemma":"δάμαλις","translit":"dámalis","kjv_def":"heifer","pron":"dam'-al-is","pos":"Noun Feminine","thayer":"<ol><li>a young cow, heifer<ol type='a'><li>of the red heifer with whose ashes, by the Mosaic law, those were to be sprinkled who had become defiled</li></ol></li></ol>","xlit":"dámalis"},"G156":{"translit":"aitía","lemma":"αἰτία","kjv_def":"accusation, case, cause, crime, fault, (wh-)ere(-fore)","strongs_def":" a cause (as if asked for), i.e. (logical) reason (motive, matter), (legal) crime (alleged or proved)","derivation":"from the same as G154 (αἰτέω);","pron":"ahee-tee'-a","pos":"Noun Feminine","thayer":"<ol><li>cause, reason</li><li>cause for which one is worthy of punishment, crime</li><li>charge of crime, accusation</li></ol>","xlit":"aitía"},"G4097":{"translit":"pipráskō","lemma":"πιπράσκω","kjv_def":"sell","strongs_def":" from the base of G4008 (πέραν)); to traffic (by travelling), i.e. dispose of as merchandise or into slavery (literally or figuratively)","derivation":"contracted from (to traverse;","pron":"pip-ras'-ko","pos":"Verb","thayer":"<ol><li>to sell<ol type='a'><li>of price, one into slavery</li><li>of the master to whom one is sold as a slave</li></ol><li>metaphorically<ol type='a'><li>sold under sin, entirely under the control of the love of sinning</li><li>of one bribed to give himself up wholly to another's will</li></ol></li></ol>","xlit":"pipráskō"},"G1429":{"translit":"dōdekáphylon","lemma":"δωδεκάφυλον","kjv_def":"twelve tribes","strongs_def":" the commonwealth of Israel","derivation":"from G1427 (δώδεκα) and G5443 (φυλή);","pron":"do-dek-af'-oo-lon","pos":"Noun Neuter","thayer":"<ol><li>the twelve tribes, used collectively of the Israelitish people, as consisting of the twelve tribes</li></ol>","xlit":"dōdekáphylon"},"G5449":{"lemma":"φύσις","translit":"phýsis","kjv_def":"(man-)kind, nature(-al)","strongs_def":" growth (by germination or expansion), i.e. (by implication) natural production (lineal descent); by extension, a genus or sort; figuratively, native disposition, constitution or usage","derivation":"from G5453 (φύω);","pron":"foo'-sis","pos":"Noun Feminine","thayer":"<ol><li>nature<ol type='a'><li>the nature of things, the force, laws, order of nature</li><li>as opposed to what is monstrous, abnormal, perverse</li><li>as opposed what has been produced by the art of man: the natural branches, i.e. branches by the operation of nature</li><li>birth, physical origin</li><li>a mode of feeling and acting which by long habit has become nature</li><li>the sum of innate properties and powers by which one person differs from others, distinctive native peculiarities, natural characteristics: the natural strength, ferocity, and intractability of beasts</li></ol></li></ol>","xlit":"phýsis"},"G2443":{"derivation":"probably from the same as the former part of G1438 (ἑαυτοῦ) (through the demonstrative idea;","strongs_def":" compare G3588 (ὁ)); in order that (denoting the purpose or the result)","kjv_def":"albeit, because, to the intent (that), lest, so as, (so) that, (for) to","translit":"hína","lemma":"ἵνα","pron":"hin'-ah","pos":"Conjunction","thayer":"<ol><li>that, in order that, so that</li></ol>","xlit":"hína"},"G880":{"kjv_def":"dumb, without signification","lemma":"ἄφωνος","translit":"áphōnos","derivation":"from G1 (Α) (as a negative particle) and G5456 (φωνή);","strongs_def":" voiceless, i.e. mute (by nature or choice); figuratively, unmeaning","pron":"af'-o-nos","pos":"Adjective","thayer":"<ol><li>voiceless, dumb</li><li>without faculty of speech<ol type='a'><li>of idols</li></ol></li></ol>","xlit":"áphōnos"},"G917":{"translit":"baréōs","lemma":"βαρέως","kjv_def":"dull","strongs_def":" heavily (figuratively)","derivation":"adverb from G926 (βαρύς);","pron":"bar-eh'-oce","pos":"Adverb","thayer":"<ol><li>heavily, with difficulty</li></ol>","xlit":"baréōs"},"G524":{"lemma":"ἀπαλγέω","translit":"apalgéō","kjv_def":"be past feeling","strongs_def":" to grieve out, i.e. become apathetic","derivation":"from G575 (ἀπό) and (to smart);","pron":"ap-alg-eh'-o","pos":"Verb","thayer":"<ol><li>to cease to feel pain or grief<ol type='a'><li>to bear troubles with greater equanimity, cease to feel pain at</li><li>to become callous, insensible to pain, apathetic</li></ol></li></ol>","xlit":"apalgéō"},"G4736":{"kjv_def":"Stephen","translit":"Stéphanos","lemma":"Στέφανος","derivation":"the same as G4735 (στέφανος);","strongs_def":" Stephanus, a Christian","pron":"stef'-an-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Stephen = \"crowned\"</p><ol><li>one of the seven deacons in Jerusalem and the first Christian martyr</li></ol>","xlit":"Stéphanos"},"G5129":{"lemma":"τούτῳ","translit":"toútōi","kjv_def":"here(-by, -in), him, one, the same, there(-in), this","strongs_def":" to (in, with or by) this (person or thing)","derivation":"dative case singular masculine or neuter of G3778 (οὗτος);","pron":"too'-to","thayer":"<ol><li>to this one</li></ol>","xlit":"toútōi"},"G1249":{"derivation":"probably from an obsolete (to run on errands; compare G1377 (διώκω));","strongs_def":" an attendant, i.e. (genitive case) a waiter (at table or in other menial duties); specially, a Christian teacher and pastor (technically, a deacon or deaconess)","kjv_def":"deacon, minister, servant","translit":"diákonos","lemma":"διάκονος","pron":"dee-ak'-on-os","pos":"Noun","thayer":"<ol><li>one who executes the commands of another, especially of a master, a servant, attendant, minister<ol type='a'><li>the servant of a king</li><li>a deacon, one who, by virtue of the office assigned to him by the church, cares for the poor and has charge of and distributes the money collected for their use</li><li>a waiter, one who serves food and drink</li></ol></li></ol>","xlit":"diákonos"},"G55":{"translit":"hagnōs","lemma":"ἁγνῶς","kjv_def":"sincerely","strongs_def":" purely, i.e. honestly","derivation":"adverb from G53 (ἁγνός);","pron":"hag-noce'","pos":"Adverb","thayer":"<ol><li>chaste, clean, pure, with sincerity</li></ol>","xlit":"hagnōs"},"G4400":{"translit":"procheirízomai","lemma":"προχειρίζομαι","kjv_def":"choose, make","strongs_def":" to handle for oneself in advance, i.e. (figuratively) to purpose","derivation":"middle voice from G4253 (πρό) and a derivative of G5495 (χείρ);","pron":"prokh-i-rid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to put into the hand, to deliver into the hands</li><li>to take into one's hands</li><li>to set before one's self, to prostrate, to determine</li><li>to choose, to appoint<ol type='a'><li>for one's use</li><li>for one's salvation</li></ol></li></ol>","xlit":"procheirízomai"},"G4861":{"kjv_def":"like-minded","translit":"sýmpsychos","lemma":"σύμψυχος","derivation":"from G4862 (σύν) and G5590 (ψυχή);","strongs_def":" co-spirited, i.e. similar in sentiment","pron":"soom'-psoo-khos","pos":"Adjective","thayer":"<ol><li>of one mind, of one accord</li></ol>","xlit":"sýmpsychos"},"G4866":{"derivation":"from G4862 (σύν) and G118 (ἀθλέω);","strongs_def":" to wrestle in company with, i.e. (figuratively) to seek jointly","kjv_def":"labour with, strive together for","lemma":"συναθλέω","translit":"synathléō","pron":"soon-ath-leh'-o","pos":"Verb","thayer":"<ol><li>to strive at the same time with another</li></ol>","xlit":"synathléō"},"G3791":{"derivation":"from G3793 (ὄχλος);","strongs_def":" to mob, i.e. (by implication) to harass","kjv_def":"vex","lemma":"ὀχλέω","translit":"ochléō","pron":"okh-leh'-o","pos":"Verb","thayer":"<ol><li>to excite a mob against one</li><li>to disturb, roll away</li><li>to trouble, molest</li><li>be in confusion, in an uproar</li><li>to be vexed, molested, troubled: by demons</li></ol>","xlit":"ochléō"},"G5439":{"translit":"phylakízō","lemma":"φυλακίζω","kjv_def":"imprison","strongs_def":" to incarcerate","derivation":"from G5441 (φύλαξ);","pron":"foo-lak-id'-zo","pos":"Verb","thayer":"<ol><li>to cast into prison, imprison</li></ol>","xlit":"phylakízō"},"G897":{"kjv_def":" Babylon","translit":"Babylṓn","lemma":"Βαβυλών","derivation":"of Hebrew origin (H0894);","strongs_def":" Babylon, the capitol of Chaldæa (literally or figuratively (as a type of tyranny))","pron":"bab-oo-lone'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Babylon = \"confusion\"</p><ol><li>a very large and famous city, the residence of the Babylonian kings, situated on both banks of the Euphrates. Cyrus had formerly captured it, but Darius Hystaspis threw down its gates and walls, and Xerxes destroyed the temple of Belis. At length the city was reduced to almost solitude, the population having been drawn off by the neighbouring Seleucia, built on the Tigris by Seleucus Nicanor.</li><li>of the territory of Babylonia</li><li>allegorically, of Rome as the most corrupt seat of idolatry and the enemy of Christianity</li></ol>","xlit":"Babylṓn"},"G1331":{"kjv_def":"make enquiry for","lemma":"διερωτάω","translit":"dierōtáō","derivation":"from G1223 (διά) and G2065 (ἐρωτάω);","strongs_def":" to question throughout, i.e. ascertain by interrogation","pron":"dee-er-o-tah'-o","pos":"Verb","thayer":"<ol><li>to ask through<ol type='a'><li>ask many, one after another</li><li>to find out by asking, enquire out</li></ol></li></ol>","xlit":"dierōtáō"},"G3738":{"kjv_def":"dance","lemma":"ὀρχέομαι","translit":"orchéomai","derivation":"middle voice from (a row or ring);","strongs_def":" to dance (from the ranklike or regular motion)","pron":"or-kheh'-om-ahee","pos":"Verb","thayer":"<ol><li>to dance</li></ol>","xlit":"orchéomai"},"G1389":{"kjv_def":"handle deceitfully","lemma":"δολόω","translit":"dolóō","derivation":"from G1388 (δόλος);","strongs_def":" to ensnare, i.e. (figuratively) adulterate","pron":"dol-o'-o","pos":"Verb","thayer":"<ol><li>to ensnare</li><li>to corrupt</li></ol>","xlit":"dolóō"},"G3992":{"derivation":"apparently a primary verb;","strongs_def":" to dispatch (from the subjective view or point of departure, whereas (as a stronger form of ) refers rather to the objective point or terminus ad quem, and G4724 (στέλλω) denotes properly, the orderly motion involved), especially on a temporary errand; also to transmit, bestow, or wield","kjv_def":"send, thrust in","lemma":"πέμπω","translit":"pémpō","pron":"pem'-po","pos":"Verb","thayer":"<ol><li>to send<ol type='a'><li>to bid a thing to be carried to one</li><li>to send (thrust or insert) a thing into another</li></ol></li></ol>","xlit":"pémpō"},"G3923":{"translit":"pareisphérō","lemma":"παρεισφέρω","kjv_def":"give","strongs_def":" to bear in alongside, i.e. introduce simultaneously","derivation":"from G3844 (παρά) and G1533 (εἰσφέρω);","pron":"par-ice-fer'-o","pos":"Verb","thayer":"<ol><li>to bring in besides</li><li>to contribute besides to something</li></ol>","xlit":"pareisphérō"},"G2400":{"derivation":"second person singular imperative middle voice of G1492 (εἴδω);","strongs_def":" used as imperative lo!; ","kjv_def":"--behold, lo, see","translit":"idoú","lemma":"ἰδού","pron":"id-oo'","thayer":"<ol><li>behold, see, lo</li></ol>","xlit":"idoú"},"G4369":{"lemma":"προστίθημι","translit":"prostíthēmi","kjv_def":"add, again, give more, increase, lay unto, proceed further, speak to any more","strongs_def":" to place additionally, i.e. lay beside, annex, repeat","derivation":"from G4314 (πρός) and G5087 (τίθημι);","pron":"pros-tith'-ay-mee","pos":"Verb","thayer":"<ol><li>to put to</li><li>to add<ol type='a'><li>i.e. to join to, gather with any company, the number of one's followers or companions<ol><li>he was gathered to his fathers, i.e. died</li></ol></li></ol></li></ol>","xlit":"prostíthēmi"},"G1159":{"kjv_def":"be at charges, consume, spend","lemma":"δαπανάω","translit":"dapanáō","derivation":"from G1160 (δαπάνη);","strongs_def":" to expend, i.e. (in a good sense) to incur cost, or (in a bad one) to waste","pron":"dap-an-ah'-o","pos":"Verb","thayer":"<ol><li>to incur expense, expend, spend</li><li>in a bad sense: to waste, squander, consume</li></ol>","xlit":"dapanáō"},"G4320":{"kjv_def":"go up","translit":"prosanabaínō","lemma":"προσαναβαίνω","derivation":"from G4314 (πρός) and G305 (ἀναβαίνω);","strongs_def":" to ascend farther, i.e. be promoted (take an upper (more honorable) seat)","pron":"pros-an-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to go up further</li><li>go up higher</li></ol>","xlit":"prosanabaínō"},"G331":{"kjv_def":"accused, anathema, curse, X great","translit":"anáthema","lemma":"ἀνάθεμα","derivation":"from G394 (ἀνατίθεμαι);","strongs_def":" a (religious) ban or (concretely) excommunicated (thing or person)","pron":"an-ath'-em-ah","pos":"Noun Neuter","thayer":"<ol><li>a thing set up or laid by in order to be kept<ol type='a'><li>specifically, an offering resulting from a vow, which after being consecrated to a god was hung upon the walls or columns of the temple, or put in some other conspicuous place</li></ol><li>a thing devoted to God without hope of being redeemed, and if an animal, to be slain; therefore a person or thing doomed to destruction<ol type='a'><li>a curse</li><li>a man accursed, devoted to the direst of woes</li></ol></li></ol>","xlit":"anáthema"},"G5408":{"kjv_def":"murder, + be slain with, slaughter","translit":"phónos","lemma":"φόνος","derivation":"from an obsolete primary (to slay);","strongs_def":" murder","pron":"fon'-os","pos":"Noun Masculine","thayer":"<ol><li>murder, slaughter</li></ol>","xlit":"phónos"},"G3603":{"kjv_def":"called, which is (make), that is (to say)","translit":"hó esti","lemma":"ὅ ἐστι","derivation":"from the neuter of G3739 (ὅς) and the third person singular present indicative of G1510 (εἰμί);","strongs_def":" which is","pron":"ho es-tee'","pos":"Verb","thayer":"<ol><li>which is, that is</li></ol>","xlit":"hó esti"},"G81":{"derivation":"from G80 (ἀδελφός);","strongs_def":" brotherhood (properly, the feeling of brotherliness), i.e. the (Christian) fraternity","kjv_def":"brethren, brotherhood","lemma":"ἀδελφότης","translit":"adelphótēs","pron":"ad-el-fot'-ace","pos":"Noun Feminine","thayer":"<ol><li>brotherhood, brotherly kindness</li><li>a family of brothers, the brotherhood</li></ol>","xlit":"adelphótēs"},"G4874":{"derivation":"from G4862 (σύν) and a compound of G303 (ἀνά) and G3396 (μίγνυμι);","strongs_def":" to mix up together, i.e. (figurative) associate with","kjv_def":"(have, keep) company (with)","lemma":"συναναμίγνυμι","translit":"synanamígnymi","pron":"soon-an-am-ig'-noo-mee","pos":"Verb","thayer":"<ol><li>to mix up together</li><li>to keep company with, be intimate with one</li></ol>","xlit":"synanamígnymi"},"G4841":{"lemma":"συμπάσχω","translit":"sympáschō","kjv_def":"suffer with","strongs_def":" to experience pain jointly or of the same kind (specially, persecution; to \"sympathize\")","derivation":"from G4862 (σύν) and G3958 (πάσχω) (including its alternate);","pron":"soom-pas'-kho","pos":"Verb","thayer":"<ol><li>to suffer or feel pain together</li><li>to suffer evils (troubles, persecutions) in the like manner with another</li></ol>","xlit":"sympáschō"},"G3180":{"kjv_def":"wile, lie in wait","translit":"methodeía","lemma":"μεθοδεία","derivation":"from a compound of G3326 (μετά) and G3593 (ὁδεύω) (compare \"method\");","strongs_def":" travelling over, i.e. travesty (trickery)","pron":"meth-od-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>cunning arts, deceit, craft, trickery</li></ol>","xlit":"methodeía"},"G4636":{"derivation":"from G4633 (σκηνή);","strongs_def":" a hut or temporary residence, i.e. (figuratively) the human body (as the abode of the spirit)","kjv_def":"tabernacle","translit":"skēnos","lemma":"σκῆνος","pron":"skay'-nos","pos":"Noun Neuter","thayer":"<ol><li>a tabernacle, a tent</li><li>metaphorically of the human body, in which the soul dwells as in a tent, and which is taken down at death</li></ol>","xlit":"skēnos"},"G1483":{"strongs_def":" as a Gentile","derivation":"adverb from G1482 (ἐθνικός);","translit":"ethnikōs","lemma":"ἐθνικῶς","kjv_def":"after the manner of Gentiles","pron":"eth-nee-koce'","pos":"Adverb","thayer":"<ol><li>like the Gentiles</li></ol>","xlit":"ethnikōs"},"G2842":{"kjv_def":"(to) communicate(-ation), communion, (contri-)distribution, fellowship","lemma":"κοινωνία","translit":"koinōnía","derivation":"from G2844 (κοινωνός);","strongs_def":" partnership, i.e. (literally) participation, or (social) intercourse, or (pecuniary) benefaction","pron":"koy-nohn-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>fellowship, association, community, communion, joint participation, intercourse<ol type='a'><li>the share which one has in anything, participation</li><li>intercourse, fellowship, intimacy<ol><li>the right hand as a sign and pledge of fellowship (in fulfilling the apostolic office)</li></ol><li>a gift jointly contributed, a collection, a contribution, as exhibiting an embodiment and proof of fellowship</li></ol></li></ol>","xlit":"koinōnía"},"G1548":{"kjv_def":"give in marriage","lemma":"ἐκγαμίσκω","translit":"ekgamískō","derivation":"from G1537 (ἐκ) and G1061 (γαμίσκω);","strongs_def":" the same as 1547","pron":"ek-gam-is'-ko","pos":"Verb","thayer":"<ol><li>to give away in marriage: a daughter</li><li>to marry, to be given in marriage</li></ol>","xlit":"ekgamískō"},"G979":{"derivation":"a primary word;","strongs_def":" life, i.e. (literally) the present state of existence; by implication, the means of livelihood","kjv_def":"good, life, living","lemma":"βίος","translit":"bíos","pron":"bee'-os","pos":"Noun Masculine","thayer":"<ol><li>life<ol type='a'><li>life extensively<ol><li>the period or course of life</li></ol><li>that by which life is sustained, resources, wealth, goods</li></ol></li></ol>","xlit":"bíos"},"G2990":{"kjv_def":"be hid, be ignorant of, unawares","lemma":"λανθάνω","translit":"lanthánō","derivation":"a prolonged form of a primary verb, which is used only as an alternate in certain tenses;","strongs_def":" to lie hid (literally or figuratively); often used adverbially, unwittingly","pron":"lan-than'-o","pos":"Verb","thayer":"<ol><li>to be hidden, to be hidden from one, secretly, unawares, without knowing</li></ol>","xlit":"lanthánō"},"G4906":{"kjv_def":"eat with","translit":"synesthíō","lemma":"συνεσθίω","derivation":"from G4862 (σύν) and G2068 (ἐσθίω) (including its alternate);","strongs_def":" to take food in company with","pron":"soon-es-thee'-o","pos":"Verb","thayer":"<ol><li>to eat with, take food together with</li></ol>","xlit":"synesthíō"},"G5410":{"strongs_def":" a forum or market-place; only in comparative with G675 (Ἄππιος); a station on the Appian road","derivation":"of Latin origin;","lemma":"Φόρον","translit":"Phóron","kjv_def":"forum","pron":"for'-on","pos":"Noun Location","thayer":"<ol><li>Appius Forum, a town in Italy, 43 Roman miles (70 km) from Rome on the Appian Way</li></ol>","xlit":"Phóron"},"G1504":{"kjv_def":"image","translit":"eikṓn","lemma":"εἰκών","derivation":"from G1503 (εἴκω);","strongs_def":" a likeness, i.e. (literally) statue, profile, or (figuratively) representation, resemblance","pron":"i-kone'","pos":"Noun Feminine","thayer":"<ol><li>an image, figure, likeness<ol type='a'><li>an image of the things (the heavenly things)<ol><li>used of the moral likeness of renewed men to God</li><li>the image of the Son of God, into which true Christians are transformed, is likeness not only to the heavenly body, but also to the most holy and blessed state of mind, which Christ possesses</li></ol><li>the image of one<ol><li>one in whom the likeness of any one is seen</li><li>applied to man on account of his power of command</li><li>to Christ on account of his divine nature and absolute moral excellence</li></ol></li></ol></li></ol>","xlit":"eikṓn"},"G1762":{"kjv_def":"be, (there) is","translit":"éni","lemma":"ἔνι","derivation":"contraction for the third person singular present indicative of G1751 (ἔνειμι);","strongs_def":" impersonally, there is in or among","pron":"en'-ee","pos":"Verb","thayer":"<ol><li>is in, is among, has place, is present</li><li>it can be, is possible, is lawful</li></ol>","xlit":"éni"},"G275":{"derivation":"from G1 (Α) (as a negative particle) and G3308 (μέριμνα);","strongs_def":" not anxious","kjv_def":"without care(-fulness), secure","lemma":"ἀμέριμνος","translit":"amérimnos","pron":"am-er'-im-nos","pos":"Adjective","thayer":"<ol><li>free from anxiety, free from care</li></ol>","xlit":"amérimnos"},"G2517":{"derivation":"from G2596 (κατά) and G1836 (ἑξῆς);","strongs_def":" thereafter, i.e. consecutively; as a noun (by ellipsis of noun) a subsequent person or time","kjv_def":"after(-ward), by (in) order","translit":"kathexēs","lemma":"καθεξῆς","pron":"kath-ex-ace'","pos":"Adverb","thayer":"<ol><li>one after another, successively, in order</li></ol>","xlit":"kathexēs"},"G105":{"kjv_def":"eagle","translit":"aetós","lemma":"ἀετός","derivation":"from the same as G109 (ἀήρ);","strongs_def":" an eagle (from its wind-like flight)","pron":"ah-et-os'","pos":"Noun Masculine","thayer":"<ol><li>an eagle: since eagles do not usually go in quest of carrion, this may to a vulture that resembles an eagle</li><li>an eagle as a standard (Roman Military)</li></ol>","xlit":"aetós"},"G1954":{"translit":"epíloipos","lemma":"ἐπίλοιπος","kjv_def":"rest","strongs_def":" left over, i.e. remaining","derivation":"from G1909 (ἐπί) and G3062 (λοιποί);","pron":"ep-il'-oy-pos","pos":"Adjective","thayer":"<ol><li>remaining besides, left over</li></ol>","xlit":"epíloipos"},"G4118":{"derivation":"irregular superlative of G4183 (πολύς);","strongs_def":" the largest number or very large","kjv_def":"very great, most","translit":"pleîstos","lemma":"πλεῖστος","pron":"plice'-tos","pos":"Adjective","thayer":"<ol><li>most</li><li>at the very most</li></ol>","xlit":"pleîstos"},"G507":{"strongs_def":" upward or on the top","derivation":"adverb from G473 (ἀντί);","translit":"ánō","lemma":"ἄνω","kjv_def":"above, brim, high, up","pron":"an'-o","pos":"Adverb","thayer":"<ol><li>up, upwards, above, on high</li><li>of the quarters of the heaven, northward</li><li>of countries, inland, up from the coast</li><li>of time, formerly</li></ol>","xlit":"ánō"},"G5337":{"derivation":"apparently a primary word;","strongs_def":" \"foul\" or \"flawy\", i.e. (figuratively) wicked","kjv_def":"evil","translit":"phaûlos","lemma":"φαῦλος","pron":"fow'-los","pos":"Adjective","thayer":"<ol><li>easy, slight, ordinary, mean, worthless, of no account</li><li>ethically, bad, base, wicked</li></ol>","xlit":"phaûlos"},"G612":{"strongs_def":" a response","derivation":"from G611 (ἀποκρίνομαι);","lemma":"ἀπόκρισις","translit":"apókrisis","kjv_def":"answer","pron":"ap-ok'-ree-sis","pos":"Noun Feminine","thayer":"<ol><li>a replying, an answer</li></ol>","xlit":"apókrisis"},"G3037":{"translit":"líthos","lemma":"λίθος","kjv_def":"(mill-, stumbling-)stone","strongs_def":" a stone (literally or figuratively)","derivation":"apparently a primary word;","pron":"lee'-thos","pos":"Noun Masculine","thayer":"<ol><li>a stone<ol type='a'><li>of small stones</li><li>of building stones</li><li>metaphorically of Christ</li></ol></li></ol>","xlit":"líthos"},"G2272":{"kjv_def":"peaceable, quiet","translit":"hēsýchios","lemma":"ἡσύχιος","derivation":"a prolonged form of a compound probably of a derivative of the base of G1476 (ἑδραῖος) and perhaps G2192 (ἔχω);","strongs_def":" properly, keeping one's seat (sedentary), i.e. (by implication) still (undisturbed, undisturbing)","pron":"hay-soo'-khee-os","pos":"Adjective","thayer":"<ol><li>quiet, tranquil</li></ol>","xlit":"hēsýchios"},"G1938":{"derivation":"from G1937 (ἐπιθυμέω);","strongs_def":" a craver","kjv_def":"+ lust after","lemma":"ἐπιθυμητής","translit":"epithymētḗs","pron":"ep-ee-thoo-may-tace'","pos":"Noun Masculine","thayer":"<ol><li>one who longs for, a craver, lover, one eager for</li></ol>","xlit":"epithymētḗs"},"G2661":{"kjv_def":"(ac-)count worthy","lemma":"καταξιόω","translit":"kataxióō","derivation":"from G2596 (κατά) and G515 (ἀξιόω);","strongs_def":" to deem entirely deserving","pron":"kat-ax-ee-o'-o","pos":"Verb","thayer":"<ol><li>to account worthy, judge worthy</li></ol>","xlit":"kataxióō"},"G1772":{"kjv_def":"lawful, under law","lemma":"ἔννομος","translit":"énnomos","derivation":"from G1722 (ἐν) and G3551 (νόμος);","strongs_def":" (subjectively) legal, or (objectively) subject to","pron":"en'-nom-os","pos":"Adjective","thayer":"<ol><li>bound to the law</li><li>bound by the law, lawful</li><li>lawful, regular</li></ol>","xlit":"énnomos"},"G5225":{"lemma":"ὑπάρχω","translit":"hypárchō","kjv_def":"after, behave, live","strongs_def":" to begin under (quietly), i.e. come into existence (be present or at hand); expletively, to exist (as copula or subordinate to an adjective, participle, adverb or preposition, or as an auxiliary to a principal (verb)","derivation":"from G5259 (ὑπό) and G756 (ἄρχομαι);","pron":"hoop-ar'-kho","pos":"Verb","thayer":"<ol><li>to begin below, to make a beginning<ol type='a'><li>to begin</li></ol><li>to come forth, hence to be there, be ready, be at hand</li><li>to be</li></ol>","xlit":"hypárchō"},"G455":{"kjv_def":"open","lemma":"ἀνοίγω","translit":"anoígō","derivation":"from G303 (ἀνά) and (to open);","strongs_def":" to open up (literally or figuratively, in various applications)","pron":"an-oy'-go","pos":"Verb","thayer":"<ol><li>to open</li></ol>","xlit":"anoígō"},"G5288":{"lemma":"ὑποστέλλω","translit":"hypostéllō","kjv_def":"draw (keep) back, shun, withdraw","strongs_def":" to withhold under (out of sight), i.e. (reflexively) to cower or shrink, (figuratively) to conceal (reserve)","derivation":"from G5259 (ὑπό) and G4724 (στέλλω);","pron":"hoop-os-tel'-lo","pos":"Verb","thayer":"<ol><li>to draw back, let down, lower<ol type='a'><li>to withdraw: of a timid person</li></ol><li>to withdraw one's self, i.e. to be timid, to cover, shrink<ol type='a'><li>of those who from timidity hesitate to avow what they believe</li><li>to be unwilling to utter from fear</li><li>to shrink from declaring, to conceal, dissemble</li></ol></li></ol>","xlit":"hypostéllō"},"G2394":{"derivation":"future active participle masculine of G2390 (ἰάομαι);","strongs_def":" about to cure; Jason, a Christian","kjv_def":"Jason","translit":"Iásōn","lemma":"Ἰάσων","pron":"ee-as'-oan","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jason = \"one who will heal\"</p><ol><li>a Thessalonians who entertained Paul and Silas, and maybe a cousin of Paul (<a class='bible' href='#b45.16.21'>Rom 16:21</a>)</li></ol>","xlit":"Iásōn"},"G5494":{"derivation":"from a derivative of (to pour;","strongs_def":" akin to the base of 5490 through the idea of a channel), meaning a storm (as pouring rain); by implication, the rainy season, i.e. winter","kjv_def":"tempest, foul weather, winter","lemma":"χειμών","translit":"cheimṓn","pron":"khi-mone'","pos":"Noun Masculine","thayer":"<ol><li>winter<ol type='a'><li>stormy or rainy weather, a tempest</li><li>winter, the winter season</li></ol></li></ol>","xlit":"cheimṓn"},"G4160":{"derivation":"apparently a prolonged form of an obsolete primary;","strongs_def":" to make or do (in a very wide application, more or less direct)","kjv_def":"abide, + agree, appoint, X avenge, + band together, be, bear, + bewray, bring (forth), cast out, cause, commit, + content, continue, deal, + without any delay, (would) do(-ing), execute, exercise, fulfil, gain, give, have, hold, X journeying, keep, + lay wait, + lighten the ship, make, X mean, + none of these things move me, observe, ordain, perform, provide, + have purged, purpose, put, + raising up, X secure, shew, X shoot out, spend, take, tarry, + transgress the law, work, yield","translit":"poiéō","lemma":"ποιέω","pron":"poy-eh'-o","pos":"Verb","thayer":"<ol><li>to make<ol type='a'><li>with the names of things made, to produce, construct, form, fashion, etc.</li><li>to be the authors of, the cause</li><li>to make ready, to prepare</li><li>to produce, bear, shoot forth</li><li>to acquire, to provide a thing for one's self</li><li>to make a thing out of something</li><li>to (make, i.e.) render one anything<ol><li>to (make, i.e.) constitute or appoint one anything, to appoint or ordain one that</li><li>to (make, i.e.) declare one anything</li></ol><li>to put one forth, to lead him out</li><li>to make one do something<ol><li>cause one to</li></ol><li>to be the authors of a thing (to cause, bring about)</li></ol><li>to do<ol type='a'><li>to act rightly, do well<ol><li>to carry out, to execute</li></ol><li>to do a thing unto one<ol><li>to do to one</li></ol><li>with designation of time: to pass, spend</li><li>to celebrate, keep<ol><li>to make ready, and so at the same time to institute, the celebration of the passover</li></ol><li>to perform: to a promise</li></ol></li></ol>","xlit":"poiéō"},"G2907":{"derivation":"perhaps a primary word;","strongs_def":" (butcher's) meat","kjv_def":"flesh","translit":"kréas","lemma":"κρέας","pron":"kreh'-as","pos":"Noun Neuter","thayer":"<ol><li>(the) flesh (of a sacrificed animal)</li></ol>","xlit":"kréas"},"G2205":{"lemma":"ζῆλος","translit":"zēlos","kjv_def":"emulation, envy(-ing), fervent mind, indignation, jealousy, zeal","strongs_def":" properly, heat, i.e. (figuratively) \"zeal\" (in a favorable sense, ardor; in an unfavorable one, jealousy, as of a husband (figuratively, of God), or an enemy, malice)","derivation":"from G2204 (ζέω);","pron":"dzay'-los","pos":"Noun","thayer":"<ol><li>excitement of mind, ardour, fervour of spirit<ol type='a'><li>zeal, ardour in embracing, pursuing, defending anything<ol><li>zeal in behalf of, for a person or thing</li><li>the fierceness of indignation, punitive zeal</li></ol><li>an envious and contentious rivalry, jealousy</li></ol></li></ol>","xlit":"zēlos"},"G3516":{"kjv_def":"babe, child (+ -ish)","lemma":"νήπιος","translit":"nḗpios","derivation":"from an obsolete particle (implying negation) and G2031 (ἔπος);","strongs_def":" not speaking, i.e. an infant (minor); figuratively, a simple-minded person, an immature Christian","pron":"nay'-pee-os","pos":"Adjective","thayer":"<ol><li>an infant, little child</li><li>a minor, not of age</li><li>metaphorically childish, untaught, unskilled</li></ol>","xlit":"nḗpios"},"G1218":{"lemma":"δῆμος","translit":"dēmos","kjv_def":"people","strongs_def":" the public (as bound together socially)","derivation":"from G1210 (δέω);","pron":"day'-mos","pos":"Noun Masculine","thayer":"<ol><li>the people, the mass of people assembled in a public place</li></ol>","xlit":"dēmos"},"G3687":{"kjv_def":"call, name","lemma":"ὀνομάζω","translit":"onomázō","derivation":"from G3686 (ὄνομα);","strongs_def":" to name, i.e. assign an appellation; by extension, to utter, mention, profess","pron":"on-om-ad'-zo","pos":"Verb","thayer":"<ol><li>to name<ol type='a'><li>to name, to utter, to make mention of the name</li><li>to name<ol><li>give name to, one</li><li>be named<ol type='a'><li>to bear the name of a person or thing</li></ol></li></ol><li>to utter the name of a person or thing</li></ol></li></ol>","xlit":"onomázō"},"G154":{"kjv_def":"ask, beg, call for, crave, desire, require","translit":"aitéō","lemma":"αἰτέω","derivation":"of uncertain derivation;","strongs_def":" to ask (in genitive case)","pron":"ahee-teh'-o","pos":"Verb","thayer":"<ol><li>to ask, beg, call for, crave, desire, require</li></ol>","xlit":"aitéō"},"G2750":{"strongs_def":" a swathe, i.e. winding-sheet","derivation":"of uncertain affinity;","lemma":"κειρία","translit":"keiría","kjv_def":"graveclothes","pron":"ki-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a band, either for bed-girth, or for tying up a corpse after it has been swathed in linen</li></ol>","xlit":"keiría"},"G2808":{"translit":"kleíō","lemma":"κλείω","kjv_def":"shut (up)","strongs_def":" to close (literally or figuratively)","derivation":"a primary verb;","pron":"kli'-o","pos":"Verb","thayer":"<ol><li>to shut, shut up</li><li>metaphorically<ol type='a'><li>to cause the heavens to withhold rain</li><li>to shut up compassion so that it is like a thing inaccessible to one, to be devoid of pity towards one</li><li>to obstruct the entrance into the kingdom of heaven</li></ol></li></ol>","xlit":"kleíō"},"G4267":{"translit":"proginṓskō","lemma":"προγινώσκω","kjv_def":"foreknow (ordain), know (before)","strongs_def":" to know beforehand, i.e. foresee","derivation":"from G4253 (πρό) and G1097 (γινώσκω);","pron":"prog-in-oce'-ko","pos":"Verb","thayer":"<ol><li>to have knowledge before hand</li><li>to foreknow<ol type='a'><li>of those whom God elected to salvation</li></ol><li>to predestinate</li></ol>","xlit":"proginṓskō"},"G3324":{"lemma":"μεστός","translit":"mestós","kjv_def":"full","strongs_def":" replete (literally or figuratively)","derivation":"of uncertain derivation;","pron":"mes-tos'","pos":"Adjective","thayer":"<ol><li>full<ol type='a'><li>in reference to persons, whose minds are as it were filled with thoughts and emotions, either good or bad</li></ol></li></ol>","xlit":"mestós"},"G4586":{"translit":"semnós","lemma":"σεμνός","kjv_def":"grave, honest","strongs_def":" venerable, i.e. honorable","derivation":"from G4576 (σέβομαι);","pron":"sem-nos'","pos":"Adjective","thayer":"<ol><li>august, venerable, reverend</li><li>to be venerated for character, honourable<ol type='a'><li>of persons</li><li>of deeds</li></ol></li></ol>","xlit":"semnós"},"G3876":{"lemma":"παρακοή","translit":"parakoḗ","kjv_def":"disobedience","strongs_def":" inattention, i.e. (by implication) disobedience","derivation":"from G3878 (παρακούω);","pron":"par-ak-o-ay'","pos":"Noun Feminine","thayer":"<ol><li>a hearing amiss</li><li>disobedience</li></ol>","xlit":"parakoḗ"},"G222":{"kjv_def":"of Alexandria","lemma":"Ἀλεξανδρῖνος","translit":"Alexandrînos","derivation":"from the same as G221 (Ἀλεξανδρεύς);","strongs_def":" Alexandrine, or belonging to Alexandria","pron":"al-ex-an-dree'-nos","pos":"Adjective","thayer":"<ol><li>a native or resident of Alexandria in Egypt</li><li>of Alexandria or belonging to Alexandria</li></ol>","xlit":"Alexandrînos"},"G1802":{"kjv_def":"Enoch","translit":"Enṓch","lemma":"Ἐνώχ","derivation":"of Hebrew origin (H02585);","strongs_def":" Enoch (i.e. Chanok), an antediluvian","pron":"en-oche'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Enoch = \"dedicated\"</p><ol><li>the son of Jared and father of Methuselah</li></ol>","xlit":"Enṓch"},"G4880":{"translit":"synapothnḗskō","lemma":"συναποθνήσκω","kjv_def":"be dead (die) with","strongs_def":" to decease (literally) in company with, or (figuratively), similarly to","derivation":"from G4862 (σύν) and G599 (ἀποθνήσκω);","pron":"soon-ap-oth-nace'-ko","pos":"Verb","thayer":"<ol><li>to die together</li><li>to die with one</li></ol>","xlit":"synapothnḗskō"},"G4417":{"strongs_def":" to trip, i.e. (figuratively) to err, sin, fail (of salvation)","derivation":"a form of G4098 (πίπτω);","translit":"ptaíō","lemma":"πταίω","kjv_def":"fall, offend, stumble","pron":"ptah'-yo","pos":"Verb","thayer":"<ol><li>to cause one to stumble or fall</li><li>to stumble<ol type='a'><li>to err, make a mistake, to sin</li><li>to fall into misery, become wretched</li></ol></li></ol>","xlit":"ptaíō"},"G1213":{"lemma":"δηλόω","translit":"dēlóō","kjv_def":"declare, shew, signify","strongs_def":" to make plain (by words)","derivation":"from G1212 (δῆλος);","pron":"day-lo'-o","pos":"Verb","thayer":"<ol><li>to make manifest</li><li>to make known by relating, to declare</li><li>to give one to understand, to indicate, signify</li></ol>","xlit":"dēlóō"},"G1935":{"strongs_def":" doomed to death","derivation":"from G1909 (ἐπί) and G2288 (θάνατος);","translit":"epithanátios","lemma":"ἐπιθανάτιος","kjv_def":"appointed to death","pron":"ep-ee-than-at'-ee-os","pos":"Adjective","thayer":"<ol><li>doomed to death</li></ol>","xlit":"epithanátios"},"G3860":{"strongs_def":" to surrender, i.e yield up, intrust, transmit","derivation":"from G3844 (παρά) and G1325 (δίδωμι);","lemma":"παραδίδωμι","translit":"paradídōmi","kjv_def":"betray, bring forth, cast, commit, deliver (up), give (over, up), hazard, put in prison, recommend","pron":"par-ad-id'-o-mee","pos":"Verb","thayer":"<ol><li>to give into the hands (of another)</li><li>to give over into (one's) power or use<ol type='a'><li>to deliver to one something to keep, use, take care of, manage</li><li>to deliver up one to custody, to be judged, condemned, punished, scourged, tormented, put to death</li><li>to deliver up treacherously<ol><li>by betrayal to cause one to be taken</li><li>to deliver one to be taught, moulded</li></ol></li></ol><li>to commit, to commend</li><li>to deliver verbally<ol type='a'><li>commands, rites</li><li>to deliver by narrating, to report</li></ol><li>to permit allow<ol type='a'><li>when the fruit will allow that is when its ripeness permits</li><li>gives itself up, presents itself</li></ol></li></ol>","xlit":"paradídōmi"},"G2356":{"strongs_def":" ceremonial observance","derivation":"from a derivative of G2357 (θρησκός);","translit":"thrēskeía","lemma":"θρησκεία","kjv_def":"religion, worshipping","pron":"thrace-ki'-ah","pos":"Noun Feminine","thayer":"<ol><li>religious worship<ol type='a'><li>especially external, that which consists of ceremonies<ol><li>religious discipline, religion</li></ol></li></ol></li></ol>","xlit":"thrēskeía"},"G4801":{"strongs_def":" to yoke together, i.e. (figuratively) conjoin (in marriage)","derivation":"from G4862 (σύν) and the base of G2201 (ζεῦγος);","translit":"syzeúgnymi","lemma":"συζεύγνυμι","kjv_def":"join together","pron":"sood-zyoog'-noo-mee","pos":"Verb","thayer":"<ol><li>to fasten to one yoke, yoke together</li><li>to join together unite<ol type='a'><li>of the marriage tie</li></ol></li></ol>","xlit":"syzeúgnymi"},"G1343":{"derivation":"from G1342 (δίκαιος);","strongs_def":" equity (of character or act); specially (Christian) justification","kjv_def":"righteousness","lemma":"δικαιοσύνη","translit":"dikaiosýnē","pron":"dik-ah-yos-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>in a broad sense: state of him who is as he ought to be, righteousness, the condition acceptable to God<ol type='a'><li>the doctrine concerning the way in which man may attain a state approved of God</li><li>integrity, virtue, purity of life, rightness, correctness of thinking feeling, and acting</li></ol><li>in a narrower sense, justice or the virtue which gives each his due</li></ol>","xlit":"dikaiosýnē"},"G2507":{"strongs_def":" to lower (or with violence) demolish (literally or figuratively)","derivation":"from G2596 (κατά) and G138 (αἱρέομαι) (including its alternate);","translit":"kathairéō","lemma":"καθαιρέω","kjv_def":"cast (pull, put, take) down, destroy","pron":"kath-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to take down<ol type='a'><li>without the notion of violence: to detach from the cross, one crucified</li><li>with the use of force: to throw down, cast down</li></ol><li>to pull down, demolish<ol type='a'><li>the subtle reasonings (of opponents) likened to a fortress, i.e. to refute, to destroy</li></ol></li></ol>","xlit":"kathairéō"},"G4393":{"derivation":"from G4253 (πρό) and G5342 (φέρω);","strongs_def":" to bear forward, i.e. produce","kjv_def":"bring forth","lemma":"προφέρω","translit":"prophérō","pron":"prof-er'-o","pos":"Verb","thayer":"<ol><li>to bring forth</li></ol>","xlit":"prophérō"},"G4904":{"kjv_def":"companion in labour, (fellow-)helper(-labourer, -worker), labourer together with, workfellow","lemma":"συνεργός","translit":"synergós","derivation":"from a presumed compound of G4862 (σύν) and the base of G2041 (ἔργον);","strongs_def":" a co-laborer, i.e. coadjutor","pron":"soon-er-gos'","pos":"Adjective","thayer":"<ol><li>a companion in work, fellow worker</li></ol>","xlit":"synergós"},"G565":{"strongs_def":" to go off (i.e. depart), aside (i.e. apart) or behind (i.e. follow), literally or figuratively","derivation":"from G575 (ἀπό) and G2064 (ἔρχομαι);","lemma":"ἀπέρχομαι","translit":"apérchomai","kjv_def":"come, depart, go (aside, away, back, out, … ways), pass away, be past","pron":"ap-erkh'-om-ahee","pos":"Verb","thayer":"<ol><li>to go away, depart<ol type='a'><li>to go away in order to follow any one, go after him, to follow his party, follow him as a leader</li></ol><li>to go away<ol type='a'><li>of departing evils and sufferings</li><li>of good things taken away from one</li><li>of an evanescent state of things</li></ol></li></ol>","xlit":"apérchomai"},"G1448":{"strongs_def":" to make near, i.e. (reflexively) approach","derivation":"from G1451 (ἐγγύς);","lemma":"ἐγγίζω","translit":"engízō","kjv_def":"approach, be at hand, come (draw) near, be (come, draw) nigh","pron":"eng-id'-zo","pos":"Verb","thayer":"<ol><li>to bring near, to join one thing to another</li><li>to draw or come near to, to approach</li></ol>","xlit":"engízō"},"G926":{"derivation":"from the same as G922 (βάρος);","strongs_def":" weighty, i.e. (fig) burdensome, grave","kjv_def":"grievous, heavy, weightier","lemma":"βαρύς","translit":"barýs","pron":"bar-ooce'","pos":"Adjective","thayer":"<ol><li>heavy in weight</li><li>metaphorically<ol type='a'><li>burdensome</li><li>severe, stern</li><li>weighty<ol><li>of great moment</li></ol><li>violent, cruel, unsparing</li></ol></li></ol>","xlit":"barýs"},"G4476":{"lemma":"ῥαφίς","translit":"rhaphís","kjv_def":" needle","strongs_def":" perhaps rather akin to the base of G4474 (ῥαπίζω) through the idea of puncturing); a needle","derivation":"from a primary (to sew;","pron":"hraf-ece'","pos":"Feminine Neuter","thayer":"<ol><li>a needle</li></ol>","xlit":"rhaphís"},"G3394":{"kjv_def":"uncleanness","lemma":"μιασμός","translit":"miasmós","derivation":"from G3392 (μιαίνω);","strongs_def":" (morally) contamination (properly, the act)","pron":"mee-as-mos'","pos":"Noun Masculine","thayer":"<ol><li>the act of defiling, defilement, pollution</li></ol>","xlit":"miasmós"},"G4146":{"strongs_def":" copiously","derivation":"adverb from G4145 (πλούσιος);","lemma":"πλουσίως","translit":"plousíōs","kjv_def":"abundantly, richly","pron":"ploo-see'-oce","pos":"Adverb","thayer":"<ol><li>abundantly, richly</li></ol>","xlit":"plousíōs"},"G1661":{"kjv_def":"of ivory","lemma":"ἐλεφάντινος","translit":"elephántinos","derivation":"from (an \"elephant\");","strongs_def":" elephantine, i.e. (by implication) composed of ivory","pron":"el-ef-an'-tee-nos","pos":"Adjective","thayer":"<ol><li>of ivory</li></ol>","xlit":"elephántinos"},"G521":{"strongs_def":" uninstructed, i.e. (figuratively) stupid","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3811 (παιδεύω);","lemma":"ἀπαίδευτος","translit":"apaídeutos","kjv_def":"unlearned","pron":"ap-ah'-ee-dyoo-tos","pos":"Adjective","thayer":"<ol><li>without instruction, and disciple, uneducated, ignorant, rude</li></ol>","xlit":"apaídeutos"},"G3447":{"kjv_def":"make a calf","lemma":"μοσχοποιέω","translit":"moschopoiéō","derivation":"from G3448 (μόσχος) and G4160 (ποιέω);","strongs_def":" to fabricate the image of a bullock","pron":"mos-khop-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to make (an image of) a calf</li></ol>","xlit":"moschopoiéō"},"G4590":{"derivation":"of Hebrew origin (H08035);","strongs_def":" Sem (i.e. Shem), a patriarch","kjv_def":" Sem","lemma":"Σήμ","translit":"Sḗm","pron":"same","pos":"Noun Masculine","thayer":"<ol><li>the eldest son of Noah</li></ol>","xlit":"Sḗm"},"G1822":{"strongs_def":" to finish out (time); figuratively, to equip fully (a teacher)","derivation":"from G1537 (ἐκ) and a derivative of G739 (ἄρτιος);","lemma":"ἐξαρτίζω","translit":"exartízō","kjv_def":"accomplish, thoroughly furnish","pron":"ex-ar-tid'-zo","pos":"Verb","thayer":"<ol><li>to complete, finish<ol type='a'><li>to furnish perfectly</li><li>to finish, accomplish, (as it were, to render the days complete)</li></ol></li></ol>","xlit":"exartízō"},"G2084":{"lemma":"ἑτερόγλωσσος","translit":"heteróglōssos","kjv_def":"man of other tongue","strongs_def":" other- tongued, i.e. a foreigner","derivation":"from G2087 (ἕτερος) and G1100 (γλῶσσα);","pron":"het-er-og'-loce-sos","pos":"Adjective","thayer":"<ol><li>one who speaks a foreign language</li></ol>","xlit":"heteróglōssos"},"G4200":{"lemma":"πορισμός","translit":"porismós","kjv_def":"gain","strongs_def":" furnishing (procuring), i.e. (by implication) money-getting (acquisition)","derivation":"from a derivative of (a way, i.e. means);","pron":"por-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>acquisition, gain</li><li>source of gain</li></ol>","xlit":"porismós"},"G5595":{"kjv_def":"(bestow to) feed","lemma":"ψωμίζω","translit":"psōmízō","derivation":"from the base of G5596 (ψωμίον);","strongs_def":" to supply with bits, i.e. (generally) to nourish","pron":"pso-mid'-zo","pos":"Verb","thayer":"<ol><li>to feed by putting a bit or crumb (of food) into the mouth<ol type='a'><li>of infants, young animals etc.</li></ol><li>to feed, nourish</li><li>to give a thing to feed someone, feed out to</li></ol>","xlit":"psōmízō"},"G1672":{"kjv_def":" Gentile, Greek","translit":"Héllēn","lemma":"Ἕλλην","derivation":"from G1671 (Ἑλλάς);","strongs_def":" a Hellen (Grecian) or inhabitant of Hellas; by extension a Greek-speaking person, especially a non-Jew","pron":"hel'-lane","pos":"Noun Masculine","thayer":"<ol><li>a Greek either by nationality, whether a native of the main land or of the Greek islands or colonies</li><li>in a wider sense the name embraces all nations not Jews that made the language, customs, and learning of the Greeks their own; the primary reference is to a difference of religion and worship</li></ol>","xlit":"Héllēn"},"G5104":{"kjv_def":"(used only with other particles in the comparative, as G2544 (καίτοιγε), G3305 (μέντοι), G5105 (τοιγαροῦν), G5106 (τοίνυν), etc","translit":"toí","lemma":"τοί","derivation":"probably for the dative case of G3588 (ὁ);","strongs_def":" an enclitic particle of asseveration by way of contrast; in sooth","pron":"toy","thayer":"<ol><li>certainly, truly</li></ol>","xlit":"toí"},"G5502":{"strongs_def":" \"cherubim\" (i.e. cherubs or kerubim)","derivation":"plural of Hebrew origin (H03742);","lemma":"χερουβίμ","translit":"cheroubím","kjv_def":"cherubims","pron":"kher-oo-beem'","pos":"Noun Neuter","thayer":"<ol><li>cherubim, two golden figures of living creatures with two wings; they were fastened to the lid of the ark of the covenant in the holy of holies (both at the sacred tabernacle and of Solomon's temple) in such a manner that their faces were turned towards each other and down towards the lid, which they overshadowed with their expanded wings. Between these figures God was regarded as having fixed his dwelling place.</li></ol>","xlit":"cheroubím"},"G310":{"strongs_def":" to halloo","derivation":"from G303 (ἀνά) and G994 (βοάω);","lemma":"ἀναβοάω","translit":"anaboáō","kjv_def":"cry (aloud, out)","pron":"an-ab-o-ah'-o","pos":"Verb","thayer":"<ol><li>to raise a cry, to cry out</li></ol>","xlit":"anaboáō"},"G70":{"translit":"agrypnía","lemma":"ἀγρυπνία","kjv_def":"watch","strongs_def":" sleeplessness, i.e. a keeping awake","derivation":"from G69 (ἀγρυπνέω);","pron":"ag-roop-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>sleeplessness, watching</li></ol>","xlit":"agrypnía"},"G2358":{"kjv_def":"(cause) to triumph (over)","lemma":"θριαμβεύω","translit":"thriambeúō","derivation":"from a prolonged compound of the base of G2360 (θροέω);","strongs_def":" and a derivative of G680 (ἅπτομαι) (meaning a noisy iambus, sung in honor of Bacchus); to make an acclamatory procession, i.e. (figuratively) to conquer or (by Hebraism) to give victory","pron":"three-am-byoo'-o","pos":"Verb","thayer":"<ol><li>to triumph, to celebrate a triumph</li><li>cause one to triumph</li></ol>","xlit":"thriambeúō"},"G878":{"derivation":"from G1 (Α) (as a negative particle) and G5424 (φρήν);","strongs_def":" properly, mindless, i.e. stupid, (by implication) ignorant, (specially) egotistic, (practically) rash, or (morally) unbelieving","kjv_def":"fool(-ish), unwise","translit":"áphrōn","lemma":"ἄφρων","pron":"af'-rone","pos":"Adjective","thayer":"<ol><li>without reason</li><li>senseless, foolish, stupid</li><li>without reflection or intelligence, acting rashly</li></ol>","xlit":"áphrōn"},"G2255":{"kjv_def":"half","translit":"hḗmisy","lemma":"ἥμισυ","derivation":"neuter of a derivative from an inseparable prefix akin to G260 (ἅμα) (through the idea of partition involved in connection) and meaning semi-;","strongs_def":" (as noun) half","pron":"hay'-mee-soo","pos":"Adjective","thayer":"<ol><li>half</li></ol>","xlit":"hḗmisy"},"G691":{"strongs_def":" to be idle, i.e. (figuratively) to delay","derivation":"from G692 (ἀργός);","lemma":"ἀργέω","translit":"argéō","kjv_def":"linger","pron":"arg-eh'-o","pos":"Verb","thayer":"<ol><li>to be idle, inactive, to linger, delay</li></ol>","xlit":"argéō"},"G1635":{"kjv_def":"willingly","lemma":"ἑκών","translit":"hekṓn","derivation":"of uncertain affinity;","strongs_def":" voluntary","pron":"hek-own'","pos":"Adjective","thayer":"<ol><li>unforced, voluntary, willing</li><li>of one's own will</li><li>of one's own accord</li></ol>","xlit":"hekṓn"},"G2965":{"lemma":"κύων","translit":"kýōn","kjv_def":"dog","strongs_def":" a dog (\"hound\") (literally or figuratively)","derivation":"a primary word;","pron":"koo'-ohn","pos":"Noun Masculine","thayer":"<ol><li>a dog</li><li>metaphorically a man of impure mind, an impudent man</li></ol>","xlit":"kýōn"},"G1628":{"derivation":"from G1537 (ἐκ) and G5343 (φεύγω);","strongs_def":" to flee out","kjv_def":"escape, flee","translit":"ekpheúgō","lemma":"ἐκφεύγω","pron":"ek-fyoo'-go","pos":"Verb","thayer":"<ol><li>to flee out of, flee away<ol type='a'><li>to seek safety in flight</li><li>to escape</li></ol></li></ol>","xlit":"ekpheúgō"},"G1354":{"strongs_def":" reveller; Dionysius, an Athenian","derivation":"from (Bacchus);","translit":"Dionýsios","lemma":"Διονύσιος","kjv_def":"Dionysius","pron":"dee-on-oo'-see-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Dionysius = \"devoted to Bacchus\"</p><ol><li>an Athenian, a member of the Areopagus, converted to Christianity by Paul</li></ol>","xlit":"Dionýsios"},"G4091":{"lemma":"Πιλᾶτος","translit":"Pilâtos","kjv_def":"Pilate","strongs_def":" close-pressed, i.e. firm; Pilatus, a Roman","derivation":"of Latin origin;","pron":"pil-at'-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Pilate = \"armed with a spear\"</p><ol><li>the sixth Roman procurator of Judah and Samaria who ordered Christ to be crucified</li></ol>","xlit":"Pilâtos"},"G4455":{"derivation":"from G4452 (-πω) and G4218 (ποτέ);","strongs_def":" at any time, i.e. (with negative particle) at no time","kjv_def":"at any time, + never (…to any man), + yet, never man","lemma":"πώποτε","translit":"pṓpote","pron":"po'-pot-e","pos":"Adverb","thayer":"<ol><li>ever, at any time</li></ol>","xlit":"pṓpote"},"G1744":{"translit":"endýnō","lemma":"ἐνδύνω","kjv_def":"creep","strongs_def":" to sink (by implication, wrap (compare G1746 (ἐνδύω)) on, i.e. (figuratively) sneak","derivation":"from G1772 (ἔννομος) and G1416 (δύνω);","pron":"en-doo'-no","pos":"Verb","thayer":"<ol><li>to put on, to envelop in, to hide in<ol type='a'><li>literally: to put on, clothe with a garment</li><li>metaphorically put on armour</li></ol><li>to creep into, insinuate one's self into, to enter</li></ol>","xlit":"endýnō"},"G1580":{"kjv_def":"carry out","lemma":"ἐκκομίζω","translit":"ekkomízō","derivation":"from G1537 (ἐκ) and G2865 (κομίζω);","strongs_def":" to bear forth (to burial)","pron":"ek-kom-id'-zo","pos":"Verb","thayer":"<ol><li>to carry out<ol type='a'><li>a dead man for burial</li></ol></li></ol>","xlit":"ekkomízō"},"G1078":{"derivation":"from the same as G1074 (γενεά);","strongs_def":" nativity; figuratively, nature","kjv_def":"generation, nature(-ral)","lemma":"γένεσις","translit":"génesis","pron":"ghen'-es-is","pos":"Noun Feminine","thayer":"<ol><li>source, origin<ol type='a'><li>a book of one's lineage, i.e. in which his ancestry or progeny are enumerated</li></ol><li>used of birth, nativity</li><li>of that which follows origin, viz. existence, life<ol type='a'><li>the wheel of life (<a class='bible' href='#b59.3.6'>Jas 3:6</a>), other explain it, the wheel of human origin which as soon as men are born begins to run, i.e. its course of life</li></ol></li></ol>","xlit":"génesis"},"G450":{"strongs_def":" to stand up (literal or figurative, transitive or intransitive)","derivation":"from G303 (ἀνά) and G2476 (ἵστημι);","lemma":"ἀνίστημι","translit":"anístēmi","kjv_def":"arise, lift up, raise up (again), rise (again), stand up(-right)","pron":"an-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to cause to rise up, raise up<ol type='a'><li>raise up from laying down</li><li>to raise up from the dead</li><li>to raise up, cause to be born, to cause to appear, bring forward</li></ol><li>to rise, stand up<ol type='a'><li>of persons lying down, of persons lying on the ground</li><li>of persons seated</li><li>of those who leave a place to go elsewhere<ol><li>of those who prepare themselves for a journey</li></ol><li>of the dead</li></ol><li>at arise, appear, stand forth<ol type='a'><li>of kings prophets, priests, leaders of insurgents</li><li>of those about to enter into conversation or dispute with anyone, or to undertake some business, or attempt something against others</li><li>to rise up against any one</li></ol></li></ol>","xlit":"anístēmi"},"G2493":{"derivation":"of Hebrew origin (H03100);","strongs_def":" Joel, an Israelite","kjv_def":"Joel","lemma":"Ἰωήλ","translit":"Iōḗl","pron":"ee-o-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Joel = \"to whom Jehovah is God\"</p><ol><li>the second of the twelve minor prophets, the son of Pethuel, probably prophesied in Judah in the reign of Uzziah</li></ol>","xlit":"Iōḗl"},"G3125":{"strongs_def":" a grandmother","derivation":"of natural origin (\"mammy\");","translit":"mámmē","lemma":"μάμμη","kjv_def":"grandmother","pron":"mam'-may","pos":"Noun Feminine","thayer":"<ol><li>mother (the name infants use in addressing their mother)</li><li>grandmother</li></ol>","xlit":"mámmē"},"G232":{"lemma":"ἁλιεύω","translit":"halieúō","kjv_def":"go a-fishing","strongs_def":" to be a fisher, i.e. (by implication) to fish","derivation":"from G231 (ἁλιεύς);","pron":"hal-ee-yoo'-o","pos":"Verb","thayer":"<ol><li>to fish</li></ol>","xlit":"halieúō"},"G1956":{"lemma":"ἐπιλύω","translit":"epilýō","kjv_def":"determine, expound","strongs_def":" to solve further, i.e. (figuratively) to explain, decide","derivation":"from G1909 (ἐπί) and G3089 (λύω);","pron":"ep-ee-loo'-o","pos":"Verb","thayer":"<ol><li>to unloose, untie</li><li>to clear (a controversy), decide, settle</li><li>to explain (what is obscure and hard to understand)</li></ol>","xlit":"epilýō"},"G4373":{"strongs_def":" recently","derivation":"adverb from G4372 (πρόσφατος);","lemma":"προσφάτως","translit":"prosphátōs","kjv_def":"lately","pron":"pros-fat'-oce","pos":"Adverb","thayer":"<ol><li>lately</li></ol>","xlit":"prosphátōs"},"G4377":{"translit":"prosphōnéō","lemma":"προσφωνέω","kjv_def":"call unto, speak (un-)to","strongs_def":" to sound towards, i.e. address, exclaim, summon","derivation":"from G4314 (πρός) and G5455 (φωνέω);","pron":"pros-fo-neh'-o","pos":"Verb","thayer":"<ol><li>to call to, to address by calling</li><li>to call to one's self, summon</li></ol>","xlit":"prosphōnéō"},"G4806":{"derivation":"from G4862 (σύν) and G2227 (ζωοποιέω);","strongs_def":" to reanimate conjointly with (figuratively)","kjv_def":"quicken together with","translit":"syzōopoiéō","lemma":"συζωοποιέω","pron":"sood-zo-op-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to make one alive together<ol type='a'><li>of Christians, with Christ</li></ol></li></ol>","xlit":"syzōopoiéō"},"G3196":{"strongs_def":" a limb or part of the body","derivation":"of uncertain affinity;","translit":"mélos","lemma":"μέλος","kjv_def":"member","pron":"mel'-os","pos":"Noun Neuter","thayer":"<ol><li>a member, limb: a member of the human body<ol type='a'><li>of bodies given up to criminal intercourse, because they are as it were members belonging to the harlot's body</li></ol></li></ol>","xlit":"mélos"},"G2254":{"lemma":"ἡμῖν","translit":"hēmîn","kjv_def":"our, (for) us, we","strongs_def":" to (or for, with, by) us","derivation":"dative case plural of G1473 (ἐγώ);","pron":"hay-meen'","thayer":"<ol><li>us, we, our</li></ol>","xlit":"hēmîn"},"G358":{"derivation":"from G1 (Α) (as a negative particle) and G251 (ἅλς);","strongs_def":" saltless, i.e. insipid","kjv_def":"X lose saltness","translit":"ánalos","lemma":"ἄναλος","pron":"an'-al-os","pos":"Adjective","thayer":"<ol><li>without salt, unsalted</li></ol>","xlit":"ánalos"},"G1222":{"derivation":"from G1211 (δή) and G4225 (πού);","strongs_def":" a particle of asseveration; indeed doubtless","kjv_def":"verily","translit":"dḗpou","lemma":"δήπου","pron":"day'-poo","pos":"Adverb","thayer":"<ol><li>it is used when something is affirmed in a slightly ironical manner, as if with an pretence of uncertainty<ol type='a'><li>perhaps</li><li>doubtless</li><li>verily</li><li>truly</li></ol></li></ol>","xlit":"dḗpou"},"G4372":{"strongs_def":" previously (recently) slain (fresh), i.e. (figuratively) lately made","derivation":"from G4253 (πρό) and a derivative of G4969 (σφάζω);","lemma":"πρόσφατος","translit":"prósphatos","kjv_def":"new","pron":"pros'-fat-os","pos":"Adjective","thayer":"<ol><li>lately slaughtered, freshly killed</li><li>recently made, new</li></ol>","xlit":"prósphatos"},"G1840":{"derivation":"from G1537 (ἐκ) and G2480 (ἰσχύω);","strongs_def":" to have full strength, i.e. be entirely competent","kjv_def":"be able","lemma":"ἐξισχύω","translit":"exischýō","pron":"ex-is-khoo'-o","pos":"Verb","thayer":"<ol><li>to be eminently able, able, to have full strength</li></ol>","xlit":"exischýō"},"G1427":{"kjv_def":"twelve","lemma":"δώδεκα","translit":"dṓdeka","derivation":"from G1417 (δύο) and G1176 (δέκα);","strongs_def":" two and ten, i.e. a dozen","pron":"do'-dek-ah","pos":"Noun","thayer":"<ol><li>twelve<ol type='a'><li>the twelve apostles of Jesus, so called by way of eminence</li></ol></li></ol>","xlit":"dṓdeka"},"G554":{"kjv_def":"put off, spoil","lemma":"ἀπεκδύομαι","translit":"apekdýomai","derivation":"middle voice from G575 (ἀπό) and G1562 (ἐκδύω);","strongs_def":" to divest wholly oneself, or (for oneself) despoil","pron":"ap-ek-doo'-om-ahee","pos":"Verb","thayer":"<ol><li>wholly put off from one's self<ol type='a'><li>denoting separation from what is put off</li></ol><li>wholly to strip off for one's self (for one's own advantage)</li><li>despoil, disarm</li></ol>","xlit":"apekdýomai"},"G2986":{"translit":"lamprós","lemma":"λαμπρός","kjv_def":"bright, clear, gay, goodly, gorgeous, white","strongs_def":" radiant; by analogy, limpid; figuratively, magnificent or sumptuous (in appearance)","derivation":"from the same as G2985 (λαμπάς);","pron":"lam-pros'","pos":"Adjective","thayer":"<ol><li>shining<ol type='a'><li>brilliant</li><li>clear, transparent</li></ol><li>splendid, magnificent<ol type='a'><li>splendid things, i.e. luxuries or elegancies in dress or style</li></ol></li></ol>","xlit":"lamprós"},"G5172":{"strongs_def":" effeminacy, i.e. luxury or debauchery","derivation":"from (to break up or (figuratively) enfeeble, especially the mind and body by indulgence);","translit":"tryphḗ","lemma":"τρυφή","kjv_def":"delicately, riot","pron":"troo-fay'","pos":"Noun Feminine","thayer":"<ol><li>softness, effeminate, luxurious living</li></ol>","xlit":"tryphḗ"},"G3158":{"translit":"Matthát","lemma":"Ματθάτ","kjv_def":"Mathat","strongs_def":" Matthat (i.e. Mattithjah), the name of two Israelites","derivation":"probably a shortened form of G3161 (Ματταθίας);","pron":"mat-that'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Matthat = \"gift of God\"</p><ol><li>a son of Levi, in the genealogy of Christ</li><li>grandfather of the Mary</li></ol>","xlit":"Matthát"},"G5289":{"lemma":"ὑποστολή","translit":"hypostolḗ","kjv_def":"draw back","strongs_def":" shrinkage (timidity), i.e. (by implication) apostasy","derivation":"from G5288 (ὑποστέλλω);","pron":"hoop-os-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>the timidity of one stealthily retreating</li></ol>","xlit":"hypostolḗ"},"G4718":{"derivation":"probably from the base of G4735 (στέφανος);","strongs_def":" a cluster of grapes (as if intertwined)","kjv_def":"grapes","lemma":"σταφυλή","translit":"staphylḗ","pron":"staf-oo-lay'","pos":"Noun Feminine","thayer":"<ol><li>grapes, bunch of grapes</li></ol>","xlit":"staphylḗ"},"G2433":{"kjv_def":"be merciful, make reconciliation for","translit":"hiláskomai","lemma":"ἱλάσκομαι","derivation":"middle voice from the same as G2436 (ἵλεως);","strongs_def":" to conciliate, i.e. (transitively) to atone for (sin), or (intransitively) be propitious","pron":"hil-as'-kom-ahee","pos":"Verb","thayer":"<ol><li>to render one's self, to appease, conciliate to one's self<ol type='a'><li>to become propitious, be placated or appeased</li><li>to be propitious, be gracious, be merciful</li></ol><li>to expiate, make propitiation for</li></ol>","xlit":"hiláskomai"},"G5574":{"kjv_def":"falsely, lie","translit":"pseúdomai","lemma":"ψεύδομαι","derivation":"middle voice of an apparently primary verb;","strongs_def":" to utter an untruth or attempt to deceive by falsehood","pron":"psyoo'-dom-ahee","pos":"Verb","thayer":"<ol><li>to lie, to speak deliberate falsehoods</li><li>to deceive one by a lie, to lie to</li></ol>","xlit":"pseúdomai"},"G5324":{"kjv_def":"sight","translit":"phantázō","lemma":"φαντάζω","derivation":"from a derivative of G5316 (φαίνω);","strongs_def":" to make apparent, i.e. (passively) to appear (neuter participle as noun, a spectacle)","pron":"fan-tad'-zo","pos":"Verb","thayer":"<ol><li>to cause to appear, make visible, expose to view, show<ol type='a'><li>the appearance, sight</li></ol></li></ol>","xlit":"phantázō"},"G3918":{"kjv_def":"come, X have, be here, + lack, (be here) present","translit":"páreimi","lemma":"πάρειμι","derivation":"from G3844 (παρά) and G1510 (εἰμί) (including its various forms);","strongs_def":" to be near, i.e. at hand; neuter present participle (singular) time being, or (plural) property","pron":"par'-i-mee","pos":"Verb","thayer":"<ol><li>to be by, be at hand, to have arrived, to be present</li><li>to be ready, in store, at command</li></ol>","xlit":"páreimi"},"G2617":{"strongs_def":" to shame down, i.e. disgrace or (by implication) put to the blush","derivation":"from G2596 (κατά) and G153 (αἰσχύνομαι);","translit":"kataischýnō","lemma":"καταισχύνω","kjv_def":"confound, dishonour, (be a-, make a-)shame(-d)","pron":"kat-ahee-skhoo'-no","pos":"Verb","thayer":"<ol><li>to dishonour, disgrace</li><li>to put to shame, make ashamed<ol type='a'><li>to be ashamed, blush with shame</li><li>one is said to be put to shame who suffers a repulse, or whom some hope has deceived</li></ol></li></ol>","xlit":"kataischýnō"},"G4057":{"derivation":"adverb from G4053 (περισσός);","strongs_def":" superabundantly","kjv_def":"exceedingly, out of measure, the more","translit":"perissōs","lemma":"περισσῶς","pron":"per-is-soce'","pos":"Adverb","thayer":"<ol><li>beyond measure, extraordinary</li><li>greatly, exceedingly</li></ol>","xlit":"perissōs"},"G244":{"strongs_def":" overseeing others' affairs, i.e. a meddler (specially, in Gentile customs)","derivation":"from G245 (ἀλλότριος) and G1985 (ἐπίσκοπος);","translit":"allotriepískopos","lemma":"ἀλλοτριεπίσκοπος","kjv_def":"busybody in other men's matters","pron":"al-lot-ree-ep-is'-kop-os","pos":"Noun Masculine","thayer":"<ol><li>one who takes the supervision of affairs pertaining to others and in no wise to himself, a meddler in other men's affairs</li></ol>","xlit":"allotriepískopos"},"G3759":{"derivation":"a primary exclamation of grief;","strongs_def":" \"woe\"","kjv_def":"alas, woe","translit":"ouaí","lemma":"οὐαί","pron":"oo-ah'-ee","thayer":"<ol><li>alas, woe</li></ol>","xlit":"ouaí"},"G3555":{"kjv_def":"brood","lemma":"νοσσιά","translit":"nossiá","derivation":"from G3502 (νεοσσός);","strongs_def":" a brood (of chickens)","pron":"nos-see-ah'","pos":"Noun Feminine","thayer":"<ol><li>a nest of birds</li><li>a brood of birds</li></ol>","xlit":"nossiá"},"G2497":{"translit":"Iōreím","lemma":"Ἰωρείμ","kjv_def":"Jorim","strongs_def":" Jorim, an Israelite","derivation":"perhaps for G2496 (Ἰωράμ);","pron":"ee-o-rime'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jorim = \"whom Jehovah has exalted\"</p><ol><li>the son of Matthat, in the genealogy of Christ</li></ol>","xlit":"Iōreím"},"G2650":{"kjv_def":"abide","translit":"kataménō","lemma":"καταμένω","derivation":"from G2596 (κατά) and G3306 (μένω);","strongs_def":" to stay fully, i.e. reside","pron":"kat-am-en'-o","pos":"Verb","thayer":"<ol><li>to remain permanently, to abide</li></ol>","xlit":"kataménō"},"G5578":{"strongs_def":" a spurious prophet, i.e. pretended foreteller or religious impostor","derivation":"from G5571 (ψευδής) and G4396 (προφήτης);","lemma":"ψευδοπροφήτης","translit":"pseudoprophḗtēs","kjv_def":"false prophet","pron":"psyoo-dop-rof-ay'-tace","pos":"Noun Masculine","thayer":"<ol><li>one who, acting the part of a divinely inspired prophet, utters falsehoods under the name of divine prophecies</li><li>a false prophet</li></ol>","xlit":"pseudoprophḗtēs"},"G3703":{"lemma":"ὀπώρα","translit":"opṓra","kjv_def":"fruit","strongs_def":" properly, even-tide of the (summer) season (dog-days), i.e. (by implication) ripe fruit","derivation":"apparently from the base of G3796 (ὀψέ) and G5610 (ὥρα);","pron":"op-o'-rah","pos":"Noun Feminine","thayer":"<ol><li>the season which succeeds summer, from the rising of Sirius to that of Arcturus, i.e. from late summer, early autumn, our dog days</li><li>ripe fruits (of trees)</li></ol>","xlit":"opṓra"},"G989":{"strongs_def":" scurrilious, i.e. calumnious (against men), or (specially) impious (against God)","derivation":"from a derivative of G984 (βλάπτω) and G5345 (φήμη);","lemma":"βλάσφημος","translit":"blásphēmos","kjv_def":"blasphemer(-mous), railing","pron":"blas'-fay-mos","pos":"Adjective","thayer":"<ol><li>speaking evil, slanderous, reproachful, railing, abusive</li></ol>","xlit":"blásphēmos"},"G4726":{"lemma":"στεναγμός","translit":"stenagmós","kjv_def":"groaning","strongs_def":" a sigh","derivation":"from G4727 (στενάζω);","pron":"sten-ag-mos'","pos":"Noun Masculine","thayer":"<ol><li>a groaning, a sigh</li></ol>","xlit":"stenagmós"},"G2260":{"lemma":"ἤπερ","translit":"ḗper","kjv_def":"than","strongs_def":" than at all (or than perhaps, than indeed)","derivation":"from G2228 (ἤ) and G4007 (περ);","pron":"ay'-per","thayer":"<ol><li>than</li></ol>","xlit":"ḗper"},"G1834":{"lemma":"ἐξηγέομαι","translit":"exēgéomai","kjv_def":"declare, tell","strongs_def":" to consider out (aloud), i.e. rehearse, unfold","derivation":"from G1537 (ἐκ) and G2233 (ἡγέομαι);","pron":"ex-ayg-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to lead out, be leader, go before</li><li>metaphorically, to draw out in narrative, unfold a teaching<ol type='a'><li>to recount, rehearse</li><li>to unfold, declare<ol><li>the things relating to God</li><li>used in Greek writing of the interpretation of things sacred and divine, oracles, dreams, etc.</li></ol></li></ol></li></ol>","xlit":"exēgéomai"},"G749":{"derivation":"from G746 (ἀρχή) and G2409 (ἱερεύς);","strongs_def":" the high-priest (literally, of the Jews, typically, Christ); by extension a chief priest","kjv_def":"chief (high) priest, chief of the priests","lemma":"ἀρχιερεύς","translit":"archiereús","pron":"ar-khee-er-yuce'","pos":"Noun Masculine","thayer":"<ol><li>chief priest, high priest - He above all others was honoured with the title of priest, the chief of priests. It was lawful for him to perform the common duties of the priesthood; but his chief duty was, once a year on the day of atonement, to enter into the Holy of Holies (from which the other priests were excluded) and offer sacrifices for his own sins and the sins of the people, and to preside over the Sanhedrin, or Supreme Council, when convened for judicial deliberations. According to Mosaic law, no one could aspire to the high priesthood unless he were of the tribe of Aaron and descended from a high priestly family; and he on whom the office was conferred held it till death. But from the time of Antiochus Epiphanes, when the kings of Seleucideae and afterwards the Herodian princes and the Romans arrogated to themselves the power of appointing the high priests, the office neither remained vested in the pontifical family nor was conferred on any for life; but it became venal, and could be transferred from one to another according to the will of civic or military rulers. Hence it came to pass, that during the one hundred and seven years intervening between Herod the Great and the destruction of the holy city, twenty eight persons held the pontifical dignity.</li><li>the high priests, these comprise in addition to one holding the high priestly office, both those who had previously discharged it and although disposed, continued to have great power in the State, as well as the members of the families from which high priest were created, provided that they had much influence in public affairs.</li><li>Used of Christ because by undergoing a bloody death he offered himself as an expiatory sacrifice to God, and has entered into the heavenly sanctuary where he continually intercedes on our behalf.</li></ol>","xlit":"archiereús"},"G178":{"strongs_def":" without (legal) trial","derivation":"from G1 (Α) (as a negative particle) and a derivative of G2632 (κατακρίνω);","lemma":"ἀκατάκριτος","translit":"akatákritos","kjv_def":"uncondemned","pron":"ak-at-ak'-ree-tos","pos":"Adjective","thayer":"<ol><li>uncondemned, punished without being tried</li></ol>","xlit":"akatákritos"},"G4825":{"translit":"sýmboulos","lemma":"σύμβουλος","kjv_def":"counsellor","strongs_def":" a consultor, i.e. adviser","derivation":"from G4862 (σύν) and G1012 (βουλή);","pron":"soom'-boo-los","pos":"Noun Masculine","thayer":"<ol><li>an adviser, counsellor</li></ol>","xlit":"sýmboulos"},"G4747":{"translit":"stoicheîon","lemma":"στοιχεῖον","kjv_def":"element, principle, rudiment","strongs_def":" something orderly in arrangement, i.e. (by implication) a serial (basal, fundamental, initial) constituent (literally), proposition (figuratively)","derivation":"neuter of a presumed derivative of the base of G4748 (στοιχέω);","pron":"stoy-khi'-on","pos":"Noun Neuter","thayer":"<ol><li>any first thing, from which the others belonging to some series or composite whole take their rise, an element, first principal<ol type='a'><li>the letters of the alphabet as the elements of speech, not however the written characters, but the spoken sounds</li><li>the elements from which all things have come, the material causes of the universe</li><li>the heavenly bodies, either as parts of the heavens or (as others think) because in them the elements of man, life and destiny were supposed to reside</li><li>the elements, rudiments, primary and fundamental principles of any art, science, or discipline<ol><li>i.e. of mathematics, Euclid's geometry</li></ol></li></ol></li></ol>","xlit":"stoicheîon"},"G3946":{"kjv_def":"like","translit":"parómoios","lemma":"παρόμοιος","derivation":"from G3844 (παρά) and G3664 (ὅμοιος);","strongs_def":" alike nearly, i.e. similar","pron":"par-om'-oy-os","pos":"Adjective","thayer":"<ol><li>like</li></ol>","xlit":"parómoios"},"G5517":{"lemma":"χοϊκός","translit":"choïkós","kjv_def":"earthy","strongs_def":" dusty or dirty (soil-like), i.e. (by implication) terrene","derivation":"from G5522 (χόος);","pron":"kho-ik-os'","pos":"Adjective","thayer":"<ol><li>made of earth, earthy</li></ol>","xlit":"choïkós"},"G2123":{"strongs_def":" better for toil, i.e. more facile","derivation":"comparative of a compound of G2095 (εὖ) and G2873 (κόπος);","translit":"eukopṓteros","lemma":"εὐκοπώτερος","kjv_def":"easier","pron":"yoo-kop-o'-ter-os","pos":"Adjective","thayer":"<ol><li>with easy labour</li><li>easy</li></ol>","xlit":"eukopṓteros"},"G2389":{"derivation":"of Egyptian origin;","strongs_def":" Jannes, an Egyptian","kjv_def":"Jannes","translit":"Iannēs","lemma":"Ἰαννῆς","pron":"ee-an-nace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Janna = \"he vexed\"</p><ol><li>he and Jambres, were two Egyptian magicians who in the presence of Pharaoh imitated the miracles of Aaron in order to destroy his influence with the king. The author of the epistle derived their names from the tradition of the Talmudists and the Rabbins</li></ol>","xlit":"Iannēs"},"G1745":{"lemma":"ἔνδυσις","translit":"éndysis","kjv_def":"putting on","strongs_def":" investment with clothing","derivation":"from G1746 (ἐνδύω);","pron":"en'-doo-sis","pos":"Noun Feminine","thayer":"<ol><li>a putting on</li></ol>","xlit":"éndysis"},"G3133":{"kjv_def":"fade away","translit":"maraínō","lemma":"μαραίνω","derivation":"of uncertain affinity;","strongs_def":" to extinguish (as fire), i.e. (figuratively and passively) to pass away","pron":"mar-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to extinguish (a flame, fire, light, etc.)</li><li>to render arid, make to waste away, consume away, perish</li><li>to have a miserable end</li></ol>","xlit":"maraínō"},"G1625":{"lemma":"ἐκτρέφω","translit":"ektréphō","kjv_def":"bring up, nourish","strongs_def":" to rear up to maturity, i.e. (genitive case) to cherish or train","derivation":"from G1537 (ἐκ) and G5142 (τρέφω);","pron":"ek-tref'-o","pos":"Verb","thayer":"<ol><li>to nourish up to maturity, to nourish</li><li>to nurture, bring up</li></ol>","xlit":"ektréphō"},"G72":{"derivation":"reduplicated from G71 (ἄγω);","strongs_def":" a bringing up, i.e. mode of living","kjv_def":"manner of life","translit":"agōgḗ","lemma":"ἀγωγή","pron":"ag-o-gay'","pos":"Noun Feminine","thayer":"<ol><li>a leading</li><li>metaphorically: conduct<ol type='a'><li>a conducting, training, education, discipline</li><li>the life led, way or course of life</li></ol></li></ol>","xlit":"agōgḗ"},"G4916":{"translit":"syntháptō","lemma":"συνθάπτω","kjv_def":"bury with","strongs_def":" to inter in company with, i.e. (figuratively) to assimilate spiritually (to Christ by a sepulture as to sin)","derivation":"from G4862 (σύν) and G2290 (θάπτω);","pron":"soon-thap'-to","pos":"Verb","thayer":"<ol><li>to bury together with</li></ol>","xlit":"syntháptō"},"G4671":{"kjv_def":"thee, thine own, thou, thy","translit":"soí","lemma":"σοί","derivation":"dative case of G4771 (σύ);","strongs_def":" to thee","pron":"soy","thayer":"<ol><li>to you</li></ol>","xlit":"soí"},"G3983":{"lemma":"πεινάω","translit":"peináō","kjv_def":"be an hungered","strongs_def":" \"pine\"); to famish (absolutely or comparatively); figuratively, to crave","derivation":"from the same as G3993 (πένης) (through the idea of pinching toil;","pron":"pi-nah'-o","pos":"Verb","thayer":"<ol><li>to hunger, be hungry<ol type='a'><li>to suffer want</li><li>to be needy</li></ol><li>metaphorically to crave ardently, to seek with eager desire</li></ol>","xlit":"peináō"},"G4307":{"derivation":"from G4306 (προνοέω);","strongs_def":" forethought, i.e. provident care or supply","kjv_def":"providence, provision","translit":"prónoia","lemma":"πρόνοια","pron":"pron'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>forethought, providential care</li><li>to make provision for a thing</li></ol>","xlit":"prónoia"},"G1993":{"strongs_def":" to put something over the mouth, i.e. (figuratively) to silence","derivation":"from G1909 (ἐπί) and G4750 (στόμα);","lemma":"ἐπιστομίζω","translit":"epistomízō","kjv_def":"stop mouths","pron":"ep-ee-stom-id'-zo","pos":"Verb","thayer":"<ol><li>to bridle or stop up the mouth</li><li>metaphorically to stop the mouth, reduce to silence</li></ol>","xlit":"epistomízō"},"G3938":{"lemma":"πάροδος","translit":"párodos","kjv_def":"way","strongs_def":" a by-road, i.e. (actively) a route","derivation":"from G3844 (παρά) and G3598 (ὁδός);","pron":"par'-od-os","pos":"Noun Feminine","thayer":"<ol><li>a passing by or passage</li><li>in passing</li></ol>","xlit":"párodos"},"G4014":{"strongs_def":" to remove all around, i.e. unveil, cast off (anchor); figuratively, to expiate","derivation":"from G4012 (περί) and G138 (αἱρέομαι) (including its alternate);","lemma":"περιαιρέω","translit":"periairéō","kjv_def":"take away (up)","pron":"per-ee-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to take away that which surrounds or envelopes a thing</li><li>metaphorically to take away altogether or entirely<ol type='a'><li>the guilt of sin, to expiate perfectly</li></ol></li></ol>","xlit":"periairéō"},"G4220":{"derivation":"neuter of a comparative of the base of G4226 (ποῦ);","strongs_def":" interrogative as adverb, which (of two), i.e. is it this or that","kjv_def":"whether","lemma":"πότερον","translit":"póteron","pron":"pot'-er-on","pos":"Conjunction","thayer":"<ol><li>which of two</li></ol>","xlit":"póteron"},"G3909":{"derivation":"from G3844 (παρά) and G5177 (τυγχάνω);","strongs_def":" to chance near, i.e. fall in with","kjv_def":"meet with","translit":"paratynchánō","lemma":"παρατυγχάνω","pron":"par-at-oong-khan'-o","pos":"Verb","thayer":"<ol><li>to chance to be by, to happen to be present, to meet by chance</li></ol>","xlit":"paratynchánō"},"G1645":{"strongs_def":" light, i.e. easy","derivation":"probably akin to G1643 (ἐλαύνω) and the base of G1640 (ἐλάσσων);","lemma":"ἐλαφρός","translit":"elaphrós","kjv_def":"light","pron":"el-af-ros'","pos":"Adjective","thayer":"<ol><li>light in weight, quick, agile</li></ol>","xlit":"elaphrós"},"G1037":{"lemma":"βυθός","translit":"bythós","kjv_def":"deep","strongs_def":" depth, i.e. (by implication) the sea","derivation":"a variation of G899 (βάθος);","pron":"boo-thos'","pos":"Noun Masculine","thayer":"<ol><li>the bottom or depth of the sea</li><li>the sea itself, the deep sea</li></ol>","xlit":"bythós"},"G573":{"derivation":"probably from G1 (Α) (as a particle of union) and the base of G4120 (πλέκω);","strongs_def":" properly, folded together, i.e. single (figuratively, clear)","kjv_def":"single","lemma":"ἁπλοῦς","translit":"haploûs","pron":"hap-looce'","pos":"Adjective","thayer":"<ol><li>simple, single</li><li>whole</li><li>good fulfilling its office, sound<ol type='a'><li>of the eye</li></ol></li></ol>","xlit":"haploûs"},"G4444":{"translit":"pýrgos","lemma":"πύργος","kjv_def":"tower","strongs_def":" a tower or castle","derivation":"apparently a primary word (\"burgh\");","pron":"poor'-gos","pos":"Noun Masculine","thayer":"<ol><li>a tower</li><li>a fortified structure rising to a considerable height, to repel a hostile attack or to enable a watchman to see in every direction</li></ol>","xlit":"pýrgos"},"G5011":{"translit":"tapeinós","lemma":"ταπεινός","kjv_def":"base, cast down, humble, of low degree (estate), lowly","strongs_def":" depressed, i.e. (figuratively) humiliated (in circumstances or disposition)","derivation":"of uncertain derivation;","pron":"tap-i-nos'","pos":"Adjective","thayer":"<ol><li>not rising far from the ground</li><li>metaphorically<ol type='a'><li>as a condition, lowly, of low degree</li><li>brought low with grief, depressed</li><li>lowly in spirit, humble</li><li>in a bad sense, deporting one's self abjectly, deferring servilely to others</li></ol></li></ol>","xlit":"tapeinós"},"G1219":{"derivation":"from G1218 (δῆμος);","strongs_def":" public; (feminine singular dative case as adverb) in public","kjv_def":"common, openly, publickly","lemma":"δημόσιος","translit":"dēmósios","pron":"day-mos'ee-os","pos":"Adjective","thayer":"<ol><li>belonging to the people or state, public</li><li>publicly, in public places, in full view of all</li></ol>","xlit":"dēmósios"},"G4555":{"derivation":"from the same as G4556 (σάρδιος);","strongs_def":" sardine (G3037 (λίθος) being implied), i.e. a gem, so called","kjv_def":"sardine","translit":"sárdinos","lemma":"σάρδινος","pron":"sar'-dee-nos","pos":"Adjective","thayer":"<ol><li>a sardius, a precious stone of which there are two types, the former is called a carnelian (because flesh coloured) and the latter a sard</li></ol>","xlit":"sárdinos"},"G433":{"kjv_def":"convenient, be fit","translit":"anḗkō","lemma":"ἀνήκω","derivation":"from G303 (ἀνά) and G2240 (ἥκω);","strongs_def":" to attain to, i.e. (figuratively) be proper","pron":"an-ay'-ko","pos":"Verb","thayer":"<ol><li>to have come up to, arrived at, to reach to</li><li>to pertain to what is due, duty, as was fitting</li></ol>","xlit":"anḗkō"},"G128":{"kjv_def":"Ethiopian","translit":"Aithíops","lemma":"Αἰθίοψ","derivation":"from (to scorch) and (the face, from G3700 (ὀπτάνομαι));","strongs_def":" an Æthiopian (as a blackamoor)","pron":"ahee-thee'-ops","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Ethiopian = \"black\"</p><ol><li>an Ethiopian</li></ol>","xlit":"Aithíops"},"G3895":{"lemma":"παραπίπτω","translit":"parapíptō","kjv_def":"fall away","strongs_def":" to fall aside, i.e. (figuratively) to apostatize","derivation":"from G3844 (παρά) and G4098 (πίπτω);","pron":"par-ap-ip'-to","pos":"Verb","thayer":"<ol><li>to fall beside a person or thing</li><li>to slip aside<ol type='a'><li>to deviate from the right path, turn aside, wander</li><li>to error</li><li>to fall away (from the true faith): from worship of Jehovah</li></ol></li></ol>","xlit":"parapíptō"},"G2223":{"kjv_def":"girdle, purse","lemma":"ζώνη","translit":"zṓnē","derivation":"probably akin to the base of G2218 (ζυγός);","strongs_def":" a belt; by implication, a pocket","pron":"dzo'-nay","pos":"Noun Feminine","thayer":"<ol><li>a girdle, belt, serving not only to gird on flowing garments but also, since it was hollow, to carry money in</li></ol>","xlit":"zṓnē"},"G2059":{"strongs_def":" to translate","derivation":"from a presumed derivative of G2060 (Ἑρμῆς) (as the god of language);","translit":"hermēneúō","lemma":"ἑρμηνεύω","kjv_def":"interpret","pron":"her-mayn-yoo'-o","pos":"Verb","thayer":"<ol><li>to explain in words, expound</li><li>to interpret<ol type='a'><li>to translate what has been spoken or written in a foreign tongue into the vernacular</li></ol></li></ol>","xlit":"hermēneúō"},"G5047":{"lemma":"τελειότης","translit":"teleiótēs","kjv_def":"perfection(-ness)","strongs_def":" (the state) completeness (mentally or morally)","derivation":"from G5046 (τέλειος);","pron":"tel-i-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>perfection<ol type='a'><li>the state of the more intelligent</li><li>moral and spiritual perfection</li></ol></li></ol>","xlit":"teleiótēs"},"G3593":{"lemma":"ὁδεύω","translit":"hodeúō","kjv_def":"journey","strongs_def":" to travel","derivation":"from G3598 (ὁδός);","pron":"hod-yoo'-o","pos":"Verb","thayer":"<ol><li>to travel, journey</li></ol>","xlit":"hodeúō"},"G1547":{"derivation":"from G1537 (ἐκ) and a form of G1061 (γαμίσκω) (compare G1548 (ἐκγαμίσκω));","strongs_def":" to marry off a daughter","kjv_def":"give in marriage","translit":"ekgamízō","lemma":"ἐκγαμίζω","pron":"ek-gam-id'-zo","pos":"Verb","thayer":"<ol><li>to give away in marriage: a daughter</li><li>to marry, to be given in marriage</li></ol>","xlit":"ekgamízō"},"G3052":{"translit":"lógios","lemma":"λόγιος","kjv_def":"eloquent","strongs_def":" fluent, i.e. an orator","derivation":"from G3056 (λόγος);","pron":"log'-ee-os","pos":"Adjective","thayer":"<ol><li>learned, a man of letters, skilled in literature and the arts, especially versed in history and the antiquities</li><li>skilled in speech, eloquent</li><li>rational, wise</li></ol>","xlit":"lógios"},"G1471":{"strongs_def":" swelling inside, i.e. pregnant","derivation":"from G1722 (ἐν) and the base of G2949 (κῦμα);","lemma":"ἔγκυος","translit":"énkyos","kjv_def":"great with child","pron":"eng'-koo-os","pos":"Adjective","thayer":"<ol><li>big with child, pregnant</li></ol>","xlit":"énkyos"},"G5424":{"kjv_def":"understanding","translit":"phrḗn","lemma":"φρήν","derivation":"probably from an obsolete (to rein in or curb; compare G5420 (φράσσω));","strongs_def":" the midrif (as a partition of the body), i.e. (figuratively and by implication, of sympathy) the feelings (or sensitive nature; by extension (also in the plural) the mind or cognitive faculties)","pron":"frane","pos":"Noun Feminine","thayer":"<ol><li>the midriff or diaphragm, the parts of the heart</li><li>the mind<ol type='a'><li>the faculty of perceiving and judging</li></ol></li></ol>","xlit":"phrḗn"},"G1939":{"lemma":"ἐπιθυμία","translit":"epithymía","kjv_def":"concupiscence, desire, lust (after)","strongs_def":" a longing (especially for what is forbidden)","derivation":"from G1937 (ἐπιθυμέω);","pron":"ep-ee-thoo-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>desire, craving, longing, desire for what is forbidden, lust</li></ol>","xlit":"epithymía"},"G4314":{"lemma":"πρός","translit":"prós","kjv_def":"about, according to , against, among, at, because of, before, between, (where-)by, for, X at thy house, in, for intent, nigh unto, of, which pertain to, that, to (the end that), X together, to (you) -ward, unto, with(-in)","strongs_def":" a preposition of direction; forward to, i.e. toward (with the genitive case, the side of, i.e. pertaining to; with the dative case, by the side of, i.e. near to; usually with the accusative case, the place, time, occasion, or respect, which is the destination of the relation, i.e. whither or for which it is predicated)","derivation":"a strengthened form of G4253 (πρό);","pron":"pros","pos":"Preposition","thayer":"<ol><li>to the advantage of</li><li>at, near, by</li><li>to, towards, with, with regard to</li></ol>","xlit":"prós"},"G379":{"translit":"anapológētos","lemma":"ἀναπολόγητος","kjv_def":"without an excuse, inexcusable","strongs_def":" indefensible","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G626 (ἀπολογέομαι);","pron":"an-ap-ol-og'-ay-tos","pos":"Adjective","thayer":"<ol><li>without defense or excuse</li><li>that which cannot be defended, inexcusable</li></ol>","xlit":"anapológētos"},"G107":{"derivation":"of Hebrew origin (compare H05809);","strongs_def":" Azor, an Israelite","kjv_def":"Azorigin ","translit":"Azṓr","lemma":"Ἀζώρ","pron":"ad-zore'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Azor = \"helper\"</p><ol><li>A son of Eliakim, in the line of our Lord. <a class='bible' href='#b40.1.13'>Mat 1:13</a>,<a class='bible' href='#b40.1.14'>Mat 1:14</a>.</li></ol>","xlit":"Azṓr"},"G791":{"strongs_def":" urbane, i.e. (by implication) handsome","derivation":"from (a city);","lemma":"ἀστεῖος","translit":"asteîos","kjv_def":"fair","pron":"as-ti'-os","pos":"Adjective","thayer":"<ol><li>of the city</li><li>of polished manners</li><li>elegant (of body), comely, fair</li></ol>","xlit":"asteîos"},"G5581":{"kjv_def":"falsely so called","lemma":"ψευδώνυμος","translit":"pseudṓnymos","derivation":"from G5571 (ψευδής) and G3686 (ὄνομα);","strongs_def":" untruly named","pron":"psyoo-do'-noo-mos","pos":"Adjective","thayer":"<ol><li>falsely named</li></ol>","xlit":"pseudṓnymos"},"G5329":{"strongs_def":" Phares (i.e. Perets), an Israelite","derivation":"of Hebrew origin (H06557);","lemma":"Φάρες","translit":"Pháres","kjv_def":"Phares","pron":"far-es'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Pharez = \"a breach\"</p><ol><li>the son of Judah and Tamar, his daughter-in-law</li></ol>","xlit":"Pháres"},"G3755":{"strongs_def":" during which same time, i.e. whilst","derivation":"for the genitive case of G3748 (ὅστις) (as adverb);","translit":"hótou","lemma":"ὅτου","kjv_def":"whiles","pron":"hot'-oo","thayer":"<ol><li>while, until</li></ol>","xlit":"hótou"},"G290":{"strongs_def":" a vineyard","derivation":"from G288 (ἄμπελος);","translit":"ampelṓn","lemma":"ἀμπελών","kjv_def":"vineyard","pron":"am-pel-ohn'","pos":"Noun Masculine","thayer":"<ol><li>a vineyard</li></ol>","xlit":"ampelṓn"},"G1636":{"strongs_def":" an olive (the tree or the fruit)","derivation":"feminine of a presumed derivative from an obsolete primary;","lemma":"ἐλαία","translit":"elaía","kjv_def":"olive (berry, tree)","pron":"el-ah'-yah","pos":"Noun Feminine","thayer":"<ol><li>an olive tree</li><li>an olive, the fruit of an olive tree</li></ol>","xlit":"elaía"},"G3439":{"derivation":"from G3441 (μόνος) and G1096 (γίνομαι);","strongs_def":" only-born, i.e. sole","kjv_def":"only (begotten, child)","translit":"monogenḗs","lemma":"μονογενής","pron":"mon-og-en-ace'","pos":"Adjective","thayer":"<ol><li>single of its kind, only<ol type='a'><li>used of only sons or daughters (viewed in relation to their parents)</li><li>used of Christ, denotes the only begotten son of God</li></ol></li></ol>","xlit":"monogenḗs"},"G4977":{"strongs_def":" to split or sever (literally or figuratively)","derivation":"apparently a primary verb;","lemma":"σχίζω","translit":"schízō","kjv_def":"break, divide, open, rend, make a rent","pron":"skhid'-zo","pos":"Verb","thayer":"<ol><li>to cleave, cleave asunder, rend</li><li>to divide by rending</li><li>to split into factions, be divided</li></ol>","xlit":"schízō"},"G2315":{"translit":"theópneustos","lemma":"θεόπνευστος","kjv_def":"given by inspiration of God","strongs_def":" divinely breathed in","derivation":"from G2316 (θεός) and a presumed derivative of G4154 (πνέω);","pron":"theh-op'-nyoo-stos","pos":"Adjective","thayer":"<ol><li>inspired by God<ol type='a'><li>the contents of the scriptures</li></ol></li></ol>","xlit":"theópneustos"},"G2357":{"lemma":"θρησκός","translit":"thrēskós","kjv_def":"religious","strongs_def":" ceremonious in worship (as demonstrative), i.e. pious","derivation":"probably from the base of G2360 (θροέω);","pron":"thrace'-kos","pos":"Adjective","thayer":"<ol><li>fearing or worshipping God</li><li>to tremble<ol type='a'><li>trembling, fearful</li></ol></li></ol>","xlit":"thrēskós"},"G2455":{"derivation":"of Hebrew origin (H03063);","strongs_def":" Judas (i.e. Jehudah), the name of ten Israelites; also of the posterity of one of them and its region","kjv_def":"Juda(-h, -s); Jude","lemma":"Ἰούδας","translit":"Ioúdas","pron":"ee-oo-das'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Judah or Judas = \"he shall be praised\"</p><ol><li>the fourth son of Jacob</li><li>an unknown ancestor of Christ</li><li>a man surnamed the Galilean, who at the time of the census of Quirinus, excited the revolt in Galilee, <a class='bible' href='#b44.5.37'>Act 5:37</a></li><li>a certain Jew of Damascus, <a class='bible' href='#b44.9.11'>Act 9:11</a></li><li>a prophet surnamed Barsabas, of the church at Jerusalem, <a class='bible' href='#b44.15.22'>Act 15:22</a>,<a class='bible' href='#b44.15.27'>Act 15:27</a>,<a class='bible' href='#b44.15.32'>Act 15:32</a></li><li>the apostle, <a class='bible' href='#b43.14.22'>Joh 14:22</a>, who was surnamed Lebbaeus or Thaddaeus, and according to opinion wrote the Epistle of Jude.</li><li>the half-brother of Jesus, <a class='bible' href='#b40.13.55'>Mat 13:55</a></li><li>Judas Iscariot, the apostle who betrayed Jesus</li></ol>","xlit":"Ioúdas"},"G2837":{"kjv_def":"(be a-, fall a-, fall on) sleep, be dead","lemma":"κοιμάω","translit":"koimáō","derivation":"from G2749 (κεῖμαι);","strongs_def":" to put to sleep, i.e. (passively or reflexively) to slumber; figuratively, to decease","pron":"koy-mah'-o","pos":"Verb","thayer":"<ol><li>to cause to sleep, put to sleep</li><li>metaphorically<ol type='a'><li>to still, calm, quiet</li><li>to fall asleep, to sleep</li><li>to die</li></ol></li></ol>","xlit":"koimáō"},"G5561":{"kjv_def":"coast, county, fields, ground, land, region","lemma":"χώρα","translit":"chṓra","derivation":"feminine of a derivative of the base of G5490 (χάσμα) through the idea of empty expanse;","strongs_def":" room, i.e. a space of territory (more or less extensive; often including its inhabitants)","pron":"kho'-rah","pos":"Noun Feminine","thayer":"<ol><li>the space lying between two places or limits</li><li>a region or country, i.e. a tract of land<ol type='a'><li>the (rural) region surrounding a city or village, the country</li><li>the region with towns and villages which surround a metropolis</li></ol><li>land which is ploughed or cultivated, ground</li></ol>","xlit":"chṓra"},"G4104":{"kjv_def":"assure of","lemma":"πιστόω","translit":"pistóō","derivation":"from G4103 (πιστός);","strongs_def":" to assure","pron":"pis-to'-o","pos":"Verb","thayer":"<ol><li>to make faithful, render trustworthy<ol type='a'><li>to make firm, establish</li></ol><li>to be firmly persuaded of<ol type='a'><li>to be assured of</li></ol></li></ol>","xlit":"pistóō"},"G828":{"kjv_def":"Augustus","translit":"Augoûstos","lemma":"Αὐγοῦστος","derivation":"from Latin (\"august\");","strongs_def":" Augustus, a title of the Roman emperor","pron":"ow'-goos-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Augustus = \"venerable\"</p><ol><li>the first Roman emperor</li><li>title conferred upon Roman emperors</li></ol>","xlit":"Augoûstos"},"G1603":{"derivation":"from G1537 (ἐκ) and G4137 (πληρόω);","strongs_def":" to accomplish entirely","kjv_def":"fulfill","lemma":"ἐκπληρόω","translit":"ekplēróō","pron":"ek-play-ro'-o","pos":"Verb","thayer":"<ol><li>to fill full, to fill up completely</li><li>metaphorically to fulfil, make good</li></ol>","xlit":"ekplēróō"},"G3551":{"translit":"nómos","lemma":"νόμος","kjv_def":"law","strongs_def":" law (through the idea of prescriptive usage), genitive case (regulation), specially, (of Moses (including the volume); also of the Gospel), or figuratively (a principle)","derivation":"from a primary (to parcel out, especially food or grazing to animals);","pron":"nom'-os","pos":"Noun Masculine","thayer":"<ol><li>anything established, anything received by usage, a custom, a law, a command<ol type='a'><li>of any law whatsoever<ol><li>a law or rule producing a state approved of God<ol type='a'><li>by the observance of which is approved of God</li></ol><li>a precept or injunction</li><li>the rule of action prescribed by reason</li></ol><li>of the Mosaic law, and referring, acc. to the context. either to the volume of the law or to its contents</li><li>the Christian religion: the law demanding faith, the moral instruction given by Christ, especially the precept concerning love</li><li>the name of the more important part (the Pentateuch), is put for the entire collection of the sacred books of the OT</li></ol></li></ol>","xlit":"nómos"},"G2407":{"strongs_def":" to be a priest, i.e. perform his functions","derivation":"prolongation from G2409 (ἱερεύς);","translit":"hierateúō","lemma":"ἱερατεύω","kjv_def":"execute the priest's office","pron":"hee-er-at-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a priest, discharge the office of a priest, to be busied in sacred duties</li></ol>","xlit":"hierateúō"},"G3784":{"derivation":"probably from the base of G3786 (ὄφελος) (through the idea of accruing);","strongs_def":" to owe (pecuniarily); figuratively, to be under obligation (ought, must, should); morally, to fail in duty","kjv_def":"behove, be bound, (be) debt(-or), (be) due(-ty), be guilty (indebted), (must) need(-s), ought, owe, should","lemma":"ὀφείλω","translit":"opheílō","pron":"of-i'-lo","pos":"Verb","thayer":"<ol><li>to owe<ol type='a'><li>to owe money, be in debt for<ol><li>that which is due, the debt</li></ol></li></ol><li>metaphorically the goodwill due</li></ol>","xlit":"opheílō"},"G3042":{"strongs_def":" a scarcity of food","derivation":"probably from G3007 (λείπω) (through the idea of destitution);","translit":"limós","lemma":"λιμός","kjv_def":"dearth, famine, hunger","pron":"lee-mos'","pos":"Noun Masculine","thayer":"<ol><li>scarcity of harvest, famine</li></ol>","xlit":"limós"},"G3639":{"kjv_def":"destruction","lemma":"ὄλεθρος","translit":"ólethros","derivation":"from a primary (to destroy;","strongs_def":" a prolonged form); ruin, i.e. death, punishment","pron":"ol'-eth-ros","pos":"Noun Masculine","thayer":"<ol><li>ruin, destroy, death<ol type='a'><li>for the destruction of the flesh, said of the external ills and troubles by which the lusts of the flesh are subdued and destroyed</li></ol></li></ol>","xlit":"ólethros"},"G3155":{"derivation":"accusative case of a derivative of the base of G3145 (μασσάομαι) (through the idea of tentative manipulation, i.e. unsuccessful search, or else of punishment);","strongs_def":" folly, i.e. (adverbially) to no purpose","kjv_def":"in vain","lemma":"μάτην","translit":"mátēn","pron":"mat'-ane","pos":"Adverb","thayer":"<ol><li>in vain, fruitlessly</li></ol>","xlit":"mátēn"},"G721":{"strongs_def":" a lambkin","derivation":"diminutive from G704 (ἀρήν);","lemma":"ἀρνίον","translit":"arníon","kjv_def":"lamb","pron":"ar-nee'-on","pos":"Noun Neuter","thayer":"<ol><li>a little lamb, a lamb</li></ol>","xlit":"arníon"},"G2800":{"strongs_def":" fracture (the act)","derivation":"from G2806 (κλάω);","lemma":"κλάσις","translit":"klásis","kjv_def":"breaking","pron":"klas'-is","pos":"Noun Feminine","thayer":"<ol><li>a breaking</li></ol>","xlit":"klásis"},"G2105":{"derivation":"feminine from G2095 (εὖ) and the alternate of G2203 (Ζεύς) (as the god of the weather);","strongs_def":" a clear sky, i.e. fine weather","kjv_def":"fair weather","translit":"eudía","lemma":"εὐδία","pron":"yoo-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a serene sky, fair weather</li></ol>","xlit":"eudía"},"G4062":{"translit":"peritrépō","lemma":"περιτρέπω","kjv_def":"+ make mad","strongs_def":" to turn around, i.e. (mentally) to craze","derivation":"from G4012 (περί) and the base of G5157 (τροπή);","pron":"per-ee-trep'-o","pos":"Verb","thayer":"<ol><li>to turn about, to turn</li><li>to transfer or change by turning<ol type='a'><li>a person or thing into some state</li><li>turning one mad</li></ol></li></ol>","xlit":"peritrépō"},"G5399":{"strongs_def":" to frighten, i.e. (passively) to be alarmed; by analogy, to be in awe of, i.e. revere","derivation":"from G5401 (φόβος);","lemma":"φοβέω","translit":"phobéō","kjv_def":"be (+ sore) afraid, fear (exceedingly), reverence","pron":"fob-eh'-o","pos":"Verb","thayer":"<ol><li>to put to flight by terrifying (to scare away)<ol type='a'><li>to put to flight, to flee</li><li>to fear, be afraid<ol><li>to be struck with fear, to be seized with alarm<ol type='a'><li>of those startled by strange sights or occurrences</li><li>of those struck with amazement</li></ol><li>to fear, be afraid of one</li><li>to fear (i.e. hesitate) to do something (for fear of harm)</li></ol><li>to reverence, venerate, to treat with deference or reverential obedience</li></ol></li></ol>","xlit":"phobéō"},"G2021":{"lemma":"ἐπιχειρέω","translit":"epicheiréō","kjv_def":"go about, take in hand (upon)","strongs_def":" to put the hand upon, i.e. undertake","derivation":"from G1909 (ἐπί) and G5495 (χείρ);","pron":"ep-ee-khi-reh'-o","pos":"Verb","thayer":"<ol><li>to put the hand to</li><li>to take in hand, undertake, attempt</li></ol>","xlit":"epicheiréō"},"G4294":{"strongs_def":" to prepare in advance","derivation":"from G4253 (πρό) and G2675 (καταρτίζω);","translit":"prokatartízō","lemma":"προκαταρτίζω","kjv_def":"make up beforehand","pron":"prok-at-ar-tid'-zo","pos":"Verb","thayer":"<ol><li>to prepare beforehand</li></ol>","xlit":"prokatartízō"},"G4766":{"derivation":"prolongation from a still simpler , (used only as an alternate in certain tenses) (probably akin to G4731 (στερεός) through the idea of positing);","strongs_def":" to \"strew,\" i.e. spread (as a carpet or couch)","kjv_def":"make bed, furnish, spread, strew","translit":"strṓnnymi","lemma":"στρώννυμι","pron":"strone'-noo-mee","pos":"Verb","thayer":"<ol><li>to spread</li><li>furnish</li><li>to spread with couches or divans</li></ol>","xlit":"strṓnnymi"},"G4881":{"kjv_def":"perish with","lemma":"συναπόλλυμι","translit":"synapóllymi","derivation":"from G4862 (σύν) and G622 (ἀπόλλυμι);","strongs_def":" to destroy (middle voice or passively, be slain) in company with","pron":"soon-ap-ol'-loo-mee","pos":"Verb","thayer":"<ol><li>to destroy together</li><li>to perish together (to be slain along with)</li></ol>","xlit":"synapóllymi"},"G2686":{"strongs_def":" to be crafty against, i.e. circumvent","derivation":"middle voice from G2596 (κατά) and G4679 (σοφίζω);","lemma":"κατασοφίζομαι","translit":"katasophízomai","kjv_def":"deal subtilly with","pron":"kat-as-of-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to circumvent by artifice or fraud, conquer by subtle devices</li><li>to outwit</li><li>overreach</li><li>to deal craftily with</li></ol>","xlit":"katasophízomai"},"G1340":{"translit":"diïschyrízomai","lemma":"διϊσχυρίζομαι","kjv_def":"confidently (constantly) affirm","strongs_def":" to stout it through, i.e. asservate","derivation":"from G1223 (διά) and a derivative of G2478 (ἰσχυρός);","pron":"dee-is-khoo-rid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to lean upon</li><li>to affirm stoutly, assert confidently</li></ol>","xlit":"diïschyrízomai"},"G4008":{"strongs_def":" through (as adverb or preposition), i.e. across","derivation":"apparently accusative case of an obsolete derivative of (to \"pierce\");","lemma":"πέραν","translit":"péran","kjv_def":"beyond, farther (other) side, over","pron":"per'-an","pos":"Adverb","thayer":"<ol><li>beyond, on the other side</li></ol>","xlit":"péran"},"G2992":{"derivation":"apparently a primary word;","strongs_def":" a people (in general; thus differing from G1218 (δῆμος), which denotes one's own populace)","kjv_def":"people","lemma":"λαός","translit":"laós","pron":"lah-os'","pos":"Noun Masculine","thayer":"<ol><li>a people, people group, tribe, nation, all those who are of the same stock and language</li><li>of a great part of the population gathered together anywhere</li></ol>","xlit":"laós"},"G1779":{"derivation":"from a compound of G1722 (ἐν) and G5028 (τάφος);","strongs_def":" to inswathe with cerements for interment","kjv_def":"bury","lemma":"ἐνταφιάζω","translit":"entaphiázō","pron":"en-taf-ee-ad'-zo","pos":"Verb","thayer":"<ol><li>to prepare a body for burial, by the use of every requisite provision and funeral adornment, that is, baths, vestments, flowers, wreathes, perfumes, libations, etc.</li><li>to lay out a corpse</li></ol>","xlit":"entaphiázō"},"G2245":{"strongs_def":" as big as, i.e. (interjectively) how much","derivation":"from (a comrade, i.e. one of the same age);","translit":"hēlíkos","lemma":"ἡλίκος","kjv_def":"how (what) great","pron":"hay-lee'-kos","pos":"Adjective","thayer":"<ol><li>as old as, as tall as<ol type='a'><li>how great</li><li>how small</li></ol></li></ol>","xlit":"hēlíkos"},"G4124":{"derivation":"from G4123 (πλεονέκτης);","strongs_def":" avarice, i.e. (by implication) fraudulency, extortion","kjv_def":"covetous(-ness) practices, greediness","translit":"pleonexía","lemma":"πλεονεξία","pron":"pleh-on-ex-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>greedy desire to have more, covetousness, avarice</li></ol>","xlit":"pleonexía"},"G5168":{"translit":"trymaliá","lemma":"τρυμαλιά","kjv_def":"eye","strongs_def":" akin to the base of G5134 (τραῦμα), G5147 (τρίβος) and G5176 (τρώγω)); an orifice, i.e. needle's eye","derivation":"from a derivative of (to wear away;","pron":"troo-mal-ee-ah'","pos":"Noun Feminine","thayer":"<ol><li>a hole, (eye of the needle)</li></ol>","xlit":"trymaliá"},"G3657":{"derivation":"from G3658 (ὅμιλος);","strongs_def":" companionship (\"homily\"), i.e. (by implication) intercourse","kjv_def":"communication","lemma":"ὁμιλία","translit":"homilía","pron":"hom-il-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>companionship, intercourse, communion</li></ol>","xlit":"homilía"},"G1016":{"kjv_def":"ox","translit":"boûs","lemma":"βοῦς","derivation":"probably from the base of G1006 (βόσκω);","strongs_def":" an ox (as grazing), i.e. an animal of that species (\"beef\")","pron":"booce","pos":"Noun Masculine","thayer":"<ol><li>an ox, a cow</li></ol>","xlit":"boûs"},"G4383":{"strongs_def":" the front (as being towards view), i.e. the countenance, aspect, appearance, surface; by implication, presence, person","derivation":"from G4314 (πρός) and (the visage, from G3700 (ὀπτάνομαι));","translit":"prósōpon","lemma":"πρόσωπον","kjv_def":"(outward) appearance, X before, countenance, face, fashion, (men's) person, presence","pron":"pros'-o-pon","pos":"Noun Neuter","thayer":"<ol><li>the face<ol type='a'><li>the front of the human head</li><li>countenance, look<ol><li>the face so far forth as it is the organ of sight, and by it various movements and changes) the index of the inward thoughts and feelings</li></ol><li>the appearance one presents by his wealth or property, his rank or low condition<ol><li>outward circumstances, external condition</li><li>used in expressions which denote to regard the person in one's judgment and treatment of men</li></ol></li></ol><li>the outward appearance of inanimate things</li></ol>","xlit":"prósōpon"},"G1575":{"translit":"ekkláō","lemma":"ἐκκλάω","kjv_def":"break off","strongs_def":" to exscind","derivation":"from G1537 (ἐκ) and G2806 (κλάω);","pron":"ek-klah'-o","pos":"Verb","thayer":"<ol><li>to break off, to cut off</li></ol>","xlit":"ekkláō"},"G2085":{"strongs_def":" to instruct differently","derivation":"from G2087 (ἕτερος) and G1320 (διδάσκαλος);","lemma":"ἑτεροδιδασκαλέω","translit":"heterodidaskaléō","kjv_def":"teach other doctrine(-wise)","pron":"het-er-od-id-as-kal-eh'-o","pos":"Verb","thayer":"<ol><li>to teach other or different doctrine<ol type='a'><li>deviating from the truth</li></ol></li></ol>","xlit":"heterodidaskaléō"},"G4609":{"derivation":"contraction for G4610 (Σιλουανός);","strongs_def":" Silas, a Christian","kjv_def":"Silas","translit":"Sílas","lemma":"Σίλας","pron":"see'-las","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Silas = \"woody\"</p><ol><li>a Roman citizen, the companion of the apostle Paul on several of his missionary journeys</li></ol>","xlit":"Sílas"},"G340":{"lemma":"ἀνακαινίζω","translit":"anakainízō","kjv_def":"renew","strongs_def":" to restore","derivation":"from G303 (ἀνά) and a derivative of G2537 (καινός);","pron":"an-ak-ahee-nid'-zo","pos":"Verb","thayer":"<ol><li>to renew, renovate</li></ol>","xlit":"anakainízō"},"G4224":{"derivation":"from the alternate of G4095 (πίνω);","strongs_def":" a drinking-bout or carousal","kjv_def":"banqueting","translit":"pótos","lemma":"πότος","pron":"pot'-os","pos":"Noun Masculine","thayer":"<ol><li>a drinking, carousing</li></ol>","xlit":"pótos"},"G1072":{"strongs_def":" to fill entirely","derivation":"transitive from G1073 (γέμω);","lemma":"γεμίζω","translit":"gemízō","kjv_def":"fill (be) full","pron":"ghem-id'-zo","pos":"Verb","thayer":"<ol><li>to fill, fill full</li></ol>","xlit":"gemízō"},"G3010":{"kjv_def":"ministering","translit":"leitourgikós","lemma":"λειτουργικός","derivation":"from the same as G3008 (λειτουργέω);","strongs_def":" functional publicly (\"liturgic\"); i.e. beneficient","pron":"li-toorg-ik-os'","pos":"Adjective","thayer":"<ol><li>relating to the performance of service, employed in ministering</li></ol>","xlit":"leitourgikós"},"G2278":{"translit":"ēchéō","lemma":"ἠχέω","kjv_def":"roar, sound","strongs_def":" to make a loud noise, i.e. reverberate","derivation":"from G2279 (ἦχος);","pron":"ay-kheh'-o","pos":"Verb","thayer":"<ol><li>to sound<ol type='a'><li>used of the roaring of the sea</li></ol></li></ol>","xlit":"ēchéō"},"G3795":{"kjv_def":"fish","translit":"opsárion","lemma":"ὀψάριον","derivation":"neuter of a presumed derivative of the base of G3702 (ὀπτός);","strongs_def":" a relish to other food (as if cooked sauce), i.e. (specially), fish (presumably salted and dried as a condiment)","pron":"op-sar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>fish</li></ol>","xlit":"opsárion"},"G3945":{"lemma":"παρομοιάζω","translit":"paromoiázō","kjv_def":"be like unto","strongs_def":" to resemble","derivation":"from G3946 (παρόμοιος);","pron":"par-om-oy-ad'-zo","pos":"Verb","thayer":"<ol><li>to be like</li><li>to be not unlike</li></ol>","xlit":"paromoiázō"},"G432":{"lemma":"ἄνηθον","translit":"ánēthon","kjv_def":"anise","strongs_def":" dill","derivation":"probably of foreign origin;","pron":"an'-ay-thon","pos":"Noun Neuter","thayer":"<ol><li>anise, dill<ol type='a'><li>a used plant used as a spice and for medicine</li></ol></li></ol>","xlit":"ánēthon"},"G996":{"strongs_def":" aid; specially, a rope or chain for frapping a vessel","derivation":"from G998 (βοηθός);","lemma":"βοήθεια","translit":"boḗtheia","kjv_def":"help","pron":"bo-ay'-thi-ah","pos":"Noun Feminine","thayer":"<ol><li>help</li></ol>","xlit":"boḗtheia"},"G5290":{"derivation":"from G5259 (ὑπό) and G4762 (στρέφω);","strongs_def":" to turn under (behind), i.e. to return (literally or figuratively)","kjv_def":"come again, return (again, back again), turn back (again)","translit":"hypostréphō","lemma":"ὑποστρέφω","pron":"hoop-os-tref'-o","pos":"Verb","thayer":"<ol><li>to turn back<ol type='a'><li>to turn about</li></ol><li>to return</li></ol>","xlit":"hypostréphō"},"G720":{"strongs_def":" to contradict, i.e. disavow, reject, abnegate","derivation":"perhaps from G1 (Α) (as a negative particle) and the middle voice of G4483 (ῥέω);","translit":"arnéomai","lemma":"ἀρνέομαι","kjv_def":"deny, refuse","pron":"ar-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to deny</li><li>to deny someone<ol type='a'><li>to deny one's self<ol><li>to disregard his own interests or to prove false to himself</li><li>act entirely unlike himself</li></ol></li></ol><li>to deny, abnegate, abjure</li><li>not to accept, to reject, to refuse something offered</li></ol>","xlit":"arnéomai"},"G3529":{"strongs_def":" conquest (abstractly), i.e. (figuratively) the means of success","derivation":"apparently a primary word;","lemma":"νίκη","translit":"níkē","kjv_def":"victory","pron":"nee'-kay","pos":"Noun Feminine","thayer":"<ol><li>victory</li></ol>","xlit":"níkē"},"G459":{"strongs_def":" lawless, i.e. (negatively) not subject to (the Jewish) law; (by implication, a Gentile), or (positively) wicked","derivation":"from G1 (Α) (as a negative particle) and G3551 (νόμος);","translit":"ánomos","lemma":"ἄνομος","kjv_def":"without law, lawless, transgressor, unlawful, wicked","pron":"an'-om-os","pos":"Adjective","thayer":"<ol><li>destitute of (the Mosaic) law<ol type='a'><li>of the Gentiles</li></ol><li>departing from the law, a violator of the law, lawless, wicked</li></ol>","xlit":"ánomos"},"G2269":{"derivation":"of Hebrew origin (H06215);","strongs_def":" Esau, an Edomite","kjv_def":"Esau","lemma":"Ἠσαῦ","translit":"Ēsaû","pron":"ay-sow'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Esau = \"hairy\"</p><ol><li>was the eldest son of Isaac and twin brother of Jacob</li></ol>","xlit":"Ēsaû"},"G1021":{"strongs_def":" slow; figuratively, dull","derivation":"of uncertain affinity;","lemma":"βραδύς","translit":"bradýs","kjv_def":"slow","pron":"brad-ooce'","pos":"Adjective","thayer":"<ol><li>slow</li><li>metaphorically dull, inactive, in mind<ol type='a'><li>stupid, slow to apprehend or believe</li></ol></li></ol>","xlit":"bradýs"},"G1911":{"translit":"epibállō","lemma":"ἐπιβάλλω","kjv_def":"beat into, cast (up-)on, fall, lay (on), put (unto), stretch forth, think on","strongs_def":" to throw upon (literal or figurative, transitive or reflexive; usually with more or less force); specially (with G1438 (ἑαυτοῦ) implied) to reflect; impersonally, to belong to","derivation":"from G1909 (ἐπί) and G906 (βάλλω);","pron":"ep-ee-bal'-lo","pos":"Verb","thayer":"<ol><li>to cast upon, to lay upon<ol type='a'><li>used of seizing one to lead him off as a prisoner</li><li>to put (i.e. sew) on</li></ol><li>to throw one's self upon, rush in<ol type='a'><li>used of waves rushing into a ship</li><li>to put one's mind upon a thing</li><li>attend to</li></ol><li>it belongs to me, falls to my share</li></ol>","xlit":"epibállō"},"G3514":{"translit":"nḗthō","lemma":"νήθω","kjv_def":"spin","strongs_def":" to spin","derivation":"from (of like meaning);","pron":"nay'-tho","pos":"Verb","thayer":"<ol><li>to spin</li></ol>","xlit":"nḗthō"},"G4044":{"kjv_def":"pierce through","translit":"peripeírō","lemma":"περιπείρω","derivation":"from G4012 (περί) and the base of G4008 (πέραν);","strongs_def":" to penetrate entirely, i.e. transfix (figuratively)","pron":"per-ee-pi'-ro","pos":"Verb","thayer":"<ol><li>to pierce through</li><li>metaphorically to torture one's soul with sorrows</li></ol>","xlit":"peripeírō"},"G3592":{"lemma":"ὅδε","translit":"hóde","kjv_def":"he, she, such, these, thus","strongs_def":" the same, i.e. this or that one (plural these or those); often used as a personal pronoun","derivation":"from G3588 (ὁ) and G1161 (δέ);","pron":"hod'-eh","thayer":"<ol><li>this one here, these things, as follows, thus</li></ol>","xlit":"hóde"},"G236":{"strongs_def":" to make different","derivation":"from G243 (ἄλλος);","lemma":"ἀλλάσσω","translit":"allássō","kjv_def":"change","pron":"al-las'-so","pos":"Verb","thayer":"<ol><li>to change, to exchange one thing for another, to transform</li></ol>","xlit":"allássō"},"G2112":{"translit":"euthéōs","lemma":"εὐθέως","kjv_def":"anon, as soon as, forthwith, immediately, shortly, straightway","strongs_def":" directly, i.e. at once or soon","derivation":"adverb from G2117 (εὐθύς);","pron":"yoo-theh'-oce","pos":"Adverb","thayer":"<ol><li>straightway, immediately, forthwith</li></ol>","xlit":"euthéōs"},"G3960":{"kjv_def":"smite, strike","lemma":"πατάσσω","translit":"patássō","derivation":"probably prolongation from G3817 (παίω);","strongs_def":" to knock (gently or with a weapon or fatally)","pron":"pat-as'-so","pos":"Verb","thayer":"<ol><li>to strike gently: as a part or a member of the body</li><li>to stroke, smite: with the sword, to afflict, to visit with evils, etc. as with a deadly disease</li><li>to smite down, cut down, to kill, slay</li></ol>","xlit":"patássō"},"G367":{"derivation":"of Hebrew origin (H02608);","strongs_def":" Ananias, the name of three Israelites","kjv_def":"Ananias","lemma":"Ἀνανίας","translit":"Ananías","pron":"an-an-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Ananias = \"whom Jehovah has graciously given\"</p><ol><li>a certain Christian at Jerusalem, the husband of Sapphira <a class='bible' href='#b44.5.1-6'>Act 5:1-6</a></li><li>a Christian at Damascus <a class='bible' href='#b44.9.10-18'>Act 9:10-18</a></li><li>a son of Nedebaeus, and high priest of the Jews c. A.D. 47-59. In the year 66, he was slain by the Sacarii. <a class='bible' href='#b44.23.2'>Act 23:2</a></li></ol>","xlit":"Ananías"},"G2691":{"strongs_def":" to become voluptuous against","derivation":"from G2596 (κατά) and G4763 (στρηνιάω);","lemma":"καταστρηνιάω","translit":"katastrēniáō","kjv_def":"begin to wax wanton against","pron":"kat-as-tray-nee-ah'-o","pos":"Verb","thayer":"<ol><li>to feel the impulses of sexual desire</li></ol>","xlit":"katastrēniáō"},"G2355":{"derivation":"from the base of G2360 (θροέω);","strongs_def":" wailing","kjv_def":"lamentation","lemma":"θρῆνος","translit":"thrēnos","pron":"thray'-nos","pos":"Noun Masculine","thayer":"<ol><li>a lamentation</li></ol>","xlit":"thrēnos"},"G3368":{"lemma":"μηδέποτε","translit":"mēdépote","kjv_def":"never","strongs_def":" not even ever","derivation":"from G3366 (μηδέ) and G4218 (ποτέ);","pron":"may-dep'-ot-eh","pos":"Adverb","thayer":"<ol><li>never</li></ol>","xlit":"mēdépote"},"G2083":{"strongs_def":" a comrade","derivation":"from (a clansman);","lemma":"ἑταῖρος","translit":"hetaîros","kjv_def":"fellow, friend","pron":"het-ah'-ee-ros","pos":"Noun Masculine","thayer":"<ol><li>a comrade, mate, partner</li><li>in kindly address<ol type='a'><li>friend, (my good friend)</li></ol></li></ol>","xlit":"hetaîros"},"G3937":{"kjv_def":"Parmenas","translit":"Parmenâs","lemma":"Παρμενᾶς","derivation":"probably by contraction for (a derivative of a compound of G3844 (παρά) and G3306 (μένω));","strongs_def":" constant; Parmenas, a Christian","pron":"par-men-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Parmenas = \"abiding\"</p><ol><li>one of the seven deacons of the church at Jerusalem</li></ol>","xlit":"Parmenâs"},"G4210":{"strongs_def":" purpureal, i.e. bluish red","derivation":"from G4209 (πορφύρα);","lemma":"πορφυροῦς","translit":"porphyroûs","kjv_def":"purple","pron":"por-foo-rooce'","pos":"Adjective","thayer":"<ol><li>purple, dyed in purple, made of purple fabric</li></ol>","xlit":"porphyroûs"},"G3765":{"derivation":"from G3756 (οὐ) and G2089 (ἔτι);","strongs_def":" not yet, no longer","kjv_def":"after that (not), (not) any more, henceforth (hereafter) not, no longer (more), not as yet (now), now no more (not), yet (not)","translit":"oukéti","lemma":"οὐκέτι","pron":"ook-et'-ee","pos":"Adverb","thayer":"<ol><li>no longer, no more, no further</li></ol>","xlit":"oukéti"},"G5130":{"kjv_def":"such, their, these (things), they, this sort, those","lemma":"τούτων","translit":"toútōn","derivation":"genitive case plural masculine or neuter of G3778 (οὗτος);","strongs_def":" of (from or concerning) these (persons or things)","pron":"too'-tone","thayer":"<ol><li>of these</li></ol>","xlit":"toútōn"},"G681":{"strongs_def":" properly, to fasten to, i.e. (specially) to set on fire","derivation":"a primary verb;","translit":"háptō","lemma":"ἅπτω","kjv_def":"kindle, light","pron":"hap'-to","pos":"Verb","thayer":"<ol><li>to fasten to, adhere to<ol type='a'><li>to fasten fire to a thing, kindle, set of fire</li></ol></li></ol>","xlit":"háptō"},"G3988":{"derivation":"from a presumed derivative of G3982 (πείθω);","strongs_def":" persuadableness, i.e. credulity","kjv_def":"persuasion","lemma":"πεισμονή","translit":"peismonḗ","pron":"pice-mon-ay'","pos":"Noun Feminine","thayer":"<ol><li>persuasion</li><li>treacherous or deceptive persuasion</li></ol>","xlit":"peismonḗ"},"G623":{"lemma":"Ἀπολλύων","translit":"Apollýōn","kjv_def":"Apollyon","strongs_def":" a destroyer (i.e. Satan)","derivation":"active participle of G622 (ἀπόλλυμι);","pron":"ap-ol-loo'-ohn","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Apollyon = \"Destroyer\"</p><ol><li>the angel of the bottomless pit, the Destroyer</li></ol>","xlit":"Apollýōn"},"G3577":{"strongs_def":" the back","derivation":"of uncertain affinity;","lemma":"νῶτος","translit":"nōtos","kjv_def":"back","pron":"no'-tos","pos":"Noun Masculine","thayer":"<ol><li>the back</li></ol>","xlit":"nōtos"},"G88":{"strongs_def":" unintermitted, i.e. permanent","derivation":"from G1 (Α) (as a negative particle) and a derivative of a compound of G1223 (διά) and G3007 (λείπω);","translit":"adiáleiptos","lemma":"ἀδιάλειπτος","kjv_def":"without ceasing, continual","pron":"ad-ee-al'-ipe-tos","pos":"Adjective","thayer":"<ol><li>unintermitted, unceasing, continual</li></ol>","xlit":"adiáleiptos"},"G1749":{"translit":"énedron","lemma":"ἔνεδρον","kjv_def":"lying in wait","strongs_def":" an ambush, i.e. (figuratively) murderous design","derivation":"neuter of the same as G1747 (ἐνέδρα);","pron":"en'-ed-ron","pos":"Noun Neuter","thayer":"<ol><li>a lying in wait for, an ambush</li></ol>","xlit":"énedron"},"G5167":{"kjv_def":"turtle-dove","translit":"trygṓn","lemma":"τρυγών","derivation":"from (to murmur;","strongs_def":" akin to G5149 (τρίζω), but denoting a duller sound); a turtle-dove (as cooing)","pron":"troo-gone'","pos":"Noun Feminine","thayer":"<ol><li>turtledove</li></ol>","xlit":"trygṓn"},"G180":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G2664 (καταπαύω);","strongs_def":" unrefraining","kjv_def":"that cannot cease","translit":"akatápaustos","lemma":"ἀκατάπαυστος","pron":"ak-at-ap'-ow-stos","pos":"Adjective","thayer":"<ol><li>unable to stop, unceasing</li><li>not quieted, that cannot be quieted</li></ol>","xlit":"akatápaustos"},"G4621":{"derivation":"of uncertain derivation;","strongs_def":" grain, especially wheat","kjv_def":"corn, wheat","lemma":"σῖτος","translit":"sîtos","pron":"see'-tos","pos":"Noun Masculine","thayer":"<ol><li>wheat, grain</li></ol>","xlit":"sîtos"},"G5060":{"kjv_def":"Tertius","translit":"Tértios","lemma":"Τέρτιος","derivation":"of Latin origin;","strongs_def":" third; Tertius, a Christian","pron":"ter'-tee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tertius = \"third\"</p><ol><li>amanuensis of Paul in writing the epistle to the Romans</li></ol>","xlit":"Tértios"},"G3474":{"kjv_def":"fool(-ish, X -ishness)","lemma":"μωρός","translit":"mōrós","derivation":"probably from the base of G3466 (μυστήριον);","strongs_def":" dull or stupid (as if shut up), i.e. heedless, (morally) blockhead, (apparently) absurd","pron":"mo-ros'","pos":"Adjective","thayer":"<ol><li>foolish</li><li>impious, godless</li></ol>","xlit":"mōrós"},"G1187":{"lemma":"δεξιολάβος","translit":"dexiolábos","kjv_def":"spearman","strongs_def":" a guardsman (as if taking the right) or light-armed soldier","derivation":"from G1188 (δεξιός) and G2983 (λαμβάνω);","pron":"dex-ee-ol-ab'-os","pos":"Noun Masculine","thayer":"<ol><li>throwing with the right hand, a slinger, an archer, javelinmen</li></ol>","xlit":"dexiolábos"},"G1027":{"kjv_def":"thunder(-ing)","lemma":"βροντή","translit":"brontḗ","derivation":"akin to (to roar);","strongs_def":" thunder","pron":"bron-tay'","pos":"Noun Feminine","thayer":"<ol><li>thunder</li></ol>","xlit":"brontḗ"},"G2578":{"derivation":"apparently a primary verb;","strongs_def":" to bend","kjv_def":"bow","lemma":"κάμπτω","translit":"kámptō","pron":"kamp'-to","pos":"Verb","thayer":"<ol><li>to bend, bow, the knee (the knees)<ol type='a'><li>to one<ol><li>in honour of one</li><li>in religious veneration</li></ol><li>used of worshippers</li></ol><li>to bow one's self</li></ol>","xlit":"kámptō"},"G467":{"lemma":"ἀνταποδίδωμι","translit":"antapodídōmi","kjv_def":"recompense, render, repay","strongs_def":" to requite (good or evil)","derivation":"from G473 (ἀντί) and G591 (ἀποδίδωμι);","pron":"an-tap-od-ee'-do-mee","pos":"Verb","thayer":"<ol><li>in a good sense, to repay, requite</li><li>in a bad sense, penalty and vengeance</li></ol>","xlit":"antapodídōmi"},"G725":{"kjv_def":"robbery","translit":"harpagmós","lemma":"ἁρπαγμός","derivation":"from G726 (ἁρπάζω);","strongs_def":" plunder (properly concrete)","pron":"har-pag-mos'","pos":"Noun Masculine","thayer":"<ol><li>the act of seizing, robbery</li><li>a thing seized or to be seized<ol type='a'><li>booty to deem anything a prize</li><li>a thing to be seized upon or to be held fast, retained</li></ol></li></ol>","xlit":"harpagmós"},"G3412":{"lemma":"Μιτυλήνη","translit":"Mitylḗnē","kjv_def":"Mitylene","strongs_def":" Mitylene (or Mytilene), a town on the island of Lesbos","derivation":"for (abounding in shellfish);","pron":"mit-oo-lay'-nay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Mitylene = \"mutilated\"</p><ol><li>the chief maritime town of the island of Lesbos in the Aegean</li></ol>","xlit":"Mitylḗnē"},"G5463":{"strongs_def":" to be \"cheer\"ful, i.e. calmly happy or well-off; impersonally, especially as salutation (on meeting or parting), be well","derivation":"a primary verb;","lemma":"χαίρω","translit":"chaírō","kjv_def":"farewell, be glad, God speed, greeting, hall, joy(- fully), rejoice","pron":"khah'-ee-ro","pos":"Verb","thayer":"<ol><li>to rejoice, be glad</li><li>to rejoice exceedingly</li><li>to be well, thrive</li><li>in salutations, hail!</li><li>at the beginning of letters: to give one greeting, salute</li></ol>","xlit":"chaírō"},"G2645":{"strongs_def":" left down (behind), i.e remaining (plural the rest)","derivation":"from G2596 (κατά) and G3062 (λοιποί);","translit":"katáloipos","lemma":"κατάλοιπος","kjv_def":"residue","pron":"kat-al'-oy-pos","pos":"Adjective","thayer":"<ol><li>left remaining</li></ol>","xlit":"katáloipos"},"G5220":{"strongs_def":" in subjection under a man, i.e. a married woman","derivation":"from G5259 (ὑπό) and G435 (ἀνήρ);","lemma":"ὕπανδρος","translit":"hýpandros","kjv_def":"which hath an husband","pron":"hoop'-an-dros","pos":"Adjective","thayer":"<ol><li>under, i.e. subject to a man: married</li></ol>","xlit":"hýpandros"},"G484":{"derivation":"from G482 (ἀντιλαμβάνομαι);","strongs_def":" relief","kjv_def":"help","lemma":"ἀντίληψις","translit":"antílēpsis","pron":"an-til'-ape-sis","pos":"Noun Feminine","thayer":"<ol><li>a laying hold of, apprehension, perception, objection of a disputant</li><li>in NT, to aid, help</li></ol>","xlit":"antílēpsis"},"G5571":{"strongs_def":" untrue, i.e. erroneous, deceitful, wicked","derivation":"from G5574 (ψεύδομαι);","lemma":"ψευδής","translit":"pseudḗs","kjv_def":"false, liar","pron":"psyoo-dace'","pos":"Adjective","thayer":"<ol><li>lying, deceitful, false</li></ol>","xlit":"pseudḗs"},"G1612":{"strongs_def":" to pervert (figuratively)","derivation":"from G1537 (ἐκ) and G4762 (στρέφω);","lemma":"ἐκστρέφω","translit":"ekstréphō","kjv_def":"subvert","pron":"ek-stref'-o","pos":"Verb","thayer":"<ol><li>to turn or twist out, tear up</li><li>to turn inside out, invert</li><li>to change for the worse, pervert, corrupt</li></ol>","xlit":"ekstréphō"},"G492":{"derivation":"from G473 (ἀντί) and G3928 (παρέρχομαι);","strongs_def":" to go along opposite","kjv_def":"pass by on the other side","lemma":"ἀντιπαρέρχομαι","translit":"antiparérchomai","pron":"an-tee-par-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to pass by opposite to</li></ol>","xlit":"antiparérchomai"},"G4578":{"kjv_def":"earthquake, tempest","lemma":"σεισμός","translit":"seismós","derivation":"from G4579 (σείω);","strongs_def":" a commotion, i.e. (of the air) a gale, (of the ground) an earthquake","pron":"sice-mos'","pos":"Noun Masculine","thayer":"<ol><li>a shaking, a commotion</li><li>a tempest</li><li>an earthquake</li></ol>","xlit":"seismós"},"G2451":{"kjv_def":"Jewish","lemma":"Ἰουδαϊκός","translit":"Ioudaïkós","derivation":"from G2453 (Ἰουδαῖος);","strongs_def":" Judaïc, i.e. resembling a Judæan","pron":"ee-oo-dah-ee-kos'","pos":"Adjective","thayer":"<ol><li>Jewish</li></ol>","xlit":"Ioudaïkós"},"G3727":{"kjv_def":"oath","lemma":"ὅρκος","translit":"hórkos","derivation":"from (a fence;","strongs_def":" perhaps akin to G3725 (ὅριον)); a limit, i.e. (sacred) restraint (specially, an oath)","pron":"hor'-kos","pos":"Noun Masculine","thayer":"<ol><li>that which has been pledged or promised with an oath</li></ol>","xlit":"hórkos"},"G1375":{"translit":"diōgmós","lemma":"διωγμός","kjv_def":"persecution","strongs_def":" persecution","derivation":"from G1377 (διώκω);","pron":"dee-ogue-mos'","pos":"Noun Masculine","thayer":"<ol><li>persecution</li></ol>","xlit":"diōgmós"},"G2447":{"translit":"iós","lemma":"ἰός","kjv_def":"poison, rust","strongs_def":" rust (as if emitted by metals); also venom (as emitted by serpents)","derivation":"perhaps from (to go) or (to send);","pron":"ee-os'","pos":"Noun Masculine","thayer":"<ol><li>poison (of animals)<ol type='a'><li>poison of asps is under their lips</li><li>spoken of men given to reviling and calumniating and thereby injuring others</li></ol><li>rust</li></ol>","xlit":"iós"},"G208":{"strongs_def":" to invalidate","derivation":"from G1 (Α) (as a negative particle) and G2964 (κυρόω);","translit":"akyróō","lemma":"ἀκυρόω","kjv_def":"disannul, make of none effect","pron":"ak-oo-ro'-o","pos":"Verb","thayer":"<ol><li>to render void, deprive of force and authority</li></ol>","xlit":"akyróō"},"G1793":{"derivation":"from G1722 (ἐν) and G5177 (τυγχάνω);","strongs_def":" to chance upon, i.e. (by implication) confer with; by extension to entreat (in favor or against)","kjv_def":"deal with, make intercession","translit":"entynchánō","lemma":"ἐντυγχάνω","pron":"en-toong-khan'-o","pos":"Verb","thayer":"<ol><li>to light upon a person or a thing, fall in with, hit upon, a person or a thing</li><li>to go to or meet a person, especially for the purpose of conversation, consultation, or supplication</li><li>to pray, entreat</li><li>make intercession for any one</li></ol>","xlit":"entynchánō"},"G814":{"translit":"atáktōs","lemma":"ἀτάκτως","kjv_def":"disorderly","derivation":"adverb from G813 (ἄτακτος), irregularly (morally)","pron":"at-ak'-toce","pos":"Adverb","thayer":"<ol><li>disorderly, out of ranks (often so of soldiers)</li><li>irregular, inordinate, immoderate pleasures</li><li>deviating from the prescribed order or rule</li></ol>","xlit":"atáktōs"},"G5600":{"derivation":"the subjunctive of G1510 (εἰμί);","strongs_def":" (may, might, can, could, would, should, must, etc.; also with G1487 (εἰ) and its comparative, as well as with other particles) be","kjv_def":"+ appear, are, (may, might, should) be, X have, is, + pass the flower of her age, should stand, were","translit":"ō","lemma":"ὦ","pron":"o","pos":"Verb","thayer":"<ol><li>be, may be, etc.</li></ol>","xlit":"ō"},"G4263":{"derivation":"probably neuter of a presumed derivative of G4260 (προβαίνω);","strongs_def":" something that walks forward (a quadruped), i.e. (specially), a sheep (literally or figuratively)","kjv_def":"sheep(-fold)","lemma":"πρόβατον","translit":"próbaton","pron":"prob'-at-on","pos":"Noun Neuter","thayer":"<ol><li>any four footed, tame animal accustomed to graze, small cattle<ol type='a'><li>a sheep, and so always in the NT</li></ol></li></ol>","xlit":"próbaton"},"G788":{"strongs_def":" more nearly, i.e. very near","derivation":"neuter comparative of the base of G1451 (ἐγγύς);","lemma":"ἆσσον","translit":"âsson","kjv_def":"close","pron":"as'-son","pos":"Adverb","thayer":"<ol><li>nearer</li></ol>","xlit":"âsson"},"G4498":{"strongs_def":" Rode, a servant girl","derivation":"probably for rhode (a rose);","lemma":"Ῥόδη","translit":"Rhódē","kjv_def":"Rhoda","pron":"hrod'-ay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Rhoda = \"rose\"</p><ol><li>the name of a certain maid servant</li></ol>","xlit":"Rhódē"},"G4391":{"strongs_def":" to exist before, i.e. (adverbially) to be or do something previously","derivation":"from G4253 (πρό) and G5225 (ὑπάρχω);","lemma":"προϋπάρχω","translit":"proÿpárchō","kjv_def":"+ be before(-time)","pron":"pro-oop-ar'-kho","pos":"Verb","thayer":"<ol><li>to be before, exist previously</li></ol>","xlit":"proÿpárchō"},"G2723":{"translit":"katēgoréō","lemma":"κατηγορέω","kjv_def":"accuse, object","strongs_def":" to be a plaintiff, i.e. to charge with some offence","derivation":"from G2725 (κατήγορος);","pron":"kat-ay-gor-eh'-o","pos":"Verb","thayer":"<ol><li>to accuse<ol type='a'><li>before a judge: to make an accusation</li><li>of an extra-judicial accusation</li></ol></li></ol>","xlit":"katēgoréō"},"G1175":{"kjv_def":"superstition","lemma":"δεισιδαιμονία","translit":"deisidaimonía","derivation":"from the same as G1174 (δεισιδαιμονέστερος);","strongs_def":" religion","pron":"dice-ee-dahee-mon-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>in a good sense<ol type='a'><li>reverencing god or the gods, pious, religious</li></ol><li>in a bad sense<ol type='a'><li>superstitious</li></ol><li>religious</li></ol>","xlit":"deisidaimonía"},"G3452":{"kjv_def":"marrow","lemma":"μυελός","translit":"myelós","derivation":"perhaps a primary word;","strongs_def":" the marrow","pron":"moo-el-os'","pos":"Noun Masculine","thayer":"<ol><li>marrow</li></ol>","xlit":"myelós"},"G2161":{"strongs_def":" well- fated, i.e. fortunate; Eutychus, a young man","derivation":"from G2095 (εὖ) and a derivative of G5177 (τυγχάνω);","translit":"Eútychos","lemma":"Εὔτυχος","kjv_def":"Eutychus","pron":"yoo'-too-khos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eutychus = \"fortunate\"</p><ol><li>a youth restored to life by Paul</li></ol>","xlit":"Eútychos"},"G2374":{"kjv_def":"door, gate","translit":"thýra","lemma":"θύρα","derivation":"apparently a primary word (compare \"door\");","strongs_def":" a portal or entrance (the opening or the closure, literally or figuratively)","pron":"thoo'-rah","pos":"Noun Feminine","thayer":"<ol><li>a door<ol type='a'><li>the vestibule</li><li>used of any opening like a door, an entrance, way or passage into</li><li>in a parable or metaphor<ol><li>the door through which sheep go in and out, the name of him who brings salvation to those who follow his guidance</li><li>\"an open door\" is used of the opportunity of doing something</li><li>the door of the kingdom of heaven (likened to a palace) denotes the conditions which must be complied with in order to be received into the kingdom of God</li></ol></li></ol></li></ol>","xlit":"thýra"},"G3961":{"derivation":"from a derivative probably of G3817 (παίω) (meaning a \"path\");","strongs_def":" to trample (literally or figuratively)","kjv_def":"tread (down, under foot)","lemma":"πατέω","translit":"patéō","pron":"pat-eh'-o","pos":"Verb","thayer":"<ol><li>to tread<ol type='a'><li>to trample, crush with the feet</li><li>to advance by setting foot upon, tread upon: to encounter successfully the greatest perils from the machinations and persecutions with which Satan would fain thwart the preaching of the gospel</li><li>to tread under foot, trample on, i.e. to treat with insult and contempt: to desecrate the holy city by devastation and outrage</li></ol></li></ol>","xlit":"patéō"},"G677":{"strongs_def":" actively, inoffensive, i.e. not leading into sin; passively, faultless, i.e. not led into sin","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G4350 (προσκόπτω);","lemma":"ἀπρόσκοπος","translit":"apróskopos","kjv_def":"none (void of, without) offence","pron":"ap-ros'-kop-os","pos":"Adjective","thayer":"<ol><li>having nothing to strike against, not causing to stumble<ol type='a'><li>of a smooth road</li><li>metaphorically of not leading others to sin by one's mode of life</li></ol><li>not striking against or stumbling<ol type='a'><li>metaphorically not led into sin, blameless</li></ol><li>without offense, not troubled by a consciousness of sin</li></ol>","xlit":"apróskopos"},"G321":{"kjv_def":"bring (again, forth, up again), depart, launch (forth), lead (up), loose, offer, sail, set forth, take up","translit":"anágō","lemma":"ἀνάγω","derivation":"from G303 (ἀνά) and G71 (ἄγω);","strongs_def":" to lead up; by extension to bring out; specially, to sail away","pron":"an-ag'-o","pos":"Verb","thayer":"<ol><li>to lead up, to lead or bring into a higher place</li><li>of navigators: launch out, set sail, put to sea</li></ol>","xlit":"anágō"},"G1316":{"kjv_def":"depart","lemma":"διαχωρίζομαι","translit":"diachōrízomai","derivation":"from G1223 (διά) and the middle voice of G5563 (χωρίζω);","strongs_def":" to remove (oneself) wholly, i.e. retire","pron":"dee-akh-o-rid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to separate thoroughly or wholly</li><li>to separate one's self, depart</li></ol>","xlit":"diachōrízomai"},"G4537":{"derivation":"from G4536 (σάλπιγξ);","strongs_def":" to trumpet, i.e. sound a blast (literally or figuratively)","kjv_def":"(which are yet to) sound (a trumpet)","lemma":"σαλπίζω","translit":"salpízō","pron":"sal-pid'-zo","pos":"Verb","thayer":"<ol><li>to sound a trumpet</li></ol>","xlit":"salpízō"},"G836":{"strongs_def":" a flute (as blown)","derivation":"from the same as G109 (ἀήρ);","lemma":"αὐλός","translit":"aulós","kjv_def":"pipe","pron":"ow-los'","pos":"Noun Masculine","thayer":"<ol><li>a pipe</li></ol>","xlit":"aulós"},"G3674":{"kjv_def":"together","lemma":"ὁμοῦ","translit":"homoû","derivation":"genitive case of (the same;","strongs_def":" akin to G260 (ἅμα)) as adverb; at the same place or time","pron":"hom-oo'","pos":"Adverb","thayer":"<ol><li>together: of persons assembled together</li></ol>","xlit":"homoû"},"G3091":{"lemma":"Λώτ","translit":"Lṓt","kjv_def":"Lot","strongs_def":" Lot, a patriarch","derivation":"of Hebrew origin (H03876);","pron":"lote","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lot = \"veil or covering\"</p><ol><li>the son of Haran and nephew to Abraham</li></ol>","xlit":"Lṓt"},"G2889":{"kjv_def":"adorning, world","translit":"kósmos","lemma":"κόσμος","derivation":"probably from the base of G2865 (κομίζω);","strongs_def":" orderly arrangement, i.e. decoration; by implication, the world (in a wide or narrow sense, including its inhabitants, literally or figuratively (morally))","pron":"kos'-mos","pos":"Noun Masculine","thayer":"<ol><li>an apt and harmonious arrangement or constitution, order, government</li><li>ornament, decoration, adornment, i.e. the arrangement of the stars, 'the heavenly hosts', as the ornament of the heavens. <a class='bible' href='#b60.3.3'>1Pe 3:3</a></li><li>the world, the universe</li><li>the circle of the earth, the earth</li><li>the inhabitants of the earth, men, the human family</li><li>the ungodly multitude; the whole mass of men alienated from God, and therefore hostile to the cause of Christ</li><li>world affairs, the aggregate of things earthly<ol type='a'><li>the whole circle of earthly goods, endowments riches, advantages, pleasures, etc, which although hollow and frail and fleeting, stir desire, seduce from God and are obstacles to the cause of Christ</li></ol><li>any aggregate or general collection of particulars of any sort<ol type='a'><li>the Gentiles as contrasted to the Jews (<a class='bible' href='#b45.11.12'>Rom 11:12</a> etc)</li><li>of believers only, <a class='bible' href='#b43.1.29'>Joh 1:29</a>; <a class='bible' href='#b43.3.16'>Joh 3:16</a>; <a class='bible' href='#b43.3.17'>Joh 3:17</a>; <a class='bible' href='#b43.6.33'>Joh 6:33</a>; <a class='bible' href='#b43.12.47'>Joh 12:47</a> <a class='bible' href='#b46.4.9'>1Co 4:9</a>; <a class='bible' href='#b47.5.19'>2Co 5:19</a></li></ol></li></ol>","xlit":"kósmos"},"G5535":{"strongs_def":" to make (i.e. have) necessity, i.e. be in want of","derivation":"from G5532 (χρεία);","translit":"chrḗizō","lemma":"χρῄζω","kjv_def":"(have) need","pron":"khrade'-zo","pos":"Verb","thayer":"<ol><li>to have need of, to be in want of</li></ol>","xlit":"chrḗizō"},"G5321":{"strongs_def":" exhibition, i.e. (figuratively) expression, (by extension) a bestowment","derivation":"from G5319 (φανερόω);","lemma":"φανέρωσις","translit":"phanérōsis","kjv_def":"manifestation","pron":"fan-er'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>manifestation</li></ol>","xlit":"phanérōsis"},"G2193":{"lemma":"ἕως","translit":"héōs","kjv_def":"even (until, unto), (as) far (as), how long, (un-)til(-l), (hither-, un-, up) to, while(-s)","strongs_def":" a conjunction, preposition and adverb of continuance, until (of time and place)","derivation":"of uncertain affinity;","pron":"heh'-oce","pos":"Conjunction","thayer":"<ol><li>till, until</li></ol>","xlit":"héōs"},"G113":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G5087 (τίθημι) (in the sense of enacting);","strongs_def":" lawless, i.e. (by implication) criminal","kjv_def":"wicked","translit":"áthesmos","lemma":"ἄθεσμος","pron":"ath'-es-mos","pos":"Adjective","thayer":"<ol><li>one who breaks through the restraint of law and gratifies his lusts</li></ol>","xlit":"áthesmos"},"G5110":{"derivation":"from the base of G5088 (τίκτω);","strongs_def":" interest on money loaned (as a produce)","kjv_def":"usury","lemma":"τόκος","translit":"tókos","pron":"tok'-os","pos":"Noun Masculine","thayer":"<ol><li>birth<ol type='a'><li>the act of bringing forth</li><li>that which has been brought forth, offspring</li></ol><li>interest of money, usury (because it multiplies money, and as it were \"breeds\" )</li></ol>","xlit":"tókos"},"G921":{"kjv_def":"Barnabas","lemma":"Βαρνάβας","translit":"Barnábas","derivation":"of Chaldee origin (H01247 and H05029);","strongs_def":" son of Nabas (i.e. prophecy); Barnabas, an Israelite","pron":"bar-nab'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barnabas = \"son of rest\"</p><ol><li>the surname of Joses or Joseph, a Levite, a native of Cyprus He was a distinguished Christian teacher and companion and colleague of Paul.</li></ol>","xlit":"Barnábas"},"G1491":{"derivation":"from G1492 (εἴδω);","strongs_def":" a view, i.e. form (literally or figuratively)","kjv_def":"appearance, fashion, shape, sight","lemma":"εἶδος","translit":"eîdos","pron":"i'-dos","pos":"Noun Neuter","thayer":"<ol><li>the external or outward appearance, form figure, shape</li><li>form, kind</li></ol>","xlit":"eîdos"},"G2403":{"kjv_def":"Jezabel","lemma":"Ἰεζαβήλ","translit":"Iezabḗl","derivation":"of Hebrew origin (H0348);","strongs_def":" Jezabel (i.e. Jezebel), a Tyrian woman (used as a synonym of a termagant or false teacher)","pron":"ee-ed-zab-ale'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Jezebel = \"chaste\"</p><ol><li>wife of Ahab, an impious and cruel queen who protected idolatry and persecuted the prophets</li><li>the symbolic name of a woman who pretended to be a prophetess, and who, addicted to antinomianism, claimed Christian liberty of eating things sacrificed to idols</li></ol>","xlit":"Iezabḗl"},"G3444":{"derivation":"perhaps from the base of G3313 (μέρος) (through the idea of adjustment of parts);","strongs_def":" shape; figuratively, nature","kjv_def":"form","translit":"morphḗ","lemma":"μορφή","pron":"mor-fay'","pos":"Noun Feminine","thayer":"<ol><li>the form by which a person or thing strikes the vision</li><li>external appearance</li></ol>","xlit":"morphḗ"},"G187":{"kjv_def":"be fully ripe","translit":"akmázō","lemma":"ἀκμάζω","derivation":"from the same as G188 (ἀκμήν);","strongs_def":" to make a point, i.e. (figuratively) mature","pron":"ak-mad'-zo","pos":"Verb","thayer":"<ol><li>to flourish, come to maturity</li></ol>","xlit":"akmázō"},"G2057":{"derivation":"probably from G2060 (Ἑρμῆς);","strongs_def":" Hermas, a Christian","kjv_def":"Hermas","lemma":"Ἑρμᾶς","translit":"Hermâs","pron":"her-mas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Hermas = \"Mercury\"</p><ol><li>a Christian mentioned in <a class='bible' href='#b45.16.14'>Rom 16:14</a>. According to tradition, he was one of the seventy disciples, and afterwards bishop of Dalmatia. (A.D. 55)</li></ol>","xlit":"Hermâs"},"G2148":{"strongs_def":" a storm from the East (or southeast), i.e. (in modern phrase) a Levanter","derivation":"from (the east wind) and G2830 (κλύδων);","lemma":"Εὐροκλύδων","translit":"Euroklýdōn","kjv_def":"Euroklydon","pron":"yoo-rok-loo'-dohn","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Euroclydon = \"a violent agitation\"</p><ol><li>south east wind raising mighty waves</li><li>a wind causing broad waves</li></ol>","xlit":"Euroklýdōn"},"G5338":{"kjv_def":"light","lemma":"φέγγος","translit":"phéngos","derivation":"probably akin to the base of G5457 (φῶς) (compare G5350 (φθέγγομαι));","strongs_def":" brilliancy","pron":"feng'-gos","pos":"Noun Neuter","thayer":"<ol><li>light<ol type='a'><li>of the moon</li><li>of a candle or lamp</li></ol><li>the bright sunshine, the beam of light</li></ol>","xlit":"phéngos"},"G1058":{"strongs_def":" Gallion (i.e. Gallio), a Roman officer","derivation":"of Latin origin;","translit":"Gallíōn","lemma":"Γαλλίων","kjv_def":"Gallio","pron":"gal-lee'-own","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Gallio = \"One who lives on milk\"</p><ol><li>Junius Annaeus Gallio, the Roman proconsul of Achaia when Paul was at Corinth, 53 A.D., under the emperor Claudius. <a class='bible' href='#b44.18.12'>Act 18:12</a>. He was brother to Jucius Annaeus Seneca, the philosopher. Jerome in the Chronicle of Eusebius says that he committed suicide in 65 A.D. Winer thinks he was put to death by Nero.</li></ol>","xlit":"Gallíōn"},"G1309":{"kjv_def":"escape","lemma":"διαφεύγω","translit":"diapheúgō","derivation":"from G1223 (διά) and G5343 (φεύγω);","strongs_def":" to flee through, i.e. escape","pron":"dee-af-yoo'-go","pos":"Verb","thayer":"<ol><li>to flee through danger, to escape</li></ol>","xlit":"diapheúgō"},"G3188":{"derivation":"neuter of G3189 (μέλας) as noun;","strongs_def":" ink","kjv_def":"ink","lemma":"μέλαν","translit":"mélan","pron":"mel'-an","pos":"Noun Neuter","thayer":"<ol><li>ink</li></ol>","xlit":"mélan"},"G2859":{"kjv_def":"bosom, creek","lemma":"κόλπος","translit":"kólpos","derivation":"apparently a primary word;","strongs_def":" the bosom; by analogy, a bay","pron":"kol'-pos","pos":"Noun Masculine","thayer":"<ol><li>the front of the body between the arms</li><li>the bosom of a garment, i.e. the hollow formed by the upper forepart of a rather loose garment bound by a girdle or sash, used for keeping and carrying things (the fold or pocket)</li><li>a bay of the sea</li></ol>","xlit":"kólpos"},"G5539":{"derivation":"from G5540 (χρῆσις);","strongs_def":" serviceable","kjv_def":"profit","lemma":"χρήσιμος","translit":"chrḗsimos","pron":"khray'-see-mos","pos":"Adjective","thayer":"<ol><li>fit for use, useful</li></ol>","xlit":"chrḗsimos"},"G1702":{"derivation":"from G1722 (ἐν) and G3815 (παίζω);","strongs_def":" to jeer at, i.e. deride","kjv_def":"mock","translit":"empaízō","lemma":"ἐμπαίζω","pron":"emp-aheed'-zo","pos":"Verb","thayer":"<ol><li>to play with, trifle with<ol type='a'><li>to mock</li><li>to delude, deceive</li></ol></li></ol>","xlit":"empaízō"},"G2090":{"kjv_def":"prepare, provide, make ready","lemma":"ἑτοιμάζω","translit":"hetoimázō","derivation":"from G2092 (ἕτοιμος);","strongs_def":" to prepare","pron":"het-oy-mad'-zo","pos":"Verb","thayer":"<ol><li>to make ready, prepare<ol type='a'><li>to make the necessary preparations, get everything ready</li></ol><li>metaphorically<ol type='a'><li>drawn from the oriental custom of sending on before kings on their journeys persons to level the roads and make them passable</li><li>to prepare the minds of men to give the Messiah a fit reception and secure his blessings</li></ol></li></ol>","xlit":"hetoimázō"},"G4797":{"strongs_def":" to commingle promiscuously, i.e. (figuratively) to throw (an assembly) into disorder, to perplex (the mind)","derivation":"from G4862 (σύν) and (to pour) or its alternate;","translit":"synchéō","lemma":"συγχέω","kjv_def":"confound, confuse, stir up, be in an uproar","pron":"soong-kheh'-o","pos":"Verb","thayer":"<ol><li>to pour together, commingle</li><li>to disturb the mind of one, to stir up to tumult or outbreak</li><li>to confound or bewilder</li></ol>","xlit":"synchéō"},"G3194":{"derivation":"of uncertain origin;","strongs_def":" Melita, an island in the Mediterranean","kjv_def":"Melita","translit":"Melítē","lemma":"Μελίτη","pron":"mel-ee'-tay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Melita = \"honey\"</p><ol><li>the name of an island in the Mediterranean, lying between Africa and Sicily, now called Malta</li></ol>","xlit":"Melítē"},"G3996":{"translit":"penthéō","lemma":"πενθέω","kjv_def":"mourn, (be-)wail","strongs_def":" to grieve (the feeling or the act)","derivation":"from G3997 (πένθος);","pron":"pen-theh'-o","pos":"Verb","thayer":"<ol><li>to mourn</li><li>to mourn for, lament one</li></ol>","xlit":"penthéō"},"G4127":{"derivation":"from G4141 (πλήσσω);","strongs_def":" a stroke; by implication, a wound; figuratively, a calamity","kjv_def":"plague, stripe, wound(-ed)","translit":"plēgḗ","lemma":"πληγή","pron":"play-gay'","pos":"Noun Feminine","thayer":"<ol><li>a blow, stripe, a wound</li><li>a public calamity, heavy affliction, plague</li></ol>","xlit":"plēgḗ"},"G2742":{"derivation":"from G2741 (καυσόω);","strongs_def":" a glare","kjv_def":"(burning) heat","lemma":"καύσων","translit":"kaúsōn","pron":"kow'-sone","pos":"Noun Masculine","thayer":"<ol><li>burning heat<ol type='a'><li>of the sun</li></ol><li>Eurus, a very dry hot, east wind, scorching and drying up everything</li></ol>","xlit":"kaúsōn"},"G1680":{"strongs_def":" expectation (abstractly or concretely) or confidence","derivation":"from a primary (to anticipate, usually with pleasure);","translit":"elpís","lemma":"ἐλπίς","kjv_def":"faith, hope","pron":"el-pece'","pos":"Noun Feminine","thayer":"<ol><li>expectation of evil, fear</li><li>expectation of good, hope<ol type='a'><li>in the Christian sense<ol><li>joyful and confident expectation of eternal salvation</li></ol></li></ol><li>on hope, in hope, having hope<ol type='a'><li>the author of hope, or he who is its foundation</li><li>the thing hoped for</li></ol></li></ol>","xlit":"elpís"},"G4362":{"strongs_def":" to fasten to, i.e. (specially), to impale (on a cross)","derivation":"from G4314 (πρός) and G4078 (πήγνυμι);","lemma":"προσπήγνυμι","translit":"prospḗgnymi","kjv_def":"crucify","pron":"pros-payg'-noo-mee","pos":"Verb","thayer":"<ol><li>to fasten</li></ol>","xlit":"prospḗgnymi"},"G1751":{"lemma":"ἔνειμι","translit":"éneimi","kjv_def":"such things as … have","strongs_def":" to be within (neuter participle plural)","derivation":"from G1772 (ἔννομος) and G1510 (εἰμί);","pron":"en'-i-mee","pos":"Verb","thayer":"<ol><li>to be in, what is within, i.e. the soul</li></ol>","xlit":"éneimi"},"G1968":{"kjv_def":"fall into (on, upon) lie on, press upon","lemma":"ἐπιπίπτω","translit":"epipíptō","derivation":"from G1909 (ἐπί) and G4098 (πίπτω);","strongs_def":" to embrace (with affection) or seize (with more or less violence; literally or figuratively)","pron":"ep-ee-pip'-to","pos":"Verb","thayer":"<ol><li>to fall upon, to rush or press upon<ol type='a'><li>to lie upon one</li><li>to fall into one's embrace</li><li>to fall back upon</li></ol><li>metaphorically<ol type='a'><li>to fall upon one, i.e. to seize, take possession of him<ol><li>of the Holy Spirit, in his inspiration and impulse</li><li>of reproaches cast upon one</li></ol></li></ol></li></ol>","xlit":"epipíptō"},"G3001":{"derivation":"from (to dig);","strongs_def":" a vegetable","kjv_def":"herb","translit":"láchanon","lemma":"λάχανον","pron":"lakh'-an-on","pos":"Noun Neuter","thayer":"<ol><li>any pot herb, vegetables</li></ol>","xlit":"láchanon"},"G336":{"kjv_def":"death","translit":"anaíresis","lemma":"ἀναίρεσις","derivation":"from G337 (ἀναιρέω);","strongs_def":" (the act of) killing","pron":"an-ah'-ee-res-is","pos":"Noun Feminine","thayer":"<ol><li>a destroying, killing, murder</li></ol>","xlit":"anaíresis"},"G1644":{"derivation":"from G1645 (ἐλαφρός);","strongs_def":" levity (figuratively), i.e. fickleness","kjv_def":"lightness","lemma":"ἐλαφρία","translit":"elaphría","pron":"el-af-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>lightness<ol type='a'><li>used of levity and fickleness of mind</li></ol></li></ol>","xlit":"elaphría"},"G3723":{"kjv_def":"plain, right(-ly)","translit":"orthōs","lemma":"ὀρθῶς","derivation":"adverb from G3717 (ὀρθός);","strongs_def":" in a straight manner, i.e. (figuratively) correctly (also morally)","pron":"or-thoce'","pos":"Adverb","thayer":"<ol><li>rightly</li></ol>","xlit":"orthōs"},"G2450":{"lemma":"Ἰουδαΐζω","translit":"Ioudaḯzō","kjv_def":"live as the Jews","strongs_def":" to become a Judæan, i.e. \"Judaize\"","derivation":"from G2453 (Ἰουδαῖος);","pron":"ee-oo-dah-id'-zo","pos":"Verb","thayer":"<ol><li>to adopt Jewish customs and rites, imitate the Jews, Judaise<ol type='a'><li>one who observes the ritual law of the Jews</li></ol></li></ol>","xlit":"Ioudaḯzō"},"G4125":{"derivation":"of uncertain affinity;","strongs_def":" a rib, i.e. (by extension) side","kjv_def":"side","translit":"pleurá","lemma":"πλευρά","pron":"plyoo-rah'","pos":"Noun Feminine","thayer":"<ol><li>the side of the body</li></ol>","xlit":"pleurá"},"G1106":{"derivation":"from G1097 (γινώσκω);","strongs_def":" cognition, i.e. (subjectively) opinion, or (objectively) resolve (counsel, consent, etc.)","kjv_def":"advice, + agree, judgment, mind, purpose, will","lemma":"γνώμη","translit":"gnṓmē","pron":"gno'-may","xlit":"gnṓmē"},"G3604":{"kjv_def":"Ozias","lemma":"Ὀζίας","translit":"Ozías","derivation":"of Hebrew origin (H05818);","strongs_def":" Ozias (i.e. Uzzijah), an Israelite","pron":"od-zee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Uzziah = \"strength of Jehovah\"</p><ol><li>son of Amaziah, king of Judah from B.C. 810 - 758</li></ol>","xlit":"Ozías"},"G126":{"kjv_def":"eternal, everlasting","lemma":"ἀΐδιος","translit":"aḯdios","derivation":"from G104 (ἀεί);","strongs_def":" everduring (forward and backward, or forward only)","pron":"ah-id'-ee-os","pos":"Adjective","thayer":"<ol><li>eternal, everlasting</li></ol>","xlit":"aḯdios"},"G3377":{"lemma":"μηνύω","translit":"mēnýō","kjv_def":"shew, tell","strongs_def":" to disclose (through the idea of mental effort and thus calling to mind), i.e. report, declare, intimate","derivation":"probably from the same base as G3145 (μασσάομαι) and G3415 (μνάομαι) (i.e. , to strive);","pron":"may-noo'-o","pos":"Verb","thayer":"<ol><li>to disclose or make known something secret<ol type='a'><li>in a forensic sense, to inform, report</li></ol><li>to declare, tell, make known</li><li>to indicate, intimate<ol type='a'><li>of a teacher</li></ol></li></ol>","xlit":"mēnýō"},"G5161":{"strongs_def":" nutritive; Trophimus, a Christian","derivation":"from G5160 (τροφή);","lemma":"Τρόφιμος","translit":"Tróphimos","kjv_def":"Trophimus","pron":"trof'-ee-mos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Trophimus = \"nutritious\"</p><ol><li>an Ephesian Christian, and friend of the apostle Paul</li></ol>","xlit":"Tróphimos"},"G4921":{"lemma":"συνιστάω","translit":"synistáō","kjv_def":"approve, commend, consist, make, stand (with)","strongs_def":" to set together, i.e. (by implication) to introduce (favorably), or (figuratively) to exhibit; intransitively, to stand near, or (figuratively) to constitute","derivation":"from G4862 (σύν) and G2476 (ἵστημι) (including its collateral forms);","pron":"soon-is-tah'-o","pos":"Verb","thayer":"<ol><li>to place together, to set in the same place,to bring or band together<ol type='a'><li>to stand with (or near)</li></ol><li>to set one with another<ol type='a'><li>by way of presenting or introducing him</li><li>to comprehend</li></ol><li>to put together by way of composition or combination, to teach by combining and comparing<ol type='a'><li>to show, prove, establish, exhibit</li></ol><li>to put together, unite parts into one whole<ol type='a'><li>to be composed of, consist</li></ol></li></ol>","xlit":"synistáō"},"G3971":{"strongs_def":" paternal, i.e. hereditary","derivation":"from G3962 (πατήρ);","lemma":"πατρῷος","translit":"patrōios","kjv_def":"of fathers","pron":"pat-ro'-os","pos":"Adjective","thayer":"<ol><li>descending from father to son or from ancestors to their posterity as it were by right of inheritance</li><li>received from the fathers</li></ol>","xlit":"patrōios"},"G3656":{"lemma":"ὁμιλέω","translit":"homiléō","kjv_def":"commune, talk","strongs_def":" to be in company with, i.e. (by implication) to converse","derivation":"from G3658 (ὅμιλος);","pron":"hom-il-eh'-o","pos":"Verb","thayer":"<ol><li>to be in company with</li><li>to associate with</li><li>to stay with</li><li>to converse with, talk about: with one</li></ol>","xlit":"homiléō"},"G2620":{"derivation":"from G2596 (κατά) and G2744 (καυχάομαι);","strongs_def":" to exult against (i.e. over)","kjv_def":"boast (against), glory, rejoice against","translit":"katakaucháomai","lemma":"κατακαυχάομαι","pron":"kat-ak-ow-khah'-om-ahee","pos":"Verb","thayer":"<ol><li>to glory against, to exult over, to boast one's self to the injury (of a person or thing)</li></ol>","xlit":"katakaucháomai"},"G529":{"strongs_def":" a (friendly) encounter","derivation":"from G528 (ἀπαντάω);","lemma":"ἀπάντησις","translit":"apántēsis","kjv_def":"meet","pron":"ap-an'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>to meet one</li></ol>","xlit":"apántēsis"},"G2365":{"strongs_def":" a daughterling","derivation":"from G2364 (θυγάτηρ);","lemma":"θυγάτριον","translit":"thygátrion","kjv_def":"little (young) daughter","pron":"thoo-gat'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a little daughter</li></ol>","xlit":"thygátrion"},"G2402":{"strongs_def":" perspiration","derivation":"a strengthened form of a primary idos (sweat);","translit":"hidrṓs","lemma":"ἱδρώς","kjv_def":"sweat","pron":"hid-roce'","pos":"Noun Masculine","thayer":"<ol><li>sweat</li></ol>","xlit":"hidrṓs"},"G1240":{"strongs_def":" a successor in office","derivation":"from G1237 (διαδέχομαι);","translit":"diádochos","lemma":"διάδοχος","kjv_def":"room","pron":"dee-ad'-okh-os","pos":"Noun Masculine","thayer":"<ol><li>succeeding, a successor</li></ol>","xlit":"diádochos"},"G661":{"kjv_def":"repay","translit":"apotínō","lemma":"ἀποτίνω","derivation":"from G575 (ἀπό) and G5099 (τίνω);","strongs_def":" to pay in full","pron":"ap-ot-ee'-no","pos":"Verb","thayer":"<ol><li>to pay off, repay</li></ol>","xlit":"apotínō"},"G730":{"translit":"árrhēn","lemma":"ἄῤῥην","kjv_def":"male, man","strongs_def":" male (as stronger for lifting)","derivation":"probably from G142 (αἴρω);","pron":"ar'-hrane","pos":"Adjective","thayer":"<ol><li>a male</li></ol>","xlit":"árrhēn"},"G4798":{"lemma":"συγχράομαι","translit":"synchráomai","kjv_def":"have dealings with","strongs_def":" to use jointly, i.e. (by implication) to hold intercourse in common","derivation":"from G4862 (σύν) and G5530 (χράομαι);","pron":"soong-khrah'-om-ahee","pos":"Verb","thayer":"<ol><li>to use with anyone, use jointly</li><li>to associate with, to have dealings with</li></ol>","xlit":"synchráomai"},"G3308":{"strongs_def":" solicitude","derivation":"from G3307 (μερίζω) (through the idea of distraction);","lemma":"μέριμνα","translit":"mérimna","kjv_def":"care","pron":"mer'-im-nah","pos":"Noun Feminine","thayer":"<ol><li>care, anxiety</li></ol>","xlit":"mérimna"},"G870":{"translit":"aphóbōs","lemma":"ἀφόβως","kjv_def":"without fear","strongs_def":" fearlessly","derivation":"adverb from a compound of G1 (Α) (as a negative particle) and G5401 (φόβος);","pron":"af-ob'-oce","pos":"Adverb","thayer":"<ol><li>without fear, boldly</li></ol>","xlit":"aphóbōs"},"G2300":{"derivation":"a prolonged form of a primary verb;","strongs_def":" to look closely at, i.e. (by implication) perceive (literally or figuratively); by extension to visit","kjv_def":"behold, look (upon), see","translit":"theáomai","lemma":"θεάομαι","pron":"theh-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to behold, look upon, view attentively, contemplate (often used of public shows)<ol type='a'><li>of important persons that are looked on with admiration</li></ol><li>to view, take a view of<ol type='a'><li>in the sense of visiting, meeting with a person</li></ol><li>to learn by looking, to see with the eyes, to perceive</li></ol>","xlit":"theáomai"},"G3586":{"lemma":"ξύλον","translit":"xýlon","kjv_def":"staff, stocks, tree, wood","strongs_def":" timber (as fuel or material); by implication, a stick, club or tree or other wooden article or substance","derivation":"from another form of the base of G3582 (ξέστης);","pron":"xoo'-lon","pos":"Noun Neuter","thayer":"<ol><li>wood<ol type='a'><li>that which is made of wood<ol><li>as a beam from which any one is suspended, a gibbet, a cross</li><li>a log or timber with holes in which the feet, hands, neck of prisoners were inserted and fastened with thongs</li><li>a fetter, or shackle for the feet</li><li>a cudgel, stick, staff</li></ol></li></ol><li>a tree</li></ol>","xlit":"xýlon"},"G2175":{"derivation":"from a compound of G2095 (εὖ) and a derivative of G3605 (ὄζω);","strongs_def":" good-scentedness, i.e. fragrance","kjv_def":"sweet savour (smell, -smelling)","lemma":"εὐωδία","translit":"euōdía","pron":"yoo-o-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a sweet smell, fragrance</li><li>a fragrant or sweet smelling thing, incense, on odour or something sweet smelling<ol type='a'><li>an odour of acquiescence, satisfaction</li><li>a sweet odour, spoken of the smell of sacrifices and obligations, agreeably to the ancient notion that God smells and is pleased with the odour of sacrifices</li></ol><li>metaphorically a thing well pleasing to God</li></ol>","xlit":"euōdía"},"G617":{"derivation":"from G575 (ἀπό) and G2947 (κυλιόω);","strongs_def":" to roll away","kjv_def":"roll away (back)","translit":"apokylíō","lemma":"ἀποκυλίω","pron":"ap-ok-oo-lee'-o","pos":"Verb","thayer":"<ol><li>to roll off or away</li></ol>","xlit":"apokylíō"},"G4521":{"strongs_def":" the Sabbath (i.e. Shabbath), or day of weekly repose from secular avocations (also the observance or institution itself); by extension, a se'nnight, i.e. the interval between two Sabbaths; likewise the plural in all the above applications","derivation":"of Hebrew origin (H07676);","lemma":"σάββατον","translit":"sábbaton","kjv_def":"sabbath (day), week","pron":"sab'-bat-on","pos":"Noun Neuter","thayer":"<ol><li>the seventh day of each week which was a sacred festival on which the Israelites were required to abstain from all work<ol type='a'><li>the institution of the sabbath, the law for keeping holy every seventh day of the week</li><li>a single sabbath, sabbath day</li></ol><li>seven days, a week</li></ol>","xlit":"sábbaton"},"G4530":{"derivation":"probably from the same as G4531 (σαλεύω);","strongs_def":" Salim, a place in Palestine","kjv_def":"Salim","lemma":"Σαλείμ","translit":"Saleím","pron":"sal-ime'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Salim = \"peace\"</p><ol><li>a well known town 8 miles (11 km) south of Scythopolis</li></ol>","xlit":"Saleím"},"G3998":{"kjv_def":"poor","translit":"penichrós","lemma":"πενιχρός","derivation":"prolongation from the base of G3993 (πένης);","strongs_def":" necessitous","pron":"pen-ikh-ros'","pos":"Adjective","thayer":"<ol><li>needy, poor</li></ol>","xlit":"penichrós"},"G1049":{"strongs_def":" a treasure-house, i.e. a court in the temple for the collection-boxes","derivation":"from G1047 (γάζα) and G5438 (φυλακή);","lemma":"γαζοφυλάκιον","translit":"gazophylákion","kjv_def":"treasury","pron":"gad-zof-oo-lak'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a repository of treasure, especially of public treasure, a treasury. It is used to describe the apartments constructed in the courts of the temple, in which the not only the sacred offerings and things needful for the service were kept, but in which the priests, etc, dwelt: <a class='bible' href='#b16.13.7'>Neh 13:7</a>; of the sacred treasury in which not only treasure but also public records were stored, and the property of widows and orphans was deposited.</li></ol>","xlit":"gazophylákion"},"G1995":{"kjv_def":"conversion","translit":"epistrophḗ","lemma":"ἐπιστροφή","derivation":"from G1994 (ἐπιστρέφω);","strongs_def":" reversion, i.e. morally, revolution","pron":"ep-is-trof-ay'","pos":"Noun Feminine","thayer":"<ol><li>conversion (of the Gentiles from idolatry to the true God)</li></ol>","xlit":"epistrophḗ"},"G4407":{"strongs_def":" pertaining to the dawn, i.e. matutinal","derivation":"from G4404 (πρωΐ);","lemma":"πρωϊνός","translit":"prōïnós","kjv_def":"morning","pron":"pro-ee-nos'","pos":"Adjective","thayer":"<ol><li>pertaining to the morning</li></ol>","xlit":"prōïnós"},"G3926":{"strongs_def":" to harass further, i.e. annoy","derivation":"from G3844 (παρά) and G1776 (ἐνοχλέω);","translit":"parenochléō","lemma":"παρενοχλέω","kjv_def":"trouble","pron":"par-en-okh-leh'-o","pos":"Verb","thayer":"<ol><li>to cause trouble in a matter, to trouble, annoy</li></ol>","xlit":"parenochléō"},"G1211":{"strongs_def":" a particle of emphasis or explicitness; now, then, etc.","derivation":"probably akin to G1161 (δέ);","translit":"dḗ","lemma":"δή","kjv_def":"also, and, doubtless, now, therefore","pron":"day","thayer":"<ol><li>now, then, verily, in truth, really, surely, certainly</li><li>forthwith, at once</li></ol>","xlit":"dḗ"},"G2831":{"lemma":"κλυδωνίζομαι","translit":"klydōnízomai","kjv_def":"toss to and fro","strongs_def":" to surge, i.e. (figuratively) to fluctuate","derivation":"middle voice from G2830 (κλύδων);","pron":"kloo-do-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to be tossed by the waves</li><li>metaphorically to be agitated (like the waves) mentally</li></ol>","xlit":"klydōnízomai"},"G4272":{"kjv_def":"first give","translit":"prodídōmi","lemma":"προδίδωμι","derivation":"from G4253 (πρό) and G1325 (δίδωμι);","strongs_def":" to give before the other party has given","pron":"prod-id'-o-mee","pos":"Verb","thayer":"<ol><li>to give before, give first</li><li>to betray</li></ol>","xlit":"prodídōmi"},"G5138":{"derivation":"perhaps strengthened from the base of G4486 (ῥήγνυμι) (as if jagged by rents);","strongs_def":" uneven, rocky (reefy)","kjv_def":"rock, rough","lemma":"τραχύς","translit":"trachýs","pron":"trakh-oos'","pos":"Adjective","thayer":"<ol><li>rough, rocky<ol type='a'><li>of places of the sea</li></ol></li></ol>","xlit":"trachýs"},"G2089":{"strongs_def":" \"yet,\" still (of time or degree)","derivation":"perhaps akin to G2094 (ἔτος);","translit":"éti","lemma":"ἔτι","kjv_def":"after that, also, ever, (any) further, (t-)henceforth (more), hereafter, (any) longer, (any) more(-one), now, still, yet","pron":"et'-ee","pos":"Adverb","thayer":"<ol><li>yet, still<ol type='a'><li>of time<ol><li>of a thing which went on formerly, whereas now a different state of things exists or has begun to exist</li><li>of a thing which continues at present<ol type='a'><li>even, now</li></ol><li>with negatives<ol type='a'><li>no longer, no more</li></ol></li></ol><li>of degree and increase<ol><li>even, yet</li><li>besides, more, further</li></ol></li></ol></li></ol>","xlit":"éti"},"G3879":{"kjv_def":"look (into), stoop down","lemma":"παρακύπτω","translit":"parakýptō","derivation":"from G3844 (παρά) and G2955 (κύπτω);","strongs_def":" to bend beside, i.e. lean over (so as to peer within)","pron":"par-ak-oop'-to","pos":"Verb","thayer":"<ol><li>to stoop to a thing in order to look at it</li><li>to look at with head bowed forward</li><li>to look into with the body bent</li><li>to stoop and look into</li><li>metaphorically to look carefully into, inspect curiously<ol type='a'><li>of one who would become acquainted with something</li></ol></li></ol>","xlit":"parakýptō"},"G5505":{"strongs_def":" one thousand (\"chiliad\")","derivation":"from G5507 (χίλιοι);","translit":"chiliás","lemma":"χιλιάς","kjv_def":"thousand","pron":"khil-ee-as'","pos":"Noun Feminine","thayer":"<ol><li>a thousand, the number one thousand</li></ol>","xlit":"chiliás"},"G188":{"translit":"akmḗn","lemma":"ἀκμήν","kjv_def":"yet","strongs_def":" adverbially, just now, i.e. still","derivation":"accusative case of a noun (\"acme\") akin to (a point) and meaning the same;","pron":"ak-mane'","pos":"Adverb","thayer":"<ol><li>a point</li><li>extremity, climax, acme, highest degree</li><li>the present time</li></ol>","xlit":"akmḗn"},"G821":{"derivation":"from G820 (ἄτιμος);","strongs_def":" used like G818 (ἀτιμάζω), to maltreat","kjv_def":"handle shamefully","lemma":"ἀτιμόω","translit":"atimóō","pron":"at-ee-mo'-o","pos":"Verb","thayer":"<ol><li>to dishonour, mark with disgrace</li></ol>","xlit":"atimóō"},"G951":{"derivation":"from G950 (βεβαιόω);","strongs_def":" stabiliment","kjv_def":"confirmation","translit":"bebaíōsis","lemma":"βεβαίωσις","pron":"beb-ah'-yo-sis","pos":"Noun Feminine","thayer":"<ol><li>confirmation</li></ol>","xlit":"bebaíōsis"},"G3829":{"translit":"pandocheîon","lemma":"πανδοχεῖον","kjv_def":"inn","strongs_def":" all-receptive, i.e. a public lodging-place (caravanserai or khan)","derivation":"neuter of a presumed compound of G3956 (πᾶς) and a derivative of G1209 (δέχομαι);","pron":"pan-dokk-i'-on","pos":"Noun Neuter","thayer":"<ol><li>an inn, a public house for the reception of strangers</li></ol>","xlit":"pandocheîon"},"G2067":{"strongs_def":" clothing (concretely)","derivation":"from a derivative of G2066 (ἐσθής);","lemma":"ἔσθησις","translit":"ésthēsis","kjv_def":"government","pron":"es'-thay-sis","pos":"Noun Feminine","thayer":"<ol><li>clothing, apparel</li></ol>","xlit":"ésthēsis"},"G1003":{"derivation":"of Hebrew origin (H01162);","strongs_def":" Booz, (i.e. Boaz), an Israelite","kjv_def":"Booz","translit":"Boóz","lemma":"Βοόζ","pron":"bo-oz'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Boaz = \"in him is strength\"</p><ol><li>a kinsman of Ruth, afterwards her second husband</li></ol>","xlit":"Boóz"},"G3401":{"kjv_def":"follow","lemma":"μιμέομαι","translit":"miméomai","derivation":"middle voice from (a \"mimic\");","strongs_def":" to imitate","pron":"mim-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to imitate: any one</li></ol>","xlit":"miméomai"},"G2034":{"derivation":"adverb from G2033 (ἑπτά);","strongs_def":" seven times","kjv_def":"seven times","lemma":"ἑπτάκις","translit":"heptákis","pron":"hep-tak-is'","pos":"Adverb","thayer":"<ol><li>seven times</li></ol>","xlit":"heptákis"},"G4296":{"strongs_def":" to herald (i.e. proclaim) in advance","derivation":"from G4253 (πρό) and G2784 (κηρύσσω);","lemma":"προκηρύσσω","translit":"prokērýssō","kjv_def":"before (first) preach","pron":"prok-ay-rooce'-so","pos":"Verb","thayer":"<ol><li>to announce or proclaim be herald beforehand</li><li>to announce beforehand (of the herald himself)</li></ol>","xlit":"prokērýssō"},"G4065":{"translit":"periphronéō","lemma":"περιφρονέω","kjv_def":"despise","strongs_def":" to think beyond, i.e. depreciate (contemn)","derivation":"from G4012 (περί) and G5426 (φρονέω);","pron":"per-ee-fron-eh'-o","pos":"Verb","thayer":"<ol><li>to consider or examine on all sides, i.e. carefully, thoroughly</li><li>to set one's self in thought beyond (exalt one's self in thought above) a person or a thing</li><li>to contemn, to despise</li></ol>","xlit":"periphronéō"},"G198":{"strongs_def":" to be exact, i.e. ascertain","derivation":"from the same as G196 (ἀκριβέστατος);","translit":"akribóō","lemma":"ἀκριβόω","kjv_def":"enquire diligently","pron":"ak-ree-bo'-o","pos":"Verb","thayer":"<ol><li>to know accurately, to do exactly</li><li>to investigate diligently</li></ol>","xlit":"akribóō"},"G2312":{"kjv_def":"taught of God","translit":"theodídaktos","lemma":"θεοδίδακτος","derivation":"from G2316 (θεός) and G1321 (διδάσκω);","strongs_def":" divinely instructed","pron":"theh-od-id'-ak-tos","pos":"Adjective","thayer":"<ol><li>taught of God</li></ol>","xlit":"theodídaktos"},"G5295":{"strongs_def":" to run under, i.e. (specially), to sail past","derivation":"from G5259 (ὑπό) and G5143 (τρέχω) (including its alternate);","translit":"hypotréchō","lemma":"ὑποτρέχω","kjv_def":"run under","pron":"hoop-ot-rekh'-o","pos":"Verb","thayer":"<ol><li>to run under<ol type='a'><li>of navigators<ol><li>to run past a place on the shore, and therefore in a higher position</li><li>running under the lee of</li></ol></li></ol></li></ol>","xlit":"hypotréchō"},"G5058":{"strongs_def":" a tax-gatherer's place of business","derivation":"neuter of a presumed derivative of G5057 (τελώνης);","lemma":"τελώνιον","translit":"telṓnion","kjv_def":"receipt of custom","pron":"tel-o'-nee-on","pos":"Noun Neuter","thayer":"<ol><li>customs, toll</li><li>toll house, place of toll, tax office</li><li>the place in which the tax collector sat to collect the taxes</li></ol>","xlit":"telṓnion"},"G5035":{"kjv_def":"lightly, quickly","translit":"tachý","lemma":"ταχύ","derivation":"neuter singular of G5036 (ταχύς) (as adverb);","strongs_def":" shortly, i.e. without delay, soon, or (by surprise) suddenly, or (by implication, of ease) readily","pron":"takh-oo'","pos":"Adverb","thayer":"<ol><li>quickly, speedily (without delay)</li></ol>","xlit":"tachý"},"G77":{"strongs_def":" and G1160 (δαπάνη); costless, i.e. gratuitous","derivation":"from G1 (Α) (as negative particle);","lemma":"ἀδάπανος","translit":"adápanos","kjv_def":"without expense","pron":"ad-ap'-an-os","pos":"Adjective","thayer":"<ol><li>without expense, requiring no outlay, costing nothing</li></ol>","xlit":"adápanos"},"G137":{"kjv_def":"Ænon","lemma":"Αἰνών","translit":"Ainṓn","derivation":"of Hebrew origin (a derivative of G5869, place of springs);","strongs_def":" Ænon, a place in Palestine","pron":"ahee-nohn'","pos":"Noun Location","thayer":"<ol><li>the name of a place \"near to Salim\" at which John baptised</li></ol>","xlit":"Ainṓn"},"G2846":{"kjv_def":"+ chamberlain","lemma":"κοιτών","translit":"koitṓn","derivation":"from G2845 (κοίτη);","strongs_def":" a bedroom","pron":"koy-tone'","pos":"Noun Masculine","thayer":"<ol><li>a sleeping room, bed chamber<ol type='a'><li>the officer who is over the bed chamber, the chamberlain</li></ol></li></ol>","xlit":"koitṓn"},"G4539":{"strongs_def":" Salome (i.e. Shelomah), an Israelitess","derivation":"probably of Hebrew origin (feminine from H07965);","lemma":"Σαλώμη","translit":"Salṓmē","kjv_def":"Salome","pron":"sal-o'-may","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Salome = \"peaceful\"</p><ol><li>the wife of Zebedee and the mother of the apostle James the elder and John</li></ol>","xlit":"Salṓmē"},"G3147":{"kjv_def":"scourge","translit":"mastízō","lemma":"μαστίζω","derivation":"from G3149 (μαστός);","strongs_def":" to whip (literally)","pron":"mas-tid'-zo","pos":"Verb","thayer":"<ol><li>to whip, flog, scourge</li></ol>","xlit":"mastízō"},"G3505":{"derivation":"of Latin origin;","strongs_def":" Neron (i.e. Nero), a Roman emperor","kjv_def":"Nero","lemma":"Νέρων","translit":"Nérōn","pron":"ner'-ohn","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nero = \"brave\"</p><ol><li>a famous but cruel emperor or Rome from 54 to 68 A.D.</li></ol>","xlit":"Nérōn"},"G2746":{"translit":"kaúchēsis","lemma":"καύχησις","kjv_def":"boasting, whereof I may glory, glorying, rejoicing","strongs_def":" boasting (properly, the act; by implication, the object), in a good or a bad sense","derivation":"from G2744 (καυχάομαι);","pron":"kow'-khay-sis","pos":"Noun Feminine","thayer":"<ol><li>the act of glorying</li></ol>","xlit":"kaúchēsis"},"G662":{"derivation":"from G575 (ἀπό) and G5111 (τολμάω);","strongs_def":" to venture plainly","kjv_def":"be very bold","lemma":"ἀποτολμάω","translit":"apotolmáō","pron":"ap-ot-ol-mah'-o","pos":"Verb","thayer":"<ol><li>to assume boldness, make bold</li></ol>","xlit":"apotolmáō"},"G654":{"strongs_def":" to turn away or back (literally or figuratively)","derivation":"from G575 (ἀπό) and G4762 (στρέφω);","lemma":"ἀποστρέφω","translit":"apostréphō","kjv_def":"bring again, pervert, turn away (from)","pron":"ap-os-tref'-o","pos":"Verb","thayer":"<ol><li>to turn away<ol type='a'><li>to remove anything from anyone</li><li>to turn him away from allegiance to any one</li><li>tempt to defect</li></ol><li>to turn back, return, bring back<ol type='a'><li>of putting a sword back in its sheath</li><li>of Judas returning money to temple</li></ol><li>to turn one's self away, turn back, return</li><li>to turn one's self away from, deserting</li></ol>","xlit":"apostréphō"},"G940":{"derivation":"akin to G5335 (φάσκω);","strongs_def":" to malign, i.e. (by extension) to fascinate (by false representations)","kjv_def":"bewitch","lemma":"βασκαίνω","translit":"baskaínō","pron":"bas-kah'-ee-no","pos":"Verb","thayer":"<ol><li>to speak ill of one, to slander, traduce him</li><li>to bring evil on one by feigning praise or an evil eye</li><li>to charm, to bewitch</li></ol>","xlit":"baskaínō"},"G633":{"translit":"aponíptō","lemma":"ἀπονίπτω","kjv_def":"wash","strongs_def":" to wash off (reflexively, one's own hands symbolically)","derivation":"from G575 (ἀπό) and G3538 (νίπτω);","pron":"ap-on-ip'-to","pos":"Verb","thayer":"<ol><li>to wash off</li><li>to wash off one's self, to wash off for one's self</li></ol>","xlit":"aponíptō"},"G4077":{"strongs_def":" a fount (literally or figuratively), i.e. source or supply (of water, blood, enjoyment) (not necessarily the original spring)","derivation":"probably from G4078 (πήγνυμι) (through the idea of gushing plumply);","translit":"pēgḗ","lemma":"πηγή","kjv_def":"fountain, well","pron":"pay-gay'","pos":"Noun Feminine","thayer":"<ol><li>fountain, spring</li><li>a well fed by a spring</li></ol>","xlit":"pēgḗ"},"G4447":{"derivation":"from G4443 (πυρά);","strongs_def":" fiery, i.e. (by implication) flaming","kjv_def":"of fire","translit":"pýrinos","lemma":"πύρινος","pron":"poo'-ree-nos","pos":"Adjective","thayer":"<ol><li>fiery</li><li>shining like fire</li></ol>","xlit":"pýrinos"},"G5487":{"derivation":"from G5485 (χάρις);","strongs_def":" to grace, i.e. indue with special honor","kjv_def":"make accepted, be highly favoured","translit":"charitóō","lemma":"χαριτόω","pron":"khar-ee-to'-o","pos":"Verb","thayer":"<ol><li>to make graceful<ol type='a'><li>charming, lovely, agreeable</li></ol><li>to peruse with grace, compass with favour</li><li>to honour with blessings</li></ol>","xlit":"charitóō"},"G1976":{"derivation":"from G1909 (ἐπί) and the base of G4476 (ῥαφίς);","strongs_def":" to stitch upon, i.e. fasten with the needle","kjv_def":"sew on","translit":"epirrháptō","lemma":"ἐπιῤῥάπτω","pron":"ep-ir-hrap'-to","pos":"Verb","thayer":"<ol><li>to sew upon, sew to</li></ol>","xlit":"epirrháptō"},"G3761":{"kjv_def":"neither (indeed), never, no (more, nor, not), nor (yet), (also, even, then) not (even, so much as), + nothing, so much as","lemma":"οὐδέ","translit":"oudé","derivation":"from G3756 (οὐ) and G1161 (δέ);","strongs_def":" not however, i.e. neither, nor, not even","pron":"oo-deh'","pos":"Conjunction","thayer":"<ol><li>but not, neither, nor, not even</li></ol>","xlit":"oudé"},"G4809":{"strongs_def":" the \"sycamore\"-fig tree","derivation":"from G4810 (σῦκον) and (the mulberry);","lemma":"συκομωραία","translit":"sykomōraía","kjv_def":"sycamore tree","pron":"soo-kom-o-rah'-yah","pos":"Noun Feminine","thayer":"<ol><li>a sycomore tree</li></ol>","xlit":"sykomōraía"},"G4710":{"derivation":"from G4692 (σπεύδω);","strongs_def":" \"speed\", i.e. (by implication) despatch, eagerness, earnestness","kjv_def":"business, (earnest) care(-fulness), diligence, forwardness, haste","translit":"spoudḗ","lemma":"σπουδή","pron":"spoo-day'","pos":"Noun Feminine","thayer":"<ol><li>haste, with haste</li><li>earnestness, diligence<ol type='a'><li>earnestness in accomplishing, promoting, or striving after anything</li><li>to give all diligence, interest one's self most earnestly</li></ol></li></ol>","xlit":"spoudḗ"},"G2781":{"derivation":"diminutive from (wax);","strongs_def":" a cell for honey, i.e. (collectively) the comb","kjv_def":"(honey-)comb","translit":"kēríon","lemma":"κηρίον","pron":"kay-ree'-on","pos":"Noun Neuter","thayer":"<ol><li>honeycomb</li></ol>","xlit":"kēríon"},"G2598":{"translit":"katabállō","lemma":"καταβάλλω","kjv_def":"cast down, lay","strongs_def":" to throw down","derivation":"from G2596 (κατά) and G906 (βάλλω);","pron":"kat-ab-al'-lo","pos":"Verb","thayer":"<ol><li>to cast down<ol type='a'><li>to throw to the ground, prostate</li></ol><li>to put in a lower place<ol type='a'><li>to lay (down) a foundation</li></ol></li></ol>","xlit":"katabállō"},"G3686":{"strongs_def":" a \"name\" (literally or figuratively) (authority, character)","derivation":"from a presumed derivative of the base of G1097 (γινώσκω) (compare G3685 (ὀνίνημι));","translit":"ónoma","lemma":"ὄνομα","kjv_def":"called, (+ sur-)name(-d)","pron":"on'-om-ah","pos":"Noun Neuter","thayer":"<ol><li>name: univ. of proper names</li><li>the name is used for everything which the name covers, everything the thought or feeling of which is aroused in the mind by mentioning, hearing, remembering, the name, i.e. for one's rank, authority, interests, pleasure, command, excellences, deeds etc.</li><li>persons reckoned up by name</li><li>the cause or reason named: on this account, because he suffers as a Christian, for this reason</li></ol>","xlit":"ónoma"},"G3707":{"kjv_def":"visible","lemma":"ὁρατός","translit":"horatós","derivation":"from G3708 (ὁράω);","strongs_def":" gazed at, i.e. (by implication) capable of being seen","pron":"hor-at-os'","pos":"Adjective","thayer":"<ol><li>visible, open to view</li></ol>","xlit":"horatós"},"G218":{"strongs_def":" to oil (with perfume)","derivation":"from G1 (Α) (as particle of union) and the base of G3045 (λιπαρός);","translit":"aleíphō","lemma":"ἀλείφω","kjv_def":"anoint","pron":"al-i'-fo","pos":"Verb","thayer":"<ol><li>to anoint</li></ol>","xlit":"aleíphō"},"G1138":{"kjv_def":"David","lemma":"Δαβίδ","translit":"Dabíd","derivation":"of Hebrew origin (H01732);","strongs_def":" Dabid (i.e. David), the Israelite king","pron":"dab-eed'","pos":"Noun Masculine","thayer":"<ol><li>second king of Israel, and ancestor of Jesus Christ</li></ol>","xlit":"Dabíd"},"G4919":{"lemma":"συνθρύπτω","translit":"synthrýptō","kjv_def":"break","strongs_def":" to crush together, i.e. (figuratively) to dispirit","derivation":"from G4862 (σύν) and (to crumble);","pron":"soon-throop'-to","pos":"Verb","thayer":"<ol><li>break in pieces, to crush</li><li>metaphorically<ol type='a'><li>to break one's heart</li><li>to deprive of strength and courage, dispirit, incapacitate for enduring trials</li></ol></li></ol>","xlit":"synthrýptō"},"G3096":{"kjv_def":"use sorcery","lemma":"μαγεύω","translit":"mageúō","derivation":"from G3097 (μάγος);","strongs_def":" to practice magic","pron":"mag-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a magician, to practise magical arts</li></ol>","xlit":"mageúō"},"G5010":{"strongs_def":" regular arrangement, i.e. (in time) fixed succession (of rank or character), official dignity","derivation":"from G5021 (τάσσω);","lemma":"τάξις","translit":"táxis","kjv_def":"order","pron":"tax'-is","pos":"Noun Feminine","thayer":"<ol><li>an arranging, arrangement</li><li>order<ol type='a'><li>a fixed succession observing a fixed time</li></ol><li>due or right order, orderly condition</li><li>the post, rank, or position which one holds in civic or other affairs<ol type='a'><li>since this position generally depends on one's talents, experience, resources<ol><li>character, fashion, quality, style</li></ol></li></ol></li></ol>","xlit":"táxis"},"G3877":{"translit":"parakolouthéō","lemma":"παρακολουθέω","kjv_def":"attain, follow, fully know, have understanding","strongs_def":" to follow near, i.e. (figuratively) attend (as a result), trace out, conform to","derivation":"from G3844 (παρά) and G190 (ἀκολουθέω);","pron":"par-ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow after<ol type='a'><li>so to follow one as to be always at his side</li><li>to follow close, accompany</li></ol><li>metaphorically<ol type='a'><li>to be always present, to attend one wherever he goes</li><li>to follow up a thing in mind so as to attain to the knowledge of it<ol><li>to understand, (compare our follow a matter up, trace its course)</li><li>to examine thoroughly, investigate</li></ol><li>to follow faithfully i.e a standard or rule, to conform one's self to</li></ol></li></ol>","xlit":"parakolouthéō"},"G2214":{"derivation":"from G2212 (ζητέω);","strongs_def":" a searching (properly, the act), i.e. a dispute or its theme","kjv_def":"question","translit":"zḗtēsis","lemma":"ζήτησις","pron":"dzay'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>a seeking</li><li>enquiry</li><li>a questioning, debate</li><li>a subject of questioning or debate, matter of controversy</li></ol>","xlit":"zḗtēsis"},"G1090":{"strongs_def":" to till (the soil)","derivation":"from G1092 (γεωργός);","lemma":"γεωργέω","translit":"geōrgéō","kjv_def":"dress","pron":"gheh-or-gheh'-o","pos":"Verb","thayer":"<ol><li>to practise agriculture, to till the ground</li></ol>","xlit":"geōrgéō"},"G408":{"kjv_def":"Adronicus","translit":"Andrónikos","lemma":"Ἀνδρόνικος","derivation":"from G435 (ἀνήρ) and G3534 (νῖκος);","strongs_def":" man of victory; Andronicos, an Israelite","pron":"an-dron'-ee-kos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Andronicus = \"man of victory\"</p><ol><li>a Jewish Christian and a kinsman of Paul</li></ol>","xlit":"Andrónikos"},"G1690":{"translit":"embrimáomai","lemma":"ἐμβριμάομαι","kjv_def":"straitly charge, groan, murmur against","strongs_def":" to have indignation on, i.e. (transitively) to blame, (intransitively) to sigh with chagrin, (specially) to sternly enjoin","derivation":"from G1722 (ἐν) and (to snort with anger);","pron":"em-brim-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to charge with earnest admonition, sternly to charge, threatened to enjoin</li></ol>","xlit":"embrimáomai"},"G4280":{"kjv_def":"foretell, say (speak, tell) before","lemma":"προερέω","translit":"proeréō","derivation":"from G4253 (πρό) and G2046 (ἐρέω);","strongs_def":" used as alternate of G4277 (προέπω); to say already, predict","pron":"pro-er-eh'-o","pos":"Verb","thayer":"<ol><li>to say before<ol type='a'><li>to say in what precedes, to say above</li><li>to say before, i.e. heretofore, formerly</li><li>to say beforehand, i.e. before the event: prophecies</li></ol></li></ol>","xlit":"proeréō"},"G3763":{"kjv_def":"neither at any time, never, nothing at any time","lemma":"οὐδέποτε","translit":"oudépote","derivation":"from G3761 (οὐδέ) and G4218 (ποτέ);","strongs_def":" not even at any time, i.e. never at all","pron":"oo-dep'-ot-eh","pos":"Adverb","thayer":"<ol><li>never</li></ol>","xlit":"oudépote"},"G4741":{"kjv_def":"fix, (e-)stablish, stedfastly set, strengthen","translit":"stērízō","lemma":"στηρίζω","derivation":"from a presumed derivative of G2476 (ἵστημι) (like G4731 (στερεός));","strongs_def":" to set fast, i.e. (literally) to turn resolutely in a certain direction, or (figuratively) to confirm","pron":"stay-rid'-zo","pos":"Verb","thayer":"<ol><li>to make stable, place firmly, set fast, fix</li><li>to strengthen, make firm</li><li>to render constant, confirm, one's mind</li></ol>","xlit":"stērízō"},"G1648":{"lemma":"Ἐλεάζαρ","translit":"Eleázar","kjv_def":"Eleazar","strongs_def":" Eleazar, an Israelite","derivation":"of Hebrew origin (H0499);","pron":"el-eh-ad'-zar","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eleazar = \"help of God\"</p><ol><li>one of the ancestors of Christ</li></ol>","xlit":"Eleázar"},"G1904":{"strongs_def":" to supervene, i.e. arrive, occur, impend, attack, (figuratively) influence","derivation":"from G1909 (ἐπί) and G2064 (ἔρχομαι);","lemma":"ἐπέρχομαι","translit":"epérchomai","kjv_def":"come (in, upon)","pron":"ep-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come to arrive<ol type='a'><li>of time, come on, be at hand, be future</li></ol><li>to come upon, overtake, one<ol type='a'><li>of sleep</li><li>of disease</li><li>of calamities</li><li>of the Holy Spirit, descending and operating in one</li><li>of an enemy attacking one</li></ol></li></ol>","xlit":"epérchomai"},"G49":{"translit":"hagnismós","lemma":"ἁγνισμός","kjv_def":"purification","strongs_def":" a cleansing (the act), i.e. (ceremonially) lustration","derivation":"from G48 (ἁγνίζω);","pron":"hag-nis-mos'","pos":"Noun Masculine","thayer":"<ol><li>purification, expiation</li></ol>","xlit":"hagnismós"},"G3726":{"derivation":"from G3727 (ὅρκος);","strongs_def":" to put on oath, i.e. make swear; by analogy, to solemnly enjoin","kjv_def":"adjure, charge","translit":"horkízō","lemma":"ὁρκίζω","pron":"hor-kid'-zo","pos":"Verb","thayer":"<ol><li>to force to take an oath, to administer an oath to</li><li>to adjure (solemnly implore)</li></ol>","xlit":"horkízō"},"G3049":{"lemma":"λογίζομαι","translit":"logízomai","kjv_def":"conclude, (ac-)count (of), + despise, esteem, impute, lay, number, reason, reckon, suppose, think (on)","strongs_def":" to take an inventory, i.e. estimate (literally or figuratively)","derivation":"middle voice from G3056 (λόγος);","pron":"log-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to reckon, count, compute, calculate, count over<ol type='a'><li>to take into account, to make an account of<ol><li>metaphorically to pass to one's account, to impute</li><li>a thing is reckoned as or to be something, i.e. as availing for or equivalent to something, as having the like force and weight</li></ol><li>to number among, reckon with</li><li>to reckon or account</li></ol><li>to reckon inward, count up or weigh the reasons, to deliberate</li><li>by reckoning up all the reasons, to gather or infer<ol type='a'><li>to consider, take into account, weigh, meditate on</li><li>to suppose, deem, judge</li><li>to determine, purpose, decide</li></ol></li></ol>","xlit":"logízomai"},"G4257":{"strongs_def":" to hear already,i.e. anticipate","derivation":"from G4253 (πρό) and G191 (ἀκούω);","translit":"proakoúō","lemma":"προακούω","kjv_def":"hear before","pron":"pro-ak-oo'-o","pos":"Verb","thayer":"<ol><li>to hear before<ol type='a'><li>the hoped for salvation before its realisation</li></ol></li></ol>","xlit":"proakoúō"},"G461":{"kjv_def":"lift (set) up, make straight","lemma":"ἀνορθόω","translit":"anorthóō","derivation":"from G303 (ἀνά) and a derivative of the base of G3717 (ὀρθός);","strongs_def":" to straighten up","pron":"an-orth-o'-o","pos":"Verb","thayer":"<ol><li>to set up, make erect<ol type='a'><li>of a deformed person</li></ol><li>to rear again, build anew</li></ol>","xlit":"anorthóō"},"G266":{"kjv_def":"offence, sin(-ful)","translit":"hamartía","lemma":"ἁμαρτία","derivation":"from G264 (ἁμαρτάνω);","strongs_def":" a sin (properly abstract)","pron":"ham-ar-tee'-ah","pos":"Noun Feminine","thayer":"<ol><li>equivalent to 264<ol type='a'><li>to be without a share in</li><li>to miss the mark</li><li>to err, be mistaken</li><li>to miss or wander from the path of uprightness and honour,to do or go wrong</li><li>to wander from the law of God, violate God's law, sin</li></ol><li>that which is done wrong, sin, an offence, a violation of the divine law in thought or in act</li><li>collectively, the complex or aggregate of sins committed either by a single person or by many</li></ol>","xlit":"hamartía"},"G4871":{"strongs_def":" to accumulate, i.e. convene","derivation":"from G4862 (σύν) and (to throng);","translit":"synalízō","lemma":"συναλίζω","kjv_def":"assemble together","pron":"soon-al-id'-zo","pos":"Verb","thayer":"<ol><li>to gather together, assemble</li><li>to be assembled, meet with</li></ol>","xlit":"synalízō"},"G4265":{"strongs_def":" to look out beforehand, i.e. furnish in advance","derivation":"from G4253 (πρό) and G991 (βλέπω);","lemma":"προβλέπω","translit":"problépō","kjv_def":"provide","pron":"prob-lep'-o","pos":"Verb","thayer":"<ol><li>to foresee</li><li>to provide</li></ol>","xlit":"problépō"},"G3364":{"derivation":"i.e. G3756 (οὐ) and G3361 (μή);","strongs_def":" a double negative strengthening the denial; not at all","kjv_def":"any more, at all, by any (no) means, neither, never, no (at all), in no case (wise), nor ever, not (at all, in any wise)","lemma":"οὐ μή","translit":"ou mḗ","pron":"oo may","thayer":"<ol><li>never, certainly not, not at all, by no means</li></ol>","xlit":"ou mḗ"},"G2966":{"kjv_def":"carcase","translit":"kōlon","lemma":"κῶλον","derivation":"from the base of G2849 (κολάζω);","strongs_def":" a limb of the body (as if lopped)","pron":"ko'-lon","pos":"Noun Neuter","thayer":"<ol><li>a member of a body, particularly the more external and prominent members especially the feet</li><li>a dead body, corpse, inasmuch as the members of a corpse are loose and fall apart</li></ol>","xlit":"kōlon"},"G2186":{"kjv_def":"--assault, come (in, to, unto, upon), be at hand (instant), present, stand (before, by, over)","translit":"ephístēmi","lemma":"ἐφίστημι","derivation":"from G1909 (ἐπί) and G2476 (ἵστημι);","strongs_def":" to stand upon, i.e. be present (in various applications, friendly or otherwise, usually literal); ","pron":"ef-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place at, place upon, place over<ol type='a'><li>to stand by, be present</li><li>to stand over one, place one's self above<ol><li>used especially of persons coming upon one suddenly<ol type='a'><li>an angel, of the advent of angels</li><li>of dreams</li></ol><li>of evils coming upon one</li></ol><li>to be at hand<ol><li>be ready</li></ol><li>of time<ol><li>to come upon<ol type='a'><li>of rain</li></ol></li></ol></li></ol></li></ol>","xlit":"ephístēmi"},"G116":{"translit":"Athēnai","lemma":"Ἀθῆναι","kjv_def":" Athens","strongs_def":" Athenæ, the capitol of Greece","derivation":"plural of (the goddess of wisdom, who was reputed to have founded the city);","pron":"ath-ay-nahee","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Athens = \"uncertainty\"</p><ol><li>A famous city in Greece, the capital of Attica, and the chief seat of learning and civilisation during the golden period of the history of Greece</li></ol>","xlit":"Athēnai"},"G5327":{"derivation":"properly, strengthened from the base of G4008 (πέραν) or rather of G4486 (ῥήγνυμι);","strongs_def":" a gap or chasm, i.e. ravine (winter-torrent)","kjv_def":"valley","lemma":"φάραγξ","translit":"pháranx","pron":"far'-anx","pos":"Noun Feminine","thayer":"<ol><li>a valley shut off by cliffs and precipices</li><li>a ravine</li></ol>","xlit":"pháranx"},"G4348":{"strongs_def":" a stub, i.e. (figuratively) occasion of apostasy","derivation":"from G4350 (προσκόπτω);","lemma":"πρόσκομμα","translit":"próskomma","kjv_def":"offence, stumbling(-block, (-stone))","pron":"pros'-kom-mah","pos":"Noun Neuter","thayer":"<ol><li>a stumbling block<ol type='a'><li>an obstacle in the way which if one strikes his foot against he stumbles or falls</li><li>that over which a soul stumbles, i.e. by which is caused to sin</li></ol></li></ol>","xlit":"próskomma"},"G667":{"translit":"apophérō","lemma":"ἀποφέρω","kjv_def":"bring, carry (away)","strongs_def":" to bear off (literally or relatively)","derivation":"from G575 (ἀπό) and G5342 (φέρω);","pron":"ap-of-er'-o","pos":"Verb","thayer":"<ol><li>to carry off or bring away</li></ol>","xlit":"apophérō"},"G3615":{"kjv_def":"they (them) of (his own) household","translit":"oikiakós","lemma":"οἰκιακός","derivation":"from G3614 (οἰκία);","strongs_def":" familiar, i.e. (as noun) relatives","pron":"oy-kee-ak-os'","pos":"Noun Masculine","thayer":"<ol><li>one belonging to the house</li><li>one under control of the master of a house, whether a son or a servant</li></ol>","xlit":"oikiakós"},"G2187":{"translit":"Ephraím","lemma":"Ἐφραίμ","kjv_def":"Ephraim","strongs_def":" Ephraim, a place in Palestine","derivation":"of Hebrew origin (H0669 or better H06085);","pron":"ef-rah-im'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Ephraim = \"double fruitfulness\"</p><ol><li>a city about a short day's journey from Jerusalem</li></ol>","xlit":"Ephraím"},"G546":{"kjv_def":"threaten","translit":"apeiléō","lemma":"ἀπειλέω","derivation":"of uncertain derivation;","strongs_def":" to menace; by implication, to forbid","pron":"ap-i-leh'-o","pos":"Verb","thayer":"<ol><li>to threaten, menace</li></ol>","xlit":"apeiléō"},"G1445":{"derivation":"from G1443 (Ἐβέρ);","strongs_def":" a Hebræan (i.e. Hebrew) or Jew","kjv_def":"Hebrew","lemma":"Ἑβραῖος","translit":"Hebraîos","pron":"heb-rah'-yos","pos":"Noun Masculine","thayer":"<ol><li>Hebrew<ol type='a'><li>any one of the Jewish or Israelitish nations</li></ol><li>in a narrower sense, those who live in Palestine and use the language of the country</li><li>all Jewish Christians, whether they spoke Aramaic or Greek</li></ol>","xlit":"Hebraîos"},"G268":{"derivation":"from G264 (ἁμαρτάνω);","strongs_def":" sinful, i.e. a sinner","kjv_def":"sinful, sinner","lemma":"ἁμαρτωλός","translit":"hamartōlós","pron":"ham-ar-to-los'","pos":"Adjective","thayer":"<ol><li>devoted to sin, a sinner<ol type='a'><li>not free from sin</li><li>pre-eminently sinful, especially wicked<ol><li>all wicked men</li><li>specifically of men stained with certain definite vices or crimes<ol type='a'><li>tax collectors, heathen</li></ol></li></ol></li></ol></li></ol>","xlit":"hamartōlós"},"G3612":{"kjv_def":"prison","translit":"oíkēma","lemma":"οἴκημα","derivation":"from G3611 (οἰκέω);","strongs_def":" a tenement, i.e. (specially), a jail","pron":"oy'-kay-mah","pos":"Noun Neuter","thayer":"<ol><li>a dwelling place, habitation</li><li>euphemistically a prison</li></ol>","xlit":"oíkēma"},"G3187":{"strongs_def":" larger (literally or figuratively, specially, in age)","derivation":"irregular comparative of G3173 (μέγας);","lemma":"μείζων","translit":"meízōn","kjv_def":"elder, greater(-est), more","pron":"mide'-zone","pos":"Adjective","thayer":"<ol><li>greater, larger, elder, stronger</li></ol>","xlit":"meízōn"},"G2712":{"strongs_def":" utterly idolatrous","derivation":"from G2596 (κατά) (intensively) and G1497 (εἴδωλον);","translit":"kateídōlos","lemma":"κατείδωλος","kjv_def":"wholly given to idolatry","pron":"kat-i'-do-los","pos":"Adjective","thayer":"<ol><li>full of idols</li></ol>","xlit":"kateídōlos"},"G642":{"lemma":"ἀπορφανίζω","translit":"aporphanízō","kjv_def":"take","strongs_def":" to bereave wholly, i.e. (figuratively) separate (from intercourse)","derivation":"from G575 (ἀπό) and a derivative of G3737 (ὀρφανός);","pron":"ap-or-fan-id'-zo","pos":"Verb","thayer":"<ol><li>to bereave of a parent or parents</li></ol>","xlit":"aporphanízō"},"G2534":{"strongs_def":" and at least (or even, indeed)","derivation":"from G2532 (καί) and G1065 (γέ);","translit":"kaíge","lemma":"καίγε","kjv_def":"and, at least","pron":"kah'-ee-gheh","pos":"Conjunction","thayer":"<ol><li>and at least, indeed</li></ol>","xlit":"kaíge"},"G5529":{"kjv_def":"Chuza","translit":"Chouzâs","lemma":"Χουζᾶς","derivation":"of uncertain origin;","strongs_def":" Chuzas, an officer of Herod","pron":"khood-zas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Chuza = \"the seer\"</p><ol><li>the house steward of Herod Antipas</li></ol>","xlit":"Chouzâs"},"G927":{"translit":"barýtimos","lemma":"βαρύτιμος","kjv_def":"very precious","strongs_def":" highly valuable","derivation":"from G926 (βαρύς) and G5092 (τιμή);","pron":"bar-oo'-tim-os","pos":"Adjective","thayer":"<ol><li>of weighty, great value, very precious, costly</li></ol>","xlit":"barýtimos"},"G3139":{"lemma":"μάρμαρος","translit":"mármaros","kjv_def":"marble","strongs_def":" marble (as sparkling white)","derivation":"from (to glisten);","pron":"mar'-mar-os","pos":"Noun Masculine","thayer":"<ol><li>a stone, a rock</li><li>marble</li></ol>","xlit":"mármaros"},"G2220":{"kjv_def":"leaven","lemma":"ζυμόω","translit":"zymóō","derivation":"from G2219 (ζύμη);","strongs_def":" to cause to ferment","pron":"dzoo-mo'-o","pos":"Verb","thayer":"<ol><li>to leaven</li><li>to mix leaven with dough so as to make it ferment</li></ol>","xlit":"zymóō"},"G5314":{"lemma":"φάγος","translit":"phágos","kjv_def":"gluttonous","strongs_def":" a glutton","derivation":"from G5315 (φάγω);","pron":"fag'-os","pos":"Noun Masculine","thayer":"<ol><li>a voracious man, a glutton</li></ol>","xlit":"phágos"},"G3732":{"strongs_def":" a birdling","derivation":"neuter of a presumed derivative of G3733 (ὄρνις);","lemma":"ὄρνεον","translit":"órneon","kjv_def":"bird, fowl","pron":"or'-neh-on","pos":"Noun Neuter","thayer":"<ol><li>a bird</li></ol>","xlit":"órneon"},"G2827":{"strongs_def":" to slant or slope, i.e. incline or recline (literally or figuratively)","derivation":"a primary verb;","translit":"klínō","lemma":"κλίνω","kjv_def":"bow (down), be far spent, lay, turn to flight, wear away","pron":"klee'-no","pos":"Verb","thayer":"<ol><li>transitively<ol type='a'><li>to incline, bow</li><li>to cause to fall back</li><li>to recline<ol><li>in a place for repose</li></ol></li></ol><li>intransitively<ol type='a'><li>to incline one's self<ol><li>of the declining of the day</li></ol></li></ol></li></ol>","xlit":"klínō"},"G4998":{"strongs_def":" safe (sound) in mind, i.e. self-controlled (moderate as to opinion or passion)","derivation":"from the base of G4982 (σώζω) and that of G5424 (φρήν);","translit":"sṓphrōn","lemma":"σώφρων","kjv_def":"discreet, sober, temperate","pron":"so'-frone","pos":"Adjective","thayer":"<ol><li>of a sound mind, sane, in one's senses</li><li>curbing one's desires and impulses, self-controlled, temperate</li></ol>","xlit":"sṓphrōn"},"G3607":{"derivation":"of uncertain affinity;","strongs_def":" a linen cloth, i.e. (especially) a sail","kjv_def":"sheet","lemma":"ὀθόνη","translit":"othónē","pron":"oth-on'-ay","pos":"Noun Feminine","thayer":"<ol><li>linen (i.e. fine white linen for women's clothing)</li><li>linen clothes (sheet or sail)</li></ol>","xlit":"othónē"},"G3786":{"kjv_def":"advantageth, profit","lemma":"ὄφελος","translit":"óphelos","derivation":"from (to heap up, i.e. accumulate or benefit);","strongs_def":" gain","pron":"of'-el-os","pos":"Noun Neuter","thayer":"<ol><li>advantage, profit</li></ol>","xlit":"óphelos"},"G36":{"lemma":"ἀγενής","translit":"agenḗs","kjv_def":"base things","strongs_def":" properly, without kin, i.e. (of unknown descent, and by implication) ignoble","derivation":"from G1 (Α) (as negative particle) and G1085 (γένος);","pron":"ag-en-ace'","pos":"Adjective","thayer":"<ol><li>ignoble, coward, mean, base, of no family, that is: low born</li></ol>","xlit":"agenḗs"},"G4683":{"kjv_def":"wrap in swaddling clothes","translit":"sparganóō","lemma":"σπαργανόω","derivation":"from (a strip;","strongs_def":" from a derivative of the base of G4682 (σπαράσσω) meaning to strap or wrap with strips); to swathe (an infant after the Oriental custom)","pron":"spar-gan-o'-o","pos":"Verb","thayer":"<ol><li>to wrap in swaddling clothes<ol type='a'><li>of an infant just born</li></ol></li></ol>","xlit":"sparganóō"},"G1181":{"strongs_def":" a tenth, i.e. as a percentage or (technically) tithe","derivation":"feminine of G1182 (δέκατος);","lemma":"δεκάτη","translit":"dekátē","kjv_def":"tenth (part), tithe","pron":"dek-at'-ay","pos":"Adjective","thayer":"<ol><li>a tenth part of anything, a tithe<ol type='a'><li>the tenth party of booty taken from an enemy</li><li>the tithes of fruits of the earth and of flocks, which by the law of Moses were presented to the Levites in the congregation of Israel</li></ol></li></ol>","xlit":"dekátē"},"G1515":{"derivation":"probably from a primary verb (to join);","strongs_def":" peace (literally or figuratively); by implication, prosperity","kjv_def":"one, peace, quietness, rest, + set at one again","translit":"eirḗnē","lemma":"εἰρήνη","pron":"i-ray'-nay","pos":"Noun Feminine","thayer":"<ol><li>a state of national tranquillity<ol type='a'><li>exemption from the rage and havoc of war</li></ol><li>peace between individuals, i.e. harmony, concord</li><li>security, safety, prosperity, felicity, (because peace and harmony make and keep things safe and prosperous)</li><li>of the Messiah's peace<ol type='a'><li>the way that leads to peace (salvation)</li></ol><li>of Christianity, the tranquil state of a soul assured of its salvation through Christ, and so fearing nothing from God and content with its earthly lot, of whatsoever sort that is</li><li>the blessed state of devout and upright men after death</li></ol>","xlit":"eirḗnē"},"G2295":{"translit":"thaûma","lemma":"θαῦμα","kjv_def":"admiration","strongs_def":" wonder (properly concrete; but by implication, abstract)","derivation":"apparently from a form of G2300 (θεάομαι);","pron":"thos'-mah","pos":"Noun Neuter","thayer":"<ol><li>a wonderful thing, a marvel</li><li>wonder<ol type='a'><li>to wonder [with great wonder i.e.] exceedingly</li></ol></li></ol>","xlit":"thaûma"},"G3086":{"strongs_def":" a redeemer (figuratively)","derivation":"from G3084 (λυτρόω);","lemma":"λυτρωτής","translit":"lytrōtḗs","kjv_def":"deliverer","pron":"loo-tro-tace'","pos":"Noun Masculine","thayer":"<ol><li>redeemer</li><li>deliverer, liberator</li></ol>","xlit":"lytrōtḗs"},"G988":{"strongs_def":" vilification (especially against God)","derivation":"from G989 (βλάσφημος);","translit":"blasphēmía","lemma":"βλασφημία","kjv_def":"blasphemy, evil speaking, railing","pron":"blas-fay-me'-ah","pos":"Noun Feminine","thayer":"<ol><li>slander, detraction, speech injurious, to another's good name</li><li>impious and reproachful speech injurious to divine majesty</li></ol>","xlit":"blasphēmía"},"G3904":{"translit":"paraskeuḗ","lemma":"παρασκευή","kjv_def":"preparation","strongs_def":" readiness","derivation":"as if from G3903 (παρασκευάζω);","pron":"par-ask-yoo-ay'","pos":"Noun Feminine","thayer":"<ol><li>a making ready, preparation, equipping</li><li>that which is prepared, equipment</li><li>in the NT in a Jewish sense, the day of preparation<ol type='a'><li>the day on which the Jews made necessary preparation to celebrate a sabbath or a feast</li></ol></li></ol>","xlit":"paraskeuḗ"},"G425":{"translit":"ánesis","lemma":"ἄνεσις","kjv_def":"eased, liberty, rest","strongs_def":" relaxation or (figuratively) relief","derivation":"from G447 (ἀνίημι);","pron":"an'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a loosening, relaxing<ol type='a'><li>spoken of a more tolerable condition in captivity, to be held in less vigorous confinement</li><li>relief, rest, from persecutions</li></ol></li></ol>","xlit":"ánesis"},"G407":{"strongs_def":" to act manly","derivation":"middle voice from G435 (ἀνήρ);","lemma":"ἀνδρίζομαι","translit":"andrízomai","kjv_def":"quit like men","pron":"an-drid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to make a man of or make brave</li><li>to show one's self a man, be brave</li></ol>","xlit":"andrízomai"},"G4650":{"strongs_def":" to dissipate, i.e. (figuratively) put to flight, waste, be liberal","derivation":"apparently from the same as G4651 (σκορπίος) (through the idea of penetrating);","translit":"skorpízō","lemma":"σκορπίζω","kjv_def":"disperse abroad, scatter (abroad)","pron":"skor-pid'-zo","pos":"Verb","thayer":"<ol><li>to scatter<ol type='a'><li>of those who, routed or terror stricken or driven by some other impulses, fly in every direction</li><li>to scatter abroad (what others may collect for themselves), or one dispensing blessings literally</li></ol></li></ol>","xlit":"skorpízō"},"G999":{"derivation":"akin to G900 (βαθύνω);","strongs_def":" a hole (in the ground); specially, a cistern","kjv_def":"ditch, pit","translit":"bóthynos","lemma":"βόθυνος","pron":"both'-oo-nos","pos":"Noun Masculine","thayer":"<ol><li>a pit, ditch</li></ol>","xlit":"bóthynos"},"G2794":{"kjv_def":"peril","translit":"kíndynos","lemma":"κίνδυνος","derivation":"of uncertain derivation;","strongs_def":" danger","pron":"kin'-doo-nos","pos":"Noun Masculine","thayer":"<ol><li>a danger, a peril</li></ol>","xlit":"kíndynos"},"G337":{"lemma":"ἀναιρέω","translit":"anairéō","kjv_def":"put to death, kill, slay, take away, take up","strongs_def":" to take up, i.e. adopt; by implication, to take away (violently), i.e. abolish, murder","derivation":"from G303 (ἀνά) and (the active of) G138 (αἱρέομαι);","pron":"an-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to take up, to lift up (from the ground)<ol type='a'><li>to take up for myself as mine</li><li>to own (an exposed infant)</li></ol><li>to take away, abolish<ol type='a'><li>to do away with or abrogate customs or ordinances</li><li>to put out of the way, kill slay a man</li></ol></li></ol>","xlit":"anairéō"},"G2049":{"translit":"erēmóō","lemma":"ἐρημόω","kjv_def":"(bring to, make) desolate(-ion), come to nought","strongs_def":" to lay waste (literally or figuratively)","derivation":"from G2048 (ἔρημος);","pron":"er-ay-mo'-o","pos":"Verb","thayer":"<ol><li>to make desolate, lay waste</li><li>to ruin, bring to desolation</li><li>to despoil one, strip her of her treasures</li></ol>","xlit":"erēmóō"},"G4618":{"strongs_def":" grain-fed, i.e. fattened","derivation":"from a derivative of G4621 (σῖτος);","lemma":"σιτευτός","translit":"siteutós","kjv_def":"fatted","pron":"sit-yoo-ros'","pos":"Adjective","thayer":"<ol><li>fattened, fatted</li></ol>","xlit":"siteutós"},"G2366":{"kjv_def":"tempest","lemma":"θύελλα","translit":"thýella","derivation":"from G2380 (θύω) (in the sense of blowing) a storm","pron":"thoo'-el-lah","pos":"Noun Feminine","thayer":"<ol><li>a sudden storm, tempest, whirlwind</li></ol>","xlit":"thýella"},"G95":{"kjv_def":"wrongfully","translit":"adíkōs","lemma":"ἀδίκως","derivation":"adverb from G94 (ἄδικος);","strongs_def":" unjustly","pron":"ad-ee'-koce","pos":"Adverb","thayer":"<ol><li>unjustly, undeserved, without fault</li></ol>","xlit":"adíkōs"},"G2121":{"lemma":"εὔκαιρος","translit":"eúkairos","kjv_def":"convenient, in time of need","strongs_def":" well-timed, i.e. opportune","derivation":"from G2095 (εὖ) and G2540 (καιρός);","pron":"yoo'-kahee-ros","pos":"Adjective","thayer":"<ol><li>seasonable, timely, opportune</li></ol>","xlit":"eúkairos"},"G2950":{"strongs_def":" a \"cymbal\" (as hollow)","derivation":"from a derivative of the base of G2949 (κῦμα);","translit":"kýmbalon","lemma":"κύμβαλον","kjv_def":"cymbal","pron":"koom'-bal-on","pos":"Noun Neuter","thayer":"<ol><li>a cymbal, i.e. a hollow basin of brass, producing when struck together a musical sound</li></ol>","xlit":"kýmbalon"},"G2739":{"derivation":"from G2738 (καῦμα);","strongs_def":" to burn","kjv_def":"scorch","lemma":"καυματίζω","translit":"kaumatízō","pron":"kow-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to burn with heat, to scorch</li><li>to be tortured with intense heat</li></ol>","xlit":"kaumatízō"},"G2798":{"lemma":"κλάδος","translit":"kládos","kjv_def":"branch","strongs_def":" a twig or bough (as if broken off)","derivation":"from G2806 (κλάω);","pron":"klad'-os","pos":"Noun Masculine","thayer":"<ol><li>a young tender shoot, broken off for grafting</li><li>a branch<ol type='a'><li>as the Jewish patriarchs are likened to a root, so their posterity are likened to branches</li></ol></li></ol>","xlit":"kládos"},"G330":{"strongs_def":" to revive","derivation":"from G303 (ἀνά) and (to flourish);","translit":"anathállō","lemma":"ἀναθάλλω","kjv_def":"flourish again","pron":"an-ath-al'-lo","pos":"Verb","thayer":"<ol><li>to shoot up, sprout again, grow green again, flourish again</li></ol>","xlit":"anathállō"},"G3917":{"derivation":"feminine of (a panther);","strongs_def":" a leopard","kjv_def":"leopard","lemma":"πάρδαλις","translit":"párdalis","pron":"par'-dal-is","pos":"Noun Feminine","thayer":"<ol><li>a pard, panther, leopard</li><li>a very fierce Asiatic and African animal, having a tawny skin marked with large black spots</li></ol>","xlit":"párdalis"},"G5258":{"kjv_def":"sleep","lemma":"ὕπνος","translit":"hýpnos","derivation":"from an obsolete primary (perhaps akin to G5259 (ὑπό) through the idea of subsilience);","strongs_def":" sleep, i.e. (figuratively) spiritual torpor","pron":"hoop'-nos","pos":"Noun Masculine","thayer":"<ol><li>sleep</li></ol>","xlit":"hýpnos"},"G4353":{"strongs_def":" an adorer","derivation":"from G4352 (προσκυνέω);","translit":"proskynētḗs","lemma":"προσκυνητής","kjv_def":"worshipper","pron":"pros-koo-nay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a worshipper</li></ol>","xlit":"proskynētḗs"},"G3647":{"translit":"holoklēría","lemma":"ὁλοκληρία","kjv_def":"perfect soundness","strongs_def":" integrity, i.e. physical wholeness","derivation":"from G3648 (ὁλόκληρος);","pron":"hol-ok-lay-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>of an unimpaired condition of the body, in which all its members are healthy and fit for use<ol type='a'><li>good health</li></ol></li></ol>","xlit":"holoklēría"},"G5416":{"derivation":"neuter of a derivative from the base of G5417 (φραγελλόω);","strongs_def":" a whip, i.e. Roman lash as a public punishment","kjv_def":"scourge","lemma":"φραγέλλιον","translit":"phragéllion","pron":"frag-el'-le-on","pos":"Noun Neuter","thayer":"<ol><li>a scourge or whip</li></ol>","xlit":"phragéllion"},"G1894":{"derivation":"from G1893 (ἐπεί) and G1211 (δή);","strongs_def":" since now, i.e. (of time) when, or (of cause) whereas","kjv_def":"after that, because, for (that, -asmuch as), seeing, since","translit":"epeidḗ","lemma":"ἐπειδή","pron":"ep-i-day'","pos":"Conjunction","thayer":"<ol><li>when now, since now<ol type='a'><li>of time: when now, after that</li><li>of cause: since, seeing that, forasmuch as</li></ol></li></ol>","xlit":"epeidḗ"},"G1576":{"kjv_def":"exclude","lemma":"ἐκκλείω","translit":"ekkleíō","derivation":"from G1537 (ἐκ) and G2808 (κλείω);","strongs_def":" to shut out (literally or figuratively)","pron":"ek-kli'-o","pos":"Verb","thayer":"<ol><li>to shut out, to turn out of doors</li><li>to prevent the approach of one</li></ol>","xlit":"ekkleíō"},"G900":{"lemma":"βαθύνω","translit":"bathýnō","kjv_def":"deep","strongs_def":" to deepen","derivation":"from G901 (βαθύς);","pron":"bath-oo'-no","pos":"Verb","thayer":"<ol><li>'the deep' sea (the 'high seas')</li><li>deep, extreme poverty, the deep things of God, things hidden and above man's scrutiny, especially divine counsels</li><li>to make deep</li></ol>","xlit":"bathýnō"},"G5222":{"derivation":"from G5221 (ὑπαντάω);","strongs_def":" an encounter or concurrence (with G1519 (εἰς) for infinitive, in order to fall in with)","kjv_def":"meeting","translit":"hypántēsis","lemma":"ὑπάντησις","pron":"hoop-an'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>to go to meet</li></ol>","xlit":"hypántēsis"},"G4838":{"strongs_def":" to take along in company","derivation":"from G4862 (σύν) and G3880 (παραλαμβάνω);","translit":"symparalambánō","lemma":"συμπαραλαμβάνω","kjv_def":"take with","pron":"soom-par-al-am-ban'-o","pos":"Verb","thayer":"<ol><li>to take along together with</li><li>in the NT to take with one as a companion</li></ol>","xlit":"symparalambánō"},"G1101":{"derivation":"from G1100 (γλῶσσα) and the base of G2889 (κόσμος);","strongs_def":" properly, a case (to keep mouthpieces of wind-instruments in) i.e. (by extension) a casket or (specially) purse","kjv_def":"bag","lemma":"γλωσσόκομον","translit":"glōssókomon","pron":"gloce-sok'-om-on","pos":"Noun Neuter","thayer":"<ol><li>a case in which to keep mouth-pieces of wind instruments</li><li>a small box for other uses<ol type='a'><li>especially a casket, a purse to keep money in</li></ol></li></ol>","xlit":"glōssókomon"},"G1442":{"derivation":"ordinal from G2033 (ἑπτά);","strongs_def":" seventh","kjv_def":"seventh","translit":"hébdomos","lemma":"ἕβδομος","pron":"heb'-dom-os","pos":"Adjective","thayer":"<ol><li>seventh</li></ol>","xlit":"hébdomos"},"G4828":{"derivation":"from G4862 (σύν) and G3140 (μαρτυρέω);","strongs_def":" to testify jointly, i.e. corroborate by (concurrent) evidence","kjv_def":"testify unto, (also) bear witness (with)","translit":"symmartyréō","lemma":"συμμαρτυρέω","pron":"soom-mar-too-reh'-o","pos":"Verb","thayer":"<ol><li>to bear witness with, bear joint witness</li></ol>","xlit":"symmartyréō"},"G3515":{"strongs_def":" to act as a babe, i.e. (figuratively) innocently","derivation":"from G3516 (νήπιος);","lemma":"νηπιάζω","translit":"nēpiázō","kjv_def":"be a child","pron":"nay-pee-ad'-zo","pos":"Verb","thayer":"<ol><li>to be a babe (infant)</li></ol>","xlit":"nēpiázō"},"G2659":{"kjv_def":"slumber","lemma":"κατάνυξις","translit":"katányxis","derivation":"from G2660 (κατανύσσω);","strongs_def":" a prickling (sensation, as of the limbs asleep), i.e. (by implication, (perhaps by some confusion with G3506 (νεύω) or even with G3571 (νύξ))) stupor (lethargy)","pron":"kat-an'-oox-is","pos":"Noun Feminine","thayer":"<ol><li>a pricking, piercing</li><li>severe sorrow, extreme grief</li><li>insensibility or torpor of mind, such as extreme grief easily produces<ol type='a'><li>hence a \"spirit of stupor\" , which renders their souls torpid so insensible that they are not affected at all by the offer made them of salvation through the Messiah</li></ol></li></ol>","xlit":"katányxis"},"G4456":{"kjv_def":" blind, harden","lemma":"πωρόω","translit":"pōróō","derivation":"apparently from (a kind of stone);","strongs_def":" to petrify, i.e. (figuratively) to indurate (render stupid or callous)","pron":"po-ro'-o","pos":"Verb","thayer":"<ol><li>to cover with a thick skin, to harden by covering with a callus</li><li>metaphorically<ol type='a'><li>to make the heart dull</li><li>to grow hard, callous, become dull, lose the power of understanding</li></ol></li></ol>","xlit":"pōróō"},"G2813":{"translit":"kléptō","lemma":"κλέπτω","kjv_def":"steal","strongs_def":" to filch","derivation":"a primary verb;","pron":"klep'-to","pos":"Verb","thayer":"<ol><li>to steal<ol type='a'><li>to commit a theft</li><li>take away by theft i.e take away by stealth</li></ol></li></ol>","xlit":"kléptō"},"G4781":{"translit":"synkámptō","lemma":"συγκάμπτω","kjv_def":"bow down","strongs_def":" to bend together, i.e. (figuratively) to afflict","derivation":"from G4862 (σύν) and G2578 (κάμπτω);","pron":"soong-kamp'-to","pos":"Verb","thayer":"<ol><li>to bend together, to bend completely</li><li>metaphorically to subject one to error and hardness of heart, a figure taken from bowing the back by captives compelled to pass under the yoke</li></ol>","xlit":"synkámptō"},"G2653":{"lemma":"καταναθεματίζω","translit":"katanathematízō","kjv_def":"curse","strongs_def":" to imprecate","derivation":"from G2596 (κατά) (intensive) and G332 (ἀναθεματίζω);","pron":"kat-an-ath-em-at-id'-zo","pos":"Verb","thayer":"<ol><li>to curse</li></ol>","xlit":"katanathematízō"},"G4006":{"derivation":"from the perfect of the alternate of G3958 (πάσχω);","strongs_def":" reliance","kjv_def":"confidence, trust","translit":"pepoíthēsis","lemma":"πεποίθησις","pron":"pep-oy'-thay-sis","pos":"Noun Feminine","thayer":"<ol><li>trust, confidence, reliance</li></ol>","xlit":"pepoíthēsis"},"G904":{"derivation":"of Hebrew origin (H01111);","strongs_def":" Balak, a Moabite","kjv_def":"Balac","translit":"Balák","lemma":"Βαλάκ","pron":"bal-ak'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Balak = \"a devastator or spoiler\"</p><ol><li>a king of Moab</li></ol>","xlit":"Balák"},"G2576":{"translit":"kammýō","lemma":"καμμύω","kjv_def":"close","strongs_def":" to shut down, i.e. close the eyes","derivation":"from a compound of G2596 (κατά) and the base of G3466 (μυστήριον);","pron":"kam-moo'-o","pos":"Verb","thayer":"<ol><li>to shut the eyes, close the eyes</li></ol>","xlit":"kammýō"},"G4830":{"translit":"symmétochos","lemma":"συμμέτοχος","kjv_def":"partaker","strongs_def":" a co-participant","derivation":"from G4862 (σύν) and G3353 (μέτοχος);","pron":"soom-met'-okh-os","pos":"Adjective","thayer":"<ol><li>partaking together with one, a joint partaker<ol type='a'><li>of something</li></ol></li></ol>","xlit":"symmétochos"},"G1114":{"strongs_def":" properly, a wizard (as muttering spells), i.e. (by implication) an imposter","derivation":"from (to wail);","translit":"góēs","lemma":"γόης","kjv_def":"seducer","pron":"go'-ace","pos":"Noun Masculine","thayer":"<ol><li>a wailer, a howler</li><li>a juggler, enchanter (because incantations used to be uttered in a kind of howl)</li><li>a deceiver, imposter</li></ol>","xlit":"góēs"},"G4923":{"kjv_def":"company","lemma":"συνοδία","translit":"synodía","derivation":"from a compound of G4862 (σύν) and G3598 (ὁδός) (\"synod\");","strongs_def":" companionship on a journey, i.e. (by implication), a caravan","pron":"soon-od-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a journey in company<ol type='a'><li>of a company of travellers, associates on a journey, a caravan</li></ol></li></ol>","xlit":"synodía"},"G3822":{"derivation":"from G3820 (παλαιός);","strongs_def":" to make (passively, become) worn out, or declare obsolete","kjv_def":"decay, make (wax) old","lemma":"παλαιόω","translit":"palaióō","pron":"pal-ah-yo'-o","pos":"Verb","thayer":"<ol><li>to make ancient or old<ol type='a'><li>to become old, to be worn out</li><li>of things worn out by time and use</li></ol><li>to declare a thing to be old and so about to be abrogated</li></ol>","xlit":"palaióō"},"G1598":{"lemma":"ἐκπειράζω","translit":"ekpeirázō","kjv_def":"tempt","strongs_def":" to test thoroughly","derivation":"from G1537 (ἐκ) and G3985 (πειράζω);","pron":"ek-pi-rad'-zo","pos":"Verb","thayer":"<ol><li>to prove, test, thoroughly</li><li>to put to proof God's character and power</li></ol>","xlit":"ekpeirázō"},"G3420":{"strongs_def":" memory","derivation":"from G3403 (μιμνήσκω);","translit":"mnḗmē","lemma":"μνήμη","kjv_def":"remembrance","pron":"mnay'-may","pos":"Noun Feminine","thayer":"<ol><li>memory, remembrance</li><li>mention: to remember a thing, call to remembrance</li></ol>","xlit":"mnḗmē"},"G4388":{"strongs_def":" to place before, i.e. (for oneself) to exhibit; (to oneself) to propose (determine)","derivation":"middle voice from G4253 (πρό) and G5087 (τίθημι);","lemma":"προτίθεμαι","translit":"protíthemai","kjv_def":"purpose, set forth","pron":"prot-ith'-em-ahee","pos":"Verb","thayer":"<ol><li>to place before, to set forth<ol type='a'><li>to set forth to be looked at, expose to view</li><li>to expose to public view<ol><li>of the bodies of the dead</li><li>to let lie in state</li></ol></li></ol><li>to set before one's self, propose to one's self<ol type='a'><li>to purpose, determine</li></ol></li></ol>","xlit":"protíthemai"},"G3466":{"kjv_def":"mystery","lemma":"μυστήριον","translit":"mystḗrion","derivation":"from a derivative of (to shut the mouth);","strongs_def":" a secret or \"mystery\" (through the idea of silence imposed by initiation into religious rites)","pron":"moos-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>hidden thing, secret, mystery<ol type='a'><li>generally mysteries, religious secrets, confided only to the initiated and not to ordinary mortals</li><li>a hidden or secret thing, not obvious to the understanding</li><li>a hidden purpose or counsel<ol><li>secret will<ol type='a'><li>of men</li><li>of God: the secret counsels which govern God in dealing with the righteous, which are hidden from ungodly and wicked men but plain to the godly</li></ol></li></ol></li></ol><li>in rabbinic writings, it denotes the mystic or hidden sense<ol type='a'><li>of an OT saying</li><li>of an image or form seen in a vision</li><li>of a dream</li></ol></li></ol>","xlit":"mystḗrion"},"G4000":{"strongs_def":" five times a thousand","derivation":"from G3999 (πεντάκις) and G5507 (χίλιοι);","translit":"pentakischílioi","lemma":"πεντακισχίλιοι","kjv_def":"five thousand","pron":"pen-tak-is-khil'-ee-oy","pos":"Adjective","thayer":"<ol><li>five thousand</li></ol>","xlit":"pentakischílioi"},"G2877":{"derivation":"neuter of a presumed derivative of (a maiden);","strongs_def":" a (little) girl","kjv_def":"damsel, maid","translit":"korásion","lemma":"κοράσιον","pron":"kor-as'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a girl, damsel, maiden</li></ol>","xlit":"korásion"},"G5311":{"translit":"hýpsos","lemma":"ὕψος","kjv_def":"be exalted, height, (on) high","strongs_def":" elevation, i.e. (abstractly) altitude, (specially), the sky, or (figuratively) dignity","derivation":"from a derivative of G5228 (ὑπέρ);","pron":"hoop'-sos","pos":"Noun Neuter","thayer":"<ol><li>height<ol type='a'><li>of measurement</li><li>of place, heaven</li><li>metaphorically rank, high station</li></ol></li></ol>","xlit":"hýpsos"},"G3152":{"translit":"mátaios","lemma":"μάταιος","kjv_def":"vain, vanity","strongs_def":" empty, i.e. (literally) profitless, or (specially), an idol","derivation":"from the base of G3155 (μάτην);","pron":"mat'-ah-yos","pos":"Adjective","thayer":"<ol><li>devoid of force, truth, success, result</li><li>useless, of no purpose</li></ol>","xlit":"mátaios"},"G3850":{"lemma":"παραβολή","translit":"parabolḗ","kjv_def":"comparison, figure, parable, proverb","strongs_def":" a similitude (\"parable\"), i.e. (symbolic) fictitious narrative (of common life conveying a moral), apothegm or adage","derivation":"from G3846 (παραβάλλω);","pron":"par-ab-ol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a placing of one thing by the side of another, juxtaposition, as of ships in battle</li><li>metaphorically<ol type='a'><li>a comparing, comparison of one thing with another, likeness, similitude</li><li>an example by which a doctrine or precept is illustrated</li><li>a narrative, fictitious but agreeable to the laws and usages of human life, by which either the duties of men or the things of God, particularly the nature and history of God's kingdom are figuratively portrayed</li><li>a parable: an earthly story with a heavenly meaning</li></ol><li>a pithy and instructive saying, involving some likeness or comparison and having preceptive or admonitory force<ol type='a'><li>an aphorism, a maxim</li></ol><li>a proverb</li><li>an act by which one exposes himself or his possessions to danger, a venture, a risk</li></ol>","xlit":"parabolḗ"},"G3556":{"kjv_def":"chicken","lemma":"νοσσίον","translit":"nossíon","derivation":"diminutive of G3502 (νεοσσός);","strongs_def":" a birdling","pron":"nos-see'-on","pos":"Noun Neuter","thayer":"<ol><li>a brood of birds</li></ol>","xlit":"nossíon"},"G2126":{"strongs_def":" taking well (carefully), i.e. circumspect (religiously, pious)","derivation":"from G2095 (εὖ) and G2983 (λαμβάνω);","lemma":"εὐλαβής","translit":"eulabḗs","kjv_def":"devout","pron":"yoo-lab-ace'","pos":"Adjective","thayer":"<ol><li>taking hold well<ol type='a'><li>carefully and surely</li><li>cautiously</li></ol><li>reverencing God, pious, religious</li></ol>","xlit":"eulabḗs"},"G1401":{"kjv_def":"bond(-man), servant","translit":"doûlos","lemma":"δοῦλος","derivation":"from G1210 (δέω);","strongs_def":" a slave (literal or figurative, involuntary or voluntary; frequently, therefore in a qualified sense of subjection or subserviency)","pron":"doo'-los","pos":"Noun","thayer":"<ol><li>a slave, bondman, man of servile condition<ol type='a'><li>a slave</li><li>metaphorically, one who gives himself up to another's will those whose service is used by Christ in extending and advancing his cause among men</li><li>devoted to another to the disregard of one's own interests</li></ol><li>a servant, attendant</li></ol>","xlit":"doûlos"},"G2852":{"derivation":"from a derivative of the base of G2849 (κολάζω);","strongs_def":" to rap with the fist","kjv_def":"buffet","lemma":"κολαφίζω","translit":"kolaphízō","pron":"kol-af-id'-zo","pos":"Verb","thayer":"<ol><li>to strike with the fist, give one a blow with the fist</li><li>to maltreat, treat with violence and contumely</li></ol>","xlit":"kolaphízō"},"G4081":{"strongs_def":" clay","derivation":"perhaps a primary word;","lemma":"πηλός","translit":"pēlós","kjv_def":"clay","pron":"pay-los'","pos":"Noun Masculine","thayer":"<ol><li>clay, which potters uses</li><li>mud (wet clay)</li></ol>","xlit":"pēlós"},"G3549":{"translit":"nomothetéō","lemma":"νομοθετέω","kjv_def":"establish, receive the law","strongs_def":" to legislate, i.e. (passively) to have (the Mosaic) enactments injoined, be sanctioned (by them)","derivation":"from G3550 (νομοθέτης);","pron":"nom-oth-et-eh'-o","pos":"Verb","thayer":"<ol><li>to enact laws<ol type='a'><li>laws are enacted or prescribed for one, to be legislated for, furnished with laws</li></ol><li>to sanction by law, enact</li></ol>","xlit":"nomothetéō"},"G5580":{"strongs_def":" a spurious Messiah","derivation":"from G5571 (ψευδής) and G5547 (Χριστός);","translit":"pseudóchristos","lemma":"ψευδόχριστος","kjv_def":"false Christ","pron":"psyoo-dokh'-ris-tos","pos":"Noun Masculine","thayer":"<ol><li>a false Christ (or Messiah)</li><li>one who falsely lays claim to the name and office of the Messiah</li></ol>","xlit":"pseudóchristos"},"G965":{"strongs_def":" Bethleem (i.e. Beth-lechem), a place in Palestine","derivation":"of Hebrew origin (H01036);","translit":"Bēthleém","lemma":"Βηθλεέμ","kjv_def":"Bethlehem","pron":"bayth-leh-em'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethlehem = \"house of bread\"</p><ol><li>a village about six miles (10 km) south of Jerusalem</li></ol>","xlit":"Bēthleém"},"G860":{"strongs_def":" probably a ligament (as fastening)","derivation":"from G680 (ἅπτομαι);","translit":"haphḗ","lemma":"ἁφή","kjv_def":"joint","pron":"haf-ay'","pos":"Noun Feminine","thayer":"<ol><li>bond, connection</li></ol>","xlit":"haphḗ"},"G5577":{"strongs_def":" untrue testimony","derivation":"from G5575 (ψευδομάρτυρ);","lemma":"ψευδομαρτυρία","translit":"pseudomartyría","kjv_def":"false witness","pron":"psyoo-dom-ar-too-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>false witness, false testimony</li></ol>","xlit":"pseudomartyría"},"G1780":{"translit":"entaphiasmós","lemma":"ἐνταφιασμός","kjv_def":"burying","strongs_def":" preparation for interment","derivation":"from G1779 (ἐνταφιάζω);","pron":"en-taf-ee-as-mos'","pos":"Noun Masculine","thayer":"<ol><li>preparation of a body for burial</li></ol>","xlit":"entaphiasmós"},"G142":{"kjv_def":"away with, bear (up), carry, lift up, loose, make to doubt, put away, remove, take (away, up)","lemma":"αἴρω","translit":"aírō","derivation":"a primary root;","strongs_def":" to lift up; by implication, to take up or away; figuratively, to raise (the voice), keep in suspense (the mind), specially, to sail away (i.e. weigh anchor); by Hebraism (compare H05375) to expiate sin","pron":"ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to raise up, elevate, lift up<ol type='a'><li>to raise from the ground, take up: stones</li><li>to raise upwards, elevate, lift up: the hand</li><li>to draw up: a fish</li></ol><li>to take upon one's self and carry what has been raised up, to bear</li><li>to bear away what has been raised, carry off<ol type='a'><li>to move from its place</li><li>to take off or away what is attached to anything</li><li>to remove</li><li>to carry off, carry away with one</li><li>to appropriate what is taken</li><li>to take away from another what is his or what is committed to him, to take by force</li><li>to take and apply to any use</li><li>to take from among the living, either by a natural death, or by violence</li><li>cause to cease</li></ol></li></ol>","xlit":"aírō"},"G4101":{"translit":"pistikós","lemma":"πιστικός","kjv_def":"spike-(nard)","strongs_def":" trustworthy, i.e. genuine (unadulterated)","derivation":"from G4102 (πίστις);","pron":"pis-tik-os'","pos":"Adjective","thayer":"<ol><li>pertaining to belief<ol type='a'><li>having the power of persuading, skilful in producing belief</li><li>trusty, faithful, that can be relied on</li></ol></li></ol>","xlit":"pistikós"},"G4066":{"kjv_def":"country (round) about, region (that lieth) round about","lemma":"περίχωρος","translit":"períchōros","derivation":"from G4012 (περί) and G5561 (χώρα);","strongs_def":" around the region, i.e. circumjacent (as noun, with G1093 (γῆ) implied vicinity)","pron":"per-ikh'-o-ros","pos":"Adjective","thayer":"<ol><li>lying round about, neighbouring<ol type='a'><li>the region round about</li><li>the region of Jordan</li></ol></li></ol>","xlit":"períchōros"},"G2731":{"kjv_def":"dwelling","lemma":"κατοίκησις","translit":"katoíkēsis","derivation":"from G2730 (κατοικέω);","strongs_def":" residence (properly, the act; but by implication, concretely, the mansion)","pron":"kat-oy'-kay-sis","pos":"Noun Feminine","thayer":"<ol><li>dwelling, abode</li></ol>","xlit":"katoíkēsis"},"G2292":{"derivation":"another form for G2293 (θαρσέω);","strongs_def":" to exercise courage","kjv_def":"be bold, X boldly, have confidence, be confident","translit":"tharrhéō","lemma":"θαῤῥέω","pron":"thar-hreh'-o","pos":"Verb","thayer":"<ol><li>to be of good courage, be of good cheer</li><li>to be bold</li></ol>","xlit":"tharrhéō"},"G5522":{"kjv_def":"dust","lemma":"χόος","translit":"chóos","derivation":"from the base of G5494 (χειμών);","strongs_def":" a heap (as poured out), i.e. rubbish; loose dirt","pron":"kho'-os","pos":"Noun Masculine","thayer":"<ol><li>earth dug out, an earth heap</li><li>dust</li></ol>","xlit":"chóos"},"G5262":{"translit":"hypódeigma","lemma":"ὑπόδειγμα","kjv_def":"en-(ex-)ample, pattern","strongs_def":" an exhibit for imitation or warning (figuratively, specimen, adumbration)","derivation":"from G5263 (ὑποδείκνυμι);","pron":"hoop-od'-igue-mah","pos":"Noun Neuter","thayer":"<ol><li>a sign suggestive of anything, delineation of a thing, representation, figure, copy</li><li>an example: for imitation<ol type='a'><li>of the thing to be imitated</li><li>for a warning, of a thing to be shunned</li></ol></li></ol>","xlit":"hypódeigma"},"G465":{"derivation":"from a compound of G473 (ἀντί) and G236 (ἀλλάσσω);","strongs_def":" an equivalent or ransom","kjv_def":"in exchange","lemma":"ἀντάλλαγμα","translit":"antállagma","pron":"an-tal'-ag-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is given in place of another thing by way of exchange</li><li>what is given either in order to keep or to acquire anything</li></ol>","xlit":"antállagma"},"G1677":{"kjv_def":"impute, put on account","lemma":"ἐλλογέω","translit":"ellogéō","derivation":"from G1722 (ἐν) and G3056 (λόγος) (in the sense of account);","strongs_def":" to reckon in, i.e. attribute","pron":"el-log-eh'-o","pos":"Verb","thayer":"<ol><li>to reckon in, set to one's account, lay to one's charge, impute</li></ol>","xlit":"ellogéō"},"G2420":{"translit":"hierōsýnē","lemma":"ἱερωσύνη","kjv_def":"priesthood","strongs_def":" sacredness, i.e. (by implication) the priestly office","derivation":"from G2413 (ἱερός);","pron":"hee-er-o-soo'-nay","pos":"Noun Feminine","thayer":"<ol><li>priesthood, the priestly office</li></ol>","xlit":"hierōsýnē"},"G1879":{"derivation":"middle voice from G1909 (ἐπί) and G373 (ἀναπαύω);","strongs_def":" to settle on; literally (remain) or figuratively (rely)","kjv_def":"rest in (upon)","lemma":"ἐπαναπαύομαι","translit":"epanapaúomai","pron":"ep-an-ah-pow'-om-ahee","pos":"Verb","thayer":"<ol><li>to cause to rest upon anything</li><li>to rest upon anything</li><li>to settle upon, fix its abode upon</li></ol>","xlit":"epanapaúomai"},"G1489":{"kjv_def":"if (so be that, yet)","lemma":"εἴγε","translit":"eíge","derivation":"from G1487 (εἰ) and G1065 (γέ);","strongs_def":" if indeed, seeing that, unless, (with negative) otherwise","pron":"i'-gheh","pos":"Conjunction","thayer":"<ol><li>if, indeed, inasmuch, as, since</li></ol>","xlit":"eíge"},"G5149":{"translit":"trízō","lemma":"τρίζω","kjv_def":"gnash","strongs_def":" to creak (squeak), i.e. (by analogy) to grate the teeth (in frenzy)","derivation":"apparently a primary verb;","pron":"trid'-zo","pos":"Verb","thayer":"<ol><li>to squeak, make a shrill cry</li><li>to gnash or grind one's teeth</li></ol>","xlit":"trízō"},"G5173":{"translit":"Tryphōsa","lemma":"Τρυφῶσα","kjv_def":"Tryphosa","strongs_def":" luxuriating; Tryphosa, a Christian female","derivation":"from G5172 (τρυφή);","pron":"troo-fo'-sah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tryphosa = \"luxuriating\"</p><ol><li>a Christian woman</li></ol>","xlit":"Tryphōsa"},"G3789":{"lemma":"ὄφις","translit":"óphis","kjv_def":"serpent","strongs_def":" a snake, figuratively, (as a type of sly cunning) an artful malicious person, especially Satan","derivation":"probably from G3700 (ὀπτάνομαι) (through the idea of sharpness of vision);","pron":"of'-is","pos":"Noun Masculine","thayer":"<ol><li>snake, serpent</li><li>with the ancients, the serpent was an emblem of cunning and wisdom. The serpent who deceived Eve was regarded by the Jews as the devil.</li></ol>","xlit":"óphis"},"G203":{"derivation":"from G206 (ἄκρον) and probably a modified form of (the penis or male sexual organ);","strongs_def":" the prepuce; by implication, an uncircumcised (i.e. gentile, figuratively, unregenerate) state or person","kjv_def":"not circumcised, uncircumcised (with G2192 (ἔχω)), uncircumcision","translit":"akrobystía","lemma":"ἀκροβυστία","pron":"ak-rob-oos-tee'-ah","pos":"Noun Feminine","thayer":"<ol><li>having the foreskin, uncircumcised</li><li>a Gentile</li><li>a condition in which the corrupt desires rooted in the flesh were not yet extinct</li></ol>","xlit":"akrobystía"},"G4478":{"lemma":"Ῥαχήλ","translit":"Rhachḗl","kjv_def":"Rachel","strongs_def":" Rachel, the wife of Jacob","derivation":"of Hebrew origin (H07354);","pron":"hrakh-ale'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Rachel = \"ewe or sheep\"</p><ol><li>the wife of Jacob</li></ol>","xlit":"Rhachḗl"},"G2516":{"kjv_def":"sit","lemma":"καθέζομαι","translit":"kathézomai","derivation":"from G2596 (κατά) and the base of G1476 (ἑδραῖος);","strongs_def":" to sit down","pron":"kath-ed'-zom-ahee","pos":"Verb","thayer":"<ol><li>to sit down, seat one's self, sit</li></ol>","xlit":"kathézomai"},"G4493":{"kjv_def":"twinkling","lemma":"ῥιπή","translit":"rhipḗ","derivation":"from G4496 (ῥίπτω);","strongs_def":" a jerk (of the eye, i.e. (by analogy) an instant)","pron":"hree-pay'","pos":"Noun Feminine","thayer":"<ol><li>a throw, stroke, beat</li><li>a moment of time</li></ol>","xlit":"rhipḗ"},"G5244":{"strongs_def":" appearing above others (conspicuous), i.e. (figuratively) haughty","derivation":"from G5228 (ὑπέρ) and G5316 (φαίνω);","lemma":"ὑπερήφανος","translit":"hyperḗphanos","kjv_def":"proud","pron":"hoop-er-ay'-fan-os","pos":"Adjective","thayer":"<ol><li>showing one's self above others, overtopping, conspicuous above others, pre-eminent</li><li>with an overweening estimate of one's means or merits, despising others or even treating them with contempt, haughty</li></ol>","xlit":"hyperḗphanos"},"G3713":{"translit":"orégomai","lemma":"ὀρέγομαι","kjv_def":"covet after, desire","strongs_def":" to stretch oneself, i.e. reach out after (long for)","derivation":"middle voice of apparently a prolonged form of an obsolete primary (compare G3735 (ὄρος));","pron":"or-eg'-om-ahee","pos":"Verb","thayer":"<ol><li>to stretch one's self out in order to touch or to grasp something, to reach after or desire something</li><li>to give one's self up to the love of money</li></ol>","xlit":"orégomai"},"G29":{"derivation":"of foreign origin (compare H0104);","strongs_def":" properly, to be a courier, i.e. (by implication) to press into public service","kjv_def":"compel (to go)","lemma":"ἀγγαρεύω","translit":"angareúō","pron":"ang-ar-yew'-o","pos":"Verb","thayer":"<ol><li>to employ a courier, dispatch a mounted messenger, press into public service, compel to go</li></ol>","xlit":"angareúō"},"G985":{"lemma":"βλαστάνω","translit":"blastánō","kjv_def":"bring forth, bud, spring (up)","strongs_def":" to germinate; by implication, to yield fruit","derivation":"from (a sprout);","pron":"blas-tan'-o","pos":"Verb","thayer":"<ol><li>to sprout, bud, put forth new leaves</li><li>to produce</li></ol>","xlit":"blastánō"},"G2061":{"derivation":"from G2060 (Ἑρμῆς) and G1096 (γίνομαι);","strongs_def":" born of Hermes; Hermogenes, an apostate Christian","kjv_def":"Hermogenes","lemma":"Ἑρμογένης","translit":"Hermogénēs","pron":"her-mog-en'-ace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Hermogenes = \"lucky born or born of Mercury\"</p><ol><li>a certain Christian mentioned in <a class='bible' href='#b55.1.15'>2Ti 1:15</a></li></ol>","xlit":"Hermogénēs"},"G2769":{"strongs_def":" something horned, i.e. (specially) the pod of the carob-tree","derivation":"neuter of a presumed derivative of G2768 (κέρας);","translit":"kerátion","lemma":"κεράτιον","kjv_def":"husk","pron":"ker-at'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a little horn</li><li>the name of the fruit, Ceratonia silqua or carobtree (called also John's Bread [from the notion that its pods, which resemble those of the \"locust\" , constituted the food of the Baptist]. This fruit was shaped like a horn and has a sweet taste; it was and is used not only for fattening swine, but as an article of food by the lower classes.</li></ol>","xlit":"kerátion"},"G4744":{"lemma":"στίλβω","translit":"stílbō","kjv_def":"shining","strongs_def":" to gleam, i.e. flash intensely","derivation":"apparently a primary verb;","pron":"stil'-bo","pos":"Verb","thayer":"<ol><li>to shine, glisten<ol type='a'><li>of garments</li></ol></li></ol>","xlit":"stílbō"},"G5441":{"translit":"phýlax","lemma":"φύλαξ","kjv_def":"keeper","strongs_def":" a watcher or sentry","derivation":"from G5442 (φυλάσσω);","pron":"foo'-lax","pos":"Noun Masculine","thayer":"<ol><li>a guard, keeper</li></ol>","xlit":"phýlax"},"G4963":{"strongs_def":" a twisting together, i.e. (figuratively) a secret coalition, riotous crowd","derivation":"from G4962 (συστρέφω);","lemma":"συστροφή","translit":"systrophḗ","kjv_def":"+ band together, concourse","pron":"soos-trof-ay'","pos":"Noun Feminine","thayer":"<ol><li>a twisting up together, a binding together</li><li>a secret combination, a coalition, conspiracy</li><li>a concourse of disorderly persons, a riot</li></ol>","xlit":"systrophḗ"},"G3322":{"strongs_def":" to form the middle, i.e. (in point of time), to be half-way over","derivation":"from G3319 (μέσος);","translit":"mesóō","lemma":"μεσόω","kjv_def":"be about the midst","pron":"mes-o'-o","pos":"Verb","thayer":"<ol><li>to be in the middle, be midway</li></ol>","xlit":"mesóō"},"G316":{"translit":"anankaîos","lemma":"ἀναγκαῖος","kjv_def":"near, necessary, necessity, needful","strongs_def":" necessary; by implication, close (of kin)","derivation":"from G318 (ἀνάγκη);","pron":"an-ang-kah'-yos","pos":"Adjective","thayer":"<ol><li>necessary<ol type='a'><li>what one can not do without, indispensable</li><li>connected by bonds of nature or friendship</li><li>what ought according to the law of duty be done, what is required by the circumstances</li></ol></li></ol>","xlit":"anankaîos"},"G329":{"strongs_def":" to re-enkindle","derivation":"from G303 (ἀνά) and a compound of the base of G2226 (ζῶον) and G4442 (πῦρ);","lemma":"ἀναζωπυρέω","translit":"anazōpyréō","kjv_def":"stir up","pron":"an-ad-zo-poor-eh'-o","pos":"Verb","thayer":"<ol><li>to kindle up, inflame one's mind, strength, zeal</li></ol>","xlit":"anazōpyréō"},"G512":{"translit":"anōphelḗs","lemma":"ἀνωφελής","kjv_def":"unprofitable(-ness)","strongs_def":" useless or (neuter) inutility","derivation":"from G1 (Α) (as a negative particle) and the base of G5624 (ὠφέλιμος);","pron":"an-o-fel'-ace","pos":"Adjective","thayer":"<ol><li>unprofitable, useless</li></ol>","xlit":"anōphelḗs"},"G2393":{"derivation":"probably of foreign origin (see H03471);","strongs_def":" \"jasper\", a gem","kjv_def":"jasper","lemma":"ἴασπις","translit":"íaspis","pron":"ee'-as-pis","pos":"Noun Feminine","thayer":"<ol><li>jasper, a precious stone of various colours (for some are purple, others blue, others green, and others the colour of brass)</li></ol>","xlit":"íaspis"},"G5440":{"translit":"phylaktḗrion","lemma":"φυλακτήριον","kjv_def":" phylactery","strongs_def":" a guard-case, i.e. \"phylactery\" for wearing slips of Scripture texts","derivation":"neuter of a derivative of G5442 (φυλάσσω);","pron":"foo-lak-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a fortified place provided with a garrison, a station for a guard or garrison</li><li>a preservative or safeguard , an amulet. The Jews used this word to describe small strips of parchment on which were written the following passages of the law of Moses, <a class='bible' href='#b2.13.1-10'>Exo 13:1-10</a>, <a class='bible' href='#b2.13.11-16'>Exo 13:11-16</a>; <a class='bible' href='#b5.6.4-9'>Deu 6:4-9</a>; and <a class='bible' href='#b5.11.13-21'>Deu 11:13-21</a></li></ol>","xlit":"phylaktḗrion"},"G515":{"kjv_def":"desire, think good, count (think) worthy","lemma":"ἀξιόω","translit":"axióō","derivation":"from G514 (ἄξιος);","strongs_def":" to deem entitled or fit","pron":"ax-ee-o'-o","pos":"Verb","thayer":"<ol><li>to think meet, fit, right</li><li>to judge worthy, deem, deserving</li></ol>","xlit":"axióō"},"G2734":{"strongs_def":" to mirror oneself, i.e. to see reflected (figuratively)","derivation":"middle voice from a compound of G2596 (κατά) and a derivative of G3700 (ὀπτάνομαι) (compare G2072 (ἔσοπτρον));","lemma":"κατοπτρίζομαι","translit":"katoptrízomai","kjv_def":"behold as in a glass","pron":"kat-op-trid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to show in a mirror, to make to reflect, to mirror</li><li>to look at one's self in a mirror</li><li>to behold one's self in a mirror</li></ol>","xlit":"katoptrízomai"},"G1349":{"translit":"díkē","lemma":"δίκη","kjv_def":"judgment, punish, vengeance","strongs_def":" right (as self-evident), i.e. justice (the principle, a decision, or its execution)","derivation":"probably from G1166 (δεικνύω);","pron":"dee'-kay","pos":"Noun Feminine","thayer":"<ol><li>custom, usage</li><li>right, just</li><li>a suit at law</li><li>a judicial hearing, judicial decision, especially sentence of condemnation</li><li>execution of a sentence, punishment<ol type='a'><li>to suffer punishment</li></ol><li>the goddess Justice, avenging justice</li></ol>","xlit":"díkē"},"G1967":{"strongs_def":" tomorrow's; but more probably from G1909 (ἐπί) and a derivative of the present participle feminine of G1510 (εἰμί); for subsistence, i.e. needful","derivation":"perhaps from the same as G1966 (ἐπιοῦσα);","lemma":"ἐπιούσιος","translit":"epioúsios","kjv_def":"daily","pron":"ep-ee-oo'-see-os","pos":"Adjective","thayer":"<ol><li>word found in the phrase<ol type='a'><li>the bread of our necessity</li><li>the bread that suffices for each day</li></ol></li></ol>","xlit":"epioúsios"},"G4095":{"derivation":"a prolonged form of ; which (together with another form) ; occurs only as an alternate in certain tenses;","strongs_def":" to imbibe (literally or figuratively)","kjv_def":"drink","translit":"pínō","lemma":"πίνω","pron":"pee'-no","pos":"Verb","thayer":"<ol><li>to drink</li><li>figuratively, to receive into the soul what serves to refresh strengthen, nourish it unto life eternal</li></ol>","xlit":"pínō"},"G353":{"translit":"analambánō","lemma":"ἀναλαμβάνω","kjv_def":"receive up, take (in, unto, up)","strongs_def":" to take up","derivation":"from G303 (ἀνά) and G2983 (λαμβάνω);","pron":"an-al-am-ban'-o","pos":"Verb","thayer":"<ol><li>to take up, raise</li><li>to take up (a thing in order to carry or use it)</li></ol>","xlit":"analambánō"},"G2007":{"kjv_def":"add unto, lade, lay upon, put (up) on, set on (up), + surname, X wound","lemma":"ἐπιτίθημι","translit":"epitíthēmi","derivation":"from G1909 (ἐπί) and G5087 (τίθημι);","strongs_def":" to impose (in a friendly or hostile sense)","pron":"ep-ee-tith'-ay-mee","pos":"Verb","thayer":"<ol><li>in the active voice<ol type='a'><li>to put or lay upon</li><li>to add to</li></ol><li>in the middle voice<ol type='a'><li>to have put on, bid to be laid on</li><li>to lay or throw one's self upon</li><li>to attack one, to make an assault on one</li></ol></li></ol>","xlit":"epitíthēmi"},"G2372":{"strongs_def":" passion (as if breathing hard)","derivation":"from G2380 (θύω);","lemma":"θυμός","translit":"thymós","kjv_def":"fierceness, indignation, wrath","pron":"thoo-mos'","pos":"Noun Masculine","thayer":"<ol><li>passion, angry, heat, anger forthwith boiling up and soon subsiding again</li><li>glow, ardour, the wine of passion, inflaming wine (which either drives the drinker mad or kills him with its strength)</li></ol>","xlit":"thymós"},"G2611":{"kjv_def":"bind up","lemma":"καταδέω","translit":"katadéō","derivation":"from G2596 (κατά) and G1210 (δέω);","strongs_def":" to tie down, i.e. bandage (a wound)","pron":"kat-ad-eh'-o","pos":"Verb","thayer":"<ol><li>to bind up</li></ol>","xlit":"katadéō"},"G2572":{"kjv_def":"cover, hide","lemma":"καλύπτω","translit":"kalýptō","derivation":"akin to G2813 (κλέπτω) and G2928 (κρύπτω);","strongs_def":" to cover up (literally or figuratively)","pron":"kal-oop'-to","pos":"Verb","thayer":"<ol><li>to hide, veil<ol type='a'><li>to hinder the knowledge of a thing</li></ol></li></ol>","xlit":"kalýptō"},"G5218":{"derivation":"from G5219 (ὑπακούω);","strongs_def":" attentive hearkening, i.e. (by implication) compliance or submission","kjv_def":"obedience, (make) obedient, obey(-ing)","lemma":"ὑπακοή","translit":"hypakoḗ","pron":"hoop-ak-o-ay'","pos":"Noun Feminine","thayer":"<ol><li>obedience, compliance, submission</li><li>obedience rendered to anyone's counsels, an obedience shown in observing the requirements of Christianity</li></ol>","xlit":"hypakoḗ"},"G5500":{"kjv_def":"choose, ordain","lemma":"χειροτονέω","translit":"cheirotonéō","derivation":"from a comparative of G5495 (χείρ) and (to stretch);","strongs_def":" to be a hand-reacher or voter (by raising the hand), i.e. (generally) to select or appoint","pron":"khi-rot-on-eh'-o","pos":"Verb","thayer":"<ol><li>to vote by stretching out the hand</li><li>to create or appoint by vote: one to have charge of some office or duty</li><li>to elect, create, appoint</li></ol>","xlit":"cheirotonéō"},"G1728":{"derivation":"from G1722 (ἐν) and G756 (ἄρχομαι);","strongs_def":" to commence on","kjv_def":"rule (by mistake for G757 (ἄρχω))","translit":"enárchomai","lemma":"ἐνάρχομαι","pron":"en-ar'-khom-ahee","pos":"Verb","thayer":"<ol><li>to begin, to make a beginning</li></ol>","xlit":"enárchomai"},"G1619":{"kjv_def":"fervently","lemma":"ἐκτενῶς","translit":"ektenōs","derivation":"adverb from G1618 (ἐκτενής);","strongs_def":" intently","pron":"ek-ten-oce'","pos":"Adverb","thayer":"<ol><li>earnestly, fervently, intensely</li></ol>","xlit":"ektenōs"},"G2866":{"derivation":"neuter comparative of a derivative of the base of 2865 (meaning, properly, well dressed, i.e. nice);","strongs_def":" figuratively, convalescent","kjv_def":"+ began to amend","translit":"kompsóteron","lemma":"κομψότερον","pron":"komp-sot'-er-on","pos":"Adverb","thayer":"<ol><li>more finely, better</li></ol>","xlit":"kompsóteron"},"G3856":{"translit":"paradeigmatízō","lemma":"παραδειγματίζω","kjv_def":"make a public example, put to an open shame","strongs_def":" to show alongside (the public), i.e. expose to infamy","derivation":"from G3844 (παρά) and G1165 (δειγματίζω);","pron":"par-ad-igue-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to set forth as a public example, make an example of<ol type='a'><li>in a bad sense<ol><li>to hold up to infamy</li><li>to expose to public disgrace</li></ol></li></ol></li></ol>","xlit":"paradeigmatízō"},"G2310":{"kjv_def":"foundation","translit":"themélios","lemma":"θεμέλιος","derivation":"from a derivative of G5087 (τίθημι);","strongs_def":" something put down, i.e. a substruction (of a building, etc.), (literally or figuratively)","pron":"them-el'-ee-os","pos":"Adjective","thayer":"<ol><li>laid down as a foundation, the foundation (of a building, wall, city)</li><li>metaphorically the foundations, beginnings, first principals<ol type='a'><li>of institution or system of truth</li></ol></li></ol>","xlit":"themélios"},"G4090":{"strongs_def":" bitterly, i.e. (figuratively) violently","derivation":"adverb from G4089 (πικρός);","translit":"pikrōs","lemma":"πικρῶς","kjv_def":"bitterly","pron":"pik-roce'","pos":"Adverb","thayer":"<ol><li>bitterly</li><li>metaphorically with poignant grief</li></ol>","xlit":"pikrōs"},"G4087":{"lemma":"πικραίνω","translit":"pikraínō","kjv_def":"be (make) bitter","strongs_def":" to embitter (literally or figuratively)","derivation":"from G4089 (πικρός);","pron":"pik-rah'-ee-no","pos":"Verb","thayer":"<ol><li>to make bitter<ol type='a'><li>to produce a bitter taste in the stomach</li></ol><li>to embitter. exasperate<ol type='a'><li>render angry, indignant</li><li>to be embittered, irritated</li><li>to visit with bitterness, to grieve (deal bitterly with)</li></ol></li></ol>","xlit":"pikraínō"},"G3991":{"derivation":"from G4002 (πέντε);","strongs_def":" fifth","kjv_def":"fifth","lemma":"πέμπτος","translit":"pémptos","pron":"pemp'-tos","pos":"Adjective","thayer":"<ol><li>fifth</li></ol>","xlit":"pémptos"},"G5124":{"strongs_def":" that thing","derivation":"neuter singular nominative or accusative case of G3778 (οὗτος);","translit":"toûto","lemma":"τοῦτο","kjv_def":"here (-unto), it, partly, self(-same), so, that (intent), the same, there(-fore, -unto), this, thus, where(-fore)","pron":"too'-to","thayer":"<ol><li>that (thing), this (thing)</li></ol>","xlit":"toûto"},"G2943":{"derivation":"adverb from the same as G2945 (κύκλῳ);","strongs_def":" from the circle, i.e. all around","kjv_def":"(round) about","lemma":"κυκλόθεν","translit":"kyklóthen","pron":"koo-kloth'-en","pos":"Adverb","thayer":"<ol><li>round about, from all sides, all around</li></ol>","xlit":"kyklóthen"},"G937":{"derivation":"from G935 (βασιλεύς);","strongs_def":" regal (in relation), i.e. (literally) belonging to (or befitting) the sovereign (as land, dress, or a courtier), or (figuratively) preeminent","kjv_def":"king's, nobleman, royal","translit":"basilikós","lemma":"βασιλικός","pron":"bas-il-ee-kos'","pos":"Adjective","thayer":"<ol><li>of or belong to a king, kingly, royal, regal<ol type='a'><li>of a man, the officer or minister of a prince, a courtier</li></ol><li>subject to a king<ol type='a'><li>of a country</li></ol><li>befitting or worthy of a king, royal</li><li>metaphorically principal, chief</li></ol>","xlit":"basilikós"},"G905":{"lemma":"βαλάντιον","translit":"balántion","kjv_def":"bag, purse","strongs_def":" a pouch (for money)","derivation":"probably remotely from G906 (βάλλω) (as a depository);","pron":"bal-an'-tee-on","pos":"Noun Neuter","thayer":"<ol><li>a money bag, purse</li></ol>","xlit":"balántion"},"G2462":{"strongs_def":" a horse","derivation":"of uncertain affinity;","lemma":"ἵππος","translit":"híppos","kjv_def":"horse","pron":"hip'-pos","pos":"Noun Masculine","thayer":"<ol><li>a horse</li></ol>","xlit":"híppos"},"G3986":{"strongs_def":" a putting to proof (by experiment (of good), experience (of evil), solicitation, discipline or provocation); by implication, adversity","derivation":"from G3985 (πειράζω);","lemma":"πειρασμός","translit":"peirasmós","kjv_def":"temptation, X try","pron":"pi-ras-mos'","pos":"Noun Masculine","thayer":"<ol><li>an experiment, attempt, trial, proving<ol type='a'><li>trial, proving: the trial made of you by my bodily condition, since condition served as to test the love of the Galatians toward Paul (<a class='bible' href='#b48.4.14'>Gal 4:14</a>)</li><li>the trial of man's fidelity, integrity, virtue, constancy<ol><li>an enticement to sin, temptation, whether arising from the desires or from the outward circumstances</li><li>an internal temptation to sin<ol type='a'><li>of the temptation by which the devil sought to divert Jesus the Messiah from his divine errand</li></ol><li>of the condition of things, or a mental state, by which we are enticed to sin, or to a lapse from the faith and holiness</li><li>adversity, affliction, trouble: sent by God and serving to test or prove one's character, faith, holiness</li></ol><li>temptation (i.e. trial) of God by men<ol><li>rebellion against God, by which his power and justice are, as it were, put to the proof and challenged to show themselves</li></ol></li></ol></li></ol>","xlit":"peirasmós"},"G4293":{"strongs_def":" to anounce beforehand, i.e. predict, promise","derivation":"from G4253 (πρό) and G2605 (καταγγέλλω);","translit":"prokatangéllō","lemma":"προκαταγγέλλω","kjv_def":"foretell, have notice, (shew) before","pron":"prok-at-ang-ghel'-lo","pos":"Verb","thayer":"<ol><li>to announce beforehand (that a thing will be)<ol type='a'><li>of prophecies</li></ol><li>to preannounce in the sense of to promise</li></ol>","xlit":"prokatangéllō"},"G4380":{"derivation":"from G4381 (προσωπολήπτης);","strongs_def":" to favor an individual, i.e. show partiality","kjv_def":"have respect to persons","translit":"prosōpolēptéō","lemma":"προσωποληπτέω","pron":"pros-o-pol-ape-teh'-o","pos":"Verb","thayer":"<ol><li>to respect the person (i.e. the external condition of man)</li><li>to have respect of persons, discriminate</li></ol>","xlit":"prosōpolēptéō"},"G2325":{"derivation":"from G2330 (θέρος) (in the sense of the crop);","strongs_def":" to harvest","kjv_def":"reap","translit":"therízō","lemma":"θερίζω","pron":"ther-id'-zo","pos":"Verb","thayer":"<ol><li>to reap, harvest</li><li>proverbial expression for sowing and reaping</li><li>cut off, destroy<ol type='a'><li>as crops are cut down with a sickle</li></ol></li></ol>","xlit":"therízō"},"G1221":{"kjv_def":"(what-)soever","translit":"dḗpote","lemma":"δήποτε","derivation":"from G1211 (δή) and G4218 (ποτέ);","strongs_def":" a particle of generalization; indeed, at any time","pron":"day'-pot-eh","pos":"Adverb","thayer":"<ol><li>now at length</li><li>at any time</li><li>at last</li><li>just exactly</li></ol>","xlit":"dḗpote"},"G5604":{"strongs_def":" a pang or throe, especially of childbirth","derivation":"akin to G3601 (ὀδύνη);","lemma":"ὠδίν","translit":"ōdín","kjv_def":"pain, sorrow, travail","pron":"o-deen'","pos":"Noun Feminine","thayer":"<ol><li>the pain of childbirth, travail pain, birth pangs</li><li>intolerable anguish, in reference to the dire calamities precede the advent of the Messiah</li></ol>","xlit":"ōdín"},"G493":{"derivation":"contracted for a compound of G473 (ἀντί) and a derivative of G3962 (πατήρ);","strongs_def":" Antipas, a Christian","kjv_def":"Antipas","lemma":"Ἀντίπας","translit":"Antípas","pron":"an-tee'-pas","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Antipas = \"like the father\"</p><ol><li>a Christian of Pergamos who suffered martyrdom</li></ol>","xlit":"Antípas"},"G4364":{"kjv_def":"make as though","translit":"prospoiéomai","lemma":"προσποιέομαι","derivation":"middle voice from G4314 (πρός) and G4160 (ποιέω);","strongs_def":" to do forward for oneself, i.e. pretend (as if about to do a thing)","pron":"pros-poy-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to take or claim a thing to one's self</li><li>to conform one's self to a thing, or rather to affect to one's self<ol type='a'><li>to pretend</li></ol></li></ol>","xlit":"prospoiéomai"},"G3718":{"kjv_def":"rightly divide","translit":"orthotoméō","lemma":"ὀρθοτομέω","derivation":"from a compound of G3717 (ὀρθός) and the base of G5114 (τομώτερος), to make a straight cut, i.e. (figuratively) to dissect (expound) correctly (the divine message)","pron":"or-thot-om-eh'-o","pos":"Verb","thayer":"<ol><li>to cut straight, to cut straight ways<ol type='a'><li>to proceed on straight paths, hold a straight course, equiv. to doing right</li></ol><li>to make straight and smooth, to handle aright, to teach the truth directly and correctly</li></ol>","xlit":"orthotoméō"},"G3008":{"kjv_def":"minister","lemma":"λειτουργέω","translit":"leitourgéō","derivation":"from G3011 (λειτουργός);","strongs_def":" to be a public servant, i.e. (by analogy) to perform religious or charitable functions (worship, obey, relieve)","pron":"li-toorg-eh'-o","pos":"Verb","thayer":"<ol><li>to serve the state at one's own cost<ol type='a'><li>to assume an office which must be administered at one's own expense</li><li>to discharge a public office at one's own cost</li><li>to render public service to the state</li></ol><li>to do a service, perform a work<ol type='a'><li>of priests and Levites who were busied with the sacred rites in the tabernacle or the temple</li><li>of Christians serving Christ, whether by prayer, or by instructing others concerning the way of salvation, or in some other way</li><li>of those who aid others with their resources, and relieve their poverty</li></ol></li></ol>","xlit":"leitourgéō"},"G1502":{"lemma":"εἴκω","translit":"eíkō","kjv_def":"give place","strongs_def":" properly, to be weak, i.e. yield","derivation":"apparently a primary verb;","pron":"i'-ko","pos":"Verb","thayer":"<ol><li>to yield</li></ol>","xlit":"eíkō"},"G735":{"strongs_def":" prompt; Artemis, the name of a Grecian goddess borrowed by the Asiatics for one of their deities","derivation":"probably from the same as G736 (ἀρτέμων);","translit":"Ártemis","lemma":"Ἄρτεμις","kjv_def":"Diana","pron":"ar'-tem-is","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Diana = \"complete light: flow restrained\"</p><ol><li>Artemis, that is to say the so called Tauric or Persian or Ephesian Artemis, the goddess of many Asiatic people, to be distinguished from the Artemis of the Greeks, the sister of Apollo. A very splendid temple was built to her at Ephesus, which was set on fire by Herostratus and reduced to ashes; but afterwards in the times of Alexander the Great, it was rebuilt in a style of greater magnificence.</li></ol>","xlit":"Ártemis"},"G3511":{"lemma":"νεωκόρος","translit":"neōkóros","kjv_def":"worshipper","strongs_def":" a temple-servant, i.e. (by implication) a votary","derivation":"from a form of G3485 (ναός) and (to sweep);","pron":"neh-o-kor'-os","pos":"Noun Masculine","thayer":"<ol><li>one who sweeps and cleans a temple</li><li>one who has charge of a temple, to keep and adorn it, a sacristan</li><li>the worshipper of a deity<ol type='a'><li>word appears from coins still extant, it was an honourary title [temple-keeper or temple-warden] of certain cities, especially in Asia Minor, or in which some special worship of some deity or even some deified human ruler had been established; used of Ephesus</li></ol></li></ol>","xlit":"neōkóros"},"G1050":{"derivation":"of Latin origin;","strongs_def":" Gaius (i.e. Caius), a Christian","kjv_def":"Gaius","translit":"Gáïos","lemma":"Γάϊος","pron":"gah'-ee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Gaius = \"lord\"</p><ol><li>a Macedonian who accompanied Paul in his travels</li><li>a man from Derbe who went with Paul from Corinth in his last journey to Jerusalem</li><li>a man of Corinth who was his host in his second sojourn in that city</li><li>an unknown Christian to whom John's third epistle is addressed</li></ol>","xlit":"Gáïos"},"G2182":{"translit":"epheuretḗs","lemma":"ἐφευρετής","kjv_def":"inventor","strongs_def":" a discoverer, i.e. contriver","derivation":"from a compound of G1909 (ἐπί) and G2147 (εὑρίσκω);","pron":"ef-yoo-ret'-ace","pos":"Noun Masculine","thayer":"<ol><li>an inventor, contriver</li></ol>","xlit":"epheuretḗs"},"G3688":{"derivation":"apparently a primary word;","strongs_def":" a donkey","kjv_def":"an ass","lemma":"ὄνος","translit":"ónos","pron":"on'-os","pos":"Noun","thayer":"<ol><li>an ass</li></ol>","xlit":"ónos"},"G1602":{"derivation":"from G1537 (ἐκ) and G4126 (πλέω);","strongs_def":" to depart by ship","kjv_def":"sail (away, thence)","lemma":"ἐκπλέω","translit":"ekpléō","pron":"ek-pleh'-o","pos":"Verb","thayer":"<ol><li>to sail from, sail away, depart by ship</li></ol>","xlit":"ekpléō"},"G1808":{"kjv_def":"put (take) away","translit":"exaírō","lemma":"ἐξαίρω","derivation":"from G1537 (ἐκ) and G142 (αἴρω);","strongs_def":" to remove","pron":"ex-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to lift up or take away out of a place</li><li>to remove</li></ol>","xlit":"exaírō"},"G3701":{"strongs_def":" visuality, i.e. (concretely) an apparition","derivation":"from a presumed derivative of G3700 (ὀπτάνομαι);","translit":"optasía","lemma":"ὀπτασία","kjv_def":"vision","pron":"op-tas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the act of exhibiting one's self to view</li><li>a sight, a vision, an appearance presented to one whether asleep or awake</li></ol>","xlit":"optasía"},"G4876":{"derivation":"from G4862 (σύν) and a derivative of G473 (ἀντί);","strongs_def":" to meet with; figuratively, to occur","kjv_def":"befall, meet","translit":"synantáō","lemma":"συναντάω","pron":"soon-an-tah'-o","pos":"Verb","thayer":"<ol><li>to meet with<ol type='a'><li>of events: to happen or befall</li></ol></li></ol>","xlit":"synantáō"},"G1923":{"derivation":"from G1924 (ἐπιγράφω);","strongs_def":" an inscription","kjv_def":"superscription","lemma":"ἐπιγραφή","translit":"epigraphḗ","pron":"ep-ig-raf-ay'","pos":"Noun Feminine","thayer":"<ol><li>an inscription, title<ol type='a'><li>in the NT of an inscription in black letters upon a whitened tablet</li><li>of the inscription on a coin</li></ol></li></ol>","xlit":"epigraphḗ"},"G1314":{"strongs_def":" to guard thoroughly, i.e. protect","derivation":"from G1223 (διά) and G5442 (φυλάσσω);","translit":"diaphylássō","lemma":"διαφυλάσσω","kjv_def":"keep","pron":"dee-af-oo-las'-so","pos":"Verb","thayer":"<ol><li>to guard carefully<ol type='a'><li>the LXX used this especially of God's providential care</li></ol></li></ol>","xlit":"diaphylássō"},"G4815":{"lemma":"συλλαμβάνω","translit":"syllambánō","kjv_def":"catch, conceive, help, take","strongs_def":" to clasp, i.e. seize (arrest, capture); specially, to conceive (literally or figuratively); by implication, to aid","derivation":"from G4862 (σύν) and G2983 (λαμβάνω);","pron":"sool-lam-ban'-o","pos":"Verb","thayer":"<ol><li>to seize, take: one as prisoner</li><li>to conceive, of a woman<ol type='a'><li>metaphorically of lust whose impulses a man indulges</li></ol><li>to seize for one's self<ol type='a'><li>in a hostile sense, to make (one a permanent) prisoner</li></ol><li>to take hold together with one, to assist, help, to succour</li></ol>","xlit":"syllambánō"},"G4892":{"kjv_def":"council","translit":"synédrion","lemma":"συνέδριον","derivation":"neuter of a presumed derivative of a compound of G4862 (σύν) and the base of G1476 (ἑδραῖος);","strongs_def":" a joint session, i.e. (specially), the Jewish Sanhedrin; by analogy, a subordinate tribunal","pron":"soon-ed'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>any assembly (especially of magistrates, judges, ambassadors), whether convened to deliberate or pass judgment</li><li>any session or assembly or people deliberating or adjudicating<ol type='a'><li>the Sanhedrin, the great council at Jerusalem, consisting of the seventy one members, viz. scribes, elders, prominent members of the high priestly families and the high priest, the president of the assembly. The most important causes were brought before this tribunal, inasmuch as the Roman rulers of Judaea had left to it the power of trying such cases, and also of pronouncing sentence of death, with the limitation that a capital sentence pronounced by the Sanhedrin was not valid unless it was confirmed by the Roman procurator.</li><li>a smaller tribunal or council which every Jewish town had for the decision of less important cases.</li></ol></li></ol>","xlit":"synédrion"},"G2957":{"lemma":"Κυρήνη","translit":"Kyrḗnē","kjv_def":"Cyrene","strongs_def":" Cyrene, a region of Africa","derivation":"of uncertain derivation;","pron":"koo-ray'-nay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cyrene = \"supremacy of the bridle\"</p><ol><li>a large and very flourishing city of Libya Cyrenaica or Pentapolitana, about 11 miles (17 km) from the sea. Among its inhabitants were a great number of Jews, whom Ptolemy I. had brought there, and invested with the right of citizens</li></ol>","xlit":"Kyrḗnē"},"G2690":{"kjv_def":"overthrow","lemma":"καταστρέφω","translit":"katastréphō","derivation":"from G2596 (κατά) and G4762 (στρέφω);","strongs_def":" to turn upside down, i.e. upset","pron":"kat-as-tref'-o","pos":"Verb","thayer":"<ol><li>to turn over, turn under<ol type='a'><li>the soil with a plough</li></ol><li>to overturn, overthrow, throw down</li></ol>","xlit":"katastréphō"},"G2829":{"derivation":"from G2813 (κλέπτω);","strongs_def":" stealing","kjv_def":"theft","lemma":"κλοπή","translit":"klopḗ","pron":"klop-ay'","pos":"Noun Feminine","thayer":"<ol><li>theft</li></ol>","xlit":"klopḗ"},"G3123":{"strongs_def":" (adverbially) more (in a greater degree)) or rather","derivation":"neuter of the comparative of the same as G3122 (μάλιστα);","lemma":"μᾶλλον","translit":"mâllon","kjv_def":"+ better, X far, (the) more (and more), (so) much (the more), rather","pron":"mal'-lon","pos":"Adverb","thayer":"<ol><li>more, to a greater degree, rather<ol type='a'><li>much, by far</li><li>rather, sooner</li><li>more willingly, more readily, sooner</li></ol></li></ol>","xlit":"mâllon"},"G2984":{"derivation":"of Hebrew origin (H03929);","strongs_def":" Lamech (i.e. Lemek), a patriarch","kjv_def":"Lamech","translit":"Lámech","lemma":"Λάμεχ","pron":"lam'-ekh","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lamech = \"why thus with thee?: unto bringing low\"</p><ol><li>the father of Noah</li></ol>","xlit":"Lámech"},"G3562":{"translit":"nounechōs","lemma":"νουνεχῶς","kjv_def":"discreetly","strongs_def":" in a mind-having way, i.e. prudently","derivation":"adverb from a comparative of the accusative case of G3563 (νοῦς) and G2192 (ἔχω);","pron":"noon-ekh-oce'","pos":"Adverb","thayer":"<ol><li>wisely, discreetly, prudently</li></ol>","xlit":"nounechōs"},"G640":{"strongs_def":" a (state of) quandary","derivation":"from the same as G639 (ἀπορέω);","translit":"aporía","lemma":"ἀπορία","kjv_def":"perplexity","pron":"ap-or-ee'-a","pos":"Noun Feminine","thayer":"<ol><li>the state of one who is in perplexity</li></ol>","xlit":"aporía"},"G2624":{"derivation":"from G2596 (κατά) and a derivative of a compound of G2819 (κλῆρος) and G1325 (δίδωμι);","strongs_def":" to be a giver of lots to each, i.e. (by implication) to apportion an estate","kjv_def":"divide by lot","translit":"kataklērodotéō","lemma":"κατακληροδοτέω","pron":"kat-ak-lay-rod-ot-eh'-o","pos":"Verb","thayer":"<ol><li>to distribute by lot</li><li>to distribute as an inheritance</li></ol>","xlit":"kataklērodotéō"},"G1460":{"translit":"enkatoikéō","lemma":"ἐγκατοικέω","kjv_def":"dwell among","strongs_def":" to settle down in a place, i.e. reside","derivation":"from G1722 (ἐν) and G2730 (κατοικέω);","pron":"eng-kat-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell among</li></ol>","xlit":"enkatoikéō"},"G641":{"derivation":"from G575 (ἀπό) and G4496 (ῥίπτω);","strongs_def":" to hurl off, i.e. precipitate (oneself)","kjv_def":"cast","translit":"aporrhíptō","lemma":"ἀποῤῥίπτω","pron":"ap-or-hrip'-to","pos":"Verb","thayer":"<ol><li>to throw away, cast down</li><li>to cast one's self down</li></ol>","xlit":"aporrhíptō"},"G3963":{"lemma":"Πάτμος","translit":"Pátmos","kjv_def":"Patmos","strongs_def":" Patmus, an islet in the Mediterranean","derivation":"of uncertain derivation;","pron":"pat'-mos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Patmos = \"my killing\"</p><ol><li>a rugged and bare island in the Aegean Sea</li></ol>","xlit":"Pátmos"},"G807":{"kjv_def":"behave self uncomely (unseemly)","translit":"aschēmonéō","lemma":"ἀσχημονέω","derivation":"from G809 (ἀσχήμων);","strongs_def":" to be (i.e. act) unbecoming","pron":"as-kay-mon-eh'-o","pos":"Verb","thayer":"<ol><li>to act unbecomingly</li></ol>","xlit":"aschēmonéō"},"G1282":{"kjv_def":"cut (to the heart)","lemma":"διαπρίω","translit":"diapríō","derivation":"from G1223 (διά) and the base of G4249 (πρίζω);","strongs_def":" to saw asunder, i.e. (figuratively) to exasperate","pron":"dee-ap-ree'-o","pos":"Verb","thayer":"<ol><li>to saw asunder or in two, to divide by a saw</li><li>to be sawn through mentally, i.e. to be rent with vexation</li></ol>","xlit":"diapríō"},"G772":{"derivation":"from G1 (Α) (as a negative particle) and the base of G4599 (σθενόω);","strongs_def":" strengthless (in various applications, literal, figurative and moral)","kjv_def":"more feeble, impotent, sick, without strength, weak(-er, -ness, thing)","lemma":"ἀσθενής","translit":"asthenḗs","pron":"as-then-ace'","pos":"Adjective","thayer":"<ol><li>weak, infirm, feeble</li></ol>","xlit":"asthenḗs"},"G2270":{"kjv_def":"cease, hold peace, be quiet, rest","lemma":"ἡσυχάζω","translit":"hēsycházō","derivation":"from the same as G2272 (ἡσύχιος);","strongs_def":" to keep still (intransitively), i.e. refrain from labor, meddlesomeness or speech","pron":"hay-soo-khad'-zo","pos":"Verb","thayer":"<ol><li>to keep quiet<ol type='a'><li>to rest, cease from labour</li><li>to lead a quiet life, said of those who are not running hither and thither, but stay at home and mind their business</li><li>to be silent, i.e. to say nothing, hold one's peace</li></ol></li></ol>","xlit":"hēsycházō"},"G842":{"derivation":"from G846 (αὐτός) and G714 (ἀρκέω);","strongs_def":" self-complacent, i.e. contented","kjv_def":"content","translit":"autárkēs","lemma":"αὐτάρκης","pron":"ow-tar'-kace","pos":"Adjective","thayer":"<ol><li>sufficient for one's self, strong enough or processing enough to need no aid or support</li><li>independent of external circumstances</li><li>contented with one's lot, with one's means, though the slenderest</li></ol>","xlit":"autárkēs"},"G1919":{"kjv_def":"earthly, in earth, terrestrial","lemma":"ἐπίγειος","translit":"epígeios","derivation":"from G1909 (ἐπί) and G1093 (γῆ);","strongs_def":" worldly (physically or morally)","pron":"ep-ig'-i-os","pos":"Adjective","thayer":"<ol><li>existing upon the earth, earthly, terrestrial</li></ol>","xlit":"epígeios"},"G1951":{"translit":"epilégomai","lemma":"ἐπιλέγομαι","kjv_def":"call, choose","strongs_def":" to surname, select","derivation":"middle voice from G1909 (ἐπί) and G3004 (λέγω);","pron":"ep-ee-leg'-om-ahee","pos":"Verb","thayer":"<ol><li>to say besides</li><li>to surname</li><li>to choose for</li><li>to choose for one's self</li></ol>","xlit":"epilégomai"},"G3740":{"kjv_def":"as oft(-en) as","translit":"hosákis","lemma":"ὁσάκις","derivation":"multiple adverb from G3739 (ὅς);","strongs_def":" how (i.e. with G302 (ἄν), so) many times as","pron":"hos-ak'-is","pos":"Adverb","thayer":"<ol><li>as often as, as often soever as</li></ol>","xlit":"hosákis"},"G4211":{"strongs_def":" a female trader in purple cloth","derivation":"feminine of a compound of G4209 (πορφύρα) and G4453 (πωλέω);","lemma":"πορφυρόπωλις","translit":"porphyrópōlis","kjv_def":"seller of purple","pron":"por-foo-rop'-o-lis","pos":"Noun Feminine","thayer":"<ol><li>a female seller of purple or of fabric dyed in purple</li></ol>","xlit":"porphyrópōlis"},"G4839":{"kjv_def":"continue with","lemma":"συμπαραμένω","translit":"symparaménō","derivation":"from G4862 (σύν) and G3887 (παραμένω);","strongs_def":" to remain in company, i.e. still live","pron":"soom-par-am-en'-o","pos":"Verb","thayer":"<ol><li>to abide together with</li><li>to continue to live together</li></ol>","xlit":"symparaménō"},"G3716":{"kjv_def":"walk uprightly","translit":"orthopodéō","lemma":"ὀρθοποδέω","derivation":"from a compound of G3717 (ὀρθός) and G4228 (πούς);","strongs_def":" to be straight-footed, i.e. (figuratively) to go directly forward","pron":"or-thop-od-eh'-o","pos":"Verb","thayer":"<ol><li>to walk in a straight course</li><li>metaphorically to act uprightly</li></ol>","xlit":"orthopodéō"},"G1424":{"strongs_def":" the sun-set, i.e. (by implication) the western region","derivation":"from G1416 (δύνω);","translit":"dysmḗ","lemma":"δυσμή","kjv_def":"west","pron":"doos-may'","pos":"Noun Feminine","thayer":"<ol><li>the setting of the sun</li><li>the region of the sunset, the west</li></ol>","xlit":"dysmḗ"},"G2068":{"lemma":"ἐσθίω","translit":"esthíō","kjv_def":"devour, eat, live","strongs_def":" used only in certain tenses, the rest being supplied by G5315 (φάγω); to eat (usually literal)","derivation":"strengthened for a primary (to eat);","pron":"es-thee'-o","pos":"Verb","thayer":"<ol><li>to eat</li><li>to eat (consume) a thing<ol type='a'><li>to take food, eat a meal</li></ol><li>metaphorically to devour, consume</li></ol>","xlit":"esthíō"},"G3496":{"derivation":"from G3501 (νέος) and G4172 (πόλις);","strongs_def":" new town; Neapolis, a place in Macedonia","kjv_def":"Neapolis","lemma":"Νεάπολις","translit":"Neápolis","pron":"neh-ap'-ol-is","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Neapolis = \"new city\"</p><ol><li>a maritime city of Macedonia, on the gulf of Syrymon, having a port and colonised by Chalcidians</li></ol>","xlit":"Neápolis"},"G4785":{"kjv_def":"number with","lemma":"συγκαταψηφίζω","translit":"synkatapsēphízō","derivation":"from G4862 (σύν) and a compound of G2596 (κατά) and G5585 (ψηφίζω);","strongs_def":" to count down in company with, i.e. enroll among","pron":"soong-kat-aps-ay-fid'-zo","pos":"Verb","thayer":"<ol><li>be depositing a ballot in the urn (i.e. by voting for) to assign one a place among, to vote one a place among</li><li>to vote against with others, i.e. to condemn with others</li></ol>","xlit":"synkatapsēphízō"},"G1885":{"kjv_def":"province","lemma":"ἐπαρχία","translit":"eparchía","derivation":"from a compound of G1909 (ἐπί) and G757 (ἄρχω) (meaning a governor of a district, \"eparch\");","strongs_def":" a special region of government, i.e. a Roman præfecture","pron":"ep-ar-khee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the office of a governor or prefect</li><li>the region subject to a prefect<ol type='a'><li>a province of the Roman empire, either a larger province, or an appendage to a larger province, as Palestine was to that of Syria</li></ol></li></ol>","xlit":"eparchía"},"G679":{"strongs_def":" not stumbling, i.e. (figuratively) without sin","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4417 (πταίω);","translit":"áptaistos","lemma":"ἄπταιστος","kjv_def":"from falling","pron":"ap-tah'-ee-stos","pos":"Adjective","thayer":"<ol><li>not stumbling, standing firm, exempt from falling</li></ol>","xlit":"áptaistos"},"G4147":{"derivation":"from G4148 (πλουτίζω);","strongs_def":" to be (or become) wealthy (literally or figuratively)","kjv_def":"be increased with goods, (be made, wax) rich","lemma":"πλουτέω","translit":"ploutéō","pron":"ploo-teh'-o","pos":"Verb","thayer":"<ol><li>to be rich, to have abundance<ol type='a'><li>of outward possessions</li></ol><li>metaphorically to be richly supplied<ol type='a'><li>is affluent in resources so that he can give blessings of salvation to all</li></ol></li></ol>","xlit":"ploutéō"},"G5199":{"lemma":"ὑγιής","translit":"hygiḗs","kjv_def":"sound, whole","strongs_def":" healthy, i.e. well (in body); figuratively, true (in doctrine)","derivation":"from the base of G837 (αὐξάνω);","pron":"hoog-ee-ace'","pos":"Adjective","thayer":"<ol><li>sound<ol type='a'><li>of a man who is sound in body</li></ol><li>to make one whole, i.e. restore him to health</li><li>metaphorically teaching which does not deviate from the truth</li></ol>","xlit":"hygiḗs"},"G615":{"kjv_def":"put to death, kill, slay","translit":"apokteínō","lemma":"ἀποκτείνω","derivation":"from G575 (ἀπό) and (to slay);","strongs_def":" to kill outright; figuratively, to destroy","pron":"ap-ok-ti'-no","pos":"Verb","thayer":"<ol><li>to kill in any way whatever<ol type='a'><li>to destroy, to allow to perish</li></ol><li>metaphorically to extinguish, abolish<ol type='a'><li>to inflict mortal death</li><li>to deprive of spiritual life and procure eternal misery in hell</li></ol></li></ol>","xlit":"apokteínō"},"G207":{"strongs_def":" Akulas, an Israelite","derivation":"probably for Latin aquila (an eagle);","translit":"Akýlas","lemma":"Ἀκύλας","kjv_def":"Aquila","pron":"ak-oo'-las","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aquila = \"an eagle\"</p><ol><li>a Jew of Pontus, a tent maker convert to Christ, companion and ally of Paul in propagating Christianity</li></ol>","xlit":"Akýlas"},"G3900":{"lemma":"παράπτωμα","translit":"paráptōma","kjv_def":"fall, fault, offence, sin, trespass","strongs_def":" a side-slip (lapse or deviation), i.e. (unintentional) error or (wilful) transgression","derivation":"from G3895 (παραπίπτω);","pron":"par-ap'-to-mah","pos":"Noun Neuter","thayer":"<ol><li>to fall beside or near something</li><li>a lapse or deviation from truth and uprightness<ol type='a'><li>a sin, misdeed</li></ol></li></ol>","xlit":"paráptōma"},"G445":{"lemma":"ἀνθυπατεύω","translit":"anthypateúō","kjv_def":"be the deputy","strongs_def":" to act as proconsul","derivation":"from G446 (ἀνθύπατος);","pron":"anth-oo-pat-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a proconsul</li></ol>","xlit":"anthypateúō"},"G4123":{"kjv_def":"covetous","lemma":"πλεονέκτης","translit":"pleonéktēs","derivation":"from G4119 (πλείων) and G2192 (ἔχω);","strongs_def":" holding (desiring) more, i.e. eager for gain (avaricious, hence a defrauder)","pron":"pleh-on-ek'-tace","pos":"Noun Masculine","thayer":"<ol><li>one eager to have more, especially what belongs to others</li><li>greedy of gain, covetous</li></ol>","xlit":"pleonéktēs"},"G5393":{"strongs_def":" blazing; Phlegon, a Christian","derivation":"active participle of the base of G5395 (φλόξ);","lemma":"Φλέγων","translit":"Phlégōn","kjv_def":"Phlegon","pron":"fleg'-one","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Phlegon = \"burning\"</p><ol><li>a resident at Rome greeted by Paul of the book of Romans</li></ol>","xlit":"Phlégōn"},"G1901":{"lemma":"ἐπεκτείνομαι","translit":"epekteínomai","kjv_def":"reach forth","strongs_def":" to stretch (oneself) forward upon","derivation":"middle voice from G1909 (ἐπί) and G1614 (ἐκτείνω);","pron":"ep-ek-ti'-nom-ahee","pos":"Verb","thayer":"<ol><li>to stretch out to or towards</li><li>to stretch (one's self) forward to</li></ol>","xlit":"epekteínomai"},"G5400":{"kjv_def":"fearful sight","lemma":"φόβητρον","translit":"phóbētron","derivation":"neuter of a derivative of G5399 (φοβέω);","strongs_def":" a frightening thing, i.e. terrific portent","pron":"fob'-ay-tron","pos":"Noun Neuter","thayer":"<ol><li>that which strikes terror, a terror, (cause of) fright</li></ol>","xlit":"phóbētron"},"G21":{"translit":"agalliáō","lemma":"ἀγαλλιάω","kjv_def":"be (exceeding) glad, with exceeding joy, rejoice (greatly)","strongs_def":" properly, to jump for joy, i.e. exult","derivation":"from agan (much) and G242 (ἅλλομαι);","pron":"ag-al-lee-ah'-o","pos":"Verb","thayer":"<ol><li>to exult, rejoice exceedingly, be exceeding glad</li></ol>","xlit":"agalliáō"},"G3518":{"strongs_def":" Neri (i.e. Nerijah), an Israelite","derivation":"of Hebrew origin (H05374);","lemma":"Νηρί","translit":"Nērí","kjv_def":"Neri","pron":"nay-ree'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Neri = \"Jehovah is my lamp\"</p><ol><li>the grandfather of Zerubbabel</li></ol>","xlit":"Nērí"},"G3570":{"lemma":"νυνί","translit":"nyní","kjv_def":"now","strongs_def":" just now","derivation":"a prolonged form of G3568 (νῦν) for emphasis;","pron":"noo-nee'","pos":"Adverb","thayer":"<ol><li>now, at this very moment</li></ol>","xlit":"nyní"},"G3798":{"kjv_def":"even(-ing, (-tide))","translit":"ópsios","lemma":"ὄψιος","derivation":"from G3796 (ὀψέ);","strongs_def":" late; feminine (as noun) afternoon (early eve) or nightfall (later eve)","pron":"op'-see-os","pos":"Adjective","thayer":"<ol><li>late</li><li>evening<ol type='a'><li>either from three to six o'clock p.m.</li><li>from six o'clock p.m. to the beginning of night</li></ol></li></ol>","xlit":"ópsios"},"G4268":{"lemma":"πρόγνωσις","translit":"prógnōsis","kjv_def":"foreknowledge","strongs_def":" forethought","derivation":"from G4267 (προγινώσκω);","pron":"prog'-no-sis","pos":"Noun Feminine","thayer":"<ol><li>foreknowledge</li><li>forethought, pre-arrangement</li></ol>","xlit":"prógnōsis"},"G2916":{"kjv_def":"barley","lemma":"κρίθινος","translit":"kríthinos","derivation":"from G2915 (κριθή);","strongs_def":" consisting of barley","pron":"kree'-thee-nos","pos":"Adjective","thayer":"<ol><li>of barley, made of barley</li></ol>","xlit":"kríthinos"},"G392":{"derivation":"from G303 (ἀνά) and the middle voice of G5021 (τάσσω);","strongs_def":" to arrange","kjv_def":"set in order","translit":"anatássomai","lemma":"ἀνατάσσομαι","pron":"an-at-as'-som-ahee","pos":"Verb","thayer":"<ol><li>to put together in order, arrange, compose</li></ol>","xlit":"anatássomai"},"G3378":{"kjv_def":"neither (followed by no), + never, not","lemma":"μὴ οὐκ","translit":"mḕ ouk","derivation":"i.e. G3361 (μή) and G3756 (οὐ);","strongs_def":" as interrogative and negative, is it not that?","pron":"may ook","thayer":"<ol><li>not, not ever</li></ol>","xlit":"mḕ ouk"},"G5401":{"kjv_def":"be afraid, + exceedingly, fear, terror","translit":"phóbos","lemma":"φόβος","derivation":"from a primary (to be put in fear);","strongs_def":" alarm or fright","pron":"fob'-os","pos":"Noun Masculine","thayer":"<ol><li>fear, dread, terror<ol type='a'><li>that which strikes terror</li></ol><li>reverence for one's husband</li></ol>","xlit":"phóbos"},"G854":{"kjv_def":"vanish away","lemma":"ἀφανισμός","translit":"aphanismós","derivation":"from G853 (ἀφανίζω);","strongs_def":" disappearance, i.e. (figuratively) abrogation","pron":"af-an-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>disappearance</li><li>destruction</li></ol>","xlit":"aphanismós"},"G2247":{"derivation":"of uncertain affinity;","strongs_def":" a stud, i.e. spike","kjv_def":"nail","lemma":"ἧλος","translit":"hēlos","pron":"hay'-los","pos":"Noun Masculine","thayer":"<ol><li>a nail</li></ol>","xlit":"hēlos"},"G789":{"derivation":"probably of foreign origin;","strongs_def":" Assus, a city of Asia MInor","kjv_def":"Assos","translit":"Ássos","lemma":"Ἄσσος","pron":"as'-sos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Assos = \"approaching\"</p><ol><li>a seaport of the Roman province of Asia in the district anciently called Mysia, on the north shore of the Gulf of Adramyttium, and about 7 miles (11 km) from Lesbos</li></ol>","xlit":"Ássos"},"G3885":{"translit":"paralytikós","lemma":"παραλυτικός","kjv_def":"that had (sick of) the palsy","strongs_def":" as if dissolved, i.e. \"paralytic\"","derivation":"from a derivative of G3886 (παραλύω);","pron":"par-al-oo-tee-kos'","pos":"Adjective","thayer":"<ol><li>paralytic<ol type='a'><li>suffering from the relaxing of the nerves of one's side</li><li>disabled, weak of limb</li></ol></li></ol>","xlit":"paralytikós"},"G923":{"strongs_def":" son of Sabas (or Tsaba); Bar-sabas, the name of two Israelites","derivation":"of Chaldee origin (H01247 and probably H06634);","translit":"Barsabâs","lemma":"Βαρσαβᾶς","kjv_def":"Barsabas","pron":"bar-sab-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barsabas = \"son of Sabas\"</p><ol><li>the surname of a certain Joseph (<a class='bible' href='#b44.1.23'>Act 1:23</a>)</li><li>the surname of a certain Judas (<a class='bible' href='#b44.15.22'>Act 15:22</a>)</li></ol>","xlit":"Barsabâs"},"G2101":{"derivation":"from G2095 (εὖ) and G701 (ἀρεστός);","strongs_def":" fully agreeable","kjv_def":"acceptable(-ted), wellpleasing","lemma":"εὐάρεστος","translit":"euárestos","pron":"yoo-ar'-es-tos","pos":"Adjective","thayer":"<ol><li>well pleasing, acceptable</li></ol>","xlit":"euárestos"},"G34":{"derivation":"from G71 (ἄγω) (compare G32 (ἄγγελος));","strongs_def":" a drove","kjv_def":"herd","translit":"agélē","lemma":"ἀγέλη","pron":"ag-el'-ay","pos":"Noun Feminine","thayer":"<ol><li>herd or oxen or cattle, a herd or company</li></ol>","xlit":"agélē"},"G3395":{"strongs_def":" a compound","derivation":"from G3396 (μίγνυμι);","lemma":"μίγμα","translit":"mígma","kjv_def":"mixture","pron":"mig'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been produced by a mixing, a mixture</li></ol>","xlit":"mígma"},"G2834":{"strongs_def":" Cnidus, a place in Asia Minor","derivation":"probably of foreign origin;","lemma":"Κνίδος","translit":"Knídos","kjv_def":"Cnidus","pron":"knee'-dos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cnidus or Gnidus = \"nettled\"</p><ol><li>a peninsula [now Cape Crio] and a city by the same name, situated at the extreme south west of the peninsula of Asia Minor, on a promontory now called Cape Crio, which projects between the islands of Cos and Rhodes</li></ol>","xlit":"Knídos"},"G3805":{"derivation":"from the same as G3804 (πάθημα);","strongs_def":" liable (i.e. doomed) to experience pain","kjv_def":"suffer","translit":"pathētós","lemma":"παθητός","pron":"path-ay-tos'","pos":"Adjective","thayer":"<ol><li>passible, endued with the capacity of suffering, capable of feeling</li><li>subject to the necessity of suffering, destined to suffer</li></ol>","xlit":"pathētós"},"G1962":{"kjv_def":"consent","lemma":"ἐπινεύω","translit":"epineúō","derivation":"from G1909 (ἐπί) and G3506 (νεύω);","strongs_def":" to nod at, i.e. (by implication) to assent","pron":"ep-een-yoo'-o","pos":"Verb","thayer":"<ol><li>to nod to</li><li>to express approval, to assent</li></ol>","xlit":"epineúō"},"G755":{"kjv_def":"governor (ruler) of the feast","lemma":"ἀρχιτρίκλινος","translit":"architríklinos","derivation":"from G746 (ἀρχή) and a compound of G5140 (τρεῖς) and G2827 (κλίνω) (a dinner-bed, because composed of three couches);","strongs_def":" director of the entertainment","pron":"ar-khee-tree'-klee-nos","pos":"Noun Masculine","thayer":"<ol><li>the superintendent of the dining room, a table master.</li></ol>","xlit":"architríklinos"},"G2733":{"strongs_def":"residence (properly, the condition; but by implication, the abode itself)","kjv_def":"habitation","lemma":"κατοικία","translit":"katoikía","pron":"kat-oy-kee'-ah","pos":"Noun Feminine","thayer":"<ol><li>dwelling, habitation</li><li>to cause to dwell, to send or bring into an abode</li><li>to give a dwelling to</li></ol>","xlit":"katoikía"},"G1008":{"lemma":"βοτάνη","translit":"botánē","kjv_def":"herb","strongs_def":" herbage (as if for grazing)","derivation":"from G1006 (βόσκω);","pron":"bot-an'-ay","pos":"Noun Feminine","thayer":"<ol><li>an herb fit for fodder, green herb, growing plant</li></ol>","xlit":"botánē"},"G249":{"derivation":"from G1 (Α) (as a negative particle) and G3056 (λόγος);","strongs_def":" irrational","kjv_def":"brute, unreasonable","translit":"álogos","lemma":"ἄλογος","pron":"al'-og-os","pos":"Adjective","thayer":"<ol><li>destitute of reason</li><li>contrary to reason, absurd</li></ol>","xlit":"álogos"},"G4419":{"lemma":"πτερύγιον","translit":"pterýgion","kjv_def":"pinnacle","strongs_def":" a winglet, i.e. (figuratively) extremity (top corner)","derivation":"neuter of a presumed derivative of G4420 (πτέρυξ);","pron":"pter-oog'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a wing, a little wing</li><li>any pointed extremity<ol type='a'><li>of fins of fishes</li><li>of part of a dress hanging down in the form of a wing</li><li>of the top of the temple at Jerusalem</li></ol></li></ol>","xlit":"pterýgion"},"G583":{"kjv_def":"tax, write","lemma":"ἀπογράφω","translit":"apográphō","derivation":"from G575 (ἀπό) and G1125 (γράφω);","strongs_def":" to write off (a copy or list), i.e. enrol","pron":"ap-og-raf'-o","pos":"Verb","thayer":"<ol><li>to write off, copy (from some pattern)</li><li>to enter in a register or records<ol type='a'><li>spec. to enter in public records the names of men, their property and income</li><li>to enrol</li></ol></li></ol>","xlit":"apográphō"},"G2807":{"derivation":"from G2808 (κλείω);","strongs_def":" a key (as shutting a lock), literally or figuratively","kjv_def":"key","lemma":"κλείς","translit":"kleís","pron":"klice","pos":"Noun Feminine","thayer":"<ol><li>a key<ol type='a'><li>since the keeper of the keys has the power to open and to shut</li><li>metaphorically in the NT to denote power and authority of various kinds</li></ol></li></ol>","xlit":"kleís"},"G3344":{"strongs_def":" to turn across, i.e. transmute or (figuratively) corrupt","derivation":"from G3326 (μετά) and G4762 (στρέφω);","translit":"metastréphō","lemma":"μεταστρέφω","kjv_def":"pervert, turn","pron":"met-as-tref'-o","pos":"Verb","thayer":"<ol><li>to turn around, turn around</li></ol>","xlit":"metastréphō"},"G4425":{"derivation":"from G4429 (πτύω);","strongs_def":" a winnowing-fork (as scattering like spittle)","kjv_def":"fan","lemma":"πτύον","translit":"ptýon","pron":"ptoo'-on","pos":"Noun Neuter","thayer":"<ol><li>a winnowing shovel</li></ol>","xlit":"ptýon"},"G2670":{"translit":"katapontízō","lemma":"καταποντίζω","kjv_def":"drown, sink","strongs_def":" to plunge down, i.e. submerge","derivation":"from G2596 (κατά) and a derivative of the same as G4195 (Πόντος);","pron":"kat-ap-on-tid'-zo","pos":"Verb","thayer":"<ol><li>to plunge or sink into the sea<ol type='a'><li>to sink, to go down</li><li>a grievous offender for the purpose of killing him, to drown</li></ol></li></ol>","xlit":"katapontízō"},"G3867":{"strongs_def":" to mispraise, i.e. recommend or advise (a different course)","derivation":"from G3844 (παρά) and G134 (αἰνέω);","lemma":"παραινέω","translit":"parainéō","kjv_def":"admonish, exhort","pron":"par-ahee-neh'-o","pos":"Verb","thayer":"<ol><li>to exhort, admonish</li></ol>","xlit":"parainéō"},"G959":{"lemma":"Βερνίκη","translit":"Berníkē","kjv_def":"Bernice","strongs_def":" victorious; Bernice, a member of the Herodian family","derivation":"from a provincial form of G5342 (φέρω) and G3529 (νίκη);","pron":"ber-nee'-kay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Bernice = \"bring victory\"</p><ol><li>the eldest daughter of Herod Agrippa I. <a class='bible' href='#b44.12.1'>Act 12:1</a> - She was first married to her uncle Herod, king of Chalcis, and after his death (A.D. 48) she lived under circumstances of great suspicion with her own brother, Agrippa II, in connection with whom she is mentioned as having visited Festus on his appointment as procurator of Judea.</li></ol>","xlit":"Berníkē"},"G151":{"derivation":"from G150 (αἰσχρός);","strongs_def":" shamefulness, i.e. obscenity","kjv_def":"filthiness","lemma":"αἰσχρότης","translit":"aischrótēs","pron":"ahee-skhrot'-ace","pos":"Noun Feminine","thayer":"<ol><li>obscenity, filthiness</li></ol>","xlit":"aischrótēs"},"G2522":{"kjv_def":"daily","translit":"kathēmerinós","lemma":"καθημερινός","derivation":"from G2596 (κατά) and G2250 (ἡμέρα);","strongs_def":" quotidian","pron":"kath-ay-mer-ee-nos'","pos":"Adjective","thayer":"<ol><li>daily</li></ol>","xlit":"kathēmerinós"},"G1096":{"strongs_def":" to cause to be (\"gen\"-erate), i.e. (reflexively) to become (come into being), used with great latitude (literal, figurative, intensive, etc.)","derivation":"a prolongation and middle voice form of a primary verb;","translit":"gínomai","lemma":"γίνομαι","kjv_def":"arise, be assembled, be(-come, -fall, -have self), be brought (to pass), (be) come (to pass), continue, be divided, draw, be ended, fall, be finished, follow, be found, be fulfilled, + God forbid, grow, happen, have, be kept, be made, be married, be ordained to be, partake, pass, be performed, be published, require, seem, be showed, X soon as it was, sound, be taken, be turned, use, wax, will, would, be wrought","pron":"ghin'-om-ahee","pos":"Verb","thayer":"<ol><li>to become, i.e. to come into existence, begin to be, receive being</li><li>to become, i.e. to come to pass, happen<ol type='a'><li>of events</li></ol><li>to arise, appear in history, come upon the stage<ol type='a'><li>of men appearing in public</li></ol><li>to be made, finished<ol type='a'><li>of miracles, to be performed, wrought</li></ol><li>to become, be made</li></ol>","xlit":"gínomai"},"G5456":{"translit":"phōnḗ","lemma":"φωνή","kjv_def":"noise, sound, voice","strongs_def":" a tone (articulate, bestial or artificial); by implication, an address (for any purpose), saying or language","derivation":"probably akin to G5316 (φαίνω) through the idea of disclosure;","pron":"fo-nay'","pos":"Noun Feminine","thayer":"<ol><li>a sound, a tone<ol type='a'><li>of inanimate things, as musical instruments</li></ol><li>a voice<ol type='a'><li>of the sound of uttered words</li></ol><li>speech<ol type='a'><li>of a language, tongue</li></ol></li></ol>","xlit":"phōnḗ"},"G646":{"derivation":"feminine of the same as G647 (ἀποστάσιον);","strongs_def":" defection from truth (properly, the state) (\"apostasy\")","kjv_def":"falling away, forsake","translit":"apostasía","lemma":"ἀποστασία","pron":"ap-os-tas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a falling away, defection, apostasy</li></ol>","xlit":"apostasía"},"G2429":{"kjv_def":"moisture","lemma":"ἱκμάς","translit":"hikmás","derivation":"of uncertain affinity;","strongs_def":" dampness","pron":"hik-mas'","pos":"Noun Feminine","thayer":"<ol><li>moisture</li></ol>","xlit":"hikmás"},"G657":{"strongs_def":" literally, to say adieu (by departing or dismissing); figuratively, to renounce","derivation":"middle voice from G575 (ἀπό) and G5021 (τάσσω);","lemma":"ἀποτάσσομαι","translit":"apotássomai","kjv_def":"bid farewell, forsake, take leave, send away","pron":"ap-ot-as'-som-ahee","pos":"Verb","thayer":"<ol><li>to set apart, separate<ol type='a'><li>to separate one's self, withdraw one's self from anyone<ol><li>to take leave of, bid farewell to</li></ol><li>to renounce, forsake</li></ol></li></ol>","xlit":"apotássomai"},"G4708":{"lemma":"σπουδαιοτέρως","translit":"spoudaiotérōs","kjv_def":"more carefully","strongs_def":" more speedily, i.e. sooner than otherwise","derivation":"adverb from G4707 (σπουδαιότερος);","pron":"spoo-dah-yot-er'-oce","pos":"Adverb","thayer":"<ol><li>hastily, with haste</li><li>diligently, earnestly</li></ol>","xlit":"spoudaiotérōs"},"G4458":{"derivation":"adverb from the base of G4225 (πού);","strongs_def":" an enclitic particle of indefiniteness of manner; somehow or anyhow; used only in composition","kjv_def":"haply, by any (some) means, perhaps","translit":"-pṓs","lemma":"-πώς","pron":"poce","thayer":"<ol><li>by any means, at all, perhaps</li></ol>","xlit":"-pṓs"},"G4783":{"kjv_def":"agreement","translit":"synkatáthesis","lemma":"συγκατάθεσις","derivation":"from G4784 (συγκατατίθεμαι);","strongs_def":" a deposition (of sentiment) in company with, i.e. (figuratively) accord with","pron":"soong-kat-ath'-es-is","pos":"Verb","thayer":"<ol><li>a putting together or joint deposit (of votes)<ol type='a'><li>hence approval, assent, agreement</li></ol></li></ol>","xlit":"synkatáthesis"},"G2474":{"strongs_def":" Israel (i.e. Jisrael), the adopted name of Jacob, including his descendants (literally or figuratively)","derivation":"of Hebrew origin (H03478);","lemma":"Ἰσραήλ","translit":"Israḗl","kjv_def":"Israel","pron":"is-rah-ale'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Israel = \"he shall be a prince of God\"</p><ol><li>the name given to the patriarch Jacob (and borne by him in addition to his former name)</li><li>the family or descendants of Israel, the nation of Israel</li><li>Christians, the Israel of God (<a class='bible' href='#b48.6.16'>Gal 6:16</a>), for not all those who draw their bodily descent from Israel are true Israelites, i.e. are those whom God pronounces to be Israelites and has chosen to salvation</li></ol>","xlit":"Israḗl"},"G1933":{"lemma":"ἐπιεικής","translit":"epieikḗs","kjv_def":"gentle, moderation, patient","strongs_def":" appropriate, i.e. (by implication) mild","derivation":"from G1909 (ἐπί) and G1503 (εἴκω);","pron":"ep-ee-i-kace'","pos":"Adjective","thayer":"<ol><li>seemingly, suitable</li><li>equitable, fair, mild, gentle</li></ol>","xlit":"epieikḗs"},"G1770":{"strongs_def":" to nod at, i.e. beckon or communicate by gesture","derivation":"from G1722 (ἐν) and G3506 (νεύω);","lemma":"ἐννεύω","translit":"enneúō","kjv_def":"make signs","pron":"en-nyoo'-o","pos":"Verb","thayer":"<ol><li>to nod to, signify or express by a nod or a sign</li></ol>","xlit":"enneúō"},"G2":{"kjv_def":"Aaron","lemma":"Ἀαρών","translit":"Aarṓn","derivation":"of Hebrew origin (H0175);","strongs_def":" Aaron, the brother of Moses","pron":"ah-ar-ohn'","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Aaron = \"light-bringer\"</p><ol><li>the brother of Moses, the first high priest of Israel and head of the whole priestly order</li></ol>","xlit":"Aarṓn"},"G385":{"translit":"anaspáō","lemma":"ἀνασπάω","kjv_def":"draw up, pull out","strongs_def":" to take up or extricate","derivation":"from G303 (ἀνά) and G4685 (σπάω);","pron":"an-as-pah'-o","pos":"Verb","thayer":"<ol><li>to draw up</li></ol>","xlit":"anaspáō"},"G1116":{"strongs_def":" Gomorrha (i.e. Amorah), a place near the Dead Sea","derivation":"of Hebrew origin (H06017);","translit":"Gómorrha","lemma":"Γόμοῤῥα","kjv_def":"Gomorrha","pron":"gom'-or-hrhah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gomorrha = \"submersion\"</p><ol><li>a city in eastern part of Judah that was destroyed when the Lord rained fire and brimstone on it; now covered by the Dead Sea</li></ol>","xlit":"Gómorrha"},"G171":{"strongs_def":" inopportunely","derivation":"adverb from the same as G170 (ἀκαιρέομαι);","translit":"akaírōs","lemma":"ἀκαίρως","kjv_def":"out of season","pron":"ak-ah'-ee-roce","pos":"Adverb","thayer":"<ol><li>unseasonable</li></ol>","xlit":"akaírōs"},"G2894":{"derivation":"of uncertain derivation;","strongs_def":" a (small) basket","kjv_def":"basket","lemma":"κόφινος","translit":"kóphinos","pron":"kof'-ee-nos","pos":"Noun Masculine","thayer":"<ol><li>a basket, wicker basket</li></ol>","xlit":"kóphinos"},"G1886":{"kjv_def":"habitation","lemma":"ἔπαυλις","translit":"épaulis","derivation":"from G1909 (ἐπί) and an equivalent of G833 (αὐλή);","strongs_def":" a hut over the head, i.e. a dwelling","pron":"ep'-ow-lis","pos":"Noun Feminine","thayer":"<ol><li>a farm</li><li>a dwelling</li></ol>","xlit":"épaulis"},"G4769":{"kjv_def":"pillar","translit":"stŷlos","lemma":"στῦλος","derivation":"from (to stiffen;","strongs_def":" properly akin to the base of G2476 (ἵστημι)); a post (\"style\"), i.e. (figuratively) support","pron":"stoo'-los","pos":"Noun Masculine","thayer":"<ol><li>a pillar</li><li>a column<ol type='a'><li>pillars of fire, i.e. flames rising like pillars</li></ol><li>a prop or support</li></ol>","xlit":"stŷlos"},"G4166":{"strongs_def":" a shepherd (literally or figuratively)","derivation":"of uncertain affinity;","translit":"poimḗn","lemma":"ποιμήν","kjv_def":"shepherd, pastor","pron":"poy-mane'","pos":"Noun Masculine","thayer":"<ol><li>a herdsman, especially a shepherd<ol type='a'><li>in the parable, he to whose care and control others have committed themselves, and whose precepts they follow</li></ol><li>metaphorically<ol type='a'><li>the presiding officer, manager, director, of any assembly: so of Christ the Head of the church<ol><li>of the overseers of the Christian assemblies</li><li>of kings and princes</li></ol></li></ol></li></ol>","xlit":"poimḗn"},"G3777":{"kjv_def":"neither, none, nor (yet), (no, yet) not, nothing","translit":"oúte","lemma":"οὔτε","derivation":"from G3756 (οὐ) and G5037 (τέ);","strongs_def":" not too, i.e. neither or nor; by analogy, not even","pron":"oo'-teh","pos":"Adverb","thayer":"<ol><li>neither, and not</li></ol>","xlit":"oúte"},"G1664":{"strongs_def":" God of majesty; Eliud, an Israelite","derivation":"of Hebrew origin (H0410 and H01935);","translit":"Elioúd","lemma":"Ἐλιούδ","kjv_def":"Eliud","pron":"el-ee-ood'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eliud = \"God his Praise\"</p><ol><li>the son of Achim in the genealogy of Christ. <a class='bible' href='#b40.1.15'>Mat 1:15</a></li></ol>","xlit":"Elioúd"},"G2113":{"translit":"euthydroméō","lemma":"εὐθυδρομέω","kjv_def":"(come) with a straight course","strongs_def":" to lay a straight course, i.e. sail direct","derivation":"from G2117 (εὐθύς) and G1408 (δρόμος);","pron":"yoo-thoo-drom-eh'-o","pos":"Verb","thayer":"<ol><li>to make a straight course, run a straight course</li></ol>","xlit":"euthydroméō"},"G3312":{"derivation":"from G3307 (μερίζω);","strongs_def":" an apportioner (administrator)","kjv_def":"divider","translit":"meristḗs","lemma":"μεριστής","pron":"mer-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>a divider<ol type='a'><li>of an inheritance</li></ol></li></ol>","xlit":"meristḗs"},"G4349":{"strongs_def":" a stumbling, i.e. (figuratively and concretely) occasion of sin","derivation":"from G4350 (προσκόπτω);","translit":"proskopḗ","lemma":"προσκοπή","kjv_def":"offence","pron":"pros-kop-ay'","pos":"Noun Feminine","thayer":"<ol><li>an occasion of stumbling</li><li>to do something which causes others to stumble<ol type='a'><li>i.e. leads them into error or sin</li></ol></li></ol>","xlit":"proskopḗ"},"G4116":{"derivation":"from G4111 (πλάσσω);","strongs_def":" spread out \"flat\" (\"plot\"), i.e. broad","kjv_def":"wide","lemma":"πλατύς","translit":"platýs","pron":"plat-oos'","pos":"Adjective","thayer":"<ol><li>broad</li></ol>","xlit":"platýs"},"G1531":{"derivation":"from G1519 (εἰς) and G4198 (πορεύομαι);","strongs_def":" to enter (literally or figuratively)","kjv_def":"come (enter) in, go into","translit":"eisporeúomai","lemma":"εἰσπορεύομαι","pron":"ice-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to go into, enter<ol type='a'><li>of persons</li><li>of things<ol><li>to be carried into or put into</li><li>as food into a mouth</li></ol></li></ol><li>metaphorically of affections entering the soul</li></ol>","xlit":"eisporeúomai"},"G5182":{"kjv_def":"trouble","lemma":"τυρβάζω","translit":"tyrbázō","derivation":"from (Latin turba, a crowd;","strongs_def":" akin to G2351 (θόρυβος)); to make \"turbid\", i.e. disturb","pron":"toor-bad'-zo","pos":"Verb","thayer":"<ol><li>disturb, trouble</li><li>to be troubled in mind, disquieted</li></ol>","xlit":"tyrbázō"},"G4647":{"lemma":"σκόλοψ","translit":"skólops","kjv_def":"thorn","strongs_def":" withered at the front, i.e. a point or prickle (figuratively, a bodily annoyance or disability)","derivation":"perhaps from the base of G4628 (σκέλος) and G3700 (ὀπτάνομαι);","pron":"skol'-ops","pos":"Noun Masculine","thayer":"<ol><li>a pointed piece of wood, a pale, a stake</li><li>a sharp stake, splinter</li></ol>","xlit":"skólops"},"G2486":{"kjv_def":"fish","lemma":"ἰχθύς","translit":"ichthýs","derivation":"of uncertain affinity;","strongs_def":" a fish","pron":"ikh-thoos'","pos":"Noun Masculine","thayer":"<ol><li>a fish</li></ol>","xlit":"ichthýs"},"G2284":{"kjv_def":"amaze, astonish","lemma":"θαμβέω","translit":"thambéō","derivation":"from G2285 (θάμβος);","strongs_def":" to stupefy (with surprise), i.e. astound","pron":"tham-beh'-o","pos":"Verb","thayer":"<ol><li>to be astonished</li><li>to astonish, terrify<ol type='a'><li>to be amazed</li><li>to be frightened</li></ol></li></ol>","xlit":"thambéō"},"G341":{"translit":"anakainóō","lemma":"ἀνακαινόω","kjv_def":"renew","strongs_def":" to renovate","derivation":"from G303 (ἀνά) and a derivative of G2537 (καινός);","pron":"an-ak-ahee-no'-o","pos":"Verb","thayer":"<ol><li>to cause to grow up, new, to make new<ol type='a'><li>new strength and vigour is given to one</li><li>to be changed into a new kind of life as opposed to the former corrupt state</li></ol></li></ol>","xlit":"anakainóō"},"G3949":{"translit":"parorgízō","lemma":"παροργίζω","kjv_def":"anger, provoke to wrath","strongs_def":" to anger alongside, i.e. enrage","derivation":"from G3844 (παρά) and G3710 (ὀργίζω);","pron":"par-org-id'-zo","pos":"Verb","thayer":"<ol><li>to rouse to wrath, to provoke, exasperate, anger</li></ol>","xlit":"parorgízō"},"G2385":{"derivation":"the same as G2384 (Ἰακώβ) Græcized;","strongs_def":" Jacobus, the name of three Israelites","kjv_def":"James","lemma":"Ἰάκωβος","translit":"Iákōbos","pron":"ee-ak'-o-bos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: James = \"supplanter\"</p><ol><li>son of Zebedee, an apostle and brother of the apostle John, commonly called James the greater or elder, slain by Herod, Acts 12</li><li>an apostle, son of Alphaeus, called the less</li><li>James the half-brother of Christ</li><li>an unknown James, father of the apostle Judas (?)</li></ol>","xlit":"Iákōbos"},"G4171":{"derivation":"from (to bustle);","strongs_def":" warfare (literally or figuratively; a single encounter or a series)","kjv_def":"battle, fight, war","translit":"pólemos","lemma":"πόλεμος","pron":"pol'-em-os","pos":"Noun Masculine","thayer":"<ol><li>a war</li><li>a fight, a battle</li><li>a dispute, strife, quarrel</li></ol>","xlit":"pólemos"},"G1867":{"strongs_def":" to applaud","derivation":"from G1909 (ἐπί) and G134 (αἰνέω);","translit":"epainéō","lemma":"ἐπαινέω","kjv_def":"commend, laud, praise","pron":"ep-ahee-neh'-o","pos":"Verb","thayer":"<ol><li>to approve, to praise</li></ol>","xlit":"epainéō"},"G2664":{"lemma":"καταπαύω","translit":"katapaúō","kjv_def":"cease, (give) rest(-rain)","strongs_def":" to settle down, i.e. (literally) to colonize, or (figuratively) to (cause to) desist","derivation":"from G2596 (κατά) and G3973 (παύω);","pron":"kat-ap-ow'-o","pos":"Verb","thayer":"<ol><li>to make quiet, to cause to be at rest, to grant rest<ol type='a'><li>to lead to a quiet abode</li><li>to still, restrain, to cause (one striving to do something) to desist</li></ol><li>to rest, take rest</li></ol>","xlit":"katapaúō"},"G961":{"kjv_def":"of Berea","translit":"Beroiaîos","lemma":"Βεροιαῖος","derivation":"from G960 (Βέροια);","strongs_def":" a Berœoean or native of Berœa","pron":"ber-oy-ah'-yos","pos":"Adjective","thayer":"<ol><li>a resident of Berea</li></ol>","xlit":"Beroiaîos"},"G606":{"lemma":"ἀπόκειμαι","translit":"apókeimai","kjv_def":"be appointed, (be) laid up","strongs_def":" to be reserved; figuratively, to await","derivation":"from G575 (ἀπό) and G2749 (κεῖμαι);","pron":"ap-ok'-i-mahee","pos":"Verb","thayer":"<ol><li>to be laid away, laid by, reserved</li><li>reserved for one, awaiting him</li></ol>","xlit":"apókeimai"},"G1380":{"lemma":"δοκέω","translit":"dokéō","kjv_def":"be accounted, (of own) please(-ure), be of reputation, seem (good), suppose, think, trow","strongs_def":" compare the base of G1166 (δεικνύω)) of the same meaning; to think; by implication, to seem (truthfully or uncertainly)","derivation":"a prolonged form of a primary verb, (used only in an alternate in certain tenses;","pron":"dok-eh'-o","pos":"Verb","thayer":"<ol><li>to be of opinion, think, suppose</li><li>to seem, to be accounted, reputed</li><li>it seems to me<ol type='a'><li>I think, judge: thus in question</li><li>it seems good to, pleased me, I determined</li></ol></li></ol>","xlit":"dokéō"},"G5041":{"strongs_def":" to be a child-bearer, i.e. parent (mother)","derivation":"from a compound of G5043 (τέκνον) and the base of G1096 (γίνομαι);","lemma":"τεκνογονέω","translit":"teknogonéō","kjv_def":"bear children","pron":"tek-nog-on-eh'-o","pos":"Verb","thayer":"<ol><li>beget or bear children</li></ol>","xlit":"teknogonéō"},"G4092":{"strongs_def":" to fire, i.e. burn (figuratively and passively, become inflamed with fever)","derivation":"a reduplicated and prolonged form of a primary ; which occurs only as an alternate in certain tenses);","lemma":"πίμπρημι","translit":"pímprēmi","kjv_def":"be (X should have) swollen","pron":"pim'-pray-mee","thayer":"<ol><li>to blow, to burn</li><li>to cause to swell, to render timid</li><li>to swell, become swollen<ol type='a'><li>of the parts of the body</li></ol></li></ol>","xlit":"pímprēmi"},"G140":{"kjv_def":"choose","lemma":"αἱρετίζω","translit":"hairetízō","derivation":"from a derivative of G138 (αἱρέομαι);","strongs_def":" to make a choice","pron":"hahee-ret-id'-zo","pos":"Verb","thayer":"<ol><li>to choose</li><li>to belong to a sect</li></ol>","xlit":"hairetízō"},"G280":{"derivation":"from G1 (Α) (as a negative particle) and G3358 (μέτρον);","strongs_def":" immoderate","kjv_def":"(thing) without measure","translit":"ámetros","lemma":"ἄμετρος","pron":"am'-et-ros","pos":"Adjective","thayer":"<ol><li>without measure, immense</li></ol>","xlit":"ámetros"},"G5540":{"derivation":"from G5530 (χράομαι);","strongs_def":" employment, i.e. (specially), sexual intercourse (as an occupation of the body)","kjv_def":"use","lemma":"χρῆσις","translit":"chrēsis","pron":"khray'-sis","pos":"Noun Feminine","thayer":"<ol><li>use<ol type='a'><li>of the sexual use of a woman</li></ol></li></ol>","xlit":"chrēsis"},"G3758":{"kjv_def":"ah","lemma":"οὐά","translit":"ouá","derivation":"a primary exclamation of surprise;","strongs_def":" \"ah\"","pron":"oo-ah'","thayer":"<ol><li>ah! ha! an interjection of wonder and amazement</li></ol>","xlit":"ouá"},"G297":{"derivation":"comparative of (around);","strongs_def":" (in plural) both","kjv_def":"both","translit":"amphóteros","lemma":"ἀμφότερος","pron":"am-fot'-er-os","pos":"Adjective","thayer":"<ol><li>both of two, both the one and the other</li></ol>","xlit":"amphóteros"},"G5461":{"strongs_def":" to shed rays, i.e. to shine or (transitively) to brighten up (literally or figuratively)","derivation":"from G5457 (φῶς);","lemma":"φωτίζω","translit":"phōtízō","kjv_def":"enlighten, illuminate, (bring to, give) light, make to see","pron":"fo-tid'-zo","pos":"Verb","thayer":"<ol><li>to give light, to shine</li><li>to enlighten, light up, illumine</li><li>to bring to light, render evident<ol type='a'><li>to cause something to exist and thus come to light and become clear to all</li></ol><li>to enlighten, spiritually, imbue with saving knowledge<ol type='a'><li>to instruct, to inform, teach</li><li>to give understanding to</li></ol></li></ol>","xlit":"phōtízō"},"G3585":{"strongs_def":" wooden","derivation":"from G3586 (ξύλον);","translit":"xýlinos","lemma":"ξύλινος","kjv_def":"of wood","pron":"xoo'-lin-os","pos":"Adjective","thayer":"<ol><li>wooden, made of wood</li></ol>","xlit":"xýlinos"},"G3629":{"kjv_def":"merciful, of tender mercy","translit":"oiktírmōn","lemma":"οἰκτίρμων","derivation":"from G3627 (οἰκτείρω);","strongs_def":" compassionate","pron":"oyk-tir'-mone","pos":"Adjective","thayer":"<ol><li>merciful</li></ol>","xlit":"oiktírmōn"},"G4704":{"translit":"spoudázō","lemma":"σπουδάζω","kjv_def":"do (give) diligence, be diligent (forward), endeavour, labour, study","strongs_def":" to use speed, i.e. to make effort, be prompt or earnest","derivation":"from G4710 (σπουδή);","pron":"spoo-dad'-zo","pos":"Verb","thayer":"<ol><li>to hasten, make haste</li><li>to exert one's self, endeavour, give diligence</li></ol>","xlit":"spoudázō"},"G3138":{"derivation":"of Latin origin;","strongs_def":" Marcus, a Christian","kjv_def":"Marcus, Mark","translit":"Márkos","lemma":"Μάρκος","pron":"mar'-kos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mark = \"a defense\"</p><ol><li>an evangelist, the author of the Gospel of Mark. Marcus was his Latin surname, his Jewish name was John. He was a cousin of Barnabas and a companion of Paul in some of his missionary journeys</li></ol>","xlit":"Márkos"},"G1447":{"strongs_def":" Hebraistically or in the Jewish (Chaldee) language","derivation":"adverb from G1446 (Ἑβραΐς);","translit":"Hebraïstí","lemma":"Ἑβραϊστί","kjv_def":"in (the) Hebrew (tongue)","pron":"heb-rah-is-tee'","pos":"Adverb","thayer":"<ol><li>in Hebrew, i.e. in Chaldee</li></ol>","xlit":"Hebraïstí"},"G2972":{"kjv_def":"Cos","translit":"Kṓs","lemma":"Κώς","derivation":"of uncertain origin;","strongs_def":" Cos, an island in the Mediterranean","pron":"koce","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Coos = \"a public prison\"</p><ol><li>a small island of the Aegean Sea, over against the cities of Cnidus and Halicarnassus, celebrated for its fertility and especially for its abundance of wine and corn</li></ol>","xlit":"Kṓs"},"G4796":{"lemma":"συγχαίρω","translit":"synchaírō","kjv_def":"rejoice in (with)","strongs_def":" to sympathize in gladness, congratulate","derivation":"from G4862 (σύν) and G5463 (χαίρω);","pron":"soong-khah'-ee-ro","pos":"Verb","thayer":"<ol><li>to rejoice with, take part in another's joy</li><li>to rejoice together, to congratulate</li></ol>","xlit":"synchaírō"},"G4712":{"kjv_def":"furlong, race","lemma":"στάδιον","translit":"stádion","derivation":"from the base of G2476 (ἵστημι) (as fixed);","strongs_def":" a stade or certain measure of distance; by implication, a stadium or race-course","pron":"stad'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a space or distance of about 600 feet (185 m)</li><li>a race course<ol type='a'><li>place in which contests in running were held, the one who outstripped the rest and reached the goal first, receiving the prize. Courses of this description were found in most of the larger Greek cities, and were like that at Olympia, 600 Greek feet in length</li></ol></li></ol>","xlit":"stádion"},"G2969":{"kjv_def":"town","translit":"kōmópolis","lemma":"κωμόπολις","derivation":"from G2968 (κώμη) and G4172 (πόλις);","strongs_def":" an unwalled city","pron":"ko-mop'-ol-is","pos":"Noun Feminine","thayer":"<ol><li>a village approximating in size and number of inhabitants to a city, a village city, a town</li></ol>","xlit":"kōmópolis"},"G4703":{"strongs_def":" a scattering (of seed), i.e. (concretely) seed (as sown)","derivation":"from G4687 (σπείρω);","translit":"spóros","lemma":"σπόρος","kjv_def":"seed (X sown)","pron":"spro'-os","pos":"Noun Masculine","thayer":"<ol><li>a sowing</li><li>seed (used in sowing)</li></ol>","xlit":"spóros"},"G130":{"derivation":"from G129 (αἷμα) and a derivative of G1632 (ἐκχέω);","strongs_def":" an effusion of blood","kjv_def":"shedding of blood","lemma":"αἱματεκχυσία","translit":"haimatekchysía","pron":"hahee-mat-ek-khoo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>shedding of blood</li></ol>","xlit":"haimatekchysía"},"G2155":{"strongs_def":" well compassioned, i.e. sympathetic","derivation":"from G2095 (εὖ) and G4698 (σπλάγχνον);","translit":"eúsplanchnos","lemma":"εὔσπλαγχνος","kjv_def":"pitiful, tender-hearted","pron":"yoo'-splangkh-nos","pos":"Adjective","thayer":"<ol><li>having strong bowels</li><li>compassionate, tender hearted</li></ol>","xlit":"eúsplanchnos"},"G5573":{"derivation":"from G5571 (ψευδής) and G3004 (λέγω);","strongs_def":" mendacious, i.e. promulgating erroneous Christian doctrine","kjv_def":"speaking lies","translit":"pseudológos","lemma":"ψευδολόγος","pron":"psyoo-dol-og'-os","pos":"Adjective","thayer":"<ol><li>speaking (teaching) falsely, speaking lies</li></ol>","xlit":"pseudológos"},"G4870":{"strongs_def":" to accompany","derivation":"from G4862 (σύν) and G190 (ἀκολουθέω);","translit":"synakolouthéō","lemma":"συνακολουθέω","kjv_def":"follow","pron":"soon-ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow together with others, to accompany</li></ol>","xlit":"synakolouthéō"},"G3950":{"kjv_def":"wrath","lemma":"παροργισμός","translit":"parorgismós","derivation":"from G3949 (παροργίζω);","strongs_def":" rage","pron":"par-org-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>indignation, wrath, exasperation</li></ol>","xlit":"parorgismós"},"G4846":{"lemma":"συμπνίγω","translit":"sympnígō","kjv_def":"choke, throng","strongs_def":" to strangle completely, i.e. (literally) to drown, or (figuratively) to crowd","derivation":"from G4862 (σύν) and G4155 (πνίγω);","pron":"soom-pnee'-go","pos":"Verb","thayer":"<ol><li>to choke utterly<ol type='a'><li>metaphorically the seed of the divine word sown in the mind</li><li>to press round or throng one so as almost to suffocate him</li></ol></li></ol>","xlit":"sympnígō"},"G2585":{"lemma":"καπηλεύω","translit":"kapēleúō","kjv_def":"corrupt","strongs_def":" to retail, i.e. (by implication) to adulterate (figuratively)","derivation":"from (a huckster);","pron":"kap-ale-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a retailer, to peddle</li><li>to make money by selling anything<ol type='a'><li>to get sordid gain by dealing in anything, to do a thing for base gain</li><li>to trade in the word of God<ol><li>to try to get base gain by teaching divine truth</li></ol><li>to corrupt, to adulterate<ol><li>peddlers were in the habit of adulterating their commodities for the sake of gain</li></ol></li></ol></li></ol>","xlit":"kapēleúō"},"G695":{"translit":"argyrokópos","lemma":"ἀργυροκόπος","kjv_def":"silversmith","strongs_def":" a beater (i.e. worker) of silver","derivation":"from G696 (ἄργυρος) and G2875 (κόπτω);","pron":"ar-goo-rok-op'-os","pos":"Noun Masculine","thayer":"<ol><li>a silversmith</li></ol>","xlit":"argyrokópos"},"G4962":{"strongs_def":" to twist together, i.e. collect (a bundle, a crowd)","derivation":"from G4862 (σύν) and G4762 (στρέφω);","lemma":"συστρέφω","translit":"systréphō","kjv_def":"gather","pron":"soos-tref'-o","pos":"Verb","thayer":"<ol><li>to twist together, roll together</li><li>to collect, combine, unite<ol type='a'><li>of men, to (gather themselves together) assemble</li></ol></li></ol>","xlit":"systréphō"},"G2446":{"derivation":"of Hebrew origin (H03383);","strongs_def":" the Jordanes (i.e. Jarden), a river of Palestine","kjv_def":"Jordan","lemma":"Ἰορδάνης","translit":"Iordánēs","pron":"ee-or-dan'-ace","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Jordan = \"the descender\"</p><ol><li>the one river of Palestine, has its course of little more than 200 miles (300 km), from the roots of Anti-Lebanon to the head of the Dead Sea.</li></ol>","xlit":"Iordánēs"},"G5241":{"derivation":"from G5228 (ὑπέρ) and G1793 (ἐντυγχάνω);","strongs_def":" to intercede in behalf of","kjv_def":"make intercession for","lemma":"ὑπερεντυγχάνω","translit":"hyperentynchánō","pron":"hoop-er-en-toong-khan'-o","pos":"Verb","thayer":"<ol><li>to intercede for one</li></ol>","xlit":"hyperentynchánō"},"G3648":{"translit":"holóklēros","lemma":"ὁλόκληρος","kjv_def":"entire, whole","strongs_def":" complete in every part, i.e. perfectly sound (in body)","derivation":"from G3650 (ὅλος) and G2819 (κλῆρος);","pron":"hol'-ok'-lay-ros","pos":"Adjective","thayer":"<ol><li>complete in all its parts, in no part wanting or unsound, complete, entire, whole<ol type='a'><li>of a body without blemish or defect, whether of a priest or of a victim</li><li>free from sin, faultless</li><li>complete in all respects, consummate</li></ol></li></ol>","xlit":"holóklēros"},"G3601":{"lemma":"ὀδύνη","translit":"odýnē","kjv_def":"sorrow","strongs_def":" grief (as dejecting)","derivation":"from G1416 (δύνω);","pron":"od-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>consuming grief, pain, sorrow</li></ol>","xlit":"odýnē"},"G4674":{"kjv_def":"thine (own), thy (friend)","lemma":"σός","translit":"sós","derivation":"from G4771 (σύ);","strongs_def":" thine","pron":"sos","thayer":"<ol><li>thy, thine</li></ol>","xlit":"sós"},"G3469":{"strongs_def":" to carp at, i.e. censure (discredit)","derivation":"from G3470 (μῶμος);","lemma":"μωμάομαι","translit":"mōmáomai","kjv_def":"blame","pron":"mo-mah'-om-ahee","pos":"Verb","thayer":"<ol><li>to blame, find fault with, mock at</li></ol>","xlit":"mōmáomai"},"G675":{"derivation":"of Latin origin;","strongs_def":" (in the genitive, i.e. possessive case) of Appius, the name of a Roman","kjv_def":"Appii","lemma":"Ἄππιος","translit":"Áppios","pron":"ap'-pee-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Appius = \"the market place of Appius\"</p><ol><li>a town in Italy, 39 miles (60 km) from Rome on the Appian Way</li></ol>","xlit":"Áppios"},"G4991":{"derivation":"feminine of a derivative of G4990 (σωτήρ) as (properly, abstract) noun;","strongs_def":" rescue or safety (physically or morally)","kjv_def":"deliver, health, salvation, save, saving","translit":"sōtēría","lemma":"σωτηρία","pron":"so-tay-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>deliverance, preservation, safety, salvation<ol type='a'><li>deliverance from the molestation of enemies</li><li>in an ethical sense, that which concludes to the souls safety or salvation<ol><li>of Messianic salvation</li></ol></li></ol><li>salvation as the present possession of all true Christians</li><li>future salvation, the sum of benefits and blessings which the Christians, redeemed from all earthly ills, will enjoy after the visible return of Christ from heaven in the consummated and eternal kingdom of God.</li></ol>","xlit":"sōtēría"},"G3675":{"kjv_def":"of one mind","lemma":"ὁμόφρων","translit":"homóphrōn","derivation":"from the base of G3674 (ὁμοῦ) and G5424 (φρήν);","strongs_def":" like-minded, i.e. harmonious","pron":"hom-of'-rone","pos":"Adjective","thayer":"<ol><li>of one mind, concordant</li></ol>","xlit":"homóphrōn"},"G4100":{"derivation":"from G4102 (πίστις);","strongs_def":" to have faith (in, upon, or with respect to, a person or thing), i.e. credit; by implication, to entrust (especially one's spiritual well-being to Christ)","kjv_def":"believe(-r), commit (to trust), put in trust with","translit":"pisteúō","lemma":"πιστεύω","pron":"pist-yoo'-o","pos":"Verb","thayer":"<ol><li>to think to be true, to be persuaded of, to credit, place confidence in<ol type='a'><li>of the thing believed<ol><li>to credit, have confidence</li></ol><li>in a moral or religious reference<ol><li>used in the NT of the conviction and trust to which a man is impelled by a certain inner and higher prerogative and law of soul</li><li>to trust in Jesus or God as able to aid either in obtaining or in doing something: saving faith</li></ol></li></ol><li>to entrust a thing to one, i.e. his fidelity<ol type='a'><li>to be intrusted with a thing</li></ol></li></ol>","xlit":"pisteúō"},"G920":{"kjv_def":"Bar-jona","translit":"Bariōnâs","lemma":"Βαριωνᾶς","derivation":"of Chaldee origin (H01247 and H03124);","strongs_def":" son of Jonas (or Jonah); Bar-jonas, an Israelite","pron":"bar-ee-oo-nas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barjona = \"son of Jonah\"</p><ol><li>the surname of the apostle Peter</li></ol>","xlit":"Bariōnâs"},"G1307":{"strongs_def":" appearing through, i.e. \"diaphanous\"","derivation":"from G1223 (διά) and G5316 (φαίνω);","translit":"diaphanḗs","lemma":"διαφανής","kjv_def":"transparent","pron":"dee-af-an-ace'","pos":"Adjective","thayer":"<ol><li>transparent, translucent</li></ol>","xlit":"diaphanḗs"},"G3003":{"translit":"legeṓn","lemma":"λεγεών","kjv_def":"legion","strongs_def":" a \"legion\", i.e. Roman regiment (figuratively)","derivation":"of Latin origin;","pron":"leg-eh-ohn'","pos":"Noun Feminine","thayer":"<ol><li>a legion, a body of soldiers whose number differed at different times, and in the time of Augustus seems to have consisted of 6826 men (i.e. 6100 foot soldiers, and 726 horsemen)</li></ol>","xlit":"legeṓn"},"G5278":{"strongs_def":" to stay under (behind), i.e. remain; figuratively, to undergo, i.e. bear (trials), have fortitude, persevere","derivation":"from G5259 (ὑπό) and G3306 (μένω);","translit":"hypoménō","lemma":"ὑπομένω","kjv_def":"abide, endure, (take) patient(-ly), suffer, tarry behind","pron":"hoop-om-en'-o","pos":"Verb","thayer":"<ol><li>to remain<ol type='a'><li>to tarry behind</li></ol><li>to remain, i.e. abide, not recede or flee<ol type='a'><li>to preserve: under misfortunes and trials to hold fast to one's faith in Christ</li><li>to endure, bear bravely and calmly: ill treatments</li></ol></li></ol>","xlit":"hypoménō"},"G2812":{"derivation":"from G2813 (κλέπτω);","strongs_def":" a stealer (literally or figuratively)","kjv_def":"thief","translit":"kléptēs","lemma":"κλέπτης","pron":"klep'-tace","pos":"Noun Masculine","thayer":"<ol><li>an embezzler, pilferer<ol type='a'><li>the name is transferred to false teachers, who do not care to instruct men, but abuse their confidence for their own gain</li></ol></li></ol>","xlit":"kléptēs"},"G1457":{"translit":"enkainízō","lemma":"ἐγκαινίζω","kjv_def":"consecrate, dedicate","strongs_def":" to renew, i.e. inaugurate","derivation":"from G1456 (ἐγκαίνια);","pron":"eng-kahee-nid'-zo","pos":"Verb","thayer":"<ol><li>to renew</li><li>to do anew, again</li><li>to initiate, consecrate, dedication</li></ol>","xlit":"enkainízō"},"G5318":{"strongs_def":" shining, i.e. apparent (literally or figuratively); neuter (as adverb) publicly, externally","derivation":"from G5316 (φαίνω);","translit":"phanerós","lemma":"φανερός","kjv_def":"abroad, + appear, known, manifest, open (+ -ly), outward (+ -ly)","pron":"fan-er-os'","pos":"Adjective","thayer":"<ol><li>apparent, manifest, evident, known</li><li>manifest i.e to be plainly recognised or known</li></ol>","xlit":"phanerós"},"G716":{"lemma":"ἅρμα","translit":"hárma","kjv_def":"chariot","strongs_def":" a chariot (as raised or fitted together (compare G719 (ἁρμός)))","derivation":"probably from G142 (αἴρω) (perhaps with G1 (Α) (as a particle of union) prefixed);","pron":"har'-mah","pos":"Noun Neuter","thayer":"<ol><li>a chariot</li><li>of war chariots (i.e. armed with scythes)</li><li>chariots (drawn with many horses)</li></ol>","xlit":"hárma"},"G1801":{"derivation":"middle voice from a compound of G1722 (ἐν) and G3775 (οὖς);","strongs_def":" to take in one's ear, i.e. to listen","kjv_def":"hearken","lemma":"ἐνωτίζομαι","translit":"enōtízomai","pron":"en-o-tid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to receive into the ear, to give ear to, listen</li></ol>","xlit":"enōtízomai"},"G2391":{"lemma":"Ἰάρεδ","translit":"Iáred","kjv_def":"Jared","strongs_def":" Jared (i.e. Jered), an antediluvian","derivation":"of Hebrew origin (H03382);","pron":"ee-ar'-ed","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jared = \"descent\"</p><ol><li>one of the antediluvian patriarchs, the father of Enoch</li></ol>","xlit":"Iáred"},"G4645":{"kjv_def":"harden","translit":"sklērýnō","lemma":"σκληρύνω","derivation":"from G4642 (σκληρός);","strongs_def":" to indurate, i.e. (figuratively) render stubborn","pron":"sklay-roo'-no","pos":"Verb","thayer":"<ol><li>to make hard, harden</li><li>metaphorically<ol type='a'><li>to render obstinate, stubborn</li><li>to be hardened</li><li>to become obstinate or stubborn</li></ol></li></ol>","xlit":"sklērýnō"},"G5299":{"derivation":"from a compound of G5259 (ὑπό) and a derivative of G3700 (ὀπτάνομαι);","strongs_def":" to hit under the eye (buffet or disable an antagonist as a pugilist), i.e. (figuratively) to tease or annoy (into compliance), subdue (one's passions)","kjv_def":"keep under, weary","lemma":"ὑπωπιάζω","translit":"hypōpiázō","pron":"hoop-o-pee-ad'-zo","pos":"Verb","thayer":"<ol><li>to beat black and blue, to smite so as to cause bruises and livid spots<ol type='a'><li>like a boxer one buffets his body, handle it roughly, discipline by hardships</li></ol><li>metaphorically<ol type='a'><li>to give one intolerable annoyance<ol><li>beat one out, wear one out</li></ol><li>by entreaties</li></ol><li>that part of the face that is under the eyes</li></ol>","xlit":"hypōpiázō"},"G3313":{"lemma":"μέρος","translit":"méros","kjv_def":"behalf, course, coast, craft, particular (+ -ly), part (+ -ly), piece, portion, respect, side, some sort(-what)","strongs_def":" a division or share (literally or figuratively, in a wide application)","derivation":"from an obsolete but more primary form of (to get as a section or allotment);","pron":"mer'-os","pos":"Noun Neuter","thayer":"<ol><li>a part<ol type='a'><li>a part due or assigned to one</li><li>lot, destiny</li></ol><li>one of the constituent parts of a whole<ol type='a'><li>in part, partly, in a measure, to some degree, as respects a part, severally, individually</li><li>any particular, in regard to this, in this respect</li></ol></li></ol>","xlit":"méros"},"G3105":{"derivation":"middle voice from a primary (to long for;","strongs_def":" through the idea of insensate craving); to rave as a \"maniac\"","kjv_def":"be beside self (mad)","translit":"maínomai","lemma":"μαίνομαι","pron":"mah'-ee-nom-ahee","pos":"Verb","thayer":"<ol><li>to be mad, to rave<ol type='a'><li>of one who so speaks that he seems not to be in his right mind</li></ol></li></ol>","xlit":"maínomai"},"G4354":{"lemma":"προσλαλέω","translit":"proslaléō","kjv_def":"speak to (with)","strongs_def":" to talk to, i.e. converse with","derivation":"from G4314 (πρός) and G2980 (λαλέω);","pron":"pros-lal-eh'-o","pos":"Verb","thayer":"<ol><li>to speak to</li></ol>","xlit":"proslaléō"},"G2092":{"kjv_def":"prepared, (made) ready(-iness, to our hand)","lemma":"ἕτοιμος","translit":"hétoimos","derivation":"from an old noun (fitness);","strongs_def":" adjusted, i.e. ready","pron":"het-oy'-mos","pos":"Adjective","thayer":"<ol><li>prepare ready<ol type='a'><li>of things<ol><li>ready at hand</li><li>opportune, seasonable</li></ol><li>of persons<ol><li>ready prepared<ol type='a'><li>to do something</li><li>to receive one coming</li></ol></li></ol></li></ol></li></ol>","xlit":"hétoimos"},"G4035":{"strongs_def":" to leave all around, i.e. (passively) survive","derivation":"from G4012 (περί) and G3007 (λείπω);","lemma":"περιλείπω","translit":"perileípō","kjv_def":"remain","pron":"per-ee-li'-po","pos":"Verb","thayer":"<ol><li>to leave over</li><li>to remain over, to survive</li></ol>","xlit":"perileípō"},"G2682":{"translit":"kataskḗnōsis","lemma":"κατασκήνωσις","kjv_def":"nest","strongs_def":" an encamping, i.e. (figuratively) a perch","derivation":"from G2681 (κατασκηνόω);","pron":"kat-as-kay'-no-sis","pos":"Noun Neuter","thayer":"<ol><li>the pitching of tents, encamping</li><li>place of tarrying, encampment, abode<ol type='a'><li>of the nest of birds</li></ol></li></ol>","xlit":"kataskḗnōsis"},"G3538":{"lemma":"νίπτω","translit":"níptō","kjv_def":"wash","strongs_def":"to cleanse (especially the hands or the feet or the face); ceremonially, to perform ablution","pron":"nip'-to","pos":"Verb","thayer":"<ol><li>to wash</li><li>to wash one's self</li></ol>","xlit":"níptō"},"G747":{"derivation":"from G746 (ἀρχή) and G71 (ἄγω);","strongs_def":" a chief leader","kjv_def":"author, captain, prince","translit":"archēgós","lemma":"ἀρχηγός","pron":"ar-khay-gos'","pos":"Adjective","thayer":"<ol><li>the chief leader, prince<ol type='a'><li>of Christ</li></ol><li>one that takes the lead in any thing and thus affords an example, a predecessor in a matter, pioneer</li><li>the author</li></ol>","xlit":"archēgós"},"G5026":{"lemma":"ταύτῃ","translit":"taútēi","kjv_def":"her, + hereof, it, that, + thereby, the (same), this (same)","strongs_def":" (towards or of) this","derivation":"dative case, accusative case and genitive case respectively of the feminine singular of G3778 (οὗτος);","pron":"tow'-tay","thayer":"<ol><li>this, that, the same, see 3778</li></ol>","xlit":"taútēi"},"G3664":{"kjv_def":"like, + manner","translit":"hómoios","lemma":"ὅμοιος","derivation":"from the base of G3674 (ὁμοῦ);","strongs_def":" similar (in appearance or character)","pron":"hom'-oy-os","pos":"Adjective","thayer":"<ol><li>like, similar, resembling<ol type='a'><li>like: i.e. resembling</li><li>like: i.e. corresponding to a thing</li></ol></li></ol>","xlit":"hómoios"},"G3753":{"lemma":"ὅτε","translit":"hóte","kjv_def":"after (that), as soon as, that, when, while","strongs_def":" at which (thing) too, i.e. when","derivation":"from G3739 (ὅς) and G5037 (τέ);","pron":"hot'-eh","thayer":"<ol><li>when whenever, while, as long as</li></ol>","xlit":"hóte"},"G3167":{"strongs_def":" magnificent, i.e. (neuter, plural as noun) a conspicuous favor, or (subjectively) perfection","derivation":"from G3173 (μέγας);","lemma":"μεγαλεῖος","translit":"megaleîos","kjv_def":"great things, wonderful works","pron":"meg-al-i'-os","pos":"Adjective","thayer":"<ol><li>magnificent, excellent, splendid, wonderful</li></ol>","xlit":"megaleîos"},"G2910":{"lemma":"κρεμάννυμι","translit":"kremánnymi","kjv_def":"hang","strongs_def":" to hang","derivation":"a prolonged form of a primary verb;","pron":"krem-an'-noo-mee","pos":"Verb","thayer":"<ol><li>to hang up, suspend</li><li>to be suspended, to hang<ol type='a'><li>used of one hanging on a cross</li><li>used of the Law and the Prophets, they is summed up or hanging on two precepts</li></ol></li></ol>","xlit":"kremánnymi"},"G429":{"strongs_def":" to find out","derivation":"from G303 (ἀνά) and G2147 (εὑρίσκω);","lemma":"ἀνευρίσκω","translit":"aneurískō","kjv_def":"find","pron":"an-yoo-ris'-ko","pos":"Verb","thayer":"<ol><li>to find out by search</li></ol>","xlit":"aneurískō"},"G1761":{"kjv_def":"device, thought","translit":"enthýmēsis","lemma":"ἐνθύμησις","derivation":"from G1760 (ἐνθυμέομαι);","strongs_def":" deliberation","pron":"en-thoo'-may-sis","pos":"Noun Feminine","thayer":"<ol><li>a thinking, consideration</li><li>thoughts</li></ol>","xlit":"enthýmēsis"},"G3821":{"strongs_def":" antiquatedness","derivation":"from G3820 (παλαιός);","translit":"palaiótēs","lemma":"παλαιότης","kjv_def":"oldness","pron":"pal-ah-yot'-ace","pos":"Noun Feminine","thayer":"<ol><li>oldness: the old state of life controlled by 'the letter'</li></ol>","xlit":"palaiótēs"},"G3145":{"derivation":"from a primary (to handle or squeeze);","strongs_def":" to chew","kjv_def":"gnaw","translit":"massáomai","lemma":"μασσάομαι","pron":"mas-sah'-om-ahee","pos":"Verb","thayer":"<ol><li>to chew, consume, eat, devour</li></ol>","xlit":"massáomai"},"G2708":{"strongs_def":" to pour down (out)","derivation":"from G2596 (κατά) and cheo (to pour);","lemma":"καταχέω","translit":"katachéō","kjv_def":"pour","pron":"kat-akh-eh'-o","pos":"Verb","thayer":"<ol><li>to pour down upon</li><li>pour over, pour upon</li></ol>","xlit":"katachéō"},"G5219":{"strongs_def":" to hear under (as a subordinate), i.e. to listen attentively; by implication, to heed or conform to a command or authority","derivation":"from G5259 (ὑπό) and G191 (ἀκούω);","lemma":"ὑπακούω","translit":"hypakoúō","kjv_def":"hearken, be obedient to, obey","pron":"hoop-ak-oo'-o","pos":"Verb","thayer":"<ol><li>to listen, to harken<ol type='a'><li>of one who on the knock at the door comes to listen who it is, (the duty of a porter)</li></ol><li>to harken to a command<ol type='a'><li>to obey, be obedient to, submit to</li></ol></li></ol>","xlit":"hypakoúō"},"G2157":{"lemma":"εὐσχημοσύνη","translit":"euschēmosýnē","kjv_def":"comeliness","strongs_def":" decorousness","derivation":"from G2158 (εὐσχήμων);","pron":"yoo-skhay-mos-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>charm or elegance of figure, external beauty, decorum, modesty, seemliness<ol type='a'><li>of external charm, comeliness</li></ol></li></ol>","xlit":"euschēmosýnē"},"G5617":{"strongs_def":" Hosee (i.e. Hoshea), an Israelite","derivation":"of Hebrew origin (H01954);","lemma":"Ὡσηέ","translit":"Hōsēé","kjv_def":"Osee","pron":"ho-say-eh'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Hosea = \"salvation\"</p><ol><li>the well known Hebrew prophet, son of Beeri and contemporary with Isaiah</li></ol>","xlit":"Hōsēé"},"G4360":{"kjv_def":"be grieved at","lemma":"προσοχθίζω","translit":"prosochthízō","derivation":"from G4314 (πρός) and a form of (to be vexed with something irksome);","strongs_def":" to feel indignant at","pron":"pros-okh-thid'-zo","pos":"Verb","thayer":"<ol><li>to be wroth or displeased with</li><li>to loathe</li><li>to spew out</li><li>to be disgusted with</li></ol>","xlit":"prosochthízō"},"G3075":{"strongs_def":" properly, to soil, i.e. (figuratively) insult (maltreat)","derivation":"middle voice from a probably derivative of G3089 (λύω) (meaning filth);","lemma":"λυμαίνομαι","translit":"lymaínomai","kjv_def":"make havock of","pron":"loo-mah'-ee-nom-ahee","pos":"Verb","thayer":"<ol><li>to affix a stigma to, to dishonour, spot, defile</li><li>to treat shamefully or with injury, to ravage, devastate, ruin</li></ol>","xlit":"lymaínomai"},"G2001":{"lemma":"ἐπισχύω","translit":"epischýō","kjv_def":"be the more fierce","strongs_def":" to avail further, i.e. (figuratively) insist stoutly","derivation":"from G1909 (ἐπί) and G2480 (ἰσχύω);","pron":"ep-is-khoo'-o","pos":"Verb","thayer":"<ol><li>to give additional strength, to make stronger</li><li>to receive greater strength, grow stronger</li></ol>","xlit":"epischýō"},"G3409":{"derivation":"from G3408 (μισθός);","strongs_def":" to let out for wages, i.e. (middle voice) to hire","kjv_def":"hire","lemma":"μισθόω","translit":"misthóō","pron":"mis-tho'-o","pos":"Verb","thayer":"<ol><li>to let out for hire</li><li>to hire</li></ol>","xlit":"misthóō"},"G2110":{"kjv_def":"benefactor","lemma":"εὐεργέτης","translit":"euergétēs","derivation":"from G2095 (εὖ) and the base of G2041 (ἔργον);","strongs_def":" a worker of good, i.e. (specially) a philanthropist","pron":"yoo-erg-et'-ace","pos":"Noun Masculine","thayer":"<ol><li>benefactor</li><li>a title of honour, conferred on such as had done their country service, and upon princes, equivalent to Soter, Pater Patriae</li></ol>","xlit":"euergétēs"},"G608":{"translit":"apokleíō","lemma":"ἀποκλείω","kjv_def":"shut up","strongs_def":" to close fully","derivation":"from G575 (ἀπό) and G2808 (κλείω);","pron":"ap-ok-li'-o","pos":"Verb","thayer":"<ol><li>to shut up</li></ol>","xlit":"apokleíō"},"G812":{"derivation":"from G813 (ἄτακτος);","strongs_def":" to be (i.e. act) irregular","kjv_def":"behave self disorderly","lemma":"ἀτακτέω","translit":"ataktéō","pron":"at-ak-teh'-o","pos":"Verb","thayer":"<ol><li>to be disorderly<ol type='a'><li>of soldiers marching out of order or quitting ranks</li><li>to be neglectful of duty, to be lawless</li><li>to lead a disorderly life</li></ol></li></ol>","xlit":"ataktéō"},"G454":{"strongs_def":" stupidity; by implication, rage","derivation":"from a compound of G1 (Α) (as a negative particle) and G3563 (νοῦς);","translit":"ánoia","lemma":"ἄνοια","kjv_def":"folly, madness","pron":"an'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>want of understanding, folly</li><li>madness expressing itself in rage</li></ol>","xlit":"ánoia"},"G4310":{"kjv_def":"suffer before","translit":"propáschō","lemma":"προπάσχω","derivation":"from G4253 (πρό) and G3958 (πάσχω);","strongs_def":" to undergo hardship previously","pron":"prop-as'-kho","pos":"Verb","thayer":"<ol><li>to suffer before</li></ol>","xlit":"propáschō"},"G3660":{"translit":"omnýō","lemma":"ὀμνύω","kjv_def":"swear","strongs_def":" to swear, i.e. take (or declare on) oath","derivation":"a prolonged form of a primary, but obsolete , for which another prolonged form is used in certain tenses;","pron":"om-noo'-o","pos":"Verb","thayer":"<ol><li>to swear</li><li>to affirm, promise, threaten, with an oath</li><li>in swearing to call a person or thing as witness, to invoke, swear by</li></ol>","xlit":"omnýō"},"G3955":{"lemma":"παῤῥησιάζομαι","translit":"parrhēsiázomai","kjv_def":"be (wax) bold, (preach, speak) boldly","strongs_def":" to be frank in utterance, or confident in spirit and demeanor","derivation":"middle voice from G3954 (παῤῥησία);","pron":"par-hray-see-ad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to use freedom in speaking, be free spoken<ol type='a'><li>to speak freely</li></ol><li>to grow confident, have boldness, show assurance, assume a bold bearing</li></ol>","xlit":"parrhēsiázomai"},"G437":{"derivation":"from G473 (ἀντί) and the middle voice of G3670 (ὁμολογέω);","strongs_def":" to confess in turn, i.e. respond in praise","kjv_def":"give thanks","lemma":"ἀνθομολογέομαι","translit":"anthomologéomai","pron":"anth-om-ol-og-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to reply by professing or by confessing</li><li>to agree mutually (in turn), to make a compact</li><li>to acknowledge in the presence of<ol type='a'><li>to give thanks</li></ol></li></ol>","xlit":"anthomologéomai"},"G282":{"translit":"amḗtōr","lemma":"ἀμήτωρ","kjv_def":"without mother","strongs_def":" motherless, i.e. of unknown maternity","derivation":"from G1 (Α) (as a negative particle) and G3384 (μήτηρ);","pron":"am-ay'-tore","pos":"Noun Masculine","thayer":"<ol><li>born without a mother</li><li>bereft of a mother</li><li>born of a base or unknown mother</li><li>unmotherly, not worthy of the name of mother</li></ol>","xlit":"amḗtōr"},"G4344":{"kjv_def":"pillow","lemma":"προσκεφάλαιον","translit":"proskephálaion","derivation":"neuter of a presumed compound of G4314 (πρός) and G2776 (κεφαλή);","strongs_def":" something for the head, i.e. a cushion","pron":"pros-kef-al'-ahee-on","pos":"Noun Neuter","thayer":"<ol><li>a pillow, cushion</li></ol>","xlit":"proskephálaion"},"G4213":{"kjv_def":"drink","translit":"pósis","lemma":"πόσις","derivation":"from the alternate of G4095 (πίνω);","strongs_def":" a drinking (the act), i.e. (concretely) a draught","pron":"pos'-is","pos":"Noun Feminine","thayer":"<ol><li>a drinking, drink</li></ol>","xlit":"pósis"},"G4689":{"lemma":"σπένδω","translit":"spéndō","kjv_def":"(be ready to) be offered","strongs_def":" to pour out as a libation, i.e. (figuratively) to devote (one's life or blood, as a sacrifice) (\"spend\")","derivation":"apparently a primary verb;","pron":"spen'-do","pos":"Verb","thayer":"<ol><li>to pour out as a drink offering, make a libation</li><li>in the NT to be offered as a libation</li><li>fig. used of one whose blood is poured out in a violent death for the cause of God</li></ol>","xlit":"spéndō"},"G2692":{"derivation":"from G2690 (καταστρέφω);","strongs_def":" an overturn (\"catastrophe\"), i.e. demolition; figuratively, apostasy","kjv_def":"overthrow, subverting","lemma":"καταστροφή","translit":"katastrophḗ","pron":"kat-as-trof-ay'","pos":"Noun Feminine","thayer":"<ol><li>overthrow, destruction<ol type='a'><li>of cities</li></ol><li>metaphorically of the extinction of a spirit of consecration</li></ol>","xlit":"katastrophḗ"},"G5608":{"strongs_def":" to purchase (synonymous with the earlier G4092 (πίμπρημι))","derivation":"middle voice from an apparently primary (a sum or price);","lemma":"ὠνέομαι","translit":"ōnéomai","kjv_def":" buy","pron":"o-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to buy</li></ol>","xlit":"ōnéomai"},"G1798":{"derivation":"from G1722 (ἐν) and G5258 (ὕπνος);","strongs_def":" something seen in sleep, i.e. a dream (vision in a dream)","kjv_def":"dream","translit":"enýpnion","lemma":"ἐνύπνιον","pron":"en-oop'-nee-on","pos":"Noun Neuter","thayer":"<ol><li>a dream</li></ol>","xlit":"enýpnion"},"G5043":{"kjv_def":"child, daughter, son","lemma":"τέκνον","translit":"téknon","derivation":"from the base of G5098 (τιμωρία);","strongs_def":" a child (as produced)","pron":"tek'-non","pos":"Noun Neuter","thayer":"<ol><li>offspring, children<ol type='a'><li>child</li><li>a male child, a son</li><li>metaphorically<ol><li>the name transferred to that intimate and reciprocal relationship formed between men by the bonds of love, friendship, trust, just as between parents and children</li><li>in affectionate address, such as patrons, helpers, teachers and the like employ: my child</li><li>in the NT, pupils or disciples are called children of their teachers, because the latter by their instruction nourish the minds of their pupils and mould their characters</li><li>children of God: in the OT of \"the people of Israel\" as especially dear to God, in the NT, in Paul's writings, all who are led by the Spirit of God and thus closely related to God</li><li>children of the devil: those who in thought and action are prompted by the devil, and so reflect his character</li></ol><li>metaphorically<ol><li>of anything who depends upon it, is possessed by a desire or affection for it, is addicted to it</li><li>one who is liable to any fate<ol type='a'><li>thus children of a city: it citizens and inhabitants</li></ol><li>the votaries of wisdom, those souls who have, as it were, been nurtured and moulded by wisdom</li><li>cursed children, exposed to a curse and doomed to God's wrath or penalty</li></ol></li></ol></li></ol>","xlit":"téknon"},"G4725":{"translit":"stémma","lemma":"στέμμα","kjv_def":"garland","strongs_def":" a wreath for show","derivation":"from the base of G4735 (στέφανος);","pron":"stem'-mah","pos":"Noun Neuter","thayer":"<ol><li>a fillet, a garland, put upon victims</li></ol>","xlit":"stémma"},"G558":{"derivation":"from G575 (ἀπό) and G1658 (ἐλεύθερος);","strongs_def":" one freed away, i.e. a freedman","kjv_def":"freeman","translit":"apeleútheros","lemma":"ἀπελεύθερος","pron":"ap-el-yoo'-ther-os","pos":"Noun Masculine","thayer":"<ol><li>a slave that has been released from servitude, a freeman</li></ol>","xlit":"apeleútheros"},"G436":{"kjv_def":"resist, withstand","translit":"anthístēmi","lemma":"ἀνθίστημι","derivation":"from G473 (ἀντί) and G2476 (ἵστημι);","strongs_def":" to stand against, i.e. oppose","pron":"anth-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to set one's self against, to withstand, resist, oppose</li><li>to set against</li></ol>","xlit":"anthístēmi"},"G4434":{"strongs_def":" akin to G4422 (πτοέω) and the alternate of G4098 (πίπτω)); a beggar (as cringing), i.e. pauper (strictly denoting absolute or public mendicancy, although also used in a qualified or relative sense; whereas G3993 (πένης) properly means only straitened circumstances in private), literally (often as noun) or figuratively (distressed)","derivation":"from (to crouch);","lemma":"πτωχός","translit":"ptōchós","kjv_def":"beggar(-ly), poor","pron":"pto-khos'","pos":"Adjective","thayer":"<ol><li>reduced to beggary, begging, asking alms</li><li>destitute of wealth, influence, position, honour<ol type='a'><li>lowly, afflicted, destitute of the Christian virtues and eternal riches</li><li>helpless, powerless to accomplish an end</li><li>poor, needy</li></ol><li>lacking in anything<ol type='a'><li>as respects their spirit<ol><li>destitute of wealth of learning and intellectual culture which the schools afford (men of this class most readily give themselves up to Christ's teaching and proved them selves fitted to lay hold of the heavenly treasure)</li></ol></li></ol></li></ol>","xlit":"ptōchós"},"G3595":{"translit":"hodēgós","lemma":"ὁδηγός","kjv_def":"guide, leader","strongs_def":" a conductor (literally or figuratively (teacher))","derivation":"from G3598 (ὁδός) and G2233 (ἡγέομαι);","pron":"hod-ayg-os'","pos":"Noun Masculine","thayer":"<ol><li>a leader of the way, a guide</li><li>a teacher of the ignorant and inexperienced</li></ol>","xlit":"hodēgós"},"G2275":{"kjv_def":"diminishing, fault","lemma":"ἥττημα","translit":"hḗttēma","derivation":"from G2274 (ἡττάω);","strongs_def":" a deterioration, i.e. (objectively) failure or (subjectively) loss","pron":"hayt'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>a diminution, decrease: i.e. defeat</li><li>loss, as respects to salvation</li></ol>","xlit":"hḗttēma"},"G5459":{"kjv_def":"day star","translit":"phōsphóros","lemma":"φωσφόρος","derivation":"from G5457 (φῶς) and G5342 (φέρω);","strongs_def":" light-bearing (\"phosphorus\"), i.e. (specially), the morning-star (figuratively)","pron":"foce-for'-os","pos":"Adjective","thayer":"<ol><li>light bringing, giving light</li><li>the planet Venus, the morning star, day star</li><li>metaphorically Christ</li></ol>","xlit":"phōsphóros"},"G4969":{"strongs_def":" to butcher (especially an animal for food or in sacrifice) or (generally) to slaughter, or (specially), to maim (violently)","derivation":"a primary verb;","lemma":"σφάζω","translit":"spházō","kjv_def":"kill, slay, wound","pron":"sfad'-zo","pos":"Verb","thayer":"<ol><li>to slay, slaughter, butcher</li><li>to put to death by violence</li><li>mortally wounded</li></ol>","xlit":"spházō"},"G3523":{"lemma":"νῆστις","translit":"nēstis","kjv_def":"fasting","strongs_def":" not eating, i.e. abstinent from food (religiously)","derivation":"from the inseparable negative particle (not) and G2068 (ἐσθίω);","pron":"nace'-tis","pos":"Noun Feminine","thayer":"<ol><li>fasting, not having eaten</li></ol>","xlit":"nēstis"},"G1737":{"strongs_def":" to invest (with a garment)","derivation":"a prolonged form of G1746 (ἐνδύω);","lemma":"ἐνδιδύσκω","translit":"endidýskō","kjv_def":"clothe in, wear","pron":"en-did-oos'-ko","pos":"Verb","thayer":"<ol><li>to put on, clothe, to put on one's self, be clothed in</li></ol>","xlit":"endidýskō"},"G4336":{"derivation":"from G4314 (πρός) and G2172 (εὔχομαι);","strongs_def":" to pray to God, i.e. supplicate, worship","kjv_def":"pray (X earnestly, for), make prayer","translit":"proseúchomai","lemma":"προσεύχομαι","pron":"pros-yoo'-khom-ahee","pos":"Verb","thayer":"<ol><li>to offer prayers, to pray</li></ol>","xlit":"proseúchomai"},"G2131":{"derivation":"from G2095 (εὖ) and G3529 (νίκη);","strongs_def":" victorious; Eunice, a Jewess","kjv_def":"Eunice","lemma":"Εὐνίκη","translit":"Euníkē","pron":"yoo-nee'-kay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Eunice = \"good victory\"</p><ol><li>the mother of Timothy</li></ol>","xlit":"Euníkē"},"G4148":{"kjv_def":"en- (make) rich","translit":"ploutízō","lemma":"πλουτίζω","derivation":"from G4149 (πλοῦτος);","strongs_def":" to make wealthy (figuratively)","pron":"ploo-tid'-zo","pos":"Verb","thayer":"<ol><li>to make rich, enrich<ol type='a'><li>of spiritual riches</li></ol><li>to be richly furnished</li></ol>","xlit":"ploutízō"},"G2763":{"translit":"kerameús","lemma":"κεραμεύς","kjv_def":"potter","strongs_def":" a potter","derivation":"from G2766 (κέραμος);","pron":"ker-am-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a potter</li></ol>","xlit":"kerameús"},"G4765":{"strongs_def":" a little sparrow","derivation":"diminutive of (a sparrow);","translit":"strouthíon","lemma":"στρουθίον","kjv_def":"sparrow","pron":"stroo-thee'-on","pos":"Noun Neuter","thayer":"<ol><li>a little bird, especially of the sparrow sort, a sparrow</li></ol>","xlit":"strouthíon"},"G4584":{"derivation":"of Hebrew origin (H08096);","strongs_def":" Semei (i.e. Shimi), an Israelite","kjv_def":"Semei","lemma":"Σεμεΐ","translit":"Semeḯ","pron":"sem-eh-ee'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Shimei = \"harkeners: my report\"</p><ol><li>the father of Mattathias in the genealogy of Christ</li></ol>","xlit":"Semeḯ"},"G3565":{"translit":"nýmphē","lemma":"νύμφη","kjv_def":"bride, daughter in law","strongs_def":" compare Latin \"nupto,\" to marry); a young married woman (as veiled), including a betrothed girl; by implication, a son's wife","derivation":"from a primary but obsolete verb (to veil as a bride;","pos":"Noun Feminine","xlit":"nýmphē"},"G1859":{"strongs_def":" a festival","derivation":"of uncertain affinity;","lemma":"ἑορτή","translit":"heortḗ","kjv_def":"feast, holyday","pron":"heh-or-tay'","pos":"Noun Feminine","thayer":"<ol><li>a feast day, festival</li></ol>","xlit":"heortḗ"},"G666":{"derivation":"from the participle of G548 (ἄπειμι);","strongs_def":" a being away","kjv_def":"absence","translit":"apousía","lemma":"ἀπουσία","pron":"ap-oo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>absence</li></ol>","xlit":"apousía"},"G2076":{"kjv_def":"are, be(-long), call, X can(-not), come, consisteth, X dure for a while, + follow, X have, (that) is (to say), make, meaneth, X must needs, + profit, + remaineth, + wrestle","translit":"estí","lemma":"ἐστί","derivation":"third person singular present indicative of G1510 (εἰμί);","strongs_def":" he (she or it) is; also (with neuter plural) they are","pron":"es-tee'","pos":"Verb","thayer":"<ol><li>third person singular of \"to be\"</li></ol>","xlit":"estí"},"G2291":{"derivation":"of Hebrew origin (H08646);","strongs_def":" Thara (i.e. Terach), the father of Abraham","kjv_def":"Thara","lemma":"Θάρα","translit":"Thára","pron":"thar'-ah","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Terah = \"station\"</p><ol><li>the father of Abraham</li></ol>","xlit":"Thára"},"G2698":{"derivation":"from G2596 (κατά) and G5087 (τίθημι);","strongs_def":" to place down, i.e. deposit (literally or figuratively)","kjv_def":"do, lay, shew","translit":"katatíthēmi","lemma":"κατατίθημι","pron":"kat-at-ith'-ay-mee","pos":"Verb","thayer":"<ol><li>to lay down, deposit, lay up</li><li>to lay by or up for one's self, for future use</li><li>to lay up favour for one's self with any one, to gain favour with (to do something for one which may win favour)</li></ol>","xlit":"katatíthēmi"},"G1986":{"kjv_def":"become uncircumcised","lemma":"ἐπισπάομαι","translit":"epispáomai","derivation":"from G1909 (ἐπί) and G4685 (σπάω);","strongs_def":" to draw over, i.e. (with G203 (ἀκροβυστία) implied) efface the mark of circumcision (by recovering with the foreskin)","pron":"ep-ee-spah'-om-ahee","pos":"Verb","thayer":"<ol><li>to draw on (let him not draw on his foreskin)</li></ol>","xlit":"epispáomai"},"G4633":{"strongs_def":" a tent or cloth hut (literally or figuratively)","derivation":"apparently akin to G4632 (σκεῦος) and G4639 (σκιά);","translit":"skēnḗ","lemma":"σκηνή","kjv_def":"habitation, tabernacle","pron":"skay-nay'","pos":"Noun Feminine","thayer":"<ol><li>tent, tabernacle, (made of green boughs, or skins or other materials)</li><li>of that well known movable temple of God after the pattern of which the temple at Jerusalem was built</li></ol>","xlit":"skēnḗ"},"G5269":{"derivation":"from G5259 (ὑπό) and G2224 (ζώννυμι);","strongs_def":" to gird under, i.e. frap (a vessel with cables across the keel, sides and deck)","kjv_def":"undergirt","lemma":"ὑποζώννυμι","translit":"hypozṓnnymi","pron":"hoop-od-zone'-noo-mee","pos":"Verb","thayer":"<ol><li>to undergird<ol type='a'><li>to bind a ship together laterally: i.e. with girths or cables, to enable it to survive the force of waves and tempest</li></ol></li></ol>","xlit":"hypozṓnnymi"},"G4397":{"derivation":"from G4396 (προφήτης);","strongs_def":" pertaining to a foreteller (\"prophetic\")","kjv_def":"of prophecy, of the prophets","translit":"prophētikós","lemma":"προφητικός","pron":"prof-ay-tik-os'","pos":"Adjective","thayer":"<ol><li>proceeding from a prophet</li><li>prophetic</li></ol>","xlit":"prophētikós"},"G3767":{"lemma":"οὖν","translit":"oûn","kjv_def":"and (so, truly), but, now (then), so (likewise then), then, therefore, verily, wherefore","strongs_def":" (adverbially) certainly, or (conjunctionally) accordingly","derivation":"apparently a primary word;","pron":"oon","thayer":"<ol><li>then, therefore, accordingly, consequently, these things being so</li></ol>","xlit":"oûn"},"G2587":{"kjv_def":"Cappadocia","translit":"Kappadokía","lemma":"Καππαδοκία","derivation":"of foreign origin;","strongs_def":" Cappadocia, a region of Asia Minor","pron":"kap-pad-ok-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cappadocia = \"province of good horses\"</p><ol><li>a region in Asia Minor, bounded under the Roman empire on the north by Pontus, on the east by Armenia Minor, on the south by Cilicia and Commagene, on the west by Lycaonia and Galatia</li></ol>","xlit":"Kappadokía"},"G995":{"strongs_def":" a halloo, i.e. call (for aid, etc.)","derivation":"from G994 (βοάω);","lemma":"βοή","translit":"boḗ","kjv_def":"cry","pron":"bo-ay'","pos":"Noun Feminine","thayer":"<ol><li>a cry</li></ol>","xlit":"boḗ"},"G3082":{"derivation":"of uncertain origin;","strongs_def":" Lystra, a place in Asia Minor","kjv_def":"Lystra","lemma":"Λύστρα","translit":"Lýstra","pron":"loos'-trah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Lystra = \"ransoming\"</p><ol><li>a city in the eastern part of the great plain of Lycaonia</li></ol>","xlit":"Lýstra"},"G511":{"lemma":"ἀνώτερος","translit":"anṓteros","kjv_def":"above, higher","strongs_def":" upper, i.e. (neuter as adverb) to a more conspicuous place, in a former part of the book","derivation":"comparative degree of G507 (ἄνω);","pron":"an-o'-ter-os","pos":"Adjective Neuter","thayer":"<ol><li>higher<ol type='a'><li>of motion: to a higher place, up higher</li><li>of rest: in a higher place, above</li></ol></li></ol>","xlit":"anṓteros"},"G2713":{"derivation":"from G2596 (κατά) and G1725 (ἔναντι);","strongs_def":" directly opposite","kjv_def":"before, over against","lemma":"κατέναντι","translit":"katénanti","pron":"kat-en'-an-tee","pos":"Adverb","thayer":"<ol><li>over against, opposite before</li><li>metaphorically before one, i.e. he being judge</li></ol>","xlit":"katénanti"},"G5217":{"strongs_def":" to lead (oneself) under, i.e. withdraw or retire (as if sinking out of sight), literally or figuratively","derivation":"from G5259 (ὑπό) and G71 (ἄγω);","translit":"hypágō","lemma":"ὑπάγω","kjv_def":"depart, get hence, go (a-)way","pron":"hoop-ag'-o","pos":"Verb","thayer":"<ol><li>to lead under, bring under</li><li>to withdraw one's self, to go away, depart</li></ol>","xlit":"hypágō"},"G4448":{"kjv_def":"burn, fiery, be on fire, try","translit":"pyróō","lemma":"πυρόω","derivation":"from G4442 (πῦρ);","strongs_def":" to kindle, i.e. (passively) to be ignited, glow (literally), be refined (by implication), or (figuratively) to be inflamed (with anger, grief, lust)","pron":"poo-ro'-o","pos":"Verb","thayer":"<ol><li>to burn with fire, to set on fire, kindle<ol type='a'><li>to be on fire, to burn<ol><li>to be incensed, indignant</li></ol><li>make to glow<ol><li>full of fire, fiery, ignited<ol type='a'><li>of darts filled with inflammable substances and set on fire</li></ol><li>melted by fire and purged of dross</li></ol></li></ol></li></ol>","xlit":"pyróō"},"G1422":{"kjv_def":"hard","lemma":"δύσκολος","translit":"dýskolos","derivation":"from G1418 (δυσ-) and (food);","strongs_def":" properly, fastidious about eating (peevish), i.e. (genitive case) impracticable","pron":"doo'-kol-os","pos":"Adjective","thayer":"<ol><li>hard to find agreeable food for, fastidious about food</li><li>difficult to please, always finding fault</li><li>difficult</li></ol>","xlit":"dýskolos"},"G1573":{"derivation":"from G1537 (ἐκ) and G2556 (κακός);","strongs_def":" to be (bad or) weak, i.e. (by implication) to fail (in heart)","kjv_def":"faint, be weary","lemma":"ἐκκακέω","translit":"ekkakéō","pron":"ek-kak-eh'-o","pos":"Verb","thayer":"<ol><li>to be utterly spiritless, to be wearied out, exhausted</li></ol>","xlit":"ekkakéō"},"G3582":{"strongs_def":" by implication, (of friction) to boil or heat); a vessel (as fashioned or for cooking) (or perhaps by corruption from the Latin sextarius, the sixth of a modius, i.e. about a pint), i.e. (specially), a measure for liquids or solids, (by analogy, a pitcher)","derivation":"as if from (properly, to smooth;","lemma":"ξέστης","translit":"xéstēs","kjv_def":"pot","pron":"xes'-tace","pos":"Noun Masculine","thayer":"<ol><li>a sextarius<ol type='a'><li>a vessel for measuring liquids, holding about a pint (.5 litre)</li></ol><li>a wooden pitcher or ewer from which water or wine is poured, whether holding a sextarius or not</li></ol>","xlit":"xéstēs"},"G4117":{"kjv_def":"broidered hair","lemma":"πλέγμα","translit":"plégma","derivation":"from G4120 (πλέκω);","strongs_def":" a plait (of hair)","pron":"pleg'-mah","pos":"Noun Neuter","thayer":"<ol><li>what is woven, plaited, or twisted together</li><li>a web, plait, braid<ol type='a'><li>of a net</li><li>of a basket, in which the infant Moses was laid</li><li>of braided hair</li></ol></li></ol>","xlit":"plégma"},"G1608":{"strongs_def":" to be utterly unchaste","derivation":"from G1537 (ἐκ) and G4203 (πορνεύω);","translit":"ekporneúō","lemma":"ἐκπορνεύω","kjv_def":"give self over to fornication","pron":"ek-porn-yoo'-o","pos":"Verb","thayer":"<ol><li>to go a whoring, \"give one's self over to fornication\"</li></ol>","xlit":"ekporneúō"},"G4203":{"derivation":"from G4204 (πόρνη);","strongs_def":" to act the harlot, i.e. (literally) indulge unlawful lust (of either sex), or (figuratively) practise idolatry","kjv_def":"commit (fornication)","translit":"porneúō","lemma":"πορνεύω","pron":"porn-yoo'-o","pos":"Verb","thayer":"<ol><li>to prostitute one's body to the lust of another</li><li>to give one's self to unlawful sexual intercourse<ol type='a'><li>to commit fornication</li></ol><li>metaphorically to be given to idolatry, to worship idols<ol type='a'><li>to permit one's self to be drawn away by another into idolatry</li></ol></li></ol>","xlit":"porneúō"},"G873":{"kjv_def":"divide, separate, sever","translit":"aphorízō","lemma":"ἀφορίζω","derivation":"from G575 (ἀπό) and G3724 (ὁρίζω);","strongs_def":" to set off by boundary, i.e. (figuratively) limit, exclude, appoint, etc.","pron":"af-or-id'-zo","pos":"Verb","thayer":"<ol><li>to mark off from others by boundaries, to limit, to separate<ol type='a'><li>in a bad sense: to exclude as disreputable</li><li>in a good sense: to appoint, set apart for some purpose</li></ol></li></ol>","xlit":"aphorízō"},"G4581":{"translit":"Seleúkeia","lemma":"Σελεύκεια","kjv_def":"Seleucia","strongs_def":" Seleuceia, a place in Syria","derivation":"from (Seleucus, a Syrian king);","pron":"sel-yook'-i-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Seleucia = \"white light\"</p><ol><li>a city of Syria near the mouth of the Orontes, about 16 miles</li></ol>","xlit":"Seleúkeia"},"G2873":{"strongs_def":" a cut, i.e. (by analogy) toil (as reducing the strength), literally or figuratively; by implication, pains","derivation":"from G2875 (κόπτω);","translit":"kópos","lemma":"κόπος","kjv_def":"labour, + trouble, weariness","pron":"kop'-os","pos":"Noun Masculine","thayer":"<ol><li>a beating</li><li>a beating of the breast with grief, sorrow</li><li>labour<ol type='a'><li>trouble<ol><li>to cause one trouble, make work for him</li></ol><li>intense labour united with trouble and toil</li></ol></li></ol>","xlit":"kópos"},"G5176":{"derivation":"probably strengthened from a collateral form of the base of G5134 (τραῦμα) and G5147 (τρίβος) through the idea of corrosion or wear;","strongs_def":" or perhaps rather of a base of G5167 (τρυγών) and G5149 (τρίζω) through the idea of a craunching sound; to gnaw or chew, i.e. (generally) to eat","kjv_def":"eat","lemma":"τρώγω","translit":"trṓgō","pron":"tro'-go","pos":"Verb","thayer":"<ol><li>to gnaw, crunch, chew raw vegetables or fruits (as nuts, almonds)<ol type='a'><li>of animals feeding</li><li>of men</li></ol><li>to eat</li></ol>","xlit":"trṓgō"},"G4884":{"derivation":"from G4862 (σύν) and G726 (ἁρπάζω);","strongs_def":" to snatch together, i.e. seize","kjv_def":"catch","lemma":"συναρπάζω","translit":"synarpázō","pron":"soon-ar-pad'-zo","pos":"Verb","thayer":"<ol><li>to seize by force</li><li>to catch or lay hold of (one so that he is no longer his own master)</li><li>to seize by force and carry away</li></ol>","xlit":"synarpázō"},"G5106":{"lemma":"τοίνυν","translit":"toínyn","kjv_def":"then, therefore","strongs_def":" truly now, i.e. accordingly","derivation":"from G5104 (τοί) and G3568 (νῦν);","pron":"toy'-noon","thayer":"<ol><li>therefore, then, accordingly</li></ol>","xlit":"toínyn"},"G3481":{"translit":"Nathán","lemma":"Ναθάν","kjv_def":"Nathan","strongs_def":" Nathan, an Israelite","derivation":"of Hebrew origin (H05416);","pron":"nath-an'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nathan = \"a giver\"</p><ol><li>one of the four sons of David who were born to him by Bathshua</li></ol>","xlit":"Nathán"},"G4784":{"derivation":"middle from G4862 (σύν) and G2698 (κατατίθημι);","strongs_def":" to deposit (one's vote or opinion) in company with, i.e. (figuratively) to accord with","kjv_def":"consent","translit":"synkatatíthemai","lemma":"συγκατατίθεμαι","pron":"soong-kat-at-ith'-em-ahee","pos":"Verb","thayer":"<ol><li>to deposit together with another</li><li>to deposit one's vote in the urn with another</li><li>to consent to, vote for, agree with</li></ol>","xlit":"synkatatíthemai"},"G3140":{"strongs_def":" to be a witness, i.e. testify (literally or figuratively)","derivation":"from G3144 (μάρτυς);","lemma":"μαρτυρέω","translit":"martyréō","kjv_def":"charge, give (evidence), bear record, have (obtain, of) good (honest) report, be well reported of, testify, give (have) testimony, (be, bear, give, obtain) witness","pron":"mar-too-reh'-o","pos":"Verb","thayer":"<ol><li>to be a witness, to bear witness, i.e. to affirm that one has seen or heard or experienced something, or that he knows it because taught by divine revelation or inspiration<ol type='a'><li>to give (not to keep back) testimony</li><li>to utter honourable testimony, give a good report</li><li>conjure, implore</li></ol></li></ol>","xlit":"martyréō"},"G1558":{"lemma":"ἔκδικος","translit":"ékdikos","kjv_def":"a (re-)venger","strongs_def":" carrying justice out, i.e. a punisher","derivation":"from G1537 (ἐκ) and G1349 (δίκη);","pron":"ek'-dik-os","pos":"Adjective","thayer":"<ol><li>without law and justice</li><li>exacting penalty from one<ol type='a'><li>an avenger, punisher</li></ol></li></ol>","xlit":"ékdikos"},"G1543":{"derivation":"from G1540 (ἑκατόν) and G757 (ἄρχω);","strongs_def":" the captain of one hundred men","kjv_def":"centurion","lemma":"ἑκατοντάρχης","translit":"hekatontárchēs","pron":"hek-at-on-tar'-khace","pos":"Noun Masculine","thayer":"<ol><li>an officer in the Roman army</li></ol>","xlit":"hekatontárchēs"},"G1972":{"derivation":"from G1971 (ἐπιποθέω);","strongs_def":" a longing for","kjv_def":"earnest (vehement) desire","translit":"epipóthēsis","lemma":"ἐπιπόθησις","pron":"ep-ee-poth'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>longing</li></ol>","xlit":"epipóthēsis"},"G911":{"translit":"báptō","lemma":"βάπτω","kjv_def":"dip","strongs_def":" to whelm, i.e. cover wholly with a fluid; in the New Testament only in a qualified or special sense, i.e. (literally) to moisten (a part of one's person), or (by implication) to stain (as with dye)","derivation":"a primary verb;","pron":"bap'-to","pos":"Verb","thayer":"<ol><li>to dip, dip in, immerse</li><li>to dip into dye, to dye, colour</li></ol>","xlit":"báptō"},"G4827":{"kjv_def":"fellow disciple","lemma":"συμμαθητής","translit":"symmathētḗs","derivation":"from a compound of G4862 (σύν) and G3129 (μανθάνω);","strongs_def":" a co-learner (of Christianity)","pron":"soom-math-ay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a fellow disciple</li></ol>","xlit":"symmathētḗs"},"G5442":{"strongs_def":" to watch, i.e. be on guard (literally of figuratively); by implication, to preserve, obey, avoid","derivation":"probably from G5443 (φυλή) through the idea of isolation;","lemma":"φυλάσσω","translit":"phylássō","kjv_def":"beward, keep (self), observe, save","pron":"foo-las'-so","pos":"Verb","thayer":"<ol><li>to guard<ol type='a'><li>to watch, keep watch</li><li>to guard or watch, have an eye upon: lest he escape</li><li>to guard a person (or thing) that he may remain safe<ol><li>lest he suffer violence, be despoiled, etc. to protect</li><li>to protect one from a person or thing</li><li>to keep from being snatched away, preserve safe and unimpaired</li><li>to guard from being lost or perishing</li><li>to guard one's self from a thing</li></ol><li>to guard, i.e. care for, take care not to violate<ol><li>to observe</li></ol></li></ol><li>to observe for one's self something to escape<ol type='a'><li>to avoid, shun flee from</li><li>to guard for one's self (i.e. for one's safety's sake) so as not to violate, i.e. to keep, observe (the precepts of the Mosaic law)</li></ol></li></ol>","xlit":"phylássō"},"G2134":{"strongs_def":" to castrate (figuratively, live unmarried)","derivation":"from G2135 (εὐνοῦχος);","lemma":"εὐνουχίζω","translit":"eunouchízō","kjv_def":"make…eunuch","pron":"yoo-noo-khid'-zo","pos":"Verb","thayer":"<ol><li>to castrate, to neuter a man</li><li>metaphorically to make one's self a eunuch, i.e. by abstaining</li></ol>","xlit":"eunouchízō"},"G508":{"strongs_def":" above the ground, i.e. (properly) the second floor of a building; used for a dome or a balcony on the upper story","derivation":"from G507 (ἄνω) and G1093 (γῆ);","translit":"anṓgeon","lemma":"ἀνώγεον","kjv_def":"upper room","pron":"an-ogue'-eh-on","pos":"Noun Neuter","thayer":"<ol><li>anything above the ground</li><li>a room in the upper part of a house</li></ol>","xlit":"anṓgeon"},"G3776":{"strongs_def":" substance, i.e. property (possessions)","derivation":"from the feminine of G5607 (ὤν);","translit":"ousía","lemma":"οὐσία","kjv_def":"goods, substance","pron":"oo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>what one has, i.e. property, possessions, estate</li></ol>","xlit":"ousía"},"G4681":{"kjv_def":"Spain","lemma":"Σπανία","translit":"Spanía","derivation":"probably of foreign origin;","strongs_def":" Spania, a region of Europe","pron":"span-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Spain = \"scarceness\"</p><ol><li>the whole peninsula south of the Pyrenees</li></ol>","xlit":"Spanía"},"G1321":{"kjv_def":"teach","translit":"didáskō","lemma":"διδάσκω","derivation":"a prolonged (causative) form of a primary verb (to learn);","strongs_def":" to teach (in the same broad application)","pron":"did-as'-ko","pos":"Verb","thayer":"<ol><li>to teach<ol type='a'><li>to hold discourse with others in order to instruct them, deliver didactic discourses</li><li>to be a teacher</li><li>to discharge the office of a teacher, conduct one's self as a teacher</li></ol><li>to teach one<ol type='a'><li>to impart instruction</li><li>instill doctrine into one</li><li>the thing taught or enjoined</li><li>to explain or expound a thing</li><li>to teach one something</li></ol></li></ol>","xlit":"didáskō"},"G5246":{"derivation":"from G5228 (ὑπέρ) and G3591 (ὄγκος);","strongs_def":" bulging over, i.e. (figuratively) insolent","kjv_def":"great swelling","lemma":"ὑπέρογκος","translit":"hypéronkos","pron":"hoop-er'-ong-kos","pos":"Adjective","thayer":"<ol><li>overswollen</li><li>metaphorically immoderate, extravagant</li></ol>","xlit":"hypéronkos"},"G1973":{"derivation":"from G1909 (ἐπί) and a derivative of the latter part of G1971 (ἐπιποθέω);","strongs_def":" yearned upon, i.e. greatly loved","kjv_def":"longed for","lemma":"ἐπιπόθητος","translit":"epipóthētos","pron":"ep-ee-poth'-ay-tos","pos":"Adjective","thayer":"<ol><li>longed for</li></ol>","xlit":"epipóthētos"},"G93":{"strongs_def":" (legal) injustice (properly, the quality, by implication, the act); morally, wrongfulness (of character, life or act)","derivation":"from G94 (ἄδικος);","lemma":"ἀδικία","translit":"adikía","kjv_def":"iniquity, unjust, unrighteousness, wrong","pron":"ad-ee-kee'-ah","pos":"Noun Feminine","thayer":"<ol><li>injustice, of a judge</li><li>unrighteousness of heart and life</li><li>a deed violating law and justice, act of unrighteousness</li></ol>","xlit":"adikía"},"G4804":{"derivation":"from G4802 (συζητέω);","strongs_def":" a disputant, i.e. sophist","kjv_def":"disputer","translit":"syzētētḗs","lemma":"συζητητής","pron":"sood-zay-tay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a disputer, i.e. a learned disputant, sophist</li></ol>","xlit":"syzētētḗs"},"G2267":{"derivation":"from G2264 (Ἡρώδης);","strongs_def":" Herodion, a Christian","kjv_def":"Herodion","translit":"Hērōdíōn","lemma":"Ἡρωδίων","pron":"hay-ro-dee'-ohn","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Herodian = \"heroic\"</p><ol><li>a certain Christian</li></ol>","xlit":"Hērōdíōn"},"G745":{"translit":"Archélaos","lemma":"Ἀρχέλαος","kjv_def":"Archelaus","strongs_def":" people-ruling; Archelaus, a Jewish king","derivation":"from G757 (ἄρχω) and G2994 (Λαοδικεύς);","pron":"ar-khel'-ah-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Archelaus = \"prince of the people\"</p><ol><li>A son of Herod the Great by Malthace, the Samaritan woman. He and his brother Antipas were brought up with a certain private man in Rome. After the death of his father, he ruled as ethnarch over Judaea, Samaria and Idumaea, (with the exception of the cities of Gaza, Gadara and Hipo). The Jews and the Samaritans having accused him at Rome of tyranny, he was banished by the emperor Augustus to Vienna of the Allobroges and died there.</li></ol>","xlit":"Archélaos"},"G4566":{"kjv_def":"Satan","translit":"Satân","lemma":"Σατᾶν","derivation":"of Hebrew origin (H07854);","strongs_def":" Satan, i.e. the devil","pron":"sat-an'","pos":"Noun Masculine","thayer":"<ol><li>adversary (one who opposes another in purpose or act), the name given to<ol type='a'><li>the prince of evil spirits, the inveterate adversary of God and Christ<ol><li>he incites apostasy from God and to sin</li><li>circumventing men by his wiles</li><li>the worshippers of idols are said to be under his control</li><li>by his demons he is able to take possession of men and inflict them with diseases</li><li>by God's assistance he is overcome</li><li>on Christ's return from heaven he will be bound with chains for a thousand years, but when the thousand years are finished he will walk the earth in yet greater power, but shortly after will be given over to eternal punishment</li></ol><li>a Satan-like man</li></ol></li></ol>","xlit":"Satân"},"G4655":{"translit":"skótos","lemma":"σκότος","kjv_def":"darkness","strongs_def":" shadiness, i.e. obscurity (literally or figuratively)","derivation":"from the base of G4639 (σκιά);","pron":"skot'-os","pos":"Noun Neuter","thayer":"<ol><li>darkness<ol type='a'><li>of night darkness</li><li>of darkened eyesight or blindness</li></ol><li>metaphorically<ol type='a'><li>of ignorance respecting divine things and human duties, and the accompanying ungodliness and immorality, together with their consequent misery in hell</li><li>persons in whom darkness becomes visible and holds sway</li></ol></li></ol>","xlit":"skótos"},"G2304":{"translit":"theîos","lemma":"θεῖος","kjv_def":" divine, godhead","strongs_def":" godlike (neuter as noun, divinity)","derivation":"from G2316 (θεός);","pron":"thi'-os","pos":"Adjective","thayer":"<ol><li>a general name of deities or divinities as used by the Greeks</li><li>spoken of the only and true God, trinity<ol type='a'><li>of Christ</li><li>Holy Spirit</li><li>the Father</li></ol></li></ol>","xlit":"theîos"},"G5185":{"translit":"typhlós","lemma":"τυφλός","kjv_def":"blind","strongs_def":" opaque (as if smoky), i.e. (by analogy) blind (physically or mentally)","derivation":"from, G5187 (τυφόω);","pron":"toof-los'","pos":"Adjective","thayer":"<ol><li>blind</li><li>mentally blind</li></ol>","xlit":"typhlós"},"G366":{"translit":"ananḗphō","lemma":"ἀνανήφω","kjv_def":"recover self","strongs_def":" to become sober again, i.e. (figuratively) regain (one's) senses","derivation":"from G303 (ἀνά) and G3525 (νήφω);","pron":"an-an-ay'-fo","pos":"Verb","thayer":"<ol><li>to return to soberness</li></ol>","xlit":"ananḗphō"},"G4949":{"kjv_def":"Syrophenician","lemma":"Συροφοίνισσα","translit":"Syrophoínissa","derivation":"feminine of a compound of G4948 (Σύρος) and the same as G5403 (Φοινίκη);","strongs_def":" a Syro-phœnician woman, i.e. a female native of Phœnicia in Syria","pron":"soo-rof-oy'-nis-sah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Syrophenician = \"exalted palm\"</p><ol><li>the name of a mixed nation, half Phoenicians and half Syrians</li></ol>","xlit":"Syrophoínissa"},"G4072":{"kjv_def":"fly(-ing)","lemma":"πέτομαι","translit":"pétomai","derivation":"middle voice of a primary verb;","strongs_def":" to fly","pron":"pet'-om-ahee","pos":"Verb","thayer":"<ol><li>to fly</li></ol>","xlit":"pétomai"},"G2281":{"translit":"thálassa","lemma":"θάλασσα","kjv_def":"sea","strongs_def":" the sea (genitive case or specially)","derivation":"probably prolonged from G251 (ἅλς);","pron":"thal'-as-sah","pos":"Noun Feminine","thayer":"<ol><li>the sea<ol type='a'><li>used of the sea in general</li><li>used specifically of the Mediterranean Sea or the Red Sea</li></ol></li></ol>","xlit":"thálassa"},"G4016":{"kjv_def":"array, cast about, clothe(-d me), put on","translit":"peribállō","lemma":"περιβάλλω","derivation":"from G4012 (περί) and G906 (βάλλω);","strongs_def":" to throw all around, i.e. invest (with a palisade or with clothing)","pron":"per-ee-bal'-lo","pos":"Verb","thayer":"<ol><li>to throw around, to put around<ol type='a'><li>to surround a city with a bank (palisade)</li><li>of garments, to clothe one<ol><li>to put a thing on one</li><li>to clothe one with a thing</li></ol><li>to put on or clothe one's self</li></ol></li></ol>","xlit":"peribállō"},"G858":{"kjv_def":"singleness","translit":"aphelótēs","lemma":"ἀφελότης","derivation":"from a compound of G1 (Α) (as a negative particle) and (in the sense of a stone as stubbing the foot);","strongs_def":" smoothness, i.e. (figuratively) simplicity","pron":"af-el-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>simplicity, singleness</li></ol>","xlit":"aphelótēs"},"G2879":{"kjv_def":"Core","lemma":"Κορέ","translit":"Koré","derivation":"of Hebrew origin (H07141);","strongs_def":" Core (i.e. Korach), an Israelite","pron":"kor-eh'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Korah = \"baldness\"</p><ol><li>a man who, with others, rebelled against Moses</li></ol>","xlit":"Koré"},"G5015":{"kjv_def":"trouble","lemma":"ταράσσω","translit":"tarássō","derivation":"of uncertain affinity;","strongs_def":" to stir or agitate (roil water)","pron":"tar-as'-so","pos":"Verb","thayer":"<ol><li>to agitate, trouble (a thing, by the movement of its parts to and fro)<ol type='a'><li>to cause one inward commotion, take away his calmness of mind, disturb his equanimity</li><li>to disquiet, make restless</li><li>to stir up</li><li>to trouble<ol><li>to strike one's spirit with fear and dread</li></ol><li>to render anxious or distressed</li><li>to perplex the mind of one by suggesting scruples or doubts</li></ol></li></ol>","xlit":"tarássō"},"G1462":{"strongs_def":" an accusation, i.e. offence alleged","derivation":"from G1458 (ἐγκαλέω);","lemma":"ἔγκλημα","translit":"énklēma","kjv_def":"crime laid against, laid to charge","pron":"eng'-klay-mah","pos":"Noun Neuter","thayer":"<ol><li>accusation: the crime of which one is accused</li></ol>","xlit":"énklēma"},"G1248":{"translit":"diakonía","lemma":"διακονία","kjv_def":"(ad-)minister(-ing, -tration, -try), office, relief, service(-ing)","strongs_def":" attendance (as a servant, etc.); figuratively (eleemosynary) aid, (official) service (especially of the Christian teacher, or technically of the diaconate)","derivation":"from G1249 (διάκονος);","pron":"dee-ak-on-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>service, ministering, especially of those who execute the commands of others</li><li>of those who by the command of God proclaim and promote religion among men<ol type='a'><li>of the office of Moses</li><li>of the office of the apostles and its administration</li><li>of the office of prophets, evangelists, elders etc.</li></ol><li>the ministration of those who render to others the offices of Christian affection especially those who help meet need by either collecting or distributing of charities</li><li>the office of the deacon in the church</li><li>the service of those who prepare and present food</li></ol>","xlit":"diakonía"},"G4847":{"strongs_def":" a native of the same town, i.e. (figuratively) co-religionist (fellow-Christian)","derivation":"from G4862 (σύν) and G4177 (πολίτης);","translit":"sympolítēs","lemma":"συμπολίτης","kjv_def":"fellow- citizen","pron":"soom-pol-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>possessing the same citizenship with others, a fellow citizen<ol type='a'><li>of Gentiles as received into communion of the saints</li><li>of the people consecrated to God</li></ol></li></ol>","xlit":"sympolítēs"},"G389":{"kjv_def":"sigh deeply","translit":"anastenázō","lemma":"ἀναστενάζω","derivation":"from G303 (ἀνά) and G4727 (στενάζω);","strongs_def":" to sigh deeply","pron":"an-as-ten-ad'-zo","pos":"Verb","thayer":"<ol><li>to draw up deep sighs from the bottom of the breast, to sigh deeply</li></ol>","xlit":"anastenázō"},"G1045":{"strongs_def":" Gad, a tribe of Israelites","derivation":"of Hebrew origin (H01410);","translit":"Gád","lemma":"Γάδ","kjv_def":"Gad","pron":"gad","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gad = \"a troop\"</p><ol><li>the seventh son of the patriarch Jacob, by Zilpah, Leah's maid</li></ol>","xlit":"Gád"},"G1514":{"kjv_def":"be at (have, live in) peace, live peaceably","lemma":"εἰρηνεύω","translit":"eirēneúō","derivation":"from G1515 (εἰρήνη);","strongs_def":" to be (act) peaceful","pron":"i-rane-yoo'-o","pos":"Verb","thayer":"<ol><li>to make peace</li><li>to cultivate or keep peace, harmony</li><li>to be at peace, live in peace</li></ol>","xlit":"eirēneúō"},"G2064":{"translit":"érchomai","lemma":"ἔρχομαι","kjv_def":"accompany, appear, bring, come, enter, fall out, go, grow, X light, X next, pass, resort, be set","strongs_def":" to come or go (in a great variety of applications, literally and figuratively)","derivation":"middle voice of a primary verb (used only in the present and imperfect tenses, the others being supplied by a kindred (middle voice) , or (active) , which do not otherwise occur);","pron":"er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come<ol type='a'><li>of persons<ol><li>to come from one place to another, and used both of persons arriving</li><li>to appear, make one's appearance, come before the public</li></ol></li></ol><li>metaphorically<ol type='a'><li>to come into being, arise, come forth, show itself, find place or influence</li><li>be established, become known, to come (fall) into or unto</li></ol><li>to go, to follow one</li></ol>","xlit":"érchomai"},"G2349":{"strongs_def":" liable to die","derivation":"from G2348 (θνήσκω);","lemma":"θνητός","translit":"thnētós","kjv_def":"mortal(-ity)","pron":"thnay-tos'","pos":"Adjective","thayer":"<ol><li>liable to death, mortal</li></ol>","xlit":"thnētós"},"G2298":{"kjv_def":"marvel(-lous)","translit":"thaumastós","lemma":"θαυμαστός","derivation":"from G2296 (θαυμάζω);","strongs_def":" wondered at, i.e. (by implication) wonderful","pron":"thow-mas-tos'","pos":"Adjective","thayer":"<ol><li>wonderful, marvellous<ol type='a'><li>worthy of pious admiration, admirable, excellent</li><li>passing human comprehension</li><li>causing amazement joined with terror</li><li>marvellous<ol><li>extraordinary, striking, surprising</li></ol></li></ol></li></ol>","xlit":"thaumastós"},"G875":{"strongs_def":" to froth at the mouth (in epilepsy)","derivation":"from G876 (ἀφρός);","translit":"aphrízō","lemma":"ἀφρίζω","kjv_def":"foam","pron":"af-rid'-zo","pos":"Verb","thayer":"<ol><li>to foam</li></ol>","xlit":"aphrízō"},"G665":{"strongs_def":" to deflect, i.e. (reflexively) avoid","derivation":"from G575 (ἀπό) and the base of G5157 (τροπή);","lemma":"ἀποτρέπω","translit":"apotrépō","kjv_def":"turn away","pron":"ap-ot-rep'-o","pos":"Verb","thayer":"<ol><li>to turn one's self away from</li><li>to shun, avoid</li></ol>","xlit":"apotrépō"},"G44":{"strongs_def":" a hook (as bent)","derivation":"from the same as G43 (ἀγκάλη);","lemma":"ἄγκιστρον","translit":"ánkistron","kjv_def":"hook","pron":"ang'-kis-tron","pos":"Noun Neuter","thayer":"<ol><li>a fishing hook, a small hook</li></ol>","xlit":"ánkistron"},"G2581":{"translit":"Kananítēs","lemma":"Κανανίτης","kjv_def":"Canaanite (by mistake for a derivative from G5477 (Χαναάν))","strongs_def":" zealous; Cananites, an epithet","derivation":"of Chaldee origin (compare H07067);","pron":"kan-an-ee'-tace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Canaanite = \"zealous\"</p><ol><li>the surname of apostle Simon, otherwise known as \"Simon Zelotes\"</li></ol>","xlit":"Kananítēs"},"G3513":{"lemma":"νή","translit":"nḗ","kjv_def":"I protest by","strongs_def":" a particle of attestation (accompanied by the object invoked or appealed to in confirmation); as sure as","derivation":"probably an intensive form of G3483 (ναί);","pron":"nay","thayer":"<ol><li>by<ol type='a'><li>used in the affirmations of oaths</li></ol></li></ol>","xlit":"nḗ"},"G307":{"kjv_def":"draw","lemma":"ἀναβιβάζω","translit":"anabibázō","derivation":"from G303 (ἀνά) and a derivative of the base of G939 (βάσις);","strongs_def":" to cause to go up, i.e. haul (a net)","pron":"an-ab-ee-bad'-zo","pos":"Verb","thayer":"<ol><li>to cause to go up or ascend, to draw up</li></ol>","xlit":"anabibázō"},"G5355":{"derivation":"probably akin to the base of G5351 (φθείρω);","strongs_def":" ill-will (as detraction), i.e. jealousy (spite)","kjv_def":"envy","translit":"phthónos","lemma":"φθόνος","pron":"fthon'-os","pos":"Noun Masculine","thayer":"<ol><li>envy</li><li>for envy, i.e. prompted by envy</li></ol>","xlit":"phthónos"},"G4374":{"strongs_def":" to bear towards, i.e. lead to, tender (especially to God), treat","derivation":"from G4314 (πρός) and G5342 (φέρω) (including its alternate);","translit":"prosphérō","lemma":"προσφέρω","kjv_def":"bring (to, unto), deal with, do, offer (unto, up), present unto, put to","pron":"pros-fer'-o","pos":"Verb","thayer":"<ol><li>to bring to, lead to<ol type='a'><li>one to a person who can heal him or is ready to show him some kindness, one to a person who is to judge him</li><li>to bring a present or a thing, to reach or hand a thing to one</li><li>to put to</li></ol><li>to be borne towards one, to attack, assail<ol type='a'><li>to behave one's self towards one, deal with one</li></ol></li></ol>","xlit":"prosphérō"},"G1947":{"strongs_def":" assistance","derivation":"from a compound of G1909 (ἐπί) and a (prolonged) form of the base of G2877 (κοράσιον) (in the sense of servant);","translit":"epikouría","lemma":"ἐπικουρία","kjv_def":"help","pron":"ep-ee-koo-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>aid, succour, help</li></ol>","xlit":"epikouría"},"G1047":{"derivation":"of foreign origin;","strongs_def":" a treasure","kjv_def":"treasure","lemma":"γάζα","translit":"gáza","pron":"gad'-zah","pos":"Noun Feminine","thayer":"<ol><li>the royal treasury, treasure, riches</li></ol>","xlit":"gáza"},"G300":{"derivation":"of Hebrew origin (H0526);","strongs_def":" Amon, an Israelite","kjv_def":"Amon","lemma":"Ἀμών","translit":"Amṓn","pron":"am-one'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Amon = \"builder\"</p><ol><li>a king of Judah, son of Manasseh, and father of Josiah</li></ol>","xlit":"Amṓn"},"G1707":{"translit":"emplékō","lemma":"ἐμπλέκω","kjv_def":"entangle (in, self with)","strongs_def":" to entwine, i.e. (figuratively) involve with","derivation":"from G1722 (ἐν) and G4120 (πλέκω);","pron":"em-plek'-o","pos":"Verb","thayer":"<ol><li>to inweave</li><li>of a thing: to entangle, involve in</li></ol>","xlit":"emplékō"},"G4467":{"derivation":"from a comparative of (easy, i.e. reckless) and G2041 (ἔργον);","strongs_def":" easy-going behavior, i.e. (by extension) a crime","kjv_def":"lewdness","lemma":"ῥᾳδιούργημα","translit":"rhaidioúrgēma","pron":"hrad-ee-oorg'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a piece of knavery, rascality, villainy</li></ol>","xlit":"rhaidioúrgēma"},"G2424":{"kjv_def":"Jesus","translit":"Iēsoûs","lemma":"Ἰησοῦς","derivation":"of Hebrew origin (H03091);","strongs_def":" Jesus (i.e. Jehoshua), the name of our Lord and two (three) other Israelites","pron":"ee-ay-sooce'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jesus = \"Jehovah is salvation\"</p><ol><li>Jesus, the Son of God, the Saviour of mankind, God incarnate</li><li>Jesus Barabbas was the captive robber whom the Jews begged Pilate to release instead of Christ</li><li>Joshua was the famous captain of the Israelites, Moses' successor (<a class='bible' href='#b44.7.45'>Act 7:45</a>, <a class='bible' href='#b58.4.8'>Heb 4:8</a>)</li><li>Jesus, son of Eliezer, one of the ancestors of Christ (<a class='bible' href='#b42.3.29'>Luk 3:29</a>)</li><li>Jesus, surnamed Justus, a Jewish Christian, an associate with Paul in the preaching of the gospel (<a class='bible' href='#b51.4.11'>Col 4:11</a>)</li></ol>","xlit":"Iēsoûs"},"G2981":{"strongs_def":" talk","derivation":"from G2980 (λαλέω);","lemma":"λαλιά","translit":"laliá","kjv_def":"saying, speech","pron":"lal-ee-ah'","pos":"Noun Feminine","thayer":"<ol><li>speech, i.e a story</li><li>dialect, mode of speech, pronunciation<ol type='a'><li>speech which discloses the speaker's native country</li></ol></li></ol>","xlit":"laliá"},"G3130":{"derivation":"from G3105 (μαίνομαι);","strongs_def":" craziness","kjv_def":"(+ make) X mad","translit":"manía","lemma":"μανία","pron":"man-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>madness, frenzy</li></ol>","xlit":"manía"},"G1695":{"translit":"Emmaoús","lemma":"Ἐμμαούς","kjv_def":"Emmaus","strongs_def":" Emmaus, a place in Palestine","derivation":"probably of Hebrew origin (compare H03222);","pron":"em-mah-ooce'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Emmaus = \"warm baths\"</p><ol><li>the village to which the two disciples were going when our Lord appeared to them on the way, on the day of resurrection. <a class='bible' href='#b42.24.13'>Luk 24:13</a>. Luke makes its distance from Jerusalem, sixty stadia, or</li></ol>","xlit":"Emmaoús"},"G4063":{"strongs_def":" to run around, i.e. traverse","derivation":"from G4012 (περί) and G5143 (τρέχω) (including its alternate);","translit":"peritréchō","lemma":"περιτρέχω","kjv_def":"run through","pron":"per-ee-trekh'-o","pos":"Verb","thayer":"<ol><li>to run around, run around about</li></ol>","xlit":"peritréchō"},"G4905":{"kjv_def":"accompany, assemble (with), come (together), come (company, go) with, resort","lemma":"συνέρχομαι","translit":"synérchomai","derivation":"from G4862 (σύν) and G2064 (ἔρχομαι);","strongs_def":" to convene, depart in company with, associate with, or (specially), cohabit (conjugally)","pron":"soon-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come together<ol type='a'><li>to assemble</li><li>of conjugal cohabitation</li></ol><li>to go (depart) or come with one, to accompany one</li></ol>","xlit":"synérchomai"},"G5485":{"strongs_def":" graciousness (as gratifying), of manner or act (abstract or concrete; literal, figurative or spiritual; especially the divine influence upon the heart, and its reflection in the life; including gratitude)","derivation":"from G5463 (χαίρω);","translit":"cháris","lemma":"χάρις","kjv_def":"acceptable, benefit, favour, gift, grace(- ious), joy, liberality, pleasure, thank(-s, -worthy)","pron":"khar'-ece","pos":"Noun Feminine","thayer":"<ol><li>grace<ol type='a'><li>that which affords joy, pleasure, delight, sweetness, charm, loveliness: grace of speech</li></ol><li>good will, loving-kindness, favour<ol type='a'><li>of the merciful kindness by which God, exerting his holy influence upon souls, turns them to Christ, keeps, strengthens, increases them in Christian faith, knowledge, affection, and kindles them to the exercise of the Christian virtues</li></ol><li>what is due to grace<ol type='a'><li>the spiritual condition of one governed by the power of divine grace</li><li>the token or proof of grace, benefit<ol><li>a gift of grace</li><li>benefit, bounty</li></ol></li></ol><li>thanks, (for benefits, services, favours), recompense, reward</li></ol>","xlit":"cháris"},"G4631":{"lemma":"σκευή","translit":"skeuḗ","kjv_def":"tackling","strongs_def":" furniture, i.e. spare tackle","derivation":"from G4632 (σκεῦος);","pron":"skyoo-ay'","pos":"Noun Feminine","thayer":"<ol><li>any apparatus, equipment, or furniture<ol type='a'><li>of the utensils or tackling of a ship</li></ol></li></ol>","xlit":"skeuḗ"},"G2054":{"strongs_def":" a quarrel, i.e. (by implication) wrangling","derivation":"of uncertain affinity;","translit":"éris","lemma":"ἔρις","kjv_def":"contention, debate, strife, variance","pron":"er'-is","pos":"Noun Feminine","thayer":"<ol><li>contention, strife, wrangling</li></ol>","xlit":"éris"},"G2900":{"derivation":"from G2904 (κράτος);","strongs_def":" powerful","kjv_def":"mighty","lemma":"κραταιός","translit":"krataiós","pron":"krat-ah-yos'","pos":"Adjective","thayer":"<ol><li>mighty<ol type='a'><li>of the mighty power of God</li></ol></li></ol>","xlit":"krataiós"},"G2213":{"derivation":"from G2212 (ζητέω);","strongs_def":" a search (properly concretely), i.e. (in words) a debate","kjv_def":"question","lemma":"ζήτημα","translit":"zḗtēma","pron":"dzay'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>a question, debate<ol type='a'><li>about the law</li></ol></li></ol>","xlit":"zḗtēma"},"G3746":{"strongs_def":" who especially","derivation":"from G3739 (ὅς) and G4007 (περ);","lemma":"ὅσπερ","translit":"hósper","kjv_def":"whomsoever","pron":"hos'-per","thayer":"<ol><li>whomever</li></ol>","xlit":"hósper"},"G770":{"strongs_def":" to be feeble (in any sense)","derivation":"from G772 (ἀσθενής);","lemma":"ἀσθενέω","translit":"asthenéō","kjv_def":"be diseased, impotent folk (man), (be) sick, (be, be made) weak","pron":"as-then-eh'-o","pos":"Verb","thayer":"<ol><li>to be weak, feeble, to be without strength, powerless</li><li>to be weak in means, needy, poor</li><li>to be feeble, sick</li></ol>","xlit":"asthenéō"},"G1928":{"strongs_def":" to appoint besides, i.e. supplement (as a codicil)","derivation":"middle voice from G1909 (ἐπί) and G1299 (διατάσσω);","translit":"epidiatássomai","lemma":"ἐπιδιατάσσομαι","kjv_def":"add to","pron":"ep-ee-dee-ah-tas'-som-ahee","pos":"Verb","thayer":"<ol><li>to ordain besides, to add something to what has been ordained</li></ol>","xlit":"epidiatássomai"},"G4098":{"derivation":"probably akin to G4072 (πέτομαι) through the idea of alighting;","strongs_def":" to fall (literally or figuratively)","kjv_def":"fail, fall (down), light on","lemma":"πίπτω","translit":"píptō","pron":"pip'-to","pos":"Verb","thayer":"<ol><li>to descend from a higher place to a lower<ol type='a'><li>to fall (either from or upon)<ol><li>to be thrust down</li></ol><li>metaphorically to fall under judgment, came under condemnation</li></ol><li>to descend from an erect to a prostrate position<ol type='a'><li>to fall down<ol><li>to be prostrated, fall prostrate</li><li>of those overcome by terror or astonishment or grief or under the attack of an evil spirit or of falling dead suddenly</li><li>the dismemberment of a corpse by decay</li><li>to prostrate one's self</li><li>used of suppliants and persons rendering homage or worship to one</li><li>to fall out, fall from, i.e. shall perish or be lost</li><li>to fall down, fall into ruin: of buildings, walls etc.</li></ol><li>to be cast down from a state of prosperity<ol><li>to fall from a state of uprightness</li><li>to perish, i.e come to an end, disappear, cease<ol type='a'><li>of virtues</li></ol><li>to lose authority, no longer have force<ol type='a'><li>of sayings, precepts, etc.</li></ol><li>to be removed from power by death</li><li>to fail of participating in, miss a share in</li></ol></li></ol></li></ol>","xlit":"píptō"},"G4593":{"derivation":"from G4592 (σημεῖον);","strongs_def":" to distinguish, i.e. mark (for avoidance)","kjv_def":"note","lemma":"σημειόω","translit":"sēmeióō","pron":"say-mi-o'-o","pos":"Verb","thayer":"<ol><li>to mark, to note, distinguish by marking</li><li>to mark or note for one's self</li></ol>","xlit":"sēmeióō"},"G3373":{"kjv_def":"grow up","translit":"mēkýnō","lemma":"μηκύνω","derivation":"from G3372 (μῆκος);","strongs_def":" to lengthen, i.e. (middle voice) to enlarge","pron":"may-koo'-no","pos":"Verb","thayer":"<ol><li>to make long, to lengthen</li><li>in the Bible twice of plants, to cause to grow, increase</li></ol>","xlit":"mēkýnō"},"G1732":{"derivation":"from G1731 (ἐνδείκνυμι);","strongs_def":" indication (abstractly)","kjv_def":"declare, evident token, proof","lemma":"ἔνδειξις","translit":"éndeixis","pron":"en'-dike-sis","pos":"Noun Feminine","thayer":"<ol><li>demonstration, proof<ol type='a'><li>manifestation made by act</li><li>sign, evidence</li></ol></li></ol>","xlit":"éndeixis"},"G4900":{"derivation":"from G4862 (σύν) and G1643 (ἐλαύνω);","strongs_def":" to drive together, i.e. (figuratively) exhort (to reconciliation)","kjv_def":"+ set at one again","lemma":"συνελαύνω","translit":"synelaúnō","pron":"soon-el-ow'-no","pos":"Verb","thayer":"<ol><li>to drive together, compel</li><li>to constrain by extortion, urge</li></ol>","xlit":"synelaúnō"},"G2031":{"kjv_def":"X say","lemma":"ἔπος","translit":"épos","derivation":"from G2036 (ἔπω);","strongs_def":" a word","pron":"ep'-os","pos":"Noun Neuter","thayer":"<ol><li>a word</li></ol>","xlit":"épos"},"G2725":{"lemma":"κατήγορος","translit":"katḗgoros","kjv_def":"accuser","strongs_def":" against one in the assembly, i.e. a complainant at law; specially, Satan","derivation":"from G2596 (κατά) and G58 (ἀγορά);","pron":"kat-ay'-gor-os","pos":"Noun Masculine","thayer":"<ol><li>an accuser<ol type='a'><li>a name given to the devil by the rabbis</li></ol></li></ol>","xlit":"katḗgoros"},"G2728":{"translit":"katióō","lemma":"κατιόω","kjv_def":"canker","strongs_def":" to rust down, i.e. corrode","derivation":"from G2596 (κατά) and a derivative of G2447 (ἰός);","pron":"kat-ee-o'-o","pos":"Verb","thayer":"<ol><li>to rust over, cover with rust</li></ol>","xlit":"katióō"},"G452":{"lemma":"Ἄννας","translit":"Ánnas","kjv_def":"Annas","strongs_def":" Annas (i.e. G367 (Ἀνανίας)), an Israelite","derivation":"of Hebrew origin (H02608);","pron":"an'-nas","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Annas = \"humble\"</p><ol><li>high priest of the Jews, elevated to the priesthood by Quirinius the governor of Syria c. 6 or 7 A.D., but afterwards deposed by Valerius Gratus, the procurator of Judaea, who put in his place, first Ismael, son of Phabi, and shortly after Eleazar, son of Annas. From the latter, the office passed to Simon; from Simon c. 18 A.D. to Caiaphas; but Annas even after he had been put out of office, continued to have great influence.</li></ol>","xlit":"Ánnas"},"G2532":{"lemma":"καί","translit":"kaí","kjv_def":"and, also, both, but, even, for, if, or, so, that, then, therefore, when, yet","strongs_def":" and, also, even, so then, too, etc.; often used in connection (or composition) with other particles or small words","derivation":"apparently, a primary particle, having a copulative and sometimes also a cumulative force;","pron":"kahee","pos":"Conjunction","thayer":"<ol><li>and, also, even, indeed, but</li></ol>","xlit":"kaí"},"G4748":{"translit":"stoichéō","lemma":"στοιχέω","kjv_def":"walk (orderly)","strongs_def":" to march in (military) rank (keep step), i.e. (figuratively) to conform to virtue and piety","derivation":"from a derivative of (to range in regular line);","pron":"stoy-kheh'-o","pos":"Verb","thayer":"<ol><li>to proceed in a row as the march of a soldier, go in order<ol type='a'><li>metaphorically to go on prosperously, to turn out well</li></ol><li>to walk<ol type='a'><li>to direct one's life, to live</li></ol></li></ol>","xlit":"stoichéō"},"G924":{"kjv_def":"Bartimæus","translit":"Bartimaîos","lemma":"Βαρτιμαῖος","derivation":"of Chaldee origin (H01247 and H02931);","strongs_def":" son of Timæus (or the unclean); Bar-timæus, an Israelite","pron":"bar-tim-ah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Bartimaeus = \"son of Timaeus\"</p><ol><li>a certain blind man</li></ol>","xlit":"Bartimaîos"},"G5334":{"strongs_def":" a saying, i.e. report","derivation":"from G5346 (φημί) (not the same as \"phase\", which is from G5316 (φαίνω));","translit":"phásis","lemma":"φάσις","kjv_def":"tidings","pron":"fas'-is","pos":"Noun Feminine","thayer":"<ol><li>in the Attic orators, the exposure of (informing against) those who have embezzled the property of the state, or violated the laws respecting the importation or exporting of merchandise, or defrauded their wards</li><li>the disclosure of secret crime</li></ol>","xlit":"phásis"},"G1443":{"kjv_def":"Eber","lemma":"Ἐβέρ","translit":"Ebér","derivation":"of Hebrew origin (H05677);","strongs_def":" Eber, a patriarch","pron":"eb-er'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eber or Hebrew = \"the region beyond\"</p><ol><li>the son of Salah, and great grandson of Shem, one of Abraham's ancestors</li></ol>","xlit":"Ebér"},"G2125":{"strongs_def":" to be circumspect, i.e. (by implication) to be apprehensive; religiously, to reverence","derivation":"middle voice from G2126 (εὐλαβής);","lemma":"εὐλαβέομαι","translit":"eulabéomai","kjv_def":"(moved with) fear","pron":"yoo-lab-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to act cautiously, circumspectly</li><li>to beware, fear</li><li>to reverence, stand in awe of</li></ol>","xlit":"eulabéomai"},"G110":{"derivation":"from a compound of G1 (Α) (as a negative particle) and G2288 (θάνατος);","strongs_def":" deathlessness","kjv_def":"immortality","translit":"athanasía","lemma":"ἀθανασία","pron":"ath-an-as-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>undying, immortality, everlasting</li></ol>","xlit":"athanasía"},"G2840":{"derivation":"from G2839 (κοινός);","strongs_def":" to make (or consider) profane (ceremonially)","kjv_def":"call common, defile, pollute, unclean","lemma":"κοινόω","translit":"koinóō","pron":"koy-no'-o","pos":"Verb","thayer":"<ol><li>to make common<ol type='a'><li>to make (Levitically) unclean, render unhallowed, defile, profane</li><li>to declare or count unclean</li></ol></li></ol>","xlit":"koinóō"},"G2809":{"translit":"klémma","lemma":"κλέμμα","kjv_def":"theft","strongs_def":" stealing (properly, the thing stolen, but used of the act)","derivation":"from G2813 (κλέπτω);","pron":"klem'-mah","pos":"Noun Neuter","thayer":"<ol><li>thing stolen</li><li>the act of theft</li></ol>","xlit":"klémma"},"G2215":{"derivation":"of uncertain origin;","strongs_def":" darnel or false grain","kjv_def":"tares","translit":"zizánion","lemma":"ζιζάνιον","pron":"dziz-an'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a kind of darnel, resembling wheat except the grains are black</li></ol>","xlit":"zizánion"},"G595":{"kjv_def":"putting away (off)","lemma":"ἀπόθεσις","translit":"apóthesis","derivation":"from G659 (ἀποτίθημι);","strongs_def":" a laying aside (literally or figuratively)","pron":"ap-oth'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a putting off or away</li></ol>","xlit":"apóthesis"},"G3958":{"derivation":"apparently a primary verb;","strongs_def":" to experience a sensation or impression (usually painful)","kjv_def":"feel, passion, suffer, vex","lemma":"πάσχω","translit":"páschō","pron":"pas'-kho","pos":"Verb","thayer":"<ol><li>to be affected or have been affected, to feel, have a sensible experience, to undergo<ol type='a'><li>in a good sense, to be well off, in good case</li><li>in a bad sense, to suffer sadly, be in a bad plight<ol><li>of a sick person</li></ol></li></ol></li></ol>","xlit":"páschō"},"G4261":{"kjv_def":"put forward, shoot forth","translit":"probállō","lemma":"προβάλλω","derivation":"from G4253 (πρό) and G906 (βάλλω);","strongs_def":" to throw forward, i.e. push to the front, germinate","pron":"prob-al'-lo","pos":"Verb","thayer":"<ol><li>to throw forward<ol type='a'><li>of trees, to shoot forth, put out leaves</li><li>to germinate</li><li>to push forward, thrust forward, put forward</li></ol></li></ol>","xlit":"probállō"},"G2452":{"lemma":"Ἰουδαϊκῶς","translit":"Ioudaïkōs","kjv_def":"as do the Jews","strongs_def":" Judaïcally or in a manner resembling a Judæan","derivation":"adverb from G2451 (Ἰουδαϊκός);","pron":"ee-oo-dah-ee-koce'","pos":"Adverb","thayer":"<ol><li>Jewishly, after the manner of the Jews</li></ol>","xlit":"Ioudaïkōs"},"G2048":{"derivation":"of uncertain affinity; lonesome, i.e. (by implication) waste (usually as a noun, G5561 (χώρα) being implied)","kjv_def":"desert, desolate, solitary, wilderness","translit":"érēmos","lemma":"ἔρημος","pron":"er'-ay-mos","thayer":"<ol><li>solitary, lonely, desolate, uninhabited<ol type='a'><li>used of places<ol><li>a desert, wilderness</li><li>deserted places, lonely regions</li><li>an uncultivated region fit for pasturage</li></ol><li>used of persons<ol><li>deserted by others</li><li>deprived of the aid and protection of others, especially of friends, acquaintances, kindred</li><li>bereft<ol type='a'><li>of a flock deserted by the shepherd</li><li>of a woman neglected by her husband, from whom the husband withholds himself</li></ol></li></ol></li></ol></li></ol>","xlit":"érēmos"},"G2770":{"derivation":"from G2771 (κέρδος);","strongs_def":" to gain (literally or figuratively)","kjv_def":"(get) gain, win","lemma":"κερδαίνω","translit":"kerdaínō","pron":"ker-dah'-ee-no","pos":"Verb","thayer":"<ol><li>to gain, acquire, to get gain</li><li>metaphorically<ol type='a'><li>of gain arising from shunning or escaping from evil (where we say \"to spare one's self\" , \"be spared\" )</li><li>to gain any one, i.e. to win him over to the kingdom of God, to gain one to faith in Christ</li><li>to gain Christ's favour and fellowship</li></ol></li></ol>","xlit":"kerdaínō"},"G1920":{"translit":"epigínomai","lemma":"ἐπιγίνομαι","kjv_def":"blow","strongs_def":" to arrive upon, i.e. spring up (as a wind)","derivation":"from G1909 (ἐπί) and G1096 (γίνομαι);","pron":"ep-ig-in'-om-ahee","pos":"Verb","thayer":"<ol><li>to become or happen afterwards<ol type='a'><li>to be born after</li></ol><li>to come to, arrive: of time</li><li>to arise, spring up, come on</li></ol>","xlit":"epigínomai"},"G1658":{"derivation":"probably from the alternate of G2064 (ἔρχομαι);","strongs_def":" unrestrained (to go at pleasure), i.e. (as a citizen) not a slave (whether freeborn or manumitted), or (genitive case) exempt (from obligation or liability)","kjv_def":"free (man, woman), at liberty","translit":"eleútheros","lemma":"ἐλεύθερος","pron":"el-yoo'-ther-os","pos":"Adjective","thayer":"<ol><li>freeborn<ol type='a'><li>in a civil sense, one who is not a slave</li><li>of one who ceases to be a slave, freed, manumitted</li></ol><li>free, exempt, unrestrained, not bound by an obligation</li><li>in an ethical sense: free from the yoke of the Mosaic Law</li></ol>","xlit":"eleútheros"},"G2386":{"kjv_def":"healing","lemma":"ἴαμα","translit":"íama","derivation":"from G2390 (ἰάομαι);","strongs_def":" a cure (the effect)","pron":"ee'-am-ah","pos":"Noun Neuter","thayer":"<ol><li>a means of healing, remedy, medicine</li><li>a healing</li></ol>","xlit":"íama"},"G5551":{"strongs_def":" to be a time-wearer, i.e. to procrastinate (linger)","derivation":"from a presumed compound of G5550 (χρόνος) and the base of G5147 (τρίβος);","translit":"chronotribéō","lemma":"χρονοτριβέω","kjv_def":"spend time","pron":"khron-ot-rib-eh'-o","pos":"Verb","thayer":"<ol><li>to wear away time, spend time</li></ol>","xlit":"chronotribéō"},"G3048":{"translit":"logía","lemma":"λογία","kjv_def":"collection, gathering","strongs_def":" a contribution","derivation":"from G3056 (λόγος) (in the commercial sense);","pron":"log-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a collection<ol type='a'><li>of money gathered for the relief of the poor</li></ol></li></ol>","xlit":"logía"},"G3343":{"derivation":"from G3326 (μετά) and G3992 (πέμπω);","strongs_def":" to send from elsewhere, i.e. (middle voice) to summon or invite","kjv_def":"call (send) for","lemma":"μεταπέμπω","translit":"metapémpō","pron":"met-ap-emp'-o","pos":"Verb","thayer":"<ol><li>to send one after another</li><li>like our send after, i.e. to send for</li><li>to send after for one's self, cause to be sent</li></ol>","xlit":"metapémpō"},"G1508":{"strongs_def":" if not","derivation":"from G1487 (εἰ) and G3361 (μή);","lemma":"εἰ μή","translit":"ei mḗ","kjv_def":"but, except (that), if not, more than, save (only) that, saving, till","pron":"i may","pos":"Conjunction","thayer":"<ol><li>if not, except, but</li></ol>","xlit":"ei mḗ"},"G1924":{"strongs_def":" to inscribe (physically or mentally)","derivation":"from G1909 (ἐπί) and G1125 (γράφω);","lemma":"ἐπιγράφω","translit":"epigráphō","kjv_def":"inscription, write in (over, thereon)","pron":"ep-ee-graf'-o","pos":"Verb","thayer":"<ol><li>to write upon, inscribe</li><li>metaphorically to write upon the mind</li></ol>","xlit":"epigráphō"},"G5046":{"strongs_def":" complete (in various applications of labor, growth, mental and moral character, etc.); neuter (as noun, with G3588 (ὁ)) completeness","derivation":"from G5056 (τέλος);","lemma":"τέλειος","translit":"téleios","kjv_def":"of full age, man, perfect","pron":"tel'-i-os","pos":"Adjective","thayer":"<ol><li>brought to its end, finished</li><li>wanting nothing necessary to completeness</li><li>perfect</li><li>that which is perfect<ol type='a'><li>consummate human integrity and virtue</li><li>of men<ol><li>full grown, adult, of full age, mature</li></ol></li></ol></li></ol>","xlit":"téleios"},"G2854":{"lemma":"κολλούριον","translit":"kolloúrion","kjv_def":" eyesalve","strongs_def":" prob akin to the base of G2853 (κολλάω)); properly, a poultice (as made of or in the form of crackers), i.e. (by analogy) a plaster","derivation":"neuter of a presumed derivative of (a cake;","pron":"kol-loo'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a preparation composed of various materials and used as a remedy for tender eyelids</li></ol>","xlit":"kolloúrion"},"G25":{"derivation":"perhaps from (much) (or compare G5689);","strongs_def":" to love (in a social or moral sense)","kjv_def":"(be-)love(-ed)","lemma":"ἀγαπάω","translit":"agapáō","pron":"ag-ap-ah'-o","pos":"Verb","thayer":"<ol><li>of persons<ol type='a'><li>to welcome, to entertain, to be fond of, to love dearly</li></ol><li>of things<ol type='a'><li>to be well pleased, to be contented at or with a thing</li></ol></li></ol>","xlit":"agapáō"},"G1827":{"strongs_def":" to convict fully, i.e. (by implication) to punish","derivation":"from G1537 (ἐκ) and G1651 (ἐλέγχω);","lemma":"ἐξελέγχω","translit":"exelénchō","kjv_def":"convince","pron":"ex-el-eng'-kho","pos":"Verb","thayer":"<ol><li>to prove to be in the wrong, convict</li></ol>","xlit":"exelénchō"},"G3858":{"kjv_def":"receive","lemma":"παραδέχομαι","translit":"paradéchomai","derivation":"from G3844 (παρά) and G1209 (δέχομαι);","strongs_def":" to accept near, i.e. admit or (by implication) delight in","pron":"par-ad-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive, take up, take upon one's self</li><li>to admit, i.e. not to reject, to accept, receive<ol type='a'><li>of a son: to acknowledge as one's own</li></ol></li></ol>","xlit":"paradéchomai"},"G2323":{"derivation":"from the same as G2324 (θεράπων);","strongs_def":" to wait upon menially, i.e. (figuratively) to adore (God), or (specially) to relieve (of disease)","kjv_def":"cure, heal, worship","lemma":"θεραπεύω","translit":"therapeúō","pron":"ther-ap-yoo'-o","pos":"Verb","thayer":"<ol><li>to serve, do service</li><li>to heal, cure, restore to health</li></ol>","xlit":"therapeúō"},"G2464":{"kjv_def":"Isaac","translit":"Isaák","lemma":"Ἰσαάκ","derivation":"of Hebrew origin (H03327);","strongs_def":" Isaac (i.e. Jitschak), the son of Abraham","pron":"ee-sah-ak'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Isaac = \"to laugh\"</p><ol><li>the son of Abraham and Sarah</li></ol>","xlit":"Isaák"},"G2360":{"derivation":"from to wail;","strongs_def":" to clamor, i.e. (by implication) to frighten","kjv_def":"trouble","translit":"throéō","lemma":"θροέω","pron":"thro-eh'-o","pos":"Verb","thayer":"<ol><li>to cry aloud, make a noise by outcry<ol type='a'><li>in the NT, to trouble, frighten</li><li>to be troubled in mind, to be frightened, alarmed</li></ol></li></ol>","xlit":"throéō"},"G443":{"kjv_def":"murderer","translit":"anthrōpoktónos","lemma":"ἀνθρωποκτόνος","derivation":"from G444 (ἄνθρωπος) and (to kill);","strongs_def":" a manslayer","pron":"anth-ro-pok-ton'-os","pos":"Adjective","thayer":"<ol><li>a manslayer, murderer</li></ol>","xlit":"anthrōpoktónos"},"G4550":{"kjv_def":"bad, corrupt","translit":"saprós","lemma":"σαπρός","derivation":"from G4595 (σήπω);","strongs_def":" rotten, i.e. worthless (literally or morally)","pron":"sap-ros'","pos":"Adjective","thayer":"<ol><li>rotten, putrefied</li><li>corrupted by one and no longer fit for use, worn out</li><li>of poor quality, bad, unfit for use, worthless</li></ol>","xlit":"saprós"},"G4450":{"derivation":"from G4442 (πῦρ);","strongs_def":" fire-like, i.e. (specially), flame- colored","kjv_def":"red","lemma":"πυῤῥός","translit":"pyrrhós","pron":"poor-hros'","pos":"Adjective","thayer":"<ol><li>having the colour of fire, red</li></ol>","xlit":"pyrrhós"},"G4132":{"lemma":"πλήμμυρα","translit":"plḗmmyra","kjv_def":"flood","strongs_def":" flood-tide, i.e. (by analogy) a freshet","derivation":"prolonged from G4130 (πλήθω);","pron":"plame-moo'-rah","pos":"Noun Feminine","thayer":"<ol><li>a flood, whether of sea or of a river</li></ol>","xlit":"plḗmmyra"},"G3014":{"translit":"lépra","lemma":"λέπρα","kjv_def":"leprosy","strongs_def":" scaliness, i.e. \"leprosy\"","derivation":"from the same as G3013 (λεπίς);","pron":"lep'-rah","pos":"Noun Feminine","thayer":"<ol><li>leprosy</li><li>a most offensive, annoying, dangerous, cutaneous disease, the virus of which generally pervades the whole body, common in Egypt and the East</li></ol>","xlit":"lépra"},"G4451":{"strongs_def":" ignition, i.e. (specially), smelting (figuratively, conflagration, calamity as a test)","derivation":"from G4448 (πυρόω);","lemma":"πύρωσις","translit":"pýrōsis","kjv_def":"burning, trial","pron":"poo'-ro-sis","pos":"Noun Feminine","thayer":"<ol><li>a burning<ol type='a'><li>the burning by which metals are roasted and reduced</li><li>by a figure drawn from a refiners fire<ol><li>calamities or trials that test the character</li></ol></li></ol></li></ol>","xlit":"pýrōsis"},"G278":{"strongs_def":" irrevocable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G3338 (μεταμέλλομαι);","lemma":"ἀμεταμέλητος","translit":"ametamélētos","kjv_def":"without repentance, not to be repented of","pron":"am-et-am-el'-ay-tos","pos":"Adjective","thayer":"<ol><li>not repentant of, unregretted</li></ol>","xlit":"ametamélētos"},"G648":{"translit":"apostegázō","lemma":"ἀποστεγάζω","kjv_def":"uncover","strongs_def":" to unroof","derivation":"from G575 (ἀπό) and a derivative of G4721 (στέγη);","pron":"ap-os-teg-ad'-zo","pos":"Verb","thayer":"<ol><li>to uncover, take off the roof</li></ol>","xlit":"apostegázō"},"G4822":{"derivation":"from G4862 (σύν) and (to force;","strongs_def":" causative (by reduplication) of the base of G939 (βάσις)); to drive together, i.e. unite (in association or affection), (mentally) to infer, show, teach","kjv_def":"compact, assuredly gather, intrust, knit together, prove","translit":"symbibázō","lemma":"συμβιβάζω","pron":"soom-bib-ad'-zo","pos":"Verb","thayer":"<ol><li>to cause to coalesce, to join together, put together<ol type='a'><li>to unite or knit together: in affection</li></ol><li>to put together in one's mind<ol type='a'><li>to compare</li><li>to gather, conclude, consider</li></ol><li>to cause a person to unite with one in a conclusion or come to the same opinion, to prove, demonstrate<ol type='a'><li>to teach, instruct, one</li></ol></li></ol>","xlit":"symbibázō"},"G1647":{"kjv_def":"less than the least","lemma":"ἐλαχιστότερος","translit":"elachistóteros","derivation":"comparative of G1646 (ἐλάχιστος);","strongs_def":" far less","pron":"el-akh-is-tot'-er-os","pos":"Adjective","thayer":"<ol><li>less than the least, lower the lowest</li></ol>","xlit":"elachistóteros"},"G3076":{"derivation":"from G3077 (λύπη);","strongs_def":" to distress; reflexively or passively, to be sad","kjv_def":"cause grief, grieve, be in heaviness, (be) sorrow(-ful), be (make) sorry","lemma":"λυπέω","translit":"lypéō","pron":"loo-peh'-o","pos":"Verb","thayer":"<ol><li>to make sorrowful</li><li>to affect with sadness, cause grief, to throw into sorrow</li><li>to grieve, offend</li><li>to make one uneasy, cause him a scruple</li></ol>","xlit":"lypéō"},"G404":{"lemma":"ἀναψύχω","translit":"anapsýchō","kjv_def":"refresh","strongs_def":" properly, to cool off, i.e. (figuratively) relieve","derivation":"from G303 (ἀνά) and G5594 (ψύχω);","pron":"an-aps-oo'-kho","pos":"Verb","thayer":"<ol><li>to cool again, to cool off, recover from the effects of heat<ol type='a'><li>to refresh (one's spirit)</li></ol><li>to recover breath, take the air, cool off, revive, refresh one's self</li></ol>","xlit":"anapsýchō"},"G2886":{"translit":"kosmikós","lemma":"κοσμικός","kjv_def":"worldly","strongs_def":" terrene (\"cosmic\"), literally (mundane) or figuratively (corrupt)","derivation":"from G2889 (κόσμος) (in its secondary sense);","pron":"kos-mee-kos'","pos":"Adjective","thayer":"<ol><li>of or belonging to the world<ol type='a'><li>relating to the universe</li><li>earthly</li><li>worldly, i.e. having the character of this present corrupt age</li></ol></li></ol>","xlit":"kosmikós"},"G1952":{"derivation":"from G1909 (ἐπί) and G3007 (λείπω);","strongs_def":" to leave upon, i.e. (figuratively) to be insufficient for","kjv_def":"fail","translit":"epileípō","lemma":"ἐπιλείπω","pron":"ep-ee-li'-po","pos":"Verb","thayer":"<ol><li>to fail, not to suffer for (any purpose, for the attainment of an end)</li></ol>","xlit":"epileípō"},"G3579":{"strongs_def":" to be a host (passively, a guest); by implication, be (make, appear) strange","derivation":"from G3581 (ξένος);","lemma":"ξενίζω","translit":"xenízō","kjv_def":"entertain, lodge, (think it) strange","pron":"xen-id'-zo","pos":"Verb","thayer":"<ol><li>to receive as a guest, to entertain, hospitably<ol type='a'><li>to be received hospitably</li><li>to stay as a guest, to lodge</li><li>be lodged</li></ol><li>to surprise or astonish by the strangeness and novelty of a thing<ol type='a'><li>to think strange, be shocked</li></ol></li></ol>","xlit":"xenízō"},"G4572":{"strongs_def":" of (with, to) thyself","derivation":"genitive case from G4571 (σέ) and G846 (αὐτός), also dative case of the same, , and accusative case , likewise contracted , , and , respectively;","translit":"seautoû","lemma":"σεαυτοῦ","kjv_def":"thee, thine own self, (thou) thy(-self)","pron":"seh-ow-too'","thayer":"<ol><li>thyself, thee</li></ol>","xlit":"seautoû"},"G2953":{"kjv_def":"of Cyprus","translit":"Kýprios","lemma":"Κύπριος","derivation":"from G2954 (Κύπρος);","strongs_def":" a Cyprian (Cypriot), i.e. inhabitant of Cyprus","pron":"koo'-pree-os","pos":"Noun Masculine","thayer":"<ol><li>a Cyprian or Cypriote, i.e. a native of Cyprus</li></ol>","xlit":"Kýprios"},"G4059":{"lemma":"περιτέμνω","translit":"peritémnō","kjv_def":"circumcise","strongs_def":" to cut around, i.e. (specially) to circumcise","derivation":"from G4012 (περί) and the base of G5114 (τομώτερος);","pron":"per-ee-tem'-no","pos":"Verb","thayer":"<ol><li>to cut around</li><li>to circumcise<ol type='a'><li>cut off one's prepuce (used of that well known rite by which not only the male children of the Israelites, on the eighth day after birth, but subsequently also \"proselytes of righteousness\" were consecrated to Jehovah and introduced into the number of his people)</li><li>to get one's self circumcised, present one's self to be circumcised, receive circumcision</li><li>since by the rite of circumcision a man was separated from the unclean world and dedicated to God, the word is transferred to denote the extinguishing of lusts and the removal of sins</li></ol></li></ol>","xlit":"peritémnō"},"G3814":{"strongs_def":" a girl, i.e. (specially), a female slave or servant","derivation":"feminine diminutive of G3816 (παῖς);","translit":"paidískē","lemma":"παιδίσκη","kjv_def":"bondmaid(-woman), damsel, maid(-en)","pron":"pahee-dis'-kay","pos":"Noun Feminine","thayer":"<ol><li>a young girl, damsel</li><li>a maid-servant, a young female slave<ol type='a'><li>a maid servant who has charge of the door</li></ol></li></ol>","xlit":"paidískē"},"G792":{"kjv_def":"star","translit":"astḗr","lemma":"ἀστήρ","derivation":"probably from the base of G4766 (στρώννυμι);","strongs_def":" a star (as strown over the sky), literally or figuratively","pron":"as-tare'","pos":"Noun Masculine","thayer":"<ol><li>a star</li></ol>","xlit":"astḗr"},"G2318":{"strongs_def":" reverent of God, i.e. pious","derivation":"from G2316 (θεός) and G4576 (σέβομαι);","lemma":"θεοσεβής","translit":"theosebḗs","kjv_def":"worshipper of God","pron":"theh-os-eb-ace'","pos":"Adjective","thayer":"<ol><li>worshipping God, pious</li></ol>","xlit":"theosebḗs"},"G2729":{"kjv_def":"prevail (against)","lemma":"κατισχύω","translit":"katischýō","derivation":"from G2596 (κατά) and G2480 (ἰσχύω);","strongs_def":" to overpower","pron":"kat-is-khoo'-o","pos":"Verb","thayer":"<ol><li>to be strong to another's detriment, to prevail against</li><li>to be superior in strength</li><li>to overcome</li><li>to prevail</li></ol>","xlit":"katischýō"},"G4941":{"lemma":"Συντύχη","translit":"Syntýchē","kjv_def":"Syntyche","strongs_def":" an accident; Syntyche, a Christian female","derivation":"from G4940 (συντυγχάνω);","pron":"soon-too'-khay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Syntyche = \"with fate\"</p><ol><li>a female member of the church of Philippi</li></ol>","xlit":"Syntýchē"},"G3625":{"lemma":"οἰκουμένη","translit":"oikouménē","kjv_def":"earth, world","strongs_def":" land, i.e. the (terrene part of the) globe; specially, the Roman empire","derivation":"feminine participle present passive of G3611 (οἰκέω) (as noun, by implication, of G1093 (γῆ));","pron":"oy-kou-men'-ay","pos":"Noun Feminine","thayer":"<ol><li>the inhabited earth<ol type='a'><li>the portion of the earth inhabited by the Greeks, in distinction from the lands of the barbarians</li><li>the Roman empire, all the subjects of the empire</li><li>the whole inhabited earth, the world</li><li>the inhabitants of the earth, men</li></ol><li>the universe, the world</li></ol>","xlit":"oikouménē"},"G1597":{"kjv_def":"of a long time, of old","lemma":"ἔκπαλαι","translit":"ékpalai","derivation":"from G1537 (ἐκ) and G3819 (πάλαι);","strongs_def":" long ago, for a long while","pron":"eh'-pal-ahee","pos":"Adverb","thayer":"<ol><li>from of old</li><li>of a long time</li></ol>","xlit":"ékpalai"},"G1040":{"kjv_def":"fine linen","translit":"býssos","lemma":"βύσσος","derivation":"of Hebrew origin (H0948);","strongs_def":" white linen","pron":"boos'-sos","pos":"Noun Feminine","thayer":"<ol><li>byssus, a species of Egyptian flax</li><li>linen made from byssus, very costly, delicate, soft, white and also of a yellow colour</li></ol>","xlit":"býssos"},"G3356":{"strongs_def":" to be moderate in passion, i.e. gentle (to treat indulgently)","derivation":"from a compound of the base of G3357 (μετρίως) and G3806 (πάθος);","translit":"metriopathéō","lemma":"μετριοπαθέω","kjv_def":"have compassion","pron":"met-ree-op-ath-eh'-o","pos":"Verb","thayer":"<ol><li>to be affected moderately or in due measure</li><li>to preserve moderation in the passions, especially anger or grief<ol type='a'><li>of one who is not unduly disturbed by the errors, faults, sins of others, but bears them gently</li></ol></li></ol>","xlit":"metriopathéō"},"G1200":{"kjv_def":"jailor, keeper of the prison","lemma":"δεσμοφύλαξ","translit":"desmophýlax","derivation":"from G1199 (δεσμόν) and G5441 (φύλαξ);","strongs_def":" a jailer (as guarding the prisoners)","pron":"des-mof-oo'-lax","pos":"Noun Masculine","thayer":"<ol><li>a keeper of a prison, a jailor</li></ol>","xlit":"desmophýlax"},"G2416":{"derivation":"from G2417 (ἱερόσυλος);","strongs_def":" to be a temple-robber (figuratively)","kjv_def":"commit sacrilege","lemma":"ἱεροσυλέω","translit":"hierosyléō","pron":"hee-er-os-ool-eh'-o","pos":"Verb","thayer":"<ol><li>to commit sacrilege, to rob a temple<ol type='a'><li>in <a class='bible' href='#b45.2.22'>Rom 2:22</a>, where the meaning is, \"thou who abhorrest idols and their contamination, doest yet not hesitate to plunder their shrines\"</li></ol></li></ol>","xlit":"hierosyléō"},"G2273":{"derivation":"from G2228 (ἤ) and G5104 (τοί);","strongs_def":" either indeed","kjv_def":"whether","translit":"ḗtoi","lemma":"ἤτοι","pron":"ay'-toy","thayer":"<ol><li>whether, either</li></ol>","xlit":"ḗtoi"},"G1521":{"kjv_def":"bring in(-to), (+ was to) lead into","translit":"eiságō","lemma":"εἰσάγω","derivation":"from G1519 (εἰς) and G71 (ἄγω);","strongs_def":" to introduce (literally or figuratively)","pron":"ice-ag'-o","pos":"Verb","thayer":"<ol><li>to lead in</li><li>to bring in, the place into which not being expressly stated</li></ol>","xlit":"eiságō"},"G600":{"translit":"apokathístēmi","lemma":"ἀποκαθίστημι","kjv_def":"restore (again)","strongs_def":" to reconstitute (in health, home or organization)","derivation":"from G575 (ἀπό) and G2525 (καθίστημι);","pron":"ap-ok-ath-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to restore to its former state</li><li>to be in its former state</li></ol>","xlit":"apokathístēmi"},"G1247":{"kjv_def":"(ad-)minister (unto), serve, use the office of a deacon","translit":"diakonéō","lemma":"διακονέω","derivation":"from G1249 (διάκονος);","strongs_def":" to be an attendant, i.e. wait upon (menially or as a host, friend, or (figuratively) teacher); technically, to act as a Christian deacon","pron":"dee-ak-on-eh'-o","pos":"Verb","thayer":"<ol><li>to be a servant, attendant, domestic, to serve, wait upon<ol type='a'><li>to minister to one, render ministering offices to<ol><li>to be served, ministered unto</li></ol><li>to wait at a table and offer food and drink to the guests<ol><li>of women preparing food</li></ol><li>to minister, i.e. supply food and necessities of life<ol><li>to relieve one's necessities (e.g. by collecting alms), to provide take care of, distribute, the things necessary to sustain life</li><li>to take care of the poor and the sick, who administer the office of a deacon</li><li>in Christian churches to serve as deacons</li></ol><li>to minister<ol><li>to attend to anything, that may serve another's interests</li><li>to minister a thing to one, to serve one or by supplying any thing</li></ol></li></ol></li></ol>","xlit":"diakonéō"},"G2379":{"derivation":"from a derivative of G2378 (θυσία);","strongs_def":" a place of sacrifice, i.e. an altar (special or genitive case, literal or figurative)","kjv_def":"altar","translit":"thysiastḗrion","lemma":"θυσιαστήριον","pron":"thoo-see-as-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>the altar for slaying and burning of victims used of<ol type='a'><li>the altar of whole burnt offerings which stood in the court of the priests in the temple at Jerusalem</li><li>the altar of incense which stood in the sanctuary or the Holy Place</li><li>any other altar<ol><li>metaphorically, the cross on which Christ suffered an expiatory death: to eat of this altar, i.e. to appropriate to one's self the fruits of Christ's expiatory death</li></ol></li></ol></li></ol>","xlit":"thysiastḗrion"},"G4519":{"lemma":"σαβαώθ","translit":"sabaṓth","kjv_def":"sabaoth","strongs_def":" armies; sabaoth (i.e. tsebaoth), a military epithet of God","derivation":"of Hebrew origin (H06635 in feminine plural);","pron":"sab-ah-owth'","pos":"Noun","thayer":"<ol><li>\"Lord of Sabaoth\"<ol type='a'><li>Lord of the armies of Israel, as those who are under the leadership and protection of Jehovah maintain his cause in war</li></ol></li></ol>","xlit":"sabaṓth"},"G4745":{"lemma":"στοά","translit":"stoá","kjv_def":"porch","strongs_def":" a colonnade or interior piazza","derivation":"probably from G2476 (ἵστημι);","pron":"sto-ah'","pos":"Noun Feminine","thayer":"<ol><li>a portico, a covered colonnade where people can stand or walk protected from the weather and the heat of the sun</li><li>the portico built by Solomon in the eastern part of the temple</li></ol>","xlit":"stoá"},"G634":{"kjv_def":"fall","translit":"apopíptō","lemma":"ἀποπίπτω","derivation":"from G575 (ἀπό) and G4098 (πίπτω);","strongs_def":" to fall off","pron":"ap-op-ip'-to","pos":"Verb","thayer":"<ol><li>to fall off, slip down from</li></ol>","xlit":"apopíptō"},"G2505":{"lemma":"καθά","translit":"kathá","kjv_def":"as","strongs_def":" according to which things, i.e. just as","derivation":"from G2596 (κατά) and the neuter plural of G3739 (ὅς);","pron":"kath-ah'","thayer":"<ol><li>according as, just as</li></ol>","xlit":"kathá"},"G319":{"kjv_def":"be made known","lemma":"ἀναγνωρίζομαι","translit":"anagnōrízomai","derivation":"middle voice from G303 (ἀνά) and G1107 (γνωρίζω);","strongs_def":" to make (oneself) known","pron":"an-ag-no-rid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to recognise</li></ol>","xlit":"anagnōrízomai"},"G998":{"derivation":"from G995 (βοή) and theo (to run);","strongs_def":" a succorer","kjv_def":"helper","translit":"boēthós","lemma":"βοηθός","pron":"bo-ay-thos'","pos":"Adjective","thayer":"<ol><li>a helper</li></ol>","xlit":"boēthós"},"G1046":{"kjv_def":"Gadarene","lemma":"Γαδαρηνός","translit":"Gadarēnós","derivation":"from (a town east of the Jordan);","strongs_def":" a Gadarene or inhabitant of Gadara","pron":"gad-ar-ay-nos'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Gadarenes = \"reward at the end\"</p><ol><li>also called Gergesenes, was the capital of Peraea, situated opposite the south extremity of the Lake of Gennesaret to the south-east, but at some distance from the lake on the banks of the river Hieromax</li></ol>","xlit":"Gadarēnós"},"G2353":{"strongs_def":" stock (as raised on a farm)","derivation":"from G5142 (τρέφω);","translit":"thrémma","lemma":"θρέμμα","kjv_def":"cattle","pron":"threm'-mah","pos":"Noun Neuter","thayer":"<ol><li>whatever is fed or nursed<ol type='a'><li>a ward, nursling, child</li></ol><li>a flock, cattle, especially sheep and goats</li></ol>","xlit":"thrémma"},"G4844":{"derivation":"from G4862 (σύν) and G4095 (πίνω);","strongs_def":" to partake a beverage in company","kjv_def":"drink with","lemma":"συμπίνω","translit":"sympínō","pron":"soom-pee'-no","pos":"Verb","thayer":"<ol><li>to drink with</li></ol>","xlit":"sympínō"},"G5094":{"derivation":"from G5093 (τίμιος);","strongs_def":" expensiveness, i.e. (by implication) magnificence","kjv_def":"costliness","translit":"timiótēs","lemma":"τιμιότης","pron":"tim-ee-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>preciousness, costliness<ol type='a'><li>an abundance of costly things</li></ol><li>metaphorically worth, excellence</li></ol>","xlit":"timiótēs"},"G853":{"kjv_def":" corrupt, disfigure, perish, vanish away","translit":"aphanízō","lemma":"ἀφανίζω","derivation":"from G852 (ἀφανής);","strongs_def":" to render unapparent, i.e. (actively) consume (becloud), or (passively) disappear (be destroyed)","pron":"af-an-id'-zo","pos":"Verb","thayer":"<ol><li>to snatch out of sight, to put out of view, to make unseen</li><li>to cause to vanish away, to destroy, consume</li><li>to deprive of lustre, render unsightly<ol type='a'><li>to disfigure</li></ol></li></ol>","xlit":"aphanízō"},"G3571":{"lemma":"νύξ","translit":"nýx","kjv_def":" (mid-)night","strongs_def":" \"night\" (literally or figuratively)","derivation":"a primary word;","pron":"noox","pos":"Noun Feminine","thayer":"<ol><li>night</li><li>metaphorically the time when work ceases<ol type='a'><li>the time of death</li><li>the time for deeds of sin and shame</li><li>the time of moral stupidity and darkness</li><li>the time when the weary and also the drunken give themselves up to slumber</li></ol></li></ol>","xlit":"nýx"},"G1950":{"kjv_def":"(be) forget(-ful of)","lemma":"ἐπιλανθάνομαι","translit":"epilanthánomai","derivation":"middle voice from G1909 (ἐπί) and G2990 (λανθάνω);","strongs_def":" to lose out of mind; by implication, to neglect","pron":"ep-ee-lan-than'-om-ahee","pos":"Verb","thayer":"<ol><li>to forget</li><li>neglecting, no longer caring for</li><li>forgotten, given over to oblivion, i.e. uncared for</li></ol>","xlit":"epilanthánomai"},"G2883":{"derivation":"of Latin origin;","strongs_def":" Cornelius, a Roman","kjv_def":"Cornelius","lemma":"Κορνήλιος","translit":"Kornḗlios","pron":"kor-nay'-lee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cornelius = \"of a horn\"</p><ol><li>a Roman centurion of the Italian cohort stationed in Caesarea who converted to Christianity</li></ol>","xlit":"Kornḗlios"},"G4688":{"strongs_def":" a speculator, i.e. military scout (spy or (by extension) life-guardsman)","derivation":"of Latin origin;","translit":"spekoulátōr","lemma":"σπεκουλάτωρ","kjv_def":"executioner","pron":"spek-oo-lat'-ore","pos":"Noun Masculine","thayer":"<ol><li>a spy, scout</li><li>under the emperors an attendant and member of the body guard, employed as messengers, watchers, and executioners</li><li>the name is transferred to an attendant of Herod Antipas that acted as executioner</li></ol>","xlit":"spekoulátōr"},"G263":{"kjv_def":"that fadeth not away","lemma":"ἀμάραντος","translit":"amárantos","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G3133 (μαραίνω);","strongs_def":" unfading, i.e. (by implication) perpetual","pron":"am-ar'-an-tos","pos":"Adjective","thayer":"<ol><li>not fading away, unfading, perennial (See <u><a class='dict' href='#sG262'>G262</a></u>)</li></ol>","xlit":"amárantos"},"G3737":{"derivation":"of uncertain affinity;","strongs_def":" bereaved (\"orphan\"), i.e. parentless","kjv_def":"comfortless, fatherless","translit":"orphanós","lemma":"ὀρφανός","pron":"or-fan-os'","pos":"Adjective","thayer":"<ol><li>bereft (of a father, of parents)<ol type='a'><li>of those bereft of a teacher, guide, guardian</li><li>orphaned</li></ol></li></ol>","xlit":"orphanós"},"G1900":{"derivation":"from G1909 (ἐπί) and (the accusative case plural neuter of) G1565 (ἐκεῖνος);","strongs_def":" upon those parts of, i.e. on the further side of","kjv_def":"beyond","lemma":"ἐπέκεινα","translit":"epékeina","pron":"ep-ek'-i-nah","pos":"Adverb","thayer":"<ol><li>beyond</li></ol>","xlit":"epékeina"},"G5491":{"lemma":"χεῖλος","translit":"cheîlos","kjv_def":"lip, shore","strongs_def":" a lip (as a pouring place); figuratively, a margin (of water)","derivation":"from a form of the same as G5490 (χάσμα);","pron":"khi'-los","pos":"Noun Neuter","thayer":"<ol><li>a lip, of the speaking mouth</li><li>metaphorically the sea shore</li></ol>","xlit":"cheîlos"},"G2564":{"strongs_def":" to \"call\" (properly, aloud, but used in a variety of applications, directly or otherwise)","derivation":"akin to the base of G2753 (κελεύω);","lemma":"καλέω","translit":"kaléō","kjv_def":"bid, call (forth), (whose, whose sur-)name (was (called))","pron":"kal-eh'-o","pos":"Verb","thayer":"<ol><li>to call<ol type='a'><li>to call aloud, utter in a loud voice</li><li>to invite</li></ol><li>to call, i.e. to name, by name<ol type='a'><li>to give a name to<ol><li>to receive the name of, receive as a name</li><li>to give some name to one, call his name</li></ol><li>to be called, i.e. to bear a name or title (among men)</li><li>to salute one by name</li></ol></li></ol>","xlit":"kaléō"},"G3198":{"lemma":"Μελχισεδέκ","translit":"Melchisedék","kjv_def":"Melchisedec","strongs_def":" Melchisedek (i.e. Malkitsedek), a patriarch","derivation":"of Hebrew origin (H04442);","pron":"mel-khis-ed-ek'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Melchizedek = \"king of righteousness\"</p><ol><li>the king of Salem and priest of the most high God, who lived in the days of Abraham</li></ol>","xlit":"Melchisedék"},"G147":{"derivation":"adverb from G146 (αἰσχροκερδής);","strongs_def":" sordidly","kjv_def":"for filthy lucre's sake","lemma":"αἰσχροκερδῶς","translit":"aischrokerdōs","pron":"ahee-skhrok-er-doce'","pos":"Adverb","thayer":"<ol><li>eagerness for base gain</li></ol>","xlit":"aischrokerdōs"},"G396":{"derivation":"from G303 (ἀνά) and the base of G5157 (τροπή);","strongs_def":" to overturn (figuratively)","kjv_def":"overthrow, subvert","lemma":"ἀνατρέπω","translit":"anatrépō","pron":"an-at-rep'-o","pos":"Verb","thayer":"<ol><li>to overthrow, overturn, destroy</li><li>to subvert</li></ol>","xlit":"anatrépō"},"G2540":{"kjv_def":"X always, opportunity, (convenient, due) season, (due, short, while) time, a while","lemma":"καιρός","translit":"kairós","derivation":"of uncertain affinity;","strongs_def":" an occasion, i.e. set or proper time","pron":"kahee-ros'","pos":"Noun Masculine","thayer":"<ol><li>due measure</li><li>a measure of time, a larger or smaller portion of time, hence:<ol type='a'><li>a fixed and definite time, the time when things are brought to crisis, the decisive epoch waited for</li><li>opportune or seasonable time</li><li>the right time</li><li>a limited period of time</li><li>to what time brings, the state of the times, the things and events of time</li></ol></li></ol>","xlit":"kairós"},"G4910":{"lemma":"συνευωχέω","translit":"syneuōchéō","kjv_def":"feast with","strongs_def":" to entertain sumptuously in company with, i.e. (middle voice or passive) to revel together","derivation":"from G4862 (σύν) and a derivative of a presumed compound of G2095 (εὖ) and a derivative of G2192 (ἔχω) (meaning to be in good condition, i.e. (by implication) to fare well, or feast);","pron":"soon-yoo-o-kheh'-o","pos":"Verb","thayer":"<ol><li>to entertain together</li><li>to feast sumptuously with</li></ol>","xlit":"syneuōchéō"},"G1254":{"kjv_def":"forbid","translit":"diakōlýō","lemma":"διακωλύω","derivation":"from G1223 (διά) and G2967 (κωλύω);","strongs_def":" to hinder altogether, i.e. utterly prohibit","pron":"dee-ak-o-loo'-o","pos":"Verb","thayer":"<ol><li>to hinder, prevent</li></ol>","xlit":"diakōlýō"},"G3310":{"strongs_def":" a portion, i.e. province, share or (abstractly) participation","derivation":"feminine of G3313 (μέρος);","lemma":"μερίς","translit":"merís","kjv_def":"part (X -akers)","pron":"mer-ece'","pos":"Noun Feminine","thayer":"<ol><li>a part as distinct from the whole</li><li>an assigned part, a portion, share</li></ol>","xlit":"merís"},"G5271":{"derivation":"middle voice from G5259 (ὑπό) and G2919 (κρίνω);","strongs_def":" to decide (speak or act) under a false part, i.e. (figuratively) dissemble (pretend)","kjv_def":"feign","lemma":"ὑποκρίνομαι","translit":"hypokrínomai","pron":"hoop-ok-rin'-om-ahee","pos":"Verb","thayer":"<ol><li>to take up another's statements in reference to what one has decided for one's self<ol type='a'><li>to reply, answer</li></ol><li>to make answer (speak) on the stage<ol type='a'><li>to impersonate anyone, play a part</li></ol><li>to simulate, feign, pretend</li></ol>","xlit":"hypokrínomai"},"G5102":{"derivation":"of Latin origin;","strongs_def":" a titulus or \"title\" (placard)","kjv_def":"title","lemma":"τίτλος","translit":"títlos","pron":"tit'-los","pos":"Noun Masculine","thayer":"<ol><li>a title</li><li>an inscription, giving the accusation or crime for which a criminal suffered</li></ol>","xlit":"títlos"},"G415":{"derivation":"from G1 (Α) (as a negative particle) and G1655 (ἐλεήμων);","strongs_def":" merciless","kjv_def":"unmerciful","translit":"aneleḗmōn","lemma":"ἀνελεήμων","pron":"an-eleh-ay'-mone","pos":"Adjective","thayer":"<ol><li>without mercy, merciless</li></ol>","xlit":"aneleḗmōn"},"G2124":{"strongs_def":" properly, caution, i.e. (religiously) reverence (piety); by implication, dread (concretely)","derivation":"from G2126 (εὐλαβής);","lemma":"εὐλάβεια","translit":"eulábeia","kjv_def":"fear(-ed)","pron":"yoo-lab'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>caution, circumspection, discretion<ol type='a'><li>avoidance</li><li>a reasonable shunning</li></ol><li>reverence, veneration<ol type='a'><li>reverence toward God, godly fear, piety</li></ol><li>fear anxiety, dread</li></ol>","xlit":"eulábeia"},"G413":{"strongs_def":" not left out, i.e. (by implication) inexhaustible","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G1587 (ἐκλείπω);","lemma":"ἀνέκλειπτος","translit":"anékleiptos","kjv_def":"that faileth not","pron":"an-ek'-lipe-tos","pos":"Adjective","thayer":"<ol><li>unfailing</li></ol>","xlit":"anékleiptos"},"G1825":{"kjv_def":"raise up","translit":"exegeírō","lemma":"ἐξεγείρω","derivation":"from G1537 (ἐκ) and G1453 (ἐγείρω);","strongs_def":" to rouse fully, i.e. (figuratively) to resuscitate (from death), release (from infliction)","pron":"ex-eg-i'-ro","pos":"Verb","thayer":"<ol><li>to arouse, raise up (from sleep)</li><li>to rouse up, stir up, incite</li></ol>","xlit":"exegeírō"},"G5285":{"translit":"hypopnéō","lemma":"ὑποπνέω","kjv_def":"blow softly","strongs_def":" to breathe gently, i.e. breeze","derivation":"from G5259 (ὑπό) and G4154 (πνέω);","pron":"hoop-op-neh'-o","pos":"Verb","thayer":"<ol><li>to blow underneath</li><li>to blow softly</li></ol>","xlit":"hypopnéō"},"G248":{"strongs_def":" to tread out grain","derivation":"from the same as G257 (ἅλων);","translit":"aloáō","lemma":"ἀλοάω","kjv_def":"thresh, tread out the corn","pron":"al-o-ah'-o","pos":"Verb","thayer":"<ol><li>to thresh</li></ol>","xlit":"aloáō"},"G2805":{"kjv_def":"wailing, weeping, X wept","translit":"klauthmós","lemma":"κλαυθμός","derivation":"from G2799 (κλαίω);","strongs_def":" lamentation","pron":"klowth-mos'","pos":"Noun Masculine","thayer":"<ol><li>weeping, lamentation</li></ol>","xlit":"klauthmós"},"G1828":{"strongs_def":" to drag forth, i.e. (figuratively) to entice (to sin)","derivation":"from G1537 (ἐκ) and G1670 (ἑλκύω);","lemma":"ἐξέλκω","translit":"exélkō","kjv_def":"draw away","pron":"ex-el'-ko","pos":"Verb","thayer":"<ol><li>to draw out</li><li>metaphorically lure forth: in hunting and fishing as game is lured from its hiding place, so man by lure is allured from the safety of self-restraint to sin. In <a class='bible' href='#b59.1.14'>Jas 1:14</a>, the language of the hunting is transferred to the seduction of a harlot.</li></ol>","xlit":"exélkō"},"G5022":{"derivation":"apparently a primary word (compare H08450, \"steer\");","strongs_def":" a bullock","kjv_def":"bull, ox","translit":"taûros","lemma":"ταῦρος","pron":"tow'-ros","pos":"Noun Masculine","xlit":"taûros"},"G753":{"strongs_def":" a chief constructor, i.e. \"architect\"","derivation":"from G746 (ἀρχή) and G5045 (τέκτων);","translit":"architéktōn","lemma":"ἀρχιτέκτων","kjv_def":"masterbuilder","pron":"ar-khee-tek'-tone","pos":"Noun Masculine","thayer":"<ol><li>a master builder, an architect, the superintendent in the erection of buildings</li></ol>","xlit":"architéktōn"},"G4560":{"kjv_def":"fleshly","translit":"sárkinos","lemma":"σάρκινος","derivation":"from G4561 (σάρξ);","strongs_def":" similar to flesh, i.e. (by analogy) soft","pron":"sar'-kee-nos","pos":"Adjective","thayer":"<ol><li>fleshly, consisting of flesh, composed of flesh</li><li>pertaining to the body (as earthly and perishable material)</li><li>wholly given up to the flesh, rooted in the flesh as it were</li></ol>","xlit":"sárkinos"},"G5249":{"kjv_def":"beyond measure","translit":"hyperperissōs","lemma":"ὑπερπερισσῶς","derivation":"from G5228 (ὑπέρ) and G4057 (περισσῶς);","strongs_def":" superabundantly, i.e. exceedingly","pron":"hoop-er-per-is-soce'","pos":"Adverb","thayer":"<ol><li>beyond measure, exceedingly</li></ol>","xlit":"hyperperissōs"},"G3484":{"strongs_def":" Nain, a place in Palestine","derivation":"probably of Hebrew origin (compare H04999);","translit":"Naḯn","lemma":"Ναΐν","kjv_def":"Nain","pron":"nah-in'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Nain =meaning \"beauty\"</p><ol><li>a village in Galilee located at the north base of Little Hermon</li></ol>","xlit":"Naḯn"},"G1031":{"lemma":"βρύχω","translit":"brýchō","kjv_def":"gnash","strongs_def":" to grate the teeth (in pain or rage)","derivation":"a primary verb;","pron":"broo'-kho","pos":"Verb","thayer":"<ol><li>to grind, gnash with the teeth</li><li>to bite, to chew</li></ol>","xlit":"brýchō"},"G3764":{"translit":"oudépō","lemma":"οὐδέπω","kjv_def":"as yet not, never before (yet), (not) yet","strongs_def":" not even yet","derivation":"from G3761 (οὐδέ) and G4452 (-πω);","pron":"oo-dep'-o","pos":"Adverb","thayer":"<ol><li>not yet, not as yet</li></ol>","xlit":"oudépō"},"G865":{"kjv_def":"despiser of those that are good","translit":"aphilágathos","lemma":"ἀφιλάγαθος","derivation":"from G1 (Α) (as a negative particle) and G5358 (φιλάγαθος);","strongs_def":" hostile to virtue","pron":"af-il-ag'-ath-os","pos":"Adjective","thayer":"<ol><li>opposed to goodness and good men</li></ol>","xlit":"aphilágathos"},"G2754":{"translit":"kenodoxía","lemma":"κενοδοξία","kjv_def":"vain-glory","strongs_def":" empty glorying, i.e. self-conceit","derivation":"from G2755 (κενόδοξος);","pron":"ken-od-ox-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>vain glory, groundless, self esteem, empty pride</li><li>a vain opinion, error</li></ol>","xlit":"kenodoxía"},"G2196":{"derivation":"of Hebrew origin (H02226);","strongs_def":" Zara, (i.e. Zerach), an Israelite","kjv_def":"Zara","lemma":"Ζαρά","translit":"Zará","pron":"dzar-ah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Zara = \"a rising (as the sun)\"</p><ol><li>the son of Judah, ancestor of Christ</li></ol>","xlit":"Zará"},"G4753":{"lemma":"στράτευμα","translit":"stráteuma","kjv_def":"army, soldier, man of war","strongs_def":" an armament, i.e. (by implication) a body of troops (more or less extensive or systematic)","derivation":"from G4754 (στρατεύομαι);","pron":"strat'-yoo-mah","pos":"Noun Neuter","thayer":"<ol><li>an army</li><li>a band of soldiers</li><li>bodyguard, guards men</li></ol>","xlit":"stráteuma"},"G4552":{"strongs_def":" a \"sapphire\" or lapis-lazuli gem","derivation":"of Hebrew origin (H05601);","lemma":"σάπφειρος","translit":"sáppheiros","kjv_def":"sapphire","pron":"sap'-fi-ros","pos":"Noun Feminine","thayer":"<ol><li>sapphire, a precious stone</li></ol>","xlit":"sáppheiros"},"G211":{"kjv_def":"(alabaster) box","lemma":"ἀλάβαστρον","translit":"alábastron","derivation":"neuter of (of uncertain derivation), the name of a stone;","strongs_def":" properly, an \"alabaster\" box, i.e. (by extension) a perfume vase (of any material)","pron":"al-ab'-as-tron","pos":"Noun Neuter","thayer":"<ol><li>a box made of alabaster in which unguents are preserved</li></ol>","xlit":"alábastron"},"G4805":{"strongs_def":" co-yoked, i.e. (figuratively) as noun, a colleague; probably rather as a proper name; Syzygus, a Christian","derivation":"from G4801 (συζεύγνυμι);","translit":"sýzygos","lemma":"σύζυγος","kjv_def":"yokefellow","pron":"sood'-zoo-gos","pos":"Adjective","thayer":"<ol><li>yoked together<ol type='a'><li>of those united by the bond of marriage, relationship, office, labour, study, business, or the like</li><li>of a yoke fellow, consort, comrade, colleague, partner</li></ol></li></ol>","xlit":"sýzygos"},"G1062":{"strongs_def":" nuptials","derivation":"of uncertain affinity;","translit":"gámos","lemma":"γάμος","kjv_def":"marriage, wedding","pron":"gam'-os","pos":"Noun Masculine","thayer":"<ol><li>a wedding or marriage festival, a wedding banquet, a wedding feast</li><li>marriage, matrimony</li></ol>","xlit":"gámos"},"G3567":{"strongs_def":" the bridal room","derivation":"from G3565 (νύμφη);","translit":"nymphṓn","lemma":"νυμφών","kjv_def":"bridechamber","pron":"noom-fohn'","pos":"Noun Masculine","thayer":"<ol><li>the chamber containing the bridal bed, the bridal chamber<ol type='a'><li>of the friends of the bridegroom whose duty it was to provide and care for whatever pertained to the bridal chamber, i.e. whatever was needed for the due celebration of the nuptials</li><li>the room in which the marriage ceremonies are held</li></ol></li></ol>","xlit":"nymphṓn"},"G3912":{"lemma":"παραφρονέω","translit":"paraphronéō","kjv_def":"as a fool","strongs_def":" to misthink, i.e. be insane (silly)","derivation":"from G3844 (παρά) and G5426 (φρονέω);","pron":"par-af-ron-eh'-o","pos":"Verb","thayer":"<ol><li>to be beside one's self, out of one's senses, void of understanding, insane</li></ol>","xlit":"paraphronéō"},"G4154":{"strongs_def":" to breathe hard, i.e. breeze","derivation":"a primary word;","translit":"pnéō","lemma":"πνέω","kjv_def":"blow","pron":"pneh'-o","pos":"Verb","thayer":"<ol><li>to breathe, to blow<ol type='a'><li>of the wind</li></ol></li></ol>","xlit":"pnéō"},"G1655":{"translit":"eleḗmōn","lemma":"ἐλεήμων","kjv_def":"merciful","strongs_def":" compassionate (actively)","derivation":"from G1653 (ἐλεέω);","pron":"el-eh-ay'-mone","pos":"Adjective","thayer":"<ol><li>merciful</li></ol>","xlit":"eleḗmōn"},"G3803":{"lemma":"παγίς","translit":"pagís","kjv_def":"snare","strongs_def":" a trap (as fastened by a noose or notch); figuratively, a trick or statagem (temptation)","derivation":"from G4078 (πήγνυμι);","pron":"pag-ece'","pos":"Noun Feminine","thayer":"<ol><li>snare, trap, noose<ol type='a'><li>of snares in which birds are entangled and caught<ol><li>implies unexpectedly, suddenly, because birds and beasts are caught unawares</li></ol><li>a snare, i.e. whatever brings peril, loss, destruction<ol><li>of a sudden and unexpected deadly peril</li><li>of the allurements and seductions of sin</li><li>the allurements to sin by which the devil holds one bound</li><li>the snares of love</li></ol></li></ol></li></ol>","xlit":"pagís"},"G1245":{"strongs_def":" to cleanse perfectly, i.e. (specially) winnow","derivation":"from G1223 (διά) and G2511 (καθαρίζω);","lemma":"διακαθαρίζω","translit":"diakatharízō","kjv_def":"thoroughly purge","pron":"dee-ak-ath-ar-id'-zo","pos":"Verb","thayer":"<ol><li>to cleanse thoroughly</li></ol>","xlit":"diakatharízō"},"G5515":{"strongs_def":" greenish, i.e. verdant, dun-colored","derivation":"from the same as G5514 (Χλόη);","translit":"chlōrós","lemma":"χλωρός","kjv_def":"green, pale","pron":"khlo-ros'","pos":"Adjective","thayer":"<ol><li>green</li><li>yellowish pale</li></ol>","xlit":"chlōrós"},"G3100":{"strongs_def":" intransitively, to become a pupil; transitively, to disciple, i.e. enrol as scholar","derivation":"from G3101 (μαθητής);","translit":"mathēteúō","lemma":"μαθητεύω","kjv_def":"be disciple, instruct, teach","pron":"math-ayt-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a disciple of one<ol type='a'><li>to follow his precepts and instructions</li></ol><li>to make a disciple<ol type='a'><li>to teach, instruct</li></ol></li></ol>","xlit":"mathēteúō"},"G3051":{"lemma":"λόγιον","translit":"lógion","kjv_def":"oracle","strongs_def":" an utterance (of God)","derivation":"neuter of G3052 (λόγιος);","pron":"log'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a brief utterance, a divine oracle (doubtless because oracles were generally brief)<ol type='a'><li>in the NT, the words or utterances of God</li><li>of the contents of the Mosaic law</li></ol></li></ol>","xlit":"lógion"},"G816":{"strongs_def":" to gaze intently","derivation":"from a compound of G1 (Α) (as a particle of union) and (to stretch);","lemma":"ἀτενίζω","translit":"atenízō","kjv_def":"behold earnestly (stedfastly), fasten (eyes), look (earnestly, stedfastly, up stedfastly), set eyes","pron":"at-en-id'-zo","pos":"Verb","thayer":"<ol><li>to fix the eyes on, gaze upon</li><li>to look into anything</li><li>metaphorically to fix one's mind on one as an example</li></ol>","xlit":"atenízō"},"G3974":{"strongs_def":" Paphus, a place in Cyprus","derivation":"of uncertain derivation;","translit":"Páphos","lemma":"Πάφος","kjv_def":"Paphos","pron":"paf'-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Paphos = \"boiling or hot\"</p><ol><li>a maritime city on the west end of Cyprus, with a harbour. It was the residence of a Roman proconsul. \"Old Paphos\" was noted for the worship and shrine of Venus (Aphrodite) and lay some 7 miles (10 km) to the south-east of it.</li></ol>","xlit":"Páphos"},"G689":{"translit":"Arám","lemma":"Ἀράμ","kjv_def":"Aram","strongs_def":" Aram (i.e. Ram), an Israelite","derivation":"of Hebrew origin (H07410);","pron":"ar-am'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aram or Ram = \"high\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Arám"},"G217":{"kjv_def":"salt","lemma":"ἅλας","translit":"hálas","derivation":"from G251 (ἅλς);","strongs_def":" salt; figuratively, prudence","pron":"hal'-as","pos":"Noun Neuter","thayer":"<ol><li>salt with which food is seasoned and sacrifices are sprinkled</li><li>those kinds of saline matter used to fertilise arable land</li><li>salt is a symbol of lasting concord, because it protects food from putrefaction and preserves it unchanged. Accordingly, in the solemn ratification of compacts, the orientals were, and are to this day, accustomed to partake of salt together</li><li>wisdom and grace exhibited in speech</li></ol>","xlit":"hálas"},"G4895":{"derivation":"from G4862 (σύν) and G1510 (εἰμί) (including its various inflections);","strongs_def":" to be in company with, i.e. present at the time","kjv_def":"be with","translit":"sýneimi","lemma":"σύνειμι","pron":"soon'-i-mee","pos":"Verb","thayer":"<ol><li>to be with</li></ol>","xlit":"sýneimi"},"G1279":{"strongs_def":" to travel through","derivation":"from G1223 (διά) and G4198 (πορεύομαι);","lemma":"διαπορεύομαι","translit":"diaporeúomai","kjv_def":"go through, journey in, pass by","pron":"dee-ap-or-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to cause to pass through a place</li><li>to carry across</li><li>to journey through a place, go through</li><li>to travel through</li></ol>","xlit":"diaporeúomai"},"G3889":{"kjv_def":"comfort","lemma":"παραμυθία","translit":"paramythía","derivation":"from G3888 (παραμυθέομαι);","strongs_def":" consolation (properly, abstract)","pron":"par-am-oo-thee'-ah","pos":"Noun Feminine","thayer":"<ol><li>any address, whether made for the purpose of persuading, or of arousing and stimulating, or of calming and consoling<ol type='a'><li>consolation, comfort</li></ol></li></ol>","xlit":"paramythía"},"G4328":{"strongs_def":" to anticipate (in thought, hope or fear); by implication, to await","derivation":"from G4314 (πρός) and dokeuo (to watch);","lemma":"προσδοκάω","translit":"prosdokáō","kjv_def":"(be in) expect(-ation), look (for), when looked, tarry, wait for","pron":"pros-dok-ah'-o","pos":"Verb","thayer":"<ol><li>to expect (whether in thought, in hope, or in fear)</li><li>to look for, wait for</li></ol>","xlit":"prosdokáō"},"G1561":{"lemma":"ἐκδοχή","translit":"ekdochḗ","kjv_def":"looking for","strongs_def":" expectation","derivation":"from G1551 (ἐκδέχομαι);","pron":"ek-dokh-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act or manner of receiving from<ol type='a'><li>reception</li><li>succession</li><li>interpretation</li><li>expectation, waiting</li></ol></li></ol>","xlit":"ekdochḗ"},"G4580":{"kjv_def":"Secundus","lemma":"Σεκοῦνδος","translit":"Sekoûndos","derivation":"of Latin origin;","strongs_def":" \"second\"; Secundus, a Christian","pron":"sek-oon'-dos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Secundus = \"fortunate\"</p><ol><li>a Thessalonian Christian</li></ol>","xlit":"Sekoûndos"},"G5513":{"lemma":"χλιαρός","translit":"chliarós","kjv_def":"lukewarm","strongs_def":" tepid","derivation":"from (to warm);","pron":"khlee-ar-os'","pos":"Adjective","thayer":"<ol><li>tepid, lukewarm</li><li>metaphorically of the condition of the soul wretchedly fluctuating between a torpor and a fervour of love</li></ol>","xlit":"chliarós"},"G1199":{"derivation":"neuter and masculine respectively from G1210 (δέω);","strongs_def":" a band, i.e. ligament (of the body) or shackle (of a prisoner); figuratively, an impediment or disability","kjv_def":"band, bond, chain, string","lemma":"δεσμόν","translit":"desmón","pron":"des-mon'","pos":"Noun Masculine","thayer":"<ol><li>a band or bond</li></ol>","xlit":"desmón"},"G2346":{"strongs_def":" to crowd (literally or figuratively)","derivation":"akin to the base of G5147 (τρίβος);","lemma":"θλίβω","translit":"thlíbō","kjv_def":"afflict, narrow, throng, suffer tribulation, trouble","pron":"thlee'-bo","pos":"Verb","thayer":"<ol><li>to press (as grapes), press hard upon</li><li>a compressed way<ol type='a'><li>narrow straitened, contracted</li></ol><li>metaphorically to trouble, afflict, distress</li></ol>","xlit":"thlíbō"},"G1978":{"kjv_def":"notable, of note","translit":"epísēmos","lemma":"ἐπίσημος","derivation":"from G1909 (ἐπί) and some form of the base of G4591 (σημαίνω);","strongs_def":" remarkable, i.e. (figuratively) eminent","pron":"ep-is'-ay-mos","pos":"Adjective","thayer":"<ol><li>having a mark on it, marked, stamped, coined</li><li>marked<ol type='a'><li>in a good sense<ol><li>of note, illustrious</li></ol><li>in a bad sense<ol><li>notorious, infamous</li></ol></li></ol></li></ol>","xlit":"epísēmos"},"G3537":{"kjv_def":"bason","lemma":"νιπτήρ","translit":"niptḗr","derivation":"from G3538 (νίπτω);","strongs_def":" a ewer","pron":"nip-tare'","pos":"Noun Masculine","thayer":"<ol><li>a vessel for washing the hands and the feet, a basin</li></ol>","xlit":"niptḗr"},"G2218":{"kjv_def":"pair of balances, yoke","lemma":"ζυγός","translit":"zygós","derivation":"from the root of (to join, especially by a \"yoke\");","strongs_def":" a coupling, i.e. (figuratively) servitude (a law or obligation); also (literally) the beam of the balance (as connecting the scales)","pron":"dzoo-gos'","pos":"Noun Masculine","thayer":"<ol><li>a yoke<ol type='a'><li>a yoke that is put on draught cattle</li><li>metaphorically, used of any burden or bondage<ol><li>as that of slavery</li><li>of troublesome laws imposed on one, especially of the Mosaic law, hence the name is so transferred to the commands of Christ as to contrast them with the commands of the Pharisees which were a veritable 'yoke'; yet even Christ's commands must be submitted to, though easier to be kept</li></ol></li></ol><li>a balance, pair of scales</li></ol>","xlit":"zygós"},"G4975":{"derivation":"neuter of a presumed derivative of the alternate of G2192 (ἔχω) as adverb;","strongs_def":" nigh, i.e. nearly","kjv_def":"almost","translit":"schedón","lemma":"σχεδόν","pron":"skhed-on'","pos":"Adverb","thayer":"<ol><li>near, hard by</li><li>well nigh, nearly, almost</li></ol>","xlit":"schedón"},"G4529":{"derivation":"probably from G4535 (σάλος) (from the surge on the shore);","strongs_def":" Salamis, a place in Cyprus","kjv_def":"Salamis","lemma":"Σαλαμίς","translit":"Salamís","pron":"sal-am-ece'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Salmis = \"salt\"</p><ol><li>a principal city at the east end of the island of Cyprus</li></ol>","xlit":"Salamís"},"G1061":{"strongs_def":" to espouse (a daughter to a husband)","derivation":"from G1062 (γάμος);","lemma":"γαμίσκω","translit":"gamískō","kjv_def":"give in marriage","pron":"gam-is'-ko","pos":"Verb","thayer":"<ol><li>give in marriage</li></ol>","xlit":"gamískō"},"G645":{"derivation":"from G575 (ἀπό) and G4685 (σπάω);","strongs_def":" to drag forth, i.e. (literally) unsheathe (a sword), or relatively (with a degree of force implied) retire (personally or factiously)","kjv_def":"(with-)draw (away), after we were gotten from","translit":"apospáō","lemma":"ἀποσπάω","pron":"ap-os-pah'-o","pos":"Verb","thayer":"<ol><li>to draw off, tear away</li></ol>","xlit":"apospáō"},"G3680":{"kjv_def":"reproach","translit":"oneidismós","lemma":"ὀνειδισμός","derivation":"from G3679 (ὀνειδίζω);","strongs_def":" contumely","pron":"on-i-dis-mos'","pos":"Noun Masculine","thayer":"<ol><li>a reproach<ol type='a'><li>such as Christ suffered, for the cause of God, from his enemies</li></ol></li></ol>","xlit":"oneidismós"},"G3372":{"lemma":"μῆκος","translit":"mēkos","derivation":"probably akin to G3173 (μέγας);","strongs_def":" length (literally or figuratively) length. ","pron":"may'-kos","pos":"Noun Neuter","thayer":"<ol><li>length</li></ol>","xlit":"mēkos"},"G2277":{"kjv_def":"let … be","lemma":"ἤτω","translit":"ḗtō","derivation":"third person singular imperative of G1510 (εἰμί);","strongs_def":" let him (or it) be","pron":"ay'-to","pos":"Verb","thayer":"<ol><li>let him (it) be</li></ol>","xlit":"ḗtō"},"G5263":{"derivation":"from G5259 (ὑπό) and G1166 (δεικνύω);","strongs_def":" to exhibit under the eyes, i.e. (figuratively) to exemplify (instruct, admonish)","kjv_def":"show, (fore-)warn","lemma":"ὑποδείκνυμι","translit":"hypodeíknymi","pron":"hoop-od-ike'-noo-mee","pos":"Verb","thayer":"<ol><li>to show by placing under (i.e. before) the eyes</li><li>to show by words and arguments, i.e. to teach</li><li>to show by make known future things</li></ol>","xlit":"hypodeíknymi"},"G4770":{"kjv_def":"Stoick","lemma":"Στωϊκός","translit":"Stōïkós","derivation":"from G4745 (στοά);","strongs_def":" a \"Stoic\" (as occupying a particular porch in Athens), i.e. adherent of a certin philosophy","pron":"sto-ik-os'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Stoics = \"of the portico\"</p><ol><li>pertaining to the Stoic philosophy, the author of which, Zeno of Citium, taught at Athens</li></ol>","xlit":"Stōïkós"},"G3920":{"derivation":"from G3919 (παρεισάγω);","strongs_def":" smuggled in","kjv_def":"unawares brought in","translit":"pareísaktos","lemma":"παρείσακτος","pron":"par-ice'-ak-tos","pos":"Adjective","thayer":"<ol><li>secretly or surreptitiously brought in</li><li>one who has stolen in</li></ol>","xlit":"pareísaktos"},"G1863":{"derivation":"from G1909 (ἐπί) and G71 (ἄγω);","strongs_def":" to superinduce, i.e. inflict (an evil), charge (a crime)","kjv_def":"bring upon","lemma":"ἐπάγω","translit":"epágō","pron":"ep-ag'-o","pos":"Verb","thayer":"<ol><li>to lead or bring upon</li><li>to bring a thing on one<ol type='a'><li>to cause something to befall one, usually something evil</li></ol></li></ol>","xlit":"epágō"},"G19":{"kjv_def":"goodness","lemma":"ἀγαθωσύνη","translit":"agathōsýnē","derivation":"from G18 (ἀγαθός);","strongs_def":" goodness, i.e. virtue or beneficence","pron":"ag-ath-o-soo'-nay","pos":"Noun Feminine","thayer":"<ol><li>uprightness of heart and life, goodness, kindness</li></ol>","xlit":"agathōsýnē"},"G5525":{"lemma":"χορός","translit":"chorós","kjv_def":"dancing","strongs_def":" a ring, i.e. round dance (\"choir\"","derivation":"of uncertain derivation;","pron":"khor-os'","pos":"Noun Masculine","thayer":"<ol><li>a band (of dancers and singers), circular dance, a dance, dancing</li></ol>","xlit":"chorós"},"G3574":{"strongs_def":" a day-and-night, i.e. full day of twenty-four hours","derivation":"from G3571 (νύξ) and G2250 (ἡμέρα);","lemma":"νυχθήμερον","translit":"nychthḗmeron","kjv_def":"night and day","pron":"nookh-thay'-mer-on","pos":"Noun Neuter","thayer":"<ol><li>a night and a day, the space of twenty four hours</li></ol>","xlit":"nychthḗmeron"},"G2334":{"lemma":"θεωρέω","translit":"theōréō","kjv_def":"behold, consider, look on, perceive, see","strongs_def":" to be a spectator of, i.e. discern, (literally, figuratively (experience) or intensively (acknowledge))","derivation":"from a derivative of G2300 (θεάομαι) (perhaps by addition of G3708 (ὁράω));","pron":"theh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to be a spectator, look at, behold<ol type='a'><li>to view attentively, take a view of, survey<ol><li>to view mentally, consider</li></ol></li></ol><li>to see<ol type='a'><li>to perceive with the eyes, to enjoy the presence of one</li><li>to discern, descry</li><li>to ascertain, find out by seeing</li></ol></li></ol>","xlit":"theōréō"},"G639":{"lemma":"ἀπορέω","translit":"aporéō","kjv_def":" (stand in) doubt, be perplexed","strongs_def":" to have no way out, i.e. be at a loss (mentally)","derivation":"from a compound of G1 (Α) (as a negative particle) and the base of G4198 (πορεύομαι);","pron":"ap-or-eh'-o","pos":"Verb","thayer":"<ol><li>to be without resources, to be in straits, to be left wanting, to be embarrassed, to be in doubt, not to know which way to turn</li><li>to be at a loss with one's self, be in doubt</li><li>not to know how to decide or what to do, to be perplexed</li></ol>","xlit":"aporéō"},"G200":{"translit":"akrís","lemma":"ἀκρίς","kjv_def":"locust","strongs_def":" a locust (as pointed, or as lighting on the top of vegetation)","derivation":"apparently from the same as G206 (ἄκρον);","pron":"ak-rece'","pos":"Noun Feminine","thayer":"<ol><li>a locust, particularly that species which especially infests oriental countries, stripping fields and trees. Numberless swarms of them almost every spring are carried by the wind from Arabia into Palestine, and having devastated that country, migrate to regions farther north, until they perish by falling into the sea. The Orientals accustomed to feed upon locusts, either raw or roasted and seasoned with salt (or prepared in other ways), and the Israelites also were permitted to eat them.</li></ol>","xlit":"akrís"},"G983":{"derivation":"from G984 (βλάπτω);","strongs_def":" injurious","kjv_def":"hurtful","lemma":"βλαβερός","translit":"blaberós","pron":"blab-er-os'","pos":"Adjective","thayer":"<ol><li>hurtful, injurious</li></ol>","xlit":"blaberós"},"G2071":{"kjv_def":"shall (should) be (have), (shall) come (to pass), X may have, X fall, what would follow, X live long, X sojourn","lemma":"ἔσομαι","translit":"ésomai","derivation":"future of G1510 (εἰμί);","strongs_def":" will be","pron":"es'-om-ahee","pos":"Verb","thayer":"<ol><li>future first person singular of \"to be\"</li></ol>","xlit":"ésomai"},"G2367":{"lemma":"θύϊνος","translit":"thýïnos","kjv_def":"thyine","strongs_def":" denoting a certain fragrant tree); made of citron-wood","derivation":"from a derivative of G2380 (θύω) (in the sense of blowing;","pron":"thoo'-ee-nos","pos":"Adjective","thayer":"<ol><li>the citrus, an odoriferous North African tree used as incense, prized by the ancient Greeks and Romans on account of the beauty of its wood for various ornamental purposes</li></ol>","xlit":"thýïnos"},"G823":{"kjv_def":" moment","translit":"átomos","lemma":"ἄτομος","derivation":"from G1 (Α) (as a negative particle) and the base of G5114 (τομώτερος);","strongs_def":" uncut, i.e. (by implication) indivisible (an \"atom\" of time)","pron":"at'-om-os","pos":"Adjective","thayer":"<ol><li>that cannot be cut in two, or divided, indivisible<ol type='a'><li>of a moment of time</li></ol></li></ol>","xlit":"átomos"},"G3330":{"lemma":"μεταδίδωμι","translit":"metadídōmi","kjv_def":"give, impart","strongs_def":" to give over, i.e. share","derivation":"from G3326 (μετά) and G1325 (δίδωμι);","pron":"met-ad-id'-o-mee","pos":"Verb","thayer":"<ol><li>to impart</li></ol>","xlit":"metadídōmi"},"G1523":{"lemma":"εἰσδέχομαι","translit":"eisdéchomai","kjv_def":"receive","strongs_def":" to take into one's favor","derivation":"from G1519 (εἰς) and G1209 (δέχομαι);","pron":"ice-dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive kindly, to treat with favour</li></ol>","xlit":"eisdéchomai"},"G2445":{"strongs_def":" Joppe (i.e. Japho), a place in Palestine","derivation":"of Hebrew origin (H03305);","lemma":"Ἰόππη","translit":"Ióppē","kjv_def":"Joppa","pron":"ee-op'-pay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Joppa or Japho = \"beautiful\"</p><ol><li>a city of Palestine on the Mediterranean, lying on the border of the tribes of Dan and Ephraim. It was subject to the Jews from the times of the Maccabees. It had a famous but dangerous port and carried on a flourishing trade. It is now called Jaffa.</li></ol>","xlit":"Ióppē"},"G1398":{"kjv_def":"be in bondage, (do) serve(-ice)","lemma":"δουλεύω","translit":"douleúō","derivation":"from G1401 (δοῦλος);","strongs_def":" to be a slave to (literal or figurative, involuntary or voluntary)","pron":"dool-yoo'-o","pos":"Verb","thayer":"<ol><li>to be a slave, serve, do service<ol type='a'><li>of a nation in subjection to other nations</li></ol><li>metaphorically to obey, submit to<ol type='a'><li>in a good sense, to yield obedience</li><li>in a bad sense, of those who become slaves to some base power, to yield to, give one's self up to</li></ol></li></ol>","xlit":"douleúō"},"G4084":{"kjv_def":"apprehend, catch, lay hand on, take","translit":"piázō","lemma":"πιάζω","derivation":"probably another form of G971 (βιάζω);","strongs_def":" to squeeze, i.e. seize (gently by the hand (press), or officially (arrest), or in hunting (capture))","pron":"pee-ad'-zo","pos":"Verb","thayer":"<ol><li>to lay hold of</li><li>to take, capture<ol type='a'><li>of fishes</li></ol><li>to apprehend<ol type='a'><li>of a man, in order to imprison him</li></ol></li></ol>","xlit":"piázō"},"G4070":{"kjv_def":"+ a year ago","translit":"pérysi","lemma":"πέρυσι","derivation":"adverb from G4009 (πέρας);","strongs_def":" the by-gone, i.e. (as noun) last year","pron":"per'-oo-si","pos":"Adverb","thayer":"<ol><li>last year</li><li>the year just past<ol type='a'><li>for a year past, a year ago</li></ol></li></ol>","xlit":"pérysi"},"G5369":{"derivation":"from G5384 (φίλος) and G2237 (ἡδονή);","strongs_def":" fond of pleasure, i.e. voluptuous","kjv_def":"lover of pleasure","lemma":"φιλήδονος","translit":"philḗdonos","pron":"fil-ay'-don-os","pos":"Adjective","thayer":"<ol><li>loving pleasure</li></ol>","xlit":"philḗdonos"},"G3772":{"derivation":"perhaps from the same as G3735 (ὄρος) (through the idea of elevation);","strongs_def":" the sky; by extension, heaven (as the abode of God); by implication, happiness, power, eternity; specially, the Gospel (Christianity)","kjv_def":"air, heaven(-ly), sky","lemma":"οὐρανός","translit":"ouranós","pron":"oo-ran-os'","pos":"Noun Masculine","thayer":"<ol><li>the vaulted expanse of the sky with all things visible in it<ol type='a'><li>the universe, the world</li><li>the aerial heavens or sky, the region where the clouds and the tempests gather, and where thunder and lightning are produced</li><li>the sidereal or starry heavens</li></ol><li>the region above the sidereal heavens, the seat of order of things eternal and consummately perfect where God dwells and other heavenly beings</li></ol>","xlit":"ouranós"},"G3935":{"derivation":"from G3844 (παρά) and hiemi (to send);","strongs_def":" to let by, i.e. relax","kjv_def":"hang down","translit":"paríēmi","lemma":"παρίημι","pron":"par-ee'-ay-mi","pos":"Verb","thayer":"<ol><li>to let pass<ol type='a'><li>to pass by, neglect</li><li>to disregard, omit</li></ol><li>to relax, loose, let go</li><li>relaxed, unstrung, weakened, exhausted</li></ol>","xlit":"paríēmi"},"G2955":{"translit":"kýptō","lemma":"κύπτω","kjv_def":"stoop (down)","strongs_def":" to bend forward","derivation":"probably from the base of G2949 (κῦμα);","pron":"koop'-to","pos":"Verb","thayer":"<ol><li>to stoop down, bend forward, to bow the head</li></ol>","xlit":"kýptō"},"G2406":{"derivation":"from G2407 (ἱερατεύω);","strongs_def":" the priestly fraternity, i.e. sacerdotal order (figuratively)","kjv_def":"priesthood","translit":"hieráteuma","lemma":"ἱεράτευμα","pron":"hee-er-at'-yoo-mah","pos":"Noun Neuter","thayer":"<ol><li>the office of a priest</li><li>the order or body of priests</li></ol>","xlit":"hieráteuma"},"G4779":{"translit":"synkaléō","lemma":"συγκαλέω","kjv_def":"call together","strongs_def":" to convoke","derivation":"from G4862 (σύν) and G2564 (καλέω);","pron":"soong-kal-eh'-o","pos":"Verb","thayer":"<ol><li>to call together, assemble</li><li>to call together to one's self</li></ol>","xlit":"synkaléō"},"G41":{"strongs_def":" sanctity (i.e. properly, the state)","derivation":"from G40 (ἅγιος);","translit":"hagiótēs","lemma":"ἁγιότης","kjv_def":"holiness","pron":"hag-ee-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>sanctity</li><li>in a moral sense: holiness</li></ol>","xlit":"hagiótēs"},"G3168":{"translit":"megaleiótēs","lemma":"μεγαλειότης","kjv_def":"magnificence, majesty, mighty power","strongs_def":" superbness, i.e. glory or splendor","derivation":"from G3167 (μεγαλεῖος);","pron":"meg-al-i-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>greatness, magnificence<ol type='a'><li>of the majesty of God</li><li>of the visible splendour of the divine majesty as it appeared in the transfiguration of Christ</li></ol></li></ol>","xlit":"megaleiótēs"},"G5213":{"derivation":"irregular dative case of G5210 (ὑμεῖς);","strongs_def":" to (with or by) you","kjv_def":"ye, you, your(-selves)","translit":"hymîn","lemma":"ὑμῖν","pron":"hoo-min'","thayer":"<ol><li>you</li></ol>","xlit":"hymîn"},"G4350":{"kjv_def":"beat upon, dash, stumble (at)","lemma":"προσκόπτω","translit":"proskóptō","derivation":"from G4314 (πρός) and G2875 (κόπτω);","strongs_def":" to strike at, i.e. surge against (as water); specially, to stub on, i.e. trip up (literally or figuratively)","pron":"pros-kop'-to","pos":"Verb","thayer":"<ol><li>to strike against<ol type='a'><li>of those who strike against a stone or other obstacle in the path, to stumble</li><li>to strike one's foot against a stone<ol><li>i.e. to meet with some harm</li></ol><li>to rush upon, beat against</li><li>to be made to stumble by a thing<ol><li>i.e. metaphorically to be induced to sin</li></ol></li></ol></li></ol>","xlit":"proskóptō"},"G3490":{"kjv_def":"owner of a ship","lemma":"ναύκληρος","translit":"naúklēros","derivation":"from G3491 (ναῦς) and G2819 (κλῆρος) (\"clerk\");","strongs_def":" a captain","pron":"now'-klay-ros","pos":"Noun Masculine","thayer":"<ol><li>a ship owner, ship master<ol type='a'><li>one who hires out his vessel, or a portion of it, for purposes of transportation</li></ol></li></ol>","xlit":"naúklēros"},"G4635":{"strongs_def":" a manufacturer of tents","derivation":"from G4633 (σκηνή) and G4160 (ποιέω);","lemma":"σκηνοποιός","translit":"skēnopoiós","kjv_def":"tent-maker","pron":"skay-nop-oy-os'","pos":"Adjective","thayer":"<ol><li>a tentmaker</li><li>one that makes small portable tents, of leather or cloth of goat's hair or linen, for the use of travellers</li></ol>","xlit":"skēnopoiós"},"G1433":{"lemma":"δωρέομαι","translit":"dōréomai","kjv_def":"give","strongs_def":" to bestow gratuitously","derivation":"middle voice from G1435 (δῶρον);","pron":"do-reh'-om-ahee","pos":"Verb","thayer":"<ol><li>to present, bestow</li></ol>","xlit":"dōréomai"},"G572":{"strongs_def":" singleness, i.e. (subjectively) sincerity (without dissimulation or self-seeking), or (objectively) generosity (copious bestowal)","derivation":"from G573 (ἁπλοῦς);","translit":"haplótēs","lemma":"ἁπλότης","kjv_def":"bountifulness, liberal(-ity), simplicity, singleness","pron":"hap-lot'-ace","pos":"Noun Feminine","thayer":"<ol><li>singleness, simplicity, sincerity, mental honesty<ol type='a'><li>the virtue of one who is free from pretence and hypocrisy</li></ol><li>not self seeking, openness of heart manifesting itself by generousity</li></ol>","xlit":"haplótēs"},"G4345":{"lemma":"προσκληρόω","translit":"prosklēróō","kjv_def":"consort with","strongs_def":" to give a common lot to, i.e. (figuratively) to associate with","derivation":"from G4314 (πρός) and G2820 (κληρόω);","pron":"pros-klay-ro'-o","pos":"Verb","thayer":"<ol><li>to add or assign by lot, to allot</li></ol>","xlit":"prosklēróō"},"G3060":{"strongs_def":" abusive, i.e. a blackguard","derivation":"from (mischief);","lemma":"λοίδορος","translit":"loídoros","kjv_def":"railer, reviler","pron":"loy'-dor-os","pos":"Noun Masculine","thayer":"<ol><li>a railer, reviler</li></ol>","xlit":"loídoros"},"G1679":{"derivation":"from G1680 (ἐλπίς);","strongs_def":" to expect or confide","kjv_def":"(have, thing) hope(-d) (for), trust","translit":"elpízō","lemma":"ἐλπίζω","pron":"el-pid'-zo","pos":"Verb","thayer":"<ol><li>to hope<ol type='a'><li>in a religious sense, to wait for salvation with joy and full confidence</li></ol><li>hopefully to trust in</li></ol>","xlit":"elpízō"},"G651":{"kjv_def":"apostleship","translit":"apostolḗ","lemma":"ἀποστολή","derivation":"from G649 (ἀποστέλλω);","strongs_def":" commission, i.e. (specially) apostolate","pron":"ap-os-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a sending away<ol type='a'><li>of the sending off of a fleet</li><li>of consuls with an army, i.e. of an expedition</li></ol><li>a sending away, i.e. a dismissal, release</li><li>a thing sent, especially of gifts</li><li>in the NT, the office and dignity of the apostles of Christ, apostleship</li></ol>","xlit":"apostolḗ"},"G3942":{"strongs_def":" apparently a state alongside of supposition, i.e. (concretely) an adage; specially, an enigmatical or fictitious illustration","derivation":"from a compound of G3844 (παρά) and perhaps a derivative of G3633 (οἴομαι);","translit":"paroimía","lemma":"παροιμία","kjv_def":"parable, proverb","pron":"par-oy-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a saying out of the usual course or deviating from the usual manner of speaking<ol type='a'><li>a current or trite saying, a proverb</li></ol><li>any dark saying which shadows forth some didactic truth<ol type='a'><li>especially a symbolic or figurative saying</li><li>speech or discourse in which a thing is illustrated by the use of similes and comparisons</li><li>an allegory<ol><li>extended and elaborate metaphor</li></ol></li></ol></li></ol>","xlit":"paroimía"},"G3345":{"lemma":"μετασχηματίζω","translit":"metaschēmatízō","kjv_def":"transfer, transform (self)","strongs_def":" to transfigure or disguise; figuratively, to apply (by accommodation)","derivation":"from G3326 (μετά) and a derivative of G4976 (σχῆμα);","pron":"met-askh-ay-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to change the figure of, to transform</li></ol>","xlit":"metaschēmatízō"},"G738":{"kjv_def":"new born","translit":"artigénnētos","lemma":"ἀρτιγέννητος","derivation":"from G737 (ἄρτι) and G1084 (γεννητός);","strongs_def":" just born, i.e. (figuratively) a young convert","pron":"ar-teeg-en'-nay-tos","pos":"Adjective","thayer":"<ol><li>just born, newborn</li></ol>","xlit":"artigénnētos"},"G5312":{"derivation":"from G5311 (ὕψος);","strongs_def":" to elevate (literally or figuratively)","kjv_def":"exalt, lift up","translit":"hypsóō","lemma":"ὑψόω","pron":"hoop-so'-o","pos":"Verb","thayer":"<ol><li>to lift up on high, to exalt</li><li>metaphorically<ol type='a'><li>to raise to the very summit of opulence and prosperity</li><li>to exalt, to raise to dignity, honour and happiness</li></ol></li></ol>","xlit":"hypsóō"},"G1585":{"derivation":"middle voice from G1537 (ἐκ) and G2990 (λανθάνω);","strongs_def":" to be utterly oblivious of","kjv_def":"forget","translit":"eklanthánomai","lemma":"ἐκλανθάνομαι","pron":"ek-lan-than'-om-ahee","pos":"Verb","thayer":"<ol><li>to cause to forget</li><li>to forget</li></ol>","xlit":"eklanthánomai"},"G4836":{"strongs_def":" to be present together, i.e. to convene; by implication, to appear in aid","derivation":"from G4862 (σύν) and G3854 (παραγίνομαι);","lemma":"συμπαραγίνομαι","translit":"symparagínomai","kjv_def":"come together, stand with","pron":"soom-par-ag-in'-om-ahee","pos":"Verb","thayer":"<ol><li>to come together</li><li>to come to one's help</li></ol>","xlit":"symparagínomai"},"G517":{"derivation":"from G1 (Α) (as a negative particle) and G3707 (ὁρατός);","strongs_def":" invisible","kjv_def":"invisible (thing)","translit":"aóratos","lemma":"ἀόρατος","pron":"ah-or'-at-os","pos":"Adjective","thayer":"<ol><li>unseen, or that which can not be seen, e.g. invisible</li></ol>","xlit":"aóratos"},"G5376":{"derivation":"from G5384 (φίλος) and G2462 (ἵππος);","strongs_def":" fond of horses; Philippus, the name of four Israelites","kjv_def":"Philip","translit":"Phílippos","lemma":"Φίλιππος","pron":"fil'-ip-pos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Philip = \"lover of horses\"</p><ol><li>an apostle of Christ</li><li>an evangelist and one of the seven deacons of the Jerusalem church</li><li>tetrarch of Trachonitis, was brother to Herod Antipas, by the father's, but not by the mother's side. Philip was born of Cleopatra, of Jerusalem, and Herod of Malthace, a Samaritan: he died in the twentieth year of Tiberias, five years after his mention in <a class='bible' href='#b42.3.1'>Luk 3:1</a>. He built Caesarea Philippi. His step brother Herod Antipas, married his wife unlawfully. (Gill)</li><li>see <u><a class='dict' href='#sG2542'>G2542</a></u>, Caesarea Philippi</li></ol>","xlit":"Phílippos"},"G3165":{"kjv_def":"I, me, my","translit":"mé","lemma":"μέ","derivation":"a shorter (and probably original) form of G1691 (ἐμέ);","strongs_def":" me","pron":"meh","xlit":"mé"},"G4746":{"derivation":"from a primary (to \"step\" or \"stamp\");","strongs_def":" a spread (as if tramped flat) of loose materials for a couch, i.e. (by implication) a bough of a tree so employed","kjv_def":"branch","lemma":"στοιβάς","translit":"stoibás","pron":"stoy-bas'","pos":"Noun Feminine","thayer":"<ol><li>branch, leafy limb</li></ol>","xlit":"stoibás"},"G1173":{"derivation":"from the same as G1160 (δαπάνη);","strongs_def":" dinner, i.e. the chief meal (usually in the evening)","kjv_def":"feast, supper","translit":"deîpnon","lemma":"δεῖπνον","pron":"dipe'-non","pos":"Noun Neuter","thayer":"<ol><li>supper, especially a formal meal usually held at the evening<ol type='a'><li>used of the Messiah's feast, symbolising salvation in the kingdom</li></ol><li>food taken at evening</li></ol>","xlit":"deîpnon"},"G4410":{"derivation":"from G4413 (πρῶτος) and G2515 (καθέδρα);","strongs_def":" a sitting first (in the front row), i.e. preeminence in council","kjv_def":"chief (highest, uppermost) seat","translit":"prōtokathedría","lemma":"πρωτοκαθεδρία","pron":"pro-tok-ath-ed-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>to sit in the first seat, the first or chief seat</li></ol>","xlit":"prōtokathedría"},"G1563":{"translit":"ekeî","lemma":"ἐκεῖ","kjv_def":"there, thither(-ward), (to) yonder (place)","strongs_def":" there; by extension, thither","derivation":"of uncertain affinity;","pron":"ek-i'","pos":"Adverb","thayer":"<ol><li>there, in or to that place</li></ol>","xlit":"ekeî"},"G4033":{"kjv_def":"compass round","translit":"perikyklóō","lemma":"περικυκλόω","derivation":"from G4012 (περί) and G2944 (κυκλόω);","strongs_def":" to encircle all around, i.e. blockade completely","pron":"per-ee-koo-klo'-o","pos":"Verb","thayer":"<ol><li>to encircle, compass about<ol type='a'><li>of a city (besieged)</li></ol></li></ol>","xlit":"perikyklóō"},"G3044":{"derivation":"perhaps from G3043 (λίνον);","strongs_def":" Linus, a Christian","kjv_def":"Linus","lemma":"Λίνος","translit":"Línos","pron":"lee'-nos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Linus = \"a net\"</p><ol><li>a Christian at Rome, known to Paul and to Timothy, <a class='bible' href='#b55.4.21'>2Ti 4:21</a>, who was the first bishop of Rome after the apostles (A.D. 64)</li></ol>","xlit":"Línos"},"G4475":{"kjv_def":"(+ strike with the) palm of the hand, smite with the hand","lemma":"ῥάπισμα","translit":"rhápisma","derivation":"from G4474 (ῥαπίζω);","strongs_def":" a slap","pron":"hrap'-is-mah","pos":"Noun Neuter","thayer":"<ol><li>a blow with a rod or staff or a scourge</li><li>a blow with the flat of the hand, a slap in the face, box the ear</li></ol>","xlit":"rhápisma"},"G2810":{"translit":"Kleópas","lemma":"Κλεόπας","kjv_def":"Cleopas","strongs_def":" Cleopas, a Christian","derivation":"probably contracted from (compound of G2811 (κλέος) and G3962 (πατήρ));","pron":"kleh-op'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cleopas = \"of a renowned father\"</p><ol><li>one of the two disciples who were going to Emmaus on the day of the resurrection</li></ol>","xlit":"Kleópas"},"G124":{"translit":"Aigýptios","lemma":"Αἰγύπτιος","kjv_def":"Egyptian","strongs_def":" an Ægyptian or inhabitant of Ægyptus","derivation":"from G125 (Αἴγυπτος);","pron":"ahee-goop'-tee-os","pos":"Adjective","thayer":"<ol><li>an Egyptian</li></ol>","xlit":"Aigýptios"},"G4457":{"strongs_def":" stupidity or callousness","derivation":"from G4456 (πωρόω);","lemma":"πώρωσις","translit":"pṓrōsis","kjv_def":"blindness, hardness","pron":"po'-ro-sis","pos":"Noun Feminine","thayer":"<ol><li>the covering with a callus</li><li>obtrusiveness of mental discernment, dulled perception</li><li>the mind of one has been blunted<ol type='a'><li>of stubbornness, obduracy</li></ol></li></ol>","xlit":"pṓrōsis"},"G5417":{"lemma":"φραγελλόω","translit":"phragellóō","kjv_def":"scourge","strongs_def":" to whip, i.e. lash as a public punishment","derivation":"from a presumed equivalent of the Latin flagellum;","pron":"frag-el-lo'-o","pos":"Verb","thayer":"<ol><li>to scourge</li></ol>","xlit":"phragellóō"},"G4416":{"strongs_def":" first-born (usually as noun, literally or figuratively)","derivation":"from G4413 (πρῶτος) and the alternate of G5088 (τίκτω);","translit":"prōtótokos","lemma":"πρωτότοκος","kjv_def":"firstbegotten(-born)","pron":"pro-tot-ok'-os","pos":"Adjective","thayer":"<ol><li>the firstborn<ol type='a'><li>of man or beast</li><li>of Christ, the first born of all creation</li></ol></li></ol>","xlit":"prōtótokos"},"G3509":{"strongs_def":" a cloud","derivation":"apparently a primary word;","translit":"néphos","lemma":"νέφος","kjv_def":"cloud","pron":"nef'-os","pos":"Noun Neuter","thayer":"<ol><li>a cloud, a large dense multitude, a throng<ol type='a'><li>used to denote a great shapeless collection of vapour obscuring the heavens as opposed to a particular and definite masses of vapour with some form or shape</li><li>a cloud in the sky</li></ol></li></ol>","xlit":"néphos"},"G4597":{"translit":"sḗs","lemma":"σής","kjv_def":"moth","strongs_def":" a moth","derivation":"apparently of Hebrew origin (H05580);","pron":"sace","pos":"Noun Neuter","thayer":"<ol><li>a moth, the clothes moth</li></ol>","xlit":"sḗs"},"G2945":{"kjv_def":"round about","translit":"kýklōi","lemma":"κύκλῳ","derivation":"as if dative case of (a ring, \"cycle\";","strongs_def":" akin to G2947 (κυλιόω)); i.e. in a circle (by implication, of G1722 (ἐν)), i.e. (adverbially) all around","pron":"koo'-klo","pos":"Adverb","thayer":"<ol><li>in a circle, around, round about, on all sides</li></ol>","xlit":"kýklōi"},"G3177":{"kjv_def":"(by) interpret(-ation)","lemma":"μεθερμηνεύω","translit":"methermēneúō","derivation":"from G3326 (μετά) and G2059 (ἑρμηνεύω);","strongs_def":" to explain over, i.e. translate","pron":"meth-er-mane-yoo'-o","pos":"Verb","thayer":"<ol><li>to translate into the language of one with whom I wish to communicate, to interpret</li></ol>","xlit":"methermēneúō"},"G4227":{"kjv_def":"Pudens","lemma":"Πούδης","translit":"Poúdēs","derivation":"of Latin origin;","strongs_def":" modest; Pudes (i.e. Pudens), a Christian","pron":"poo'-dace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Pudens = \"modest\"</p><ol><li>a Christian friend of Timothy at Rome, and may have been one of the seventy disciples</li></ol>","xlit":"Poúdēs"},"G5224":{"kjv_def":"goods, that which one has, things which (one) possesseth, substance, that hast","lemma":"ὑπάρχοντα","translit":"hypárchonta","derivation":"neuter plural of present participle active of G5225 (ὑπάρχω) as noun;","strongs_def":" things extant or in hand, i.e. property or possessions","pron":"hoop-ar'-khon-tah","pos":"Verb","thayer":"<ol><li>possessions, goods, wealth, property</li></ol>","xlit":"hypárchonta"},"G67":{"kjv_def":"Agrippa","lemma":"Ἀγρίππας","translit":"Agríppas","derivation":"apparently from G66 (ἄγριος) and G2462 (ἵππος);","strongs_def":" wild-horse tamer; Agrippas, one of the Herods","pron":"ag-rip'-pas","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Agrippa = \"Hero like\"</p><ol><li>Name of a ruling family in Israel at the time of Christ</li></ol>","xlit":"Agríppas"},"G2404":{"lemma":"Ἱεράπολις","translit":"Hierápolis","kjv_def":"Hierapolis","strongs_def":" holy city; Hierapolis, a place in Asia Minor","derivation":"from G2413 (ἱερός) and G4172 (πόλις);","pron":"hee-er-ap'-ol-is","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Hierapolis = \"holy city\"</p><ol><li>a city of Phrygia, situated above the junction of the rivers Lycus and Maeander, near Colosse and Laodicea</li></ol>","xlit":"Hierápolis"},"G2241":{"derivation":"of Hebrew origin (H0410 with pronominal suffix);","strongs_def":" my God","kjv_def":" Eli","translit":"ēlí","lemma":"ἠλί","pron":"ay-lee'","pos":"Noun Masculine","thayer":"<ol><li>Eli, Eli, lama sabachthani. The Hebrew form, as Elio, Elio, etc., is the Syro-Chaldaic (the common language in use by the Jews in the time of Christ) of the first words of the twenty second Psalm; they mean \"My God, My God, why hast thou forsaken me?\"</li></ol>","xlit":"ēlí"},"G1710":{"translit":"emporeúomai","lemma":"ἐμπορεύομαι","kjv_def":"buy and sell, make merchandise","strongs_def":" to travel in (a country as a pedlar), i.e. (by implication) to trade","derivation":"from G1722 (ἐν) and G4198 (πορεύομαι);","pron":"em-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to go a trading, to travel for business, to traffic, trade</li><li>of a thing, to import for sale</li><li>to deal in</li><li>to use a person or a thing for gain</li></ol>","xlit":"emporeúomai"},"G3017":{"translit":"Leuḯ","lemma":"Λευΐ","kjv_def":"Levi","strongs_def":" Levi, the name of three Israelites","derivation":"of Hebrew origin (H03878);","pron":"lyoo'-ee","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Levi = \"joined\"</p><ol><li>the third son of the patriarch Jacob by his wife Leah, the founder of the tribe of Israelites which bears his name</li><li>the son of Melchi, one of Christ's ancestors</li><li>the son of Simeon, an ancestor of Christ</li></ol>","xlit":"Leuḯ"},"G167":{"derivation":"from G169 (ἀκάθαρτος);","strongs_def":" impurity (the quality), physically or morally","kjv_def":"uncleanness","translit":"akatharsía","lemma":"ἀκαθαρσία","pron":"ak-ath-ar-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>uncleanness<ol type='a'><li>physical</li><li>in a moral sense: the impurity of lustful, luxurious, profligate living<ol><li>of impure motives</li></ol></li></ol></li></ol>","xlit":"akatharsía"},"G3025":{"kjv_def":"winepress","translit":"lēnós","lemma":"ληνός","derivation":"apparently a primary word;","strongs_def":" a trough, i.e. wine-vat","pron":"lay-nos'","pos":"Noun Feminine","thayer":"<ol><li>a tub or trough shaped receptacle, vat, in which grapes are trodden</li><li>the lower vat, dug in the ground, into which the must or new wine flowed from the press</li></ol>","xlit":"lēnós"},"G1215":{"strongs_def":" to be a people-gatherer, i.e. to address a public assembly","derivation":"from a compound of G1218 (δῆμος) and G58 (ἀγορά);","lemma":"δημηγορέω","translit":"dēmēgoréō","kjv_def":"make an oration","pron":"day-may-gor-eh'-o","pos":"Verb","thayer":"<ol><li>to address a public assembly, make a speech to the people</li></ol>","xlit":"dēmēgoréō"},"G857":{"kjv_def":"neglecting","lemma":"ἀφειδία","translit":"apheidía","derivation":"from a compound of G1 (Α) (as a negative particle) and G5339 (φείδομαι);","strongs_def":" unsparingness, i.e. austerity (asceticism)","pron":"af-i-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>unsparingly severity</li></ol>","xlit":"apheidía"},"G4853":{"kjv_def":"countryman","translit":"symphylétēs","lemma":"συμφυλέτης","derivation":"from G4862 (σύν) and a derivative of G5443 (φυλή);","strongs_def":" a co-tribesman, i.e. native of the same country","pron":"soom-foo-let'-ace","pos":"Noun Masculine","thayer":"<ol><li>one who is of the same people, a fellow countryman</li></ol>","xlit":"symphylétēs"},"G1642":{"lemma":"ἐλαττόω","translit":"elattóō","kjv_def":"decrease, make lower","strongs_def":" to lessen (in rank or influence)","derivation":"from G1640 (ἐλάσσων);","pron":"el-at-to'-o","pos":"Verb","thayer":"<ol><li>to make less or inferior: in dignity</li><li>to be made less or inferior: in dignity</li><li>to decrease in authority or popularity</li></ol>","xlit":"elattóō"},"G4632":{"kjv_def":"goods, sail, stuff, vessel","lemma":"σκεῦος","translit":"skeûos","derivation":"of uncertain affinity;","strongs_def":" a vessel, implement, equipment or apparatus (literally or figuratively [specially, a wife as contributing to the usefulness of the husband])","pron":"skyoo'-os","pos":"Noun Neuter","thayer":"<ol><li>a vessel</li><li>an implement<ol type='a'><li>in the plural<ol><li>household utensils, domestic gear</li><li>the tackle and armament of vessels, used specifically of sails and ropes</li></ol></li></ol><li>metaphorically<ol type='a'><li>a man of quality, a chosen instrument</li><li>in a bad sense, an assistant in accomplishing an evil deed</li></ol></li></ol>","xlit":"skeûos"},"G4242":{"strongs_def":" seniority (eldership), i.e. (by implication) an embassy (concretely, ambassadors)","derivation":"from G4243 (πρεσβεύω);","lemma":"πρεσβεία","translit":"presbeía","kjv_def":"ambassage, message","pron":"pres-bi'-ah","pos":"Noun Feminine","thayer":"<ol><li>age, dignity, right of the first born</li><li>the business normally intrusted to elders, spec. the office of an ambassador, an embassy</li></ol>","xlit":"presbeía"},"G1549":{"strongs_def":" a descendant, i.e. (specially) grandchild","derivation":"neuter of a derivative of a compound of G1537 (ἐκ) and G1096 (γίνομαι);","lemma":"ἔκγονον","translit":"ékgonon","kjv_def":"nephew","pron":"ek'-gon-on","pos":"Adjective","thayer":"<ol><li>sprung from one, born, begotten</li><li>a son, daughter, offspring, children, descendants</li><li>grandchildren</li></ol>","xlit":"ékgonon"},"G5322":{"lemma":"φανός","translit":"phanós","kjv_def":"lantern","strongs_def":" a lightener, i.e. light; lantern","derivation":"from G5316 (φαίνω);","pron":"fan-os'","pos":"Noun Masculine","thayer":"<ol><li>a torch</li></ol>","xlit":"phanós"},"G1818":{"translit":"exapatáō","lemma":"ἐξαπατάω","kjv_def":"beguile, deceive","strongs_def":" to seduce wholly","derivation":"from G1537 (ἐκ) and G538 (ἀπατάω);","pron":"ex-ap-at-ah'-o","pos":"Verb","thayer":"<ol><li>to deceive</li></ol>","xlit":"exapatáō"},"G2744":{"derivation":"from some (obsolete) base akin to that of (to boast) and G2172 (εὔχομαι);","strongs_def":" to vaunt (in a good or a bad sense)","kjv_def":"(make) boast, glory, joy, rejoice","translit":"kaucháomai","lemma":"καυχάομαι","pron":"kow-khah'-om-ahee","pos":"Verb","thayer":"<ol><li>to glory (whether with reason or without)</li><li>to glory on account of a thing</li><li>to glory in a thing</li></ol>","xlit":"kaucháomai"},"G161":{"translit":"aichmalōsía","lemma":"αἰχμαλωσία","kjv_def":"captivity","strongs_def":" captivity","derivation":"from G164 (αἰχμάλωτος);","pron":"aheekh-mal-o-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>captivity</li></ol>","xlit":"aichmalōsía"},"G2467":{"lemma":"ἴσημι","translit":"ísēmi","kjv_def":"know","strongs_def":" to know","derivation":"assumed by some as the base of certain irregular forms of G1492 (εἴδω);","pron":"is'-ay-mee","pos":"Verb","thayer":"<ol><li>to know</li></ol>","xlit":"ísēmi"},"G3965":{"translit":"patriá","lemma":"πατριά","kjv_def":"family, kindred, lineage","strongs_def":" paternal descent, i.e. (concretely) a group of families or a whole race (nation)","derivation":"as if feminine of a derivative of G3962 (πατήρ);","pron":"pat-ree-ah'","pos":"Noun Feminine","thayer":"<ol><li>lineage running back to some progenitor, ancestry</li><li>a nation or tribe<ol type='a'><li>a group of families, all those who in a given people lay claim to a common origin</li><li>the Israelites which distributed into twelve tribes, descended from the twelve sons of Jacob, these were divided into families which were divided into houses</li></ol><li>family, in a wider sense, nation, people</li></ol>","xlit":"patriá"},"G5255":{"kjv_def":"obedient","translit":"hypḗkoos","lemma":"ὑπήκοος","derivation":"from G5219 (ὑπακούω);","strongs_def":" attentively listening, i.e. (by implication) submissive","pron":"hoop-ay'-ko-os","pos":"Adjective","thayer":"<ol><li>giving ear, obedient</li></ol>","xlit":"hypḗkoos"},"G2290":{"lemma":"θάπτω","translit":"tháptō","kjv_def":"bury","strongs_def":" to celebrate funeral rites, i.e. inter","derivation":"a primary verb;","pron":"thap'-to","pos":"Verb","thayer":"<ol><li>to bury, inter</li></ol>","xlit":"tháptō"},"G209":{"derivation":"adverb from a compound of G1 (Α) (as a negative particle) and a derivative of G2967 (κωλύω);","strongs_def":" in an unhindered manner, i.e. freely","kjv_def":"no man forbidding him","lemma":"ἀκωλύτως","translit":"akōlýtōs","pron":"ak-o-loo'-toce","pos":"Adverb","thayer":"<ol><li>without hindrances, freely</li></ol>","xlit":"akōlýtōs"},"G1875":{"strongs_def":" a particle of indefinite contemporaneousness; whenever, as soon as","derivation":"from G1909 (ἐπί) and G302 (ἄν);","lemma":"ἐπάν","translit":"epán","kjv_def":"when","pron":"ep-an'","pos":"Conjunction","thayer":"<ol><li>after, when</li></ol>","xlit":"epán"},"G4194":{"kjv_def":"Pontius","lemma":"Πόντιος","translit":"Póntios","derivation":"of Latin origin;","strongs_def":" apparently bridged; Pontius, a Roman","pron":"pon'-tee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Pontius [Pilate] = \"of the sea\"</p><ol><li>the sixth Roman procurator of Judah who crucified Christ</li></ol>","xlit":"Póntios"},"G1659":{"strongs_def":" to liberate, i.e. (figuratively) to exempt (from moral, ceremonial or mortal liability)","derivation":"from G1658 (ἐλεύθερος);","translit":"eleutheróō","lemma":"ἐλευθερόω","kjv_def":"deliver, make free","pron":"el-yoo-ther-o'-o","pos":"Verb","thayer":"<ol><li>to make free</li><li>set at liberty: from the dominion of sin</li></ol>","xlit":"eleutheróō"},"G2097":{"derivation":"from G2095 (εὖ) and G32 (ἄγγελος);","strongs_def":" to announce good news (\"evangelize\") especially the gospel","kjv_def":"declare, bring (declare, show) glad (good) tidings, preach (the gospel)","translit":"euangelízō","lemma":"εὐαγγελίζω","pron":"yoo-ang-ghel-id'-zo","pos":"Verb","thayer":"<ol><li>to bring good news, to announce glad tidings<ol type='a'><li>used in the OT of any kind of good news<ol><li>of the joyful tidings of God's kindness, in particular, of the Messianic blessings</li></ol><li>in the NT used especially of the glad tidings of the coming kingdom of God, and of the salvation to be obtained in it through Christ, and of what relates to this salvation</li><li>glad tidings are brought to one, one has glad tidings proclaimed to him</li><li>to proclaim glad tidings<ol><li>instruct (men) concerning the things that pertain to Christian salvation</li></ol></li></ol></li></ol>","xlit":"euangelízō"},"G751":{"kjv_def":"Archippus","lemma":"Ἄρχιππος","translit":"Árchippos","derivation":"from G746 (ἀρχή) and G2462 (ἵππος);","strongs_def":" horse-ruler; Archippus, a Christian","pron":"ar'-khip-pos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Archippus = \"master of the horse\"</p><ol><li>a certain Christian teacher in Colosse</li></ol>","xlit":"Árchippos"},"G2550":{"derivation":"from a compound of G2556 (κακός) and G2239 (ἦθος);","strongs_def":" bad character, i.e. (specially) mischievousness","kjv_def":"malignity","lemma":"κακοήθεια","translit":"kakoḗtheia","pron":"kak-o-ay'-thi-ah","pos":"Noun Feminine","thayer":"<ol><li>bad character, depravity of heart and life</li><li>malignant subtlety, malicious craftiness</li></ol>","xlit":"kakoḗtheia"},"G3641":{"lemma":"ὀλίγος","translit":"olígos","kjv_def":"+ almost, brief(-ly), few, (a) little, + long, a season, short, small, a while","strongs_def":" puny (in extent, degree, number, duration or value); especially neuter (adverbially) somewhat","derivation":"of uncertain affinity;","pron":"ol-ee'-gos","pos":"Adjective","thayer":"<ol><li>little, small, few<ol type='a'><li>of number: multitude, quantity, or size</li><li>of time: short</li><li>of degree or intensity: light, slight</li></ol></li></ol>","xlit":"olígos"},"G159":{"derivation":"from the same as G154 (αἰτέω);","strongs_def":" causative, i.e. (concretely) a causer","kjv_def":"author","translit":"aítios","lemma":"αἴτιος","pron":"ah'-ee-tee-os","pos":"Adjective","thayer":"<ol><li>that which is the cause of anything resides, causative, causing<ol type='a'><li>the author<ol><li>of a cause</li><li>of crime or offence</li></ol></li></ol></li></ol>","xlit":"aítios"},"G981":{"translit":"bíōsis","lemma":"βίωσις","kjv_def":"manner of life","strongs_def":" living (properly, the act, by implication, the mode)","derivation":"from G980 (βιόω);","pron":"bee'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>manner of living and acting, way of life</li></ol>","xlit":"bíōsis"},"G1815":{"lemma":"ἐξανάστασις","translit":"exanástasis","kjv_def":"resurrection","strongs_def":" a rising from death","derivation":"from G1817 (ἐξανίστημι);","pron":"ex-an-as'-tas-is","pos":"Noun Feminine","thayer":"<ol><li>a rising up, a rising again</li><li>resurrection</li></ol>","xlit":"exanástasis"},"G2471":{"translit":"isótēs","lemma":"ἰσότης","kjv_def":"equal(-ity)","strongs_def":"likeness (in condition or proportion); by implication, equity","pron":"ee-sot'-ace","pos":"Noun Feminine","thayer":"<ol><li>equality</li><li>equity, fairness, what is equitable</li></ol>","xlit":"isótēs"},"G590":{"lemma":"ἀπόδημος","translit":"apódēmos","kjv_def":"taking a far journey","strongs_def":" absent from one's own people, i.e. a foreign traveller","derivation":"from G575 (ἀπό) and G1218 (δῆμος);","pron":"ap-od'-ay-mos","pos":"Adjective","thayer":"<ol><li>away from one's people, go abroad</li></ol>","xlit":"apódēmos"},"G2952":{"lemma":"κυνάριον","translit":"kynárion","kjv_def":"dog","strongs_def":" a puppy","derivation":"neuter of a presumed derivative of G2965 (κύων);","pron":"koo-nar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a little dog</li></ol>","xlit":"kynárion"},"G1435":{"strongs_def":"a present; specially, a sacrifice","kjv_def":"gift, offering","translit":"dōron","lemma":"δῶρον","pron":"do'-ron","pos":"Noun Neuter","thayer":"<ol><li>a gift, present<ol type='a'><li>gifts offered in expression of honour<ol><li>of sacrifices and other gifts offered to God</li><li>of money cast into the treasury for the purposes of the temple and for the support of the poor</li></ol></li></ol><li>the offering of a gift or of gifts</li></ol>","xlit":"dōron"},"G991":{"kjv_def":"behold, beware, lie, look (on, to), perceive, regard, see, sight, take heed","translit":"blépō","lemma":"βλέπω","derivation":"a primary verb;","strongs_def":" to look at (literally or figuratively)","pron":"blep'-o","pos":"Verb","thayer":"<ol><li>to see, discern, of the bodily eye<ol type='a'><li>with the bodily eye: to be possessed of sight, have the power of seeing</li><li>perceive by the use of the eyes: to see, look descry</li><li>to turn the eyes to anything: to look at, look upon, gaze at</li><li>to perceive by the senses, to feel</li><li>to discover by use, to know by experience</li></ol><li>metaphorically to see with the mind's eye<ol type='a'><li>to have (the power of) understanding</li><li>to discern mentally, observe, perceive, discover, understand</li><li>to turn the thoughts or direct the mind to a thing, to consider, contemplate, to look at, to weigh carefully, examine</li></ol><li>in a geographical sense of places, mountains, buildings, etc. turning towards any quarter, as it were, facing it</li></ol>","xlit":"blépō"},"G5383":{"strongs_def":" to be fond of being first, i.e. ambitious of distinction","derivation":"from a compound of G5384 (φίλος) and G4413 (πρῶτος);","translit":"philoprōteúō","lemma":"φιλοπρωτεύω","kjv_def":"love to have the preeminence","pron":"fil-op-rote-yoo'-o","pos":"Verb","thayer":"<ol><li>to aspire to pre-eminence, to desire to be first</li></ol>","xlit":"philoprōteúō"},"G3422":{"derivation":"from G3421 (μνημονεύω);","strongs_def":" a reminder (memorandum), i.e. record","kjv_def":"memorial","translit":"mnēmósynon","lemma":"μνημόσυνον","pron":"mnay-mos'-oo-non","pos":"Noun Neuter","thayer":"<ol><li>a memorial (that by which the memory of any person or thing is preserved), a remembrance</li></ol>","xlit":"mnēmósynon"},"G822":{"derivation":"from the same as G109 (ἀήρ);","strongs_def":" mist","kjv_def":"vapour","lemma":"ἀτμίς","translit":"atmís","pron":"at-mece'","pos":"Noun Feminine","thayer":"<ol><li>vapour</li></ol>","xlit":"atmís"},"G5536":{"strongs_def":"something useful or needed, i.e. wealth, price","kjv_def":"money, riches","translit":"chrēma","lemma":"χρῆμα","pron":"khray'-mah","pos":"Noun Neuter","thayer":"<ol><li>a thing, a matter, affair, event, business<ol type='a'><li>spec. money, riches</li></ol></li></ol>","xlit":"chrēma"},"G4359":{"strongs_def":" to be indebted additionally","derivation":"from G4314 (πρός) and G3784 (ὀφείλω);","translit":"prosopheílō","lemma":"προσοφείλω","kjv_def":"over besides","pron":"pros-of-i'-lo","pos":"Verb","thayer":"<ol><li>to owe beside</li></ol>","xlit":"prosopheílō"},"G4145":{"kjv_def":"rich","lemma":"πλούσιος","translit":"ploúsios","derivation":"from G4149 (πλοῦτος);","strongs_def":" wealthy; figuratively, abounding with","pron":"ploo'-see-os","pos":"Adjective","thayer":"<ol><li>wealthy, abounding in material resources</li><li>metaphorically abounding, abundantly supplied<ol type='a'><li>abounding (rich) in Christian virtues and eternal possessions</li></ol></li></ol>","xlit":"ploúsios"},"G5326":{"translit":"phántasma","lemma":"φάντασμα","kjv_def":"spirit","strongs_def":" (properly concrete) a (mere) show (\"phantasm\"), i.e. spectre","derivation":"from G5324 (φαντάζω);","pron":"fan'-tas-mah","pos":"Noun Neuter","thayer":"<ol><li>an appearance</li><li>an apparition, spectre</li></ol>","xlit":"phántasma"},"G5214":{"translit":"hymnéō","lemma":"ὑμνέω","kjv_def":"sing a hymn (praise unto)","strongs_def":" to hymn, i.e. sing a religious ode; by implication, to celebrate (God) in song","derivation":"from G5215 (ὕμνος);","pron":"hoom-neh'-o","pos":"Verb","thayer":"<ol><li>to sing the praise of, sing hymns to</li><li>to sing a hymn, to sing<ol type='a'><li>singing of paschal hymns these were Psalms 113 - 118 and 136, which the Jews called the \"great Hallel\"</li></ol></li></ol>","xlit":"hymnéō"},"G4562":{"strongs_def":" Saruch (i.e. Serug), a patriarch","derivation":"of Hebrew origin (H08286);","lemma":"Σαρούχ","translit":"Saroúch","kjv_def":"Saruch","pron":"sar-ooch'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Serug = \"intertwined\"</p><ol><li>the son of Reu in the genealogy of Christ</li></ol>","xlit":"Saroúch"},"G2967":{"kjv_def":"forbid, hinder, keep from, let, not suffer, withstand","lemma":"κωλύω","translit":"kōlýō","derivation":"from the base of G2849 (κολάζω);","strongs_def":" to estop, i.e. prevent (by word or act)","pron":"ko-loo'-o","pos":"Verb","thayer":"<ol><li>to hinder, prevent forbid</li><li>to withhold a thing from anyone</li><li>to deny or refuse one a thing</li></ol>","xlit":"kōlýō"},"G1322":{"strongs_def":" instruction (the act or the matter)","derivation":"from G1321 (διδάσκω);","lemma":"διδαχή","translit":"didachḗ","kjv_def":"doctrine, hath been taught","pron":"did-akh-ay'","pos":"Noun Feminine","thayer":"<ol><li>teaching<ol type='a'><li>that which is taught</li><li>doctrine, teaching, concerning something</li></ol><li>the act of teaching, instruction<ol type='a'><li>in religious assemblies of the Christians, to speak in the way of teaching, in distinction from other modes of speaking in public</li></ol></li></ol>","xlit":"didachḗ"},"G2960":{"kjv_def":"Lord's","translit":"kyriakós","lemma":"κυριακός","derivation":"from G2962 (κύριος);","strongs_def":" belonging to the Lord (Jehovah or Jesus)","pron":"koo-ree-ak-os'","pos":"Adjective","thayer":"<ol><li>belonging to the Lord</li><li>related to the Lord</li></ol>","xlit":"kyriakós"},"G1468":{"strongs_def":" strong in a thing (masterful), i.e. (figuratively and reflexively) self-controlled (in appetite, etc.)","derivation":"from G1722 (ἐν) and G2904 (κράτος);","translit":"enkratḗs","lemma":"ἐγκρατής","kjv_def":"temperate","pron":"eng-krat-ace'","pos":"Adjective","thayer":"<ol><li>strong, robust</li><li>having power over, possessed of (a thing)</li><li>mastering, controlling, curbing, restraining<ol type='a'><li>controlling one's self, temperate, continent</li></ol></li></ol>","xlit":"enkratḗs"},"G754":{"kjv_def":"chief among the publicans","lemma":"ἀρχιτελώνης","translit":"architelṓnēs","derivation":"from G746 (ἀρχή) and G5057 (τελώνης);","strongs_def":" a principle tax-gatherer","pron":"ar-khee-tel-o'-nace","pos":"Noun Masculine","thayer":"<ol><li>a chief of tax collectors, chief publican</li></ol>","xlit":"architelṓnēs"},"G4275":{"derivation":"from G4253 (πρό) and G1492 (εἴδω);","strongs_def":" foresee","kjv_def":"foresee, saw before","lemma":"προείδω","translit":"proeídō","pron":"pro-i'-do","pos":"Verb","thayer":"<ol><li>to foresee</li></ol>","xlit":"proeídō"},"G164":{"derivation":"from (a spear) and a derivative of the same as G259 (ἅλωσις);","strongs_def":" properly, a prisoner of war, i.e. (genitive case) a captive","kjv_def":"captive","lemma":"αἰχμάλωτος","translit":"aichmálōtos","pron":"aheekh-mal-o-tos'","pos":"Adjective","thayer":"<ol><li>a captive</li></ol>","xlit":"aichmálōtos"},"G778":{"derivation":"probably from the same as G4632 (σκεῦος);","strongs_def":" to elaborate, i.e. (figuratively) train (by implication, strive)","kjv_def":"exercise","translit":"askéō","lemma":"ἀσκέω","pron":"as-keh'-o","pos":"Verb","thayer":"<ol><li>to form by art, to adorn</li><li>to exercise (one's) self, take pains, labour, strive</li></ol>","xlit":"askéō"},"G2701":{"kjv_def":"run down","lemma":"κατατρέχω","translit":"katatréchō","derivation":"from G2596 (κατά) and G5143 (τρέχω);","strongs_def":" to run down, i.e. hasten from a tower","pron":"kat-at-rekh'-o","pos":"Verb","thayer":"<ol><li>to run down, hasten down</li></ol>","xlit":"katatréchō"},"G3321":{"kjv_def":"midst of heaven","lemma":"μεσουράνημα","translit":"mesouránēma","derivation":"from a presumed compound of G3319 (μέσος) and G3772 (οὐρανός);","strongs_def":" mid-sky","pron":"mes-oo-ran'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>mid-heaven</li><li>the highest point in the heavens, which the sun occupies at noon, where what is done can be seen and heard by all</li></ol>","xlit":"mesouránēma"},"G4819":{"kjv_def":"be(-fall), happen (unto)","translit":"symbaínō","lemma":"συμβαίνω","derivation":"from G4862 (σύν) and the base of G939 (βάσις);","strongs_def":" to walk (figuratively, transpire) together, i.e. concur (take place)","pron":"soom-bah'-ee-no","pos":"Verb","thayer":"<ol><li>to walk with the feet near together</li><li>to come together, meet with one</li><li>of things which fall out at the same time, to happen, turn out, come to pass</li></ol>","xlit":"symbaínō"},"G4311":{"lemma":"προπέμπω","translit":"propémpō","kjv_def":"accompany, bring (forward) on journey (way), conduct forth","strongs_def":" to send forward, i.e. escort or aid in travel","derivation":"from G4253 (πρό) and G3992 (πέμπω);","pron":"prop-em'-po","pos":"Verb","thayer":"<ol><li>to send before</li><li>to send forward, bring on the way, accompany or escort</li><li>to set one forward, fit him out with the requisites for a journey</li></ol>","xlit":"propémpō"},"G3999":{"kjv_def":"five times","translit":"pentákis","lemma":"πεντάκις","derivation":"multiplicative adverb from G4002 (πέντε);","strongs_def":" five times","pron":"pen-tak-ece'","pos":"Adverb","thayer":"<ol><li>five times</li></ol>","xlit":"pentákis"},"G3981":{"lemma":"πειθός","translit":"peithós","kjv_def":"enticing","strongs_def":" persuasive","derivation":"from G3982 (πείθω);","pron":"pi-thos'","pos":"Adjective","thayer":"<ol><li>persuasive</li></ol>","xlit":"peithós"},"G3673":{"kjv_def":"of the same craft","translit":"homótechnos","lemma":"ὁμότεχνος","derivation":"from the base of G3674 (ὁμοῦ) and G5078 (τέχνη);","strongs_def":" a fellow-artificer","pron":"hom-ot'-ekh-nos","pos":"Adjective","thayer":"<ol><li>practising the same trade or craft, of the same trade</li></ol>","xlit":"homótechnos"},"G1305":{"lemma":"διατροφή","translit":"diatrophḗ","kjv_def":"food","strongs_def":" nourishment","derivation":"from a compound of G1223 (διά) and G5142 (τρέφω);","pron":"dee-at-rof-ay'","pos":"Noun Feminine","thayer":"<ol><li>sustenance</li></ol>","xlit":"diatrophḗ"},"G824":{"translit":"átopos","lemma":"ἄτοπος","kjv_def":"amiss, harm, unreasonable","strongs_def":" out of place, i.e. (figuratively) improper, injurious, wicked","derivation":"from G1 (Α) (as a negative particle) and G5117 (τόπος);","pron":"at'-op-os","pos":"Adjective","thayer":"<ol><li>out of place, not befitting, unbecoming</li><li>improper, wicked</li><li>unrighteous</li><li>inconvenient, harmful</li></ol>","xlit":"átopos"},"G4108":{"kjv_def":"--deceiver, seducing","translit":"plános","lemma":"πλάνος","derivation":"of uncertain affinity;","strongs_def":" roving (as a tramp), i.e. (by implication) an impostor or misleader; ","pron":"plan'-os","pos":"Adjective","thayer":"<ol><li>wandering, roving</li><li>misleading, leading into error<ol type='a'><li>a vagabond, \"tramp\" , imposter</li><li>corrupter, deceiver</li></ol></li></ol>","xlit":"plános"},"G2138":{"kjv_def":"easy to be intreated","translit":"eupeithḗs","lemma":"εὐπειθής","derivation":"from G2095 (εὖ) and G3982 (πείθω);","strongs_def":" good for persuasion, i.e. (intransitively) complaint","pron":"yoo-pi-thace'","pos":"Adjective","thayer":"<ol><li>easily obeying, compliant</li></ol>","xlit":"eupeithḗs"},"G5575":{"derivation":"from G5571 (ψευδής) and a kindred form of G3144 (μάρτυς);","strongs_def":" a spurious witness, i.e. bearer of untrue testimony","kjv_def":"false witness","translit":"pseudomártyr","lemma":"ψευδομάρτυρ","pron":"psyoo-dom-ar'-toor","pos":"Noun Masculine","thayer":"<ol><li>a false witness</li></ol>","xlit":"pseudomártyr"},"G994":{"derivation":"apparently a prolonged form of a primary verb;","strongs_def":" to halloo, i.e. shout (for help or in a tumultuous way)","kjv_def":"cry","translit":"boáō","lemma":"βοάω","pron":"bo-ah'-o","pos":"Verb","thayer":"<ol><li>to raise a cry, of joy pain etc.</li><li>to cry, speak with a high, strong voice</li><li>to cry to one for help, to implore his aid</li></ol>","xlit":"boáō"},"G1771":{"derivation":"from a compound of G1722 (ἐν) and G3563 (νοῦς);","strongs_def":" thoughtfulness, i.e. moral understanding","kjv_def":"intent, mind","translit":"énnoia","lemma":"ἔννοια","pron":"en'-noy-ah","pos":"Noun Feminine","thayer":"<ol><li>the act of thinking, consideration, meditation</li><li>a thought, notion, conception</li><li>mind, understanding, will, manner of feeling, and thinking</li></ol>","xlit":"énnoia"},"G4208":{"translit":"porrhōtérō","lemma":"ποῤῥωτέρω","kjv_def":"farther","strongs_def":" further, i.e. a greater distance","derivation":"adverb comparative of G4206 (πόῤῥω);","pron":"por-rho-ter'-o","pos":"Adverb","thayer":"<ol><li>further</li></ol>","xlit":"porrhōtérō"},"G399":{"translit":"anaphérō","lemma":"ἀναφέρω","kjv_def":"bear, bring (carry, lead) up, offer (up)","strongs_def":" to take up (literally or figuratively)","derivation":"from G303 (ἀνά) and G5342 (φέρω);","pron":"an-af-er'-o","pos":"Verb","thayer":"<ol><li>to carry or bring up, to lead up<ol type='a'><li>men to a higher place</li></ol><li>to put upon the altar, to bring to the altar, to offer</li><li>to lift up one's self, to take upon one's self<ol type='a'><li>to place on one's self anything as a load to be carried</li><li>to sustain, i.e. their punishment</li></ol></li></ol>","xlit":"anaphérō"},"G277":{"strongs_def":" immovable","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3334 (μετακινέω);","translit":"ametakínētos","lemma":"ἀμετακίνητος","kjv_def":"unmovable","pron":"am-et-ak-in'-ay-tos","pos":"Adjective","thayer":"<ol><li>not to be moved from its place, unmoved</li><li>metaphorically firmly persistent</li></ol>","xlit":"ametakínētos"},"G2643":{"derivation":"from G2644 (καταλλάσσω);","strongs_def":" exchange (figuratively, adjustment), i.e. restoration to (the divine) favor","kjv_def":"atonement, reconciliation(-ing)","lemma":"καταλλαγή","translit":"katallagḗ","pron":"kat-al-lag-ay'","pos":"Noun Feminine","thayer":"<ol><li>exchange<ol type='a'><li>of the business of money changers, exchanging equivalent values</li></ol><li>adjustment of a difference, reconciliation, restoration to favour<ol type='a'><li>in the NT of the restoration of the favour of God to sinners that repent and put their trust in the expiatory death of Christ</li></ol></li></ol>","xlit":"katallagḗ"},"G4625":{"strongs_def":" a trap-stick (bent sapling), i.e. snare (figuratively, cause of displeasure or sin)","derivation":"(\"scandal\"); probably from a derivative of G2578 (κάμπτω);","lemma":"σκάνδαλον","translit":"skándalon","kjv_def":"occasion to fall (of stumbling), offence, thing that offends, stumblingblock","pron":"skan'-dal-on","pos":"Noun Neuter","thayer":"<ol><li>the movable stick or trigger of a trap, a trap stick<ol type='a'><li>a trap, snare</li><li>any impediment placed in the way and causing one to stumble or fall, (a stumbling block, occasion of stumbling), i.e. a rock which is a cause of stumbling</li><li>fig. applied to Jesus Christ, whose person and career were so contrary to the expectations of the Jews concerning the Messiah, that they rejected him and by their obstinacy made shipwreck of their salvation</li></ol><li>any person or thing by which one is (entrapped) drawn into error or sin</li></ol>","xlit":"skándalon"},"G5394":{"kjv_def":"set on fire","lemma":"φλογίζω","translit":"phlogízō","derivation":"from G5395 (φλόξ);","strongs_def":" to cause a blaze, i.e. ignite (figuratively, to inflame with passion)","pron":"flog-id'-zo","pos":"Verb","thayer":"<ol><li>to ignite, set on fire</li><li>to burn up</li><li>fig. to operate destructively, have a most pernicious power<ol type='a'><li>of that in which the destructive influences are kindled</li></ol></li></ol>","xlit":"phlogízō"},"G2580":{"kjv_def":"Cana","lemma":"Κανᾶ","translit":"Kanâ","derivation":"of Hebrew origin (compare H07071);","strongs_def":" Cana, a place in Palestine","pron":"kan-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cana = \"place of reeds\"</p><ol><li>a village in Galilee about 5 miles (8 km) NW from Nazareth</li></ol>","xlit":"Kanâ"},"G2667":{"translit":"katapíptō","lemma":"καταπίπτω","kjv_def":"fall (down)","strongs_def":" to fall down","derivation":"from G2596 (κατά) and G4098 (πίπτω);","pron":"kat-ap-ip'-to","pos":"Verb","thayer":"<ol><li>to fall down</li></ol>","xlit":"katapíptō"},"G276":{"strongs_def":" unchangeable, or (neuter as abstract) unchangeability","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3346 (μετατίθημι);","lemma":"ἀμετάθετος","translit":"ametáthetos","kjv_def":"immutable(-ility)","pron":"am-et-ath'-et-os","pos":"Adjective","thayer":"<ol><li>not transposed, not to be transferred, fixed, unalterable</li></ol>","xlit":"ametáthetos"},"G3174":{"derivation":"from G3173 (μέγας);","strongs_def":" magnitude (figuratively)","kjv_def":"greatness","lemma":"μέγεθος","translit":"mégethos","pron":"meg'-eth-os","pos":"Noun Neuter","thayer":"<ol><li>greatness</li></ol>","xlit":"mégethos"},"G2563":{"kjv_def":"pen, reed","lemma":"κάλαμος","translit":"kálamos","derivation":"of uncertain affinity;","strongs_def":" a reed (the plant or its stem, or that of a similar plant); by implication, a pen","pron":"kal'-am-os","pos":"Noun Masculine","thayer":"<ol><li>a reed</li><li>a staff made of a reed, a reed staff</li><li>a measuring reed or rod</li><li>a writer's reed, a pen</li></ol>","xlit":"kálamos"},"G2000":{"derivation":"from a compound of G1909 (ἐπί) and (to trip);","strongs_def":" figuratively, insecure","kjv_def":"dangerous","translit":"episphalḗs","lemma":"ἐπισφαλής","pron":"ep-ee-sfal-ace'","pos":"Adjective","thayer":"<ol><li>prone to fall</li></ol>","xlit":"episphalḗs"},"G2253":{"lemma":"ἡμιθανής","translit":"hēmithanḗs","kjv_def":"half dead","strongs_def":" half dead, i.e. entirely exhausted","derivation":"from a presumed compound of the base of G2255 (ἥμισυ) and G2348 (θνήσκω);","pron":"hay-mee-than-ace'","pos":"Adjective","thayer":"<ol><li>half dead</li></ol>","xlit":"hēmithanḗs"},"G3933":{"derivation":"of unknown origin;","strongs_def":" a maiden; by implication, an unmarried daughter","kjv_def":"virgin","translit":"parthénos","lemma":"παρθένος","pron":"par-then'-os","pos":"Noun Feminine","thayer":"<ol><li>a virgin<ol type='a'><li>a marriageable maiden</li><li>a woman who has never had sexual intercourse with a man</li><li>one's marriageable daughter</li></ol><li>a man who has abstained from all uncleanness and whoredom attendant on idolatry, and so has kept his chastity<ol type='a'><li>one who has never had intercourse with women</li></ol></li></ol>","xlit":"parthénos"},"G1250":{"kjv_def":"two hundred","translit":"diakósioi","lemma":"διακόσιοι","derivation":"from G1364 (δίς) and G1540 (ἑκατόν);","strongs_def":" two hundred","pron":"dee-ak-os'-ee-oy","pos":"Adjective","thayer":"<ol><li>two hundred</li></ol>","xlit":"diakósioi"},"G3385":{"kjv_def":"not (the particle usually not expressed, except by the form of the question)","lemma":"μήτι","translit":"mḗti","derivation":"from G3361 (μή) and the neuter of G5100 (τὶς);","strongs_def":" whether at all","pron":"may'-tee","thayer":"<ol><li>whether, at all, perchance</li></ol>","xlit":"mḗti"},"G5450":{"derivation":"from G5448 (φυσιόω);","strongs_def":" inflation, i.e. (figuratively) haughtiness","kjv_def":"swelling","lemma":"φυσίωσις","translit":"physíōsis","pron":"foo-see'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>a puffing up of soul, loftiness, pride</li></ol>","xlit":"physíōsis"},"G686":{"derivation":"probably from G142 (αἴρω) (through the idea of drawing a conclusion);","strongs_def":" a particle denoting an inference more or less decisive (as follows)","kjv_def":"haply, (what) manner (of man), no doubt, perhaps, so be, then, therefore, truly, wherefore","translit":"ára","lemma":"ἄρα","pron":"ar'-ah","thayer":"<ol><li>therefore, so then, wherefore</li></ol>","xlit":"ára"},"G141":{"kjv_def":"heretic (the Greek word itself)","lemma":"αἱρετικός","translit":"hairetikós","derivation":"from the same as G140 (αἱρετίζω);","strongs_def":" a schismatic","pron":"hahee-ret-ee-kos'","pos":"Adjective","thayer":"<ol><li>fitted or able to take or choose a thing</li><li>schismatic, factious, a follower of a false doctrine</li><li>heretic</li></ol>","xlit":"hairetikós"},"G4762":{"derivation":"strengthened from the base of G5157 (τροπή);","strongs_def":" to twist, i.e. turn quite around or reverse (literally or figuratively)","kjv_def":"convert, turn (again, back again, self, self about)","lemma":"στρέφω","translit":"stréphō","pron":"stref'-o","pos":"Verb","thayer":"<ol><li>to turn, turn around</li><li>to turn one's self (i.e. to turn the back to one<ol type='a'><li>of one who no longer cares for another)</li><li>metaphorically to turn one's self from one's course of conduct, i.e. to change one's mind</li></ol></li></ol>","xlit":"stréphō"},"G5501":{"derivation":"irregular comparative of G2556 (κακός);","strongs_def":" from an obsolete equivalent (of uncertain derivation); more evil or aggravated (physically, mentally or morally)","kjv_def":"sorer, worse","translit":"cheírōn","lemma":"χείρων","pron":"khi'-rone","pos":"Adjective","thayer":"<ol><li>worse</li></ol>","xlit":"cheírōn"},"G5306":{"strongs_def":" later","derivation":"comparative from G5259 (ὑπό) (in the sense of behind);","translit":"hýsteros","lemma":"ὕστερος","kjv_def":"latter","pron":"hoos'-ter-os","pos":"Adjective","thayer":"<ol><li>latter, later, coming after, the second</li><li>afterward, after this, later, lastly</li></ol>","xlit":"hýsteros"},"G1226":{"kjv_def":"affirm constantly","translit":"diabebaióomai","lemma":"διαβεβαιόομαι","derivation":"middle voice of a compound of G1223 (διά) and G950 (βεβαιόω);","strongs_def":" to confirm thoroughly (by words), i.e. asseverate","pron":"dee-ab-eb-ahee-o'-om-ahee","pos":"Verb","thayer":"<ol><li>to affirm strongly, assert confidently</li></ol>","xlit":"diabebaióomai"},"G827":{"derivation":"of uncertain derivation;","strongs_def":" a ray of light, i.e. (by implication) radiance, dawn","kjv_def":"break of day","translit":"augḗ","lemma":"αὐγή","pron":"owg'-ay","pos":"Noun Feminine","thayer":"<ol><li>brightness, radiance, daylight</li></ol>","xlit":"augḗ"},"G655":{"translit":"apostygéō","lemma":"ἀποστυγέω","kjv_def":"abhor","strongs_def":" to detest utterly","derivation":"from G575 (ἀπό) and the base of G4767 (στυγνητός);","pron":"ap-os-toog-eh'-o","pos":"Verb","thayer":"<ol><li>to dislike, abhor, have a horror of</li></ol>","xlit":"apostygéō"},"G5061":{"derivation":"of uncertain derivation;","strongs_def":" Tertullus, a Roman","kjv_def":"Tertullus","translit":"Tértyllos","lemma":"Τέρτυλλος","pron":"ter'-tool-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tertullus = \"triple-hardened\"</p><ol><li>a Roman orator</li></ol>","xlit":"Tértyllos"},"G3173":{"strongs_def":" big (literally or figuratively, in a very wide application)","derivation":"(including the prolonged forms, feminine , plural , etc.; compare also G3176 (μέγιστος), G3187 (μείζων));","lemma":"μέγας","translit":"mégas","kjv_def":"(+ fear) exceedingly, great(-est), high, large, loud, mighty, + (be) sore (afraid), strong, X to years","pron":"meg'-as","pos":"Adjective","thayer":"<ol><li>great<ol type='a'><li>of the external form or sensible appearance of things (or of persons)<ol><li>in particular, of space and its dimensions, as respects<ol type='a'><li>mass and weight: great</li><li>compass and extent: large, spacious</li><li>measure and height: long</li><li>stature and age: great, old</li></ol></li></ol><li>of number and quantity: numerous, large, abundant</li><li>of age: the elder</li><li>used of intensity and its degrees: with great effort, of the affections and emotions of the mind, of natural events powerfully affecting the senses: violent, mighty, strong</li></ol><li>predicated of rank, as belonging to<ol type='a'><li>persons, eminent for ability, virtue, authority, power</li><li>things esteemed highly for their importance: of great moment, of great weight, importance</li><li>a thing to be highly esteemed for its excellence: excellent</li></ol><li>splendid, prepared on a grand scale, stately</li><li>great things<ol type='a'><li>of God's preeminent blessings</li><li>of things which overstep the province of a created being, proud (presumptuous) things, full of arrogance, derogatory to the majesty of God</li></ol></li></ol>","xlit":"mégas"},"G3392":{"strongs_def":" to sully or taint, i.e. contaminate (ceremonially or morally)","derivation":"perhaps a primary verb;","translit":"miaínō","lemma":"μιαίνω","kjv_def":"defile","pron":"me-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to dye with another colour, to stain</li><li>to defile, pollute, sully, contaminate, soil<ol type='a'><li>to defile with sins</li></ol></li></ol>","xlit":"miaínō"},"G470":{"lemma":"ἀνταποκρίνομαι","translit":"antapokrínomai","kjv_def":"answer again, reply against","strongs_def":" to contradict or dispute","derivation":"from G473 (ἀντί) and G611 (ἀποκρίνομαι);","pron":"an-tap-ok-ree'-nom-ahee","pos":"Verb","thayer":"<ol><li>to contradict in reply, to answer by contradiction, reply against</li></ol>","xlit":"antapokrínomai"},"G2554":{"kjv_def":"do(ing) evil","translit":"kakopoiéō","lemma":"κακοποιέω","derivation":"from G2555 (κακοποιός);","strongs_def":" to be a bad-doer, i.e. (objectively) to injure, or (genitive) to sin","pron":"kak-op-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to do harm</li><li>to do evil, do wrong</li></ol>","xlit":"kakopoiéō"},"G3801":{"translit":"ho ṑn kaí ho ēn kaí ho erchómenos","lemma":"ὁ ὢν καί ὁ ἦν καί ὁ ἐρχόμενος","kjv_def":"which art (is, was), and (which) wast (is, was), and art (is) to come (shalt be)","strongs_def":" the one being and the one that was and the one coming, i.e. the Eternal, as a divine epithet of Christ","derivation":"a phrase combining G3588 (ὁ) with the present participle and imperfect of G1510 (εἰμί) and the present participle of G2064 (ἔρχομαι) by means of G2532 (καί);","pron":"Strong's Definition","xlit":"ho ṑn kaí ho ēn kaí ho erchómenos"},"G5562":{"kjv_def":"come, contain, go, have place, (can, be room to) receive","translit":"chōréō","lemma":"χωρέω","derivation":"from G5561 (χώρα);","strongs_def":" to be in (give) space, i.e. (intransitively) to pass, enter, or (transitively) to hold, admit (literally or figuratively)","pron":"kho-reh'-o","pos":"Verb","thayer":"<ol><li>to leave space (which may be filled or occupied by another), to make room, give place, yield<ol type='a'><li>to retire</li><li>metaphorically to betake one's self, turn one's self</li></ol><li>to go forward, advance, proceed, succeed</li><li>to have space or room for receiving or holding something</li></ol>","xlit":"chōréō"},"G1376":{"strongs_def":" a persecutor","derivation":"from G1377 (διώκω);","translit":"diṓktēs","lemma":"διώκτης","kjv_def":"persecutor","pron":"dee-oke'-tace","pos":"Noun Masculine","thayer":"<ol><li>persecutor</li></ol>","xlit":"diṓktēs"},"G1756":{"kjv_def":"effectual, powerful","translit":"energḗs","lemma":"ἐνεργής","derivation":"from G1722 (ἐν) and G2041 (ἔργον);","strongs_def":" active, operative","pron":"en-er-gace'","pos":"Adjective","thayer":"<ol><li>active</li></ol>","xlit":"energḗs"},"G1621":{"derivation":"from G1537 (ἐκ) and tinasso (to swing);","strongs_def":" to shake violently","kjv_def":"shake (off)","translit":"ektinássō","lemma":"ἐκτινάσσω","pron":"ek-tin-as'-so","pos":"Verb","thayer":"<ol><li>to shake off so that something adhering shall fall<ol type='a'><li>by this symbolic act a person, expresses extreme contempt for another and refuses to have any further dealings with him</li><li>to shake off for (the cleansing of) one's self</li></ol></li></ol>","xlit":"ektinássō"},"G4772":{"strongs_def":" relationship, i.e. (concretely) relatives","derivation":"from G4773 (συγγενής);","lemma":"συγγένεια","translit":"syngéneia","kjv_def":"kindred","pron":"soong-ghen'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>a kinship, relationship</li><li>kindred, relations collectively, family</li></ol>","xlit":"syngéneia"},"G3457":{"strongs_def":" belonging to a mill","derivation":"from G3458 (μύλος);","translit":"mylikós","lemma":"μυλικός","kjv_def":"mill(-stone)","pron":"moo-lee-kos'","pos":"Adjective","thayer":"<ol><li>belonging to a mill</li><li>made of millstone</li></ol>","xlit":"mylikós"},"G1631":{"kjv_def":"put forth","translit":"ekphýō","lemma":"ἐκφύω","derivation":"from G1537 (ἐκ) and G5453 (φύω);","strongs_def":" to sprout up","pron":"ek-foo'-o","pos":"Verb","thayer":"<ol><li>to generate or produce from</li><li>to cause to grow out</li></ol>","xlit":"ekphýō"},"G1982":{"kjv_def":"overshadow","lemma":"ἐπισκιάζω","translit":"episkiázō","derivation":"from G1909 (ἐπί) and a derivative of G4639 (σκιά);","strongs_def":" to cast a shade upon, i.e. (by analogy) to envelop in a haze of brilliancy; figuratively, to invest with preternatural influence","pron":"ep-ee-skee-ad'-zo","pos":"Verb","thayer":"<ol><li>to throw a shadow upon, to envelop in a shadow, to overshadow</li></ol>","xlit":"episkiázō"},"G1387":{"translit":"dolióō","lemma":"δολιόω","kjv_def":"use deceit","strongs_def":" to be guileful","derivation":"from G1386 (δόλιος);","pron":"dol-ee-o'-o","pos":"Verb","thayer":"<ol><li>to deceive, use deceit</li></ol>","xlit":"dolióō"},"G2722":{"derivation":"from G2596 (κατά) and G2192 (ἔχω);","strongs_def":" to hold down (fast), in various applications (literally or figuratively)","kjv_def":"have, hold (fast), keep (in memory), let, X make toward, possess, retain, seize on, stay, take, withhold","translit":"katéchō","lemma":"κατέχω","pron":"kat-ekh'-o","pos":"Verb","thayer":"<ol><li>to hold back, detain, retain<ol type='a'><li>from going away</li><li>to restrain, hinder (the course or progress of)<ol><li>that which hinders, Antichrist from making his appearance</li><li>to check a ship's headway, i.e. to hold or head the ship</li></ol><li>to hold fast, keep secure, keep firm possession of</li></ol><li>to get possession of, take<ol type='a'><li>to possess</li></ol></li></ol>","xlit":"katéchō"},"G4965":{"kjv_def":"Sychar","translit":"Sychár","lemma":"Συχάρ","derivation":"of Hebrew origin (H07941);","strongs_def":" Sychar (i.e. Shekar), a place in Palestine","pron":"soo-khar'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sychar = \"drunken\"</p><ol><li>probably another name for the town of Shechem, a town in Samaria, near the well of Jacob</li></ol>","xlit":"Sychár"},"G5361":{"kjv_def":"love as brethren","lemma":"φιλάδελφος","translit":"philádelphos","derivation":"from G5384 (φίλος) and G80 (ἀδελφός);","strongs_def":" fond of brethren, i.e. fraternal","pron":"fil-ad'-el-fos","pos":"Adjective","thayer":"<ol><li>loving brother or sister</li><li>in a broader sense, loving one like a brother, loving one's fellow countrymen<ol type='a'><li>of an Israelite</li><li>of a Christian loving Christians</li></ol></li></ol>","xlit":"philádelphos"},"G1198":{"translit":"désmios","lemma":"δέσμιος","kjv_def":"in bonds, prisoner","strongs_def":" a captive (as bound)","derivation":"from G1199 (δεσμόν);","pron":"des'-mee-os","pos":"Adjective","thayer":"<ol><li>bound, in bonds, a captive, a prisoner</li></ol>","xlit":"désmios"},"G1899":{"derivation":"from G1909 (ἐπί) and G1534 (εἶτα);","strongs_def":" thereafter","kjv_def":"after that(-ward), then","translit":"épeita","lemma":"ἔπειτα","pron":"ep'-i-tah","pos":"Adverb","thayer":"<ol><li>thereupon, thereafter, then, afterwards</li></ol>","xlit":"épeita"},"G4599":{"strongs_def":" probably akin to the base of G2476 (ἵστημι)); to strengthen, i.e. (figuratively) confirm (in spiritual knowledge and power)","derivation":"from (bodily vigor;","lemma":"σθενόω","translit":"sthenóō","kjv_def":"strengthen","pron":"sthen-o'-o","pos":"Verb","thayer":"<ol><li>to make strong, strengthen<ol type='a'><li>of one's soul</li></ol></li></ol>","xlit":"sthenóō"},"G2500":{"kjv_def":"Joses","lemma":"Ἰωσῆς","translit":"Iōsēs","derivation":"perhaps for G2501 (Ἰωσήφ);","strongs_def":" Joses, the name of two Israelites","pron":"ee-o-sace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Joses = \"exalted\"</p><ol><li>one of the ancestors of Christ, <a class='bible' href='#b42.3.29'>Luk 3:29</a></li><li>Joses, the brother of Jesus, <a class='bible' href='#b41.6.3'>Mar 6:3</a></li><li>Joses, the son of Mary, the sister of the mother of Jesus, <a class='bible' href='#b40.27.56'>Mat 27:56</a></li><li>Joses, a Levite, <a class='bible' href='#b44.4.36'>Act 4:36</a></li></ol>","xlit":"Iōsēs"},"G4387":{"derivation":"comparative of G4253 (πρό);","strongs_def":" prior or previous","kjv_def":"former","lemma":"πρότερος","translit":"próteros","pron":"prot'-er-os","pos":"Adjective","thayer":"<ol><li>before, prior<ol type='a'><li>of time, previous, former</li></ol></li></ol>","xlit":"próteros"},"G1203":{"lemma":"δεσπότης","translit":"despótēs","kjv_def":"Lord, master","strongs_def":" an absolute ruler (\"despot\")","derivation":"perhaps from G1210 (δέω) and (a husband);","pron":"des-pot'-ace","pos":"Noun Masculine","thayer":"<ol><li>a master, Lord</li></ol>","xlit":"despótēs"},"G438":{"kjv_def":"flower","lemma":"ἄνθος","translit":"ánthos","derivation":"a primary word;","strongs_def":" a blossom","pron":"anth'-os","pos":"Noun Neuter","thayer":"<ol><li>a flower</li></ol>","xlit":"ánthos"},"G5143":{"lemma":"τρέχω","translit":"tréchō","kjv_def":"have course, run","strongs_def":" compare G2359 (θρίξ)); which uses (the base of G1408 (δρόμος)) as alternate in certain tenses; to run or walk hastily (literally or figuratively)","derivation":"apparently a primary verb (properly, ;","pron":"trekh'-o","pos":"Verb","thayer":"<ol><li>to run<ol type='a'><li>of persons in haste</li><li>of those who run in a race course</li></ol><li>metaphorically<ol type='a'><li>of doctrine rapidly propagated</li><li>by a metaphor taken from runners in a race, to exert one's self, strive hard</li><li>to spend one's strength in performing or attaining something</li><li>word occurs in Greek writings denoting to incur extreme peril, which it requires the exertion of all one's effort to overcome</li></ol></li></ol>","xlit":"tréchō"},"G5153":{"kjv_def":"three thousand","translit":"trischílioi","lemma":"τρισχίλιοι","derivation":"from G5151 (τρίς) and G5507 (χίλιοι);","strongs_def":" three times a thousand","pron":"tris-khil'-ee-oy","pos":"Adjective","thayer":"<ol><li>three thousand</li></ol>","xlit":"trischílioi"},"G797":{"strongs_def":" to flash as lightning","derivation":"probably from G792 (ἀστήρ);","lemma":"ἀστράπτω","translit":"astráptō","kjv_def":"lighten, shine","pron":"as-trap'-to","pos":"Verb","thayer":"<ol><li>to lighten<ol type='a'><li>of dazzling objects</li></ol></li></ol>","xlit":"astráptō"},"G1364":{"lemma":"δίς","translit":"dís","kjv_def":"again, twice","strongs_def":" twice","derivation":"adverb from G1417 (δύο);","pron":"dece","pos":"Adverb","thayer":"<ol><li>twice</li></ol>","xlit":"dís"},"G5087":{"derivation":"a prolonged form of a primary (which is used only as alternate in certain tenses);","strongs_def":" to place (in the widest application, literally and figuratively; properly, in a passive or horizontal posture, and thus different from G2476 (ἵστημι), which properly denotes an upright and active position, while G2749 (κεῖμαι) is properly reflexive and utterly prostrate)","kjv_def":"+ advise, appoint, bow, commit, conceive, give, X kneel down, lay (aside, down, up), make, ordain, purpose, put, set (forth), settle, sink down","translit":"títhēmi","lemma":"τίθημι","pron":"tith'-ay-mee","pos":"Verb","thayer":"<ol><li>to set, put, place<ol type='a'><li>to place or lay</li><li>to put down, lay down<ol><li>to bend down</li><li>to lay off or aside, to wear or carry no longer</li><li>to lay by, lay aside money</li></ol><li>to set on (serve) something to eat or drink</li><li>to set forth, something to be explained by discourse</li></ol><li>to make<ol type='a'><li>to make (or set) for one's self or for one's use</li></ol><li>to set, fix establish<ol type='a'><li>to set forth</li><li>to establish, ordain</li></ol></li></ol>","xlit":"títhēmi"},"G570":{"kjv_def":"unbelief","translit":"apistía","lemma":"ἀπιστία","derivation":"from G571 (ἄπιστος);","strongs_def":" faithlessness, i.e. (negatively) disbelief (lack of Christian faith), or (positively) unfaithfulness (disobedience)","pron":"ap-is-tee'-ah","pos":"Noun Feminine","thayer":"<ol><li>unfaithfulness, faithless</li><li>want of faith, unbelief</li><li>weakness of faith</li></ol>","xlit":"apistía"},"G3697":{"derivation":"from G3739 (ὅς) and G4169 (ποῖος);","strongs_def":" of what kind that, i.e. how (as) great (excellent) (specially, as an indefinite correlative to the definite antecedent G5108 (τοιοῦτος) of quality)","kjv_def":"what manner (sort) of, such as whatsoever","lemma":"ὁποῖος","translit":"hopoîos","pron":"hop-oy'-os","thayer":"<ol><li>of what sort or quality, what manner of</li></ol>","xlit":"hopoîos"},"G4737":{"translit":"stephanóō","lemma":"στεφανόω","kjv_def":"crown","strongs_def":" to adorn with an honorary wreath (literally or figuratively)","derivation":"from G4735 (στέφανος);","pron":"stef-an-o'-o","pos":"Verb","thayer":"<ol><li>to encircle with a crown, to crown: the victor in a contest</li><li>to adorn, to honour</li></ol>","xlit":"stephanóō"},"G66":{"strongs_def":" wild (as pertaining to the country), literally (natural) or figuratively (fierce)","derivation":"from G68 (ἀγρός);","lemma":"ἄγριος","translit":"ágrios","kjv_def":"wild, raging","pron":"ag'-ree-os","pos":"Adjective","thayer":"<ol><li>living or growing in the fields or woods<ol type='a'><li>of animals, wild, savage</li><li>of countries, wild, uncultivated, unreclaimed</li></ol><li>of men and animals in a moral sense, wild savage, fierce<ol type='a'><li>boorish, rude</li><li>of any violent passion, vehement, furious</li></ol></li></ol>","xlit":"ágrios"},"G1912":{"strongs_def":" to be heavy upon, i.e. (pecuniarily) to be expensive to; figuratively, to be severe towards","derivation":"from G1909 (ἐπί) and G916 (βαρέω);","translit":"epibaréō","lemma":"ἐπιβαρέω","kjv_def":"be chargeable to, overcharge","pron":"ep-ee-bar-eh'-o","pos":"Verb","thayer":"<ol><li>to put a burden upon, to load</li><li>to be burdensome</li></ol>","xlit":"epibaréō"},"G2242":{"derivation":"of Hebrew origin (H05941);","strongs_def":" Heli (i.e. Eli), an Israelite","kjv_def":"Heli","lemma":"Ἡλί","translit":"Hēlí","pron":"hay-lee'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Heli = \"ascending\"</p><ol><li>the father of Joseph, the husband of Mary</li></ol>","xlit":"Hēlí"},"G2047":{"lemma":"ἐρημία","translit":"erēmía","kjv_def":"desert, wilderness","strongs_def":" solitude (concretely)","derivation":"from G2048 (ἔρημος);","pron":"er-ay-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a solitude, an uninhabited region, a waste</li></ol>","xlit":"erēmía"},"G4469":{"kjv_def":"Raca","translit":"rhaká","lemma":"ῥακά","derivation":"of Chaldee origin (compare H07386);","strongs_def":" O empty one, i.e. thou worthless (as a term of utter vilification)","pron":"rhak-ah'","pos":"Noun","thayer":"<ol><li>empty, i.e. a senseless, empty headed man</li><li>a term of reproach used among the Jews in the time of Christ</li></ol>","xlit":"rhaká"},"G3327":{"derivation":"from G3326 (μετά) and the base of G939 (βάσις);","strongs_def":" to change place","kjv_def":"depart, go, pass, remove","translit":"metabaínō","lemma":"μεταβαίνω","pron":"met-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to pass over from one place to another, to remove, depart</li></ol>","xlit":"metabaínō"},"G871":{"derivation":"from G575 (ἀπό) and G3666 (ὁμοιόω);","strongs_def":" to assimilate closely","kjv_def":"make like","translit":"aphomoióō","lemma":"ἀφομοιόω","pron":"af-om-oy-o'-o","pos":"Verb","thayer":"<ol><li>to cause a model to pass off into an image or shape like it</li><li>to express itself in it, to copy</li><li>to produce a facsimile</li><li>to be made like, render similar</li></ol>","xlit":"aphomoióō"},"G4184":{"strongs_def":" extremely compassionate","derivation":"from G4183 (πολύς) and G4698 (σπλάγχνον) (figuratively);","lemma":"πολύσπλαγχνος","translit":"polýsplanchnos","kjv_def":"very pitiful","pron":"pol-oo'-splankh-nos","pos":"Adjective","thayer":"<ol><li>full of pity, very kind</li></ol>","xlit":"polýsplanchnos"},"G439":{"derivation":"from G440 (ἄνθραξ);","strongs_def":" a bed of burning coals","kjv_def":"fire of coals","translit":"anthrakiá","lemma":"ἀνθρακιά","pron":"anth-rak-ee-ah'","pos":"Noun Feminine","thayer":"<ol><li>a heap of burning coals</li></ol>","xlit":"anthrakiá"},"G1197":{"strongs_def":" a bundle","derivation":"from G1196 (δεσμέω);","lemma":"δέσμη","translit":"désmē","kjv_def":"bundle","pron":"des-may'","pos":"Noun Feminine","thayer":"<ol><li>a bundle</li></ol>","xlit":"désmē"},"G1787":{"translit":"entós","lemma":"ἐντός","kjv_def":"within","strongs_def":" inside (adverb or noun)","derivation":"from G1722 (ἐν);","pron":"en-tos'","pos":"Preposition","thayer":"<ol><li>within, inside<ol type='a'><li>within you, i.e. in the midst of you</li><li>within you, i.e. your soul</li></ol></li></ol>","xlit":"entós"},"G1494":{"lemma":"εἰδωλόθυτον","translit":"eidōlóthyton","kjv_def":"(meat, thing that is) offered (in sacrifice, sacrificed) to (unto) idols","strongs_def":" an image-sacrifice, i.e. part of an idolatrous offering","derivation":"neuter of a compound of G1497 (εἴδωλον) and a presumed derivative of G2380 (θύω);","pron":"i-do-loth'-oo-ton","pos":"Adjective","thayer":"<ol><li>sacrificed to idols, the flesh left over from the heathen sacrifices<ol type='a'><li>it was either eaten at the feasts or sold (by the poor and the miserly) in the market</li></ol></li></ol>","xlit":"eidōlóthyton"},"G624":{"derivation":"from the pagan deity (i.e. the sun;","strongs_def":" from G622 (ἀπόλλυμι)); Apollonia, a place in Macedonia","kjv_def":"Apollonia","lemma":"Ἀπολλωνία","translit":"Apollōnía","pron":"ap-ol-lo-nee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Apollonia = \"belonging to Apollo\"</p><ol><li>a maritime city of Macedonia, about a day's journey from Amphipolis</li></ol>","xlit":"Apollōnía"},"G890":{"kjv_def":"unprofitable","translit":"áchrēstos","lemma":"ἄχρηστος","derivation":"from G1 (Α) (as a negative particle) and G5543 (χρηστός);","strongs_def":" inefficient, i.e. (by implication) detrimental","pron":"akh'-race-tos","pos":"Adjective","thayer":"<ol><li>useless, unprofitable</li></ol>","xlit":"áchrēstos"},"G4810":{"lemma":"σῦκον","translit":"sŷkon","kjv_def":"fig","strongs_def":" a fig","derivation":"apparently a primary word;","pron":"soo'-kon","pos":"Noun Neuter","thayer":"<ol><li>a fig, the ripe fruit of a fig tree</li></ol>","xlit":"sŷkon"},"G3733":{"strongs_def":" a bird (as rising in the air), i.e. (specially), a hen (or female domestic fowl)","derivation":"probably from a prolonged form of the base of G3735 (ὄρος);","lemma":"ὄρνις","translit":"órnis","kjv_def":"hen","pron":"or'-nis","pos":"Noun Masculine","thayer":"<ol><li>a bird</li><li>a cock, a hen</li></ol>","xlit":"órnis"},"G338":{"kjv_def":"blameless, guiltless","lemma":"ἀναίτιος","translit":"anaítios","derivation":"from G1 (Α) (as a negative particle) and G159 (αἴτιος) (in the sense of G156 (αἰτία));","strongs_def":" innocent","pron":"an-ah'-ee-tee-os","pos":"Adjective","thayer":"<ol><li>guiltless, innocent</li></ol>","xlit":"anaítios"},"G148":{"derivation":"from G150 (αἰσχρός) and G3056 (λόγος);","strongs_def":" vile conversation","kjv_def":"filthy communication","lemma":"αἰσχρολογία","translit":"aischrología","pron":"ahee-skhrol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>foul speaking, low and obscene speech</li></ol>","xlit":"aischrología"},"G3978":{"kjv_def":"go afoot","lemma":"πεζεύω","translit":"pezeúō","derivation":"from the same as G3979 (πεζῇ);","strongs_def":" to foot a journey, i.e. travel by land","pron":"ped-zyoo'-o","pos":"Verb","thayer":"<ol><li>to travel on foot (not on horseback or in carriage), or (if opp. to going by sea) by land</li></ol>","xlit":"pezeúō"},"G4536":{"lemma":"σάλπιγξ","translit":"sálpinx","kjv_def":"trump(-et)","strongs_def":" a trumpet","derivation":"perhaps from G4535 (σάλος) (through the idea of quavering or reverberation);","pron":"sal'-pinx","pos":"Noun Feminine","thayer":"<ol><li>a trumpet</li></ol>","xlit":"sálpinx"},"G2850":{"translit":"kolakeía","lemma":"κολακεία","kjv_def":" X flattering","strongs_def":" flattery","derivation":"from a derivative of (a fawner);","pron":"kol-ak-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>flattery, flattering discourse</li></ol>","xlit":"kolakeía"},"G4192":{"translit":"pónos","lemma":"πόνος","kjv_def":"pain","strongs_def":" toil, i.e. (by implication) anguish","derivation":"from the base of G3993 (πένης);","pron":"pon'-os","pos":"Noun Masculine","thayer":"<ol><li>great trouble, intense desire</li><li>pain</li></ol>","xlit":"pónos"},"G532":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G3903 (παρασκευάζω);","strongs_def":" unready","kjv_def":"unprepared","lemma":"ἀπαρασκεύαστος","translit":"aparaskeúastos","pron":"ap-ar-ask-yoo'-as-tos","pos":"Adjective","thayer":"<ol><li>unprepared</li></ol>","xlit":"aparaskeúastos"},"G5447":{"translit":"physikōs","lemma":"φυσικῶς","kjv_def":"naturally","strongs_def":" \"physically\", i.e. (by implication) instinctively","derivation":"adverb from G5446 (φυσικός);","pron":"foo-see-koce'","pos":"Adverb","thayer":"<ol><li>in a natural manner, by nature, under the guidance of nature: by the aid of the bodily senses</li></ol>","xlit":"physikōs"},"G3175":{"translit":"megistânes","lemma":"μεγιστᾶνες","kjv_def":"great men, lords","strongs_def":" grandees","derivation":"plural from G3176 (μέγιστος);","pron":"meg-is-tan'-es","pos":"Noun Masculine","thayer":"<ol><li>the grandees, magnates, nobles, chief men<ol type='a'><li>of a city or a people</li><li>of the associates or courtiers of a king</li></ol></li></ol>","xlit":"megistânes"},"G3418":{"lemma":"μνῆμα","translit":"mnēma","kjv_def":"grave, sepulchre, tomb","strongs_def":" a memorial, i.e. sepulchral monument (burial-place)","derivation":"from G3415 (μνάομαι);","pron":"mnay'-mah","pos":"Noun Neuter","thayer":"<ol><li>a monument or memorial to perpetuate the memory of any person or thing</li><li>a sepulchral monument</li><li>a sepulchre or tomb</li></ol>","xlit":"mnēma"},"G2414":{"derivation":"of Hebrew origin (H03389);","strongs_def":" Hierosolyma (i.e. Jerushalaim), the capitol of Palestine","kjv_def":"Jerusalem","translit":"Hierosólyma","lemma":"Ἱεροσόλυμα","pron":"hee-er-os-ol'-oo-mah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Jerusalem = \"set ye double peace\"</p><ol><li>denotes either the city itself or the inhabitants</li><li>\"the Jerusalem that now is\" , with its present religious institutions, i.e. the Mosaic system, so designated from its primary external location</li><li>\"Jerusalem that is above\" , that is existing in heaven, according to the pattern of which the earthly Jerusalem was supposed to be built<ol type='a'><li>metaphorically \"the City of God founded by Christ\" , now wearing the form of the church, but after Christ's return to put on the form of the perfected Messianic kingdom</li></ol><li>\"the heavenly Jerusalem\" , that is the heavenly abode of God, Christ, the angels, saints of the Old and New Testament periods and those Christians that are alive at Christ's return</li><li>\"the New Jerusalem\" , a splendid visible city to be let down from heaven after the renovation of the world, the future abode of the blessed</li></ol>","xlit":"Hierosólyma"},"G3883":{"derivation":"from a compound of G3844 (παρά) and G236 (ἀλλάσσω);","strongs_def":" transmutation (of phase or orbit), i.e. (figuratively) fickleness","kjv_def":"variableness","translit":"parallagḗ","lemma":"παραλλαγή","pron":"par-al-lag-ay'","pos":"Noun Feminine","thayer":"<ol><li>variation, change</li></ol>","xlit":"parallagḗ"},"G253":{"strongs_def":" more without grief","derivation":"comparative of a compound of G1 (Α) (as a negative particle) and G3077 (λύπη);","lemma":"ἀλυπότερος","translit":"alypóteros","kjv_def":"less sorrowful","pron":"al-oo-pot'-er-os","pos":"Adjective","thayer":"<ol><li>free from pain or grief</li></ol>","xlit":"alypóteros"},"G4936":{"strongs_def":" to rush together (hastily assemble) or headlong (figuratively)","derivation":"from G4862 (σύν) and G5143 (τρέχω) (including its alternate);","lemma":"συντρέχω","translit":"syntréchō","kjv_def":"run (together, with)","pron":"soon-trekh'-o","pos":"Verb","thayer":"<ol><li>to run together<ol type='a'><li>of the gathering of a multitude</li></ol><li>to run along with others</li><li>metaphorically<ol type='a'><li>to rush with, to cast one's self, plunge</li></ol></li></ol>","xlit":"syntréchō"},"G3431":{"lemma":"μοιχεύω","translit":"moicheúō","kjv_def":"commit adultery","strongs_def":" to commit adultery","derivation":"from G3432 (μοιχός);","pron":"moy-khyoo'-o","pos":"Verb","thayer":"<ol><li>to commit adultery<ol type='a'><li>to be an adulterer</li><li>to commit adultery with, have unlawful intercourse with another's wife</li><li>of the wife: to suffer adultery, be debauched</li><li>A Hebrew idiom, the word is used of those who at a woman's solicitation are drawn away to idolatry, i.e. to the eating of things sacrificed to idols</li></ol></li></ol>","xlit":"moicheúō"},"G4106":{"derivation":"feminine of G4108 (πλάνος) (as abstractly);","strongs_def":" objectively, fraudulence; subjectively, a straying from orthodoxy or piety","kjv_def":"deceit, to deceive, delusion, error","lemma":"πλάνη","translit":"plánē","pron":"plan'-ay","pos":"Noun Feminine","thayer":"<ol><li>a wandering, a straying about<ol type='a'><li>one led astray from the right way, roams hither and thither</li></ol><li>metaphorically<ol type='a'><li>mental straying<ol><li>error, wrong opinion relative to morals or religion</li></ol><li>error which shows itself in action, a wrong mode of acting</li><li>error, that which leads into error, deceit or fraud</li></ol></li></ol>","xlit":"plánē"},"G4642":{"strongs_def":" dry, i.e. hard or tough (figuratively, harsh, severe)","derivation":"from the base of G4628 (σκέλος);","lemma":"σκληρός","translit":"sklērós","kjv_def":"fierce, hard","pron":"sklay-ros'","pos":"Adjective","thayer":"<ol><li>hard, harsh, rough, stiff<ol type='a'><li>of men: metaphorically harsh, stern, hard</li><li>of things: violent, rough, offensive, intolerable</li></ol></li></ol>","xlit":"sklērós"},"G1444":{"lemma":"Ἑβραϊκός","translit":"Hebraïkós","kjv_def":"Hebrew","strongs_def":" Hebraic or the Jewish language","derivation":"from G1443 (Ἐβέρ);","pron":"heb-rah-ee-kos'","pos":"Adjective","thayer":"<ol><li>Hebrew</li></ol>","xlit":"Hebraïkós"},"G3141":{"derivation":"from G3144 (μάρτυς);","strongs_def":" evidence given (judicially or genitive case)","kjv_def":"record, report, testimony, witness","lemma":"μαρτυρία","translit":"martyría","pron":"mar-too-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a testifying<ol type='a'><li>the office committed to the prophets of testifying concerning future events</li></ol><li>what one testifies, testimony, i.e. before a judge</li></ol>","xlit":"martyría"},"G2303":{"derivation":"probably neuter of G2304 (θεῖος) (in its original sense of flashing);","strongs_def":" sulphur","kjv_def":"brimstone","lemma":"θεῖον","translit":"theîon","pron":"thi'-on","pos":"Noun Neuter","thayer":"<ol><li>brimstone<ol type='a'><li>divine incense, because burning brimstone was regarded as having power to purify, and to ward off disease</li></ol></li></ol>","xlit":"theîon"},"G2938":{"strongs_def":" an original formation (concretely), i.e. product (created thing)","derivation":"from G2936 (κτίζω);","translit":"ktísma","lemma":"κτίσμα","kjv_def":"creature","pron":"ktis'-mah","pos":"Noun Neuter","thayer":"<ol><li>thing founded</li><li>created thing</li></ol>","xlit":"ktísma"},"G2749":{"strongs_def":" to lie outstretched (literally or figuratively)","derivation":"middle voice of a primary verb;","translit":"keîmai","lemma":"κεῖμαι","kjv_def":"be (appointed, laid up, made, set), lay, lie","pron":"ki'-mahee","pos":"Verb","thayer":"<ol><li>to lie<ol type='a'><li>of an infant</li><li>of one buried</li><li>of things that quietly cover some spot<ol><li>of a city situated on a hill</li></ol><li>of things put or set in any place, in ref. to which we often use \"to stand\"<ol><li>of vessels, of a throne, of the site of a city, of grain and other things laid up together, of a foundation</li></ol></li></ol><li>metaphorically<ol type='a'><li>to be (by God's intent) set, i.e. destined, appointed</li><li>of laws, to be made, laid down</li><li>lies in the power of the evil one, i.e. is held in subjection by the devil</li></ol></li></ol>","xlit":"keîmai"},"G4358":{"kjv_def":"draw to the shore","translit":"prosormízō","lemma":"προσορμίζω","derivation":"from G4314 (πρός) and a derivative of the same as G3730 (ὁρμή) (meaning to tie (anchor) or lull);","strongs_def":" to moor to, i.e. (by implication) land at","pron":"pros-or-mid'-zo","pos":"Verb","thayer":"<ol><li>to bring a ship to moorings</li><li>to take one's station near the shore</li><li>to moor, come to anchor</li></ol>","xlit":"prosormízō"},"G826":{"kjv_def":"shine","translit":"augázō","lemma":"αὐγάζω","derivation":"from G827 (αὐγή);","strongs_def":" to beam forth (figuratively)","pron":"ow-gad'-zo","pos":"Verb","thayer":"<ol><li>to beam upon, irradiate</li><li>to be bright, to shine forth</li></ol>","xlit":"augázō"},"G2431":{"lemma":"ἱλαρός","translit":"hilarós","kjv_def":"cheerful","strongs_def":" propitious or merry (\"hilarious\"), i.e. prompt or willing","derivation":"from the same as G2436 (ἵλεως);","pron":"hil-ar-os'","pos":"Adjective","thayer":"<ol><li>cheerful, joyous, prompt to do anything</li></ol>","xlit":"hilarós"},"G5620":{"translit":"hṓste","lemma":"ὥστε","kjv_def":"(insomuch) as, so that (then), (insomuch) that, therefore, to, wherefore","strongs_def":" so too, i.e. thus therefore (in various relations of consecution, as follow)","derivation":"from G5613 (ὡς) and G5037 (τέ);","pron":"hoce'-teh","thayer":"<ol><li>so that, insomuch that</li><li>so then, therefore, wherefore</li></ol>","xlit":"hṓste"},"G17":{"lemma":"ἀγαθοποιός","translit":"agathopoiós","kjv_def":"them that do well","strongs_def":" a well-doer, i.e. virtuous","derivation":"from G18 (ἀγαθός) and G4160 (ποιέω);","pron":"ag-ath-op-oy-os'","pos":"Adjective","thayer":"<ol><li>acting rightly, doing well, virtuous</li></ol>","xlit":"agathopoiós"},"G4700":{"derivation":"of uncertain derivation;","strongs_def":" ashes","kjv_def":"ashes","translit":"spodós","lemma":"σποδός","pron":"spod-os'","pos":"Noun Masculine","thayer":"<ol><li>ashes: placed on sackcloth as a token of grief</li></ol>","xlit":"spodós"},"G1722":{"strongs_def":" \"in,\" at, (up-)on, by, etc.","derivation":"a primary preposition denoting (fixed) position (in place, time or state), and (by implication) instrumentality (medially or constructively), i.e. a relation of rest (intermediate between G1519 (εἰς) and G1537 (ἐκ));","translit":"en","lemma":"ἐν","kjv_def":"about, after, against, + almost, X altogether, among, X as, at, before, between, (here-)by (+ all means), for (… sake of), + give self wholly to, (here-)in(-to, -wardly), X mightily, (because) of, (up-)on, (open-)ly, X outwardly, one, X quickly, X shortly, (speedi-)ly, X that, X there(-in, -on), through(-out), (un-)to(-ward), under, when, where(-with), while, with(-in)","pron":"en","pos":"Preposition","thayer":"<ol><li>in, by, with etc.</li></ol>","xlit":"en"},"G2070":{"strongs_def":" we are","derivation":"first person plural indicative of G1510 (εἰμί);","lemma":"ἐσμέν","translit":"esmén","kjv_def":"are, be, have our being, X have hope, + (the gospel) was (preached unto) us","pron":"es-men'","pos":"Verb","thayer":"<ol><li>first person plural of \"to be\"</li></ol>","xlit":"esmén"},"G3808":{"derivation":"neuter of a presumed derivative of G3816 (παῖς);","strongs_def":" a little boy","kjv_def":"child, lad","translit":"paidárion","lemma":"παιδάριον","pron":"pahee-dar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>little boy, a lad</li></ol>","xlit":"paidárion"},"G4162":{"kjv_def":"deed","lemma":"ποίησις","translit":"poíēsis","derivation":"from G4160 (ποιέω);","strongs_def":" action, i.e. performance (of the law)","pron":"poy'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>a making</li><li>a doing or performing<ol type='a'><li>in his doing, i.e. in the obedience he renders to the law</li></ol></li></ol>","xlit":"poíēsis"},"G4333":{"kjv_def":"gain","translit":"prosergázomai","lemma":"προσεργάζομαι","derivation":"from G4314 (πρός) and G2038 (ἐργάζομαι);","strongs_def":" to work additionally, i.e. (by implication) acquire besides","pron":"pros-er-gad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to work besides</li><li>by working or trading to make or gain besides</li></ol>","xlit":"prosergázomai"},"G2189":{"strongs_def":" hostility; by implication, a reason for opposition","derivation":"feminine of G2190 (ἐχθρός);","lemma":"ἔχθρα","translit":"échthra","kjv_def":"enmity, hatred","pron":"ekh'-thrah","pos":"Noun Feminine","thayer":"<ol><li>enmity</li><li>cause of enmity</li></ol>","xlit":"échthra"},"G3766":{"strongs_def":" is it not therefore that, i.e. (affirmatively) hence or so","derivation":"from G3756 (οὐ) and G3767 (οὖν);","lemma":"οὐκοῦν","translit":"oukoûn","kjv_def":"then","pron":"ook-oon'","pos":"Adverb","thayer":"<ol><li>not therefore</li></ol>","xlit":"oukoûn"},"G2621":{"kjv_def":"keep, lie, sit at meat (down)","lemma":"κατάκειμαι","translit":"katákeimai","derivation":"from G2596 (κατά) and G2749 (κεῖμαι);","strongs_def":" to lie down, i.e. (by implication) be sick; specially, to recline at a meal","pron":"kat-ak'-i-mahee","pos":"Verb","thayer":"<ol><li>to have lain down, i.e. to lie prostrate<ol type='a'><li>of the sick</li><li>of those at meals, to recline</li></ol></li></ol>","xlit":"katákeimai"},"G175":{"kjv_def":"without fruit, unfruitful","lemma":"ἄκαρπος","translit":"ákarpos","derivation":"from G1 (Α) (as a negative particle) and G2590 (καρπός);","strongs_def":" barren (literally or figuratively)","pron":"ak'-ar-pos","pos":"Adjective","thayer":"<ol><li>metaphorically without fruit, barren, not yielding what it ought to yield</li></ol>","xlit":"ákarpos"},"G4243":{"derivation":"from the base of G4245 (πρεσβύτερος);","strongs_def":" to be a senior, i.e. (by implication) act as a representative (figuratively, preacher)","kjv_def":"be an ambassador","translit":"presbeúō","lemma":"πρεσβεύω","pron":"pres-byoo'-o","pos":"Verb","thayer":"<ol><li>to be older, prior by birth or in age</li><li>to be an ambassador, act as an ambassador</li></ol>","xlit":"presbeúō"},"G3170":{"kjv_def":"enlarge, magnify, shew great","translit":"megalýnō","lemma":"μεγαλύνω","derivation":"from G3173 (μέγας);","strongs_def":" to make (or declare) great, i.e. increase or (figuratively) extol","pron":"meg-al-oo'-no","pos":"Verb","thayer":"<ol><li>to make great, magnify<ol type='a'><li>metaphorically to make conspicuous</li></ol><li>to deem or declare great<ol type='a'><li>to esteem highly, to extol, laud, celebrate</li></ol><li>to get glory and praise</li></ol>","xlit":"megalýnō"},"G2506":{"derivation":"from G2507 (καθαιρέω);","strongs_def":" demolition; figuratively, extinction","kjv_def":"destruction, pulling down","translit":"kathaíresis","lemma":"καθαίρεσις","pron":"kath-ah'-ee-res-is","pos":"Noun Feminine","thayer":"<ol><li>a pulling down, destruction, demolition</li></ol>","xlit":"kathaíresis"},"G5119":{"derivation":"from (the neuter of) G3588 (ὁ) and G3753 (ὅτε);","strongs_def":" the when, i.e. at the time that (of the past or future, also in consecution)","kjv_def":"that time, then","translit":"tóte","lemma":"τότε","pron":"tot'-eh","pos":"Adverb","thayer":"<ol><li>then</li><li>at that time</li></ol>","xlit":"tóte"},"G1497":{"kjv_def":"idol","lemma":"εἴδωλον","translit":"eídōlon","derivation":"from G1491 (εἶδος);","strongs_def":" an image (i.e. for worship); by implication, a heathen god, or (plural) the worship of such","pron":"i'-do-lon","pos":"Noun Neuter","thayer":"<ol><li>an image, likeness<ol type='a'><li>i.e. whatever represents the form of an object, either real or imaginary</li><li>used of the shades of the departed, apparitions, spectres, phantoms of the mind, etc.</li></ol><li>the image of an heathen god</li><li>a false god</li></ol>","xlit":"eídōlon"},"G3804":{"translit":"páthēma","lemma":"πάθημα","kjv_def":" affection, affliction, motion, suffering","strongs_def":" something undergone, i.e. hardship or pain; subjectively, an emotion or influence","derivation":"from a presumed derivative of G3806 (πάθος);","pron":"path'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>that which one suffers or has suffered<ol type='a'><li>externally, a suffering, misfortune, calamity, evil, affliction<ol><li>of the sufferings of Christ</li><li>also the afflictions which Christians must undergo in behalf of the same cause which Christ patiently endured</li></ol><li>of an inward state, an affliction, passion</li></ol><li>an enduring, undergoing, suffering</li></ol>","xlit":"páthēma"},"G5009":{"derivation":"neuter contraction of a presumed derivative of (a dispenser or distributor;","strongs_def":" akin to , to cut); a dispensary or magazine, i.e. a chamber on the ground-floor or interior of an Oriental house (generally used for storage or privacy, a spot for retirement)","kjv_def":"secret chamber, closet, storehouse","lemma":"ταμεῖον","translit":"tameîon","pron":"tam-i'-on","pos":"Noun Neuter","thayer":"<ol><li>a storage chamber, storeroom</li><li>a chamber especially an inner chamber</li><li>a secret room</li></ol>","xlit":"tameîon"},"G5296":{"kjv_def":"form, pattern","translit":"hypotýpōsis","lemma":"ὑποτύπωσις","derivation":"from a compound of G5259 (ὑπό) and a derivative of G5179 (τύπος);","strongs_def":" typification under (after), i.e. (concretely) a sketch (figuratively) for imitation","pron":"hoop-ot-oop'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>an outline, sketch, brief and summary exposition</li><li>an example, pattern<ol type='a'><li>for an example of those who should hereafter believe</li><li>to show by the example of my conversation that the same grace which I had obtained would not be wanting also to those who should hereafter believe</li></ol></li></ol>","xlit":"hypotýpōsis"},"G4223":{"derivation":"of Latin origin;","strongs_def":" little wells, i.e. mineral springs; Potioli (i.e. Puteoli), a place in Italy","kjv_def":"Puteoli","translit":"Potíoloi","lemma":"Ποτίολοι","pron":"pot-ee'-ol-oy","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Puteoli = \"sulphurous springs\"</p><ol><li>a city of Campania, in Italy, situated on the Bay of Naples</li></ol>","xlit":"Potíoloi"},"G4489":{"lemma":"ῥήτωρ","translit":"rhḗtōr","kjv_def":"orator","strongs_def":" a speaker, i.e. (by implication) a forensic advocate","derivation":"from G4483 (ῥέω);","pron":"hray'-tore","pos":"Noun Masculine","thayer":"<ol><li>a speaker, an orator<ol type='a'><li>of a forensic orator or advocate</li></ol></li></ol>","xlit":"rhḗtōr"},"G1012":{"derivation":"from G1014 (βούλομαι);","strongs_def":" volition, i.e. (objectively) advice, or (by implication) purpose","kjv_def":"+ advise, counsel, will","translit":"boulḗ","lemma":"βουλή","pron":"boo-lay'","pos":"Noun Feminine","thayer":"<ol><li>counsel, purpose</li></ol>","xlit":"boulḗ"},"G3067":{"derivation":"from G3068 (λούω);","strongs_def":" a bath, i.e. (figuratively), baptism","kjv_def":"washing","translit":"loutrón","lemma":"λουτρόν","pron":"loo-tron'","pos":"Noun Neuter","thayer":"<ol><li>bathing, bath, the act of bathing</li></ol>","xlit":"loutrón"},"G1782":{"kjv_def":"(from) hence, on either side","lemma":"ἐντεῦθεν","translit":"enteûthen","derivation":"from the same as G1759 (ἐνθάδε);","strongs_def":" hence (literally or figuratively); (repeated) on both sides","pron":"ent-yoo'-then","pos":"Adverb","thayer":"<ol><li>from this place, hence</li><li>on the one side and on the other, on each side</li></ol>","xlit":"enteûthen"},"G5298":{"kjv_def":"go aside, withdraw self","lemma":"ὑποχωρέω","translit":"hypochōréō","derivation":"from G5259 (ὑπό) and G5562 (χωρέω);","strongs_def":" to vacate down, i.e. retire quietly","pron":"hoop-okh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to go back</li><li>withdraw</li></ol>","xlit":"hypochōréō"},"G2209":{"translit":"zēmía","lemma":"ζημία","kjv_def":"damage, loss","strongs_def":" detriment","derivation":"probably akin to the base of G1150 (δαμάζω) (through the idea of violence);","pron":"dzay-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>damage, loss</li></ol>","xlit":"zēmía"},"G5554":{"lemma":"χρυσοδακτύλιος","translit":"chrysodaktýlios","kjv_def":"with a gold ring","strongs_def":" gold-ringed, i.e. wearing a golden finger-ring or similar jewelry","derivation":"from G5557 (χρυσός) and G1146 (δακτύλιος);","pron":"khroo-sod-ak-too'-lee-os","pos":"Adjective","thayer":"<ol><li>gold ringed, adorned with gold rings</li></ol>","xlit":"chrysodaktýlios"},"G2363":{"translit":"Thyáteira","lemma":"Θυάτειρα","kjv_def":"Thyatira","strongs_def":" Thyatira, a place in Asia Minor","derivation":"of uncertain derivation;","pron":"thoo-at'-i-rah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Thyatira = \"odour of affliction\"</p><ol><li>a colony of Macedonia Greeks, situated between Sardis and Pergamos on the river Lycus; its inhabitants gained their living by traffic and the art of dyeing in purple</li></ol>","xlit":"Thyáteira"},"G1310":{"kjv_def":"blaze abroad, commonly report, spread abroad, fame","lemma":"διαφημίζω","translit":"diaphēmízō","derivation":"from G1223 (διά) and a derivative of G5345 (φήμη);","strongs_def":" to report thoroughly, i.e. divulgate","pron":"dee-af-ay-mid'-zo","pos":"Verb","thayer":"<ol><li>to spread abroad, blaze abroad</li><li>to spread abroad his fame or renown</li></ol>","xlit":"diaphēmízō"},"G649":{"derivation":"from G575 (ἀπό) and G4724 (στέλλω);","strongs_def":" set apart, i.e. (by implication) to send out (properly, on a mission) literally or figuratively","kjv_def":"put in, send (away, forth, out), set (at liberty)","lemma":"ἀποστέλλω","translit":"apostéllō","pron":"ap-os-tel'-lo","pos":"Verb","thayer":"<ol><li>to order (one) to go to a place appointed</li><li>to send away, dismiss<ol type='a'><li>to allow one to depart, that he may be in a state of liberty</li><li>to order one to depart, send off</li><li>to drive away</li></ol></li></ol>","xlit":"apostéllō"},"G503":{"strongs_def":" to face","derivation":"from a compound of G473 (ἀντί) and G3788 (ὀφθαλμός);","translit":"antophthalméō","lemma":"ἀντοφθαλμέω","kjv_def":"bear up into","pron":"ant-of-thal-meh'-o","pos":"Verb","thayer":"<ol><li>to look against or straight at</li><li>metaphorically to bear up against, withstand</li></ol>","xlit":"antophthalméō"},"G2687":{"lemma":"καταστέλλω","translit":"katastéllō","kjv_def":"appease, quiet","strongs_def":" to put down, i.e. quell","derivation":"from G2596 (κατά) and G4724 (στέλλω);","pron":"kat-as-tel'-lo","pos":"Verb","thayer":"<ol><li>to send or put down, to lower</li><li>to put or keep down one who is roused or incensed, to repress, restrain, appease, quiet</li></ol>","xlit":"katastéllō"},"G818":{"strongs_def":" to render infamous, i.e. (by implication) contemn or maltreat","derivation":"from G820 (ἄτιμος);","lemma":"ἀτιμάζω","translit":"atimázō","kjv_def":"despise, dishonour, suffer shame, entreat shamefully","pron":"at-im-ad'-zo","pos":"Verb","thayer":"<ol><li>to dishonour, insult, treat with contempt<ol type='a'><li>whether in word, deed or thought</li></ol></li></ol>","xlit":"atimázō"},"G5178":{"kjv_def":"torture","translit":"tympanízō","lemma":"τυμπανίζω","derivation":"from a derivative of G5180 (τύπτω) (meaning a drum, \"tympanum\");","strongs_def":" to stretch on an instrument of torture resembling a drum, and thus beat to death","pron":"toom-pan-id'-zo","pos":"Verb","thayer":"<ol><li>to beat the drum or timbrel</li><li>to torture with the tympanum, an instrument of punishment</li></ol>","xlit":"tympanízō"},"G4714":{"kjv_def":"dissension, insurrection, X standing, uproar","translit":"stásis","lemma":"στάσις","derivation":"from the base of G2476 (ἵστημι);","strongs_def":" a standing (properly, the act), i.e. (by analogy) position (existence); by implication, a popular uprising; figuratively, controversy","pron":"stas'-is","pos":"Noun Feminine","thayer":"<ol><li>a standing, station, state</li><li>an insurrection</li><li>strife, insurrection</li></ol>","xlit":"stásis"},"G1163":{"translit":"deî","lemma":"δεῖ","kjv_def":"behoved, be meet, must (needs), (be) need(-ful), ought, should","strongs_def":" also deon deh-on'; neuter active participle of the same; both used impersonally; it is (was, etc.) necessary (as binding)","derivation":"3rd person singular active present of G1210 (δέω);","pron":"die","pos":"Verb","thayer":"<ol><li>it is necessary, there is need of, it behooves, is right and proper<ol type='a'><li>necessity lying in the nature of the case</li><li>necessity brought on by circumstances or by the conduct of others toward us.</li><li>necessity in reference to what is required to attain some end</li><li>a necessity of law and command, of duty, equity</li><li>necessity established by the counsel and decree of God, especially by that purpose of his which relates to the salvation of men by the intervention of Christ and which is disclosed in the Old Testament prophecies<ol><li>concerning what Christ was destined finally to undergo, his sufferings, death, resurrection, ascension</li></ol></li></ol></li></ol>","xlit":"deî"},"G4686":{"derivation":"of immediate Latin origin, but ultimately a derivative of G138 (αἱρέομαι) in the sense of its cognate G1507 (εἱλίσσω);","strongs_def":" a coil (spira, \"spire\"), i.e. (figuratively) a mass of men (a Roman military cohort; also (by analogy) a squad of Levitical janitors)","kjv_def":"band","translit":"speîra","lemma":"σπεῖρα","pron":"spi'-rah","pos":"Noun Feminine","thayer":"<ol><li>anything rolled into a circle or ball, anything wound, rolled up, folded together</li><li>a military cohort<ol type='a'><li>the tenth part of legion<ol><li>about 600 men, i.e. legionaries</li><li>if auxiliaries either 500 or 1000</li><li>a maniple, or the thirtieth part of a legion</li></ol><li>any band, company, or detachment, of soldiers</li></ol></li></ol>","xlit":"speîra"},"G1555":{"strongs_def":" to narrate through wholly","derivation":"from G1537 (ἐκ) and a compound of G1223 (διά) and G2233 (ἡγέομαι);","lemma":"ἐκδιηγέομαι","translit":"ekdiēgéomai","kjv_def":"declare","pron":"ek-dee-ayg-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to narrate in full or wholly</li><li>to relate, tell, declare</li></ol>","xlit":"ekdiēgéomai"},"G5177":{"lemma":"τυγχάνω","translit":"tynchánō","kjv_def":"be, chance, enjoy, little, obtain, X refresh…self, + special","strongs_def":" akin to the base of G5088 (τίκτω) through the idea of effecting; properly, to affect; or (specially), to hit or light upon (as a mark to be reached), i.e. (transitively) to attain or secure an object or end, or (intransitively) to happen (as if meeting with); but in the latter application only impersonal (with G1487 (εἰ)), i.e. perchance; or (present participle) as adjective, usual (as if commonly met with, with G3756 (οὐ), extraordinary), neuter (as adverb) perhaps; or (with another verb) as adverb, by accident (as it were)","derivation":"probably for an obsolete (for which the middle voice of another alternate (to make ready or bring to pass) is used in certain tenses;","pron":"toong-khan'-o","pos":"Verb","thayer":"<ol><li>to hit the mark<ol type='a'><li>of one discharging a javelin or arrow</li></ol><li>to reach, attain, obtain, get, become master of</li><li>to happen, chance, fall out<ol type='a'><li>to specify, to take a case, as for example</li></ol><li>to meet one</li><li>of he who meets one or presents himself unsought, any chance, ordinary, common person</li><li>to chance to be</li></ol>","xlit":"tynchánō"},"G4189":{"translit":"ponēría","lemma":"πονηρία","kjv_def":"iniquity, wickedness","strongs_def":" depravity, i.e. (specially), malice; plural (concretely) plots, sins","derivation":"from G4190 (πονηρός);","pron":"pon-ay-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>depravity, iniquity, wickedness</li><li>malice</li><li>evil purposes and desires</li></ol>","xlit":"ponēría"},"G2035":{"derivation":"from G2034 (ἑπτάκις) and G5507 (χίλιοι);","strongs_def":" seven times a thousand","kjv_def":"seven thousand","lemma":"ἑπτακισχίλιοι","translit":"heptakischílioi","pron":"hep-tak-is-khil'-ee-oy","pos":"Noun","thayer":"<ol><li>seven thousand</li></ol>","xlit":"heptakischílioi"},"G1193":{"translit":"dermátinos","lemma":"δερμάτινος","kjv_def":"leathern, of a skin","strongs_def":" made of hide","derivation":"from G1192 (δέρμα);","pron":"der-mat'-ee-nos","pos":"Adjective","thayer":"<ol><li>made of skin, leathern</li></ol>","xlit":"dermátinos"},"G3339":{"translit":"metamorphóō","lemma":"μεταμορφόω","kjv_def":"change, transfigure, transform","strongs_def":" to transform (literally or figuratively, \"metamorphose\")","derivation":"from G3326 (μετά) and G3445 (μορφόω);","pron":"met-am-or-fo'-o","pos":"Verb","thayer":"<ol><li>to change into another form, to transform, to transfigure<ol type='a'><li>Christ's appearance was changed and was resplendent with divine brightness on the mount of transfiguration</li></ol></li></ol>","xlit":"metamorphóō"},"G4086":{"derivation":"from a compound of a derivative of G3982 (πείθω) and G3056 (λόγος);","strongs_def":" persuasive language","kjv_def":"enticing words","lemma":"πιθανολογία","translit":"pithanología","pron":"pith-an-ol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>speech adapted to persuade, discourse in which probable arguments are adduced</li><li>in a bad sense, persuasiveness of speech, specious discourse leading others into error</li></ol>","xlit":"pithanología"},"G223":{"translit":"Aléxandros","lemma":"Ἀλέξανδρος","kjv_def":"Alexander","strongs_def":" man-defender; Alexander, the name of three Israelites and one other man","derivation":"from the same as (the first part of) G220 (ἀλέκτωρ) and G435 (ἀνήρ);","pron":"al-ex'-an-dros","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Alexander = \"man defender\"</p><ol><li>son of Simon of Cyrene who carried Jesus's cross, <a class='bible' href='#b41.15.21'>Mar 15:21</a></li><li>a certain man of the kindred of the high priest, <a class='bible' href='#b44.4.6'>Act 4:6</a></li><li>a certain Jew, <a class='bible' href='#b44.19.33'>Act 19:33</a></li><li>a certain coppersmith who opposed the Apostle Paul, <a class='bible' href='#b54.1.20'>1Ti 1:20</a></li></ol>","xlit":"Aléxandros"},"G4094":{"derivation":"apparently a form of G4109 (πλάξ);","strongs_def":" a plate","kjv_def":"charger, platter","lemma":"πίναξ","translit":"pínax","pron":"pin'-ax","pos":"Noun Feminine","thayer":"<ol><li>a board, a tablet</li><li>a dish, plate, platter</li></ol>","xlit":"pínax"},"G4435":{"kjv_def":"oft","translit":"pygmḗ","lemma":"πυγμή","derivation":"from a primary (the fist as a weapon);","strongs_def":" the clenched hand, i.e. (only in dative case as adverb) with the fist (hard scrubbing)","pron":"poog-may'","pos":"Noun Feminine","thayer":"<ol><li>the fist, clenched hand</li><li>up to the elbow</li></ol>","xlit":"pygmḗ"},"G57":{"translit":"ágnōstos","lemma":"ἄγνωστος","kjv_def":"unknown","strongs_def":" unknown","derivation":"from G1 (Α) (as negative particle) and G1110 (γνωστός);","pron":"ag'-noce-tos'","pos":"Adjective","thayer":"<ol><li>unknown, forgotten</li></ol>","xlit":"ágnōstos"},"G229":{"derivation":"from the same as G224 (ἄλευρον);","strongs_def":" to grind","kjv_def":"grind","lemma":"ἀλήθω","translit":"alḗthō","pron":"al-ay'-tho","pos":"Verb","thayer":"<ol><li>to grind</li></ol>","xlit":"alḗthō"},"G692":{"kjv_def":"barren, idle, slow","translit":"argós","lemma":"ἀργός","derivation":"from G1 (Α) (as a negative particle) and G2041 (ἔργον);","strongs_def":" inactive, i.e. unemployed; (by implication) lazy, useless","pron":"ar-gos'","pos":"Adjective","thayer":"<ol><li>free from labour, at leisure</li><li>lazy, shunning the labour which one ought to perform</li></ol>","xlit":"argós"},"G3670":{"kjv_def":"con- (pro-)fess, confession is made, give thanks, promise","translit":"homologéō","lemma":"ὁμολογέω","derivation":"from a compound of the base of G3674 (ὁμοῦ) and G3056 (λόγος);","strongs_def":" to assent, i.e. covenant, acknowledge","pron":"hom-ol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to say the same thing as another, i.e. to agree with, assent</li><li>to concede<ol type='a'><li>not to refuse, to promise</li><li>not to deny<ol><li>to confess</li><li>declare</li><li>to confess, i.e. to admit or declare one's self guilty of what one is accused of</li></ol></li></ol><li>to profess<ol type='a'><li>to declare openly, speak out freely</li><li>to profess one's self the worshipper of one</li></ol><li>to praise, celebrate</li></ol>","xlit":"homologéō"},"G664":{"kjv_def":"sharply(-ness)","translit":"apotómōs","lemma":"ἀποτόμως","derivation":"adverb from a derivative of a comparative of G575 (ἀπό) and (to cut);","strongs_def":" abruptly, i.e. peremptorily","pron":"ap-ot-om'-oce","pos":"Adverb","thayer":"<ol><li>abruptly, precipitously</li><li>sharply, severely, curtly</li></ol>","xlit":"apotómōs"},"G1678":{"derivation":"of Hebrew origin (perhaps for H0486);","strongs_def":" Elmodam, an Israelite","kjv_def":"Elmodam","lemma":"Ἐλμωδάμ","translit":"Elmōdám","pron":"el-mo-dam'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Elmodam = \"measure\"</p><ol><li>son of Er, in the genealogy of Joseph, <a class='bible' href='#b42.3.28'>Luk 3:28</a></li></ol>","xlit":"Elmōdám"},"G4439":{"derivation":"apparently a primary word;","strongs_def":" a gate, i.e. the leaf or wing of a folding entrance (literally or figuratively)","kjv_def":"gate","lemma":"πύλη","translit":"pýlē","pron":"poo'-lay","pos":"Noun Feminine","thayer":"<ol><li>a gate<ol type='a'><li>of the larger sort<ol><li>in the wall of either a city</li><li>a palace</li><li>a town</li><li>the temple</li><li>a prison</li></ol></li></ol><li>the gates of hell (likened to a vast prison)</li><li>metaphorically the access or entrance into any state</li></ol>","xlit":"pýlē"},"G4153":{"kjv_def":"spiritually","lemma":"πνευματικῶς","translit":"pneumatikōs","derivation":"adverb from G4152 (πνευματικός);","strongs_def":" non-physically, i.e. divinely, figuratively","pron":"pnyoo-mat-ik-oce'","pos":"Adverb","thayer":"<ol><li>spiritually: i.e. by the aid of the Holy Spirit</li></ol>","xlit":"pneumatikōs"},"G4738":{"derivation":"from G2476 (ἵστημι) (as standing prominently);","strongs_def":" the (entire external) bosom, i.e. chest","kjv_def":"breast","lemma":"στῆθος","translit":"stēthos","pron":"stay'-thos","pos":"Noun Neuter","thayer":"<ol><li>the breast</li></ol>","xlit":"stēthos"},"G4230":{"derivation":"from G4231 (πραγματεύομαι);","strongs_def":" a transaction, i.e. negotiation","kjv_def":"affair","translit":"pragmateía","lemma":"πραγματεία","pron":"prag-mat-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>prosecution of any affair<ol type='a'><li>business, occupation</li></ol></li></ol>","xlit":"pragmateía"},"G1671":{"kjv_def":"Greece","lemma":"Ἑλλάς","translit":"Hellás","derivation":"of uncertain affinity;","strongs_def":" Hellas (or Greece), a country of Europe","pron":"hel-las'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Greece = \"unstable: the miry one\"</p><ol><li>a country in southern Europe</li></ol>","xlit":"Hellás"},"G181":{"kjv_def":"commotion, confusion, tumult","lemma":"ἀκαταστασία","translit":"akatastasía","derivation":"from G182 (ἀκατάστατος);","strongs_def":" instability, i.e. disorder","pron":"ak-at-as-tah-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>instability, a state of disorder, disturbance, confusion</li></ol>","xlit":"akatastasía"},"G3947":{"translit":"paroxýnō","lemma":"παροξύνω","kjv_def":"easily provoke, stir","strongs_def":" to sharpen alongside, i.e. (figuratively) to exasperate","derivation":"from G3844 (παρά) and a derivative of G3691 (ὀξύς);","pron":"par-ox-oo'-no","pos":"Verb","thayer":"<ol><li>to make sharp, sharpen<ol type='a'><li>to stimulate, spur on, urge</li><li>to irritate, provoke, arouse to anger<ol><li>to scorn, despise</li><li>provoke, make angry</li><li>to exasperate, to burn with anger</li></ol></li></ol></li></ol>","xlit":"paroxýnō"},"G1212":{"translit":"dēlos","lemma":"δῆλος","kjv_def":"+ bewray, certain, evident, manifest","strongs_def":" clear","derivation":"of uncertain derivation;","pron":"day'-los","pos":"Adjective","thayer":"<ol><li>clear, evident, manifest</li></ol>","xlit":"dēlos"},"G3757":{"strongs_def":" at which place, i.e. where","derivation":"genitive case of G3739 (ὅς) as adverb;","translit":"hoû","lemma":"οὗ","kjv_def":"where(-in), whither(-soever)","pron":"hoo","thayer":"<ol><li>where</li></ol>","xlit":"hoû"},"G3201":{"strongs_def":" to blame","derivation":"middle voice of an apparently primary verb;","translit":"mémphomai","lemma":"μέμφομαι","kjv_def":"find fault","pron":"mem'-fom-ahee","pos":"Verb","thayer":"<ol><li>to blame, find fault</li></ol>","xlit":"mémphomai"},"G5568":{"kjv_def":"psalm","translit":"psalmós","lemma":"ψαλμός","derivation":"from G5567 (ψάλλω);","strongs_def":" a set piece of music, i.e. a sacred ode (accompanied with the voice, harp or other instrument; a \"psalm\"); collectively, the book of the Psalms","pron":"psal-mos'","pos":"Noun Masculine","thayer":"<ol><li>a striking, twanging<ol type='a'><li>of a striking the chords of a musical instrument</li><li>of a pious song, a psalm</li></ol></li></ol>","xlit":"psalmós"},"G3369":{"kjv_def":"not yet","lemma":"μηδέπω","translit":"mēdépō","derivation":"from G3366 (μηδέ) and G4452 (-πω);","strongs_def":" not even yet","pron":"may-dep'-o","pos":"Adverb","thayer":"<ol><li>not yet</li></ol>","xlit":"mēdépō"},"G1488":{"strongs_def":" thou art","derivation":"second person singular present of G1510 (εἰμί);","translit":"eî","lemma":"εἶ","kjv_def":"art, be","pron":"i","pos":"Verb","thayer":"<ol><li>you are, thou art</li></ol>","xlit":"eî"},"G1907":{"lemma":"ἐπέχω","translit":"epéchō","kjv_def":"give (take) heed unto, hold forth, mark, stay","strongs_def":" to hold upon, i.e. (by implication) to retain; (by extension) to detain; (with implication, of G3563 (νοῦς)) to pay attention to","derivation":"from G1909 (ἐπί) and G2192 (ἔχω);","pron":"ep-ekh'-o","pos":"Verb","thayer":"<ol><li>to have or hold upon, apply, to observe, attend to<ol type='a'><li>to give attention to</li></ol><li>to hold towards, hold forth, present</li><li>to check<ol type='a'><li>delay, stop, stay</li></ol></li></ol>","xlit":"epéchō"},"G1763":{"kjv_def":"year","lemma":"ἐνιαυτός","translit":"eniautós","derivation":"prolongation from a primary (a year);","strongs_def":" a year","pron":"en-ee-ow-tos'","pos":"Noun Masculine","thayer":"<ol><li>a year, in a wider sense, for some fixed definite period of time</li></ol>","xlit":"eniautós"},"G351":{"kjv_def":"examination","translit":"anákrisis","lemma":"ἀνάκρισις","derivation":"from G350 (ἀνακρίνω);","strongs_def":" a (judicial) investigation","pron":"an-ak'-ree-sis","pos":"Noun Feminine","thayer":"<ol><li>an examination</li><li>as a law term among the Greeks, the preliminary investigation held for the purposes of gathering evidences for the information of the judges</li></ol>","xlit":"anákrisis"},"G1357":{"lemma":"διόρθωσις","translit":"diórthōsis","kjv_def":"reformation","strongs_def":" rectification, i.e. (specially) the Messianic restauration","derivation":"from a compound of G1223 (διά) and a derivative of G3717 (ὀρθός), meaning to straighten thoroughly;","pron":"dee-or'-tho-sis","pos":"Noun Feminine","thayer":"<ol><li>in a physical sense, a making straight, restoring to its natural and normal condition something which in some way protrudes or has got out of line, as broken or misshapen limbs</li><li>of acts and institutions, reformation</li></ol>","xlit":"diórthōsis"},"G2130":{"lemma":"εὐμετάδοτος","translit":"eumetádotos","kjv_def":"ready to distribute","strongs_def":" good at imparting, i.e. liberal","derivation":"from G2095 (εὖ) and a presumed derivative of G3330 (μεταδίδωμι);","pron":"yoo-met-ad'-ot-os","pos":"Adjective","thayer":"<ol><li>ready or free to impart</li><li>liberal</li></ol>","xlit":"eumetádotos"},"G602":{"derivation":"from G601 (ἀποκαλύπτω);","strongs_def":" disclosure","kjv_def":"appearing, coming, lighten, manifestation, be revealed, revelation","translit":"apokálypsis","lemma":"ἀποκάλυψις","pron":"ap-ok-al'-oop-sis","pos":"Noun Feminine","thayer":"<ol><li>laying bear, making naked</li><li>a disclosure of truth, instruction<ol type='a'><li>concerning things before unknown</li><li>used of events by which things or states or persons hitherto withdrawn from view are made visible to all</li></ol><li>manifestation, appearance</li></ol>","xlit":"apokálypsis"},"G473":{"kjv_def":"for, in the room of","lemma":"ἀντί","translit":"antí","derivation":"a primary particle;","strongs_def":" opposite, i.e. instead or because of (rarely in addition to)","pron":"an-tee'","pos":"Preposition","thayer":"<ol><li>over against, opposite to, before</li><li>for, instead of, in place of (something)<ol type='a'><li>instead of</li><li>for</li><li>for that, because</li><li>wherefore, for this cause</li></ol></li></ol>","xlit":"antí"},"G3112":{"strongs_def":" at a distance (literally or figuratively)","derivation":"feminine accusative case singular of G3117 (μακρός) (G3598 (ὁδός) being implied);","translit":"makrán","lemma":"μακράν","kjv_def":"(a-)far (off), good (great) way off","pron":"mak-ran'","pos":"Adverb","thayer":"<ol><li>far, a great way</li><li>far hence</li></ol>","xlit":"makrán"},"G120":{"derivation":"from a compound of G1 (Α) (as a negative particle) and G2372 (θυμός);","strongs_def":" to be spiritless, i.e. disheartened","kjv_def":"be dismayed","translit":"athyméō","lemma":"ἀθυμέω","pron":"ath-oo-meh'-o","pos":"Verb","thayer":"<ol><li>to be disheartened, dispirited, broken in spirit</li></ol>","xlit":"athyméō"},"G2483":{"strongs_def":" Italic, i.e. belonging to Italia","derivation":"from G2482 (Ἰταλία);","lemma":"Ἰταλικός","translit":"Italikós","kjv_def":"Italian","pron":"ee-tal-ee-kos'","pos":"Adjective","thayer":"<ol><li>Italian</li></ol>","xlit":"Italikós"},"G4085":{"derivation":"another form for G4084 (πιάζω);","strongs_def":" to pack","kjv_def":"press down","translit":"piézō","lemma":"πιέζω","pron":"pee-ed'-zo","pos":"Verb","thayer":"<ol><li>to press, press together</li></ol>","xlit":"piézō"},"G3400":{"lemma":"μίλιον","translit":"mílion","kjv_def":"mile","strongs_def":" a thousand paces, i.e. a \"mile\"","derivation":"of Latin origin;","pron":"mil'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a mile, among the Romans the distance of a thousand paces or eight stadia, about 1.5 km [somewhat less than our mile]</li></ol>","xlit":"mílion"},"G794":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of (to cherish affectionately);","strongs_def":" hard-hearted towards kindred","kjv_def":"without natural affection","translit":"ástorgos","lemma":"ἄστοργος","pron":"as'-tor-gos","pos":"Adjective","thayer":"<ol><li>without natural affection, unsociable (<a class='bible' href='#b45.1.31'>Rom 1:31</a> marg.), inhuman (<a class='bible' href='#b55.3.3 8'>2Ti 3:3 8</a> RSV), unloving (<a class='bible' href='#b55.3.3 4'>2Ti 3:3 4</a> NKJV)</li></ol>","xlit":"ástorgos"},"G2249":{"kjv_def":"us, we (ourselves)","lemma":"ἡμεῖς","translit":"hēmeîs","derivation":"nominative plural of G1473 (ἐγώ);","strongs_def":" we (only used when emphatic)","pron":"hay-mice'","thayer":"<ol><li>us, we etc.</li></ol>","xlit":"hēmeîs"},"G1909":{"strongs_def":" properly, meaning superimposition (of time, place, order, etc.), as a relation of distribution (with the genitive case), i.e. over, upon, etc.; of rest (with the dative case) at, on, etc.; of direction (with the accusative case) towards, upon, etc.","derivation":"a primary preposition;","lemma":"ἐπί","translit":"epí","kjv_def":"about (the times), above, after, against, among, as long as (touching), at, beside, X have charge of, (be-, (where-))fore, in (a place, as much as, the time of, -to), (because) of, (up-)on (behalf of), over, (by, for) the space of, through(-out), (un-)to(-ward), with","pron":"ep-ee'","pos":"Preposition","thayer":"<ol><li>upon, on, at, by, before</li><li>of position, on, at, by, over, against</li><li>to, over, on, at, across, against</li></ol>","xlit":"epí"},"G1685":{"translit":"embállō","lemma":"ἐμβάλλω","kjv_def":"cast into","strongs_def":" to throw on, i.e. (figuratively) subject to (eternal punishment)","derivation":"from G1722 (ἐν) and G906 (βάλλω);","pron":"em-bal'-lo","pos":"Verb","thayer":"<ol><li>to throw in, cast into</li></ol>","xlit":"embállō"},"G5084":{"translit":"tḗrēsis","lemma":"τήρησις","kjv_def":"hold","strongs_def":" a watching, i.e. (figuratively) observance, or (concretely) a prison","derivation":"from G5083 (τηρέω);","pron":"tay'-ray-sis","pos":"Noun Feminine","thayer":"<ol><li>a watching<ol type='a'><li>of prisoners</li><li>a place where prisoners are kept, a prison</li></ol><li>a keeping<ol type='a'><li>complying with, obeying</li></ol></li></ol>","xlit":"tḗrēsis"},"G2460":{"translit":"hippeús","lemma":"ἱππεύς","kjv_def":"horseman","strongs_def":" an equestrian, i.e. member of a cavalry corps","derivation":"from G2462 (ἵππος);","pron":"hip-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a horseman</li></ol>","xlit":"hippeús"},"G3972":{"derivation":"of Latin origin;","strongs_def":" (little; but remotely from a derivative of G3973 (παύω), meaning the same); Paulus, the name of a Roman and of an apostle","kjv_def":"Paul, Paulus","translit":"Paûlos","lemma":"Παῦλος","pron":"pow'-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Paul or Paulus = \"small or little\"</p><ol><li>Paul was the most famous of the apostles and wrote a good part of the NT, the 14 Pauline epistles</li><li>Paulus was a deputy or pro-consul of Cyprus and is said to be a prudent man, in the management of affairs, as a governor</li></ol>","xlit":"Paûlos"},"G27":{"translit":"agapētós","lemma":"ἀγαπητός","kjv_def":"(dearly, well) beloved, dear","strongs_def":" beloved","derivation":"from G25 (ἀγαπάω);","pron":"ag-ap-ay-tos'","pos":"Adjective","thayer":"<ol><li>beloved, esteemed, dear, favourite, worthy of love</li></ol>","xlit":"agapētós"},"G2099":{"kjv_def":"evangelist","lemma":"εὐαγγελιστής","translit":"euangelistḗs","derivation":"from G2097 (εὐαγγελίζω);","strongs_def":" a preacher of the gospel","pron":"yoo-ang-ghel-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>a bringer of good tidings, an evangelist</li><li>the name given to the NT heralds of salvation through Christ who are not apostles</li></ol>","xlit":"euangelistḗs"},"G2039":{"strongs_def":" occupation; by implication, profit, pains","derivation":"from G2040 (ἐργάτης);","translit":"ergasía","lemma":"ἐργασία","kjv_def":"craft, diligence, gain, work","pron":"er-gas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a working, performing</li><li>work, business</li><li>gain got by work, profit</li><li>endeavour, pains</li></ol>","xlit":"ergasía"},"G4576":{"strongs_def":" to revere, i.e. adore","derivation":"middle voice of an apparently primary verb;","translit":"sébomai","lemma":"σέβομαι","kjv_def":"devout, religious, worship","pron":"seb'-om-ahee","pos":"Verb","thayer":"<ol><li>to revere, to worship</li></ol>","xlit":"sébomai"},"G488":{"lemma":"ἀντιμετρέω","translit":"antimetréō","kjv_def":"measure again","strongs_def":" to mete in return","derivation":"from G473 (ἀντί) and G3354 (μετρέω);","pron":"an-tee-met-reh'-o","pos":"Verb","thayer":"<ol><li>to measure back, to measure in return, repay</li></ol>","xlit":"antimetréō"},"G2396":{"kjv_def":"behold, lo, see","translit":"íde","lemma":"ἴδε","derivation":"second person singular imperative active of G1492 (εἴδω);","strongs_def":" used as an interjection to denote surprise; lo!","pron":"id'-eh","thayer":"<ol><li>behold, see</li></ol>","xlit":"íde"},"G518":{"derivation":"from G575 (ἀπό) and the base of G32 (ἄγγελος);","strongs_def":" to announce","kjv_def":"bring word (again), declare, report, shew (again), tell","translit":"apangéllō","lemma":"ἀπαγγέλλω","pron":"ap-ang-el'-lo","pos":"Verb","thayer":"<ol><li>to bring tidings (from a person or a thing), bring word, report</li><li>to proclaim, to make known openly, declare</li></ol>","xlit":"apangéllō"},"G3618":{"kjv_def":"(be in) build(-er, -ing, up), edify, embolden","lemma":"οἰκοδομέω","translit":"oikodoméō","derivation":"from the same as G3619 (οἰκοδομή);","strongs_def":" to be a house-builder, i.e. construct or (figuratively) confirm","pron":"oy-kod-om-eh'-o","pos":"Verb","thayer":"<ol><li>to build a house, erect a building<ol type='a'><li>to build (up from the foundation)</li><li>to restore by building, to rebuild, repair</li></ol><li>metaphorically<ol type='a'><li>to found, establish</li><li>to promote growth in Christian wisdom, affection, grace, virtue, holiness, blessedness</li><li>to grow in wisdom and piety</li></ol></li></ol>","xlit":"oikodoméō"},"G708":{"lemma":"Ἀρίσταρχος","translit":"Arístarchos","kjv_def":"Aristarchus","strongs_def":" best ruling; Aristarchus, a Macedonian","derivation":"from the same as G712 (ἄριστον) and G757 (ἄρχω);","pron":"ar-is'-tar-khos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aristarchus = \"the best ruler\"</p><ol><li>a certain Christian of Thessalonica, and accompanied Paul on his third missionary journey</li></ol>","xlit":"Arístarchos"},"G4716":{"kjv_def":"cross","lemma":"σταυρός","translit":"staurós","derivation":"from the base of G2476 (ἵστημι);","strongs_def":" a stake or post (as set upright), i.e. (specially), a pole or cross (as an instrument of capital punishment); figuratively, exposure to death, i.e. self-denial; by implication, the atonement of Christ","pron":"stow-ros'","pos":"Noun Masculine","thayer":"<ol><li>an upright stake, especially a pointed one</li><li>a cross<ol type='a'><li>a well known instrument of most cruel and ignominious punishment, borrowed by the Greeks and Romans from the Phoenicians; to it were affixed among the Romans, down to the time of Constantine the Great, the guiltiest criminals, particularly the basest slaves, robbers, the authors and abetters of insurrections, and occasionally in the provinces, at the arbitrary pleasure of the governors, upright and peaceable men also, and even Roman citizens themselves</li><li>the crucifixion which Christ underwent</li></ol></li></ol>","xlit":"staurós"},"G2995":{"kjv_def":"throat","lemma":"λάρυγξ","translit":"lárynx","derivation":"of uncertain derivation;","strongs_def":" the throat (\"larynx\")","pron":"lar'-oongks","pos":"Noun Masculine","thayer":"<ol><li>the throat<ol type='a'><li>of the instrument or organ of speech</li></ol></li></ol>","xlit":"lárynx"},"G2459":{"translit":"Ioûstos","lemma":"Ἰοῦστος","kjv_def":"Justus","strongs_def":" Justus, the name of three Christian","derivation":"of Latin origin (\"just\");","pron":"ee-ooce'-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Justus = \"just\"</p><ol><li>a surname of Joseph, called Barsabas. <a class='bible' href='#b44.1.23'>Act 1:23</a></li><li>of Titus, a Christian at Corinth, with whom Paul lodged. <a class='bible' href='#b44.18.7'>Act 18:7</a></li><li>a surname of Jesus, a friend of Paul. <a class='bible' href='#b51.4.11'>Col 4:11</a></li></ol>","xlit":"Ioûstos"},"G5621":{"strongs_def":" an earlet, i.e. one of the ears, or perhaps the lobe of the ear","derivation":"diminutive of G3775 (οὖς);","translit":"ōtíon","lemma":"ὠτίον","kjv_def":"ear","pron":"o-tee'-on","pos":"Noun Neuter","thayer":"<ol><li>the ear</li></ol>","xlit":"ōtíon"},"G4679":{"derivation":"from G4680 (σοφός);","strongs_def":" to render wise; in a sinister acceptation, to form \"sophisms\", i.e. continue plausible error","kjv_def":"cunningly devised, make wise","translit":"sophízō","lemma":"σοφίζω","pron":"sof-id'-zo","pos":"Verb","thayer":"<ol><li>to make wise, teach</li><li>to become wise, to have understanding<ol type='a'><li>to invent, play the sophist</li><li>to devise cleverly or cunningly</li></ol></li></ol>","xlit":"sophízō"},"G2176":{"strongs_def":" properly, well-named (good-omened), i.e. the left (which was the lucky side among the pagan Greeks); neuter as adverbial, at the left hand","derivation":"from G2095 (εὖ) and G3686 (ὄνομα);","translit":"euṓnymos","lemma":"εὐώνυμος","kjv_def":"(on the) left","pron":"yoo-o'-noo-mos","pos":"Adjective","thayer":"<ol><li>of good name and of good omen<ol type='a'><li>in the latter sense used in taking auguries; but those omens were euphemistically called \"euonumos\" which in fact were regarded as unlucky, i.e. which came from the left, sinister omens, (for which a good name was desired)</li></ol><li>left, on the left hand</li></ol>","xlit":"euṓnymos"},"G2790":{"derivation":"from G2788 (κιθάρα) and a derivative of the same as G5603 (ᾠδή);","strongs_def":" a lyre-singer(-player), i.e. harpist","kjv_def":"harper","lemma":"κιθαρῳδός","translit":"kitharōidós","pron":"kith-ar-o'-dos","pos":"Noun Masculine","thayer":"<ol><li>a harper, one who plays the harp and accompanies it with his voice</li></ol>","xlit":"kitharōidós"},"G4426":{"lemma":"πτύρω","translit":"ptýrō","kjv_def":"terrify","strongs_def":" to frighten","derivation":"from a presumed derivative of G4429 (πτύω) (and thus akin to G4422 (πτοέω));","pron":"ptoo'-ro","pos":"Verb","thayer":"<ol><li>to frighten, affright</li></ol>","xlit":"ptýrō"},"G2772":{"strongs_def":" a clipping (bit), i.e. (specially) a coin","derivation":"from G2751 (κείρω);","lemma":"κέρμα","translit":"kérma","kjv_def":"money","pron":"ker'-mah","pos":"Noun Neuter","thayer":"<ol><li>small pieces of money, small coin, change, money</li></ol>","xlit":"kérma"},"G5038":{"lemma":"τεῖχος","translit":"teîchos","kjv_def":"wall","strongs_def":" a wall (as formative of a house)","derivation":"akin to the base of G5088 (τίκτω);","pron":"ti'-khos","pos":"Noun Neuter","thayer":"<ol><li>the wall around a city, town wall</li></ol>","xlit":"teîchos"},"G5486":{"kjv_def":"(free) gift","lemma":"χάρισμα","translit":"chárisma","derivation":"from G5483 (χαρίζομαι);","strongs_def":" a (divine) gratuity, i.e. deliverance (from danger or passion); (specially), a (spiritual) endowment, i.e. (subjectively) religious qualification, or (objectively) miraculous faculty","pron":"khar'-is-mah","pos":"Noun Neuter","thayer":"<ol><li>a favour with which one receives without any merit of his own</li><li>the gift of divine grace</li><li>the gift of faith, knowledge, holiness, virtue</li><li>the economy of divine grace, by which the pardon of sin and eternal salvation is appointed to sinners in consideration of the merits of Christ laid hold of by faith</li><li>grace or gifts denoting extraordinary powers, distinguishing certain Christians and enabling them to serve the church of Christ, the reception of which is due to the power of divine grace operating on their souls by the Holy Spirit</li></ol>","xlit":"chárisma"},"G5053":{"derivation":"from a presumed derivative of G5055 (τελέω);","strongs_def":" to finish life (by implication, of G979 (βίος)), i.e. expire (demise)","kjv_def":"be dead, decease, die","translit":"teleutáō","lemma":"τελευτάω","pron":"tel-yoo-tah'-o","pos":"Verb","thayer":"<ol><li>to finish, bring to and end, close</li><li>to have an end or close, come to an end</li></ol>","xlit":"teleutáō"},"G3547":{"derivation":"from G3551 (νόμος) and G1320 (διδάσκαλος);","strongs_def":" an expounder of the (Jewish) law, i.e. a Rabbi","kjv_def":"doctor (teacher) of the law","lemma":"νομοδιδάσκαλος","translit":"nomodidáskalos","pron":"nom-od-id-as'-kal-os","pos":"Noun Masculine","thayer":"<ol><li>a teacher and interpreter of the law: among the Jews<ol type='a'><li>of those who among Christians went about as champions and interpreters of the Mosaic law</li></ol></li></ol>","xlit":"nomodidáskalos"},"G2472":{"kjv_def":"like precious","lemma":"ἰσότιμος","translit":"isótimos","derivation":"from G2470 (ἴσος) and G5092 (τιμή);","strongs_def":" of equal value or honor","pron":"ee-sot'-ee-mos","pos":"Adjective","thayer":"<ol><li>equally precious</li><li>equally honoured, to be esteemed equal to</li></ol>","xlit":"isótimos"},"G4161":{"strongs_def":" a product, i.e. fabric (literally or figuratively)","derivation":"from G4160 (ποιέω);","translit":"poíēma","lemma":"ποίημα","kjv_def":"thing that is made, workmanship","pron":"poy'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been made</li><li>a work<ol type='a'><li>of the works of God as creator</li></ol></li></ol>","xlit":"poíēma"},"G2801":{"strongs_def":" a piece (bit)","derivation":"from G2806 (κλάω);","lemma":"κλάσμα","translit":"klásma","kjv_def":"broken, fragment","pron":"klas'-mah","pos":"Noun Neuter","thayer":"<ol><li>a fragment, broken piece<ol type='a'><li>remnants of food</li></ol></li></ol>","xlit":"klásma"},"G5433":{"derivation":"akin to G1032 (βρύω), G1031 (βρύχω);","strongs_def":" to snort (as a spirited horse), i.e. (figuratively) to make a tumult","kjv_def":"rage","lemma":"φρυάσσω","translit":"phryássō","pron":"froo-as'-so","pos":"Verb","thayer":"<ol><li>to neigh, stamp the ground, prance, snort</li><li>to be high-spirited<ol type='a'><li>of horses</li><li>of men<ol><li>to take on lofty airs</li><li>behave arrogantly</li></ol><li>to be tumultuous, to rage</li></ol></li></ol>","xlit":"phryássō"},"G4873":{"derivation":"from G4862 (σύν) and G345 (ἀνακεῖμαι);","strongs_def":" to recline in company with (at a meal)","kjv_def":"sit (down, at the table, together) with (at meat)","lemma":"συνανάκειμαι","translit":"synanákeimai","pron":"soon-an-ak'-i-mahee","pos":"Verb","thayer":"<ol><li>to recline together, feast together<ol type='a'><li>of guests</li></ol></li></ol>","xlit":"synanákeimai"},"G1227":{"kjv_def":"see clearly","translit":"diablépō","lemma":"διαβλέπω","derivation":"from G1223 (διά) and G991 (βλέπω);","strongs_def":" to look through, i.e. recover full vision","pron":"dee-ab-lep'-o","pos":"Verb","thayer":"<ol><li>to look through, penetrate by vision<ol type='a'><li>to look fixedly, stare straight before one</li><li>to see clearly</li></ol></li></ol>","xlit":"diablépō"},"G1011":{"lemma":"βουλεύω","translit":"bouleúō","kjv_def":"consult, take counsel, determine, be minded, purpose","strongs_def":" to advise, i.e. (reflexively) deliberate, or (by implication) resolve","derivation":"from G1012 (βουλή);","pron":"bool-yoo'-o","pos":"Verb","thayer":"<ol><li>to deliberate with one's self, consider</li><li>to take counsel, resolve</li></ol>","xlit":"bouleúō"},"G3702":{"lemma":"ὀπτός","translit":"optós","kjv_def":"broiled","strongs_def":" cooked, i.e. roasted","derivation":"from an obsolete verb akin to (to \"steep\");","pron":"op-tos'","pos":"Adjective","thayer":"<ol><li>cooked, broiled</li></ol>","xlit":"optós"},"G4957":{"kjv_def":"crucify with","translit":"systauróō","lemma":"συσταυρόω","derivation":"from G4862 (σύν) and G4717 (σταυρόω);","strongs_def":" to impale in company with (literally or figuratively)","pron":"soos-tow-ro'-o","pos":"Verb","thayer":"<ol><li>to crucify alone with</li></ol>","xlit":"systauróō"},"G5194":{"derivation":"perhaps from the same as G5205 (ὑετός) (as being transparent like rain);","strongs_def":" glass","kjv_def":"glass","lemma":"ὕαλος","translit":"hýalos","pron":"hoo'-al-os","pos":"Noun Masculine","thayer":"<ol><li>any stone transparent like glass</li><li>glass</li></ol>","xlit":"hýalos"},"G562":{"kjv_def":"endless","lemma":"ἀπέραντος","translit":"apérantos","derivation":"from G1 (Α) (as a negative particle) and a secondary derivative of G4008 (πέραν);","strongs_def":" unfinished, i.e. (by implication) interminable","pron":"ap-er'-an-tos","pos":"Adjective","thayer":"<ol><li>that can not be passed through, boundless, endless</li></ol>","xlit":"apérantos"},"G2056":{"kjv_def":"goat, kid","translit":"ériphos","lemma":"ἔριφος","derivation":"perhaps from the same as G2053 (ἔριον) (through the idea of hairiness);","strongs_def":" a kid or (genitive case) goat","pron":"er'-if-os","pos":"Noun Masculine","thayer":"<ol><li>a kid, a young goat</li></ol>","xlit":"ériphos"},"G781":{"derivation":"from G1 (Α) (as a negative particle) and G4680 (σοφός);","strongs_def":" unwise","kjv_def":"fool","lemma":"ἄσοφος","translit":"ásophos","pron":"as'-of-os","pos":"Adjective","thayer":"<ol><li>unwise, foolish</li></ol>","xlit":"ásophos"},"G793":{"strongs_def":" unfixed, i.e. (figuratively) vacillating","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G4741 (στηρίζω);","lemma":"ἀστήρικτος","translit":"astḗriktos","kjv_def":"unstable","pron":"as-tay'-rik-tos","pos":"Adjective","thayer":"<ol><li>unstable, unsteadfast</li></ol>","xlit":"astḗriktos"},"G5211":{"kjv_def":"Hymenæus","lemma":"Ὑμεναῖος","translit":"Hymenaîos","derivation":"from (the god of weddings);","strongs_def":" \"hymenæal\"; Hymenæus, an opponent of Christianity","pron":"hoo-men-ah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Hymenaeus = \"belonging to marriage\"</p><ol><li>a heretic, one of the opponents of the apostle Paul</li></ol>","xlit":"Hymenaîos"},"G560":{"strongs_def":" to hope out, i.e. fully expect","derivation":"from G575 (ἀπό) and G1679 (ἐλπίζω);","lemma":"ἀπελπίζω","translit":"apelpízō","kjv_def":"hope for again","pron":"ap-el-pid'-zo","pos":"Verb","thayer":"<ol><li>nothing despairing</li><li>despairing of no one</li><li>causing no one to despair</li></ol>","xlit":"apelpízō"},"G502":{"strongs_def":" a baling-vessel","derivation":"from G501 (ἀντλέω);","lemma":"ἄντλημα","translit":"ántlēma","kjv_def":"thing to draw with","pron":"ant'-lay-mah","pos":"Noun Neuter","thayer":"<ol><li>what is drawn</li><li>the act of drawing water</li><li>a thing to draw with, e.g. bucket and rope let down into a well</li></ol>","xlit":"ántlēma"},"G913":{"derivation":"of Hebrew origin (H01301);","strongs_def":" Barak, an Israelite","kjv_def":"Barak","lemma":"Βαράκ","translit":"Barák","pron":"bar-ak'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barak = \"lightning\"</p><ol><li>a commander of the Israelites</li></ol>","xlit":"Barák"},"G2401":{"derivation":"of Hebrew origin (H0123);","strongs_def":" Idumæa (i.e. Edom), a region East (and South) of Palestine","kjv_def":"Idumæa","translit":"Idoumaía","lemma":"Ἰδουμαία","pron":"id-oo-mah'-yah","pos":"Noun Location","thayer":"<ol><li>Idumaea, the name of a region between southern Palestine and the Arabian Petraea inhabited by Edom or Esau and his posterity</li></ol>","xlit":"Idoumaía"},"G1963":{"strongs_def":" attention of the mind, i.e. (by implication) purpose","derivation":"from G1909 (ἐπί) and G3563 (νοῦς);","translit":"epínoia","lemma":"ἐπίνοια","kjv_def":"thought","pron":"ep-in'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>thought, purpose</li></ol>","xlit":"epínoia"},"G4022":{"derivation":"from G4012 (περί) and G2064 (ἔρχομαι) (including its alternate);","strongs_def":" to come all around, i.e. stroll, vacillate, veer","kjv_def":"fetch a compass, vagabond, wandering about","lemma":"περιέρχομαι","translit":"periérchomai","pron":"per-ee-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go about<ol type='a'><li>of strollers</li><li>of wanderers</li><li>of navigators (making a circuit)</li></ol></li></ol>","xlit":"periérchomai"},"G2835":{"strongs_def":" a quadrans, i.e. the fourth part of an as","derivation":"of Latin origin;","lemma":"κοδράντης","translit":"kodrántēs","kjv_def":"farthing","pron":"kod-ran'-tace","pos":"Noun Masculine","thayer":"<ol><li>a quadrans (about the fourth part of an \"as\" ); in the NT a coin equal to one half the Attic chalcus worth about 3/8 of a cent</li></ol>","xlit":"kodrántēs"},"G2091":{"strongs_def":" preparation","derivation":"from G2090 (ἑτοιμάζω);","translit":"hetoimasía","lemma":"ἑτοιμασία","kjv_def":"preparation","pron":"het-oy-mas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the act of preparing</li><li>the condition of a person or thing so far forth as prepared, preparedness, readiness</li></ol>","xlit":"hetoimasía"},"G4442":{"derivation":"a primary word;","strongs_def":" \"fire\" (literally or figuratively, specially, lightning)","kjv_def":"fiery, fire","lemma":"πῦρ","translit":"pŷr","pron":"poor","pos":"Noun Neuter","thayer":"<ol><li>fire</li></ol>","xlit":"pŷr"},"G1463":{"translit":"enkombóomai","lemma":"ἐγκομβόομαι","kjv_def":"be clothed with","strongs_def":" to engirdle oneself (for labor), i.e. figuratively (the apron as being a badge of servitude) to wear (in token of mutual deference)","derivation":"middle voice from G1722 (ἐν) and (to gird);","pron":"eng-kom-bo'-om-ahee","pos":"Verb","thayer":"<ol><li>knot or band by which two things are fastened together, to fasten or gird one's self</li></ol>","xlit":"enkombóomai"},"G1700":{"kjv_def":"me, mine, my","lemma":"ἐμοῦ","translit":"emoû","derivation":"a prolonged form of G3449 (μόχθος);","strongs_def":" of me","pron":"em-oo'","thayer":"<ol><li>me, my, mine, etc.</li></ol>","xlit":"emoû"},"G4817":{"derivation":"from G4862 (σύν) and G3049 (λογίζομαι);","strongs_def":" to reckon together (with oneself), i.e. deliberate","kjv_def":"reason with","lemma":"συλλογίζομαι","translit":"syllogízomai","pron":"sool-log-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to bring together accounts, reckon up, compute</li><li>to reckon with one's self, to reason</li></ol>","xlit":"syllogízomai"},"G5012":{"derivation":"from a compound of G5011 (ταπεινός) and the base of G5424 (φρήν);","strongs_def":" humiliation of mind, i.e. modesty","kjv_def":"humbleness of mind, humility (of mind, loneliness (of mind)","lemma":"ταπεινοφροσύνη","translit":"tapeinophrosýnē","pron":"tap-i-nof-ros-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>the having a humble opinion of one's self</li><li>a deep sense of one's (moral) littleness</li><li>modesty, humility, lowliness of mind</li></ol>","xlit":"tapeinophrosýnē"},"G1591":{"translit":"ekmássō","lemma":"ἐκμάσσω","kjv_def":"wipe","strongs_def":" to knead out, i.e. (by analogy) to wipe dry","derivation":"from G1537 (ἐκ) and the base of G3145 (μασσάομαι);","pron":"ek-mas'-so","pos":"Verb","thayer":"<ol><li>to wipe off, to wipe away</li></ol>","xlit":"ekmássō"},"G1029":{"derivation":"of uncertain derivation;","strongs_def":" a noose","kjv_def":"snare","translit":"bróchos","lemma":"βρόχος","pron":"brokh'-os","pos":"Noun Masculine","thayer":"<ol><li>a noose, slip-knot, by which any person or thing is caught, or fastened, or suspended</li><li>to throw a noose upon one, a figure borrowed from war or the chase so that by craft or by force one is bound to some necessity, to constrain him to obey some command</li></ol>","xlit":"bróchos"},"G4064":{"translit":"periphérō","lemma":"περιφέρω","kjv_def":"bear (carry) about","strongs_def":" to convey around, i.e. transport hither and thither","derivation":"from G4012 (περί) and G5342 (φέρω);","pron":"per-ee-fer'-o","pos":"Verb","thayer":"<ol><li>to carry round, to bear about everywhere with one</li><li>to carry here and there</li><li>to be driven<ol type='a'><li>in doubt and hesitation to be led away now to this opinion, now to that</li></ol></li></ol>","xlit":"periphérō"},"G808":{"strongs_def":" an indecency; by implication, the pudenda","derivation":"from G809 (ἀσχήμων);","lemma":"ἀσχημοσύνη","translit":"aschēmosýnē","kjv_def":"shame, that which is unseemly","pron":"as-kay-mos-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>unseemliness, an unseemly deed<ol type='a'><li>of a woman's genitals</li><li>of one's nakedness, shame</li></ol></li></ol>","xlit":"aschēmosýnē"},"G1927":{"lemma":"ἐπιδημέω","translit":"epidēméō","kjv_def":"(be) dwelling (which were) there, stranger","strongs_def":" to make oneself at home, i.e. (by extension) to reside (in a foreign country)","derivation":"from a compound of G1909 (ἐπί) and G1218 (δῆμος);","pron":"ep-ee-day-meh'-o","pos":"Verb","thayer":"<ol><li>to be present among one's people, in one's city or one's native land</li><li>to be a sojourner<ol type='a'><li>of a foreign resident, among any people, in any country</li></ol></li></ol>","xlit":"epidēméō"},"G1893":{"kjv_def":"because, else, for that (then, -asmuch as), otherwise, seeing that, since, when","lemma":"ἐπεί","translit":"epeí","derivation":"from G1909 (ἐπί) and G1487 (εἰ);","strongs_def":" thereupon, i.e. since (of time or cause)","pron":"ep-i'","pos":"Conjunction","thayer":"<ol><li>when, since<ol type='a'><li>of time: after</li><li>of cause: since, seeing that, because</li></ol></li></ol>","xlit":"epeí"},"G5303":{"derivation":"from G5302 (ὑστερέω);","strongs_def":" a deficit; specially, poverty","kjv_def":"that which is behind, (that which was) lack(-ing), penury, want","lemma":"ὑστέρημα","translit":"hystérēma","pron":"hoos-ter'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>deficiency, that which is lacking</li><li>in reference to property and resources, poverty, want, destitution</li></ol>","xlit":"hystérēma"},"G5071":{"strongs_def":" four hundred","derivation":"plural from G5064 (τέσσαρες) and G1540 (ἑκατόν);","lemma":"τετρακόσιοι","translit":"tetrakósioi","kjv_def":"four hundred","pron":"tet-rak-os'-ee-oy","pos":"Adjective","thayer":"<ol><li>four hundred</li></ol>","xlit":"tetrakósioi"},"G3714":{"lemma":"ὀρεινός","translit":"oreinós","kjv_def":"hill country","strongs_def":" mountainous, i.e. (feminine by implication, of G5561 (χώρα)) the Highlands (of Judæa)","derivation":"from G3735 (ὄρος);","pron":"or-i-nos","pos":"Adjective","thayer":"<ol><li>mountainous, hilly</li><li>the mountain district, hill country</li></ol>","xlit":"oreinós"},"G1538":{"kjv_def":"any, both, each (one), every (man, one, woman), particularly","lemma":"ἕκαστος","translit":"hékastos","derivation":"as if a superlative of (afar);","strongs_def":" each or every","pron":"hek'-as-tos","pos":"Adjective","thayer":"<ol><li>each, every</li></ol>","xlit":"hékastos"},"G1028":{"lemma":"βροχή","translit":"brochḗ","kjv_def":"rain","strongs_def":" rain","derivation":"from G1026 (βρέχω);","pron":"brokh-ay'","pos":"Noun Feminine","thayer":"<ol><li>a besprinkling, watering, rain<ol type='a'><li>used of a heavy shower or violent rainstorm</li></ol></li></ol>","xlit":"brochḗ"},"G3831":{"lemma":"πανήγυρις","translit":"panḗgyris","kjv_def":"general assembly","strongs_def":" a mass-meeting, i.e. (figuratively) universal companionship","derivation":"from G3956 (πᾶς) and a derivative of G58 (ἀγορά);","pron":"pan-ay'-goo-ris","pos":"Noun Feminine","thayer":"<ol><li>a festal gathering of the whole people to celebrate public games or other solemnities</li><li>a public festal assembly</li></ol>","xlit":"panḗgyris"},"G3329":{"kjv_def":"turn about","translit":"metágō","lemma":"μετάγω","derivation":"from G3326 (μετά) and G718 (ἁρμόζω);","strongs_def":" to lead over, i.e. transfer (direct)","pron":"met-ag'-o","pos":"Verb","thayer":"<ol><li>to transfer, lead over</li><li>to direct</li></ol>","xlit":"metágō"},"G78":{"kjv_def":"Addi","lemma":"Ἀδδί","translit":"Addí","derivation":"probably of Hebrew origin (compare H05716);","strongs_def":" Addi, an Israelite","pron":"ad-dee'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Addi = \"ornament\"</p><ol><li>son of Cosam, and father of Melchi in our Lord's genealogy</li></ol>","xlit":"Addí"},"G1843":{"kjv_def":"confess, profess, promise","lemma":"ἐξομολογέω","translit":"exomologéō","derivation":"from G1537 (ἐκ) and G3670 (ὁμολογέω);","strongs_def":" to acknowledge or (by implication, of assent) agree fully","pron":"ex-om-ol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to confess</li><li>to profess<ol type='a'><li>acknowledge openly and joyfully</li><li>to one's honour: to celebrate, give praise to</li><li>to profess that one will do something, to promise, agree, engage</li></ol></li></ol>","xlit":"exomologéō"},"G4662":{"derivation":"from G4663 (σκώληξ) and a derivative of G977 (βιβρώσκω);","strongs_def":" worm-eaten, i.e. diseased with maggots","kjv_def":"eaten of worms","lemma":"σκωληκόβρωτος","translit":"skōlēkóbrōtos","pron":"sko-lay-kob'-ro-tos","pos":"Adjective","thayer":"<ol><li>eaten of worms</li></ol>","xlit":"skōlēkóbrōtos"},"G1617":{"strongs_def":" more intently","derivation":"neuter of the comparative of G1618 (ἐκτενής);","lemma":"ἐκτενέστερον","translit":"ektenésteron","kjv_def":"more earnestly","pron":"ek-ten-es'-ter-on","pos":"Adjective","thayer":"<ol><li>more intently, more earnestly</li></ol>","xlit":"ektenésteron"},"G1100":{"derivation":"of uncertain affinity;","strongs_def":" the tongue; by implication, a language (specially, one naturally unacquired)","kjv_def":"tongue","lemma":"γλῶσσα","translit":"glōssa","pron":"gloce-sah'","pos":"Noun Feminine","thayer":"<ol><li>the tongue, a member of the body, an organ of speech</li><li>a tongue<ol type='a'><li>the language or dialect used by a particular people distinct from that of other nations</li></ol></li></ol>","xlit":"glōssa"},"G530":{"derivation":"probably from G537 (ἅπας);","strongs_def":" one (or a single) time (numerically or conclusively)","kjv_def":"once","lemma":"ἅπαξ","translit":"hápax","pron":"hap'-ax","pos":"Adverb","thayer":"<ol><li>once, one time</li><li>once for all</li></ol>","xlit":"hápax"},"G2033":{"kjv_def":"seven","translit":"heptá","lemma":"ἑπτά","derivation":"a primary number;","strongs_def":" seven","pron":"hep-tah'","pos":"Noun","thayer":"<ol><li>seven</li></ol>","xlit":"heptá"},"G286":{"lemma":"ἀμνός","translit":"amnós","kjv_def":"lamb","strongs_def":" a lamb","derivation":"apparently a primary word;","pron":"am-nos'","pos":"Noun Masculine","thayer":"<ol><li>a lamb</li></ol>","xlit":"amnós"},"G672":{"derivation":"from G575 (ἀπό) and G5562 (χωρέω);","strongs_def":" to go away","kjv_def":"depart","translit":"apochōréō","lemma":"ἀποχωρέω","pron":"ap-okh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to go away, depart</li></ol>","xlit":"apochōréō"},"G5307":{"derivation":"from to weave;","strongs_def":" woven, i.e. (perhaps) knitted","kjv_def":"woven","lemma":"ὑφαντός","translit":"hyphantós","pron":"hoo-fan-tos'","pos":"Adjective","thayer":"<ol><li>woven</li></ol>","xlit":"hyphantós"},"G5584":{"translit":"psēlapháō","lemma":"ψηλαφάω","kjv_def":"feel after, handle, touch","strongs_def":" to manipulate, i.e. verify by contact; figuratively, to search for","derivation":"from the base of G5567 (ψάλλω) (compare G5586 (ψῆφος));","pron":"psay-laf-ah'-o","pos":"Verb","thayer":"<ol><li>to handle, touch and feel</li><li>metaphorically mentally to seek after tokens of a person or a thing</li></ol>","xlit":"psēlapháō"},"G1897":{"derivation":"from G1893 (ἐπεί) and G4007 (περ);","strongs_def":" since indeed (of cause)","kjv_def":"seeing","translit":"epeíper","lemma":"ἐπείπερ","pron":"ep-i'-per","pos":"Conjunction","thayer":"<ol><li>since indeed, since at all events</li></ol>","xlit":"epeíper"},"G5528":{"strongs_def":" a \"court\" or \"garden\", i.e. (by implication, of pasture) herbage or vegetation","derivation":"apparently a primary word;","lemma":"χόρτος","translit":"chórtos","kjv_def":"blade, grass, hay","pron":"khor'-tos","pos":"Noun Masculine","thayer":"<ol><li>the place where grass grows and animals graze</li><li>grass, herbage, hay, provender<ol type='a'><li>of green grass</li><li>of growing crops</li></ol></li></ol>","xlit":"chórtos"},"G5457":{"derivation":"from an obsolete (to shine or make manifest, especially by rays;","strongs_def":" compare G5316 (φαίνω), G5346 (φημί)); luminousness (in the widest application, natural or artificial, abstract or concrete, literal or figurative)","kjv_def":"fire, light","lemma":"φῶς","translit":"phōs","pron":"foce","pos":"Noun Neuter","thayer":"<ol><li>light<ol type='a'><li>the light<ol><li>emitted by a lamp</li><li>a heavenly light such as surrounds angels when they appear on earth</li></ol><li>anything emitting light<ol><li>a star</li><li>fire because it is light and sheds light</li><li>a lamp or torch</li></ol><li>light, i.e brightness<ol><li>of a lamp</li></ol></li></ol><li>metaphorically<ol type='a'><li>God is light because light has the extremely delicate, subtle, pure, brilliant quality</li><li>of truth and its knowledge, together with the spiritual purity associated with it</li><li>that which is exposed to the view of all, openly, publicly</li><li>reason, mind<ol><li>the power of understanding especially moral and spiritual truth</li></ol></li></ol></li></ol>","xlit":"phōs"},"G4068":{"derivation":"middle voice from (braggart;","strongs_def":" perhaps by reduplication of the base of G4008 (πέραν)); to boast","kjv_def":"vaunt itself","lemma":"περπερεύομαι","translit":"perpereúomai","pron":"per-per-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to boast one's self</li><li>a self display, employing rhetorical embellishments in extolling one's self excessively</li></ol>","xlit":"perpereúomai"},"G1552":{"kjv_def":"manifest","translit":"ékdēlos","lemma":"ἔκδηλος","derivation":"from G1537 (ἐκ) and G1212 (δῆλος);","strongs_def":" wholly evident","pron":"ek'-day-los","pos":"Adjective","thayer":"<ol><li>evident, clear, conspicuous</li></ol>","xlit":"ékdēlos"},"G5107":{"kjv_def":"such","lemma":"τοιόσδε","translit":"toiósde","derivation":"(including the other inflections); from a derivative of 5104 and G1161 (δέ);","strongs_def":" such-like then, i.e. so great","pron":"toy-os'-deh","pos":"Adjective","thayer":"<ol><li>such</li></ol>","xlit":"toiósde"},"G4193":{"strongs_def":" a Pontican, i.e. native of Pontus","derivation":"from G4195 (Πόντος);","translit":"Pontikós","lemma":"Ποντικός","kjv_def":"born in Pontus","pron":"pon-tik-os'","pos":"Adjective","thayer":"<ol><li>belonging to Pontus, born in Pontus</li></ol>","xlit":"Pontikós"},"G4990":{"kjv_def":"saviour","lemma":"σωτήρ","translit":"sōtḗr","derivation":"from G4982 (σώζω);","strongs_def":" a deliverer, i.e. God or Christ","pron":"so-tare'","pos":"Noun Masculine","thayer":"<ol><li>saviour, deliverer, preserver</li></ol>","xlit":"sōtḗr"},"G4903":{"kjv_def":"help (work) with, work(-er) together","lemma":"συνεργέω","translit":"synergéō","derivation":"from G4904 (συνεργός);","strongs_def":" to be a fellow-worker, i.e. co-operate","pron":"soon-erg-eh'-o","pos":"Verb","thayer":"<ol><li>to work together, help in work, be partner in labour</li><li>to put forth power together with and thereby to assist</li></ol>","xlit":"synergéō"},"G5304":{"lemma":"ὑστέρησις","translit":"hystérēsis","kjv_def":"want","strongs_def":" a falling short, i.e. (specially), penury","derivation":"from G5302 (ὑστερέω);","pron":"hoos-ter'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>want, poverty</li></ol>","xlit":"hystérēsis"},"G4952":{"strongs_def":" to rend completely, i.e. (by analogy) to convulse violently","derivation":"from G4862 (σύν) and G4682 (σπαράσσω);","lemma":"συσπαράσσω","translit":"sysparássō","kjv_def":"throw down","pron":"soos-par-as'-so","pos":"Verb","thayer":"<ol><li>to convulse completely</li></ol>","xlit":"sysparássō"},"G1052":{"derivation":"from G1053 (Γαλατία);","strongs_def":" a Galatian or inhabitant of Galatia","kjv_def":"Galatian","translit":"Galátēs","lemma":"Γαλάτης","pron":"gal-at'-ace","pos":"Noun Masculine","thayer":"<ol><li>a Galatians</li></ol>","xlit":"Galátēs"},"G3088":{"kjv_def":"candle, light","translit":"lýchnos","lemma":"λύχνος","derivation":"from the base of G3022 (λευκός);","strongs_def":" a portable lamp or other illuminator (literally or figuratively)","pron":"lookh'-nos","pos":"Noun Masculine","thayer":"<ol><li>a lamp, candle, that is placed on a stand or candlestick</li></ol>","xlit":"lýchnos"},"G4221":{"strongs_def":" a drinking-vessel; by extension, the contents thereof, i.e. a cupful (draught); figuratively, a lot or fate","derivation":"neuter of a derivative of the alternate of G4095 (πίνω);","translit":"potḗrion","lemma":"ποτήριον","kjv_def":"cup","pron":"pot-ay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a cup, a drinking vessel</li><li>metaphorically one's lot or experience, whether joyous or adverse, divine appointments, whether favourable or unfavourable, are likened to a cup which God presents one to drink: so of prosperity and adversity</li></ol>","xlit":"potḗrion"},"G935":{"derivation":"probably from G939 (βάσις) (through the notion of a foundation of power);","strongs_def":" a sovereign (abstractly, relatively, or figuratively)","kjv_def":"king","translit":"basileús","lemma":"βασιλεύς","pron":"bas-il-yooce'","pos":"Noun Masculine","thayer":"<ol><li>leader of the people, prince, commander, lord of the land, king</li></ol>","xlit":"basileús"},"G650":{"translit":"aposteréō","lemma":"ἀποστερέω","kjv_def":"defraud, destitute, kept back by fraud","strongs_def":" to despoil","derivation":"from G575 (ἀπό) and (to deprive);","pron":"ap-os-ter-eh'-o","pos":"Verb","thayer":"<ol><li>to defraud, rob, despoil</li></ol>","xlit":"aposteréō"},"G922":{"translit":"báros","lemma":"βάρος","kjv_def":"burden(-some), weight","strongs_def":" compare G899 (βάθος)); weight; in the New Testament only, figuratively, a load, abundance, authority","derivation":"probably from the same as G939 (βάσις) (through the notion of going down;","pron":"bar'-os","pos":"Noun Neuter","thayer":"<ol><li>heaviness, weight, burden, trouble</li></ol>","xlit":"báros"},"G5019":{"lemma":"Ταρσός","translit":"Tarsós","kjv_def":"Tarsus","strongs_def":" Tarsus, a place in Asia Minor","derivation":"perhaps the same as (a flat basket);","pron":"tar-sos'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Tarsus = \"a flat basket\"</p><ol><li>a major city in Cilicia and the birthplace and early home of Paul. <a class='bible' href='#b44.9.11'>Act 9:11</a>; <a class='bible' href='#b44.21.39'>Act 21:39</a>; <a class='bible' href='#b44.22.3'>Act 22:3</a>. Even in the flourishing period of Greek history it was an important city. In the Roman civil wars, it sided with Caesar and on the occasion of a visit from him its name changed to Juliopolis. Augustus made it a free city. Its was renowned as a place of education under the early Roman emperors. Strabo compares it in this respect to Athens and Alexandria. Tarsus also was a place of much commerce. It was situated in a wild and fertile plain on the banks of the Cydnus. No ruins of any importance remain.</li></ol>","xlit":"Tarsós"},"G4346":{"strongs_def":" a leaning towards, i.e. (figuratively) proclivity (favoritism)","derivation":"from a compound of G4314 (πρός) and G2827 (κλίνω);","translit":"prósklisis","lemma":"πρόσκλισις","kjv_def":"partiality","pron":"pros'-klis-is","pos":"Noun Feminine","thayer":"<ol><li>an inclination or proclivity of mind</li><li>a joining the party of one</li><li>partiality</li></ol>","xlit":"prósklisis"},"G3969":{"translit":"Patrobâs","lemma":"Πατροβᾶς","kjv_def":"Patrobas","strongs_def":" father's life; Patrobas, a Christian","derivation":"perhaps a contraction for (a compound of G3962 (πατήρ) and G979 (βίος));","pron":"pat-rob'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Patrobas = \"paternal\"</p><ol><li>a certain Christian in Rome</li></ol>","xlit":"Patrobâs"},"G678":{"translit":"aprosōpolḗptōs","lemma":"ἀπροσωπολήπτως","kjv_def":"without respect of persons","strongs_def":" in a way not accepting the person, i.e. impartially","derivation":"adverb from a compound of G1 (Α) (as a negative particle) and a presumed derivative of a presumed compound of G4383 (πρόσωπον) and G2983 (λαμβάνω) (compare G4381 (προσωπολήπτης));","pron":"ap-ros-o-pol-ape'-tos","pos":"Adverb","thayer":"<ol><li>without respect of persons, impartial</li></ol>","xlit":"aprosōpolḗptōs"},"G3441":{"strongs_def":" remaining, i.e. sole or single; by implication, mere","derivation":"probably from G3306 (μένω);","lemma":"μόνος","translit":"mónos","kjv_def":"alone, only, by themselves","pron":"mon'-os","pos":"Adjective","thayer":"<ol><li>alone (without a companion), forsaken, destitute of help, alone, only, merely</li></ol>","xlit":"mónos"},"G491":{"derivation":"from G490 (Ἀντιόχεια);","strongs_def":" an Antiochian or inhabitant of Antiochia","kjv_def":"of Antioch","translit":"Antiocheús","lemma":"Ἀντιοχεύς","pron":"an-tee-okh-yoos'","pos":"Noun Masculine","thayer":"<ol><li>an Antiochian, a native of Antioch</li></ol>","xlit":"Antiocheús"},"G1134":{"derivation":"from G1135 (γυνή);","strongs_def":" feminine","kjv_def":"wife","translit":"gynaikeîos","lemma":"γυναικεῖος","pron":"goo-nahee-ki'-os","pos":"Adjective","thayer":"<ol><li>of or belonging to a woman, feminine, female</li></ol>","xlit":"gynaikeîos"},"G1727":{"kjv_def":"(over) against, contrary","lemma":"ἐναντίος","translit":"enantíos","derivation":"from G1725 (ἔναντι);","strongs_def":" opposite; figuratively, antagonistic","pron":"en-an-tee'-os","pos":"Adjective","thayer":"<ol><li>over against, opposite<ol type='a'><li>of place, opposite, contrary (of the wind)</li></ol><li>metaphorically<ol type='a'><li>opposed as an adversary, hostile, antagonistic in feeling or act</li><li>an opponent</li></ol></li></ol>","xlit":"enantíos"},"G1917":{"strongs_def":" a plan against someone, i.e. a plot","derivation":"from a presumed compound of G1909 (ἐπί) and G1014 (βούλομαι);","lemma":"ἐπιβουλή","translit":"epiboulḗ","kjv_def":"laying (lying) in wait","pron":"ep-ee-boo-lay'","pos":"Noun Feminine","thayer":"<ol><li>a plan formed against one, a plot</li></ol>","xlit":"epiboulḗ"},"G2825":{"translit":"klínē","lemma":"κλίνη","kjv_def":"bed, table","strongs_def":" a couch (for sleep, sickness, sitting or eating)","derivation":"from G2827 (κλίνω);","pron":"klee'-nay","pos":"Noun Neuter","thayer":"<ol><li>a small bed, a couch</li><li>a couch to recline on at meals</li><li>a couch on which a sick man is carried</li></ol>","xlit":"klínē"},"G3459":{"strongs_def":" a mill-house","derivation":"from G3458 (μύλος);","lemma":"μύλων","translit":"mýlōn","kjv_def":"mill","pron":"moo'-lone","pos":"Noun Masculine","thayer":"<ol><li>place where a mill runs</li><li>mill house</li></ol>","xlit":"mýlōn"},"G2874":{"derivation":"from (ordure;","strongs_def":" perhaps akin to G2875 (κόπτω)); manure","kjv_def":"dung(-hill)","translit":"kopría","lemma":"κοπρία","pron":"kop-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>dung, manure</li></ol>","xlit":"kopría"},"G2569":{"strongs_def":" to do well, i.e. live virtuously","derivation":"from G2570 (καλός) and G4160 (ποιέω);","lemma":"καλοποιέω","translit":"kalopoiéō","kjv_def":"well doing","pron":"kal-op-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to do well, act uprightly</li></ol>","xlit":"kalopoiéō"},"G5331":{"strongs_def":" medication (\"pharmacy\"), i.e. (by extension) magic (literally or figuratively)","derivation":"from G5332 (φαρμακεύς);","translit":"pharmakeía","lemma":"φαρμακεία","kjv_def":"sorcery, witchcraft","pron":"far-mak-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>the use or the administering of drugs</li><li>poisoning</li><li>sorcery, magical arts, often found in connection with idolatry and fostered by it</li><li>metaphorically the deceptions and seductions of idolatry</li></ol>","xlit":"pharmakeía"},"G2208":{"kjv_def":"Zelotes","translit":"Zēlōtḗs","lemma":"Ζηλωτής","derivation":"the same as G2207 (ζηλωτής);","strongs_def":" a Zealot, i.e. (specially) partisan for Jewish political independence","pron":"dzay-lo-tace'","pos":"Noun Masculine","thayer":"<ol><li>one burning with zeal, a zealot</li><li>used of God as jealous of any rival and sternly vindicating his control</li><li>most eagerly desirous of, zealous for, a thing<ol type='a'><li>to acquire a thing, (zealous of)</li><li>to defend and uphold a thing, vehemently contending for a thing</li></ol></li></ol>","xlit":"Zēlōtḗs"},"G498":{"lemma":"ἀντιτάσσομαι","translit":"antitássomai","kjv_def":"oppose themselves, resist","strongs_def":" to range oneself against, i.e. oppose","derivation":"from G473 (ἀντί) and the middle voice of G5021 (τάσσω);","pron":"an-tee-tas'-som-ahee","pos":"Verb","thayer":"<ol><li>to range in battle against</li><li>to oppose one's self, resist</li></ol>","xlit":"antitássomai"},"G2381":{"strongs_def":" the twin; Thomas, a Christian","derivation":"of Chaldee origin (compare H08380);","lemma":"Θωμᾶς","translit":"Thōmâs","kjv_def":"Thomas","pron":"tho-mas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Thomas = \"a twin\"</p><ol><li>one of the apostles</li></ol>","xlit":"Thōmâs"},"G715":{"strongs_def":" a bear (as obstructing by ferocity)","derivation":"probably from G714 (ἀρκέω);","translit":"árktos","lemma":"ἄρκτος","kjv_def":"bear","pron":"ark'-tos","pos":"Noun","thayer":"<ol><li>a bear</li></ol>","xlit":"árktos"},"G2327":{"kjv_def":"reaper","lemma":"θεριστής","translit":"theristḗs","derivation":"from G2325 (θερίζω);","strongs_def":" a harvester","pron":"ther-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>a reaper</li></ol>","xlit":"theristḗs"},"G2378":{"strongs_def":" sacrifice (the act or the victim, literally or figuratively)","derivation":"from G2380 (θύω);","translit":"thysía","lemma":"θυσία","kjv_def":"sacrifice","pron":"thoo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>a sacrifice, victim</li></ol>","xlit":"thysía"},"G1124":{"derivation":"from G1125 (γράφω);","strongs_def":" a document, i.e. holy Writ (or its contents or a statement in it)","kjv_def":"scripture","lemma":"γραφή","translit":"graphḗ","pron":"graf-ay'","pos":"Noun Feminine","thayer":"<ol><li>a writing, thing written</li><li>the Scripture, used to denote either the book itself, or its contents</li><li>a certain portion or section of the Holy Scripture</li></ol>","xlit":"graphḗ"},"G734":{"lemma":"Ἀρτεμάς","translit":"Artemás","kjv_def":"Artemas","strongs_def":" gift of Artemis; Artemas (or Artemidorus), a Christian","derivation":"contracted from a compound of G735 (Ἄρτεμις) and G1435 (δῶρον);","pron":"ar-tem-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Artemas = \"gift of Artemis\"</p><ol><li>a friend of Paul the apostle</li></ol>","xlit":"Artemás"},"G5086":{"strongs_def":" probably pertaining to the river Tiberis or Tiber; Tiberius, a Roman emperor","derivation":"of Latin origin;","translit":"Tibérios","lemma":"Τιβέριος","kjv_def":"Tiberius","pron":"tib-er'-ee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tiberius = \"from the Tiber (as god-river)\"</p><ol><li>the second Roman emperor</li></ol>","xlit":"Tibérios"},"G3101":{"kjv_def":"disciple","translit":"mathētḗs","lemma":"μαθητής","derivation":"from G3129 (μανθάνω);","strongs_def":" a learner, i.e. pupil","pron":"math-ay-tes'","pos":"Noun Masculine","thayer":"<ol><li>a learner, pupil, disciple</li></ol>","xlit":"mathētḗs"},"G3163":{"kjv_def":"fighting, strive, striving","translit":"máchē","lemma":"μάχη","derivation":"from G3164 (μάχομαι);","strongs_def":" a battle, i.e. (figuratively) controversy","pron":"makh'-ay","pos":"Noun Feminine","thayer":"<ol><li>a fight or combat<ol type='a'><li>of those in arms, a battle</li><li>of persons at variance, disputants etc., strife, contention</li><li>a quarrel</li></ol></li></ol>","xlit":"máchē"},"G191":{"kjv_def":"give (in the) audience (of), come (to the ears), (shall) hear(-er, -ken), be noised, be reported, understand","lemma":"ἀκούω","translit":"akoúō","derivation":"a primary verb;","strongs_def":" to hear (in various senses)","pron":"ak-oo'-o","pos":"Verb","thayer":"<ol><li>to be endowed with the faculty of hearing, not deaf</li><li>to hear<ol type='a'><li>to attend to, consider what is or has been said</li><li>to understand, perceive the sense of what is said</li></ol><li>to hear something<ol type='a'><li>to perceive by the ear what is announced in one's presence</li><li>to get by hearing learn</li><li>a thing comes to one's ears, to find out, learn</li><li>to give ear to a teaching or a teacher</li><li>to comprehend, to understand</li></ol></li></ol>","xlit":"akoúō"},"G5468":{"strongs_def":" to be a bit-leader, i.e. to curb (figuratively)","derivation":"from a compound of G5469 (χαλινός) and the reduplicated form of G71 (ἄγω);","translit":"chalinagōgéō","lemma":"χαλιναγωγέω","kjv_def":"bridle","pron":"khal-in-ag-ogue-eh'-o","pos":"Verb","thayer":"<ol><li>to lead by a bridle, to guide</li><li>to bridle, hold in check, restrain</li></ol>","xlit":"chalinagōgéō"},"G3936":{"derivation":"from G3844 (παρά) and G2476 (ἵστημι);","strongs_def":" to stand beside, i.e. (transitively) to exhibit, proffer, (specially), recommend, (figuratively) substantiate; or (intransitively) to be at hand (or ready), aid","kjv_def":"assist, bring before, command, commend, give presently, present, prove, provide, shew, stand (before, by, here, up, with), yield","translit":"parístēmi","lemma":"παρίστημι","pron":"par-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place beside or near<ol type='a'><li>to set at hand<ol><li>to present</li><li>to proffer</li><li>to provide</li><li>to place a person or thing at one's disposal</li><li>to present a person for another to see and question</li><li>to present or show</li><li>to bring to, bring near</li><li>metaphorically i.e to bring into one's fellowship or intimacy</li></ol><li>to present (show) by argument, to prove</li></ol><li>to stand beside, stand by or near, to be at hand, be present<ol type='a'><li>to stand by<ol><li>to stand beside one, a bystander</li></ol><li>to appear</li><li>to be at hand, stand ready</li><li>to stand by to help, to succour</li><li>to be present<ol><li>to have come</li><li>of time</li></ol></li></ol></li></ol>","xlit":"parístēmi"},"G5330":{"derivation":"of Hebrew origin (compare H06567);","strongs_def":" a separatist, i.e. exclusively religious; a Pharisean, i.e. Jewish sectary","kjv_def":"Pharisee","lemma":"Φαρισαῖος","translit":"Pharisaîos","pron":"far-is-ah'-yos","pos":"Noun Masculine","thayer":"<ol><li>A sect that seems to have started after the Jewish exile. In addition to OT books the Pharisees recognised in oral tradition a standard of belief and life. They sought for distinction and praise by outward observance of external rites and by outward forms of piety, and such as ceremonial washings, fastings, prayers, and alms giving; and, comparatively negligent of genuine piety, they prided themselves on their fancied good works. They held strenuously to a belief in the existence of good and evil angels, and to the expectation of a Messiah; and they cherished the hope that the dead, after a preliminary experience either of reward or of penalty in Hades, would be recalled to life by him, and be requited each according to his individual deeds. In opposition to the usurped dominion of the Herods and the rule of the Romans, they stoutly upheld the theocracy and their country's cause, and possessed great influence with the common people. According to Josephus they numbered more than 6000. They were bitter enemies of Jesus and his cause; and were in turn severely rebuked by him for their avarice, ambition, hollow reliance on outward works, and affection of piety in order to gain popularity.</li></ol>","xlit":"Pharisaîos"},"G2439":{"kjv_def":"clothe","lemma":"ἱματίζω","translit":"himatízō","derivation":"from G2440 (ἱμάτιον);","strongs_def":" to dress","pron":"him-at-id'-zo","pos":"Verb","thayer":"<ol><li>to clothe</li></ol>","xlit":"himatízō"},"G2649":{"lemma":"καταμαρτυρέω","translit":"katamartyréō","kjv_def":"witness against","strongs_def":" to testify against","derivation":"from G2596 (κατά) and G3140 (μαρτυρέω);","pron":"kat-am-ar-too-reh'-o","pos":"Verb","thayer":"<ol><li>to bear witness against, to testify against one</li></ol>","xlit":"katamartyréō"},"G2301":{"strongs_def":" to expose as a spectacle","derivation":"from G2302 (θέατρον);","lemma":"θεατρίζω","translit":"theatrízō","kjv_def":"make a gazing stock","pron":"theh-at-rid'-zo","pos":"Verb","thayer":"<ol><li>to bring upon the stage</li><li>to set forth as a spectacle, expose to contempt</li></ol>","xlit":"theatrízō"},"G2222":{"kjv_def":"life(-time)","translit":"zōḗ","lemma":"ζωή","derivation":"from G2198 (ζάω);","strongs_def":" life (literally or figuratively)","pron":"dzo-ay'","pos":"Noun Feminine","thayer":"<ol><li>life<ol type='a'><li>the state of one who is possessed of vitality or is animate</li><li>every living soul</li></ol><li>life<ol type='a'><li>of the absolute fulness of life, both essential and ethical, which belongs to God, and through him both to the hypostatic \"logos\" and to Christ in whom the \"logos\" put on human nature</li><li>life real and genuine, a life active and vigorous, devoted to God, blessed, in the portion even in this world of those who put their trust in Christ, but after the resurrection to be consummated by new accessions (among them a more perfect body), and to last for ever.</li></ol></li></ol>","xlit":"zōḗ"},"G4845":{"kjv_def":"(fully) come, fill up","translit":"symplēróō","lemma":"συμπληρόω","derivation":"from G4862 (σύν) and G4137 (πληρόω);","strongs_def":" to implenish completely, i.e. (of space) to swamp (a boat), or (of time) to accomplish (passive, be complete)","pron":"soom-play-ro'-o","pos":"Verb","thayer":"<ol><li>to fill completely<ol type='a'><li>of the hold of a ship</li></ol><li>to complete entirely, be fulfilled: of time</li></ol>","xlit":"symplēróō"},"G5174":{"kjv_def":"Troas","lemma":"Τρωάς","translit":"Trōás","derivation":"from (a Trojan);","strongs_def":" the Troad (or plain of Troy), i.e. Troas, a place in Asia Minor","pron":"tro-as'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Troas = \"a Trojan\"</p><ol><li>a city near Hellespont</li></ol>","xlit":"Trōás"},"G1746":{"strongs_def":" to invest with clothing (literally or figuratively)","derivation":"from G1722 (ἐν) and G1416 (δύνω) (in the sense of sinking into a garment);","lemma":"ἐνδύω","translit":"endýō","kjv_def":"array, clothe (with), endue, have (put) on","pron":"en-doo'-o","pos":"Verb","thayer":"<ol><li>to sink into (clothing), put on, clothe one's self</li></ol>","xlit":"endýō"},"G844":{"lemma":"αὐτόματος","translit":"autómatos","kjv_def":"of own accord, of self","strongs_def":" self-moved (\"automatic\"), i.e. spontaneous","derivation":"from G846 (αὐτός) and the same as G3155 (μάτην);","pron":"ow-tom'-at-os","pos":"Adjective","thayer":"<ol><li>moved by one's own impulse, or acting without the instigation or intervention of another</li><li>often used of the earth producing plants of itself, and of the plants themselves and the fruits growing without culture</li></ol>","xlit":"autómatos"},"G26":{"strongs_def":" love, i.e. affection or benevolence; specially (plural) a love-feast","derivation":"from G25 (ἀγαπάω);","translit":"agápē","lemma":"ἀγάπη","kjv_def":"(feast of) charity(-ably), dear, love","pron":"ag-ah'-pay","pos":"Noun Feminine","thayer":"<ol><li>brotherly love, affection, good will, love, benevolence</li><li>love feasts</li></ol>","xlit":"agápē"},"G1630":{"lemma":"ἔκφοβος","translit":"ékphobos","kjv_def":" sore afraid, exceedingly fear","strongs_def":" frightened out of one's wits","derivation":"from G1537 (ἐκ) and G5401 (φόβος);","pron":"ek'-fob-os","pos":"Adjective","thayer":"<ol><li>stricken with fear or terror, exceedingly, frightened, terrified</li></ol>","xlit":"ékphobos"},"G2654":{"derivation":"from G2596 (κατά) and G355 (ἀναλίσκω);","strongs_def":" to consume utterly","kjv_def":"consume","lemma":"καταναλίσκω","translit":"katanalískō","pron":"kat-an-al-is'-ko","pos":"Verb","thayer":"<ol><li>to consume<ol type='a'><li>of fire</li></ol></li></ol>","xlit":"katanalískō"},"G5420":{"strongs_def":" to fence or inclose, i.e. (specially), to block up (figuratively, to silence)","derivation":"apparently a strengthening form of the base of G5424 (φρήν);","lemma":"φράσσω","translit":"phrássō","kjv_def":"stop","pron":"fras'-so","pos":"Verb","thayer":"<ol><li>to fence in, block up, stop up, close up</li><li>to put to silence</li></ol>","xlit":"phrássō"},"G3087":{"strongs_def":" a lamp-stand (literally or figuratively)","derivation":"from G3088 (λύχνος);","lemma":"λυχνία","translit":"lychnía","kjv_def":"candlestick","pron":"lookh-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a (candlestick) lamp stand, candelabrum</li></ol>","xlit":"lychnía"},"G4589":{"derivation":"of Hebrew origin (H08352);","strongs_def":" Seth (i.e. Sheth), a patriarch","kjv_def":"Seth","translit":"Sḗth","lemma":"Σήθ","pron":"sayth","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Seth = \"compensation\"</p><ol><li>the third son of Adam and the father of Enos</li></ol>","xlit":"Sḗth"},"G1964":{"derivation":"from G1965 (ἐπίορκος);","strongs_def":" to commit perjury","kjv_def":"forswear self","lemma":"ἐπιορκέω","translit":"epiorkéō","pron":"ep-ee-or-keh'-o","pos":"Verb","thayer":"<ol><li>to swear falsely, forswear one's self</li></ol>","xlit":"epiorkéō"},"G4959":{"derivation":"from G4862 (σύν) and G4727 (στενάζω);","strongs_def":" to moan jointly, i.e. (figuratively) experience a common calamity","kjv_def":"groan together","translit":"systenázō","lemma":"συστενάζω","pron":"soos-ten-ad'-zo","pos":"Verb","thayer":"<ol><li>to groan together</li></ol>","xlit":"systenázō"},"G1088":{"strongs_def":" aged","derivation":"of uncertain affinity (compare G1094 (γῆρας));","translit":"gérōn","lemma":"γέρων","kjv_def":"old","pron":"gher'-own","pos":"Noun Masculine","thayer":"<ol><li>an old man</li></ol>","xlit":"gérōn"},"G5356":{"derivation":"from G5351 (φθείρω);","strongs_def":" decay, i.e. ruin (spontaneous or inflicted, literally or figuratively)","kjv_def":"corruption, destroy, perish","lemma":"φθορά","translit":"phthorá","pron":"fthor-ah'","pos":"Noun Feminine","thayer":"<ol><li>corruption, destruction, perishing<ol type='a'><li>that which is subject to corruption, what is perishable</li><li>in the Christian sense, eternal misery in hell</li></ol><li>in the NT, in an ethical sense, corruption, i.e. moral decay</li></ol>","xlit":"phthorá"},"G3349":{"kjv_def":"be of doubtful mind","lemma":"μετεωρίζω","translit":"meteōrízō","derivation":"from a compound of G3326 (μετά) and a collateral form of G142 (αἴρω) or perhaps rather G109 (ἀήρ) (compare \"meteor\");","strongs_def":" to raise in mid-air, i.e. (figuratively) suspend (passively, fluctuate or be anxious)","pron":"met-eh-o-rid'-zo","pos":"Verb","thayer":"<ol><li>to rise up on high<ol type='a'><li>to put a ship [out to sea] up upon the deep</li><li>to raise up fortifications</li></ol><li>metaphorically<ol type='a'><li>to lift up one's soul, raise his spirits<ol><li>to buoy up with hope</li><li>to inflate with pride</li><li>to be elated</li><li>to take one airs, be puffed up with pride</li></ol><li>by a metaphor taken from ships that are tossed about on the deep by winds and waves<ol><li>to cause one to waver or fluctuate in the mind</li><li>to agitate or harass with cares</li><li>to make anxious</li></ol></li></ol></li></ol>","xlit":"meteōrízō"},"G1154":{"kjv_def":"Damascus","lemma":"Δαμασκός","translit":"Damaskós","derivation":"of Hebrew origin (H01834);","strongs_def":" Damascus, a city of Syria","pron":"dam-as-kos'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Damascus = \"silent is the sackcloth weaver\"</p><ol><li>one of the most ancient and most important cities of Syria lying in almost lovely and fertile plain at the eastern base of the Antilibanus</li></ol>","xlit":"Damaskós"},"G1408":{"derivation":"from the alternate of G5143 (τρέχω);","strongs_def":" a race, i.e. (figuratively) career","kjv_def":"course","translit":"drómos","lemma":"δρόμος","pron":"drom'-os","pos":"Noun Masculine","thayer":"<ol><li>a course<ol type='a'><li>in the NT figuratively, the course of life or of office</li></ol></li></ol>","xlit":"drómos"},"G3824":{"translit":"palingenesía","lemma":"παλιγγενεσία","kjv_def":"regeneration","strongs_def":" (spiritual) rebirth (the state or the act), i.e. (figuratively) spiritual renovation; specially, Messianic restoration","derivation":"from G3825 (πάλιν) and G1078 (γένεσις);","pron":"pal-ing-ghen-es-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>new birth, reproduction, renewal, recreation, regeneration<ol type='a'><li>hence renovation, regeneration, the production of a new life consecrated to God, a radical change of mind for the better. The word often used to denote the restoration of a thing to its pristine state, its renovation, as a renewal or restoration of life after death</li><li>the renovation of the earth after the deluge</li><li>the renewal of the world to take place after its destruction by fire, as the Stoics taught</li><li>the signal and glorious change of all things (in heaven and earth) for the better, that restoration of the primal and perfect condition of things which existed before the fall of our first parents, which the Jews looked for in connection with the advent of the Messiah, and which Christians expected in connection with the visible return of Jesus from heaven.</li><li>other uses<ol><li>of Cicero's restoration to rank and fortune on his recall from exile</li><li>of the restoration of the Jewish nation after exile</li><li>of the recovery of knowledge by recollection</li></ol></li></ol></li></ol>","xlit":"palingenesía"},"G2737":{"lemma":"κατώτερος","translit":"katṓteros","kjv_def":"lower","strongs_def":" inferior (locally, of Hades)","derivation":"comparative from G2736 (κάτω);","pron":"kat-o'-ter-os","pos":"Adjective","thayer":"<ol><li>lower</li></ol>","xlit":"katṓteros"},"G943":{"strongs_def":" a bath, or measure for liquids","derivation":"of Hebrew origin (H01324);","lemma":"βάτος","translit":"bátos","kjv_def":"measure","pron":"bat'-os","pos":"Noun","thayer":"<ol><li>a bath, a Jewish measure of liquids of about 8 or 9 gallons</li></ol>","xlit":"bátos"},"G3035":{"kjv_def":"of stone","translit":"líthinos","lemma":"λίθινος","derivation":"from G3037 (λίθος);","strongs_def":" stony, i.e. made of stone","pron":"lith-ee'-nos","pos":"Adjective","thayer":"<ol><li>of stone</li></ol>","xlit":"líthinos"},"G939":{"derivation":"from (to walk);","strongs_def":" a pace (\"base\"), i.e. (by implication) the foot","kjv_def":"foot","translit":"básis","lemma":"βάσις","pron":"bas'-ece","pos":"Noun Feminine","thayer":"<ol><li>a stepping, walking</li><li>that with which one steps, the foot</li></ol>","xlit":"básis"},"G2987":{"lemma":"λαμπρότης","translit":"lamprótēs","kjv_def":"brightness","strongs_def":" brilliancy","derivation":"from G2986 (λαμπρός);","pron":"lam-prot'-ace","pos":"Noun Feminine","thayer":"<ol><li>brightness, brilliancy</li></ol>","xlit":"lamprótēs"},"G1743":{"strongs_def":" to empower","derivation":"from G1722 (ἐν) and G1412 (δυναμόω);","translit":"endynamóō","lemma":"ἐνδυναμόω","kjv_def":"enable, (increase in) strength(-en), be (make) strong","pron":"en-doo-nam-o'-o","pos":"Verb","thayer":"<ol><li>to be strong, endue with strength, strengthen</li><li>to receive strength, be strengthened, increase in strength</li><li>in a bad sense<ol type='a'><li>be bold, headstrong</li></ol></li></ol>","xlit":"endynamóō"},"G1361":{"strongs_def":" Jove-nourished; Diotrephes, an opponent of Christianity","derivation":"from the alternate of G2203 (Ζεύς) and G5142 (τρέφω);","lemma":"Διοτρεφής","translit":"Diotrephḗs","kjv_def":"Diotrephes","pron":"dee-ot-ref-ace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Diotrephes = \"nourished by Jove\"</p><ol><li>a proud arrogant Christian mentioned in <a class='bible' href='#b64.1.9'>3Jn 1:9</a></li></ol>","xlit":"Diotrephḗs"},"G2149":{"kjv_def":"broad","lemma":"εὐρύχωρος","translit":"eurýchōros","derivation":"from (wide) and G5561 (χώρα);","strongs_def":" spacious","pron":"yoo-roo'-kho-ros","pos":"Adjective","thayer":"<ol><li>spacious, broad</li></ol>","xlit":"eurýchōros"},"G230":{"strongs_def":" truly","derivation":"adverb from G227 (ἀληθής);","translit":"alēthōs","lemma":"ἀληθῶς","kjv_def":"indeed, surely, of a surety, truly, of a (in) truth, verily, very","pron":"al-ay-thoce'","pos":"Adverb","thayer":"<ol><li>truly, of a truth, in reality, most certainly</li></ol>","xlit":"alēthōs"},"G4953":{"strongs_def":" a sign in common, i.e. preconcerted signal","derivation":"neuter of a compound of G4862 (σύν) and the base of G4591 (σημαίνω);","translit":"sýssēmon","lemma":"σύσσημον","kjv_def":"token","pron":"soos'-say-mon","pos":"Noun Neuter","thayer":"<ol><li>a common sign or concerted signal</li><li>a sign given according to agreement</li></ol>","xlit":"sýssēmon"},"G61":{"lemma":"ἄγρα","translit":"ágra","kjv_def":"draught","strongs_def":" (abstractly) a catching (of fish); also (concretely) a haul (of fish)","derivation":"from G71 (ἄγω);","pron":"ag'-rah","pos":"Noun Feminine","thayer":"<ol><li>a catching, hunting</li><li>that which is taken in hunting, the booty, prey<ol type='a'><li>of birds or beasts, game</li><li>of fish, a draught or haul</li></ol></li></ol>","xlit":"ágra"},"G4829":{"translit":"symmerízomai","lemma":"συμμερίζομαι","kjv_def":"be partaker with","strongs_def":" to share jointly, i.e. participate in","derivation":"middle voice from G4862 (σύν) and G3307 (μερίζω);","pron":"soom-mer-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to divide at the same time, divide together</li><li>to assign a portion</li><li>to divide together with one (so that a part comes to me, a part to him)</li></ol>","xlit":"symmerízomai"},"G954":{"strongs_def":" dung-god; Beelzebul, a name of Satan","derivation":"of Chaldee origin (by parody on H01176);","translit":"Beelzeboúl","lemma":"Βεελζεβούλ","kjv_def":"Beelzebub","pron":"beh-el-zeb-ool'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Beelzebub = \"lord of the house\"</p><ol><li>a name of Satan, the prince of evil spirits</li></ol>","xlit":"Beelzeboúl"},"G2946":{"derivation":"from G2947 (κυλιόω);","strongs_def":" a wallow (the effect of rolling), i.e. filth","kjv_def":"wallowing","translit":"kýlisma","lemma":"κύλισμα","pron":"koo'-lis-mah","pos":"Noun Neuter","thayer":"<ol><li>thing rolled, rolled (wallowed) mud or mire</li></ol>","xlit":"kýlisma"},"G5146":{"kjv_def":"brier, thistle","lemma":"τρίβολος","translit":"tríbolos","derivation":"from G5140 (τρεῖς) and G956 (βέλος);","strongs_def":" properly, a crow-foot (three-pronged obstruction in war), i.e. (by analogy) a thorny plant (caltrop)","pron":"trib'-ol-os","pos":"Noun Masculine","thayer":"<ol><li>a thistle, a prickly wild plant, hurtful to other plants</li></ol>","xlit":"tríbolos"},"G4167":{"translit":"poímnē","lemma":"ποίμνη","kjv_def":"flock, fold","strongs_def":" a flock (literally or figuratively)","derivation":"contraction from G4165 (ποιμαίνω);","pron":"poym'-nay","pos":"Noun Feminine","thayer":"<ol><li>a flock (especially) of sheep<ol type='a'><li>of Christ's flock, i.e. the body of those who follow Jesus as their guide and keeper</li></ol></li></ol>","xlit":"poímnē"},"G5063":{"kjv_def":"(+ full, of) forty years (old)","translit":"tessarakontaetḗs","lemma":"τεσσαρακονταετής","derivation":"from G5062 (τεσσαράκοντα) and G2094 (ἔτος);","strongs_def":" of forty years of age","pron":"tes-sar-ak-on-tah-et-ace'","pos":"Adjective","thayer":"<ol><li>of forty years, forty years old</li></ol>","xlit":"tessarakontaetḗs"},"G4288":{"derivation":"from G4289 (πρόθυμος);","strongs_def":" predisposition, i.e. alacrity","kjv_def":"forwardness of mind, readiness (of mind), ready (willing) mind","translit":"prothymía","lemma":"προθυμία","pron":"proth-oo-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>zeal, spirit, eagerness</li><li>inclination, readiness of mind</li></ol>","xlit":"prothymía"},"G1589":{"derivation":"from G1586 (ἐκλέγομαι);","strongs_def":" (divine) selection (abstractly or concretely)","kjv_def":"chosen, election","lemma":"ἐκλογή","translit":"eklogḗ","pron":"ek-log-ay'","pos":"Noun Feminine","thayer":"<ol><li>the act of picking out, choosing<ol type='a'><li>of the act of God's free will by which before the foundation of the world he decreed his blessings to certain persons</li><li>the decree made from choice by which he determined to bless certain persons through Christ by grace alone</li></ol><li>a thing or person chosen<ol type='a'><li>of persons: God's elect</li></ol></li></ol>","xlit":"eklogḗ"},"G710":{"derivation":"apparently a comparative of the same as G712 (ἄριστον);","strongs_def":" the left hand (as second-best)","kjv_def":"left (hand)","translit":"aristerós","lemma":"ἀριστερός","pron":"ar-is-ter-os'","pos":"Adjective","thayer":"<ol><li>left</li></ol>","xlit":"aristerós"},"G4909":{"kjv_def":"allow, assent, be pleased, have pleasure","translit":"syneudokéō","lemma":"συνευδοκέω","derivation":"from G4862 (σύν) and G2106 (εὐδοκέω);","strongs_def":" to think well of in common, i.e. assent to, feel gratified with","pron":"soon-yoo-dok-eh'-o","pos":"Verb","thayer":"<ol><li>to be pleased together with, to approve together (with others)</li><li>to be pleased at the same time with, consent, agree to<ol type='a'><li>to applaud</li></ol></li></ol>","xlit":"syneudokéō"},"G4376":{"kjv_def":"offering (up)","lemma":"προσφορά","translit":"prosphorá","derivation":"from G4374 (προσφέρω);","strongs_def":" presentation; concretely, an oblation (bloodless) or sacrifice","pron":"pros-for-ah'","pos":"Noun Feminine","thayer":"<ol><li>the act of offering, a bringing to</li><li>that which is offered, a gift, a present. In the NT a sacrifice, whether bloody or not: offering for sin, expiatory offering</li></ol>","xlit":"prosphorá"},"G5519":{"kjv_def":"swine","lemma":"χοῖρος","translit":"choîros","derivation":"of uncertain derivation;","strongs_def":" a hog","pron":"khoy'-ros","pos":"Noun Masculine","thayer":"<ol><li>a swine</li></ol>","xlit":"choîros"},"G2180":{"derivation":"from G2181 (Ἔφεσος);","strongs_def":" an Ephesian or inhabitant of Ephesus","kjv_def":"Ephesian, of Ephesus","lemma":"Ἐφέσιος","translit":"Ephésios","pron":"ef-es'-ee-os","pos":"Adjective","thayer":"<ol><li>a native or inhabitant of Ephesus</li></ol>","xlit":"Ephésios"},"G4449":{"kjv_def":"be red","translit":"pyrrházō","lemma":"πυῤῥάζω","derivation":"from G4450 (πυῤῥός);","strongs_def":" to redden (intransitively)","pron":"poor-hrad'-zo","pos":"Verb","thayer":"<ol><li>to become glowing, grow red, be red</li></ol>","xlit":"pyrrházō"},"G2136":{"derivation":"from the same as G2137 (εὐοδόω);","strongs_def":" fine travelling; Euodia, a Christian woman","kjv_def":"Euodias","translit":"Euodía","lemma":"Εὐοδία","pron":"yoo-od-ee'-ah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Euodias = \"fragrant\"</p><ol><li>a Christian woman at Philippi</li></ol>","xlit":"Euodía"},"G4512":{"translit":"rhytís","lemma":"ῥυτίς","kjv_def":"wrinkle","strongs_def":" a fold (as drawing together), i.e. a wrinkle (especially on the face)","derivation":"from G4506 (ῥύομαι);","pron":"hroo-tece'","pos":"Noun Feminine","thayer":"<ol><li>a wrinkle</li></ol>","xlit":"rhytís"},"G3193":{"strongs_def":" relating to honey, i.e. bee (comb)","derivation":"from G3192 (μέλι);","translit":"melíssios","lemma":"μελίσσιος","kjv_def":"honeycomb","pron":"mel-is'-see-os","pos":"Adjective","thayer":"<ol><li>of bees, made by bees</li></ol>","xlit":"melíssios"},"G1566":{"derivation":"from G1563 (ἐκεῖ);","strongs_def":" thither","kjv_def":"there","lemma":"ἐκεῖσε","translit":"ekeîse","pron":"ek-i'-seh","pos":"Adverb","thayer":"<ol><li>there, at that place</li></ol>","xlit":"ekeîse"},"G401":{"lemma":"ἀνάχυσις","translit":"anáchysis","kjv_def":"excess","strongs_def":" properly, effusion, i.e. (figuratively) license","derivation":"from a comparative of G303 (ἀνά) and (to pour);","pron":"an-akh'-oo-sis","pos":"Noun Feminine","thayer":"<ol><li>an overflowing, a pouring out</li><li>metaphorically the excess (flood) of riot in which a dissolute life pours itself forth</li></ol>","xlit":"anáchysis"},"G5274":{"strongs_def":" to take from below, i.e. carry upward; figuratively, to take up, i.e. continue a discourse or topic; mentally, to assume (presume)","derivation":"from G5259 (ὑπό) and G2983 (λαμβάνω);","lemma":"ὑπολαμβάνω","translit":"hypolambánō","kjv_def":"answer, receive, suppose","pron":"hoop-ol-am-ban'-o","pos":"Verb","thayer":"<ol><li>to take up in order to raise, to bear on high<ol type='a'><li>to take up and carry away</li></ol><li>to receive hospitably, welcome</li><li>to take up<ol type='a'><li>follow in speech, in order either to reply to or controvert or supplement what another has said</li></ol><li>to take up in the mind<ol type='a'><li>to assume, suppose</li></ol></li></ol>","xlit":"hypolambánō"},"G2518":{"derivation":"from G2596 (κατά) and (to sleep);","strongs_def":" to lie down to rest, i.e. (by implication) to fall asleep (literally or figuratively)","kjv_def":"(be a-)sleep","lemma":"καθεύδω","translit":"katheúdō","pron":"kath-yoo'-do","pos":"Verb","thayer":"<ol><li>to fall asleep, drop off to sleep</li><li>to sleep<ol type='a'><li>to sleep normally</li><li>euphemistically, to be dead</li><li>metaphorically<ol><li>to yield to sloth and sin</li><li>to be indifferent to one's salvation</li></ol></li></ol></li></ol>","xlit":"katheúdō"},"G2861":{"strongs_def":" a diving-place, i.e. pond for bathing (or swimming)","derivation":"from G2860 (κολυμβάω);","lemma":"κολυμβήθρα","translit":"kolymbḗthra","kjv_def":"pool","pron":"kol-oom-bay'-thrah","pos":"Noun Feminine","thayer":"<ol><li>a place for diving, a swimming hole, a reservoir or pool for bathing</li></ol>","xlit":"kolymbḗthra"},"G1152":{"kjv_def":"Damaris","translit":"Dámaris","lemma":"Δάμαρις","derivation":"probably from the base of G1150 (δαμάζω);","strongs_def":" perhaps gentle; Damaris, an Athenian woman","pron":"dam'-ar-is","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Damaris = \"a heifer\"</p><ol><li>an Athenian woman converted to Christianity by Paul's preaching</li></ol>","xlit":"Dámaris"},"G291":{"lemma":"Ἀμπλίας","translit":"Amplías","kjv_def":"Amplias","strongs_def":" Amplias, a Roman Christian","derivation":"contracted for Latin ampliatus (enlarged);","pron":"am-plee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Amplias = \"large\"</p><ol><li>a Christian living in Rome</li></ol>","xlit":"Amplías"},"G4696":{"kjv_def":"spot","lemma":"σπίλος","translit":"spílos","derivation":"of uncertain derivation;","strongs_def":" a stain or blemish, i.e. (figuratively) defect, disgrace","pron":"spee'-los","pos":"Noun Masculine","thayer":"<ol><li>a spot</li><li>a fault, moral blemish<ol type='a'><li>of base and gluttonous men</li></ol></li></ol>","xlit":"spílos"},"G3488":{"translit":"Nárkissos","lemma":"Νάρκισσος","kjv_def":"Narcissus","strongs_def":" Narcissus, a Roman","derivation":"a flower of the same name, from (stupefaction, as a \"narcotic\");","pron":"nar'-kis-sos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Narcissus = \"stupidity\"</p><ol><li>a dweller at Rome mentioned by Paul in <a class='bible' href='#b45.16.11'>Rom 16:11</a></li></ol>","xlit":"Nárkissos"},"G2509":{"strongs_def":" exactly as","derivation":"from G2505 (καθά) and G4007 (περ);","lemma":"καθάπερ","translit":"katháper","kjv_def":"(even, as well) as","pron":"kath-ap'-er","thayer":"<ol><li>according as, just as, even as</li></ol>","xlit":"katháper"},"G2409":{"derivation":"from G2413 (ἱερός);","strongs_def":" a priest (literally or figuratively)","kjv_def":"(high) priest","translit":"hiereús","lemma":"ἱερεύς","pron":"hee-er-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a priest, one who offers sacrifices and in general in busied with sacred rites<ol type='a'><li>referring to priests of Gentiles or the Jews</li></ol><li>metaphorically of Christians, because, purified by the blood of Christ and brought into close intercourse with God, they devote their life to him alone and to Christ</li></ol>","xlit":"hiereús"},"G2087":{"kjv_def":"altered, else, next (day), one, (an-)other, some, strange","translit":"héteros","lemma":"ἕτερος","derivation":"of uncertain affinity;","strongs_def":" (an-, the) other or different","pron":"het'-er-os","pos":"Adjective","thayer":"<ol><li>the other, another, other<ol type='a'><li>to number<ol><li>to number as opposed to some former person or thing</li><li>the other of two</li></ol><li>to quality<ol><li>another: i.e. one not of the same nature, form, class, kind, different</li></ol></li></ol></li></ol>","xlit":"héteros"},"G4695":{"strongs_def":" to stain or soil (literally or figuratively)","derivation":"from G4696 (σπίλος);","lemma":"σπιλόω","translit":"spilóō","kjv_def":"defile, spot","pron":"spee-lo'-o","pos":"Verb","thayer":"<ol><li>to defile, spot</li></ol>","xlit":"spilóō"},"G4497":{"lemma":"Ῥοβοάμ","translit":"Rhoboám","kjv_def":"Roboam","strongs_def":" Roboam (i.e. Rechobam), an Israelite","derivation":"of Hebrew origin (H07346);","pron":"hrob-o-am'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Rehoboam = \"enlarger of the people\"</p><ol><li>the son of Solomon by an Ammonite princess Naamah</li></ol>","xlit":"Rhoboám"},"G3573":{"kjv_def":"slumber","translit":"nystázō","lemma":"νυστάζω","derivation":"from a presumed derivative of G3506 (νεύω);","strongs_def":" to nod, i.e. (by implication) to fall asleep; figuratively, to delay","pron":"noos-tad'-zo","pos":"Verb","thayer":"<ol><li>to nod in sleep, to sleep<ol type='a'><li>to be overcome or oppressed with sleep</li><li>to fall asleep, drop off to sleep</li></ol><li>to be negligent, careless<ol type='a'><li>of a thing, i.e. to linger, delay</li></ol></li></ol>","xlit":"nystázō"},"G1895":{"kjv_def":"forasmuch","translit":"epeidḗper","lemma":"ἐπειδήπερ","derivation":"from G1894 (ἐπειδή) and G4007 (περ);","strongs_def":" since indeed (of cause)","pron":"ep-i-day'-per","pos":"Conjunction","thayer":"<ol><li>seeing that, forasmuch as</li></ol>","xlit":"epeidḗper"},"G1009":{"translit":"bótrys","lemma":"βότρυς","kjv_def":"(vine) cluster (of the vine)","strongs_def":" a bunch (of grapes)","derivation":"of uncertain derivation;","pron":"bot'-rooce","pos":"Noun Masculine","thayer":"<ol><li>a bunch or cluster of grapes</li></ol>","xlit":"bótrys"},"G1325":{"lemma":"δίδωμι","translit":"dídōmi","kjv_def":"adventure, bestow, bring forth, commit, deliver (up), give, grant, hinder, make, minister, number, offer, have power, put, receive, set, shew, smite (+ with the hand), strike (+ with the palm of the hand), suffer, take, utter, yield","strongs_def":" to give (used in a very wide application, properly, or by implication, literally or figuratively; greatly modified by the connection)","derivation":"a prolonged form of a primary verb (which is used as an alternative in most of the tenses);","pron":"did'-o-mee","pos":"Verb","thayer":"<ol><li>to give</li><li>to give something to someone<ol type='a'><li>of one's own accord to give one something, to his advantage<ol><li>to bestow a gift</li></ol><li>to grant, give to one asking, let have</li><li>to supply, furnish, necessary things</li><li>to give over, deliver<ol><li>to reach out, extend, present</li><li>of a writing</li><li>to give over to one's care, intrust, commit<ol type='a'><li>something to be administered</li><li>to give or commit to some one something to be religiously observed</li></ol></li></ol><li>to give what is due or obligatory, to pay: wages or reward</li><li>to furnish, endue</li></ol><li>to give<ol type='a'><li>to cause, profuse, give forth from one's self<ol><li>to give, hand out lots</li></ol><li>to appoint to an office</li><li>to cause to come forth, i.e. as the sea, death and Hell are said to give up the dead who have been engulfed or received by them</li><li>to give one to someone as his own<ol><li>as an object of his saving care</li><li>to give one to someone, to follow him as a leader and master</li><li>to give one to someone to care for his interests</li><li>to give one to someone to whom he already belonged, to return</li></ol></li></ol><li>to grant or permit one<ol type='a'><li>to commission</li></ol></li></ol>","xlit":"dídōmi"},"G4363":{"kjv_def":"beat upon, fall (down) at (before)","translit":"prospíptō","lemma":"προσπίπτω","derivation":"from G4314 (πρός) and G4098 (πίπτω);","strongs_def":" to fall towards, i.e. (gently) prostrate oneself (in supplication or homage), or (violently) to rush upon (in storm)","pron":"pros-pip'-to","pos":"Verb","thayer":"<ol><li>to fall forwards, fall down, prostrate one's self before, in homage or supplication: at one's feet</li><li>to rush upon, beat against<ol type='a'><li>of winds beating upon a house</li></ol></li></ol>","xlit":"prospíptō"},"G4937":{"strongs_def":" to crush completely, i.e. to shatter (literally or figuratively)","derivation":"from G4862 (σύν) and the base of G5147 (τρίβος);","lemma":"συντρίβω","translit":"syntríbō","kjv_def":"break (in pieces), broken to shivers (+ -hearted), bruise","pron":"soon-tree'-bo","pos":"Verb","thayer":"<ol><li>break, to break in pieces, shiver</li><li>to tread down<ol type='a'><li>to put Satan under foot and (as a conqueror) trample on him</li><li>to break down, crush<ol><li>to tear one's body and shatter one's strength</li></ol></li></ol></li></ol>","xlit":"syntríbō"},"G5196":{"derivation":"from G5228 (ὑπέρ);","strongs_def":" insolence (as over-bearing), i.e. insult, injury","kjv_def":"harm, hurt, reproach","translit":"hýbris","lemma":"ὕβρις","pron":"hoo'-bris","pos":"Noun Feminine","thayer":"<ol><li>insolence<ol type='a'><li>impudence, pride, haughtiness</li></ol><li>a wrong springing from insolence, an injury, affront, insult</li><li>mental injury and wantonness of its infliction being prominent</li><li>injury inflicted by the violence of a tempest</li></ol>","xlit":"hýbris"},"G3711":{"strongs_def":" irascible","derivation":"from G3709 (ὀργή);","translit":"orgílos","lemma":"ὀργίλος","kjv_def":"soon angry","pron":"org-ee'-los","pos":"Adjective","thayer":"<ol><li>prone to anger, irascible</li></ol>","xlit":"orgílos"},"G45":{"kjv_def":"anchor","lemma":"ἄγκυρα","translit":"ánkyra","derivation":"from the same as G43 (ἀγκάλη);","strongs_def":" an \"anchor\" (as crooked)","pron":"ang'-koo-rah","pos":"Noun Feminine","thayer":"<ol><li>an anchor</li><li>metaphorically any stay or safeguard</li></ol>","xlit":"ánkyra"},"G2338":{"strongs_def":" female","derivation":"from the same as G2337 (θηλάζω);","translit":"thēlys","lemma":"θῆλυς","kjv_def":"female, woman","pron":"thay'-loos","pos":"Adjective","thayer":"<ol><li>of the female sex</li><li>a woman, a female</li></ol>","xlit":"thēlys"},"G5308":{"kjv_def":"high(-er, -ly) (esteemed)","lemma":"ὑψηλός","translit":"hypsēlós","derivation":"from G5311 (ὕψος);","strongs_def":" lofty (in place or character)","pron":"hoop-say-los'","pos":"Adjective","thayer":"<ol><li>high, lofty<ol type='a'><li>exalted on high</li><li>with an uplifted arm, i.e. with signal power</li></ol><li>metaphorically eminent, exalted<ol type='a'><li>in influence and honour</li><li>to set the mind on, to seek, high things (as honours and riches), to be aspiring</li></ol></li></ol>","xlit":"hypsēlós"},"G4929":{"derivation":"from G4862 (σύν) and G5021 (τάσσω);","strongs_def":" to arrange jointly, i.e. (figuratively) to direct","kjv_def":"appoint","translit":"syntássō","lemma":"συντάσσω","pron":"soon-tas-so","pos":"Verb","thayer":"<ol><li>to put in order with or together, to arrange</li><li>to (put together), constitute<ol type='a'><li>to prescribe, appoint</li></ol></li></ol>","xlit":"syntássō"},"G3878":{"translit":"parakoúō","lemma":"παρακούω","kjv_def":"neglect to hear","strongs_def":" to mishear, i.e. (by implication) to disobey","derivation":"from G3844 (παρά) and G191 (ἀκούω);","pron":"par-ak-oo'-o","pos":"Verb","thayer":"<ol><li>to hear aside<ol type='a'><li>causally or carelessly or amiss</li></ol><li>to be unwilling to hear<ol type='a'><li>on hearing to neglect, to pay no heed to</li><li>to refuse to hear, pay no regard to, disobey</li></ol></li></ol>","xlit":"parakoúō"},"G1800":{"derivation":"of Hebrew origin (H0583);","strongs_def":" Enos (i.e. Enosh), a patriarch","kjv_def":"Enos","translit":"Enṓs","lemma":"Ἐνώς","pron":"en-oce'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Enos = \"mortal man\"</p><ol><li>the son of Seth</li></ol>","xlit":"Enṓs"},"G2207":{"translit":"zēlōtḗs","lemma":"ζηλωτής","kjv_def":"zealous","strongs_def":" a \"zealot\"","derivation":"from G2206 (ζηλόω);","pron":"dzay-lo-tace'","pos":"Noun Masculine","thayer":"<ol><li>one burning with zeal, a zealot</li><li>used of God as jealous of any rival and sternly vindicating his control</li><li>most eagerly desirous of, zealous for, a thing<ol type='a'><li>to acquire a thing, (zealous of)</li><li>to defend and uphold a thing, vehemently contending for a thing</li></ol></li></ol>","xlit":"zēlōtḗs"},"G5144":{"strongs_def":" thirty","derivation":"the decade of G5140 (τρεῖς);","lemma":"τριάκοντα","translit":"triákonta","kjv_def":"thirty","pron":"tree-ak'-on-tah","pos":"Adjective","thayer":"<ol><li>thirty</li></ol>","xlit":"triákonta"},"G2944":{"strongs_def":" to encircle, i.e. surround","derivation":"from the same as G2945 (κύκλῳ);","lemma":"κυκλόω","translit":"kyklóō","kjv_def":"compass (about), come (stand) round about","pron":"koo-klo'-o","pos":"Verb","thayer":"<ol><li>to go around, lead around</li><li>to surround, encircle, encompass<ol type='a'><li>of persons standing around</li><li>of besiegers</li></ol></li></ol>","xlit":"kyklóō"},"G4126":{"kjv_def":"sail","translit":"pléō","lemma":"πλέω","derivation":"probably a form of G4150 (πλύνω) (through the idea of plunging through the water);","strongs_def":" to pass in a vessel","pron":"pleh'-o","pos":"Verb","thayer":"<ol><li>to sail, navigate, travel by ship</li></ol>","xlit":"pléō"},"G5407":{"kjv_def":"kill, do murder, slay","translit":"phoneúō","lemma":"φονεύω","derivation":"from G5406 (φονεύς);","strongs_def":" to be a murderer (of)","pron":"fon-yoo'-o","pos":"Verb","thayer":"<ol><li>to kill, slay, murder</li><li>to commit murder</li></ol>","xlit":"phoneúō"},"G1104":{"strongs_def":" genuinely, i.e. really","derivation":"adverb from G1103 (γνήσιος);","translit":"gnēsíōs","lemma":"γνησίως","kjv_def":"naturally","pron":"gnay-see'-ose","pos":"Adverb","thayer":"<ol><li>genuinely, faithfully, sincerely</li></ol>","xlit":"gnēsíōs"},"G4508":{"derivation":"from G4509 (ῥύπος);","strongs_def":" dirty, i.e. (relatively) cheap or shabby; morally, wicked","kjv_def":"vile","translit":"rhyparós","lemma":"ῥυπαρός","pron":"rhoo-par-os'","pos":"Adjective","thayer":"<ol><li>to be dirty, grow filthy</li><li>metaphorically to be defiled with iniquity</li></ol>","xlit":"rhyparós"},"G5454":{"translit":"phōleós","lemma":"φωλεός","kjv_def":"hole","strongs_def":" a burrow or lurking-place","derivation":"of uncertain derivative;","pron":"fo-leh-os'","pos":"Noun Masculine","thayer":"<ol><li>a lurking hole, a burrow</li><li>a lair</li></ol>","xlit":"phōleós"},"G1036":{"derivation":"from G1037 (βυθός);","strongs_def":" to sink; by implication, to drown","kjv_def":"begin to sink, drown","lemma":"βυθίζω","translit":"bythízō","pron":"boo-thid'-zo","pos":"Verb","thayer":"<ol><li>to plunge into the deep, to sink</li></ol>","xlit":"bythízō"},"G1262":{"strongs_def":" to dissolve utterly","derivation":"from G1223 (διά) and G3089 (λύω);","translit":"dialýō","lemma":"διαλύω","kjv_def":"scatter","pron":"dee-al-oo'-o","pos":"Verb","thayer":"<ol><li>to dissolve</li></ol>","xlit":"dialýō"},"G1871":{"translit":"epaitéō","lemma":"ἐπαιτέω","kjv_def":"beg","strongs_def":" to ask for","derivation":"from G1909 (ἐπί) and G154 (αἰτέω);","pron":"ep-ahee-teh'-o","pos":"Verb","thayer":"<ol><li>to ask besides, ask for more</li><li>to ask again and again, importunately</li><li>to beg, to ask alms</li></ol>","xlit":"epaitéō"},"G974":{"strongs_def":" a booklet","derivation":"a diminutive of G975 (βιβλίον);","lemma":"βιβλιαρίδιον","translit":"bibliarídion","kjv_def":"little book","pron":"bib-lee-ar-id'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a little book</li></ol>","xlit":"bibliarídion"},"G5534":{"kjv_def":"ought","translit":"chrḗ","lemma":"χρή","derivation":"third person singular of the same as G5530 (χράομαι) or G5531 (χράω) used impersonally;","strongs_def":" it needs (must or should) be","pron":"khray","pos":"Verb","thayer":"<ol><li>it is necessary</li><li>it behooves</li></ol>","xlit":"chrḗ"},"G4964":{"derivation":"from G4862 (σύν) and a derivative of G4976 (σχῆμα);","strongs_def":" to fashion alike, i.e. conform to the same pattern (figuratively)","kjv_def":"conform to, fashion self according to","lemma":"συσχηματίζω","translit":"syschēmatízō","pron":"soos-khay-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to conform one's self (i.e. one's mind and character) to another's pattern, (fashion one's self according to)</li></ol>","xlit":"syschēmatízō"},"G5480":{"derivation":"from the same as G5482 (χάραξ);","strongs_def":" a scratch or etching, i.e. stamp (as a badge of servitude), or scupltured figure (statue)","kjv_def":"graven, mark","lemma":"χάραγμα","translit":"cháragma","pron":"khar'-ag-mah","pos":"Noun Neuter","thayer":"<ol><li>a stamp, an imprinted mark<ol type='a'><li>of the mark stamped on the forehead or the right hand as the badge of the followers of the Antichrist</li><li>the mark branded upon horses</li></ol><li>thing carved, sculpture, graven work<ol type='a'><li>of idolatrous images</li></ol></li></ol>","xlit":"cháragma"},"G4656":{"strongs_def":" to obscure or blind (literally or figuratively)","derivation":"from G4655 (σκότος);","translit":"skotóō","lemma":"σκοτόω","kjv_def":"be full of darkness","pron":"skot-o'-o","pos":"Verb","thayer":"<ol><li>to darken, cover with darkness</li><li>metaphorically to darken or blind the mind</li></ol>","xlit":"skotóō"},"G4427":{"strongs_def":" saliva","derivation":"from G4429 (πτύω);","translit":"ptýsma","lemma":"πτύσμα","kjv_def":"spittle","pron":"ptoos'-mah","pos":"Noun Neuter","thayer":"<ol><li>spittle</li></ol>","xlit":"ptýsma"},"G1611":{"kjv_def":"+ be amazed, amazement, astonishment, trance","translit":"ékstasis","lemma":"ἔκστασις","derivation":"from G1839 (ἐξίστημι);","strongs_def":" a displacement of the mind, i.e. bewilderment, \"ecstasy\"","pron":"ek'-stas-is","pos":"Noun Feminine","thayer":"<ol><li>any casting down of a thing from its proper place or state, displacement</li><li>a throwing of the mind out of its normal state, alienation of mind, whether such as makes a lunatic or that of a man who by some sudden emotion is transported as it were out of himself, so that in this rapt condition, although he is awake, his mind is drawn off from all surrounding objects and wholly fixed on things divine that he sees nothing but the forms and images lying within, and thinks that he perceives with his bodily eyes and ears realities shown him by God.</li><li>amazement, the state of one who, either owing to the importance or the novelty of an event, is thrown into a state of blended fear and wonderment</li></ol>","xlit":"ékstasis"},"G975":{"translit":"biblíon","lemma":"βιβλίον","kjv_def":"bill, book, scroll, writing","strongs_def":" a roll","derivation":"a diminutive of G976 (βίβλος);","pron":"bib-lee'-on","pos":"Noun Neuter","thayer":"<ol><li>a small book, a scroll, a written document</li><li>a sheet on which something has been written<ol type='a'><li>a bill of divorcement</li></ol></li></ol>","xlit":"biblíon"},"G238":{"kjv_def":"be an allegory (the Greek word itself)","translit":"allēgoréō","lemma":"ἀλληγορέω","derivation":"from G243 (ἄλλος) and (to harangue (compare G58 (ἀγορά)));","strongs_def":" to allegorize","pron":"al-lay-gor-eh'-o","pos":"Verb","thayer":"<ol><li>to speak allegorically or in a figure</li></ol>","xlit":"allēgoréō"},"G1921":{"kjv_def":"(ac-, have, take)know(-ledge, well), perceive","translit":"epiginṓskō","lemma":"ἐπιγινώσκω","derivation":"from G1909 (ἐπί) and G1097 (γινώσκω);","strongs_def":" to know upon some mark, i.e. recognize; by implication, to become fully acquainted with, to acknowledge","pron":"ep-ig-in-oce'-ko","pos":"Verb","thayer":"<ol><li>to become thoroughly acquainted with, to know thoroughly<ol type='a'><li>to know accurately, know well</li></ol><li>to know<ol type='a'><li>to recognise<ol><li>by sight, hearing, of certain signs, to perceive who a person is</li></ol><li>to know, i.e. to perceive</li><li>to know, i.e. to find out, ascertain</li><li>to know, i.e. to understand</li></ol></li></ol>","xlit":"epiginṓskō"},"G4913":{"lemma":"συνήδομαι","translit":"synḗdomai","kjv_def":"delight","strongs_def":" to rejoice in with oneself, i.e. feel satisfaction concerning","derivation":"middle voice from G4862 (σύν) and the base of G2237 (ἡδονή);","pron":"soon-ay'-dom-ahee","pos":"Verb","thayer":"<ol><li>to rejoice together with (another or others)</li><li>in the NT once to rejoice or delight with one's self or inwardly</li></ol>","xlit":"synḗdomai"},"G4300":{"derivation":"from G4253 (πρό) and G2964 (κυρόω);","strongs_def":" to ratify previously","kjv_def":"confirm before","translit":"prokyróō","lemma":"προκυρόω","pron":"prok-oo-ro'-o","pos":"Verb","thayer":"<ol><li>to sanction, ratify, or establish beforehand</li></ol>","xlit":"prokyróō"},"G2543":{"kjv_def":"although","lemma":"καίτοι","translit":"kaítoi","derivation":"from G2532 (καί) and G5104 (τοί);","strongs_def":" and yet, i.e. nevertheless","pron":"kah'-ee-toy","thayer":"<ol><li>and yet, although</li></ol>","xlit":"kaítoi"},"G1283":{"strongs_def":" to seize asunder, i.e. plunder","derivation":"from G1223 (διά) and G726 (ἁρπάζω);","lemma":"διαρπάζω","translit":"diarpázō","kjv_def":"spoil","pron":"dee-ar-pad'-zo","pos":"Verb","thayer":"<ol><li>to plunder</li></ol>","xlit":"diarpázō"},"G4532":{"translit":"Salḗm","lemma":"Σαλήμ","kjv_def":"Salem","strongs_def":" Salem (i.e. Shalem), a place in Palestine","derivation":"of Hebrew origin (H08004);","pron":"sal-ame'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Salem = \"peace\"</p><ol><li>the place where Melchizedek was king and thought to be the ancient name of Jerusalem</li></ol>","xlit":"Salḗm"},"G4984":{"derivation":"from G4983 (σῶμα);","strongs_def":" corporeal or physical","kjv_def":"bodily","lemma":"σωματικός","translit":"sōmatikós","pron":"so-mat-ee-kos'","pos":"Adjective","thayer":"<ol><li>corporeal, bodily<ol type='a'><li>having a bodily form or nature</li><li>pertaining to the body</li></ol></li></ol>","xlit":"sōmatikós"},"G561":{"strongs_def":" from in front, i.e. opposite, before or against","derivation":"from G575 (ἀπό) and G1725 (ἔναντι);","translit":"apénanti","lemma":"ἀπέναντι","kjv_def":"before, contrary, over against, in the presence of","pron":"ap-en'-an-tee","pos":"Preposition","thayer":"<ol><li>over against, opposite</li><li>in sight of, before</li><li>in opposition to, against</li></ol>","xlit":"apénanti"},"G831":{"kjv_def":"usurp authority over","lemma":"αὐθεντέω","translit":"authentéō","derivation":"from a compound of G846 (αὐτός) and an obsolete (a worker);","strongs_def":" to act of oneself, i.e. (figuratively) dominate","pron":"ow-then-teh'-o","pos":"Verb","thayer":"<ol><li>one who with his own hands kills another or himself</li><li>one who acts on his own authority, autocratic</li><li>an absolute master</li><li>to govern, exercise dominion over one</li></ol>","xlit":"authentéō"},"G3870":{"strongs_def":" to call near, i.e. invite, invoke (by imploration, hortation or consolation)","derivation":"from G3844 (παρά) and G2564 (καλέω);","translit":"parakaléō","lemma":"παρακαλέω","kjv_def":"beseech, call for, (be of good) comfort, desire, (give) exhort(-ation), intreat, pray","pron":"par-ak-al-eh'-o","pos":"Verb","thayer":"<ol><li>to call to one's side, call for, summon</li><li>to address, speak to, (call to, call upon), which may be done in the way of exhortation, entreaty, comfort, instruction, etc.<ol type='a'><li>to admonish, exhort</li><li>to beg, entreat, beseech<ol><li>to strive to appease by entreaty</li></ol><li>to console, to encourage and strengthen by consolation, to comfort<ol><li>to receive consolation, be comforted</li></ol><li>to encourage, strengthen</li><li>exhorting and comforting and encouraging</li><li>to instruct, teach</li></ol></li></ol>","xlit":"parakaléō"},"G2111":{"strongs_def":" well placed, i.e. (figuratively) appropriate","derivation":"from G2095 (εὖ) and a derivative of G5087 (τίθημι);","lemma":"εὔθετος","translit":"eúthetos","kjv_def":"fit, meet","pron":"yoo'-thet-os","pos":"Adjective","thayer":"<ol><li>well placed<ol type='a'><li>fit</li><li>useful</li></ol></li></ol>","xlit":"eúthetos"},"G3741":{"kjv_def":"holy, mercy, shalt be","translit":"hósios","lemma":"ὅσιος","derivation":"of uncertain affinity; properly, right (by intrinsic or divine character; thus distinguished from 1342, which refers rather to human statutes and relations; from G2413 (ἱερός), which denotes formal consecration;","strongs_def":" and from G40 (ἅγιος), which relates to purity from defilement), i.e. hallowed (pious, sacred, sure)","pron":"hos'-ee-os","pos":"Adjective","thayer":"<ol><li>undefiled by sin, free from wickedness, religiously observing every moral obligation, pure holy, pious</li></ol>","xlit":"hósios"},"G1156":{"derivation":"from (a gift);","strongs_def":" probably akin to the base of G1325 (δίδωμι); a loan","kjv_def":"debt","lemma":"δάνειον","translit":"dáneion","pron":"dan'-i-on","pos":"Noun Neuter","thayer":"<ol><li>a loan</li></ol>","xlit":"dáneion"},"G1275":{"translit":"diapantós","lemma":"διαπαντός","kjv_def":"alway(-s), continually","strongs_def":" through all time, i.e. (adverbially) constantly","derivation":"from G1223 (διά) and the genitive case of G3956 (πᾶς);","pron":"dee-ap-an-tos'","pos":"Adverb","thayer":"<ol><li>constantly, always, continually</li></ol>","xlit":"diapantós"},"G1210":{"strongs_def":" to bind (in various applications, literally or figuratively)","derivation":"a primary verb;","translit":"déō","lemma":"δέω","kjv_def":"bind, be in bonds, knit, tie, wind","pron":"deh'-o","pos":"Verb","thayer":"<ol><li>to bind tie, fasten<ol type='a'><li>to bind, fasten with chains, to throw into chains</li><li>metaphorically<ol><li>Satan is said to bind a woman bent together by means of a demon, as his messenger, taking possession of the woman and preventing her from standing upright</li><li>to bind, put under obligation, of the law, duty etc.<ol type='a'><li>to be bound to one, a wife, a husband</li></ol><li>to forbid, prohibit, declare to be illicit</li></ol></li></ol></li></ol>","xlit":"déō"},"G1139":{"lemma":"δαιμονίζομαι","translit":"daimonízomai","kjv_def":"have a (be vexed with, be possessed with) devil(-s)","strongs_def":" to be exercised by a dæmon","derivation":"middle voice from G1142 (δαίμων);","pron":"dahee-mon-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to be under the power of a demon.</li></ol>","xlit":"daimonízomai"},"G2695":{"derivation":"from G2596 (κατά) and G4969 (σφάζω);","strongs_def":" to kill down, i.e. slaughter","kjv_def":"slay","lemma":"κατασφάττω","translit":"kataspháttō","pron":"kat-as-fat'-to","pos":"Verb","thayer":"<ol><li>to kill off, to slaughter</li></ol>","xlit":"kataspháttō"},"G2259":{"kjv_def":"when","lemma":"ἡνίκα","translit":"hēníka","derivation":"of uncertain affinity;","strongs_def":" at which time","pron":"hay-nee'-kah","thayer":"<ol><li>at which time, when</li><li>whenever, at length when</li></ol>","xlit":"hēníka"},"G2799":{"translit":"klaíō","lemma":"κλαίω","kjv_def":"bewail, weep","strongs_def":" to sob, i.e. wail aloud (whereas 1145 is rather to cry silently)","derivation":"of uncertain affinity;","pron":"klah'-yo","pos":"Verb","thayer":"<ol><li>to mourn, weep, lament<ol type='a'><li>weeping as the sign of pain and grief for the thing signified (i.e. for the pain and grief)</li><li>of those who mourn for the dead</li></ol><li>to weep for, mourn for, bewail, one</li></ol>","xlit":"klaíō"},"G2658":{"kjv_def":"attain, come","translit":"katantáō","lemma":"καταντάω","derivation":"from G2596 (κατά) and a derivative of G473 (ἀντί);","strongs_def":" to meet against, i.e. arrive at (literally or figuratively)","pron":"kat-an-tah'-o","pos":"Verb","thayer":"<ol><li>to come to, arrive<ol type='a'><li>to come to a place over against, opposite another</li><li>metaphorically to attain to a thing</li></ol></li></ol>","xlit":"katantáō"},"G1755":{"strongs_def":" an effect","derivation":"from G1754 (ἐνεργέω);","translit":"enérgēma","lemma":"ἐνέργημα","kjv_def":"operation, working","pron":"en-erg'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>thing wrought</li><li>effect operation</li></ol>","xlit":"enérgēma"},"G333":{"kjv_def":"behold, consider","lemma":"ἀναθεωρέω","translit":"anatheōréō","derivation":"from G303 (ἀνά) and G2334 (θεωρέω);","strongs_def":" to look again (i.e. attentively) at (literally or figuratively)","pron":"an-ath-eh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to look at attentively, to consider well, to observe accurately</li></ol>","xlit":"anatheōréō"},"G2644":{"kjv_def":"reconcile","lemma":"καταλλάσσω","translit":"katallássō","derivation":"from G2596 (κατά) and G236 (ἀλλάσσω);","strongs_def":" to change mutually, i.e. (figuratively) to compound a difference","pron":"kat-al-las'-so","pos":"Verb","thayer":"<ol><li>to change, exchange, as coins for others of equivalent value<ol type='a'><li>to reconcile (those who are at variance)</li><li>return to favour with, be reconciled to one</li><li>to receive one into favour</li></ol></li></ol>","xlit":"katallássō"},"G2481":{"kjv_def":"it may be","translit":"ísōs","lemma":"ἴσως","derivation":"adverb from G2470 (ἴσος);","strongs_def":" likely, i.e. perhaps","pron":"ee'-soce","pos":"Adverb","thayer":"<ol><li>equally, in like manner</li><li>agreeably to expectation, i.e. it may be, probably</li></ol>","xlit":"ísōs"},"G2009":{"strongs_def":" properly, esteem, i.e. citizenship; used (in the sense of G2008 (ἐπιτιμάω)) of a penalty","derivation":"from a compound of G1909 (ἐπί) and G5092 (τιμή);","lemma":"ἐπιτιμία","translit":"epitimía","kjv_def":"punishment","pron":"ep-ee-tee-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>punishment</li></ol>","xlit":"epitimía"},"G4858":{"kjv_def":"music","translit":"symphōnía","lemma":"συμφωνία","derivation":"from G4859 (σύμφωνος);","strongs_def":" unison of sound (\"symphony\"), i.e. a concert of instruments (harmonious note)","pron":"soom-fo-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>music</li></ol>","xlit":"symphōnía"},"G5572":{"derivation":"from G5571 (ψευδής) and G1320 (διδάσκαλος);","strongs_def":" a spurious teacher, i.e. propagator of erroneous Christian doctrine","kjv_def":"false teacher","translit":"pseudodidáskalos","lemma":"ψευδοδιδάσκαλος","pron":"psyoo-dod-id-as'-kal-os","pos":"Noun Masculine","thayer":"<ol><li>a false teacher</li></ol>","xlit":"pseudodidáskalos"},"G3521":{"kjv_def":" fast(-ing)","translit":"nēsteía","lemma":"νηστεία","derivation":"from G3522 (νηστεύω);","strongs_def":" abstinence (from lack of food, or voluntary and religious); specially, the fast of the Day of Atonement","pron":"nace-ti'-ah","pos":"Noun Feminine","thayer":"<ol><li>a fasting, fast<ol type='a'><li>a voluntary, as a religious exercise<ol><li>of private fasting</li><li>the public fast as prescribed by the Mosaic Law and kept yearly on the great day of atonement, the tenth of the month of Tisri (the month Tisri comprises a part of our September and October); the fast accordingly, occurred in the autumn when navigation was usually dangerous on account of storms</li></ol><li>a fasting caused by want or poverty</li></ol></li></ol>","xlit":"nēsteía"},"G2453":{"strongs_def":" Judæan, i.e. belonging to Jehudah","derivation":"from G2448 (Ἰουδά) (in the sense of G2455 (Ἰούδας) as a country);","translit":"Ioudaîos","lemma":"Ἰουδαῖος","kjv_def":"Jew(-ess), of Judæa","pron":"ee-oo-dah'-yos","pos":"Adjective","thayer":"<ol><li>Jewish, belonging to the Jewish nation</li><li>Jewish as respects to birth, origin, religion</li></ol>","xlit":"Ioudaîos"},"G2129":{"strongs_def":" fine speaking, i.e. elegance of language; commendation (\"eulogy\"), i.e. (reverentially) adoration; religiously, benediction; by implication, consecration; by extension, benefit or largess","derivation":"from the same as G2127 (εὐλογέω);","lemma":"εὐλογία","translit":"eulogía","kjv_def":"blessing (a matter of) bounty (X -tifully), fair speech","pron":"yoo-log-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>praise, laudation, panegyric: of Christ or God</li><li>fine discourse, polished language<ol type='a'><li>in a bad sense, language artfully adapted to captivate the hearer: fair speaking, fine speeches</li></ol><li>an invocation of blessing, benediction</li><li>consecration</li><li>a (concrete) blessing, benefit</li></ol>","xlit":"eulogía"},"G250":{"translit":"alóē","lemma":"ἀλόη","kjv_def":"aloes","strongs_def":" aloes (the gum)","derivation":"of foreign origin (compare G174 (ἀκάνθινος));","pron":"al-o-ay'","pos":"Noun Feminine","thayer":"<ol><li>aloe, aloes</li></ol>","xlit":"alóē"},"G3690":{"derivation":"from G3691 (ὀξύς);","strongs_def":" vinegar, i.e. sour wine","kjv_def":"vinegar","translit":"óxos","lemma":"ὄξος","pron":"oz-os","pos":"Noun Neuter","thayer":"<ol><li>vinegar<ol type='a'><li>the mixture of sour wine or vinegar and water which the Roman soldiers were accustomed to drink</li></ol></li></ol>","xlit":"óxos"},"G526":{"strongs_def":" to estrange away, i.e. (passively and figuratively) to be non-participant","derivation":"from G575 (ἀπό) and a derivative of G245 (ἀλλότριος);","lemma":"ἀπαλλοτριόω","translit":"apallotrióō","kjv_def":" alienate, be alien","pron":"ap-al-lot-ree-o'-o","pos":"Verb","thayer":"<ol><li>to alienate, estrange</li><li>to be shut out from one's fellowship and intimacy</li></ol>","xlit":"apallotrióō"},"G4658":{"lemma":"Σκύθης","translit":"Skýthēs","kjv_def":"Scythian","strongs_def":" a Scythene or Scythian, i.e. (by implication) a savage","derivation":"probably of foreign origin;","pron":"skoo'-thace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Scythian = \"rude or rough\"</p><ol><li>a Scythian, an inhabitant of Scythia or modern day Russia<ol type='a'><li>by the more civilised nations of antiquity the Scythians were regarded as the wildest of barbarians</li></ol></li></ol>","xlit":"Skýthēs"},"G23":{"derivation":"from (much) and (grief;","strongs_def":" akin to the base of G43 (ἀγκάλη)); to be greatly afflicted, i.e. (figuratively) indignant","kjv_def":"be much (sore) displeased, have (be moved with, with) indignation","lemma":"ἀγανακτέω","translit":"aganaktéō","pron":"ag-an-ak-teh'-o","pos":"Verb","thayer":"<ol><li>to be indignant, moved with indignation, be very displeased</li></ol>","xlit":"aganaktéō"},"G1520":{"derivation":"a primary numeral;","strongs_def":" one","kjv_def":"a(-n, -ny, certain), + abundantly, man, one (another), only, other, some","lemma":"εἷς","translit":"heîs","pron":"hice","thayer":"<ol><li>one</li></ol>","xlit":"heîs"},"G3771":{"lemma":"οὐρανόθεν","translit":"ouranóthen","kjv_def":"from heaven","strongs_def":" from the sky","derivation":"from G3772 (οὐρανός) and the enclitic of source;","pron":"oo-ran-oth'-en","pos":"Adverb","thayer":"<ol><li>from heaven</li></ol>","xlit":"ouranóthen"},"G5320":{"derivation":"adverb from G5318 (φανερός);","strongs_def":" plainly, i.e. clearly or publicly","kjv_def":"evidently, openly","lemma":"φανερῶς","translit":"phanerōs","pron":"fan-er-oce'","pos":"Adverb","thayer":"<ol><li>manifestly<ol type='a'><li>plainly, clearly</li><li>openly</li></ol></li></ol>","xlit":"phanerōs"},"G92":{"kjv_def":"evil doing, iniquity, matter of wrong","translit":"adíkēma","lemma":"ἀδίκημα","derivation":"from G91 (ἀδικέω);","strongs_def":" a wrong done","pron":"ad-eek'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a misdeed, evil doing, iniquity</li></ol>","xlit":"adíkēma"},"G5206":{"derivation":"from a presumed compound of G5207 (υἱός) and a derivative of G5087 (τίθημι);","strongs_def":" the placing as a son, i.e. adoption (figuratively, Christian sonship in respect to God)","kjv_def":"adoption (of children, of sons)","translit":"huiothesía","lemma":"υἱοθεσία","pron":"hwee-oth-es-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>adoption, adoption as sons<ol type='a'><li>that relationship which God was pleased to establish between himself and the Israelites in preference to all other nations</li><li>the nature and condition of the true disciples in Christ, who by receiving the Spirit of God into their souls become sons of God</li><li>the blessed state looked for in the future life after the visible return of Christ from heaven</li></ol></li></ol>","xlit":"huiothesía"},"G71":{"derivation":"a primary verb;","strongs_def":" properly, to lead; by implication, to bring, drive, (reflexively) go, (specially) pass (time), or (figuratively) induce","kjv_def":"be, bring (forth), carry, (let) go, keep, lead away, be open","lemma":"ἄγω","translit":"ágō","pron":"ag'-o","pos":"Verb","thayer":"<ol><li>to lead, take with one<ol type='a'><li>to lead by laying hold of, and this way to bring to the point of destination: of an animal</li><li>to lead by accompanying to (into) a place</li><li>to lead with one's self, attach to one's self as an attendant</li><li>to conduct, bring</li><li>to lead away, to a court of justice, magistrate, etc.</li></ol><li>to lead<ol type='a'><li>to lead, guide, direct</li><li>to lead through, conduct to: to something</li><li>to move, impel: of forces and influences on the mind</li></ol><li>to pass a day, keep or celebrate a feast, etc.</li><li>to go, depart</li></ol>","xlit":"ágō"},"G1717":{"strongs_def":" apparent in self","derivation":"from a compound of G1722 (ἐν) and G5316 (φαίνω);","lemma":"ἐμφανής","translit":"emphanḗs","kjv_def":"manifest, openly","pron":"em-fan-ace'","pos":"Adjective","thayer":"<ol><li>manifest<ol type='a'><li>fig. of God giving proofs of his saving grace and thus manifesting himself</li></ol></li></ol>","xlit":"emphanḗs"},"G4800":{"translit":"syzáō","lemma":"συζάω","kjv_def":"live with","strongs_def":" to continue to live in common with, i.e. co-survive (literally or figuratively)","derivation":"from G4862 (σύν) and G2198 (ζάω);","pron":"sood-zah'-o","pos":"Verb","thayer":"<ol><li>to live together with one<ol type='a'><li>of physical life on earth</li><li>to live a new life in union with Christ, i.e. dedicated to God</li></ol></li></ol>","xlit":"syzáō"},"G1437":{"derivation":"from G1487 (εἰ) and G302 (ἄν);","strongs_def":" a conditional particle; in case that, provided, etc.; often used in connection with other particles to denote indefiniteness or uncertainty","kjv_def":"before, but, except, (and) if, (if) so, (what-, whither-)soever, though, when (-soever), whether (or), to whom, (who-)so(-ever)","lemma":"ἐάν","translit":"eán","pron":"eh-an'","pos":"Conjunction","thayer":"<ol><li>if, in case</li></ol>","xlit":"eán"},"G1148":{"translit":"Dalmanouthá","lemma":"Δαλμανουθά","kjv_def":"Dalmanutha","strongs_def":" Dalmanutha, a place in Palestine","derivation":"probably of Chaldee origin;","pron":"dal-man-oo-thah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Dalmanutha = \"slow firebrand\"</p><ol><li>is a town on the west side of the Sea of Galilee, near Magdala</li></ol>","xlit":"Dalmanouthá"},"G118":{"kjv_def":"strive","lemma":"ἀθλέω","translit":"athléō","derivation":"from (a contest in the public lists);","strongs_def":" to contend in the competitive games","pron":"ath-leh'-o","pos":"Verb","thayer":"<ol><li>to engage in a contest, contend in public games, contend for a prize</li><li>to endure, suffer</li></ol>","xlit":"athléō"},"G265":{"lemma":"ἁμάρτημα","translit":"hamártēma","kjv_def":"sin","strongs_def":" a sin (properly concrete)","derivation":"from G264 (ἁμαρτάνω);","pron":"ham-ar'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>sin, evil deed</li></ol>","xlit":"hamártēma"},"G3913":{"lemma":"παραφρονία","translit":"paraphronía","kjv_def":"madness","strongs_def":" insanity, i.e. foolhardiness","derivation":"from G3912 (παραφρονέω);","pron":"par-af-ron-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>madness, insanity</li></ol>","xlit":"paraphronía"},"G5092":{"strongs_def":" a value, i.e. money paid, or (concretely and collectively) valuables; by analogy, esteem (especially of the highest degree), or the dignity itself","derivation":"from G5099 (τίνω);","lemma":"τιμή","translit":"timḗ","kjv_def":"honour, precious, price, some","pron":"tee-may'","pos":"Noun Feminine","thayer":"<ol><li>a valuing by which the price is fixed<ol type='a'><li>of the price itself</li><li>of the price paid or received for a person or thing bought or sold</li></ol><li>honour which belongs or is shown to one<ol type='a'><li>of the honour which one has by reason of rank and state of office which he holds</li><li>deference, reverence</li></ol></li></ol>","xlit":"timḗ"},"G4651":{"strongs_def":" a \"scorpion\" (from its sting)","derivation":"probably from an obsolete (perhaps strengthened from the base of G4649 (σκοπός) and meaning to pierce);","translit":"skorpíos","lemma":"σκορπίος","kjv_def":"scorpion","pron":"skor-pee'-os","pos":"Noun Masculine","thayer":"<ol><li>a scorpion, the name of a little animal, somewhat resembling a lobster, which in warm regions lurk, especially in stone walls; it has a poisonous sting in its tail</li></ol>","xlit":"skorpíos"},"G5476":{"kjv_def":"on (to) the ground","lemma":"χαμαί","translit":"chamaí","derivation":"adverb perhaps from the base of G5490 (χάσμα) through the idea of a fissure in the soil;","strongs_def":" earthward, i.e. prostrate","pron":"kham-ah'-ee","pos":"Adverb","thayer":"<ol><li>on the ground, on the earth</li><li>to the ground</li></ol>","xlit":"chamaí"},"G5117":{"strongs_def":" a spot (general in space, but limited by occupancy; whereas G5561 (χώρα) is a large but participle locality), i.e. location (as a position, home, tract, etc.); figuratively, condition, opportunity; specially, a scabbard","derivation":"apparently a primary word;","translit":"tópos","lemma":"τόπος","kjv_def":"coast, licence, place, X plain, quarter, + rock, room, where","pron":"top'-os","pos":"Noun Masculine","thayer":"<ol><li>place, any portion or space marked off, as it were from surrounding space<ol type='a'><li>an inhabited place, as a city, village, district</li><li>a place (passage) in a book</li></ol><li>metaphorically<ol type='a'><li>the condition or station held by one in any company or assembly</li><li>opportunity, power, occasion for acting</li></ol></li></ol>","xlit":"tópos"},"G2951":{"derivation":"of foreign origin (compare H03646);","strongs_def":" dill or fennel (\"cummin\")","kjv_def":"cummin","translit":"kýminon","lemma":"κύμινον","pron":"koo'-min-on","pos":"Noun Neuter","thayer":"<ol><li>cummin is a cultivated plant in Palestine with seeds that have a bitter warm taste and an aromatic flavour</li></ol>","xlit":"kýminon"},"G2640":{"strongs_def":" a remainder, i.e. (by implication) a few","derivation":"from G2641 (καταλείπω);","translit":"katáleimma","lemma":"κατάλειμμα","kjv_def":"remnant","pron":"kat-al'-ime-mah","pos":"Noun Neuter","thayer":"<ol><li>remnant, remains</li></ol>","xlit":"katáleimma"},"G235":{"kjv_def":"and, but (even), howbeit, indeed, nay, nevertheless, no, notwithstanding, save, therefore, yea, yet","translit":"allá","lemma":"ἀλλά","derivation":"neuter plural of G243 (ἄλλος);","strongs_def":" properly, other things, i.e. (adverbially) contrariwise (in many relations)","pron":"al-lah'","pos":"Conjunction","thayer":"<ol><li>but<ol type='a'><li>nevertheless, notwithstanding</li><li>an objection</li><li>an exception</li><li>a restriction</li><li>nay, rather, yea, moreover</li><li>forms a transition to the cardinal matter</li></ol></li></ol>","xlit":"allá"},"G3031":{"derivation":"from G3030 (λίβανος);","strongs_def":" frankincense, i.e. (by extension) a censer for burning it","kjv_def":"censer","lemma":"λιβανωτός","translit":"libanōtós","pron":"lib-an-o-tos'","pos":"Noun Masculine","thayer":"<ol><li>the gum exuding from a frankincense tree</li><li>a censer</li></ol>","xlit":"libanōtós"},"G5504":{"strongs_def":" \"yesterday\"; by extension, in time past or hitherto","derivation":"of uncertain derivation;","translit":"chthés","lemma":"χθές","kjv_def":"yesterday","pron":"khthes","pos":"Adverb","thayer":"<ol><li>yesterday</li></ol>","xlit":"chthés"},"G2266":{"strongs_def":" Herodias, a woman of the Heodian family","derivation":"from G2264 (Ἡρώδης);","translit":"Hērōdiás","lemma":"Ἡρωδιάς","kjv_def":"Herodias","pron":"hay-ro-dee-as'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Herodias = \"heroic\"</p><ol><li>daughter of Aristobulus and granddaughter of Herod the Great. She was first married to Herod Philip I, son of Herod the Great, a man in private life; but afterwards formed an unlawful union with Herod Antipas, whom she induced not only to slay John the Baptist but also to make the journey to Rome which ruined him; at last she followed him to exile in Gaul.</li></ol>","xlit":"Hērōdiás"},"G2158":{"kjv_def":"comely, honourable","translit":"euschḗmōn","lemma":"εὐσχήμων","derivation":"from G2095 (εὖ) and G4976 (σχῆμα);","strongs_def":" well-formed, i.e. (figuratively) decorous, noble (in rank)","pron":"yoo-skhay'-mone","pos":"Adjective","thayer":"<ol><li>of elegant figure<ol type='a'><li>shapely, graceful, comely, bearing one's self becomingly in speech or behaviour</li></ol><li>of good standing<ol type='a'><li>honourable, influential, wealthy, respectable</li></ol></li></ol>","xlit":"euschḗmōn"},"G2814":{"strongs_def":" a limb or shoot (as if broken off)","derivation":"from G2806 (κλάω);","lemma":"κλῆμα","translit":"klēma","kjv_def":"branch","pron":"kaly'-mah","pos":"Noun Neuter","thayer":"<ol><li>a tender and flexible branch</li><li>spec. the shoot or branch of a vine, a vine sprout</li></ol>","xlit":"klēma"},"G4276":{"translit":"proelpízō","lemma":"προελπίζω","kjv_def":"first trust","strongs_def":" to hope in advance of other confirmation","derivation":"from G4253 (πρό) and G1679 (ἐλπίζω);","pron":"pro-el-pid'-zo","pos":"Verb","thayer":"<ol><li>to hope before</li></ol>","xlit":"proelpízō"},"G4290":{"derivation":"adverb from G4289 (πρόθυμος);","strongs_def":" with alacrity","kjv_def":"willingly","lemma":"προθύμως","translit":"prothýmōs","pron":"proth-oo'-moce","pos":"Adverb","thayer":"<ol><li>willingly, with alacrity</li></ol>","xlit":"prothýmōs"},"G2988":{"derivation":"adverb from G2986 (λαμπρός);","strongs_def":" brilliantly, i.e. figuratively, luxuriously","kjv_def":"sumptuously","translit":"lamprōs","lemma":"λαμπρῶς","pron":"lam-proce'","pos":"Adverb","thayer":"<ol><li>splendidly, magnificently<ol type='a'><li>of sumptuous living</li></ol></li></ol>","xlit":"lamprōs"},"G4503":{"derivation":"of Hebrew origin (H07327);","strongs_def":" Ruth, a Moabitess","kjv_def":"Ruth","lemma":"Ῥούθ","translit":"Rhoúth","pron":"hrooth","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Ruth = \"a female friend\"</p><ol><li>the ancestor of David and of Christ</li></ol>","xlit":"Rhoúth"},"G1855":{"lemma":"ἔξωθεν","translit":"éxōthen","kjv_def":"out(-side, -ward, - wardly), (from) without","strongs_def":" external(-ly)","derivation":"from G1854 (ἔξω);","pron":"ex'-o-then","pos":"Adverb","thayer":"<ol><li>from without, outward</li></ol>","xlit":"éxōthen"},"G4143":{"translit":"ploîon","lemma":"πλοῖον","kjv_def":"ship(-ing)","strongs_def":" a sailer, i.e. vessel","derivation":"from G4126 (πλέω);","pron":"ploy'-on","pos":"Noun Neuter","thayer":"<ol><li>a ship</li></ol>","xlit":"ploîon"},"G4624":{"strongs_def":" to entrap, i.e. trip up (figuratively, stumble (transitively) or entice to sin, apostasy or displeasure)","derivation":"from G4625 (σκάνδαλον);","translit":"skandalízō","lemma":"σκανδαλίζω","kjv_def":"(make to) offend","pron":"skan-dal-id'-zo","pos":"Verb","thayer":"<ol><li>to put a stumbling block or impediment in the way, upon which another may trip and fall, metaphorically to offend<ol type='a'><li>to entice to sin</li><li>to cause a person to begin to distrust and desert one whom he ought to trust and obey<ol><li>to cause to fall away</li><li>to be offended in one, i.e. to see in another what I disapprove of and what hinders me from acknowledging his authority</li><li>to cause one to judge unfavourably or unjustly of another</li></ol><li>since one who stumbles or whose foot gets entangled feels annoyed<ol><li>to cause one displeasure at a thing</li><li>to make indignant</li><li>to be displeased, indignant</li></ol></li></ol></li></ol>","xlit":"skandalízō"},"G2824":{"kjv_def":"part, region","lemma":"κλίμα","translit":"klíma","derivation":"from G2827 (κλίνω);","strongs_def":" a slope, i.e. (specially) a \"clime\" or tract of country","pron":"klee'-mah","pos":"Noun Neuter","thayer":"<ol><li>an inclination, slope, declivity</li><li>the [supposed] sloping of the earth from the equator towards the poles, a zone</li><li>a tract of land, a region</li></ol>","xlit":"klíma"},"G4571":{"strongs_def":" thee","derivation":"accusative case singular of G4771 (σύ);","lemma":"σέ","translit":"sé","kjv_def":"thee, thou, X thy house","pron":"seh","thayer":"<ol><li>thou, thee</li></ol>","xlit":"sé"},"G1194":{"derivation":"a primary verb;","strongs_def":" properly, to flay, i.e. (by implication) to scourge, or (by analogy) to thrash","kjv_def":"beat, smite","lemma":"δέρω","translit":"dérō","pron":"der'-o","pos":"Verb","thayer":"<ol><li>to flay, skin</li><li>to beat, thrash, smite</li></ol>","xlit":"dérō"},"G4399":{"translit":"prophthánō","lemma":"προφθάνω","kjv_def":"prevent","strongs_def":" to get an earlier start of, i.e. anticipate","derivation":"from G4253 (πρό) and G5348 (φθάνω);","pron":"prof-than'-o","pos":"Verb","thayer":"<ol><li>to come before, to anticipate</li></ol>","xlit":"prophthánō"},"G1934":{"kjv_def":"desire, enquire, seek (after, for)","lemma":"ἐπιζητέω","translit":"epizētéō","derivation":"from G1909 (ἐπί) and G2212 (ζητέω);","strongs_def":" to search (inquire) for; intensively, to demand, to crave","pron":"ep-eed-zay-teh'-o","pos":"Verb","thayer":"<ol><li>to enquire for, seek for, search for, seek diligently</li><li>to wish for, crave</li><li>to demand, clamour for</li></ol>","xlit":"epizētéō"},"G4429":{"lemma":"πτύω","translit":"ptýō","kjv_def":"spit","strongs_def":" to spit","derivation":"a primary verb (compare G4428 (πτύσσω));","pron":"ptoo'-o","pos":"Verb","thayer":"<ol><li>to spit</li></ol>","xlit":"ptýō"},"G3109":{"derivation":"from G3110 (Μακεδών);","strongs_def":" Macedonia, a region of Greece","kjv_def":"Macedonia","lemma":"Μακεδονία","translit":"Makedonía","pron":"mak-ed-on-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Macedonia = \"extended land\"</p><ol><li>a country bounded on the south by Thessaly and Epirus, on the east by Thrace and the Aegean Sea, on the west by Illyria, and on the North by Dardania and Moesia</li></ol>","xlit":"Makedonía"},"G5205":{"derivation":"from a primary (to rain);","strongs_def":" rain, especially a shower","kjv_def":"rain","lemma":"ὑετός","translit":"hyetós","pron":"hoo-et-os'","pos":"Noun Masculine","thayer":"<ol><li>rain</li></ol>","xlit":"hyetós"},"G3919":{"kjv_def":"privily bring in","lemma":"παρεισάγω","translit":"pareiságō","derivation":"from G3844 (παρά) and G1521 (εἰσάγω);","strongs_def":" to lead in aside, i.e. introduce surreptitiously","pron":"par-ice-ag'-o","pos":"Verb","thayer":"<ol><li>to introduce or bring in secretly or craftily</li></ol>","xlit":"pareiságō"},"G5541":{"derivation":"middle voice from G5543 (χρηστός);","strongs_def":" to show oneself useful, i.e. act benevolently","kjv_def":"be kind","translit":"chrēsteúomai","lemma":"χρηστεύομαι","pron":"khraste-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to show one's self mild, to be kind, use kindness</li></ol>","xlit":"chrēsteúomai"},"G704":{"translit":"arḗn","lemma":"ἀρήν","kjv_def":"lamb","strongs_def":" a lamb (as a male)","derivation":"perhaps the same as G730 (ἄῤῥην);","pron":"ar-ane'","pos":"Noun Masculine","thayer":"<ol><li>a sheep, a lamb</li></ol>","xlit":"arḗn"},"G2592":{"derivation":"from G2593 (καρποφόρος);","strongs_def":" to be fertile (literally or figuratively)","kjv_def":"be (bear, bring forth) fruit(-ful)","translit":"karpophoréō","lemma":"καρποφορέω","pron":"kar-pof-or-eh'-o","pos":"Verb","thayer":"<ol><li>to bear fruit</li><li>to bear, bring forth, deeds</li><li>to bear fruit of one's self</li></ol>","xlit":"karpophoréō"},"G2337":{"derivation":"from (the nipple);","strongs_def":" to suckle, (by implication) to suck","kjv_def":"(give) suck(-ling)","translit":"thēlázō","lemma":"θηλάζω","pron":"thay-lad'-zo","pos":"Verb","thayer":"<ol><li>to give the breast, give suck, to suckle</li><li>to suck</li></ol>","xlit":"thēlázō"},"G2423":{"translit":"Iechonías","lemma":"Ἰεχονίας","kjv_def":"Jechonias","strongs_def":" Jechonias (i.e. Jekonjah), an Israelite","derivation":"of Hebrew origin (H03204);","pron":"ee-ekh-on-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jeconiah or Jehoiachin = \"whom Jehovah establishes\"</p><ol><li>was the son of Jehoiakim, and for three months and ten days king of Judah until Nebuchadnezzar carried him into captivity (597 BC)</li></ol>","xlit":"Iechonías"},"G1276":{"strongs_def":" to cross entirely","derivation":"from G1223 (διά) and a derivative of the base of G4008 (πέραν);","translit":"diaperáō","lemma":"διαπεράω","kjv_def":"go over, pass (over), sail over","pron":"dee-ap-er-ah'-o","pos":"Verb","thayer":"<ol><li>to pass over, cross over, i.e. a river, a lake</li></ol>","xlit":"diaperáō"},"G2796":{"derivation":"from G2795 (κινέω);","strongs_def":" a stirring","kjv_def":"moving","translit":"kínēsis","lemma":"κίνησις","pron":"kin'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>a moving, agitation</li></ol>","xlit":"kínēsis"},"G3553":{"strongs_def":" an ailment","derivation":"from G3552 (νοσέω);","translit":"nósēma","lemma":"νόσημα","kjv_def":"disease","pron":"nos'-ay-ma","pos":"Noun Neuter","thayer":"<ol><li>disease, sickness</li></ol>","xlit":"nósēma"},"G1292":{"kjv_def":"space","lemma":"διάστημα","translit":"diástēma","derivation":"from G1339 (διΐστημι);","strongs_def":" an interval","pron":"dee-as'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>an interval, distance, space of time</li></ol>","xlit":"diástēma"},"G3760":{"translit":"oudamōs","lemma":"οὐδαμῶς","kjv_def":"not","strongs_def":" by no means","derivation":"adverb from (the feminine) of G3762 (οὐδείς);","pron":"oo-dam-oce'","pos":"Adverb","thayer":"<ol><li>by no means, in no wise</li></ol>","xlit":"oudamōs"},"G416":{"strongs_def":" to toss with the wind","derivation":"from G417 (ἄνεμος);","translit":"anemízō","lemma":"ἀνεμίζω","kjv_def":"drive with the wind","pron":"an-em-id'-zo","pos":"Verb","thayer":"<ol><li>to agitate or drive by the wind</li></ol>","xlit":"anemízō"},"G2694":{"translit":"katasýrō","lemma":"κατασύρω","kjv_def":"hale","strongs_def":" to drag down, i.e. arrest judicially","derivation":"from G2596 (κατά) and G4951 (σύρω);","pron":"kat-as-oo'-ro","pos":"Verb","thayer":"<ol><li>to draw down, pull down</li><li>to draw along, drag forcibly</li></ol>","xlit":"katasýrō"},"G593":{"strongs_def":" to disapprove, i.e. (by implication) to repudiate","derivation":"from G575 (ἀπό) and G1381 (δοκιμάζω);","lemma":"ἀποδοκιμάζω","translit":"apodokimázō","kjv_def":"disallow, reject","pron":"ap-od-ok-ee-mad'-zo","pos":"Verb","thayer":"<ol><li>to disapprove, reject, repudiate</li></ol>","xlit":"apodokimázō"},"G5164":{"strongs_def":" a wheel (as a runner), i.e. (figuratively) a circuit of physical effects","derivation":"from G5143 (τρέχω);","lemma":"τροχός","translit":"trochós","kjv_def":"course","pron":"trokh-os'","pos":"Noun Neuter","thayer":"<ol><li>a wheel</li></ol>","xlit":"trochós"},"G5425":{"kjv_def":"tremble","lemma":"φρίσσω","translit":"phríssō","derivation":"apparently a primary verb;","strongs_def":" to \"bristle\" or chill, i.e. shudder (fear)","pron":"fris'-so","pos":"Verb","thayer":"<ol><li>to bristle, stiffen stand up</li><li>to shudder, to be struck with extreme fear, to be horrified</li></ol>","xlit":"phríssō"},"G644":{"lemma":"ἀποσκίασμα","translit":"aposkíasma","kjv_def":"shadow","strongs_def":" a shading off, i.e. obscuration","derivation":"from a compound of G575 (ἀπό) and a derivative of G4639 (σκιά);","pron":"ap-os-kee'-as-mah","pos":"Noun Neuter","thayer":"<ol><li>a shade cast by one object on another, a shadow</li></ol>","xlit":"aposkíasma"},"G4245":{"kjv_def":" elder(-est), old","lemma":"πρεσβύτερος","translit":"presbýteros","derivation":"comparative of (elderly);","strongs_def":" older; as noun, a senior; specially, an Israelite Sanhedrist (also figuratively, member of the celestial council) or Christian \"presbyter\"","pron":"pres-boo'-ter-os","pos":"Adjective","thayer":"<ol><li>elder, of age<ol type='a'><li>the elder of two people</li><li>advanced in life, an elder, a senior<ol><li>forefathers</li></ol></li></ol><li>a term of rank or office<ol type='a'><li>among the Jews<ol><li>members of the great council or Sanhedrin (because in early times the rulers of the people, judges, etc., were selected from elderly men)</li><li>of those who in separate cities managed public affairs and administered justice</li></ol><li>among the Christians, those who presided over the assemblies (or churches) The NT uses the term bishop, elders, and presbyters interchangeably</li><li>the twenty four members of the heavenly Sanhedrin or court seated on thrones around the throne of God</li></ol></li></ol>","xlit":"presbýteros"},"G3640":{"derivation":"from G3641 (ὀλίγος) and G4102 (πίστις);","strongs_def":" incredulous, i.e. lacking confidence (in Christ)","kjv_def":"of little faith","lemma":"ὀλιγόπιστος","translit":"oligópistos","pron":"ol-ig-op'-is-tos","pos":"Noun Feminine","thayer":"<ol><li>of little faith, trusting too little</li></ol>","xlit":"oligópistos"},"G1287":{"lemma":"διασκορπίζω","translit":"diaskorpízō","kjv_def":"disperse, scatter (abroad), strew, waste","strongs_def":" to dissipate, i.e. (genitive case) to rout or separate; specially, to winnow; figuratively, to squander","derivation":"from G1223 (διά) and G4650 (σκορπίζω);","pron":"dee-as-kor-pid'-zo","pos":"Verb","thayer":"<ol><li>to scatter abroad, disperse, to winnow<ol type='a'><li>to throw the grain a considerable distance, or up into the air, that it may be separated from the chaff</li><li>to gather the wheat, freed from the chaff into the granary</li><li>to winnow grain</li></ol></li></ol>","xlit":"diaskorpízō"},"G4173":{"kjv_def":"ruler of the city","lemma":"πολιτάρχης","translit":"politárchēs","derivation":"from G4172 (πόλις) and G757 (ἄρχω);","strongs_def":" a town-officer, i.e. magistrate","pron":"pol-it-ar'-khace","pos":"Noun Masculine","thayer":"<ol><li>a ruler of a city or citizens</li></ol>","xlit":"politárchēs"},"G5341":{"strongs_def":" a mantle (surtout)","derivation":"by transposition for a derivative probably of G5316 (φαίνω) (as showing outside the other garments);","translit":"phelónēs","lemma":"φελόνης","kjv_def":" cloke","pron":"fel-on'-ace","pos":"Noun Masculine","thayer":"<ol><li>a travelling cloke, used for protection against stormy weather</li></ol>","xlit":"phelónēs"},"G3735":{"kjv_def":"hill, mount(-ain)","lemma":"ὄρος","translit":"óros","derivation":"probably from an obsolete (to rise or \"rear\";","strongs_def":" perhaps akin to G142 (αἴρω); compare G3733 (ὄρνις)); a mountain (as lifting itself above the plain)","pron":"or'-os","pos":"Noun Neuter","thayer":"<ol><li>a mountain</li></ol>","xlit":"óros"},"G1725":{"derivation":"from G1722 (ἐν) and G473 (ἀντί);","strongs_def":" in front (i.e. figuratively, presence) of","kjv_def":"before","lemma":"ἔναντι","translit":"énanti","pron":"en'-an-tee","pos":"Adverb","thayer":"<ol><li>before</li></ol>","xlit":"énanti"},"G671":{"strongs_def":" the act of using up, i.e. consumption","derivation":"from a compound of G575 (ἀπό) and G5530 (χράομαι);","translit":"apóchrēsis","lemma":"ἀπόχρησις","kjv_def":"using","pron":"ap-okh'-ray-sis","pos":"Noun Feminine","thayer":"<ol><li>abuse, misuse</li></ol>","xlit":"apóchrēsis"},"G133":{"translit":"aínesis","lemma":"αἴνεσις","kjv_def":"praise","strongs_def":" a praising (the act), i.e. (specially) a thank(-offering)","derivation":"from G134 (αἰνέω);","pron":"ah'-ee-nes-is","pos":"Noun Feminine","thayer":"<ol><li>praise, a thank offering</li></ol>","xlit":"aínesis"},"G2764":{"strongs_def":" made of clay, i.e. earthen","derivation":"from G2766 (κέραμος);","translit":"keramikós","lemma":"κεραμικός","kjv_def":"of a potter","pron":"ker-am-ik-os'","pos":"Adjective","thayer":"<ol><li>of or belonging to a potter</li><li>made of clay, earthen</li></ol>","xlit":"keramikós"},"G3423":{"derivation":"from a derivative of G3415 (μνάομαι);","strongs_def":" to give a souvenir (engagement present), i.e. betroth","kjv_def":"espouse","translit":"mnēsteúō","lemma":"μνηστεύω","pron":"mnace-tyoo'-o","pos":"Verb","thayer":"<ol><li>to woo her and ask her in marriage</li><li>to be promised in marriage, be betrothed</li></ol>","xlit":"mnēsteúō"},"G196":{"kjv_def":"most straitest","lemma":"ἀκριβέστατος","translit":"akribéstatos","derivation":"superlative of (a derivative of the same as G206 (ἄκρον));","strongs_def":" most exact","pron":"ak-ree-bes'-ta-tos","pos":"Adjective","thayer":"<ol><li>exact, careful</li><li>of the strictest sect: the most precise and rigorous in interpreting the Mosaic law, and in observing even the more minute precepts of the law and tradition</li></ol>","xlit":"akribéstatos"},"G3956":{"derivation":"including all the forms of declension; apparently a primary word;","strongs_def":" all, any, every, the whole","kjv_def":"all (manner of, means), alway(-s), any (one), X daily, + ever, every (one, way), as many as, + no(-thing), X thoroughly, whatsoever, whole, whosoever","translit":"pâs","lemma":"πᾶς","pron":"pas","pos":"Adjective","thayer":"<ol><li>individually<ol type='a'><li>each, every, any, all, the whole, everyone, all things,everything</li></ol><li>collectively<ol type='a'><li>some of all types</li></ol></li></ol>","xlit":"pâs"},"G5596":{"strongs_def":" a crumb or morsel (as if rubbed off), i.e. a mouthful","derivation":"diminutive from a derivative of the base of G5597 (ψώχω);","translit":"psōmíon","lemma":"ψωμίον","kjv_def":"sop","pron":"pso-mee'-on","pos":"Noun Neuter","thayer":"<ol><li>a fragment, bit, morsel</li></ol>","xlit":"psōmíon"},"G328":{"kjv_def":"gird up","translit":"anazṓnnymi","lemma":"ἀναζώννυμι","derivation":"from G303 (ἀνά) and G2224 (ζώννυμι);","strongs_def":" to gird afresh","pron":"an-ad-zone'-noo-mee","pos":"Verb","thayer":"<ol><li>to gird up</li><li>metaphorically be prepared<ol type='a'><li>a metaphor derived from the practice of the Orientals, who in order to be unimpeded in their movements were accustomed, when starting a journey or engaging in any work, to bind their long flowing garments closely around their bodies and fastened them with a leather belt.</li></ol></li></ol>","xlit":"anazṓnnymi"},"G1377":{"kjv_def":"ensue, follow (after), given to, (suffer) persecute(-ion), press forward","translit":"diṓkō","lemma":"διώκω","derivation":"a prolonged (and causative) form of a primary verb (to flee;","strongs_def":" compare the base of G1169 (δειλός) and G1249 (διάκονος)); to pursue (literally or figuratively); by implication, to persecute","pron":"dee-o'-ko","pos":"Verb","thayer":"<ol><li>to make to run or flee, put to flight, drive away</li><li>to run swiftly in order to catch a person or thing, to run after<ol type='a'><li>to press on: figuratively of one who in a race runs swiftly to reach the goal</li><li>to pursue (in a hostile manner)</li></ol><li>in any way whatever to harass, trouble, molest one<ol type='a'><li>to persecute</li><li>to be mistreated, suffer persecution on account of something</li></ol><li>without the idea of hostility, to run after, follow after: someone</li><li>metaphorically, to pursue<ol type='a'><li>to seek after eagerly, earnestly endeavour to acquire</li></ol></li></ol>","xlit":"diṓkō"},"G2288":{"strongs_def":" (properly, an adjective used as a noun) death (literally or figuratively)","derivation":"from G2348 (θνήσκω);","lemma":"θάνατος","translit":"thánatos","kjv_def":"X deadly, (be…) death","pron":"than'-at-os","pos":"Noun Masculine","thayer":"<ol><li>the death of the body<ol type='a'><li>that separation (whether natural or violent) of the soul and the body by which the life on earth is ended</li><li>with the implied idea of future misery in hell<ol><li>the power of death</li></ol><li>since the nether world, the abode of the dead, was conceived as being very dark, it is equivalent to the region of thickest darkness, i.e. figuratively, a region enveloped in the darkness of ignorance and sin</li></ol><li>metaphorically, the loss of that life which alone is worthy of the name<ol type='a'><li>the misery of the soul arising from sin, which begins on earth but lasts and increases after the death of the body in hell</li></ol><li>the miserable state of the wicked dead in hell</li><li>in the widest sense, death comprising all the miseries arising from sin, as well physical death as the loss of a life consecrated to God and blessed in him on earth, to be followed by wretchedness in hell</li></ol>","xlit":"thánatos"},"G5590":{"kjv_def":"heart (+ -ily), life, mind, soul, + us, + you","translit":"psychḗ","lemma":"ψυχή","derivation":"from G5594 (ψύχω);","strongs_def":" breath, i.e. (by implication) spirit, abstractly or concretely (the animal sentient principle only; thus distinguished on the one hand from G4151 (πνεῦμα), which is the rational and immortal soul; and on the other from G2222 (ζωή), which is mere vitality, even of plants: these terms thus exactly correspond respectively to the Hebrew H05315, H07307 and H02416)","pron":"psoo-khay'","pos":"Noun Feminine","thayer":"<ol><li>breath<ol type='a'><li>the breath of life<ol><li>the vital force which animates the body and shows itself in breathing<ol type='a'><li>of animals</li><li>of men</li></ol></li></ol><li>life</li><li>that in which there is life<ol><li>a living being, a living soul</li></ol></li></ol><li>the soul<ol type='a'><li>the seat of the feelings, desires, affections, aversions (our heart, soul etc.)</li><li>the (human) soul in so far as it is constituted that by the right use of the aids offered it by God it can attain its highest end and secure eternal blessedness, the soul regarded as a moral being designed for everlasting life</li><li>the soul as an essence which differs from the body and is not dissolved by death (distinguished from other parts of the body)</li></ol></li></ol>","xlit":"psychḗ"},"G2343":{"strongs_def":" to amass or reserve (literally or figuratively)","derivation":"from G2344 (θησαυρός);","translit":"thēsaurízō","lemma":"θησαυρίζω","kjv_def":"lay up (treasure), (keep) in store, (heap) treasure (together, up)","pron":"thay-sow-rid'-zo","pos":"Verb","thayer":"<ol><li>to gather and lay up, to heap up, store up<ol type='a'><li>to accumulate riches</li><li>to keep in store, store up, reserve</li></ol><li>metaphorically so to live from day to day as to increase either the bitterness or the happiness of one's consequent lot</li></ol>","xlit":"thēsaurízō"},"G3144":{"strongs_def":" a witness (literally (judicially) or figuratively (genitive case)); by analogy, a \"martyr\"","derivation":"of uncertain affinity;","lemma":"μάρτυς","translit":"mártys","kjv_def":" martyr, record, witness","pron":"mar'-toos","pos":"Noun Masculine","thayer":"<ol><li>a witness<ol type='a'><li>in a legal sense</li><li>an historical sense<ol><li>one who is a spectator of anything, e.g. of a contest</li></ol><li>in an ethical sense<ol><li>those who after his example have proved the strength and genuineness of their faith in Christ by undergoing a violent death</li></ol></li></ol></li></ol>","xlit":"mártys"},"G5157":{"translit":"tropḗ","lemma":"τροπή","kjv_def":"turning","strongs_def":" a turn (\"trope\"), i.e. revolution (figuratively, variation)","derivation":"from an apparently primary to turn;","pron":"trop-ay'","pos":"Noun Feminine","thayer":"<ol><li>a turning<ol type='a'><li>of the heavenly bodies</li></ol></li></ol>","xlit":"tropḗ"},"G3624":{"lemma":"οἶκος","translit":"oîkos","kjv_def":"home, house(-hold), temple","strongs_def":" a dwelling (more or less extensive, literal or figurative); by implication, a family (more or less related, literally or figuratively)","derivation":"of uncertain affinity;","pron":"oy'-kos","pos":"Noun Masculine","thayer":"<ol><li>a house<ol type='a'><li>an inhabited house, home</li><li>any building whatever<ol><li>of a palace</li><li>the house of God, the tabernacle</li></ol><li>any dwelling place<ol><li>of the human body as the abode of demons that possess it</li><li>of tents, and huts, and later, of the nests, stalls, lairs, of animals</li><li>the place where one has fixed his residence, one's settled abode, domicile</li></ol></li></ol><li>the inmates of a house, all the persons forming one family, a household<ol type='a'><li>the family of God, of the Christian Church, of the church of the Old and New Testaments</li></ol><li>stock, family, descendants of one</li></ol>","xlit":"oîkos"},"G4622":{"translit":"Siṓn","lemma":"Σιών","kjv_def":"Sion","strongs_def":" Sion (i.e. Tsijon), a hill of Jerusalem; figuratively, the Church (militant or triumphant)","derivation":"of Hebrew origin (H06726);","pron":"see-own'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sion or Zion = \"a parched place\"</p><ol><li>the hill on which the higher and more ancient part of Jerusalem was built<ol type='a'><li>the southwestern most and highest of the hills on which the city was built</li></ol><li>often used of the entire city of Jerusalem</li><li>since Jerusalem because the temple stood there, was called the dwelling place of God</li></ol>","xlit":"Siṓn"},"G174":{"kjv_def":"of thorns","translit":"akánthinos","lemma":"ἀκάνθινος","derivation":"from G173 (ἄκανθα);","strongs_def":" thorny","pron":"ak-an'-thee-nos","pos":"Adjective","thayer":"<ol><li>thorny, woven out of twigs of a thorny plant</li></ol>","xlit":"akánthinos"},"G3315":{"lemma":"μεσιτεύω","translit":"mesiteúō","kjv_def":"confirm","strongs_def":" to interpose (as arbiter), i.e (by implication) to ratify (as surety)","derivation":"from G3316 (μεσίτης);","pron":"mes-it-yoo'-o","pos":"Verb","thayer":"<ol><li>to act as a mediator between litigating or covenanting parties<ol type='a'><li>to accomplish something by interposing between two parties</li><li>to mediate</li></ol><li>act as a sponsor or surety<ol type='a'><li>to pledge one's self, give surety</li></ol></li></ol>","xlit":"mesiteúō"},"G4266":{"derivation":"from G4253 (πρό) and G1096 (γίνομαι);","strongs_def":" to be already, i.e. have previousy transpired","kjv_def":"be past","translit":"progínomai","lemma":"προγίνομαι","pron":"prog-in'-om-ahee","pos":"Verb","thayer":"<ol><li>to arise or come before, happen before<ol type='a'><li>of sins committed previously</li></ol></li></ol>","xlit":"progínomai"},"G2765":{"lemma":"κεράμιον","translit":"kerámion","kjv_def":"pitcher","strongs_def":" an earthenware vessel, i.e. jar","derivation":"neuter of a presumed derivative of G2766 (κέραμος);","pron":"ker-am'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>an earthen vessel, a pot, jar</li><li>a jug or pitcher</li><li>a water pitcher</li></ol>","xlit":"kerámion"},"G5384":{"lemma":"φίλος","translit":"phílos","kjv_def":"friend","strongs_def":" actively, fond, i.e. friendly (still as a noun, an associate, neighbor, etc.)","derivation":"properly, dear, i.e. a friend;","pron":"fee'-los","pos":"Adjective","thayer":"<ol><li>friend, to be friendly to one, wish him well<ol type='a'><li>a friend</li><li>an associate</li><li>he who associates familiarly with one, a companion</li><li>one of the bridegroom's friends who on his behalf asked the hand of the bride and rendered him various services in closing the marriage and celebrating the nuptials</li></ol></li></ol>","xlit":"phílos"},"G4032":{"derivation":"from G4012 (περί) and G2928 (κρύπτω);","strongs_def":" to conceal all around, i.e. entirely","kjv_def":"hide","translit":"perikrýptō","lemma":"περικρύπτω","pron":"per-ee-kroop'-to","pos":"Verb","thayer":"<ol><li>to conceal on all sides or entirely, to hide, seclude</li></ol>","xlit":"perikrýptō"},"G2641":{"strongs_def":" to leave down, i.e. behind; by implication, to abandon, have remaining","derivation":"from G2596 (κατά) and G3007 (λείπω);","lemma":"καταλείπω","translit":"kataleípō","kjv_def":"forsake, leave, reserve","pron":"kat-al-i'-po","pos":"Verb","thayer":"<ol><li>to leave behind<ol type='a'><li>to depart from, leave<ol><li>to be left</li></ol><li>to bid (one) to remain</li><li>to forsake, leave to one's self a person or thing by ceasing to care for it, to abandon, leave in the lurch<ol><li>to be abandoned, forsaken</li></ol><li>to cause to be left over, to reserve, to leave remaining</li><li>like our \"leave behind\" , it is used of one who on being called away cannot take another with him<ol><li>especially of the dying (to leave behind)</li></ol><li>like our \"leave\" , leave alone, disregard<ol><li>of those who sail past a place without stopping</li></ol></li></ol></li></ol>","xlit":"kataleípō"},"G1848":{"translit":"exouthenéō","lemma":"ἐξουθενέω","kjv_def":"contemptible, despise, least esteemed, set at nought","derivation":"a variation of G1847 (ἐξουδενόω) and meaning the same","pron":"ex-oo-then-eh'-o","pos":"Verb","thayer":"<ol><li>to make of no account, despise utterly</li></ol>","xlit":"exouthenéō"},"G5406":{"translit":"phoneús","lemma":"φονεύς","kjv_def":"murderer","strongs_def":" a murderer (always of criminal (or at least intentional) homicide; which G443 (ἀνθρωποκτόνος) does not necessarily imply; while G4607 (σικάριος) is a special term for a public bandit)","derivation":"from G5408 (φόνος);","pron":"fon-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a murderer, a homicide</li></ol>","xlit":"phoneús"},"G4879":{"derivation":"from G4862 (σύν) and G520 (ἀπάγω);","strongs_def":" to take off together, i.e. transport with (seduce, passively, yield)","kjv_def":"carry (lead) away with, condescend","lemma":"συναπάγω","translit":"synapágō","pron":"soon-ap-ag'-o","pos":"Verb","thayer":"<ol><li>to lead away with or together</li><li>metaphorically to be carried away with<ol type='a'><li>of a thing, i.e. by a thing, so as to experience with others the force of that which carries away</li><li>to yield or submit one's self to lowly things, conditions, employments: not to evade their power</li></ol></li></ol>","xlit":"synapágō"},"G4534":{"derivation":"perhaps of similar origin to G4529 (Σαλαμίς);","strongs_def":" Salmone, a place in Crete","kjv_def":"Salmone","lemma":"Σαλμώνη","translit":"Salmṓnē","pron":"sal-mo'-nay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Salmone = \"clothed\"</p><ol><li>a bold promontory on the east point of the island of Crete</li></ol>","xlit":"Salmṓnē"},"G462":{"kjv_def":"unholy","lemma":"ἀνόσιος","translit":"anósios","derivation":"from G1 (Α) (as a negative particle) and G3741 (ὅσιος);","strongs_def":" wicked","pron":"an-os'-ee-os","pos":"Adjective","thayer":"<ol><li>unholy, impious, wicked</li></ol>","xlit":"anósios"},"G4601":{"kjv_def":"keep close (secret, silence), hold peace","lemma":"σιγάω","translit":"sigáō","derivation":"from G4602 (σιγή);","strongs_def":" to keep silent (transitively or intransitively)","pron":"see-gah'-o","pos":"Verb","thayer":"<ol><li>to keep silence, hold one's peace</li><li>to be kept in silence, be concealed</li></ol>","xlit":"sigáō"},"G4168":{"kjv_def":"flock","lemma":"ποίμνιον","translit":"poímnion","derivation":"neuter of a presumed derivative of G4167 (ποίμνη);","strongs_def":" a flock, i.e. (figuratively) group (of believers)","pron":"poym'-nee-on","pos":"Noun Neuter","thayer":"<ol><li>a flock (especially) of sheep</li><li>a group of Christ's disciples</li><li>bodies of Christian (churches) presided over by elders</li></ol>","xlit":"poímnion"},"G4968":{"derivation":"neuter of a derivative of G4967 (σφαγή);","strongs_def":" a victim (in sacrifice)","kjv_def":"slain beast","lemma":"σφάγιον","translit":"sphágion","pron":"sfag'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>that which is destined for slaughter, a victim</li></ol>","xlit":"sphágion"},"G5364":{"kjv_def":"courteously","translit":"philanthrṓpōs","lemma":"φιλανθρώπως","derivation":"adverb from a compound of G5384 (φίλος) and G444 (ἄνθρωπος);","strongs_def":" fondly to man (\"philanthropically\"), i.e. humanely","pron":"fil-an-thro'-poce","pos":"Adverb","thayer":"<ol><li>humanely, kindly</li></ol>","xlit":"philanthrṓpōs"},"G1039":{"kjv_def":"fine linen","translit":"býssinos","lemma":"βύσσινος","derivation":"from G1040 (βύσσος);","strongs_def":" made of linen (neuter a linen cloth)","pron":"boos'-see-nos","pos":"Adjective","thayer":"<ol><li>a fine linen (garment)</li><li>made of fine linen</li></ol>","xlit":"býssinos"},"G4842":{"kjv_def":"send with","translit":"sympémpō","lemma":"συμπέμπω","derivation":"from G4862 (σύν) and G3992 (πέμπω);","strongs_def":" to despatch in company","pron":"soom-pem'-po","pos":"Verb","thayer":"<ol><li>to send together with</li></ol>","xlit":"sympémpō"},"G4823":{"kjv_def":"consult, (give, take) counsel (together)","lemma":"συμβουλεύω","translit":"symbouleúō","derivation":"from G4862 (σύν) and G1011 (βουλεύω);","strongs_def":" to give (or take) advice jointly, i.e. recommend, deliberate or determine","pron":"soom-bool-yoo'-o","pos":"Verb","thayer":"<ol><li>to give counsel</li><li>to take counsel with others, take counsel together, to consult, deliberate</li></ol>","xlit":"symbouleúō"},"G5209":{"translit":"hymâs","lemma":"ὑμᾶς","kjv_def":"ye, you (+ -ward), your (+ own)","strongs_def":" you (as the objective of a verb or preposition)","derivation":"accusative case of G5210 (ὑμεῖς);","pron":"hoo-mas'","thayer":"<ol><li>you</li></ol>","xlit":"hymâs"},"G4150":{"derivation":"a prolonged form of an obsolete (to \"flow\");","strongs_def":" to \"plunge\", i.e. launder clothing","kjv_def":"wash","lemma":"πλύνω","translit":"plýnō","pron":"ploo'-no","pos":"Verb","thayer":"<ol><li>to wash: with reference to clothing<ol type='a'><li>use figuratively of those who by faith so appropriate the results of Christ's expiation as to be regarded by God as pure and sinless</li></ol></li></ol>","xlit":"plýnō"},"G4042":{"strongs_def":" a being held around, i.e. (concretely) a passage (of Scripture, as circumscribed)","derivation":"from G4023 (περιέχω);","lemma":"περιοχή","translit":"periochḗ","kjv_def":"place","pron":"per-ee-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>an encompassing, compass, circuit</li><li>that which is contained<ol type='a'><li>the contents of any writing</li></ol></li></ol>","xlit":"periochḗ"},"G4776":{"kjv_def":"(make) sit (down) together","lemma":"συγκαθίζω","translit":"synkathízō","derivation":"from G4862 (σύν) and G2523 (καθίζω);","strongs_def":" to give (or take) a seat in company with","pron":"soong-kath-id'-zo","pos":"Verb","thayer":"<ol><li>to cause to sit down together, place together</li><li>to sit down together</li></ol>","xlit":"synkathízō"},"G369":{"derivation":"adverb from G368 (ἀναντίῤῥητος);","strongs_def":" promptly","kjv_def":"without gainsaying","translit":"anantirrhḗtōs","lemma":"ἀναντιῤῥήτως","pron":"an-an-tir-hray'-toce","pos":"Adverb","thayer":"<ol><li>without contradiction</li></ol>","xlit":"anantirrhḗtōs"},"G5121":{"derivation":"contraction for the neuter of G3588 (ὁ) and G1726 (ἐναντίον);","strongs_def":" on the contrary","kjv_def":"contrariwise","translit":"tounantíon","lemma":"τοὐναντίον","pron":"too-nan-tee'-on","pos":"Adverb","thayer":"<ol><li>on the contrary, contrariwise</li></ol>","xlit":"tounantíon"},"G5233":{"strongs_def":" to transcend, i.e. (figuratively) to overreach","derivation":"from G5228 (ὑπέρ) and the base of G939 (βάσις);","lemma":"ὑπερβαίνω","translit":"hyperbaínō","kjv_def":"go beyond","pron":"hoop-er-bah'-ee-no","pos":"Verb","thayer":"<ol><li>to step over, beyond</li><li>metaphorically<ol type='a'><li>to transgress</li><li>to overstep the proper limits</li><li>trespass, do wrong, sin<ol><li>of one who defrauds another in business</li></ol><li>overreaches</li></ol></li></ol>","xlit":"hyperbaínō"},"G5079":{"strongs_def":" an artisan; figuratively, a founder (Creator)","derivation":"from G5078 (τέχνη);","lemma":"τεχνίτης","translit":"technítēs","kjv_def":"builder, craftsman","pron":"tekh-nee'-tace","pos":"Noun Masculine","thayer":"<ol><li>an artificer, craftsman</li></ol>","xlit":"technítēs"},"G2856":{"strongs_def":" to dock, i.e. (figuratively) abridge","derivation":"from a derivative of the base of G2849 (κολάζω);","translit":"kolobóō","lemma":"κολοβόω","kjv_def":"shorten","pron":"kol-ob-o'-o","pos":"Verb","thayer":"<ol><li>to mutilate</li><li>in NT: to shorten, abridge, curtail</li></ol>","xlit":"kolobóō"},"G4120":{"derivation":"a primary word;","strongs_def":" to twine or braid","kjv_def":"plait","lemma":"πλέκω","translit":"plékō","pron":"plek'-o","pos":"Verb","thayer":"<ol><li>to plait, braid, weave together</li></ol>","xlit":"plékō"},"G3887":{"strongs_def":" to stay near, i.e. remain (literally, tarry; or figuratively, be permanent, persevere)","derivation":"from G3844 (παρά) and G3306 (μένω);","translit":"paraménō","lemma":"παραμένω","kjv_def":"abide, continue","pron":"par-am-en'-o","pos":"Verb","thayer":"<ol><li>to remain beside, continue always near</li><li>to survive, remain alive</li></ol>","xlit":"paraménō"},"G5618":{"kjv_def":"(even, like) as","lemma":"ὥσπερ","translit":"hṓsper","derivation":"from G5613 (ὡς) and G4007 (περ);","strongs_def":" just as, i.e. exactly like","pron":"hoce'-per","pos":"Adverb","thayer":"<ol><li>just as, even as</li></ol>","xlit":"hṓsper"},"G5482":{"kjv_def":"trench","translit":"chárax","lemma":"χάραξ","derivation":"from (to sharpen to a point;","strongs_def":" akin to G1125 (γράφω) through the idea of scratching); a stake, i.e. (by implication) a palisade or rampart (military mound for circumvallation in a siege)","pron":"khar'-ax","pos":"Noun Masculine","thayer":"<ol><li>a pale or stake, a palisade</li><li>a palisade or rampart<ol type='a'><li>pales between which earth, stones, trees, and timbers are heaped and packed together</li></ol></li></ol>","xlit":"chárax"},"G1438":{"lemma":"ἑαυτοῦ","translit":"heautoû","kjv_def":"alone, her (own, -self), (he) himself, his (own), itself, one (to) another, our (thine) own(-selves), + that she had, their (own, own selves), (of) them(-selves), they, thyself, you, your (own, own conceits, own selves, -selves)","strongs_def":" him- (her-, it-, them-, also (in conjunction with the personal pronoun of the other persons) my-, thy-, our-, your-) self (selves), etc.","derivation":"from a reflexive pronoun otherwise obsolete and the genitive case (dative case or accusative case) of G846 (αὐτός);","pron":"heh-ow-too'","thayer":"<ol><li>himself, herself, itself, themselves</li></ol>","xlit":"heautoû"},"G1103":{"kjv_def":"own, sincerity, true","translit":"gnḗsios","lemma":"γνήσιος","derivation":"from the same as G1077 (γενέσια);","strongs_def":" legitimate (of birth), i.e. genuine","pron":"gnay'-see-os","pos":"Adjective","thayer":"<ol><li>legitimately born, not spurious</li><li>true, genuine, sincere</li></ol>","xlit":"gnḗsios"},"G5490":{"lemma":"χάσμα","translit":"chásma","kjv_def":"gulf","strongs_def":" a \"chasm\" or vacancy (impassable interval)","derivation":"from a form of an obsolete primary (to \"gape\" or \"yawn\");","pron":"khas'-mah","pos":"Noun Neuter","thayer":"<ol><li>a gaping opening, a chasm, a gulf</li></ol>","xlit":"chásma"},"G2557":{"strongs_def":" a wrong-doer, i.e. criminal","derivation":"from G2556 (κακός) and the base of G2041 (ἔργον);","lemma":"κακοῦργος","translit":"kakoûrgos","kjv_def":"evil-doer, malefactor","pron":"kak-oor'-gos","pos":"Adjective","thayer":"<ol><li>a malefactor</li></ol>","xlit":"kakoûrgos"},"G5017":{"strongs_def":" a disturbance, i.e. (popular) tumult","derivation":"masculine from G5015 (ταράσσω);","translit":"tárachos","lemma":"τάραχος","kjv_def":"stir","pron":"tar'-akh-os","pos":"Noun Masculine","thayer":"<ol><li>commotion, stir (of mind)</li><li>tumult</li></ol>","xlit":"tárachos"},"G4926":{"derivation":"from G4862 (σύν) and G3656 (ὁμιλέω);","strongs_def":" to converse mutually","kjv_def":"talk with","lemma":"συνομιλέω","translit":"synomiléō","pron":"soon-om-il-eh'-o","pos":"Verb","thayer":"<ol><li>to talk with</li></ol>","xlit":"synomiléō"},"G960":{"derivation":"perhaps a provincial from a derivative of G4008 (πέραν) (Perœa, i.e. the region beyond the coast-line);","strongs_def":" Berœa, a place in Macedonia","kjv_def":"Berea","translit":"Béroia","lemma":"Βέροια","pron":"ber'-oy-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Berea = \"well watered\"</p><ol><li>a city in Macedonia, near Pella, at the foot of Mount Bermius</li></ol>","xlit":"Béroia"},"G5242":{"translit":"hyperéchō","lemma":"ὑπερέχω","kjv_def":"better, excellency, higher, pass, supreme","strongs_def":" to hold oneself above, i.e. (figuratively) to excel; participle (as adjective, or neuter as noun) superior, superiority","derivation":"from G5228 (ὑπέρ) and G2192 (ἔχω);","pron":"hoop-er-ekh'-o","pos":"Verb","thayer":"<ol><li>to have or hold over one</li><li>to stand out, rise above, overtop<ol type='a'><li>to be above, be superior in rank, authority, power<ol><li>the prominent men, rulers</li></ol><li>to excel, to be superior, better than, to surpass</li></ol></li></ol>","xlit":"hyperéchō"},"G3848":{"strongs_def":" a violator","derivation":"from G3845 (παραβαίνω);","lemma":"παραβάτης","translit":"parabátēs","kjv_def":"breaker, transgress(-or)","pron":"par-ab-at'-ace","pos":"Noun Masculine","thayer":"<ol><li>a transgressor</li><li>a lawbreaker</li></ol>","xlit":"parabátēs"},"G748":{"strongs_def":" high-priestly","derivation":"from G746 (ἀρχή) and a derivative of G2413 (ἱερός);","lemma":"ἀρχιερατικός","translit":"archieratikós","kjv_def":"of the high-priest","pron":"ar-khee-er-at-ee-kos'","pos":"Adjective","thayer":"<ol><li>high priestly, pontifical</li></ol>","xlit":"archieratikós"},"G4973":{"derivation":"probably strengthened from G5420 (φράσσω);","strongs_def":" a signet (as fencing in or protecting from misappropriation); by implication, the stamp impressed (as a mark of privacy, or genuineness), literally or figuratively","kjv_def":"seal","translit":"sphragís","lemma":"σφραγίς","pron":"sfrag-ece'","pos":"Noun Feminine","thayer":"<ol><li>a seal<ol type='a'><li>the seal placed upon books</li><li>a signet ring</li><li>the inscription or impression made by a seal<ol><li>of the name of God and Christ stamped upon their foreheads</li></ol><li>that by which anything is confirmed, proved, authenticated, as by a seal (a token or proof)</li></ol></li></ol>","xlit":"sphragís"},"G2514":{"derivation":"from G2513 (καθαρός);","strongs_def":" cleanness (ceremonially)","kjv_def":"purification","lemma":"καθαρότης","translit":"katharótēs","pron":"kath-ar-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>cleanness, purity<ol type='a'><li>in a Levitical sense</li></ol></li></ol>","xlit":"katharótēs"},"G3522":{"strongs_def":" to abstain from food (religiously)","derivation":"from G3523 (νῆστις);","lemma":"νηστεύω","translit":"nēsteúō","kjv_def":"fast","pron":"nace-tyoo'-o","pos":"Verb","thayer":"<ol><li>to abstain as a religious exercise from food and drink: either entirely, if the fast lasted but a single day, or from customary and choice nourishment, if it continued several days</li></ol>","xlit":"nēsteúō"},"G202":{"kjv_def":"hearer","translit":"akroatḗs","lemma":"ἀκροατής","derivation":"from (to listen;","strongs_def":" apparently an intensive of G191 (ἀκούω)); a hearer (merely)","pron":"ak-ro-at-ace'","pos":"Noun Masculine","thayer":"<ol><li>a hearer</li></ol>","xlit":"akroatḗs"},"G3800":{"strongs_def":" rations for a soldier, i.e. (by extension) his stipend or pay","derivation":"neuter of a presumed derivative of the same as G3795 (ὀψάριον);","lemma":"ὀψώνιον","translit":"opsṓnion","kjv_def":" wages","pron":"op-so'-nee-on","pos":"Noun Neuter","thayer":"<ol><li>a soldier's pay, allowance<ol type='a'><li>that part of the soldier's support given in place of pay [i.e. rations] and the money in which he is paid</li></ol><li>metaphorically wages: hire or pay of sin</li></ol>","xlit":"opsṓnion"},"G3487":{"derivation":"of foreign origin (compare H05373);","strongs_def":" \"nard\"","kjv_def":"(spike-)nard","translit":"nárdos","lemma":"νάρδος","pron":"nar'dos","pos":"Noun Feminine","thayer":"<ol><li>nard, the head or spike of a fragrant East Indian plant belonging to the genus Valerianna, which yields a juice of delicious odour which the ancients used (either pure or mixed) in the preparation of a most precious ointment</li><li>nard oil or ointment</li></ol>","xlit":"nárdos"},"G2411":{"translit":"hierón","lemma":"ἱερόν","kjv_def":"temple","strongs_def":" a sacred place, i.e. the entire precincts (whereas G3485 (ναός) denotes the central sanctuary itself) of the Temple (at Jerusalem or elsewhere)","derivation":"neuter of G2413 (ἱερός);","pron":"hee-er-on'","pos":"Noun Neuter","thayer":"<ol><li>a sacred place, temple<ol type='a'><li>used of the temple of Artemis at Ephesus</li><li>used of the temple at Jerusalem</li></ol></li></ol>","xlit":"hierón"},"G3443":{"kjv_def":"be desolate","lemma":"μονόω","translit":"monóō","derivation":"from G3441 (μόνος);","strongs_def":" to isolate, i.e. bereave","pron":"mon-o'-o","pos":"Verb","thayer":"<ol><li>to make single or solitary</li><li>leave alone, forsake</li></ol>","xlit":"monóō"},"G5":{"derivation":"of Chaldee origin (H02);","strongs_def":" father as a vocative","kjv_def":"Abba","translit":"Abbâ","lemma":"Ἀββᾶ","pron":"ab-bah'","pos":"Noun","thayer":"<strong>Thayer Definition</strong>: Abba = \"father\"</p><ol><li>father, customary title used of God in prayer. Whenever it occurs in the New Testament it has the Greek interpretation joined to it, that is apparently to be explained by the fact that the Chaldee \"ABBA\" through frequent use in prayer, gradually acquired the nature of a most sacred proper name, to which the Greek speaking Jews added the name from their own tongue.</li></ol>","xlit":"Abbâ"},"G4051":{"translit":"perísseuma","lemma":"περίσσευμα","kjv_def":"abundance, that was left, over and above","strongs_def":" a surplus, or superabundance","derivation":"from G4052 (περισσεύω);","pron":"per-is'-syoo-mah","pos":"Noun Neuter","thayer":"<ol><li>abundance, in which one delights<ol type='a'><li>of that which fills the heart</li></ol><li>that which is left over, residue, remains</li></ol>","xlit":"perísseuma"},"G1518":{"strongs_def":" pacificatory, i.e. (subjectively) peaceable","derivation":"from G1515 (εἰρήνη) and G4160 (ποιέω);","translit":"eirēnopoiós","lemma":"εἰρηνοποιός","kjv_def":"peacemaker","pron":"i-ray-nop-oy-os'","pos":"Adjective","thayer":"<ol><li>a peacemaker</li><li>pacific, loving peace</li></ol>","xlit":"eirēnopoiós"},"G1835":{"translit":"hexḗkonta","lemma":"ἑξήκοντα","kjv_def":"sixty(-fold), threescore","strongs_def":" sixty","derivation":"the tenth multiple of G1803 (ἕξ);","pron":"hex-ay'-kon-tah","pos":"Noun","thayer":"<ol><li>sixty</li></ol>","xlit":"hexḗkonta"},"G2399":{"derivation":"from G2398 (ἴδιος);","strongs_def":" a private person, i.e. (by implication) an ignoramus (compare \"idiot\")","kjv_def":"ignorant, rude, unlearned","translit":"idiṓtēs","lemma":"ἰδιώτης","pron":"id-ee-o'-tace","pos":"Noun Masculine","thayer":"<ol><li>a private person as opposed to a magistrate, ruler, king</li><li>a common soldier, as opposed to a military officer</li><li>a writer of prose as opposed to a poet</li><li>in the NT, an unlearned, illiterate, man as opposed to the learned and educated: one who is unskilled in any art</li></ol>","xlit":"idiṓtēs"},"G775":{"derivation":"from G773 (Ἀσία) and G746 (ἀρχή);","strongs_def":" an Asiarch or president of the public festivities in a city of Asia Minor","kjv_def":"chief of Asia","lemma":"Ἀσιάρχης","translit":"Asiárchēs","pron":"as-ee-ar'-khace","pos":"Noun Masculine","thayer":"<ol><li>an Asiarch, President of Asia.</li></ol>","xlit":"Asiárchēs"},"G5085":{"translit":"Tiberiás","lemma":"Τιβεριάς","kjv_def":"Tiberias","strongs_def":" Tiberias, the name of a town and a lake in Palestine","derivation":"from G5086 (Τιβέριος);","pron":"tib-er-ee-as'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tiberias = \"from the Tiber (as river-god)\"</p><ol><li>a city of Galilee near the Lake of Gennesaret, which Herod Antipas, tetrarch of Galilee, greatly enlarged and beautified, and named Tiberias in honour of Tiberias Caesar</li></ol>","xlit":"Tiberiás"},"G614":{"strongs_def":" secret; by implication, treasured","derivation":"from G613 (ἀποκρύπτω);","translit":"apókryphos","lemma":"ἀπόκρυφος","kjv_def":"hid, kept secret","pron":"ap-ok'-roo-fos","pos":"Adjective","thayer":"<ol><li>hidden, secret</li><li>stored up</li></ol>","xlit":"apókryphos"},"G2566":{"kjv_def":"very well","translit":"kallíon","lemma":"καλλίον","derivation":"neuter of the (irregular) comparative of G2570 (καλός);","strongs_def":" (adverbially) better than many","pron":"kal-lee'-on","xlit":"kallíon"},"G5286":{"kjv_def":"footstool","translit":"hypopódion","lemma":"ὑποπόδιον","derivation":"neuter of a compound of G5259 (ὑπό) and G4228 (πούς);","strongs_def":" something under the feet, i.e. a foot-rest (figuratively)","pron":"hoop-op-od'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a footstool<ol type='a'><li>to make one a footstool of one's feet, i.e. to subject, to reduce under one's power</li><li>metaphorically taken from the practice of conquerors who placed their feet on the necks of their conquered enemies</li></ol></li></ol>","xlit":"hypopódion"},"G4401":{"kjv_def":"choose before","lemma":"προχειροτονέω","translit":"procheirotonéō","derivation":"from G4253 (πρό) and G5500 (χειροτονέω);","strongs_def":" to elect in advance","pron":"prokh-i-rot-on-eh'-o","pos":"Verb","thayer":"<ol><li>to choose or designate beforehand</li></ol>","xlit":"procheirotonéō"},"G4050":{"kjv_def":"abundance(-ant, (-ly)), superfluity","lemma":"περισσεία","translit":"perisseía","derivation":"from G4052 (περισσεύω);","strongs_def":" surplusage, i.e. superabundance","pron":"per-is-si'-ah","pos":"Noun Feminine","thayer":"<ol><li>abundance, superabundantly, superfluously</li><li>superiority, preference, pre-eminence</li><li>gain, profit</li><li>residue, remains: the wickedness remaining over in a Christian from his state prior to conversion</li></ol>","xlit":"perisseía"},"G4335":{"kjv_def":"X pray earnestly, prayer","translit":"proseuchḗ","lemma":"προσευχή","derivation":"from G4336 (προσεύχομαι);","strongs_def":" prayer (worship); by implication, an oratory (chapel)","pron":"pros-yoo-khay'","pos":"Noun Feminine","thayer":"<ol><li>prayer addressed to God</li><li>a place set apart or suited for the offering of prayer<ol type='a'><li>a synagogue</li><li>a place in the open air where the Jews were wont to pray, outside the cities, where they had no synagogue<ol><li>such places were situated upon the bank of a stream or the shore of a sea, where there was a supply of water for washing the hands before prayer</li></ol></li></ol></li></ol>","xlit":"proseuchḗ"},"G3510":{"strongs_def":" a kidney (plural), i.e. (figuratively) the inmost mind","derivation":"of uncertain affinity;","lemma":"νεφρός","translit":"nephrós","kjv_def":"reins","pron":"nef-ros'","pos":"Noun Masculine","thayer":"<ol><li>a kidney</li><li>kidneys, loins<ol type='a'><li>used of the inmost thoughts, feelings, purposes, of the soul</li></ol></li></ol>","xlit":"nephrós"},"G2043":{"translit":"ereídō","lemma":"ἐρείδω","kjv_def":"stick fast","strongs_def":" to prop, i.e. (reflexively) get fast","derivation":"of obscure affinity;","pron":"er-i'-do","pos":"Verb","thayer":"<ol><li>to fix, prop firmly</li></ol>","xlit":"ereídō"},"G3671":{"derivation":"from the same as G3670 (ὁμολογέω);","strongs_def":" acknowledgment","kjv_def":"con- (pro-)fession, professed","lemma":"ὁμολογία","translit":"homología","pron":"hom-ol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>profession<ol type='a'><li>subjectively: whom we profess to be ours</li><li>objectively: profession [confession], i.e. what one professes [confesses]</li></ol></li></ol>","xlit":"homología"},"G548":{"lemma":"ἄπειμι","translit":"ápeimi","kjv_def":"be absent","strongs_def":" to be away","derivation":"from G575 (ἀπό) and G1510 (εἰμί);","pron":"ap'-i-mee","pos":"Verb","thayer":"<ol><li>to go away, depart</li></ol>","xlit":"ápeimi"},"G1233":{"derivation":"from G1231 (διαγινώσκω);","strongs_def":" (magisterial) examination (\"diagnosis\")","kjv_def":"hearing","lemma":"διάγνωσις","translit":"diágnōsis","pron":"dee-ag'-no-sis","pos":"Noun Feminine","thayer":"<ol><li>to distinguish</li><li>in a legal sense, examination, opinion, decision</li></ol>","xlit":"diágnōsis"},"G3005":{"strongs_def":" a remainder","derivation":"from G3007 (λείπω);","translit":"leîmma","lemma":"λεῖμμα","kjv_def":"remnant","pron":"lime'-mah","pos":"Noun Neuter","thayer":"<ol><li>a remnant</li></ol>","xlit":"leîmma"},"G2387":{"lemma":"Ἰαμβρῆς","translit":"Iambrēs","kjv_def":"Jambres","strongs_def":" Jambres, an Egyptian","derivation":"of Egyptian origin;","pron":"ee-am-brace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jambres = \"foamy healer\"</p><ol><li>he and Jannes, were two Egyptian magicians who in the presence of Pharaoh imitated the miracles of Aaron in order to destroy his influence with the king. The author of the epistle derived their names from the tradition of the Talmudists and the Rabbins</li></ol>","xlit":"Iambrēs"},"G2669":{"derivation":"from G2596 (κατά) and a derivative of G4192 (πόνος);","strongs_def":" to labor down, i.e. wear with toil (figuratively, harass)","kjv_def":"oppress, vex","lemma":"καταπονέω","translit":"kataponéō","pron":"kat-ap-on-eh'-o","pos":"Verb","thayer":"<ol><li>to tire down with toil, exhaust with labour<ol type='a'><li>to afflict or oppress with evils</li><li>to make trouble for</li><li>to treat roughly</li></ol></li></ol>","xlit":"kataponéō"},"G1238":{"strongs_def":" a \"diadem\" (as bound about the head)","derivation":"from a compound of G1223 (διά) and G1210 (δέω);","lemma":"διάδημα","translit":"diádēma","kjv_def":"crown","pron":"dee-ad'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a diadem<ol type='a'><li>a blue band marked with white which Persian kings used to bind on the turban or tiara</li><li>the kingly ornament for the head, the crown</li></ol></li></ol>","xlit":"diádēma"},"G4256":{"translit":"proaitiáomai","lemma":"προαιτιάομαι","kjv_def":"prove before","strongs_def":" to accuse already, i.e. previously charge","derivation":"from G4253 (πρό) and a derivative of G156 (αἰτία);","pron":"pro-ahee-tee-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to bring a charge against previously (i.e. in what has previously been said)</li></ol>","xlit":"proaitiáomai"},"G1696":{"kjv_def":"continue","translit":"emménō","lemma":"ἐμμένω","derivation":"from G1722 (ἐν) and G3306 (μένω);","strongs_def":" to stay in the same place, i.e. (figuratively) persevere","pron":"em-men'-o","pos":"Verb","thayer":"<ol><li>to remain in, continue</li><li>to persevere in anything, a state of mind etc.</li><li>to hold fast, to be true to, abide by, keep</li></ol>","xlit":"emménō"},"G2881":{"strongs_def":" a Corinthian, i.e. inhabitant of Corinth","derivation":"from G2882 (Κόρινθος);","translit":"Korínthios","lemma":"Κορίνθιος","kjv_def":"Corinthian","pron":"kor-in'-thee-os","pos":"Noun Masculine","thayer":"<ol><li>a Corinthian, and inhabitant of Corinth</li></ol>","xlit":"Korínthios"},"G1144":{"strongs_def":" a tear","derivation":"of uncertain affinity;","translit":"dákry","lemma":"δάκρυ","kjv_def":"tear","pron":"dak'-roo","pos":"Noun Neuter","thayer":"<ol><li>a tear</li></ol>","xlit":"dákry"},"G383":{"kjv_def":"move, stir up","lemma":"ἀνασείω","translit":"anaseíō","derivation":"from G303 (ἀνά) and G4579 (σείω);","strongs_def":" figuratively, to excite","pron":"an-as-i'-o","pos":"Verb","thayer":"<ol><li>to shake up</li><li>to stir up, excite, rouse</li></ol>","xlit":"anaseíō"},"G1646":{"translit":"eláchistos","lemma":"ἐλάχιστος","kjv_def":"least, very little (small), smallest","strongs_def":" used as equivalent to G3398 (μικρός); least (in size, amount, dignity, etc.)","derivation":"superlative of (short);","pron":"el-akh'-is-tos","pos":"Adjective","thayer":"<ol><li>smallest least<ol type='a'><li>in size</li><li>in amount: of management of affairs</li><li>in importance: what is the least moment</li><li>in authority: of commandments</li><li>in the estimation of men: of persons</li><li>in rank and excellence: of persons</li></ol></li></ol>","xlit":"eláchistos"},"G2635":{"strongs_def":" to be a traducer, i.e. to slander","derivation":"from G2637 (κατάλαλος);","translit":"katalaléō","lemma":"καταλαλέω","kjv_def":"speak against (evil of)","pron":"kat-al-al-eh'-o","pos":"Verb","thayer":"<ol><li>to speak against one, to criminate, traduce</li></ol>","xlit":"katalaléō"},"G3318":{"kjv_def":"Mesopotamia","lemma":"Μεσοποταμία","translit":"Mesopotamía","derivation":"from G3319 (μέσος) and G4215 (ποταμός);","strongs_def":" Mesopotamia (as lying between the Euphrates and the Tigris; compare 0763), a region of Asia","pron":"mes-op-ot-am-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Mesopotamia = \"between two rivers\"</p><ol><li>the entire country between the two rivers, the Tigris and the Euphrates</li></ol>","xlit":"Mesopotamía"},"G1799":{"strongs_def":" in the face of (literally or figuratively)","derivation":"neuter of a compound of G1722 (ἐν) and a derivative of G3700 (ὀπτάνομαι);","lemma":"ἐνώπιον","translit":"enṓpion","kjv_def":"before, in the presence (sight) of, to","pron":"en-o'-pee-on","pos":"Preposition","thayer":"<ol><li>in the presence of, before<ol type='a'><li>of occupied place: in that place which is before, or over against, opposite, any one and towards which another turns his eyes</li></ol></li></ol>","xlit":"enṓpion"},"G3548":{"strongs_def":" legislation (specially, the institution of the Mosaic code)","derivation":"from G3550 (νομοθέτης);","translit":"nomothesía","lemma":"νομοθεσία","kjv_def":"giving of the law","pron":"nom-oth-es-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>law giving, legislation</li></ol>","xlit":"nomothesía"},"G1992":{"translit":"epistolḗ","lemma":"ἐπιστολή","kjv_def":"\"epistle,\" letter","strongs_def":" a written message","derivation":"from G1989 (ἐπιστέλλω);","pron":"ep-is-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a letter, epistle</li></ol>","xlit":"epistolḗ"},"G10":{"kjv_def":"Abiud","translit":"Abioúd","lemma":"Ἀβιούδ","derivation":"of Hebrew origin (H031);","strongs_def":" Abihud, an Israelite","pron":"ab-ee-ood'","pos":"Proper Name Location","thayer":"<strong>Thayer Definition</strong>: Abiud = \"my father is majesty\"</p><ol><li>the son of Bela and grandson of Benjamin (<a class='bible' href='#b13.8.3'>1Ch 8:3</a>)</li></ol>","xlit":"Abioúd"},"G5152":{"translit":"trístegon","lemma":"τρίστεγον","kjv_def":"third loft","strongs_def":" a third roof (story)","derivation":"neuter of a compound of G5140 (τρεῖς) and G4721 (στέγη) as noun;","pron":"tris'-teg-on","pos":"Adjective","thayer":"<ol><li>having three roofs or stories, the third story</li></ol>","xlit":"trístegon"},"G4637":{"derivation":"from G4636 (σκῆνος);","strongs_def":" to tent or encamp, i.e. (figuratively) to occupy (as a mansion) or (specially), to reside (as God did in the Tabernacle of old, a symbol of protection and communion)","kjv_def":" dwell","translit":"skēnóō","lemma":"σκηνόω","pron":"skay-no'-o","pos":"Verb","thayer":"<ol><li>to fix one's tabernacle, have one's tabernacle, abide (or live) in a tabernacle (or tent), tabernacle</li><li>to dwell</li></ol>","xlit":"skēnóō"},"G4164":{"translit":"poikílos","lemma":"ποικίλος","kjv_def":"divers, manifold","strongs_def":" motley, i.e. various in character","derivation":"of uncertain derivation;","pron":"poy-kee'-los","pos":"Adjective","thayer":"<ol><li>a various colours, variegated</li><li>of various sorts</li></ol>","xlit":"poikílos"},"G5564":{"lemma":"χωρίον","translit":"chōríon","kjv_def":"field, land, parcel of ground, place, possession","strongs_def":" a spot or plot of ground","derivation":"diminutive of G5561 (χώρα);","pron":"kho-ree'-on","pos":"Noun Neuter","thayer":"<ol><li>a space, a place, a region, a district</li><li>a piece of ground, a field, land</li></ol>","xlit":"chōríon"},"G2759":{"kjv_def":"prick, sting","translit":"kéntron","lemma":"κέντρον","derivation":"from (to prick);","strongs_def":" a point (\"centre\"), i.e. a sting (figuratively, poison) or goad (figuratively, divine impulse)","pron":"ken'-tron","pos":"Noun Neuter","thayer":"<ol><li>a sting, as that of bees, scorpions, locusts. Since animals wound by their sting and even cause death, Paul attributes death, personified as a sting, i.e. a deadly weapon</li><li>an iron goad, for urging on oxen, horses and other beasts of burden<ol type='a'><li>hence the proverb, \"to kick against the goad\" , i.e. to offer vain and perilous or ruinous resistance</li></ol></li></ol>","xlit":"kéntron"},"G3478":{"derivation":"of uncertain derivation;","strongs_def":" Nazareth or Nazaret, a place in Palestine","kjv_def":"Nazareth","translit":"Nazaréth","lemma":"Ναζαρέθ","pron":"nad-zar-eth'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Nazareth = \"the guarded one\"</p><ol><li>the ordinary residence and home town of Christ</li></ol>","xlit":"Nazaréth"},"G2991":{"derivation":"from a compound of (a stone) and the base of G3584 (ξηρός) (in its original sense of scraping);","strongs_def":" rock-quarried","kjv_def":"hewn in stone","translit":"laxeutós","lemma":"λαξευτός","pron":"lax-yoo-tos'","pos":"Adjective","thayer":"<ol><li>cut out of stone</li></ol>","xlit":"laxeutós"},"G3928":{"derivation":"from G3844 (παρά) and G2064 (ἔρχομαι);","strongs_def":" to come near or aside, i.e. to approach (arrive), go by (or away), (figuratively) perish or neglect, (causative) avert","kjv_def":"come (forth), go, pass (away, by, over), past, transgress","lemma":"παρέρχομαι","translit":"parérchomai","pron":"par-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go past, pass by<ol type='a'><li>of persons moving forward<ol><li>to pass by</li></ol><li>of time<ol><li>an act continuing for a time</li></ol><li>metaphorically<ol><li>to pass away, perish</li><li>to pass by (pass over), that is, to neglect, omit, (transgress)</li><li>to be led by, to be carried past, be averted</li></ol></li></ol><li>to come near, come forward, arrive</li></ol>","xlit":"parérchomai"},"G2322":{"derivation":"from G2323 (θεραπεύω);","strongs_def":" attendance (specially, medical, i.e. cure); figuratively and collectively, domestics","kjv_def":"healing, household","lemma":"θεραπεία","translit":"therapeía","pron":"ther-ap-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>service rendered by one to another</li><li>spec. medical service: curing, healing</li><li>household service<ol type='a'><li>body of attendants, servants, domestics</li></ol></li></ol>","xlit":"therapeía"},"G4928":{"strongs_def":" restraint, i.e. (figuratively) anxiety","derivation":"from G4912 (συνέχω);","translit":"synochḗ","lemma":"συνοχή","kjv_def":"anguish, distress","pron":"soon-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>a holding together, a narrowing</li><li>the contracting part of a way</li><li>metaphorically straits, distress, anguish</li></ol>","xlit":"synochḗ"},"G4177":{"derivation":"from G4172 (πόλις);","strongs_def":" a townsman","kjv_def":"citizen","lemma":"πολίτης","translit":"polítēs","pron":"pol-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a citizen<ol type='a'><li>the inhabitant of any city or country</li><li>the association of another in citizenship<ol><li>a fellow citizen, fellow countryman</li></ol></li></ol></li></ol>","xlit":"polítēs"},"G4304":{"kjv_def":"meditate before","translit":"promeletáō","lemma":"προμελετάω","derivation":"from G4253 (πρό) and G3191 (μελετάω);","strongs_def":" to premeditate","pron":"prom-el-et-ah'-o","pos":"Verb","thayer":"<ol><li>to meditate beforehand</li></ol>","xlit":"promeletáō"},"G5567":{"strongs_def":" compare G5597 (ψώχω)); to twitch or twang, i.e. to play on a stringed instrument (celebrate the divine worship with music and accompanying odes)","derivation":"probably strengthened from (to rub or touch the surface;","translit":"psállō","lemma":"ψάλλω","kjv_def":"make melody, sing (psalms)","pron":"psal'-lo","pos":"Verb","thayer":"<ol><li>to pluck off, pull out</li><li>to cause to vibrate by touching, to twang<ol type='a'><li>to touch or strike the chord, to twang the strings of a musical instrument so that they gently vibrate</li><li>to play on a stringed instrument, to play, the harp, etc.</li><li>to sing to the music of the harp</li><li>in the NT to sing a hymn, to celebrate the praises of God in song</li></ol></li></ol>","xlit":"psállō"},"G1420":{"derivation":"from G1418 (δυσ-) and a comparative of G1787 (ἐντός) (meaning a bowel);","strongs_def":" a \"dysentery\"","kjv_def":"bloody flux","lemma":"δυσεντερία","translit":"dysentería","pron":"doos-en-ter-ee'-ah","pos":"Noun Neuter","thayer":"<ol><li>dysentery, bowel ailment</li></ol>","xlit":"dysentería"},"G1382":{"translit":"dokimḗ","lemma":"δοκιμή","kjv_def":"experience(-riment), proof, trial","strongs_def":" test (abstractly or concretely); by implication, trustiness","derivation":"from the same as G1384 (δόκιμος);","pron":"dok-ee-may'","pos":"Noun Feminine","thayer":"<ol><li>proving, trial</li><li>approved, tried character</li><li>a proof, a specimen of tried worth</li></ol>","xlit":"dokimḗ"},"G1216":{"derivation":"from (Ceres);","strongs_def":" Demetrius, the name of an Ephesian and of a Christian","kjv_def":"Demetrius","translit":"Dēmḗtrios","lemma":"Δημήτριος","pron":"day-may'-tree-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Demetrius = \"belonging to Ceres\"</p><ol><li>a heathen silversmith at Ephesus</li><li>a certain Christian, 3Jo 12</li></ol>","xlit":"Dēmḗtrios"},"G3654":{"derivation":"adverb from G3650 (ὅλος);","strongs_def":" completely, i.e. altogether; (by analogy), everywhere; (negatively) not by any means","kjv_def":"at all, commonly, utterly","translit":"hólōs","lemma":"ὅλως","pron":"hol'-oce","pos":"Adverb","thayer":"<ol><li>wholly, altogether</li></ol>","xlit":"hólōs"},"G2678":{"strongs_def":" to sway downward, i.e. make a signal","derivation":"from G2596 (κατά) and G4579 (σείω);","lemma":"κατασείω","translit":"kataseíō","kjv_def":"beckon","pron":"kat-as-i'-o","pos":"Verb","thayer":"<ol><li>to shake down, throw down</li><li>to shake<ol type='a'><li>to make a sign, to signal with the hand to one</li></ol></li></ol>","xlit":"kataseíō"},"G2229":{"kjv_def":"surely","lemma":"ἦ","translit":"ē","derivation":"an adverb of confirmation; perhaps intensive of G2228 (ἤ); used only (in the New Testament) before G3303 (μέν);","strongs_def":" assuredly","pron":"ay","pos":"Adverb","thayer":"<ol><li>assuredly, most certainly, full surely</li></ol>","xlit":"ē"},"G4505":{"derivation":"prolongation from G4506 (ῥύομαι) in its original sense;","strongs_def":" an alley or avenue (as crowded)","kjv_def":"lane, street","translit":"rhýmē","lemma":"ῥύμη","pron":"hroo'-may","pos":"Noun Feminine","thayer":"<ol><li>a swing, rush, force, trail, of a body in motion</li><li>a tract of way in a town shut in by buildings on both sides</li><li>a street, a lane</li></ol>","xlit":"rhýmē"},"G3360":{"strongs_def":" as far as, i.e. up to a certain point (as a preposition, of extent (denoting the terminus, whereas G891 (ἄχρι) refers especially to the space of time or place intervening) or conjunction)","derivation":"from G3372 (μῆκος);","translit":"méchri","lemma":"μέχρι","kjv_def":"till, (un-)to, until","pron":"mekh'-ree","thayer":"<ol><li>as far as, until</li></ol>","xlit":"méchri"},"G4424":{"lemma":"Πτολεμαΐς","translit":"Ptolemaḯs","kjv_def":"Ptolemais","strongs_def":" Ptolemais, a place in Palestine","derivation":"from (Ptolemy, after whom it was named);","pron":"ptol-em-ah-is'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Ptolemais or Accho = \"warlike\"</p><ol><li>a maritime city of Phoenicia, which got its name, apparently, from Ptolemy Lathyrus, who captured it 103 BC, and rebuilt it more beautifully</li></ol>","xlit":"Ptolemaḯs"},"G2699":{"strongs_def":" a cutting down (off), i.e. mutilation (ironically)","derivation":"from a compound of G2596 (κατά) and (to cut);","translit":"katatomḗ","lemma":"κατατομή","kjv_def":"concision","pron":"kat-at-om-ay'","pos":"Noun Feminine","thayer":"<ol><li>to cut up, mutilation</li></ol>","xlit":"katatomḗ"},"G2309":{"kjv_def":"desire, be disposed (forward), intend, list, love, mean, please, have rather, (be) will (have, -ling, - ling(-ly))","translit":"thélō","lemma":"θέλω","derivation":"apparently strengthened from the alternate form of G138 (αἱρέομαι);","strongs_def":" to determine (as an active option from subjective impulse; whereas G1014 (βούλομαι) properly denotes rather a passive acquiescence in objective considerations), i.e. choose or prefer (literally or figuratively); by implication, to wish, i.e. be inclined to (sometimes adverbially, gladly); impersonally for the future tense, to be about to; by Hebraism, to delight in","pron":"thel'-o","pos":"Verb","thayer":"<ol><li>to will, have in mind, intend<ol type='a'><li>to be resolved or determined, to purpose</li><li>to desire, to wish</li><li>to love<ol><li>to like to do a thing, be fond of doing</li></ol><li>to take delight in, have pleasure</li></ol></li></ol>","xlit":"thélō"},"G5193":{"lemma":"ὑάλινος","translit":"hyálinos","kjv_def":"of glass","strongs_def":" glassy, i.e. transparent","derivation":"from G5194 (ὕαλος);","pron":"hoo-al'-ee-nos","pos":"Adjective","thayer":"<ol><li>of glass or transparent like glass, glassy</li></ol>","xlit":"hyálinos"},"G3388":{"kjv_def":"womb","lemma":"μήτρα","translit":"mḗtra","derivation":"from G3384 (μήτηρ);","strongs_def":" the matrix","pron":"may'-trah","pos":"Noun Feminine","thayer":"<ol><li>the womb</li></ol>","xlit":"mḗtra"},"G4860":{"strongs_def":" to compute jointly","derivation":"from G4862 (σύν) and G5585 (ψηφίζω);","lemma":"συμψηφίζω","translit":"sympsēphízō","kjv_def":"reckon","pron":"soom-psay-fid'-zo","pos":"Verb","thayer":"<ol><li>to compute, count up</li><li>to vote with one</li></ol>","xlit":"sympsēphízō"},"G3587":{"strongs_def":" to shave or \"shear\" the hair","derivation":"from a derivative of the same as G3586 (ξύλον) (meaning a razor);","lemma":"ξυράω","translit":"xyráō","kjv_def":"shave","pron":"xoo-rah'-o","pos":"Verb","thayer":"<ol><li>to shear, shave</li><li>to get one's self shaved</li></ol>","xlit":"xyráō"},"G4672":{"kjv_def":"Solomon","translit":"Solomṓn","lemma":"Σολομών","derivation":"of Hebrew origin (H08010);","strongs_def":" Solomon (i.e. Shelomoh), the son of David","pron":"sol-om-one'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Solomon = \"peaceful\"</p><ol><li>the son of David and was the wisest and richest king that ever lived</li></ol>","xlit":"Solomṓn"},"G2463":{"translit":"îris","lemma":"ἶρις","kjv_def":"rainbow","strongs_def":" a rainbow (\"iris\")","derivation":"perhaps from G2046 (ἐρέω) (as a symbol of the female messenger of the pagan deities);","pron":"ee'-ris","pos":"Noun Feminine","thayer":"<ol><li>a rainbow</li></ol>","xlit":"îris"},"G3545":{"kjv_def":"lawfully","translit":"nomímōs","lemma":"νομίμως","derivation":"adverb from a derivative of G3551 (νόμος);","strongs_def":" legitimately (specially, agreeably to the rules of the lists)","pron":"nom-im'-oce","pos":"Noun Masculine","thayer":"<ol><li>lawfully, agreeable to the law, properly</li></ol>","xlit":"nomímōs"},"G723":{"derivation":"from (to till);","strongs_def":" a plow","kjv_def":"plough","lemma":"ἄροτρον","translit":"árotron","pron":"ar'-ot-ron","pos":"Noun Neuter","thayer":"<ol><li>a plough</li></ol>","xlit":"árotron"},"G891":{"derivation":"akin to G206 (ἄκρον) (through the idea of a terminus);","strongs_def":" (of time) until or (of place) up to","kjv_def":"as far as, for, in(-to), till, (even, un-)to, until, while","translit":"áchri","lemma":"ἄχρι","pron":"akh'-ree","thayer":"<ol><li>until, unto, etc.</li></ol>","xlit":"áchri"},"G403":{"lemma":"ἀνάψυξις","translit":"anápsyxis","kjv_def":"revival","strongs_def":" properly, a recovery of breath, i.e. (figuratively) revival","derivation":"from G404 (ἀναψύχω);","pron":"an-aps'-ook-sis","pos":"Noun Feminine","thayer":"<ol><li>a cooling, refreshing</li></ol>","xlit":"anápsyxis"},"G4430":{"translit":"ptōma","lemma":"πτῶμα","kjv_def":"dead body, carcase, corpse","strongs_def":" a ruin, i.e. (specially), lifeless body (corpse, carrion)","derivation":"from the alternate of G4098 (πίπτω);","pron":"pto'-mah","pos":"Noun Neuter","thayer":"<ol><li>a fall, downfall<ol type='a'><li>metaphorically a failure, defeat, calamity</li><li>an error, lapse into sin</li></ol><li>that which has fallen<ol type='a'><li>the fallen body of one dead or slain, a corpse, a carcase</li></ol></li></ol>","xlit":"ptōma"},"G4659":{"lemma":"σκυθρωπός","translit":"skythrōpós","kjv_def":"of a sad countenance","strongs_def":" angry-visaged, i.e. gloomy or affecting a mournful appearance","derivation":"from (sullen) and a derivative of G3700 (ὀπτάνομαι);","pron":"skoo-thro-pos'","pos":"Adjective","thayer":"<ol><li>of a sad and gloomy countenance</li></ol>","xlit":"skythrōpós"},"G3178":{"translit":"méthē","lemma":"μέθη","kjv_def":"drunkenness","strongs_def":" an intoxicant, i.e. (by implication) intoxication","derivation":"apparently a primary word;","pron":"meth'-ay","pos":"Noun Feminine","thayer":"<ol><li>intoxication</li><li>drunkenness</li></ol>","xlit":"méthē"},"G3122":{"derivation":"neuter plural of the superlative of an apparently primary adverb (very);","strongs_def":" (adverbially) most (in the greatest degree) or particularly","kjv_def":"chiefly, most of all, (e-)specially","translit":"málista","lemma":"μάλιστα","pron":"mal'-is-tah","pos":"Adverb","thayer":"<ol><li>especially, chiefly, most of all, above all</li></ol>","xlit":"málista"},"G3925":{"kjv_def":"army, camp, castle","lemma":"παρεμβολή","translit":"parembolḗ","derivation":"from a compound of G3844 (παρά) and G1685 (ἐμβάλλω);","strongs_def":" a throwing in beside (juxtaposition), i.e. (specially), battle-array, encampment or barracks (tower Antonia)","pron":"par-em-bol-ay'","pos":"Noun Feminine","thayer":"<ol><li>an encampment<ol type='a'><li>the camp of Israel in the desert<ol><li>used for the city of Jerusalem, inasmuch as that was to the Israelites what formerly the encampment had been in the desert</li><li>of the sacred congregation or assembly of Israel, as it had been gathered formerly in camps in the wilderness</li></ol><li>the barracks of the Roman soldiers, which at Jerusalem were in the castle of Antonia</li></ol><li>an army in a line of battle</li></ol>","xlit":"parembolḗ"},"G3694":{"kjv_def":"after, back(-ward), (+ get) behind, + follow","lemma":"ὀπίσω","translit":"opísō","derivation":"from the same as G3693 (ὄπισθεν) with enclitic of direction;","strongs_def":" to the back, i.e. aback (as adverb or preposition of time or place; or as noun)","pron":"op-is'-o","pos":"Adverb","thayer":"<ol><li>back, behind, after, afterwards<ol type='a'><li>of place: things that are behind</li><li>of time: after</li></ol></li></ol>","xlit":"opísō"},"G528":{"kjv_def":"meet","translit":"apantáō","lemma":"ἀπαντάω","derivation":"from G575 (ἀπό) and a derivative of G473 (ἀντί);","strongs_def":" to meet away, i.e. encounter","pron":"ap-an-tah'-o","pos":"Verb","thayer":"<ol><li>to go to meet, to meet<ol type='a'><li>in a military sense: a hostile meeting</li></ol></li></ol>","xlit":"apantáō"},"G2487":{"kjv_def":"step","translit":"íchnos","lemma":"ἴχνος","derivation":"from (to arrive;","strongs_def":" compare G2240 (ἥκω)); a track (figuratively)","pron":"ikh'-nos","pos":"Noun Neuter","thayer":"<ol><li>a footprint, track, footstep</li><li>in the NT, metaphorically of imitating the example of any one</li></ol>","xlit":"íchnos"},"G1890":{"derivation":"from G1909 (ἐπί) and G875 (ἀφρίζω);","strongs_def":" to foam upon, i.e. (figuratively) to exhibit (a vile passion)","kjv_def":"foam out","translit":"epaphrízō","lemma":"ἐπαφρίζω","pron":"ep-af-rid'-zo","pos":"Verb","thayer":"<ol><li>to foam up</li><li>to cast out as foam, foam out</li></ol>","xlit":"epaphrízō"},"G909":{"derivation":"from G907 (βαπτίζω);","strongs_def":" ablution (ceremonial or Christian)","kjv_def":"baptism, washing","lemma":"βαπτισμός","translit":"baptismós","pron":"bap-tis-mos'","pos":"Noun Masculine","thayer":"<ol><li>a washing, purification effected by means of water<ol type='a'><li>of washing prescribed by the Mosaic law (<a class='bible' href='#b58.9.10'>Heb 9:10</a>) which seems to mean an exposition of the difference between the washings prescribed by the Mosaic law and Christian baptism</li></ol></li></ol>","xlit":"baptismós"},"G2537":{"kjv_def":"new","translit":"kainós","lemma":"καινός","derivation":"of uncertain affinity; new (especially in freshness; while G3501 (νέος) is properly so with respect to age","pron":"kahee-nos'","pos":"Adjective","thayer":"<ol><li>new<ol type='a'><li>as respects form<ol><li>recently made, fresh, recent, unused, unworn</li></ol><li>as respects substance<ol><li>of a new kind, unprecedented, novel, uncommon, unheard of</li></ol></li></ol></li></ol>","xlit":"kainós"},"G1007":{"kjv_def":"Bosor","lemma":"Βοσόρ","translit":"Bosór","derivation":"of Hebrew origin (H01160);","strongs_def":" Bosor (i.e. Beor), a Moabite","pron":"bos-or'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Bosor = \"burning or torch\"</p><ol><li>the father of Balaam</li></ol>","xlit":"Bosór"},"G2961":{"kjv_def":"have dominion over, lord, be lord of, exercise lordship over","translit":"kyrieúō","lemma":"κυριεύω","derivation":"from G2962 (κύριος);","strongs_def":" to rule","pron":"ko-ree-yoo'-o","pos":"Verb","thayer":"<ol><li>to be lord of, to rule, have dominion over</li><li>of things and forces<ol type='a'><li>to exercise influence upon, to have power over</li></ol></li></ol>","xlit":"kyrieúō"},"G929":{"translit":"basanismós","lemma":"βασανισμός","kjv_def":"torment","strongs_def":" torture","derivation":"from G928 (βασανίζω);","pron":"bas-an-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>to torture, a testing by the touchstone, which is a black siliceous stone used to test the purity of gold or silver by the colour of the streak produced on it by rubbing it with either metal</li><li>torment, torture<ol type='a'><li>the act of tormenting</li><li>the state or condition of those tormented</li></ol></li></ol>","xlit":"basanismós"},"G3815":{"kjv_def":"play","lemma":"παίζω","translit":"paízō","derivation":"from G3816 (παῖς);","strongs_def":" to sport (as a boy)","pron":"paheed'-zo","pos":"Verb","thayer":"<ol><li>to play like a child</li><li>to play, sport, jest</li><li>to give way to hilarity, especially by joking singing, dancing</li></ol>","xlit":"paízō"},"G3793":{"lemma":"ὄχλος","translit":"óchlos","kjv_def":"company, multitude, number (of people), people, press","strongs_def":" a throng (as borne along); by implication, the rabble; by extension, a class of people; figuratively, a riot","derivation":"from a derivative of G2192 (ἔχω) (meaning a vehicle);","pron":"okh'los","pos":"Noun Masculine","thayer":"<ol><li>a crowd<ol type='a'><li>a casual collection of people<ol><li>a multitude of men who have flocked together in some place</li><li>a throng</li></ol><li>a multitude<ol><li>the common people, as opposed to the rulers and leading men</li><li>with contempt: the ignorant multitude, the populace</li></ol><li>a multitude<ol><li>the multitudes, seems to denote troops of people gathered together without order</li></ol></li></ol></li></ol>","xlit":"óchlos"},"G4226":{"strongs_def":" as adverb of place; at (by implication, to) what locality","derivation":"genitive case of an interrogative pronoun (what) otherwise obsolete (perhaps the same as G4225 (πού) used with the rising slide of inquiry);","lemma":"ποῦ","translit":"poû","kjv_def":"where, whither","pron":"poo","pos":"Adverb","thayer":"<ol><li>somewhere</li><li>nearly</li><li>with numerals: somewhere about, about</li></ol>","xlit":"poû"},"G4465":{"lemma":"ῥαβδοῦχος","translit":"rhabdoûchos","kjv_def":"serjeant","strongs_def":" a rod- (the Latin fasces) holder, i.e. a Roman lictor (constable or executioner)","derivation":"from G4464 (ῥάβδος) and G2192 (ἔχω);","pron":"hrab-doo'-khos","pos":"Noun Masculine","thayer":"<ol><li>one who carries the rods, i.e. the fasces</li><li>a lictor, a public official who bore the fasces or staff and other insignia of office before a magistrate</li></ol>","xlit":"rhabdoûchos"},"G3331":{"lemma":"μετάθεσις","translit":"metáthesis","kjv_def":"change, removing, translation","strongs_def":" transposition, i.e. transferral (to heaven), disestablishment (of a law)","derivation":"from G3346 (μετατίθημι);","pron":"met-ath'-es-is","pos":"Noun Feminine","thayer":"<ol><li>transfer: from one place to another</li><li>to change<ol type='a'><li>of things instituted or established</li></ol></li></ol>","xlit":"metáthesis"},"G1974":{"derivation":"from G1971 (ἐπιποθέω);","strongs_def":" intense longing","kjv_def":"great desire","lemma":"ἐπιποθία","translit":"epipothía","pron":"ep-ee-poth-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>longing</li></ol>","xlit":"epipothía"},"G2909":{"derivation":"comparative of a derivative of G2904 (κράτος);","strongs_def":" stronger, i.e. (figuratively) better, i.e. nobler","kjv_def":"best, better","translit":"kreíttōn","lemma":"κρείττων","pron":"krite'-tohn","pos":"Adjective","thayer":"<ol><li>more useful, more serviceable, more advantageous</li><li>more excellent</li></ol>","xlit":"kreíttōn"},"G3838":{"lemma":"παντελής","translit":"pantelḗs","kjv_def":"+ in (no) wise, uttermost","strongs_def":" full-ended, i.e. entire (neuter as noun, completion)","derivation":"from G3956 (πᾶς) and G5056 (τέλος);","pron":"pan-tel-ace'","pos":"Adjective","thayer":"<ol><li>all complete, perfect</li><li>completely, perfectly, utterly</li></ol>","xlit":"pantelḗs"},"G856":{"strongs_def":" a place of sitting apart, i.e. a privy","derivation":"from a compound of G575 (ἀπό) and the base of G1476 (ἑδραῖος);","translit":"aphedrṓn","lemma":"ἀφεδρών","kjv_def":"draught","pron":"af-ed-rone'","pos":"Noun Masculine","thayer":"<ol><li>a place where the human waste discharges are dumped<ol type='a'><li>a privy, sink, toilet</li></ol></li></ol>","xlit":"aphedrṓn"},"G179":{"kjv_def":"endless","lemma":"ἀκατάλυτος","translit":"akatálytos","derivation":"from G1 (Α) (as a negative particle) and a derivative of G2647 (καταλύω);","strongs_def":" indissoluble, i.e. (figuratively) permanent","pron":"ak-at-al'-oo-tos","pos":"Adjective","thayer":"<ol><li>indissoluble, not subject to destruction</li></ol>","xlit":"akatálytos"},"G862":{"lemma":"ἄφθαρτος","translit":"áphthartos","kjv_def":"not (in-, un-)corruptible, immortal","strongs_def":" undecaying (in essence or continuance)","derivation":"from G1 (Α) (as a negative particle) and a derivative of G5351 (φθείρω);","pron":"af'-thar-tos","pos":"Adjective","thayer":"<ol><li>uncorrupted, not liable to corruption or decay, imperishable<ol type='a'><li>of things</li></ol><li>immortal<ol type='a'><li>of the risen dead</li></ol></li></ol>","xlit":"áphthartos"},"G3098":{"kjv_def":"Magog","lemma":"Μαγώγ","translit":"Magṓg","derivation":"of Hebrew origin (H04031);","strongs_def":" Magog, a foreign nation, i.e. (figuratively) an Antichristian party","pron":"mag-ogue'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Magog = \"overtopping: covering\"</p><ol><li>a land north of Israel from which the King of Gog will come to attack Israel</li></ol>","xlit":"Magṓg"},"G1708":{"derivation":"from G1707 (ἐμπλέκω);","strongs_def":" elaborate braiding of the hair","kjv_def":"plaiting","lemma":"ἐμπλοκή","translit":"emplokḗ","pron":"em-plok-ay'","pos":"Noun Feminine","thayer":"<ol><li>an interweaving, braiding, a knot</li><li>an elaborate gathering of one's hair into knots</li></ol>","xlit":"emplokḗ"},"G146":{"kjv_def":"given to (greedy of) filthy lucre","lemma":"αἰσχροκερδής","translit":"aischrokerdḗs","derivation":"from G150 (αἰσχρός) and (gain);","strongs_def":" sordid","pron":"ahee-skhrok-er-dace'","pos":"Adjective","thayer":"<ol><li>eager for base gain, greedy for money</li></ol>","xlit":"aischrokerdḗs"},"G5478":{"translit":"Chanaanaîos","lemma":"Χανααναῖος","kjv_def":"of Canaan","strongs_def":" a Chanaanæan (i.e. Kenaanite), or native of gentile Palestine","derivation":"from G5477 (Χαναάν);","pron":"khan-ah-an-ah'-yos","pos":"Adjective","thayer":"<ol><li>Canaanite, the name of the ancient inhabitants of Palestine before its conquest by the Israelites</li><li>in Christ's time: a Phoenician</li></ol>","xlit":"Chanaanaîos"},"G5392":{"strongs_def":" to muzzle","derivation":"from (a muzzle);","translit":"phimóō","lemma":"φιμόω","kjv_def":"muzzle","pron":"fee-mo'-o","pos":"Verb","thayer":"<ol><li>to close the mouth with a muzzle, to muzzle</li><li>metaphorically<ol type='a'><li>to stop the mouth, make speechless, reduce to silence</li><li>to become speechless</li></ol><li>to be kept in check</li></ol>","xlit":"phimóō"},"G5602":{"kjv_def":"here, hither, (in) this place, there","lemma":"ὧδε","translit":"hōde","derivation":"from an adverb form of G3592 (ὅδε);","strongs_def":" in this same spot, i.e. here or hither","pron":"ho'-deh","pos":"Adverb","thayer":"<ol><li>here, to this place, etc.</li></ol>","xlit":"hōde"},"G1632":{"translit":"ekchéō","lemma":"ἐκχέω","kjv_def":"gush (pour) out, run greedily (out), shed (abroad, forth), spill","strongs_def":" to pour forth; figuratively, to bestow","derivation":"from G1537 (ἐκ) and (to pour);","pron":"ek-kheh'-o","pos":"Verb","thayer":"<ol><li>to pour out, shed forth</li><li>metaphorically to bestow or distribute largely</li></ol>","xlit":"ekchéō"},"G246":{"derivation":"from G243 (ἄλλος) and G5443 (φυλή);","strongs_def":" foreign, i.e. (specially) Gentile","kjv_def":"one of another nation","lemma":"ἀλλόφυλος","translit":"allóphylos","pron":"al-lof'-oo-los","pos":"Adjective","thayer":"<ol><li>foreign</li></ol>","xlit":"allóphylos"},"G915":{"lemma":"βάρβαρος","translit":"bárbaros","kjv_def":"barbarian(-rous)","strongs_def":" a foreigner (i.e. non-Greek)","derivation":"of uncertain derivation;","pron":"bar'-bar-os","pos":"Adjective","thayer":"<ol><li>one whose speech is rude, rough and harsh</li><li>one who speaks a foreign or strange language which is not understood by another</li><li>used by the Greeks of any foreigner ignorant of the Greek language, whether mental or moral, with the added notion after the Persian war, of rudeness and brutality. The word is used in the N.T. without the idea of reproachfulness.</li></ol>","xlit":"bárbaros"},"G591":{"strongs_def":" to give away, i.e. up, over, back, etc. (in various applications)","derivation":"from G575 (ἀπό) and G1325 (δίδωμι);","translit":"apodídōmi","lemma":"ἀποδίδωμι","kjv_def":"deliver (again), give (again), (re-)pay(-ment be made), perform, recompense, render, requite, restore, reward, sell, yield","pron":"ap-od-eed'-o-mee","pos":"Verb","thayer":"<ol><li>to deliver, to give away for one's own profit what is one's own, to sell</li><li>to pay off, discharge what is due<ol type='a'><li>a debt, wages, tribute, taxes, produce due</li><li>things promised under oath</li><li>conjugal duty</li><li>to render account</li></ol><li>to give back, restore</li><li>to requite, recompense in a good or a bad sense</li></ol>","xlit":"apodídōmi"},"G3783":{"translit":"opheílēma","lemma":"ὀφείλημα","kjv_def":"debt","strongs_def":" something owed, i.e. (figuratively) a due; morally, a fault","derivation":"from (the alternate of) G3784 (ὀφείλω);","pron":"of-i'-lay-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is owed<ol type='a'><li>that which is justly or legally due, a debt</li></ol><li>metaphorically offence, sin</li></ol>","xlit":"opheílēma"},"G510":{"kjv_def":"upper","lemma":"ἀνωτερικός","translit":"anōterikós","derivation":"from G511 (ἀνώτερος);","strongs_def":" superior, i.e. (locally) more remote","pron":"an-o-ter-ee-kos'","pos":"Adjective","thayer":"<ol><li>upper</li></ol>","xlit":"anōterikós"},"G3874":{"lemma":"παράκλησις","translit":"paráklēsis","kjv_def":"comfort, consolation, exhortation, intreaty","strongs_def":" imploration, hortation, solace","derivation":"from G3870 (παρακαλέω);","pron":"par-ak'-lay-sis","pos":"Noun Feminine","thayer":"<ol><li>a calling near, summons, (especially for help)</li><li>importation, supplication, entreaty</li><li>exhortation, admonition, encouragement</li><li>consolation, comfort, solace; that which affords comfort or refreshment<ol type='a'><li>thus of the Messianic salvation (so the Rabbis call the Messiah the consoler, the comforter)</li></ol><li>persuasive discourse, stirring address<ol type='a'><li>instructive, admonitory, conciliatory, powerful hortatory discourse</li></ol></li></ol>","xlit":"paráklēsis"},"G2761":{"strongs_def":" vainly, i.e. to no purpose","derivation":"adverb from G2756 (κενός);","translit":"kenōs","lemma":"κενῶς","kjv_def":"in vain","pron":"ken-oce'","pos":"Adverb","thayer":"<ol><li>vainly, in vain</li></ol>","xlit":"kenōs"},"G1246":{"lemma":"διακατελέγχομαι","translit":"diakatelénchomai","kjv_def":"convince","strongs_def":" to prove downright, i.e. confute","derivation":"middle voice from G1223 (διά) and a compound of G2596 (κατά) and G1651 (ἐλέγχω);","pron":"dee-ak-at-el-eng'-khom-ahee","pos":"Verb","thayer":"<ol><li>to confute with rivalry and effort or in a contest</li></ol>","xlit":"diakatelénchomai"},"G5208":{"kjv_def":"matter","lemma":"ὕλη","translit":"hýlē","derivation":"perhaps akin to G3586 (ξύλον);","strongs_def":" a forest, i.e. (by implication) fuel","pron":"hoo-lay'","pos":"Noun Feminine","thayer":"<ol><li>a forest, a wood</li><li>felled wood, fuel</li></ol>","xlit":"hýlē"},"G1741":{"lemma":"ἔνδοξος","translit":"éndoxos","kjv_def":"glorious, gorgeous(-ly), honourable","strongs_def":" in glory, i.e. splendid, (figuratively) noble","derivation":"from G1722 (ἐν) and G1391 (δόξα);","pron":"en'-dox-os","pos":"Adjective","thayer":"<ol><li>held in good or in great esteem, of high repute<ol type='a'><li>illustrious, honourable, esteemed</li><li>notable, glorious</li><li>splendid<ol><li>of clothing</li><li>fig., free from sins</li></ol></li></ol></li></ol>","xlit":"éndoxos"},"G1724":{"derivation":"from G1722 (ἐν) and G251 (ἅλς);","strongs_def":" in the sea, i.e. marine","kjv_def":"thing in the sea","translit":"enálios","lemma":"ἐνάλιος","pron":"en-al'-ee-os","pos":"Adjective","thayer":"<ol><li>that which is in the sea, marine</li></ol>","xlit":"enálios"},"G1519":{"kjv_def":"(abundant-)ly, against, among, as, at, (back-)ward, before, by, concerning, + continual, + far more exceeding, for (intent, purpose), fore, + forth, in (among, at, unto, -so much that, -to), to the intent that, + of one mind, + never, of, (up-)on, + perish, + set at one again, (so) that, therefore(-unto), throughout, til, to (be, the end, -ward), (here-)until(-to), …ward, (where-)fore, with","lemma":"εἰς","translit":"eis","derivation":"a primary preposition;","strongs_def":" to or into (indicating the point reached or entered), of place, time, or (figuratively) purpose (result, etc.); also in adverbial phrases","pron":"ice","pos":"Preposition","thayer":"<ol><li>into, unto, to, towards, for, among</li></ol>","xlit":"eis"},"G4972":{"kjv_def":"(set a, set to) seal up, stop","lemma":"σφραγίζω","translit":"sphragízō","derivation":"from G4973 (σφραγίς);","strongs_def":" to stamp (with a signet or private mark) for security or preservation (literally or figuratively); by implication, to keep secret, to attest","pron":"sfrag-id'-zo","pos":"Verb","thayer":"<ol><li>to set a seal upon, mark with a seal, to seal<ol type='a'><li>for security: from Satan</li><li>since things sealed up are concealed (as the contents of a letter), to hide, keep in silence, keep secret</li><li>in order to mark a person or a thing<ol><li>to set a mark upon by the impress of a seal or a stamp</li><li>angels are said to be sealed by God</li></ol><li>in order to prove, confirm, or attest a thing<ol><li>to confirm authenticate, place beyond doubt<ol type='a'><li>of a written document</li><li>to prove one's testimony to a person that he is what he professes to be</li></ol></li></ol></li></ol></li></ol>","xlit":"sphragízō"},"G4956":{"kjv_def":"of commendation","translit":"systatikós","lemma":"συστατικός","derivation":"from a derivative of G4921 (συνιστάω);","strongs_def":" introductory, i.e. recommendatory","pron":"soos-tat-ee-kos'","pos":"Adjective","thayer":"<ol><li>commendatory, introductory</li></ol>","xlit":"systatikós"},"G3404":{"kjv_def":"hate(-ful)","translit":"miséō","lemma":"μισέω","derivation":"from a primary (hatred);","strongs_def":" to detest (especially to persecute); by extension, to love less","pron":"mis-eh'-o","pos":"Verb","thayer":"<ol><li>to hate, pursue with hatred, detest</li><li>to be hated, detested</li></ol>","xlit":"miséō"},"G3468":{"kjv_def":"stripe","translit":"mṓlōps","lemma":"μώλωψ","derivation":"from (\"moil\";","strongs_def":" probably akin to the base of G3433 (μόλις)) and probably (the face; from G3700 (ὀπτάνομαι)); a mole (\"black eye\") or blow-mark","pron":"mo'-lopes","pos":"Noun Masculine","thayer":"<ol><li>a bruise, wale, wound that trickles with blood</li></ol>","xlit":"mṓlōps"},"G881":{"strongs_def":" Achaz, an Israelite","derivation":"of Hebrew origin (H0271);","translit":"Acház","lemma":"Ἀχάζ","kjv_def":"Achaz","pron":"akh-adz'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Ahaz = \"possessor\"</p><ol><li>the eleventh king of Judah, son of Jotham</li></ol>","xlit":"Acház"},"G1790":{"lemma":"ἔντρομος","translit":"éntromos","kjv_def":"X quake, X trembled","strongs_def":" terrified","derivation":"from G1722 (ἐν) and G5156 (τρόμος);","pron":"en'-trom-os","pos":"Adjective","thayer":"<ol><li>trembling, terrified</li></ol>","xlit":"éntromos"},"G4901":{"strongs_def":" to testify further jointly, i.e. unite in adding evidence","derivation":"from G4862 (σύν) and G1957 (ἐπιμαρτυρέω);","translit":"synepimartyréō","lemma":"συνεπιμαρτυρέω","kjv_def":"also bear witness","pron":"soon-ep-ee-mar-too-reh'-o","pos":"Verb","thayer":"<ol><li>at attest together with</li><li>to join in bearing witness, to unite in adding testimony</li></ol>","xlit":"synepimartyréō"},"G2206":{"lemma":"ζηλόω","translit":"zēlóō","kjv_def":"affect, covet (earnestly), (have) desire, (move with) envy, be jealous over, (be) zealous(-ly affect)","strongs_def":" to have warmth of feeling for or against","derivation":"from G2205 (ζῆλος);","pron":"dzay-lo'-o","pos":"Verb","thayer":"<ol><li>to burn with zeal<ol type='a'><li>to be heated or to boil with envy, hatred, anger<ol><li>in a good sense, to be zealous in the pursuit of good</li></ol><li>to desire earnestly, pursue<ol><li>to desire one earnestly, to strive after, busy one's self about him</li><li>to exert one's self for one (that he may not be torn from me)</li><li>to be the object of the zeal of others, to be zealously sought after</li></ol><li>to envy</li></ol></li></ol>","xlit":"zēlóō"},"G714":{"translit":"arkéō","lemma":"ἀρκέω","kjv_def":"be content, be enough, suffice, be sufficient","strongs_def":" properly, to ward off, i.e. (by implication) to avail (figuratively, be satisfactory)","derivation":"apparently a primary verb (but probably akin to G142 (αἴρω) through the idea of raising a barrier);","pron":"ar-keh'-o","pos":"Verb","thayer":"<ol><li>to be possessed of unfailing strength<ol type='a'><li>to be strong, to suffice, to be enough<ol><li>to defend, ward off</li></ol><li>to be satisfied, to be contented</li></ol></li></ol>","xlit":"arkéō"},"G2415":{"kjv_def":"of Jerusalem","lemma":"Ἱεροσολυμίτης","translit":"Hierosolymítēs","derivation":"from G2414 (Ἱεροσόλυμα);","strongs_def":" a Hierosolymite, i.e. inhabitant of Hierosolyma","pron":"hee-er-os-ol-oo-mee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a citizen or inhabitant of Jerusalem</li></ol>","xlit":"Hierosolymítēs"},"G2069":{"translit":"Eslí","lemma":"Ἐσλί","kjv_def":"Esli","strongs_def":" Esli, an Israelite","derivation":"of Hebrew origin (probably for H0454);","pron":"es-lee'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Esli = \"reserved of Jehovah\"</p><ol><li>the son of Nagge or Naggai in the genealogy of Christ. <a class='bible' href='#b42.3.25'>Luk 3:25</a>.</li></ol>","xlit":"Eslí"},"G434":{"derivation":"from G1 (Α) (as a negative particle) and (lame);","strongs_def":" savage","kjv_def":"fierce","lemma":"ἀνήμερος","translit":"anḗmeros","pron":"an-ay'-mer-os","pos":"Adjective","thayer":"<ol><li>not tame, savage, fierce</li></ol>","xlit":"anḗmeros"},"G4201":{"derivation":"of Latin origin;","strongs_def":" apparently swinish; Porcius, a Roman","kjv_def":"Porcius","lemma":"Πόρκιος","translit":"Pórkios","pron":"por'-kee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Porcius [Festus] = \"swinish\"</p><ol><li>the successor of Felix as procurator of Judea</li></ol>","xlit":"Pórkios"},"G90":{"strongs_def":" incorruptibleness, i.e. (figuratively) purity (of doctrine)","derivation":"from a derivative of a compound of G1 (Α) (as a negative particle) and a derivative of G1311 (διαφθείρω);","translit":"adiaphthoría","lemma":"ἀδιαφθορία","kjv_def":"uncorruptness","pron":"ad-ee-af-thor-ee'-ah","thayer":"<ol><li>incorruptibility, soundness, integrity<ol type='a'><li>of mind</li></ol></li></ol>","xlit":"adiaphthoría"},"G4854":{"lemma":"σύμφυτος","translit":"sýmphytos","kjv_def":"planted together","strongs_def":" grown along with (connate), i.e. (figuratively) closely united to","derivation":"from G4862 (σύν) and a derivative of G5453 (φύω);","pron":"soom'-foo-tos","pos":"Adjective","thayer":"<ol><li>born together with, of joint origin<ol type='a'><li>connate, congenital, innate, implanted by birth or nature</li></ol><li>grown together, united with</li><li>kindred</li></ol>","xlit":"sýmphytos"},"G1715":{"strongs_def":" in front of (in place (literally or figuratively) or time)","derivation":"from G1722 (ἐν) and G4314 (πρός);","lemma":"ἔμπροσθεν","translit":"émprosthen","kjv_def":"against, at, before, (in presence, sight) of","pron":"em'-pros-then","pos":"Adverb","thayer":"<ol><li>in front, before<ol type='a'><li>before, i.e. in that local region which is in front of a person or thing</li><li>before, in the presence of, i.e. opposite to, over against one</li><li>before, in the sight of</li><li>before, denoting rank</li></ol></li></ol>","xlit":"émprosthen"},"G1066":{"strongs_def":" Gedeon (i.e. Gid(e)on), an Israelite","derivation":"of Hebrew origin (H01439);","lemma":"Γεδεών","translit":"Gedeṓn","kjv_def":"Gedeon (in the King James Version)","pron":"ghed-eh-own'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Gideon = \"the cutter down\"</p><ol><li>a of the judge of Israel who delivered them from the Midianites</li></ol>","xlit":"Gedeṓn"},"G1270":{"derivation":"from a compound of G1223 (διά) and G3539 (νοιέω);","strongs_def":" something thought through, i.e. a sentiment","kjv_def":"thought","lemma":"διανόημα","translit":"dianóēma","pron":"dee-an-o'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a thought</li></ol>","xlit":"dianóēma"},"G3578":{"derivation":"from G3581 (ξένος);","strongs_def":" hospitality, i.e. (by implication) a place of entertainment","kjv_def":"lodging","translit":"xenía","lemma":"ξενία","pron":"xen-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>hospitality, hospitable reception</li><li>a lodging place, lodgings</li></ol>","xlit":"xenía"},"G5370":{"translit":"phílēma","lemma":"φίλημα","kjv_def":"kiss","strongs_def":" a kiss","derivation":"from G5368 (φιλέω);","pron":"fil'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a kiss</li><li>the kiss with which, as a sign of fraternal affection, Christians were accustomed to welcome or dismiss their companions in the faith</li></ol>","xlit":"phílēma"},"G799":{"translit":"Asýnkritos","lemma":"Ἀσύγκριτος","kjv_def":"Asyncritos","strongs_def":" incomparable; Asyncritus, a Christian","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4793 (συγκρίνω);","pron":"as-oong'-kree-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Asyncritus = \"incomparable\"</p><ol><li>an unknown Christian at Rome saluted by Paul</li></ol>","xlit":"Asýnkritos"},"G5531":{"lemma":"χράω","translit":"chráō","kjv_def":"lend","strongs_def":" to loan","derivation":"probably the same as the base of G5530 (χράομαι);","pron":"khrah'-o","pos":"Verb","thayer":"<ol><li>to lend</li></ol>","xlit":"chráō"},"G1185":{"kjv_def":"allure, beguile, entice","translit":"deleázō","lemma":"δελεάζω","derivation":"from the base of G1388 (δόλος);","strongs_def":" to entrap, i.e. (figuratively) delude","pron":"del-eh-ad'-zo","pos":"Verb","thayer":"<ol><li>to bait, catch by a bait</li><li>metaphorically to beguile by blanishments, allure, entice, deceive</li></ol>","xlit":"deleázō"},"G5148":{"translit":"trietía","lemma":"τριετία","kjv_def":"space of three years","strongs_def":" a three years' period (triennium)","derivation":"from a compound of G5140 (τρεῖς) and G2094 (ἔτος);","pron":"tree-et-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a space of three years</li></ol>","xlit":"trietía"},"G4824":{"strongs_def":" advisement; specially, a deliberative body, i.e. the provincial assessors or lay-court","derivation":"neuter of a presumed derivative of G4825 (σύμβουλος);","lemma":"συμβούλιον","translit":"symboúlion","kjv_def":"consultation, counsel, council","pron":"soom-boo'-lee-on","pos":"Noun Neuter","thayer":"<ol><li>counsel, which is given, taken, entered upon<ol type='a'><li>consult, deliberate</li></ol><li>a council<ol type='a'><li>an assembly of counsellors or persons in consultation (the governors and procurators of provinces had a board of assessors or advisers with whom they took council before rendering judgment)</li></ol></li></ol>","xlit":"symboúlion"},"G3411":{"translit":"misthōtós","lemma":"μισθωτός","kjv_def":"hired servant, hireling","strongs_def":" a wage-worker (good or bad)","derivation":"from G3409 (μισθόω);","pron":"mis-tho-tos'","pos":"Adjective","thayer":"<ol><li>one hired, a hireling</li></ol>","xlit":"misthōtós"},"G1999":{"translit":"episýstasis","lemma":"ἐπισύστασις","kjv_def":"that which cometh upon, + raising up","strongs_def":" a conspiracy, i.e. concourse (riotous or friendly)","derivation":"from the middle voice of a compound of G1909 (ἐπί) and G4921 (συνιστάω);","pron":"ep-ee-soo'-stas-is","pos":"Noun Feminine","thayer":"<ol><li>a hostile banding together or concourse<ol type='a'><li>to excite to a riotous gathering of the people to make a mob</li><li>a troublesome throng of persons seeking help, counsel, comfort</li><li>throng to one</li></ol></li></ol>","xlit":"episýstasis"},"G963":{"derivation":"of Chaldee origin;","strongs_def":" date-house; Beth-any, a place in Palestine","kjv_def":"Bethany","lemma":"Βηθανία","translit":"Bēthanía","pron":"bay-than-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethany = \"house of dates\" or, \"house of misery\"</p><ol><li>a village at the Mount of Olives, about two miles (3 km) from Jerusalem, on or near the normal road to Jericho</li><li>a town or village on the east bank of the Jordan, where John was baptising</li></ol>","xlit":"Bēthanía"},"G1932":{"derivation":"from G1933 (ἐπιεικής);","strongs_def":" suitableness, i.e. (by implication) equity, mildness","kjv_def":"clemency, gentleness","lemma":"ἐπιείκεια","translit":"epieíkeia","pron":"ep-ee-i'-ki-ah","pos":"Noun Feminine","thayer":"<ol><li>mildness, gentleness, fairness</li></ol>","xlit":"epieíkeia"},"G2239":{"lemma":"ἦθος","translit":"ēthos","kjv_def":"manners","strongs_def":" usage, i.e. (plural) moral habits","derivation":"a strengthened form of G1485 (ἔθος);","pron":"ay'-thos","pos":"Noun Neuter","thayer":"<ol><li>a customary abode, dwelling place, haunt, customary state</li><li>custom, usage, morals, character</li></ol>","xlit":"ēthos"},"G4083":{"derivation":"of uncertain affinity;","strongs_def":" the fore-arm, i.e. (as a measure) a cubit","kjv_def":"cubit","lemma":"πῆχυς","translit":"pēchys","pron":"pay'-khoos","pos":"Noun Masculine","thayer":"<ol><li>a cubit</li><li>a measure of length equal to distance from the joint of the elbow to the tip of the middle finger (i.e. about 18 inches, (.5 m) but its precise length varied and is disputed)</li></ol>","xlit":"pēchys"},"G419":{"strongs_def":" not searched out, i.e. (by implication) inscrutable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G1830 (ἐξερευνάω);","lemma":"ἀνεξερεύνητος","translit":"anexereúnētos","kjv_def":"unsearchable","pron":"an-ex-er-yoo'-nay-tos","pos":"Adjective","thayer":"<ol><li>that cannot be searched out</li></ol>","xlit":"anexereúnētos"},"G1794":{"strongs_def":" probably akin to G1507 (εἱλίσσω)); to entwine, i.e. wind up in","derivation":"from G1722 (ἐν) and (to twist;","lemma":"ἐντυλίσσω","translit":"entylíssō","kjv_def":"wrap in (together)","pron":"en-too-lis'-so","pos":"Verb","thayer":"<ol><li>to roll up, wrap together</li></ol>","xlit":"entylíssō"},"G119":{"kjv_def":"fight","translit":"áthlēsis","lemma":"ἄθλησις","derivation":"from G118 (ἀθλέω);","strongs_def":" a struggle (figuratively)","pron":"ath'-lay-sis","pos":"Noun Feminine","thayer":"<ol><li>to contest, to combat, to strive, struggle, hard trial</li></ol>","xlit":"áthlēsis"},"G4215":{"derivation":"probably from a derivative of the alternate of G4095 (πίνω) (compare G4224 (πότος));","strongs_def":" a current, brook or freshet (as drinkable), i.e. running water","kjv_def":"flood, river, stream, water","lemma":"ποταμός","translit":"potamós","pron":"pot-am-os'","pos":"Noun Masculine","thayer":"<ol><li>a stream, a river</li><li>a torrent</li><li>floods</li></ol>","xlit":"potamós"},"G3064":{"strongs_def":" remaining time","derivation":"genitive case singular of the same as G3062 (λοιποί);","translit":"loipoû","lemma":"λοιποῦ","kjv_def":"from henceforth","pron":"loy-poo'","pos":"Adjective","thayer":"<ol><li>hereafter, for the future, henceforth</li></ol>","xlit":"loipoû"},"G722":{"strongs_def":" to plow","derivation":"from G723 (ἄροτρον);","lemma":"ἀροτριόω","translit":"arotrióō","kjv_def":"plough","pron":"ar-ot-ree-o'-o","pos":"Verb","thayer":"<ol><li>to plough</li></ol>","xlit":"arotrióō"},"G1691":{"derivation":"a prolonged form of G3165 (μέ);","strongs_def":" me","kjv_def":"I, me, my(-self)","translit":"emé","lemma":"ἐμέ","pron":"em-eh'","thayer":"<ol><li>I, me, myself, etc.</li></ol>","xlit":"emé"},"G5171":{"kjv_def":"live in pleasure","lemma":"τρυφάω","translit":"trypháō","derivation":"from G5172 (τρυφή);","strongs_def":" to indulge in luxury","pron":"troo-fah'-o","pos":"Verb","thayer":"<ol><li>to live delicately, live luxuriously, be given to soft and luxurious life</li></ol>","xlit":"trypháō"},"G1534":{"kjv_def":"after that(-ward), furthermore, then","lemma":"εἶτα","translit":"eîta","derivation":"of uncertain affinity;","strongs_def":" a particle of succession (in time or logical enumeration), then, moreover","pron":"i'-tah","pos":"Adverb","thayer":"<ol><li>then</li><li>next, after that</li></ol>","xlit":"eîta"},"G2630":{"strongs_def":" to precipitate down","derivation":"from G2596 (κατά) and a derivative of G2911 (κρημνός);","translit":"katakrēmnízō","lemma":"κατακρημνίζω","kjv_def":"cast down headlong","pron":"kat-ak-rame-nid'-zo","pos":"Verb","thayer":"<ol><li>to cast down a precipice</li><li>to through down headlong</li></ol>","xlit":"katakrēmnízō"},"G3627":{"kjv_def":"have compassion on","translit":"oikteírō","lemma":"οἰκτείρω","derivation":"from (pity);","strongs_def":" to exercise pity","pron":"oyk-ti'-ro","pos":"Verb","thayer":"<ol><li>to pity, have compassion on</li></ol>","xlit":"oikteírō"},"G5076":{"derivation":"from G5064 (τέσσαρες) and G757 (ἄρχω);","strongs_def":" the ruler of a fourth part of a country (\"tetrarch\")","kjv_def":"tetrarch","lemma":"τετράρχης","translit":"tetrárchēs","pron":"tet-rar'-khace","pos":"Noun Masculine","thayer":"<ol><li>a tetrarch<ol type='a'><li>a governor of the fourth part of a region. Thus Strabo states that Galactia was formerly divided into three parts, each one of which was distributed into four smaller subdivisions each of which was governed by a tetrarch. Strabo relates that Thessaly, before the time of Philip of Macedon, had been divided into four tetrarchies, each having its own tetrarch.</li><li>the governor of a third part or half a country, or even a ruler of an entire country or district provided it were of comparatively narrow limits; a petty prince. Thus Antony made Herod (afterwards king) and Phasael, sons of Antipater, tetrarchs of Palestine. After the death of Herod the Great, his sons, Achelaus styled an ethnarch but Antipas and Philip with the title of tetrarchs, divided and governed the kingdom left by their father.</li></ol></li></ol>","xlit":"tetrárchēs"},"G2978":{"kjv_def":"storm, tempest","translit":"laîlaps","lemma":"λαῖλαψ","derivation":"of uncertain derivation;","strongs_def":" a whirlwind (squall)","pron":"lah'-ee-laps","pos":"Noun Feminine","thayer":"<ol><li>a whirlwind, a tempestuous wind</li><li>a violent attack of wind, a squall<ol type='a'><li>never a single gust nor a steady blowing wind, however violent, but a storm breaking forth from black thunder clouds in furious gusts, with floods of rain, and throwing everything topsy-turvy</li></ol></li></ol>","xlit":"laîlaps"},"G3195":{"translit":"méllō","lemma":"μέλλω","kjv_def":"about, after that, be (almost), (that which is, things, + which was for) to come, intend, was to (be), mean, mind, be at the point, (be) ready, + return, shall (begin), (which, that) should (after, afterwards, hereafter) tarry, which was for, will, would, be yet","strongs_def":" to intend, i.e. be about to be, do, or suffer something (of persons or things, especially events; in the sense of purpose, duty, necessity, probability, possibility, or hesitation)","derivation":"a strengthened form of G3199 (μέλω) (through the idea of expectation);","pron":"mel'-lo","pos":"Verb","thayer":"<ol><li>to be about<ol type='a'><li>to be on the point of doing or suffering something</li><li>to intend, have in mind, think to</li></ol></li></ol>","xlit":"méllō"},"G1128":{"derivation":"from G1131 (γυμνός);","strongs_def":" to practise naked (in the games), i.e. train (figuratively)","kjv_def":"exercise","lemma":"γυμνάζω","translit":"gymnázō","pron":"goom-nad'-zo","pos":"Verb","thayer":"<ol><li>to exercise naked (in a palaestra or school of athletics)</li><li>to exercise vigorously, in any way, either the body or the mind</li></ol>","xlit":"gymnázō"},"G4527":{"derivation":"of Hebrew origin (H07974);","strongs_def":" Sala (i.e. Shelach), a patriarch ","kjv_def":"Sala","translit":"Salá","lemma":"Σαλά","pron":"sal-ah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Salah = \"sprout\"</p><ol><li>the son of Arphaxad, and father of Eber</li></ol>","xlit":"Salá"},"G1167":{"derivation":"from G1169 (δειλός);","strongs_def":" timidity","kjv_def":"fear","translit":"deilía","lemma":"δειλία","pron":"di-lee'-ah","pos":"Noun Feminine","thayer":"<ol><li>timidity, fearfulness, cowardice</li></ol>","xlit":"deilía"},"G2437":{"derivation":"neuter of an adjective from a name of uncertain derivation;","strongs_def":" (the) Illyrican (shore), i.e. (as a name itself) Illyricum, a region of Europe","kjv_def":"Illyricum","translit":"Illyrikón","lemma":"Ἰλλυρικόν","pron":"il-loo-ree-kon'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Illyricum = \"the lyric band\"</p><ol><li>a region lying between Italy, Germany, Macedonia and Thrice, having on one side the Adriatic Sea, and on the other the Danube</li></ol>","xlit":"Illyrikón"},"G5142":{"derivation":"a primary verb (properly, ;","strongs_def":" but perhaps strengthened from the base of G5157 (τροπή) through the idea of convolution); properly, to stiffen, i.e. fatten (by implication, to cherish (with food, etc.), pamper, rear)","kjv_def":"bring up, feed, nourish","translit":"tréphō","lemma":"τρέφω","pron":"tref'-o","thayer":"<ol><li>to nourish, support</li><li>feed</li><li>to give suck, to fatten</li><li>to bring up, nurture</li></ol>","xlit":"tréphō"},"G2930":{"derivation":"from a derivative of (frost);","strongs_def":" ice, i.e. (by analogy) rock \"crystal\"","kjv_def":"crystal","translit":"krýstallos","lemma":"κρύσταλλος","pron":"kroos'-tal-los","pos":"Noun Masculine","thayer":"<ol><li>crystal, a kind of precious stone</li></ol>","xlit":"krýstallos"},"G5613":{"kjv_def":"about, after (that), (according) as (it had been, it were), as soon (as), even as (like), for, how (greatly), like (as, unto), since, so (that), that, to wit, unto, when(-soever), while, X with all speed","translit":"hōs","lemma":"ὡς","derivation":"probably adverb of comparative from G3739 (ὅς);","strongs_def":" which how, i.e. in that manner (very variously used, as follows)","pron":"hoce","pos":"Adverb","thayer":"<ol><li>as, like, even as, etc.</li></ol>","xlit":"hōs"},"G3006":{"kjv_def":"smooth","lemma":"λεῖος","translit":"leîos","derivation":"apparently a primary word;","strongs_def":" smooth, i.e. \"level\"","pron":"li'-os","pos":"Adjective","thayer":"<ol><li>smooth, level</li></ol>","xlit":"leîos"},"G2671":{"kjv_def":"curse(-d, ing)","lemma":"κατάρα","translit":"katára","derivation":"from G2596 (κατά) (intensive) and G685 (ἀρά);","strongs_def":" imprecation, execration","pron":"kat-ar'-ah","pos":"Noun Feminine","thayer":"<ol><li>an execration, imprecation, curse</li></ol>","xlit":"katára"},"G4463":{"derivation":"from G4464 (ῥάβδος);","strongs_def":" to strike with a stick, i.e. bastinado","kjv_def":"beat (with rods)","translit":"rhabdízō","lemma":"ῥαβδίζω","pron":"hrab-did'-zo","pos":"Verb","thayer":"<ol><li>to beat with rods</li></ol>","xlit":"rhabdízō"},"G5387":{"kjv_def":"kindly affectioned","translit":"philóstorgos","lemma":"φιλόστοργος","derivation":"from G5384 (φίλος) and (cherishing one's kindred, especially parents or children);","strongs_def":" fond of natural relatives, i.e. fraternal towards fellow Christian","pron":"fil-os'-tor-gos","pos":"Adjective","thayer":"<ol><li>the mutual love of parents and children and wives and husbands</li><li>loving affection, prone to love, loving tenderly<ol type='a'><li>chiefly of the reciprocal tenderness of parents and children</li></ol></li></ol>","xlit":"philóstorgos"},"G1368":{"derivation":"from G1223 (διά) and (to filter);","strongs_def":" to strain out","kjv_def":"strain at (probably by misprint)","translit":"diÿlízō","lemma":"διϋλίζω","pron":"dee-oo-lid'-zo","pos":"Verb","thayer":"<ol><li>to filter through, strain through, pour through a filter, strain out</li></ol>","xlit":"diÿlízō"},"G1010":{"lemma":"βουλευτής","translit":"bouleutḗs","kjv_def":"counsellor","strongs_def":" an adviser, i.e. (specially) a councillor or member of the Jewish Sanhedrin","derivation":"from G1011 (βουλεύω);","pron":"bool-yoo-tace'","pos":"Noun Masculine","thayer":"<ol><li>a councillor, senator</li><li>a member of the Sanhedrin</li></ol>","xlit":"bouleutḗs"},"G1379":{"derivation":"from G1378 (δόγμα);","strongs_def":" to prescribe by statute, i.e. (reflexively) to submit to, ceremonially rule","kjv_def":"be subject to ordinances","lemma":"δογματίζω","translit":"dogmatízō","pron":"dog-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to decree, command, enjoin, lay down an ordinance</li></ol>","xlit":"dogmatízō"},"G1374":{"strongs_def":" two-spirited, i.e. vacillating (in opinion or purpose)","derivation":"from G1364 (δίς) and G5590 (ψυχή);","lemma":"δίψυχος","translit":"dípsychos","kjv_def":"double minded","pron":"dip'-soo-khos","pos":"Adjective","thayer":"<ol><li>double minded<ol type='a'><li>wavering, uncertain, doubting</li><li>divided in interest</li></ol></li></ol>","xlit":"dípsychos"},"G1698":{"kjv_def":"I, me, mine, my","translit":"emoí","lemma":"ἐμοί","derivation":"a prolonged form of G3427 (μοί);","strongs_def":" to me","pron":"em-oy'","thayer":"<ol><li>I, me, myself, etc.</li></ol>","xlit":"emoí"},"G190":{"lemma":"ἀκολουθέω","translit":"akolouthéō","kjv_def":"follow, reach","strongs_def":" properly, to be in the same way with, i.e. to accompany (specially, as a disciple)","derivation":"from G1 (Α) (as a particle of union) and (a road);","pron":"ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow one who precedes, join him as his attendant, accompany him</li><li>to join one as a disciple, become or be his disciple<ol type='a'><li>side with his party</li></ol></li></ol>","xlit":"akolouthéō"},"G4690":{"lemma":"σπέρμα","translit":"spérma","kjv_def":"issue, seed","strongs_def":" something sown, i.e. seed (including the male \"sperm\"); by implication, offspring; specially, a remnant (figuratively, as if kept over for planting)","derivation":"from G4687 (σπείρω);","pron":"sper'-mah","pos":"Noun Neuter","thayer":"<ol><li>from which a plant germinates<ol type='a'><li>the seed, i.e. the grain or kernel which contains within itself the germ of the future plants<ol><li>of the grains or kernels sown</li></ol><li>metaphorically a seed, i.e. a residue, or a few survivors reserved as the germ of the next generation (just as seed is kept from the harvest for the sowing)</li></ol><li>the semen virile<ol type='a'><li>the product of this semen, seed, children, offspring, progeny</li><li>family, tribe, posterity</li><li>whatever possesses vital force or life giving power<ol><li>of divine energy of the Holy Spirit operating within the soul by which we are regenerated</li></ol></li></ol></li></ol>","xlit":"spérma"},"G350":{"kjv_def":"ask, question, discern, examine, judge, search","lemma":"ἀνακρίνω","translit":"anakrínō","derivation":"from G303 (ἀνά) and G2919 (κρίνω);","strongs_def":" properly, to scrutinize, i.e. (by implication) investigate, interrogate, determine","pron":"an-ak-ree'-no","pos":"Verb","thayer":"<ol><li>examine or judge<ol type='a'><li>to investigate, examine, enquire into, scrutinise, sift, question<ol><li>specifically in a forensic sense of a judge to hold an investigation</li><li>to interrogate, examine the accused or witnesses</li></ol><li>to judge of, estimate, determine (the excellence or defects of any person or thing</li></ol></li></ol>","xlit":"anakrínō"},"G2377":{"strongs_def":" a gate- warden","derivation":"from G2374 (θύρα) and (a watcher);","lemma":"θυρωρός","translit":"thyrōrós","kjv_def":"that kept the door, porter","pron":"thoo-ro-ros'","pos":"Noun Masculine","thayer":"<ol><li>a doorkeeper, porter<ol type='a'><li>a male or female janitor</li></ol></li></ol>","xlit":"thyrōrós"},"G2958":{"strongs_def":" Cyrenius (i.e. Quirinus), a Roman","derivation":"of Latin origin;","lemma":"Κυρήνιος","translit":"Kyrḗnios","kjv_def":"Cyrenius","pron":"koo-ray'-nee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cyrenius = \"warrior\"</p><ol><li>the Greek form of the Roman name Quirinus. His full name is Publius Sulpicius Quirinus. He was consul B.C. 12., and was made governor of Syria after the banishment of Archelaus in A.D. 6. He was probably twice governor of Syria; his first governorship extended from B.C. 4 (the year of Christ's birth) to B.C. 1. It was during this time that he was sent to make enrolment which caused Joseph and Mary to visit Bethlehem. <a class='bible' href='#b42.2.2'>Luk 2:2</a>. The second enrolment is mentioned in <a class='bible' href='#b44.5.37'>Act 5:37</a>.</li></ol>","xlit":"Kyrḗnios"},"G122":{"strongs_def":" belonging to a goat","derivation":"from (a goat);","translit":"aígeios","lemma":"αἴγειος","kjv_def":"goat","pron":"ah'-ee-ghi-os","pos":"Adjective","thayer":"<ol><li>of a goat, goatskin</li></ol>","xlit":"aígeios"},"G1852":{"strongs_def":" to waken","derivation":"from G1853 (ἔξυπνος);","translit":"exypnízō","lemma":"ἐξυπνίζω","kjv_def":"awake out of sleep","pron":"ex-oop-nid'-zo","pos":"Verb","thayer":"<ol><li>to wake up, awaken out of a sleep</li></ol>","xlit":"exypnízō"},"G1126":{"strongs_def":" crone-like, i.e. silly","derivation":"from (an old woman) and G1491 (εἶδος);","translit":"graṓdēs","lemma":"γραώδης","kjv_def":"old wives'","pron":"grah-o'-dace","pos":"Adjective","thayer":"<ol><li>old womanish, old wives, an old woman</li></ol>","xlit":"graṓdēs"},"G1626":{"strongs_def":" a miscarriage (abortion), i.e. (by analogy) untimely birth","derivation":"from a comparative of G1537 (ἐκ) and (to wound);","translit":"éktrōma","lemma":"ἔκτρωμα","kjv_def":"born out of due time","pron":"ek'-tro-mah","pos":"Noun Neuter","thayer":"<ol><li>an abortion, abortive birth</li><li>an untimely birth</li></ol>","xlit":"éktrōma"},"G1836":{"lemma":"ἑξῆς","translit":"hexēs","kjv_def":"after, following, X morrow, next","strongs_def":" successive","derivation":"from G2192 (ἔχω) (in the sense of taking hold of, i.e. adjoining);","pron":"hex-ace'","pos":"Adverb","thayer":"<ol><li>successively in order</li><li>the next following, the next in succession</li></ol>","xlit":"hexēs"},"G2689":{"derivation":"from G2687 (καταστέλλω);","strongs_def":" a deposit, i.e. (specially) costume","kjv_def":"apparel","translit":"katastolḗ","lemma":"καταστολή","pron":"kat-as-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a lowering, letting down</li><li>a garment let down, dress, attire</li></ol>","xlit":"katastolḗ"},"G2619":{"kjv_def":"cover, hide","translit":"katakalýptō","lemma":"κατακαλύπτω","derivation":"from G2596 (κατά) and G2572 (καλύπτω);","strongs_def":" to cover wholly, i.e. veil","pron":"kat-ak-al-oop'-to","pos":"Verb","thayer":"<ol><li>to cover up</li><li>to veil or cover one's self</li></ol>","xlit":"katakalýptō"},"G2094":{"strongs_def":" a year","derivation":"apparently a primary word;","translit":"étos","lemma":"ἔτος","kjv_def":"year","pron":"et'-os","pos":"Noun Neuter","thayer":"<ol><li>year</li></ol>","xlit":"étos"},"G3070":{"kjv_def":"Lydia","lemma":"Λυδία","translit":"Lydía","derivation":"properly, feminine of Ludios (of foreign origin) (a Lydian, in Asia Minor);","strongs_def":" Lydia, a Christian woman","pron":"loo-dee'-ah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Lydia = \"travail\"</p><ol><li>a woman of Thyatira, a seller of purple, the first European convert of Paul, and afterward his hostess during his first stay at Philippi</li></ol>","xlit":"Lydía"},"G4163":{"derivation":"from G4160 (ποιέω);","strongs_def":" a performer; specially, a \"poet\"; ","kjv_def":"--doer, poet","lemma":"ποιητής","translit":"poiētḗs","pron":"poy-ay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a maker, a producer, author</li><li>a doer, performer<ol type='a'><li>one who obeys or fulfils the law</li></ol><li>a poet</li></ol>","xlit":"poiētḗs"},"G5216":{"kjv_def":"ye, you, your (own, -selves)","translit":"hymōn","lemma":"ὑμῶν","derivation":"genitive case of G5210 (ὑμεῖς);","strongs_def":" of (from or concerning) you","pron":"hoo-mone'","thayer":"<ol><li>of yours</li></ol>","xlit":"hymōn"},"G109":{"kjv_def":"air","lemma":"ἀήρ","translit":"aḗr","derivation":"from (to breathe unconsciously, i.e. respire;","strongs_def":" by analogy, to blow); \"air\" (as naturally circumambient)","pron":"ah-ayr'","pos":"Noun Masculine","thayer":"<ol><li>the air, particularly the lower and denser air as distinguished from the higher and rarer air</li><li>the atmospheric region</li></ol>","xlit":"aḗr"},"G4577":{"derivation":"probably from G4951 (σύρω) through its congener (to fasten;","strongs_def":" akin to G138 (αἱρέομαι)); a chain (as binding or drawing)","kjv_def":"chain","translit":"seirá","lemma":"σειρά","pron":"si-rah'","pos":"Noun Feminine","thayer":"<ol><li>a line, a rope</li><li>a chain</li></ol>","xlit":"seirá"},"G1229":{"derivation":"from G1223 (διά) and the base of G32 (ἄγγελος);","strongs_def":" to herald thoroughly","kjv_def":"declare, preach, signify","lemma":"διαγγέλλω","translit":"diangéllō","pron":"de-ang-gel'-lo","pos":"Verb","thayer":"<ol><li>to carry a message through, announce everywhere, through places, through assemblies of men etc.</li><li>to publish abroad, declare</li></ol>","xlit":"diangéllō"},"G2203":{"kjv_def":"Jupiter","translit":"Zeús","lemma":"Ζεύς","derivation":"of uncertain affinity;","strongs_def":" in the oblique cases there is used instead of it a (probably cognate) name , which is otherwise obsolete; Zeus or Dis (among the Latins, Jupiter or Jove), the supreme deity of the Greeks","pron":"dzyooce","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jupiter or Zeus = \"a father of helps\"</p><ol><li>the national god of the Greeks and corresponds to the Roman Jupiter</li></ol>","xlit":"Zeús"},"G5349":{"derivation":"from G5351 (φθείρω);","strongs_def":" decayed, i.e. (by implication) perishable","kjv_def":"corruptible","translit":"phthartós","lemma":"φθαρτός","pron":"fthar-tos'","pos":"Adjective","thayer":"<ol><li>corruptible, perishing</li></ol>","xlit":"phthartós"},"G971":{"translit":"biázō","lemma":"βιάζω","kjv_def":"press, suffer violence","strongs_def":" to force, i.e. (reflexively) to crowd oneself (into), or (passively) to be seized","derivation":"from G979 (βίος);","pron":"bee-ad'-zo","pos":"Verb","thayer":"<ol><li>to use force, to apply force</li><li>to force, inflict violence on</li></ol>","xlit":"biázō"},"G4214":{"kjv_def":"how great (long, many), what","lemma":"πόσος","translit":"pósos","derivation":"from an absolute (who, what) and G3739 (ὅς);","strongs_def":" interrogative pronoun (of amount) how much (large, long or (plural) many)","pron":"pos'-os","thayer":"<ol><li>how great</li><li>how much</li><li>how many</li></ol>","xlit":"pósos"},"G3872":{"kjv_def":"that (thing) which is committed (un-)to (trust)","translit":"parakatathḗkē","lemma":"παρακαταθήκη","derivation":"from a compound of G3844 (παρά) and G2698 (κατατίθημι);","strongs_def":" something put down alongside, i.e. a deposit (sacred trust)","pron":"par-ak-at-ath-ay'-kay","pos":"Noun Feminine","thayer":"<ol><li>a deposit, a trust or thing consigned to one's faithful keeping<ol type='a'><li>used of the correct knowledge and pure doctrine of the gospel, to be held firmly and faithfully, and to be conscientiously delivered unto others</li></ol></li></ol>","xlit":"parakatathḗkē"},"G4206":{"strongs_def":" forwards, i.e. at a distance","derivation":"adverb from G4253 (πρό);","lemma":"πόῤῥω","translit":"pórrhō","kjv_def":"far, a great way off","pron":"por'-rho","pos":"Adverb","thayer":"<ol><li>far, at a distance, a great way off</li></ol>","xlit":"pórrhō"},"G2608":{"derivation":"from G2596 (κατά) and the base of G4486 (ῥήγνυμι);","strongs_def":" to rend in pieces, i.e. crack apart","kjv_def":"break","lemma":"κατάγνυμι","translit":"katágnymi","pron":"kat-ag'-noo-mee","pos":"Verb","thayer":"<ol><li>to break</li></ol>","xlit":"katágnymi"},"G5227":{"derivation":"from G5259 (ὑπό) and G1727 (ἐναντίος);","strongs_def":" under (covertly) contrary to, i.e. opposed or (as noun) an opponent","kjv_def":"adversary, against","translit":"hypenantíos","lemma":"ὑπεναντίος","pron":"hoop-en-an-tee'-os","pos":"Adjective","thayer":"<ol><li>opposite to<ol type='a'><li>set over against: meeting one another</li></ol><li>opposed to, contrary to, an adversary</li></ol>","xlit":"hypenantíos"},"G4887":{"lemma":"συνδέω","translit":"syndéō","kjv_def":"be bound with","strongs_def":" to bind with, i.e. (passively) be a fellow-prisoner (figuratively)","derivation":"from G4862 (σύν) and G1210 (δέω);","pron":"soon-deh'-o","pos":"Verb","thayer":"<ol><li>to tie together, to bind together</li><li>to bind or fasten on all sides</li><li>to bind just as (i.e. jointly with) another</li></ol>","xlit":"syndéō"},"G4332":{"lemma":"προσεδρεύω","translit":"prosedreúō","kjv_def":"wait at","strongs_def":" to sit near, i.e. attend as a servant","derivation":"from a compound of G4314 (πρός) and the base of G1476 (ἑδραῖος);","pron":"pros-ed-ryoo'-o","pos":"Verb","thayer":"<ol><li>to sit near</li><li>to attend assiduously</li><li>to be in attendance upon, not to quit one's side</li></ol>","xlit":"prosedreúō"},"G4174":{"translit":"politeía","lemma":"πολιτεία","kjv_def":"commonwealth, freedom","strongs_def":" citizenship; concretely, a community","derivation":"from G4177 (πολίτης) (\"polity\");","pron":"pol-ee-ti'-ah","pos":"Noun Feminine","thayer":"<ol><li>the administration of civil affairs</li><li>a state or commonwealth</li><li>citizenship, the rights of a citizen</li></ol>","xlit":"politeía"},"G1074":{"lemma":"γενεά","translit":"geneá","kjv_def":"age, generation, nation, time","strongs_def":" a generation; by implication, an age (the period or the persons)","derivation":"from (a presumed derivative of) G1085 (γένος);","pron":"ghen-eh-ah'","pos":"Noun Feminine","thayer":"<ol><li>fathered, birth, nativity</li><li>that which has been begotten, men of the same stock, a family<ol type='a'><li>the several ranks of natural descent, the successive members of a genealogy</li><li>metaphorically a group of men very like each other in endowments, pursuits, character<ol><li>especially in a bad sense, a perverse nation</li></ol></li></ol><li>the whole multitude of men living at the same time</li><li>an age (i.e. the time ordinarily occupied be each successive generation), a space of 30 - 33 years</li></ol>","xlit":"geneá"},"G478":{"strongs_def":" to set down (troops) against, i.e. withstand","derivation":"from G473 (ἀντί) and G2525 (καθίστημι);","lemma":"ἀντικαθίστημι","translit":"antikathístēmi","kjv_def":"resist","pron":"an-tee-kath-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to put in place of another</li><li>to place in opposition<ol type='a'><li>to dispose troops, set an army in line of battle</li><li>to stand against, resist</li></ol></li></ol>","xlit":"antikathístēmi"},"G195":{"lemma":"ἀκρίβεια","translit":"akríbeia","kjv_def":"perfect manner","strongs_def":" exactness","derivation":"from the same as G196 (ἀκριβέστατος);","pron":"ak-ree'-bi-ah","pos":"Noun Feminine","thayer":"<ol><li>exactness, exactest care: in accordance with the strictness of the Mosaic law</li></ol>","xlit":"akríbeia"},"G3018":{"kjv_def":"Levi","lemma":"Λευΐς","translit":"Leuḯs","derivation":"a form of G3017 (Λευΐ);","strongs_def":" Lewis (i.e. Levi), a Christian","pron":"lyoo-is'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Levi = \"joined\"</p><ol><li>the son of Alphaeus, a collector of customs</li></ol>","xlit":"Leuḯs"},"G2529":{"derivation":"from G2596 (κατά) and G3708 (ὁράω);","strongs_def":" to behold fully, i.e. (figuratively) distinctly apprehend","kjv_def":"clearly see","translit":"kathoráō","lemma":"καθοράω","pron":"kath-or-ah'-o","pos":"Verb","thayer":"<ol><li>to look down, see from above, view from on high</li><li>to see thoroughly, perceive clearly, understand</li></ol>","xlit":"kathoráō"},"G2077":{"strongs_def":" be thou; also , third person of the same; let them be","derivation":"second person singular present imperative of G1510 (εἰμί);","lemma":"ἔστω","translit":"éstō","kjv_def":"be","pron":"es'-to","pos":"Verb","thayer":"<ol><li>third persons singular imperative of \"to be\"</li></ol>","xlit":"éstō"},"G864":{"kjv_def":"come abroad","translit":"aphiknéomai","lemma":"ἀφικνέομαι","derivation":"from G575 (ἀπό) and the base of G2425 (ἱκανός);","strongs_def":" to go (i.e. spread) forth (by rumor)","pron":"af-ik-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to come from a place</li><li>to come to, arrive</li></ol>","xlit":"aphiknéomai"},"G3810":{"kjv_def":"which corrected, instructor","lemma":"παιδευτής","translit":"paideutḗs","derivation":"from G3811 (παιδεύω);","strongs_def":" a trainer, i.e. teacher or (by implication) discipliner","pron":"pahee-dyoo-tace'","pos":"Noun Masculine","thayer":"<ol><li>an instructor, preceptor, teacher</li><li>a chastiser</li></ol>","xlit":"paideutḗs"},"G5335":{"strongs_def":" to assert","derivation":"prolongation from the same as G5346 (φημί);","lemma":"φάσκω","translit":"pháskō","kjv_def":"affirm, profess, say","pron":"fas'-ko","pos":"Verb","thayer":"<ol><li>to affirm, allege, portend or profess</li></ol>","xlit":"pháskō"},"G4701":{"strongs_def":" a sowing, i.e. (by implication) parentage","derivation":"from G4687 (σπείρω);","translit":"sporá","lemma":"σπορά","kjv_def":"seed","pron":"spor-ah'","pos":"Noun Feminine","thayer":"<ol><li>seed</li></ol>","xlit":"sporá"},"G2921":{"kjv_def":"Crispus","lemma":"Κρίσπος","translit":"Kríspos","derivation":"of Latin origin;","strongs_def":" \"crisp\"; Crispus, a Corinthian","pron":"kris'-pos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Crispus = \"curled\"</p><ol><li>the ruler of the Jewish synagogue in Corinth, baptised by Paul</li></ol>","xlit":"Kríspos"},"G2539":{"strongs_def":" and indeed, i.e. nevertheless or notwithstanding","derivation":"from G2532 (καί) and G4007 (περ);","translit":"kaíper","lemma":"καίπερ","kjv_def":"and yet, although","pron":"kah'-ee-per","pos":"Conjunction","thayer":"<ol><li>although</li></ol>","xlit":"kaíper"},"G556":{"lemma":"ἀπελαύνω","translit":"apelaúnō","kjv_def":"drive","strongs_def":" to dismiss","derivation":"from G575 (ἀπό) and G1643 (ἐλαύνω);","pron":"ap-el-ow'-no","pos":"Verb","thayer":"<ol><li>to drive away, drive off</li></ol>","xlit":"apelaúnō"},"G1660":{"strongs_def":" an advent","derivation":"from the alternate of G2064 (ἔρχομαι);","translit":"éleusis","lemma":"ἔλευσις","kjv_def":"coming","pron":"el'-yoo-sis","pos":"Noun Feminine","thayer":"<ol><li>a coming, advent</li></ol>","xlit":"éleusis"},"G1970":{"lemma":"ἐπιπνίγω","translit":"epipnígō","kjv_def":"choke","strongs_def":" to throttle upon, i.e. (figuratively) overgrow","derivation":"from G1909 (ἐπί) and G4155 (πνίγω);","pron":"ep-ee-pnee'-go","pos":"Verb","thayer":"<ol><li>to throttle upon, to overgrow, to choke</li></ol>","xlit":"epipnígō"},"G3160":{"strongs_def":" Mattatha (i.e. Mattithjah), an Israelite","derivation":"probably a shortened form of G3161 (Ματταθίας) (compare G4992 (σωτήριον));","lemma":"Ματταθά","translit":"Mattathá","kjv_def":"Mattatha","pron":"mat-tath-ah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mattatha = \"givingness\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Mattathá"},"G3580":{"derivation":"from a compound of G3581 (ξένος) and G1209 (δέχομαι);","strongs_def":" to be hospitable","kjv_def":"lodge strangers","lemma":"ξενοδοχέω","translit":"xenodochéō","pron":"xen-od-okh-eh'-o","pos":"Verb","thayer":"<ol><li>to receive and entertain hospitably, to be hospitable</li></ol>","xlit":"xenodochéō"},"G896":{"kjv_def":"Baal","translit":"Báal","lemma":"Βάαλ","derivation":"of Hebrew origin (H01168);","strongs_def":" Baal, a Phœnician deity (used as a symbol of idolatry)","pron":"bah'-al","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Baal = \"lord\"</p><ol><li>the supreme male divinity of the Phoenician and Canaanitish nations, as Ashtoreth was their supreme female divinity</li></ol>","xlit":"Báal"},"G4604":{"strongs_def":" iron","derivation":"of uncertain derivation;","lemma":"σίδηρος","translit":"sídēros","kjv_def":"iron","pron":"sid'-ay-ros","pos":"Noun Masculine","thayer":"<ol><li>iron</li></ol>","xlit":"sídēros"},"G5527":{"lemma":"χόρτασμα","translit":"chórtasma","kjv_def":"sustenance","strongs_def":" forage, i.e. food","derivation":"from G5526 (χορτάζω);","pron":"khor'-tas-mah","pos":"Noun Neuter","thayer":"<ol><li>feed, fodder for animals</li><li>food, (vegetable) sustenance, whether for men or flocks</li></ol>","xlit":"chórtasma"},"G1453":{"strongs_def":" to waken (transitively or intransitively), i.e. rouse (literally, from sleep, from sitting or lying, from disease, from death; or figuratively, from obscurity, inactivity, ruins, nonexistence)","derivation":"probably akin to the base of G58 (ἀγορά) (through the idea of collecting one's faculties);","lemma":"ἐγείρω","translit":"egeírō","kjv_def":"awake, lift (up), raise (again, up), rear up, (a-)rise (again, up), stand, take up","pron":"eg-i'-ro","pos":"Verb","thayer":"<ol><li>to arouse, cause to rise<ol type='a'><li>to arouse from sleep, to awake</li><li>to arouse from the sleep of death, to recall the dead to life</li><li>to cause to rise from a seat or bed etc.</li><li>to raise up, produce, cause to appear<ol><li>to cause to appear, bring before the public</li><li>to raise up, stir up, against one</li><li>to raise up, i.e. cause to be born</li><li>of buildings, to raise up, construct, erect</li></ol></li></ol></li></ol>","xlit":"egeírō"},"G2922":{"derivation":"neuter of a presumed derivative of G2923 (κριτής);","strongs_def":" a rule of judging (\"criterion\"), i.e. (by implication) a tribunal","kjv_def":"to judge, judgment (seat)","translit":"kritḗrion","lemma":"κριτήριον","pron":"kree-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>the instrument or means of trying or judging anything<ol type='a'><li>the rule by which one judges</li></ol><li>the place where judgment is given<ol type='a'><li>the tribunal of a judge</li><li>a bench of judges</li></ol><li>the matter judged, thing to be decided, suit, case</li></ol>","xlit":"kritḗrion"},"G3172":{"derivation":"from G3173 (μέγας);","strongs_def":" greatness, i.e. (figuratively) divinity (often God himself)","kjv_def":"majesty","lemma":"μεγαλωσύνη","translit":"megalōsýnē","pron":"meg-al-o-soo'-nay","pos":"Noun Feminine","thayer":"<ol><li>majesty<ol type='a'><li>of the majesty of God</li></ol></li></ol>","xlit":"megalōsýnē"},"G224":{"translit":"áleuron","lemma":"ἄλευρον","kjv_def":"meal","strongs_def":" flour","derivation":"from (to grind);","pron":"al'-yoo-ron","pos":"Noun Neuter","thayer":"<ol><li>wheat flour, meal</li></ol>","xlit":"áleuron"},"G3706":{"derivation":"from G3708 (ὁράω);","strongs_def":" the act of gazing, i.e. (externally) an aspect or (internally) an inspired appearance","kjv_def":"sight, vision","translit":"hórasis","lemma":"ὅρασις","pron":"hor'-as-is","pos":"Noun Feminine","thayer":"<ol><li>the act of seeing<ol type='a'><li>the sense of sight, the eyes</li></ol><li>appearance, visible form</li><li>a vision<ol type='a'><li>an appearance divinely granted in an ecstasy or dream</li></ol></li></ol>","xlit":"hórasis"},"G417":{"strongs_def":" wind; (plural) by implication, (the four) quarters (of the earth)","derivation":"from the base of G109 (ἀήρ);","translit":"ánemos","lemma":"ἄνεμος","kjv_def":"wind","pron":"an'-em-os","pos":"Noun Masculine","thayer":"<ol><li>wind, a violent agitation and stream of air</li><li>a very strong tempestuous wind</li><li>the four principal or cardinal winds, hence the four corners of heaven</li></ol>","xlit":"ánemos"},"G3907":{"kjv_def":"obervation","lemma":"παρατήρησις","translit":"paratḗrēsis","derivation":"from G3906 (παρατηρέω);","strongs_def":" inspection, i.e. ocular evidence","pron":"par-at-ay'-ray-sis","pos":"Noun Feminine","thayer":"<ol><li>observation</li></ol>","xlit":"paratḗrēsis"},"G1208":{"derivation":"as the comparative of G1417 (δύο);","strongs_def":" (ordinal) second (in time, place, or rank; also adverb)","kjv_def":"afterward, again, second(-arily, time)","translit":"deúteros","lemma":"δεύτερος","pron":"dyoo'-ter-os","pos":"Adjective","thayer":"<ol><li>the second, the other of two</li></ol>","xlit":"deúteros"},"G2412":{"derivation":"from G2413 (ἱερός) and the same as G4241 (πρέπω);","strongs_def":" reverent","kjv_def":"as becometh holiness","lemma":"ἱεροπρεπής","translit":"hieroprepḗs","pron":"hee-er-op-rep-ace'","pos":"Adjective","thayer":"<ol><li>befitting men, places, actions or sacred things to God</li><li>reverent</li></ol>","xlit":"hieroprepḗs"},"G2666":{"strongs_def":" to drink down, i.e. gulp entire (literally or figuratively)","derivation":"from G2596 (κατά) and G4095 (πίνω);","lemma":"καταπίνω","translit":"katapínō","kjv_def":"devour, drown, swallow (up)","pron":"kat-ap-ee'-no","pos":"Verb","thayer":"<ol><li>to drink down, swallow down</li><li>to devour</li><li>to swallow up, destroy</li></ol>","xlit":"katapínō"},"G4250":{"lemma":"πρίν","translit":"prín","kjv_def":"before (that), ere","strongs_def":" prior, sooner","derivation":"adverb from G4253 (πρό);","pron":"prin","pos":"Adverb","thayer":"<ol><li>before, formerly</li></ol>","xlit":"prín"},"G2888":{"lemma":"κοσμοκράτωρ","translit":"kosmokrátōr","kjv_def":"ruler","strongs_def":" a world-ruler, an epithet of Satan","derivation":"from G2889 (κόσμος) and G2902 (κρατέω);","pron":"kos-mok-rat'-ore","pos":"Noun Masculine","thayer":"<ol><li>lord of the world, prince of this age<ol type='a'><li>the devil and his demons</li></ol></li></ol>","xlit":"kosmokrátōr"},"G4155":{"strongs_def":" to wheeze, i.e. (causative, by implication) to throttle or strangle (drown)","derivation":"strengthened from G4154 (πνέω);","lemma":"πνίγω","translit":"pnígō","kjv_def":"choke, take by the throat","pron":"pnee'-go","pos":"Verb","thayer":"<ol><li>to choke, strangle<ol type='a'><li>of thorns crowding out the seed in the field and hindering its growth</li></ol><li>to wring one's neck, throttle</li></ol>","xlit":"pnígō"},"G241":{"derivation":"from G243 (ἄλλος) and G1085 (γένος);","strongs_def":" foreign, i.e. not a Jew","kjv_def":"stranger","translit":"allogenḗs","lemma":"ἀλλογενής","pron":"al-log-en-ace'","pos":"Adjective","thayer":"<ol><li>sprung from another tribe, a foreigner, alien</li></ol>","xlit":"allogenḗs"},"G3896":{"derivation":"from G3844 (παρά) and G4126 (πλέω);","strongs_def":" to sail near","kjv_def":"sail by","lemma":"παραπλέω","translit":"parapléō","pron":"par-ap-leh'-o","pos":"Verb","thayer":"<ol><li>to sail by, sail past</li></ol>","xlit":"parapléō"},"G2117":{"translit":"euthýs","lemma":"εὐθύς","kjv_def":"anon, by and by, forthwith, immediately, straightway","strongs_def":" straight, i.e. (literally) level, or (figuratively) true; adverbially (of time) at once","derivation":"perhaps from G2095 (εὖ) and G5087 (τίθημι);","pron":"yoo-thoos'","pos":"Adjective","thayer":"<ol><li>straight, level</li><li>straight forward, upright, true, sincere</li><li>straightway, immediately, forthwith</li></ol>","xlit":"euthýs"},"G4553":{"strongs_def":" a basket (as interwoven or wicker-work","derivation":"apparently of Hebrew origin (H08276);","lemma":"σαργάνη","translit":"sargánē","kjv_def":"basket","pron":"sar-gan'-ay","pos":"Noun Feminine","thayer":"<ol><li>a braided rope, a band</li><li>a basket, a basket made of ropes, a hamper</li></ol>","xlit":"sargánē"},"G4398":{"strongs_def":" a female foreteller or an inspired woman","derivation":"feminine of G4396 (προφήτης);","lemma":"προφῆτις","translit":"prophētis","kjv_def":"prophetess","pron":"prof-ay'-tis","pos":"Noun Feminine","thayer":"<ol><li>a prophetess</li><li>a woman to whom future events or things hidden from others are at times revealed, either by inspiration or by dreams and visions</li><li>a female who declares or interprets oracles</li></ol>","xlit":"prophētis"},"G5268":{"strongs_def":" an animal under the yoke (draught-beast), i.e. (specially), a donkey","derivation":"neuter of a compound of G5259 (ὑπό) and G2218 (ζυγός);","lemma":"ὑποζύγιον","translit":"hypozýgion","kjv_def":"ass","pron":"hoop-od-zoog'-ee-on","pos":"Adjective","thayer":"<ol><li>under the yoke</li><li>a beast of burden, an ass<ol type='a'><li>the ass was the common animal used by the Orientals on journey and for carrying burdens</li></ol></li></ol>","xlit":"hypozýgion"},"G2530":{"strongs_def":" and G3739 (ὅς) and G5100 (τὶς); according to which certain thing, i.e. as far (or inasmuch) as","derivation":"from G2596 (κατά);","translit":"kathóti","lemma":"καθότι","kjv_def":"(according, forasmuch) as, because (that)","pron":"kath-ot'-ee","pos":"Adverb","thayer":"<ol><li>according to what<ol type='a'><li>as far as, according as</li><li>because that, because</li><li>as just as</li></ol></li></ol>","xlit":"kathóti"},"G1778":{"lemma":"ἔνταλμα","translit":"éntalma","kjv_def":"commandment","strongs_def":" an injunction, i.e. religious precept","derivation":"from G1781 (ἐντέλλομαι);","pron":"en'-tal-mah","pos":"Noun Neuter","thayer":"<ol><li>a precept</li></ol>","xlit":"éntalma"},"G5436":{"derivation":"probably from G5343 (φεύγω);","strongs_def":" fugitive; Phygellus, an apostate Christian","kjv_def":"Phygellus","lemma":"Φύγελλος","translit":"Phýgellos","pron":"foog'-el-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Phygellus = \"a little fugitive\"</p><ol><li>a Christian who was with Paul and deserted him</li></ol>","xlit":"Phýgellos"},"G3084":{"translit":"lytróō","lemma":"λυτρόω","kjv_def":"redeem","strongs_def":" to ransom (literally or figuratively)","derivation":"from G3083 (λύτρον);","pron":"loo-tro'-o","pos":"Verb","thayer":"<ol><li>to release on receipt of ransom</li><li>to redeem, liberate by payment of ransom<ol type='a'><li>to liberate</li><li>to cause to be released to one's self by payment of a ransom</li><li>to redeem</li><li>to deliver: from evils of every kind, internal and external</li></ol></li></ol>","xlit":"lytróō"},"G2184":{"derivation":"from G1909 (ἐπί) and G2250 (ἡμέρα);","strongs_def":" for a day (\"ephemeral\"), i.e. diurnal","kjv_def":"daily","translit":"ephḗmeros","lemma":"ἐφήμερος","pron":"ef-ay'-mer-os","pos":"Adjective","thayer":"<ol><li>lasting for a day</li><li>daily</li></ol>","xlit":"ephḗmeros"},"G3113":{"lemma":"μακρόθεν","translit":"makróthen","kjv_def":"afar off, from far","strongs_def":" from a distance or afar","derivation":"adverb from G3117 (μακρός);","pron":"mak-roth'-en","pos":"Adverb","thayer":"<ol><li>from afar, afar</li></ol>","xlit":"makróthen"},"G2556":{"kjv_def":"bad, evil, harm, ill, noisome, wicked","translit":"kakós","lemma":"κακός","derivation":"apparently a primary word;","strongs_def":" worthless (intrinsically, such; whereas G4190 (πονηρός) properly refers to effects), i.e. (subjectively) depraved, or (objectively) injurious","pron":"kak-os'","pos":"Adjective","thayer":"<ol><li>of a bad nature<ol type='a'><li>not such as it ought to be</li></ol><li>of a mode of thinking, feeling, acting<ol type='a'><li>base, wrong, wicked</li></ol><li>troublesome, injurious, pernicious, destructive, baneful</li></ol>","xlit":"kakós"},"G3341":{"derivation":"from G3340 (μετανοέω);","strongs_def":" (subjectively) compunction (for guilt, including reformation); by implication, reversal (of (another's) decision)","kjv_def":"repentance","lemma":"μετάνοια","translit":"metánoia","pron":"met-an'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>a change of mind, as it appears to one who repents, of a purpose he has formed or of something he has done</li></ol>","xlit":"metánoia"},"G4082":{"kjv_def":"scrip","lemma":"πήρα","translit":"pḗra","derivation":"of uncertain affinity;","strongs_def":" a wallet or leather pouch for food","pron":"pay'-rah","pos":"Noun Feminine","thayer":"<ol><li>a wallet</li><li>a leathern sack, in which travellers and shepherds carried their provisions</li></ol>","xlit":"pḗra"},"G4514":{"derivation":"from G4516 (Ῥώμη);","strongs_def":" Romæan, i.e. Roman (as noun)","kjv_def":"Roman, of Rome","lemma":"Ῥωμαῖος","translit":"Rhōmaîos","pron":"hro-mah'-yos","pos":"Adjective","thayer":"<ol><li>a resident of the city of Rome, a Roman citizen</li></ol>","xlit":"Rhōmaîos"},"G4646":{"derivation":"from the base of G4628 (σκέλος);","strongs_def":" warped, i.e. winding; figuratively, perverse","kjv_def":"crooked, froward, untoward","translit":"skoliós","lemma":"σκολιός","pron":"skol-ee-os'","pos":"Adjective","thayer":"<ol><li>crooked, curved</li><li>metaphorically<ol type='a'><li>perverse, wicked</li><li>unfair, surly, froward</li></ol></li></ol>","xlit":"skoliós"},"G302":{"derivation":"a primary particle, denoting a supposition, wish, possibility or uncertainty","kjv_def":"(what-, where-, wither-, who-)soever","translit":"án","lemma":"ἄν","pron":"an","thayer":"<ol><li>has no exact English equivalent, see definitions under AV</li></ol>","xlit":"án"},"G2181":{"strongs_def":" Ephesus, a city of Asia Minor","derivation":"probably of foreign origin;","translit":"Éphesos","lemma":"Ἔφεσος","kjv_def":"Ephesus","pron":"ef'-es-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Ephesus = \"permitted\"</p><ol><li>a maritime city of Asia Minor, capital of Ionia and under the Romans, of proconsular Asia, situated on the Icarian Sea between Smyrna and Miletus</li></ol>","xlit":"Éphesos"},"G2875":{"derivation":"a primary verb;","strongs_def":" to \"chop\"; specially, to beat the breast in grief","kjv_def":"cut down, lament, mourn, (be-)wail","translit":"kóptō","lemma":"κόπτω","pron":"kop'-to","pos":"Verb","thayer":"<ol><li>to cut, strike, smite</li><li>to cut from, cut off</li><li>to beat one's breast for grief</li></ol>","xlit":"kóptō"},"G1675":{"derivation":"from a derivative of G1672 (Ἕλλην);","strongs_def":" a Hellenist or Greek-speaking Jew","kjv_def":"Grecian","translit":"Hellēnistḗs","lemma":"Ἑλληνιστής","pron":"hel-lay-nis-tace'","pos":"Noun Masculine","thayer":"<ol><li>a Hellenist<ol type='a'><li>one who imitates the manners and customs or the worship of the Greeks, and use the Greek tongue</li><li>used in the NT of Jews born in foreign lands and speaking Greek</li></ol></li></ol>","xlit":"Hellēnistḗs"},"G1272":{"kjv_def":"open","translit":"dianoígō","lemma":"διανοίγω","derivation":"from G1223 (διά) and G455 (ἀνοίγω);","strongs_def":" to open thoroughly, literally (as a first-born) or figuratively (to expound)","pron":"dee-an-oy'-go","pos":"Verb","thayer":"<ol><li>to open by dividing or drawing asunder, to open thoroughly<ol type='a'><li>a male opening the womb (the closed matrix), i.e. the first-born</li><li>of the eyes and the ears</li><li>to open the mind of one, i.e. to cause to understand a thing<ol><li>to open one's soul, i.e. to rouse in one the faculty of understanding or the desire of learning</li></ol></li></ol></li></ol>","xlit":"dianoígō"},"G2348":{"derivation":"a strengthened form of a simpler primary (which is used for it only in certain tenses);","strongs_def":" to die (literally or figuratively)","kjv_def":"be dead, die","lemma":"θνήσκω","translit":"thnḗskō","pron":"thnay'-sko","pos":"Verb","thayer":"<ol><li>to die, to be dead</li><li>metaphorically to be spiritually dead</li></ol>","xlit":"thnḗskō"},"G541":{"lemma":"ἀπαύγασμα","translit":"apaúgasma","kjv_def":"brightness","strongs_def":" an off-flash, i.e. effulgence","derivation":"from a compound of G575 (ἀπό) and G826 (αὐγάζω);","pron":"ap-ow'-gas-mah","pos":"Noun Neuter","thayer":"<ol><li>reflected brightness<ol type='a'><li>of Christ in that he perfectly reflects the majesty of God</li></ol><li>effulgence<ol type='a'><li>shining forth, of a light coming from a luminous body (Vine)</li><li>out-raying (Vincent)</li></ol></li></ol>","xlit":"apaúgasma"},"G3480":{"lemma":"Ναζωραῖος","translit":"Nazōraîos","kjv_def":"Nazarene, of Nazareth","strongs_def":" a Nazoræan, i.e. inhabitant of Nazareth; by extension, a Christian","derivation":"from G3478 (Ναζαρέθ);","pron":"nad-zo-rah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nazarite = \"one separated\"</p><ol><li>an inhabitant of Nazareth</li><li>a title given to Jesus in the NT</li><li>a name given to Christians by the Jews, <a class='bible' href='#b44.24.5'>Act 24:5</a></li></ol>","xlit":"Nazōraîos"},"G3021":{"kjv_def":"make white, whiten","lemma":"λευκαίνω","translit":"leukaínō","derivation":"from G3022 (λευκός);","strongs_def":" to whiten","pron":"lyoo-kah'-ee-no","pos":"Verb","thayer":"<ol><li>to whiten, make white</li></ol>","xlit":"leukaínō"},"G4105":{"kjv_def":"go astray, deceive, err, seduce, wander, be out of the way","lemma":"πλανάω","translit":"planáō","derivation":"from G4106 (πλάνη);","strongs_def":" to (properly, cause to) roam (from safety, truth, or virtue)","pron":"plan-ah'-o","pos":"Verb","thayer":"<ol><li>to cause to stray, to lead astray, lead aside from the right way<ol type='a'><li>to go astray, wander, roam about</li></ol><li>metaphorically<ol type='a'><li>to lead away from the truth, to lead into error, to deceive</li><li>to be led into error</li><li>to be led aside from the path of virtue, to go astray, sin</li><li>to sever or fall away from the truth<ol><li>of heretics</li></ol><li>to be led away into error and sin</li></ol></li></ol>","xlit":"planáō"},"G5187":{"lemma":"τυφόω","translit":"typhóō","kjv_def":"high-minded, be lifted up with pride, be proud","strongs_def":" to envelop with smoke, i.e. (figuratively) to inflate with self-conceit","derivation":"from a derivative of G5188 (τύφω);","pron":"toof-o'-o","pos":"Verb","thayer":"<ol><li>to raise a smoke, to wrap in a mist<ol type='a'><li>metaphorically<ol><li>to make proud, puff up with pride, render insolent</li><li>to be puffed up with haughtiness or pride</li></ol></li></ol><li>to blind with pride or conceit, to render foolish or stupid<ol type='a'><li>beclouded, besotted</li></ol></li></ol>","xlit":"typhóō"},"G5556":{"strongs_def":" a greenish-yellow gem (\"chrysoprase\")","derivation":"from G5557 (χρυσός) and (a leek);","translit":"chrysóprasos","lemma":"χρυσόπρασος","kjv_def":"chrysoprase","pron":"khroo-sop'-ras-os","pos":"Noun Masculine","thayer":"<ol><li>chrysoprasus is a stone of green colour, inclined to that of gold, from whence it has its name; for this is agate in the breast plate, which was Naphtali's stone. (Gill)</li></ol>","xlit":"chrysóprasos"},"G4692":{"derivation":"probably strengthened from G4228 (πούς);","strongs_def":" to \"speed\" (\"study\"), i.e. urge on (diligently or earnestly); by implication, to await eagerly","kjv_def":"(make, with) haste unto","lemma":"σπεύδω","translit":"speúdō","pron":"spyoo'-do","pos":"Verb","thayer":"<ol><li>to haste, make haste</li><li>to desire earnestly</li></ol>","xlit":"speúdō"},"G3013":{"lemma":"λεπίς","translit":"lepís","kjv_def":"scale","strongs_def":" a flake","derivation":"from (to peel);","pron":"lep-is'","pos":"Noun Feminine","thayer":"<ol><li>a scale</li></ol>","xlit":"lepís"},"G2941":{"strongs_def":" pilotage, i.e. (figuratively) directorship (in the church)","derivation":"from (of Latin origin, to steer);","translit":"kybérnēsis","lemma":"κυβέρνησις","kjv_def":"government","pron":"koo-ber'-nay-sis","pos":"Noun Feminine","thayer":"<ol><li>a governing, government</li></ol>","xlit":"kybérnēsis"},"G5036":{"derivation":"of uncertain affinity;","strongs_def":" fleet, i.e. (figuratively) prompt or ready","kjv_def":"swift","lemma":"ταχύς","translit":"tachýs","pron":"takh-oos'","pos":"Adjective","thayer":"<ol><li>quick, fleet, speedy</li></ol>","xlit":"tachýs"},"G3351":{"derivation":"from the same as G3350 (μετοικεσία);","strongs_def":" to transfer as a settler or captive, i.e colonize or exile","kjv_def":"carry away, remove into","lemma":"μετοικίζω","translit":"metoikízō","pron":"met-oy-kid'-zo","pos":"Verb","thayer":"<ol><li>to transfer settlers</li><li>to cause to remove into another land</li></ol>","xlit":"metoikízō"},"G2777":{"kjv_def":"volume","translit":"kephalís","lemma":"κεφαλίς","derivation":"from G2776 (κεφαλή);","strongs_def":" properly, a knob, i.e. (by implication) a roll (by extension from the end of a stick on which the manuscript was rolled)","pron":"kef-al-is'","pos":"Noun Feminine","thayer":"<ol><li>a little head</li><li>the highest part, extremity of anything<ol type='a'><li>as the capital of a column</li><li>the tips or knobs of the wooden rod around which parchments were rolled were called by this word, because they resembled little heads</li></ol><li>the Alexandrian writers transferred the name to the roll or volume itself<ol type='a'><li>in the roll of the book</li></ol></li></ol>","xlit":"kephalís"},"G1948":{"kjv_def":"give sentence","translit":"epikrínō","lemma":"ἐπικρίνω","derivation":"from G1909 (ἐπί) and G2919 (κρίνω);","strongs_def":" to adjudge","pron":"ep-ee-kree'-no","pos":"Verb","thayer":"<ol><li>to adjudge, approve by one's decision, decree, give sentence</li></ol>","xlit":"epikrínō"},"G2677":{"kjv_def":"perfecting","lemma":"καταρτισμός","translit":"katartismós","derivation":"from G2675 (καταρτίζω);","strongs_def":" complete furnishing (objectively)","pron":"kat-ar-tis-mos'","pos":"Noun Masculine","thayer":"<ol><li>complete furnishing, equipping</li></ol>","xlit":"katartismós"},"G5593":{"translit":"psychrós","lemma":"ψυχρός","kjv_def":"cold","strongs_def":" chilly (literally or figuratively)","derivation":"from G5592 (ψύχος);","pron":"psoo-chros'","pos":"Adjective","thayer":"<ol><li>cold, cool<ol type='a'><li>of cool water</li></ol><li>metaphorically<ol type='a'><li>cold, i.e. sluggish, inert</li><li>in mind: of one destitute of warm Christian faith and the desire for holiness</li></ol></li></ol>","xlit":"psychrós"},"G5360":{"translit":"philadelphía","lemma":"φιλαδελφία","kjv_def":"brotherly love (kindness), love of the brethren","strongs_def":" fraternal affection","derivation":"from G5361 (φιλάδελφος);","pron":"fil-ad-el-fee'-ah","pos":"Noun Feminine","thayer":"<ol><li>love of brothers or sisters, brotherly love</li><li>in the NT the love which Christians cherish for each other as brethren</li></ol>","xlit":"philadelphía"},"G426":{"derivation":"from G303 (ἀνά) and (to test);","strongs_def":" to investigate (judicially)","kjv_def":"(should have) examined(-d)","lemma":"ἀνετάζω","translit":"anetázō","pron":"an-et-ad'-zo","pos":"Verb","thayer":"<ol><li>to investigate, to examine</li><li>to examine judicially</li></ol>","xlit":"anetázō"},"G5207":{"strongs_def":" a \"son\" (sometimes of animals), used very widely of immediate, remote or figuratively, kinship","derivation":"apparently a primary word;","lemma":"υἱός","translit":"huiós","kjv_def":"child, foal, son","pron":"hwee-os'","pos":"Noun Masculine","thayer":"<ol><li>a son<ol type='a'><li>rarely used for the young of animals</li><li>generally used of the offspring of men</li><li>in a restricted sense, the male offspring (one born by a father and of a mother)</li><li>in a wider sense, a descendant, one of the posterity of any one<ol><li>the children of Israel</li><li>sons of Abraham</li></ol><li>used to describe one who depends on another or is his follower<ol><li>a pupil</li></ol></li></ol><li>son of man<ol type='a'><li>term describing man, carrying the connotation of weakness and mortality</li><li>son of man, symbolically denotes the fifth kingdom in <a class='bible' href='#b27.7.13'>Dan 7:13</a> and by this term its humanity is indicated in contrast with the barbarity and ferocity of the four preceding kingdoms (the Babylonian, the Median and the Persian, the Macedonian, and the Roman) typified by the four beasts. In the book of Enoch (2nd Century) it is used of Christ.</li><li>used by Christ himself, doubtless in order that he might intimate his Messiahship and also that he might designate himself as the head of the human family, the man, the one who both furnished the pattern of the perfect man and acted on behalf of all mankind. Christ seems to have preferred this to the other Messianic titles, because by its lowliness it was least suited to foster the expectation of an earthly Messiah in royal splendour.</li></ol><li>son of God<ol type='a'><li>used to describe Adam (<a class='bible' href='#b42.3.38'>Luk 3:38</a>)</li><li>used to describe those who are born again (<a class='bible' href='#b42.20.36'>Luk 20:36</a>) and of angels and of Jesus Christ</li><li>of those whom God esteems as sons, whom he loves, protects and benefits above others<ol><li>in the OT used of the Jews</li><li>in the NT of Christians</li><li>those whose character God, as a loving father, shapes by chastisements (<a class='bible' href='#b58.12.5-8'>Heb 12:5-8</a>)</li></ol><li>those who revere God as their father, the pious worshippers of God, those who in character and life resemble God, those who are governed by the Spirit of God, repose the same calm and joyful trust in God which children do in their parents (<a class='bible' href='#b45.8.14'>Rom 8:14</a>, <a class='bible' href='#b48.3.26'>Gal 3:26</a> ), and hereafter in the blessedness and glory of the life eternal will openly wear this dignity of the sons of God. Term used preeminently of Jesus Christ, as enjoying the supreme love of God, united to him in affectionate intimacy, privy to his saving councils, obedient to the Father's will in all his acts</li></ol></li></ol>","xlit":"huiós"},"G5186":{"strongs_def":" to make blind, i.e. (figuratively) to obscure","derivation":"from G5185 (τυφλός);","lemma":"τυφλόω","translit":"typhlóō","kjv_def":"blind","pron":"toof-lo'-o","pos":"Verb","thayer":"<ol><li>to blind, make blind</li><li>in the NT metaphorically to blunt the mental discernment, darken the mind</li></ol>","xlit":"typhlóō"},"G1273":{"derivation":"from G1223 (διά) and a derivative of G3571 (νύξ);","strongs_def":" to sit up the whole night","kjv_def":"continue all night","translit":"dianyktereúō","lemma":"διανυκτερεύω","pron":"dee-an-ook-ter-yoo'-o","pos":"Verb","thayer":"<ol><li>to spend the night, to pass the whole night</li></ol>","xlit":"dianyktereúō"},"G2732":{"derivation":"from a derivative of G2730 (κατοικέω);","strongs_def":" a dwelling-place","kjv_def":"habitation","translit":"katoikētḗrion","lemma":"κατοικητήριον","pron":"kat-oy-kay-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>an abode, a habitation</li></ol>","xlit":"katoikētḗrion"},"G4406":{"strongs_def":" dawning, i.e. (by analogy) autumnal (showering, the first of the rainy season)","derivation":"from G4404 (πρωΐ);","lemma":"πρώϊμος","translit":"prṓïmos","kjv_def":"early","pron":"pro'-ee-mos","pos":"Adjective","thayer":"<ol><li>early<ol type='a'><li>of the early rain which fell from October on</li></ol></li></ol>","xlit":"prṓïmos"},"G697":{"translit":"Áreios Págos","lemma":"Ἄρειος Πάγος","kjv_def":"Areopagus, Mars' Hill","strongs_def":" rock of Ares, a place in Athens","derivation":"from (the name of the Greek deity of war) and a derivative of G4078 (πήγνυμι);","pron":"ar'-i-os pag'-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Areopagus = \"martial peak\"</p><ol><li>a rocky height in the city of Athens, opposite the western end of the Acropolis toward the west.</li></ol>","xlit":"Áreios Págos"},"G2073":{"derivation":"feminine of an adjective hesperos (evening); the eve (G5610 (ὥρα) being implied)","lemma":"ἑσπέρα","translit":"hespéra","kjv_def":"evening(-tide)","pron":"hes-per'-ah","pos":"Noun Feminine","thayer":"<ol><li>evening, eventide</li></ol>","xlit":"hespéra"},"G2710":{"derivation":"from G2596 (κατά) and G5530 (χράομαι);","strongs_def":" to overuse, i.e. misuse","kjv_def":"abuse","lemma":"καταχράομαι","translit":"katachráomai","pron":"kat-akh-rah'-om-ahee","pos":"Verb","thayer":"<ol><li>to use much or excessively or ill</li><li>to use up, consume by use</li><li>to use fully</li></ol>","xlit":"katachráomai"},"G2102":{"strongs_def":" quite agreeably","derivation":"adverb from G2101 (εὐάρεστος);","lemma":"εὐαρέστως","translit":"euaréstōs","kjv_def":"acceptably, + please well","pron":"yoo-ar-es'-toce","pos":"Adverb","thayer":"<ol><li>in a manner well pleasing to one, acceptable</li></ol>","xlit":"euaréstōs"},"G5032":{"strongs_def":" more swiftly, i.e. (in manner) more rapidly, or (in time) more speedily","derivation":"neuter singular of the comparative of G5036 (ταχύς) (as adverb);","lemma":"τάχιον","translit":"táchion","kjv_def":"out (run), quickly, shortly, sooner","pron":"takh'-ee-on","pos":"Adverb","thayer":"<ol><li>more swiftly, more quickly</li></ol>","xlit":"táchion"},"G598":{"lemma":"ἀποθλίβω","translit":"apothlíbō","kjv_def":"press","strongs_def":" to crowd (from every side)","derivation":"from G575 (ἀπό) and G2346 (θλίβω);","pron":"ap-oth-lee'-bo","pos":"Verb","thayer":"<ol><li>to press on all sides, squeeze, press hard<ol type='a'><li>of pressing out grapes and olives</li></ol></li></ol>","xlit":"apothlíbō"},"G1260":{"derivation":"from G1223 (διά) and G3049 (λογίζομαι);","strongs_def":" to reckon thoroughly, i.e. (genitive case) to deliberate (by reflection or discussion)","kjv_def":"cast in mind, consider, dispute, muse, reason, think","lemma":"διαλογίζομαι","translit":"dialogízomai","pron":"dee-al-og-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to bring together different reasons, to reckon up the reasons, to reason, revolve in one's mind, deliberate</li></ol>","xlit":"dialogízomai"},"G2625":{"translit":"kataklínō","lemma":"κατακλίνω","kjv_def":"(make) sit down (at meat)","strongs_def":" to recline down, i.e. (specially) to take a place at table","derivation":"from G2596 (κατά) and G2827 (κλίνω);","pron":"kat-ak-lee'-no","pos":"Verb","thayer":"<ol><li>in the NT in reference to eating, to make to recline</li><li>to recline (at a table)</li></ol>","xlit":"kataklínō"},"G2153":{"kjv_def":"godly","translit":"eusebōs","lemma":"εὐσεβῶς","derivation":"adverb from G2152 (εὐσεβής);","strongs_def":" piously","pron":"yoo-seb-oce'","pos":"Adverb","thayer":"<ol><li>piously, godly</li></ol>","xlit":"eusebōs"},"G5002":{"lemma":"τακτός","translit":"taktós","kjv_def":"set","strongs_def":" arranged, i.e. appointed or stated","derivation":"from G5021 (τάσσω);","pron":"tak-tos'","pos":"Adjective","thayer":"<ol><li>ordered, arranged, fixed, stated</li></ol>","xlit":"taktós"},"G482":{"translit":"antilambánomai","lemma":"ἀντιλαμβάνομαι","kjv_def":"help, partaker, support","strongs_def":" to take hold of in turn, i.e. succor; also to participate","derivation":"from G473 (ἀντί) and the middle voice of G2983 (λαμβάνω);","pron":"an-tee-lam-ban'-om-ahee","pos":"Verb","thayer":"<ol><li>to lay hold of, hold fast to anything</li><li>to take a person or thing in order as it were to be held, to take to, embrace</li><li>to help, to be a partaker of, partake of (the benefits of the services rendered by the slaves)</li></ol>","xlit":"antilambánomai"},"G2082":{"strongs_def":" interior","derivation":"comparative of G2080 (ἔσω);","translit":"esṓteros","lemma":"ἐσώτερος","kjv_def":"inner, within","pron":"es-o'-ter-os","pos":"Adjective","thayer":"<ol><li>inner<ol type='a'><li>the inner space which is behind the veil</li><li>the shrine, the Holy of Holies, said of heaven by a figure drawn from earthly temple</li></ol></li></ol>","xlit":"esṓteros"},"G4258":{"kjv_def":"sin already, heretofore sin","lemma":"προαμαρτάνω","translit":"proamartánō","derivation":"from G4253 (πρό) and G264 (ἁμαρτάνω);","strongs_def":" to sin previously (to conversion)","pron":"pro-am-ar-tan'-o","pos":"Verb","thayer":"<ol><li>to sin before<ol type='a'><li>of those who before receiving baptism had been guilty of the vices especially common among the Gentiles</li></ol></li></ol>","xlit":"proamartánō"},"G2482":{"kjv_def":"Italy","lemma":"Ἰταλία","translit":"Italía","derivation":"probably of foreign origin;","strongs_def":" Italia, a region of Europe","pron":"ee-tal-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Italy = \"calf like\"</p><ol><li>the whole peninsula between the Alps and the Straits of Messina</li></ol>","xlit":"Italía"},"G1350":{"strongs_def":" a seine (for fishing)","derivation":"probably from a primary verb (to cast);","translit":"díktyon","lemma":"δίκτυον","kjv_def":"net","pron":"dik'-too-on","pos":"Noun Neuter","thayer":"<ol><li>a net</li></ol>","xlit":"díktyon"},"G160":{"kjv_def":"sudden, unawares","translit":"aiphnídios","lemma":"αἰφνίδιος","derivation":"from a compound of G1 (Α) (as a negative particle) and G5316 (φαίνω) (compare G1810 (ἐξαίφνης)) (meaning non-apparent);","strongs_def":" unexpected, i.e. (adverbially) suddenly","pron":"aheef-nid'-ee-os","pos":"Adjective","thayer":"<ol><li>unexpected, sudden, unforeseen</li></ol>","xlit":"aiphnídios"},"G3561":{"lemma":"νουμηνία","translit":"noumēnía","kjv_def":"new moon","strongs_def":" the festival of new moon","derivation":"feminine of a compound of G3501 (νέος) and G3376 (μήν) (as noun by implication, of G2250 (ἡμέρα));","pron":"noo-may-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>new moon<ol type='a'><li>of the Jewish festival of the new moon</li></ol></li></ol>","xlit":"noumēnía"},"G5342":{"translit":"phérō","lemma":"φέρω","kjv_def":"be, bear, bring (forth), carry, come, + let her drive, be driven, endure, go on, lay, lead, move, reach, rushing, uphold","strongs_def":" to \"bear\" or carry (in a very wide application, literally and figuratively, as follows)","derivation":"a primary verb (for which other, and apparently not cognate ones are used in certain tenses only; namely, ; and ;","pron":"fer'-o","pos":"Verb","thayer":"<ol><li>to carry<ol type='a'><li>to carry some burden<ol><li>to bear with one's self</li></ol><li>to move by bearing; move or, to be conveyed or borne, with the suggestion of force or speed<ol><li>of persons borne in a ship over the sea</li><li>of a gust of wind, to rush</li><li>of the mind, to be moved inwardly, prompted</li></ol><li>to bear up, i.e. uphold (keep from falling)<ol><li>of Christ, the preserver of the universe</li></ol></li></ol><li>to bear, i.e. endure, to endure the rigour of a thing, to bear patiently one's conduct, or spare one (abstain from punishing or destroying)</li><li>to bring, bring to, bring forward<ol type='a'><li>to move to, apply</li><li>to bring in by announcing, to announce</li><li>to bear, i.e. bring forth, produce; to bring forward in a speech</li><li>to lead, conduct</li></ol></li></ol>","xlit":"phérō"},"G3128":{"translit":"Manassēs","lemma":"Μανασσῆς","kjv_def":"Manasses","strongs_def":" Mannasses (i.e. Menashsheh), an Israelite","derivation":"of Hebrew origin (H04519);","pron":"man-as-sace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Manasseh = \"forgetting\"</p><ol><li>the first born son of Joseph</li><li>the son of Hezekiah, king of Judah</li></ol>","xlit":"Manassēs"},"G522":{"strongs_def":" to lift off, i.e. remove","derivation":"from G575 (ἀπό) and G142 (αἴρω);","translit":"apaírō","lemma":"ἀπαίρω","kjv_def":"take (away)","pron":"ap-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to lift off, take or carry away</li><li>to be taken away from anyone</li></ol>","xlit":"apaírō"},"G176":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G2607 (καταγινώσκω);","strongs_def":" unblamable","kjv_def":"that cannot be condemned","lemma":"ἀκατάγνωστος","translit":"akatágnōstos","pron":"ak-at-ag'-noce-tos","pos":"Adjective","thayer":"<ol><li>that cannot be condemned, not to be censored</li></ol>","xlit":"akatágnōstos"},"G1509":{"lemma":"εἰ μή τι","translit":"ei mḗ ti","kjv_def":"except","strongs_def":" if not somewhat","derivation":"from G1508 (εἰ μή) and the neuter of G5100 (τὶς);","pron":"i may tee","pos":"Conjunction","thayer":"<ol><li>unless indeed, except, unless perhaps</li></ol>","xlit":"ei mḗ ti"},"G1688":{"derivation":"from G1722 (ἐν) and (to mount;","strongs_def":" causative of G1684 (ἐμβαίνω)); to place on, i.e. transfer (aboard a vessel)","kjv_def":"put in","translit":"embibázō","lemma":"ἐμβιβάζω","pron":"em-bib-ad'-zo","pos":"Verb","thayer":"<ol><li>to put in or on, lead in, cause to enter</li></ol>","xlit":"embibázō"},"G2405":{"kjv_def":"office of the priesthood, priest's office","lemma":"ἱερατεία","translit":"hierateía","derivation":"from G2407 (ἱερατεύω);","strongs_def":" priestliness, i.e. the sacerdotal function","pron":"hee-er-at-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>the priesthood, the office of a priest</li></ol>","xlit":"hierateía"},"G4279":{"lemma":"προεπαγγέλλομαι","translit":"proepangéllomai","kjv_def":"promise before","strongs_def":" to promise of old","derivation":"middle voice from G4253 (πρό) and G1861 (ἐπαγγέλλω);","pron":"pro-ep-ang-ghel'-lom-ahee","pos":"Verb","thayer":"<ol><li>to announce before</li><li>to promise before</li></ol>","xlit":"proepangéllomai"},"G1351":{"lemma":"δίλογος","translit":"dílogos","kjv_def":"double-tongued","strongs_def":" equivocal, i.e. telling a different story","derivation":"from G1364 (δίς) and G3056 (λόγος);","pron":"dil'-og-os","pos":"Verb","thayer":"<ol><li>saying the same thing twice, repeating</li><li>double tongued, double in speech, saying one thing with one person another with another (with the intent to deceive)</li></ol>","xlit":"dílogos"},"G2804":{"kjv_def":"Claudius","lemma":"Κλαύδιος","translit":"Klaúdios","derivation":"of Latin origin;","strongs_def":" Claudius, the name of two Romans","pron":"klow'-dee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Claudius = \"lame\"</p><ol><li>C. Caesar the name of the fourth Roman emperor, who came to power in 41 A.D. and was poisoned by his wife Agrippina, in 54 A.D.</li><li>C. Lysias a tribune of the Roman cohort who rescued Paul from the hands of the mob at Jerusalem</li></ol>","xlit":"Klaúdios"},"G5105":{"strongs_def":" truly for then, i.e. consequently","derivation":"from G5104 (τοί) and G1063 (γάρ) and G3767 (οὖν);","lemma":"τοιγαροῦν","translit":"toigaroûn","kjv_def":"there-(where-)fore","pron":"toy-gar-oon'","thayer":"<ol><li>wherefore then, for which reason, therefore, consequently</li></ol>","xlit":"toigaroûn"},"G1182":{"strongs_def":" tenth","derivation":"ordinal from G1176 (δέκα);","lemma":"δέκατος","translit":"dékatos","kjv_def":"tenth","pron":"dek'-at-os","pos":"Adjective","thayer":"<ol><li>the tenth</li></ol>","xlit":"dékatos"},"G4682":{"kjv_def":"rend, tear","lemma":"σπαράσσω","translit":"sparássō","derivation":"prolongation from (to grasp;","strongs_def":" apparently strengthened from G4685 (σπάω) through the idea of spasmodic contraction); to mangle, i.e. convluse with epilepsy","pron":"spar-as'-so","pos":"Verb","thayer":"<ol><li>to convulse, tear</li></ol>","xlit":"sparássō"},"G1285":{"derivation":"from G1223 (διά) and (clear);","strongs_def":" to clear thoroughly, i.e. (figuratively) declare","kjv_def":"tell unto","translit":"diasaphéō","lemma":"διασαφέω","pron":"dee-as-af-eh'-o","pos":"Verb","thayer":"<ol><li>to make clear or plain, to explain, unfold, declare</li><li>of things done, to declare, i.e. to tell, announce, narrate</li></ol>","xlit":"diasaphéō"},"G56":{"derivation":"from G1 (Α) (as negative particle) and G1108 (γνῶσις);","strongs_def":" ignorance (properly, the state)","kjv_def":"ignorance, not the knowledge","translit":"agnōsía","lemma":"ἀγνωσία","pron":"ag-no-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>not knowing, ignorance</li></ol>","xlit":"agnōsía"},"G4076":{"strongs_def":" rue (from its thick or fleshy leaves)","derivation":"from G4078 (πήγνυμι);","lemma":"πήγανον","translit":"pḗganon","kjv_def":"rue","pron":"pay'-gan-on","pos":"Noun Neuter","thayer":"<ol><li>rue</li><li>a shrubby plant about 2 feet (60 cm) high, of medicinal value</li></ol>","xlit":"pḗganon"},"G1014":{"kjv_def":"be disposed, minded, intend, list, (be, of own) will (-ing)","lemma":"βούλομαι","translit":"boúlomai","derivation":"middle voice of a primary verb;","strongs_def":" to \"will,\" i.e. (reflexively) be willing","pron":"boo'-lom-ahee","pos":"Verb","thayer":"<ol><li>to will deliberately, have a purpose, be minded</li><li>of willing as an affection, to desire</li></ol>","xlit":"boúlomai"},"G4366":{"kjv_def":"beat vehemently against (upon)","translit":"prosrḗgnymi","lemma":"προσρήγνυμι","derivation":"from G4314 (πρός) and G4486 (ῥήγνυμι);","strongs_def":" to tear towards, i.e. burst upon (as a tempest or flood)","pron":"pros-rayg'-noo-mee","pos":"Verb","thayer":"<ol><li>to break against, break by dashing against</li></ol>","xlit":"prosrḗgnymi"},"G2432":{"strongs_def":" alacrity","derivation":"from G2431 (ἱλαρός);","translit":"hilarótēs","lemma":"ἱλαρότης","kjv_def":"cheerfulness","pron":"hil-ar-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>cheerfulness, readiness of mind</li></ol>","xlit":"hilarótēs"},"G736":{"kjv_def":"mainsail","translit":"artémōn","lemma":"ἀρτέμων","derivation":"from a derivative of G737 (ἄρτι);","strongs_def":" properly, something ready (or else more remotely from G142 (αἴρω) (compare G740 (ἄρτος)); something hung up), i.e. (specially) the topsail (rather foresail or jib) of a vessel","pron":"ar-tem'-ohn","pos":"Noun Masculine","thayer":"<ol><li>a top-sail or foresail of a ship</li></ol>","xlit":"artémōn"},"G1385":{"kjv_def":"beam","translit":"dokós","lemma":"δοκός","derivation":"from G1209 (δέχομαι) (through the idea of holding up);","strongs_def":" a stick of timber","pron":"dok-os'","pos":"Noun Feminine","thayer":"<ol><li>a beam</li></ol>","xlit":"dokós"},"G4585":{"strongs_def":" fine wheaten flour","derivation":"probably of foreign origin;","lemma":"σεμίδαλις","translit":"semídalis","kjv_def":"fine flour","pron":"sem-id'-al-is","pos":"Noun Feminine","thayer":"<ol><li>the finest wheat flour</li></ol>","xlit":"semídalis"},"G4039":{"translit":"perioikéō","lemma":"περιοικέω","kjv_def":"dwell round about","strongs_def":" to reside around, i.e. be a neighbor","derivation":"from G4012 (περί) and G3611 (οἰκέω);","pron":"per-ee-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell round about, to be one's neighbour</li></ol>","xlit":"perioikéō"},"G801":{"strongs_def":" unintelligent; by implication, wicked","derivation":"from G1 (Α) (as a negative particle) and G4908 (συνετός);","translit":"asýnetos","lemma":"ἀσύνετος","kjv_def":"foolish, without understanding","pron":"as-oon'-ay-tos","pos":"Adjective","thayer":"<ol><li>unintelligent, without understanding, stupid</li></ol>","xlit":"asýnetos"},"G1111":{"strongs_def":" to grumble","derivation":"of uncertain derivation;","lemma":"γογγύζω","translit":"gongýzō","kjv_def":"murmur","pron":"gong-good'-zo","pos":"Verb","thayer":"<ol><li>to murmur, mutter, grumble, say anything against in a low tone<ol type='a'><li>of the cooing of doves</li><li>of those who confer secretly together</li><li>of those who discontentedly complain</li></ol></li></ol>","xlit":"gongýzō"},"G3149":{"lemma":"μαστός","translit":"mastós","kjv_def":"pap","strongs_def":" a (properly, female) breast (as if kneaded up)","derivation":"from the base of G3145 (μασσάομαι);","pron":"mas-tos'","pos":"Noun Masculine","thayer":"<ol><li>the breasts</li><li>the breasts (nipples) of a man</li><li>breasts of a women</li></ol>","xlit":"mastós"},"G5039":{"kjv_def":"infallible proof","translit":"tekmḗrion","lemma":"τεκμήριον","derivation":"neuter of a presumed derivative of (a goal or fixed limit);","strongs_def":" a token (as defining a fact), i.e. criterion of certainty","pron":"tek-may'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>that from which something is surely and plainly known</li><li>on indubitable evidence, a proof</li></ol>","xlit":"tekmḗrion"},"G1568":{"strongs_def":" to astonish utterly","derivation":"from G1569 (ἔκθαμβος);","translit":"ekthambéō","lemma":"ἐκθαμβέω","kjv_def":"affright, greatly (sore) amaze","pron":"ek-tham-beh'-o","pos":"Verb","thayer":"<ol><li>to throw into terror or amazement<ol type='a'><li>to alarm thoroughly, to terrify</li></ol><li>to be struck with amazement<ol type='a'><li>to be thoroughly amazed, astounded</li><li>to be struck with terror</li></ol></li></ol>","xlit":"ekthambéō"},"G5570":{"derivation":"from G5571 (ψευδής) and G652 (ἀπόστολος);","strongs_def":" a spurious apostle, i.e. pretended pracher","kjv_def":"false teacher","lemma":"ψευδαπόστολος","translit":"pseudapóstolos","pron":"psyoo-dap-os'-tol-os","pos":"Noun Masculine","thayer":"<ol><li>a false apostle, one who falsely claims to be an ambassador of Christ</li></ol>","xlit":"pseudapóstolos"},"G5395":{"translit":"phlóx","lemma":"φλόξ","kjv_def":"flame(-ing)","strongs_def":" a blaze","derivation":"from a primary (to \"flash\" or \"flame\");","pron":"flox","pos":"Noun Feminine","thayer":"<ol><li>a flame</li></ol>","xlit":"phlóx"},"G2845":{"kjv_def":"bed, chambering, X conceive","translit":"koítē","lemma":"κοίτη","derivation":"from G2749 (κεῖμαι);","strongs_def":" a couch; by extension, cohabitation; by implication, the male sperm","pron":"koy'-tay","pos":"Noun Feminine","thayer":"<ol><li>a place for laying down, resting, sleeping in<ol type='a'><li>a bed, couch</li></ol><li>the marriage bed<ol type='a'><li>of adultery</li></ol><li>cohabitation, whether lawful or unlawful<ol type='a'><li>sexual intercourse</li></ol></li></ol>","xlit":"koítē"},"G5465":{"derivation":"from the base of G5490 (χάσμα);","strongs_def":" to lower (as into a void)","kjv_def":"let down, strike","translit":"chaláō","lemma":"χαλάω","pron":"khal-ah'-o","pos":"Verb","thayer":"<ol><li>to loosen, slacken, relax</li><li>to let down from a higher place to a lower</li></ol>","xlit":"chaláō"},"G5059":{"strongs_def":" a prodigy or omen","derivation":"of uncertain affinity;","lemma":"τέρας","translit":"téras","kjv_def":"wonder","pron":"ter'-as","pos":"Noun Neuter","thayer":"<ol><li>a prodigy, portent</li><li>miracle: performed by any one</li></ol>","xlit":"téras"},"G3536":{"strongs_def":" a Ninevite, i.e. inhabitant of Nineveh","derivation":"from G3535 (Νινευΐ);","translit":"Nineuḯtēs","lemma":"Νινευΐτης","kjv_def":"of Nineve, Ninevite","pron":"nin-yoo-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a Ninevite, an inhabitant of Nineveh</li></ol>","xlit":"Nineuḯtēs"},"G534":{"derivation":"from G575 (ἀπό) and G737 (ἄρτι);","strongs_def":" from now, i.e. henceforth (already)","kjv_def":"from henceforth","lemma":"ἀπάρτι","translit":"apárti","pron":"ap-ar'-tee","pos":"Adverb","thayer":"<ol><li>from now, henceforth</li></ol>","xlit":"apárti"},"G888":{"strongs_def":" useless, i.e. (euphemistically) unmeritorious","derivation":"from G1 (Α) (as a negative particle) and a derivative of G5534 (χρή) (compare G5532 (χρεία));","translit":"achreîos","lemma":"ἀχρεῖος","kjv_def":"unprofitable","pron":"akh-ri'-os","pos":"Adjective","thayer":"<ol><li>useless, good for nothing</li></ol>","xlit":"achreîos"},"G4733":{"derivation":"from G4732 (στερεόω);","strongs_def":" something established, i.e. (abstractly) confirmation (stability)","kjv_def":"stedfastness","translit":"steréōma","lemma":"στερέωμα","pron":"ster-eh'-o-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been made firm<ol type='a'><li>the firmament, the arch of the sky, which in early times was thought to be solid<ol><li>a fortified place</li></ol><li>that which furnishes a foundation<ol><li>on which a thing rests firmly, support</li></ol><li>firmness, steadfastness<ol><li>metaphorically in a military sense: solid front</li></ol></li></ol></li></ol>","xlit":"steréōma"},"G4235":{"derivation":"a form of G4239 (πραΰς), used in certain parts;","strongs_def":" gentle, i.e. humble","kjv_def":"meek","translit":"prâios","lemma":"πρᾷος","pron":"prah'-os","pos":"Adjective","thayer":"<ol><li>gentle, mild, meek</li></ol>","xlit":"prâios"},"G2705":{"lemma":"καταφιλέω","translit":"kataphiléō","kjv_def":"kiss","strongs_def":" to kiss earnestly","derivation":"from 2596 and 5368;","pron":"kat-af-ee-leh'-o","pos":"Verb","thayer":"<ol><li>to kiss much, kiss again and again, kiss tenderly</li></ol>","xlit":"kataphiléō"},"G2488":{"derivation":"of Hebrew origin (H03147);","strongs_def":" Joatham (i.e. Jotham), an Israelite","kjv_def":"Joatham","translit":"Iōátham","lemma":"Ἰωάθαμ","pron":"ee-o-ath'-am","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jotham = \"Jehovah is upright\"</p><ol><li>the son of King Uzziah or Azariah and Jerusha</li></ol>","xlit":"Iōátham"},"G1729":{"strongs_def":" deficient in","derivation":"from a compound of G1722 (ἐν) and G1210 (δέω) (in the sense of lacking);","translit":"endeḗs","lemma":"ἐνδεής","kjv_def":"lacking","pron":"en-deh-ace'","pos":"Adjective","thayer":"<ol><li>needy, destitute</li></ol>","xlit":"endeḗs"},"G51":{"lemma":"ἀγνόημα","translit":"agnóēma","kjv_def":"error","strongs_def":" a thing ignored, i.e. shortcoming","derivation":"from G50 (ἀγνοέω);","pron":"ag-no'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a sin committed through ignorance or thoughtlessness</li></ol>","xlit":"agnóēma"},"G5415":{"derivation":"of Latin origin;","strongs_def":" \"fortunate\"; Fortunatus, a Christian","kjv_def":"Fortunatus","lemma":"Φορτουνᾶτος","translit":"Phortounâtos","pron":"for-too-nat'-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Fortunatus = \"well freighted\"</p><ol><li>a Christian of Corinth</li></ol>","xlit":"Phortounâtos"},"G43":{"translit":"ankálē","lemma":"ἀγκάλη","kjv_def":"arm","strongs_def":" an arm (as curved)","derivation":"from (a bend, \"ache\");","pron":"ang-kal'-ay","pos":"Noun Feminine","thayer":"<ol><li>the curve or inner angle of the arm, the bent arm</li><li>anything closely enfolding, as the arms of the sea, etc.</li></ol>","xlit":"ankálē"},"G2119":{"strongs_def":" to have good time, i.e. opportunity or leisure","derivation":"from G2121 (εὔκαιρος);","lemma":"εὐκαιρέω","translit":"eukairéō","kjv_def":"have leisure (convenient time), spend time","pron":"yoo-kahee-reh'-o","pos":"Verb","thayer":"<ol><li>to have opportunity</li><li>to have leisure</li><li>to do something</li><li>to give one's time to a thing</li></ol>","xlit":"eukairéō"},"G1851":{"derivation":"from a compound of G1537 (ἐκ) and G2192 (ἔχω) (meaning to stand out);","strongs_def":" prominence (figuratively)","kjv_def":"principal","translit":"exochḗ","lemma":"ἐξοχή","pron":"ex-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>any prominence or projection, as a peak or summit of a mountain<ol type='a'><li>in medical writing a proturbance, swelling, wart, etc.</li></ol><li>metaphorically eminence, excellence, superiority</li></ol>","xlit":"exochḗ"},"G2286":{"derivation":"from G2288 (θάνατος);","strongs_def":" fatal, i.e. poisonous","kjv_def":"deadly","translit":"thanásimos","lemma":"θανάσιμος","pron":"than-as'-ee-mos","pos":"Adjective","thayer":"<ol><li>deadly</li></ol>","xlit":"thanásimos"},"G440":{"strongs_def":" a live coal","derivation":"of uncertain derivation;","translit":"ánthrax","lemma":"ἄνθραξ","kjv_def":"coal of fire","pron":"anth'-rax","pos":"Adjective","thayer":"<ol><li>a burning or live coal</li></ol>","xlit":"ánthrax"},"G2603":{"translit":"katabrabeúō","lemma":"καταβραβεύω","kjv_def":"beguile of reward","strongs_def":" to award the price against, i.e. (figuratively) to defraud (of salvation)","derivation":"from G2596 (κατά) and G1018 (βραβεύω) (in its original sense);","pron":"kat-ab-rab-yoo'-o","pos":"Verb","thayer":"<ol><li>to decide as umpire against someone</li><li>to defraud or beguile of the prize of victory</li><li>metaphorically to deprive of salvation</li></ol>","xlit":"katabrabeúō"},"G314":{"derivation":"from G303 (ἀνά) and G1097 (γινώσκω);","strongs_def":" to know again, i.e. (by extension) to read","kjv_def":"read","translit":"anaginṓskō","lemma":"ἀναγινώσκω","pron":"an-ag-in-oce'-ko","pos":"Verb","thayer":"<ol><li>to distinguish between, to recognise, to know accurately, to acknowledge</li><li>to read</li></ol>","xlit":"anaginṓskō"},"G1253":{"lemma":"διάκρισις","translit":"diákrisis","kjv_def":"discern(-ing), disputation","strongs_def":" judicial estimation","derivation":"from G1252 (διακρίνω);","pron":"dee-ak'-ree-sis","pos":"Noun Feminine","thayer":"<ol><li>a distinguishing, discerning, judging</li></ol>","xlit":"diákrisis"},"G3704":{"kjv_def":"because, how, (so) that, to, when","lemma":"ὅπως","translit":"hópōs","derivation":"from G3739 (ὅς) and G4459 (πῶς);","strongs_def":" what(-ever) how, i.e. in the manner that (as adverb or conjunction of coincidence, intentional or actual)","pron":"hop'-oce","thayer":"<ol><li>how, that</li></ol>","xlit":"hópōs"},"G94":{"strongs_def":" unjust; by extension wicked; by implication, treacherous; specially, heathen","derivation":"from G1 (Α) (as a negative particle) and G1349 (δίκη);","lemma":"ἄδικος","translit":"ádikos","kjv_def":"unjust, unrighteous","pron":"ad'-ee-kos","pos":"Adjective","thayer":"<ol><li>descriptive of one who violates or has violated justice<ol type='a'><li>unjust</li><li>unrighteous, sinful</li><li>of one who deals fraudulently with others, deceitful</li></ol></li></ol>","xlit":"ádikos"},"G2219":{"translit":"zýmē","lemma":"ζύμη","kjv_def":"leaven","strongs_def":" ferment (as if boiling up)","derivation":"probably from G2204 (ζέω);","pron":"dzoo'-may","pos":"Noun Feminine","thayer":"<ol><li>leaven</li><li>metaphorically of inveterate mental and moral corruption, viewed in its tendency to infect others</li></ol>","xlit":"zýmē"},"G4996":{"translit":"sōphrónōs","lemma":"σωφρόνως","kjv_def":"soberly","strongs_def":" with sound mind, i.e. moderately","derivation":"adverb from G4998 (σώφρων);","pron":"so-fron'-oce","pos":"Adverb","thayer":"<ol><li>with sound mind, soberly, temperately, discreetly</li></ol>","xlit":"sōphrónōs"},"G5169":{"derivation":"from a derivative of the base of G5168 (τρυμαλιά);","strongs_def":" an aperture, i.e. a needle's eye","kjv_def":"eye","lemma":"τρύπημα","translit":"trýpēma","pron":"troo'-pay-mah","pos":"Noun Neuter","thayer":"<ol><li>a hole, (eye of the needle)</li></ol>","xlit":"trýpēma"},"G2489":{"derivation":"feminine of the same as G2491 (Ἰωάννης);","strongs_def":" Joanna, a Christian","kjv_def":"Joanna","translit":"Iōánna","lemma":"Ἰωάννα","pron":"ee-o-an'-nah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Joanna = \"Jehovah is a gracious giver\"</p><ol><li>the wife of Chuza, Herod's steward, and a follower of Jesus</li></ol>","xlit":"Iōánna"},"G4056":{"kjv_def":"more abundant(-ly), X the more earnest, (more) exceedingly, more frequent, much more, the rather","lemma":"περισσοτέρως","translit":"perissotérōs","derivation":"adverb from G4055 (περισσότερος);","strongs_def":" more superabundantly","pron":"per-is-sot-er'-oce","pos":"Adverb","thayer":"<ol><li>more abundantly</li><li>more in a greater degree</li><li>more earnestly, more exceedingly</li><li>especially, above others</li></ol>","xlit":"perissotérōs"},"G956":{"translit":"bélos","lemma":"βέλος","kjv_def":"dart","strongs_def":" a missile, i.e. spear or arrow","derivation":"from G906 (βάλλω);","pron":"bel'-os","pos":"Noun Neuter","thayer":"<ol><li>a missile, dart, javelin, arrow</li></ol>","xlit":"bélos"},"G4486":{"translit":"rhḗgnymi","lemma":"ῥήγνυμι","kjv_def":"break (forth), burst, rend, tear","strongs_def":" G2608 (κατάγνυμι) being its intensive (with the preposition in composition), and G2352 (θραύω) a shattering to minute fragments; but not a reduction to the constituent particles, like G3089 (λύω)) or disrupt, lacerate; by implication, to convulse (with spasms); figuratively, to give vent to joyful emotions","derivation":"both prolonged forms of (which appears only in certain forms, and is itself probably a strengthened form of (see in G2608 (κατάγνυμι))) to \"break,\" \"wreck\" or \"crack\", i.e. (especially) to sunder (by separation of the parts;","pron":"hrayg'-noo-mee","pos":"Verb","thayer":"<ol><li>to rend, burst or break asunder, break up, break through<ol type='a'><li>to tear in pieces</li><li>to break forth<ol><li>into joy, of infants or dumb persons beginning to speak</li></ol><li>to distort, convulse<ol><li>of a demon causing convulsions in a man possessed</li><li>to dash down, hurl to the ground (a common occurrence in cases of demon possession and epilepsy)</li></ol></li></ol></li></ol>","xlit":"rhḗgnymi"},"G2963":{"derivation":"from G2962 (κύριος);","strongs_def":" mastery, i.e. (concretely and collectively) rulers","kjv_def":"dominion, government","lemma":"κυριότης","translit":"kyriótēs","pron":"koo-ree-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>dominion, power, lordship</li><li>in the NT: one who possesses dominion</li></ol>","xlit":"kyriótēs"},"G5481":{"kjv_def":"express image","lemma":"χαρακτήρ","translit":"charaktḗr","derivation":"from the same as G5482 (χάραξ);","strongs_def":" a graver (the tool or the person), i.e. (by implication) engraving ((\"character\"), the figure stamped, i.e. an exact copy or (figuratively) representation)","pron":"khar-ak-tare'","pos":"Noun Masculine","thayer":"<ol><li>the instrument used for engraving or carving</li><li>the mark stamped upon that instrument or wrought out on it<ol type='a'><li>a mark or figure burned in (<a class='bible' href='#b3.13.28'>Lev 13:28</a>) or stamped on, an impression</li><li>the exact expression (the image) of any person or thing, marked likeness, precise reproduction in every respect, i.e facsimile</li></ol></li></ol>","xlit":"charaktḗr"},"G4111":{"derivation":"a primary verb;","strongs_def":" to mould, i.e. shape or fabricate","kjv_def":"form","lemma":"πλάσσω","translit":"plássō","pron":"plas'-so","pos":"Verb","thayer":"<ol><li>to form, mould (something from clay, wax, etc.)<ol type='a'><li>used of a potter</li></ol></li></ol>","xlit":"plássō"},"G5377":{"translit":"philótheos","lemma":"φιλόθεος","kjv_def":"lover of God","strongs_def":" fond of God, i.e. pious","derivation":"from G5384 (φίλος) and G2316 (θεός);","pron":"fil-oth'-eh-os","pos":"Adjective","thayer":"<ol><li>loving God</li></ol>","xlit":"philótheos"},"G1684":{"derivation":"from G1722 (ἐν) and the base of G939 (βάσις);","strongs_def":" to walk on, i.e. embark (aboard a vessel), reach (a pool)","kjv_def":"come (get) into, enter (into), go (up) into, step in, take ship","lemma":"ἐμβαίνω","translit":"embaínō","pron":"em-ba'-hee-no","pos":"Verb","thayer":"<ol><li>to go into, step into</li></ol>","xlit":"embaínō"},"G2317":{"kjv_def":"godliness","lemma":"θεοσέβεια","translit":"theosébeia","derivation":"from G2318 (θεοσεβής);","strongs_def":" devoutness, i.e. piety","pron":"theh-os-eb'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>reverence towards God's goodness</li></ol>","xlit":"theosébeia"},"G1312":{"kjv_def":"corruption","translit":"diaphthorá","lemma":"διαφθορά","derivation":"from G1311 (διαφθείρω);","strongs_def":" decay","pron":"dee-af-thor-ah'","pos":"Noun Feminine","thayer":"<ol><li>corruption, destruction</li><li>in the NT that destruction which is effected by the decay of the body after death</li></ol>","xlit":"diaphthorá"},"G3826":{"kjv_def":"all at once","lemma":"παμπληθεί","translit":"pamplētheí","derivation":"dative case (adverb) of a compound of G3956 (πᾶς) and G4128 (πλῆθος);","strongs_def":" in full multitude, i.e. concertedly or simultaneously","pron":"pam-play-thi'","pos":"Adverb","thayer":"<ol><li>with the whole multitude</li><li>all together, one and all</li></ol>","xlit":"pamplētheí"},"G1513":{"translit":"eí pōs","lemma":"εἴ πως","kjv_def":"if by any means","strongs_def":" if somehow","derivation":"from G1487 (εἰ) and G4458 (-πώς);","pron":"i poce","pos":"Conjunction","thayer":"<ol><li>if indeed, since, if after all</li></ol>","xlit":"eí pōs"},"G2780":{"translit":"kēpourós","lemma":"κηπουρός","kjv_def":"gardener","strongs_def":" a garden-keeper, i.e. gardener","derivation":"from G2779 (κῆπος) and (a warden);","pron":"kay-poo-ros'","pos":"Noun Masculine","thayer":"<ol><li>a keeper of a garden, a gardener</li></ol>","xlit":"kēpourós"},"G760":{"translit":"Asá","lemma":"Ἀσά","kjv_def":"Asa","strongs_def":" Asa, an Israelite","derivation":"of Hebrew origin (H0609);","pron":"as-ah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Asa = \"physician, or cure\"</p><ol><li>son of Abijah and king of Judah</li></ol>","xlit":"Asá"},"G4405":{"kjv_def":"early, morning","translit":"prōḯa","lemma":"πρωΐα","derivation":"feminine of a derivative of G4404 (πρωΐ) as noun;","strongs_def":" day-dawn","pron":"pro-ee'-ah","pos":"Adjective","thayer":"<ol><li>early, pertaining to the morning, at day break</li></ol>","xlit":"prōḯa"},"G732":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G4517 (ῥώννυμι);","strongs_def":" infirm","kjv_def":"sick (folk, -ly)","translit":"árrhōstos","lemma":"ἄῤῥωστος","pron":"ar'-hroce-tos","pos":"Verb","thayer":"<ol><li>without strength, weak, sick</li></ol>","xlit":"árrhōstos"},"G2527":{"derivation":"from G2596 (κατά) and G3650 (ὅλος);","strongs_def":" on the whole, i.e. entirely","kjv_def":"at all","translit":"kathólou","lemma":"καθόλου","pron":"kath-ol'-oo","pos":"Adverb","thayer":"<ol><li>wholly, entirely, at all</li></ol>","xlit":"kathólou"},"G1002":{"strongs_def":" a missile, i.e. javelin","derivation":"from G906 (βάλλω);","lemma":"βολίς","translit":"bolís","kjv_def":"dart","pron":"bol-ece'","pos":"Noun Feminine","thayer":"<ol><li>a missile, dart, javelin</li></ol>","xlit":"bolís"},"G5031":{"derivation":"from G5034 (τάχος);","strongs_def":" curt, i.e. impending","kjv_def":"shortly, swift","lemma":"ταχινός","translit":"tachinós","pron":"takh-ee-nos'","pos":"Adjective","thayer":"<ol><li>swift, quick</li></ol>","xlit":"tachinós"},"G902":{"derivation":"a diminutive of a derivative probably of the base of G939 (βάσις);","strongs_def":" a palm twig (as going out far)","kjv_def":"branch","translit":"baḯon","lemma":"βαΐον","pron":"bah-ee'-on","pos":"Noun Neuter","thayer":"<ol><li>a palm branch</li></ol>","xlit":"baḯon"},"G2545":{"translit":"kaíō","lemma":"καίω","kjv_def":"burn, light","strongs_def":" to set on fire, i.e. kindle or (by implication) consume","derivation":"apparently a primary verb;","pron":"kah'-yo","pos":"Verb","thayer":"<ol><li>to set on fire, light, burning</li><li>to burn, consume with fire</li></ol>","xlit":"kaíō"},"G3317":{"derivation":"neuter of compound of G3319 (μέσος) and G3571 (νύξ);","strongs_def":" midnight (especially as a watch)","kjv_def":"midnight","translit":"mesonýktion","lemma":"μεσονύκτιον","pron":"mes-on-ook'-tee-on","pos":"Noun Neuter","thayer":"<ol><li>midnight</li></ol>","xlit":"mesonýktion"},"G4922":{"kjv_def":"journey with","translit":"synodeúō","lemma":"συνοδεύω","derivation":"from G4862 (σύν) and G3593 (ὁδεύω);","strongs_def":" to travel in company with","pron":"soon-od-yoo'-o","pos":"Verb","thayer":"<ol><li>to journey with, travel in company with</li></ol>","xlit":"synodeúō"},"G1129":{"derivation":"from G1128 (γυμνάζω);","strongs_def":" training, i.e. (figuratively) asceticism","kjv_def":"exercise","translit":"gymnasía","lemma":"γυμνασία","pron":"goom-nas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the exercise of the body in a palaestra or school of athletics</li><li>any exercise whatever<ol type='a'><li>the exercise of conscientiousness relative to the body such as is characteristic of ascetics and consists in abstinence from matrimony and certain kinds of food</li></ol></li></ol>","xlit":"gymnasía"},"G3731":{"kjv_def":"violence","translit":"hórmēma","lemma":"ὅρμημα","derivation":"from G3730 (ὁρμή);","strongs_def":" an attack, i.e. (abstractly) precipitancy","pron":"hor'-may-mah","pos":"Noun Neuter","thayer":"<ol><li>a rush, impulse</li><li>that which is impelled or hurried away by impulse</li></ol>","xlit":"hórmēma"},"G2454":{"derivation":"from G2450 (Ἰουδαΐζω);","strongs_def":" \"Judaism\", i.e. the Jewish faith and usages","kjv_def":"Jews' religion","lemma":"Ἰουδαϊσμός","translit":"Ioudaïsmós","pron":"ee-oo-dah-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>the Jewish faith and worship, religion of the Jews, Judaism</li></ol>","xlit":"Ioudaïsmós"},"G1958":{"strongs_def":" carefulness, i.e. kind attention (hospitality)","derivation":"from G1959 (ἐπιμελέομαι);","translit":"epiméleia","lemma":"ἐπιμέλεια","kjv_def":"+ refresh self","pron":"ep-ee-mel'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>care, attention</li></ol>","xlit":"epiméleia"},"G40":{"derivation":"from (an awful thing) (compare G53 (ἁγνός), G2282 (θάλπω));","strongs_def":" sacred (physically, pure, morally blameless or religious, ceremonially, consecrated)","kjv_def":"(most) holy (one, thing), saint","lemma":"ἅγιος","translit":"hágios","pron":"hag'-ee-os","pos":"Adjective","thayer":"<ol><li>most holy thing, a saint</li></ol>","xlit":"hágios"},"G3319":{"lemma":"μέσος","translit":"mésos","kjv_def":"among, X before them, between, + forth, mid(-day, -night), midst, way","strongs_def":" middle (as an adjective or (neuter) noun)","derivation":"from G3326 (μετά);","pron":"mes'-os","pos":"Adjective","thayer":"<ol><li>middle</li><li>the midst</li><li>in the midst of, amongst</li></ol>","xlit":"mésos"},"G2307":{"kjv_def":" desire, pleasure, will","lemma":"θέλημα","translit":"thélēma","derivation":"from the prolonged form of G2309 (θέλω);","strongs_def":" a determination (properly, the thing), i.e. (actively) choice (specially, purpose, decree; abstractly, volition) or (passively) inclination","pron":"thel'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>what one wishes or has determined shall be done<ol type='a'><li>of the purpose of God to bless mankind through Christ</li><li>of what God wishes to be done by us<ol><li>commands, precepts</li></ol></li></ol><li>will, choice, inclination, desire, pleasure</li></ol>","xlit":"thélēma"},"G3906":{"strongs_def":" to inspect alongside, i.e. note insidiously or scrupulously","derivation":"from G3844 (παρά) and G5083 (τηρέω);","lemma":"παρατηρέω","translit":"paratēréō","kjv_def":"observe, watch","pron":"par-at-ay-reh'-o","pos":"Verb","thayer":"<ol><li>to stand beside and watch, to watch assiduously, observe carefully<ol type='a'><li>to watch, attend to with the eyes</li><li>of auguries, to see what he is going to do</li><li>in a bad sense, to watch insidiously</li><li>to watch one's self</li><li>to observe, keep scrupulously<ol><li>to neglect nothing requisite to the religious observance of</li></ol></li></ol></li></ol>","xlit":"paratēréō"},"G1455":{"lemma":"ἐγκάθετος","translit":"enkáthetos","kjv_def":"spy","strongs_def":" subinduced, i.e. surreptitiously suborned as a lier-in-wait","derivation":"from G1722 (ἐν) and a derivative of G2524 (καθίημι);","pron":"eng-kath'-et-os","pos":"Adjective","thayer":"<ol><li>secretly to lie in wait, a spy</li><li>one who is bribed by others to entrap a man by crafty words</li></ol>","xlit":"enkáthetos"},"G3742":{"strongs_def":" piety","derivation":"from G3741 (ὅσιος);","translit":"hosiótēs","lemma":"ὁσιότης","kjv_def":"holiness","pron":"hos-ee-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>piety towards God, fidelity in observing the obligations of piety, holiness</li></ol>","xlit":"hosiótēs"},"G410":{"kjv_def":"blameless","translit":"anénklētos","lemma":"ἀνέγκλητος","derivation":"from G1 (Α) (as a negative particle) and a derivative of G1458 (ἐγκαλέω);","strongs_def":" unaccused, i.e. (by implication) irreproachable","pron":"an-eng'-klay-tos","pos":"Adjective","thayer":"<ol><li>that cannot be called into to account, unreproveable, unaccused, blameless</li></ol>","xlit":"anénklētos"},"G767":{"kjv_def":"mean","lemma":"ἄσημος","translit":"ásēmos","derivation":"from G1 (Α) (as a negative particle) and the base of G4591 (σημαίνω);","strongs_def":" unmarked, i.e. (figuratively) ignoble","pron":"as'-ay-mos","pos":"Adjective","thayer":"<ol><li>unmarked or unstamped<ol type='a'><li>of money</li></ol><li>unknown, of no mark, insignificant, ignoble</li></ol>","xlit":"ásēmos"},"G810":{"strongs_def":" properly, unsavedness, i.e. (by implication) profligacy","derivation":"from a compound of G1 (Α) (as a negative particle) and a presumed derivative of G4982 (σώζω);","lemma":"ἀσωτία","translit":"asōtía","kjv_def":"excess, riot","pron":"as-o-tee'-ah","xlit":"asōtía"},"G5332":{"kjv_def":"sorcerer","lemma":"φαρμακεύς","translit":"pharmakeús","derivation":"from (a drug, i.e. spell-giving potion);","strongs_def":" a druggist (\"pharmacist\") or poisoner, i.e. (by extension) a magician","pron":"far-mak-yoos'","pos":"Noun Masculine","thayer":"<ol><li>one who prepares or uses magical remedies</li><li>sorcerer</li></ol>","xlit":"pharmakeús"},"G3073":{"derivation":"probably remotely from G3074 (λύκος);","strongs_def":" Lycia, a province of Asia Minor","kjv_def":"Lycia","translit":"Lykía","lemma":"Λυκία","pron":"loo-kee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Lycia = \"wolfish\"</p><ol><li>a mountainous region in Asia Minor, bounded by Pamphylia, Phrygia, Caria, and the Mediterranean Sea</li></ol>","xlit":"Lykía"},"G2166":{"lemma":"Εὐφράτης","translit":"Euphrátēs","kjv_def":"Euphrates","strongs_def":" Euphrates, a river of Asia","derivation":"of foreign origin (compare H06578);","pron":"yoo-frat'-ace","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Euphrates = \"the good and abounding river\"</p><ol><li>a large, famous river which rises in the mountains of Armenia Major, flows through Assyria, Syria, Mesopotamia and the city of Babylon, and empties into the Gulf of Persia</li></ol>","xlit":"Euphrátēs"},"G813":{"kjv_def":"unruly","lemma":"ἄτακτος","translit":"átaktos","derivation":"from G1 (Α) (as a negative particle) and a derivative of G5021 (τάσσω);","strongs_def":" unarranged, i.e. (by implication) insubordinate (religiously)","pron":"at'-ak-tos","pos":"Adjective","thayer":"<ol><li>disorderly, out of ranks (often so of soldiers)</li><li>irregular, inordinate, immoderate pleasures</li><li>deviating from the prescribed order or rule</li></ol>","xlit":"átaktos"},"G406":{"kjv_def":"Andrew","lemma":"Ἀνδρέας","translit":"Andréas","derivation":"from G435 (ἀνήρ);","strongs_def":" manly; Andreas, an Israelite","pron":"an-dreh'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Andrew = \"manly\"</p><ol><li>A native of Bethsaida in Galilee, brother of Simon Peter, a disciple of John the Baptist, and afterwards an apostle of Christ. He is said to have been crucified at Patrae in Archaia.</li></ol>","xlit":"Andréas"},"G1810":{"derivation":"from G1537 (ἐκ) and the base of G160 (αἰφνίδιος);","strongs_def":" of a sudden (unexpectedly)","kjv_def":"suddenly","lemma":"ἐξαίφνης","translit":"exaíphnēs","pron":"ex-ah'-eef-nace","pos":"Adverb","thayer":"<ol><li>of a sudden, suddenly, unexpectedly</li></ol>","xlit":"exaíphnēs"},"G24":{"derivation":"from G23 (ἀγανακτέω);","strongs_def":" indignation","kjv_def":"indignation","translit":"aganáktēsis","lemma":"ἀγανάκτησις","pron":"ag-an-ak'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>indignation, irritation, vexation</li></ol>","xlit":"aganáktēsis"},"G3367":{"derivation":"from G3361 (μή) and G1520 (εἷς);","strongs_def":" not even one (man, woman, thing)","kjv_def":"any (man, thing), no (man), none, not (at all, any man, a whit), nothing, + without delay","lemma":"μηδείς","translit":"mēdeís","pron":"may-dice'","pos":"Adjective","thayer":"<ol><li>nobody, no one, nothing</li></ol>","xlit":"mēdeís"},"G4233":{"strongs_def":" a practiser, i.e. (specially), an official collector","derivation":"from a derivative of G4238 (πράσσω);","lemma":"πράκτωρ","translit":"práktōr","kjv_def":"officer","pron":"prak'-tor","pos":"Noun Masculine","thayer":"<ol><li>one who does anything, a doer</li><li>one who does the work of inflicting punishment or taking vengeance<ol type='a'><li>the avenger of murder</li><li>the exactor of a monetary fine</li><li>an officer of justice of the lower order whose business it is to inflict punishment</li></ol></li></ol>","xlit":"práktōr"},"G1821":{"derivation":"from G1537 (ἐκ) and G649 (ἀποστέλλω);","strongs_def":" to send away forth, i.e. (on a mission) to despatch, or (peremptorily) to dismiss","kjv_def":"send (away, forth, out)","lemma":"ἐξαποστέλλω","translit":"exapostéllō","pron":"ex-ap-os-tel'-lo","pos":"Verb","thayer":"<ol><li>to send forth</li><li>to send away</li></ol>","xlit":"exapostéllō"},"G2927":{"strongs_def":" concealed, i.e. private","derivation":"from G2928 (κρύπτω);","translit":"kryptós","lemma":"κρυπτός","kjv_def":"hid(-den), inward(-ly), secret","pron":"kroop-tos'","pos":"Adjective","thayer":"<ol><li>hidden, concealed, secret</li></ol>","xlit":"kryptós"},"G423":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G1949 (ἐπιλαμβάνομαι);","strongs_def":" not arrested, i.e. (by implication) inculpable","kjv_def":"blameless, unrebukeable","translit":"anepílēptos","lemma":"ἀνεπίληπτος","pron":"an-ep-eel'-ape-tos","pos":"Adjective","thayer":"<ol><li>not apprehended, that cannot be laid hold of</li><li>that cannot be reprehended, not open to censure, irreproachable</li></ol>","xlit":"anepílēptos"},"G5139":{"translit":"Trachōnîtis","lemma":"Τραχωνῖτις","kjv_def":"Trachonitis","strongs_def":" rough district; Trachonitis, a region of Syria","derivation":"from a derivative of G5138 (τραχύς);","pron":"trakh-o-nee'-tis","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Trachonitis = \"a rugged region\"</p><ol><li>a rough region, inhabited by robbers, situated between Antilibanus on the west and on the east by the mountains of Batanaea and on the north by the territory of Damascus</li></ol>","xlit":"Trachōnîtis"},"G5363":{"strongs_def":" fondness of mankind, i.e. benevolence (\"philanthropy\")","derivation":"from the same as G5364 (φιλανθρώπως);","lemma":"φιλανθρωπία","translit":"philanthrōpía","kjv_def":"kindness, love towards man","pron":"fil-an-thro-pee'-ah","pos":"Noun Feminine","thayer":"<ol><li>love of mankind, benevolence</li></ol>","xlit":"philanthrōpía"},"G5313":{"kjv_def":" height, high thing","translit":"hýpsōma","lemma":"ὕψωμα","derivation":"from G5312 (ὑψόω);","strongs_def":" an elevated place or thing, i.e. (abstractly) altitude, or (by implication) a barrier (figuratively)","pron":"hoop'-so-mah","pos":"Noun Neuter","thayer":"<ol><li>thing elevated, height<ol type='a'><li>of space</li><li>elevated structure, i.e. barrier, rampart, bulwark</li></ol></li></ol>","xlit":"hýpsōma"},"G3497":{"lemma":"Νεεμάν","translit":"Neemán","kjv_def":"Naaman","strongs_def":" Neeman (i.e. Naaman), a Syrian","derivation":"of Hebrew origin (H05283);","pron":"neh-eh-man'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Naaman the Syrian = \"pleasantness\"</p><ol><li>commander-in-chief of the army of Syria</li></ol>","xlit":"Neemán"},"G3053":{"derivation":"from G3049 (λογίζομαι);","strongs_def":" computation, i.e. (figuratively) reasoning (conscience, conceit)","kjv_def":"imagination, thought","lemma":"λογισμός","translit":"logismós","pron":"log-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a reckoning, computation</li><li>a reasoning: such as is hostile to the Christian faith</li><li>a judgment, decision: such as conscience passes</li></ol>","xlit":"logismós"},"G3910":{"derivation":"from G3844 (παρά) and a derivative of G846 (αὐτός);","strongs_def":" at the very instant, i.e. momentary","kjv_def":"but for a moment","translit":"parautíka","lemma":"παραυτίκα","pron":"par-ow-tee'-kah","pos":"Adverb","thayer":"<ol><li>for the moment</li></ol>","xlit":"parautíka"},"G802":{"strongs_def":" properly, not agreed, i.e. treacherous to compacts","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4934 (συντίθεμαι);","translit":"asýnthetos","lemma":"ἀσύνθετος","kjv_def":" covenant-breaker","pron":"as-oon'-thet-os","pos":"Adjective","thayer":"<ol><li>uncompounded, simple</li><li>covenant breaking, faithless</li></ol>","xlit":"asýnthetos"},"G2444":{"lemma":"ἱνατί","translit":"hinatí","kjv_def":"wherefore, why","strongs_def":" for what reason ?, i.e. why?","derivation":"from G2443 (ἵνα) and G5101 (τίς);","pron":"hin-at-ee'","pos":"Conjunction","thayer":"<ol><li>for what purpose, wherefore, why</li></ol>","xlit":"hinatí"},"G2542":{"derivation":"from G2541 (Καῖσαρ);","strongs_def":" Cæsaria, the name of two places in Palestine","kjv_def":"Cæsarea","translit":"Kaisáreia","lemma":"Καισάρεια","pron":"kahee-sar'-i-a","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Caesarea = \"severed\"</p><ol><li>Caesarea of Philippi was situated at the foot of Lebanon near the sources of the Jordan in Gaulanitis, and formerly called Paneas; but afterward being rebuilt by Philip the tetrarch, it was called by him Caesarea, in honour of Tiberias Caesar; subsequently called Neronias by Agrippa II, in honour of Nero.</li><li>Caesarea of Palestine was built near the Mediterranean by Herod the Great on the site of Strabo's Tower, between Joppa and Dora. It was provided with a magnificent harbour and had conferred upon it the name of Caesarea, in honour of Augustus. It was the residence of Roman procurators, and the majority of its inhabitants were Greeks.</li></ol>","xlit":"Kaisáreia"},"G5493":{"strongs_def":" a storm-runlet, i.e. winter-torrent","derivation":"from the base of G5494 (χειμών) and G4482 (ῥέω);","translit":"cheímarrhos","lemma":"χείμαῤῥος","kjv_def":"brook","pron":"khi'-mar-hros","pos":"Adjective","thayer":"<ol><li>flowing in winter, a torrent</li></ol>","xlit":"cheímarrhos"},"G2230":{"lemma":"ἡγεμονεύω","translit":"hēgemoneúō","kjv_def":"be governor","strongs_def":" to act as ruler","derivation":"from G2232 (ἡγεμών);","pron":"hayg-em-on-yoo'-o","pos":"Verb","thayer":"<ol><li>to be leader, to lead the way</li><li>to rule, command<ol type='a'><li>of a province, to be governor of a province</li><li>said of a proconsul, of a procurator</li></ol></li></ol>","xlit":"hēgemoneúō"},"G1977":{"derivation":"from G1909 (ἐπί) and G4496 (ῥίπτω);","strongs_def":" to throw upon (literally or figuratively)","kjv_def":"cast upon","translit":"epirrhíptō","lemma":"ἐπιῤῥίπτω","pron":"ep-ir-hrip'-to","pos":"Verb","thayer":"<ol><li>to throw upon, place upon</li></ol>","xlit":"epirrhíptō"},"G4627":{"strongs_def":"a \"skiff\" (as if dug out), or yawl (carried aboard a large vessel for landing)","kjv_def":"boat","translit":"skáphē","lemma":"σκάφη","pron":"skaf'-ay","pos":"Noun Feminine","thayer":"<ol><li>anything dug out, hollow vessel, trough, tray, tub</li><li>of a boat</li></ol>","xlit":"skáphē"},"G877":{"lemma":"ἀφροσύνη","translit":"aphrosýnē","kjv_def":"folly, foolishly(-ness)","strongs_def":" senselessness, i.e. (euphemistically) egotism; (morally) recklessness","derivation":"from G878 (ἄφρων);","pron":"af-ros-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>foolishness, folly, senselessness</li><li>thoughtlessness, recklessness</li></ol>","xlit":"aphrosýnē"},"G1581":{"lemma":"ἐκκόπτω","translit":"ekkóptō","kjv_def":"cut down (off, out), hew down, hinder","strongs_def":" to exscind; figuratively, to frustrate","derivation":"from G1537 (ἐκ) and G2875 (κόπτω);","pron":"ek-kop'-to","pos":"Verb","thayer":"<ol><li>to cut out, cut off<ol type='a'><li>of a tree</li></ol><li>metaphorically to cut off occasion</li></ol>","xlit":"ekkóptō"},"G334":{"strongs_def":" a votive offering","derivation":"from G394 (ἀνατίθεμαι) (like G331 (ἀνάθεμα), but in a good sense);","lemma":"ἀνάθημα","translit":"anáthēma","kjv_def":"gift","pron":"an-ath'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>a gift consecrated and laid up in a temple</li><li>an offering resulting from a vow</li></ol>","xlit":"anáthēma"},"G779":{"translit":"askós","lemma":"ἀσκός","kjv_def":"bottle","strongs_def":" a leathern (or skin) bag used as a bottle","derivation":"from the same as G778 (ἀσκέω);","pron":"as-kos'","pos":"Noun Masculine","thayer":"<ol><li>a leathern bag or bottle, in which water or wine was kept</li></ol>","xlit":"askós"},"G4334":{"strongs_def":" to approach, i.e. (literally) come near, visit, or (figuratively) worship, assent to","derivation":"from G4314 (πρός) and G2064 (ἔρχομαι) (including its alternate);","lemma":"προσέρχομαι","translit":"prosérchomai","kjv_def":"(as soon as he) come (unto), come thereunto, consent, draw near, go (near, to, unto)","pron":"pros-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come to, approach</li><li>draw near to</li><li>to assent to</li></ol>","xlit":"prosérchomai"},"G2302":{"kjv_def":"spectacle, theatre","lemma":"θέατρον","translit":"théatron","derivation":"from G2300 (θεάομαι);","strongs_def":" a place for public show (\"theatre\"), i.e. general audience-room; by implication, a show itself (figuratively)","pron":"theh'-at-ron","pos":"Noun Neuter","thayer":"<ol><li>a theatre, a place in which games and dramatic spectacles are exhibited, and public assemblies held (for the Greeks used the theatre also as a forum)</li><li>a public show<ol type='a'><li>metaphorically, a man who is exhibited to be gazed at and made sport of</li></ol></li></ol>","xlit":"théatron"},"G4023":{"strongs_def":" to hold all around, i.e. include, clasp (figuratively)","derivation":"from G4012 (περί) and G2192 (ἔχω);","lemma":"περιέχω","translit":"periéchō","kjv_def":"+ astonished, contain, after (this manner)","pron":"per-ee-ekh'-o","pos":"Verb","thayer":"<ol><li>to surround, encompass<ol type='a'><li>to contain: of the subject-matter, contents, of a writing</li><li>to take possession of, to seize</li></ol></li></ol>","xlit":"periéchō"},"G1926":{"kjv_def":"receive","translit":"epidéchomai","lemma":"ἐπιδέχομαι","derivation":"from G1909 (ἐπί) and G1209 (δέχομαι);","strongs_def":" to admit (as a guest or (figuratively) teacher)","pron":"ep-ee-dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive hospitality</li><li>to admit, i.e. not to reject</li></ol>","xlit":"epidéchomai"},"G1824":{"translit":"exautēs","lemma":"ἐξαυτῆς","kjv_def":"by and by, immediately, presently, straightway","strongs_def":" from that hour, i.e. instantly","derivation":"from G1537 (ἐκ) and the genitive case singular feminine of G846 (αὐτός) (G5610 (ὥρα) being understood);","pron":"ex-ow'-tace","pos":"Adverb","thayer":"<ol><li>on the instant, forthwith</li></ol>","xlit":"exautēs"},"G1505":{"derivation":"from G1506 (εἰλικρινής);","strongs_def":" clearness, i.e. (by implication) purity (figuratively)","kjv_def":"sincerity","translit":"eilikríneia","lemma":"εἰλικρίνεια","pron":"i-lik-ree'-ni-ah","pos":"Noun Feminine","thayer":"<ol><li>purity, sincerity, ingenuousness</li></ol>","xlit":"eilikríneia"},"G4309":{"kjv_def":"determine before, ordain, predestinate","lemma":"προορίζω","translit":"proorízō","derivation":"from G4253 (πρό) and G3724 (ὁρίζω);","strongs_def":" to limit in advance, i.e. (figuratively) predetermine","pron":"pro-or-id'-zo","pos":"Verb","thayer":"<ol><li>to predetermine, decide beforehand</li><li>in the NT of God decreeing from eternity</li><li>to foreordain, appoint beforehand</li></ol>","xlit":"proorízō"},"G1498":{"strongs_def":" might (could, would, or should) be","derivation":"optative (i.e. English subjunctive) present of G1510 (εἰμί) (including the other person);","translit":"eíēn","lemma":"εἴην","kjv_def":"mean, + perish, should be, was, were","pron":"i'-ane","pos":"Verb","thayer":"<ol><li>to be, to exist, to happen, to be present</li></ol>","xlit":"eíēn"},"G3681":{"derivation":"probably akin to the base of G3686 (ὄνομα);","strongs_def":" notoriety, i.e. a taunt (disgrace)","kjv_def":"reproach","translit":"óneidos","lemma":"ὄνειδος","pron":"on'-i-dos","pos":"Noun Neuter","thayer":"<ol><li>reproach</li><li>shame</li></ol>","xlit":"óneidos"},"G1623":{"strongs_def":" sixth","derivation":"ordinal from G1803 (ἕξ);","lemma":"ἕκτος","translit":"héktos","kjv_def":"sixth","pron":"hek'-tos","pos":"Adjective","thayer":"<ol><li>the sixth</li></ol>","xlit":"héktos"},"G4615":{"kjv_def":"mustard","translit":"sínapi","lemma":"σίναπι","derivation":"perhaps from (to hurt, i.e. sting);","strongs_def":" mustard (the plant)","pron":"sin'-ap-ee","pos":"Noun Neuter","thayer":"<ol><li>mustard, the name of a plant which in oriental countries grows from a very small seed and attains to the height of a tree, 10 feet (3 m) and more; hence a very small quantity of a thing is likened to a mustard seed, and also a thing which grows to a remarkable size</li></ol>","xlit":"sínapi"},"G1119":{"derivation":"of uncertain affinity;","strongs_def":" the \"knee\"","kjv_def":"knee(X -l)","translit":"góny","lemma":"γόνυ","pron":"gon-oo'","pos":"Noun Neuter","thayer":"<ol><li>the knee, to kneel down</li></ol>","xlit":"góny"},"G2341":{"kjv_def":"fight with wild beasts","lemma":"θηριομαχέω","translit":"thēriomachéō","derivation":"from a compound of G2342 (θηρίον) and G3164 (μάχομαι);","strongs_def":" to be a beast-fighter (in the gladiatorial show), i.e. (figuratively) to encounter (furious men)","pron":"thay-ree-om-akh-eh'-o","pos":"Verb","thayer":"<ol><li>to fight with wild beasts</li></ol>","xlit":"thēriomachéō"},"G4216":{"kjv_def":"carried away of the flood","lemma":"ποταμοφόρητος","translit":"potamophórētos","derivation":"from G4215 (ποταμός) and a derivative of G5409 (φορέω);","strongs_def":" river-borne, i.e. overwhelmed by a stream","pron":"pot-am-of-or'-ay-tos","pos":"Adjective","thayer":"<ol><li>carried away by a stream (i.e. overwhelmed, drowned in the waters)</li></ol>","xlit":"potamophórētos"},"G2524":{"strongs_def":" and (to send); to lower","derivation":"from G2596 (κατά);","translit":"kathíēmi","lemma":"καθίημι","kjv_def":"let down","pron":"kath-ee'-ay-mee","pos":"Verb","thayer":"<ol><li>to send down, to let down</li></ol>","xlit":"kathíēmi"},"G16":{"derivation":"from G17 (ἀγαθοποιός);","strongs_def":" well-doing, i.e. virtue","kjv_def":"well-doing","translit":"agathopoiḯa","lemma":"ἀγαθοποιΐα","pron":"ag-ath-op-oy-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a course of right action, well doing, virtue</li></ol>","xlit":"agathopoiḯa"},"G1902":{"kjv_def":"be clothed upon","translit":"ependýomai","lemma":"ἐπενδύομαι","derivation":"middle voice from G1909 (ἐπί) and G1746 (ἐνδύω);","strongs_def":" to invest upon oneself","pron":"ep-en-doo'-om-ahee","pos":"Verb","thayer":"<ol><li>to put on over</li></ol>","xlit":"ependýomai"},"G4321":{"derivation":"from G4314 (πρός) and G355 (ἀναλίσκω);","strongs_def":" to expend further","kjv_def":"spend","translit":"prosanalískō","lemma":"προσαναλίσκω","pron":"pros-an-al-is'-ko","pos":"Verb","thayer":"<ol><li>to expend besides (i.e. upon physicians)</li></ol>","xlit":"prosanalískō"},"G2475":{"kjv_def":"Israelite","translit":"Israēlítēs","lemma":"Ἰσραηλίτης","derivation":"from G2474 (Ἰσραήλ);","strongs_def":" an \"Israelite\", i.e. descendant of Israel (literally or figuratively)","pron":"is-rah-ale-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>an Israelite, one of the nation of Israel, a name to be held in honour</li></ol>","xlit":"Israēlítēs"},"G1996":{"kjv_def":"gather (together)","lemma":"ἐπισυνάγω","translit":"episynágō","derivation":"from G1909 (ἐπί) and G4863 (συνάγω);","strongs_def":" to collect upon the same place","pron":"ep-ee-soon-ag'-o","pos":"Verb","thayer":"<ol><li>to gather together besides, to bring together to others already assembled</li><li>to gather together against</li><li>to gather together in one place</li></ol>","xlit":"episynágō"},"G2351":{"strongs_def":" a disturbance","derivation":"from the base of G2360 (θροέω);","lemma":"θόρυβος","translit":"thórybos","kjv_def":"tumult, uproar","pron":"thor'-oo-bos","pos":"Noun Masculine","thayer":"<ol><li>a noise, tumult, uproar<ol type='a'><li>of persons wailing</li><li>of a clamorous and excited multitude</li><li>of riotous persons</li></ol><li>a tumult, as a breach of public order</li></ol>","xlit":"thórybos"},"G1582":{"strongs_def":" to hang upon the lips of a speaker, i.e. listen closely","derivation":"middle voice from G1537 (ἐκ) and G2910 (κρεμάννυμι);","translit":"ekkrémamai","lemma":"ἐκκρέμαμαι","kjv_def":"be very attentive","pron":"ek-krem'-am-ahee","pos":"Verb","thayer":"<ol><li>to hang from</li></ol>","xlit":"ekkrémamai"},"G4761":{"derivation":"from a derivative of G4762 (στρέφω);","strongs_def":" to wrench, i.e. (specially), to torture (by the rack), but only figuratively, to pervert","kjv_def":" wrest","translit":"streblóō","lemma":"στρεβλόω","pron":"streb-lo'-o","pos":"Verb","thayer":"<ol><li>to twist, turn awry</li><li>to torture, put to the rack</li><li>metaphorically to pervert, of one who wrests or tortures language in a false sense</li></ol>","xlit":"streblóō"},"G5291":{"derivation":"from G5259 (ὑπό) and G4766 (στρώννυμι);","strongs_def":" to strew underneath (the feet as a carpet)","kjv_def":"spread","translit":"hypostrṓnnymi","lemma":"ὑποστρώννυμι","pron":"hoop-os-trone'-noo-mee","pos":"Verb","thayer":"<ol><li>to strew, spread under</li></ol>","xlit":"hypostrṓnnymi"},"G2248":{"translit":"hēmâs","lemma":"ἡμᾶς","kjv_def":"our, us, we","strongs_def":" us","derivation":"accusative case plural of G1473 (ἐγώ);","pron":"hay-mas'","thayer":"<ol><li>us, we, our etc.</li></ol>","xlit":"hēmâs"},"G303":{"derivation":"a primary preposition and adverb;","strongs_def":" properly, up; but (by extension) used (distributively) severally, or (locally) at (etc.)","kjv_def":"and, apiece, by, each, every (man), in, through","lemma":"ἀνά","translit":"aná","pron":"an-ah'","pos":"Preposition","thayer":"<ol><li>into the midst, in the midst, amidst, among, between</li></ol>","xlit":"aná"},"G5003":{"translit":"talaipōréō","lemma":"ταλαιπωρέω","kjv_def":"be afflicted","strongs_def":" to be wretched, i.e. realize one's own misery","derivation":"from G5005 (ταλαίπωρος);","pron":"tal-ahee-po-reh'-o","pos":"Verb","thayer":"<ol><li>to toil heavily, to endure labours and hardships</li><li>to be afflicted</li><li>to feel afflicted and miserable</li><li>to afflict</li></ol>","xlit":"talaipōréō"},"G2296":{"derivation":"from G2295 (θαῦμα);","strongs_def":" to wonder; by implication, to admire","kjv_def":"admire, have in admiration, marvel, wonder","translit":"thaumázō","lemma":"θαυμάζω","pron":"thou-mad'-zo","pos":"Verb","thayer":"<ol><li>to wonder, wonder at, marvel</li><li>to be wondered at, to be had in admiration</li></ol>","xlit":"thaumázō"},"G2783":{"kjv_def":"preacher","lemma":"κῆρυξ","translit":"kēryx","derivation":"from G2784 (κηρύσσω);","strongs_def":" a herald, i.e. of divine truth (especially of the gospel)","pron":"kay'-roox","pos":"Noun Masculine","thayer":"<ol><li>a herald or messenger vested with public authority, who conveyed the official messages of kings, magistrates, princes, military commanders, or who gave a public summons or demand, and performed various other duties. In the NT God's ambassador, and the herald or proclaimer of the divine word.</li></ol>","xlit":"kēryx"},"G5235":{"kjv_def":"exceeding, excel, pass","lemma":"ὑπερβάλλω","translit":"hyperbállō","derivation":"from G5228 (ὑπέρ) and G906 (βάλλω);","strongs_def":" to throw beyod the usual mark, i.e. (figuratively) to surpass (only active participle supereminent)","pron":"hoop-er-bal'-lo","pos":"Verb","thayer":"<ol><li>to surpass in throwing, to throw over or beyond any thing</li><li>to transcend, surpass, exceed, excel</li><li>excelling, exceeding</li></ol>","xlit":"hyperbállō"},"G1363":{"kjv_def":"double","lemma":"διπλόω","translit":"diplóō","derivation":"from G1362 (διπλοῦς);","strongs_def":" to render two-fold","pron":"dip-lo'-o","pos":"Verb","thayer":"<ol><li>to double</li></ol>","xlit":"diplóō"},"G4199":{"lemma":"πορθέω","translit":"porthéō","kjv_def":"destroy, waste","strongs_def":" to ravage (figuratively)","derivation":"prolongation from (to sack);","pron":"por-theh'-o","pos":"Verb","thayer":"<ol><li>to destroy, overthrow</li></ol>","xlit":"porthéō"},"G3775":{"kjv_def":"ear","translit":"oûs","lemma":"οὖς","derivation":"apparently a primary word;","strongs_def":" the ear (physically or mentally)","pron":"ooce","pos":"Noun Neuter","thayer":"<ol><li>the ear</li><li>metaphorically the faculty of perceiving with the mind, the faculty of understanding and knowing</li></ol>","xlit":"oûs"},"G1300":{"derivation":"from G1223 (διά) and G5055 (τελέω);","strongs_def":" to accomplish thoroughly, i.e. (subjectively) to persist","kjv_def":"continue","lemma":"διατελέω","translit":"diateléō","pron":"dee-at-el-eh'-o","pos":"Verb","thayer":"<ol><li>to bring thoroughly to an end, accomplish</li></ol>","xlit":"diateléō"},"G4981":{"kjv_def":"school","translit":"scholḗ","lemma":"σχολή","derivation":"probably feminine of a presumed derivative of the alternate of G2192 (ἔχω);","strongs_def":" properly, loitering (as a withholding of oneself from work) or leisure, i.e. (by implication) a \"school\" (as vacation from physical employment)","pron":"skhol-ay'","pos":"Noun Feminine","thayer":"<ol><li>freedom from labour</li><li>a place where there is leisure for anything, a school</li></ol>","xlit":"scholḗ"},"G1256":{"strongs_def":" to say thoroughly, i.e. discuss (in argument or exhortation)","derivation":"middle voice from G1223 (διά) and G3004 (λέγω);","lemma":"διαλέγομαι","translit":"dialégomai","kjv_def":"dispute, preach (unto), reason (with), speak","pron":"dee-al-eg'-om-ahee","pos":"Verb","thayer":"<ol><li>to think different things with one's self, mingle thought with thought<ol type='a'><li>to ponder, revolve in mind</li></ol><li>to converse, discourse with one, argue, discuss</li></ol>","xlit":"dialégomai"},"G4411":{"lemma":"πρωτοκλισία","translit":"prōtoklisía","kjv_def":"chief (highest, uppermost) room","strongs_def":" a reclining first (in the place of honor) at the dinner-bed, i.e. preeminence at meals","derivation":"from G4413 (πρῶτος) and G2828 (κλισία);","pron":"pro-tok-lis-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the first reclining place, the chief place at table</li><li>the relative rank of the several places at table varied among the Persians, Greeks, and Romans; and what arrangements the Jews had in the time of Christ can not be accurately determined</li></ol>","xlit":"prōtoklisía"},"G4119":{"lemma":"πλείων","translit":"pleíōn","kjv_def":"X above, + exceed, more excellent, further, (very) great(-er), long(-er), (very) many, greater (more) part, + yet but","strongs_def":" more in quantity, number, or quality; also (in plural) the major portion","derivation":"comparative of G4183 (πολύς);","pron":"pli-own","pos":"Adjective","thayer":"<ol><li>greater in quantity<ol type='a'><li>the more part, very many</li></ol><li>greater in quality, superior, more excellent</li></ol>","xlit":"pleíōn"},"G4428":{"translit":"ptýssō","lemma":"πτύσσω","kjv_def":"close","strongs_def":" and thus apparently allied to G4072 (πέτομαι) through the idea of expansion, and to 4429 through that of flattening; compare G3961 (πατέω)); to fold, i.e. furl a scroll","derivation":"probably akin to (to spread;","pron":"ptoos'-so","pos":"Verb","thayer":"<ol><li>to fold together, roll up</li></ol>","xlit":"ptýssō"},"G4418":{"derivation":"of uncertain derivation;","strongs_def":" the heel (figuratively)","kjv_def":"heel","lemma":"πτέρνα","translit":"ptérna","pron":"pter'-nah","pos":"Noun Feminine","thayer":"<ol><li>the heel (of the foot)</li><li>to lift up the heel against one<ol type='a'><li>to injure one by trickery (figure borrowed either from kicking, or from a wrestler tripping up his antagonist)</li></ol></li></ol>","xlit":"ptérna"},"G1150":{"lemma":"δαμάζω","translit":"damázō","kjv_def":"tame","strongs_def":" to tame","derivation":"a variation of an obsolete primary of the same meaning;","pron":"dam-ad'-zo","pos":"Verb","thayer":"<ol><li>to tame</li><li>curb, restrain</li></ol>","xlit":"damázō"},"G5434":{"strongs_def":" akin to the base of G5395 (φλόξ)); something desiccated, i.e. a dry twig","derivation":"neuter of a presumed derivative of (to roast or parch;","translit":"phrýganon","lemma":"φρύγανον","kjv_def":"stick","pron":"froo'-gan-on","pos":"Noun Neuter","thayer":"<ol><li>a dry stick, a twig</li><li>all dry sticks, bush wood, fire wood, or similar material used as fuel<ol type='a'><li>of straw, stubble</li></ol></li></ol>","xlit":"phrýganon"},"G4573":{"translit":"sebázomai","lemma":"σεβάζομαι","kjv_def":"worship","strongs_def":" to venerate, i.e. adore","derivation":"middle voice from a derivative of G4576 (σέβομαι);","pron":"seb-ad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to fear, be afraid</li><li>to honour religiously, to worship</li></ol>","xlit":"sebázomai"},"G3575":{"lemma":"Νῶε","translit":"Nōe","kjv_def":"Noe","strongs_def":" Noë, (i.e. Noäch), a patriarch","derivation":"of Hebrew origin (H05146);","pron":"no'-eh","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Noah = \"rest\"</p><ol><li>the tenth in descent from Adam, second father of the human family</li></ol>","xlit":"Nōe"},"G5284":{"kjv_def":"sail under","lemma":"ὑποπλέω","translit":"hypopléō","derivation":"from G5259 (ὑπό) and G4126 (πλέω);","strongs_def":" to sail under the lee of","pron":"hoop-op-leh'-o","pos":"Verb","thayer":"<ol><li>to sail under, that is, to sail close by</li><li>to the leeward of</li></ol>","xlit":"hypopléō"},"G1554":{"derivation":"from G1537 (ἐκ) and G1325 (δίδωμι);","strongs_def":" to give forth, i.e. (specially) to lease","kjv_def":"let forth (out)","lemma":"ἐκδίδωμι","translit":"ekdídōmi","pron":"ek-did-o'-mee","pos":"Verb","thayer":"<ol><li>to give out of one's house, power, hand, stores</li><li>to give out, give up, give over</li><li>to let out for hire</li><li>to farm out</li><li>to let out for one's advantage</li></ol>","xlit":"ekdídōmi"},"G4944":{"derivation":"from G4862 (σύν) and G5605 (ὠδίνω);","strongs_def":" to have (parturition) pangs in company (concert, simultaneously) with, i.e. (figuratively) to sympathize (in expectation of relief from suffering)","kjv_def":"travail in pain together","translit":"synōdínō","lemma":"συνωδίνω","pron":"soon-o-dee'-no","pos":"Verb","thayer":"<ol><li>to feel the pains of travail with, be in travail together</li><li>metaphorically to undergo agony (like a woman in childbirth) along with</li></ol>","xlit":"synōdínō"},"G4515":{"kjv_def":"Latin","lemma":"Ῥωμαϊστί","translit":"Rhōmaïstí","derivation":"adverb from a presumed derivative of G4516 (Ῥώμη);","strongs_def":" Romaistically, i.e. in the Latin language","pron":"hro-mah-is-tee'","pos":"Adverb","thayer":"<strong>Thayer Definition</strong>: Latin = \"of Rome's strength\"</p><ol><li>the language spoken by the Romans</li></ol>","xlit":"Rhōmaïstí"},"G584":{"translit":"apodeíknymi","lemma":"ἀποδείκνυμι","kjv_def":"(ap-)prove, set forth, shew","strongs_def":" to show off, i.e. exhibit; figuratively, to demonstrate, i.e. accredit","derivation":"from G575 (ἀπό) and G1166 (δεικνύω);","pron":"ap-od-ike'-noo-mee","pos":"Verb","thayer":"<ol><li>to point away from one's self, to point out, show forth, to expose to view, exhibit</li><li>to declare, to show, to prove what kind of person anyone is, to prove by arguments, demonstrate</li></ol>","xlit":"apodeíknymi"},"G5067":{"strongs_def":" fourth","derivation":"ordinal from G5064 (τέσσαρες);","translit":"tétartos","lemma":"τέταρτος","kjv_def":"four(-th)","pron":"tet'-ar-tos","pos":"Adjective","thayer":"<ol><li>the fourth</li></ol>","xlit":"tétartos"},"G111":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of (statute;","strongs_def":" from the base of G5087 (τίθημι)); illegal; by implication, flagitious","kjv_def":"abominable, unlawful thing","lemma":"ἀθέμιτος","translit":"athémitos","pron":"ath-em'-ee-tos","pos":"Adjective","thayer":"<ol><li>contrary to law and justice, prohibited by law, illicit, criminal</li></ol>","xlit":"athémitos"},"G2755":{"lemma":"κενόδοξος","translit":"kenódoxos","kjv_def":"desirous of vain-glory","strongs_def":" vainly glorifying, i.e. self-conceited","derivation":"from G2756 (κενός) and G1391 (δόξα);","pron":"ken-od'-ox-os","pos":"Adjective","thayer":"<ol><li>glorying without reason, conceited, vain glorious, eager for empty glory</li></ol>","xlit":"kenódoxos"},"G5477":{"translit":"Chanaán","lemma":"Χαναάν","kjv_def":"Chanaan","strongs_def":" Chanaan (i.e. Kenaan), the early name of Palestine","derivation":"of Hebrew origin (H03667);","pron":"khan-ah-an'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Canaan = \"lowland\"</p><ol><li>the land of Canaan</li><li>in a narrower sense: the part of Palestine lying west of the Jordan</li><li>in a wider sense: all of Palestine</li></ol>","xlit":"Chanaán"},"G1860":{"derivation":"from G1861 (ἐπαγγέλλω);","strongs_def":" an announcement (for information, assent or pledge; especially a divine assurance of good)","kjv_def":"message, promise","lemma":"ἐπαγγελία","translit":"epangelía","pron":"ep-ang-el-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>announcement</li><li>promise<ol type='a'><li>the act of promising, a promise given or to be given</li><li>a promised good or blessing</li></ol></li></ol>","xlit":"epangelía"},"G839":{"kjv_def":"(to-)morrow, next day","lemma":"αὔριον","translit":"aúrion","derivation":"from a derivative of the same as G109 (ἀήρ) (meaning a breeze, i.e. the morning air);","strongs_def":" properly, fresh, i.e. (adverb with ellipsis of G2250 (ἡμέρα)) to-morrow","pron":"ow'-ree-on","pos":"Adverb","thayer":"<ol><li>tomorrow</li></ol>","xlit":"aúrion"},"G4228":{"kjv_def":"foot(-stool)","translit":"poús","lemma":"πούς","derivation":"a primary word;","strongs_def":" a \"foot\" (figuratively or literally)","pron":"pooce","pos":"Noun Masculine","thayer":"<ol><li>a foot, both of men or beast<ol type='a'><li>often in the orient, one put his foot on vanquished</li><li>of disciples listening to their teacher's instruction are said to be at his feet</li></ol></li></ol>","xlit":"poús"},"G709":{"kjv_def":"dine","translit":"aristáō","lemma":"ἀριστάω","derivation":"from G712 (ἄριστον);","strongs_def":" to take the principle meal","pron":"ar-is-tah'-o","pos":"Verb","thayer":"<ol><li>to breakfast</li><li>by later usage, to dine</li></ol>","xlit":"aristáō"},"G2324":{"kjv_def":"servant","lemma":"θεράπων","translit":"therápōn","derivation":"apparently a participle from an otherwise obsolete derivative of the base of G2330 (θέρος);","strongs_def":" a menial attendant (as if cherishing)","pron":"ther-ap'-ohn","pos":"Noun Masculine","thayer":"<ol><li>an attendant, servant: of God<ol type='a'><li>spoken of Moses discharging the duties committed to him by God</li></ol></li></ol>","xlit":"therápōn"},"G2321":{"kjv_def":"Theophilus","lemma":"Θεόφιλος","translit":"Theóphilos","derivation":"from G2316 (θεός) and G5384 (φίλος);","strongs_def":" friend of God; Theophilus, a Christian","pron":"theh-of'-il-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Theophilus = \"friend of God\"</p><ol><li>the person to whom Luke addressed his Gospel and the book of Acts</li></ol>","xlit":"Theóphilos"},"G3658":{"lemma":"ὅμιλος","translit":"hómilos","kjv_def":"company","strongs_def":" association together, i.e. a multitude","derivation":"from the base of G3674 (ὁμοῦ) and a derivative of the alternate of G138 (αἱρέομαι) (meaning a crowd);","pron":"hom'-il-os","pos":"Noun Masculine","thayer":"<ol><li>a multitude of men gathered together, a crowd, a throng</li></ol>","xlit":"hómilos"},"G5080":{"strongs_def":" to liquefy","derivation":"apparently a primary verb;","lemma":"τήκω","translit":"tḗkō","kjv_def":"melt","pron":"tay'-ko","pos":"Verb","thayer":"<ol><li>to make liquid</li><li>to become liquid, to melt</li><li>to perish or become destroyed by melting</li></ol>","xlit":"tḗkō"},"G2614":{"kjv_def":"follow after","lemma":"καταδιώκω","translit":"katadiṓkō","derivation":"from G2596 (κατά) and G1377 (διώκω);","strongs_def":" to hunt down, i.e. search for","pron":"kat-ad-ee-o'-ko","pos":"Verb","thayer":"<ol><li>to follow after, follow up</li></ol>","xlit":"katadiṓkō"},"G1906":{"strongs_def":" an inquiry","derivation":"from G1905 (ἐπερωτάω);","lemma":"ἐπερώτημα","translit":"eperṓtēma","kjv_def":"answer","pron":"ep-er-o'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>an enquiry, a question</li><li>a demand</li><li>earnestly seeking<ol type='a'><li>craving, an intense desire</li></ol></li></ol>","xlit":"eperṓtēma"},"G4480":{"kjv_def":"chariot","translit":"rhéda","lemma":"ῥέδα","derivation":"of Latin origin;","strongs_def":" a rheda, i.e. four-wheeled carriage (wagon for riding)","pron":"hred'-ah","pos":"Noun Feminine","thayer":"<ol><li>a chariot, a type of vehicle having four wheels</li></ol>","xlit":"rhéda"},"G2939":{"translit":"ktístēs","lemma":"κτίστης","kjv_def":"Creator","strongs_def":" a founder, i.e. God (as author of all things)","derivation":"from G2936 (κτίζω);","pron":"ktis-tace'","pos":"Noun Masculine","thayer":"<ol><li>a founder</li><li>a creator</li></ol>","xlit":"ktístēs"},"G3366":{"strongs_def":" but not, not even; in a continued negation, nor","derivation":"from G3361 (μή) and G1161 (δέ);","translit":"mēdé","lemma":"μηδέ","kjv_def":"neither, nor (yet), (no) not (once, so much as)","pron":"may-deh'","thayer":"<ol><li>and not, but not, nor, not</li></ol>","xlit":"mēdé"},"G3413":{"strongs_def":" Michael, an archangel","derivation":"of Hebrew origin (H04317);","lemma":"Μιχαήλ","translit":"Michaḗl","kjv_def":"Michael","pron":"mikh-ah-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Michael = \"who is like God\"</p><ol><li>the first of the chief princes or archangels who is supposed to be the guardian angel of the Israelites</li></ol>","xlit":"Michaḗl"},"G4943":{"kjv_def":"help together","lemma":"συνυπουργέω","translit":"synypourgéō","derivation":"from G4862 (σύν) and a derivative of a compound of G5259 (ὑπό) and the base of G2041 (ἔργον);","strongs_def":" to be a co-auxiliary, i.e. assist","pron":"soon-oop-oorg-eh'-o","pos":"Verb","thayer":"<ol><li>to help together</li></ol>","xlit":"synypourgéō"},"G1987":{"derivation":"apparently a middle voice of G2186 (ἐφίστημι) (with G3563 (νοῦς) implied);","strongs_def":" to put the mind upon, i.e. comprehend, or be acquainted with","kjv_def":"know, understand","lemma":"ἐπίσταμαι","translit":"epístamai","pron":"ep-is'-tam-ahee","pos":"Verb","thayer":"<ol><li>to put one's attention on, fix one's thoughts on, to turn one's self or one's mind to, put one's thought upon a thing<ol type='a'><li>to be acquainted with, to understand</li><li>to know</li></ol></li></ol>","xlit":"epístamai"},"G2836":{"derivation":"from (\"hollow\");","strongs_def":" a cavity, i.e. (especially) the abdomen; by implication, the matrix; figuratively, the heart","kjv_def":"belly, womb","lemma":"κοιλία","translit":"koilía","pron":"koy-lee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the whole belly, the entire cavity<ol type='a'><li>the upper [i.e. stomach] and the lower belly are distinguished</li></ol><li>the lower belly, the lower region, the receptacle of the excrement</li><li>the gullet<ol type='a'><li>to be given up to the pleasures of the palate, to gluttony</li></ol><li>the womb, the place where the foetus is conceived and nourished until birth<ol type='a'><li>of the uterus of animals</li></ol><li>the innermost part of a man, the soul, heart as the seat of thought, feeling, choice</li></ol>","xlit":"koilía"},"G2736":{"derivation":"(compare G2737 (κατώτερος)); adverb from G2596 (κατά);","strongs_def":" downwards","kjv_def":"beneath, bottom, down, under","lemma":"κάτω","translit":"kátō","pron":"kat'-o","thayer":"<ol><li>down, downwards</li><li>below, beneath<ol type='a'><li>of place, below</li><li>of temporal succession</li></ol></li></ol>","xlit":"kátō"},"G1353":{"strongs_def":" to travel through","derivation":"from G1223 (διά) and G3593 (ὁδεύω);","lemma":"διοδεύω","translit":"diodeúō","kjv_def":"go throughout, pass through","pron":"dee-od-yoo'-o","pos":"Verb","thayer":"<ol><li>to pass or travel through</li><li>to travel here and there, go about</li></ol>","xlit":"diodeúō"},"G3114":{"translit":"makrothyméō","lemma":"μακροθυμέω","kjv_def":"bear (suffer) long, be longsuffering, have (long) patience, be patient, patiently endure","strongs_def":" to be long-spirited, i.e. (objectively) forbearing or (subjectively) patient","derivation":"from the same as G3116 (μακροθυμώς);","pron":"mak-roth-oo-meh'-o","pos":"Verb","thayer":"<ol><li>to be of a long spirit, not to lose heart<ol type='a'><li>to persevere patiently and bravely in enduring misfortunes and troubles</li><li>to be patient in bearing the offenses and injuries of others<ol><li>to be mild and slow in avenging</li><li>to be longsuffering, slow to anger, slow to punish</li></ol></li></ol></li></ol>","xlit":"makrothyméō"},"G2914":{"kjv_def":"Crete","translit":"Krḗtē","lemma":"Κρήτη","derivation":"of uncertain derivation;","strongs_def":" Crete, an island in the Mediterranean","pron":"kray'-tay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Crete = \"fleshy\"</p><ol><li>the largest and most fertile island of the Mediterranean archipelago or Aegean Sea, now the modern Candia</li></ol>","xlit":"Krḗtē"},"G4955":{"lemma":"συστασιαστής","translit":"systasiastḗs","kjv_def":"make insurrection with","strongs_def":" a fellow-insurgent","derivation":"from a compound of G4862 (σύν) and a derivative of G4714 (στάσις);","pron":"soos-tas-ee-as-tace'","pos":"Noun Masculine","thayer":"<ol><li>a companion in insurrection, a fellow rioter</li></ol>","xlit":"systasiastḗs"},"G5281":{"kjv_def":"enduring, patience, patient continuance (waiting)","translit":"hypomonḗ","lemma":"ὑπομονή","derivation":"from G5278 (ὑπομένω);","strongs_def":" cheerful (or hopeful) endurance, constancy","pron":"hoop-om-on-ay'","pos":"Noun Feminine","thayer":"<ol><li>steadfastness, constancy, endurance<ol type='a'><li>in the NT the characteristic of a man who is not swerved from his deliberate purpose and his loyalty to faith and piety by even the greatest trials and sufferings</li><li>patiently, and steadfastly</li></ol><li>a patient, steadfast waiting for</li><li>a patient enduring, sustaining, perseverance</li></ol>","xlit":"hypomonḗ"},"G1768":{"kjv_def":"ninety and nine","lemma":"ἐννενηκονταεννέα","translit":"ennenēkontaennéa","derivation":"from a (tenth) multiple of G1767 (ἐννέα) and G1767 (ἐννέα) itself;","strongs_def":" ninety-nine","pron":"en-nen-ay-kon-tah-en-neh'-ah","pos":"Noun","thayer":"<ol><li>ninety nine</li></ol>","xlit":"ennenēkontaennéa"},"G3739":{"strongs_def":" the relatively (sometimes demonstrative) pronoun, who, which, what, that","derivation":"probably a primary word (or perhaps a form of the article G3588 (ὁ));","lemma":"ὅς","translit":"hós","kjv_def":"one, (an-, the) other, some, that, what, which, who(-m, -se), etc","pron":"hos","thayer":"<ol><li>who, which, what, that</li></ol>","xlit":"hós"},"G1816":{"translit":"exanatéllō","lemma":"ἐξανατέλλω","kjv_def":"spring up","strongs_def":" to start up out of the ground, i.e. germinate","derivation":"from G1537 (ἐκ) and G393 (ἀνατέλλω);","pron":"ex-an-at-el'-lo","pos":"Verb","thayer":"<ol><li>to make spring up, cause to shoot forth</li><li>to spring up</li></ol>","xlit":"exanatéllō"},"G442":{"derivation":"from G444 (ἄνθρωπος);","strongs_def":" human","kjv_def":"human, common to man, man(-kind), (man-)kind, men's, after the manner of men","translit":"anthrṓpinos","lemma":"ἀνθρώπινος","pron":"anth-ro'-pee-nos","pos":"Adjective","thayer":"<ol><li>human<ol type='a'><li>applied to things belonging to men</li></ol></li></ol>","xlit":"anthrṓpinos"},"G5099":{"strongs_def":" to pay a price, i.e. as a penalty","derivation":"strengthened for a primary (which is only used as an alternate in certain tenses);","translit":"tínō","lemma":"τίνω","kjv_def":"be punished with","pron":"tee'-no","pos":"Verb","thayer":"<ol><li>to pay, to recompense</li><li>to pay penalty, suffer punishment</li></ol>","xlit":"tínō"},"G918":{"strongs_def":" son of Tolmai; Bar-tholomæus, a Christian apostle","derivation":"of Chaldee origin (H01247 and H08526);","lemma":"Βαρθολομαῖος","translit":"Bartholomaîos","kjv_def":"Bartholomeus","pron":"bar-thol-om-ah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Bartholomew = \"son of Tolmai\"</p><ol><li>one of the twelve apostles of Christ</li></ol>","xlit":"Bartholomaîos"},"G5333":{"derivation":"the same as 5332","kjv_def":"sorcerer","lemma":"φάρμακος","translit":"phármakos","pron":"far-mak-os'","pos":"Adjective","thayer":"<ol><li>pertaining to magical arts</li></ol>","xlit":"phármakos"},"G5030":{"derivation":"adverb from G5036 (ταχύς);","strongs_def":" briefly, i.e. (in time) speedily, or (in manner) rapidly","kjv_def":"hastily, quickly, shortly, soon, suddenly","translit":"tachéōs","lemma":"ταχέως","pron":"takh-eh'-oce","pos":"Adverb","thayer":"<ol><li>quickly, shortly</li></ol>","xlit":"tachéōs"},"G1235":{"lemma":"διαγρηγορέω","translit":"diagrēgoréō","kjv_def":"be awake","strongs_def":" to waken thoroughly","derivation":"from G1223 (διά) and G1127 (γρηγορεύω);","pron":"dee-ag-ray-gor-eh'-o","pos":"Verb","thayer":"<ol><li>to watch through</li><li>to remain awake</li><li>to be fully awake</li></ol>","xlit":"diagrēgoréō"},"G186":{"kjv_def":"without wavering","translit":"aklinḗs","lemma":"ἀκλινής","derivation":"from G1 (Α) (as a negative particle) and G2827 (κλίνω);","strongs_def":" not leaning, i.e. (figuratively) firm","pron":"ak-lee-nace'","pos":"Adjective","thayer":"<ol><li>not inclining, firm, unmoved</li></ol>","xlit":"aklinḗs"},"G2523":{"derivation":"another (active) form for G2516 (καθέζομαι);","strongs_def":" to seat down, i.e. set (figuratively, appoint); intransitively, to sit (down); figuratively, to settle (hover, dwell)","kjv_def":"continue, set, sit (down), tarry","translit":"kathízō","lemma":"καθίζω","pron":"kath-id'-zo","pos":"Verb","thayer":"<ol><li>to make to sit down<ol type='a'><li>to set, appoint, to confer a kingdom on one</li></ol><li>intransitively<ol type='a'><li>to sit down</li><li>to sit<ol><li>to have fixed one's abode</li><li>to sojourn, to settle, settle down</li></ol></li></ol></li></ol>","xlit":"kathízō"},"G3068":{"translit":"loúō","lemma":"λούω","kjv_def":"wash","strongs_def":" to bathe (the whole person; whereas G3538 (νίπτω) means to wet a part only, and G4150 (πλύνω) to wash, cleanse garments exclusively)","derivation":"a primary verb;","pron":"loo'-o","pos":"Verb","thayer":"<ol><li>to bathe, wash<ol type='a'><li>of a dead person</li><li>washing to cleanse blood out of wounds</li></ol></li></ol>","xlit":"loúō"},"G607":{"translit":"apokephalízō","lemma":"ἀποκεφαλίζω","kjv_def":"behead","strongs_def":" to decapitate","derivation":"from G575 (ἀπό) and G2776 (κεφαλή);","pron":"ap-ok-ef-al-id'-zo","pos":"Verb","thayer":"<ol><li>to cut off the head, behead, decapitate</li></ol>","xlit":"apokephalízō"},"G4121":{"kjv_def":"abound, abundant, make to increase, have over","translit":"pleonázō","lemma":"πλεονάζω","derivation":"from G4119 (πλείων);","strongs_def":" to do, make or be more, i.e. increase (transitively or intransitively); by extension, to superabound","pron":"pleh-on-ad'-zo","pos":"Verb","thayer":"<ol><li>to superabound<ol type='a'><li>of things<ol><li>to exist in abundance</li><li>to increase</li><li>be augmented</li></ol></li></ol><li>to make to increase: one in a thing</li></ol>","xlit":"pleonázō"},"G1328":{"kjv_def":"interpreter","lemma":"διερμηνευτής","translit":"diermēneutḗs","derivation":"from G1329 (διερμηνεύω);","strongs_def":" an explainer","pron":"dee-er-main-yoo-tace'","pos":"Noun Masculine","thayer":"<ol><li>an interpreter</li></ol>","xlit":"diermēneutḗs"},"G4754":{"kjv_def":"soldier, (go to) war(-fare)","lemma":"στρατεύομαι","translit":"strateúomai","derivation":"middle voice from the base of G4756 (στρατιά);","strongs_def":" to serve in a military campaign; figuratively, to execute the apostolate (with its arduous duties and functions), to contend with carnal inclinations","pron":"strat-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to make a military expedition, to lead soldiers to war or to battle, (spoken of a commander)</li><li>to do military duty, be on active service, be a soldier</li><li>to fight</li></ol>","xlit":"strateúomai"},"G1975":{"translit":"epiporeúomai","lemma":"ἐπιπορεύομαι","kjv_def":"come","strongs_def":" to journey further, i.e. travel on (reach)","derivation":"from G1909 (ἐπί) and G4198 (πορεύομαι);","pron":"ep-ee-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to go or journey to</li><li>to go to, traverse<ol type='a'><li>regions, cities</li></ol><li>to make a hostile inroad, overrun, march over</li></ol>","xlit":"epiporeúomai"},"G2046":{"strongs_def":" an alternate for G2036 (ἔπω) in certain tenses; to utter, i.e. speak or say","derivation":"probably a fuller form of G4483 (ῥέω);","lemma":"ἐρέω","translit":"eréō","kjv_def":"call, say, speak (of), tell","pron":"er-eh'-o","pos":"Verb","thayer":"<ol><li>to utter, speak, say</li></ol>","xlit":"eréō"},"G3200":{"kjv_def":"parchment","lemma":"μεμβράνα","translit":"membrána","derivation":"of Latin origin (\"membrane\");","strongs_def":" a (written) sheep-skin","pron":"mem-bran'-ah","pos":"Noun Feminine","thayer":"<ol><li>parchment, made first of dressed skins at Pergamos, hence its name</li></ol>","xlit":"membrána"},"G3698":{"strongs_def":" what(-ever) then, i.e. (of time) as soon as","derivation":"from G3739 (ὅς) and G4218 (ποτέ);","lemma":"ὁπότε","translit":"hopóte","kjv_def":"when","pron":"hop-ot'-eh","thayer":"<ol><li>when</li></ol>","xlit":"hopóte"},"G4561":{"lemma":"σάρξ","translit":"sárx","kjv_def":"carnal(-ly, + -ly minded), flesh(-ly)","strongs_def":" flesh (as stripped of the skin), i.e. (strictly) the meat of an animal (as food), or (by extension) the body (as opposed to the soul (or spirit), or as the symbol of what is external, or as the means of kindred), or (by implication) human nature (with its frailties (physically or morally) and passions), or (specially), a human being (as such)","derivation":"probably from the base of G4563 (σαρόω);","pron":"sarx","pos":"Noun Feminine","thayer":"<ol><li>flesh (the soft substance of the living body, which covers the bones and is permeated with blood) of both man and beasts</li><li>the body<ol type='a'><li>the body of a man</li><li>used of natural or physical origin, generation or relationship<ol><li>born of natural generation</li></ol><li>the sensuous nature of man, \"the animal nature\"<ol><li>without any suggestion of depravity</li><li>the animal nature with cravings which incite to sin</li><li>the physical nature of man as subject to suffering</li></ol></li></ol><li>a living creature (because possessed of a body of flesh) whether man or beast</li><li>the flesh, denotes mere human nature, the earthly nature of man apart from divine influence, and therefore prone to sin and opposed to God</li></ol>","xlit":"sárx"},"G2501":{"translit":"Iōsḗph","lemma":"Ἰωσήφ","kjv_def":"Joseph","strongs_def":" Joseph, the name of seven Israelites","derivation":"of Hebrew origin (H03130);","pron":"ee-o-safe'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Joseph = \"let him add\"</p><ol><li>the patriarch, the eleventh son of Jacob</li><li>the son of Jonan or Jonam, one of the ancestors of Christ, <a class='bible' href='#b42.3.30'>Luk 3:30</a></li><li>the son of Judah [or Judas; better Joda] another ancestor of Jesus, <a class='bible' href='#b42.3.26'>Luk 3:26</a></li><li>the son of Mattathias, another ancestor of Christ, <a class='bible' href='#b42.3.24'>Luk 3:24</a></li><li>the husband of Mary, the mother of Jesus</li><li>a half-brother of Jesus <a class='bible' href='#b40.13.55'>Mat 13:55</a></li><li>Joseph of Arimathaea, a member of the Sanhedrin, who favoured Jesus. <a class='bible' href='#b40.27.57'>Mat 27:57</a>,<a class='bible' href='#b40.27.59'>Mat 27:59</a>; <a class='bible' href='#b41.15.43'>Mar 15:43</a>,<a class='bible' href='#b41.15.45'>Mar 15:45</a></li><li>Joseph surnamed Barnabas <a class='bible' href='#b44.4.36'>Act 4:36</a></li><li>Joseph call Barsabas and surnamed Justus, <a class='bible' href='#b44.1.23'>Act 1:23</a></li></ol>","xlit":"Iōsḗph"},"G553":{"translit":"apekdéchomai","lemma":"ἀπεκδέχομαι","kjv_def":"look (wait) for","strongs_def":" to expect fully","derivation":"from G575 (ἀπό) and G1551 (ἐκδέχομαι);","pron":"ap-ek-dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>assiduously and patiently waiting for</li></ol>","xlit":"apekdéchomai"},"G2584":{"translit":"Kapernaoúm","lemma":"Καπερναούμ","kjv_def":"Capernaum","strongs_def":" Capernaum (i.e. Caphanachum), a place in Palestine","derivation":"of Hebrew origin (probably H03723 and H05151);","pron":"cap-er-nah-oom'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Capernaum = \"village of comfort\"</p><ol><li>a flourishing city of Galilee situated on the western shore of the Sea of Galilee or Lake of Gennesaret, near the place where the Jordan flows into the lake</li></ol>","xlit":"Kapernaoúm"},"G2496":{"translit":"Iōrám","lemma":"Ἰωράμ","kjv_def":"Joram","strongs_def":" Joram, an Israelite","derivation":"of Hebrew origin (H03141);","pron":"ee-o-ram'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jehoram = \"whom Jehovah has exalted\"</p><ol><li>the son of Jehoshaphat, king of Judah, succeeded his father on the throne of Judah</li></ol>","xlit":"Iōrám"},"G658":{"strongs_def":" to complete entirely, i.e. consummate","derivation":"from G575 (ἀπό) and G5055 (τελέω);","lemma":"ἀποτελέω","translit":"apoteléō","kjv_def":"finish","pron":"ap-ot-el-eh'-o","pos":"Verb","thayer":"<ol><li>to perfect, to bring quite to an end</li><li>accomplish</li></ol>","xlit":"apoteléō"},"G1161":{"kjv_def":"also, and, but, moreover, now (often unexpressed in English)","lemma":"δέ","translit":"dé","derivation":"a primary particle (adversative or continuative);","strongs_def":" but, and, etc.","pron":"deh","pos":"Conjunction","thayer":"<ol><li>but, moreover, and, etc.</li></ol>","xlit":"dé"},"G5518":{"kjv_def":"measure","translit":"choînix","lemma":"χοῖνιξ","derivation":"of uncertain derivation;","strongs_def":" a chœnix or certain dry measure","pron":"khoy'-nix","pos":"Noun Feminine","thayer":"<ol><li>a choenix, a dry measure, containing four cotylae or two setarii (less than our quart, one litre) (or as much as would support a man of moderate appetite for a day)</li></ol>","xlit":"choînix"},"G4709":{"translit":"spoudaíōs","lemma":"σπουδαίως","kjv_def":"diligently, instantly","strongs_def":" earnestly, promptly","derivation":"adverb from G4705 (σπουδαῖος);","pron":"spoo-dah'-yoce","pos":"Adverb","thayer":"<ol><li>hastily, with haste</li><li>diligently</li><li>earnestly</li></ol>","xlit":"spoudaíōs"},"G1473":{"derivation":"a primary pronoun of the first person I (only expressed when emphatic)","translit":"egṓ","lemma":"ἐγώ","kjv_def":"I, me","pron":"eg-o'","thayer":"<ol><li>I, me, my</li></ol>","xlit":"egṓ"},"G578":{"lemma":"ἀποβλέπω","translit":"apoblépō","kjv_def":"have respect","strongs_def":" to look away from everything else, i.e. (figuratively) intently regard","derivation":"from G575 (ἀπό) and G991 (βλέπω);","pron":"ap-ob-lep'-o","pos":"Verb","thayer":"<ol><li>to turn the eyes away from other things and fix them on some one thing<ol type='a'><li>to look at attentively</li></ol><li>to look with steadfast mental gaze</li></ol>","xlit":"apoblépō"},"G2607":{"derivation":"from G2596 (κατά) and G1097 (γινώσκω);","strongs_def":" to note against, i.e. find fault with","kjv_def":"blame, condemn","lemma":"καταγινώσκω","translit":"kataginṓskō","pron":"kat-ag-in-o'-sko","pos":"Verb","thayer":"<ol><li>to find fault with, blame</li><li>to accuse, condemn</li></ol>","xlit":"kataginṓskō"},"G5265":{"strongs_def":" to bind under one's feet, i.e. put on shoes or sandals","derivation":"from G5259 (ὑπό) and G1210 (δέω);","lemma":"ὑποδέω","translit":"hypodéō","kjv_def":"bind on, (be) shod","pron":"hoop-od-eh'-o","pos":"Verb","thayer":"<ol><li>to underbind</li><li>to bind under one's self, bind on</li></ol>","xlit":"hypodéō"},"G2655":{"translit":"katanarkáō","lemma":"καταναρκάω","kjv_def":"be burdensome (chargeable)","strongs_def":" to grow utterly torpid, i.e. (by implication) slothful (figuratively, expensive)","derivation":"from G2596 (κατά) and (to be numb);","pron":"kat-an-ar-kah'-o","pos":"Verb","thayer":"<ol><li>to cause to grow numb or torpid</li><li>to be torpid, inactive, to be to the detriment of one</li><li>to weigh heavily upon, be burdensome to</li></ol>","xlit":"katanarkáō"},"G3535":{"lemma":"Νινευΐ","translit":"Nineuḯ","kjv_def":"Nineve","strongs_def":" Ninevi (i.e. Nineveh), the capital of Assyria","derivation":"of Hebrew origin (H05210);","pron":"nin-yoo-ee'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Nineveh = \"offspring of ease: offspring abiding\"</p><ol><li>the capital of the ancient kingdom of Assyria</li></ol>","xlit":"Nineuḯ"},"G3902":{"lemma":"παράσημος","translit":"parásēmos","kjv_def":"sign","strongs_def":" side-marked, i.e. labelled (with a badge (figure-head) of a ship)","derivation":"from G3844 (παρά) and the base of G4591 (σημαίνω);","pron":"par-as'-ay-mos","pos":"Adjective","thayer":"<ol><li>marked falsely, spurious, counterfeit: as a coin</li><li>marked beside or in the margin<ol type='a'><li>so noteworthy words, which the reader of a book marks on the margin</li></ol><li>noted, marked, conspicuous, remarkable<ol type='a'><li>of persons in a bad sense, notorious</li></ol><li>marked with a sign: a ship marked with the image or figure of Dioscuri (Castor and Pollux)</li></ol>","xlit":"parásēmos"},"G4698":{"lemma":"σπλάγχνον","translit":"splánchnon","kjv_def":"bowels, inward affection, + tender mercy","strongs_def":" an intestine (plural); figuratively, pity or sympathy","derivation":"probably strengthened from (the \"spleen\");","pron":"splangkh'-non","pos":"Noun Neuter","thayer":"<ol><li>bowels, intestines, (the heart, lungs, liver, etc.)<ol type='a'><li>bowels</li><li>the bowels were regarded as the seat of the more violent passions, such as anger and love; but by the Hebrews as the seat of the tenderer affections, especially kindness, benevolence, compassion; hence our heart (tender mercies, affections, etc.)</li><li>a heart in which mercy resides</li></ol></li></ol>","xlit":"splánchnon"},"G2897":{"translit":"kraipálē","lemma":"κραιπάλη","kjv_def":"surfeiting","strongs_def":" properly, a headache (as a seizure of pain) from drunkenness, i.e. (by implication) a debauch (by analogy, a glut)","derivation":"probably from the same as G726 (ἁρπάζω);","pron":"krahee-pal'-ay","pos":"Noun Feminine","thayer":"<ol><li>the giddiness and headache caused by drinking wine to excess</li></ol>","xlit":"kraipálē"},"G2531":{"derivation":"from G2596 (κατά) and G5613 (ὡς);","strongs_def":" just (or inasmuch) as, that","kjv_def":"according to, (according, even) as, how, when","lemma":"καθώς","translit":"kathṓs","pron":"kath-oce'","pos":"Adverb","thayer":"<ol><li>according as<ol type='a'><li>just as, even as</li><li>in proportion as, in the degree that</li></ol><li>since, seeing that, agreeably to the fact that</li><li>when, after that</li></ol>","xlit":"kathṓs"},"G947":{"kjv_def":"abominable","lemma":"βδελυκτός","translit":"bdelyktós","derivation":"from G948 (βδελύσσω);","strongs_def":" detestable, i.e. (specially) idolatrous","pron":"bdel-ook-tos'","pos":"Adjective","thayer":"<ol><li>abominable, detestable</li></ol>","xlit":"bdelyktós"},"G504":{"strongs_def":" waterless, i.e. dry","derivation":"from G1 (Α) (as a negative particle) and G5204 (ὕδωρ);","translit":"ánydros","lemma":"ἄνυδρος","kjv_def":"dry, without water","pron":"an'-oo-dros","pos":"Adjective","thayer":"<ol><li>without water</li></ol>","xlit":"ánydros"},"G58":{"derivation":"from (to gather;","strongs_def":" probably akin to G1453 (ἐγείρω)); properly, the town-square (as a place of public resort); by implication, a market or thoroughfare","kjv_def":"market(-place), street","translit":"agorá","lemma":"ἀγορά","pron":"ag-or-ah'","pos":"Noun Feminine","thayer":"<ol><li>any assembly, especially of the people</li><li>the place of assembly<ol type='a'><li>for public debating</li><li>for elections</li><li>for trials</li><li>for buying and selling</li><li>for all kinds of business</li></ol><li>market place, street</li></ol>","xlit":"agorá"},"G1883":{"strongs_def":" up above, i.e. over or on (of place, amount, rank, etc.)","derivation":"from G1909 (ἐπί) and G507 (ἄνω);","translit":"epánō","lemma":"ἐπάνω","kjv_def":"above, more than, (up-)on, over","pron":"ep-an'-o","pos":"Adverb","thayer":"<ol><li>above<ol type='a'><li>of place</li><li>of number: more than</li></ol></li></ol>","xlit":"epánō"},"G4774":{"kjv_def":"permission","translit":"syngnṓmē","lemma":"συγγνώμη","derivation":"from a compound of G4862 (σύν) and G1097 (γινώσκω);","strongs_def":" fellow knowledge, i.e. concession","pron":"soong-gno'-may","pos":"Noun Feminine","thayer":"<ol><li>pardon, indulgence</li></ol>","xlit":"syngnṓmē"},"G2106":{"strongs_def":" to think well of, i.e. approve (an act); specially, to approbate (a person or thing)","derivation":"from G2095 (εὖ) and G1380 (δοκέω);","translit":"eudokéō","lemma":"εὐδοκέω","kjv_def":"think good, (be well) please(-d), be the good (have, take) pleasure, be willing","pron":"yoo-dok-eh'-o","pos":"Verb","thayer":"<ol><li>it seems good to one, is one's good pleasure<ol type='a'><li>think it good, choose, determine, decide</li><li>to do willingly</li><li>to be ready to, to prefer, choose rather</li></ol><li>to be well pleased with, take pleasure in, to be favourably inclined towards one</li></ol>","xlit":"eudokéō"},"G1503":{"derivation":"apparently a primary verb (perhaps akin to G1502 (εἴκω) through the idea of faintness as a copy);","strongs_def":" to resemble","kjv_def":"be like","translit":"eíkō","lemma":"εἴκω","pron":"i'-ko","pos":"Verb","thayer":"<ol><li>to be like</li></ol>","xlit":"eíkō"},"G4433":{"strongs_def":" to be a beggar, i.e. (by implication) to become indigent (figuratively)","derivation":"from G4434 (πτωχός);","lemma":"πτωχεύω","translit":"ptōcheúō","kjv_def":"become poor","pron":"pto-khyoo'-o","pos":"Verb","thayer":"<ol><li>to be a beggar, to beg, to be poor</li></ol>","xlit":"ptōcheúō"},"G1831":{"derivation":"from G1537 (ἐκ) and G2064 (ἔρχομαι);","strongs_def":" to issue (literally or figuratively)","kjv_def":"come (forth, out), depart (out of), escape, get out, go (abroad, away, forth, out, thence), proceed (forth), spread abroad","translit":"exérchomai","lemma":"ἐξέρχομαι","pron":"ex-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go or come forth of<ol type='a'><li>with mention of the place out of which one goes, or the point from which he departs<ol><li>of those who leave a place of their own accord</li><li>of those who are expelled or cast out</li></ol></li></ol><li>metaphorically<ol type='a'><li>to go out of an assembly, i.e. forsake it</li><li>to come forth from physically, arise from, to be born of</li><li>to go forth from one's power, escape from it in safety</li><li>to come forth (from privacy) into the world, before the public, (of those who by novelty of opinion attract attention)</li><li>of things<ol><li>of reports, rumours, messages, precepts</li><li>to be made known, declared</li><li>to be spread, to be proclaimed</li><li>to come forth<ol type='a'><li>emitted as from the heart or the mouth</li><li>to flow forth from the body</li><li>to emanate, issue<ol><li>used of a sudden flash of lightning</li><li>used of a thing vanishing</li><li>used of a hope which has disappeared</li></ol></li></ol></li></ol></li></ol></li></ol>","xlit":"exérchomai"},"G4142":{"lemma":"πλοιάριον","translit":"ploiárion","kjv_def":"boat, little (small) ship","strongs_def":" a boat","derivation":"neuter of a presumed derivative of G4143 (πλοῖον);","pron":"ploy-ar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a small vessel, a boat</li></ol>","xlit":"ploiárion"},"G1297":{"kjv_def":"commandment","lemma":"διάταγμα","translit":"diátagma","derivation":"from G1299 (διατάσσω);","strongs_def":" an arrangement, i.e. (authoritative) edict","pron":"dee-at'-ag-mah","pos":"Noun Neuter","thayer":"<ol><li>an injunction, mandate</li></ol>","xlit":"diátagma"},"G5122":{"kjv_def":"named","lemma":"τοὔνομα","translit":"toúnoma","derivation":"contraction for the neuter of G3588 (ὁ) and G3686 (ὄνομα);","strongs_def":" the name (is)","pron":"too'-no-mah","pos":"Adverb","thayer":"<ol><li>by name</li></ol>","xlit":"toúnoma"},"G1556":{"strongs_def":" to vindicate, retaliate, punish","derivation":"from G1558 (ἔκδικος);","lemma":"ἐκδικέω","translit":"ekdikéō","kjv_def":"a (re-)venge","pron":"ek-dik-eh'-o","pos":"Verb","thayer":"<ol><li>to vindicate one's right, do one justice<ol type='a'><li>to protect, defend, one person from another</li></ol><li>to avenge a thing<ol type='a'><li>to punish a person for a thing</li></ol></li></ol>","xlit":"ekdikéō"},"G1296":{"strongs_def":" arrangement, i.e. institution","derivation":"from G1299 (διατάσσω);","translit":"diatagḗ","lemma":"διαταγή","kjv_def":"instrumentality","pron":"dee-at-ag-ay'","pos":"Noun Feminine","thayer":"<ol><li>a disposition, arrangement, ordinance</li></ol>","xlit":"diatagḗ"},"G2093":{"kjv_def":"ready","lemma":"ἑτοίμως","translit":"hetoímōs","derivation":"adverb from G2092 (ἕτοιμος);","strongs_def":" in readiness","pron":"het'-oy-moce","pos":"Adverb","thayer":"<ol><li>readily, to be ready</li></ol>","xlit":"hetoímōs"},"G3124":{"kjv_def":"Malchus","lemma":"Μάλχος","translit":"Málchos","derivation":"of Hebrew origin (H04429);","strongs_def":" Malchus, an Israelite","pron":"mal'-khos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Malchus = \"king or kingdom\"</p><ol><li>was the name of the servant of the high priest whose right ear Peter cut off at the time of Christ's arrest in the garden</li></ol>","xlit":"Málchos"},"G5029":{"kjv_def":"peradventure(-haps)","translit":"tácha","lemma":"τάχα","derivation":"as if neuter plural of G5036 (ταχύς) (adverbially);","strongs_def":" shortly, i.e. (figuratively) possibly","pron":"takh'-ah","pos":"Adverb","thayer":"<ol><li>hastily, quickly, soon</li><li>peradventure, perhaps</li></ol>","xlit":"tácha"},"G3685":{"translit":"onínēmi","lemma":"ὀνίνημι","kjv_def":"have joy","strongs_def":" for which another prolonged form () is used as an alternate in some tenses (unless indeed it be identical with the base of G3686 (ὄνομα) through the idea of notoriety); to gratify, i.e. (middle voice) to derive pleasure or advantage from","derivation":"a prolonged form of an apparently primary verb (, to slur);","pron":"on-in'-ay-mee","pos":"Verb","thayer":"<ol><li>to be useful, to profit, help</li><li>to receive profit or advantage, be helped [or have joy]</li></ol>","xlit":"onínēmi"},"G3720":{"derivation":"from G3722 (ὄρθρος);","strongs_def":" relating to the dawn, i.e. matutinal (as an epithet of Venus, especially brilliant in the early day)","kjv_def":"morning","lemma":"ὀρθρινός","translit":"orthrinós","pron":"or-thrin-os'","pos":"Adjective","thayer":"<ol><li>early</li></ol>","xlit":"orthrinós"},"G2339":{"derivation":"from (a wild animal, as game);","strongs_def":" hunting, i.e. (figuratively) destruction","kjv_def":"trap","lemma":"θήρα","translit":"thḗra","pron":"thay'-rah","pos":"Noun Feminine","thayer":"<ol><li>a hunting of wild beasts to destroy them</li><li>metaphorically of preparing destruction for men</li></ol>","xlit":"thḗra"},"G3095":{"lemma":"μαγεία","translit":"mageía","kjv_def":"sorcery","strongs_def":" \"magic\"","derivation":"from G3096 (μαγεύω);","pron":"mag-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>magic, magic arts, sorceries</li></ol>","xlit":"mageía"},"G4531":{"kjv_def":"move, shake (together), which can(-not) be shaken, stir up","lemma":"σαλεύω","translit":"saleúō","derivation":"from G4535 (σάλος);","strongs_def":" to waver, i.e. agitate, rock, topple or (by implication) destroy; figuratively, to disturb, incite","pron":"sal-yoo'-o","pos":"Verb","thayer":"<ol><li>a motion produced by winds, storms, waves, etc<ol type='a'><li>to agitate or shake</li><li>to cause to totter</li><li>to shake thoroughly, of a measure filled by shaking its contents together</li></ol><li>to shake down, overthrow<ol type='a'><li>to cast down from one's (secure and happy) state</li><li>to move, agitate the mind, to disturb one</li></ol></li></ol>","xlit":"saleúō"},"G2103":{"translit":"Eúboulos","lemma":"Εὔβουλος","kjv_def":"Eubulus","strongs_def":" good-willer; Eubulus, a Christian","derivation":"from G2095 (εὖ) and G1014 (βούλομαι);","pron":"yoo'-boo-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eubulus = \"prudent\"</p><ol><li>a Christian at Rome</li></ol>","xlit":"Eúboulos"},"G4855":{"derivation":"from G4862 (σύν) and G5453 (φύω);","strongs_def":" passive, to grow jointly","kjv_def":"spring up with","lemma":"συμφύω","translit":"symphýō","pron":"soom-foo'-o","pos":"Verb","thayer":"<ol><li>to cause to grow together</li><li>to grow together, grow with</li></ol>","xlit":"symphýō"},"G405":{"translit":"andrapodistḗs","lemma":"ἀνδραποδιστής","kjv_def":"menstealer","strongs_def":" an enslaver (as bringing men to his feet)","derivation":"from a derivative of a compound of G435 (ἀνήρ) and G4228 (πούς);","pron":"an-drap-od-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>a slave-dealer, kidnapper, man-stealer<ol type='a'><li>of one who unjustly reduces free men to slavery</li><li>of one who steals the slaves of others and sells them</li></ol></li></ol>","xlit":"andrapodistḗs"},"G2225":{"kjv_def":"live, preserve","translit":"zōogonéō","lemma":"ζωογονέω","derivation":"from the same as G2226 (ζῶον) and a derivative of G1096 (γίνομαι);","strongs_def":" to engender alive, i.e. (by analogy) to rescue (passively, be saved) from death","pron":"dzo-og-on-eh'-o","pos":"Verb","thayer":"<ol><li>to bring forth alive</li><li>to give life</li><li>to preserve alive</li></ol>","xlit":"zōogonéō"},"G2192":{"derivation":"a primary verb;","strongs_def":" to hold (used in very various applications, literally or figuratively, direct or remote; such as possession; ability, contiuity, relation, or condition)","kjv_def":"be (able, X hold, possessed with), accompany, + begin to amend, can(+ -not), X conceive, count, diseased, do + eat, + enjoy, + fear, following, have, hold, keep, + lack, + go to law, lie, + must needs, + of necessity, + need, next, + recover, + reign, + rest, + return, X sick, take for, + tremble, + uncircumcised, use","translit":"échō","lemma":"ἔχω","pron":"ekh'-o","pos":"Verb","thayer":"<ol><li>to have, i.e. to hold<ol type='a'><li>to have (hold) in the hand, in the sense of wearing, to have (hold) possession of the mind (refers to alarm, agitating emotions, etc.), to hold fast keep, to have or comprise or involve, to regard or consider or hold as</li></ol><li>to have, i.e. own, possess<ol type='a'><li>external things such as pertain to property or riches or furniture or utensils or goods or food etc.</li><li>used of those joined to any one by the bonds of natural blood or marriage or friendship or duty or law etc, of attendance or companionship</li></ol><li>to hold one's self or find one's self so and so, to be in such or such a condition</li><li>to hold one's self to a thing, to lay hold of a thing, to adhere or cling to<ol type='a'><li>to be closely joined to a person or a thing</li></ol></li></ol>","xlit":"échō"},"G4620":{"kjv_def":"portion of meat","translit":"sitómetron","lemma":"σιτόμετρον","derivation":"from G4621 (σῖτος) and G3358 (μέτρον);","strongs_def":" a grain-measure, i.e. (by implication) ration (allowance of food)","pron":"sit-om'-et-ron","pos":"Noun Neuter","thayer":"<ol><li>a measured 'portion of' grain or 'food'</li></ol>","xlit":"sitómetron"},"G2005":{"strongs_def":" to fulfill further (or completely), i.e. execute; by implication, to terminate, undergo","derivation":"from G1909 (ἐπί) and G5055 (τελέω);","translit":"epiteléō","lemma":"ἐπιτελέω","kjv_def":"accomplish, do, finish, (make) (perfect), perform(X -ance)","pron":"ep-ee-tel-eh'-o","pos":"Verb","thayer":"<ol><li>to bring to an end, accomplish, perfect, execute, complete<ol type='a'><li>to take upon one's self</li><li>to make an end for one's self<ol><li>to leave off</li></ol></li></ol><li>to appoint to, impose upon</li></ol>","xlit":"epiteléō"},"G193":{"kjv_def":"incontinent","translit":"akratḗs","lemma":"ἀκρατής","derivation":"from G1 (Α) (as a negative particle) and G2904 (κράτος);","strongs_def":" powerless, i.e. without self-control","pron":"ak-rat'-ace","pos":"Adjective","thayer":"<ol><li>without self-control, intemperate</li></ol>","xlit":"akratḗs"},"G4483":{"kjv_def":"command, make, say, speak (of)","lemma":"ῥέω","translit":"rhéō","derivation":"perhaps akin (or identical) with G4482 (ῥέω) (through the idea of pouring forth);","strongs_def":" to utter, i.e. speak or say","pron":"hreh'-o","pos":"Verb","thayer":"<ol><li>to pour forth, to utter</li></ol>","xlit":"rhéō"},"G2551":{"kjv_def":"curse, speak evil of","translit":"kakologéō","lemma":"κακολογέω","derivation":"from a compound of G2556 (κακός) and G3056 (λόγος);","strongs_def":" to revile","pron":"kak-ol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to speak evil of, revile, abuse, one</li><li>to curse</li></ol>","xlit":"kakologéō"},"G1196":{"derivation":"from G1199 (δεσμόν);","strongs_def":" to tie, i.e. shackle","kjv_def":"bind","lemma":"δεσμέω","translit":"desméō","pron":"des-meh'-o","pos":"Verb","thayer":"<ol><li>to bind, tie</li></ol>","xlit":"desméō"},"G2371":{"strongs_def":" to be in a furious fight, i.e. (figuratively) to be exasperated","derivation":"from a presumed compound of G2372 (θυμός) and G3164 (μάχομαι);","lemma":"θυμομαχέω","translit":"thymomachéō","kjv_def":"be highly displeased","pron":"thoo-mom-akh-eh'-o","pos":"Verb","thayer":"<ol><li>to carry on war with great animosity</li><li>to be very angry, be exasperated</li></ol>","xlit":"thymomachéō"},"G1130":{"derivation":"from a derivative of G1131 (γυμνός);","strongs_def":" to strip, i.e. (reflexively) go poorly clad","kjv_def":"be naked","lemma":"γυμνητεύω","translit":"gymnēteúō","pron":"goom-nayt-yoo'-o","pos":"Verb","thayer":"<ol><li>to be lightly or poorly clad</li><li>to be a light armed soldier</li></ol>","xlit":"gymnēteúō"},"G4706":{"lemma":"σπουδαιότερον","translit":"spoudaióteron","kjv_def":"very diligently","strongs_def":" more earnestly than others), i.e. very promptly","derivation":"neuter of G4707 (σπουδαιότερος) as adverb;","pron":"spoo-dah-yot'-er-on","pos":"Adjective","thayer":"<ol><li>very diligently</li></ol>","xlit":"spoudaióteron"},"G2261":{"kjv_def":"gentle","translit":"ḗpios","lemma":"ἤπιος","derivation":"probably from G2031 (ἔπος);","strongs_def":" properly, affable, i.e. mild or kind","pron":"ay'-pee-os","pos":"Adjective","thayer":"<ol><li>affable</li><li>mild, gentle</li></ol>","xlit":"ḗpios"},"G5257":{"derivation":"from G5259 (ὑπό) and a derivative of (to row);","strongs_def":" an under-oarsman, i.e. (generally) subordinate (assistant, sexton, constable)","kjv_def":"minister, officer, servant","lemma":"ὑπηρέτης","translit":"hypērétēs","pron":"hoop-ay-ret'-ace","pos":"Noun Masculine","thayer":"<ol><li>servant<ol type='a'><li>an underrower, subordinate rower</li><li>any one who serves with hands: a servant<ol><li>in the NT of the officers and attendants of magistrates as - of the officer who executes penalties</li><li>of the attendants of a king, servants, retinue, the soldiers of a king, of the attendant of a synagogue</li><li>of any one ministering or rendering service</li></ol><li>any one who aids another in any work<ol><li>an assistant</li><li>of the preacher of the gospel</li></ol></li></ol></li></ol>","xlit":"hypērétēs"},"G3662":{"strongs_def":" to resemble","derivation":"from G3664 (ὅμοιος);","translit":"homoiázō","lemma":"ὁμοιάζω","kjv_def":"agree","pron":"hom-oy-ad'-zo","pos":"Verb","thayer":"<ol><li>to be like</li></ol>","xlit":"homoiázō"},"G274":{"strongs_def":" faultlessly","derivation":"adverb from G273 (ἄμεμπτος);","lemma":"ἀμέμπτως","translit":"amémptōs","kjv_def":"blameless, unblamably","pron":"am-emp'-toce","pos":"Adverb","thayer":"<ol><li>blameless, so that there is no cause for censure</li></ol>","xlit":"amémptōs"},"G132":{"derivation":"of uncertain derivation;","strongs_def":" Ænĕas, an Israelite","kjv_def":"Æneas","lemma":"Αἰνέας","translit":"Ainéas","pron":"ahee-neh'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aeneas = \"laudable\"</p><ol><li>the name of a paralytic cured by Peter at Lydia</li></ol>","xlit":"Ainéas"},"G4026":{"derivation":"from G4012 (περί) and G2476 (ἵστημι);","strongs_def":" to stand all around, i.e. (near) to be a bystander, or (aloof) to keep away from","kjv_def":"avoid, shun, stand by (round about)","translit":"periḯstēmi","lemma":"περιΐστημι","pron":"per-ee-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place around one</li><li>to stand around<ol type='a'><li>to turn one's self about for the purpose of avoiding something</li><li>to avoid, shun</li></ol></li></ol>","xlit":"periḯstēmi"},"G5056":{"derivation":"from a primary (to set out for a definite point or goal);","strongs_def":" properly, the point aimed at as a limit, i.e. (by implication) the conclusion of an act or state (termination (literally, figuratively or indefinitely), result (immediate, ultimate or prophetic), purpose); specially, an impost or levy (as paid)","kjv_def":"+ continual, custom, end(-ing), finally, uttermost","translit":"télos","lemma":"τέλος","pron":"tel'-os","pos":"Noun Neuter","thayer":"<ol><li>end<ol type='a'><li>termination, the limit at which a thing ceases to be (always of the end of some act or state, but not of the end of a period of time)</li><li>the end<ol><li>the last in any succession or series</li><li>eternal</li></ol><li>that by which a thing is finished, its close, issue</li><li>the end to which all things relate, the aim, purpose</li></ol><li>toll, custom (i.e. indirect tax on goods)</li></ol>","xlit":"télos"},"G1701":{"lemma":"ἐμπαιγμός","translit":"empaigmós","kjv_def":"mocking","strongs_def":" derision","derivation":"from G1702 (ἐμπαίζω);","pron":"emp-aheeg-mos'","pos":"Noun Masculine","thayer":"<ol><li>a mocking, scoffing</li></ol>","xlit":"empaigmós"},"G3090":{"kjv_def":"Lois","lemma":"Λωΐς","translit":"Lōḯs","derivation":"of uncertain origin;","strongs_def":" Lois, a Christian woman","pron":"lo-ece'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Lois = \"agreeable\"</p><ol><li>the grandmother of Timothy</li></ol>","xlit":"Lōḯs"},"G668":{"kjv_def":"escape","translit":"apopheúgō","lemma":"ἀποφεύγω","derivation":"from G575 (ἀπό) and G5343 (φεύγω);","strongs_def":" (figuratively) to escape","pron":"ap-of-yoo'-go","pos":"Verb","thayer":"<ol><li>to flee from, escape</li></ol>","xlit":"apopheúgō"},"G3736":{"lemma":"ὀρύσσω","translit":"orýssō","kjv_def":"dig","strongs_def":" to \"burrow\" in the ground, i.e. dig","derivation":"apparently a primary verb;","pron":"or-oos'-so","pos":"Verb","thayer":"<ol><li>to dig</li></ol>","xlit":"orýssō"},"G3881":{"derivation":"from G3844 (παρά) and the middle voice of G3004 (λέγω) (in its original sense);","strongs_def":" (specially), to lay one's course near, i.e. sail past","kjv_def":"pass, sail by","lemma":"παραλέγομαι","translit":"paralégomai","pron":"par-al-eg'-om-ahee","pos":"Verb","thayer":"<ol><li>to sail past, coast along</li><li>work past, weather</li></ol>","xlit":"paralégomai"},"G1546":{"derivation":"from G1544 (ἐκβάλλω);","strongs_def":" ejection, i.e. (specially) a throwing overboard of the cargo","kjv_def":"+ lighten the ship","translit":"ekbolḗ","lemma":"ἐκβολή","pron":"ek-bol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a casting out</li><li>the throwing overboard of goods and lading whereby sailors lighten a ship in a storm to keep her from sinking</li></ol>","xlit":"ekbolḗ"},"G5300":{"translit":"hŷs","lemma":"ὗς","kjv_def":"sow","strongs_def":" a hog (\"swine\")","derivation":"apparently a primary word;","pron":"hoos","pos":"Noun Feminine","thayer":"<ol><li>swine</li></ol>","xlit":"hŷs"},"G5016":{"kjv_def":"trouble(-ing)","lemma":"ταραχή","translit":"tarachḗ","derivation":"feminine from G5015 (ταράσσω);","strongs_def":" disturbance, i.e. (of water) roiling, or (of a mob) sedition","pron":"tar-akh-ay'","pos":"Noun Feminine","thayer":"<ol><li>disturbance, commotion</li><li>metaphorically a tumult, sedition</li></ol>","xlit":"tarachḗ"},"G2262":{"derivation":"of Hebrew origin (H06147);","strongs_def":" Er, an Israelite","kjv_def":"Er","lemma":"Ἤρ","translit":"Ḗr","pron":"ayr","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Er = \"watchful\"</p><ol><li>the son of Jose and the father of Elmodam</li></ol>","xlit":"Ḗr"},"G830":{"strongs_def":" self-chosen, i.e. (by implication) voluntary","derivation":"from G846 (αὐτός) and the same as G140 (αἱρετίζω);","lemma":"αὐθαίρετος","translit":"authaíretos","kjv_def":"of own accord, willing of self","pron":"ow-thah'-ee-ret-os","pos":"Adjective","thayer":"<ol><li>voluntary, of free choice, of one's own accord</li></ol>","xlit":"authaíretos"},"G4778":{"strongs_def":" to maltreat in company with, i.e. (passively) endure persecution together","derivation":"from G4862 (σύν) and G2558 (κακουχέω);","translit":"synkakouchéō","lemma":"συγκακουχέω","kjv_def":"suffer affliction with","pron":"soong-kak-oo-kheh'-o","pos":"Verb","thayer":"<ol><li>to treat ill with another</li><li>to be ill treated in company with, share persecutions or come into a fellowship of ills</li></ol>","xlit":"synkakouchéō"},"G3153":{"derivation":"from G3152 (μάταιος);","strongs_def":" inutility; figuratively, transientness; morally, depravity","kjv_def":"vanity","translit":"mataiótēs","lemma":"ματαιότης","pron":"mat-ah-yot'-ace","pos":"Noun Feminine","thayer":"<ol><li>what is devoid of truth and appropriateness</li><li>perverseness, depravity</li><li>frailty, want of vigour</li></ol>","xlit":"mataiótēs"},"G3985":{"derivation":"from G3984 (πεῖρα);","strongs_def":" to test (objectively), i.e. endeavor, scrutinize, entice, discipline","kjv_def":"assay, examine, go about, prove, tempt(-er), try","lemma":"πειράζω","translit":"peirázō","pron":"pi-rad'-zo","pos":"Verb","thayer":"<ol><li>to try whether a thing can be done<ol type='a'><li>to attempt, endeavour</li></ol><li>to try, make trial of, test: for the purpose of ascertaining his quantity, or what he thinks, or how he will behave himself<ol type='a'><li>in a good sense</li><li>in a bad sense, to test one maliciously, craftily to put to the proof his feelings or judgments</li><li>to try or test one's faith, virtue, character, by enticement to sin<ol><li>to solicit to sin, to tempt<ol type='a'><li>of the temptations of the devil</li></ol></li></ol><li>after the OT usage<ol><li>of God: to inflict evils upon one in order to prove his character and the steadfastness of his faith</li><li>men are said to tempt God by exhibitions of distrust, as though they wished to try whether he is not justly distrusted</li><li>by impious or wicked conduct to test God's justice and patience, and to challenge him, as it were to give proof of his perfections.</li></ol></li></ol></li></ol>","xlit":"peirázō"},"G932":{"strongs_def":" properly, royalty, i.e. (abstractly) rule, or (concretely) a realm (literally or figuratively)","derivation":"from G935 (βασιλεύς);","lemma":"βασιλεία","translit":"basileía","kjv_def":"kingdom, + reign","pron":"bas-il-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>royal power, kingship, dominion, rule<ol type='a'><li>not to be confused with an actual kingdom but rather the right or authority to rule over a kingdom</li><li>of the royal power of Jesus as the triumphant Messiah</li><li>of the royal power and dignity conferred on Christians in the Messiah's kingdom</li></ol><li>a kingdom, the territory subject to the rule of a king</li><li>used in the N.T. to refer to the reign of the Messiah</li></ol>","xlit":"basileía"},"G4394":{"translit":"prophēteía","lemma":"προφητεία","kjv_def":"prophecy, prophesying","strongs_def":" prediction (scriptural or other)","derivation":"from G4396 (προφήτης) (\"prophecy\");","pron":"prof-ay-ti'-ah","pos":"Noun Feminine","thayer":"<ol><li>prophecy<ol type='a'><li>a discourse emanating from divine inspiration and declaring the purposes of God, whether by reproving and admonishing the wicked, or comforting the afflicted, or revealing things hidden; especially by foretelling future events</li><li>Used in the NT of the utterance of OT prophets<ol><li>of the prediction of events relating to Christ's kingdom and its speedy triumph, together with the consolations and admonitions pertaining to it, the spirit of prophecy, the divine mind, to which the prophetic faculty is due</li><li>of the endowment and speech of the Christian teachers called prophets</li><li>the gifts and utterances of these prophets, especially of the predictions of the works of which, set apart to teach the gospel, will accomplish for the kingdom of Christ</li></ol></li></ol></li></ol>","xlit":"prophēteía"},"G4676":{"derivation":"of Latin origin;","strongs_def":" a sudarium (sweat-cloth), i.e. towel (for wiping the perspiration from the face, or binding the face of a corpse)","kjv_def":"handkerchief, napkin","translit":"soudárion","lemma":"σουδάριον","pron":"soo-dar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a handkerchief</li><li>a cloth for wiping perspiration from the face and for cleaning the nose and also used in swathing the head of a corpse</li></ol>","xlit":"soudárion"},"G5267":{"translit":"hypódikos","lemma":"ὑπόδικος","kjv_def":"guilty","strongs_def":" under sentence, i.e. (by implication) condemned","derivation":"from G5259 (ὑπό) and G1349 (δίκη);","pron":"hoop-od'-ee-kos","pos":"Adjective","thayer":"<ol><li>under judgment, one who lost his suit</li><li>debtor to one, owing satisfaction to<ol type='a'><li>of liable to punishment from God</li></ol></li></ol>","xlit":"hypódikos"},"G52":{"strongs_def":" ignorance (properly, the quality)","derivation":"from G50 (ἀγνοέω);","translit":"ágnoia","lemma":"ἄγνοια","kjv_def":"ignorance","pron":"ag'-noy-ah","pos":"Noun Feminine","thayer":"<ol><li>lack of knowledge, ignorance<ol type='a'><li>especially of divine things</li><li>of moral blindness</li></ol></li></ol>","xlit":"ágnoia"},"G2612":{"kjv_def":"far more evident","translit":"katádēlos","lemma":"κατάδηλος","derivation":"from G2596 (κατά) intensive and G1212 (δῆλος);","strongs_def":" manifest","pron":"kat-ad'-ay-los","pos":"Adjective","thayer":"<ol><li>thoroughly clear, plain, evident</li></ol>","xlit":"katádēlos"},"G4731":{"strongs_def":" stiff, i.e. solid, stable (literally or figuratively)","derivation":"from G2476 (ἵστημι);","lemma":"στερεός","translit":"stereós","kjv_def":"stedfast, strong, sure","pron":"ster-eh-os'","pos":"Adjective","thayer":"<ol><li>strong, firm, immovable, solid, hard, rigid<ol type='a'><li>in a bad sense, cruel, stiff, stubborn, hard</li><li>in a good sense, firm, steadfast</li></ol></li></ol>","xlit":"stereós"},"G3626":{"strongs_def":" be \"ware\"); a stayer at home, i.e. domestically inclined (a \"good housekeeper\")","derivation":"from G3624 (οἶκος) and (a guard;","translit":"oikourós","lemma":"οἰκουρός","kjv_def":"keeper at home","pron":"oy-koo-ros'","pos":"Adjective","thayer":"<ol><li>caring for the house, working at home<ol type='a'><li>the (watch or) keeper of the house</li><li>keeping at home and taking care of household affairs</li><li>a domestic</li></ol></li></ol>","xlit":"oikourós"},"G2380":{"lemma":"θύω","translit":"thýō","kjv_def":"kill, (do) sacrifice, slay","strongs_def":" properly, to rush (breathe hard, blow, smoke), i.e. (by implication) to sacrifice (properly, by fire, but genitive case); by extension to immolate (slaughter for any purpose)","derivation":"a primary verb;","pron":"thoo'-o","pos":"Verb","thayer":"<ol><li>to sacrifice, immolate</li><li>to slay, kill<ol type='a'><li>of the paschal lamb</li></ol><li>slaughter</li></ol>","xlit":"thýō"},"G5453":{"lemma":"φύω","translit":"phýō","kjv_def":"spring (up)","strongs_def":" probably originally, to \"puff\" or blow, i.e. to swell up; but only used in the implied sense, to germinate or grow (sprout, produce), literally or figuratively","derivation":"a primary verb;","pron":"foo'-o","pos":"Verb","thayer":"<ol><li>to beget, bring forth, produce</li><li>to be born, to spring up, to grow</li><li>to shoot forth, spring up</li></ol>","xlit":"phýō"},"G2616":{"kjv_def":"oppress","translit":"katadynasteúō","lemma":"καταδυναστεύω","derivation":"from G2596 (κατά) and a derivative of G1413 (δυνάστης);","strongs_def":" to exercise dominion against, i.e. oppress","pron":"kat-ad-oo-nas-tyoo'-o","pos":"Verb","thayer":"<ol><li>to exercise harsh control over one, to use one's power against one</li><li>to oppress one</li></ol>","xlit":"katadynasteúō"},"G5375":{"kjv_def":"Philippi","translit":"Phílippoi","lemma":"Φίλιπποι","derivation":"plural of G5376 (Φίλιππος);","strongs_def":" Philippi, a place in Macedonia","pron":"fil'-ip-poy","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Philippi = \"Lover of horses\"</p><ol><li>a city of Macedonia located on or near the northern coast of the Aegean Sea, between the rivers Strymon and Nestus, and the cities Neapolis and Amphipolis</li></ol>","xlit":"Phílippoi"},"G2872":{"derivation":"from a derivative of G2873 (κόπος);","strongs_def":" to feel fatigue; by implication, to work hard","kjv_def":"(bestow) labour, toil, be wearied","translit":"kopiáō","lemma":"κοπιάω","pron":"kop-ee-ah'-o","pos":"Verb","thayer":"<ol><li>to grow weary, tired, exhausted (with toil or burdens or grief)</li><li>to labour with wearisome effort, to toil<ol type='a'><li>of bodily labour</li></ol></li></ol>","xlit":"kopiáō"},"G525":{"lemma":"ἀπαλλάσσω","translit":"apallássō","kjv_def":"deliver, depart","strongs_def":" to change away, i.e. release, (reflexively) remove","derivation":"from G575 (ἀπό) and G236 (ἀλλάσσω);","pron":"ap-al-las'-so","pos":"Verb","thayer":"<ol><li>to remove, release, to be removed, to depart</li><li>to set free, deliver</li></ol>","xlit":"apallássō"},"G4799":{"kjv_def":"confusion","translit":"sýnchysis","lemma":"σύγχυσις","derivation":"from G4797 (συγχέω);","strongs_def":" commixture, i.e. (figuratively) riotous disturbance","pron":"soong'-khoo-sis","pos":"Noun Feminine","thayer":"<ol><li>confusion, disturbance<ol type='a'><li>of riotous persons</li></ol></li></ol>","xlit":"sýnchysis"},"G1487":{"derivation":"a primary particle of conditionality;","strongs_def":" if, whether, that, etc.","kjv_def":"forasmuch as, if, that, (al-)though, whether","translit":"ei","lemma":"εἰ","pron":"i","pos":"Conjunction","thayer":"<ol><li>if, whether</li></ol>","xlit":"ei"},"G327":{"strongs_def":" to search out","derivation":"from G303 (ἀνά) and G2212 (ζητέω);","lemma":"ἀναζητέω","translit":"anazētéō","kjv_def":"seek","pron":"an-ad-zay-teh'-o","pos":"Verb","thayer":"<ol><li>to seek out, search through, make diligent search</li></ol>","xlit":"anazētéō"},"G134":{"strongs_def":" to praise (God)","derivation":"from G136 (αἶνος);","translit":"ainéō","lemma":"αἰνέω","kjv_def":"praise","pron":"ahee-neh'-o","pos":"Verb","thayer":"<ol><li>to praise, extol, to sing praises in honour to God</li><li>to allow, recommend</li><li>to promise or vow</li></ol>","xlit":"ainéō"},"G1228":{"kjv_def":"false accuser, devil, slanderer","lemma":"διάβολος","translit":"diábolos","derivation":"from G1225 (διαβάλλω);","strongs_def":" a traducer; specially, Satan (compare H07854)","pron":"dee-ab'-ol-os","pos":"Adjective","thayer":"<ol><li>prone to slander, slanderous, accusing falsely<ol type='a'><li>a calumniator, false accuser, slanderer</li></ol><li>metaphorically applied to a man who, by opposing the cause of God, may be said to act the part of the devil or to side with him</li></ol>","xlit":"diábolos"},"G3419":{"derivation":"from G3420 (μνήμη);","strongs_def":" a remembrance, i.e. cenotaph (place of interment)","kjv_def":"grave, sepulchre, tomb","lemma":"μνημεῖον","translit":"mnēmeîon","pron":"mnay-mi'-on","pos":"Noun Neuter","thayer":"<ol><li>any visible object for preserving or recalling the memory of any person or thing<ol type='a'><li>a memorial, monument, specifically, a sepulchral monument</li></ol><li>a sepulchre, a tomb</li></ol>","xlit":"mnēmeîon"},"G5181":{"strongs_def":" a \"tyrant\"; Tyrannus, an Ephesian","derivation":"a provincial form of the derivative of the base of G2962 (κύριος);","translit":"Týrannos","lemma":"Τύραννος","kjv_def":"Tyrannus","pron":"too'-ran-nos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tyrannus = \"sovereign\"</p><ol><li>an Ephesian in whose school Paul taught the gospel</li></ol>","xlit":"Týrannos"},"G4607":{"strongs_def":" a dagger-man or assassin; a freebooter (Jewish fanatic outlawed by the Romans)","derivation":"of Latin origin;","translit":"sikários","lemma":"σικάριος","kjv_def":"murderer","pron":"sik-ar'-ee-os","pos":"Noun Masculine","thayer":"<ol><li>an assassin<ol type='a'><li>one who carries a dagger or short sword under his clothing, that he may kill secretly and treacherously any one he wishes to</li><li>a cutthroat</li></ol></li></ol>","xlit":"sikários"},"G5088":{"translit":"tíktō","lemma":"τίκτω","kjv_def":"bear, be born, bring forth, be delivered, be in travail","strongs_def":" to produce (from seed, as a mother, a plant, the earth, etc.), literally or figuratively","derivation":"a strengthened form of a primary (which is used only as alternate in certain tenses);","pron":"tik'-to","pos":"Verb","thayer":"<ol><li>to bring forth, bear, produce (fruit from the seed)<ol type='a'><li>of a woman giving birth</li><li>of the earth bringing forth its fruits</li><li>metaphorically to bear, bring forth</li></ol></li></ol>","xlit":"tíktō"},"G3744":{"strongs_def":" fragrance (literally or figuratively)","derivation":"from G3605 (ὄζω);","translit":"osmḗ","lemma":"ὀσμή","kjv_def":"odour, savour","pron":"os-may'","pos":"Noun Feminine","thayer":"<ol><li>a smell, odour</li></ol>","xlit":"osmḗ"},"G501":{"lemma":"ἀντλέω","translit":"antléō","kjv_def":"draw (out)","strongs_def":" to bale up (properly, bilge water), i.e. dip water (with a bucket, pitcher, etc.)","derivation":"from (the hold of a ship);","pron":"ant-leh-o","pos":"Verb","thayer":"<ol><li>to draw out of a ship's bilge-water, to bale or pump out</li><li>to draw water</li></ol>","xlit":"antléō"},"G4113":{"derivation":"feminine of G4116 (πλατύς);","strongs_def":" a wide \"plat\" or \"place\", i.e. open square","kjv_def":"street","lemma":"πλατεῖα","translit":"plateîa","pron":"plat-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>a broad way, a street</li></ol>","xlit":"plateîa"},"G571":{"derivation":"from G1 (Α) (as a negative particle) and G4103 (πιστός);","strongs_def":" (actively) disbelieving, i.e. without Christian faith (specially, a heathen); (passively) untrustworthy (person), or incredible (thing)","kjv_def":"that believeth not, faithless, incredible thing, infidel, unbeliever(-ing)","translit":"ápistos","lemma":"ἄπιστος","pron":"ap'-is-tos","pos":"Adjective","thayer":"<ol><li>unfaithful, faithless, (not to be trusted, perfidious)</li><li>incredible<ol type='a'><li>of things</li></ol><li>unbelieving, incredulous<ol type='a'><li>without trust (in God)</li></ol></li></ol>","xlit":"ápistos"},"G2165":{"lemma":"εὐφραίνω","translit":"euphraínō","kjv_def":"fare, make glad, be (make) merry, rejoice","strongs_def":" to put (middle voice or passively, be) in a good frame of mind, i.e. rejoice","derivation":"from G2095 (εὖ) and G5424 (φρήν);","pron":"yoo-frah'-ee-no","pos":"Verb","thayer":"<ol><li>to gladden, make joyful<ol type='a'><li>to be glad, to be merry, to rejoice</li><li>to rejoice in, be delighted with a thing</li></ol></li></ol>","xlit":"euphraínō"},"G1165":{"lemma":"δειγματίζω","translit":"deigmatízō","kjv_def":"make a shew","strongs_def":" to exhibit","derivation":"from G1164 (δεῖγμα);","pron":"digh-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to make an example of, to show as an example</li></ol>","xlit":"deigmatízō"},"G1056":{"translit":"Galilaía","lemma":"Γαλιλαία","kjv_def":"Galilee","strongs_def":" Galilæa (i.e. the heathen circle), a region of Palestine","derivation":"of Hebrew origin (H01551);","pron":"gal-il-ah'-yah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Galilee = \"Circuit\"</p><ol><li>the name of a region of northern Palestine, bounded on the north by Syria, on the west by Sidon, Tyre, Ptolemais and their territories and the promontory of Carmel, on the south by Samaria and on the east by the Jordan. It was divided into Upper Galilee and Lower Galilee.</li></ol>","xlit":"Galilaía"},"G3458":{"derivation":"probably ultimately from the base of G3433 (μόλις) (through the idea of hardship);","strongs_def":" a \"mill\", i.e. (by implication), a grinder (millstone)","kjv_def":"millstone","lemma":"μύλος","translit":"mýlos","pron":"moo'-los","pos":"Noun Masculine","thayer":"<ol><li>a mill stone<ol type='a'><li>a large mill consisted of two stones, an upper and an under one</li><li>the \"nether\" stone was stationary, but the upper one was turned by an ass</li></ol><li>a mill, the noise made by a mill</li></ol>","xlit":"mýlos"},"G2100":{"derivation":"from G2101 (εὐάρεστος);","strongs_def":" to gratify entirely","kjv_def":"please (well)","translit":"euarestéō","lemma":"εὐαρεστέω","pron":"yoo-ar-es-teh'-o","pos":"Verb","thayer":"<ol><li>to be well pleasing</li><li>to be well pleased with a thing</li></ol>","xlit":"euarestéō"},"G1268":{"kjv_def":"spread","translit":"dianémō","lemma":"διανέμω","derivation":"from G1223 (διά) and the base of G3551 (νόμος);","strongs_def":" to distribute, i.e. (of information) to disseminate","pron":"dee-an-em'-o","pos":"Verb","thayer":"<ol><li>to distribute, divide</li></ol>","xlit":"dianémō"},"G5131":{"kjv_def":"goat","translit":"trágos","lemma":"τράγος","derivation":"from the base of G5176 (τρώγω);","strongs_def":" a he-goat (as a gnawer)","pron":"trag'-os","pos":"Noun Masculine","thayer":"<ol><li>male goat</li></ol>","xlit":"trágos"},"G4931":{"strongs_def":" to complete entirely; generally, to execute (literally or figuratively)","derivation":"from G4862 (σύν) and G5055 (τελέω);","lemma":"συντελέω","translit":"synteléō","kjv_def":"end, finish, fulfil, make","pron":"soon-tel-eh'-o","pos":"Verb","thayer":"<ol><li>to end together or at the same time</li><li>to end completely<ol type='a'><li>bring to an end, finish, complete</li></ol><li>to accomplish, bring to fulfilment<ol type='a'><li>to come to pass</li></ol><li>to effect, make, (conclude)</li><li>to finish<ol type='a'><li>to make an end of</li><li>to bring to an end</li><li>destroy</li></ol></li></ol>","xlit":"synteléō"},"G1190":{"strongs_def":" a Derbæan or inhabitant of Derbe","derivation":"from G1191 (Δέρβη);","translit":"Derbaîos","lemma":"Δερβαῖος","kjv_def":"of Derbe","pron":"der-bah'-ee-os","pos":"Adjective","thayer":"<ol><li>a native of Derbe</li></ol>","xlit":"Derbaîos"},"G1891":{"strongs_def":" Epaphroditus, a Christian","derivation":"from G1909 (ἐπί) (in the sense of devoted to) and (Venus);","lemma":"Ἐπαφρόδιτος","translit":"Epaphróditos","kjv_def":"Epaphroditus","pron":"ep-af-rod'-ee-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Epaphroditus = \"lovely\"</p><ol><li>an associate with Paul in the ministry</li></ol>","xlit":"Epaphróditos"},"G5273":{"kjv_def":"hypocrite","translit":"hypokritḗs","lemma":"ὑποκριτής","derivation":"from G5271 (ὑποκρίνομαι);","strongs_def":" an actor under an assumed character (stage-player), i.e. (figuratively) a dissembler (\"hypocrite\"","pron":"hoop-ok-ree-tace'","pos":"Noun Masculine","thayer":"<ol><li>one who answers, an interpreter</li><li>an actor, stage player</li><li>a dissembler, pretender, hypocrite</li></ol>","xlit":"hypokritḗs"},"G3079":{"translit":"Lysías","lemma":"Λυσίας","kjv_def":"Lysias","strongs_def":" Lysias, a Roman","derivation":"of uncertain affinity;","pron":"loo-see'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lysias = \"releaser\"</p><ol><li>a tribune or chiliarch of the Roman cohort</li></ol>","xlit":"Lysías"},"G683":{"kjv_def":"cast away, put away (from), thrust away (from)","translit":"apōthéomai","lemma":"ἀπωθέομαι","derivation":"from G575 (ἀπό) and the middle voice of or (to shove);","strongs_def":" to push off, figuratively, to reject","pron":"ap-o-theh'-om-ahee","pos":"Verb","thayer":"<ol><li>to thrust away, push away, repel</li><li>to thrust away from one's self, to drive away from one's self<ol type='a'><li>repudiate, reject, refuse</li></ol></li></ol>","xlit":"apōthéomai"},"G5276":{"kjv_def":"winefat","translit":"hypolḗnion","lemma":"ὑπολήνιον","derivation":"neuter of a presumed compound of G5259 (ὑπό) and G3025 (ληνός);","strongs_def":" vessel or receptacle under the press, i.e. lower wine-vat","pron":"hoop-ol-ay'-nee-on","pos":"Noun Neuter","thayer":"<ol><li>a vessel placed under a press (and in the Orient usually sunk in the earth) to receive the expressed juice of the grapes, a pit</li></ol>","xlit":"hypolḗnion"},"G1170":{"derivation":"probably from the same as G1171 (δεινῶς) (through the idea of forgetting the name as fearful, i.e. strange);","strongs_def":" so and so (when the person is not specified)","kjv_def":"such a man","lemma":"δεῖνα","translit":"deîna","pron":"di'-nah","pos":"Noun","thayer":"<ol><li>such a one, a certain one, i.e. one whose name I cannot call on the instant, or whose name it is of no importance to mention</li></ol>","xlit":"deîna"},"G5203":{"kjv_def":"have the dropsy","translit":"hydrōpikós","lemma":"ὑδρωπικός","derivation":"from a compound of G5204 (ὕδωρ) and a derivative of G3700 (ὀπτάνομαι) (as if looking watery);","strongs_def":" to be \"dropsical\"","pron":"hoo-dro-pik-os'","pos":"Adjective","thayer":"<ol><li>dropsical, suffering from dropsy</li></ol>","xlit":"hydrōpikós"},"G3407":{"derivation":"from G3408 (μισθός);","strongs_def":" a wage-earner","kjv_def":"hired servant","lemma":"μίσθιος","translit":"místhios","pron":"mis'-thee-os","pos":"Adjective","thayer":"<ol><li>employed for hire, hired</li></ol>","xlit":"místhios"},"G3332":{"strongs_def":" to betake oneself, i.e. remove (locally)","derivation":"from G3326 (μετά) and G142 (αἴρω);","translit":"metaírō","lemma":"μεταίρω","kjv_def":"depart","pron":"met-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to lift up and remove from one place to another, to transfer</li><li>to go away, depart</li></ol>","xlit":"metaírō"},"G4395":{"derivation":"from G4396 (προφήτης);","strongs_def":" to foretell events, divine, speak under inspiration, exercise the prophetic office","kjv_def":"prophesy","translit":"prophēteúō","lemma":"προφητεύω","pron":"prof-ate-yoo'-o","pos":"Verb","thayer":"<ol><li>to prophesy, to be a prophet, speak forth by divine inspirations, to predict<ol type='a'><li>to prophesy</li><li>with the idea of foretelling future events pertaining especially to the kingdom of God</li><li>to utter forth, declare, a thing which can only be known by divine revelation</li><li>to break forth under sudden impulse in lofty discourse or praise of the divine counsels<ol><li>under like prompting, to teach, refute, reprove, admonish, comfort others</li></ol><li>to act as a prophet, discharge the prophetic office</li></ol></li></ol>","xlit":"prophēteúō"},"G769":{"strongs_def":" feebleness (of mind or body); by implication, malady; morally, frailty","derivation":"from G772 (ἀσθενής);","translit":"asthéneia","lemma":"ἀσθένεια","kjv_def":"disease, infirmity, sickness, weakness","pron":"as-then'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>want of strength, weakness, infirmity<ol type='a'><li>of the body<ol><li>its native weakness and frailty</li><li>feebleness of health or sickness</li></ol><li>of the soul<ol><li>want of strength and capacity requisite<ol type='a'><li>to understand a thing</li><li>to do things great and glorious</li><li>to restrain corrupt desires</li><li>to bear trials and troubles</li></ol></li></ol></li></ol></li></ol>","xlit":"asthéneia"},"G378":{"strongs_def":" to complete; by implication, to occupy, supply; figuratively, to accomplish (by coincidence ot obedience)","derivation":"from G303 (ἀνά) and G4137 (πληρόω);","translit":"anaplēróō","lemma":"ἀναπληρόω","kjv_def":"fill up, fulfill, occupy, supply","pron":"an-ap-lay-ro'-o","pos":"Verb","thayer":"<ol><li>to fill up, make full, e.g. a ditch</li><li>to supply</li></ol>","xlit":"anaplēróō"},"G2558":{"strongs_def":" to maltreat","derivation":"from a presumed compound of G2556 (κακός) and G2192 (ἔχω);","lemma":"κακουχέω","translit":"kakouchéō","kjv_def":"which suffer adversity, torment","pron":"kak-oo-kheh'-o","pos":"Verb","thayer":"<ol><li>to treat ill, oppress, plague</li></ol>","xlit":"kakouchéō"},"G2362":{"kjv_def":"seat, throne","translit":"thrónos","lemma":"θρόνος","derivation":"from (to sit);","strongs_def":" a stately seat (\"throne\"); by implication, power or (concretely) a potentate","pron":"thron'-os","pos":"Noun Masculine","thayer":"<ol><li>a throne seat<ol type='a'><li>a chair of state having a footstool</li><li>assigned in the NT to kings, hence, kingly power or royalty<ol><li>metaphorically to God, the governor of the world</li><li>to the Messiah, Christ, the partner and assistant in the divine administration<ol type='a'><li>hence divine power belonging to Christ</li></ol><li>to judges, i.e. tribunal or bench</li><li>to elders</li></ol></li></ol></li></ol>","xlit":"thrónos"},"G1358":{"strongs_def":" to penetrate burglariously","derivation":"from G1223 (διά) and G3736 (ὀρύσσω);","lemma":"διορύσσω","translit":"diorýssō","kjv_def":"break through (up)","pron":"dee-or-oos'-so","pos":"Verb","thayer":"<ol><li>to dig through: a house</li></ol>","xlit":"diorýssō"},"G1663":{"derivation":"of Hebrew origin (H0461);","strongs_def":" Eliezer, an Israelite","kjv_def":"Eliezer","lemma":"Ἐλιέζερ","translit":"Eliézer","pron":"el-ee-ed'-zer","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eliezer = \"God is his help\"</p><ol><li>the son of Jorim, in the genealogy of Christ. <a class='bible' href='#b42.3.29'>Luk 3:29</a></li></ol>","xlit":"Eliézer"},"G2898":{"kjv_def":"Calvary, skull","lemma":"κρανίον","translit":"kraníon","derivation":"diminutive of a derivative of the base of G2768 (κέρας);","strongs_def":" a skull (\"cranium\")","pron":"kran-ee'-on","pos":"Noun Neuter","thayer":"<ol><li>a skull</li></ol>","xlit":"kraníon"},"G659":{"kjv_def":"cast off, lay apart (aside, down), put away (off)","lemma":"ἀποτίθημι","translit":"apotíthēmi","derivation":"from G575 (ἀπό) and G5087 (τίθημι);","strongs_def":" to put away (literally or figuratively)","pron":"ap-ot-eeth'-ay-mee","pos":"Verb","thayer":"<ol><li>to put off or aside or away</li></ol>","xlit":"apotíthēmi"},"G1333":{"kjv_def":"two years","lemma":"διετία","translit":"dietía","derivation":"from G1332 (διετής);","strongs_def":" a space of two years (biennium)","pron":"dee-et-ee'-a","pos":"Noun Feminine","thayer":"<ol><li>the space of two years</li></ol>","xlit":"dietía"},"G3823":{"derivation":"from (to vibrate;","strongs_def":" another form for G906 (βάλλω)); wrestling","kjv_def":"+ wrestle","translit":"pálē","lemma":"πάλη","pron":"pal'-ay","pos":"Noun Feminine","thayer":"<ol><li>wrestling (a contest between two in which each endeavours to throw the other, and which is decided when the victor is able to hold his opponent down with his hand upon his neck)<ol type='a'><li>the term is transferred to the Christian's struggle with the power of evil</li></ol></li></ol>","xlit":"pálē"},"G3649":{"translit":"ololýzō","lemma":"ὀλολύζω","kjv_def":"howl","strongs_def":" to \"howl\" or \"halloo\", i.e. shriek","derivation":"a reduplicated primary verb;","pron":"ol-ol-odd'-zo","pos":"Verb","thayer":"<ol><li>to howl, wail, lament<ol type='a'><li>of a loud cry whether for joy or of grief</li></ol></li></ol>","xlit":"ololýzō"},"G756":{"kjv_def":"(rehearse from the) begin(-ning)","translit":"árchomai","lemma":"ἄρχομαι","derivation":"middle voice of G757 (ἄρχω) (through the implication, of precedence);","strongs_def":" to commence (in order of time)","pron":"ar'-khom-ahee","pos":"Verb","thayer":"<ol><li>to be the first to do (anything), to begin</li><li>to be chief, leader, ruler</li><li>to begin, make a beginning</li></ol>","xlit":"árchomai"},"G103":{"strongs_def":" to sing","derivation":"a primary verb;","translit":"áidō","lemma":"ᾄδω","kjv_def":"sing","pron":"ad'-o","pos":"Verb","thayer":"<ol><li>to the praise of anyone, to sing</li></ol>","xlit":"áidō"},"G5145":{"strongs_def":" three hundred","derivation":"plural from G5140 (τρεῖς) and G1540 (ἑκατόν);","translit":"triakósioi","lemma":"τριακόσιοι","kjv_def":"three hundred","pron":"tree-ak-os'-ee-oy","pos":"Adjective","thayer":"<ol><li>three hundred</li></ol>","xlit":"triakósioi"},"G5179":{"derivation":"from G5180 (τύπτω);","strongs_def":" a die (as struck), i.e. (by implication) a stamp or scar; by analogy, a shape, i.e. a statue, (figuratively) style or resemblance; specially, a sampler (\"type\"), i.e. a model (for imitation) or instance (for warning)","kjv_def":"en-(ex-)ample, fashion, figure, form, manner, pattern, print","lemma":"τύπος","translit":"týpos","pron":"too'-pos","pos":"Noun Masculine","thayer":"<ol><li>the mark of a stroke or blow, print</li><li>a figure formed by a blow or impression<ol type='a'><li>of a figure or image</li><li>of the image of the gods</li></ol><li>form<ol type='a'><li>the teaching which embodies the sum and substance of religion and represents it to the mind, manner of writing, the contents and form of a letter</li></ol><li>an example<ol type='a'><li>in the technical sense, the pattern in conformity to which a thing must be made</li><li>in an ethical sense, a dissuasive example, a pattern of warning<ol><li>of ruinous events which serve as admonitions or warnings to others</li></ol><li>an example to be imitated<ol><li>of men worthy of imitation</li></ol><li>in a doctrinal sense<ol><li>of a type, i.e. a person or thing prefiguring a future (Messianic) person or thing</li></ol></li></ol></li></ol>","xlit":"týpos"},"G2855":{"kjv_def":"(money-)changer","translit":"kollybistḗs","lemma":"κολλυβιστής","derivation":"from a presumed derivative of (a small coin;","strongs_def":" probably akin to G2854 (κολλούριον)); a coin-dealer","pron":"kol-loo-bis-tace'","pos":"Noun Masculine","thayer":"<ol><li>a money-changer, banker</li></ol>","xlit":"kollybistḗs"},"G4078":{"strongs_def":" to fix (\"peg\"), i.e. (specially) to set up (a tent)","derivation":"a prolonged form of a primary verb (which in its simpler form occurs only as an alternate in certain tenses);","lemma":"πήγνυμι","translit":"pḗgnymi","kjv_def":"pitch","pron":"payg'-noo-mee","pos":"Verb","thayer":"<ol><li>to make fast, to fix</li><li>to fasten together, to build by fastening together</li></ol>","xlit":"pḗgnymi"},"G3470":{"kjv_def":"blemish","translit":"mōmos","lemma":"μῶμος","derivation":"perhaps from G3201 (μέμφομαι);","strongs_def":" a flaw or blot, i.e. (figuratively) disgraceful person","pron":"mo'-mos","pos":"Noun Masculine","thayer":"<ol><li>blemish, blot, disgrace<ol type='a'><li>censure</li><li>insult<ol><li>of men who are a disgrace to society</li></ol></li></ol></li></ol>","xlit":"mōmos"},"G643":{"lemma":"ἀποσκευάζω","translit":"aposkeuázō","kjv_def":"take up… carriages","strongs_def":" to pack up (one's) baggage","derivation":"from G575 (ἀπό) and a derivative of G4632 (σκεῦος);","pron":"ap-osk-yoo-ad'-zo","pos":"Verb","thayer":"<ol><li>to carry off goods and chattels</li><li>to pack up and carry off</li><li>to carry off one's personal property or provide for its carrying away</li></ol>","xlit":"aposkeuázō"},"G210":{"derivation":"from G1 (Α) (as a negative particle) and G1635 (ἑκών);","strongs_def":" unwilling","kjv_def":"against the will","lemma":"ἄκων","translit":"ákōn","pron":"ak'-ohn","pos":"Adjective","thayer":"<ol><li>not of one's own will, unwillingly, against the will</li></ol>","xlit":"ákōn"},"G2382":{"lemma":"θώραξ","translit":"thṓrax","kjv_def":"breast-plate","strongs_def":" the chest (\"thorax\"), i.e. (by implication) a corslet","derivation":"of uncertain affinity;","pron":"tho'-rax","pos":"Noun Masculine","thayer":"<ol><li>the breast, the part of the body from the neck to the navel, where the ribs end</li><li>a breastplate or corset consisting of two parts and protecting the body on both sides from the neck to the middle</li></ol>","xlit":"thṓrax"},"G737":{"derivation":"adverb from a derivative of G142 (αἴρω) (compare G740 (ἄρτος)) through the idea of suspension;","strongs_def":" just now","kjv_def":"this day (hour), hence(-forth), here(-after), hither(-to), (even) now, (this) present","translit":"árti","lemma":"ἄρτι","pron":"ar'-tee","pos":"Adverb","thayer":"<ol><li>just now, this moment</li><li>now at this time, at this very time, this moment</li></ol>","xlit":"árti"},"G2308":{"strongs_def":" determination (properly, the act), i.e. option","derivation":"from G2309 (θέλω);","lemma":"θέλησις","translit":"thélēsis","kjv_def":"will","pron":"thel'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>a willing will</li></ol>","xlit":"thélēsis"},"G1207":{"kjv_def":"second … after the first","translit":"deuteróprōtos","lemma":"δευτερόπρωτος","derivation":"from G1208 (δεύτερος) and G4413 (πρῶτος);","strongs_def":" second-first, i.e. (specially) a designation of the Sabbath immediately after the Paschal week (being the second after Passover day, and the first of the seven Sabbaths intervening before Pentecost)","pron":"dyoo-ter-op'-ro-tos","pos":"Adjective","thayer":"<ol><li>second-first</li><li>the second of the first Sabbaths after the feast of the Passover</li></ol>","xlit":"deuteróprōtos"},"G1804":{"lemma":"ἐξαγγέλλω","translit":"exangéllō","kjv_def":"shew forth","strongs_def":" to publish, i.e. celebrate","derivation":"from G1537 (ἐκ) and the base of G32 (ἄγγελος);","pron":"ex-ang-el'-lo","pos":"Verb","thayer":"<ol><li>to tell out or forth</li><li>to declare abroad, divulge, publish</li><li>to make known by praising or proclaiming, to celebrate</li></ol>","xlit":"exangéllō"},"G993":{"kjv_def":"Boanerges","translit":"Boanergés","lemma":"Βοανεργές","derivation":"of Chaldee origin (H01123 and H07266);","strongs_def":" sons of commotion; Boanerges, an epithet of two of the apostles","pron":"bo-an-erg-es'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Boanerges = \"sons of thunder\"</p><ol><li>a nickname given to James and John, the sons of Zebedee, by the Lord. The name seems to denote fiery and destructive zeal that may be likened to a thunder storm.</li></ol>","xlit":"Boanergés"},"G950":{"lemma":"βεβαιόω","translit":"bebaióō","kjv_def":"confirm, (e-)stablish","strongs_def":" to stabilitate (figuratively)","derivation":"from G949 (βέβαιος);","pron":"beb-ah-yo'-o","pos":"Verb","thayer":"<ol><li>to make firm, establish, confirm, make sure</li></ol>","xlit":"bebaióō"},"G2923":{"derivation":"from G2919 (κρίνω);","strongs_def":" a judge (genitive case or specially)","kjv_def":"judge","lemma":"κριτής","translit":"kritḗs","pron":"kree-tace'","pos":"Noun Masculine","thayer":"<ol><li>one who passes or arrogates to himself, judgment on anything<ol type='a'><li>an arbiter</li><li>of a Roman procurator administering justice</li><li>of God passing judgment on men</li><li>of the leaders or rulers of the Israelites</li></ol></li></ol>","xlit":"kritḗs"},"G969":{"strongs_def":" a \"beryl\"","derivation":"of uncertain derivation;","lemma":"βήρυλλος","translit":"bḗryllos","kjv_def":"beryl","pron":"bay'-rool-los","pos":"Noun","thayer":"<ol><li>beryl, a precious stone of a pale green colour</li></ol>","xlit":"bḗryllos"},"G3812":{"kjv_def":"of a child","lemma":"παιδιόθεν","translit":"paidióthen","derivation":"adverb (of source) from G3813 (παιδίον);","strongs_def":" from infancy","pron":"pahee-dee-oth'-en","pos":"Adverb","thayer":"<ol><li>from childhood, from a child</li></ol>","xlit":"paidióthen"},"G2632":{"kjv_def":"condemn, damn","translit":"katakrínō","lemma":"κατακρίνω","derivation":"from G2596 (κατά) and G2919 (κρίνω);","strongs_def":" to judge against, i.e. sentence","pron":"kat-ak-ree'-no","pos":"Verb","thayer":"<ol><li>to give judgment against, to judge worthy of punishment<ol type='a'><li>to condemn</li><li>by one's good example to render another's wickedness themore evident and censurable</li></ol></li></ol>","xlit":"katakrínō"},"G3794":{"kjv_def":"stronghold","lemma":"ὀχύρωμα","translit":"ochýrōma","derivation":"from a remote derivative of G2192 (ἔχω) (meaning to fortify, through the idea of holding safely);","strongs_def":" a castle (figuratively, argument)","pron":"okh-oo'-ro-mah","pos":"Noun Neuter","thayer":"<ol><li>a castle, stronghold, fortress, fastness</li><li>anything on which one relies<ol type='a'><li>of the arguments and reasonings by which a disputant endeavours to fortify his opinion and defend it against his opponent</li></ol></li></ol>","xlit":"ochýrōma"},"G20":{"strongs_def":" exultation; specially, welcome","derivation":"from G21 (ἀγαλλιάω);","lemma":"ἀγαλλίασις","translit":"agallíasis","kjv_def":"gladness, (exceeding) joy","pron":"ag-al-lee'-as-is","pos":"Noun Feminine","thayer":"<ol><li>exultation, extreme joy, gladness</li></ol>","xlit":"agallíasis"},"G1120":{"strongs_def":" to fall on the knee","derivation":"from a compound of G1119 (γόνυ) and the alternate of G4098 (πίπτω);","translit":"gonypetéō","lemma":"γονυπετέω","kjv_def":"bow the knee, kneel down","pron":"gon-oo-pet-eh'-o","pos":"Verb","thayer":"<ol><li>to fall on the knees, the act of imploring aid, and of expressing reverence and honour</li></ol>","xlit":"gonypetéō"},"G4040":{"strongs_def":" housed around, i.e. neighboring (used elliptically as a noun)","derivation":"from G4012 (περί) and G3624 (οἶκος);","lemma":"περίοικος","translit":"períoikos","kjv_def":"neighbour","pron":"per-ee'-oy-kos","pos":"Adjective","thayer":"<ol><li>dwelling around, a neighbour</li></ol>","xlit":"períoikos"},"G5389":{"lemma":"φιλοτιμέομαι","translit":"philotiméomai","kjv_def":"labour, strive, study","strongs_def":" to be fond of honor, i.e. emulous (eager or earnest to do something)","derivation":"middle voice from a compound of G5384 (φίλος) and G5092 (τιμή);","pron":"fil-ot-im-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to be fond of honour<ol type='a'><li>to be actuated by love of honour</li><li>from a love of honour to strive to bring something to pass</li></ol><li>to be ambitious<ol type='a'><li>to strive earnestly, make it one's aim</li></ol></li></ol>","xlit":"philotiméomai"},"G2762":{"lemma":"κεραία","translit":"keraía","kjv_def":"tittle","strongs_def":" something horn-like, i.e. (specially) the apex of a Hebrew letter (figuratively, the least particle)","derivation":"feminine of a presumed derivative of the base of G2768 (κέρας);","pron":"ker-ah'-yah","pos":"Noun Feminine","thayer":"<ol><li>a little horn</li><li>extremity, apex, point<ol type='a'><li>used by grammarians of the accents and diacritical points. Jesus used it of the little lines or projections, by which the Hebrew letters in other respects similar differ from one another; the meaning is, \"not even the minutest part of the law shall perish\" .</li></ol></li></ol>","xlit":"keraía"},"G2730":{"translit":"katoikéō","lemma":"κατοικέω","kjv_def":"dwell(-er), inhabitant(-ter)","strongs_def":" to house permanently, i.e. reside (literally or figuratively)","derivation":"from G2596 (κατά) and G3611 (οἰκέω);","pron":"kat-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell, settle<ol type='a'><li>metaphorically divine powers, influences, etc., are said to dwell in his soul, to pervade, prompt, govern it</li></ol><li>to dwell in, inhabit<ol type='a'><li>God is said to dwell in the temple, i.e. to be always present for worshippers</li></ol></li></ol>","xlit":"katoikéō"},"G3661":{"kjv_def":"with one accord (mind)","lemma":"ὁμοθυμαδόν","translit":"homothymadón","derivation":"adverb from a compound of the base of G3674 (ὁμοῦ) and G2372 (θυμός);","strongs_def":" unanimously","pron":"hom-oth-oo-mad-on'","pos":"Adverb","thayer":"<ol><li>with one mind, with one accord, with one passion</li></ol>","xlit":"homothymadón"},"G28":{"derivation":"of Hebrew origin (H01904);","strongs_def":" Hagar, the concubine of Abraham","kjv_def":"Hagar","translit":"Ágar","lemma":"Ἄγαρ","pron":"ag'-ar","pos":"Proper Name Feminine","thayer":"<strong>Thayer Definition</strong>: Hagar = \"flight\"</p><ol><li>Abraham's concubine and mother to Ishmael</li></ol>","xlit":"Ágar"},"G1736":{"derivation":"from a compound of G1722 (ἐν) and G1218 (δῆμος);","strongs_def":" to be in one's own country, i.e. home (figuratively)","kjv_def":"be at home (present)","translit":"endēméō","lemma":"ἐνδημέω","pron":"en-day-meh'-o","pos":"Verb","thayer":"<ol><li>to be among one's own people, dwell in one's own country, stay at home</li></ol>","xlit":"endēméō"},"G1791":{"derivation":"from G1788 (ἐντρέπω);","strongs_def":" confusion","kjv_def":"shame","lemma":"ἐντροπή","translit":"entropḗ","pron":"en-trop-ay'","pos":"Noun Feminine","thayer":"<ol><li>shame</li><li>respect, reverence</li></ol>","xlit":"entropḗ"},"G4239":{"derivation":"apparently a primary word;","strongs_def":" mild, i.e. (by implication) humble","kjv_def":"meek","lemma":"πραΰς","translit":"praÿs","pron":"prah-ooce'","pos":"Adjective","thayer":"<ol><li>mildness of disposition, gentleness of spirit, meekness</li></ol>","xlit":"praÿs"},"G1426":{"strongs_def":" defamation","derivation":"from a compound of G1418 (δυσ-) and G5345 (φήμη);","lemma":"δυσφημία","translit":"dysphēmía","kjv_def":"evil report","pron":"doos-fay-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the condition of one who is defamed<ol type='a'><li>ill-repute, and the action of one who uses disgraceful language</li></ol></li></ol>","xlit":"dysphēmía"},"G833":{"kjv_def":"court, (sheep-)fold, hall, palace","translit":"aulḗ","lemma":"αὐλή","derivation":"from the same as G109 (ἀήρ);","strongs_def":" a yard (as open to the wind); by implication, a mansion","pron":"ow-lay'","pos":"Noun Feminine","thayer":"<ol><li>among the Greeks in Homer's time, an uncovered space around the house, enclosed by a wall, in which the stables stood, hence among the Orientals that roofless enclosure by a wall, in the open country in which the flocks were herded at night, a sheepfold</li><li>the uncovered courtyard of the house. In the O.T. particularly of the courts of the tabernacle and of the temple in Jerusalem. The dwellings of the higher classes usually had two, one exterior, between the door and the street; the other interior, surrounded by the buildings of the dwelling itself. The latter is mentioned <a class='bible' href='#b40.26.69'>Mat 26:69</a>.</li><li>the house itself, a palace</li></ol>","xlit":"aulḗ"},"G4997":{"kjv_def":"soberness, sobriety","translit":"sōphrosýnē","lemma":"σωφροσύνη","derivation":"from G4998 (σώφρων);","strongs_def":" soundness of mind, i.e. (literally) sanity or (figuratively) self-control","pron":"so-fros-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>soundness of mind</li><li>self-control, sobriety</li></ol>","xlit":"sōphrosýnē"},"G201":{"derivation":"from G202 (ἀκροατής);","strongs_def":" an audience-room","kjv_def":"place of hearing","lemma":"ἀκροατήριον","translit":"akroatḗrion","pron":"ak-ro-at-ay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a place set aside for hearing and deciding cases</li></ol>","xlit":"akroatḗrion"},"G3908":{"strongs_def":" to place alongside, i.e. present (food, truth); by implication, to deposit (as a trust or for protection)","derivation":"from G3844 (παρά) and G5087 (τίθημι);","translit":"paratíthēmi","lemma":"παρατίθημι","kjv_def":"allege, commend, commit (the keeping of), put forth, set before","pron":"par-at-ith'-ay-mee","pos":"Verb","thayer":"<ol><li>to place beside or near or set before<ol type='a'><li>food, i.e. food placed on a table</li><li>to set before (one) in teaching</li><li>to set forth (from one's self), to explain</li></ol><li>to place down (from one's self or for one's self) with any one<ol type='a'><li>to deposit</li><li>to intrust, commit to one's charge</li></ol></li></ol>","xlit":"paratíthēmi"},"G1336":{"kjv_def":"+ continually, for ever","translit":"diēnekḗs","lemma":"διηνεκής","derivation":"neuter of a compound of G1223 (διά) and a derivative of an alternate of G5342 (φέρω);","strongs_def":" carried through, i.e. (adverbially with G1519 (εἰς) and G3588 (ὁ) prefixed) perpetually","pron":"dee-ay-nek-es'","pos":"Adjective","thayer":"<ol><li>continuously, continuous</li></ol>","xlit":"diēnekḗs"},"G4436":{"strongs_def":" a Python, i.e. (by analogy, with the supposed diviner there) inspiration (soothsaying)","derivation":"from (the name of the region where Delphi, the seat of the famous oracle, was located);","lemma":"Πύθων","translit":"Pýthōn","kjv_def":" divination","pron":"poo'-thone","pos":"Noun Masculine","thayer":"<ol><li>in Greek mythology the name of the Pythian serpent or dragon that dwelt in the region of Pytho at the foot of Parnassus in Phocis, and was said to have guarded the oracle at Delphi and been slain by Apollo</li><li>a spirit of divination</li></ol>","xlit":"Pýthōn"},"G5565":{"derivation":"adverb from G5561 (χώρα);","strongs_def":" at a space, i.e. separately or apart from (often as preposition)","kjv_def":"beside, by itself, without","translit":"chōrís","lemma":"χωρίς","pron":"kho-rece'","pos":"Adverb","thayer":"<ol><li>separate, apart<ol type='a'><li>without any</li><li>besides</li></ol></li></ol>","xlit":"chōrís"},"G3884":{"kjv_def":"beguile, deceive","lemma":"παραλογίζομαι","translit":"paralogízomai","derivation":"from G3844 (παρά) and G3049 (λογίζομαι);","strongs_def":" to misreckon, i.e. delude","pron":"par-al-og-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to reckon wrong, miscount</li><li>to cheat by false reckoning<ol type='a'><li>to deceive by false reasoning</li></ol><li>to deceive, delude, circumvent</li></ol>","xlit":"paralogízomai"},"G757":{"derivation":"a primary verb;","strongs_def":" to be first (in political rank or power)","kjv_def":"reign (rule) over","lemma":"ἄρχω","translit":"árchō","pron":"ar'-kho","pos":"Verb","thayer":"<ol><li>to be chief, to lead, to rule</li></ol>","xlit":"árchō"},"G2844":{"strongs_def":" a sharer, i.e. associate","derivation":"from G2839 (κοινός);","translit":"koinōnós","lemma":"κοινωνός","kjv_def":"companion, X fellowship, partaker, partner","pron":"koy-no-nos'","pos":"Noun Masculine","thayer":"<ol><li>a partner, associate, comrade, companion</li><li>a partner, sharer, in anything<ol type='a'><li>of the altar in Jerusalem on which the sacrifices are offered<ol><li>sharing in the worship of the Jews</li></ol><li>partakers of (or with) demons<ol><li>brought into fellowship with them, because they are the authors of heathen worship</li></ol></li></ol></li></ol>","xlit":"koinōnós"},"G3816":{"derivation":"perhaps from G3817 (παίω);","strongs_def":" a boy (as often beaten with impunity), or (by analogy), a girl, and (genitive case) a child; specially, a slave or servant (especially a minister to a king; and by eminence to God)","kjv_def":"child, maid(-en), (man) servant, son, young man","lemma":"παῖς","translit":"paîs","pron":"paheece","pos":"Noun","thayer":"<ol><li>a child, boy or girl<ol type='a'><li>infants, children</li></ol><li>servant, slave<ol type='a'><li>an attendant, servant, spec. a king's attendant, minister</li></ol></li></ol>","xlit":"paîs"},"G38":{"translit":"hagiasmós","lemma":"ἁγιασμός","kjv_def":"holiness, sanctification","strongs_def":" properly, purification, i.e. (the state) purity; concretely (by Hebraism) a purifier","derivation":"from G37 (ἁγιάζω);","pron":"hag-ee-as-mos'","pos":"Noun Masculine","thayer":"<ol><li>consecration, purification</li><li>the effect of consecration<ol type='a'><li>sanctification of heart and life</li></ol></li></ol>","xlit":"hagiasmós"},"G3012":{"kjv_def":"towel","lemma":"λέντιον","translit":"léntion","derivation":"of Latin origin;","strongs_def":" a \"linen\" cloth, i.e. apron","pron":"len'-tee-on","pos":"Noun Neuter","thayer":"<ol><li>a linen cloth, towel<ol type='a'><li>of the towel or apron with which servants put on when about to work</li></ol></li></ol>","xlit":"léntion"},"G2865":{"lemma":"κομίζω","translit":"komízō","kjv_def":"bring, receive","strongs_def":" properly, to provide for, i.e. (by implication) to carry off (as if from harm; genitive case obtain)","derivation":"from a primary (to tend, i.e. take care of);","pron":"kom-id'-zo","pos":"Verb","thayer":"<ol><li>to care for, take care of, provide for</li><li>to take up or carry away in order to care for and preserve</li><li>to carry away, bear off</li><li>to carry, bear, bring to, to carry away for one's self, to carry off what is one's own, to bring back<ol type='a'><li>to receive, obtain: the promised blessing</li><li>to receive what was previously one's own, to get back, receive back, recover</li></ol></li></ol>","xlit":"komízō"},"G2142":{"lemma":"εὐπορία","translit":"euporía","kjv_def":"wealth","strongs_def":" pecuniary resources","derivation":"from the same as G2141 (εὐπορέω);","pron":"yoo-por-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>riches, means, wealth</li></ol>","xlit":"euporía"},"G3072":{"derivation":"adverb from a derivative of G3071 (Λυκαονία);","strongs_def":" Lycaonistically, i.e. in the language of the Lycaonians","kjv_def":"in the speech of Lycaonia","lemma":"Λυκαονιστί","translit":"Lykaonistí","pron":"loo-kah-on-is-tee'","pos":"Adverb","thayer":"<ol><li>in the speech or tongue of the Lycaonia</li></ol>","xlit":"Lykaonistí"},"G4816":{"strongs_def":" to collect","derivation":"from G4862 (σύν) and G3004 (λέγω) in its original sense;","translit":"syllégō","lemma":"συλλέγω","kjv_def":"gather (together, up)","pron":"sool-leg'-o","pos":"Verb","thayer":"<ol><li>to gather up</li><li>to collect in order to carry off</li></ol>","xlit":"syllégō"},"G815":{"lemma":"ἄτεκνος","translit":"áteknos","kjv_def":"childless, without children","strongs_def":" childless","derivation":"from G1 (Α) (as a negative particle) and G5043 (τέκνον);","pron":"at'-ek-nos","pos":"Adjective","thayer":"<ol><li>without offspring, childless</li></ol>","xlit":"áteknos"},"G2688":{"kjv_def":"behaviour","translit":"katástēma","lemma":"κατάστημα","derivation":"from G2525 (καθίστημι);","strongs_def":" properly, a position or condition, i.e. (subjectively) demeanor","pron":"kat-as'-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>demeanour, deportment, bearing</li></ol>","xlit":"katástēma"},"G97":{"translit":"ádolos","lemma":"ἄδολος","kjv_def":"sincere","strongs_def":" and G1388 (δόλος); undeceitful, i.e. (figuratively) unadulterated","derivation":"from G1 (Α) (as a negative particle);","pron":"ad'-ol-os","pos":"Adjective","thayer":"<ol><li>guileless<ol type='a'><li>in things: unmixed, unadulterated, pure</li><li>in persons: without dishonest intent, guileless</li></ol></li></ol>","xlit":"ádolos"},"G1925":{"kjv_def":"shew","translit":"epideíknymi","lemma":"ἐπιδείκνυμι","derivation":"from G1909 (ἐπί) and G1166 (δεικνύω);","strongs_def":" to exhibit (physically or mentally)","pron":"ep-ee-dike'-noo-mee","pos":"Verb","thayer":"<ol><li>to exhibit, show<ol type='a'><li>to bring forth to view, to show<ol><li>furnish to be looked at, produce what may looked at</li><li>to display something belonging to one's self</li></ol><li>to prove, demonstrate, set forth to be known and acknowledged</li></ol></li></ol>","xlit":"epideíknymi"},"G3584":{"derivation":"from the base of G3582 (ξέστης) (through the idea of scorching);","strongs_def":" arid; by implication, shrunken, earth (as opposed to water)","kjv_def":"dry land, withered","translit":"xērós","lemma":"ξηρός","pron":"xay-ros'","pos":"Adjective","thayer":"<ol><li>dry<ol type='a'><li>of members of the body deprived of their natural juices, shrunk, wasted, withered</li><li>of the land in distinction from the water</li></ol></li></ol>","xlit":"xērós"},"G3000":{"translit":"latreúō","lemma":"λατρεύω","kjv_def":"serve, do the service, worship(-per)","strongs_def":" to minister (to God), i.e. render religious homage","derivation":"from (a hired menial);","pron":"lat-ryoo'-o","pos":"Verb","thayer":"<ol><li>to serve for hire</li><li>to serve, minister to, either to the gods or men and used alike of slaves and freemen<ol type='a'><li>in the NT, to render religious service or homage, to worship</li><li>to perform sacred services, to offer gifts, to worship God in the observance of the rites instituted for his worship<ol><li>of priests, to officiate, to discharge the sacred office</li></ol></li></ol></li></ol>","xlit":"latreúō"},"G3129":{"strongs_def":" to learn (in any way)","derivation":"prolongation from a primary verb, another form of which, , is used as an alternate in certain tenses;","translit":"manthánō","lemma":"μανθάνω","kjv_def":"learn, understand","pron":"man-than'-o","pos":"Verb","thayer":"<ol><li>to learn, be appraised<ol type='a'><li>to increase one's knowledge, to be increased in knowledge</li><li>to hear, be informed</li><li>to learn by use and practice<ol><li>to be in the habit of, accustomed to</li></ol></li></ol></li></ol>","xlit":"manthánō"},"G3320":{"derivation":"from G3319 (μέσος) and G5109 (τοῖχος);","strongs_def":" a partition (figuratively)","kjv_def":"middle wall","lemma":"μεσότοιχον","translit":"mesótoichon","pron":"mes-ot'-oy-khon","pos":"Noun Neuter","thayer":"<ol><li>a partition wall</li></ol>","xlit":"mesótoichon"},"G2791":{"derivation":"probably of foreign origin;","strongs_def":" Cilicia, a region of Asia Minor","kjv_def":"Cilicia","translit":"Kilikía","lemma":"Κιλικία","pron":"kil-ik-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cilicia = \"the land of Celix\"</p><ol><li>a maritime province in the southeast of Asia Minor, boarding on Pamphylia in the west, Lycaonia and Cappadocia in the north and Syria in the east. Its capital, Tarsus, was the birth place of Paul</li></ol>","xlit":"Kilikía"},"G3348":{"derivation":"from G3326 (μετά) and G2192 (ἔχω);","strongs_def":" to share or participate; by implication, belong to, eat (or drink)","kjv_def":"be partaker, pertain, take part, use","lemma":"μετέχω","translit":"metéchō","pron":"met-ekh'-o","pos":"Verb","thayer":"<ol><li>to be or become partaker</li><li>to partake</li></ol>","xlit":"metéchō"},"G5151":{"strongs_def":" three times","derivation":"adverb from G5140 (τρεῖς);","translit":"trís","lemma":"τρίς","kjv_def":"three times, thrice","pron":"trece","pos":"Adverb","thayer":"<ol><li>thrice</li></ol>","xlit":"trís"},"G1303":{"strongs_def":" to put apart, i.e. (figuratively) dispose (by assignment, compact, or bequest)","derivation":"middle voice from G1223 (διά) and G5087 (τίθημι);","lemma":"διατίθεμαι","translit":"diatíthemai","kjv_def":"appoint, make, testator","pron":"dee-at-ith'-em-ahee","pos":"Verb","thayer":"<ol><li>to arrange, dispose of, one's own affairs<ol type='a'><li>of something that belongs to one</li><li>to dispose of by will, make a testament</li></ol><li>to make a covenant, enter into a covenant, with one</li></ol>","xlit":"diatíthemai"},"G2648":{"strongs_def":" to learn thoroughly, i.e. (by implication) to note carefully","derivation":"from G2596 (κατά) and G3129 (μανθάνω);","translit":"katamanthánō","lemma":"καταμανθάνω","kjv_def":"consider","pron":"kat-am-an-than'-o","pos":"Verb","thayer":"<ol><li>to learn thoroughly, examine carefully</li><li>to consider well</li></ol>","xlit":"katamanthánō"},"G1416":{"translit":"dýnō","lemma":"δύνω","kjv_def":"set","strongs_def":" to go \"down\"","derivation":"prolonged forms of an obsolete primary (to sink);","pron":"doo'-no","pos":"Verb","thayer":"<ol><li>to go into, enter</li><li>go under, be plunged into, sink in<ol type='a'><li>used in the NT of the setting of the sun</li></ol></li></ol>","xlit":"dýnō"},"G495":{"lemma":"ἀντιπέραν","translit":"antipéran","kjv_def":"over against","strongs_def":" on the opposite side","derivation":"from G473 (ἀντί) and G4008 (πέραν);","pron":"an-tee-per'-an","pos":"Adverb","thayer":"<ol><li>over against, on the opposite shore, on the other side</li></ol>","xlit":"antipéran"},"G1712":{"derivation":"neuter from G1713 (ἔμπορος);","strongs_def":" a mart (\"emporium\")","kjv_def":"merchandise","lemma":"ἐμπόριον","translit":"empórion","pron":"em-por'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a place were trade is carried on, especially a seaport<ol type='a'><li>a mart, an emporium</li></ol></li></ol>","xlit":"empórion"},"G1255":{"translit":"dialaléō","lemma":"διαλαλέω","kjv_def":"commune, noise abroad","strongs_def":" to talk throughout a company, i.e. converse or (genitive case) publish","derivation":"from G1223 (διά) and G2980 (λαλέω);","pron":"dee-al-al-eh'-o","pos":"Verb","thayer":"<ol><li>to converse together, to talk with</li></ol>","xlit":"dialaléō"},"G3773":{"derivation":"of Latin origin;","strongs_def":" Urbanus (of the city, \"urbane\"), a Christian","kjv_def":"Urbanus","translit":"Ourbanós","lemma":"Οὐρβανός","pron":"oor-ban-os'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Urbane = \"of the city; polite\"</p><ol><li>a certain Christian in <a class='bible' href='#b45.16.9'>Rom 16:9</a></li></ol>","xlit":"Ourbanós"},"G194":{"lemma":"ἄκρατος","translit":"ákratos","kjv_def":"without mixture","strongs_def":" undiluted","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G2767 (κεράννυμι);","pron":"ak'-rat-os","pos":"Adjective","thayer":"<ol><li>unmixed, pure</li></ol>","xlit":"ákratos"},"G2962":{"derivation":"from (supremacy);","strongs_def":" supreme in authority, i.e. (as noun) controller; by implication, Master (as a respectful title)","kjv_def":" God, Lord, master, Sir","lemma":"κύριος","translit":"kýrios","pron":"koo'-ree-os","pos":"Noun Masculine","thayer":"<ol><li>he to whom a person or thing belongs, about which he has power of deciding; master, lord<ol type='a'><li>the possessor and disposer of a thing<ol><li>the owner; one who has control of the person, the master</li><li>in the state: the sovereign, prince, chief, the Roman emperor</li></ol><li>is a title of honour expressive of respect and reverence, with which servants greet their master</li><li>this title is given to: God, the Messiah</li></ol></li></ol>","xlit":"kýrios"},"G4563":{"derivation":"from a derivative of (to brush off;","strongs_def":" akin to G4951 (σύρω)); meaning a broom; to sweep","kjv_def":"sweep","translit":"saróō","lemma":"σαρόω","pron":"sar-o'-o","pos":"Verb","thayer":"<ol><li>to sweep, clean by sweeping</li></ol>","xlit":"saróō"},"G1528":{"kjv_def":"call in","translit":"eiskaléō","lemma":"εἰσκαλέω","derivation":"from G1519 (εἰς) and G2564 (καλέω);","strongs_def":" to invite in","pron":"ice-kal-eh'-o","pos":"Verb","thayer":"<ol><li>to call into one's self, to invite in to one's house</li></ol>","xlit":"eiskaléō"},"G5048":{"lemma":"τελειόω","translit":"teleióō","kjv_def":"consecrate, finish, fulfil, make) perfect","strongs_def":" to complete, i.e. (literally) accomplish, or (figuratively) consummate (in character)","derivation":"from G5046 (τέλειος);","pron":"tel-i-o'-o","pos":"Verb","thayer":"<ol><li>to make perfect, complete<ol type='a'><li>to carry through completely, to accomplish, finish, bring to an end</li></ol><li>to complete (perfect)<ol type='a'><li>add what is yet wanting in order to render a thing full</li><li>to be found perfect</li></ol><li>to bring to the end (goal) proposed</li><li>to accomplish<ol type='a'><li>bring to a close or fulfilment by event<ol><li>of the prophecies of the scriptures</li></ol></li></ol></li></ol>","xlit":"teleióō"},"G3987":{"kjv_def":"assay","translit":"peiráō","lemma":"πειράω","derivation":"from G3984 (πεῖρα);","strongs_def":" to test (subjectively), i.e. (reflexively) to attempt","pron":"pi-rah'-o","pos":"Verb","thayer":"<ol><li>to make a trial of, to attempt<ol type='a'><li>taught by trial, experienced</li></ol><li>to test, to make trial of one, put him to proof<ol type='a'><li>his mind, sentiments, temper</li><li>in particular, to attempt to induce one to commit some (especially carnal) crime</li><li>tempted to sin</li></ol></li></ol>","xlit":"peiráō"},"G4980":{"strongs_def":" to take a holiday, i.e. be at leisure for (by implication, devote oneself wholly to); figuratively, to be vacant (of a house)","derivation":"from G4981 (σχολή);","translit":"scholázō","lemma":"σχολάζω","kjv_def":"empty, give self","pron":"skhol-ad'-zo","pos":"Verb","thayer":"<ol><li>to cease from labour, to loiter</li><li>to be free from labour, to be at leisure, to be idle<ol type='a'><li>to have leisure for a thing</li><li>to give one's self to a thing</li></ol><li>of things<ol type='a'><li>of places, to be unoccupied, empty</li><li>of a centurion's vacant office</li><li>of vacant ecclesiastical offices</li><li>of officers without charge</li></ol></li></ol>","xlit":"scholázō"},"G1643":{"translit":"elaúnō","lemma":"ἐλαύνω","kjv_def":"carry, drive, row","strongs_def":" to push (as wind, oars or dæmonical power)","derivation":"a prolonged form of a primary verb (obsolete except in certain tenses as an alternative of this) of uncertain affinity;","pron":"el-ow'-no","pos":"Verb","thayer":"<ol><li>to drive<ol type='a'><li>of the wind driving ships or clouds</li><li>of sailors propelling a vessel by oars, to row</li><li>to be carried in a ship, to sail</li><li>of demons driving to some place the men whom they possess</li></ol></li></ol>","xlit":"elaúnō"},"G3811":{"derivation":"from G3816 (παῖς);","strongs_def":" to train up a child, i.e. educate, or (by implication), discipline (by punishment)","kjv_def":"chasten(-ise), instruct, learn, teach","lemma":"παιδεύω","translit":"paideúō","pron":"pahee-dyoo'-o","pos":"Verb","thayer":"<ol><li>to train children<ol type='a'><li>to be instructed or taught or learn</li><li>to cause one to learn</li></ol><li>to chastise<ol type='a'><li>to chastise or castigate with words, to correct<ol><li>of those who are moulding the character of others by reproof and admonition</li></ol><li>of God<ol><li>to chasten by the affliction of evils and calamities</li></ol><li>to chastise with blows, to scourge<ol><li>of a father punishing his son</li><li>of a judge ordering one to be scourged</li></ol></li></ol></li></ol>","xlit":"paideúō"},"G2913":{"translit":"Krḗskēs","lemma":"Κρήσκης","kjv_def":"Crescens","strongs_def":" growing; Cresces (i.e. Crescens), a Christian","derivation":"of Latin origin;","pron":"krace'-kace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Crescens = \"growing\"</p><ol><li>an assistant of Paul, said to be one of the seventy disciples</li></ol>","xlit":"Krḗskēs"},"G2168":{"derivation":"from G2170 (εὐχάριστος);","strongs_def":" to be grateful, i.e. (actively) to express gratitude (towards); specially, to say grace at a meal","kjv_def":"(give) thank(-ful, -s)","translit":"eucharistéō","lemma":"εὐχαριστέω","pron":"yoo-khar-is-teh'-o","pos":"Verb","thayer":"<ol><li>to be grateful, feel thankful</li><li>give thanks</li></ol>","xlit":"eucharistéō"},"G3583":{"derivation":"from G3584 (ξηρός);","strongs_def":" to desiccate; by implication, to shrivel, to mature","kjv_def":"dry up, pine away, be ripe, wither (away)","translit":"xēraínō","lemma":"ξηραίνω","pron":"xay-rah'-ee-no","pos":"Verb","thayer":"<ol><li>to make dry, dry up, wither</li><li>to become dry, to be dry, be withered<ol type='a'><li>of plants</li><li>of the ripening of crops</li><li>of fluids</li><li>of the members of the body</li></ol><li>to waste away, pine away, i.e. a withered hand</li></ol>","xlit":"xēraínō"},"G3471":{"strongs_def":" to become insipid; figuratively, to make (passively, act) as a simpleton","derivation":"from G3474 (μωρός);","lemma":"μωραίνω","translit":"mōraínō","kjv_def":"become fool, make foolish, lose savour","pron":"mo-rah'-ee-no","pos":"Verb","thayer":"<ol><li>to be foolish, to act foolishly<ol type='a'><li>to make foolish<ol><li>to prove a person or a thing foolish</li></ol><li>to make flat and tasteless<ol><li>of salt that has lost its strength and flavour</li></ol></li></ol></li></ol>","xlit":"mōraínō"},"G1013":{"lemma":"βούλημα","translit":"boúlēma","kjv_def":"purpose, will","strongs_def":" a resolve","derivation":"from G1014 (βούλομαι);","pron":"boo'-lay-mah","pos":"Noun Neuter","thayer":"<ol><li>will, counsel, purpose</li></ol>","xlit":"boúlēma"},"G1231":{"translit":"diaginṓskō","lemma":"διαγινώσκω","kjv_def":"(would) enquire, know the uttermost","strongs_def":" to know thoroughly, i.e. ascertain exactly","derivation":"from G1223 (διά) and G1097 (γινώσκω);","pron":"dee-ag-in-o'-sko","pos":"Verb","thayer":"<ol><li>to distinguish, i.e. to know accurately, ascertain exactly</li><li>in a legal sense, to examine, determine, decide</li></ol>","xlit":"diaginṓskō"},"G2163":{"kjv_def":"of good report","lemma":"εὔφημος","translit":"eúphēmos","derivation":"from G2095 (εὖ) and G5345 (φήμη);","strongs_def":" well spoken of, i.e. reputable","pron":"yoo'-fay-mos","pos":"Adjective","thayer":"<ol><li>sounding well</li><li>uttering words of good omen, speaking auspiciously</li></ol>","xlit":"eúphēmos"},"G1657":{"kjv_def":"liberty","translit":"eleuthería","lemma":"ἐλευθερία","derivation":"from G1658 (ἐλεύθερος);","strongs_def":" freedom (legitimate or licentious, chiefly moral or ceremonial)","pron":"el-yoo-ther-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>liberty to do or to omit things having no relationship to salvation</li><li>fancied liberty<ol type='a'><li>licence, the liberty to do as one pleases</li></ol><li>true liberty is living as we should not as we please</li></ol>","xlit":"eleuthería"},"G76":{"lemma":"Ἀδάμ","translit":"Adám","kjv_def":"Adam","strongs_def":" Adam, the first man; typically (of Jesus) man (as his representative)","derivation":"of Hebrew origin (H0121);","pron":"ad-am'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Adam = \"the red earth\"</p><ol><li>Adam, the first man, the parent of the whole human family</li></ol>","xlit":"Adám"},"G946":{"derivation":"from G948 (βδελύσσω);","strongs_def":" a detestation, i.e. (specially) idolatry","kjv_def":"abomination","lemma":"βδέλυγμα","translit":"bdélygma","pron":"bdel'-oog-mah","pos":"Noun Neuter","thayer":"<ol><li>a foul thing, a detestable thing<ol type='a'><li>of idols and things pertaining to idolatry</li></ol></li></ol>","xlit":"bdélygma"},"G3181":{"derivation":"from G3326 (μετά) and G3725 (ὅριον);","strongs_def":" bounded alongside, i.e. contiguous (neuter plural as noun, frontier)","kjv_def":"border","lemma":"μεθόριος","translit":"methórios","pron":"meth-or'-ee-os","pos":"Noun Neuter","thayer":"<ol><li>a border, frontier</li></ol>","xlit":"methórios"},"G1149":{"lemma":"Δαλματία","translit":"Dalmatía","kjv_def":"Dalmatia","strongs_def":" Dalmatia, a region of Europe","derivation":"probably of foreign derivation;","pron":"dal-mat-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Dalmatia = \"a priestly robe\"</p><ol><li>a part of Illyricum on the Adriatic Sea; on the east adjoining Pannonia and upper Moesia, on the north separated from Liburia by the river Titus, and extending southwards as far as the river Drinus and the city Lissus</li></ol>","xlit":"Dalmatía"},"G1017":{"translit":"brabeîon","lemma":"βραβεῖον","kjv_def":"prize","strongs_def":" an award (of arbitration), i.e. (specially) a prize in the public games","derivation":"from (an umpire of uncertain derivation);","pron":"brab-i'-on","pos":"Noun Neuter","thayer":"<ol><li>the award to the victor in the games, a prize</li><li>metaphorically of the heavenly reward for Christian character</li></ol>","xlit":"brabeîon"},"G2609":{"strongs_def":" to lead down; specially, to moor a vessel","derivation":"from G2596 (κατά) and G71 (ἄγω);","translit":"katágō","lemma":"κατάγω","kjv_def":"bring (down, forth), (bring to) land, touch","pron":"kat-ag'-o","pos":"Verb","thayer":"<ol><li>to lead down, bring down</li><li>to bring the vessel from deep water to the land</li><li>to be brought (down) in a ship, to land, touch at</li></ol>","xlit":"katágō"},"G4557":{"strongs_def":" hence the \"onyx\" stone); a \"sardonyx\", i.e. the gem so called","derivation":"from the base of G4556 (σάρδιος) and (the nail of a finger;","lemma":"σαρδόνυξ","translit":"sardónyx","kjv_def":" sardonyx","pron":"sar-don'-oox","pos":"Noun Masculine","thayer":"<ol><li>a sardonyx, a precious stone marked by the red colours of the carnelian (sard) and the white of the onyx</li></ol>","xlit":"sardónyx"},"G4569":{"strongs_def":" Saulus (i.e. Shaul), the Jewish name of Paul","derivation":"of Hebrew origin, the same as G4549 (Σαούλ);","translit":"Saûlos","lemma":"Σαῦλος","kjv_def":"Saul","pron":"sow'-los","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Saul = \"desired\"</p><ol><li>the Jewish name of the apostle Paul</li></ol>","xlit":"Saûlos"},"G3046":{"derivation":"of Latin origin (libra);","strongs_def":" a pound in weight","kjv_def":"pound","lemma":"λίτρα","translit":"lítra","pron":"lee'-trah","pos":"Noun Feminine","thayer":"<ol><li>a pound, a weight of 12 ounces (340 gm)</li></ol>","xlit":"lítra"},"G476":{"kjv_def":"adversary","translit":"antídikos","lemma":"ἀντίδικος","derivation":"from G473 (ἀντί) and G1349 (δίκη);","strongs_def":" an opponent (in a lawsuit); specially, Satan (as the arch-enemy)","pron":"an-tid'-ee-kos","pos":"Noun Masculine","thayer":"<ol><li>opponent<ol type='a'><li>an opponent in a suit of law</li><li>an adversary, enemy</li></ol></li></ol>","xlit":"antídikos"},"G1752":{"derivation":"of uncertain affinity;","strongs_def":" on account of","kjv_def":"because, for (cause, sake), (where-)fore, by reason of, that","translit":"héneka","lemma":"ἕνεκα","pron":"hen'-ek-ah","pos":"Preposition","thayer":"<ol><li>on account of, for the sake of, for</li><li>for this cause, therefore</li></ol>","xlit":"héneka"},"G1289":{"kjv_def":"scatter abroad","lemma":"διασπείρω","translit":"diaspeírō","derivation":"from G1223 (διά) and G4687 (σπείρω);","strongs_def":" to sow throughout, i.e. (figuratively) distribute in foreign lands","pron":"dee-as-pi'-ro","pos":"Verb","thayer":"<ol><li>to scatter abroad, disperse</li></ol>","xlit":"diaspeírō"},"G6":{"kjv_def":"Abel","translit":"Ábel","lemma":"Ἄβελ","derivation":"of Hebrew origin (H01893);","strongs_def":" Abel, the son of Adam","pron":"ab'-el","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Abel = \"vanity (that is: transitory)\"</p><ol><li>the second son of Adam, murdered by his brother Cain</li></ol>","xlit":"Ábel"},"G1317":{"strongs_def":" instructive (\"didactic\")","derivation":"from G1318 (διδακτός);","lemma":"διδακτικός","translit":"didaktikós","kjv_def":"apt to teach","pron":"did-ak-tik-os'","pos":"Adjective","thayer":"<ol><li>apt and skilful in teaching</li></ol>","xlit":"didaktikós"},"G2502":{"strongs_def":" Josias (i.e. Joshiah), an Israelite","derivation":"of Hebrew origin (H02977);","translit":"Iōsías","lemma":"Ἰωσίας","kjv_def":"Josias","pron":"ee-o-see'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Josiah = \"whom Jehovah heals\"</p><ol><li>king of Judah, who restored among the Jews the worship of the true God, and after a reign of thirty one years was slain in battle about 611 BC</li></ol>","xlit":"Iōsías"},"G2052":{"lemma":"ἐριθεία","translit":"eritheía","kjv_def":"contention(-ious), strife","strongs_def":" properly, intrigue, i.e. (by implication) faction","derivation":"perhaps as the same as G2042 (ἐρεθίζω);","pron":"er-ith-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>electioneering or intriguing for office<ol type='a'><li>apparently, in the NT a courting distinction, a desire to put one's self forward, a partisan and fractious spirit which does not disdain low arts</li><li>partisanship, fractiousness</li></ol></li></ol>","xlit":"eritheía"},"G4713":{"derivation":"from the base of G2476 (ἵστημι) (as stationary);","strongs_def":" a jar or earthen tank","kjv_def":"pot","lemma":"στάμνος","translit":"stámnos","pron":"stam'-nos","pos":"Noun Feminine","thayer":"<ol><li>among the Greeks an earthen jar, into which wine was drawn off for keeping but also used for other purposes<ol type='a'><li>of the little jar in which the manna was kept, laid up in the ark of the covenant</li></ol></li></ol>","xlit":"stámnos"},"G3059":{"strongs_def":" slander or vituperation","derivation":"from G3060 (λοίδορος);","lemma":"λοιδορία","translit":"loidoría","kjv_def":"railing, reproach(-fully)","pron":"loy-dor-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>railing, reviling</li></ol>","xlit":"loidoría"},"G5050":{"derivation":"from G5448 (φυσιόω);","strongs_def":" (the act) completion, i.e. (of prophecy) verification, or (of expiation) absolution","kjv_def":"perfection, performance","translit":"teleíōsis","lemma":"τελείωσις","pron":"tel-i'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>a completing, a perfecting<ol type='a'><li>fulfilment, accomplishment</li><li>the event which verifies the promise</li><li>consummation, perfection</li></ol></li></ol>","xlit":"teleíōsis"},"G4848":{"kjv_def":"go with, resort","translit":"symporeúomai","lemma":"συμπορεύομαι","derivation":"from G4862 (σύν) and G4198 (πορεύομαι);","strongs_def":" to journey together; by implication, to assemble","pron":"soom-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to go or journey together</li><li>to come together, to assemble</li></ol>","xlit":"symporeúomai"},"G1479":{"strongs_def":" voluntary (arbitrary and unwarranted) piety, i.e. sanctimony","derivation":"from G2309 (θέλω) and G2356 (θρησκεία);","lemma":"ἐθελοθρησκεία","translit":"ethelothrēskeía","kjv_def":"will worship","pron":"eth-el-oth-race-ki'-ah","pos":"Noun Feminine","thayer":"<ol><li>voluntary, arbitrary worship<ol type='a'><li>worship which one prescribes and devises for himself, contrary to the contents and nature of faith which ought to be directed to Christ</li><li>said of the misdirected zeal and the practice of ascetics</li></ol></li></ol>","xlit":"ethelothrēskeía"},"G2395":{"derivation":"from G2390 (ἰάομαι);","strongs_def":" a physician","kjv_def":"physician","translit":"iatrós","lemma":"ἰατρός","pron":"ee-at-ros'","pos":"Noun Masculine","thayer":"<ol><li>a physician</li></ol>","xlit":"iatrós"},"G1041":{"strongs_def":" properly, a stand, i.e. (specially) an altar","derivation":"from the base of G939 (βάσις);","lemma":"βωμός","translit":"bōmós","kjv_def":"altar","pron":"bo'-mos","pos":"Noun Masculine","thayer":"<ol><li>an elevated place<ol type='a'><li>very often a raised place on which to offer a sacrifice, an altar</li></ol></li></ol>","xlit":"bōmós"},"G1261":{"lemma":"διαλογισμός","translit":"dialogismós","kjv_def":"dispute, doubtful(-ing), imagination, reasoning, thought","strongs_def":" discussion, i.e. (internal) consideration (by implication, purpose), or (external) debate","derivation":"from G1260 (διαλογίζομαι);","pron":"dee-al-og-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>the thinking of a man deliberating with himself<ol type='a'><li>a thought, inward reasoning</li><li>purpose, design</li></ol><li>a deliberating, questioning about what is true<ol type='a'><li>hesitation, doubting</li><li>disputing, arguing</li></ol></li></ol>","xlit":"dialogismós"},"G1873":{"kjv_def":"hear","lemma":"ἐπακούω","translit":"epakoúō","derivation":"from G1909 (ἐπί) and G191 (ἀκούω);","strongs_def":" to hearken (favorably) to","pron":"ep-ak-oo'-o","pos":"Verb","thayer":"<ol><li>to give ear to, listen to<ol type='a'><li>to perceive by the ear</li></ol><li>to listen to<ol type='a'><li>to hear with favour, grant one's request</li></ol></li></ol>","xlit":"epakoúō"},"G1865":{"strongs_def":" to accumulate","derivation":"from G1909 (ἐπί) and (to assemble);","lemma":"ἐπαθροίζω","translit":"epathroízō","kjv_def":"gather thick together","pron":"ep-ath-roid'-zo","pos":"Verb","thayer":"<ol><li>to gather together (to others already present)</li></ol>","xlit":"epathroízō"},"G516":{"kjv_def":"as becometh, after a godly sort, worthily(-thy)","lemma":"ἀξίως","translit":"axíōs","derivation":"adverb from G514 (ἄξιος);","strongs_def":" appropriately","pron":"ax-ee'-oce","pos":"Adverb","thayer":"<ol><li>suitably, worthily, in a manner worthy of</li></ol>","xlit":"axíōs"},"G5346":{"lemma":"φημί","translit":"phēmí","kjv_def":"affirm, say","strongs_def":" to show or make known one's thoughts, i.e. speak or say","derivation":"properly, the same as the base of G5457 (φῶς) and G5316 (φαίνω);","pron":"fay-mee'","pos":"Verb","thayer":"<ol><li>to make known one's thoughts, to declare</li><li>to say</li></ol>","xlit":"phēmí"},"G4107":{"derivation":"from G4108 (πλάνος);","strongs_def":" a rover (\"planet\"), i.e. (figuratively) an erratic teacher","kjv_def":"wandering","translit":"planḗtēs","lemma":"πλανήτης","pron":"plan-ay'-tace","pos":"Noun Masculine","thayer":"<ol><li>a wanderer: wandering stars</li></ol>","xlit":"planḗtēs"},"G3929":{"translit":"páresis","lemma":"πάρεσις","kjv_def":"remission","strongs_def":" praetermission, i.e. toleration","derivation":"from G2935 (κτήτωρ);","pron":"par'-es-is","pos":"Noun Feminine","thayer":"<ol><li>passing over, letting pass, neglecting, disregarding</li></ol>","xlit":"páresis"},"G4396":{"derivation":"from a compound of G4253 (πρό) and G5346 (φημί);","strongs_def":" a foreteller (\"prophet\"); by analogy, an inspired speaker; by extension, a poet","kjv_def":"prophet","lemma":"προφήτης","translit":"prophḗtēs","pron":"prof-ay'-tace","pos":"Noun Masculine","thayer":"<ol><li>in Greek writings, an interpreter of oracles or of other hidden things</li><li>one who, moved by the Spirit of God and hence his organ or spokesman, solemnly declares to men what he has received by inspiration, especially concerning future events, and in particular such as relate to the cause and kingdom of God and to human salvation<ol type='a'><li>the OT prophets, having foretold the kingdom, deeds and death, of Jesus the Messiah.</li><li>of John the Baptist, the herald of Jesus the Messiah</li><li>of the illustrious prophet, the Jews expected before the advent of the Messiah</li><li>the Messiah</li><li>of men filled with the Spirit of God, who by God's authority and command in words of weight pleads the cause of God and urges salvation of men</li><li>of prophets that appeared in the apostolic age among Christians<ol><li>they are associated with the apostles</li><li>they discerned and did what is best for the Christian cause, foretelling certain future events. (<a class='bible' href='#b44.11.27'>Act 11:27</a>)</li><li>in the religious assemblies of the Christians, they were moved by the Holy Spirit to speak, having power to instruct, comfort, encourage, rebuke, convict, and stimulate, their hearers</li></ol></li></ol><li>a poet (because poets were believed to sing under divine inspiration)<ol type='a'><li>of Epimenides (<a class='bible' href='#b56.1.12'>Tit 1:12</a>)</li></ol></li></ol>","xlit":"prophḗtēs"},"G4643":{"derivation":"from G4642 (σκληρός);","strongs_def":" callousness, i.e. (figuratively) stubbornness","kjv_def":"hardness","lemma":"σκληρότης","translit":"sklērótēs","pron":"sklay-rot'-ace","pos":"Noun Feminine","thayer":"<ol><li>hardness</li><li>obstinacy, stubbornness</li></ol>","xlit":"sklērótēs"},"G5429":{"derivation":"from G5424 (φρήν);","strongs_def":" thoughtful, i.e. sagacious or discreet (implying a cautious character; while G4680 (σοφός) denotes practical skill or acumen; and G4908 (συνετός) indicates rather intelligence or mental acquirement); in a bad sense conceited (also in the comparative)","kjv_def":"wise(-r)","translit":"phrónimos","lemma":"φρόνιμος","pron":"fron'-ee-mos","pos":"Adjective","thayer":"<ol><li>intelligent, wise</li><li>prudent, i.e. mindful of one's interests</li></ol>","xlit":"phrónimos"},"G5619":{"lemma":"ὡσπερεί","translit":"hōspereí","kjv_def":"as","strongs_def":" just as if, i.e. as it were","derivation":"from G5618 (ὥσπερ) and G1487 (εἰ);","pron":"hoce-per-i'","pos":"Adverb","thayer":"<ol><li>as, as it were</li></ol>","xlit":"hōspereí"},"G5560":{"kjv_def":"cripple, halt, lame","lemma":"χωλός","translit":"chōlós","derivation":"apparently a primary word;","strongs_def":" \"halt\", i.e. limping","pron":"kho-los'","pos":"Adjective","thayer":"<ol><li>lame<ol type='a'><li>deprived of a foot, maimed</li></ol></li></ol>","xlit":"chōlós"},"G2663":{"translit":"katápausis","lemma":"κατάπαυσις","kjv_def":"rest","strongs_def":" reposing down, i.e. (by Hebraism) abode","derivation":"from G2664 (καταπαύω);","pron":"kat-ap'-ow-sis","pos":"Noun Feminine","thayer":"<ol><li>a putting to rest<ol type='a'><li>calming of the winds</li></ol><li>a resting place<ol type='a'><li>metaphorically the heavenly blessedness in which God dwells, and of which he has promised to make persevering believers in Christ partakers after the toils and trials of life on earth are ended</li></ol></li></ol>","xlit":"katápausis"},"G4675":{"derivation":"genitive case of G4771 (σύ);","strongs_def":" of thee, thy","kjv_def":"X home, thee, thine (own), thou, thy","lemma":"σοῦ","translit":"soû","pron":"soo","thayer":"<ol><li>thy, thee</li></ol>","xlit":"soû"},"G4003":{"derivation":"from G4002 (πέντε) and G2532 (καί) and G1182 (δέκατος);","strongs_def":" five and tenth","kjv_def":"fifteenth","lemma":"πεντεκαιδέκατος","translit":"pentekaidékatos","pron":"pen-tek-ahee-ded'-at-os","pos":"Adjective","thayer":"<ol><li>the fifteenth</li></ol>","xlit":"pentekaidékatos"},"G5027":{"strongs_def":" burial (the act)","derivation":"feminine from G2290 (θάπτω);","lemma":"ταφή","translit":"taphḗ","kjv_def":"X bury","pron":"taf-ay'","pos":"Noun Feminine","thayer":"<ol><li>burial</li></ol>","xlit":"taphḗ"},"G4038":{"translit":"périx","lemma":"πέριξ","kjv_def":"round about","strongs_def":" all around, i.e. (as an adjective) circumjacent","derivation":"adverb from G4012 (περί);","pron":"per'-ix","pos":"Adverb","thayer":"<ol><li>round about: the neighbouring cities</li></ol>","xlit":"périx"},"G685":{"kjv_def":"curse","lemma":"ἀρά","translit":"ará","derivation":"probably from G142 (αἴρω);","strongs_def":" properly, prayer (as lifted to Heaven), i.e. (by implication) imprecation","pron":"ar-ah'","pos":"Noun Feminine","thayer":"<ol><li>a prayer, a supplication</li><li>an imprecation, curse, malediction</li></ol>","xlit":"ará"},"G296":{"derivation":"from the base of G297 (ἀμφότερος) and G3598 (ὁδός);","strongs_def":" a fork in the road","kjv_def":"where two ways meet","lemma":"ἄμφοδον","translit":"ámphodon","pron":"am'-fod-on","pos":"Noun Neuter","thayer":"<ol><li>a road around anything, a street</li></ol>","xlit":"ámphodon"},"G4477":{"kjv_def":"Rachab","translit":"Rhacháb","lemma":"Ῥαχάβ","derivation":"from the same as G4460 (Ῥαάβ);","strongs_def":" Rachab, a Canaanitess","pron":"hrakh-ab'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Rahab = \"wide\"</p><ol><li>a harlot of Jericho</li></ol>","xlit":"Rhacháb"},"G149":{"derivation":"neuter of G150 (αἰσχρός);","strongs_def":" a shameful thing, i.e. indecorum","kjv_def":"shame","translit":"aischrón","lemma":"αἰσχρόν","pron":"ahee-skhron'","pos":"Noun Neuter","thayer":"<ol><li>shame, base, dishonourable</li></ol>","xlit":"aischrón"},"G4777":{"strongs_def":" to suffer hardship in company with","derivation":"from G4862 (σύν) and G2553 (κακοπαθέω);","lemma":"συγκακοπαθέω","translit":"synkakopathéō","kjv_def":"be partaker of afflictions","pron":"soong-kak-op-ath-eh'-o","pos":"Verb","thayer":"<ol><li>to suffer hardship together with one</li></ol>","xlit":"synkakopathéō"},"G1726":{"lemma":"ἐναντίον","translit":"enantíon","kjv_def":"before, in the presence of","strongs_def":" (adverbially) in the presence (view) of","derivation":"neuter of G1727 (ἐναντίος);","pron":"en-an-tee'-on","pos":"Preposition","thayer":"<ol><li>over against, opposite<ol type='a'><li>of place, opposite, contrary (of the wind)</li></ol><li>metaphorically<ol type='a'><li>opposed as an adversary, hostile, antagonistic in feeling or act</li><li>an opponent</li></ol></li></ol>","xlit":"enantíon"},"G1065":{"derivation":"a primary particle of emphasis or qualification (often used with other particles prefixed)","kjv_def":"and besides, doubtless, at least, yet","translit":"gé","lemma":"γέ","pron":"gheh","thayer":"<ol><li>indeed, truly, at least</li><li>even</li><li>if indeed, seeing that</li></ol>","xlit":"gé"},"G5133":{"strongs_def":" a money-broker or banker","derivation":"from G5132 (τράπεζα);","lemma":"τραπεζίτης","translit":"trapezítēs","kjv_def":"exchanger","pron":"trap-ed-zee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a money changer, broker, banker</li><li>one who exchanges money for a fee, and pays interest on deposits</li></ol>","xlit":"trapezítēs"},"G4872":{"lemma":"συναναβαίνω","translit":"synanabaínō","kjv_def":"come up with","strongs_def":" to ascend in company with","derivation":"from G4862 (σύν) and G305 (ἀναβαίνω);","pron":"soon-an-ab-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to ascend at the same time, come up together with to a higher place<ol type='a'><li>with one</li></ol></li></ol>","xlit":"synanabaínō"},"G1544":{"strongs_def":" to eject (literally or figuratively)","derivation":"from G1537 (ἐκ) and G906 (βάλλω);","translit":"ekbállō","lemma":"ἐκβάλλω","kjv_def":"bring forth, cast (forth, out), drive (out), expel, leave, pluck (pull, take, thrust) out, put forth (out), send away (forth, out)","pron":"ek-bal'-lo","pos":"Verb","thayer":"<ol><li>to cast out, drive out, to send out<ol type='a'><li>with notion of violence<ol><li>to drive out (cast out)</li><li>to cast out<ol type='a'><li>of the world, i.e. be deprived of the power and influence he exercises in the world</li><li>a thing: excrement from the belly into the sink</li></ol><li>to expel a person from a society: to banish from a family</li><li>to compel one to depart; to bid one depart, in stern though not violent language</li><li>so employed that the rapid motion of the one going is transferred to the one sending forth<ol type='a'><li>to command or cause one to depart in haste</li></ol><li>to draw out with force, tear out</li><li>with implication of force overcoming opposite force<ol type='a'><li>to cause a thing to move straight on its intended goal</li></ol><li>to reject with contempt, to cast off or away</li></ol><li>without the notion of violence<ol><li>to draw out, extract, one thing inserted in another</li><li>to bring out of, to draw or bring forth</li><li>to except, to leave out, i.e. not receive</li><li>to lead one forth or away somewhere with a force which he cannot resist</li></ol></li></ol></li></ol>","xlit":"ekbállō"},"G3637":{"derivation":"from G3638 (ὀκτώ) and G2250 (ἡμέρα);","strongs_def":" an eight-day old person or act","kjv_def":"the eighth day","translit":"oktaḗmeros","lemma":"ὀκταήμερος","pron":"ok-tah-ay'-mer-os","pos":"Adjective","thayer":"<ol><li>eight days old</li><li>passing the eighth day</li></ol>","xlit":"oktaḗmeros"},"G984":{"translit":"bláptō","lemma":"βλάπτω","kjv_def":"hurt","strongs_def":" properly, to hinder, i.e. (by implication) to injure","derivation":"a primary verb;","pron":"blap'-to","pos":"Verb","thayer":"<ol><li>to hurt, harm, injure</li></ol>","xlit":"bláptō"},"G1550":{"kjv_def":"spend","lemma":"ἐκδαπανάω","translit":"ekdapanáō","derivation":"from G1537 (ἐκ) and G1159 (δαπανάω);","strongs_def":" to expend (wholly), i.e. (figuratively) exhaust","pron":"ek-dap-an-ah'-o","pos":"Verb","thayer":"<ol><li>to exhaust by expending, to spend wholly, use up</li><li>to spend one's self wholly</li></ol>","xlit":"ekdapanáō"},"G1758":{"lemma":"ἐνέχω","translit":"enéchō","kjv_def":"entangle with, have a quarrel against, urge","strongs_def":" to hold in or upon, i.e. ensnare; by implication, to keep a grudge","derivation":"from G1722 (ἐν) and G2192 (ἔχω);","pron":"en-ekh'-o","pos":"Verb","thayer":"<ol><li>to have within, to hold in<ol type='a'><li>to be held, entangled, be held ensnared</li><li>to be engaged with, set one's self against, hold a grudge against someone</li></ol></li></ol>","xlit":"enéchō"},"G4074":{"derivation":"apparently a primary word;","strongs_def":" a (piece of) rock (larger than G3037 (λίθος)); as a name, Petrus, an apostle","kjv_def":"Peter, rock","translit":"Pétros","lemma":"Πέτρος","pron":"pet'-ros","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Peter = \"a rock or a stone\"</p><ol><li>one of the twelve disciples of Jesus</li></ol>","xlit":"Pétros"},"G5496":{"derivation":"from G5497 (χειραγωγός);","strongs_def":" to be a hand-leader, i.e. to guide (a blind person)","kjv_def":"lead by the hand","lemma":"χειραγωγέω","translit":"cheiragōgéō","pron":"khi-rag-ogue-eh'-o","pos":"Verb","thayer":"<ol><li>to lead by the hand</li></ol>","xlit":"cheiragōgéō"},"G2114":{"derivation":"from G2115 (εὔθυμος);","strongs_def":" to cheer up, i.e. (intransitively) be cheerful; neuter comparative (adverbially) more cheerfully","kjv_def":"be of good cheer (merry)","lemma":"εὐθυμέω","translit":"euthyméō","pron":"yoo-thoo-meh'-o","pos":"Verb","thayer":"<ol><li>to put in good spirits, gladden, make cheerful<ol type='a'><li>to be of good spirits, to be cheerful</li></ol><li>to be joyful, be of good cheer, of good courage</li></ol>","xlit":"euthyméō"},"G1441":{"translit":"hebdomēkontákis","lemma":"ἑβδομηκοντάκις","kjv_def":"seventy times","strongs_def":" seventy times","derivation":"multiple adverb from G1440 (ἑβδομήκοντα);","pron":"heb-dom-ay-kon-tak-is","pos":"Adverb","thayer":"<ol><li>seventy times seven times<ol type='a'><li>countless times</li></ol></li></ol>","xlit":"hebdomēkontákis"},"G726":{"strongs_def":" to seize (in various applications)","derivation":"from a derivative of G138 (αἱρέομαι);","lemma":"ἁρπάζω","translit":"harpázō","kjv_def":"catch (away, up), pluck, pull, take (by force)","pron":"har-pad'-zo","pos":"Verb","thayer":"<ol><li>to seize, carry off by force</li><li>to seize on, claim for one's self eagerly</li><li>to snatch out or away</li></ol>","xlit":"harpázō"},"G3820":{"derivation":"from G3819 (πάλαι);","strongs_def":" antique, i.e. not recent, worn out","kjv_def":"old","lemma":"παλαιός","translit":"palaiós","pron":"pal-ah-yos'","pos":"Adjective","thayer":"<ol><li>old, ancient</li><li>no longer new, worn by use, the worse for wear, old</li></ol>","xlit":"palaiós"},"G3665":{"strongs_def":" resemblance","derivation":"from G3664 (ὅμοιος);","lemma":"ὁμοιότης","translit":"homoiótēs","kjv_def":"like as, similitude","pron":"hom-oy-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>likeness</li></ol>","xlit":"homoiótēs"},"G3450":{"strongs_def":" of me","derivation":"the simpler form of G1700 (ἐμοῦ);","translit":"moû","lemma":"μοῦ","kjv_def":"I, me, mine (own), my","pron":"moo","thayer":"<ol><li>I, me, my, of me</li></ol>","xlit":"moû"},"G3508":{"derivation":"of Hebrew origin (H05321);","strongs_def":" Nephthaleim (i.e. Naphthali), a tribe in Palestine","kjv_def":"Nephthalim","translit":"Nephthaleím","lemma":"Νεφθαλείμ","pron":"nef-thal-ime'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Naphtali = \"wrestling\"</p><ol><li>was the sixth son of Jacob, the second child borne to him by Bilhah, Rachel's slave. His posterity form the tribe of Naphtali.</li></ol>","xlit":"Nephthaleím"},"G4843":{"strongs_def":" to take by enclosing altogether, i.e. earnestly throw the arms about one","derivation":"from G4862 (σύν) and a compound of G4012 (περί) and G2983 (λαμβάνω);","translit":"symperilambánō","lemma":"συμπεριλαμβάνω","kjv_def":"embrace","pron":"soom-per-ee-lam-ban'-o","pos":"Verb","thayer":"<ol><li>to comprehend at once</li><li>to embrace completely</li></ol>","xlit":"symperilambánō"},"G2636":{"lemma":"καταλαλία","translit":"katalalía","kjv_def":"backbiting, evil speaking","strongs_def":" defamation","derivation":"from G2637 (κατάλαλος);","pron":"kat-al-al-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>defamation, evil speaking</li></ol>","xlit":"katalalía"},"G3058":{"derivation":"from G3060 (λοίδορος);","strongs_def":" to reproach, i.e. vilify","kjv_def":"revile","translit":"loidoréō","lemma":"λοιδορέω","pron":"loy-dor-eh'-o","pos":"Verb","thayer":"<ol><li>to reproach, rail at, revile, heap abuse upon</li></ol>","xlit":"loidoréō"},"G1767":{"derivation":"a primary number;","strongs_def":" nine","kjv_def":"nine","translit":"ennéa","lemma":"ἐννέα","pron":"en-neh'-ah","pos":"Noun","thayer":"<ol><li>nine</li></ol>","xlit":"ennéa"},"G2672":{"strongs_def":" to execrate; by analogy, to doom","derivation":"middle voice from G2671 (κατάρα);","lemma":"καταράομαι","translit":"kataráomai","kjv_def":"curse","pron":"kat-ar-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to curse, doom, imprecate evil upon</li></ol>","xlit":"kataráomai"},"G4460":{"kjv_def":"Rahab","lemma":"Ῥαάβ","translit":"Rhaáb","derivation":"of Hebrew origin (G7343);","strongs_def":" Raab (i.e. Rachab), a Canaanitess","pron":"hrah-ab'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Rahab = \"wide\"</p><ol><li>a harlot of Jericho</li></ol>","xlit":"Rhaáb"},"G2457":{"derivation":"of Latin origin;","strongs_def":" Julius, a centurion","kjv_def":"Julius","lemma":"Ἰούλιος","translit":"Ioúlios","pron":"ee-oo'-lee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Julius = \"soft-haired\"</p><ol><li>the centurion of \"Augustus Band\" , to whose charge Paul was delivered when he was sent prisoner from Caesarea to Rome</li></ol>","xlit":"Ioúlios"},"G3107":{"kjv_def":" blessed, happy(X -ier)","translit":"makários","lemma":"μακάριος","derivation":"a prolonged form of the poetical (meaning the same);","strongs_def":" supremely blest; by extension, fortunate, well off","pron":"mak-ar'-ee-os","pos":"Adjective","thayer":"<ol><li>blessed, happy</li></ol>","xlit":"makários"},"G1026":{"kjv_def":"(send) rain, wash","lemma":"βρέχω","translit":"bréchō","derivation":"a primary verb;","strongs_def":" to moisten (especially by a shower)","pron":"brekh'-o","pos":"Verb","thayer":"<ol><li>to moisten, wet, water</li><li>to water with rain, to cause to rain, to pour the rain, to send down like rain</li></ol>","xlit":"bréchō"},"G632":{"kjv_def":"give","translit":"aponémō","lemma":"ἀπονέμω","derivation":"from G575 (ἀπό) and the base of G3551 (νόμος);","strongs_def":" to apportion, i.e. bestow","pron":"ap-on-em'-o","pos":"Verb","thayer":"<ol><li>to assign, portion out</li></ol>","xlit":"aponémō"},"G115":{"derivation":"from G114 (ἀθετέω);","strongs_def":" cancellation (literally or figuratively)","kjv_def":"disannulling, put away","lemma":"ἀθέτησις","translit":"athétēsis","pron":"ath-et'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>abolition, disannulling, put away, rejection</li></ol>","xlit":"athétēsis"},"G3852":{"strongs_def":" a mandate","derivation":"from G3853 (παραγγέλλω);","translit":"parangelía","lemma":"παραγγελία","kjv_def":"charge, command","pron":"par-ang-gel-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>announcement, a proclaiming or giving a message to</li><li>a charge, a command</li></ol>","xlit":"parangelía"},"G4504":{"lemma":"Ῥοῦφος","translit":"Rhoûphos","kjv_def":"Rufus","strongs_def":" red; Rufus, a Christian","derivation":"of Latin origin;","pron":"hroo'-fos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Rufus = \"red\"</p><ol><li>name of a certain Christian</li></ol>","xlit":"Rhoûphos"},"G4803":{"kjv_def":"disputation(-ting), reasoning","lemma":"συζήτησις","translit":"syzḗtēsis","derivation":"from G4802 (συζητέω);","strongs_def":" mutual questioning, i.e. discussion","pron":"sood-zay'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>mutual questioning, disputation, discussion</li></ol>","xlit":"syzḗtēsis"},"G1446":{"strongs_def":" the Hebraistic (Hebrew) or Jewish (Chaldee) language","derivation":"from G1443 (Ἐβέρ);","translit":"Hebraḯs","lemma":"Ἑβραΐς","kjv_def":"Hebrew","pron":"heb-rah-is'","pos":"Noun Feminine","thayer":"<ol><li>Hebrew, the Hebrew language, not that however in which the OT was written but the Chaldee, which at the time of Jesus and the apostles had long superseded it in Palestine</li></ol>","xlit":"Hebraḯs"},"G3646":{"strongs_def":" a wholly-consumed sacrifice (\"holocaust\")","derivation":"from a derivative of a compound of G3650 (ὅλος) and a derivative of G2545 (καίω);","lemma":"ὁλοκαύτωμα","translit":"holokaútōma","kjv_def":"(whole) burnt offering","pron":"hol-ok-ow'-to-mah","pos":"Noun Neuter","thayer":"<ol><li>a whole burnt offering<ol type='a'><li>a victim the whole (and not like other victims only a part) of which was burned</li></ol></li></ol>","xlit":"holokaútōma"},"G2903":{"derivation":"superlative of a derivative of G2904 (κράτος);","strongs_def":" strongest, i.e. (in dignity) very honorable","kjv_def":"most excellent (noble)","lemma":"κράτιστος","translit":"krátistos","pron":"krat'-is-tos","pos":"Adjective","thayer":"<ol><li>mightiest, strongest, noblest, most illustrious, best, most excellent<ol type='a'><li>used in addressing men of prominent rank or office</li></ol></li></ol>","xlit":"krátistos"},"G1486":{"strongs_def":" to be used (by habit or conventionality); neuter perfect participle usage","derivation":"a primary verb;","lemma":"ἔθω","translit":"éthō","kjv_def":"be custom (manner, wont)","pron":"eth'-o","pos":"Verb","thayer":"<ol><li>to be accustomed, used, wont</li><li>that which is wont</li><li>usage, custom</li></ol>","xlit":"éthō"},"G3631":{"strongs_def":" \"wine\" (literally or figuratively)","derivation":"a primary word (or perhaps of Hebrew origin (H03196));","translit":"oînos","lemma":"οἶνος","kjv_def":"wine","pron":"oy'-nos","pos":"Noun Masculine","thayer":"<ol><li>wine</li><li>metaphorically fiery wine of God's wrath</li></ol>","xlit":"oînos"},"G1853":{"kjv_def":"X out of sleep","lemma":"ἔξυπνος","translit":"éxypnos","derivation":"from G1537 (ἐκ) and G5258 (ὕπνος);","strongs_def":" awake","pron":"ex'-oop-nos","pos":"Adjective","thayer":"<ol><li>roused out of a sleep</li></ol>","xlit":"éxypnos"},"G2526":{"derivation":"from G2596 (κατά) and G3739 (ὅς);","strongs_def":" according to which thing, i.e. precisely as, in proportion as","kjv_def":"according to that, (inasmuch) as","lemma":"καθό","translit":"kathó","pron":"kath-o'","pos":"Adverb","thayer":"<ol><li>according to what<ol type='a'><li>as</li><li>according as, in so far as, so far forth as</li></ol></li></ol>","xlit":"kathó"},"G2579":{"kjv_def":"and (also) if (so much as), if but, at the least, though, yet","lemma":"κἄν","translit":"kán","derivation":"from G2532 (καί) and G1437 (ἐάν);","strongs_def":" and (or even) if","pron":"kan","thayer":"<ol><li>and if</li><li>also or even if<ol type='a'><li>of only, at least</li><li>even if</li></ol></li></ol>","xlit":"kán"},"G746":{"derivation":"from G756 (ἄρχομαι);","strongs_def":" (properly abstract) a commencement, or (concretely) chief (in various applications of order, time, place, or rank)","kjv_def":"beginning, corner, (at the, the) first (estate), magistrate, power, principality, principle, rule","lemma":"ἀρχή","translit":"archḗ","pron":"ar-khay'","pos":"Noun Feminine","thayer":"<ol><li>beginning, origin</li><li>the person or thing that commences, the first person or thing in a series, the leader</li><li>that by which anything begins to be, the origin, the active cause</li><li>the extremity of a thing<ol type='a'><li>of the corners of a sail</li></ol><li>the first place, principality, rule, magistracy<ol type='a'><li>of angels and demons</li></ol></li></ol>","xlit":"archḗ"},"G1095":{"derivation":"from G1094 (γῆρας);","strongs_def":" to be senescent","kjv_def":"be (wax) old","lemma":"γηράσκω","translit":"gēráskō","pron":"ghay-ras'-ko","pos":"Verb","thayer":"<ol><li>to grow old</li><li>of things and institutions: to fail from age, be obsolescent</li></ol>","xlit":"gēráskō"},"G3676":{"derivation":"adverb from the base of G3674 (ὁμοῦ);","strongs_def":" at the same time, i.e. (conjunctionally) notwithstanding, yet still","kjv_def":"and even, nevertheless, though but","translit":"hómōs","lemma":"ὅμως","pron":"hom'-oce","pos":"Adverb","thayer":"<ol><li>nevertheless, yet</li></ol>","xlit":"hómōs"},"G3132":{"derivation":"from a derivative of G3105 (μαίνομαι) (meaning a prophet, as supposed to rave through inspiration);","strongs_def":" to divine, i.e. utter spells (under pretense of foretelling","kjv_def":"by soothsaying","translit":"manteúomai","lemma":"μαντεύομαι","pron":"mant-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to act as a seer<ol type='a'><li>deliver an oracle, prophesy, divine</li></ol></li></ol>","xlit":"manteúomai"},"G2735":{"derivation":"from a compound of G2596 (κατά) and a derivative of G3717 (ὀρθός) (compare G1357 (διόρθωσις));","strongs_def":" something made fully upright, i.e. (figuratively) rectification (specially, good public administration)","kjv_def":"very worthy deed","translit":"katórthōma","lemma":"κατόρθωμα","pron":"kat-or'-tho-mah","pos":"Noun Neuter","thayer":"<ol><li>a right action, a successful achievement<ol type='a'><li>of wholesome public measures or institutions</li></ol></li></ol>","xlit":"katórthōma"},"G4305":{"derivation":"from G4253 (πρό) and G3309 (μεριμνάω);","strongs_def":" to care (anxiously) in advance","kjv_def":"take thought beforehand","lemma":"προμεριμνάω","translit":"promerimnáō","pron":"prom-er-im-nah'-o","pos":"Verb","thayer":"<ol><li>to be anxious beforehand</li></ol>","xlit":"promerimnáō"},"G169":{"kjv_def":"foul, unclean","translit":"akáthartos","lemma":"ἀκάθαρτος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G2508 (καθαίρω) (meaning cleansed);","strongs_def":" impure (ceremonially, morally (lewd) or specially, (demonic))","pron":"ak-ath'-ar-tos","pos":"Adjective","thayer":"<ol><li>not cleansed, unclean<ol type='a'><li>in a ceremonial sense: that which must be abstained from according to the levitical law</li><li>in a moral sense: unclean in thought and life</li></ol></li></ol>","xlit":"akáthartos"},"G1813":{"strongs_def":" to smear out, i.e. obliterate (erase tears, figuratively, pardon sin)","derivation":"from G1537 (ἐκ) and G218 (ἀλείφω);","translit":"exaleíphō","lemma":"ἐξαλείφω","kjv_def":"blot out, wipe away","pron":"ex-al-i'-fo","pos":"Verb","thayer":"<ol><li>to anoint or wash in every part<ol type='a'><li>to besmear: i.e. cover with lime (to whitewash or plaster)</li></ol><li>to wipe off, wipe away<ol type='a'><li>to obliterate, erase, wipe out, blot out</li></ol></li></ol>","xlit":"exaleíphō"},"G1862":{"kjv_def":"promise","translit":"epángelma","lemma":"ἐπάγγελμα","derivation":"from G1861 (ἐπαγγέλλω);","strongs_def":" a self-committal (by assurance of conferring some good)","pron":"ep-ang'-el-mah","pos":"Noun Neuter","thayer":"<ol><li>a promise</li></ol>","xlit":"epángelma"},"G944":{"derivation":"of uncertain derivation;","strongs_def":" a frog","kjv_def":"frog","lemma":"βάτραχος","translit":"bátrachos","pron":"bat'-rakh-os","pos":"Noun Masculine","thayer":"<ol><li>a frog</li></ol>","xlit":"bátrachos"},"G157":{"lemma":"αἰτίαμα","translit":"aitíama","kjv_def":"complaint","strongs_def":" a thing charged","derivation":"from a derivative of G156 (αἰτία);","pron":"ahee-tee'-am-ah","pos":"Noun Neuter","thayer":"<ol><li>to accuse, bring a charge against, complaint</li></ol>","xlit":"aitíama"},"G790":{"kjv_def":"have no certain dwelling-place","lemma":"ἀστατέω","translit":"astatéō","derivation":"from G1 (Α) (as a negative particle) and a derivative of G2476 (ἵστημι);","strongs_def":" to be non-stationary, i.e. (figuratively) homeless","pron":"as-tat-eh'-o","pos":"Verb","thayer":"<ol><li>to wander about, to rove without a settled abode</li></ol>","xlit":"astatéō"},"G616":{"derivation":"from G575 (ἀπό) and the base of G2949 (κῦμα);","strongs_def":" to breed forth, i.e. (by transference) to generate (figuratively)","kjv_def":"beget, produce","lemma":"ἀποκυέω","translit":"apokyéō","pron":"ap-ok-oo-eh'-o","pos":"Verb","thayer":"<ol><li>to bring forth<ol type='a'><li>from the womb</li><li>give birth to</li></ol><li>produce</li></ol>","xlit":"apokyéō"},"G636":{"derivation":"from G575 (ἀπό) and G4126 (πλέω);","strongs_def":" to set sail","kjv_def":"sail away","translit":"apopléō","lemma":"ἀποπλέω","pron":"ap-op-leh'-o","pos":"Verb","thayer":"<ol><li>to sail away, depart by ship, set sail</li></ol>","xlit":"apopléō"},"G957":{"kjv_def":"very well","lemma":"βελτίον","translit":"beltíon","derivation":"neuter of a compound of a derivative of G906 (βάλλω) (used for the comparative of G18 (ἀγαθός));","strongs_def":" better","pron":"bel-tee'-on","pos":"Adjective","thayer":"<ol><li>better</li></ol>","xlit":"beltíon"},"G621":{"lemma":"ἀπολείχω","translit":"apoleíchō","kjv_def":"lick","strongs_def":" to lick clean","derivation":"from G575 (ἀπό) and (to \"lick\");","pron":"ap-ol-i'-kho","pos":"Verb","thayer":"<ol><li>to lick off, lick up</li></ol>","xlit":"apoleíchō"},"G1609":{"kjv_def":"reject","lemma":"ἐκπτύω","translit":"ekptýō","derivation":"from G1537 (ἐκ) and G4429 (πτύω);","strongs_def":" to spit out, i.e. (figuratively) spurn","pron":"ek-ptoo'-o","pos":"Verb","thayer":"<ol><li>to spit out</li><li>reject, spurn, loathe</li></ol>","xlit":"ekptýō"},"G2565":{"kjv_def":"good olive tree","translit":"kalliélaios","lemma":"καλλιέλαιος","derivation":"from the base of G2566 (καλλίον) and G1636 (ἐλαία);","strongs_def":" a cultivated olive tree, i.e. a domesticated or improved one","pron":"kal-le-el'-ah-yos","pos":"Noun Feminine","thayer":"<ol><li>the garden olive as opposed to the wild olive</li></ol>","xlit":"kalliélaios"},"G375":{"kjv_def":"send (again)","translit":"anapémpō","lemma":"ἀναπέμπω","derivation":"from G303 (ἀνά) and G3992 (πέμπω);","strongs_def":" to send up or back","pron":"an-ap-em'-po","pos":"Verb","thayer":"<ol><li>to send up<ol type='a'><li>to a higher place</li><li>to a person higher in office, authority, or power</li></ol><li>to send back</li></ol>","xlit":"anapémpō"},"G1823":{"derivation":"from G1537 (ἐκ) and G797 (ἀστράπτω);","strongs_def":" to lighten forth, i.e. (figuratively) to be radiant (of very white garments)","kjv_def":"glistening","translit":"exastráptō","lemma":"ἐξαστράπτω","pron":"ex-as-trap'-to","pos":"Verb","thayer":"<ol><li>to send forth lightning, to lighten</li><li>to flash out like lightning, to shine, be radiant<ol type='a'><li>of garments</li></ol></li></ol>","xlit":"exastráptō"},"G2417":{"strongs_def":" a temple-despoiler","derivation":"from G2411 (ἱερόν) and G4813 (συλάω);","translit":"hierósylos","lemma":"ἱερόσυλος","kjv_def":"robber of churches","pron":"hee-er-os'-oo-los","pos":"Noun Masculine","thayer":"<ol><li>guilty of sacrilege</li></ol>","xlit":"hierósylos"},"G1766":{"derivation":"ordinal from G1767 (ἐννέα);","strongs_def":" ninth","kjv_def":"ninth","translit":"énnatos","lemma":"ἔννατος","pron":"en'-nat-os","pos":"Adjective","thayer":"<ol><li>ninth<ol type='a'><li>the ninth hour corresponds to our 3 o'clock in the afternoon for the sixth hour of the Jews coincides with the twelfth of the day as divided by our method, and the first hour of the day is 6 A.M. to us</li></ol></li></ol>","xlit":"énnatos"},"G1320":{"strongs_def":" an instructor (genitive case or specially)","derivation":"from G1321 (διδάσκω);","lemma":"διδάσκαλος","translit":"didáskalos","kjv_def":"doctor, master, teacher","pron":"did-as'-kal-os","pos":"Noun Masculine","thayer":"<ol><li>a teacher</li><li>in the NT one who teaches concerning the things of God, and the duties of man<ol type='a'><li>one who is fitted to teach, or thinks himself so</li><li>the teachers of the Jewish religion</li><li>of those who by their great power as teachers draw crowds around them, i.e. John the Baptist, Jesus</li><li>by preeminence used of Jesus by himself, as one who showed men the way of salvation</li><li>of the apostles, and of Paul</li><li>of those who in the religious assemblies of the Christians, undertook the work of teaching, with the special assistance of the Holy Spirit</li><li>of false teachers among Christians</li></ol></li></ol>","xlit":"didáskalos"},"G5443":{"kjv_def":"kindred, tribe","lemma":"φυλή","translit":"phylḗ","derivation":"from G5453 (φύω) (compare G5444 (φύλλον));","strongs_def":" an offshoot, i.e. race or clan","pron":"foo-lay'","pos":"Noun Feminine","thayer":"<ol><li>a tribe<ol type='a'><li>in the NT all the persons descending from one of the twelve sons of the patriarch, Jacob</li></ol><li>a nation, people</li></ol>","xlit":"phylḗ"},"G2622":{"lemma":"κατακλάω","translit":"katakláō","kjv_def":"break","strongs_def":" to break down, i.e. divide","derivation":"from G2596 (κατά) and G2806 (κλάω);","pron":"kat-ak-lah'-o","pos":"Verb","thayer":"<ol><li>to break in pieces</li></ol>","xlit":"katakláō"},"G3659":{"kjv_def":"eye","translit":"ómma","lemma":"ὄμμα","derivation":"from G3700 (ὀπτάνομαι);","strongs_def":" a sight, i.e. (by implication) the eye","pron":"om'-mah","pos":"Noun Neuter","thayer":"<ol><li>an eye</li></ol>","xlit":"ómma"},"G1220":{"kjv_def":"pence, penny(-worth)","lemma":"δηνάριον","translit":"dēnárion","derivation":"of Latin origin;","strongs_def":" a denarius (or ten asses)","pron":"day-nar'-ee-on","pos":"Noun Neuter","thayer":"<strong>Thayer Definition</strong>: denarius = \"containing ten\"</p><ol><li>A Roman silver coin in NT time. It took its name from it being equal to ten \"asses\" , a number after 217 B.C. increased to sixteen (about 3.898 grams or .1375 oz.). It was the principal silver coin of the Roman empire. From the parable of the labourers in the vineyard, it would seem that a denarius was then the ordinary pay for a day's wages. (<a class='bible' href='#b40.20.2-13'>Mat 20:2-13</a>)</li></ol>","xlit":"dēnárion"},"G326":{"kjv_def":"(be a-)live again, revive","translit":"anazáō","lemma":"ἀναζάω","derivation":"from G303 (ἀνά) and G2198 (ζάω);","strongs_def":" to recover life (literally or figuratively)","pron":"an-ad-zah'-o","pos":"Verb","thayer":"<ol><li>live again, recover life<ol type='a'><li>to be restored to a correct life<ol><li>of one who returns to a better moral state</li></ol><li>to revive, regain strength and vigour</li></ol></li></ol>","xlit":"anazáō"},"G5069":{"derivation":"neuter of a presumed derivative of (a tetrad;","strongs_def":" from G5064 (τέσσαρες)); a quaternion or squad (picket) of four Roman soldiers","kjv_def":"quaternion","lemma":"τετράδιον","translit":"tetrádion","pron":"tet-rad'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a quaternion</li></ol>","xlit":"tetrádion"},"G1892":{"kjv_def":"raise, stir up","lemma":"ἐπεγείρω","translit":"epegeírō","derivation":"from G1909 (ἐπί) and G1453 (ἐγείρω);","strongs_def":" to rouse upon, i.e. (figuratively) to excite against","pron":"ep-eg-i'-ro","pos":"Verb","thayer":"<ol><li>to raise or excite against</li></ol>","xlit":"epegeírō"},"G3817":{"strongs_def":" to hit (as if by a single blow and less violently than G5180 (τύπτω)); specially, to sting (as a scorpion)","derivation":"a primary verb;","lemma":"παίω","translit":"paíō","kjv_def":"smite, strike","pron":"pah'-yo","thayer":"<ol><li>to strike, smite</li><li>to sting (to strike or wound with a sting)</li></ol>","xlit":"paíō"},"G1757":{"strongs_def":" to confer a benefit on","derivation":"from G1722 (ἐν) and G2127 (εὐλογέω);","lemma":"ἐνευλογέω","translit":"eneulogéō","kjv_def":"bless","pron":"en-yoo-log-eh'-o","pos":"Verb","thayer":"<ol><li>to confer benefits on, to bless</li></ol>","xlit":"eneulogéō"},"G3914":{"strongs_def":" to winter near, i.e. stay with over the rainy season","derivation":"from G3844 (παρά) and G5492 (χειμάζω);","lemma":"παραχειμάζω","translit":"paracheimázō","kjv_def":"winter","pron":"par-akh-i-mad'-zo","pos":"Verb","thayer":"<ol><li>to winter, pass the winter, with one or at a place</li></ol>","xlit":"paracheimázō"},"G653":{"lemma":"ἀποστοματίζω","translit":"apostomatízō","kjv_def":"provoke to speak","strongs_def":" to speak off-hand (properly, dictate), i.e. to catechize (in an invidious manner)","derivation":"from G575 (ἀπό) and a (presumed) derivative of G4750 (στόμα);","pron":"ap-os-tom-at-id'-zo","pos":"Verb","thayer":"<ol><li>to recite from memory<ol type='a'><li>to repeat to a pupil (anything) for him to commit to memory</li></ol><li>to ply with questions, to catechise, and so to entice to answers</li></ol>","xlit":"apostomatízō"},"G285":{"derivation":"perhaps from G260 (ἅμα);","strongs_def":" sand (as heaped on the beach)","kjv_def":"sand","lemma":"ἄμμος","translit":"ámmos","pron":"am'-mos","pos":"Noun Feminine","thayer":"<ol><li>sand, sandy ground</li></ol>","xlit":"ámmos"},"G1584":{"derivation":"from G1537 (ἐκ) and G2989 (λάμπω);","strongs_def":" to be resplendent","kjv_def":"shine forth","lemma":"ἐκλάμπω","translit":"eklámpō","pron":"ek-lam'-po","pos":"Verb","thayer":"<ol><li>to shine forth</li></ol>","xlit":"eklámpō"},"G4":{"strongs_def":" weightless, i.e. (figuratively) not burdensome","derivation":"from G1 (Α) (as a negative particle) and G922 (βάρος);","lemma":"ἀβαρής","translit":"abarḗs","kjv_def":"from being burdensome","pron":"ab-ar-ace'","pos":"Adjective","thayer":"<ol><li>not burdensome</li><li>not heavy</li><li>light without weight</li></ol>","xlit":"abarḗs"},"G4814":{"kjv_def":"commune (confer, talk) with, speak among","translit":"syllaléō","lemma":"συλλαλέω","derivation":"from G4862 (σύν) and G2980 (λαλέω);","strongs_def":" to talk together, i.e. converse","pron":"sool-lal-eh'-o","pos":"Verb","thayer":"<ol><li>to talk with</li></ol>","xlit":"syllaléō"},"G4277":{"strongs_def":" to say already, to predict","derivation":"from G4253 (πρό) and G2036 (ἔπω);","translit":"proépō","lemma":"προέπω","kjv_def":"forewarn, say (speak, tell) before","pron":"pro-ep'-o","pos":"Verb","thayer":"<ol><li>to say before<ol type='a'><li>to say in what precedes, to say above</li><li>to say before, i.e. heretofore, formerly</li><li>to say beforehand, i.e. before the event: prophecies</li></ol></li></ol>","xlit":"proépō"},"G2504":{"strongs_def":" so also the dative case , and accusative case and (or also, even, etc.) I, (to) me","derivation":"from G2532 (καί) and G1473 (ἐγώ);","translit":"kagṓ","lemma":"κἀγώ","kjv_def":"(and, even, even so, so) I (also, in like wise), both me, me also","pron":"kag-o'","pos":"Conjunction","thayer":"<ol><li>and I</li><li>I also, I as well, I likewise, in like manner I</li><li>even I, this selfsame I</li></ol>","xlit":"kagṓ"},"G1637":{"lemma":"ἔλαιον","translit":"élaion","kjv_def":"oil","strongs_def":" olive oil","derivation":"neuter of the same as G1636 (ἐλαία);","pron":"el'-ah-yon","pos":"Noun Neuter","thayer":"<ol><li>olive oil<ol type='a'><li>for fuel for lamps</li><li>for healing the sick</li><li>for anointing the head and body at feasts</li><li>mentioned among articles of commerce</li></ol></li></ol>","xlit":"élaion"},"G3039":{"derivation":"from , the equivalent of (a winnowing fan or basket);","strongs_def":" to winnow, i.e. (by analogy), to triturate","kjv_def":"grind to powder","lemma":"λικμάω","translit":"likmáō","pron":"lik-mah'-o","pos":"Verb","thayer":"<ol><li>to winnow, cleanse away the chaff from the grain by winnowing</li><li>to scatter</li><li>to crush to pieces, grind to powder</li></ol>","xlit":"likmáō"},"G4030":{"strongs_def":" encirclement of the head, i.e. a helmet","derivation":"feminine of a compound of G4012 (περί) and G2776 (κεφαλή);","lemma":"περικεφαλαία","translit":"perikephalaía","kjv_def":"helmet","pron":"per-ee-kef-al-ah'-yah","pos":"Noun Feminine","thayer":"<ol><li>a helmet</li><li>metaphorically<ol type='a'><li>the protection of the soul which consists in (the hope of) salvation</li></ol></li></ol>","xlit":"perikephalaía"},"G1665":{"translit":"Elisábet","lemma":"Ἐλισάβετ","kjv_def":"Elisabeth","strongs_def":" Elisabet, an Israelitess","derivation":"of Hebrew origin (H0472);","pron":"el-ee-sab'-et","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Elisabeth = \"oath of God\"</p><ol><li>the wife of Zacharias and mother of John the Baptist, of the priestly family, and a relative of Mary, <a class='bible' href='#b42.1.36'>Luk 1:36</a></li></ol>","xlit":"Elisábet"},"G1699":{"kjv_def":"of me, mine (own), my","lemma":"ἐμός","translit":"emós","derivation":"from the oblique cases of G1473 (ἐγώ) (G1698 (ἐμοί), G1700 (ἐμοῦ), G1691 (ἐμέ));","strongs_def":" my","pron":"em-os'","thayer":"<ol><li>my, mine, etc.</li></ol>","xlit":"emós"},"G3880":{"derivation":"from G3844 (παρά) and G2983 (λαμβάνω);","strongs_def":" to receive near, i.e. associate with oneself (in any familiar or intimate act or relation); by analogy, to assume an office; figuratively, to learn","kjv_def":"receive, take (unto, with)","lemma":"παραλαμβάνω","translit":"paralambánō","pron":"par-al-am-ban'-o","pos":"Verb","thayer":"<ol><li>to take to, to take with one's self, to join to one's self<ol type='a'><li>an associate, a companion</li><li>metaphorically<ol><li>to accept or acknowledge one to be such as he professes to be</li><li>not to reject, not to withhold obedience</li></ol></li></ol><li>to receive something transmitted<ol type='a'><li>an office to be discharged</li><li>to receive with the mind<ol><li>by oral transmission: of the authors from whom the tradition proceeds</li><li>by the narrating to others, by instruction of teachers (used of disciples)</li></ol></li></ol></li></ol>","xlit":"paralambánō"},"G5397":{"lemma":"φλύαρος","translit":"phlýaros","kjv_def":"tattler","strongs_def":" a garrulous person, i.e. prater","derivation":"from (to bubble);","pron":"floo'-ar-os","pos":"Adjective","thayer":"<ol><li>of persons uttering or doing silly things, garrulous, babbling</li><li>of things, foolish, trifling, vain</li></ol>","xlit":"phlýaros"},"G102":{"kjv_def":"could not do, impossible, impotent, not possible, weak","translit":"adýnatos","lemma":"ἀδύνατος","derivation":"from G1 (Α) (as a negative particle) and G1415 (δυνατός);","strongs_def":" unable, i.e. weak (literally or figuratively); passively, impossible","pron":"ad-oo'-nat-os","pos":"Adjective","thayer":"<ol><li>without strength, impotent, powerless, weakly, disabled</li><li>unable to be done, impossible</li></ol>","xlit":"adýnatos"},"G62":{"lemma":"ἀγράμματος","translit":"agrámmatos","kjv_def":"unlearned","strongs_def":" unlettered, i.e. illiterate","derivation":"from G1 (Α) (as negative particle) and G1121 (γράμμα);","pron":"ag-ram-mat-os","pos":"Adjective","thayer":"<ol><li>illiterate, unlearned</li></ol>","xlit":"agrámmatos"},"G117":{"lemma":"Ἀθηναῖος","translit":"Athēnaîos","kjv_def":"Athenian","strongs_def":" an Athenæan or inhabitant of Athenæ","derivation":"from G116 (Ἀθῆναι);","pron":"ath-ay-nah'-yos","pos":"Adjective","thayer":"<ol><li>a person who lives in Athens, an Athenian</li></ol>","xlit":"Athēnaîos"},"G763":{"derivation":"from G765 (ἀσεβής);","strongs_def":" impiety, i.e. (by implication) wickedness","kjv_def":"ungodly(-liness)","translit":"asébeia","lemma":"ἀσέβεια","pron":"as-eb'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>want of reverence towards God, impiety, ungodliness</li></ol>","xlit":"asébeia"},"G1880":{"translit":"epanérchomai","lemma":"ἐπανέρχομαι","kjv_def":"come again, return","strongs_def":" to come up on, i.e. return","derivation":"from G1909 (ἐπί) and G424 (ἀνέρχομαι);","pron":"ep-an-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to return, come back again</li></ol>","xlit":"epanérchomai"},"G129":{"derivation":"of uncertain derivation;","strongs_def":" blood, literally (of men or animals), figuratively (the juice of grapes) or specially (the atoning blood of Christ); by implication, bloodshed, also kindred","kjv_def":"blood","translit":"haîma","lemma":"αἷμα","pron":"hah'-ee-mah","pos":"Noun Masculine","thayer":"<ol><li>blood<ol type='a'><li>of man or animals</li><li>refers to the seat of life</li><li>of those things that resemble blood, grape juice</li></ol><li>blood shed, to be shed by violence, slay, murder</li></ol>","xlit":"haîma"},"G5055":{"translit":"teléō","lemma":"τελέω","kjv_def":"accomplish, make an end, expire, fill up, finish, go over, pay, perform","strongs_def":" to end, i.e. complete, execute, conclude, discharge (a debt)","derivation":"from G5056 (τέλος);","pron":"tel-eh'-o","pos":"Verb","thayer":"<ol><li>to bring to a close, to finish, to end<ol type='a'><li>passed, finished</li></ol><li>to perform, execute, complete, fulfil, (so that the thing done corresponds to what has been said, the order, command etc.)<ol type='a'><li>with special reference to the subject matter, to carry out the contents of a command</li><li>with reference also to the form, to do just as commanded, and generally involving the notion of time, to perform the last act which completes a process, to accomplish, fulfil</li></ol><li>to pay<ol type='a'><li>of tribute</li></ol></li></ol>","xlit":"teléō"},"G3397":{"kjv_def":"a (little) (while)","translit":"mikrón","lemma":"μικρόν","derivation":"masculine or neuter singular of G3398 (μικρός) (as noun);","strongs_def":" a small space of time or degree","pron":"mik-ron'","pos":"Adjective","thayer":"<ol><li>small, little<ol type='a'><li>of size: of stature, of length</li><li>of space</li><li>of age: less by birth, younger</li><li>of time: short, brief, a little while, how little!</li><li>of quantity: i.e. number, amount</li><li>of rank or influence</li></ol></li></ol>","xlit":"mikrón"},"G98":{"derivation":"from (a place in Asia Minor);","strongs_def":" Adramyttene or belonging to Adramyttium","kjv_def":"of Adramyttium","translit":"Adramyttēnós","lemma":"Ἀδραμυττηνός","pron":"ad-ram-oot-tay-nos'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Adramyttium = \"I shall abide in death\"</p><ol><li>Adramyttium, a seaport of Mysia</li></ol>","xlit":"Adramyttēnós"},"G1186":{"derivation":"probably from (an oak);","strongs_def":" a tree","kjv_def":"tree","translit":"déndron","lemma":"δένδρον","pron":"den'-dron","pos":"Noun Neuter","thayer":"<ol><li>a tree</li></ol>","xlit":"déndron"},"G3043":{"translit":"línon","lemma":"λίνον","kjv_def":"linen","strongs_def":" flax, i.e. (by implication) \"linen\"","derivation":"probably a primary word;","pron":"lee'-non","pos":"Noun Neuter","thayer":"<ol><li>linen clothing made from flax</li></ol>","xlit":"línon"},"G3809":{"kjv_def":"chastening, chastisement, instruction, nurture","translit":"paideía","lemma":"παιδεία","derivation":"from G3811 (παιδεύω);","strongs_def":" tutorage, i.e. education or training; by implication, disciplinary correction","pron":"pahee-di'-ah","pos":"Noun Feminine","thayer":"<ol><li>the whole training and education of children (which relates to the cultivation of mind and morals, and employs for this purpose now commands and admonitions, now reproof and punishment) It also includes the training and care of the body</li><li>whatever in adults also cultivates the soul, especially by correcting mistakes and curbing passions.<ol type='a'><li>instruction which aims at increasing virtue</li><li>chastisement, chastening, (of the evils with which God visits men for their amendment)</li></ol></li></ol>","xlit":"paideía"},"G3700":{"derivation":"a (middle voice) prolonged form of the primary (middle voice) ; which is used for it in certain tenses; and both as alternate of G3708 (ὁράω);","strongs_def":" to gaze (i.e. with wide-open eyes, as at something remarkable; and thus differing from G991 (βλέπω), which denotes simply voluntary observation; and from G1492 (εἴδω), which expresses merely mechanical, passive or casual vision; while G2300 (θεάομαι), and still more emphatically its intensive G2334 (θεωρέω), signifies an earnest but more continued inspection; and G4648 (σκοπέω) a watching from a distance)","kjv_def":"appear, look, see, shew self","translit":"optánomai","lemma":"ὀπτάνομαι","pron":"op-tan'-om-ahee","pos":"Verb","thayer":"<ol><li>to look at, behold</li><li>to allow one's self to be seen, to appear</li></ol>","xlit":"optánomai"},"G85":{"kjv_def":"be full of heaviness, be very heavy","translit":"adēmonéō","lemma":"ἀδημονέω","derivation":"from a derivative of (to be sated to loathing);","strongs_def":" to be in distress (of mind)","pron":"ad-ay-mon-eh'-o","pos":"Verb","thayer":"<ol><li>to be troubled, great distress or anguish, depressed</li></ol>","xlit":"adēmonéō"},"G4516":{"strongs_def":" strength; Roma, the capital of Italy","derivation":"from the base of G4517 (ῥώννυμι);","lemma":"Ῥώμη","translit":"Rhṓmē","kjv_def":"Rome","pron":"hro'-may","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Rome = \"strength\"</p><ol><li>the famous capital of the ancient world</li></ol>","xlit":"Rhṓmē"},"G4711":{"derivation":"from G4687 (σπείρω) (as woven);","strongs_def":" a hamper or lunch-receptacle","kjv_def":"basket","lemma":"σπυρίς","translit":"spyrís","pron":"spoo-rece'","pos":"Noun Feminine","thayer":"<ol><li>a reed basket, (a plaited basket, a lunch basket, hamper)</li></ol>","xlit":"spyrís"},"G2956":{"strongs_def":" i.e. Cyrenæan, i.e. inhabitant of Cyrene","derivation":"from G2957 (Κυρήνη);","translit":"Kyrēnaîos","lemma":"Κυρηναῖος","kjv_def":"of Cyrene, Cyrenian","pron":"koo-ray-nah'-yos","pos":"Noun Masculine","thayer":"<ol><li>a native of Cyrene</li></ol>","xlit":"Kyrēnaîos"},"G3644":{"kjv_def":"destroyer","lemma":"ὀλοθρευτής","translit":"olothreutḗs","derivation":"from G3645 (ὀλοθρεύω);","strongs_def":" a ruiner, i.e. (specially), a venomous serpent","pron":"ol-oth-ryoo-tace'","pos":"Noun Masculine","thayer":"<ol><li>a destroyer</li></ol>","xlit":"olothreutḗs"},"G1176":{"translit":"déka","lemma":"δέκα","kjv_def":"(eight-)een, ten","strongs_def":" ten","derivation":"a primary number;","pron":"dek'-ah","pos":"Noun","thayer":"<ol><li>ten</li></ol>","xlit":"déka"},"G1595":{"translit":"hekoúsion","lemma":"ἑκούσιον","kjv_def":"willingly","strongs_def":" voluntariness","derivation":"neuter of a derivative from G1635 (ἑκών);","pron":"hek-oo'-see-on","pos":"Adjective","thayer":"<ol><li>voluntary</li></ol>","xlit":"hekoúsion"},"G2328":{"kjv_def":"(be) warm(-ed, self)","translit":"thermaínō","lemma":"θερμαίνω","derivation":"from G2329 (θέρμη);","strongs_def":" to heat (oneself)","pron":"ther-mah'-ee-no","pos":"Verb","thayer":"<ol><li>to make warm, to heat</li><li>to warm one's self</li></ol>","xlit":"thermaínō"},"G5509":{"translit":"chitṓn","lemma":"χιτών","kjv_def":"clothes, coat, garment","strongs_def":" a tunic or shirt","derivation":"of foreign origin (H03801);","pron":"khee-tone'","pos":"Noun Masculine","thayer":"<ol><li>a tunic, an undergarment, usually worn next to the skin, a garment, a vestment</li></ol>","xlit":"chitṓn"},"G4719":{"kjv_def":"ear (of corn)","translit":"stáchys","lemma":"στάχυς","derivation":"from the base of G2476 (ἵστημι);","strongs_def":" a head of grain (as standing out from the stalk)","pron":"stakh'-oos","pos":"Noun Masculine","thayer":"<ol><li>an ear of corn or of growing grain</li></ol>","xlit":"stáchys"},"G345":{"derivation":"from G303 (ἀνά) and G2749 (κεῖμαι);","strongs_def":" to recline (as a corpse or at a meal)","kjv_def":"guest, lean, lie, sit (down, at meat), at the table","lemma":"ἀνακεῖμαι","translit":"anakeîmai","pron":"an-ak-i'-mahee","pos":"Verb","thayer":"<ol><li>to lie at a table, eat together, dine</li></ol>","xlit":"anakeîmai"},"G4169":{"lemma":"ποῖος","translit":"poîos","kjv_def":"what (manner of), which","strongs_def":" individualizing interrogative (of character) what sort of, or (of number) which one","derivation":"from the base of G4226 (ποῦ) and G3634 (οἷος);","pron":"poy'-os","thayer":"<ol><li>of what sort or nature</li></ol>","xlit":"poîos"},"G2896":{"strongs_def":" properly, to \"croak\" (as a raven) or scream, i.e. (genitive case) to call aloud (shriek, exclaim, intreat)","derivation":"a primary verb;","translit":"krázō","lemma":"κράζω","kjv_def":"cry (out)","pron":"krad'-zo","pos":"Verb","thayer":"<ol><li>to croak<ol type='a'><li>of the cry of a raven</li><li>hence, to cry out, cry aloud, vociferate</li><li>to cry or pray for vengeance</li></ol><li>to cry<ol type='a'><li>cry out aloud, speak with a loud voice</li></ol></li></ol>","xlit":"krázō"},"G669":{"derivation":"from G575 (ἀπό) and G5350 (φθέγγομαι);","strongs_def":" to enunciate plainly, i.e. declare","kjv_def":"say, speak forth, utterance","lemma":"ἀποφθέγγομαι","translit":"apophthéngomai","pron":"ap-of-theng'-om-ahee","pos":"Verb","thayer":"<ol><li>to speak out, speak forth, pronounce<ol type='a'><li>not a word of everyday speech but one \"belonging to dignified and elevated discourse\"</li></ol></li></ol>","xlit":"apophthéngomai"},"G2771":{"lemma":"κέρδος","translit":"kérdos","kjv_def":"gain, lucre","strongs_def":" gain (pecuniary or genitive case)","derivation":"of uncertain affinity;","pron":"ker'-dos","pos":"Noun Neuter","thayer":"<ol><li>gain, advantage</li></ol>","xlit":"kérdos"},"G1946":{"strongs_def":" an Epicurean or follower of Epicurus","derivation":"from (compare G1947 (ἐπικουρία)) (a noted philosopher);","translit":"Epikoúreios","lemma":"Ἐπικούρειος","kjv_def":"Epicurean","pron":"ep-ee-koo'-ri-os","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Epicurean = \"a helper: defender\"</p><ol><li>belonging to the sect of Epicurius, the philosopher</li></ol>","xlit":"Epikoúreios"},"G3966":{"derivation":"from G3965 (πατριά) and G757 (ἄρχω);","strongs_def":" a progenitor (\"patriarch\")","kjv_def":"patriarch","lemma":"πατριάρχης","translit":"patriárchēs","pron":"pat-ree-arkh'-ace","pos":"Noun Masculine","thayer":"<ol><li>patriarch, founder of a tribe, progenitor<ol type='a'><li>of the twelve sons of Jacob, founders of the tribes of Israel</li><li>of Abraham, Isaac and Jacob</li></ol></li></ol>","xlit":"patriárchēs"},"G150":{"kjv_def":"filthy","lemma":"αἰσχρός","translit":"aischrós","derivation":"from the same as G153 (αἰσχύνομαι);","strongs_def":" shameful, i.e. base (specially, venal)","pron":"ahee-skhros'","pos":"Adjective","thayer":"<ol><li>filthy, baseness, dishonour</li></ol>","xlit":"aischrós"},"G422":{"kjv_def":"--that needeth not to be ashamed","translit":"anepaíschyntos","lemma":"ἀνεπαίσχυντος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of a compound of G1909 (ἐπί) and G153 (αἰσχύνομαι);","strongs_def":" not ashamed, i.e. irreprehensible: ","pron":"an-ep-ah'-ee-skhoon-tos","pos":"Adjective","thayer":"<ol><li>having no cause to be ashamed</li></ol>","xlit":"anepaíschyntos"},"G1961":{"derivation":"from G1909 (ἐπί) and G3306 (μένω);","strongs_def":" to stay over, i.e. remain (figuratively, persevere)","kjv_def":"abide (in), continue (in), tarry","translit":"epiménō","lemma":"ἐπιμένω","pron":"ep-ee-men'-o","pos":"Verb","thayer":"<ol><li>to stay at or with, to tarry still, still to abide, to continue, remain<ol type='a'><li>of tarrying in a place</li><li>to persevere, continue<ol><li>of the thing continued in</li><li>in the work of teaching</li><li>of the blessing for which one keeps himself fit</li><li>denoting the action persisted in</li></ol></li></ol></li></ol>","xlit":"epiménō"},"G2368":{"strongs_def":" an aroma, i.e. fragrant powder burnt in religious service; by implication, the burning itself","derivation":"from G2370 (θυμιάω);","translit":"thymíama","lemma":"θυμίαμα","kjv_def":"incense, odour","pron":"thoo-mee'-am-ah","pos":"Noun Neuter","thayer":"<ol><li>an aromatic substance burnt, incense</li></ol>","xlit":"thymíama"},"G1969":{"kjv_def":"rebuke","translit":"epiplḗssō","lemma":"ἐπιπλήσσω","derivation":"from G1909 (ἐπί) and G4141 (πλήσσω);","strongs_def":" to chastise, i.e. (with words) to upbraid","pron":"ep-ee-place'-so","pos":"Verb","thayer":"<ol><li>to strike upon, beat upon</li><li>to chastise with words, to chide, upbraid, rebuke</li></ol>","xlit":"epiplḗssō"},"G3405":{"strongs_def":" requital (good or bad)","derivation":"from G3406 (μισθαποδότης);","lemma":"μισθαποδοσία","translit":"misthapodosía","kjv_def":"recompence of reward","pron":"mis-thap-od-os-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>payment of wages due, recompence</li></ol>","xlit":"misthapodosía"},"G780":{"lemma":"ἀσμένως","translit":"asménōs","kjv_def":"gladly","strongs_def":" with pleasure","derivation":"adverb from a derivative of the base of G2237 (ἡδονή);","pron":"as-men'-oce","pos":"Adverb","thayer":"<ol><li>with joy, gladness</li></ol>","xlit":"asménōs"},"G4479":{"derivation":"of Hebrew origin (H07259);","strongs_def":" Rebecca (i.e. Ribkah), the wife of Isaac","kjv_def":"Rebecca","translit":"Rhebékka","lemma":"Ῥεβέκκα","pron":"hreb-bek'-kah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Rebekah = \"ensnarer\"</p><ol><li>the wife of Isaac</li></ol>","xlit":"Rhebékka"},"G4225":{"kjv_def":"about, a certain place","translit":"poú","lemma":"πού","derivation":"genitive case of an indefinite pronoun (some) otherwise obsolete (compare G4214 (πόσος));","strongs_def":" as adverb of place, somewhere, i.e. nearly","pron":"poo","pos":"Adverb","thayer":"<ol><li>where?, in what place?</li></ol>","xlit":"poú"},"G59":{"strongs_def":" properly, to go to market, i.e. (by implication) to purchase; specially, to redeem","derivation":"from G58 (ἀγορά);","translit":"agorázō","lemma":"ἀγοράζω","kjv_def":"buy, redeem","pron":"ag-or-ad'-zo","pos":"Verb","thayer":"<ol><li>to be in the market place, to attend it</li><li>to do business there, buy or sell</li><li>of idle people: to haunt the market place, lounge there</li></ol>","xlit":"agorázō"},"G2756":{"kjv_def":"empty, (in) vain","lemma":"κενός","translit":"kenós","derivation":"apparently a primary word;","strongs_def":" empty (literally or figuratively)","pron":"ken-os'","pos":"Adjective","thayer":"<ol><li>empty, vain, devoid of truth<ol type='a'><li>of places, vessels, etc. which contain nothing</li><li>of men<ol><li>empty handed</li><li>without a gift</li></ol><li>metaphorically destitute of spiritual wealth, of one who boasts of his faith as a transcendent possession, yet is without the fruits of faith</li><li>metaphorically of endeavours, labours, acts, which result in nothing, vain, fruitless, without effect<ol><li>vain of no purpose</li></ol></li></ol></li></ol>","xlit":"kenós"},"G1257":{"strongs_def":" to leave off in the middle, i.e. intermit","derivation":"from G1223 (διά) and G3007 (λείπω);","translit":"dialeípō","lemma":"διαλείπω","kjv_def":"cease","pron":"dee-al-i'-po","pos":"Verb","thayer":"<ol><li>to interpose a delay, to intermit, leave off for a time something already begun</li></ol>","xlit":"dialeípō"},"G3097":{"kjv_def":"sorcerer, wise man","translit":"mágos","lemma":"μάγος","derivation":"of foreign origin (H07248);","strongs_def":" a Magian, i.e. Oriental scientist; by implication, a magician","pron":"mag'-os","pos":"Noun Masculine","thayer":"<ol><li>a magus<ol type='a'><li>the name given by the Babylonians (Chaldeans), Medes, Persians, and others, to the wise men, teachers, priests, physicians, astrologers, seers, interpreters of dreams, augers, soothsayers, sorcerers etc.</li><li>the oriental wise men (astrologers) who, having discovered by the rising of a remarkable star that the Messiah had just been born, came to Jerusalem to worship him</li><li>a false prophet and sorcerer</li></ol></li></ol>","xlit":"mágos"},"G1410":{"strongs_def":" to be able or possible","derivation":"of uncertain affinity;","lemma":"δύναμαι","translit":"dýnamai","kjv_def":"be able, can (do, + -not), could, may, might, be possible, be of power","pron":"doo'-nam-ahee","pos":"Verb","thayer":"<ol><li>to be able, have power whether by virtue of one's own ability and resources, or of a state of mind, or through favourable circumstances, or by permission of law or custom</li><li>to be able to do something</li><li>to be capable, strong and powerful</li></ol>","xlit":"dýnamai"},"G1419":{"translit":"dysbástaktos","lemma":"δυσβάστακτος","kjv_def":"grievous to be borne","strongs_def":" oppressive","derivation":"from G1418 (δυσ-) and a derivative of G941 (βαστάζω);","pron":"doos-bas'-tak-tos","pos":"Adjective","thayer":"<ol><li>hard to be borne</li></ol>","xlit":"dysbástaktos"},"G391":{"strongs_def":" behavior","derivation":"from G390 (ἀναστρέφω);","lemma":"ἀναστροφή","translit":"anastrophḗ","kjv_def":"conversation","pron":"an-as-trof-ay'","pos":"Noun Feminine","thayer":"<ol><li>manner of life, conduct, behaviour, deportment</li></ol>","xlit":"anastrophḗ"},"G2228":{"kjv_def":"and, but (either), (n-)either, except it be, (n-)or (else), rather, save, than, that, what, yea","translit":"ḗ","lemma":"ἤ","derivation":"a primary particle of distinction between two connected terms;","strongs_def":" disjunctive, or; comparative, than","pron":"ay","thayer":"<ol><li>either, or, than</li></ol>","xlit":"ḗ"},"G3041":{"strongs_def":" a pond (large or small)","derivation":"probably from G3040 (λιμήν) (through the idea of nearness of shore);","translit":"límnē","lemma":"λίμνη","kjv_def":"lake","pron":"lim'-nay","pos":"Noun Feminine","thayer":"<ol><li>a lake</li></ol>","xlit":"límnē"},"G4255":{"kjv_def":"purpose","translit":"proairéomai","lemma":"προαιρέομαι","derivation":"from G4253 (πρό) and G138 (αἱρέομαι);","strongs_def":" to choose for oneself before another thing (prefer), i.e. (by implication) to propose (intend)","pron":"pro-ahee-reh'-om-ahee","pos":"Verb","thayer":"<ol><li>to bring forward, bring forth from one's stores</li><li>to bring forth for one's self, to choose for one's self before another, to prefer</li><li>to purpose</li></ol>","xlit":"proairéomai"},"G5277":{"derivation":"a prolonged form for G5275 (ὑπολείπω);","strongs_def":" to leave behind, i.e. bequeath","kjv_def":"leave","translit":"hypolimpánō","lemma":"ὑπολιμπάνω","pron":"hoop-ol-im-pan'-o","pos":"Verb","thayer":"<ol><li>to leave, leave behind</li></ol>","xlit":"hypolimpánō"},"G5198":{"strongs_def":" to have sound health, i.e. be well (in body); figuratively, to be uncorrupt (true in doctrine)","derivation":"from G5199 (ὑγιής);","translit":"hygiaínō","lemma":"ὑγιαίνω","kjv_def":"be in health, (be safe and) sound, (be) whole(-some)","pron":"hoog-ee-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to be sound, to be well, to be in good health</li><li>metaphorically<ol type='a'><li>of Christians whose opinions are free from any mixture of error</li><li>of one who keeps the graces and is strong</li></ol></li></ol>","xlit":"hygiaínō"},"G2418":{"kjv_def":"minister","lemma":"ἱερουργέω","translit":"hierourgéō","derivation":"from a compound of G2411 (ἱερόν) and the base of G2041 (ἔργον);","strongs_def":" to be a temple-worker, i.e. officiate as a priest (figuratively)","pron":"hee-er-oorg-eh'-o","pos":"Verb","thayer":"<ol><li>to minister in the manner of a priest, minister in priestly service<ol type='a'><li>of those who defend the sanctity of the law by undergoing a violent death</li><li>of the preaching of the gospel</li></ol></li></ol>","xlit":"hierourgéō"},"G1304":{"derivation":"from G1223 (διά) and the base of G5147 (τρίβος);","strongs_def":" to wear through (time), i.e. remain","kjv_def":"abide, be, continue, tarry","translit":"diatríbō","lemma":"διατρίβω","pron":"dee-at-ree'-bo","pos":"Verb","thayer":"<ol><li>to rub between, rub hard</li><li>to wear away, consume</li><li>to spend, pass time</li></ol>","xlit":"diatríbō"},"G3799":{"lemma":"ὄψις","translit":"ópsis","kjv_def":"appearance, countenance, face","strongs_def":" properly, sight (the act), i.e. (by implication) the visage, an external show","derivation":"from G3700 (ὀπτάνομαι);","pron":"op'-sis","pos":"Noun Feminine","thayer":"<ol><li>seeing, sight</li><li>face, countenance</li><li>the outward appearance, look</li></ol>","xlit":"ópsis"},"G549":{"derivation":"from G575 (ἀπό) and (to go);","strongs_def":" to go away","kjv_def":"go","lemma":"ἄπειμι","translit":"ápeimi","pron":"ap'-i-mee","pos":"Verb","thayer":"<ol><li>to go away, depart</li></ol>","xlit":"ápeimi"},"G637":{"derivation":"from G575 (ἀπό) and G4150 (πλύνω);","strongs_def":" to rinse off","kjv_def":"wash","lemma":"ἀποπλύνω","translit":"apoplýnō","pron":"ap-op-loo'-no","pos":"Verb","thayer":"<ol><li>to wash off</li></ol>","xlit":"apoplýnō"},"G2079":{"kjv_def":"point of death","translit":"eschátōs","lemma":"ἐσχάτως","derivation":"adverb from G2078 (ἔσχατος);","strongs_def":" finally, i.e. (with G2192 (ἔχω)) at the extremity of life","pron":"es-khat'-oce","pos":"Adverb","thayer":"<ol><li>extreme, to be in the last gasp, at the point of death</li></ol>","xlit":"eschátōs"},"G1299":{"lemma":"διατάσσω","translit":"diatássō","kjv_def":"appoint, command, give, (set in) order, ordain","strongs_def":" to arrange thoroughly, i.e. (specially) institute, prescribe, etc.","derivation":"from G1223 (διά) and G5021 (τάσσω);","pron":"dee-at-as'-so","pos":"Verb","thayer":"<ol><li>to arrange, appoint, ordain, prescribe, give order</li></ol>","xlit":"diatássō"},"G1178":{"translit":"dekapénte","lemma":"δεκαπέντε","kjv_def":"fifteen","strongs_def":" ten and five, i.e. fifteen","derivation":"from G1176 (δέκα) and G4002 (πέντε);","pron":"dek-ap-en'-teh","pos":"Noun","thayer":"<ol><li>fifteen</li></ol>","xlit":"dekapénte"},"G4140":{"lemma":"πλησμονή","translit":"plēsmonḗ","kjv_def":"satisfying","strongs_def":" a filling up, i.e. (figuratively) gratification","derivation":"from a presumed derivative of G4130 (πλήθω);","pron":"place-mon-ay'","pos":"Noun Feminine","thayer":"<ol><li>repletion, satiety, for the satisfying of the flesh, to satiate the desires of the flesh<ol type='a'><li>indulgence of the flesh</li></ol></li></ol>","xlit":"plēsmonḗ"},"G2838":{"strongs_def":" sleeping, i.e. (by implication) repose","derivation":"from G2837 (κοιμάω);","translit":"koímēsis","lemma":"κοίμησις","kjv_def":"taking of rest","pron":"koy'-may-sis","pos":"Noun Feminine","thayer":"<ol><li>a reposing, taking rest</li><li>a lying, reclining</li></ol>","xlit":"koímēsis"},"G1832":{"kjv_def":"be lawful, let, X may(-est)","lemma":"ἔξεστι","translit":"éxesti","derivation":"third person singular present indicative of a compound of G1537 (ἐκ) and G1510 (εἰμί);","strongs_def":" so also neuter present participle of the same (with or without some form of G1510 (εἰμί) expressed); impersonally, it is right (through the figurative idea of being out in public)","pron":"ex'-es-tee","pos":"Verb","thayer":"<ol><li>it is lawful</li></ol>","xlit":"éxesti"},"G3916":{"strongs_def":" at the thing itself, i.e. instantly","derivation":"from G3844 (παρά) and G5536 (χρῆμα) (in its original sense);","translit":"parachrēma","lemma":"παραχρῆμα","kjv_def":"forthwith, immediately, presently, straightway, soon","pron":"par-akh-ray'-mah","pos":"Adverb","thayer":"<ol><li>immediately, forthwith, instantly</li></ol>","xlit":"parachrēma"},"G5236":{"strongs_def":" a throwing beyond others, i.e. (figuratively) supereminence; adverbially (with G1519 (εἰς) or G2596 (κατά)) pre- eminently","derivation":"from G5235 (ὑπερβάλλω);","translit":"hyperbolḗ","lemma":"ὑπερβολή","kjv_def":"abundance, (far more) exceeding, excellency, more excellent, beyond (out of) measure","pron":"hoop-er-bol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a throwing beyond</li><li>metaphorically<ol type='a'><li>superiority, excellence, pre-eminence</li><li>beyond measure, exceedingly, preeminently</li><li>beyond all measure</li></ol></li></ol>","xlit":"hyperbolḗ"},"G5516":{"kjv_def":"six hundred threescore and six","translit":"chx stigma","lemma":"χξϛ","derivation":"the 22nd, 14th and an obsolete letter (G4742 (στίγμα) as a cross) of the Greek alphabet (intermediate between the 5th and 6th), used as numbers; denoting respectively 600, 60 and 6;","strongs_def":" 666 as a numeral","pron":"khee xee stig'-ma","thayer":"<ol><li>six hundred and sixty six, the meaning of which is the basis of much vain speculation</li></ol>","xlit":"chx stigma"},"G3684":{"kjv_def":"millstone","lemma":"ὀνικός","translit":"onikós","derivation":"from G3688 (ὄνος);","strongs_def":" belonging to a ass, i.e. large (so as to be turned by a ass)","pron":"on-ik-os'","pos":"Adjective","thayer":"<ol><li>of or for an ass, turned by an ass<ol type='a'><li>these beasts were often employed to turn millstones</li></ol></li></ol>","xlit":"onikós"},"G1570":{"translit":"ékthetos","lemma":"ἔκθετος","kjv_def":"cast out","strongs_def":" put out, i.e. exposed to perish","derivation":"from G1537 (ἐκ) and a derivative of G5087 (τίθημι);","pron":"ek'-thet-os","pos":"Adjective","thayer":"<ol><li>cast out, exposed</li></ol>","xlit":"ékthetos"},"G1638":{"translit":"elaiṓn","lemma":"ἐλαιών","kjv_def":"Olivet","strongs_def":" an olive-orchard, i.e. (specially) the Mount of Olives","derivation":"from G1636 (ἐλαία);","pron":"el-ah-yone'","pos":"Noun Masculine","thayer":"<ol><li>an olive orchard, a place planted with olive trees<ol type='a'><li>Mount of Olives</li></ol></li></ol>","xlit":"elaiṓn"},"G5114":{"strongs_def":" more comprehensive or decisive than G2875 (κόπτω), as if by a single stroke; whereas that implies repeated blows, like hacking); more keen","derivation":"comparative of a derivative of the primary (to cut;","translit":"tomṓteros","lemma":"τομώτερος","kjv_def":"sharper","pron":"tom-o'-ter-os","pos":"Adjective","thayer":"<ol><li>sharper</li></ol>","xlit":"tomṓteros"},"G879":{"lemma":"ἀφυπνόω","translit":"aphypnóō","kjv_def":"fall asleep","strongs_def":" properly, to become awake, i.e. (by implication) to drop (off) in slumber","derivation":"from a compound of G575 (ἀπό) and G5258 (ὕπνος);","pron":"af-oop-no'-o","pos":"Verb","thayer":"<ol><li>to awaken from sleep</li><li>to fall asleep, to fall off to sleep</li></ol>","xlit":"aphypnóō"},"G5013":{"strongs_def":" to depress; figuratively, to humiliate (in condition or heart)","derivation":"from G5011 (ταπεινός);","lemma":"ταπεινόω","translit":"tapeinóō","kjv_def":"abase, bring low, humble (self)","pron":"tap-i-no'-o","pos":"Verb","thayer":"<ol><li>to make low, bring low<ol type='a'><li>to level, reduce to a plain</li><li>metaphorically to bring into a humble condition, reduce to meaner circumstances<ol><li>to assign a lower rank or place to</li><li>to abase</li><li>to be ranked below others who are honoured or rewarded</li><li>to humble or abase myself by humble living</li></ol><li>to lower, depress<ol><li>of one's soul bring down one's pride</li><li>to have a modest opinion of one's self</li><li>to behave in an unassuming manner</li><li>devoid of all haughtiness</li></ol></li></ol></li></ol>","xlit":"tapeinóō"},"G1656":{"kjv_def":"(+ tender) mercy","translit":"éleos","lemma":"ἔλεος","derivation":"of uncertain affinity;","strongs_def":" compassion (human or divine, especially active)","pron":"el'-eh-os","pos":"Noun Neuter","thayer":"<ol><li>mercy: kindness or good will towards the miserable and the afflicted, joined with a desire to help them<ol type='a'><li>of men towards men: to exercise the virtue of mercy, show one's self merciful</li><li>of God towards men: in general providence; the mercy and clemency of God in providing and offering to men salvation by Christ</li><li>the mercy of Christ, whereby at his return to judgment he will bless true Christians with eternal life</li></ol></li></ol>","xlit":"éleos"},"G123":{"kjv_def":"shore","translit":"aigialós","lemma":"αἰγιαλός","derivation":"from (to rush) and G251 (ἅλς) (in the sense of the sea;","strongs_def":" a beach (on which the waves dash)","pron":"ahee-ghee-al-os'","pos":"Noun Masculine","thayer":"<ol><li>the shore of the sea, the beach</li></ol>","xlit":"aigialós"},"G2571":{"kjv_def":"vail","translit":"kályma","lemma":"κάλυμα","derivation":"from G2572 (καλύπτω);","strongs_def":" a cover, i.e. veil","pron":"kal'-oo-mah","pos":"Noun Neuter","thayer":"<ol><li>a veil, covering</li></ol>","xlit":"kályma"},"G2786":{"strongs_def":" the Rock; Cephas (i.e. Kepha), a surname of Peter","derivation":"of Chaldee origin (compare H03710);","translit":"Kēphâs","lemma":"Κηφᾶς","kjv_def":"Cephas","pron":"kay-fas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cephas = \"stone\"</p><ol><li>another name for the apostle Peter</li></ol>","xlit":"Kēphâs"},"G2122":{"kjv_def":"conveniently, in season","translit":"eukaírōs","lemma":"εὐκαίρως","derivation":"adverb from G2121 (εὔκαιρος);","strongs_def":" opportunely","pron":"yoo-kah'-ee-roce","pos":"Adverb","thayer":"<ol><li>seasonably, opportunely</li><li>when the opportunity occurs</li></ol>","xlit":"eukaírōs"},"G4807":{"derivation":"of Hebrew origin (H08256) in imitation of G4809 (συκομωραία);","strongs_def":" a sycamore-fig tree","kjv_def":"sycamine tree","translit":"sykáminos","lemma":"συκάμινος","pron":"soo-kam'-ee-nos","pos":"Noun Feminine","thayer":"<ol><li>sycamine tree, having the form and foliage of the mulberry, but fruit resembling the fig</li></ol>","xlit":"sykáminos"},"G4375":{"kjv_def":"lovely","lemma":"προσφιλής","translit":"prosphilḗs","derivation":"from a presumed compound of G4314 (πρός) and G5368 (φιλέω);","strongs_def":" friendly towards, i.e. acceptable","pron":"pros-fee-lace'","pos":"Adjective","thayer":"<ol><li>acceptable, pleasing</li></ol>","xlit":"prosphilḗs"},"G1985":{"derivation":"from G1909 (ἐπί) and G4649 (σκοπός) (in the sense of G1983 (ἐπισκοπέω));","strongs_def":" a superintendent, i.e. Christian officer in genitive case charge of a (or the) church (literally or figuratively)","kjv_def":"bishop, overseer","translit":"epískopos","lemma":"ἐπίσκοπος","pron":"ep-is'-kop-os","pos":"Noun Masculine","thayer":"<ol><li>an overseer<ol type='a'><li>a man charged with the duty of seeing that things to be done by others are done rightly, any curator, guardian or superintendent</li><li>the superintendent, elder, or overseer of a Christian church</li></ol></li></ol>","xlit":"epískopos"},"G466":{"derivation":"from G473 (ἀντί) and G378 (ἀναπληρόω);","strongs_def":" to supplement","kjv_def":"fill up","lemma":"ἀνταναπληρόω","translit":"antanaplēróō","pron":"an-tan-ap-lay-ro'-o","pos":"Verb","thayer":"<ol><li>to fill up in turn<ol type='a'><li>in <a class='bible' href='#b51.1.24'>Col 1:24</a>, the meaning is, 'what is wanting in the afflictions of Christ to be borne by me, that I supply in order to repay the benefits which Christ conferred on me by filling up the measure of the afflictions laid upon me'.</li></ol></li></ol>","xlit":"antanaplēróō"},"G3591":{"strongs_def":" a mass (as bending or bulging by its load), i.e. burden (hindrance)","derivation":"probably from the same as G43 (ἀγκάλη);","translit":"ónkos","lemma":"ὄγκος","kjv_def":"weight","pron":"ong'-kos","pos":"Noun Masculine","thayer":"<ol><li>whatever is prominent, protuberance, bulk, mass<ol type='a'><li>hence a burden, weight, encumbrance</li></ol></li></ol>","xlit":"ónkos"},"G311":{"derivation":"from G306 (ἀναβάλλομαι);","strongs_def":" a putting off","kjv_def":"delay","translit":"anabolḗ","lemma":"ἀναβολή","pron":"an-ab-ol-ay'","pos":"Noun Feminine","thayer":"<ol><li>delay, a putting off</li></ol>","xlit":"anabolḗ"},"G1998":{"lemma":"ἐπισυντρέχω","translit":"episyntréchō","kjv_def":"come running together","strongs_def":" to hasten together upon one place (or a particular occasion)","derivation":"from G1909 (ἐπί) and G4936 (συντρέχω);","pron":"ep-ee-soon-trekh'-o","pos":"Verb","thayer":"<ol><li>to run together besides<ol type='a'><li>to others already gathered</li></ol></li></ol>","xlit":"episyntréchō"},"G1807":{"kjv_def":"deliver, pluck out, rescue","translit":"exairéō","lemma":"ἐξαιρέω","derivation":"from G1537 (ἐκ) and G138 (αἱρέομαι);","strongs_def":" actively, to tear out; middle voice, to select; figuratively, to release","pron":"ex-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to pluck out, draw out, i.e. root out</li><li>to choose out (for one's self), select, one person from many</li><li>to rescue, deliver</li></ol>","xlit":"exairéō"},"G1789":{"kjv_def":"nourish up in","lemma":"ἐντρέφω","translit":"entréphō","derivation":"from G1722 (ἐν) and G5142 (τρέφω);","strongs_def":" (figuratively) to educate","pron":"en-tref'-o","pos":"Verb","thayer":"<ol><li>to nourish in: a person or a thing</li><li>metaphorically to educate, form the mind</li></ol>","xlit":"entréphō"},"G355":{"lemma":"ἀναλίσκω","translit":"analískō","kjv_def":"consume","strongs_def":" properly, to use up, i.e. destroy","derivation":"from G303 (ἀνά) and a form of the alternate of G138 (αἱρέομαι);","pron":"an-al-is'-ko","pos":"Verb","thayer":"<ol><li>to expend<ol type='a'><li>to consume, e.g. spend money</li></ol><li>to consume, use up, destroy</li></ol>","xlit":"analískō"},"G1414":{"translit":"dynatéō","lemma":"δυνατέω","kjv_def":"be mighty","strongs_def":" to be efficient (figuratively)","derivation":"from G1415 (δυνατός);","pron":"doo-nat-eh'-o","pos":"Verb","thayer":"<ol><li>to be powerful or mighty</li><li>show one's self powerful</li><li>to be able, have power</li></ol>","xlit":"dynatéō"},"G5141":{"derivation":"strengthened from a primary (to \"dread\", \"terrify\");","strongs_def":" to \"tremble\" or fear","kjv_def":"be afraid, trembling","lemma":"τρέμω","translit":"trémō","pron":"trem'-o","pos":"Verb","thayer":"<ol><li>tremble</li><li>to fear, be afraid</li></ol>","xlit":"trémō"},"G3384":{"derivation":"apparently a primary word;","strongs_def":" a \"mother\" (literally or figuratively, immediate or remote)","kjv_def":"mother","lemma":"μήτηρ","translit":"mḗtēr","pron":"may'-tare","pos":"Noun Feminine","thayer":"<ol><li>a mother</li><li>metaphorically the source of something, the motherland</li></ol>","xlit":"mḗtēr"},"G5419":{"kjv_def":" declare","translit":"phrázō","lemma":"φράζω","derivation":"probably akin to G5420 (φράσσω) through the idea of defining;","strongs_def":" to indicate (by word or act), i.e. (specially), to expound","pron":"frad'-zo","pos":"Verb","thayer":"<ol><li>to indicate plainly, make known, declare, whether by gesture or by writing or speaking, or in some other ways</li><li>to explain</li></ol>","xlit":"phrázō"},"G3390":{"kjv_def":"chiefest city","lemma":"μητρόπολις","translit":"mētrópolis","derivation":"from G3384 (μήτηρ) and G4172 (πόλις);","strongs_def":" a mother city, i.e. \"metropolis\"","pron":"may-trop'-ol-is","pos":"Noun Feminine","thayer":"<ol><li>a metropolis, a chief city</li></ol>","xlit":"mētrópolis"},"G5195":{"translit":"hybrízō","lemma":"ὑβρίζω","kjv_def":"use despitefully, reproach, entreat shamefully (spitefully)","strongs_def":" to exercise violence, i.e. abuse","derivation":"from G5196 (ὕβρις);","pron":"hoo-brid'-zo","pos":"Verb","thayer":"<ol><li>to be insolent, to behave insolently, wantonly, outrageously</li><li>to act insolently and shamefully towards one, to treat shamefully</li><li>of one who injures another by speaking evil of him</li></ol>","xlit":"hybrízō"},"G5247":{"strongs_def":" prominence, i.e. (figuratively) superiority (in rank or character)","derivation":"from G5242 (ὑπερέχω);","translit":"hyperochḗ","lemma":"ὑπεροχή","kjv_def":"authority, excellency","pron":"hoop-er-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>elevation, pre-eminence, superiority</li><li>metaphorically excellence</li></ol>","xlit":"hyperochḗ"},"G145":{"strongs_def":" properly, an organ of perception, i.e. (figuratively) judgment","derivation":"from a derivative of G143 (αἰσθάνομαι);","lemma":"αἰσθητήριον","translit":"aisthētḗrion","kjv_def":"senses","pron":"ahee-sthay-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>faculty of the mind for perceiving, understanding, judging</li></ol>","xlit":"aisthētḗrion"},"G5558":{"lemma":"χρυσόω","translit":"chrysóō","kjv_def":"deck","strongs_def":" to gild, i.e. bespangle with golden ornaments","derivation":"from G5557 (χρυσός);","pron":"khroo-so'-o","pos":"Verb","thayer":"<ol><li>to adorn with gold, to gild<ol type='a'><li>of a woman ornamented with gold so profusely that she seems to be gilded</li></ol></li></ol>","xlit":"chrysóō"},"G5310":{"strongs_def":" highest, i.e. (masculine singular) the Supreme (God), or (neuter plural) the heavens","derivation":"superlative from the base of G5311 (ὕψος);","lemma":"ὕψιστος","translit":"hýpsistos","kjv_def":"most high, highest","pron":"hoop'-sis-tos","pos":"Adverb","thayer":"<ol><li>highest, most high<ol type='a'><li>of place: the highest regions</li><li>of rank: the most high God</li></ol></li></ol>","xlit":"hýpsistos"},"G5542":{"strongs_def":" fair speech, i.e. plausibility","derivation":"from a compound of G5543 (χρηστός) and G3004 (λέγω);","translit":"chrēstología","lemma":"χρηστολογία","kjv_def":"good words","pron":"khrase-tol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>fair speaking, the smooth and plausible address which simulates goodness</li></ol>","xlit":"chrēstología"},"G688":{"strongs_def":" Arabia, a region of Asia","derivation":"of Hebrew origin (H06152);","lemma":"Ἀραβία","translit":"Arabía","kjv_def":"Arabia","pron":"ar-ab-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Arabia = \"desert or barren\"</p><ol><li>a well known peninsula of Asia lying towards Africa, and bounded by Egypt, Palestine, Syria, Mesopotamia, Babylonia, the Gulf of Arabia, the Persian Gulf, the Red Sea and the Indian Ocean</li></ol>","xlit":"Arabía"},"G4522":{"derivation":"from a derivative of (to equip) meaning furniture, especially a pack-saddle (which in the East is merely a bag of netted rope);","strongs_def":" a \"seine\" for fishing","kjv_def":"net","translit":"sagḗnē","lemma":"σαγήνη","pron":"sag-ay'-nay","pos":"Noun Feminine","thayer":"<ol><li>a large fishing net, a drag net</li></ol>","xlit":"sagḗnē"},"G577":{"kjv_def":"cast away","translit":"apobállō","lemma":"ἀποβάλλω","derivation":"from G575 (ἀπό) and G906 (βάλλω);","strongs_def":" to throw off; figuratively, to lose","pron":"ap-ob-al'-lo","pos":"Verb","thayer":"<ol><li>to throw off, cast away</li></ol>","xlit":"apobállō"},"G5201":{"derivation":"from G5204 (ὕδωρ);","strongs_def":" a water-jar, i.e. receptacle for family supply","kjv_def":"water-pot","lemma":"ὑδρία","translit":"hydría","pron":"hoo-dree-ah'","pos":"Noun Feminine","thayer":"<ol><li>a vessel for holding water</li><li>a water jar, a water pot</li></ol>","xlit":"hydría"},"G497":{"kjv_def":"war against","translit":"antistrateúomai","lemma":"ἀντιστρατεύομαι","derivation":"from G473 (ἀντί) and G4754 (στρατεύομαι);","strongs_def":" (figuratively) to attack, i.e. (by implication) destroy","pron":"an-tee-strat-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to make a military expedition, or take the field, against anyone</li><li>to oppose, war against</li></ol>","xlit":"antistrateúomai"},"G588":{"kjv_def":"accept, receive (gladly)","lemma":"ἀποδέχομαι","translit":"apodéchomai","derivation":"from G575 (ἀπό) and G1209 (δέχομαι);","strongs_def":" to take fully, i.e. welcome (persons), approve (things)","pron":"ap-od-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to accept from, receive</li><li>to accept what is offered from without</li></ol>","xlit":"apodéchomai"},"G4694":{"derivation":"of uncertain derivation;","strongs_def":" a ledge or reef of rock in the sea","kjv_def":"spot (by confusion with G4696 (σπίλος))","translit":"spilás","lemma":"σπιλάς","pron":"spee-las'","pos":"Noun Feminine","thayer":"<ol><li>a rock in the sea, ledge, reef</li><li>metaphorically of men who by their conduct damage others morally, wreck them as it were</li></ol>","xlit":"spilás"},"G906":{"kjv_def":"arise, cast (out), X dung, lay, lie, pour, put (up), send, strike, throw (down), thrust","translit":"bállō","lemma":"βάλλω","derivation":"a primary verb;","strongs_def":" to throw (in various applications, more or less violent or intense)","pron":"bal'-lo","pos":"Verb","thayer":"<ol><li>to throw or let go of a thing without caring where it falls<ol type='a'><li>to scatter, to throw, cast into</li><li>to give over to one's care uncertain about the result</li><li>of fluids<ol><li>to pour, pour into of rivers</li><li>to pour out</li></ol></li></ol><li>to put into, insert</li></ol>","xlit":"bállō"},"G4048":{"strongs_def":" to tear all around, i.e. completely away","derivation":"from G4012 (περί) and G4486 (ῥήγνυμι);","translit":"perirrhḗgnymi","lemma":"περιῤῥήγνυμι","kjv_def":"rend off","pron":"per-ir-hrayg'-noo-mee","pos":"Verb","thayer":"<ol><li>to break off on all sides, break off all around</li><li>to rend or tear off all around</li></ol>","xlit":"perirrhḗgnymi"},"G2915":{"strongs_def":" barley","derivation":"of uncertain derivation;","translit":"krithḗ","lemma":"κριθή","kjv_def":"barley","pron":"kree-thay'","pos":"Noun Feminine","thayer":"<ol><li>barley</li></ol>","xlit":"krithḗ"},"G1786":{"strongs_def":" a resident","derivation":"from G1722 (ἐν) and G5117 (τόπος);","translit":"entópios","lemma":"ἐντόπιος","kjv_def":"of that place","pron":"en-top'-ee-os","pos":"Adjective","thayer":"<ol><li>a dweller in a place</li><li>a resident or native of a place</li></ol>","xlit":"entópios"},"G5507":{"lemma":"χίλιοι","translit":"chílioi","kjv_def":"thousand","strongs_def":" a thousand","derivation":"plural of uncertain affinity;","pron":"khil'-ee-oy","pos":"Adjective","thayer":"<ol><li>a thousand</li></ol>","xlit":"chílioi"},"G4546":{"derivation":"of Hebrew origin (H08123);","strongs_def":" Sampson (i.e. Shimshon), an Israelite","kjv_def":"Samson","lemma":"Σαμψών","translit":"Sampsṓn","pron":"samp-sone'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Samson = \"like the sun\"</p><ol><li>a famous judge of Israel renowned for his physical strength</li></ol>","xlit":"Sampsṓn"},"G1242":{"kjv_def":"covenant, testament","translit":"diathḗkē","lemma":"διαθήκη","derivation":"from G1303 (διατίθεμαι);","strongs_def":" properly, a disposition, i.e. (specially) a contract (especially a devisory will)","pron":"dee-ath-ay'-kay","pos":"Noun Feminine","thayer":"<ol><li>a disposition, arrangement, of any sort, which one wishes to be valid, the last disposition which one makes of his earthly possessions after his death, a testament or will</li><li>a compact, a covenant, a testament<ol type='a'><li>God's covenant with Noah, etc.</li></ol></li></ol>","xlit":"diathḗkē"},"G3598":{"translit":"hodós","lemma":"ὁδός","kjv_def":"journey, (high-)way","strongs_def":" a road; by implication, a progress (the route, act or distance); figuratively, a mode or means","derivation":"apparently a primary word;","pron":"hod-os'","pos":"Noun Feminine","thayer":"<ol><li>properly<ol type='a'><li>a way<ol><li>a travelled way, road</li></ol><li>a travellers way, journey, travelling</li></ol><li>metaphorically<ol type='a'><li>a course of conduct</li><li>a way (i.e. manner) of thinking, feeling, deciding</li></ol></li></ol>","xlit":"hodós"},"G4264":{"lemma":"προβιβάζω","translit":"probibázō","kjv_def":"draw, before instruct","strongs_def":" to force forward, i.e. bring to the front, instigate","derivation":"from G4253 (πρό) and a reduplicated form of G971 (βιάζω);","pron":"prob-ib-ad'-zo","pos":"Verb","thayer":"<ol><li>to cause to go forward, to lean forward, to bring forward, drag forward</li><li>metaphorically to incite, instigate, urge, forward, set on<ol type='a'><li>to induce by persuasion</li></ol></li></ol>","xlit":"probibázō"},"G1366":{"kjv_def":"with two edges, two-edged","lemma":"δίστομος","translit":"dístomos","derivation":"from G1364 (δίς) and G4750 (στόμα);","strongs_def":" double-edged","pron":"dis'-tom-os","pos":"Adjective","thayer":"<ol><li>having a double mouth as a river<ol type='a'><li>used of the edge of the sword and of other weapons, so has the meaning of two-edged</li></ol></li></ol>","xlit":"dístomos"},"G4240":{"derivation":"from G4239 (πραΰς);","strongs_def":" mildness, i.e. (by implication) humility","kjv_def":"meekness","translit":"praÿtēs","lemma":"πραΰτης","pron":"prah-oo'-tace","pos":"Noun Feminine","thayer":"<ol><li>mildness of disposition, gentleness of spirit, meekness</li></ol>","xlit":"praÿtēs"},"G3137":{"strongs_def":" Maria or Mariam (i.e. Mirjam), the name of six Christian females","derivation":"of Hebrew origin (H04813);","translit":"María","lemma":"Μαρία","kjv_def":" Mary","pron":"mar-ee'-ah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Mary or Miriam = \"their rebellion\"</p><ol><li>Mary the mother of Jesus</li><li>Mary Magdalene, a women from Magdala</li><li>Mary, the sister of Lazarus and Martha</li><li>Mary of Cleophas the mother of James the less</li><li>Mary the mother of John Mark, a sister of Barnabas</li><li>Mary, a Roman Christian who is greeted by Paul in <a class='bible' href='#b45.16.6'>Rom 16:6</a></li></ol>","xlit":"María"},"G2159":{"kjv_def":"mightily, vehemently","lemma":"εὐτόνως","translit":"eutónōs","derivation":"adverb from a compound of G2095 (εὖ) and a derivative of (to stretch);","strongs_def":" in a well-strung manner, i.e. (figuratively) intensely (in a good sense, cogently; in a bad one, fiercely)","pron":"yoo-ton'-oce","pos":"Adverb","thayer":"<ol><li>vehemently, forcibly</li></ol>","xlit":"eutónōs"},"G1596":{"derivation":"adverb from the same as G1595 (ἑκούσιον);","strongs_def":" voluntarily","kjv_def":"wilfully, willingly","translit":"hekousíōs","lemma":"ἑκουσίως","pron":"hek-oo-see'-ose","pos":"Adverb","thayer":"<ol><li>voluntarily, willingly, of one's own accord<ol type='a'><li>to sin wilfully as opposed to sins committed inconsiderately, and from ignorance or from weakness</li></ol></li></ol>","xlit":"hekousíōs"},"G2285":{"lemma":"θάμβος","translit":"thámbos","kjv_def":"X amazed, + astonished, wonder","strongs_def":" stupefaction (by surprise), i.e. astonishment","derivation":"akin to an obsolete (to dumbfound);","pron":"tham'-bos","pos":"Noun","thayer":"<ol><li>to render immovable</li><li>amazement</li></ol>","xlit":"thámbos"},"G348":{"kjv_def":"hinder","translit":"anakóptō","lemma":"ἀνακόπτω","derivation":"from G303 (ἀνά) and G2875 (κόπτω);","strongs_def":" to beat back, i.e. check","pron":"an-ak-op'-to","pos":"Verb","thayer":"<ol><li>to beat back, check (as in the course of a ship)</li></ol>","xlit":"anakóptō"},"G1616":{"translit":"ekténeia","lemma":"ἐκτένεια","kjv_def":"X instantly","strongs_def":" intentness","derivation":"from G1618 (ἐκτενής);","pron":"ek-ten'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>extension</li><li>intentness (of mind), earnestness</li></ol>","xlit":"ekténeia"},"G3477":{"strongs_def":" Nangæ (i.e. perhaps Nogach), an Israelite","derivation":"probably of Hebrew origin (compare H05052);","lemma":"Ναγγαί","translit":"Nangaí","kjv_def":"Nagge","pron":"nang-gah'-ee","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nagge = \"illuminating\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Nangaí"},"G596":{"kjv_def":"barn, garner","lemma":"ἀποθήκη","translit":"apothḗkē","derivation":"from G659 (ἀποτίθημι);","strongs_def":" a repository, i.e. granary","pron":"ap-oth-ay'-kay","pos":"Noun Feminine","thayer":"<ol><li>a place in which anything is laid by or up</li><li>a storehouse, granary</li></ol>","xlit":"apothḗkē"},"G4180":{"kjv_def":"much speaking","lemma":"πολυλογία","translit":"polylogía","derivation":"from a compound of G4183 (πολύς) and G3056 (λόγος);","strongs_def":" loquacity, i.e. prolixity","pron":"pol-oo-log-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>much speaking</li></ol>","xlit":"polylogía"},"G1423":{"translit":"dyskólōs","lemma":"δυσκόλως","kjv_def":"hardly","strongs_def":" impracticably","derivation":"adverb from G1422 (δύσκολος);","pron":"doos-kol'-oce","pos":"Adverb","thayer":"<ol><li>with difficulty</li></ol>","xlit":"dyskólōs"},"G2864":{"derivation":"apparently from the same as G2865 (κομίζω);","strongs_def":" the hair of the head (locks, as ornamental, and thus differing from G2359 (θρίξ); which properly denotes merely the scalp)","kjv_def":"hair","lemma":"κόμη","translit":"kómē","pron":"kom'-ay","pos":"Noun Feminine","thayer":"<ol><li>hair, head of hair</li></ol>","xlit":"kómē"},"G2297":{"translit":"thaumásios","lemma":"θαυμάσιος","kjv_def":"wonderful thing","strongs_def":" wondrous, i.e. (neuter as noun) a miracle","derivation":"from G2295 (θαῦμα);","pron":"thow-mas'-ee-os","pos":"Adjective","thayer":"<ol><li>wonderful, marvellous</li><li>wonderful deeds, wonders</li></ol>","xlit":"thaumásios"},"G4043":{"strongs_def":" to tread all around, i.e. walk at large (especially as proof of ability); figuratively, to live, deport oneself, follow (as a companion or votary)","derivation":"from G4012 (περί) and G3961 (πατέω);","translit":"peripatéō","lemma":"περιπατέω","kjv_def":"go, be occupied with, walk (about)","pron":"per-ee-pat-eh'-o","pos":"Verb","thayer":"<ol><li>to walk<ol type='a'><li>to make one's way, progress; to make due use of opportunities</li><li>Hebrew for, to live<ol><li>to regulate one's life</li><li>to conduct one's self</li><li>to pass one's life</li></ol></li></ol></li></ol>","xlit":"peripatéō"},"G1830":{"strongs_def":" to explore (figuratively)","derivation":"from G1537 (ἐκ) and G2045 (ἐρευνάω);","translit":"exereunáō","lemma":"ἐξερευνάω","kjv_def":"search diligently","pron":"ex-er-yoo-nah'-o","pos":"Verb","thayer":"<ol><li>to search out, search anxiously and diligently</li></ol>","xlit":"exereunáō"},"G3410":{"lemma":"μίσθωμα","translit":"místhōma","kjv_def":"hired house","strongs_def":" a rented building","derivation":"from G3409 (μισθόω);","pron":"mis'-tho-mah","pos":"Noun Neuter","thayer":"<ol><li>the price for which anything is either let or hired<ol type='a'><li>of a harlots hire</li></ol><li>that which is either let or hired for a price, as of a house, dwelling, lodging</li></ol>","xlit":"místhōma"},"G2347":{"kjv_def":"afflicted(-tion), anguish, burdened, persecution, tribulation, trouble","translit":"thlîpsis","lemma":"θλῖψις","derivation":"from G2346 (θλίβω);","strongs_def":" pressure (literally or figuratively)","pron":"thlip'-sis","pos":"Noun Feminine","thayer":"<ol><li>a pressing, pressing together, pressure</li><li>metaphorically oppression, affliction, tribulation, distress, straits</li></ol>","xlit":"thlîpsis"},"G3136":{"lemma":"Μάρθα","translit":"Mártha","kjv_def":"Martha","strongs_def":" Martha, a Christian woman","derivation":"probably of Chaldee origin (meaning mistress);","pron":"mar'-thah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Martha = \"she was rebellious\"</p><ol><li>was the sister of Lazarus and Mary of Bethany</li></ol>","xlit":"Mártha"},"G1944":{"translit":"epikatáratos","lemma":"ἐπικατάρατος","kjv_def":"accursed","strongs_def":" imprecated, i.e. execrable","derivation":"from G1909 (ἐπί) and a derivative of G2672 (καταράομαι);","pron":"ep-ee-kat-ar'-at-os","pos":"Adjective","thayer":"<ol><li>accursed, execrable, exposed to divine vengeance, lying under God's curse</li></ol>","xlit":"epikatáratos"},"G4715":{"derivation":"from the base of G2746 (καύχησις);","strongs_def":" a stander (standard of value), i.e. (specially), a stater or certain coin","kjv_def":"piece of money","translit":"statḗr","lemma":"στατήρ","pron":"stat-air'","pos":"Noun Masculine","thayer":"<ol><li>a stater, a coin<ol type='a'><li>in the NT a silver stater equal to four Attic or two Alexandrian drachmas, a Jewish shekel</li></ol></li></ol>","xlit":"statḗr"},"G2244":{"strongs_def":" maturity (in years or size)","derivation":"from the same as G2245 (ἡλίκος);","lemma":"ἡλικία","translit":"hēlikía","kjv_def":"age, stature","pron":"hay-lik-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>age, time of life<ol type='a'><li>age, term or length of life</li><li>adult age, maturity</li><li>suitable age for anything</li><li>metaphorically of an attained state fit for a thing</li></ol><li>stature, i.e in height and comeliness of stature</li></ol>","xlit":"hēlikía"},"G4004":{"derivation":"multiplicative of G4002 (πέντε);","strongs_def":" fifty","kjv_def":"fifty","lemma":"πεντήκοντα","translit":"pentḗkonta","pron":"pen-tay'-kon-tah","pos":"Adjective","thayer":"<ol><li>fifty</li></ol>","xlit":"pentḗkonta"},"G3790":{"kjv_def":"brow","translit":"ophrŷs","lemma":"ὀφρῦς","derivation":"perhaps from G3700 (ὀπτάνομαι) (through the idea of the shading or proximity to the organ of vision);","strongs_def":" the eye-\"brow\" or forehead, i.e. (figuratively) the brink of a precipice","pron":"of-roos'","pos":"Noun Feminine","thayer":"<ol><li>the eyebrow</li><li>any prominence or projection</li></ol>","xlit":"ophrŷs"},"G373":{"derivation":"from G303 (ἀνά) and G3973 (παύω);","strongs_def":" (reflexively) to repose (literally or figuratively (be exempt), remain); by implication, to refresh","kjv_def":"take ease, refresh, (give, take) rest","lemma":"ἀναπαύω","translit":"anapaúō","pron":"an-ap-ow'-o","pos":"Verb","thayer":"<ol><li>to cause or permit one to cease from any movement or labour in order to recover and collect his strength</li><li>to give rest, refresh, to give one's self rest, take rest</li><li>to keep quiet, of calm and patient expectation</li></ol>","xlit":"anapaúō"},"G3495":{"derivation":"from the same as G3494 (νεανίας);","strongs_def":" a youth (under forty)","kjv_def":"young man","lemma":"νεανίσκος","translit":"neanískos","pron":"neh-an-is'-kos","pos":"Noun Masculine","thayer":"<ol><li>a young man, youth<ol type='a'><li>used of a young attendant or servant</li></ol></li></ol>","xlit":"neanískos"},"G2340":{"strongs_def":" to hunt (an animal), i.e. (figuratively) to carp at","derivation":"from G2339 (θήρα);","lemma":"θηρεύω","translit":"thēreúō","kjv_def":"catch","pron":"thay-ryoo'-o","pos":"Verb","thayer":"<ol><li>to go a hunting, to hunt, to catch in hunting</li><li>metaphorically to lay wait for, strive to ensnare, catch artfully</li></ol>","xlit":"thēreúō"},"G3519":{"kjv_def":"island","translit":"nēsíon","lemma":"νησίον","derivation":"diminutive of G3520 (νῆσος);","strongs_def":" an islet","pron":"nay-see'-on","pos":"Noun Neuter","thayer":"<ol><li>a small island</li></ol>","xlit":"nēsíon"},"G5001":{"derivation":"from G5021 (τάσσω);","strongs_def":" something orderly in arrangement (a troop), i.e. (figuratively) a series or succession","kjv_def":"order","lemma":"τάγμα","translit":"tágma","pron":"tag'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been arranged, thing placed in order</li><li>a body of soldiers, a corps</li><li>band, troop, class</li></ol>","xlit":"tágma"},"G4217":{"strongs_def":" interrogatively, whatever, i.e. of what possible sort","derivation":"apparently from G4219 (πότε) and the base of G4226 (ποῦ);","lemma":"ποταπός","translit":"potapós","kjv_def":"what (manner of)","pron":"pot-ap-os'","pos":"Adjective","thayer":"<ol><li>from what country, nation or tribe</li><li>of what sort or quality (what manner of)<ol type='a'><li>of persons</li><li>of things</li></ol></li></ol>","xlit":"potapós"},"G2361":{"kjv_def":"great drop","translit":"thrómbos","lemma":"θρόμβος","derivation":"perhaps from G5142 (τρέφω) (in the sense of thickening);","strongs_def":" a clot","pron":"throm'-bos","pos":"Noun Masculine","thayer":"<ol><li>a large thick drop, especially of clotted blood</li></ol>","xlit":"thrómbos"},"G2562":{"derivation":"feminine of G2563 (κάλαμος);","strongs_def":" a stalk of grain, i.e. (collectively) stubble","kjv_def":"stubble","lemma":"καλάμη","translit":"kalámē","pron":"kal-am'-ay","pos":"Noun Feminine","thayer":"<ol><li>a stalk of grain or a reed, stubble<ol type='a'><li>the stalk left after the ears are cut off</li></ol></li></ol>","xlit":"kalámē"},"G3077":{"kjv_def":"grief, grievous, + grudgingly, heaviness, sorrow","lemma":"λύπη","translit":"lýpē","derivation":"apparently a primary word;","strongs_def":" sadness","pron":"loo'-pay","pos":"Noun Feminine","thayer":"<ol><li>sorrow, pain, grief, annoyance, affliction<ol type='a'><li>of persons mourning</li></ol></li></ol>","xlit":"lýpē"},"G4523":{"kjv_def":"Sadducee","translit":"Saddoukaîos","lemma":"Σαδδουκαῖος","derivation":"probably from G4524 (Σαδώκ);","strongs_def":" a Sadducæan (i.e. Tsadokian), or follower of a certain heretical Israelite","pron":"sad-doo-kah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sadducees = \"the righteous\"</p><ol><li>a religious party at the time of Christ among the Jews, who denied that the oral law was a revelation of God to the Israelites, and who deemed the written law alone to be obligatory on the nation, as the divine authority. They denied the following doctrines:<ol type='a'><li>resurrection of the body</li><li>immortality of the soul</li><li>existence of spirits and angels</li><li>divine predestination, affirmed free will</li></ol></li></ol>","xlit":"Saddoukaîos"},"G4379":{"lemma":"προσψαύω","translit":"prospsaúō","kjv_def":"touch","strongs_def":" to impinge, i.e. lay a finger on (in order to relieve)","derivation":"from G4314 (πρός) and (to touch);","pron":"pros-psow'-o","pos":"Verb","thayer":"<ol><li>to touch</li></ol>","xlit":"prospsaúō"},"G2942":{"lemma":"κυβερνήτης","translit":"kybernḗtēs","kjv_def":"(ship) master","strongs_def":" helmsman, i.e. (by implication) captain","derivation":"from the same as G2941 (κυβέρνησις);","pron":"koo-ber-nay'-tace","pos":"Noun Masculine","thayer":"<ol><li>steersman, helmsman, sailing master</li></ol>","xlit":"kybernḗtēs"},"G3980":{"strongs_def":" to be persuaded by a ruler, i.e. (genitive case) to submit to authority; by analogy, to conform to advice","derivation":"from a compound of G3982 (πείθω) and G757 (ἄρχω);","translit":"peitharchéō","lemma":"πειθαρχέω","kjv_def":"hearken, obey (magistrates)","pron":"pi-tharkh-eh'-o","pos":"Verb","thayer":"<ol><li>to obey (a ruler or a superior)</li></ol>","xlit":"peitharchéō"},"G3492":{"strongs_def":" a boatman, i.e. seaman","derivation":"from G3491 (ναῦς);","lemma":"ναύτης","translit":"naútēs","kjv_def":"sailor, shipman","pron":"now'-tace","pos":"Noun Masculine","thayer":"<ol><li>a sailor, seaman, mariner</li></ol>","xlit":"naútēs"},"G2702":{"derivation":"from G2596 (κατά) and G5342 (φέρω) (including its alternate);","strongs_def":" to bear down, i.e. (figuratively) overcome (with drowsiness); specially, to cast a vote","kjv_def":"fall, give, sink down","lemma":"καταφέρω","translit":"kataphérō","pron":"kat-af-er'-o","pos":"Verb","thayer":"<ol><li>to bear down, bring down, cast down<ol type='a'><li>to cast a pebble or calculus into the urn<ol><li>to give one's vote, to approve</li></ol><li>to be born down, to sink, (from the window to the pavement)</li><li>metaphorically<ol><li>to be weighted down by, overcome, carried away</li><li>to sink into sleep, drop asleep</li></ol></li></ol></li></ol>","xlit":"kataphérō"},"G4760":{"lemma":"στρατόπεδον","translit":"stratópedon","kjv_def":"army","strongs_def":" a camping-ground, i.e. (by implication) a body of troops","derivation":"from the base of G4756 (στρατιά) and the same as G3977 (πεδινός);","pron":"strat-op'-ed-on","pos":"Noun Neuter","thayer":"<ol><li>a military camp</li><li>soldiers in camp, an army</li></ol>","xlit":"stratópedon"},"G4389":{"kjv_def":"exhort","translit":"protrépomai","lemma":"προτρέπομαι","derivation":"middle voice from G4253 (πρό) and the base of G5157 (τροπή);","strongs_def":" to turn forward for oneself, i.e. encourage","pron":"prot-rep'-om-ahee","pos":"Verb","thayer":"<ol><li>to urge forwards, exhort, encourage</li></ol>","xlit":"protrépomai"},"G2555":{"strongs_def":" a bad-doer; (specially), a criminal","derivation":"from G2556 (κακός) and G4160 (ποιέω);","translit":"kakopoiós","lemma":"κακοποιός","kjv_def":"evil-doer, malefactor","pron":"kak-op-oy-os'","pos":"Adjective","thayer":"<ol><li>an evil doer, malefactor</li></ol>","xlit":"kakopoiós"},"G74":{"kjv_def":"agony","translit":"agōnía","lemma":"ἀγωνία","derivation":"from G73 (ἀγών);","strongs_def":" a struggle (properly, the state), i.e. (figuratively) anguish","pron":"ag-o-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a struggle for victory<ol type='a'><li>gymnastic exercise, wrestling</li></ol><li>of severe mental struggles and emotions, agony, anguish</li></ol>","xlit":"agōnía"},"G1436":{"derivation":"apparent imperative of G1439 (ἐάω);","strongs_def":" properly, let it be, i.e. (as interjection) aha!","kjv_def":"let alone","translit":"éa","lemma":"ἔα","pron":"eh'-ah","thayer":"<ol><li>interjection expressive of indignation, or of wonder mixed with fear, ha! ah!</li></ol>","xlit":"éa"},"G1269":{"strongs_def":" to nod (or express by signs) across an intervening space","derivation":"from G1223 (διά) and G3506 (νεύω);","lemma":"διανεύω","translit":"dianeúō","kjv_def":"beckon","pron":"dee-an-yoo'-o","pos":"Verb","thayer":"<ol><li>to express one's meaning by a sign, nod to, beckon to, wink at</li></ol>","xlit":"dianeúō"},"G2104":{"translit":"eugenḗs","lemma":"εὐγενής","kjv_def":"more noble, nobleman","strongs_def":" well born, i.e. (literally) high in rank, or (figuratively) generous","derivation":"from G2095 (εὖ) and G1096 (γίνομαι);","pron":"yoog-en'-ace","pos":"Adjective","thayer":"<ol><li>well born, of a noble family</li><li>noble minded</li></ol>","xlit":"eugenḗs"},"G4852":{"derivation":"from G4862 (σύν) and G5346 (φημί);","strongs_def":" to say jointly, i.e. assent to","kjv_def":"consent unto","translit":"sýmphēmi","lemma":"σύμφημι","pron":"soom'-fay-mee","pos":"Verb","thayer":"<ol><li>to consent, confess</li></ol>","xlit":"sýmphēmi"},"G2999":{"kjv_def":"(divine) service","lemma":"λατρεία","translit":"latreía","derivation":"from G3000 (λατρεύω);","strongs_def":" ministration of God, i.e. worship","pron":"lat-ri'-ah","pos":"Noun Feminine","thayer":"<ol><li>service rendered for hire<ol type='a'><li>any service or ministration: the service of God</li></ol><li>the service and worship of God according to the requirements of the Levitical law</li><li>to perform sacred services</li></ol>","xlit":"latreía"},"G3973":{"derivation":"a primary verb (\"pause\");","strongs_def":" to stop (transitively or intransitively), i.e. restrain, quit, desist, come to an end","kjv_def":"cease, leave, refrain","translit":"paúō","lemma":"παύω","pron":"pow'-o","pos":"Verb","thayer":"<ol><li>to make to cease or desist</li><li>to restrain a thing or person from something</li><li>to cease, to leave off</li><li>have got release from sin<ol type='a'><li>no longer stirred by its incitements and seductions</li></ol></li></ol>","xlit":"paúō"},"G536":{"translit":"aparchḗ","lemma":"ἀπαρχή","kjv_def":"first-fruits","strongs_def":" a beginning of sacrifice, i.e. the (Jewish) first-fruit (figuratively)","derivation":"from a compound of G575 (ἀπό) and G756 (ἄρχομαι);","pron":"ap-ar-khay'","pos":"Noun Feminine","thayer":"<ol><li>to offer firstlings or firstfruits</li><li>to take away the firstfruits of the productions of the earth which was offered to God. The first portion of the dough, from which sacred loaves were to be prepared. Hence term used of persons consecrated to God for all time.</li><li>persons superior in excellence to others of the same class</li></ol>","xlit":"aparchḗ"},"G3645":{"strongs_def":" to spoil, i.e. slay","derivation":"from G3639 (ὄλεθρος);","translit":"olothreúō","lemma":"ὀλοθρεύω","kjv_def":"destroy","pron":"ol-oth-ryoo'-o","pos":"Verb","thayer":"<ol><li>to destroy</li></ol>","xlit":"olothreúō"},"G1929":{"lemma":"ἐπιδίδωμι","translit":"epidídōmi","kjv_def":"deliver unto, give, let (+ (her drive)), offer","strongs_def":" to give over (by hand or surrender)","derivation":"from G1909 (ἐπί) and G1325 (δίδωμι);","pron":"ep-ee-did'-o-mee","pos":"Verb","thayer":"<ol><li>to hand, give by hand</li><li>to give over<ol type='a'><li>give up to the power or will of one</li></ol></li></ol>","xlit":"epidídōmi"},"G2191":{"kjv_def":"viper","translit":"échidna","lemma":"ἔχιδνα","derivation":"of uncertain origin;","strongs_def":" an adder or other poisonous snake (literally or figuratively)","pron":"ekh'-id-nah","pos":"Noun Feminine","thayer":"<ol><li>a viper, offspring of vipers<ol type='a'><li>addressed to cunning, malignant, wicked men</li></ol></li></ol>","xlit":"échidna"},"G3142":{"translit":"martýrion","lemma":"μαρτύριον","kjv_def":"to be testified, testimony, witness","strongs_def":" something evidential, i.e. (genitive case) evidence given or (specially), the Decalogue (in the sacred Tabernacle)","derivation":"neuter of a presumed derivative of G3144 (μάρτυς);","pron":"mar-too'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>testimony</li></ol>","xlit":"martýrion"},"G2588":{"derivation":"prolonged from a primary (Latin cor, \"heart\");","strongs_def":" the heart, i.e. (figuratively) the thoughts or feelings (mind); also (by analogy) the middle","kjv_def":"(+ broken-)heart(-ed)","translit":"kardía","lemma":"καρδία","pron":"kar-dee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the heart<ol type='a'><li>that organ in the animal body which is the centre of the circulation of the blood, and hence was regarded as the seat of physical life</li><li>denotes the centre of all physical and spiritual life</li><li>the vigour and sense of physical life</li><li>the centre and seat of spiritual life<ol><li>the soul or mind, as it is the fountain and seat of the thoughts, passions, desires, appetites, affections, purposes, endeavours</li><li>of the understanding, the faculty and seat of the intelligence</li><li>of the will and character</li><li>of the soul so far as it is affected and stirred in a bad way or good, or of the soul as the seat of the sensibilities, affections, emotions, desires, appetites, passions</li></ol><li>of the middle or central or inmost part of anything, even though inanimate</li></ol></li></ol>","xlit":"kardía"},"G4614":{"translit":"Sinâ","lemma":"Σινᾶ","kjv_def":"Sina","strongs_def":" Sina (i.e. Sinai), a mountain in Arabia","derivation":"of Hebrew origin (H05514);","pron":"see-nah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sinai = \"thorny\"</p><ol><li>a mountain or rather a mountainous region in the peninsula of Arabia Petraea, made famous by the giving of the Mosaic law</li></ol>","xlit":"Sinâ"},"G2020":{"derivation":"a form of G2017 (ἐπιφαύω);","strongs_def":" to begin to grow light","kjv_def":"begin to dawn, X draw on","lemma":"ἐπιφώσκω","translit":"epiphṓskō","pron":"ep-ee-foce'-ko","pos":"Verb","thayer":"<ol><li>to grow light, to dawn</li></ol>","xlit":"epiphṓskō"},"G4018":{"strongs_def":" something thrown around one, i.e. a mantle, veil","derivation":"neuter of a presumed derivative of G4016 (περιβάλλω);","lemma":"περιβόλαιον","translit":"peribólaion","kjv_def":"covering, vesture","pron":"per-ib-ol'-ah-yon","pos":"Noun Neuter","thayer":"<ol><li>a covering thrown around, a wrapper<ol type='a'><li>a mantle</li><li>a veil</li></ol></li></ol>","xlit":"peribólaion"},"G5559":{"strongs_def":" the body (properly, its surface or skin)","derivation":"probably akin to the base of G5530 (χράομαι) through the idea of handling;","lemma":"χρώς","translit":"chrṓs","kjv_def":"body","pron":"khroce","pos":"Noun Masculine","thayer":"<ol><li>the surface of the body, the skin</li></ol>","xlit":"chrṓs"},"G82":{"kjv_def":"appear not, uncertain","lemma":"ἄδηλος","translit":"ádēlos","derivation":"from G1 (Α) (as a negative particle) and G1212 (δῆλος);","strongs_def":" hidden, figuratively, indistinct","pron":"ad'-ay-los","pos":"Adjective","thayer":"<ol><li>not manifest, indistinct, uncertain, obscure</li></ol>","xlit":"ádēlos"},"G742":{"strongs_def":" Arphaxad, a post-diluvian patriarch","derivation":"of Hebrew origin (H0775);","translit":"Arphaxád","lemma":"Ἀρφαξάδ","kjv_def":"Arphaxad","pron":"ar-fax-ad'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Arphaxad = \"stronghold of Chaldees\"</p><ol><li>the son of Shem and ancestor of Eber</li></ol>","xlit":"Arphaxád"},"G1735":{"derivation":"third person singular present of a compound of G1722 (ἐν) and G1209 (δέχομαι);","strongs_def":" (impersonally) it is accepted in, i.e. admitted (possible)","kjv_def":"can (+ not) be","lemma":"ἐνδέχεται","translit":"endéchetai","pron":"en-dekh'-et-ahee","pos":"Verb","thayer":"<ol><li>to receive, admit, approve, allow</li><li>it can be allowed, is possible, may be</li></ol>","xlit":"endéchetai"},"G3486":{"kjv_def":"Naum","translit":"Naoúm","lemma":"Ναούμ","derivation":"of Hebrew origin (H05151);","strongs_def":" Naum (i.e. Nachum), an Israelite","pron":"nah-oom'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Naum = \"consolation\"</p><ol><li>son of Esli and father of Amos, in the genealogy of Christ</li></ol>","xlit":"Naoúm"},"G1232":{"kjv_def":"make known","translit":"diagnōrízō","lemma":"διαγνωρίζω","derivation":"from G1123 (γραπτός) and G1107 (γνωρίζω);","strongs_def":" to tell abroad","pron":"dee-ag-no-rid'-zo","pos":"Verb","thayer":"<ol><li>to publish abroad, make known thoroughly</li><li>to discriminate</li></ol>","xlit":"diagnōrízō"},"G4591":{"derivation":"from (a mark;","strongs_def":" of uncertain derivation); to indicate","kjv_def":"signify","translit":"sēmaínō","lemma":"σημαίνω","pron":"say-mah'-ee-no","pos":"Verb","thayer":"<ol><li>to give a sign, to signify, indicate</li><li>to make known</li></ol>","xlit":"sēmaínō"},"G1586":{"strongs_def":" to select","derivation":"middle voice from G1537 (ἐκ) and G3004 (λέγω) (in its primary sense);","lemma":"ἐκλέγομαι","translit":"eklégomai","kjv_def":"make choice, choose (out), chosen","pron":"ek-leg'-om-ahee","pos":"Verb","thayer":"<ol><li>to pick out, choose, to pick or choose out for one's self<ol type='a'><li>choosing one out of many, i.e. Jesus choosing his disciples</li><li>choosing one for an office</li><li>of God choosing whom he judged fit to receive his favours and separated from the rest of mankind to be peculiarly his own and to be attended continually by his gracious oversight<ol><li>i.e. the Israelites</li></ol><li>of God the Father choosing Christians, as those whom he set apart from the irreligious multitude as dear unto himself, and whom he has rendered, through faith in Christ, citizens in the Messianic kingdom: (<a class='bible' href='#b59.2.5'>Jas 2:5</a>) so that the ground of the choice lies in Christ and his merits only</li></ol></li></ol>","xlit":"eklégomai"},"G382":{"lemma":"ἀναρίθμητος","translit":"anaríthmētos","kjv_def":"innumerable","strongs_def":" unnumbered, i.e. without number","derivation":"from G1 (Α) (as a negative particle) and a derivative of G705 (ἀριθμέω);","pron":"an-ar-ith'-may-tos","pos":"Adjective","thayer":"<ol><li>innumerable</li></ol>","xlit":"anaríthmētos"},"G5404":{"translit":"phoînix","lemma":"φοῖνιξ","kjv_def":"palm (tree)","strongs_def":" a palm-tree","derivation":"of uncertain derivation;","pron":"foy'-nix","pos":"Noun Masculine","thayer":"<ol><li>a palm tree, date palm</li></ol>","xlit":"phoînix"},"G5451":{"kjv_def":"plant","translit":"phyteía","lemma":"φυτεία","derivation":"from G5452 (φυτεύω);","strongs_def":" trans-planting, i.e. (concretely) a shrub or vegetable","pron":"foo-ti'-ah","pos":"Noun Feminine","thayer":"<ol><li>a planting</li><li>the thing planted, a plant</li></ol>","xlit":"phyteía"},"G3901":{"strongs_def":" to flow by, i.e. (figuratively) carelessly pass (miss)","derivation":"from G3844 (παρά) and the alternate of G4482 (ῥέω);","translit":"pararrhyéō","lemma":"παραῤῥυέω","kjv_def":"let slip","pron":"par-ar-hroo-eh'-o","pos":"Verb","thayer":"<ol><li>to glide by: lest we be carried by, pass by<ol type='a'><li>lest the salvation which these things heard show us how to obtain, slip away from us</li><li>a thing escapes me</li><li>slips my mind</li></ol></li></ol>","xlit":"pararrhyéō"},"G3730":{"kjv_def":"assault","lemma":"ὁρμή","translit":"hormḗ","derivation":"of uncertain affinity;","strongs_def":" a violent impulse, i.e. onset","pron":"hor-may'","pos":"Noun Feminine","thayer":"<ol><li>a violent motion, impulse</li><li>a hostile movement, onset, assault</li></ol>","xlit":"hormḗ"},"G3524":{"kjv_def":"sober","translit":"nēpháleos","lemma":"νηφάλεος","derivation":"from G3525 (νήφω);","strongs_def":" sober, i.e. (figuratively) circumspect","pron":"nay-fal'-eh-os","pos":"Adjective","thayer":"<ol><li>sober, temperate<ol type='a'><li>abstaining from wine, either entirely or at least from its immoderate use</li><li>of things free from all wine, as vessels, offerings</li></ol></li></ol>","xlit":"nēpháleos"},"G1474":{"kjv_def":"lay even with the ground","lemma":"ἐδαφίζω","translit":"edaphízō","derivation":"from G1475 (ἔδαφος);","strongs_def":" to raze","pron":"ed-af-id'-zo","pos":"Verb","thayer":"<ol><li>to throw to the ground<ol type='a'><li>both of cities and buildings, to raze, level with the earth</li><li>metaphorically of men</li></ol></li></ol>","xlit":"edaphízō"},"G5623":{"kjv_def":"advantage, better, prevail, profit","lemma":"ὠφελέω","translit":"ōpheléō","derivation":"from the same as G5622 (ὠφέλεια);","strongs_def":" to be useful, i.e. to benefit","pron":"o-fel-eh'-o","pos":"Verb","thayer":"<ol><li>to assist, to be useful or advantageous, to profit</li></ol>","xlit":"ōpheléō"},"G1184":{"translit":"dektós","lemma":"δεκτός","kjv_def":" accepted(-table)","strongs_def":" approved; (figuratively) propitious","derivation":"from G1209 (δέχομαι);","pron":"dek-tos'","pos":"Adjective","thayer":"<ol><li>accepted, acceptable</li></ol>","xlit":"dektós"},"G2183":{"lemma":"ἐφημερία","translit":"ephēmería","kjv_def":"course","strongs_def":" diurnality, i.e. (specially) the quotidian rotation or class of the Jewish priests' service at the Temple, as distributed by families","derivation":"from G2184 (ἐφήμερος);","pron":"ef-ay-mer-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a service limited to a stated series of days</li><li>the class or course itself of priests who for a week at a time performed the duties of the priestly office. David divided the priests into twenty four classes, each of which in its turn discharged the duties of the office for an entire week, from sabbath to sabbath</li></ol>","xlit":"ephēmería"},"G3494":{"derivation":"from a derivative of G3501 (νέος);","strongs_def":" a youth (up to about forty years)","kjv_def":"young man","translit":"neanías","lemma":"νεανίας","pron":"neh-an-ee'-as","pos":"Noun Masculine","thayer":"<ol><li>a young man</li></ol>","xlit":"neanías"},"G50":{"strongs_def":" not to know (through lack of information or intelligence); by implication, to ignore (through disinclination)","derivation":"from G1 (Α) (as a negative particle) and G3539 (νοιέω);","lemma":"ἀγνοέω","translit":"agnoéō","kjv_def":"(be) ignorant(-ly), not know, not understand, unknown","pron":"ag-no-eh'-o","pos":"Verb","thayer":"<ol><li>to be ignorant, not to know</li><li>not to understand, unknown</li><li>to err or sin through mistake, to be wrong</li></ol>","xlit":"agnoéō"},"G288":{"kjv_def":"vine","translit":"ámpelos","lemma":"ἄμπελος","derivation":"probably from the base of G297 (ἀμφότερος) and that of G257 (ἅλων);","strongs_def":" a vine (as coiling about a support)","pron":"am'-pel-os","pos":"Noun Feminine","thayer":"<ol><li>a vine</li></ol>","xlit":"ámpelos"},"G2891":{"strongs_def":" cumi (i.e. rise!)","derivation":"of Chaldee origin (H06966);","translit":"koûmi","lemma":"κοῦμι","kjv_def":"cumi","pron":"koo'-mee","pos":"Verb","thayer":"<ol><li>arise</li></ol>","xlit":"koûmi"},"G1559":{"kjv_def":"persecute","lemma":"ἐκδιώκω","translit":"ekdiṓkō","derivation":"from G1537 (ἐκ) and G1377 (διώκω);","strongs_def":" to pursue out, i.e. expel or persecute implacably","pron":"ek-dee-o'-ko","pos":"Verb","thayer":"<ol><li>to drive out, banish</li><li>to pursue<ol type='a'><li>to persecute, oppress with calamities</li></ol></li></ol>","xlit":"ekdiṓkō"},"G3534":{"translit":"nîkos","lemma":"νῖκος","kjv_def":"victory","strongs_def":" a conquest (concretely), i.e. (by implication) triumph","derivation":"from G3529 (νίκη);","pron":"nee'-kos","pos":"Noun Neuter","thayer":"<ol><li>victory</li><li>to utterly vanquish</li></ol>","xlit":"nîkos"},"G1545":{"kjv_def":"end, way to escape","lemma":"ἔκβασις","translit":"ékbasis","derivation":"from a compound of G1537 (ἐκ) and the base of G939 (βάσις) (meaning to go out);","strongs_def":" an exit (literally or figuratively)","pron":"ek'-bas-is","pos":"Noun Feminine","thayer":"<ol><li>an egress, way out, exit<ol type='a'><li>applied figuratively to the way of escape from temptation</li></ol><li>the issue referring to the end of one's life<ol type='a'><li><a class='bible' href='#b58.13.7'>Heb 13:7</a> refers not only to end of physical life, but the manner in which they closed a well spent life as exhibited by their spirit in dying</li></ol></li></ol>","xlit":"ékbasis"},"G1564":{"kjv_def":"from that place, (from) thence, there","translit":"ekeîthen","lemma":"ἐκεῖθεν","derivation":"from G1563 (ἐκεῖ);","strongs_def":" thence","pron":"ek-i'-then","pos":"Adverb","thayer":"<ol><li>thence, from that place</li></ol>","xlit":"ekeîthen"},"G4543":{"kjv_def":"Samothracia","translit":"Samothráikē","lemma":"Σαμοθρᾴκη","derivation":"from G4544 (Σάμος) and (Thrace);","strongs_def":" Samo-thrace (Samos of Thrace), an island in the Mediterranean","pron":"sam-oth-rak'-ay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Samothracia = \"a sign of rags\"</p><ol><li>an island on the Aegean Sea, about 38 Miles (60 km) from the coast of Thrace at the mouth of the river Hebrus</li></ol>","xlit":"Samothráikē"},"G1529":{"strongs_def":" an entrance (literally or figuratively)","derivation":"from G1519 (εἰς) and G3598 (ὁδός);","translit":"eísodos","lemma":"εἴσοδος","kjv_def":"coming, enter(-ing) in (to)","pron":"ice'-od-os","pos":"Noun Feminine","thayer":"<ol><li>an entrance<ol type='a'><li>the place or way leading into a place (as a gate)</li><li>the act of entering</li></ol></li></ol>","xlit":"eísodos"},"G3434":{"kjv_def":"Moloch","translit":"Molóch","lemma":"Μολόχ","derivation":"of Hebrew origin (H04432);","strongs_def":" Moloch (i.e. Molek), an idol","pron":"mol-okh'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Molech = \"king\"</p><ol><li>the name of the idol god of the Ammonites, to which human victims, particularly young children were offered in sacrifice. Its image was a hollow brazen figure, with the head of an ox, and outstretched human arms. It was heated red hot by a fire from within, and the little ones placed in its arms to be slowly burned, while to prevent the parents from hearing the dying cries, the sacrificing priests beat drums</li></ol>","xlit":"Molóch"},"G251":{"kjv_def":"salt","translit":"háls","lemma":"ἅλς","derivation":"a primary word;","strongs_def":" \"salt\"","pron":"Thayer Definition","pos":"Noun Masculine","thayer":"<ol><li>salt</li></ol>","xlit":"háls"},"G1313":{"kjv_def":"differing, divers, more excellent","translit":"diáphoros","lemma":"διάφορος","derivation":"from G1308 (διαφέρω);","strongs_def":" varying; also surpassing","pron":"dee-af'-or-os","pos":"Adjective","thayer":"<ol><li>different, varying in kind</li><li>excellent, surpassing</li></ol>","xlit":"diáphoros"},"G3525":{"kjv_def":"be sober, watch","translit":"nḗphō","lemma":"νήφω","derivation":"of uncertain affinity;","strongs_def":" to abstain from wine (keep sober), i.e. (figuratively) be discreet","pron":"nay'-fo","pos":"Verb","thayer":"<ol><li>to be sober, to be calm and collected in spirit</li><li>to be temperate, dispassionate, circumspect</li></ol>","xlit":"nḗphō"},"G5266":{"derivation":"from G5265 (ὑποδέω);","strongs_def":" something bound under the feet, i.e. a shoe or sandal","kjv_def":"shoe","lemma":"ὑπόδημα","translit":"hypódēma","pron":"hoop-od'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>what is bound under, a sandal, a sole fastened to the foot with thongs</li></ol>","xlit":"hypódēma"},"G3550":{"kjv_def":"lawgiver","translit":"nomothétēs","lemma":"νομοθέτης","derivation":"from G3551 (νόμος) and a derivative of G5087 (τίθημι);","strongs_def":" a legislator","pron":"nom-oth-et'-ace","pos":"Noun Masculine","thayer":"<ol><li>a lawgiver</li></ol>","xlit":"nomothétēs"},"G1032":{"derivation":"a primary verb;","strongs_def":" to swell out, i.e. (by implication) to gush","kjv_def":"send forth","translit":"brýō","lemma":"βρύω","pron":"broo'-o","pos":"Verb","thayer":"<ol><li>to abound, gush forth, teem with juices</li><li>to send forth abundantly, to teem</li></ol>","xlit":"brýō"},"G37":{"kjv_def":"hallow, be holy, sanctify","lemma":"ἁγιάζω","translit":"hagiázō","derivation":"from G40 (ἅγιος);","strongs_def":" to make holy, i.e. (ceremonially) purify or consecrate; (mentally) to venerate","pron":"hag-ee-ad'-zo","pos":"Verb","thayer":"<ol><li>to render or acknowledge, or to be venerable or hallow</li><li>to separate from profane things and dedicate to God<ol type='a'><li>consecrate things to God</li><li>dedicate people to God</li></ol><li>to purify<ol type='a'><li>to cleanse externally</li><li>to purify by expiation: free from the guilt of sin</li><li>to purify internally by renewing of the soul</li></ol></li></ol>","xlit":"hagiázō"},"G2570":{"derivation":"of uncertain affinity; properly, beautiful, but chiefly (figuratively) good (literally or morally), i.e. valuable or virtuous (for appearance or use, and thus distinguished from G18 (ἀγαθός), which is properly intrinsic)","kjv_def":"X better, fair, good(-ly), honest, meet, well, worthy","translit":"kalós","lemma":"καλός","pron":"kal-os'","pos":"Adjective","thayer":"<ol><li>beautiful, handsome, excellent, eminent, choice, surpassing, precious, useful, suitable, commendable, admirable<ol type='a'><li>beautiful to look at, shapely, magnificent</li><li>good, excellent in its nature and characteristics, and therefore well adapted to its ends<ol><li>genuine, approved</li><li>precious</li><li>joined to names of men designated by their office, competent, able, such as one ought to be</li><li>praiseworthy, noble</li></ol><li>beautiful by reason of purity of heart and life, and hence praiseworthy<ol><li>morally good, noble</li></ol><li>honourable, conferring honour</li><li>affecting the mind agreeably, comforting and confirming</li></ol></li></ol>","xlit":"kalós"},"G1252":{"lemma":"διακρίνω","translit":"diakrínō","kjv_def":"contend, make (to) differ(-ence), discern, doubt, judge, be partial, stagger, waver","strongs_def":" to separate thoroughly, i.e. (literally and reflexively) to withdraw from, or (by implication) oppose; figuratively, to discriminate (by implication, decide), or (reflexively) hesitate","derivation":"from G1223 (διά) and G2919 (κρίνω);","pron":"dee-ak-ree'-no","pos":"Verb","thayer":"<ol><li>to separate, make a distinction, discriminate, to prefer</li><li>to learn by discrimination, to try, decide<ol type='a'><li>to determine, give judgment, decide a dispute</li></ol><li>to withdraw from one, desert</li><li>to separate one's self in a hostile spirit, to oppose, strive with dispute, contend</li><li>to be at variance with one's self, hesitate, doubt</li></ol>","xlit":"diakrínō"},"G2745":{"strongs_def":" a boast (properly, the object; by implication, the act) in a good or a bad sense","derivation":"from G2744 (καυχάομαι);","translit":"kaúchēma","lemma":"καύχημα","kjv_def":"boasting, (whereof) to glory (of), glorying, rejoice(-ing)","pron":"kow'-khay-mah","pos":"Noun Neuter","thayer":"<ol><li>that of which one glories or can glory, matter or ground of glorying</li><li>a glorying or boasting</li></ol>","xlit":"kaúchēma"},"G592":{"strongs_def":" to disjoin (by a boundary, figuratively, a party)","derivation":"from G575 (ἀπό) and a compound of G223 (Ἀλέξανδρος) and G3724 (ὁρίζω);","translit":"apodiorízō","lemma":"ἀποδιορίζω","kjv_def":"separate","pron":"ap-od-ee-or-id'-zo","pos":"Verb","thayer":"<ol><li>to disjoin, part, separate from another</li><li>making divisions or separations</li></ol>","xlit":"apodiorízō"},"G4197":{"strongs_def":" travel (by land); figuratively (plural) proceedings, i.e. career","derivation":"from G4198 (πορεύομαι);","translit":"poreía","lemma":"πορεία","kjv_def":"journey(-ing), ways","pron":"por-i'-ah","thayer":"<ol><li>a journey</li><li>a going, that is: purpose, pursuit, undertaking</li></ol>","xlit":"poreía"},"G1405":{"kjv_def":"take","lemma":"δράσσομαι","translit":"drássomai","derivation":"perhaps akin to the base of G1404 (δράκων) (through the idea of capturing);","strongs_def":" to grasp, i.e. (figuratively) entrap","pron":"dras'-som-ahee","pos":"Verb","thayer":"<ol><li>to grasp with the hand, take</li></ol>","xlit":"drássomai"},"G339":{"derivation":"from G303 (ἀνά) and G2523 (καθίζω);","strongs_def":" properly, to set up, i.e. (reflexively) to sit up","kjv_def":"sit up","lemma":"ἀνακαθίζω","translit":"anakathízō","pron":"an-ak-ath-id'-zo","pos":"Verb","thayer":"<ol><li>to raise one's self and sit upright, to sit up, erect</li></ol>","xlit":"anakathízō"},"G1997":{"strongs_def":" a complete collection; especially a Christian meeting (for worship)","derivation":"from G1996 (ἐπισυνάγω);","lemma":"ἐπισυναγωγή","translit":"episynagōgḗ","kjv_def":"assembling (gathering) together","pron":"ep-ee-soon-ag-o-gay'","pos":"Noun Feminine","thayer":"<ol><li>a gathering together in one place</li><li>the (religious) assembly (of Christians)</li></ol>","xlit":"episynagōgḗ"},"G3429":{"kjv_def":"commit adultery","translit":"moicháō","lemma":"μοιχάω","derivation":"from G3432 (μοιχός);","strongs_def":" (middle voice) to commit adultery","pron":"moy-khah'-o","pos":"Verb","thayer":"<ol><li>to have unlawful intercourse with another's wife, to commit adultery with</li></ol>","xlit":"moicháō"},"G2495":{"strongs_def":" Jonas (i.e. Jonah), the name of two Israelites","derivation":"of Hebrew origin (H03124);","lemma":"Ἰωνᾶς","translit":"Iōnâs","kjv_def":"Jonas","pron":"ee-o-nas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jonah or Jonas = \"dove\"</p><ol><li>the fifth minor prophet, the son of Amittai, and a native of Gath-hepher and lived during the reign of Jeroboam II, king of Israel</li><li>Jonas, the father of Peter</li></ol>","xlit":"Iōnâs"},"G4673":{"kjv_def":"bier","translit":"sorós","lemma":"σορός","derivation":"probably akin to the base of G4987 (σωρεύω);","strongs_def":" a funereal receptacle (urn, coffin), i.e. (by analogy) a bier","pron":"sor-os'","pos":"Noun Feminine","thayer":"<ol><li>an urn or receptacle for keeping the bones of the dead</li><li>the funeral couch or bier on which the Jews carried their dead forth to burial</li></ol>","xlit":"sorós"},"G1500":{"kjv_def":"without a cause, (in) vain(-ly)","translit":"eikē","lemma":"εἰκῆ","derivation":"probably from G1502 (εἴκω) (through the idea of failure);","strongs_def":" idly, i.e. without reason (or effect)","pron":"i-kay'","pos":"Adverb","thayer":"<ol><li>inconsiderably, without purpose, without just cause</li><li>in vain<ol type='a'><li>without success or effort</li></ol></li></ol>","xlit":"eikē"},"G3827":{"lemma":"πάμπολυς","translit":"pámpolys","kjv_def":"very great","strongs_def":" full many, i.e. immense","derivation":"from G3956 (πᾶς) and G4183 (πολύς);","pron":"pam-pol-ooce","pos":"Adjective","thayer":"<ol><li>very great</li></ol>","xlit":"pámpolys"},"G468":{"kjv_def":"recompense","lemma":"ἀνταπόδομα","translit":"antapódoma","derivation":"from G467 (ἀνταποδίδωμι);","strongs_def":" a requital (properly, the thing)","pron":"an-tap-od'-om-ah","pos":"Noun Neuter","thayer":"<ol><li>the thing paid back, requital</li></ol>","xlit":"antapódoma"},"G2133":{"derivation":"from the same as G2132 (εὐνοέω);","strongs_def":" kindness; euphemistically, conjugal duty","kjv_def":"benevolence, good will","translit":"eúnoia","lemma":"εὔνοια","pron":"yoo'-noy-ah","pos":"Noun Feminine","thayer":"<ol><li>good will, kindness</li></ol>","xlit":"eúnoia"},"G3857":{"derivation":"of Oriental origin (compare H06508);","strongs_def":" a park, i.e. (specially), an Eden (place of future happiness, \"paradise\")","kjv_def":"paradise","lemma":"παράδεισος","translit":"parádeisos","pron":"par-ad'-i-sos","pos":"Noun Masculine","thayer":"<ol><li>among the Persians a grand enclosure or preserve, hunting ground, park, shady and well watered, in which wild animals, were kept for the hunt; it was enclosed by walls and furnished with towers for the hunters</li><li>a garden, pleasure ground<ol type='a'><li>grove, park</li></ol><li>the part of Hades which was thought by the later Jews to be the abode of the souls of pious until the resurrection: but some understand this to be a heavenly paradise</li><li>the upper regions of the heavens. According to the early church Fathers, the paradise in which our first parents dwelt before the fall still exists, neither on the earth or in the heavens, but above and beyond the world</li><li>heaven</li></ol>","xlit":"parádeisos"},"G3638":{"derivation":"a primary numeral;","strongs_def":" \"eight\"","kjv_def":"eight","lemma":"ὀκτώ","translit":"oktṓ","pron":"ok-to'","pos":"Noun","thayer":"<ol><li>eight</li></ol>","xlit":"oktṓ"},"G2118":{"strongs_def":" rectitude","derivation":"from G2117 (εὐθύς);","translit":"euthýtēs","lemma":"εὐθύτης","kjv_def":"righteousness","pron":"yoo-thoo'-tace","pos":"Noun Feminine","thayer":"<ol><li>rectitude, unrighteousness</li></ol>","xlit":"euthýtēs"},"G3151":{"strongs_def":" an idle (i.e. senseless or mischievous) talker, i.e. a wrangler","derivation":"from G3152 (μάταιος) and G3004 (λέγω);","lemma":"ματαιολόγος","translit":"mataiológos","kjv_def":"vain talker","pron":"mat-ah-yol-og'-os","pos":"Noun Masculine","thayer":"<ol><li>an idle talker, one who utters empty senseless things</li></ol>","xlit":"mataiológos"},"G2237":{"derivation":"from (to please);","strongs_def":" sensual delight; by implication, desire","kjv_def":"lust, pleasure","lemma":"ἡδονή","translit":"hēdonḗ","pron":"hay-don-ay'","pos":"Noun Feminine","thayer":"<ol><li>pleasure</li><li>desires for pleasure</li></ol>","xlit":"hēdonḗ"},"G3526":{"kjv_def":"Niger","translit":"Níger","lemma":"Νίγερ","derivation":"of Latin origin;","strongs_def":" black; Niger, a Christian","pron":"neeg'-er","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Niger = \"black\"</p><ol><li>surname of the prophet Simeon</li></ol>","xlit":"Níger"},"G5155":{"derivation":"from G2359 (θρίξ);","strongs_def":" hairy, i.e. made of hair (mohair)","kjv_def":"of hair","lemma":"τρίχινος","translit":"tríchinos","pron":"trikh'-ee-nos","pos":"Adjective","thayer":"<ol><li>made of hair</li></ol>","xlit":"tríchinos"},"G914":{"derivation":"of Hebrew origin (H01296);","strongs_def":" Barachias (i.e. Berechijah), an Israelite","kjv_def":"Barachias","lemma":"Βαραχίας","translit":"Barachías","pron":"bar-akh-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barachiah = \"Jehovah blesses\"</p><ol><li>said to be the father of the Zachariah slain in the temple</li></ol>","xlit":"Barachías"},"G4691":{"strongs_def":" a seed-picker (as the crow), i.e. (figuratively) a sponger, loafer (specially, a gossip or trifler in talk)","derivation":"from G4690 (σπέρμα) and G3004 (λέγω);","translit":"spermológos","lemma":"σπερμολόγος","kjv_def":"babbler","pron":"sper-mol-og'-os","pos":"Adjective","thayer":"<ol><li>picking up seed<ol type='a'><li>of birds, especially of the crow or daw that picks up grain in fields</li></ol><li>metaphorically<ol type='a'><li>lounging about the market place and picking up a substance by whatever may chance to fall from the loads of merchandise</li><li>hence, beggarly, abject, vile, (a parasite)</li><li>getting a living by flattery and bufferoonery</li><li>an empty talker, babbler</li></ol></li></ol>","xlit":"spermológos"},"G2352":{"lemma":"θραύω","translit":"thraúō","kjv_def":"bruise","strongs_def":" to crush","derivation":"a primary verb;","pron":"throw'-o","pos":"Verb","thayer":"<ol><li>to break, break in pieces, shatter, smite through</li></ol>","xlit":"thraúō"},"G364":{"strongs_def":" recollection","derivation":"from G363 (ἀναμιμνήσκω);","lemma":"ἀνάμνησις","translit":"anámnēsis","kjv_def":"remembrance (again)","pron":"an-am'-nay-sis","pos":"Noun Feminine","thayer":"<ol><li>a remembering, recollection</li></ol>","xlit":"anámnēsis"},"G3169":{"strongs_def":" befitting greatness or magnificence (majestic)","derivation":"from G3173 (μέγας) and G4241 (πρέπω);","translit":"megaloprepḗs","lemma":"μεγαλοπρεπής","kjv_def":"excellent","pron":"meg-al-op-rep-ace'","pos":"Adjective","thayer":"<ol><li>befitting a great man, magnificent, splendid</li><li>full of majesty, majestic</li></ol>","xlit":"megaloprepḗs"},"G3445":{"translit":"morphóō","lemma":"μορφόω","kjv_def":"form","strongs_def":" to fashion (figuratively)","derivation":"from the same as G3444 (μορφή);","pron":"mor-fo'-o","pos":"Verb","thayer":"<ol><li>to form</li></ol>","xlit":"morphóō"},"G2115":{"lemma":"εὔθυμος","translit":"eúthymos","kjv_def":"of good cheer, the more cheerfully","strongs_def":" in fine spirits, i.e. cheerful","derivation":"from G2095 (εὖ) and G2372 (θυμός);","pron":"yoo'-thoo-mos","pos":"Adjective","thayer":"<ol><li>well disposed, kind</li><li>of good cheer, of good courage</li></ol>","xlit":"eúthymos"},"G5090":{"lemma":"Τιμαῖος","translit":"Timaîos","kjv_def":"Timæus","strongs_def":" Timæus (i.e. Timay), an Israelite","derivation":"probably of Chaldee origin (compare H02931);","pron":"tim'-ah-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Timaeus = \"highly prized\"</p><ol><li>the father of the blind man, Bartimaeus</li></ol>","xlit":"Timaîos"},"G4732":{"lemma":"στερεόω","translit":"stereóō","kjv_def":"establish, receive strength, make strong","strongs_def":" to solidify, i.e. confirm (literally or figuratively)","derivation":"from G4731 (στερεός);","pron":"ster-eh-o'-o","pos":"Verb","thayer":"<ol><li>to make solid, make firm, strengthen, make strong<ol type='a'><li>of the body of anyone</li></ol></li></ol>","xlit":"stereóō"},"G3030":{"derivation":"of foreign origin (H03828);","strongs_def":" the incense-tree, i.e. (by implication) incense itself","kjv_def":"frankincense","translit":"líbanos","lemma":"λίβανος","pron":"lib'-an-os","pos":"Noun Masculine","thayer":"<ol><li>the frankincense tree</li><li>the perfume, frankincense</li></ol>","xlit":"líbanos"},"G4966":{"strongs_def":" Sychem (i.e. Shekem), the name of a Canaanite and of a place in Palestine","derivation":"of Hebrew origin (H07927);","translit":"Sychém","lemma":"Συχέμ","kjv_def":"Sychem","pron":"soo-khem'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Shechem = \"shoulder (literal early rising): diligence\"</p><ol><li>a city in Ephraim</li><li>the son of Emmor</li></ol>","xlit":"Sychém"},"G611":{"strongs_def":" to conclude for oneself, i.e. (by implication) to respond; by Hebraism (compare H06030) to begin to speak (where an address is expected)","derivation":"from G575 (ἀπό) and ;","lemma":"ἀποκρίνομαι","translit":"apokrínomai","kjv_def":"answer","pron":"ap-ok-ree'-nom-ahee","pos":"Verb","thayer":"<ol><li>to give an answer to a question proposed, to answer</li><li>to begin to speak, but always where something has preceded</li></ol>","xlit":"apokrínomai"},"G2029":{"derivation":"from G1909 (ἐπί) and a derivative of G3700 (ὀπτάνομαι);","strongs_def":" to inspect, i.e. watch","kjv_def":"behold","lemma":"ἐποπτεύω","translit":"epopteúō","pron":"ep-opt-yoo'-o","pos":"Verb","thayer":"<ol><li>to be an overseer</li><li>to look upon, view attentively</li><li>to watch</li></ol>","xlit":"epopteúō"},"G5120":{"derivation":"properly, the genitive case of G3588 (ὁ);","strongs_def":" sometimes used for G5127 (τούτου); of this person","kjv_def":"his","translit":"toû","lemma":"τοῦ","pron":"too","xlit":"toû"},"G4010":{"strongs_def":" fortified; Pergamus, a place in Asia Minor","derivation":"from G4444 (πύργος);","translit":"Pérgamos","lemma":"Πέργαμος","kjv_def":"Pergamos","pron":"per'-gam-os","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Pergamos = \"height or elevation\"</p><ol><li>a city of Mysia Minor, in Asia Minor, the seat of the dynasties of Attalus and Eumenes, famous for its temple of Aesculapius and the invention and manufacture of parchment. The river Selinus flowed through it and the Cetius ran past it. It was the birthplace of the physician Galen, and had a great royal library. It had a Christian church.</li></ol>","xlit":"Pérgamos"},"G4948":{"derivation":"from the same as G4947 (Συρία);","strongs_def":" a Syran (i.e. probably Tyrian), a native of Syria","kjv_def":"Syrian","lemma":"Σύρος","translit":"Sýros","pron":"soo'-ros","pos":"Noun Masculine","thayer":"<ol><li>an inhabitant of Syria</li></ol>","xlit":"Sýros"},"G1205":{"strongs_def":" come hither!","derivation":"from G1204 (δεῦρο) and an imperative form of (to go);","lemma":"δεῦτε","translit":"deûte","kjv_def":"come, X follow","pron":"dyoo'-teh","pos":"Adverb","thayer":"<ol><li>come hither, come here, come</li><li>interjection, come!, come now!</li></ol>","xlit":"deûte"},"G4729":{"strongs_def":" to hem in closely, i.e. (figuratively) cramp","derivation":"from the same as G4730 (στενοχωρία);","lemma":"στενοχωρέω","translit":"stenochōréō","kjv_def":"distress, straiten","pron":"sten-okh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to be in a narrow place</li><li>to straiten, compress, cramp, reduce to straits<ol type='a'><li>to be sorely straitened in spirit</li></ol></li></ol>","xlit":"stenochōréō"},"G2461":{"kjv_def":"horse(-men)","lemma":"ἱππικόν","translit":"hippikón","derivation":"neuter of a derivative of G2462 (ἵππος);","strongs_def":" the cavalry force","pron":"hip-pee-kon'","pos":"Adjective","thayer":"<ol><li>equestrian, the horse(men), cavalry</li></ol>","xlit":"hippikón"},"G575":{"derivation":"a primary particle;","strongs_def":" \"off,\" i.e. away (from something near), in various senses (of place, time, or relation; literal or figurative)","kjv_def":"(X here-)after, ago, at, because of, before, by (the space of), for(-th), from, in, (out) of, off, (up-)on(-ce), since, with","lemma":"ἀπό","translit":"apó","pron":"apo'","thayer":"<ol><li>of separation<ol type='a'><li>of local separation, after verbs of motion from a place, i.e. of departing, of fleeing, ...</li><li>of separation of a part from the whole<ol><li>where of a whole some part is taken</li></ol><li>of any kind of separation of one thing from another by which the union or fellowship of the two is destroyed</li><li>of a state of separation, that is of distance<ol><li>physical, of distance of place</li><li>temporal, of distance of time</li></ol></li></ol><li>of origin<ol type='a'><li>of the place whence anything is, comes, befalls, is taken</li><li>of origin of a cause</li></ol></li></ol>","xlit":"apó"},"G907":{"strongs_def":" to immerse, submerge; to make whelmed (i.e. fully wet); used only (in the New Testament) of ceremonial ablution, especially (technically) of the ordinance of Christian baptism","derivation":"from a derivative of G911 (βάπτω);","translit":"baptízō","lemma":"βαπτίζω","kjv_def":"Baptist, baptize, wash","pron":"bap-tid'-zo","thayer":"<ol><li>to dip repeatedly, to immerse, to submerge (of vessels sunk)</li><li>to cleanse by dipping or submerging, to wash, to make clean with water, to wash one's self, bathe</li><li>to overwhelm</li></ol>","xlit":"baptízō"},"G3416":{"kjv_def":"Mnason","lemma":"Μνάσων","translit":"Mnásōn","derivation":"of uncertain origin;","strongs_def":" Mnason, a Christian","pron":"mnah'-sohn","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mnason = \"remembering\"</p><ol><li>a Christian from Cyprus, a common Greek name</li></ol>","xlit":"Mnásōn"},"G1569":{"strongs_def":" utterly astounded","derivation":"from G1537 (ἐκ) and G2285 (θάμβος);","translit":"ékthambos","lemma":"ἔκθαμβος","kjv_def":"greatly wondering","pron":"ek'-tham-bos","pos":"Adjective","thayer":"<ol><li>quite astonished, amazed</li><li>terrifying, dreadful</li><li>wonder or marvel greatly</li></ol>","xlit":"ékthambos"},"G3475":{"derivation":"of Hebrew origin; (H04872);","strongs_def":" Moseus, Moses, or Mouses (i.e. Mosheh), the Hebrew lawgiver","kjv_def":"Moses","translit":"Mōseús","lemma":"Μωσεύς","pron":"moce-yoos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Moses = \"drawing out\"</p><ol><li>the legislator of the Jewish people and in a certain sense the founder of the Jewish religion. He wrote the first five books of the Bible, commonly referred to as the Books of Moses.</li></ol>","xlit":"Mōseús"},"G4487":{"kjv_def":"+ evil, + nothing, saying, word","translit":"rhēma","lemma":"ῥῆμα","derivation":"from G4483 (ῥέω);","strongs_def":" an utterance (individually, collectively or specially),; by implication, a matter or topic (especially of narration, command or dispute); with a negative naught whatever","pron":"hray'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is or has been uttered by the living voice, thing spoken, word<ol type='a'><li>any sound produced by the voice and having definite meaning</li><li>speech, discourse<ol><li>what one has said</li></ol><li>a series of words joined together into a sentence (a declaration of one's mind made in words)<ol><li>an utterance</li><li>a saying of any sort as a message, a narrative<ol type='a'><li>concerning some occurrence</li></ol></li></ol></li></ol><li>subject matter of speech, thing spoken of<ol type='a'><li>so far forth as it is a matter of narration</li><li>so far as it is a matter of command</li><li>a matter of dispute, case at law</li></ol></li></ol>","xlit":"rhēma"},"G885":{"lemma":"Ἀχείμ","translit":"Acheím","kjv_def":"Achim","strongs_def":" Achim, an Israelite","derivation":"probably of Hebrew origin (compare H03137);","pron":"akh-ime'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Achim = \"the Lord will establish\"</p><ol><li>one of the ancestors of Christ, his name is not mentioned in the OT</li></ol>","xlit":"Acheím"},"G3143":{"strongs_def":" to be adduced as a witness, i.e. (figuratively) to obtest (in affirmation or exhortation)","derivation":"middle voice from G3144 (μάρτυς);","translit":"martýromai","lemma":"μαρτύρομαι","kjv_def":"take to record, testify","pron":"mar-too'-rom-ahee","pos":"Verb","thayer":"<ol><li>to cite a witness, bring forward a witness, call to witness<ol type='a'><li>to affirm be appeal to God, to declare solemnly, protest</li></ol><li>to conjure, beseech as in God's name, exhort solemnly</li></ol>","xlit":"martýromai"},"G356":{"strongs_def":" proportion","derivation":"from a compound of G303 (ἀνά) and G3056 (λόγος);","lemma":"ἀναλογία","translit":"analogía","kjv_def":"proportion","pron":"an-al-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>proportion</li></ol>","xlit":"analogía"},"G1075":{"derivation":"from G1074 (γενεά) and G3056 (λόγος);","strongs_def":" to reckon by generations, i.e. trace in genealogy","kjv_def":"count by descent","lemma":"γενεαλογέω","translit":"genealogéō","pron":"ghen-eh-al-og-eh'-o","pos":"Verb","thayer":"<ol><li>to recount a family's origin and lineage, trace ancestry</li><li>to draw one's origin, derive one's pedigree</li></ol>","xlit":"genealogéō"},"G3131":{"derivation":"of Hebrew origin (H04478);","strongs_def":" manna (i.e. man), an edible gum","kjv_def":"manna","translit":"mánna","lemma":"μάννα","pron":"man'-nah","pos":"Noun Neuter","thayer":"<strong>Thayer Definition</strong>: manna = \"what is it\"</p><ol><li>the food that nourished the Israelites for forty years in the wilderness</li><li>of the manna was kept in the ark of the covenant</li><li>symbolically, that which is kept in the heavenly temple for the food of angels and the blessed</li></ol>","xlit":"mánna"},"G1760":{"strongs_def":" to be inspirited, i.e. ponder","derivation":"from a compound of G1722 (ἐν) and G2372 (θυμός);","translit":"enthyméomai","lemma":"ἐνθυμέομαι","kjv_def":"think","pron":"en-thoo-meh'-om-ahee","pos":"Verb","thayer":"<ol><li>to bring to mind, revolve in mind, ponder</li><li>to think, to deliberate</li></ol>","xlit":"enthyméomai"},"G3020":{"strongs_def":" Levitic, i.e. relating to the Levites","derivation":"from G3019 (Λευΐτης);","translit":"Leuïtikós","lemma":"Λευϊτικός","kjv_def":"Levitical","pron":"lyoo-it'-ee-kos","pos":"Adjective","thayer":"<ol><li>Levitical, pertaining to the Levites</li></ol>","xlit":"Leuïtikós"},"G3078":{"strongs_def":" grief-dispelling; Lysanias, a governor of Abilene","derivation":"from G3080 (λύσις) and (trouble);","translit":"Lysanías","lemma":"Λυσανίας","kjv_def":"Lysanias","pron":"loo-san-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lysanias = \"that drives away sorrow\"</p><ol><li>a tetrarch of Abilene (i.e. the district around Abila) in the thirteenth year of Tiberias (A.D. 29), at the time when Herod Antipas was tetrarch of Galilee and when Herod Philip was tetrarch of Ituraea and Trachonitis</li></ol>","xlit":"Lysanías"},"G3903":{"translit":"paraskeuázō","lemma":"παρασκευάζω","kjv_def":"prepare self, be (make) ready","strongs_def":" to furnish aside, i.e. get ready","derivation":"from G3844 (παρά) and a derivative of G4632 (σκεῦος);","pron":"par-ask-yoo-ad'-zo","pos":"Verb","thayer":"<ol><li>to make one's self ready, to prepare one's self</li><li>have prepared one's self, to be prepared or ready</li></ol>","xlit":"paraskeuázō"},"G2851":{"translit":"kólasis","lemma":"κόλασις","kjv_def":"punishment, torment","strongs_def":" penal infliction","derivation":"from G2849 (κολάζω);","pron":"kol'-as-is","pos":"Noun Feminine","thayer":"<ol><li>correction, punishment, penalty</li></ol>","xlit":"kólasis"},"G1607":{"kjv_def":"come (forth, out of), depart, go (forth, out), issue, proceed (out of)","lemma":"ἐκπορεύομαι","translit":"ekporeúomai","derivation":"from G1537 (ἐκ) and G4198 (πορεύομαι);","strongs_def":" to depart, be discharged, proceed, project","pron":"ek-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to go forth, go out, depart</li><li>metaphorically<ol type='a'><li>to come forth, to issue, to proceed<ol><li>of feelings, affections, deeds, sayings</li></ol><li>to flow forth<ol><li>of a river</li></ol><li>to project, from the mouth of one</li><li>to spread abroad, of a rumour</li></ol></li></ol>","xlit":"ekporeúomai"},"G5287":{"derivation":"from a compound of G5259 (ὑπό) and G2476 (ἵστημι);","strongs_def":" a setting under (support), i.e. (figuratively) concretely, essence, or abstractly, assurance (objectively or subjectively)","kjv_def":"confidence, confident, person, substance","lemma":"ὑπόστασις","translit":"hypóstasis","pron":"hoop-os'-tas-is","pos":"Noun Feminine","thayer":"<ol><li>a setting or placing under<ol type='a'><li>thing put under, substructure, foundation</li></ol><li>that which has foundation, is firm<ol type='a'><li>that which has actual existence<ol><li>a substance, real being</li></ol><li>the substantial quality, nature, of a person or thing</li><li>the steadfastness of mind, firmness, courage, resolution<ol><li>confidence, firm trust, assurance</li></ol></li></ol></li></ol>","xlit":"hypóstasis"},"G1740":{"kjv_def":"glorify","lemma":"ἐνδοξάζω","translit":"endoxázō","derivation":"from G1741 (ἔνδοξος);","strongs_def":" to glorify","pron":"en-dox-ad'-zo","pos":"Verb","thayer":"<ol><li>glorify, adorn with glory</li></ol>","xlit":"endoxázō"},"G1599":{"strongs_def":" to despatch","derivation":"from G1537 (ἐκ) and G3992 (πέμπω);","lemma":"ἐκπέμπω","translit":"ekpémpō","kjv_def":"send away (forth)","pron":"ek-pem'-po","pos":"Verb","thayer":"<ol><li>to send away, send forth</li></ol>","xlit":"ekpémpō"},"G3375":{"translit":"mḗn","lemma":"μήν","kjv_def":"+ surely","strongs_def":" a particle of affirmation (only with G2229 (ἦ)); assuredly","derivation":"a stronger form of G3303 (μέν);","pron":"mane","thayer":"<ol><li>verily, certainly, truly</li></ol>","xlit":"mḗn"},"G3563":{"strongs_def":" the intellect, i.e. mind (divine or human; in thought, feeling, or will); by implication, meaning","derivation":"probably from the base of G1097 (γινώσκω);","translit":"noûs","lemma":"νοῦς","kjv_def":"mind, understanding","pron":"nooce","pos":"Noun Masculine","thayer":"<ol><li>the mind, comprising alike the faculties of perceiving and understanding and those of feeling, judging, determining<ol type='a'><li>the intellectual faculty, the understanding</li><li>reason in the narrower sense, as the capacity for spiritual truth, the higher powers of the soul, the faculty of perceiving divine things, of recognising goodness and of hating evil</li><li>the power of considering and judging soberly, calmly and impartially</li></ol><li>a particular mode of thinking and judging, i.e thoughts, feelings, purposes, desires</li></ol>","xlit":"noûs"},"G3461":{"derivation":"from G3463 (μύριοι);","strongs_def":" a ten-thousand; by extension, a \"myriad\" or indefinite number","kjv_def":"ten thousand","translit":"myriás","lemma":"μυριάς","pron":"moo-ree'-as","pos":"Noun Feminine","thayer":"<ol><li>ten thousand</li><li>an innumerable multitude, an unlimited number</li><li>innumerable hosts</li></ol>","xlit":"myriás"},"G1673":{"derivation":"from G1672 (Ἕλλην);","strongs_def":" Hellenic, i.e. Grecian (in language)","kjv_def":"Greek","lemma":"Ἑλληνικός","translit":"Hellēnikós","pron":"hel-lay-nee-kos'","pos":"Adjective","thayer":"<ol><li>a Grecian</li></ol>","xlit":"Hellēnikós"},"G2096":{"strongs_def":" Eua (or Eva, i.e. Chavvah), the first woman","derivation":"of Hebrew origin (H02332);","lemma":"Εὖα","translit":"Eûa","kjv_def":"Eve","pron":"yoo'-ah","pos":"Noun Feminine","thayer":"<ol><li>first woman in the scriptures, mother of the entire human family</li></ol>","xlit":"Eûa"},"G3071":{"lemma":"Λυκαονία","translit":"Lykaonía","kjv_def":"Lycaonia","strongs_def":" Lycaonia, a region of Asia Minor","derivation":"perhaps remotely from G3074 (λύκος);","pron":"loo-kah-on-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Lycaonia = \"wolf land\"</p><ol><li>a region in Asia Minor, situated between Pisidia, Cilicia, Cappadocia, Galatia and Phrygia, whose chief towns were Derbe, Lystra and Iconium</li></ol>","xlit":"Lykaonía"},"G1720":{"strongs_def":" to blow at or on","derivation":"from G1722 (ἐν) and (to puff) (compare G5453 (φύω));","translit":"emphysáō","lemma":"ἐμφυσάω","kjv_def":"breathe on","pron":"em-foo-sah'-o","pos":"Verb","thayer":"<ol><li>to blow or breathe upon</li></ol>","xlit":"emphysáō"},"G5272":{"kjv_def":"condemnation, dissimulation, hypocrisy","lemma":"ὑπόκρισις","translit":"hypókrisis","derivation":"from G5271 (ὑποκρίνομαι);","strongs_def":" acting under a feigned part, i.e. (figuratively) deceit (\"hypocrisy\")","pron":"hoop-ok'-ree-sis","pos":"Noun Feminine","thayer":"<ol><li>an answering</li><li>an answer</li><li>the acting of a stage player</li><li>dissimulation, hypocrisy</li></ol>","xlit":"hypókrisis"},"G707":{"derivation":"of Hebrew origin (H07414);","strongs_def":" Arimathæa (or Ramah), a place in Palestine","kjv_def":"Arimathæa","lemma":"Ἀριμαθαία","translit":"Arimathaía","pron":"ar-ee-math-ah'-ee-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Arimathaea = \"heights\"</p><ol><li>the name of several cities in Palestine The one mentioned in <a class='bible' href='#b40.27.57'>Mat 27:57</a>, <a class='bible' href='#b41.15.43'>Mar 15:43</a>, <a class='bible' href='#b42.23.51'>Luk 23:51</a>, <a class='bible' href='#b43.19.38'>Joh 19:38</a> appears to have been the same as the birthplace of Samuel in Mount Ephraim.</li></ol>","xlit":"Arimathaía"},"G2535":{"translit":"Káïn","lemma":"Κάϊν","kjv_def":"Cain","strongs_def":" Cain, (i.e. Cajin), the son of Adam","derivation":"of Hebrew origin (H07014);","pron":"kah'-in","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cain = \"maker: fabricator (literally smith)\"</p><ol><li>the first born of Adam, and slew his brother, Abel</li></ol>","xlit":"Káïn"},"G2065":{"kjv_def":"ask, beseech, desire, intreat, pray","lemma":"ἐρωτάω","translit":"erōtáō","derivation":"apparently from G2046 (ἐρέω) (compare G2045 (ἐρευνάω));","strongs_def":" to interrogate; by implication, to request","pron":"er-o-tah'-o","pos":"Verb","thayer":"<ol><li>to question</li><li>to ask<ol type='a'><li>to request, entreat, beg, beseech</li></ol></li></ol>","xlit":"erōtáō"},"G4282":{"translit":"proetoimázō","lemma":"προετοιμάζω","kjv_def":"ordain before, prepare afore","strongs_def":" to fit up in advance (literally or figuratively)","derivation":"from G4253 (πρό) and G2090 (ἑτοιμάζω);","pron":"pro-et-oy-mad'-zo","pos":"Verb","thayer":"<ol><li>to prepare before, to make ready beforehand</li></ol>","xlit":"proetoimázō"},"G394":{"translit":"anatíthemai","lemma":"ἀνατίθεμαι","kjv_def":"communicate, declare","strongs_def":" to set forth (for oneself), i.e propound","derivation":"from G303 (ἀνά) and the middle voice of G5087 (τίθημι);","pron":"an-at-ith'-em-ahee","pos":"Verb","thayer":"<ol><li>to set forth (in words), communicate</li></ol>","xlit":"anatíthemai"},"G4789":{"strongs_def":" a co-heir, i.e. (by analogy) participant in common","derivation":"from G4862 (σύν) and G2818 (κληρονόμος);","translit":"synklēronómos","lemma":"συγκληρονόμος","kjv_def":"fellow (joint)-heir, heir together, heir with","pron":"soong-klay-ron-om'-os","pos":"Noun Masculine","thayer":"<ol><li>a fellow heir, a joint heir</li><li>one who obtains something assigned to himself with others, a joint participant</li></ol>","xlit":"synklēronómos"},"G1393":{"kjv_def":"Dorcas","translit":"Dorkás","lemma":"Δορκάς","strongs_def":"gazelle; Dorcas, a Christian woman","pron":"dor-kas'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Dorcas = \"gazelle\"</p><ol><li>the name of a woman Peter raised from the dead</li></ol>","xlit":"Dorkás"},"G3491":{"kjv_def":"ship","lemma":"ναῦς","translit":"naûs","derivation":"from or (to float);","strongs_def":" a boat (of any size)","pron":"nowce","pos":"Noun Feminine","thayer":"<ol><li>a ship, vessel of considerable size</li></ol>","xlit":"naûs"},"G1137":{"kjv_def":"corner, quarter","translit":"gōnía","lemma":"γωνία","derivation":"probably akin to G1119 (γόνυ);","strongs_def":" an angle","pron":"go-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>corner<ol type='a'><li>an external angle, a corner</li><li>internal corner, i.e. a secret place</li></ol></li></ol>","xlit":"gōnía"},"G2375":{"lemma":"θυρεός","translit":"thyreós","kjv_def":"shield","strongs_def":" a large shield (as door-shaped)","derivation":"from G2374 (θύρα);","pron":"thoo-reh-os'","pos":"Noun Masculine","thayer":"<ol><li>a shield, a large oblong, four cornered shield</li></ol>","xlit":"thyreós"},"G2982":{"strongs_def":" lama (i.e. why)","derivation":"of Hebrew origin (H04100 with prepositional prefix);","lemma":"λαμά","translit":"lamá","kjv_def":"lama","pron":"lam-ah'","thayer":"<ol><li>why</li></ol>","xlit":"lamá"},"G4668":{"lemma":"Σμυρναῖος","translit":"Smyrnaîos","kjv_def":"in Smyrna","strongs_def":" a Smyrnæan","derivation":"from G4667 (Σμύρνα);","pron":"smoor-nah'-yos","pos":"Adjective","thayer":"<ol><li>of or belonging to Smyrna, an inhabitant of Smyrna</li></ol>","xlit":"Smyrnaîos"},"G2041":{"derivation":"from a primary (but obsolete) (to work);","strongs_def":" toil (as an effort or occupation); by implication, an act","kjv_def":"deed, doing, labour, work","translit":"érgon","lemma":"ἔργον","pron":"er'-gon","pos":"Noun Neuter","thayer":"<ol><li>business, employment, that which any one is occupied<ol type='a'><li>that which one undertakes to do, enterprise, undertaking</li></ol><li>any product whatever, any thing accomplished by hand, art, industry, or mind</li><li>an act, deed, thing done: the idea of working is emphasised in opp. to that which is less than work</li></ol>","xlit":"érgon"},"G4720":{"kjv_def":"Stachys","translit":"Stáchys","lemma":"Στάχυς","derivation":"the same as G4719 (στάχυς);","strongs_def":" Stachys, a Christian","pron":"stakh'-oos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Stachys = \"a head of grain\"</p><ol><li>a man with a Greek name, he is said to be one of the seventy disciples, and bishop of Byzantium (Gill)</li></ol>","xlit":"Stáchys"},"G3435":{"strongs_def":" to soil (figuratively)","derivation":"probably from G3189 (μέλας);","translit":"molýnō","lemma":"μολύνω","kjv_def":"defile","pron":"mol-oo'-no","pos":"Verb","thayer":"<ol><li>to pollute, stain, contaminate, defile<ol type='a'><li>used in NT of those who have not kept themselves pure from the defilements of sin, who have soiled themselves by fornication and adultery</li></ol></li></ol>","xlit":"molýnō"},"G262":{"strongs_def":" \"amaranthine\", i.e. (by implication) fadeless","derivation":"from G263 (ἀμάραντος);","translit":"amarántinos","lemma":"ἀμαράντινος","kjv_def":"that fadeth not away","pron":"am-ar-an'-tee-nos","pos":"Adjective","thayer":"<ol><li>composed of amaranth<ol type='a'><li>a flower so called because it never withers or fades, and when plucked off revives if moistened with water</li><li>a symbol of perpetuity and immortality</li></ol></li></ol>","xlit":"amarántinos"},"G2925":{"derivation":"apparently a primary verb;","strongs_def":" to rap","kjv_def":"knock","lemma":"κρούω","translit":"kroúō","pron":"kroo'-o","pos":"Verb","thayer":"<ol><li>to knock: at the door</li></ol>","xlit":"kroúō"},"G1164":{"lemma":"δεῖγμα","translit":"deîgma","kjv_def":"example","strongs_def":" a specimen (as shown)","derivation":"from the base of G1166 (δεικνύω);","pron":"digh'-mah","pos":"Noun Neuter","thayer":"<ol><li>a thing shown</li><li>a specimen of any thing, example, pattern</li></ol>","xlit":"deîgma"},"G2469":{"strongs_def":" inhabitant of Kerioth; Iscariotes (i.e. Keriothite), an epithet of Judas the traitor","derivation":"of Hebrew origin (probably H0377 and H07149);","lemma":"Ἰσκαριώτης","translit":"Iskariṓtēs","kjv_def":"Iscariot","pron":"is-kar-ee-o'-tace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Iscariot = \"men of Kerioth\"</p><ol><li>the apostle who betrayed Jesus</li></ol>","xlit":"Iskariṓtēs"},"G2652":{"kjv_def":"curse","translit":"katanáthema","lemma":"κατανάθεμα","derivation":"from G2596 (κατά) (intensive) and G331 (ἀνάθεμα);","strongs_def":" an imprecation","pron":"kat-an-ath'-em-ah","pos":"Noun Neuter","thayer":"<ol><li>curse</li></ol>","xlit":"katanáthema"},"G2806":{"strongs_def":" to break (specially, of bread)","derivation":"a primary verb;","lemma":"κλάω","translit":"kláō","kjv_def":"break","pron":"klah'-o","pos":"Verb","thayer":"<ol><li>to break<ol type='a'><li>used in the NT of the breaking of bread or communion</li></ol></li></ol>","xlit":"kláō"},"G4152":{"kjv_def":"spiritual","lemma":"πνευματικός","translit":"pneumatikós","derivation":"from G4151 (πνεῦμα);","strongs_def":" non-carnal, i.e. (humanly) ethereal (as opposed to gross), or (dæmoniacally) a spirit (concretely), or (divinely) supernatural, regenerate, religious","pron":"pnyoo-mat-ik-os'","pos":"Adjective","thayer":"<ol><li>relating to the human spirit, or rational soul, as part of the man which is akin to God and serves as his instrument or organ<ol type='a'><li>that which possesses the nature of the rational soul</li></ol><li>belonging to a spirit, or a being higher than man but inferior to God</li><li>belonging to the Divine Spirit<ol type='a'><li>of God the Holy Spirit</li><li>one who is filled with and governed by the Spirit of God</li></ol><li>pertaining to the wind or breath; windy, exposed to the wind, blowing</li></ol>","xlit":"pneumatikós"},"G5421":{"strongs_def":" a hole in the ground (dug for obtaining or holding water or other purposes), i.e. a cistern or well; figuratively, an abyss (as a prison)","derivation":"of uncertain derivation;","translit":"phréar","lemma":"φρέαρ","kjv_def":"well, pit","pron":"freh'-ar","pos":"Noun Neuter","thayer":"<ol><li>a well</li><li>the pit of the abyss (because the nether world is thought to increase in size the further it extends from the surface of the earth and so resemble a cistern, the orifice of which is narrow)</li></ol>","xlit":"phréar"},"G5126":{"strongs_def":" this (person, as objective of verb or preposition)","derivation":"accusative case singular masculine of G3778 (οὗτος);","translit":"toûton","lemma":"τοῦτον","kjv_def":"him, the same, that, this","pron":"too'-ton","thayer":"<ol><li>this</li></ol>","xlit":"toûton"},"G3620":{"derivation":"from the same as G3619 (οἰκοδομή);","strongs_def":" confirmation","kjv_def":"edifying","lemma":"οἰκοδομία","translit":"oikodomía","pron":"oy-kod-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>(the act of) building, erection</li></ol>","xlit":"oikodomía"},"G1373":{"kjv_def":"thirst","lemma":"δίψος","translit":"dípsos","derivation":"of uncertain affinity;","strongs_def":" thirst","pron":"dip'-sos","pos":"Noun Neuter","thayer":"<ol><li>thirst</li></ol>","xlit":"dípsos"},"G5583":{"strongs_def":" a falsifier","derivation":"from G5574 (ψεύδομαι);","lemma":"ψεύστης","translit":"pseústēs","kjv_def":"liar","pron":"psyoos-tace'","pos":"Noun Masculine","thayer":"<ol><li>a liar</li><li>one who breaks faith</li><li>a false and faithless man</li></ol>","xlit":"pseústēs"},"G4452":{"strongs_def":" an enclitic particle of indefiniteness; yet, even; used only in the comparative. See G3369 (μηδέπω), G3380 (μήπω), G3764 (οὐδέπω), G3768 (οὔπω), G4455 (πώποτε).","derivation":"another form of the base of G4458 (-πώς);","lemma":"-πω","translit":"-pō","pron":"po","thayer":"<ol><li>yet, even</li><li>used only in compound with words <u><a class='dict' href='#sG3369'>G3369</a></u>, <u><a class='dict' href='#sG3380'>G3380</a></u>, <u><a class='dict' href='#sG3764'>G3764</a></u>, <u><a class='dict' href='#sG3768'>G3768</a></u>, <u><a class='dict' href='#sG4455'>G4455</a></u></li></ol>","xlit":"-pō"},"G2139":{"strongs_def":" well standing around, i.e. (a competitor) thwarting (a racer) in every direction (figuratively, of sin in genitive case)","derivation":"from G2095 (εὖ) and a derivative of a presumed compound of G4012 (περί) and G2476 (ἵστημι);","translit":"euperístatos","lemma":"εὐπερίστατος","kjv_def":"which doth so easily beset","pron":"yoo-per-is'-tat-os","pos":"Adjective","thayer":"<ol><li>skilfully surrounding, i.e. besetting</li></ol>","xlit":"euperístatos"},"G2668":{"derivation":"from G2596 (κατά) and G4126 (πλέω);","strongs_def":" to sail down upon a place, i.e. to land at","kjv_def":"arrive","lemma":"καταπλέω","translit":"katapléō","pron":"kat-ap-leh'-o","pos":"Verb","thayer":"<ol><li>to sail down from the deep sea to the land</li><li>to put in</li></ol>","xlit":"katapléō"},"G5566":{"lemma":"χῶρος","translit":"chōros","kjv_def":"north west","strongs_def":" the north-west wind","derivation":"of Latin origin;","pron":"kho'-ros","pos":"Noun Masculine","thayer":"<ol><li>the northwest wind</li><li>for the quarter of the heavens from which the wind blows</li></ol>","xlit":"chōros"},"G1639":{"derivation":"of Hebrew origin (H05867);","strongs_def":" an Elamite or Persian","kjv_def":"Elamite","translit":"Elamítēs","lemma":"Ἐλαμίτης","pron":"el-am-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>an Elamite, i.e. an inhabitant of the province of Elymais, a region stretching southwards to the Persian Gulf, but boundaries of which are variously given</li></ol>","xlit":"Elamítēs"},"G3621":{"derivation":"from G3623 (οἰκονόμος);","strongs_def":" to manage (a house, i.e. an estate)","kjv_def":"be steward","translit":"oikonoméō","lemma":"οἰκονομέω","pron":"oy-kon-om-eh'-o","pos":"Verb","thayer":"<ol><li>to be a steward</li><li>to manage the affairs of a household</li><li>to manage, dispense, order, regulate</li></ol>","xlit":"oikonoméō"},"G144":{"strongs_def":" perception, i.e. (figuratively) discernment","derivation":"from G143 (αἰσθάνομαι);","translit":"aísthēsis","lemma":"αἴσθησις","kjv_def":"judgment","pron":"ah'-ee-sthay-sis","pos":"Noun Feminine","thayer":"<ol><li>perception, not only by the senses but by the intellect</li><li>cognition, discernment<ol type='a'><li>of moral discernment in ethical matters</li></ol></li></ol>","xlit":"aísthēsis"},"G787":{"kjv_def":"farthing","lemma":"ἀσσάριον","translit":"assárion","derivation":"of Latin origin;","strongs_def":" an assarius or as, a Roman coin","pron":"as-sar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>an assarium or assarius, the name of a coin equal to the tenth part of a drachma</li></ol>","xlit":"assárion"},"G1155":{"kjv_def":"borrow, lend","lemma":"δανείζω","translit":"daneízō","derivation":"from G1156 (δάνειον);","strongs_def":" to loan on interest; reflexively, to borrow","pron":"dan-ide'-zo","pos":"Verb","thayer":"<ol><li>to lend money</li><li>to have money lent to one's self</li><li>to take a loan, borrow</li></ol>","xlit":"daneízō"},"G1959":{"strongs_def":" to care for (physically or otherwise)","derivation":"middle voice from G1909 (ἐπί) and the same as G3199 (μέλω);","translit":"epimeléomai","lemma":"ἐπιμελέομαι","kjv_def":"take care of","pron":"ep-ee-mel-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to take care of a person or thing</li></ol>","xlit":"epimeléomai"},"G3024":{"strongs_def":" forgetfulness","derivation":"from G2990 (λανθάνω);","translit":"lḗthē","lemma":"λήθη","kjv_def":"+ forget","pron":"lay'-thay","pos":"Noun Feminine","thayer":"<ol><li>forgetfulness</li></ol>","xlit":"lḗthē"},"G257":{"kjv_def":"floor","translit":"hálōn","lemma":"ἅλων","derivation":"probably from the base of G1507 (εἱλίσσω);","strongs_def":" a threshing-floor (as rolled hard), i.e. (figuratively) the grain (and chaff, as just threshed)","pron":"hal'-ohn","pos":"Noun Feminine","thayer":"<ol><li>a ground plot or threshing floor, i.e. a place in the field made hard after the harvest by a roller, where grain was threshed out</li></ol>","xlit":"hálōn"},"G5328":{"strongs_def":" Pharao (i.e. Pharoh), an Egyptian king","derivation":"of foreign origin (H06547);","translit":"Pharaṓ","lemma":"Φαραώ","kjv_def":"Pharaoh","pron":"far-ah-o'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Pharaoh = \"his nakedness\"</p><ol><li>was a common title of the native kings of Egypt</li></ol>","xlit":"Pharaṓ"},"G2536":{"lemma":"Καϊνάν","translit":"Kaïnán","kjv_def":"Cainan","strongs_def":" Cainan (i.e. Kenan), the name of two patriarchs","derivation":"of Hebrew origin (H07018);","pron":"kah-ee-nan'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cainan = \"their smith\"</p><ol><li>the son of Enos, <a class='bible' href='#b1.5.9'>Gen 5:9</a></li><li>son of Arphaxad and ancestor of Christ, <a class='bible' href='#b42.3.36'>Luk 3:36</a></li></ol>","xlit":"Kaïnán"},"G585":{"lemma":"ἀπόδειξις","translit":"apódeixis","kjv_def":"demonstration","strongs_def":" manifestation","derivation":"from G584 (ἀποδείκνυμι);","pron":"ap-od'-ike-sis","pos":"Noun Feminine","thayer":"<ol><li>a making manifest, showing forth</li><li>a demonstration, proof</li></ol>","xlit":"apódeixis"},"G728":{"translit":"arrhabṓn","lemma":"ἀῤῥαβών","kjv_def":"earnest","strongs_def":" a pledge, i.e. part of the purchase-money or property given in advance as security for the rest","derivation":"of Hebrew origin (H06162);","pron":"ar-hrab-ohn'","pos":"Noun Masculine","thayer":"<ol><li>an earnest<ol type='a'><li>money which in purchases is given as a pledge or downpayment that the full amount will subsequently be paid</li></ol></li></ol>","xlit":"arrhabṓn"},"G4598":{"derivation":"from G4597 (σής) and a derivative of G977 (βιβρώσκω);","strongs_def":" moth-eaten","kjv_def":"motheaten","lemma":"σητόβρωτος","translit":"sētóbrōtos","pron":"say-tob'-ro-tos","pos":"Adjective","thayer":"<ol><li>moth eaten</li></ol>","xlit":"sētóbrōtos"},"G4024":{"lemma":"περιζώννυμι","translit":"perizṓnnymi","kjv_def":"gird (about, self)","strongs_def":" to gird all around, i.e. (middle voice or passive) to fasten on one's belt (literally or figuratively)","derivation":"from G4012 (περί) and G2224 (ζώννυμι);","pron":"per-id-zone'-noo-mee","pos":"Verb","thayer":"<ol><li>to fasten garments with a girdle or belt</li><li>to gird one's self</li><li>metaphorically with truth as a girdle<ol type='a'><li>to equip one's self with knowledge of the truth</li></ol></li></ol>","xlit":"perizṓnnymi"},"G260":{"derivation":"a primary particle;","strongs_def":" properly, at the \"same\" time, but freely used as a preposition or adverb denoting close association","kjv_def":"also, and, together, with(-al)","lemma":"ἅμα","translit":"háma","pron":"ham'-ah","xlit":"háma"},"G2959":{"lemma":"Κυρία","translit":"Kyría","kjv_def":"lady","strongs_def":" Cyria, a Christian woman","derivation":"feminine of G2962 (κύριος);","pron":"koo-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a Christian woman to whom the second Epistle of John is addressed</li></ol>","xlit":"Kyría"},"G1641":{"derivation":"from G1640 (ἐλάσσων);","strongs_def":" to diminish, i.e. fall short","kjv_def":"have lack","translit":"elattonéō","lemma":"ἐλαττονέω","pron":"el-at-ton-eh-o","pos":"Verb","thayer":"<ol><li>to be less, inferior, (in possessions)</li><li>to make less, diminish</li></ol>","xlit":"elattonéō"},"G2350":{"kjv_def":"make ado (a noise), trouble self, set on an uproar","translit":"thorybéō","lemma":"θορυβέω","derivation":"from G2351 (θόρυβος);","strongs_def":" to be in tumult, i.e. disturb, clamor","pron":"thor-oo-beh'-o","pos":"Verb","thayer":"<ol><li>to make a noise or uproar, be turbulent</li><li>to disturb, throw into confusion<ol type='a'><li>to be troubled in mind</li><li>to wail tumultuously</li></ol></li></ol>","xlit":"thorybéō"},"G3623":{"kjv_def":"chamberlain, governor, steward","lemma":"οἰκονόμος","translit":"oikonómos","derivation":"from G3624 (οἶκος) and the base of G3551 (νόμος);","strongs_def":" a house-distributor (i.e. manager), or overseer, i.e. an employee in that capacity; by extension, a fiscal agent (treasurer); figuratively, a preacher (of the Gospel)","pron":"oy-kon-om'-os","pos":"Noun Masculine","thayer":"<ol><li>the manager of household or of household affairs<ol type='a'><li>especially a steward, manager, superintendent (whether free-born as was usually the case, a freed-man or a slave) to whom the head of the house or proprietor has intrusted the management of his affairs, the care of receipts and expenditures, and the duty of dealing out the proper portion to every servant and even to the children not yet of age</li><li>the manager of a farm or landed estate, an overseer</li><li>the superintendent of the city's finances, the treasurer of a city (or of treasurers or quaestors of kings)</li></ol><li>metaphorically the apostles and other Christian teachers and bishops and overseers</li></ol>","xlit":"oikonómos"},"G3830":{"derivation":"from the same as G3829 (πανδοχεῖον);","strongs_def":" an innkeeper (warden of a caravanserai)","kjv_def":"host","lemma":"πανδοχεύς","translit":"pandocheús","pron":"pan-dokh-yoos'","pos":"Noun Masculine","thayer":"<ol><li>an inn keeper, host</li></ol>","xlit":"pandocheús"},"G1553":{"kjv_def":"be absent","lemma":"ἐκδημέω","translit":"ekdēméō","derivation":"from a compound of G1537 (ἐκ) and G1218 (δῆμος);","strongs_def":" to emigrate, i.e. (figuratively) vacate or quit","pron":"ek-day-meh'-o","pos":"Verb","thayer":"<ol><li>to go abroad</li><li>emigrate, depart</li><li>to be or live abroad</li></ol>","xlit":"ekdēméō"},"G2574":{"derivation":"of Hebrew origin (H01581);","strongs_def":" a \"camel\"","kjv_def":"camel","lemma":"κάμηλος","translit":"kámēlos","pron":"kam'-ay-los","pos":"Noun","thayer":"<ol><li>camel</li></ol>","xlit":"kámēlos"},"G2647":{"kjv_def":"destroy, dissolve, be guest, lodge, come to nought, overthrow, throw down","lemma":"καταλύω","translit":"katalýō","derivation":"from G2596 (κατά) and G3089 (λύω);","strongs_def":" to loosen down (disintegrate), i.e. (by implication) to demolish (literally or figuratively); specially (compare G2646 (κατάλυμα)) to halt for the night","pron":"kat-al-oo'-o","pos":"Verb","thayer":"<ol><li>to dissolve, disunite<ol type='a'><li>(what has been joined together), to destroy, demolish</li><li>metaphorically to overthrow, i.e. render vain, deprive of success, bring to naught<ol><li>to subvert, overthrow<ol type='a'><li>of institutions, forms of government, laws, etc., to deprive of force, annul, abrogate, discard</li></ol></li></ol><li>of travellers, to halt on a journey, to put up, lodge (the figurative expression originating in the circumstance that, to put up for the night, the straps and packs of the beasts of burden are unbound and taken off; or, more correctly from the fact that the traveller's garments, tied up when he is on the journey, are unloosed at it end)</li></ol></li></ol>","xlit":"katalýō"},"G1":{"strongs_def":" the first letter of the alphabet; figuratively, only (from its use as a numeral) the first: ","derivation":"of Hebrew origin;","lemma":"Α","translit":"A","kjv_def":"--Alpha","pron":"al'-fah","pos":"Letter","thayer":"<ol><li>first letter of Greek alphabet</li><li>Christ is the Alpha to indicate that he is the beginning and the end</li></ol>","xlit":"A"},"G4722":{"kjv_def":"(for-)bear, suffer","lemma":"στέγω","translit":"stégō","derivation":"from G4721 (στέγη);","strongs_def":" to roof over, i.e. (figuratively) to cover with silence (endure patiently)","pron":"steg'-o","pos":"Verb","thayer":"<ol><li>deck, thatch, to cover<ol type='a'><li>to protect or keep by covering, to preserve</li></ol><li>to cover over with silence<ol type='a'><li>to keep secret</li><li>to hide, conceal<ol><li>of the errors and faults of others</li></ol></li></ol><li>by covering to keep off something which threatens, to bear up against, hold out against, and so endure, bear, forbear</li></ol>","xlit":"stégō"},"G4325":{"strongs_def":" to expend additionally","derivation":"from G4314 (πρός) and G1159 (δαπανάω);","translit":"prosdapanáō","lemma":"προσδαπανάω","kjv_def":"spend more","pron":"pros-dap-an-ah'-o","pos":"Verb","thayer":"<ol><li>to spend besides</li></ol>","xlit":"prosdapanáō"},"G1082":{"derivation":"of Hebrew origin (compare H03672);","strongs_def":" Gennesaret (i.e. Kinnereth), a lake and plain in Palestine","kjv_def":"Gennesaret","translit":"Gennēsarét","lemma":"Γεννησαρέτ","pron":"ghen-nay-sar-et'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gennesaret = \"a harp\"</p><ol><li>a lake also called the sea of Galilee or the sea of Tiberias The lake 12 by 7 miles (20 by 11 km) and 700 feet (210 m) below the Mediterranean Sea.</li><li>a very lovely and fertile region on the Sea of Galilee.</li></ol>","xlit":"Gennēsarét"},"G5512":{"kjv_def":"mock","lemma":"χλευάζω","translit":"chleuázō","derivation":"from a derivative probably of G5491 (χεῖλος);","strongs_def":" to throw out the lip, i.e. jeer at","pron":"khlyoo-ad'-zo","pos":"Verb","thayer":"<ol><li>to mock, deride, jeer</li></ol>","xlit":"chleuázō"},"G4757":{"strongs_def":" a camper-out, i.e. a (common) warrior (literally or figuratively)","derivation":"from a presumed derivative of the same as G4756 (στρατιά);","lemma":"στρατιώτης","translit":"stratiṓtēs","kjv_def":"soldier","pron":"strat-ee-o'-tace","pos":"Noun Masculine","thayer":"<ol><li>a (common) soldier</li><li>metaphorically a champion of the cause of Christ</li></ol>","xlit":"stratiṓtēs"},"G2560":{"derivation":"from G2556 (κακός);","strongs_def":" badly (physically or morally)","kjv_def":"amiss, diseased, evil, grievously, miserably, sick, sore","translit":"kakōs","lemma":"κακῶς","pron":"kak-oce'","pos":"Adverb","thayer":"<ol><li>miserable, to be ill</li><li>improperly, wrongly</li><li>to speak ill of, revile, one</li></ol>","xlit":"kakōs"},"G1614":{"strongs_def":" to extend","derivation":"from G1537 (ἐκ) and teino (to stretch);","lemma":"ἐκτείνω","translit":"ekteínō","kjv_def":"cast, put forth, stretch forth (out)","pron":"ek-ti'-no","pos":"Verb","thayer":"<ol><li>to stretch out, stretch forth<ol type='a'><li>over, towards, against one</li></ol></li></ol>","xlit":"ekteínō"},"G4182":{"derivation":"from G4183 (πολύς) and G4164 (ποικίλος);","strongs_def":" much variegated, i.e. multifarious","kjv_def":"manifold","translit":"polypoíkilos","lemma":"πολυποίκιλος","pron":"pol-oo-poy'-kil-os","pos":"Adjective","thayer":"<ol><li>much variegated, marked with a great variety of colours<ol><li>of cloth or a painting</li></ol></li></ol><li>much varied, manifold</li></ol>","xlit":"polypoíkilos"},"G1236":{"kjv_def":"lead life, living","lemma":"διάγω","translit":"diágō","derivation":"from G1223 (διά) and G71 (ἄγω);","strongs_def":" to pass time or life","pron":"dee-ag'-o","pos":"Verb","thayer":"<ol><li>to lead through, lead across, send across</li><li>to pass, to live</li></ol>","xlit":"diágō"},"G3774":{"derivation":"of Hebrew origin (H0223);","strongs_def":" Urias (i.e. Urijah), a Hittite","kjv_def":"Urias","lemma":"Οὐρίας","translit":"Ourías","pron":"oo-ree'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Uriah = \"light of Jehovah\"</p><ol><li>the husband of Bathsheba, one of David's mighty men</li></ol>","xlit":"Ourías"},"G2062":{"derivation":"neuter of a derivative of (to creep);","strongs_def":" a reptile, i.e. (by Hebraism (compare H07431)) a small animal","kjv_def":"creeping thing, serpent","lemma":"ἑρπετόν","translit":"herpetón","pron":"her-pet-on'","pos":"Noun Neuter","thayer":"<ol><li>a creeping animal, reptile<ol type='a'><li>used chiefly of snakes</li></ol><li>an animal of any sort<ol type='a'><li>four-legged animals and birds</li><li>marine animals</li></ol></li></ol>","xlit":"herpetón"},"G552":{"strongs_def":" inexperienced, i.e. ignorant","derivation":"from G1 (Α) (as a negative particle) and G3984 (πεῖρα);","lemma":"ἄπειρος","translit":"ápeiros","kjv_def":"unskilful","pron":"ap'-i-ros","pos":"Adjective","thayer":"<ol><li>inexperienced in, without experience of</li></ol>","xlit":"ápeiros"},"G804":{"strongs_def":" secure (literally or figuratively)","derivation":"from G1 (Α) (as a negative particle) and sphallo (to \"fail\");","lemma":"ἀσφαλής","translit":"asphalḗs","kjv_def":"certain(-ty), safe, sure","pron":"as-fal-ace'","pos":"Adjective","thayer":"<ol><li>firm (that which can be relied on)</li><li>certain, true</li><li>suited to confirm</li></ol>","xlit":"asphalḗs"},"G5319":{"strongs_def":" to render apparent (literally or figuratively)","derivation":"from G5318 (φανερός);","translit":"phaneróō","lemma":"φανερόω","kjv_def":"appear, manifestly declare, (make) manifest (forth), shew (self)","pron":"fan-er-o'-o","pos":"Verb","thayer":"<ol><li>to make manifest or visible or known what has been hidden or unknown, to manifest, whether by words, or deeds, or in any other way<ol type='a'><li>make actual and visible, realised</li><li>to make known by teaching</li><li>to become manifest, be made known</li><li>of a person<ol><li>expose to view, make manifest, to show one's self, appear</li></ol><li>to become known, to be plainly recognised, thoroughly understood<ol><li>who and what one is</li></ol></li></ol></li></ol>","xlit":"phaneróō"},"G4588":{"strongs_def":" Sergius, a Roman","derivation":"of Latin origin;","lemma":"Σέργιος","translit":"Sérgios","kjv_def":"Sergius","pron":"serg'-ee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sergius = \"earth-born: born a wonder\"</p><ol><li>surnamed Paulus, a deputy or proconsul of Cyprus and converted to Christianity by Paul</li></ol>","xlit":"Sérgios"},"G3408":{"strongs_def":" pay for service (literally or figuratively), good or bad","derivation":"apparently a primary word;","translit":"misthós","lemma":"μισθός","kjv_def":"hire, reward, wages","pron":"mis-thos'","pos":"Noun Masculine","thayer":"<ol><li>dues paid for work<ol type='a'><li>wages, hire</li></ol><li>reward: used of the fruit naturally resulting from toils and endeavours<ol type='a'><li>in both senses, rewards and punishments</li><li>of the rewards which God bestows, or will bestow, upon good deeds and endeavours</li><li>of punishments</li></ol></li></ol>","xlit":"misthós"},"G2116":{"strongs_def":" to straighten (level); technically, to steer","derivation":"from G2117 (εὐθύς);","lemma":"εὐθύνω","translit":"euthýnō","kjv_def":"governor, make straight","pron":"yoo-thoo'-no","pos":"Adverb","thayer":"<ol><li>to make straight, level, plain</li><li>to lead or guide straight, to keep straight or direct<ol type='a'><li>of the steersman or helmsman of a ship</li><li>of a charioteer</li></ol></li></ol>","xlit":"euthýnō"},"G2095":{"kjv_def":"good, well (done)","lemma":"εὖ","translit":"eû","derivation":"neuter of a primary (good);","strongs_def":" (adverbially) well","pron":"yoo","pos":"Adverb","thayer":"<ol><li>to be well off, fare well, prosper</li><li>acting well</li></ol>","xlit":"eû"},"G4787":{"lemma":"συγκινέω","translit":"synkinéō","kjv_def":"stir up","strongs_def":" to move together, i.e. (specially), to excite as a mass (to sedition)","derivation":"from G4682 (σπαράσσω) and G2795 (κινέω);","pron":"soong-kin-eh'-o","pos":"Verb","thayer":"<ol><li>to move together with others</li><li>to throw into commotion, excite, stir up</li></ol>","xlit":"synkinéō"},"G4832":{"translit":"sýmmorphos","lemma":"σύμμορφος","kjv_def":"conformed to, fashioned like unto","strongs_def":" jointly formed, i.e. (figuratively) similar","derivation":"from G4862 (σύν) and G3444 (μορφή);","pron":"soom-mor-fos'","pos":"Adjective","thayer":"<ol><li>having the same form as another, similar, conformed to</li></ol>","xlit":"sýmmorphos"},"G388":{"derivation":"from G303 (ἀνά) and G4717 (σταυρόω);","strongs_def":" to recrucify (figuratively)","kjv_def":"crucify afresh","lemma":"ἀνασταυρόω","translit":"anastauróō","pron":"an-as-tow-ro'-o","pos":"Verb","thayer":"<ol><li>to raise up upon a cross, crucify</li></ol>","xlit":"anastauróō"},"G852":{"derivation":"from G1 (Α) (as a negative particle) and G5316 (φαίνω);","strongs_def":" non-apparent)","kjv_def":"that is not manifest","lemma":"ἀφανής","translit":"aphanḗs","pron":"af-an-ace'","pos":"Adjective","thayer":"<ol><li>not manifest, hidden</li></ol>","xlit":"aphanḗs"},"G2063":{"translit":"erythrós","lemma":"ἐρυθρός","kjv_def":"red","derivation":"of uncertain affinity; red, i.e. (with G2281 (θάλασσα)) the Red Sea","pron":"er-oo-thros'","pos":"Adjective","thayer":"<ol><li>the Red Sea<ol type='a'><li>the Indian Ocean washing the shores of Arabia and Persia, with its two gulfs, of which the one on the east is called the Persian Gulf, the other on the opposite side the Arabian. In the NT the phrase denotes the upper part of the Arabian Gulf (the Heropolitie Gulf, so called [i.e. the Gulf of Suez]), through which the Israelites made their passage out of Egypt to the shore of Arabia.</li></ol></li></ol>","xlit":"erythrós"},"G1703":{"strongs_def":" a derider, i.e. (by implication) a false teacher","derivation":"from G1702 (ἐμπαίζω);","translit":"empaíktēs","lemma":"ἐμπαίκτης","kjv_def":"mocker, scoffer","pron":"emp-aheek-tace'","pos":"Noun Masculine","thayer":"<ol><li>a mocker, a scoffer</li></ol>","xlit":"empaíktēs"},"G4500":{"derivation":"adverb from a derivative of (a whir);","strongs_def":" whizzingly, i.e. with a crash","kjv_def":"with a great noise","lemma":"ῥοιζηδόν","translit":"rhoizēdón","pron":"hroyd-zay-don'","pos":"Adverb","thayer":"<ol><li>with a loud noise</li></ol>","xlit":"rhoizēdón"},"G647":{"derivation":"neuter of a (presumed) adjective from a derivative of G868 (ἀφίστημι);","strongs_def":" properly, something separative, i.e. (specially) divorce","kjv_def":"(writing of) divorcement","lemma":"ἀποστάσιον","translit":"apostásion","pron":"ap-os-tas'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>divorce, repudiation</li><li>a bill of divorce</li></ol>","xlit":"apostásion"},"G5028":{"derivation":"masculine from G2290 (θάπτω);","strongs_def":" a grave (the place of interment)","kjv_def":"sepulchre, tomb","lemma":"τάφος","translit":"táphos","pron":"taf'-os","pos":"Noun Masculine","thayer":"<ol><li>burial</li><li>a grave, a sepulchre</li></ol>","xlit":"táphos"},"G5245":{"translit":"hypernikáō","lemma":"ὑπερνικάω","kjv_def":"more than conquer","strongs_def":" to vanquish beyond, i.e. gain a decisive victory","derivation":"from G5228 (ὑπέρ) and G3528 (νικάω);","pron":"hoop-er-nik-ah'-o","pos":"Verb","thayer":"<ol><li>to be more than a conqueror, to gain a surpassing victory</li></ol>","xlit":"hypernikáō"},"G2289":{"kjv_def":"become dead, (cause to be) put to death, kill, mortify","translit":"thanatóō","lemma":"θανατόω","derivation":"from G2288 (θάνατος) to kill (literally or figuratively)","pron":"than-at-o'-o","pos":"Verb","thayer":"<ol><li>to put to death</li><li>metaphorically<ol type='a'><li>to make to die, i.e. destroy, render extinct</li><li>by death to be liberated from the bond of anything, literally to be made dead in relation to (something)</li></ol></li></ol>","xlit":"thanatóō"},"G1371":{"translit":"dichotoméō","lemma":"διχοτομέω","kjv_def":"cut asunder (in sunder)","strongs_def":" to bisect, i.e. (by extension) to flog severely","derivation":"from a compound of a derivative of G1364 (δίς) and a derivative of (to cut);","pron":"dee-khot-om-eh'-o","pos":"Verb","thayer":"<ol><li>to cut into two parts<ol type='a'><li>of the cruel method of punishment used by the Hebrews and others of cutting one in two</li></ol><li>cut up by scourging, scourge severely</li></ol>","xlit":"dichotoméō"},"G1054":{"derivation":"from G1053 (Γαλατία);","strongs_def":" Galatic or relating to Galatia","kjv_def":"of Galatia","lemma":"Γαλατικός","translit":"Galatikós","pron":"gal-at-ee-kos'","pos":"Adjective","thayer":"<ol><li>a citizen of Galatia</li></ol>","xlit":"Galatikós"},"G3463":{"kjv_def":"ten thousand","translit":"mýrioi","lemma":"μύριοι","derivation":"plural of an apparently primary word (properly, meaning very many);","strongs_def":" ten thousand; by extension, innumerably many","pron":"moo'-ree-oi","pos":"Adjective","thayer":"<ol><li>innumerable, countless</li><li>ten thousand</li></ol>","xlit":"mýrioi"},"G800":{"strongs_def":" inharmonious (figuratively)","derivation":"from G1 (Α) (as a negative particle) and G4859 (σύμφωνος);","translit":"asýmphōnos","lemma":"ἀσύμφωνος","kjv_def":"agree not","pron":"as-oom'-fo-nos","pos":"Adjective","thayer":"<ol><li>not agreeing in sound, dissonant, inharmonious, at variance</li></ol>","xlit":"asýmphōnos"},"G3453":{"kjv_def":"instruct","translit":"myéō","lemma":"μυέω","derivation":"from the base of G3466 (μυστήριον);","strongs_def":" to initiate, i.e. (by implication) to teach","pron":"moo-eh'-o","pos":"Verb","thayer":"<ol><li>to initiate into the mysteries</li><li>to teach fully, instruct<ol type='a'><li>to accustom one to a thing</li><li>to give one an intimate acquaintance with a thing</li></ol></li></ol>","xlit":"myéō"},"G3089":{"translit":"lýō","lemma":"λύω","kjv_def":"break (up), destroy, dissolve, (un-)loose, melt, put off","strongs_def":" to \"loosen\" (literally or figuratively)","derivation":"a primary verb;","pron":"loo'-o","pos":"Verb","thayer":"<ol><li>to loose any person (or thing) tied or fastened<ol type='a'><li>bandages of the feet, the shoes</li><li>of a husband and wife joined together by the bond of matrimony</li><li>of a single man, whether he has already had a wife or has not yet married</li></ol><li>to loose one bound, i.e. to unbind, release from bonds, set free<ol type='a'><li>of one bound up (swathed in bandages)</li><li>bound with chains (a prisoner), discharge from prison, let go</li></ol><li>to loosen, undo, dissolve, anything bound, tied, or compacted together<ol type='a'><li>an assembly, i.e. to dismiss, break up</li><li>laws, as having a binding force, are likened to bonds</li><li>to annul, subvert</li><li>to do away with, to deprive of authority, whether by precept or act</li><li>to declare unlawful</li><li>to loose what is compacted or built together, to break up, demolish, destroy</li><li>to dissolve something coherent into parts, to destroy</li><li>metaphorically, to overthrow, to do away with</li></ol></li></ol>","xlit":"lýō"},"G3921":{"kjv_def":"creep in unawares","lemma":"παρεισδύνω","translit":"pareisdýnō","derivation":"from G3844 (παρά) and a compound of G1519 (εἰς) and G1416 (δύνω);","strongs_def":" to settle in alongside, i.e. lodge stealthily","pron":"par-ice-doo'-no","pos":"Verb","thayer":"<ol><li>to enter secretly, slip in stealthily</li><li>to steal in</li></ol>","xlit":"pareisdýnō"},"G5492":{"derivation":"from the same as G5494 (χειμών);","strongs_def":" to storm, i.e. (passively) to labor under a gale","kjv_def":"be tossed with tempest","translit":"cheimázō","lemma":"χειμάζω","pron":"khi-mad'-zo","pos":"Verb","thayer":"<ol><li>to afflict with a tempest, to toss about upon the waves</li></ol>","xlit":"cheimázō"},"G1409":{"translit":"Droúsilla","lemma":"Δρούσιλλα","kjv_def":"Drusilla","strongs_def":" Drusilla, a member of the Herodian family","derivation":"a feminine diminutive of Drusus (a Roman name);","pron":"droo'-sil-lah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Drusilla = \"watered by the dew\"</p><ol><li>the daughter of Agrippa the elder, wife of Felix, the governor of Judaea, a most licentious woman</li></ol>","xlit":"Droúsilla"},"G2026":{"kjv_def":"build thereon (thereupon, on, upon)","lemma":"ἐποικοδομέω","translit":"epoikodoméō","derivation":"from G1909 (ἐπί) and G3618 (οἰκοδομέω);","strongs_def":" to build upon, i.e. (figuratively) to rear up","pron":"ep-oy-kod-om-eh'-o","pos":"Verb","thayer":"<ol><li>to build upon, build up</li></ol>","xlit":"epoikodoméō"},"G3828":{"translit":"Pamphylía","lemma":"Παμφυλία","kjv_def":"Pamphylia","strongs_def":" every-tribal, i.e. heterogeneous (G5561 (χώρα) being implied); Pamphylia, a region of Asia Minor","derivation":"from a compound of G3956 (πᾶς) and G4443 (πυρά);","pron":"pam-fool-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Pamphylia = \"of every tribe\"</p><ol><li>a province in Asia Minor, bounded on the east by Cilicia, on the west by Lycia and Phrygia Minor, on the north by Galatia and Cappadocia, and on the south by the Mediterranean Sea</li></ol>","xlit":"Pamphylía"},"G2172":{"strongs_def":" to wish; by implication, to pray to God","derivation":"middle voice of a primary verb;","translit":"eúchomai","lemma":"εὔχομαι","kjv_def":"pray, will, wish","pron":"yoo'-khom-ahee","pos":"Verb","thayer":"<ol><li>to pray to God</li><li>to wish, to pray, to pray for</li></ol>","xlit":"eúchomai"},"G3417":{"translit":"mneía","lemma":"μνεία","kjv_def":"mention, remembrance","strongs_def":" recollection; by implication, recital","derivation":"from G3415 (μνάομαι) or G3403 (μιμνήσκω);","pron":"mni'-ah","pos":"Noun Feminine","thayer":"<ol><li>remembrance, memory, mention</li></ol>","xlit":"mneía"},"G1271":{"translit":"diánoia","lemma":"διάνοια","kjv_def":" imagination, mind, understanding","strongs_def":" deep thought, properly, the faculty (mind or its disposition), by implication, its exercise","derivation":"from G1223 (διά) and G3563 (νοῦς);","pron":"dee-an'-oy-ah","pos":"Noun Feminine","thayer":"<ol><li>the mind as a faculty of understanding, feeling, desiring</li><li>understanding</li><li>mind, i.e. spirit, way of thinking and feeling</li><li>thoughts, either good or bad</li></ol>","xlit":"diánoia"},"G75":{"translit":"agōnízomai","lemma":"ἀγωνίζομαι","kjv_def":"fight, labor fervently, strive","strongs_def":" to struggle, literally (to compete for a prize), figuratively (to contend with an adversary), or genitive case (to endeavor to accomplish something)","derivation":"from G73 (ἀγών);","pron":"ag-o-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to enter a contest: contend in the gymnastic games</li><li>to contend with adversaries, fight</li><li>metaphorically to contend, struggle, with difficulties and dangers</li><li>to endeavour with strenuous zeal, strive: to obtain something</li></ol>","xlit":"agōnízomai"},"G3633":{"kjv_def":"suppose, think","lemma":"οἴομαι","translit":"oíomai","derivation":"middle voice apparently from G3634 (οἷος);","strongs_def":" to make like (oneself), i.e. imagine (be of the opinion)","pron":"oy'-om-ahee","pos":"Verb","thayer":"<ol><li>to suppose, think</li></ol>","xlit":"oíomai"},"G2740":{"kjv_def":"be burned","lemma":"καῦσις","translit":"kaûsis","derivation":"from G2545 (καίω);","strongs_def":" burning (the act)","pron":"kow'-sis","pos":"Noun Feminine","thayer":"<ol><li>burning, burning up</li></ol>","xlit":"kaûsis"},"G5154":{"lemma":"τρίτος","translit":"trítos","kjv_def":"third(-ly)","strongs_def":" third; neuter (as noun) a third part, or (as adverb) a (or the) third time, thirdly","derivation":"ordinal from G5140 (τρεῖς);","pron":"tree'-tos","pos":"Adjective","thayer":"<ol><li>the third</li></ol>","xlit":"trítos"},"G4236":{"kjv_def":"meekness","translit":"praiótēs","lemma":"πρᾳότης","derivation":"from G4235 (πρᾷος);","strongs_def":" gentleness, by implication, humility","pron":"prah-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>gentleness, mildness, meekness</li></ol>","xlit":"praiótēs"},"G5532":{"derivation":"from the base of G5530 (χράομαι) or G5534 (χρή);","strongs_def":" employment, i.e. an affair; also (by implication) occasion, demand, requirement or destitution","kjv_def":"business, lack, necessary(-ity), need(-ful), use, want","translit":"chreía","lemma":"χρεία","pron":"khri'-ah","pos":"Noun Feminine","thayer":"<ol><li>necessity, need</li><li>duty, business</li></ol>","xlit":"chreía"},"G1516":{"lemma":"εἰρηνικός","translit":"eirēnikós","kjv_def":"peaceable","strongs_def":" pacific; by implication, salutary","derivation":"from G1515 (εἰρήνη);","pron":"i-ray-nee-kos'","pos":"Adjective","thayer":"<ol><li>relating to peace</li><li>peaceable, pacific, loving peace</li><li>bring peace with it, peaceful, salutary</li></ol>","xlit":"eirēnikós"},"G5253":{"derivation":"neuter of a derivative of G5228 (ὑπέρ);","strongs_def":" a higher part of the house, i.e. apartment in the third story","kjv_def":"upper chamber (room)","translit":"hyperōion","lemma":"ὑπερῷον","pron":"hoop-er-o'-on","pos":"Noun Neuter","thayer":"<ol><li>the highest part of the house, the upper rooms or story where the women resided</li><li>a room in the upper part of a house, sometimes built upon the flat roof of the house, whither Orientals were wont to retire in order to sup, meditate, pray</li></ol>","xlit":"hyperōion"},"G2384":{"translit":"Iakṓb","lemma":"Ἰακώβ","kjv_def":"also an Israelite:--Jacob","strongs_def":" Jacob (i.e. Ja`akob), the progenitor of the Israelites","derivation":"of Hebrew origin (H03290);","pron":"ee-ak-obe'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jacob = \"heel-catcher or supplanter\"</p><ol><li>was the second son of Isaac</li><li>the father of Joseph, the husband of Mary</li></ol>","xlit":"Iakṓb"},"G1153":{"kjv_def":"Damascene","translit":"Damaskēnós","lemma":"Δαμασκηνός","derivation":"from G1154 (Δαμασκός);","strongs_def":" a Damascene or inhabitant of Damascus","pron":"dam-as-kay-nos'","pos":"Adjective","thayer":"<ol><li>of Damascus</li></ol>","xlit":"Damaskēnós"},"G3628":{"lemma":"οἰκτιρμός","translit":"oiktirmós","kjv_def":"mercy","strongs_def":" pity","derivation":"from G3627 (οἰκτείρω);","pron":"oyk-tir-mos'","pos":"Noun Masculine","thayer":"<ol><li>compassion, pity, mercy<ol type='a'><li>bowels in which compassion resides, a heart of compassion</li><li>emotions, longings, manifestations of pity</li></ol></li></ol>","xlit":"oiktirmós"},"G1122":{"kjv_def":"scribe, town-clerk","translit":"grammateús","lemma":"γραμματεύς","derivation":"from G1121 (γράμμα). a writer, i.e. (professionally) scribe or secretary","pron":"gram-mat-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a clerk, scribe, especiallya public servant, secretary, recorder, whose office and influence differed in different states</li><li>in the Bible, a man learned in the Mosaic law and in the sacred writings, an interpreter, teacher. Scribes examined the more difficult and subtle questions of the law; added to the Mosaic law decisions of various kinds thought to elucidate its meaning and scope, and did this to the detriment of religion. Since the advice of men skilled in the law was needed in the examination in the causes and the solution of the difficult questions, they were enrolled in the Sanhedrin; and are mentioned in connection with the priests and elders of the people. See a Bible Dictionary for more information on the scribes.</li><li>a religious teacher: so instructed that from his learning and ability to teach advantage may redound to the kingdom of heaven</li></ol>","xlit":"grammateús"},"G5390":{"strongs_def":" with friendliness of mind, i.e. kindly","derivation":"adverb from G5391 (φιλόφρων);","translit":"philophrónōs","lemma":"φιλοφρόνως","kjv_def":"courteously","pron":"fil-of-ron'-oce","pos":"Adverb","thayer":"<ol><li>kindly, in a friendly manner</li></ol>","xlit":"philophrónōs"},"G1593":{"derivation":"from G1537 (ἐκ) and G3506 (νεύω);","strongs_def":" (by analogy) to slip off, i.e. quietly withdraw","kjv_def":"convey self away","translit":"ekneúō","lemma":"ἐκνεύω","pron":"ek-nyoo'-o","pos":"Verb","thayer":"<ol><li>to bend to one side</li><li>to take one's self away, to turn one's self, to avoid a thing</li><li>to swim away, escape by swimming</li><li>to escape, slip away secretly</li></ol>","xlit":"ekneúō"},"G112":{"kjv_def":"without God","lemma":"ἄθεος","translit":"átheos","derivation":"from G1 (Α) (as a negative particle) and G2316 (θεός);","strongs_def":" godless","pron":"ath'-eh-os","pos":"Adjective","thayer":"<ol><li>without God, knowing and worshipping no God</li><li>denying the gods, especially the recognised gods of the state</li><li>godless, ungodly</li><li>abandoned by the gods</li></ol>","xlit":"átheos"},"G1742":{"lemma":"ἔνδυμα","translit":"éndyma","kjv_def":"clothing, garment, raiment","strongs_def":" apparel (especially the outer robe)","derivation":"from G1746 (ἐνδύω);","pron":"en'-doo-mah","pos":"Noun Neuter","thayer":"<ol><li>garment, raiment, cloak, an outer garment</li></ol>","xlit":"éndyma"},"G2582":{"strongs_def":" Candacè, an Egyptian queen","derivation":"of foreign origin;","lemma":"Κανδάκη","translit":"Kandákē","kjv_def":"Candace","pron":"kan-dak'-ay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Candace = \"prince of servants\"</p><ol><li>a queen of Ethiopia mentioned in <a class='bible' href='#b44.8.27'>Act 8:27</a>. (A.D. 38) The name was not a proper name of an individual, but that of a dynasty of Ethiopian queens.</li></ol>","xlit":"Kandákē"},"G1347":{"strongs_def":" aquittal (for Christ's sake)","derivation":"from G1344 (δικαιόω);","lemma":"δικαίωσις","translit":"dikaíōsis","kjv_def":"justification","pron":"dik-ah'-yo-sis","pos":"Noun Feminine","thayer":"<ol><li>the act of God declaring men free from guilt and acceptable to him</li><li>abjuring to be righteous, justification</li></ol>","xlit":"dikaíōsis"},"G304":{"kjv_def":"stairs","lemma":"ἀναβαθμός","translit":"anabathmós","derivation":"from G305 (ἀναβαίνω) (compare G898 (βαθμός));","strongs_def":" a stairway","pron":"an-ab-ath-mos'","pos":"Noun Masculine","thayer":"<ol><li>an ascent</li><li>a means of going up, a flight of stairs, stairs</li></ol>","xlit":"anabathmós"},"G2906":{"kjv_def":"clamour, cry(-ing)","lemma":"κραυγή","translit":"kraugḗ","derivation":"from G2896 (κράζω);","strongs_def":" an outcry (in notification, tumult or grief)","pron":"krow-gay'","pos":"Noun Feminine","thayer":"<ol><li>a crying, outcry, clamour</li></ol>","xlit":"kraugḗ"},"G1094":{"derivation":"akin to G1088 (γέρων);","strongs_def":" senility","kjv_def":"old age","translit":"gēras","lemma":"γῆρας","pron":"ghay'-ras","pos":"Noun Neuter","thayer":"<ol><li>old age</li></ol>","xlit":"gēras"},"G1386":{"kjv_def":"deceitful","lemma":"δόλιος","translit":"dólios","derivation":"from G1388 (δόλος);","strongs_def":" guileful","pron":"dol'-ee-os","pos":"Adjective","thayer":"<ol><li>deceitful</li></ol>","xlit":"dólios"},"G931":{"lemma":"βάσανος","translit":"básanos","kjv_def":"torment","strongs_def":" a touch-stone, i.e. (by analogy) torture","derivation":"perhaps remotely from the same as G939 (βάσις) (through the notion of going to the bottom);","pron":"bas'-an-os","pos":"Noun Masculine","thayer":"<ol><li>a touchstone, which is a black siliceous stone used to test the purity of gold or silver by the colour of the streak produced on it by rubbing it with either metal</li><li>the rack or instrument of torture by which one is forced to divulge the truth</li><li>torture, torment, acute pains<ol type='a'><li>of the pains of a disease</li><li>of those in hell after death</li></ol></li></ol>","xlit":"básanos"},"G177":{"translit":"akatakályptos","lemma":"ἀκατακάλυπτος","kjv_def":"uncovered","strongs_def":" unveiled","derivation":"from G1 (Α) (as a negative particle) and a derivative of a compound of G2596 (κατά) and G2572 (καλύπτω);","pron":"ak-at-ak-al'-oop-tos","pos":"Adjective","thayer":"<ol><li>not covered, unveiled</li></ol>","xlit":"akatakályptos"},"G4526":{"strongs_def":" \"sack\"-cloth, i.e. mohair (the material or garments made of it, worn as a sign of grief)","derivation":"of Hebrew origin (H08242);","lemma":"σάκκος","translit":"sákkos","kjv_def":" sackcloth","pron":"sak'-kos","pos":"Noun Masculine","thayer":"<ol><li>a sack<ol type='a'><li>a receptacle for holding or carrying various things, as money, food, etc.</li><li>a course cloth, a dark course stuff made especially from the hair of animals</li><li>a garment of the like material, and clinging to the person like a sack, which was wont to be worn (or drawn over the tunic instead of the cloak or mantle) by mourners, penitents, suppliants and also by those who like the Hebrew prophets, lead an austere life</li></ol></li></ol>","xlit":"sákkos"},"G2919":{"strongs_def":" by implication, to try, condemn, punish","derivation":"properly, to distinguish, i.e. decide (mentally or judicially);","translit":"krínō","lemma":"κρίνω","kjv_def":"avenge, conclude, condemn, damn, decree, determine, esteem, judge, go to (sue at the) law, ordain, call in question, sentence to, think","pron":"kree'-no","pos":"Verb","thayer":"<ol><li>to separate, put asunder, to pick out, select, choose</li><li>to approve, esteem, to prefer</li><li>to be of opinion, deem, think, to be of opinion</li><li>to determine, resolve, decree</li><li>to judge<ol type='a'><li>to pronounce an opinion concerning right and wrong<ol><li>to be judged, i.e. summoned to trial that one's case may be examined and judgment passed upon it</li></ol><li>to pronounce judgment, to subject to censure<ol><li>of those who act the part of judges or arbiters in matters of common life, or pass judgment on the deeds and words of others</li></ol></li></ol><li>to rule, govern<ol type='a'><li>to preside over with the power of giving judicial decisions, because it was the prerogative of kings and rulers to pass judgment</li></ol><li>to contend together, of warriors and combatants<ol type='a'><li>to dispute</li><li>in a forensic sense<ol><li>to go to law, have suit at law</li></ol></li></ol></li></ol>","xlit":"krínō"},"G2060":{"lemma":"Ἑρμῆς","translit":"Hermēs","kjv_def":"Hermes, Mercury","strongs_def":" Hermes, the name of the messenger of the Greek deities; also of a Christian","derivation":"perhaps from G2046 (ἐρέω);","pron":"her-mace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mercurius or Hermes = \"herald of the gods\"</p><ol><li>a Greek deity called by the Romans Mercurius (Mercury)</li><li>a certain Christian</li></ol>","xlit":"Hermēs"},"G2066":{"kjv_def":"apparel, clothing, raiment, robe","lemma":"ἐσθής","translit":"esthḗs","derivation":"from (to clothe);","strongs_def":" dress","pron":"es-thace'","pos":"Noun Feminine","thayer":"<ol><li>clothing, raiment, apparel</li></ol>","xlit":"esthḗs"},"G4826":{"kjv_def":"Simeon, Simon","lemma":"Συμεών","translit":"Symeṓn","derivation":"from the same as G4613 (Σίμων);","strongs_def":" Symeon (i.e. Shimon), the name of five Israelites","pron":"soom-eh-one'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Simon = \"harkening\"</p><ol><li>the second son of Jacob by Leah</li><li>one of Abraham's descendants</li><li>the one who took the infant Jesus in his arms in the temple</li><li>a teacher at the church of Antioch</li><li>the original name of Peter the apostle</li></ol>","xlit":"Symeṓn"},"G3398":{"derivation":"apparently a primary word;","strongs_def":" small (in size, quantity, number or (figuratively) dignity)","kjv_def":"least, less, little, small","translit":"mikrós","lemma":"μικρός","pron":"mik-ros'","pos":"Adjective","thayer":"<ol><li>small, little<ol type='a'><li>of size: hence of stature, of length</li><li>of space</li><li>of age: less by birth, younger</li><li>of time: short, brief, a little while, how little!</li><li>of quantity: i.e. number, amount</li><li>of rank or influence</li></ol></li></ol>","xlit":"mikrós"},"G3402":{"kjv_def":"follower","lemma":"μιμητής","translit":"mimētḗs","derivation":"from G3401 (μιμέομαι);","strongs_def":" an imitator","pron":"mim-ay-tace'","pos":"Noun Masculine","thayer":"<ol><li>an imitator</li></ol>","xlit":"mimētḗs"},"G2528":{"derivation":"from G2596 (κατά);","strongs_def":" and G3695 (ὁπλίζω); to equip fully with armor","kjv_def":"arm","translit":"kathoplízō","lemma":"καθοπλίζω","pron":"kath-op-lid'-zo","pos":"Verb","thayer":"<ol><li>furnish with arms</li></ol>","xlit":"kathoplízō"},"G3428":{"lemma":"μοιχαλίς","translit":"moichalís","kjv_def":"adulteress(-ous, -y)","strongs_def":" an adulteress (literally or figuratively)","derivation":"a prolonged form of the feminine of G3432 (μοιχός);","pron":"moy-khal-is'","pos":"Noun Feminine","thayer":"<ol><li>an adulteress</li><li>as the intimate alliance of God with the people of Israel was likened to a marriage, those who relapse into idolatry are said to commit adultery or play the harlot<ol type='a'><li>fig. equiv. to faithless to God, unclean, apostate</li></ol></li></ol>","xlit":"moichalís"},"G5446":{"kjv_def":"natural","translit":"physikós","lemma":"φυσικός","derivation":"from G5449 (φύσις);","strongs_def":" \"physical\", i.e. (by implication) instinctive","pron":"foo-see-kos'","pos":"Adjective","thayer":"<ol><li>produced by nature, inborn</li><li>agreeable to nature</li><li>governed by (the instincts of) nature</li></ol>","xlit":"physikós"},"G1826":{"strongs_def":" to issue, i.e. leave (a place), escape (to the shore)","derivation":"from G1537 (ἐκ) and (to go);","translit":"éxeimi","lemma":"ἔξειμι","kjv_def":"depart, get (to land), go out","pron":"ex'-i-mee","pos":"Verb","thayer":"<ol><li>to go forth, go out</li></ol>","xlit":"éxeimi"},"G4920":{"derivation":"from G4862 (σύν) and (to send);","strongs_def":" to put together, i.e. (mentally) to comprehend; by implication, to act piously","kjv_def":" consider, understand, be wise","lemma":"συνίημι","translit":"syníēmi","pron":"soon-ee'-ay-mee","pos":"Verb","thayer":"<ol><li>to set or bring together<ol type='a'><li>in a hostile sense, of combatants</li></ol><li>to put (as it were) the perception with the thing perceived<ol type='a'><li>to set or join together in the mind<ol><li>i.e. to understand: the man of understanding</li><li>idiom for: a good and upright man (having the knowledge of those things which pertain to salvation)</li></ol></li></ol></li></ol>","xlit":"syníēmi"},"G4484":{"translit":"Rhḗgion","lemma":"Ῥήγιον","kjv_def":"Rhegium","strongs_def":" Rhegium, a place in Italy","derivation":"of Latin origin;","pron":"hrayg'-ee-on","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Rhegium = \"breach\"</p><ol><li>an Italian town situated on the Bruttian coast, just at the southern entrance of the Straits of Messina</li></ol>","xlit":"Rhḗgion"},"G5382":{"derivation":"from G5384 (φίλος) and G3581 (ξένος);","strongs_def":" fond of guests, i.e. hospitable","kjv_def":"given to (lover of, use) hospitality","translit":"philóxenos","lemma":"φιλόξενος","pron":"fil-ox'-en-os","pos":"Adjective","thayer":"<ol><li>hospitable, generous to guests</li></ol>","xlit":"philóxenos"},"G5045":{"derivation":"from the base of G5098 (τιμωρία);","strongs_def":" an artificer (as producer of fabrics), i.e. (specially), a craftsman in wood","kjv_def":"carpenter","translit":"téktōn","lemma":"τέκτων","pron":"tek'-tone","pos":"Noun Masculine","thayer":"<ol><li>a worker in wood, a carpenter, joiner, builder<ol type='a'><li>a ship's carpenter or builder</li></ol><li>any craftsman, or workman<ol type='a'><li>the art of poetry, maker of songs</li></ol><li>a planner, contriver, plotter<ol type='a'><li>an author</li></ol></li></ol>","xlit":"téktōn"},"G2332":{"strongs_def":" Thessalonice, a place in Asia Minor","derivation":"from (a Thessalian) and G3529 (νίκη);","translit":"Thessaloníkē","lemma":"Θεσσαλονίκη","kjv_def":"Thessalonica","pron":"thes-sal-on-ee'-kay","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Thessalonica = \"victory of falsity\"</p><ol><li>a famous and populous city, situated on the Thermaic Gulf, the capital of the second division of Macedonia and the residence of a Roman governor and quaestor</li></ol>","xlit":"Thessaloníkē"},"G155":{"derivation":"from G154 (αἰτέω);","strongs_def":" a thing asked or (abstractly) an asking","kjv_def":"petition, request, required","translit":"aítēma","lemma":"αἴτημα","pron":"ah'-ee-tay-mah","pos":"Noun Neuter","thayer":"<ol><li>petition, request, required</li></ol>","xlit":"aítēma"},"G2613":{"derivation":"from G2596 (κατά) and a derivative of G1349 (δίκη);","strongs_def":" to adjudge against, i.e. pronounce guilty","kjv_def":"condemn","lemma":"καταδικάζω","translit":"katadikázō","pron":"kat-ad-ik-ad'-zo","pos":"Verb","thayer":"<ol><li>to give judgment against (one), to pronounce guilty</li><li>to condemn</li></ol>","xlit":"katadikázō"},"G1773":{"lemma":"ἔννυχον","translit":"énnychon","kjv_def":"before day","strongs_def":" (adverbially) by night","derivation":"neuter of a compound of G1722 (ἐν) and G3571 (νύξ);","pron":"en'-noo-khon","pos":"Adjective","thayer":"<ol><li>nightly, nocturnal</li></ol>","xlit":"énnychon"},"G5474":{"kjv_def":"fine brass","lemma":"χαλκολίβανον","translit":"chalkolíbanon","derivation":"neuter of a compound of G5475 (χαλκός) and G3030 (λίβανος) (in the implied mean of whiteness or brilliancy);","strongs_def":" burnished copper, an alloy of copper (or gold) and silver having a brilliant lustre","pron":"khal-kol-ib'-an-on","pos":"Noun Neuter","thayer":"<ol><li>some metal like gold if not more precious</li></ol>","xlit":"chalkolíbanon"},"G2707":{"lemma":"καταφροντής","translit":"kataphrontḗs","kjv_def":"despiser","strongs_def":" a contemner","derivation":"from G2706 (καταφρονέω);","pron":"kat-af-ron-tace'","pos":"Noun Masculine","thayer":"<ol><li>despiser</li></ol>","xlit":"kataphrontḗs"},"G3855":{"lemma":"παράγω","translit":"parágō","kjv_def":"depart, pass (away, by, forth)","strongs_def":" to lead near, i.e. (reflexively or intransitively) to go along or away","derivation":"from G3844 (παρά) and G71 (ἄγω);","pron":"par-ag'-o","pos":"Verb","thayer":"<ol><li>pass by<ol type='a'><li>to lead past, lead by</li><li>to lead aside, mislead<ol><li>to lead away</li></ol><li>to lead to<ol><li>to lead forth, bring forward</li></ol></li></ol><li>to pass by, go past<ol type='a'><li>to depart, go away</li></ol><li>metaphorically disappear</li></ol>","xlit":"parágō"},"G1845":{"lemma":"ἐξορκιστής","translit":"exorkistḗs","kjv_def":"exorcist","strongs_def":" one that binds by an oath (or spell), i.e. (by implication) an \"exorcist\" (conjurer)","derivation":"from G1844 (ἐξορκίζω);","pron":"ex-or-kis-tace'","pos":"Noun Masculine","thayer":"<ol><li>he who extracts an oath of one</li><li>an exorcist<ol type='a'><li>one who employs a formula of conjuration for expelling demons</li></ol></li></ol>","xlit":"exorkistḗs"},"G5371":{"strongs_def":" friendly; Philemon, a Christian","derivation":"from G5368 (φιλέω);","lemma":"Φιλήμων","translit":"Philḗmōn","kjv_def":"Philemon","pron":"fil-ay'-mone","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Philemon = \"one who kisses\"</p><ol><li>a resident of Colosse, converted to Christianity by Paul, and the recipient of the letter bearing his name</li></ol>","xlit":"Philḗmōn"},"G4069":{"kjv_def":"Persis","translit":"Persís","lemma":"Περσίς","strongs_def":"a Persian woman; Persis, a Christian female","pron":"per-sece'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Persis = \"a Persian woman\"</p><ol><li>a Christian woman at Rome</li></ol>","xlit":"Persís"},"G31":{"derivation":"from G32 (ἄγγελος);","strongs_def":" an announcement, i.e. (by implication) precept","kjv_def":"message","translit":"angelía","lemma":"ἀγγελία","pron":"ang-el-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>message, announcement, news</li><li>a proclamation, command, order</li></ol>","xlit":"angelía"},"G1605":{"strongs_def":" to strike with astonishment","derivation":"from G1537 (ἐκ) and G4141 (πλήσσω);","translit":"ekplḗssō","lemma":"ἐκπλήσσω","kjv_def":"amaze, astonish","pron":"ek-place'-so","pos":"Verb","thayer":"<ol><li>to strike out, expel by a blow, drive out or away</li><li>to cast off by a blow, to drive out<ol type='a'><li>commonly, to strike one out of self-possession, to strike with panic, shock, astonish</li></ol><li>to be struck with amazement, astonished, amazed</li></ol>","xlit":"ekplḗssō"},"G4241":{"lemma":"πρέπω","translit":"prépō","kjv_def":"become, comely","strongs_def":" to tower up (be conspicuous), i.e. (by implication) to be suitable or proper (third person singular present indicative, often used impersonally, it is fit or right)","derivation":"apparently a primary verb;","pron":"prep'-o","pos":"Verb","thayer":"<ol><li>to stand out, to be conspicuous, to be eminent</li><li>to be becoming, seemly, fit</li></ol>","xlit":"prépō"},"G409":{"lemma":"ἀνδροφόνος","translit":"androphónos","kjv_def":"manslayer","strongs_def":" a murderer","derivation":"from G435 (ἀνήρ) and G5408 (φόνος);","pron":"an-drof-on'-os","pos":"Noun Masculine","thayer":"<ol><li>a murderer</li></ol>","xlit":"androphónos"},"G3307":{"strongs_def":" to part, i.e. (literally) to apportion, bestow, share, or (figuratively) to disunite, differ","derivation":"from G3313 (μέρος);","translit":"merízō","lemma":"μερίζω","kjv_def":"deal, be difference between, distribute, divide, give participle ","pron":"mer-id'-zo","pos":"Verb","thayer":"<ol><li>to divide<ol type='a'><li>to separate into parts, cut into pieces<ol><li>to divide into parties, i.e. be split into factions</li></ol><li>to distribute<ol><li>a thing among people</li><li>bestow, impart</li></ol></li></ol></li></ol>","xlit":"merízō"},"G4365":{"strongs_def":" to journey towards, i.e. approach (not the same as G4313 (προπορεύομαι))","derivation":"from G4314 (πρός) and G4198 (πορεύομαι);","lemma":"προσπορεύομαι","translit":"prosporeúomai","kjv_def":"go before","pron":"pros-por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to draw near, approach</li></ol>","xlit":"prosporeúomai"},"G4915":{"derivation":"from G4862 (σύν) and a derivative of G2244 (ἡλικία);","strongs_def":" a co-aged person, i.e. alike in years","kjv_def":"equal","lemma":"συνηλικιώτης","translit":"synēlikiṓtēs","pron":"soon-ay-lik-ee-o'-tace","pos":"Noun Masculine","thayer":"<ol><li>one of the same age, an equal in age</li></ol>","xlit":"synēlikiṓtēs"},"G1020":{"strongs_def":" to sail slowly","derivation":"from G1021 (βραδύς) and a prolonged form of G4126 (πλέω);","translit":"bradyploéō","lemma":"βραδυπλοέω","kjv_def":"sail slowly","pron":"brad-oo-plo-eh'-o","pos":"Verb","thayer":"<ol><li>to sail slowly</li></ol>","xlit":"bradyploéō"},"G3467":{"derivation":"from a compound of the base of G3466 (μυστήριον) and (the face;","strongs_def":" from G3700 (ὀπτάνομαι)); to shut the eyes, i.e. blink (see indistinctly)","kjv_def":" cannot see far off","translit":"myōpázō","lemma":"μυωπάζω","pron":"moo-ope-ad'-zo","pos":"Verb","thayer":"<ol><li>to see dimly, see only what is near</li></ol>","xlit":"myōpázō"},"G2948":{"derivation":"from the same as G2947 (κυλιόω);","strongs_def":" rocking about, i.e. crippled (maimed, in feet or hands)","kjv_def":"maimed","lemma":"κυλλός","translit":"kyllós","pron":"kool-los'","pos":"Adjective","thayer":"<ol><li>crooked<ol type='a'><li>of the members of the body</li><li>injured, disabled</li></ol><li>maimed, mutilated</li></ol>","xlit":"kyllós"},"G2227":{"lemma":"ζωοποιέω","translit":"zōopoiéō","kjv_def":"make alive, give life, quicken","strongs_def":" to (re-)vitalize (literally or figuratively)","derivation":"from the same as G2226 (ζῶον) and G4160 (ποιέω);","pron":"dzo-op-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to produce alive, begat or bear living young</li><li>to cause to live, make alive, give life<ol type='a'><li>by spiritual power to arouse and invigorate</li><li>to restore to life</li><li>to give increase of life: thus of physical life</li><li>of the spirit, quickening as respects the spirit, endued with new and greater powers of life</li></ol><li>metaphorically, of seeds quickened into life, i.e. germinating, springing up, growing</li></ol>","xlit":"zōopoiéō"},"G3606":{"derivation":"from G3739 (ὅς) with the directive enclitic of source;","strongs_def":" from which place or source or cause (adverb or conjunction)","kjv_def":"from thence, (from) whence, where(-by, -fore, -upon)","translit":"hóthen","lemma":"ὅθεν","pron":"hoth'-en","pos":"Adverb","thayer":"<ol><li>from which, whence<ol type='a'><li>of the place from which</li><li>of the source from which a thing is known, from which, whereby</li><li>of the cause from which, for which reason, wherefore, on which account</li></ol></li></ol>","xlit":"hóthen"},"G3527":{"translit":"Nikánōr","lemma":"Νικάνωρ","kjv_def":"Nicanor","strongs_def":" victorious; Nicanor, a Christian","derivation":"probably from G3528 (νικάω);","pron":"nik-an'-ore","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nicanor = \"conqueror\"</p><ol><li>one of the seven deacons in the church at Jerusalem</li></ol>","xlit":"Nikánōr"},"G1024":{"translit":"brachýs","lemma":"βραχύς","kjv_def":"few words, little (space, while)","strongs_def":" short (of time, place, quantity, or number)","derivation":"of uncertain affinity;","pron":"brakh-ooce'","pos":"Adjective","thayer":"<ol><li>short, small, little<ol type='a'><li>of place, a short distance, a little</li><li>of time, a short time, for a little while</li></ol></li></ol>","xlit":"brachýs"},"G4630":{"derivation":"apparently of Latin origin;","strongs_def":" left-handed; Scevas (i.e. Scævus), an Israelite","kjv_def":"Sceva","translit":"Skeuâs","lemma":"Σκευᾶς","pron":"skyoo-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sceva = \"mind reader\"</p><ol><li>a certain chief priest residing at Ephesus</li></ol>","xlit":"Skeuâs"},"G3677":{"derivation":"of uncertain derivation;","strongs_def":" a dream","kjv_def":"dream","translit":"ónar","lemma":"ὄναρ","pron":"on'-ar","pos":"Noun Neuter","thayer":"<ol><li>a dream</li></ol>","xlit":"ónar"},"G3682":{"derivation":"from G3685 (ὀνίνημι);","strongs_def":" profitable; Onesimus, a Christian","kjv_def":"Onesimus","lemma":"Ὀνήσιμος","translit":"Onḗsimos","pron":"on-ay'-sim-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Onesimus = \"profitable or useful\"</p><ol><li>a Christian slave of Philemon</li></ol>","xlit":"Onḗsimos"},"G1081":{"derivation":"from G1080 (γεννάω);","strongs_def":" offspring; by analogy, produce (literally or figuratively)","kjv_def":"fruit, generation","translit":"génnēma","lemma":"γέννημα","pron":"ghen'-nay-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been born or begotten<ol type='a'><li>the offspring or progeny of men or animals</li><li>the fruits of the earth, the produce of agriculture</li></ol></li></ol>","xlit":"génnēma"},"G5350":{"kjv_def":"speak","translit":"phthéngomai","lemma":"φθέγγομαι","derivation":"probably akin to G5338 (φέγγος) and thus to G5346 (φημί);","strongs_def":" to utter a clear sound, i.e. (generally) to proclaim","pron":"ftheng'-gom-ahee","pos":"Verb","thayer":"<ol><li>to give out a sound, noise or cry<ol type='a'><li>of any sort of sound or voice, whether of man or of animal or inanimate object as thunder, musical instruments, etc.</li></ol></li></ol>","xlit":"phthéngomai"},"G3340":{"derivation":"from G3326 (μετά) and G3539 (νοιέω);","strongs_def":" to think differently or afterwards, i.e. reconsider (morally, feel compunction)","kjv_def":"repent","translit":"metanoéō","lemma":"μετανοέω","pron":"met-an-o-eh'-o","pos":"Verb","thayer":"<ol><li>to change one's mind, i.e. to repent</li><li>to change one's mind for better, heartily to amend with abhorrence of one's past sins</li></ol>","xlit":"metanoéō"},"G3047":{"kjv_def":"southwest","translit":"líps","lemma":"λίψ","derivation":"probably from (to pour a \"libation\");","strongs_def":" the south(- west) wind (as bringing rain, i.e. (by extension) the south quarter)","pron":"leeps","pos":"Noun Masculine","thayer":"<ol><li>the south west wind</li><li>the quarter of the heavens whence the south west wind blows</li></ol>","xlit":"líps"},"G2484":{"kjv_def":"Ituræa","translit":"Itouraḯa","lemma":"Ἰτουραΐα","derivation":"of Hebrew origin (H03195);","strongs_def":" Ituræa (i.e. Jetur), a region of Palestine","pron":"ee-too-rah'-yah","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Ituraea = \"past the limits\" or \"he will arrange\"</p><ol><li>a mountainous region, lying northeast of Palestine and west of Damascus. At the time when John the Baptist made his public appearance it was subject to Philip the tetrarch, son of Herod the Great, among the regions assigned to this prince after his father's death. It was brought under Jewish control by king Aristobulus around 100 B.C. Its inhabitants had been noted for robbery and skilful use of the bow.</li></ol>","xlit":"Itouraḯa"},"G3668":{"kjv_def":"likewise, so","lemma":"ὁμοίως","translit":"homoíōs","derivation":"adverb from G3664 (ὅμοιος);","strongs_def":" similarly","pron":"hom-oy'-oce","pos":"Adverb","thayer":"<ol><li>likewise, equally, in the same way</li></ol>","xlit":"homoíōs"},"G837":{"kjv_def":"grow (up), (give the) increase","translit":"auxánō","lemma":"αὐξάνω","derivation":"a prolonged form of a primary verb;","strongs_def":" to grow (\"wax\"), i.e. enlarge (literal or figurative, active or passive)","pron":"owx-an'-o","pos":"Verb","thayer":"<ol><li>to cause to grow, augment</li><li>to increase, become greater</li><li>to grow, increase<ol type='a'><li>of plants</li><li>of infants</li><li>of a multitude of people</li><li>of inward Christian growth</li></ol></li></ol>","xlit":"auxánō"},"G2234":{"translit":"hēdéōs","lemma":"ἡδέως","kjv_def":"gladly","strongs_def":" sweetly, i.e. (figuratively) with pleasure","derivation":"adverb from a derivative of the base of G2237 (ἡδονή);","pron":"hay-deh'-oce","pos":"Adverb","thayer":"<ol><li>with pleasure, gladly</li></ol>","xlit":"hēdéōs"},"G840":{"kjv_def":"austere","translit":"austērós","lemma":"αὐστηρός","derivation":"from a (presumed) derivative of the same as G109 (ἀήρ) (meaning blown);","strongs_def":" rough (properly as a gale), i.e. (figuratively) severe","pron":"ow-stay-ros'","pos":"Adjective","thayer":"<ol><li>of mind and manners: harsh, rough, rigid</li></ol>","xlit":"austērós"},"G5398":{"translit":"phoberós","lemma":"φοβερός","kjv_def":"fearful, terrible","strongs_def":" frightful, i.e. (objectively) formidable","derivation":"from G5401 (φόβος);","pron":"fob-er-os'","pos":"Adjective","thayer":"<ol><li>inspiring fear, terrible, formidable</li><li>affected with fear, timid</li></ol>","xlit":"phoberós"},"G47":{"lemma":"ἁγνεία","translit":"hagneía","kjv_def":"purity","strongs_def":" cleanliness (the quality), i.e. (specially) chastity","derivation":"from G53 (ἁγνός);","pron":"hag-ni'-ah","pos":"Noun Feminine","thayer":"<ol><li>purity, sinlessness of life</li></ol>","xlit":"hagneía"},"G5411":{"strongs_def":" a load (as borne), i.e. (figuratively) a tax (properly, an individual assessment on persons or property; whereas G5056 (τέλος) is usually a general toll on goods or travel)","derivation":"from G5342 (φέρω);","lemma":"φόρος","translit":"phóros","kjv_def":"tribute","pron":"for'-os","pos":"Noun Masculine","thayer":"<ol><li>tribute, especially the annual tax levied upon houses, lands, and persons</li></ol>","xlit":"phóros"},"G547":{"lemma":"ἀπειλή","translit":"apeilḗ","kjv_def":"X straitly, threatening","strongs_def":" a menace","derivation":"from G546 (ἀπειλέω);","pron":"ap-i-lay'","pos":"Noun Feminine","thayer":"<ol><li>a threatening, threat</li></ol>","xlit":"apeilḗ"},"G2305":{"derivation":"from G2304 (θεῖος);","strongs_def":" divinity (abstractly)","kjv_def":"godhead","translit":"theiótēs","lemma":"θειότης","pron":"thi-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>divinity, divine nature</li></ol>","xlit":"theiótēs"},"G270":{"strongs_def":" properly, to collect, i.e. (by implication) reap","derivation":"from G260 (ἅμα);","lemma":"ἀμάω","translit":"amáō","kjv_def":"reap down","pron":"am-ah'-o","pos":"Verb","thayer":"<ol><li>to reap, mow down</li></ol>","xlit":"amáō"},"G5183":{"derivation":"from G5184 (Τύρος);","strongs_def":" a Tyrian, i.e. inhabitant of Tyrus","kjv_def":"of Tyre","translit":"Týrios","lemma":"Τύριος","pron":"too'-ree-os","pos":"Noun Masculine","thayer":"<ol><li>a resident of Tyre</li></ol>","xlit":"Týrios"},"G322":{"kjv_def":"appoint, shew","lemma":"ἀναδείκνυμι","translit":"anadeíknymi","derivation":"from G303 (ἀνά) and G1166 (δεικνύω);","strongs_def":" to exhibit, i.e. (by implication) to indicate, appoint","pron":"an-ad-ike'-noo-mee","pos":"Verb","thayer":"<ol><li>to proclaim any one as elected to office</li><li>to announce as appointed a king, general, etc.</li><li>to lift up anything on high and exhibit it for all to behold</li></ol>","xlit":"anadeíknymi"},"G4339":{"kjv_def":"proselyte","lemma":"προσήλυτος","translit":"prosḗlytos","derivation":"from the alternate of G4334 (προσέρχομαι);","strongs_def":" an arriver from a foreign region, i.e. (specially), an acceder (convert) to Judaism (\"proselyte\")","pron":"pros-ay'-loo-tos","pos":"Adjective","thayer":"<ol><li>a newcomer<ol type='a'><li>a stranger, alien</li></ol><li>a proselyte<ol type='a'><li>one who has come over from a Gentile religion to Judaism</li></ol></li></ol>","xlit":"prosḗlytos"},"G5231":{"derivation":"from G5228 (ὑπέρ) and G507 (ἄνω);","strongs_def":" above upward, i.e. greatly higher (in place or rank)","kjv_def":"far above, over","translit":"hyperánō","lemma":"ὑπεράνω","pron":"hoop-er-an'-o","pos":"Adverb","thayer":"<ol><li>above<ol type='a'><li>above a thing</li><li>of a place</li><li>of rank or power</li></ol></li></ol>","xlit":"hyperánō"},"G5378":{"lemma":"Φιλόλογος","translit":"Philólogos","kjv_def":"Philologus","strongs_def":" fond of words, i.e. talkative (argumentative, learned, \"philological\"); Philologus, a Christian","derivation":"from G5384 (φίλος) and G3056 (λόγος);","pron":"fil-ol'-og-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Philologus = \"lover of the Word\"</p><ol><li>a Christian Paul greets in his epistle to Romans</li></ol>","xlit":"Philólogos"},"G1706":{"derivation":"from G1722 (ἐν) and G4098 (πίπτω);","strongs_def":" to fall on, i.e. (literally) to be entrapped by, or (figuratively) be overwhelmed with","kjv_def":"fall among (into)","lemma":"ἐμπίπτω","translit":"empíptō","pron":"em-pip'-to","pos":"Verb","thayer":"<ol><li>to fall into<ol type='a'><li>to fall among robbers</li><li>fall into one's power</li></ol></li></ol>","xlit":"empíptō"},"G4897":{"derivation":"from G4862 (σύν) and G1525 (εἰσέρχομαι);","strongs_def":" to enter in company with","kjv_def":"go in with, go with into","translit":"syneisérchomai","lemma":"συνεισέρχομαι","pron":"soon-ice-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to enter together</li></ol>","xlit":"syneisérchomai"},"G2108":{"strongs_def":" beneficence (genitive case or specially)","derivation":"from G2110 (εὐεργέτης);","translit":"euergesía","lemma":"εὐεργεσία","kjv_def":"benefit, good deed done","pron":"yoo-erg-es-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a good deed, benefit</li></ol>","xlit":"euergesía"},"G1811":{"strongs_def":" to follow out, i.e. (figuratively) to imitate, obey, yield to","derivation":"from G1537 (ἐκ) and G190 (ἀκολουθέω);","lemma":"ἐξακολουθέω","translit":"exakolouthéō","kjv_def":"follow","pron":"ex-ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow out or up, tread in one's steps<ol type='a'><li>metaphorically, to imitate one's ways of acting</li><li>to follow one's authority</li><li>to comply with, yield to</li></ol></li></ol>","xlit":"exakolouthéō"},"G2719":{"lemma":"κατεσθίω","translit":"katesthíō","kjv_def":"devour","strongs_def":" to eat down, i.e. devour (literally or figuratively)","derivation":"from G2596 (κατά) and G2068 (ἐσθίω) (including its alternate);","pron":"kat-es-thee'-o","pos":"Verb","thayer":"<ol><li>to consume by eating, to eat up, devour<ol type='a'><li>of birds</li><li>of a dragon</li><li>of a man eating up the little book</li></ol><li>metaphorically<ol type='a'><li>to devour, i.e. squander, waste: substance</li><li>to devour, i.e. forcibly appropriate: widows' property</li><li>to strip one of his goods<ol><li>to ruin (by the infliction of injuries)</li></ol><li>by fire, to devour, i.e. to utterly consume, destroy</li><li>of the consumption of the strength of body and mind by strong emotions</li></ol></li></ol>","xlit":"katesthíō"},"G5473":{"strongs_def":" a copper dish","derivation":"diminutive from G5475 (χαλκός);","translit":"chalkíon","lemma":"χαλκίον","kjv_def":"brazen vessel","pron":"khal-kee'-on","pos":"Noun Neuter","thayer":"<ol><li>a (copper or) brazen vessel</li></ol>","xlit":"chalkíon"},"G3851":{"kjv_def":"not (to) regard(-ing)","translit":"parabouleúomai","lemma":"παραβουλεύομαι","derivation":"from G3844 (παρά) and the middle voice of G1011 (βουλεύω);","strongs_def":" to misconsult, i.e. disregard","pron":"par-ab-ool-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to consult amiss</li></ol>","xlit":"parabouleúomai"},"G5020":{"kjv_def":"cast down to hell","translit":"tartaróō","lemma":"ταρταρόω","derivation":"from (the deepest abyss of Hades);","strongs_def":" to incarcerate in eternal torment","pron":"tar-tar-o'-o","pos":"Verb","thayer":"<ol><li>the name of the subterranean region, doleful and dark, regarded by the ancient Greeks as the abode of the wicked dead, where they suffer punishment for their evil deeds; it answers to Gehenna of the Jews</li><li>to thrust down to Tartarus, to hold captive in Tartarus</li></ol>","xlit":"tartaróō"},"G752":{"kjv_def":"(chief) ruler of the synagogue","lemma":"ἀρχισυνάγωγος","translit":"archisynágōgos","derivation":"from G746 (ἀρχή) and G4864 (συναγωγή);","strongs_def":" director of the synagogue services","pron":"ar-khee-soon-ag'-o-gos","pos":"Noun Masculine","thayer":"<ol><li>ruler of the synagogue. It was his duty to select the readers or teachers in the synagogue, to examine the discourses of the public speakers, and to see that all things were done with decency and in accordance with ancestral usage.</li></ol>","xlit":"archisynágōgos"},"G5113":{"strongs_def":" a daring (audacious) man","derivation":"from G5111 (τολμάω);","lemma":"τολμητής","translit":"tolmētḗs","kjv_def":"presumptuous","pron":"tol-may-tace'","pos":"Noun Masculine","thayer":"<ol><li>a daring man</li></ol>","xlit":"tolmētḗs"},"G2132":{"lemma":"εὐνοέω","translit":"eunoéō","kjv_def":"agree","strongs_def":" to be well- minded, i.e. reconcile","derivation":"from a compound of G2095 (εὖ) and G3563 (νοῦς);","pron":"yoo-no-eh'-o","pos":"Verb","thayer":"<ol><li>to wish (one) well</li><li>to be well disposed, of a peaceable spirit</li></ol>","xlit":"eunoéō"},"G1872":{"translit":"epakolouthéō","lemma":"ἐπακολουθέω","kjv_def":"follow (after)","strongs_def":" to accompany","derivation":"from G1909 (ἐπί) and G190 (ἀκολουθέω);","pron":"ep-ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow (close) upon, follow after</li><li>to tread in one's footsteps, i.e. to imitate his example</li></ol>","xlit":"epakolouthéō"},"G3581":{"strongs_def":" foreign (literally, alien, or figuratively, novel); by implication, a guest or (vice-versa) entertainer","derivation":"apparently a primary word;","translit":"xénos","lemma":"ξένος","kjv_def":"host, strange(-r)","pron":"xen'-os","pos":"Adjective","thayer":"<ol><li>a foreigner, a stranger<ol type='a'><li>alien (from a person or a thing)</li><li>without the knowledge of, without a share in</li><li>new, unheard of</li></ol><li>one who receives and entertains another hospitably<ol type='a'><li>with whom he stays or lodges, a host</li></ol></li></ol>","xlit":"xénos"},"G903":{"strongs_def":" Balaam, a Mesopotamian (symbolic of a false teacher)","derivation":"of Hebrew origin (H01109);","lemma":"Βαλαάμ","translit":"Balaám","kjv_def":"Balaam","pron":"bal-ah-am'","pos":"Noun Masculine","thayer":"<ol><li>A native of Pethor a city in Mesopotamia, endued by Jehovah with prophetic power. He was hired by Balak to curse the Israelites; and influenced by the love of reward, he wished to gratify Balak; but he was compelled by Jehovah's power to bless them. Hence later the Jews saw him as a most abandoned deceiver.</li></ol>","xlit":"Balaám"},"G4041":{"kjv_def":"peculiar","lemma":"περιούσιος","translit":"perioúsios","derivation":"from the present participle feminine of a compound of 4012 and G1510 (εἰμί);","strongs_def":" being beyond usual, i.e. special (one's own)","pron":"per-ee-oo'-see-os","pos":"Adjective","thayer":"<ol><li>that which is one's own, belonging to one's possessions<ol type='a'><li>a people selected by God from the other nations for his own possession</li></ol></li></ol>","xlit":"perioúsios"},"G3038":{"lemma":"λιθόστρωτος","translit":"lithóstrōtos","kjv_def":"Pavement","strongs_def":" stone-strewed, i.e. a tessellated mosaic on which the Roman tribunal was placed","derivation":"from G3037 (λίθος) and a derivative of G4766 (στρώννυμι);","pron":"lith-os'-tro-tos","pos":"Adjective","thayer":"<ol><li>spread (paved with stones)</li><li>a mosaic or tessellated pavement<ol type='a'><li>of a place near the praetorium or palace of Jerusalem</li><li>an apartment whose pavement consists of tessellated work</li><li>of places in the outer courts of temple</li></ol></li></ol>","xlit":"lithóstrōtos"},"G739":{"lemma":"ἄρτιος","translit":"ártios","kjv_def":"perfect","strongs_def":" fresh, i.e. (by implication) complete","derivation":"from G737 (ἄρτι);","pron":"ar'-tee-os","pos":"Adjective","thayer":"<ol><li>fitted</li><li>complete, perfect<ol type='a'><li>having reference apparently to \"special aptitude for given uses\"</li></ol></li></ol>","xlit":"ártios"},"G4739":{"lemma":"στήκω","translit":"stḗkō","kjv_def":"stand (fast)","strongs_def":" to be stationary, i.e. (figuratively) to persevere","derivation":"from the perfect tense of G2476 (ἵστημι);","pron":"stay'-ko","pos":"Verb","thayer":"<ol><li>to stand firm</li><li>to persevere, to persist</li><li>to keep one's standing</li></ol>","xlit":"stḗkō"},"G3507":{"derivation":"from G3509 (νέφος);","strongs_def":" properly, cloudiness, i.e. (concretely) a cloud","kjv_def":"cloud","lemma":"νεφέλη","translit":"nephélē","pron":"nef-el'-ay","pos":"Noun Feminine","thayer":"<ol><li>a cloud<ol type='a'><li>used of the cloud which led the Israelites in the wilderness</li></ol></li></ol>","xlit":"nephélē"},"G3899":{"kjv_def":"go, pass (by)","lemma":"παραπορεύομαι","translit":"paraporeúomai","derivation":"from G3844 (παρά) and G4198 (πορεύομαι);","strongs_def":" to travel near","pron":"par-ap-or-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to proceed at the side, go past, pass by</li></ol>","xlit":"paraporeúomai"},"G3464":{"derivation":"probably of foreign origin (compare H04753, G4666 (σμύρνα));","strongs_def":" \"myrrh\", i.e. (by implication) perfumed oil","kjv_def":"ointment","lemma":"μύρον","translit":"mýron","pron":"moo'-ron","pos":"Noun Neuter","thayer":"<ol><li>ointment</li></ol>","xlit":"mýron"},"G3115":{"kjv_def":"longsuffering, patience","lemma":"μακροθυμία","translit":"makrothymía","derivation":"from the same as G3116 (μακροθυμώς);","strongs_def":" longanimity, i.e. (objectively) forbearance or (subjectively) fortitude","pron":"mak-roth-oo-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>patience, endurance, constancy, steadfastness, perseverance</li><li>patience, forbearance, longsuffering, slowness in avenging wrongs</li></ol>","xlit":"makrothymía"},"G1070":{"translit":"geláō","lemma":"γελάω","kjv_def":"laugh","strongs_def":" to laugh (as a sign of joy or satisfaction)","derivation":"of uncertain affinity;","pron":"ghel-ah'-o","pos":"Verb","thayer":"<ol><li>to laugh</li></ol>","xlit":"geláō"},"G4134":{"strongs_def":" replete, or covered over; by analogy, complete","derivation":"from G4130 (πλήθω);","translit":"plḗrēs","lemma":"πλήρης","kjv_def":"full","pron":"play'-race","pos":"Adjective","thayer":"<ol><li>full, i.e. filled up (as opposed to empty)<ol type='a'><li>of hollow vessels</li><li>of a surface, covered in every part</li><li>of the soul, thoroughly permeated with</li></ol><li>full, i.e. complete<ol type='a'><li>lacking nothing, perfect</li></ol></li></ol>","xlit":"plḗrēs"},"G1876":{"derivation":"neuter of a presumed compound of G1909 (ἐπί) and G318 (ἀνάγκη);","strongs_def":" (adverbially) on necessity, i.e. necessarily","kjv_def":"necessary","lemma":"ἐπάναγκες","translit":"epánankes","pron":"ep-an'-ang-kes","pos":"Adjective Neuter","thayer":"<ol><li>necessarily</li></ol>","xlit":"epánankes"},"G496":{"kjv_def":"resist","lemma":"ἀντιπίπτω","translit":"antipíptō","derivation":"from G473 (ἀντί) and G4098 (πίπτω) (including its alternate);","strongs_def":" to oppose","pron":"an-tee-pip'-to","pos":"Verb","thayer":"<ol><li>to fall upon, run against</li><li>to be adverse, oppose, strive against</li></ol>","xlit":"antipíptō"},"G390":{"kjv_def":"abide, behave self, have conversation, live, overthrow, pass, return, be used","translit":"anastréphō","lemma":"ἀναστρέφω","derivation":"from G303 (ἀνά) and G4762 (στρέφω);","strongs_def":" to overturn; also to return; by implication, to busy oneself, i.e. remain, live","pron":"an-as-tref'-o","pos":"Verb","thayer":"<ol><li>to turn upside down, overturn</li><li>to turn back</li><li>to turn hither and thither, to turn one's self about, sojourn dwell in a place</li><li>metaphorically to conduct one's self, behave one's self, live</li></ol>","xlit":"anastréphō"},"G1206":{"strongs_def":" secondary, i.e. (specially) on the second day","derivation":"from G1208 (δεύτερος);","lemma":"δευτεραῖος","translit":"deuteraîos","kjv_def":"next day","pron":"dyoo-ter-ah'-yos","pos":"Adjective","thayer":"<ol><li>of or belonging to the second</li><li>of one who comes or does a thing, on the second day</li></ol>","xlit":"deuteraîos"},"G4538":{"kjv_def":"trumpeter","translit":"salpistḗs","lemma":"σαλπιστής","derivation":"from G4537 (σαλπίζω);","strongs_def":" a trumpeter","pron":"sal-pis-tace'","pos":"Noun Masculine","thayer":"<ol><li>a trumpeter</li></ol>","xlit":"salpistḗs"},"G3734":{"kjv_def":"bound","translit":"horothesía","lemma":"ὁροθεσία","derivation":"from a compound of the base of G3725 (ὅριον) and a derivative of G5087 (τίθημι);","strongs_def":" a limit-placing, i.e. (concretely) boundary-line","pron":"hor-oth-es-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a setting of boundaries, laying down limits</li><li>a definite limit, bounds</li></ol>","xlit":"horothesía"},"G1391":{"kjv_def":"dignity, glory(-ious), honour, praise, worship","lemma":"δόξα","translit":"dóxa","derivation":"from the base of G1380 (δοκέω);","strongs_def":" glory (as very apparent), in a wide application (literal or figurative, objective or subjective)","pron":"dox'-ah","pos":"Noun Feminine","thayer":"<ol><li>opinion, judgment, view</li><li>opinion, estimate, whether good or bad concerning someone<ol type='a'><li>in the NT always a good opinion concerning one, resulting in praise, honour, and glory</li></ol><li>splendour, brightness<ol type='a'><li>of the moon, sun, stars</li><li>magnificence, excellence, preeminence, dignity, grace</li><li>majesty<ol><li>a thing belonging to God</li><li>the kingly majesty which belongs to him as supreme ruler, majesty in the sense of the absolute perfection of the deity</li><li>a thing belonging to Christ<ol type='a'><li>the kingly majesty of the Messiah</li><li>the absolutely perfect inward or personal excellency of Christ; the majesty</li></ol><li>of the angels<ol type='a'><li>as apparent in their exterior brightness</li></ol></li></ol></li></ol><li>a most glorious condition, most exalted state<ol type='a'><li>of that condition with God the Father in heaven to which Christ was raised after he had achieved his work on earth</li><li>the glorious condition of blessedness into which is appointed and promised that true Christians shall enter after their Saviour's return from heaven</li></ol></li></ol>","xlit":"dóxa"},"G3427":{"derivation":"the simpler form of G1698 (ἐμοί);","strongs_def":" to me","kjv_def":"I, me, mine, my","lemma":"μοί","translit":"moí","pron":"moy","thayer":"<ol><li>I, me, my</li></ol>","xlit":"moí"},"G4501":{"lemma":"ῥομφαία","translit":"rhomphaía","kjv_def":"sword","strongs_def":" a sabre, i.e. a long and broad cutlass (any weapon of the kind, literally or figuratively)","derivation":"probably of foreign origin;","pron":"hrom-fah'-yah","pos":"Noun Feminine","thayer":"<ol><li>a large sword</li><li>properly a long Thracian javelin, also a kind of long sword wont to be worn on the right shoulder</li></ol>","xlit":"rhomphaía"},"G5136":{"strongs_def":" to seize by the throat or neck, i.e. to expose the gullet of a victim for killing (generally, to lay bare)","derivation":"from G5137 (τράχηλος);","translit":"trachēlízō","lemma":"τραχηλίζω","kjv_def":"opened","pron":"trakh-ay-lid'-zo","pos":"Verb","thayer":"<ol><li>to seize and twist the neck or throat<ol type='a'><li>of combatants who handle thus their antagonist</li></ol><li>to bend back the neck of a victim to be slain, to lay bare or expose by bending back</li><li>to lay bare, uncover, expose</li><li>laid bare, laid open, made manifest to one</li></ol>","xlit":"trachēlízō"},"G535":{"lemma":"ἀπαρτισμός","translit":"apartismós","kjv_def":"finishing","strongs_def":" completion","derivation":"from a derivative of G534 (ἀπάρτι);","pron":"ap-ar-tis-mos'","pos":"Noun Masculine","thayer":"<ol><li>completion</li></ol>","xlit":"apartismós"},"G5471":{"translit":"chalkeús","lemma":"χαλκεύς","kjv_def":"coppersmith","strongs_def":" a copper-worker or brazier","derivation":"from G5475 (χαλκός);","pron":"khalk-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a worker in copper or iron, a smith</li></ol>","xlit":"chalkeús"},"G2726":{"strongs_def":" demureness, i.e. (by implication) sadness","derivation":"from a compound of G2596 (κατά) and perhaps a derivative of the base of G5316 (φαίνω) (meaning downcast in look);","lemma":"κατήφεια","translit":"katḗpheia","kjv_def":"heaviness","pron":"kat-ay'-fi-ah","pos":"Noun Feminine","thayer":"<ol><li>a downcast look expressive of sorrow</li><li>shame, dejection, gloom</li></ol>","xlit":"katḗpheia"},"G5484":{"lemma":"χάριν","translit":"chárin","kjv_def":"be-(for) cause of, for sake of, +…fore, X reproachfully","strongs_def":" through favor of, i.e. on account of","derivation":"accusative case of G5485 (χάρις) as preposition;","pron":"khar'-in","pos":"Preposition","thayer":"<ol><li>in favour of, for the pleasure of</li><li>for, for the sake of</li><li>on this account, for this cause</li></ol>","xlit":"chárin"},"G5234":{"strongs_def":" excessively","derivation":"adverb from present participle active of G5235 (ὑπερβάλλω);","lemma":"ὑπερβαλλόντως","translit":"hyperballóntōs","kjv_def":"beyond measure","pron":"hoop-er-bal-lon'-toce","pos":"Adverb","thayer":"<ol><li>above measure</li></ol>","xlit":"hyperballóntōs"},"G898":{"lemma":"βαθμός","translit":"bathmós","kjv_def":"degree","strongs_def":" a step, i.e. (figuratively) grade (of dignity)","derivation":"from the same as G899 (βάθος);","pron":"bath-mos'","pos":"Noun Masculine","thayer":"<ol><li>threshold, step<ol type='a'><li>of a grade of dignity and wholesome influence in the church</li></ol></li></ol>","xlit":"bathmós"},"G1055":{"derivation":"of uncertain derivation;","strongs_def":" tranquillity","kjv_def":"calm","translit":"galḗnē","lemma":"γαλήνη","pron":"gal-ay'-nay","pos":"Noun Feminine","thayer":"<ol><li>calmness, stillness of the sea, a calm</li></ol>","xlit":"galḗnē"},"G3186":{"strongs_def":" still larger (figuratively)","derivation":"continued comparative of G3187 (μείζων);","translit":"meizóteros","lemma":"μειζότερος","kjv_def":"greater","pron":"mide-zot'-er-os","pos":"Adjective","thayer":"<ol><li>greater</li></ol>","xlit":"meizóteros"},"G2782":{"derivation":"from G2784 (κηρύσσω);","strongs_def":" a proclamation (especially of the gospel; by implication, the gospel itself)","kjv_def":"preaching","lemma":"κήρυγμα","translit":"kḗrygma","pron":"kay'-roog-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is proclaimed by a herald or public crier, a proclamation by herald</li><li>in the NT the message or proclamation of the heralds of God or Christ</li></ol>","xlit":"kḗrygma"},"G4863":{"strongs_def":" to lead together, i.e. collect or convene; specially, to entertain (hospitably)","derivation":"from G4862 (σύν) and G71 (ἄγω);","translit":"synágō","lemma":"συνάγω","kjv_def":"+ accompany, assemble (selves, together), bestow, come together, gather (selves together, up, together), lead into, resort, take in","pron":"soon-ag'-o","pos":"Verb","thayer":"<ol><li>to gather together, to gather<ol type='a'><li>to draw together, collect<ol><li>of fishes</li><li>of a net in which they are caught</li></ol></li></ol><li>to bring together, assemble, collect<ol type='a'><li>to join together, join in one (those previously separated)</li><li>to gather together by convoking</li><li>to be gathered, i.e. come together, gather, meet</li></ol><li>to lead with one's self<ol type='a'><li>into one's home, i.e. to receive hospitably, to entertain</li></ol></li></ol>","xlit":"synágō"},"G2023":{"translit":"epichorēgéō","lemma":"ἐπιχορηγέω","kjv_def":"add, minister (nourishment, unto)","strongs_def":" to furnish besides, i.e. fully supply, (figuratively) aid or contribute","derivation":"from G1909 (ἐπί) and G5524 (χορηγέω);","pron":"ep-ee-khor-ayg-eh'-o","pos":"Verb","thayer":"<ol><li>to supply, furnish, present</li><li>to be supplied, ministered to, assisted</li></ol>","xlit":"epichorēgéō"},"G2050":{"lemma":"ἐρήμωσις","translit":"erḗmōsis","kjv_def":"desolation","strongs_def":" despoliation","derivation":"from G2049 (ἐρημόω);","pron":"er-ay'-mo-sis","pos":"Noun Feminine","thayer":"<ol><li>a making desolate, desolation</li></ol>","xlit":"erḗmōsis"},"G2822":{"strongs_def":" invited, i.e. appointed, or (specially), a saint","derivation":"from the same as G2821 (κλῆσις);","translit":"klētós","lemma":"κλητός","kjv_def":"called","pron":"klay-tos'","pos":"Adjective","thayer":"<ol><li>called, invited (to a banquet)<ol type='a'><li>invited (by God in the proclamation of the Gospel) to obtain eternal salvation in the kingdom through Christ</li><li>called to (the discharge of) some office<ol><li>divinely selected and appointed</li></ol></li></ol></li></ol>","xlit":"klētós"},"G1930":{"kjv_def":"set in order","translit":"epidiorthóō","lemma":"ἐπιδιορθόω","derivation":"from G1909 (ἐπί) and a derivative of G3717 (ὀρθός);","strongs_def":" to straighten further, i.e. (figuratively) arrange additionally","pron":"ep-ee-dee-or-tho'-o","pos":"Verb","thayer":"<ol><li>to set in order besides or further</li></ol>","xlit":"epidiorthóō"},"G1121":{"translit":"grámma","lemma":"γράμμα","kjv_def":"bill, learning, letter, scripture, writing, written","strongs_def":" a writing, i.e. a letter, note, epistle, book, etc.; plural learning","derivation":"from G1125 (γράφω);","pron":"gram'-mah","pos":"Noun Neuter","thayer":"<ol><li>a letter</li><li>any writing, a document or record<ol type='a'><li>a note of hand, bill, bond, account, written acknowledgement of a debt</li><li>a letter, an epistle</li><li>the sacred writings (of the OT)</li></ol><li>letters, i.e. learning<ol type='a'><li>of sacred learning</li></ol></li></ol>","xlit":"grámma"},"G3599":{"derivation":"perhaps from the base of G2068 (ἐσθίω);","strongs_def":" a \"tooth\"","kjv_def":"tooth","lemma":"ὀδούς","translit":"odoús","pron":"od-ooce","pos":"Noun Masculine","thayer":"<ol><li>a tooth</li></ol>","xlit":"odoús"},"G2849":{"derivation":"from (dwarf);","strongs_def":" properly, to curtail, i.e. (figuratively) to chastise (or reserve for infliction)","kjv_def":"punish","translit":"kolázō","lemma":"κολάζω","pron":"kol-ad'-zo","pos":"Verb","thayer":"<ol><li>to lop or prune, as trees and wings</li><li>to curb, check, restrain</li><li>to chastise, correct, punishment</li><li>to cause to be punished</li></ol>","xlit":"kolázō"},"G4099":{"lemma":"Πισιδία","translit":"Pisidía","kjv_def":"Pisidia","strongs_def":" Pisidia, a region of Asia Minor","derivation":"probably of foreign origin;","pron":"pis-id-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Pisidia = \"pitchy\"</p><ol><li>a region in Asia Minor bounded by Pamphylia, and the Pamphylian Sea, Phrygia, and Lycaonia</li></ol>","xlit":"Pisidía"},"G3948":{"kjv_def":"contention, provoke unto","lemma":"παροξυσμός","translit":"paroxysmós","derivation":"from G3947 (παροξύνω) (\"paroxysm\");","strongs_def":" incitement (to good), or dispute (in anger)","pron":"par-ox-oos-mos'","pos":"Noun Masculine","thayer":"<ol><li>an inciting, incitement</li><li>irritation</li></ol>","xlit":"paroxysmós"},"G1839":{"derivation":"from G1537 (ἐκ) and G2476 (ἵστημι);","strongs_def":" to put (stand) out of wits, i.e. astound, or (reflexively) become astounded, insane","kjv_def":"amaze, be (make) astonished, be beside self (selves), bewitch, wonder","lemma":"ἐξίστημι","translit":"exístēmi","pron":"ex-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to throw out of position, displace<ol type='a'><li>to amaze, to astonish, throw into wonderment</li><li>to be amazed, astounded</li><li>to be out of one's mind, besides one's self, insane</li></ol></li></ol>","xlit":"exístēmi"},"G4898":{"strongs_def":" a co-absentee from home, i.e. fellow-traveller","derivation":"from G4862 (σύν) and the base of G1553 (ἐκδημέω);","lemma":"συνέκδημος","translit":"synékdēmos","kjv_def":"companion in travel, travel with","pron":"soon-ek'-day-mos","pos":"Noun Masculine","thayer":"<ol><li>a fellow traveller, companion in travel</li></ol>","xlit":"synékdēmos"},"G4414":{"kjv_def":"ringleader","lemma":"πρωτοστάτης","translit":"prōtostátēs","derivation":"from G4413 (πρῶτος) and G2476 (ἵστημι);","strongs_def":" one standing first in the ranks, i.e. a captain (champion)","pron":"pro-tos-tat'-ace","pos":"Noun Masculine","thayer":"<ol><li>one who stands in the front rank<ol type='a'><li>a leader, chief, champion</li></ol></li></ol>","xlit":"prōtostátēs"},"G212":{"strongs_def":" braggadocio, i.e. (by implication) self-confidence","derivation":"from G213 (ἀλαζών);","lemma":"ἀλαζονεία","translit":"alazoneía","kjv_def":"boasting, pride","pron":"al-ad-zon-i'-a","pos":"Noun Feminine","thayer":"<ol><li>empty, braggart talk</li><li>an insolent and empty assurance, which trusts in its own power and resources and shamefully despises and violates divine laws and human rights</li><li>an impious and empty presumption which trusts in the stability of earthy things</li></ol>","xlit":"alazoneía"},"G4660":{"strongs_def":" to flay, i.e. (figuratively) to harass","derivation":"apparently a primary verb;","translit":"skýllō","lemma":"σκύλλω","kjv_def":"trouble(self)","pron":"skool'-lo","pos":"Verb","thayer":"<ol><li>to skin, flay</li><li>to rend, mangle<ol type='a'><li>to vex, trouble, annoy</li><li>to give one's self trouble, trouble one's self</li></ol></li></ol>","xlit":"skýllō"},"G481":{"translit":"antikrý","lemma":"ἀντικρύ","kjv_def":"over against","strongs_def":" opposite","derivation":"prolonged from G473 (ἀντί);","pron":"an-tee-kroo'","pos":"Adverb","thayer":"<ol><li>over against, opposite</li></ol>","xlit":"antikrý"},"G2586":{"kjv_def":"smoke","translit":"kapnós","lemma":"καπνός","derivation":"of uncertain affinity;","strongs_def":" smoke","pron":"kap-nos'","pos":"Noun Masculine","thayer":"<ol><li>smoke</li></ol>","xlit":"kapnós"},"G2072":{"kjv_def":"glass","translit":"ésoptron","lemma":"ἔσοπτρον","derivation":"from G1519 (εἰς) and a presumed derivative of G3700 (ὀπτάνομαι);","strongs_def":" a mirror (for looking into)","pron":"es'-op-tron","pos":"Noun Neuter","thayer":"<ol><li>a mirror<ol type='a'><li>the mirrors of the ancients were made, not of glass, but steel</li></ol></li></ol>","xlit":"ésoptron"},"G4408":{"lemma":"πρῶρα","translit":"prōra","kjv_def":"forepart(-ship)","strongs_def":" the prow, i.e. forward part of a vessel","derivation":"feminine of a presumed derivative of G4253 (πρό) as noun;","pron":"pro'-ra","pos":"Adjective","thayer":"<ol><li>the prow or forward part of a ship</li></ol>","xlit":"prōra"},"G5252":{"strongs_def":" to esteem oneself overmuch, i.e. be vain or arrogant","derivation":"from G5228 (ὑπέρ) and G5426 (φρονέω);","translit":"hyperphronéō","lemma":"ὑπερφρονέω","kjv_def":"think more highly","pron":"hoop-er-fron-eh'-o","pos":"Verb","thayer":"<ol><li>to think more highly of one's self than is proper</li></ol>","xlit":"hyperphronéō"},"G4587":{"translit":"semnótēs","lemma":"σεμνότης","kjv_def":"gravity, honesty","strongs_def":" venerableness, i.e. probity","derivation":"from G4586 (σεμνός);","pron":"sem-not'-ace","pos":"Noun Feminine","thayer":"<ol><li>the characteristic of a thing or person which entitles to reverence and respect, dignity, majesty, sanctity</li><li>honour, purity</li></ol>","xlit":"semnótēs"},"G4730":{"translit":"stenochōría","lemma":"στενοχωρία","kjv_def":"anguish, distress","strongs_def":" narrowness of room, i.e. (figuratively) calamity","derivation":"from a compound of G4728 (στενός) and G5561 (χώρα);","pron":"sten-okh-o-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>narrowness of place, a narrow place</li><li>metaphorically dire calamity, extreme affliction</li></ol>","xlit":"stenochōría"},"G3389":{"strongs_def":" a mother-thresher, i.e. matricide","derivation":"from G3384 (μήτηρ) and the base of G257 (ἅλων);","translit":"mētralṓias","lemma":"μητραλῴας","kjv_def":"murderer of mothers","pron":"may-tral-o'-as","pos":"Noun Masculine","thayer":"<ol><li>matricide, the murderer of a mother</li></ol>","xlit":"mētralṓias"},"G1877":{"translit":"epanágō","lemma":"ἐπανάγω","kjv_def":"launch (thrust) out, return","strongs_def":" to lead up on, i.e. (technical) to put out (to sea); (intransitively) to return","derivation":"from G1909 (ἐπί) and G321 (ἀνάγω);","pron":"ep-an-ag'-o","pos":"Verb","thayer":"<ol><li>to lead up upon<ol type='a'><li>a ship upon the deep, to put out</li></ol><li>to lead back</li><li>to return</li></ol>","xlit":"epanágō"},"G5042":{"lemma":"τεκνογονία","translit":"teknogonía","kjv_def":"childbearing","strongs_def":" childbirth (parentage), i.e. (by implication) maternity (the performance of maternal duties)","derivation":"from the same as G5041 (τεκνογονέω);","pron":"tek-nog-on-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>childbearing</li></ol>","xlit":"teknogonía"},"G400":{"translit":"anaphōnéō","lemma":"ἀναφωνέω","kjv_def":"speak out","strongs_def":" to exclaim","derivation":"from G303 (ἀνά) and G5455 (φωνέω);","pron":"an-af-o-neh'-o","pos":"Verb","thayer":"<ol><li>to cry out with a loud voice, call aloud, exclaim</li></ol>","xlit":"anaphōnéō"},"G5037":{"kjv_def":"also, and, both, even, then, whether","translit":"té","lemma":"τέ","derivation":"a primary particle (enclitic) of connection or addition;","strongs_def":" both or also (properly, as correlation of G2532 (καί))","pron":"teh","thayer":"<ol><li>not only ... but also</li><li>both ... and</li><li>as ... so</li></ol>","xlit":"té"},"G2440":{"translit":"himátion","lemma":"ἱμάτιον","kjv_def":"apparel, cloke, clothes, garment, raiment, robe, vesture","strongs_def":" a dress (inner or outer)","derivation":"neuter of a presumed derivative of ennumi (to put on);","pron":"him-at'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a garment (of any sort)<ol type='a'><li>garments, i.e. the cloak or mantle and the tunic</li></ol><li>the upper garment, the cloak or mantle</li></ol>","xlit":"himátion"},"G395":{"strongs_def":" a rising of light, i.e. dawn (figuratively); by implication, the east (also in plural)","derivation":"from G393 (ἀνατέλλω);","translit":"anatolḗ","lemma":"ἀνατολή","kjv_def":"dayspring, east, rising","pron":"an-at-ol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a rising (of the sun and stars)</li><li>the east (the direction of the sun's rising)</li></ol>","xlit":"anatolḗ"},"G3748":{"lemma":"ὅστις","translit":"hóstis","kjv_def":"X and (they), (such) as, (they) that, in that they, what(-soever), whereas ye, (they) which, who(-soever)","strongs_def":" which some, i.e. any that; also (definite) which same","derivation":"from G3739 (ὅς) and G5100 (τὶς);","pron":"hos'-tis","thayer":"<ol><li>whoever, whatever, who</li></ol>","xlit":"hóstis"},"G4994":{"strongs_def":" to make of sound mind, i.e. (figuratively) to discipline or correct","derivation":"from G4998 (σώφρων);","lemma":"σωφρονίζω","translit":"sōphronízō","kjv_def":"teach to be sober","pron":"so-fron-id'-zo","pos":"Verb","thayer":"<ol><li>restore one to his senses</li><li>to moderate, control, curb, disciple</li><li>to hold one to his duty</li><li>to admonish, to exhort earnestly</li></ol>","xlit":"sōphronízō"},"G569":{"derivation":"from G571 (ἄπιστος);","strongs_def":" to be unbelieving, i.e. (transitively) disbelieve, or (by implication) disobey","kjv_def":"believe not","translit":"apistéō","lemma":"ἀπιστέω","pron":"ap-is-teh'-o","pos":"Verb","thayer":"<ol><li>to betray a trust, be unfaithful</li><li>to have no belief, disbelieve</li></ol>","xlit":"apistéō"},"G4112":{"strongs_def":" moulded, i.e. (by implication) artificial or (figuratively) fictitious (false)","derivation":"from G4111 (πλάσσω);","translit":"plastós","lemma":"πλαστός","kjv_def":"feigned","pron":"plas-tos'","pos":"Adjective","thayer":"<ol><li>moulded, formed, as from clay, wax, or stone</li><li>feigned</li></ol>","xlit":"plastós"},"G1714":{"lemma":"ἐμπρήθω","translit":"emprḗthō","kjv_def":"burn up","strongs_def":" to enkindle, i.e. set on fire","derivation":"from G1722 (ἐν) and (to blow a flame);","pron":"em-pray'-tho","pos":"Verb","thayer":"<ol><li>to burn</li><li>destroy by fire</li></ol>","xlit":"emprḗthō"},"G2633":{"lemma":"κατάκρισις","translit":"katákrisis","kjv_def":"condemn(-ation)","strongs_def":" sentencing adversely (the act)","derivation":"from G2632 (κατακρίνω);","pron":"kat-ak'-ree-sis","pos":"Verb","thayer":"<ol><li>condemnation</li></ol>","xlit":"katákrisis"},"G2602":{"strongs_def":" a deposition, i.e. founding; figuratively, conception","derivation":"from G2598 (καταβάλλω);","lemma":"καταβολή","translit":"katabolḗ","kjv_def":"conceive, foundation","pron":"kat-ab-ol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a throwing or laying down<ol type='a'><li>the injection or depositing of the virile semen in the womb</li><li>of the seed of plants and animals</li></ol><li>a founding (laying down a foundation)</li></ol>","xlit":"katabolḗ"},"G3770":{"derivation":"from G3772 (οὐρανός);","strongs_def":" celestial, i.e. belonging to or coming from the sky","kjv_def":"heavenly","translit":"ouránios","lemma":"οὐράνιος","pron":"oo-ran'-ee-os","pos":"Adjective","thayer":"<ol><li>heavenly<ol type='a'><li>dwelling in heaven</li><li>coming from heaven</li></ol></li></ol>","xlit":"ouránios"},"G4037":{"kjv_def":"wait for","translit":"periménō","lemma":"περιμένω","derivation":"from G4012 (περί) and G3306 (μένω);","strongs_def":" to stay around, i.e. await","pron":"per-ee-men'-o","pos":"Verb","thayer":"<ol><li>to wait for</li></ol>","xlit":"periménō"},"G806":{"translit":"asphalōs","lemma":"ἀσφαλῶς","kjv_def":"assuredly, safely","strongs_def":" securely (literally or figuratively)","derivation":"adverb from G804 (ἀσφαλής);","pron":"as-fal-oce'","pos":"Adverb","thayer":"<ol><li>safety (so as to prevent escape), assuredly</li></ol>","xlit":"asphalōs"},"G2470":{"kjv_def":"+ agree, as much, equal, like","translit":"ísos","lemma":"ἴσος","derivation":"probably from G1492 (εἴδω) (through the idea of seeming);","strongs_def":" similar (in amount and kind)","pron":"ee'-sos","pos":"Adjective","thayer":"<ol><li>equal, in quantity or quality</li></ol>","xlit":"ísos"},"G1689":{"kjv_def":"behold, gaze up, look upon, (could) see","lemma":"ἐμβλέπω","translit":"emblépō","derivation":"from G1722 (ἐν) and G991 (βλέπω);","strongs_def":" to look on, i.e. (relatively) to observe fixedly, or (absolutely) to discern clearly","pron":"em-blep'-o","pos":"Verb","thayer":"<ol><li>to turn one's eyes on</li><li>look at</li><li>metaphorically to look at with the mind, to consider</li></ol>","xlit":"emblépō"},"G1329":{"derivation":"from G1223 (διά) and G2059 (ἑρμηνεύω);","strongs_def":" to explain thoroughly, by implication, to translate","kjv_def":"expound, interpret(-ation)","translit":"diermēneúō","lemma":"διερμηνεύω","pron":"dee-er-main-yoo'-o","pos":"Verb","thayer":"<ol><li>to unfold the meaning of what is said, explain, expound</li><li>to translate into one's native language</li></ol>","xlit":"diermēneúō"},"G750":{"derivation":"from G746 (ἀρχή) and G4166 (ποιμήν);","strongs_def":" a head shepherd","kjv_def":"chief shepherd","translit":"archipoímēn","lemma":"ἀρχιποίμην","pron":"ar-khee-poy'-mane","pos":"Noun Masculine","thayer":"<ol><li>chief shepherd<ol type='a'><li>of Christ the head of the church</li></ol></li></ol>","xlit":"archipoímēn"},"G4582":{"kjv_def":"moon","translit":"selḗnē","lemma":"σελήνη","derivation":"from (brilliancy;","strongs_def":" probably akin to the alternate of G138 (αἱρέομαι), through the idea of attractiveness); the moon","pron":"sel-ay'-nay","pos":"Noun Feminine","thayer":"<ol><li>the moon</li></ol>","xlit":"selḗnē"},"G5445":{"kjv_def":"lump","translit":"phýrama","lemma":"φύραμα","derivation":"from a prolonged form of (to mix a liquid with a solid;","strongs_def":" perhaps akin to G5453 (φύω) through the idea of swelling in bulk), mean to knead; a mass of dough","pron":"foo'-ram-ah","pos":"Noun Neuter","thayer":"<ol><li>any substance mixed with water and kneaded</li><li>a mass, a lump<ol type='a'><li>of dough</li><li>of clay</li></ol></li></ol>","xlit":"phýrama"},"G874":{"lemma":"ἀφορμή","translit":"aphormḗ","kjv_def":"occasion","strongs_def":" a starting-point, i.e. (figuratively) an opportunity","derivation":"from a compound of G575 (ἀπό) and G3729 (ὁρμάω);","pron":"af-or-may'","pos":"Noun Feminine","thayer":"<ol><li>a place from which a movement or attack is made, a base of operations</li><li>metaphorically that by which endeavour is excited and from which it goes forth<ol type='a'><li>that which gives occasion and supplies matter for an undertaking, the incentive</li><li>the resources we avail ourselves of in attempting or performing anything</li></ol></li></ol>","xlit":"aphormḗ"},"G33":{"translit":"áge","lemma":"ἄγε","kjv_def":"go to","strongs_def":" properly, lead, i.e. come on","derivation":"imperative of G71 (ἄγω);","pron":"ag'-eh","thayer":"<ol><li>go to, come!, come now!</li></ol>","xlit":"áge"},"G114":{"kjv_def":"cast off, despise, disannul, frustrate, bring to nought, reject","lemma":"ἀθετέω","translit":"athetéō","derivation":"from a compound of G1 (Α) (as a negative particle) and a derivative of G5087 (τίθημι);","strongs_def":" to set aside, i.e. (by implication) to disesteem, neutralize or violate","pron":"ath-et-eh'-o","pos":"Verb","thayer":"<ol><li>to do away with, to set aside, disregard</li><li>to thwart the efficacy of anything, nullify, make void, frustrate</li><li>to reject, to refuse, to slight</li></ol>","xlit":"athetéō"},"G3162":{"kjv_def":"sword","lemma":"μάχαιρα","translit":"máchaira","derivation":"probably feminine of a presumed derivative of G3163 (μάχη);","strongs_def":" a knife, i.e. dirk; figuratively, war, judicial punishment","pron":"makh'-ahee-rah","pos":"Noun Feminine","thayer":"<ol><li>a large knife, used for killing animals and cutting up flesh</li><li>a small sword, as distinguished from a large sword<ol type='a'><li>curved sword, for a cutting stroke</li><li>a straight sword, for thrusting</li></ol></li></ol>","xlit":"máchaira"},"G3778":{"derivation":"from the article G3588 (ὁ) and G846 (αὐτός);","strongs_def":" the he (she or it), i.e. this or that (often with article repeated)","kjv_def":"he (it was that), hereof, it, she, such as, the same, these, they, this (man, same, woman), which, who","lemma":"οὗτος","translit":"hoûtos","pron":"hoo'-tos","thayer":"<ol><li>this, these, etc.</li></ol>","xlit":"hoûtos"},"G1108":{"derivation":"from G1097 (γινώσκω);","strongs_def":" knowing (the act), i.e. (by implication) knowledge","kjv_def":"knowledge, science","lemma":"γνῶσις","translit":"gnōsis","pron":"gno'-sis","pos":"Noun Feminine","thayer":"<ol><li>knowledge signifies in general intelligence, understanding<ol type='a'><li>the general knowledge of Christian religion</li><li>the deeper more perfect and enlarged knowledge of this religion, such as belongs to the more advanced</li><li>especially of things lawful and unlawful for Christians</li><li>moral wisdom, such as is seen in right living</li></ol></li></ol>","xlit":"gnōsis"},"G1590":{"derivation":"from G1537 (ἐκ) and G3089 (λύω);","strongs_def":" to relax (literally or figuratively)","kjv_def":"faint","lemma":"ἐκλύω","translit":"eklýō","pron":"ek-loo'-o","pos":"Verb","thayer":"<ol><li>to loose, unloose, to set free</li><li>to dissolve, metaphorically, to weaken, relax, exhaust<ol type='a'><li>to have one's strength relaxed, to be enfeebled through exhaustion, to grow weak, grow weary, be tired out</li><li>to despond, become faint hearted</li></ol></li></ol>","xlit":"eklýō"},"G2606":{"strongs_def":"to laugh down, i.e. deride","translit":"katageláō","lemma":"καταγελάω","kjv_def":"laugh to scorn","pron":"kat-ag-el-ah'-o","pos":"Verb","thayer":"<ol><li>to deride</li></ol>","xlit":"katageláō"},"G4888":{"derivation":"from G4862 (σύν) and G1392 (δοξάζω);","strongs_def":" to exalt to dignity in company (i.e. similarly) with","kjv_def":"glorify together","lemma":"συνδοξάζω","translit":"syndoxázō","pron":"soon-dox-ad'-zo","pos":"Verb","thayer":"<ol><li>to approve together, to join in approving</li><li>to glorify together</li></ol>","xlit":"syndoxázō"},"G4946":{"derivation":"plural of uncertain derivation;","strongs_def":" Syracuse, the capital of Sicily","kjv_def":"Syracuse","lemma":"Συράκουσαι","translit":"Syrákousai","pron":"soo-rak'-oo-sahee","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Syracuse = \"a Syrian hearing\"</p><ol><li>a large maritime city of Sicily, having an excellent harbour and surrounded by a 14 mile (23 km) wall</li></ol>","xlit":"Syrákousai"},"G626":{"derivation":"middle voice from a compound of G575 (ἀπό) and G3056 (λόγος);","strongs_def":" to give an account (legal plea) of oneself, i.e. exculpate (self)","kjv_def":"answer (for self), make defence, excuse (self), speak for self","lemma":"ἀπολογέομαι","translit":"apologéomai","pron":"ap-ol-og-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to defend one's self, make one's defence</li><li>to defend a person or a thing</li><li>to give a full account of<ol type='a'><li>to calculate or consider well</li></ol></li></ol>","xlit":"apologéomai"},"G2830":{"strongs_def":" a surge of the sea (literally or figuratively)","derivation":"from (to billow or dash over);","lemma":"κλύδων","translit":"klýdōn","kjv_def":"raging, wave","pron":"kloo'-dohn","pos":"Noun Masculine","thayer":"<ol><li>a dashing or surging wave, a surge, a violent agitation of the sea</li></ol>","xlit":"klýdōn"},"G477":{"kjv_def":"opposition","lemma":"ἀντίθεσις","translit":"antíthesis","derivation":"from a compound of G473 (ἀντί) and G5087 (τίθημι);","strongs_def":" opposition, i.e. a conflict (of theories)","pron":"an-tith'-es-is","pos":"Noun Feminine","thayer":"<ol><li>opposition, that which is opposed</li></ol>","xlit":"antíthesis"},"G4976":{"kjv_def":"fashion","translit":"schēma","lemma":"σχῆμα","derivation":"from the alternate of G2192 (ἔχω);","strongs_def":" a figure (as a mode or circumstance), i.e. (by implication) external condition","pron":"skhay'-mah","pos":"Noun Neuter","thayer":"<ol><li>the habitus, as comprising everything in a person which strikes the senses, the figure, bearing, discourse, actions, manner of life etc.</li></ol>","xlit":"schēma"},"G1858":{"lemma":"ἑορτάζω","translit":"heortázō","kjv_def":"keep the feast","strongs_def":" to observe a festival","derivation":"from G1859 (ἑορτή);","pron":"heh-or-tad'-zo","pos":"Verb","thayer":"<ol><li>to keep a feast day, celebrate a feast</li></ol>","xlit":"heortázō"},"G5553":{"kjv_def":"gold","lemma":"χρυσίον","translit":"chrysíon","derivation":"diminutive of G5557 (χρυσός);","strongs_def":" a golden article, i.e. gold plating, ornament, or coin","pron":"khroo-see'-on","pos":"Noun Neuter","thayer":"<ol><li>gold, both that which lies imbedded in the earth and is dug out of it</li><li>that which has been smelted and wrought<ol type='a'><li>of a gold coin</li><li>of golden ornaments</li><li>of precious things made of gold</li></ol></li></ol>","xlit":"chrysíon"},"G4234":{"lemma":"πρᾶξις","translit":"prâxis","kjv_def":"deed, office, work","strongs_def":" practice, i.e. (concretely) an act; by extension, a function","derivation":"from G4238 (πράσσω);","pron":"prax'-is","pos":"Noun Feminine","thayer":"<ol><li>a doing, a mode of acting, a deal, a transaction<ol type='a'><li>the doings of the apostles</li><li>in a bad sense, wicked deed, crime, wicked doings (our practices, i.e. trickery)</li></ol><li>a thing to be done, business</li></ol>","xlit":"prâxis"},"G795":{"translit":"astochéō","lemma":"ἀστοχέω","kjv_def":"err, swerve","strongs_def":" to miss the mark, i.e. (figuratively) deviate from truth","derivation":"from a compound of G1 (Α) (as a negative particle) and (an aim);","pron":"as-tokh-eh'-o","pos":"Verb","thayer":"<ol><li>to deviate from, miss (the mark)</li></ol>","xlit":"astochéō"},"G4202":{"translit":"porneía","lemma":"πορνεία","kjv_def":"fornication","strongs_def":" harlotry (including adultery and incest); figuratively, idolatry","derivation":"from G4203 (πορνεύω);","pron":"por-ni'-ah","pos":"Noun Feminine","thayer":"<ol><li>illicit sexual intercourse<ol type='a'><li>adultery, fornication, homosexuality, lesbianism, intercourse with animals etc.</li><li>sexual intercourse with close relatives; Lev. 18</li><li>sexual intercourse with a divorced man or woman; <a class='bible' href='#b41.10.11'>Mar 10:11</a>,<a class='bible' href='#b41.10.12'>Mar 10:12</a></li></ol><li>metaphorically the worship of idols<ol type='a'><li>of the defilement of idolatry, as incurred by eating the sacrifices offered to idols</li></ol></li></ol>","xlit":"porneía"},"G4724":{"translit":"stéllō","lemma":"στέλλω","kjv_def":"avoid, withdraw self","strongs_def":" properly, to set fast (\"stall\"), i.e. (figuratively) to repress (reflexively, abstain from associating with)","derivation":"probably strengthened from the base of G2476 (ἵστημι);","pron":"stel'-lo","pos":"Verb","thayer":"<ol><li>to set, place, set in order, arrange<ol type='a'><li>to fit out, to prepare, equip</li><li>to prepare one's self, to fit out for one's self</li><li>to fit out for one's own use</li><li>to prepare one's self, to fit out for one's self</li><li>to fit out for one's own use<ol><li>arranging, providing for this, etc.</li></ol></li></ol><li>to bring together, contract, shorten<ol type='a'><li>to diminish, check, cause to cease</li><li>to cease to exist</li><li>to remove one's self, withdraw one's self, to depart</li><li>to abstain from familiar intercourse with one</li></ol></li></ol>","xlit":"stéllō"},"G1034":{"kjv_def":"meat","translit":"brṓsimos","lemma":"βρώσιμος","derivation":"from G1035 (βρῶσις);","strongs_def":" eatable","pron":"bro'-sim-os","pos":"Adjective","thayer":"<ol><li>eatable</li></ol>","xlit":"brṓsimos"},"G1057":{"derivation":"from G1056 (Γαλιλαία);","strongs_def":" Galilean or belonging to Galilea","kjv_def":"Galilean, of Galilee","translit":"Galilaîos","lemma":"Γαλιλαῖος","pron":"gal-ee-lah'-yos","pos":"Adjective","thayer":"<ol><li>a native of Galilee</li></ol>","xlit":"Galilaîos"},"G919":{"kjv_def":"Barjesus","lemma":"Βαριησοῦς","translit":"Bariēsoûs","derivation":"of Chaldee origin (H01247 and H03091);","strongs_def":" son of Jesus (or Joshua); Bar-jesus, an Israelite","pron":"bar-ee-ay-sooce'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barjesus = \"son of Jesus\"</p><ol><li>a certain false prophet</li></ol>","xlit":"Bariēsoûs"},"G4548":{"strongs_def":" a plank","derivation":"of uncertain affinity;","translit":"sanís","lemma":"σανίς","kjv_def":"board","pron":"san-ece'","pos":"Noun Feminine","thayer":"<ol><li>a board, a plank</li></ol>","xlit":"sanís"},"G1532":{"translit":"eistréchō","lemma":"εἰστρέχω","kjv_def":"run in","strongs_def":" to hasten inward","derivation":"from G1519 (εἰς) and G5143 (τρέχω);","pron":"ice-trekh'-o","pos":"Verb","thayer":"<ol><li>to run in</li></ol>","xlit":"eistréchō"},"G1337":{"kjv_def":"where two seas meet","translit":"dithálassos","lemma":"διθάλασσος","derivation":"from G1364 (δίς) and G2281 (θάλασσα);","strongs_def":" having two seas, i.e. a sound with a double outlet","pron":"dee-thal'-as-sos","pos":"Adjective","thayer":"<ol><li>resembling or forming two seas: thus of the Euxine Sea</li><li>lying between two seas, i.e. washed on both sides by the sea<ol type='a'><li>an isthmus or tongue of land, the extremity of which is covered by the waves</li><li>a projecting reef or bar against which the waves dash on both sides</li></ol></li></ol>","xlit":"dithálassos"},"G713":{"kjv_def":"enough, suffice (-ient)","lemma":"ἀρκετός","translit":"arketós","derivation":"from G714 (ἀρκέω);","strongs_def":" satisfactory","pron":"ar-ket-os'","pos":"Adjective","thayer":"<ol><li>sufficient, enough</li></ol>","xlit":"arketós"},"G2789":{"kjv_def":"harp","lemma":"κιθαρίζω","translit":"kitharízō","derivation":"from G2788 (κιθάρα);","strongs_def":" to play on a lyre","pron":"kith-ar-id'-zo","pos":"Verb","thayer":"<ol><li>to play upon the harp</li></ol>","xlit":"kitharízō"},"G1465":{"translit":"enkóptō","lemma":"ἐγκόπτω","kjv_def":"hinder, be tedious unto","strongs_def":" to cut into, i.e. (figuratively) impede, detain","derivation":"from G1722 (ἐν) and G2875 (κόπτω);","pron":"eng-kop'-to","pos":"Verb","thayer":"<ol><li>to cut into, to impede one's course by cutting off his way</li><li>hinder</li></ol>","xlit":"enkóptō"},"G3338":{"kjv_def":"repent (self)","lemma":"μεταμέλλομαι","translit":"metaméllomai","derivation":"from G3326 (μετά) and the middle voice of G3199 (μέλω);","strongs_def":" to care afterwards, i.e. regret","pron":"met-am-el'-lom-ahee","pos":"Verb","thayer":"<ol><li>it is a care to one afterwards<ol type='a'><li>it repents one, to repent one's self</li></ol></li></ol>","xlit":"metaméllomai"},"G1237":{"kjv_def":"come after","translit":"diadéchomai","lemma":"διαδέχομαι","derivation":"from G1223 (διά) and G1209 (δέχομαι);","strongs_def":" to receive in turn, i.e. (figuratively) succeed to","pron":"dee-ad-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive through another, anything left or bequeathed by him, to receive in succession, receive in turn, succeed to</li></ol>","xlit":"diadéchomai"},"G4302":{"kjv_def":"foretell, tell before","translit":"prolégō","lemma":"προλέγω","derivation":"from G4253 (πρό) and G3004 (λέγω);","strongs_def":" to say beforehand, i.e. predict, forewarn","pron":"prol-eg'-o","pos":"Verb","thayer":"<ol><li>to say beforehand, to predict</li></ol>","xlit":"prolégō"},"G5188":{"strongs_def":" to make a smoke, i.e. slowly consume without flame","derivation":"apparently a primary verb;","translit":"týphō","lemma":"τύφω","kjv_def":"smoke","pron":"too'-fo","pos":"Verb","thayer":"<ol><li>to cause or emit smoke, raise a smoke</li><li>to smoke</li></ol>","xlit":"týphō"},"G4248":{"lemma":"πρηνής","translit":"prēnḗs","kjv_def":"headlong","strongs_def":" leaning (falling) forward (\"prone\"), i.e. head foremost","derivation":"from G4253 (πρό);","pron":"pray-nace'","pos":"Adjective","thayer":"<ol><li>headlong</li></ol>","xlit":"prēnḗs"},"G166":{"kjv_def":"eternal, for ever, everlasting, world (began)","translit":"aiṓnios","lemma":"αἰώνιος","derivation":"from G165 (αἰών);","strongs_def":" perpetual (also used of past time, or past and future as well)","pron":"ahee-o'-nee-os","pos":"Adjective","thayer":"<ol><li>without beginning and end, that which always has been and always will be</li><li>without beginning</li><li>without end, never to cease, everlasting</li></ol>","xlit":"aiṓnios"},"G2549":{"lemma":"κακία","translit":"kakía","kjv_def":"evil, malice(-iousness), naughtiness, wickedness","strongs_def":" badness, i.e. (subjectively) depravity, or (actively) malignity, or (passively) trouble","derivation":"from G2556 (κακός);","pron":"kak-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>malignity, malice, ill-will, desire to injure</li><li>wickedness, depravity<ol type='a'><li>wickedness that is not ashamed to break laws</li></ol><li>evil, trouble</li></ol>","xlit":"kakía"},"G4764":{"kjv_def":"delicacy","translit":"strēnos","lemma":"στρῆνος","derivation":"akin to G4731 (στερεός);","strongs_def":" a \"straining\", \"strenuousness\" or \"strength\", i.e. (figuratively) luxury (voluptuousness)","pron":"stray'-nos","pos":"Noun Neuter","thayer":"<ol><li>excessive strength which longs to break forth, over strength</li><li>luxury</li><li>eager desire</li></ol>","xlit":"strēnos"},"G2567":{"kjv_def":"teacher of good things","lemma":"καλοδιδάσκαλος","translit":"kalodidáskalos","derivation":"from G2570 (καλός) and G1320 (διδάσκαλος);","strongs_def":" a teacher of the right","pron":"kal-od-id-as'-kal-os","pos":"Adjective","thayer":"<ol><li>teaching that which is good, a teacher of goodness</li></ol>","xlit":"kalodidáskalos"},"G397":{"strongs_def":" to rear (physically or mentally)","derivation":"from G303 (ἀνά) and G5142 (τρέφω);","lemma":"ἀνατρέφω","translit":"anatréphō","kjv_def":"bring up, nourish (up)","pron":"an-at-ref'-o","pos":"Verb","thayer":"<ol><li>to nurse up, nourish up<ol type='a'><li>of young children and animals nourished to promote growth</li></ol><li>to bring up<ol type='a'><li>with the predominant idea of forming the mind</li></ol></li></ol>","xlit":"anatréphō"},"G4156":{"strongs_def":" throttled, i.e. (neuter concretely) an animal choked to death (not bled)","derivation":"from G4155 (πνίγω);","lemma":"πνικτός","translit":"pniktós","kjv_def":"strangled","pron":"pnik-tos'","pos":"Adjective","thayer":"<ol><li>suffocate, strangled<ol type='a'><li>what is strangled, i.e. an animal deprived of life without the shedding of blood</li><li>of cooking: our \"smothered\" as a culinary term</li></ol></li></ol>","xlit":"pniktós"},"G1417":{"lemma":"δύο","translit":"dýo","kjv_def":"both, twain, two","strongs_def":" \"two\"","derivation":"a primary numeral;","pron":"doo'-o","pos":"Noun","thayer":"<ol><li>the two, the twain</li></ol>","xlit":"dýo"},"G2816":{"kjv_def":"be heir, (obtain by) inherit(-ance)","lemma":"κληρονομέω","translit":"klēronoméō","derivation":"from G2818 (κληρονόμος);","strongs_def":" to be an heir to (literally or figuratively)","pron":"klay-ron-om-eh'-o","pos":"Verb","thayer":"<ol><li>to receive a lot, receive by lot<ol type='a'><li>especially to receive a part of an inheritance, receive as an inheritance, obtain by right of inheritance</li><li>to be an heir, to inherit</li></ol><li>to receive the portion assigned to one, receive an allotted portion, receive as one's own or as a possession</li><li>to become partaker of, to obtain</li></ol>","xlit":"klēronoméō"},"G4958":{"kjv_def":" short, wind up","translit":"systéllō","lemma":"συστέλλω","derivation":"from G4862 (σύν) and G4724 (στέλλω);","strongs_def":" to send (draw) together, i.e. enwrap (enshroud a corpse for burial), contract (an interval)","pron":"soos-tel'-lo","pos":"Verb","thayer":"<ol><li>to place together<ol type='a'><li>to draw together, contact<ol><li>to diminish</li><li>to shorten, abridge</li><li>the time has been drawn together into a brief compass, is shortened</li></ol><li>to roll together, wrap up, wrap around with bandages, etc., to enshroud</li></ol></li></ol>","xlit":"systéllō"},"G1352":{"strongs_def":" through which thing, i.e. consequently","derivation":"from G1223 (διά) and G3739 (ὅς);","translit":"dió","lemma":"διό","kjv_def":"for which cause, therefore, wherefore","pron":"dee-o'","pos":"Conjunction","thayer":"<ol><li>wherefore, on account off</li></ol>","xlit":"dió"},"G3074":{"strongs_def":" a wolf","derivation":"perhaps akin to the base of G3022 (λευκός) (from the whitish hair);","translit":"lýkos","lemma":"λύκος","kjv_def":"wolf","pron":"loo'-kos","pos":"Noun Masculine","thayer":"<ol><li>a wolf</li><li>metaphorically of cruel, greedy, rapacious, destructive men</li></ol>","xlit":"lýkos"},"G2030":{"strongs_def":" a looker-on","derivation":"from G1909 (ἐπί) and a presumed derivative of G3700 (ὀπτάνομαι);","translit":"epóptēs","lemma":"ἐπόπτης","kjv_def":"eye-witness","pron":"ep-op'-tace","pos":"Noun Masculine","thayer":"<ol><li>an overseer, inspector</li><li>spectator, eye witness of anything</li></ol>","xlit":"epóptēs"},"G3473":{"lemma":"μωρολογία","translit":"mōrología","kjv_def":"foolish talking","strongs_def":" silly talk, i.e. buffoonery","derivation":"from a compound of G3474 (μωρός) and G3004 (λέγω);","pron":"mo-rol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>foolish talking</li></ol>","xlit":"mōrología"},"G5132":{"derivation":"probably contracted from G5064 (τέσσαρες) and G3979 (πεζῇ);","strongs_def":" a table or stool (as being four-legged), usually for food (figuratively, a meal); also a counter for money (figuratively, a broker's office for loans at interest)","kjv_def":"bank, meat, table","translit":"trápeza","lemma":"τράπεζα","pron":"trap'-ed-zah","pos":"Noun Feminine","thayer":"<ol><li>a table<ol type='a'><li>a table on which food is placed, an eating place<ol><li>the table in the temple at Jerusalem on which the consecrated loaves were placed</li></ol><li>equiv. to the food placed upon the table<ol><li>to set a table</li><li>put food before one</li></ol><li>a banquet, feast</li></ol><li>the table or stand of a money changer, where he sits, exchanging different kinds of money for a fee (agio), and paying back with interest loans or deposits</li></ol>","xlit":"trápeza"},"G582":{"strongs_def":" an enrollment; by implication, an assessment","derivation":"from G583 (ἀπογράφω);","translit":"apographḗ","lemma":"ἀπογραφή","kjv_def":"taxing","pron":"ap-og-raf-ay'","pos":"Noun Feminine","thayer":"<ol><li>a writing off, transcript (from some pattern)</li><li>an enrolment or registration in the public records of persons together with their income and property, as the basis of a census or valuation, i.e. that it might appear how much tax should be levied upon each one</li></ol>","xlit":"apographḗ"},"G1627":{"translit":"ekphérō","lemma":"ἐκφέρω","kjv_def":"bear, bring forth, carry forth (out)","strongs_def":" to bear out (literally or figuratively)","derivation":"from G1537 (ἐκ) and G5342 (φέρω);","pron":"ek-fer'-o","pos":"Verb","thayer":"<ol><li>to carry out, to bear forth<ol type='a'><li>the dead for burial</li></ol><li>to bring, i.e. lead out</li><li>to bring forth, i.e. produce<ol type='a'><li>of the earth bearing plants</li></ol></li></ol>","xlit":"ekphérō"},"G2747":{"strongs_def":" Cenchreæ, a port of Corinth","derivation":"probably from kegchros (millet);","translit":"Kenchreaí","lemma":"Κεγχρεαί","kjv_def":"Cencrea","pron":"keng-khreh-a'-hee","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cenchrea = \"millet\"</p><ol><li>the eastern harbour of Corinth (i.e. its harbour on the Saronic Gulf) and the emporium of its trade with the Asiatic shores of the Mediterranean, as Lechaeum on the Corinthian Gulf connected it with Italy and the west</li></ol>","xlit":"Kenchreaí"},"G1475":{"lemma":"ἔδαφος","translit":"édaphos","kjv_def":"ground","strongs_def":" a basis (bottom), i.e. the soil","derivation":"from the base of G1476 (ἑδραῖος);","pron":"ed'-af-os","pos":"Noun Neuter","thayer":"<ol><li>bottom, base, ground</li></ol>","xlit":"édaphos"},"G4653":{"derivation":"from G4655 (σκότος);","strongs_def":" dimness, obscurity (literally or figuratively)","kjv_def":"dark(-ness)","translit":"skotía","lemma":"σκοτία","pron":"skot-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>darkness</li><li>the darkness due to want of light</li><li>metaphorically used of ignorance of divine things, and its associated wickedness, and the resultant misery in hell</li></ol>","xlit":"skotía"},"G3391":{"derivation":"irregular feminine of G1520 (εἷς);","strongs_def":" one or first","kjv_def":"a (certain), + agree, first, one, X other","translit":"mía","lemma":"μία","pron":"mee'-ah","pos":"Adjective","thayer":"<ol><li>only one, someone</li></ol>","xlit":"mía"},"G5530":{"kjv_def":"entreat, use","lemma":"χράομαι","translit":"chráomai","derivation":"middle voice of a primary verb (perhaps rather from G5495 (χείρ), to handle);","strongs_def":" to furnish what is needed; (give an oracle, \"graze\" (touch slightly), light upon, etc.), i.e. (by implication) to employ or (by extension) to act towards one in a given manner","pron":"khrah'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive a loan</li><li>borrow</li><li>to take for one's use, to use<ol type='a'><li>to make use of a thing</li></ol></li></ol>","xlit":"chráomai"},"G2882":{"kjv_def":"Corinth","translit":"Kórinthos","lemma":"Κόρινθος","derivation":"of uncertain derivation;","strongs_def":" Corinthus, a city of Greece","pron":"kor'-in-thos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Corinth = \"satiated\"</p><ol><li>an ancient and famous city of Greece, on the Isthmus of Corinth, and about 40 miles (65 km) west of Athens</li></ol>","xlit":"Kórinthos"},"G3932":{"kjv_def":"virginity","translit":"parthenía","lemma":"παρθενία","derivation":"from G3933 (παρθένος);","strongs_def":" maidenhood","pron":"par-then-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>virginity</li></ol>","xlit":"parthenía"},"G14":{"strongs_def":" to work good","derivation":"from G18 (ἀγαθός) and G2041 (ἔργον);","lemma":"ἀγαθοεργέω","translit":"agathoergéō","kjv_def":"do good","pron":"ag-ath-er-gheh'-o","pos":"Verb","thayer":"<ol><li>to work good, to do good, to do well, act rightly</li></ol>","xlit":"agathoergéō"},"G1874":{"derivation":"from G1909 (ἐπί) and the base of G202 (ἀκροατής);","strongs_def":" to listen (intently) to","kjv_def":"hear","lemma":"ἐπακροάομαι","translit":"epakroáomai","pron":"ep-ak-ro-ah'-om-ahee","pos":"Verb","thayer":"<ol><li>to listen to</li></ol>","xlit":"epakroáomai"},"G4680":{"derivation":"akin to (clear);","strongs_def":" wise (in a most general application)","kjv_def":"wise","lemma":"σοφός","translit":"sophós","pron":"sof-os'","pos":"Adjective","thayer":"<ol><li>wise<ol type='a'><li>skilled, expert: of artificers</li><li>wise, skilled in letters, cultivated, learned<ol><li>of the Greek philosophers and orators</li><li>of Jewish theologians</li><li>of Christian teachers</li></ol><li>forming the best plans and using the best means for their execution</li></ol></li></ol>","xlit":"sophós"},"G1979":{"strongs_def":" a provisioning, i.e. (concretely) food","derivation":"from a compound of G1909 (ἐπί) and a derivative of G4621 (σῖτος);","translit":"episitismós","lemma":"ἐπισιτισμός","kjv_def":"victuals","pron":"ep-ee-sit-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>foraging, providing food</li><li>supplies, provisions, food</li></ol>","xlit":"episitismós"},"G4684":{"strongs_def":" to be voluptuous","derivation":"from (luxury);","translit":"spataláō","lemma":"σπαταλάω","kjv_def":"live in pleasure, be wanton","pron":"spat-al-ah'-o","pos":"Verb","thayer":"<ol><li>to live luxuriously, lead a voluptuous life, (give one's self to pleasure)</li></ol>","xlit":"spataláō"},"G4528":{"translit":"Salathiḗl","lemma":"Σαλαθιήλ","kjv_def":"Salathiel","strongs_def":" Salathiel (i.e. Shealtiel), an Israelite","derivation":"of Hebrew origin (H07597);","pron":"sal-ath-ee-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Shealtiel = \"I have asked of God\"</p><ol><li>the son of Jeconiah in the genealogy of Christ</li></ol>","xlit":"Salathiḗl"},"G4583":{"derivation":"middle voice or passive from a presumed derivative of G4582 (σελήνη);","strongs_def":" to be moon-struck, i.e. crazy","kjv_def":"be a lunatic","lemma":"σεληνιάζομαι","translit":"selēniázomai","pron":"sel-ay-nee-ad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to be moon-struck or lunatic</li><li>to be epileptic<ol type='a'><li>epilepsy being supposed to return and increase with the increase of the moon. This meaning is doubtful as the Greeks knew nothing of epilepsy.</li></ol></li></ol>","xlit":"selēniázomai"},"G990":{"derivation":"from G991 (βλέπω);","strongs_def":" vision (properly concrete; by implication, abstract)","kjv_def":"seeing","lemma":"βλέμμα","translit":"blémma","pron":"blem'-mah","pos":"Noun Neuter","thayer":"<ol><li>a look, a glance</li></ol>","xlit":"blémma"},"G4995":{"lemma":"σωφρονισμός","translit":"sōphronismós","kjv_def":"sound mind","strongs_def":" discipline, i.e. self-control","derivation":"from G4994 (σωφρονίζω);","pron":"so-fron-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>an admonishing or calling to soundness of mind, to moderation and self-control</li><li>self-control, moderation</li></ol>","xlit":"sōphronismós"},"G2503":{"derivation":"of Hebrew origin (the tenth letter of the Hebrew alphabet);","strongs_def":" \"iota\", the name of the eighth letter of the Greek alphabet, put (figuratively) for a very small part of anything","kjv_def":"jot","lemma":"ἰῶτα","translit":"iōta","pron":"ee-o'-tah","pos":"Noun Neuter","thayer":"<ol><li>the Hebrew letter `, the smallest of them all<ol type='a'><li>hence equivalent to the minutest part</li></ol></li></ol>","xlit":"iōta"},"G4490":{"lemma":"ῥητῶς","translit":"rhētōs","kjv_def":"expressly","strongs_def":" out-spokenly, i.e. distinctly","derivation":"adverb from a derivative of G4483 (ῥέω);","pron":"hray-toce'","pos":"Adverb","thayer":"<ol><li>expressly, in express words</li></ol>","xlit":"rhētōs"},"G387":{"kjv_def":"trouble, turn upside down, make an uproar","lemma":"ἀναστατόω","translit":"anastatóō","derivation":"from a derivative of G450 (ἀνίστημι) (in the sense of removal);","strongs_def":" properly, to drive out of home, i.e. (by implication) to disturb (literally or figuratively)","pron":"an-as-tat-o'-o","pos":"Verb","thayer":"<ol><li>to stir up, excite, unsettle<ol type='a'><li>to excite tumults and seditions in the state</li><li>to upset, unsettle, minds by disseminating religious error</li></ol></li></ol>","xlit":"anastatóō"},"G5550":{"derivation":"of uncertain derivation;","strongs_def":" a space of time (in general, and thus properly distinguished from G2540 (καιρός), which designates a fixed or special occasion; and from G165 (αἰών), which denotes a particular period) or interval; by extension, an individual opportunity; by implication, delay","kjv_def":"+ years old, season, space, (X often-)time(-s), (a) while","lemma":"χρόνος","translit":"chrónos","pron":"khron'-os","pos":"Noun Masculine","thayer":"<ol><li>time either long or short</li></ol>","xlit":"chrónos"},"G3751":{"lemma":"ὀσφῦς","translit":"osphŷs","kjv_def":"loin","strongs_def":" the loin (externally), i.e. the hip; internally (by extension) procreative power","derivation":"of uncertain affinity;","pron":"os-foos'","pos":"Noun Feminine","thayer":"<ol><li>the hip (loin)<ol type='a'><li>to gird, gird about, the loins</li></ol><li>a loin, the (two) loins<ol type='a'><li>the place where the Hebrews thought the generative power (semen) resided</li></ol></li></ol>","xlit":"osphŷs"},"G4545":{"kjv_def":"Samuel","translit":"Samouḗl","lemma":"Σαμουήλ","derivation":"of Hebrew origin (H08050);","strongs_def":" Samuel (i.e. Shemuel), an Israelite","pron":"sam-oo-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Samuel = \"his name is of God\"</p><ol><li>the son of Elkanah and Hannah, the last of the judges, a distinguished prophet, and a founder of the prophetic order, he gave the Jews there first kings, Saul, David</li></ol>","xlit":"Samouḗl"},"G594":{"strongs_def":" acceptance","derivation":"from G588 (ἀποδέχομαι);","lemma":"ἀποδοχή","translit":"apodochḗ","kjv_def":"acceptation","pron":"ap-od-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>reception, admission, acceptance, approbation</li></ol>","xlit":"apodochḗ"},"G3630":{"strongs_def":" a tippler","derivation":"from G3631 (οἶνος) and a derivative of the alternate of G4095 (πίνω);","lemma":"οἰνοπότης","translit":"oinopótēs","kjv_def":"winebibber","pron":"oy-nop-ot'-ace","pos":"Noun Masculine","thayer":"<ol><li>a winebibber, given to wine, a wino</li></ol>","xlit":"oinopótēs"},"G1127":{"kjv_def":"be vigilant, wake, (be) watch(-ful)","translit":"grēgoreúō","lemma":"γρηγορεύω","derivation":"from G1453 (ἐγείρω);","strongs_def":" to keep awake, i.e. watch (literally or figuratively)","pron":"gray-gor-yoo'-o","pos":"Verb","thayer":"<ol><li>to watch</li><li>metaphorically give strict attention to, be cautious, active<ol type='a'><li>to take heed lest through remission and indolence some destructive calamity suddenly overtake one</li></ol></li></ol>","xlit":"grēgoreúō"},"G4743":{"translit":"stigmḗ","lemma":"στιγμή","kjv_def":"moment","strongs_def":" a point of time, i.e. an instant","derivation":"feminine of G4742 (στίγμα);","pron":"stig-may'","pos":"Noun Feminine","thayer":"<ol><li>an instant (i.e. a moment) of time</li></ol>","xlit":"stigmḗ"},"G2715":{"translit":"katexousiázō","lemma":"κατεξουσιάζω","kjv_def":"exercise authority","strongs_def":" to have (wield) full privilege over","derivation":"from G2596 (κατά) and G1850 (ἐξουσιάζω);","pron":"kat-ex-oo-see-ad'-zo","pos":"Verb","thayer":"<ol><li>to exercise authority, wield power</li></ol>","xlit":"katexousiázō"},"G2478":{"translit":"ischyrós","lemma":"ἰσχυρός","kjv_def":"boisterous, mighty(-ier), powerful, strong(-er, man), valiant","strongs_def":" forcible (literally or figuratively)","derivation":"from G2479 (ἰσχύς);","pron":"is-khoo-ros'","pos":"Adjective","thayer":"<ol><li>strong, mighty<ol type='a'><li>of living beings<ol><li>strong either in body or in mind</li><li>of one who has strength of soul to sustain the attacks of Satan, strong and therefore exhibiting many excellences</li></ol><li>on inanimate things<ol><li>strong, violent, forcibly uttered, firm, sure</li></ol></li></ol></li></ol>","xlit":"ischyrós"},"G4795":{"kjv_def":"chance","lemma":"συγκυρία","translit":"synkyría","derivation":"from a comparative of G4862 (σύν) and (to light or happen;","strongs_def":" from the base of G2962 (κύριος)); concurrence, i.e. accident","pron":"soong-koo-ree'-ah","pos":"Feminine Neuter","thayer":"<ol><li>accident, by chance</li></ol>","xlit":"synkyría"},"G3745":{"strongs_def":" as (much, great, long, etc.) as","derivation":"by reduplication from G3739 (ὅς);","translit":"hósos","lemma":"ὅσος","kjv_def":"all (that), as (long, many, much) (as), how great (many, much), (in-)asmuch as, so many as, that (ever), the more, those things, what (great, -soever), wheresoever, wherewithsoever, which, X while, who(-soever)","pron":"hos'-os","thayer":"<ol><li>as great as, as far as, how much, how many, whoever</li></ol>","xlit":"hósos"},"G551":{"kjv_def":"not to be tempted","translit":"apeírastos","lemma":"ἀπείραστος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G3987 (πειράω);","strongs_def":" untried, i.e. not temptable","pron":"ap-i'-ras-tos","pos":"Adjective","thayer":"<ol><li>that can not be tempted by evil, not liable to temptation to sin</li></ol>","xlit":"apeírastos"},"G5497":{"strongs_def":" a hand-leader, i.e. personal conductor (of a blind person)","derivation":"from G5495 (χείρ) and a reduplicated form of G71 (ἄγω);","lemma":"χειραγωγός","translit":"cheiragōgós","kjv_def":"some to lead by the hand","pron":"khi-rag-o-gos'","pos":"Noun Masculine","thayer":"<ol><li>leading one by the hand</li></ol>","xlit":"cheiragōgós"},"G3371":{"strongs_def":" no further","derivation":"from G3361 (μή) and G2089 (ἔτι);","translit":"mēkéti","lemma":"μηκέτι","kjv_def":"any longer, (not) henceforth, hereafter, no henceforward (longer, more, soon), not any more","pron":"may-ket'-ee","pos":"Adverb","thayer":"<ol><li>no longer, no more, not hereafter</li></ol>","xlit":"mēkéti"},"G3905":{"translit":"parateínō","lemma":"παρατείνω","kjv_def":"continue","strongs_def":" to extend along, i.e. prolong (in point of time)","derivation":"from G3844 (παρά) and teino (to stretch);","pron":"par-at-i'-no","pos":"Verb","thayer":"<ol><li>to extend beside, to stretch out lengthwise, to extend</li><li>to prolong</li></ol>","xlit":"parateínō"},"G2199":{"lemma":"Ζεβεδαῖος","translit":"Zebedaîos","kjv_def":"Zebedee","strongs_def":" Zebedæus, an Israelite","derivation":"of Hebrew origin (compare H02067);","pron":"dzeb-ed-ah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Zebedee = \"my gift\"</p><ol><li>a fisherman of Galilee, the father of the apostles James the Great and John, and the husband of Salome</li></ol>","xlit":"Zebedaîos"},"G2344":{"kjv_def":"treasure","lemma":"θησαυρός","translit":"thēsaurós","derivation":"from G5087 (τίθημι);","strongs_def":" a deposit, i.e. wealth (literally or figuratively)","pron":"thay-sow-ros'","pos":"Noun Masculine","thayer":"<ol><li>the place in which good and precious things are collected and laid up<ol type='a'><li>a casket, coffer, or other receptacle, in which valuables are kept</li><li>a treasury</li><li>storehouse, repository, magazine</li></ol><li>the things laid up in a treasury, collected treasures</li></ol>","xlit":"thēsaurós"},"G1682":{"derivation":"of Chaldean origin (H0426 with pronominal suffix) my God","kjv_def":"Eloi","lemma":"ἐλοΐ","translit":"eloḯ","pron":"el-o-ee'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eloi = \"my God\"</p><ol><li>Aramaic for the phrase \"my God\"</li></ol>","xlit":"eloḯ"},"G2541":{"lemma":"Καῖσαρ","translit":"Kaîsar","kjv_def":"Cæsar","strongs_def":" Cæsar, a title of the Roman emperor","derivation":"of Latin origin;","pron":"kah'-ee-sar","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Caesar = \"severed\"</p><ol><li>the surname of Julius Caesar, which adopted by Octavius Augustus and his successors afterwards became a title, and was appropriated by the Roman emperors as part of their title</li></ol>","xlit":"Kaîsar"},"G3861":{"strongs_def":" contrary to expectation, i.e. extraordinary (\"paradox\")","derivation":"from G3844 (παρά) and G1391 (δόξα) (in the sense of seeming);","lemma":"παράδοξος","translit":"parádoxos","kjv_def":"strange","pron":"par-ad'-ox-os","pos":"Adjective","thayer":"<ol><li>unexpected, uncommon, incredible, wonderful</li></ol>","xlit":"parádoxos"},"G700":{"derivation":"probably from G142 (αἴρω) (through the idea of exciting emotion);","strongs_def":" to be agreeable (or by implication, to seek to be so)","kjv_def":"please","translit":"aréskō","lemma":"ἀρέσκω","pron":"ar-es'-ko","pos":"Verb","thayer":"<ol><li>to please</li><li>to strive to please<ol type='a'><li>to accommodate one's self to the opinions desires and interests of others</li></ol></li></ol>","xlit":"aréskō"},"G3568":{"derivation":"a primary particle of present time;","strongs_def":" \"now\" (as adverb of date, a transition or emphasis); also as noun or adjective present or immediate","kjv_def":"henceforth, + hereafter, of late, soon, present, this (time)","translit":"nŷn","lemma":"νῦν","pron":"noon","pos":"Adverb","thayer":"<ol><li>at this time, the present, now</li></ol>","xlit":"nŷn"},"G2336":{"derivation":"from G5087 (τίθημι);","strongs_def":" a receptacle, i.e. scabbard","kjv_def":"sheath","translit":"thḗkē","lemma":"θήκη","pron":"thay'-kay","pos":"Noun Feminine","thayer":"<ol><li>that which a thing is put or laid away, a receptacle, repository, chest, box<ol type='a'><li>used of the sheath of a sword</li></ol></li></ol>","xlit":"thḗkē"},"G1005":{"strongs_def":" the north (properly, wind)","derivation":"of uncertain derivation;","lemma":"βοῤῥᾶς","translit":"borrhâs","kjv_def":"north","pron":"bor-hras'","pos":"Noun Masculine","thayer":"<ol><li>Boreas, the north-north-east wind</li><li>the north</li></ol>","xlit":"borrhâs"},"G1565":{"derivation":"from G1563 (ἐκεῖ);","strongs_def":" that one (or (neuter) thing); often intensified by the article prefixed","kjv_def":"he, it, the other (same), selfsame, that (same, very), X their, X them, they, this, those","lemma":"ἐκεῖνος","translit":"ekeînos","pron":"ek-i'-nos","thayer":"<ol><li>he, she it, etc.</li></ol>","xlit":"ekeînos"},"G5470":{"kjv_def":"brass","translit":"chálkeos","lemma":"χάλκεος","derivation":"from G5475 (χαλκός);","strongs_def":" coppery","pron":"khal'-keh-os","pos":"Adjective","thayer":"<ol><li>brazen, made of brass</li></ol>","xlit":"chálkeos"},"G4899":{"kjv_def":"elected together with","lemma":"συνεκλεκτός","translit":"syneklektós","derivation":"from a compound of G4862 (σύν) and G1586 (ἐκλέγομαι);","strongs_def":" chosen in company with, i.e. co-elect (fellow Christian)","pron":"soon-ek-lek-tos'","pos":"Adjective","thayer":"<ol><li>elected or chosen (by God to eternal life) together with</li></ol>","xlit":"syneklektós"},"G4052":{"strongs_def":" to superabound (in quantity or quality), be in excess, be superfluous; also (transitively) to cause to superabound or excel","derivation":"from G4053 (περισσός);","lemma":"περισσεύω","translit":"perisseúō","kjv_def":"(make, more) abound, (have, have more) abundance (be more) abundant, be the better, enough and to spare, exceed, excel, increase, be left, redound, remain (over and above)","pron":"per-is-syoo'-o","pos":"Verb","thayer":"<ol><li>to exceed a fixed number of measure, to be left over and above a certain number or measure<ol type='a'><li>to be over, to remain</li><li>to exist or be at hand in abundance<ol><li>to be great (abundant)</li><li>a thing which comes in abundance, or overflows unto one, something falls to the lot of one in large measure</li><li>to redound unto, turn out abundantly for, a thing</li></ol><li>to abound, overflow<ol><li>to be abundantly furnished with, to have in abundance, abound in (a thing), to be in affluence</li><li>to be pre-eminent, to excel</li><li>to excel more than, exceed</li></ol></li></ol><li>to make to abound<ol type='a'><li>to furnish one richly so that he has abundance</li><li>to make abundant or excellent</li></ol></li></ol>","xlit":"perisseúō"},"G1396":{"strongs_def":" to be a slave-driver, i.e. to enslave (figuratively, subdue)","derivation":"from a presumed compound of G1401 (δοῦλος) and G71 (ἄγω);","translit":"doulagōgéō","lemma":"δουλαγωγέω","kjv_def":"bring into subjection","pron":"doo-lag-ogue-eh'-o","pos":"Verb","thayer":"<ol><li>to lead away into slavery, claim as one's slave</li><li>to make a slave and to treat as a slave, i.e. with severity, subject to stern and rigid discipline</li></ol>","xlit":"doulagōgéō"},"G1654":{"strongs_def":" compassionateness, i.e. (as exercised towards the poor) beneficence, or (concretely) a benefaction","derivation":"from G1656 (ἔλεος);","lemma":"ἐλεημοσύνη","translit":"eleēmosýnē","kjv_def":"alms(-deeds)","pron":"el-eh-ay-mos-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>mercy, pity<ol type='a'><li>especially as exhibited in giving alms, charity</li></ol><li>the benefaction itself, a donation to the poor, alms</li></ol>","xlit":"eleēmosýnē"},"G2553":{"kjv_def":"be afflicted, endure afflictions (hardness), suffer trouble","translit":"kakopathéō","lemma":"κακοπαθέω","derivation":"from the same as G2552 (κακοπάθεια);","strongs_def":" to undergo hardship","pron":"kak-op-ath-eh'-o","pos":"Verb","thayer":"<ol><li>to suffer (endure) evils (hardships, troubles)</li><li>to be afflicted</li></ol>","xlit":"kakopathéō"},"G5591":{"kjv_def":"natural, sensual","lemma":"ψυχικός","translit":"psychikós","derivation":"from G5590 (ψυχή);","strongs_def":" sensitive, i.e. animate (in distinction on the one hand from G4152 (πνευματικός), which is the higher or renovated nature; and on the other from G5446 (φυσικός), which is the lower or bestial nature)","pron":"psoo-khee-kos'","pos":"Adjective","thayer":"<ol><li>of or belonging to breath<ol type='a'><li>having the nature and characteristics of the breath<ol><li>the principal of animal life, which men have in common with the brutes</li></ol><li>governed by breath<ol><li>the sensuous nature with its subjection to appetite and passion</li></ol></li></ol></li></ol>","xlit":"psychikós"},"G2152":{"kjv_def":"devout, godly","lemma":"εὐσεβής","translit":"eusebḗs","derivation":"from G2095 (εὖ) and G4576 (σέβομαι);","strongs_def":" well-reverent, i.e. pious","pron":"yoo-seb-ace'","pos":"Adjective","thayer":"<ol><li>pious, dutiful</li></ol>","xlit":"eusebḗs"},"G2784":{"strongs_def":" to herald (as a public crier), especially divine truth (the gospel)","derivation":"of uncertain affinity;","translit":"kērýssō","lemma":"κηρύσσω","kjv_def":"preacher(-er), proclaim, publish","pron":"kay-roos'-so","pos":"Verb","thayer":"<ol><li>to be a herald, to officiate as a herald<ol type='a'><li>to proclaim after the manner of a herald</li><li>always with the suggestion of formality, gravity and an authority which must be listened to and obeyed</li></ol><li>to publish, proclaim openly: something which has been done</li><li>used of the public proclamation of the gospel and matters pertaining to it, made by John the Baptist, by Jesus, by the apostles and other Christian teachers</li></ol>","xlit":"kērýssō"},"G4420":{"kjv_def":"wing","translit":"ptéryx","lemma":"πτέρυξ","derivation":"from a derivative of G4072 (πέτομαι) (meaning a feather);","strongs_def":" a wing","pron":"pter'-oox","pos":"Noun Feminine","thayer":"<ol><li>a wing: of birds</li></ol>","xlit":"ptéryx"},"G324":{"derivation":"from G303 (ἀνά) and G1209 (δέχομαι);","strongs_def":" to entertain (as a guest)","kjv_def":"receive","lemma":"ἀναδέχομαι","translit":"anadéchomai","pron":"an-ad-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to take up, take upon's self, undertake, assume</li><li>to receive, entertain anyone hospitably</li></ol>","xlit":"anadéchomai"},"G5049":{"strongs_def":" completely, i.e. (of hope) without wavering","derivation":"adverb from G5046 (τέλειος);","lemma":"τελείως","translit":"teleíōs","kjv_def":"to the end","pron":"tel-i'-oce","pos":"Adverb","thayer":"<ol><li>perfectly, completely</li></ol>","xlit":"teleíōs"},"G1937":{"kjv_def":"covet, desire, would fain, lust (after)","lemma":"ἐπιθυμέω","translit":"epithyméō","derivation":"from G1909 (ἐπί) and G2372 (θυμός);","strongs_def":" to set the heart upon, i.e. long for (rightfully or otherwise)","pron":"ep-ee-thoo-meh'-o","pos":"Verb","thayer":"<ol><li>to turn upon a thing</li><li>to have a desire for, long for, to desire</li><li>to lust after, covet<ol type='a'><li>of those who seek things forbidden</li></ol></li></ol>","xlit":"epithyméō"},"G3382":{"strongs_def":" a thigh","derivation":"perhaps a primary word;","lemma":"μηρός","translit":"mērós","kjv_def":"thigh","pron":"may-ros'","pos":"Noun Masculine","thayer":"<ol><li>thigh</li></ol>","xlit":"mērós"},"G1399":{"derivation":"feminine of G1401 (δοῦλος);","strongs_def":" a female slave (involuntarily or voluntarily)","kjv_def":"handmaid(-en)","translit":"doúlē","lemma":"δούλη","pron":"doo'-lay","pos":"Noun Feminine","thayer":"<ol><li>a female slave, bondmaid, handmaid</li></ol>","xlit":"doúlē"},"G3110":{"lemma":"Μακεδών","translit":"Makedṓn","kjv_def":"of Macedonia, Macedonian","strongs_def":" a Macedon (Macedonian), i.e. inhabitant of Macedonia","derivation":"of uncertain derivation;","pron":"mak-ed'-ohn","pos":"Noun Masculine","thayer":"<ol><li>a Macedonian</li></ol>","xlit":"Makedṓn"},"G15":{"kjv_def":"(when) do good (well)","translit":"agathopoiéō","lemma":"ἀγαθοποιέω","derivation":"from G17 (ἀγαθοποιός);","strongs_def":" to be a well-doer (as a favor or a duty)","pron":"ag-ath-op-oy-eh'-o","pos":"Verb","thayer":"<ol><li>to do good, do something which profits others<ol type='a'><li>to be a good help to someone</li><li>to do someone a favour</li><li>to benefit</li></ol><li>to do well, do right</li></ol>","xlit":"agathopoiéō"},"G2188":{"derivation":"of Chaldee origin (H06606);","strongs_def":" be opened!","kjv_def":"Ephphatha","lemma":"ἐφφαθά","translit":"ephphathá","pron":"ef-fath-ah'","thayer":"<ol><li>be thou opened<ol type='a'><li>receive the power of hearing, the ears of the deaf and the eyes of the blind being considered as closed</li></ol></li></ol>","xlit":"ephphathá"},"G5499":{"lemma":"χειροποίητος","translit":"cheiropoíētos","kjv_def":"made by (make with) hands","strongs_def":" manufactured, i.e. of human construction","derivation":"from G5495 (χείρ) and a derivative of G4160 (ποιέω);","pron":"khi-rop-oy'-ay-tos","pos":"Adjective","thayer":"<ol><li>made by the hands i.e the skill of men<ol type='a'><li>of temples</li><li>of circumcision</li><li>of idols</li></ol></li></ol>","xlit":"cheiropoíētos"},"G843":{"kjv_def":"condemned of self","translit":"autokatákritos","lemma":"αὐτοκατάκριτος","derivation":"from G846 (αὐτός) and a derivative or G2632 (κατακρίνω);","strongs_def":" self-condemned","pron":"ow-tok-at-ak'-ree-tos","pos":"Adjective","thayer":"<ol><li>self-condemned</li></ol>","xlit":"autokatákritos"},"G2235":{"translit":"ḗdē","lemma":"ἤδη","kjv_def":"already, (even) now (already), by this time","strongs_def":" even now","derivation":"apparently from G2228 (ἤ) (or possibly G2229 (ἦ)) and G1211 (δή);","pron":"ay'-day","pos":"Adverb","thayer":"<ol><li>now, already</li></ol>","xlit":"ḗdē"},"G2793":{"derivation":"from G2794 (κίνδυνος);","strongs_def":" to undergo peril","kjv_def":"be in danger, be (stand) in jeopardy","lemma":"κινδυνεύω","translit":"kindyneúō","pron":"kin-doon-yoo'-o","pos":"Verb","thayer":"<ol><li>to be in jeopardy, to be in danger, to put in peril</li></ol>","xlit":"kindyneúō"},"G1294":{"derivation":"from G1223 (διά) and G4762 (στρέφω);","strongs_def":" to distort, i.e. (figuratively) misinterpret, or (morally) corrupt","kjv_def":"perverse(-rt), turn away","lemma":"διαστρέφω","translit":"diastréphō","pron":"dee-as-tref'-o","pos":"Verb","thayer":"<ol><li>to distort, turn aside<ol type='a'><li>to oppose, plot against the saving purposes and plans of God</li></ol><li>to turn aside from the right path, to pervert, corrupt</li></ol>","xlit":"diastréphō"},"G2280":{"kjv_def":"Thaddæus","lemma":"Θαδδαῖος","translit":"Thaddaîos","derivation":"of uncertain origin;","strongs_def":" Thaddæus, one of the Apostles","pron":"thad-dah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Thaddaeus = \"large hearted, courageous\"</p><ol><li>one of the twelve apostles. From a comparison with the catalogue of apostles in <a class='bible' href='#b42.6.16'>Luk 6:16</a>, and <a class='bible' href='#b44.1.13'>Act 1:13</a>, is seems that Judas, Lebbaeus and Thaddaeus were the same person, and the writer of the book of Jude.</li></ol>","xlit":"Thaddaîos"},"G3023":{"derivation":"a primary word;","strongs_def":" a \"lion\"","kjv_def":"lion","lemma":"λέων","translit":"léōn","pron":"leh-ohn'","pos":"Noun Masculine","thayer":"<ol><li>a lion</li><li>a brave and mighty hero</li></ol>","xlit":"léōn"},"G3611":{"kjv_def":"dwell","lemma":"οἰκέω","translit":"oikéō","derivation":"from G3624 (οἶκος);","strongs_def":" to occupy a house, i.e. reside (figuratively, inhabit, remain, inhere); by implication, to cohabit","pron":"oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell in</li></ol>","xlit":"oikéō"},"G2721":{"derivation":"from G2596 (κατά) and G2186 (ἐφίστημι);","strongs_def":" to stand over against, i.e. rush upon (assault)","kjv_def":"make insurrection against","translit":"katephístēmi","lemma":"κατεφίστημι","pron":"kat-ef-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to set up against</li></ol>","xlit":"katephístēmi"},"G5156":{"lemma":"τρόμος","translit":"trómos","kjv_def":"+ tremble(-ing)","strongs_def":" a \"trembling\", i.e. quaking with fear","derivation":"from G5141 (τρέμω);","pron":"trom'-os","pos":"Noun Masculine","thayer":"<ol><li>a trembling or quaking with fear</li><li>with fear and trembling, used to describe the anxiety of one who distrusts his ability completely to meet all requirements, but religiously does his utmost to fulfil his duty</li></ol>","xlit":"trómos"},"G1472":{"strongs_def":" to rub in (oil), i.e. besmear","derivation":"from G1722 (ἐν) and G5548 (χρίω);","translit":"enchríō","lemma":"ἐγχρίω","kjv_def":"anoint","pron":"eng-khree'-o","pos":"Verb","thayer":"<ol><li>to rub in, besmirch, anoint</li><li>to anoint one's self</li></ol>","xlit":"enchríō"},"G357":{"strongs_def":" to estimate, i.e. (figuratively) contemplate","derivation":"middle voice from G356 (ἀναλογία);","lemma":"ἀναλογίζομαι","translit":"analogízomai","kjv_def":"consider","pron":"an-al-og-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to think over, consider, ponder</li></ol>","xlit":"analogízomai"},"G4640":{"strongs_def":" to jump, i.e. sympathetically move (as the quickening of a fetus)","derivation":"akin to (to skip);","translit":"skirtáō","lemma":"σκιρτάω","kjv_def":"leap (for joy)","pron":"skeer-tah'-o","pos":"Verb","thayer":"<ol><li>to leap</li></ol>","xlit":"skirtáō"},"G1541":{"derivation":"from G1540 (ἑκατόν) and G2094 (ἔτος);","strongs_def":" centenarian","kjv_def":"hundred years old","translit":"hekatontaétēs","lemma":"ἑκατονταέτης","pron":"hek-at-on-tah-et'-ace","pos":"Adjective","thayer":"<ol><li>centenarian, a hundred years old</li></ol>","xlit":"hekatontaétēs"},"G494":{"strongs_def":" Antipatris, a place in Palestine","derivation":"from the same as G493 (Ἀντίπας);","translit":"Antipatrís","lemma":"Ἀντιπατρίς","kjv_def":"Antipatris","pron":"an-tip-at-rece'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Antipatris = \"for forefather\"</p><ol><li>a city situated between Joppa and Caesarea, in a very fertile region, not far from the coast; rebuilt by Herod the Great and named Antipatris in honour of his father Antipater</li></ol>","xlit":"Antipatrís"},"G272":{"derivation":"from G1 (Α) (as a negative particle) and G3199 (μέλω);","strongs_def":" to be careless of","kjv_def":"make light of, neglect, be negligent, no regard","translit":"ameléō","lemma":"ἀμελέω","pron":"am-el-eh'-o","pos":"Verb","thayer":"<ol><li>to be careless of, to neglect</li></ol>","xlit":"ameléō"},"G32":{"translit":"ángelos","lemma":"ἄγγελος","kjv_def":"angel, messenger","strongs_def":" compare G34 (ἀγέλη)) (to bring tidings); a messenger; especially an \"angel\"; by implication, a pastor","derivation":"from (probably derived from G71 (ἄγω);","pron":"ang'-el-os","pos":"Noun Masculine","thayer":"<ol><li>a messenger, envoy, one who is sent, an angel, a messenger from God</li></ol>","xlit":"ángelos"},"G2815":{"kjv_def":"Clement","lemma":"Κλήμης","translit":"Klḗmēs","derivation":"of Latin origin;","strongs_def":" merciful; Clemes (i.e. Clemens), a Christian","pron":"klay'-mace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Clement = \"mild, merciful\"</p><ol><li>a companion of Paul and apparently a member of the church of Philippi. According to tradition, he is identical with that Clement who was bishop of Rome towards the close of the first century.</li></ol>","xlit":"Klḗmēs"},"G1434":{"kjv_def":"gift","translit":"dṓrēma","lemma":"δώρημα","derivation":"from G1433 (δωρέομαι);","strongs_def":" a bestowment","pron":"do'-ray-mah","pos":"Noun Neuter","thayer":"<ol><li>a gift, bounty, benefaction</li></ol>","xlit":"dṓrēma"},"G4075":{"derivation":"from G4073 (πέτρα) and G1491 (εἶδος);","strongs_def":" rock-like, i.e. rocky","kjv_def":"stony","translit":"petrṓdēs","lemma":"πετρώδης","pron":"pet-ro'-dace","pos":"Adjective","thayer":"<ol><li>rocky, stony<ol type='a'><li>of a ground full of rocks</li></ol></li></ol>","xlit":"petrṓdēs"},"G3501":{"kjv_def":"new, young","translit":"néos","lemma":"νέος","derivation":"including the comparative ; a primary word;","strongs_def":" \"new\", i.e. (of persons) youthful, or (of things) fresh; figuratively, regenerate","pron":"neh'-os","pos":"Adjective","thayer":"<ol><li>recently born, young, youthful</li><li>new</li></ol>","xlit":"néos"},"G2257":{"kjv_def":"our (company), us, we","lemma":"ἡμῶν","translit":"hēmōn","derivation":"genitive case plural of G1473 (ἐγώ);","strongs_def":" of (or from) us","pron":"hay-mone'","thayer":"<ol><li>our, we, us</li></ol>","xlit":"hēmōn"},"G5191":{"derivation":"from G5192 (ὑάκινθος);","strongs_def":" \"hyacinthine\" or \"jacinthine\", i.e. deep blue","kjv_def":"jacinth","translit":"hyakínthinos","lemma":"ὑακίνθινος","pron":"hoo-ak-in'-thee-nos","pos":"Adjective","thayer":"<ol><li>hyacinth, of the colour of hyacinth<ol type='a'><li>of a red colour bordering on black</li></ol></li></ol>","xlit":"hyakínthinos"},"G1983":{"lemma":"ἐπισκοπέω","translit":"episkopéō","kjv_def":"look diligently, take the oversight","strongs_def":" to oversee; by implication, to beware","derivation":"from G1909 (ἐπί) and G4648 (σκοπέω);","pron":"ep-ee-skop-eh'-o","pos":"Verb","thayer":"<ol><li>to look upon, inspect, oversee, look after, care for<ol type='a'><li>of the care of the church which rested upon the elders</li><li>to look carefully, beware</li></ol></li></ol>","xlit":"episkopéō"},"G2752":{"lemma":"κέλευμα","translit":"kéleuma","kjv_def":"shout","strongs_def":" a cry of incitement","derivation":"from G2753 (κελεύω);","pron":"kel'-yoo-mah","pos":"Noun Neuter","thayer":"<ol><li>an order, command, spec. a stimulating cry, either that by which animals are roused and urged on by man, as horses by charioteers, hounds by hunters, etc., or that by which a signal is given to men, e.g. to rowers by the master of a ship, to soldiers by a commander (with a loud summons, a trumpet call)</li></ol>","xlit":"kéleuma"},"G3150":{"derivation":"from G3151 (ματαιολόγος);","strongs_def":" random talk, i.e. babble","kjv_def":"vain jangling","lemma":"ματαιολογία","translit":"mataiología","pron":"mat-ah-yol-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>vain talking, empty talk</li></ol>","xlit":"mataiología"},"G3062":{"derivation":"masculine plural of a derivative of G3007 (λείπω);","strongs_def":" remaining ones","kjv_def":"other, which remain, remnant, residue, rest","lemma":"λοιποί","translit":"loipoí","pron":"loy-poy'","pos":"Adverb","thayer":"<ol><li>remaining, the rest<ol type='a'><li>the rest of any number or class under consideration</li><li>with a certain distinction and contrast, the rest, who are not of a specific class or number</li><li>the rest of the things that remain</li></ol></li></ol>","xlit":"loipoí"},"G604":{"kjv_def":"reconcile","translit":"apokatallássō","lemma":"ἀποκαταλλάσσω","derivation":"from G575 (ἀπό) and G2644 (καταλλάσσω);","strongs_def":" to reconcile fully","pron":"ap-ok-at-al-las'-so","pos":"Verb","thayer":"<ol><li>to reconcile completely</li><li>to reconcile back again</li><li>bring back a former state of harmony</li></ol>","xlit":"apokatallássō"},"G2236":{"kjv_def":"most (very) gladly","translit":"hḗdista","lemma":"ἥδιστα","derivation":"neuter plural of the superlative of the same as G2234 (ἡδέως);","strongs_def":" with great pleasure","pron":"hay'-dis-tah","pos":"Adverb Neuter","thayer":"<ol><li>most gladly</li></ol>","xlit":"hḗdista"},"G5275":{"kjv_def":"be left","lemma":"ὑπολείπω","translit":"hypoleípō","derivation":"from G5295 (ὑποτρέχω) and G3007 (λείπω);","strongs_def":" to leave under (behind), i.e. (passively) to remain (survive)","pron":"hoop-ol-i'-po","pos":"Verb","thayer":"<ol><li>to leave behind</li><li>to be left behind, left remaining<ol type='a'><li>of a survivor</li></ol></li></ol>","xlit":"hypoleípō"},"G2513":{"derivation":"of uncertain affinity;","strongs_def":" clean (literally or figuratively)","kjv_def":"clean, clear, pure","lemma":"καθαρός","translit":"katharós","pron":"kath-ar-os'","pos":"Adjective","thayer":"<ol><li>clean, pure<ol type='a'><li>physically<ol><li>purified by fire</li><li>in a similitude, like a vine cleansed by pruning and so fitted to bear fruit</li></ol><li>in a levitical sense<ol><li>clean, the use of which is not forbidden, imparts no uncleanness</li></ol><li>ethically<ol><li>free from corrupt desire, from sin and guilt</li><li>free from every admixture of what is false, sincere genuine</li><li>blameless, innocent</li><li>unstained with the guilt of anything</li></ol></li></ol></li></ol>","xlit":"katharós"},"G5325":{"derivation":"from a derivative of G5324 (φαντάζω);","strongs_def":" (properly abstract) a (vain) show (\"fantasy\")","kjv_def":"pomp","lemma":"φαντασία","translit":"phantasía","pron":"fan-tas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>show, showy appearance, display, pomp</li></ol>","xlit":"phantasía"},"G4114":{"kjv_def":"breadth","lemma":"πλάτος","translit":"plátos","derivation":"from G4116 (πλατύς);","strongs_def":" width","pron":"plat'-os","pos":"Noun Neuter","thayer":"<ol><li>breadth<ol type='a'><li>suggesting great extent</li></ol></li></ol>","xlit":"plátos"},"G1067":{"derivation":"of Hebrew origin (H01516 and H02011);","strongs_def":" valley of (the son of) Hinnom; ge-henna (or Ge-Hinnom), a valley of Jerusalem, used (figuratively) as a name for the place (or state) of everlasting punishment","kjv_def":"hell","translit":"géenna","lemma":"γέεννα","pron":"gheh'-en-nah","pos":"Noun Feminine","thayer":"<ol><li>Hell is the place of the future punishment call \"Gehenna\" or \"Gehenna of fire\" . This was originally the valley of Hinnom, south of Jerusalem, where the filth and dead animals of the city were cast out and burned; a fit symbol of the wicked and their future destruction.</li></ol>","xlit":"géenna"},"G1043":{"derivation":"of Hebrew origin (H01403);","strongs_def":" Gabriel, an archangel","kjv_def":"Gabriel","lemma":"Γαβριήλ","translit":"Gabriḗl","pron":"gab-ree-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Gabriel = \"man of God\"</p><ol><li>one of the angel princes or chiefs of the angels</li></ol>","xlit":"Gabriḗl"},"G1264":{"strongs_def":" to fight fiercely (in altercation)","derivation":"from G1223 (διά) and G3164 (μάχομαι);","lemma":"διαμάχομαι","translit":"diamáchomai","kjv_def":"strive","pron":"dee-am-akh'-om-ahee","pos":"Verb","thayer":"<ol><li>to fight out</li><li>contend fiercely</li></ol>","xlit":"diamáchomai"},"G1023":{"strongs_def":" the arm, i.e. (figuratively) strength","derivation":"properly, comparative of G1024 (βραχύς), but apparently in the sense of (to wield);","lemma":"βραχίων","translit":"brachíōn","kjv_def":"arm","pron":"brakh-ee'-own","pos":"Noun Masculine","thayer":"<ol><li>the arm<ol type='a'><li>the arm of God is a Hebrew idiom for the might and</li></ol></li></ol>","xlit":"brachíōn"},"G3617":{"translit":"oikodespótēs","lemma":"οἰκοδεσπότης","kjv_def":"goodman (of the house), householder, master of the house","strongs_def":" the head of a family","derivation":"from G3624 (οἶκος) and G1203 (δεσπότης);","pron":"oy-kod-es-pot'-ace","pos":"Noun Masculine","thayer":"<ol><li>master of the house, householder</li></ol>","xlit":"oikodespótēs"},"G5170":{"kjv_def":"Tryphena","lemma":"Τρύφαινα","translit":"Trýphaina","derivation":"from G5172 (τρυφή);","strongs_def":" luxurious; Tryphæna, a Christian woman","pron":"troo'-fahee-nah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tryphena = \"luxurious\"</p><ol><li>a Christian woman</li></ol>","xlit":"Trýphaina"},"G5228":{"lemma":"ὑπέρ","translit":"hypér","kjv_def":"(+ exceeding, abundantly) above, in (on) behalf of, beyond, by, + very chiefest, concerning, exceeding (above, -ly), for, + very highly, more (than), of, over, on the part of, for sake of, in stead, than, to(-ward), very","strongs_def":" \"over\", i.e. (with the genitive case) of place, above, beyond, across, or causal, for the sake of, instead, regarding; with the accusative case superior to, more than","derivation":"a primary preposition;","pron":"hoop-er'","pos":"Preposition","thayer":"<ol><li>in behalf of, for the sake of</li><li>over, beyond, more than</li><li>more, beyond, over</li></ol>","xlit":"hypér"},"G869":{"kjv_def":"suddenly","lemma":"ἄφνω","translit":"áphnō","derivation":"adverb from G852 (ἀφανής) (contraction);","strongs_def":" unawares, i.e. unexpectedly","pron":"af'-no","pos":"Adverb","thayer":"<ol><li>suddenly</li></ol>","xlit":"áphnō"},"G4337":{"kjv_def":"(give) attend(-ance, -ance at, -ance to, unto), beware, be given to, give (take) heed (to unto); have regard","lemma":"προσέχω","translit":"proséchō","derivation":"from G4314 (πρός) and G2192 (ἔχω);","strongs_def":" (figuratively) to hold the mind (3563 implied) towards, i.e. pay attention to, be cautious about, apply oneself to, adhere to","pron":"pros-ekh'-o","pos":"Verb","thayer":"<ol><li>to bring to, bring near<ol type='a'><li>to bring a ship to land, and simply to touch at, put in</li></ol><li>to turn the mind to, attend to be attentive<ol type='a'><li>to a person or a thing: of caring for, providing for</li></ol><li>to attend to one's self, i.e. to give heed to one's self<ol type='a'><li>give attention to, take heed</li></ol><li>to apply one's self to, attach one's self to, hold or cleave to a person or a thing<ol type='a'><li>to be given or addicted to</li><li>to devote thought and effort to</li></ol></li></ol>","xlit":"proséchō"},"G3931":{"kjv_def":"comfort","lemma":"παρηγορία","translit":"parēgoría","derivation":"from a compound of G3844 (παρά) and a derivative of G58 (ἀγορά) (meaning to harangue an assembly);","strongs_def":" an address alongside, i.e. (specially), consolation","pron":"par-ay-gor-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>addressing, address<ol type='a'><li>exhortation</li><li>comfort, solace, relief, alleviation, consolation</li></ol></li></ol>","xlit":"parēgoría"},"G2748":{"translit":"Kedrṓn","lemma":"Κεδρών","kjv_def":"Cedron","strongs_def":" Cedron (i.e. Kidron), a brook near Jerusalem","derivation":"of Hebrew origin (H06939);","pron":"ked-rone'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cedron or Kidron = \"turbid\"</p><ol><li>the name of a winter torrent, rising near Jerusalem and flowing down through a valley of Kidron, having the Mount of Olives on the east, into the Dead Sea</li></ol>","xlit":"Kedrṓn"},"G3886":{"lemma":"παραλύω","translit":"paralýō","kjv_def":"feeble, sick of the (taken with) palsy","strongs_def":" to loosen beside, i.e. relax (perfect passive participle, paralyzed or enfeebled)","derivation":"from G3844 (παρά) and G3089 (λύω);","pron":"par-al-oo'-o","pos":"Verb","thayer":"<ol><li>to loose on one side or from the side</li><li>to loose or part things placed side by side</li><li>to loosen, dissolve</li><li>to weaken, enfeeble</li><li>suffering from the relaxing of the nerves, unstrung, weak of limb</li><li>tottering, weakened, feeble knees</li></ol>","xlit":"paralýō"},"G1878":{"lemma":"ἐπαναμιμνήσκω","translit":"epanamimnḗskō","kjv_def":"put in mind","strongs_def":" to remind of","derivation":"from G1909 (ἐπί) and G363 (ἀναμιμνήσκω);","pron":"ep-an-ah-mim-nace'-ko","pos":"Verb","thayer":"<ol><li>to recall to mind again</li><li>reminding one</li></ol>","xlit":"epanamimnḗskō"},"G2232":{"derivation":"from G2233 (ἡγέομαι);","strongs_def":" a leader, i.e. chief person (or figuratively, place) of a province","kjv_def":"governor, prince, ruler","translit":"hēgemṓn","lemma":"ἡγεμών","pron":"hayg-em-ohn'","pos":"Noun Masculine","thayer":"<ol><li>a leader of any kind, a guide, ruler, prefect, president, chief, general, commander, sovereign<ol type='a'><li>a \"legatus Caesaris\" , an officer administering a province in the name and with the authority of the Roman emperor<ol><li>the governor of a province</li></ol><li>a procurator, an officer who was attached to a proconsul or a proprietor and had charge of the imperial revenues<ol><li>in causes relating to these revenues he administered justice. In the smaller provinces also, which were so to speak appendages of the greater, he discharged the functions of governor of the province; and such was the relation of the procurator of Judaea to the governor of Syria.</li></ol><li>first, leading, chief<ol><li>of a principal town as the capital of the region</li></ol></li></ol></li></ol>","xlit":"hēgemṓn"},"G3120":{"kjv_def":"effeminate, soft","lemma":"μαλακός","translit":"malakós","derivation":"of uncertain affinity;","strongs_def":" soft, i.e. fine (clothing); figuratively, a catamite","pron":"mal-ak-os'","pos":"Adjective","thayer":"<ol><li>soft, soft to the touch</li><li>metaphorically in a bad sense<ol type='a'><li>effeminate<ol><li>of a catamite</li><li>of a boy kept for homosexual relations with a man</li><li>of a male who submits his body to unnatural lewdness</li><li>of a male prostitute</li></ol></li></ol></li></ol>","xlit":"malakós"},"G2465":{"translit":"isángelos","lemma":"ἰσάγγελος","kjv_def":"equal unto the angels","strongs_def":" like an angel, i.e. angelic","derivation":"from G2470 (ἴσος) and G32 (ἄγγελος);","pron":"ee-sang'-el-los","pos":"Adjective","thayer":"<ol><li>like the angels</li></ol>","xlit":"isángelos"},"G1692":{"derivation":"of uncertain affinity;","strongs_def":" to vomit","kjv_def":"(will) spue","translit":"eméō","lemma":"ἐμέω","pron":"em-eh'-o","pos":"Verb","thayer":"<ol><li>to vomit, vomit forth, throw up</li></ol>","xlit":"eméō"},"G916":{"lemma":"βαρέω","translit":"baréō","kjv_def":"burden, charge, heavy, press","strongs_def":" to weigh down (figuratively)","derivation":"from G926 (βαρύς);","pron":"bar-eh'-o","pos":"Verb","thayer":"<ol><li>to burden, weigh down, depress</li></ol>","xlit":"baréō"},"G3962":{"strongs_def":" a \"father\" (literally or figuratively, near or more remote)","derivation":"apparently a primary word;","translit":"patḗr","lemma":"πατήρ","kjv_def":"father, parent","pron":"pat-ayr'","pos":"Noun Masculine","thayer":"<ol><li>generator or male ancestor<ol type='a'><li>either the nearest ancestor: father of the corporeal nature, natural fathers, both parents</li><li>a more remote ancestor, the founder of a family or tribe, progenitor of a people, forefather: so Abraham is called, Jacob and David<ol><li>fathers, i.e. ancestors, forefathers, founders of a nation</li></ol><li>one advanced in years, a senior</li></ol><li>metaphorically<ol type='a'><li>the originator and transmitter of anything<ol><li>the authors of a family or society of persons animated by the same spirit as himself</li><li>one who has infused his own spirit into others, who actuates and governs their minds</li></ol><li>one who stands in a father's place and looks after another in a paternal way</li><li>a title of honour<ol><li>teachers, as those to whom pupils trace back the knowledge and training they have received</li><li>the members of the Sanhedrin, whose prerogative it was by virtue of the wisdom and experience in which they excelled, to take charge of the interests of others</li></ol></li></ol><li>God is called the Father<ol type='a'><li>of the stars, the heavenly luminaries, because he is their creator, upholder, ruler</li><li>of all rational and intelligent beings, whether angels or men, because he is their creator, preserver, guardian and protector<ol><li>of spiritual beings and of all men</li></ol><li>of Christians, as those who through Christ have been exalted to a specially close and intimate relationship with God, and who no longer dread him as a stern judge of sinners, but revere him as their reconciled and loving Father</li><li>the Father of Jesus Christ, as one whom God has united to himself in the closest bond of love and intimacy, made acquainted with his purposes, appointed to explain and carry out among men the plan of salvation, and made to share also in his own divine nature<ol><li>by Jesus Christ himself</li><li>by the apostles</li></ol></li></ol></li></ol>","xlit":"patḗr"},"G5005":{"derivation":"from the base of G5007 (τάλαντον) and a derivative of the base of G3984 (πεῖρα);","strongs_def":" enduring trial, i.e. miserable","kjv_def":"wretched","lemma":"ταλαίπωρος","translit":"talaípōros","pron":"tal-ah'-ee-po-ros","pos":"Adjective","thayer":"<ol><li>enduring toils and troubles</li><li>afflicted, wretched</li></ol>","xlit":"talaípōros"},"G955":{"translit":"Belíal","lemma":"Βελίαλ","kjv_def":"Belial","strongs_def":" worthlessness; Belial, as an epithet of Satan","derivation":"of Hebrew origin (H01100);","pron":"bel-ee'-al","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Belial = \"worthless or wicked\"</p><ol><li>a name of Satan</li></ol>","xlit":"Belíal"},"G4979":{"strongs_def":" of uncertain derivation); a rushlet, i.e. grass-withe or tie (generally)","derivation":"diminutive of (a rush or flag-plant;","lemma":"σχοινίον","translit":"schoiníon","kjv_def":"small cord, rope","pron":"skhoy-nee'-on","pos":"Noun Neuter","thayer":"<ol><li>a cord or rope made of rushes</li><li>a rope</li></ol>","xlit":"schoiníon"},"G2758":{"translit":"kenóō","lemma":"κενόω","kjv_def":"make (of none effect, of no reputation, void), be in vain","strongs_def":" to make empty, i.e. (figuratively) to abase, neutralize, falsify","derivation":"from G2756 (κενός);","pron":"ken-o'-o","pos":"Verb","thayer":"<ol><li>to empty, make empty<ol type='a'><li>of Christ, he laid aside equality with or the form of God</li></ol><li>to make void<ol type='a'><li>deprive of force, render vain, useless, of no effect</li></ol><li>to make void<ol type='a'><li>cause a thing to be seen to be empty, hollow, false</li></ol></li></ol>","xlit":"kenóō"},"G143":{"kjv_def":"perceive","translit":"aisthánomai","lemma":"αἰσθάνομαι","derivation":"of uncertain derivation;","strongs_def":" to apprehend (properly, by the senses)","pron":"ahee-sthan'-om-ahee","pos":"Verb","thayer":"<ol><li>to perceive<ol type='a'><li>by the bodily senses</li><li>with the mind, understand</li></ol></li></ol>","xlit":"aisthánomai"},"G3374":{"derivation":"from (a sheep);","strongs_def":" a sheep-skin","kjv_def":"sheepskin","lemma":"μηλωτή","translit":"mēlōtḗ","pron":"may-lo-tay'","pos":"Noun Feminine","thayer":"<ol><li>a sheepskin</li><li>an outer robe or mantle since most mantles were made of skins</li></ol>","xlit":"mēlōtḗ"},"G7":{"lemma":"Ἀβιά","translit":"Abiá","kjv_def":"Abia","strongs_def":" Abijah, the name of two Israelites","derivation":"of Hebrew origin (H029);","pron":"ab-ee-ah'","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Abijah = \"my father is Jah (Jehovah)\"</p><ol><li>a priest, the head of a priestly family from whom when David divided the priests into 24 classes, Abia was the 8th order</li><li>son and successor to Rehoboam on the throne of Judah</li></ol>","xlit":"Abiá"},"G5111":{"strongs_def":" probably itself from the base of G5056 (τέλος) through the idea of extreme conduct); to venture (objectively or in act; while G2292 (θαῤῥέω) is rather subjective or in feeling); by implication, to be courageous","derivation":"from (boldness;","lemma":"τολμάω","translit":"tolmáō","kjv_def":"be bold, boldly, dare, durst","pron":"tol-mah'-o","pos":"Verb","thayer":"<ol><li>not to dread or shun through fear</li><li>to bear, endure</li><li>to bring one's self to</li><li>to be bold</li><li>bear one's self boldly, deal boldly</li></ol>","xlit":"tolmáō"},"G817":{"derivation":"a particle probably akin to G427 (ἄνευ);","strongs_def":" aloof, i.e. apart from (literally or figuratively)","kjv_def":"in the absence of, without","translit":"áter","lemma":"ἄτερ","pron":"at'-er","pos":"Preposition","thayer":"<ol><li>without, apart from</li></ol>","xlit":"áter"},"G4950":{"derivation":"from G4951 (σύρω);","strongs_def":" a shoal (from the sand drawn thither by the waves), i.e. the Syrtis Major or great bay on the north coast of Africa","kjv_def":"quicksands","translit":"sýrtis","lemma":"σύρτις","pron":"soor'-tis","pos":"Noun Feminine","thayer":"<ol><li>Syrtis, the name of two places in the African or Libyan Sea between Carthage and Cyrenaicia, full of shallows and sandbanks, and therefore destructive to ships; the western Syrtis, between the islands Cercina and Meninx (or the promontories of Zeitha and Brachodes), was called Syris minor, the eastern (extending from the promontories of Cephalae on the west to that of Boreum on the east) was called Syris major; this latter must be the one referred to in <a class='bible' href='#b44.27.17'>Act 27:17</a>, for upon this the ship in which Paul was sailing might easily be cast after leaving Crete</li></ol>","xlit":"sýrtis"},"G86":{"kjv_def":"grave, hell","lemma":"ᾅδης","translit":"háidēs","derivation":"from G1 (Α) (as negative particle) and G1492 (εἴδω);","strongs_def":" properly, unseen, i.e. \"Hades\" or the place (state) of departed souls","pron":"hah'-dace","pos":"Noun Location","thayer":"<ol><li>name Hades or Pluto, the god of the lower regions</li><li>Orcus, the nether world, the realm of the dead</li><li>later use of this word: the grave, death, hell</li></ol>","xlit":"háidēs"},"G315":{"strongs_def":" to necessitate","derivation":"from G318 (ἀνάγκη);","translit":"anankázō","lemma":"ἀναγκάζω","kjv_def":"compel, constrain","pron":"an-ang-kad'-zo","pos":"Verb","thayer":"<ol><li>to necessitate, compel, drive to, constrain<ol type='a'><li>by force, threats, etc.</li><li>by permission, entreaties, etc.</li><li>by other means</li></ol></li></ol>","xlit":"anankázō"},"G4278":{"lemma":"προενάρχομαι","translit":"proenárchomai","kjv_def":"begin (before)","strongs_def":" to commence already","derivation":"from G4253 (πρό) and G1728 (ἐνάρχομαι);","pron":"pro-en-ar'-khom-ahee","pos":"Verb","thayer":"<ol><li>to make a beginning before</li></ol>","xlit":"proenárchomai"},"G4518":{"kjv_def":"sabachthani","translit":"sabachtháni","lemma":"σαβαχθάνι","derivation":"of Chaldee or (H07662 with pronominal suffix);","strongs_def":" thou hast left me; sabachthani (i.e. shebakthani), a cry of distress","pron":"sab-akh-than-ee'","thayer":"<ol><li>thou hast forsaken me</li></ol>","xlit":"sabachtháni"},"G5159":{"lemma":"τροποφορέω","translit":"tropophoréō","kjv_def":"suffer the manners","strongs_def":" to endure one's habits","derivation":"from G5158 (τρόπος) and G5409 (φορέω);","pron":"trop-of-or-eh'-o","pos":"Verb","thayer":"<ol><li>to bear one's manner, endure one's character</li></ol>","xlit":"tropophoréō"},"G1469":{"kjv_def":"make of the number","lemma":"ἐγκρίνω","translit":"enkrínō","derivation":"from G1722 (ἐν) and G2919 (κρίνω);","strongs_def":" to judge in, i.e. count among","pron":"eng-kree'-no","pos":"Verb","thayer":"<ol><li>to reckon among, judge among</li><li>to judge one worthy of being admitted to a certain class</li></ol>","xlit":"enkrínō"},"G5066":{"strongs_def":" pertaining to the fourth day","derivation":"from G5064 (τέσσαρες);","lemma":"τεταρταῖος","translit":"tetartaîos","kjv_def":"four days","pron":"tet-ar-tah'-yos","pos":"Adjective","thayer":"<ol><li>on the fourth day</li></ol>","xlit":"tetartaîos"},"G5305":{"kjv_def":"afterward, (at the) last (of all)","lemma":"ὕστερον","translit":"hýsteron","derivation":"neuter of G5306 (ὕστερος) as adverb;","strongs_def":" more lately, i.e. eventually","pron":"hoos'-ter-on","pos":"Noun Neuter","thayer":"<ol><li>latter, later, coming after, the second</li><li>afterward, after this, later, lastly</li></ol>","xlit":"hýsteron"},"G1015":{"derivation":"probably of foreign origin;","strongs_def":" a hillock","kjv_def":"hill","translit":"bounós","lemma":"βουνός","pron":"boo-nos'","pos":"Noun Masculine","thayer":"<ol><li>a hill, eminence, mound</li></ol>","xlit":"bounós"},"G5127":{"derivation":"genitive case singular masculine or neuter of G3778 (οὗτος);","strongs_def":" of (from or concerning) this (person or thing)","kjv_def":"here(-by), him, it, + such manner of, that, thence(-forth), thereabout, this, thus","translit":"toútou","lemma":"τούτου","pron":"too'-too","thayer":"<ol><li>of this one</li></ol>","xlit":"toútou"},"G580":{"strongs_def":" rejection; figuratively, loss","derivation":"from G577 (ἀποβάλλω);","lemma":"ἀποβολή","translit":"apobolḗ","kjv_def":"casting away, loss","pron":"ap-ob-ol-ay'","thayer":"<ol><li>rejection, repudiation<ol type='a'><li>to throw away from one's self, cast off, repudiate</li></ol><li>a losing, a loss</li></ol>","xlit":"apobolḗ"},"G4889":{"kjv_def":"fellowservant","translit":"sýndoulos","lemma":"σύνδουλος","derivation":"from G4862 (σύν) and G1401 (δοῦλος);","strongs_def":" a co-slave, i.e. servitor or ministrant of the same master (human or divine)","pron":"soon'-doo-los","pos":"Noun Masculine","thayer":"<ol><li>a fellow servant, one who serves the same master with another<ol type='a'><li>the associate of a servant (or slave)</li><li>one who with others serves (ministers to) a king</li><li>a colleague of one who is Christ's servant in publishing the gospel</li><li>one who with others acknowledges the same Lord, Jesus, and obeys his commands</li><li>one who with others is subject to the same divine authority in the Messianic economy<ol><li>of angels as the fellow servants of Christians</li></ol></li></ol></li></ol>","xlit":"sýndoulos"},"G3328":{"translit":"metabállō","lemma":"μεταβάλλω","kjv_def":"change mind","strongs_def":" to throw over, i.e. (middle voice figuratively) to turn about in opinion","derivation":"from G3326 (μετά) and G906 (βάλλω);","pron":"met-ab-al'-lo","pos":"Verb","thayer":"<ol><li>to turn around, to turn about</li><li>to turn one's self about, or transform one's self</li><li>to change one's opinion</li></ol>","xlit":"metabállō"},"G3709":{"kjv_def":"anger, indignation, vengeance, wrath","translit":"orgḗ","lemma":"ὀργή","derivation":"from G3713 (ὀρέγομαι);","strongs_def":" properly, desire (as a reaching forth or excitement of the mind), i.e. (by analogy), violent passion (ire, or (justifiable) abhorrence); by implication punishment","pron":"or-gay'","pos":"Noun Feminine","thayer":"<ol><li>anger, the natural disposition, temper, character</li><li>movement or agitation of the soul, impulse, desire, any violent emotion, but especially anger</li><li>anger, wrath, indignation</li><li>anger exhibited in punishment, hence used for punishment itself<ol type='a'><li>of punishments inflicted by magistrates</li></ol></li></ol>","xlit":"orgḗ"},"G3600":{"kjv_def":"sorrow, torment","translit":"odynáō","lemma":"ὀδυνάω","derivation":"from G3601 (ὀδύνη);","strongs_def":" to grieve","pron":"od-oo-nah'-o","pos":"Verb","thayer":"<ol><li>to cause intense pain</li><li>to be in anguish, be tormented</li><li>to torment or distress one's self</li></ol>","xlit":"odynáō"},"G420":{"derivation":"from G430 (ἀνέχομαι) and G2556 (κακός);","strongs_def":" enduring of ill, i.e. forbearing","kjv_def":"patient","lemma":"ἀνεξίκακος","translit":"anexíkakos","pron":"an-ex-ik'-ak-os","pos":"Adjective","thayer":"<ol><li>patient of ills and wrongs, forbearing</li></ol>","xlit":"anexíkakos"},"G101":{"kjv_def":"be impossible","lemma":"ἀδυνατέω","translit":"adynatéō","derivation":"from G102 (ἀδύνατος);","strongs_def":" to be unable, i.e. (passively) impossible","pron":"ad-oo-nat-eh'-o","pos":"Verb","thayer":"<ol><li>impossible<ol type='a'><li>not to have strength, power, or ability, to be weak</li><li>can not be done, to be impossible</li></ol></li></ol>","xlit":"adynatéō"},"G1837":{"kjv_def":"sound forth","lemma":"ἐξηχέομαι","translit":"exēchéomai","derivation":"middle voice from G1537 (ἐκ) and G2278 (ἠχέω);","strongs_def":" to \"echo\" forth, i.e. resound (be generally reported)","pron":"ex-ay-kheh'-om-ahee","pos":"Verb","thayer":"<ol><li>to sound forth, emit, sound, resound</li></ol>","xlit":"exēchéomai"},"G3161":{"kjv_def":"Mattathias","translit":"Mattathías","lemma":"Ματταθίας","derivation":"of Hebrew origin (H04993);","strongs_def":" Mattathias (i.e. Mattithjah), an Israelite and a Christian","pron":"mat-tath-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Mattathias = \"gift of Jehovah\"</p><ol><li>the son of Amos, in the genealogy of Christ</li><li>Mattathias was the son of Semei in the genealogy of Christ</li></ol>","xlit":"Mattathías"},"G2011":{"translit":"epitropḗ","lemma":"ἐπιτροπή","kjv_def":"commission","strongs_def":" permission, i.e. (by implication) full power","derivation":"from G2010 (ἐπιτρέπω);","pron":"ep-ee-trop-ay'","pos":"Noun Feminine","thayer":"<ol><li>permission, power, commission</li></ol>","xlit":"epitropḗ"},"G480":{"strongs_def":" to lie opposite, i.e. be adverse (figuratively, repugnant) to","derivation":"from G473 (ἀντί) and G2749 (κεῖμαι);","translit":"antíkeimai","lemma":"ἀντίκειμαι","kjv_def":"adversary, be contrary, oppose","pron":"an-tik'-i-mahee","pos":"Verb","thayer":"<ol><li>to be set over against, opposite to</li><li>to oppose, be adverse to, withstand</li></ol>","xlit":"antíkeimai"},"G4821":{"kjv_def":"reign with","lemma":"συμβασιλεύω","translit":"symbasileúō","derivation":"from G4862 (σύν) and G936 (βασιλεύω);","strongs_def":" to be co-regent (figuratively)","pron":"soom-bas-il-yoo'-o","pos":"Verb","thayer":"<ol><li>to reign together</li><li>metaphorically to possess supreme honour, liberty, blessedness, with one in the kingdom of God</li></ol>","xlit":"symbasileúō"},"G1620":{"strongs_def":" to expose; figuratively, to declare","derivation":"from G1537 (ἐκ) and G5087 (τίθημι);","lemma":"ἐκτίθημι","translit":"ektíthēmi","kjv_def":"cast out, expound","pron":"ek-tith'-ay-mee","pos":"Verb","thayer":"<ol><li>to place or set out, put outside, expose</li><li>to set up, exhibit</li><li>metaphorically to set forth, declare, expound</li></ol>","xlit":"ektíthēmi"},"G1774":{"kjv_def":"dwell in","translit":"enoikéō","lemma":"ἐνοικέω","derivation":"from G1722 (ἐν) and G3611 (οἰκέω);","strongs_def":" to inhabit (figuratively)","pron":"en-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell in</li><li>metaphorically to dwell in one and influence him (for good)</li></ol>","xlit":"enoikéō"},"G4157":{"kjv_def":"breath, wind","translit":"pnoḗ","lemma":"πνοή","derivation":"from G4154 (πνέω);","strongs_def":" respiration, a breeze","pron":"pno-ay'","pos":"Noun Feminine","thayer":"<ol><li>breath, breath of life</li><li>wind</li></ol>","xlit":"pnoḗ"},"G3609":{"translit":"oikeîos","lemma":"οἰκεῖος","kjv_def":"(those) of the (his own) house(-hold)","strongs_def":" domestic, i.e. (as noun), a relative, adherent","derivation":"from G3624 (οἶκος);","pron":"oy-ki'-os","pos":"Adjective","thayer":"<ol><li>belonging to a house or family, domestic, intimate<ol type='a'><li>belonging to one's household, related by blood, kindred</li><li>belonging to the household of God</li><li>belonging, devoted to, adherents of a thing</li></ol></li></ol>","xlit":"oikeîos"},"G361":{"kjv_def":"that is without sin","translit":"anamártētos","lemma":"ἀναμάρτητος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G264 (ἁμαρτάνω);","strongs_def":" sinless","pron":"an-am-ar'-tay-tos","pos":"Adjective","thayer":"<ol><li>sinless<ol type='a'><li>of one who has not sinned</li><li>of one who cannot sin</li></ol></li></ol>","xlit":"anamártētos"},"G2480":{"lemma":"ἰσχύω","translit":"ischýō","kjv_def":"be able, avail, can do(-not), could, be good, might, prevail, be of strength, be whole, + much work","strongs_def":" to have (or exercise) force (literally or figuratively)","derivation":"from G2479 (ἰσχύς);","pron":"is-khoo'-o","pos":"Verb","thayer":"<ol><li>to be strong<ol type='a'><li>to be strong in body, to be robust, to be in sound health</li></ol><li>to have power<ol type='a'><li>to have power as shown by extraordinary deeds<ol><li>to exert, wield power, to have strength to overcome</li></ol><li>to be a force, avail</li><li>to be serviceable</li><li>to be able, can</li></ol></li></ol>","xlit":"ischýō"},"G3868":{"kjv_def":"avoid, (make) excuse, intreat, refuse, reject","translit":"paraitéomai","lemma":"παραιτέομαι","derivation":"from G3844 (παρά) and the middle voice of G154 (αἰτέω);","strongs_def":" to beg off, i.e. deprecate, decline, shun","pron":"par-ahee-teh'-om-ahee","pos":"Verb","thayer":"<ol><li>to ask along side, beg to have near one<ol type='a'><li>to obtain by entreaty</li><li>to beg from, to ask for, supplicate</li></ol><li>to avert by entreaty or seek to avert, to deprecate<ol type='a'><li>to entreat that ... not</li><li>to refuse, decline</li><li>to shun, avoid</li><li>to avert displeasure by entreaty<ol><li>to beg pardon, crave indulgence, to excuse</li><li>of one excusing himself for not accepting a wedding invitation to a feast</li></ol></li></ol></li></ol>","xlit":"paraitéomai"},"G3":{"derivation":"of Hebrew origin (H011);","strongs_def":" a destroying angel","kjv_def":"Abaddon","lemma":"Ἀβαδδών","translit":"Abaddṓn","pron":"ab-ad-dohn'","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Abaddon = \"destruction\"</p><ol><li>ruin</li><li>destruction</li><li>the place of destruction</li><li>the name of the angel-prince of the infernal regions, the minister of death and the author of havoc on the earth</li></ol>","xlit":"Abaddṓn"},"G4638":{"strongs_def":" an encampment, i.e. (figuratively) the Temple (as God's residence), the body (as a tenement for the soul)","derivation":"from G4637 (σκηνόω);","translit":"skḗnōma","lemma":"σκήνωμα","kjv_def":" tabernacle","pron":"skay'-no-mah","pos":"Noun Neuter","thayer":"<ol><li>a tent, a tabernacle<ol type='a'><li>of the temple as God's habitation</li><li>of the tabernacle of the covenant</li><li>metaphorically of the human body as the dwelling of the soul</li></ol></li></ol>","xlit":"skḗnōma"},"G5354":{"strongs_def":" to be jealous of","derivation":"from G5355 (φθόνος);","translit":"phthonéō","lemma":"φθονέω","kjv_def":"envy","pron":"fthon-eh'-o","pos":"Verb","thayer":"<ol><li>to envy</li></ol>","xlit":"phthonéō"},"G2766":{"derivation":"probably from the base of G2767 (κεράννυμι) (through the idea of mixing clay and water);","strongs_def":" earthenware, i.e. a tile (by analogy, a thin roof or awning)","kjv_def":"tiling","lemma":"κέραμος","translit":"kéramos","pron":"ker'-am-os","pos":"Noun Masculine","thayer":"<ol><li>clay, potter's earth</li><li>anything made of clay, earthen ware</li><li>a roofing tile<ol type='a'><li>the roof itself</li><li>the phrase \"through the roof\" , means through the door in the roof to which a ladder or stairway led up from the street (according to the Rabbis distinguish two ways of entering a house, \"the way through the door\" and \"the way through the roof\"</li></ol></li></ol>","xlit":"kéramos"},"G5221":{"kjv_def":"(go to) meet","translit":"hypantáō","lemma":"ὑπαντάω","derivation":"from G5259 (ὑπό) and a derivative of G473 (ἀντί);","strongs_def":" to go opposite (meet) under (quietly), i.e. to encounter, fall in with","pron":"hoop-an-tah'-o","pos":"Verb","thayer":"<ol><li>to go to meet, to meet</li><li>in military reference<ol type='a'><li>of a hostile meeting</li></ol></li></ol>","xlit":"hypantáō"},"G2354":{"kjv_def":"lament, mourn","lemma":"θρηνέω","translit":"thrēnéō","derivation":"from G2355 (θρῆνος);","strongs_def":" to bewail","pron":"thray-neh'-o","pos":"Verb","thayer":"<ol><li>to mourn, to lament<ol type='a'><li>of singers of dirges, [to wail]</li></ol><li>to bewail, deplore</li></ol>","xlit":"thrēnéō"},"G3054":{"lemma":"λογομαχέω","translit":"logomachéō","kjv_def":"strive about words","strongs_def":" to be disputatious (on trifles)","derivation":"from a compound of G3056 (λόγος) and G3164 (μάχομαι);","pron":"log-om-akh-eh'-o","pos":"Verb","thayer":"<ol><li>to contend about words</li><li>to wrangle about empty and trifling matters</li></ol>","xlit":"logomachéō"},"G4005":{"strongs_def":" fiftieth (G2250 (ἡμέρα) being implied) from Passover, i.e. the festival of \"Pentecost\"","derivation":"feminine of the ordinal of G4004 (πεντήκοντα);","translit":"pentēkostḗ","lemma":"πεντηκοστή","kjv_def":"Pentecost","pron":"pen-tay-kos-tay'","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Pentecost = \"the fiftieth day\"</p><ol><li>the second of the three great Jewish feasts, celebrated at Jerusalem yearly, the seventh week after the Passover, in grateful recognition of the completed harvest</li></ol>","xlit":"pentēkostḗ"},"G2980":{"strongs_def":" to talk, i.e. utter words","derivation":"a prolonged form of an otherwise obsolete verb;","lemma":"λαλέω","translit":"laléō","kjv_def":"preach, say, speak (after), talk, tell, utter","pron":"lal-eh'-o","pos":"Verb","thayer":"<ol><li>to utter a voice or emit a sound</li><li>to speak<ol type='a'><li>to use the tongue or the faculty of speech</li><li>to utter articulate sounds</li></ol><li>to talk</li><li>to utter, tell</li><li>to use words in order to declare one's mind and disclose one's thoughts<ol type='a'><li>to speak</li></ol></li></ol>","xlit":"laléō"},"G5264":{"kjv_def":"receive","translit":"hypodéchomai","lemma":"ὑποδέχομαι","derivation":"from G5259 (ὑπό) and G1209 (δέχομαι);","strongs_def":" to admit under one's roof, i.e. entertain hospitably","pron":"hoop-od-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive as a guest</li></ol>","xlit":"hypodéchomai"},"G2657":{"derivation":"from G2596 (κατά) and G3539 (νοιέω);","strongs_def":" to observe fully","kjv_def":"behold, consider, discover, perceive","translit":"katanoéō","lemma":"κατανοέω","pron":"kat-an-o-eh'-o","pos":"Verb","thayer":"<ol><li>to perceive, remark, observe, understand</li><li>to consider attentively, fix one's eyes or mind upon</li></ol>","xlit":"katanoéō"},"G5460":{"derivation":"from G5457 (φῶς);","strongs_def":" lustrous, i.e. transparent or well-illuminated (figuratively)","kjv_def":"bright, full of light","lemma":"φωτεινός","translit":"phōteinós","pron":"fo-ti-nos'","pos":"Adjective","thayer":"<ol><li>light<ol type='a'><li>composed of light</li><li>of a bright character</li><li>full of light</li><li>well lit</li></ol></li></ol>","xlit":"phōteinós"},"G483":{"strongs_def":" to dispute, refuse","derivation":"from G473 (ἀντί) and G3004 (λέγω);","lemma":"ἀντιλέγω","translit":"antilégō","kjv_def":"answer again, contradict, deny, gainsay(-er), speak against","pron":"an-til'-eg-o","pos":"Verb","thayer":"<ol><li>to speak against, gainsay, contradict</li><li>to oppose one's self to one, decline to obey him, declare one's self against him, refuse to have anything to do with him</li></ol>","xlit":"antilégō"},"G2282":{"lemma":"θάλπω","translit":"thálpō","kjv_def":"cherish","strongs_def":" to brood, i.e. (figuratively) to foster","derivation":"probably akin to (to warm);","pron":"thal'-po","pos":"Verb","thayer":"<ol><li>to warm, keep warm</li><li>to cherish with tender love, to foster with tender care</li></ol>","xlit":"thálpō"},"G1913":{"derivation":"from G1909 (ἐπί) and a reduplicated derivative of the base of G939 (βάσις) (compare G307 (ἀναβιβάζω));","strongs_def":" to cause to mount (an animal)","kjv_def":"set on","translit":"epibibázō","lemma":"ἐπιβιβάζω","pron":"ep-ee-bee-bad'-zo","pos":"Verb","thayer":"<ol><li>to cause to mount</li><li>to place upon</li></ol>","xlit":"epibibázō"},"G2843":{"strongs_def":" communicative, i.e. (pecuniarily) liberal","derivation":"from G2844 (κοινωνός);","translit":"koinōnikós","lemma":"κοινωνικός","kjv_def":"willing to communicate","pron":"koy-no-nee-kos'","pos":"Adjective","thayer":"<ol><li>social, sociable, ready and apt to form and maintain communion and fellowship</li><li>inclined to make others sharers in one's possessions, inclined to impart, free in giving, liberal</li></ol>","xlit":"koinōnikós"},"G550":{"translit":"apeipómēn","lemma":"ἀπειπόμην","kjv_def":"renounce","strongs_def":" to say off for oneself, i.e. disown","derivation":"reflexive past of a compound of G575 (ἀπό) and G2036 (ἔπω);","pron":"ap-i-pom'-ane","pos":"Verb","thayer":"<ol><li>to speak out, set forth, declare</li><li>to forbid</li><li>to give up, renounce</li></ol>","xlit":"apeipómēn"},"G2642":{"kjv_def":"stone","lemma":"καταλιθάζω","translit":"katalitházō","derivation":"from G2596 (κατά) and G3034 (λιθάζω);","strongs_def":" to stone down, i.e. to death","pron":"kat-al-ith-ad'-zo","pos":"Verb","thayer":"<ol><li>to overwhelm with stones, to stone</li></ol>","xlit":"katalitházō"},"G4025":{"derivation":"from G4060 (περιτίθημι);","strongs_def":" a putting all around, i.e. decorating oneself with","kjv_def":"wearing","lemma":"περίθεσις","translit":"períthesis","pron":"per-ith'-es-is","pos":"Noun Feminine","thayer":"<ol><li>the act of putting around</li><li>the adornment consisting of the golden ornaments wont to be placed around the head or the body</li></ol>","xlit":"períthesis"},"G2190":{"derivation":"from a primary (to hate);","strongs_def":" hateful (passively, odious, or actively, hostile); usually as a noun, an adversary (especially Satan)","kjv_def":"enemy, foe","lemma":"ἐχθρός","translit":"echthrós","pron":"ech-thros'","pos":"Adjective","thayer":"<ol><li>hated, odious, hateful</li><li>hostile, hating, and opposing another<ol type='a'><li>used of men as at enmity with God by their sin<ol><li>opposing (God) in the mind</li><li>a man that is hostile</li><li>a certain enemy</li><li>the hostile one</li><li>the devil who is the most bitter enemy of the divine government</li></ol></li></ol></li></ol>","xlit":"echthrós"},"G3485":{"derivation":"from a primary (to dwell);","strongs_def":" a fane, shrine, temple ","kjv_def":"shrine, temple","translit":"naós","lemma":"ναός","pron":"nah-os'","pos":"Noun Masculine","thayer":"<ol><li>used of the temple at Jerusalem, but only of the sacred edifice</li><li>any heathen temple or shrine</li><li>metaphorically the spiritual temple consisting of the saints of all ages joined together by and in Christ</li></ol>","xlit":"naós"},"G5074":{"kjv_def":"fourfooted beast","lemma":"τετράπους","translit":"tetrápous","derivation":"from G5064 (τέσσαρες) and G4228 (πούς);","strongs_def":" a quadruped","pron":"tet-rap'-ooce","pos":"Adjective","thayer":"<ol><li>a fourfooted animal</li></ol>","xlit":"tetrápous"},"G1174":{"lemma":"δεισιδαιμονέστερος","translit":"deisidaimonésteros","kjv_def":"too superstitious","strongs_def":" more religious than others","derivation":"the compound of a derivative of the base of G1169 (δειλός) and G1142 (δαίμων);","pron":"dice-ee-dahee-mon-es'-ter-os","pos":"Adjective","thayer":"<ol><li>in a good sense<ol type='a'><li>reverencing god or the gods, pious, religious</li></ol><li>in a bad sense<ol type='a'><li>superstitious</li></ol></li></ol>","xlit":"deisidaimonésteros"},"G4749":{"lemma":"στολή","translit":"stolḗ","kjv_def":"long clothing (garment), (long) robe","strongs_def":" equipment, i.e. (specially), a \"stole\" or long-fitting gown (as a mark of dignity)","derivation":"from G4724 (στέλλω);","pron":"stol-ay'","pos":"Noun Feminine","thayer":"<ol><li>an equipment</li><li>an equipment in clothes, clothing<ol type='a'><li>spec. a loose outer garment for men extending to the feet, worn by kings, priests, and persons of rank</li></ol></li></ol>","xlit":"stolḗ"},"G1482":{"kjv_def":"heathen (man)","translit":"ethnikós","lemma":"ἐθνικός","derivation":"from G1484 (ἔθνος);","strongs_def":" national (\"ethnic\"), i.e. (specially) a Gentile","pron":"eth-nee-kos'","pos":"Noun Masculine","thayer":"<ol><li>adapted to the genius or customs of a people, peculiar to a people, national</li><li>suited to the manners or language of foreigners, strange, foreign</li><li>in the NT savouring of the nature of pagans, alien to the worship of the true God, heathenish<ol type='a'><li>of the pagan, the Gentile</li></ol></li></ol>","xlit":"ethnikós"},"G4564":{"derivation":"of Hebrew origin (H08283);","strongs_def":" Sarra (i.e. Sarah), the wife of Abraham","kjv_def":"Sara, Sarah","lemma":"Σάῤῥα","translit":"Sárrha","pron":"sar'-hrah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Sarah = \"princess\"</p><ol><li>the wife of Abraham</li></ol>","xlit":"Sárrha"},"G5624":{"kjv_def":"profit(-able)","lemma":"ὠφέλιμος","translit":"ōphélimos","derivation":"from a form of G3786 (ὄφελος);","strongs_def":" helpful or serviceable, i.e. advantageous","pron":"o-fel'-ee-mos","pos":"Adjective","thayer":"<ol><li>profitable</li></ol>","xlit":"ōphélimos"},"G1204":{"translit":"deûro","lemma":"δεῦρο","kjv_def":"come (hither), hither(-to)","strongs_def":" here; used also imperative hither!; and of time, hitherto","derivation":"of uncertain affinity;","pron":"dyoo'-ro","pos":"Adverb","thayer":"<ol><li>of place<ol type='a'><li>hither to this place</li><li>in urging and calling, here! come!</li></ol><li>of time, hither to, now</li></ol>","xlit":"deûro"},"G3121":{"kjv_def":"Maleleel","lemma":"Μαλελεήλ","translit":"Maleleḗl","derivation":"of Hebrew origin (H04111);","strongs_def":" Maleleel (i.e. Mahalalel), an antediluvian","pron":"mal-el-eh-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Maleleel or Mahalaleel = \"praise of God\"</p><ol><li>the fourth in descent from Adam, son of Cainan</li></ol>","xlit":"Maleleḗl"},"G5358":{"kjv_def":"love of good men","lemma":"φιλάγαθος","translit":"philágathos","derivation":"from G5384 (φίλος) and G18 (ἀγαθός);","strongs_def":" fond to good, i.e. a promoter of virtue","pron":"fil-ag'-ath-os","pos":"Adjective","thayer":"<ol><li>loving goodness</li></ol>","xlit":"philágathos"},"G893":{"derivation":"from G1 (Α) (as a negative particle) and G5579 (ψεῦδος);","strongs_def":" veracious","kjv_def":"that cannot lie","lemma":"ἀψευδής","translit":"apseudḗs","pron":"aps-yoo-dace'","pos":"Adjective","thayer":"<ol><li>without lie, truthful</li></ol>","xlit":"apseudḗs"},"G3747":{"kjv_def":"bone","lemma":"ὀστέον","translit":"ostéon","derivation":"of uncertain affinity;","strongs_def":" a bone","pron":"os-teh'-on","pos":"Noun Neuter","thayer":"<ol><li>a bone</li></ol>","xlit":"ostéon"},"G4752":{"derivation":"from G4754 (στρατεύομαι);","strongs_def":" military service, i.e. (figuratively) the apostolic career (as one of hardship and danger)","kjv_def":"warfare","translit":"strateía","lemma":"στρατεία","pron":"strat-i'-ah","pos":"Noun Feminine","thayer":"<ol><li>an expedition, campaign, military service, warfare</li><li>metaphorically Paul likens his contest with the difficulties that oppose him in the discharge of his apostolic duties, as warfare</li></ol>","xlit":"strateía"},"G451":{"kjv_def":"Anna","lemma":"Ἄννα","translit":"Ánna","derivation":"of Hebrew origin (H02584);","strongs_def":" Anna, an Israelitess","pron":"an'-nah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Anna = \"grace\"</p><ol><li>A prophetess in Jerusalem at the time of the Lord's presentation in the Temple. She was of the tribe of Asher.</li></ol>","xlit":"Ánna"},"G372":{"derivation":"from G373 (ἀναπαύω);","strongs_def":" intermission; by implication, recreation","kjv_def":"rest","translit":"anápausis","lemma":"ἀνάπαυσις","pron":"an-ap'-ow-sis","pos":"Noun Feminine","thayer":"<ol><li>intermission, cessation of any motion, business or labour</li><li>rest, recreation</li></ol>","xlit":"anápausis"},"G777":{"derivation":"from G1 (Α) (as a negative particle) and G4621 (σῖτος);","strongs_def":" without (taking) food","kjv_def":"fasting","lemma":"ἄσιτος","translit":"ásitos","pron":"as'-ee-tos","pos":"Adjective","thayer":"<ol><li>fasting, without having eaten</li></ol>","xlit":"ásitos"},"G4385":{"derivation":"from G4253 (πρό) and (to stretch);","strongs_def":" to protend, i.e. tie prostrate (for scourging)","kjv_def":"bind","translit":"proteínō","lemma":"προτείνω","pron":"prot-i'-no","pos":"Verb","thayer":"<ol><li>to stretch forth, stretch out<ol type='a'><li>when they had stretched one out on the thongs, i.e. to receive the blows of the thongs (by tying him up to a beam or a pillar)</li></ol></li></ol>","xlit":"proteínō"},"G1943":{"derivation":"from G1909 (ἐπί) and G2572 (καλύπτω);","strongs_def":" to conceal, i.e. (figuratively) forgive","kjv_def":"cover","lemma":"ἐπικαλύπτω","translit":"epikalýptō","pron":"ep-ee-kal-oop'-to","pos":"Verb","thayer":"<ol><li>to cover over</li></ol>","xlit":"epikalýptō"},"G3539":{"translit":"noiéō","lemma":"νοιέω","kjv_def":"consider, perceive, think, understand","strongs_def":" to exercise the mind (observe), i.e. (figuratively) to comprehend, heed","derivation":"from G3563 (νοῦς);","pron":"no-eh'-o","pos":"Verb","thayer":"<ol><li>to perceive with the mind, to understand, to have understanding</li><li>to think upon, heed, ponder, consider</li></ol>","xlit":"noiéō"},"G3379":{"derivation":"from G3361 (μή) and G4218 (ποτέ);","strongs_def":" not ever; also if (or lest) ever (or perhaps)","kjv_def":"if peradventure, lest (at any time, haply), not at all, whether or not","lemma":"μήποτε","translit":"mḗpote","pron":"may'-pot-eh","pos":"Conjunction","thayer":"<ol><li>that ... not, lest, whether perhaps, whether or not, in no way, perhaps</li></ol>","xlit":"mḗpote"},"G2684":{"kjv_def":"spy out","translit":"kataskopéō","lemma":"κατασκοπέω","derivation":"from G2685 (κατάσκοπος);","strongs_def":" to be a sentinel, i.e. to inspect insidiously","pron":"kat-as-kop-eh'-o","pos":"Verb","thayer":"<ol><li>to inspect, view closely, in order to spy out and plot against</li></ol>","xlit":"kataskopéō"},"G273":{"lemma":"ἄμεμπτος","translit":"ámemptos","kjv_def":"blameless, faultless, unblamable","strongs_def":" irreproachable","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3201 (μέμφομαι);","pron":"am'-emp-tos","pos":"Adjective","thayer":"<ol><li>blameless, deserving no censure, free from fault or defect</li></ol>","xlit":"ámemptos"},"G4219":{"kjv_def":"+ how long, when","lemma":"πότε","translit":"póte","derivation":"from the base of G4226 (ποῦ) and G5037 (τέ);","strongs_def":" interrogative adverb, at what time","pron":"pot'-eh","pos":"Adverb","thayer":"<ol><li>when?, at what time?</li></ol>","xlit":"póte"},"G2774":{"strongs_def":" a principal thing, i.e. main point; specially, an amount (of money)","derivation":"neuter of a derivative of G2776 (κεφαλή);","translit":"kephálaion","lemma":"κεφάλαιον","kjv_def":"sum","pron":"kef-al'-ah-yon","pos":"Noun Neuter","thayer":"<ol><li>the chief or main point, the principal thing</li><li>the pecuniary sum total of a reckoning, amount<ol type='a'><li>the principal, capital, as distinguished from the interest</li><li>a sum of money, sum</li></ol></li></ol>","xlit":"kephálaion"},"G4596":{"derivation":"from (an Indian tribe from whom silk was procured;","strongs_def":" hence the name of the silk-worm); Seric, i.e. silken (neuter as noun, a silky fabric)","kjv_def":"silk","translit":"sērikós","lemma":"σηρικός","pron":"say-ree-kos'","pos":"Adjective","thayer":"<ol><li>made of silk</li><li>silk, i.e. the fabric, silken garments</li></ol>","xlit":"sērikós"},"G3040":{"strongs_def":" a harbor","derivation":"apparently a primary word;","translit":"limḗn","lemma":"λιμήν","kjv_def":"haven","pron":"lee-mane'","pos":"Noun Masculine","thayer":"<ol><li>a harbour, haven</li></ol>","xlit":"limḗn"},"G5051":{"lemma":"τελειωτής","translit":"teleiōtḗs","kjv_def":"finisher","strongs_def":" a completer, i.e. consummater","derivation":"from G5048 (τελειόω);","pron":"tel-i-o-tace'","pos":"Noun Masculine","thayer":"<ol><li>a perfector</li><li>one who has in his own person raised faith to its perfection and so set before us the highest example of faith</li></ol>","xlit":"teleiōtḗs"},"G5548":{"kjv_def":"anoint","lemma":"χρίω","translit":"chríō","derivation":"probably akin to G5530 (χράομαι) through the idea of contact;","strongs_def":" to smear or rub with oil, i.e. (by implication) to consecrate to an office or religious service","pron":"khree'-o","pos":"Verb","thayer":"<ol><li>to anoint<ol type='a'><li>consecrating Jesus to the Messianic office, and furnishing him with the necessary powers for its administration</li><li>enduing Christians with the gifts of the Holy Spirit</li></ol></li></ol>","xlit":"chríō"},"G1579":{"derivation":"from G1537 (ἐκ) and G2860 (κολυμβάω);","strongs_def":" to escape by swimming","kjv_def":"swim out","translit":"ekkolymbáō","lemma":"ἐκκολυμβάω","pron":"ek-kol-oom-bah'-o","pos":"Verb","thayer":"<ol><li>to swim out of</li></ol>","xlit":"ekkolymbáō"},"G2008":{"derivation":"from G1909 (ἐπί) and G5091 (τιμάω);","strongs_def":" to tax upon, i.e. censure or admonish; by implication, forbid","kjv_def":"(straitly) charge, rebuke","translit":"epitimáō","lemma":"ἐπιτιμάω","pron":"ep-ee-tee-mah'-o","pos":"Verb","thayer":"<ol><li>to show honour to, to honour</li><li>to raise the price of</li><li>to adjudge, award, in the sense of merited penalty</li><li>to tax with fault, rate, chide, rebuke, reprove, censure severely<ol type='a'><li>to admonish or charge sharply</li></ol></li></ol>","xlit":"epitimáō"},"G3448":{"strongs_def":" a young bullock","derivation":"probably strengthened for (a shoot);","lemma":"μόσχος","translit":"móschos","kjv_def":"calf","pron":"mos'-khos","pos":"Noun Masculine","thayer":"<ol><li>a tender juicy shoot<ol type='a'><li>a sprout, of a plant or tree</li></ol><li>offspring<ol type='a'><li>of men: a boy or a girl, especially if fresh and delicate</li><li>of animals: a young one</li></ol><li>a calf, a bullock, a heifer</li></ol>","xlit":"móschos"},"G414":{"lemma":"ἀνεκτότερος","translit":"anektóteros","kjv_def":"more tolerable","strongs_def":" more endurable","derivation":"comparative of a derivative of G430 (ἀνέχομαι);","pron":"an-ek-tot'-er-os","pos":"Adjective","thayer":"<ol><li>bearable, tolerable</li></ol>","xlit":"anektóteros"},"G978":{"kjv_def":"Bithynia","lemma":"Βιθυνία","translit":"Bithynía","derivation":"of uncertain derivation;","strongs_def":" Bithynia, a region of Asia","pron":"bee-thoo-nee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bithynia = \"a violent rushing\"</p><ol><li>a Roman province in Asia Minor, bounded by the Euxine Sea, the Propontis, Mysia, Phrygia, Galatia, Paphlagonia</li></ol>","xlit":"Bithynía"},"G5140":{"kjv_def":"three","lemma":"τρεῖς","translit":"treîs","derivation":"a primary (plural) number;","strongs_def":" \"three\"","pron":"trice","pos":"Noun Feminine","thayer":"<ol><li>three</li></ol>","xlit":"treîs"},"G1430":{"derivation":"from (to build);","strongs_def":" properly, an edifice, i.e. (specially) a roof","kjv_def":"housetop","lemma":"δῶμα","translit":"dōma","pron":"do'-mah","pos":"Noun Neuter","thayer":"<ol><li>a building, house</li><li>a part of a building, dining room, hall</li><li>house top, roof<ol type='a'><li>the house tops of the Orientals were (and still are) level and frequented not only for walking, but also for meditation and prayer</li></ol></li></ol>","xlit":"dōma"},"G2169":{"kjv_def":"thankfulness, (giving of) thanks(-giving)","translit":"eucharistía","lemma":"εὐχαριστία","derivation":"from G2170 (εὐχάριστος);","strongs_def":" gratitude; actively, grateful language (to God, as an act of worship)","pron":"yoo-khar-is-tee'-ah","pos":"Noun Feminine","thayer":"<ol><li>thankfulness</li><li>the giving of thanks</li></ol>","xlit":"eucharistía"},"G3869":{"kjv_def":"sit","translit":"parakathízō","lemma":"παρακαθίζω","derivation":"from G3844 (παρά) and G2523 (καθίζω);","strongs_def":" to sit down near","pron":"par-ak-ath-id'-zo","pos":"Verb","thayer":"<ol><li>to make to sit down besides</li><li>to set beside, place near</li><li>sit down beside</li></ol>","xlit":"parakathízō"},"G1594":{"kjv_def":"awake","translit":"eknḗphō","lemma":"ἐκνήφω","derivation":"from G1537 (ἐκ) and G3525 (νήφω);","strongs_def":" (figuratively) to rouse (oneself) out of stupor","pron":"ek-nay'-fo","pos":"Verb","thayer":"<ol><li>to return to one's self from drunkenness, become sober</li><li>metaphorically to return to soberness of mind</li></ol>","xlit":"eknḗphō"},"G3499":{"derivation":"from G3498 (νεκρός);","strongs_def":" to deaden, i.e. (figuratively) to subdue","kjv_def":"be dead, mortify","translit":"nekróō","lemma":"νεκρόω","pron":"nek-ro'-o","pos":"Verb","thayer":"<ol><li>to make dead, to put to death, slay</li><li>worn out<ol type='a'><li>of an impotent old man</li></ol><li>to deprive of power, destroy the strength of</li></ol>","xlit":"nekróō"},"G3970":{"strongs_def":" traditionary","derivation":"from G3962 (πατήρ) and a derivative of G3860 (παραδίδωμι) (in the sense of handing over or down);","lemma":"πατροπαράδοτος","translit":"patroparádotos","kjv_def":"received by tradition from fathers","pron":"pat-rop-ar-ad'-ot-os","pos":"Adjective","thayer":"<ol><li>handed down from one's father's or ancestors</li></ol>","xlit":"patroparádotos"},"G3365":{"strongs_def":" by no means","derivation":"adverb from a compound of G3361 (μή) and (somebody);","translit":"mēdamōs","lemma":"μηδαμῶς","kjv_def":"not so","pron":"may-dam-oce'","pos":"Adverb","thayer":"<ol><li>by no means</li></ol>","xlit":"mēdamōs"},"G3719":{"translit":"orthrízō","lemma":"ὀρθρίζω","kjv_def":"come early in the morning","strongs_def":" to use the dawn, i.e. (by implication) to repair betimes","derivation":"from G3722 (ὄρθρος);","pron":"or-thrid'-zo","pos":"Verb","thayer":"<ol><li>to rise early in the morning</li></ol>","xlit":"orthrízō"},"G1734":{"strongs_def":" eleventh","derivation":"ordinal from G1733 (ἕνδεκα);","translit":"hendékatos","lemma":"ἑνδέκατος","kjv_def":"eleventh","pron":"hen-dek'-at-os","pos":"Adjective","thayer":"<ol><li>eleventh</li></ol>","xlit":"hendékatos"},"G5018":{"derivation":"from G5019 (Ταρσός);","strongs_def":" a Tarsean, i.e. native of Tarsus","kjv_def":"of Tarsus","lemma":"Ταρσεύς","translit":"Tarseús","pron":"tar-syoos'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Tarsus = \"a flat basket\"</p><ol><li>belong to Tarsus, a native of Tarsus</li></ol>","xlit":"Tarseús"},"G4734":{"kjv_def":"Stephanas","lemma":"Στεφανᾶς","translit":"Stephanâs","derivation":"probably contraction for (crowned;","strongs_def":" from G4737 (στεφανόω)); Stephanas, a Christian","pron":"stef-an-as'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Stephanas = \"crowned\"</p><ol><li>a Christian convert of Corinth</li></ol>","xlit":"Stephanâs"},"G1063":{"strongs_def":" properly, assigning a reason (used in argument, explanation or intensification; often with other particles)","derivation":"a primary particle;","translit":"gár","lemma":"γάρ","kjv_def":"and, as, because (that), but, even, for, indeed, no doubt, seeing, then, therefore, verily, what, why, yet","pron":"gar","pos":"Conjunction","thayer":"<ol><li>for</li></ol>","xlit":"gár"},"G4644":{"lemma":"σκληροτράχηλος","translit":"sklērotráchēlos","kjv_def":"stiffnecked","strongs_def":" hardnaped, i.e. (figuratively) obstinate","derivation":"from G4642 (σκληρός) and G5137 (τράχηλος);","pron":"sklay-rot-rakh'-ay-los","pos":"Adjective","thayer":"<ol><li>stiffnecked</li><li>stubborn, headstrong, obstinate</li></ol>","xlit":"sklērotráchēlos"},"G2720":{"kjv_def":"guide, direct","translit":"kateuthýnō","lemma":"κατευθύνω","derivation":"from G2596 (κατά) and G2116 (εὐθύνω);","strongs_def":" to straighten fully, i.e. (figuratively) direct","pron":"kat-yoo-thoo'-no","pos":"Verb","thayer":"<ol><li>to make straight, guide, direct<ol type='a'><li>of the removal of the hindrances to coming to one</li></ol></li></ol>","xlit":"kateuthýnō"},"G5464":{"kjv_def":"hail","lemma":"χάλαζα","translit":"chálaza","derivation":"probably from G5465 (χαλάω);","strongs_def":" hail","pron":"khal'-ad-zah","pos":"Noun Feminine","thayer":"<ol><li>hail</li></ol>","xlit":"chálaza"},"G5466":{"lemma":"Χαλδαῖος","translit":"Chaldaîos","kjv_def":"Chaldæan","strongs_def":" a Chaldæan (i.e. Kasdi), or native or the region of the lower Euphrates","derivation":"probably of Hebrew or (H03778);","pron":"khal-dah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Chaldean = \"as clod breakers\"</p><ol><li>a Chaldean</li></ol>","xlit":"Chaldaîos"},"G1806":{"lemma":"ἐξάγω","translit":"exágō","kjv_def":"bring forth (out), fetch (lead) out","strongs_def":" to lead forth","derivation":"from G1537 (ἐκ) and G71 (ἄγω);","pron":"ex-ag'-o","pos":"Verb","thayer":"<ol><li>to lead out</li></ol>","xlit":"exágō"},"G3119":{"derivation":"from G3120 (μαλακός);","strongs_def":" softness, i.e. enervation (debility)","kjv_def":"disease","translit":"malakía","lemma":"μαλακία","pron":"mal-ak-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>softness</li><li>in the NT infirmity, debility, bodily weakness, sickness</li></ol>","xlit":"malakía"},"G2741":{"derivation":"from G2740 (καῦσις);","strongs_def":" to set on fire","kjv_def":"fervent heat","translit":"kausóō","lemma":"καυσόω","pron":"kow-so'-o","pos":"Verb","thayer":"<ol><li>to burn up, set fire to</li><li>to suffer with feverish burning, be parched with fever</li></ol>","xlit":"kausóō"},"G1785":{"translit":"entolḗ","lemma":"ἐντολή","kjv_def":"commandment, precept","strongs_def":" injunction, i.e. an authoritative prescription","derivation":"from G1781 (ἐντέλλομαι);","pron":"en-tol-ay'","pos":"Noun Feminine","thayer":"<ol><li>an order, command, charge, precept, injunction<ol type='a'><li>that which is prescribed to one by reason of his office</li></ol><li>a commandment<ol type='a'><li>a prescribed rule in accordance with which a thing is done<ol><li>a precept relating to lineage, of the Mosaic precept concerning the priesthood</li><li>ethically used of the commandments in the Mosaic law or Jewish tradition</li></ol></li></ol></li></ol>","xlit":"entolḗ"},"G4794":{"derivation":"from G4862 (σύν) and G2955 (κύπτω);","strongs_def":" to stoop altogether, i.e. be completely overcome by","kjv_def":"bow together","translit":"synkýptō","lemma":"συγκύπτω","pron":"soong-koop'-to","pos":"Verb","thayer":"<ol><li>to bend completely forwards, to be bowed together</li></ol>","xlit":"synkýptō"},"G4058":{"derivation":"of uncertain derivation;","strongs_def":" a pigeon","kjv_def":"dove, pigeon","lemma":"περιστερά","translit":"peristerá","pron":"per-is-ter-ah'","pos":"Noun Feminine","thayer":"<ol><li>a dove</li></ol>","xlit":"peristerá"},"G3383":{"kjv_def":"neither, (n-)or, so as much","lemma":"μήτε","translit":"mḗte","derivation":"from G3361 (μή) and G5037 (τέ);","strongs_def":" not too, i.e. (in continued negation) neither or nor; also, not even","pron":"may'-teh","pos":"Conjunction","thayer":"<ol><li>and not, neither ... nor, not so</li></ol>","xlit":"mḗte"},"G214":{"kjv_def":"tinkle, wail","lemma":"ἀλαλάζω","translit":"alalázō","derivation":"from ( a shout, \"halloo\");","strongs_def":" to vociferate, i.e. (by implication) to wail; figuratively, to clang","pron":"al-al-ad'-zo","pos":"Verb","thayer":"<ol><li>to repeat frequently the cry \"alala\" as soldiers used to do on entering into battle</li><li>to utter a joyful sound</li><li>to wail, lament</li><li>to ring loudly, to clang</li></ol>","xlit":"alalázō"},"G3057":{"strongs_def":" a \"lance\"","derivation":"perhaps a primary word;","lemma":"λόγχη","translit":"lónchē","kjv_def":"spear","pron":"long'-khay","pos":"Noun Feminine","thayer":"<ol><li>the iron point or head of a spear</li><li>a lance, spear (a shaft armed with iron)</li></ol>","xlit":"lónchē"},"G5579":{"derivation":"from G5574 (ψεύδομαι);","strongs_def":" a falsehood","kjv_def":"lie, lying","translit":"pseûdos","lemma":"ψεῦδος","pron":"psyoo'-dos","pos":"Noun Neuter","thayer":"<ol><li>a lie</li><li>conscious and intentional falsehood</li><li>in a broad sense, whatever is not what it seems to be<ol type='a'><li>of perverse, impious, deceitful precepts</li></ol></li></ol>","xlit":"pseûdos"},"G4865":{"derivation":"from G4862 (σύν) and G75 (ἀγωνίζομαι);","strongs_def":" to struggle in company with, i.e. (figuratively) to be a partner (assistant)","kjv_def":"strive together with","translit":"synagōnízomai","lemma":"συναγωνίζομαι","pron":"soon-ag-o-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to strive together with one, to help one in striving</li></ol>","xlit":"synagōnízomai"},"G676":{"strongs_def":" inaccessible","derivation":"from G1 (Α) (as a negative particle) and a derivative of a comparative of G4314 (πρός) and (to go);","lemma":"ἀπρόσιτος","translit":"aprósitos","kjv_def":"which no man can approach","pron":"ap-ros'-ee-tos","pos":"Adjective","thayer":"<ol><li>unapproachable, inaccessible</li></ol>","xlit":"aprósitos"},"G427":{"derivation":"a primary particle;","strongs_def":" without","kjv_def":"without","translit":"áneu","lemma":"ἄνευ","pron":"an'-yoo","pos":"Preposition","thayer":"<ol><li>without one's will or intervention</li></ol>","xlit":"áneu"},"G1640":{"derivation":"comparative of the same as G1646 (ἐλάχιστος);","strongs_def":" smaller (in size, quantity, age or quality)","kjv_def":"less, under, worse, younger","lemma":"ἐλάσσων","translit":"elássōn","pron":"el-as'-sone","pos":"Verb","thayer":"<ol><li>less<ol type='a'><li>in age (younger)</li><li>in rank</li><li>in excellence, worse</li></ol></li></ol>","xlit":"elássōn"},"G1670":{"strongs_def":" to drag (literally or figuratively)","derivation":"probably akin to G138 (αἱρέομαι);","translit":"helkýō","lemma":"ἑλκύω","kjv_def":"draw","pron":"hel-koo'-o","pos":"Verb","thayer":"<ol><li>to draw, drag off</li><li>metaphorically, to draw by inward power, lead, impel</li></ol>","xlit":"helkýō"},"G3619":{"derivation":"feminine (abstract) of a compound of G3624 (οἶκος) and the base of G1430 (δῶμα);","strongs_def":" architecture, i.e. (concretely) a structure; figuratively, confirmation","kjv_def":"building, edify(-ication, -ing)","lemma":"οἰκοδομή","translit":"oikodomḗ","pron":"oy-kod-om-ay'","pos":"Noun Feminine","thayer":"<ol><li>(the act of) building, building up</li><li>metaphorically edifying, edification<ol type='a'><li>the act of one who promotes another's growth in Christian wisdom, piety, happiness, holiness</li></ol><li>a building (i.e. the thing built, edifice)</li></ol>","xlit":"oikodomḗ"},"G231":{"translit":"halieús","lemma":"ἁλιεύς","kjv_def":"fisher(-man)","strongs_def":" a sailor (as engaged on the salt water), i.e. (by implication) a fisher","derivation":"from G251 (ἅλς);","pron":"hal-ee-yoos'","pos":"Noun Masculine","thayer":"<ol><li>a fisherman, fisher</li></ol>","xlit":"halieús"},"G3843":{"lemma":"πάντως","translit":"pántōs","kjv_def":"by all means, altogether, at all, needs, no doubt, in (no) wise, surely","strongs_def":" entirely; specially, at all events, (with negative, following) in no event","derivation":"adverb from G3956 (πᾶς);","pron":"pan'-toce","pos":"Adverb","thayer":"<ol><li>altogether<ol type='a'><li>in any and every way, by all means</li><li>doubtless, surely, certainly</li><li>in no wise, not at all</li></ol></li></ol>","xlit":"pántōs"},"G2575":{"kjv_def":"furnace","translit":"káminos","lemma":"κάμινος","derivation":"probably from G2545 (καίω);","strongs_def":" a furnace","pron":"kam'-ee-nos","pos":"Noun Feminine","thayer":"<ol><li>a furnace<ol type='a'><li>for smelting</li><li>for burning earthen ware</li><li>for baking bread</li></ol></li></ol>","xlit":"káminos"},"G2017":{"kjv_def":"give light","translit":"epiphaúō","lemma":"ἐπιφαύω","derivation":"a form of G2014 (ἐπιφαίνω);","strongs_def":" to illuminate (figuratively)","pron":"ep-ee-fows'-ko","pos":"Verb","thayer":"<ol><li>to shine upon<ol type='a'><li>Christ will pour upon you the divine truth as the sun gives light to men aroused from sleep</li></ol></li></ol>","xlit":"epiphaúō"},"G3350":{"strongs_def":" a change of abode, i.e. (specially), expatriation","derivation":"from a derivative of a compound of G3326 (μετά) and G3624 (οἶκος);","translit":"metoikesía","lemma":"μετοικεσία","kjv_def":"X brought, carried(-ying) away (in-)to","pron":"met-oy-kes-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>removal from one abode to another, especially a forced removal</li></ol>","xlit":"metoikesía"},"G2293":{"strongs_def":" to have courage","derivation":"from G2294 (θάρσος);","lemma":"θαρσέω","translit":"tharséō","kjv_def":"be of good cheer (comfort)","pron":"thar-seh'-o","pos":"Verb","thayer":"<ol><li>to be of good courage, be of good cheer</li></ol>","xlit":"tharséō"},"G3882":{"kjv_def":"sea coast","translit":"parálios","lemma":"παράλιος","derivation":"from G3844 (παρά) and G251 (ἅλς);","strongs_def":" beside the salt (sea), i.e. maritime","pron":"par-al'-ee-os","pos":"Adjective","thayer":"<ol><li>by the sea, maritime, the sea coast</li></ol>","xlit":"parálios"},"G1896":{"lemma":"ἐπεῖδον","translit":"epeîdon","kjv_def":"behold, look upon","strongs_def":" to regard (favorably or otherwise)","derivation":"and other moods and persons of the same tense; from G1909 (ἐπί) and G1492 (εἴδω);","pron":"ep-i'-don","pos":"Verb","thayer":"<ol><li>to look upon, to regard</li></ol>","xlit":"epeîdon"},"G3117":{"kjv_def":"far, long","lemma":"μακρός","translit":"makrós","derivation":"from G3372 (μῆκος);","strongs_def":" long (in place (distant) or time (neuter plural))","pron":"mak-ros'","pos":"Adjective","thayer":"<ol><li>long<ol type='a'><li>of place: remote, distant, far off</li><li>of time: long, long lasting</li></ol></li></ol>","xlit":"makrós"},"G1286":{"kjv_def":"do violence to","translit":"diaseíō","lemma":"διασείω","derivation":"from G1223 (διά) and G4579 (σείω);","strongs_def":" to shake thoroughly, i.e. (figuratively) to intimidate","pron":"dee-as-i'-o","pos":"Verb","thayer":"<ol><li>to shake thoroughly</li><li>to make to tremble</li><li>to terrify</li><li>to agitate</li><li>to extort from one by intimidation money or other property</li></ol>","xlit":"diaseíō"},"G3964":{"kjv_def":"murderer of fathers","lemma":"πατραλῴας","translit":"patralṓias","derivation":"from G3962 (πατήρ) and the same as the latter part of G3389 (μητραλῴας);","strongs_def":" a parricide","pron":"pat-ral-o'-as","pos":"Noun Masculine","thayer":"<ol><li>a patricide</li></ol>","xlit":"patralṓias"},"G2714":{"translit":"katenṓpion","lemma":"κατενώπιον","kjv_def":"before (the presence of), in the sight of","strongs_def":" directly in front of","derivation":"from G2596 (κατά) and G1799 (ἐνώπιον);","pron":"kat-en-o'-pee-on","pos":"Adverb","thayer":"<ol><li>over against, before the face of, before the presence of, in the sight of, before<ol type='a'><li>referring to places</li><li>metaphorically<ol><li>having one as it were before the eyes, before one as witness</li><li>before God as judge</li></ol></li></ol></li></ol>","xlit":"katenṓpion"},"G4473":{"kjv_def":"sprinkling","lemma":"ῥαντισμός","translit":"rhantismós","derivation":"from G4472 (ῥαντίζω);","strongs_def":" aspersion (ceremonially or figuratively)","pron":"hran-tis-mos'","pos":"Noun Masculine","thayer":"<ol><li>a sprinkling (purification)<ol type='a'><li>blood of sprinkling<ol><li>i.e. appointed for sprinkling (serving to purify)</li></ol></li></ol></li></ol>","xlit":"rhantismós"},"G418":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of the same as G1735 (ἐνδέχεται);","strongs_def":" unadmitted, i.e. (by implication) not supposable","kjv_def":"impossible","translit":"anéndektos","lemma":"ἀνένδεκτος","pron":"an-en'-dek-tos","pos":"Adjective","thayer":"<ol><li>that cannot be admitted, inadmissible, unallowable, improper</li></ol>","xlit":"anéndektos"},"G2546":{"derivation":"from G2532 (καί) and G1563 (ἐκεῖ);","strongs_def":" likewise in that place","kjv_def":"and there, there (thither) also","lemma":"κἀκεῖ","translit":"kakeî","pron":"kak-i'","pos":"Adverb","thayer":"<ol><li>and there</li><li>there also</li></ol>","xlit":"kakeî"},"G1449":{"translit":"engráphō","lemma":"ἐγγράφω","kjv_def":"write (in)","strongs_def":" to \"engrave\", i.e. inscribe","derivation":"from G1722 (ἐν) and G1125 (γράφω);","pron":"eng-graf'-o","pos":"Verb","thayer":"<ol><li>to engrave, inscribe, write in or on<ol type='a'><li>to record, enrol</li></ol></li></ol>","xlit":"engráphō"},"G5352":{"derivation":"from derivative of (to wane;","strongs_def":" akin to the base of G5351 (φθείρω)) and G3703 (ὀπώρα) (meaning late autumn); autumnal (as stripped of leaves)","kjv_def":"whose fruit withereth","lemma":"φθινοπωρινός","translit":"phthinopōrinós","pron":"fthin-op-o-ree-nos'","thayer":"<ol><li>autumn trees<ol type='a'><li>trees such as they are at the close of autumn, dry, leafless and without fruit</li><li>metaphorically of unfruitful, worthless men</li></ol></li></ol>","xlit":"phthinopōrinós"},"G3437":{"kjv_def":"quarrel","translit":"momphḗ","lemma":"μομφή","derivation":"from G3201 (μέμφομαι);","strongs_def":" blame, i.e. (by implication), a fault","pron":"mom-fay'","pos":"Noun Feminine","thayer":"<ol><li>blame</li><li>to have a complaint against any one</li></ol>","xlit":"momphḗ"},"G3111":{"translit":"mákellon","lemma":"μάκελλον","kjv_def":"shambles","strongs_def":" a butcher's stall, meat market or provision-shop","derivation":"of Latin origin (macellum);","pron":"mak'-el-lon","pos":"Noun Neuter","thayer":"<ol><li>a place where meat and other articles of food are sold, meat market</li></ol>","xlit":"mákellon"},"G3780":{"translit":"ouchí","lemma":"οὐχί","kjv_def":"nay, not","strongs_def":" not indeed","derivation":"intensive of G3756 (οὐ);","pron":"oo-khee'","thayer":"<ol><li>not, by no means, not at all</li></ol>","xlit":"ouchí"},"G966":{"derivation":"of Chaldee origin (compare H01004 and H06719);","strongs_def":" fishing-house; Bethsaida, a place in Palestine","kjv_def":"Bethsaida","translit":"Bēthsaïdá","lemma":"Βηθσαϊδά","pron":"bayth-sahee-dah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethsaida = \"house of fish\"</p><ol><li>a small fishing village on the west shore of Lake Gennesaret, home of Andrew, Peter, Philip and John</li><li>a village in lower Gaulanitis on the eastern shore of Lake Gennesaret, not far from where the Jordan empties into it</li></ol>","xlit":"Bēthsaïdá"},"G4422":{"kjv_def":"frighten","translit":"ptoéō","lemma":"πτοέω","derivation":"probably akin to the alternate of G4098 (πίπτω) (through the idea of causing to fall) or to G4072 (πέτομαι) (through that of causing to fly away);","strongs_def":" to scare","pron":"pto-eh'-o","pos":"Verb","thayer":"<ol><li>to terrify</li><li>be terrified</li></ol>","xlit":"ptoéō"},"G5116":{"derivation":"neuter of a presumed derivative (alternately) of (a \"topaz\";","strongs_def":" of uncertain origin); a gem, probably the chrysolite","kjv_def":"topaz","lemma":"τοπάζιον","translit":"topázion","pron":"top-ad'-zee-on","pos":"Noun Neuter","thayer":"<ol><li>topaz, a greenish yellow precious stone (our chrysolite)</li></ol>","xlit":"topázion"},"G5344":{"translit":"Phēlix","lemma":"Φῆλιξ","kjv_def":"Felix","strongs_def":" happy; Phelix (i.e. Felix), a Roman","derivation":"of Latin origin;","pron":"fay'-lix","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Felix = \"happy\"</p><ol><li>a Roman procurator of Judea appointed by the emperor Claudius in A.D. 53. He ruled the province in a mean, cruel, and profligate manner. His period of office was full of troubles and seditions. Paul was brought before Felix at Caesarea. He was remanded in prison, and kept there two years in hopes of extorting money from him. <a class='bible' href='#b44.24.26'>Act 24:26</a>,<a class='bible' href='#b44.24.27'>Act 24:27</a>. At the end of that time Porcius Festus was appointed to supersede Felix, who, on his return to Rome, was accused by the Jews in Caesarea, and would have suffered the penalty due to his atrocities had not his brother Pallas prevailed with the emperor Nero to spare him. The wife of Felix was Drusilla, daughter of Herod Agrippa I., who was his third wife and whom he persuaded to leave her husband and marry him.</li></ol>","xlit":"Phēlix"},"G4382":{"translit":"prosōpolēpsía","lemma":"προσωποληψία","kjv_def":"respect of persons","strongs_def":" partiality, i.e. favoritism","derivation":"from G4381 (προσωπολήπτης);","pron":"pros-o-pol-ape-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>respect of persons</li><li>partiality<ol type='a'><li>the fault of one who when called on to give judgment has respect of the outward circumstances of man and not to their intrinsic merits, and so prefers, as the more worthy, one who is rich, high born, or powerful, to another who does not have these qualities</li></ol></li></ol>","xlit":"prosōpolēpsía"},"G2477":{"lemma":"ἱστορέω","translit":"historéō","kjv_def":"see","strongs_def":" to be knowing (learned), i.e. (by implication) to visit for information (interview)","derivation":"from a derivative of G1492 (εἴδω);","pron":"his-tor-eh'-o","pos":"Verb","thayer":"<ol><li>to enquire into, examine, investigate</li><li>to find out, learn, by enquiry</li><li>to gain knowledge of by visiting<ol type='a'><li>of some distinguished person, to become personally acquainted with, know face to face</li></ol></li></ol>","xlit":"historéō"},"G1267":{"derivation":"from G1266 (διαμερίζω);","strongs_def":" disunion (of opinion and conduct)","kjv_def":"division","lemma":"διαμερισμός","translit":"diamerismós","pron":"dee-am-er-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a parting, distribution</li><li>disunion, dissension</li></ol>","xlit":"diamerismós"},"G4751":{"kjv_def":"stomach","lemma":"στόμαχος","translit":"stómachos","derivation":"from G4750 (στόμα);","strongs_def":" an orifice (the gullet), i.e. (specially), the \"stomach\"","pron":"stom'-akh-os","pos":"Noun Masculine","thayer":"<ol><li>the throat</li><li>an opening, orifice, especially of the stomach</li><li>the stomach</li></ol>","xlit":"stómachos"},"G4096":{"derivation":"from (fat;","strongs_def":" perhaps akin to the alternate of G4095 (πίνω) through the idea of repletion); plumpness, i.e. (by implication) richness (oiliness)","kjv_def":"fatness","translit":"piótēs","lemma":"πιότης","pron":"pee-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>fatness</li></ol>","xlit":"piótēs"},"G4386":{"lemma":"πρότερον","translit":"próteron","kjv_def":"before, (at the) first, former","strongs_def":" previously","derivation":"neuter of G4387 (πρότερος) as adverb (with or without the article);","pron":"prot'-er-on","pos":"Adjective","thayer":"<ol><li>before, prior<ol type='a'><li>of time, former</li></ol></li></ol>","xlit":"próteron"},"G2590":{"derivation":"probably from the base of G726 (ἁρπάζω);","strongs_def":" fruit (as plucked), literally or figuratively","kjv_def":"fruit","lemma":"καρπός","translit":"karpós","pron":"kar-pos'","pos":"Noun Masculine","thayer":"<ol><li>fruit<ol type='a'><li>the fruit of the trees, vines, of the fields</li><li>the fruit of one's loins, i.e. his progeny, his posterity</li></ol><li>that which originates or comes from something, an effect, result<ol type='a'><li>work, act, deed</li><li>advantage, profit, utility</li><li>praises, which are presented to God as a thank offering</li><li>to gather fruit (i.e. a reaped harvest) into life eternal (as into a granary), is used in fig. discourse of those who by their labours have fitted souls to obtain eternal life</li></ol></li></ol>","xlit":"karpós"},"G1105":{"derivation":"akin to G3509 (νέφος);","strongs_def":" gloom (as of a storm)","kjv_def":"blackness","lemma":"γνόφος","translit":"gnóphos","pron":"gnof'-os","pos":"Noun Masculine","thayer":"<ol><li>darkness, gloom</li></ol>","xlit":"gnóphos"},"G4808":{"strongs_def":" a fig-tree","derivation":"from G4810 (σῦκον);","lemma":"συκῆ","translit":"sykē","kjv_def":"fig tree","pron":"soo-kay'","pos":"Noun Feminine","thayer":"<ol><li>a fig tree</li></ol>","xlit":"sykē"},"G2179":{"kjv_def":"of Ephesus","lemma":"Ἐφεσῖνος","translit":"Ephesînos","derivation":"from G2181 (Ἔφεσος);","strongs_def":" Ephesine, or situated at Ephesus","pron":"ef-es-ee'-nos","pos":"Adjective","thayer":"<ol><li>a native or inhabitant of Ephesus</li></ol>","xlit":"Ephesînos"},"G3334":{"strongs_def":" to stir to a place elsewhere, i.e. remove (figuratively)","derivation":"from G3326 (μετά) and G2795 (κινέω);","translit":"metakinéō","lemma":"μετακινέω","kjv_def":"move away","pron":"met-ak-ee-neh'-o","pos":"Verb","thayer":"<ol><li>to move from a place, to move away</li></ol>","xlit":"metakinéō"},"G3930":{"derivation":"from G3844 (παρά) and G2192 (ἔχω);","strongs_def":" to hold near, i.e. present, afford, exhibit, furnish occasion","kjv_def":"bring, do, give, keep, minister, offer, shew, + trouble","lemma":"παρέχω","translit":"paréchō","pron":"par-ekh'-o","pos":"Verb","thayer":"<ol><li>to reach forth, offer</li><li>to show, afford, supply</li><li>to be the authors of, or to cause one to have<ol type='a'><li>to give, bring, cause one something either favourable or unfavourable, to occasion</li></ol><li>to offer, show or present one's self</li><li>to exhibit or offer on one's own part<ol type='a'><li>to render or afford from one's own resources or by one's own power</li></ol></li></ol>","xlit":"paréchō"},"G1378":{"translit":"dógma","lemma":"δόγμα","kjv_def":"decree, ordinance","strongs_def":" a law (civil, ceremonial or ecclesiastical)","derivation":"from the base of G1380 (δοκέω);","pron":"dog'-mah","pos":"Noun Neuter","thayer":"<ol><li>doctrine, decree, ordinance<ol type='a'><li>of public decrees</li><li>of the Roman Senate</li><li>of rulers</li></ol><li>the rules and requirements of the law of Moses; carrying a suggestion of severity and of threatened judgment</li><li>of certain decrees of the apostles relative to right living</li></ol>","xlit":"dógma"},"G4027":{"derivation":"from a compound of G4012 (περί) and G2508 (καθαίρω);","strongs_def":" something cleaned off all around, i.e. refuse (figuratively)","kjv_def":"filth","lemma":"περικάθαρμα","translit":"perikátharma","pron":"per-ee-kath'-ar-mah","pos":"Noun Neuter","thayer":"<ol><li>off scouring, refuse</li><li>metaphorically<ol type='a'><li>the most abject and despicable men</li><li>the price of expiation or redemption, because the Greeks used to apply the term \"katharmata\" to victims sacrificed to make expiation for the people, and even to criminals who were maintained at the public expense, that on the outbreak of a pestilence or other calamity they might be offered as sacrifices to make expiation for the state</li></ol></li></ol>","xlit":"perikátharma"},"G3844":{"translit":"pará","lemma":"παρά","kjv_def":"above, against, among, at, before, by, contrary to, X friend, from, + give (such things as they), + that (she) had, X his, in, more than, nigh unto, (out) of, past, save, side…by, in the sight of, than, (there-)fore, with","strongs_def":" properly, near; i.e. (with genitive case) from beside (literally or figuratively), (with dative case) at (or in) the vicinity of (objectively or subjectively), (with accusative case) to the proximity with (local (especially beyond or opposed to) or causal (on account of)","derivation":"a primary preposition;","pron":"par-ah'","pos":"Preposition","thayer":"<ol><li>from, of at, by, besides, near</li></ol>","xlit":"pará"},"G1335":{"strongs_def":" a recital","derivation":"from G1334 (διηγέομαι);","translit":"diḗgesis","lemma":"διήγεσις","kjv_def":"declaration","pron":"dee-ayg'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a narration, narrative</li></ol>","xlit":"diḗgesis"},"G2628":{"strongs_def":" to accompany closely","derivation":"from G2596 (κατά) and G190 (ἀκολουθέω);","lemma":"κατακολουθέω","translit":"katakolouthéō","kjv_def":"follow (after)","pron":"kat-ak-ol-oo-theh'-o","pos":"Verb","thayer":"<ol><li>to follow after</li></ol>","xlit":"katakolouthéō"},"G2006":{"lemma":"ἐπιτήδειος","translit":"epitḗdeios","kjv_def":"things which are needful","strongs_def":" serviceable, i.e. (by implication) requisite","derivation":"from (enough);","pron":"ep-ee-tay'-di-os","pos":"Adjective","thayer":"<ol><li>fit, suitable, convenient, advantageous</li><li>needful, especially of the necessities of life</li></ol>","xlit":"epitḗdeios"},"G2757":{"lemma":"κενοφωνία","translit":"kenophōnía","kjv_def":"vain","strongs_def":" empty sounding, i.e. fruitless discussion","derivation":"from a presumed compound of G2756 (κενός) and G5456 (φωνή);","pron":"ken-of-o-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>empty discussion, discussion of vain and useless matters</li></ol>","xlit":"kenophōnía"},"G4639":{"derivation":"apparently a primary word;","strongs_def":" \"shade\" or a shadow (literally or figuratively (darkness of error or an adumbration))","kjv_def":" shadow","translit":"skiá","lemma":"σκιά","pron":"skee'-ah","pos":"Noun Feminine","thayer":"<ol><li>shadow<ol type='a'><li>shade caused by the interception of light</li><li>an image cast by an object and representing the form of that object</li><li>a sketch, outline, adumbration</li></ol></li></ol>","xlit":"skiá"},"G1157":{"strongs_def":" a lender","derivation":"from G1155 (δανείζω);","translit":"daneistḗs","lemma":"δανειστής","kjv_def":"creditor","pron":"dan-ice-tace'","pos":"Noun Masculine","thayer":"<ol><li>a money lender, creditor</li></ol>","xlit":"daneistḗs"},"G2716":{"derivation":"from G2596 (κατά) and G2038 (ἐργάζομαι);","strongs_def":" to work fully, i.e. accomplish; by implication, to finish, fashion","kjv_def":"cause, to (deed), perform, work (out)","translit":"katergázomai","lemma":"κατεργάζομαι","pron":"kat-er-gad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to perform, accomplish, achieve</li><li>to work out, i.e. to do that from which something results<ol type='a'><li>of things: bring about, result in</li></ol><li>to fashion, i.e. render one fit for a thing</li></ol>","xlit":"katergázomai"},"G2593":{"translit":"karpophóros","lemma":"καρποφόρος","kjv_def":"fruitful","strongs_def":" fruitbearing (figuratively)","derivation":"from G2590 (καρπός) and G5342 (φέρω);","pron":"kar-pof-or'-os","pos":"Adjective","thayer":"<ol><li>fruit bearing, fruitful, productive</li></ol>","xlit":"karpophóros"},"G4606":{"kjv_def":"of Sidon","lemma":"Σιδώνιος","translit":"Sidṓnios","derivation":"from G4605 (Σιδών);","strongs_def":" a Sidonian, i.e. inhabitant of Sidon","pron":"sid-o'-nee-os","pos":"Adjective","thayer":"<ol><li>an inhabitant of Sidon, a Sidonian</li></ol>","xlit":"Sidṓnios"},"G3953":{"derivation":"from G3844 (παρά) and the base of G3795 (ὀψάριον);","strongs_def":" a side-dish (the receptacle)","kjv_def":"platter","lemma":"παροψίς","translit":"paropsís","pron":"par-op-sis'","pos":"Noun Feminine","thayer":"<ol><li>a side dish, a dish of dainties or choice food suited not so much to satisfy as to gratify the appetite<ol type='a'><li>a side accompaniment of the more solid food</li></ol><li>the dish itself in which the delicacies are served up</li></ol>","xlit":"paropsís"},"G5357":{"derivation":"of uncertain affinity;","strongs_def":" a broad shallow cup (\"phial\")","kjv_def":"vial","translit":"phiálē","lemma":"φιάλη","pron":"fee-al'-ay","pos":"Noun Feminine","thayer":"<ol><li>a broad shallow bowl, deep saucer</li></ol>","xlit":"phiálē"},"G5430":{"strongs_def":" prudently","derivation":"adverb from G5429 (φρόνιμος);","lemma":"φρονίμως","translit":"phronímōs","kjv_def":"wisely","pron":"fron-im'-oce","pos":"Adverb","thayer":"<ol><li>prudently, wisely</li></ol>","xlit":"phronímōs"},"G1402":{"kjv_def":"bring into (be under) bondage, X given, become (make) servant","translit":"doulóō","lemma":"δουλόω","derivation":"from G1401 (δοῦλος);","strongs_def":" to enslave (literally or figuratively)","pron":"doo-lo'-o","pos":"Noun Masculine","thayer":"<ol><li>to make a slave of, reduce to bondage</li><li>metaphorically give myself wholly to one's needs and service, make myself a bondman to him</li></ol>","xlit":"doulóō"},"G882":{"kjv_def":"Achaia","lemma":"Ἀχαΐα","translit":"Achaḯa","derivation":"of uncertain derivation;","strongs_def":" Achaia (i.e. Greece), a country of Europe","pron":"ach-ah-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Achaia = \"trouble\"</p><ol><li>in a restricted sense, the maritime region of northern Peloponnesus</li><li>in a broader sense, a Roman province embracing all Greece except Thessaly</li></ol>","xlit":"Achaḯa"},"G3337":{"derivation":"from G3326 (μετά) and G236 (ἀλλάσσω);","strongs_def":" to exchange","kjv_def":"change","lemma":"μεταλλάσσω","translit":"metallássō","pron":"met-al-las'-so","pos":"Verb","thayer":"<ol><li>to exchange, change</li></ol>","xlit":"metallássō"},"G1819":{"kjv_def":"suddenly","translit":"exápina","lemma":"ἐξάπινα","derivation":"from G1537 (ἐκ) and a derivative of the same as G160 (αἰφνίδιος);","strongs_def":" of a sudden, i.e. unexpectedly","pron":"ex-ap'-ee-nah","pos":"Adverb","thayer":"<ol><li>suddenly</li></ol>","xlit":"exápina"},"G2696":{"translit":"katasphragízō","lemma":"κατασφραγίζω","kjv_def":"seal","strongs_def":" to seal closely","derivation":"from G2596 (κατά) and G4972 (σφραγίζω);","pron":"kat-as-frag-id'-zo","pos":"Verb","thayer":"<ol><li>to cover with a seal, to close up, close with a seal</li></ol>","xlit":"katasphragízō"},"G4151":{"lemma":"πνεῦμα","translit":"pneûma","kjv_def":"ghost, life, spirit(-ual, -ually), mind","strongs_def":" a current of air, i.e. breath (blast) or a breeze; by analogy or figuratively, a spirit, i.e. (human) the rational soul, (by implication) vital principle, mental disposition, etc., or (superhuman) an angel, demon, or (divine) God, Christ's spirit, the Holy Spirit","derivation":"from G4154 (πνέω);","pron":"pnyoo'-mah","pos":"Noun Neuter","thayer":"<ol><li>the third person of the triune God, the Holy Spirit, coequal, coeternal with the Father and the Son<ol type='a'><li>sometimes referred to in a way which emphasises his personality and character (the Spirit)</li><li>sometimes referred to in a way which emphasises his work and power (the Spirit of 1c) never referred to as a depersonalised force</li></ol><li>the spirit, i.e. the vital principal by which the body is animated<ol type='a'><li>the rational spirit, the power by which the human being feels, thinks, decides</li><li>the soul</li></ol><li>a spirit, i.e. a simple essence, devoid of all or at least all grosser matter, and possessed of the power of knowing, desiring, deciding, and acting<ol type='a'><li>a life giving spirit</li><li>a human soul that has left the body</li><li>a spirit higher than man but lower than God, i.e. an angel<ol><li>used of demons, or evil spirits, who were conceived as inhabiting the bodies of men</li><li>the spiritual nature of Christ, higher than the highest angels and equal to God, the divine nature of Christ</li></ol></li></ol><li>the disposition or influence which fills and governs the soul of any one<ol type='a'><li>the efficient source of any power, affection, emotion, desire, etc.</li></ol><li>a movement of air (a gentle blast)<ol type='a'><li>of the wind, hence the wind itself</li><li>breath of nostrils or mouth</li></ol></li></ol>","xlit":"pneûma"},"G4978":{"lemma":"σχίσμα","translit":"schísma","kjv_def":"division, rent, schism","strongs_def":" a split or gap (\"schism\"), literally or figuratively","derivation":"from G4977 (σχίζω);","pron":"skhis'-mah","pos":"Noun Neuter","thayer":"<ol><li>a rent</li><li>metaphorically a division, dissension</li></ol>","xlit":"schísma"},"G4338":{"strongs_def":" to peg to, i.e. spike fast","derivation":"from G4314 (πρός) and a derivative of G2247 (ἧλος);","lemma":"προσηλόω","translit":"prosēlóō","kjv_def":"nail to","pron":"pros-ay-lo'-o","pos":"Verb","thayer":"<ol><li>to fasten with nails to, nail to</li></ol>","xlit":"prosēlóō"},"G2908":{"strongs_def":" (as noun) better, i.e. greater advantage","derivation":"neuter of an alternate form of G2909 (κρείττων);","translit":"kreîsson","lemma":"κρεῖσσον","kjv_def":"better","pron":"krice'-son","pos":"Adverb","thayer":"<ol><li>better</li></ol>","xlit":"kreîsson"},"G4421":{"kjv_def":"bird","translit":"ptēnón","lemma":"πτηνόν","derivation":"contraction for G4071 (πετεινόν);","strongs_def":" a bird","pron":"ptay-non'","pos":"Adjective","thayer":"<ol><li>furnished with wings</li><li>winged, flying<ol type='a'><li>of birds</li></ol></li></ol>","xlit":"ptēnón"},"G4001":{"strongs_def":" five hundred","derivation":"from G4002 (πέντε) and G1540 (ἑκατόν);","translit":"pentakósioi","lemma":"πεντακόσιοι","kjv_def":"five hundred","pron":"pen-tak-os'-ee-oy","pos":"Adjective","thayer":"<ol><li>five hundred</li></ol>","xlit":"pentakósioi"},"G4619":{"kjv_def":"fatling","translit":"sitistós","lemma":"σιτιστός","derivation":"from a derivative of G4621 (σῖτος);","strongs_def":" grained, i.e. fatted","pron":"sit-is-tos'","pos":"Adjective","thayer":"<ol><li>fattened</li></ol>","xlit":"sitistós"},"G2013":{"lemma":"ἐπιτυγχάνω","translit":"epitynchánō","kjv_def":"obtain","strongs_def":" to chance upon, i.e. (by implication) to attain","derivation":"from G1909 (ἐπί) and G5177 (τυγχάνω);","pron":"ep-ee-toong-khan'-o","pos":"Verb","thayer":"<ol><li>to light or hit upon any person or thing</li><li>to attain to, obtain</li></ol>","xlit":"epitynchánō"},"G3306":{"translit":"ménō","lemma":"μένω","kjv_def":"abide, continue, dwell, endure, be present, remain, stand, tarry (for), X thine own","strongs_def":" to stay (in a given place, state, relation or expectancy)","derivation":"a primary verb;","pron":"men'-o","pos":"Verb","thayer":"<ol><li>to remain, abide<ol type='a'><li>in reference to place<ol><li>to sojourn, tarry</li><li>not to depart<ol type='a'><li>to continue to be present</li><li>to be held, kept, continually</li></ol></li></ol><li>in reference to time<ol><li>to continue to be, not to perish, to last, endure<ol type='a'><li>of persons, to survive, live</li></ol></li></ol><li>in reference to state or condition<ol><li>to remain as one, not to become another or different</li></ol></li></ol><li>to wait for, await one</li></ol>","xlit":"ménō"},"G568":{"kjv_def":"be, have, receive","translit":"apéchō","lemma":"ἀπέχω","derivation":"from G575 (ἀπό) and G2192 (ἔχω);","strongs_def":" (actively) to have out, i.e. receive in full; (intransitively) to keep (oneself) away, i.e. be distant (literally or figuratively)","pron":"ap-ekh'-o","pos":"Verb","thayer":"<ol><li>have<ol type='a'><li>to hold back, keep off, prevent</li><li>to have wholly or in full, to have received</li><li>it is enough, sufficient</li></ol><li>to be away, absent, distant</li><li>to hold one's self off, abstain</li></ol>","xlit":"apéchō"},"G2028":{"lemma":"ἐπονομάζω","translit":"eponomázō","kjv_def":"call","strongs_def":" to name further, i.e. denominate","derivation":"from G1909 (ἐπί) and G3687 (ὀνομάζω);","pron":"ep-on-om-ad'-zo","pos":"Verb","thayer":"<ol><li>to put a name upon, name</li><li>to be named</li></ol>","xlit":"eponomázō"},"G2853":{"derivation":"from (\"glue\");","strongs_def":" to glue, i.e. (passively or reflexively) to stick (figuratively)","kjv_def":"cleave, join (self), keep company","lemma":"κολλάω","translit":"kolláō","pron":"kol-lah'-o","pos":"Verb","thayer":"<ol><li>to glue, to glue together, cement, fasten together</li><li>to join or fasten firmly together</li><li>to join one's self to, cleave to</li></ol>","xlit":"kolláō"},"G2333":{"kjv_def":"Theudas","lemma":"Θευδᾶς","translit":"Theudâs","derivation":"of uncertain origin;","strongs_def":" Theudas, an Israelite","pron":"thyoo-das'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Theudas = \"God-given\"</p><ol><li>the name of an insurgent mentioned in Gamaliel's speech before the Jewish council, <a class='bible' href='#b44.5.35-39'>Act 5:35-39</a>, at the time of the arraignment of the apostles. He appeared, according to Luke's account, at the head of about four hundred men. He was probably one of the insurrectionary chiefs or fanatics by whom the land was overrun in the last year of Herod's reign. Josephus speaks of a Theudas who played a similar part at the time of Claudius, about A.D. 44; but the Theudas mentioned by Luke must be a different person from the one spoken of by Josephus.</li></ol>","xlit":"Theudâs"},"G1847":{"translit":"exoudenóō","lemma":"ἐξουδενόω","kjv_def":"set at nought","strongs_def":" to make utterly nothing of, i.e. despise","derivation":"from G1537 (ἐκ) and a derivative of the neuter of G3762 (οὐδείς);","pron":"ex-oo-den-o'-o","pos":"Verb","thayer":"<ol><li>to hold and treat as of no account, utterly to despise</li><li>to set at nought, treat with contempt</li></ol>","xlit":"exoudenóō"},"G872":{"strongs_def":" to consider attentively","derivation":"from G575 (ἀπό) and G3708 (ὁράω);","lemma":"ἀφοράω","translit":"aphoráō","kjv_def":"look","pron":"af-or-ah'-o","pos":"Verb","thayer":"<ol><li>to turn the eyes away from other things and fix them on something</li></ol>","xlit":"aphoráō"},"G4629":{"derivation":"from a derivative of (a covering;","strongs_def":" perhaps akin to the base of G4649 (σκοπός) through the idea of noticeableness); clothing","kjv_def":"raiment","lemma":"σκέπασμα","translit":"sképasma","pron":"skep'-as-mah","pos":"Neuter","thayer":"<ol><li>a covering, spec. clothing</li></ol>","xlit":"sképasma"},"G579":{"kjv_def":"be refused","lemma":"ἀπόβλητος","translit":"apóblētos","derivation":"from G577 (ἀποβάλλω);","strongs_def":" cast off, i.e. (figuratively) such as to be rejected","pron":"ap-ob'-lay-tos","pos":"Adjective","thayer":"<ol><li>thrown away, to be thrown away, rejected, despised, abominated<ol type='a'><li>as unclean</li></ol></li></ol>","xlit":"apóblētos"},"G1721":{"kjv_def":"engrafted","translit":"émphytos","lemma":"ἔμφυτος","derivation":"from G1722 (ἐν) and a derivative of G5453 (φύω);","strongs_def":" implanted (figuratively)","pron":"em'-foo-tos","pos":"Adjective","thayer":"<ol><li>inborn, implanted by nature, implanted by others instruction</li></ol>","xlit":"émphytos"},"G163":{"derivation":"from G164 (αἰχμάλωτος);","strongs_def":" to make captive","kjv_def":"lead away captive, bring into captivity","lemma":"αἰχμαλωτίζω","translit":"aichmalōtízō","pron":"aheekh-mal-o-tid'-zo","pos":"Verb","thayer":"<ol><li>to lead away captive</li><li>metaphorically to capture ones mind, captivate</li></ol>","xlit":"aichmalōtízō"},"G104":{"strongs_def":" \"ever,\" by qualification regularly; by implication, earnestly","derivation":"from an obsolete primary noun (apparently meaning continued duration);","lemma":"ἀεί","translit":"aeí","kjv_def":"always, ever","pron":"ah-eye'","pos":"Adverb","thayer":"<ol><li>perpetually, incessantly</li><li>invariably, at any and every time: when according to the circumstances something is or ought to be done again</li></ol>","xlit":"aeí"},"G2202":{"kjv_def":"band","translit":"zeuktēría","lemma":"ζευκτηρία","derivation":"feminine of a derivative (at the second stage) from the same as G2218 (ζυγός);","strongs_def":" a fastening (tiller-rope)","pron":"dzook-tay-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a band, fastening</li></ol>","xlit":"zeuktēría"},"G761":{"kjv_def":"which cannot be moved, unmovable","translit":"asáleutos","lemma":"ἀσάλευτος","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4531 (σαλεύω);","strongs_def":" unshaken, i.e. (by implication) immovable (figuratively)","pron":"as-al'-yoo-tos","pos":"Adjective","thayer":"<ol><li>unshaken, unmoved</li><li>metaphorically not liable to overthrow and disorder, firm stable</li></ol>","xlit":"asáleutos"},"G4616":{"kjv_def":"(fine) linen (cloth)","lemma":"σινδών","translit":"sindṓn","derivation":"of uncertain (perhaps foreign) origin;","strongs_def":" byssos, i.e. bleached linen (the cloth or a garment of it)","pron":"sin-done'","pos":"Noun Feminine","thayer":"<ol><li>linen cloth, especially that which was fine and costly, in which the bodies of the dead were wrapped</li><li>thing made of fine cloth<ol type='a'><li>of a light and loose garment worn at night over a naked body</li></ol></li></ol>","xlit":"sindṓn"},"G4868":{"translit":"synaírō","lemma":"συναίρω","kjv_def":"reckon, take","strongs_def":" to make up together, i.e. (figuratively) to compute (an account)","derivation":"from G4862 (σύν) and G142 (αἴρω);","pron":"soon-ah'-ee-ro","pos":"Verb","thayer":"<ol><li>to take up together with another or others</li><li>to bring together with others<ol type='a'><li>to cast up or settle accounts</li><li>to make a reckoning with</li></ol></li></ol>","xlit":"synaírō"},"G4654":{"strongs_def":" to obscure (literally or figuratively)","derivation":"from G4655 (σκότος);","lemma":"σκοτίζω","translit":"skotízō","kjv_def":"darken","pron":"skot-id-zo","pos":"Verb","thayer":"<ol><li>to cover with darkness, to darken</li><li>to be covered with darkness, be darkened<ol type='a'><li>of heavenly bodies as deprived of light</li><li>metaphorically<ol><li>of the eyes</li><li>of the understanding</li><li>of the mind</li></ol></li></ol></li></ol>","xlit":"skotízō"},"G490":{"kjv_def":"Antioch","lemma":"Ἀντιόχεια","translit":"Antiócheia","derivation":"from (a Syrian king);","strongs_def":" Antiochia, a place in Syria","pron":"an-tee-okh'-i-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Antioch = 'driven against\"</p><ol><li>Capital of Syria, situated on the river Orontes, founded by Seleucus Nicanor in 300 B.C. and named in honour of his father, Antiochus. Many Greek-Jews lived there and it was here that the followers of Christ were first called Christians.</li><li>A city in Pisidia on the borders Phrygia, founded by Seleucus Nicanor. Under the Romans it became a \"colonia\" and was also called Caesarea</li></ol>","xlit":"Antiócheia"},"G172":{"strongs_def":" not bad, i.e. (objectively) innocent or (subjectively) unsuspecting","derivation":"from G1 (Α) (as a negative particle) and G2556 (κακός);","lemma":"ἄκακος","translit":"ákakos","kjv_def":"harmless, simple","pron":"ak'-ak-os","pos":"Adjective","thayer":"<ol><li>without guile or fraud, harmless, free from guilt</li><li>fearing no evil from others, distrusting no one</li></ol>","xlit":"ákakos"},"G5082":{"derivation":"from a compound of G3588 (ὁ) with G2245 (ἡλίκος) and G3778 (οὗτος);","strongs_def":" such as this, i.e. (in (figurative) magnitude) so vast","kjv_def":"so great, so mighty","lemma":"τηλικοῦτος","translit":"tēlikoûtos","pron":"tay-lik-oo'-tos","thayer":"<ol><li>of age<ol type='a'><li>of such an age</li><li>of so great an age, so old</li><li>so young</li></ol><li>of so great a size, in bulk</li><li>such and so great</li></ol>","xlit":"tēlikoûtos"},"G768":{"kjv_def":"Aser","translit":"Asḗr","lemma":"Ἀσήρ","derivation":"of Hebrew origin (H0836);","strongs_def":" Aser (i.e. Asher), an Israelite tribe","pron":"as-ayr'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Asher = \"blessed\"</p><ol><li>the eighth son of Jacob</li></ol>","xlit":"Asḗr"},"G3927":{"lemma":"παρεπίδημος","translit":"parepídēmos","kjv_def":"pilgrim, stranger","strongs_def":" an alien alongside, i.e. a resident foreigner","derivation":"from G3844 (παρά) and the base of G1927 (ἐπιδημέω);","pron":"par-ep-id'-ay-mos","pos":"Adjective","thayer":"<ol><li>one who comes from a foreign country into a city or land to reside there by the side of the natives</li><li>a stranger</li><li>sojourning in a strange place, a foreigner</li><li>in the NT metaphorically in reference to heaven as the native country, one who sojourns on earth</li></ol>","xlit":"parepídēmos"},"G1281":{"kjv_def":"gain by trading","translit":"diapragmateúomai","lemma":"διαπραγματεύομαι","derivation":"from G1223 (διά) and G4231 (πραγματεύομαι);","strongs_def":" to thoroughly occupy oneself, i.e. (transitively and by implication) to earn in business","pron":"dee-ap-rag-mat-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>thoroughly, earnestly to undertake a business</li><li>to undertake a business for sake of gain</li></ol>","xlit":"diapragmateúomai"},"G1653":{"strongs_def":" to compassionate (by word or deed, specially, by divine grace)","derivation":"from G1656 (ἔλεος);","lemma":"ἐλεέω","translit":"eleéō","kjv_def":"have compassion (pity on), have (obtain, receive, shew) mercy (on)","pron":"el-eh-eh'-o","pos":"Verb","thayer":"<ol><li>to have mercy on</li><li>to help one afflicted or seeking aid</li><li>to help the afflicted, to bring help to the wretched</li><li>to experience mercy</li></ol>","xlit":"eleéō"},"G4542":{"kjv_def":"of Samaria","lemma":"Σαμαρεῖτις","translit":"Samareîtis","derivation":"feminine of G4541 (Σαμαρείτης);","strongs_def":" a Samaritess, i.e. woman of Samaria","pron":"sam-ar-i'-tis","pos":"Noun Feminine","thayer":"<ol><li>a Samaritan woman</li></ol>","xlit":"Samareîtis"},"G1507":{"kjv_def":"roll together","lemma":"εἱλίσσω","translit":"heilíssō","derivation":"a prolonged form of a primary but defective verb (of the same meaning);","strongs_def":" to coil or wrap","pron":"hi-lis'-so","pos":"Verb","thayer":"<ol><li>to roll up or together</li></ol>","xlit":"heilíssō"},"G1092":{"kjv_def":"husbandman","lemma":"γεωργός","translit":"geōrgós","derivation":"from G1093 (γῆ) and the base of G2041 (ἔργον);","strongs_def":" a land-worker, i.e. farmer","pron":"gheh-ore-gos'","pos":"Noun Masculine","thayer":"<ol><li>a husbandman, tiller of the soil, a vine dresser</li></ol>","xlit":"geōrgós"},"G1739":{"derivation":"from a compound of G1722 (ἐν) and a derivative of the base of G1218 (δῆμος);","strongs_def":" a housing in (residence), i.e. structure","kjv_def":"building","translit":"endómēsis","lemma":"ἐνδόμησις","pron":"en-dom'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>that which is build in<ol type='a'><li>the material built into a wall, i.e. of which the wall is composed</li><li>a mole built into the sea to form a breakwater, and so construct a harbour</li></ol></li></ol>","xlit":"endómēsis"},"G3588":{"derivation":"the definite article;","strongs_def":" the (sometimes to be supplied, at others omitted, in English idiom)","kjv_def":"the, this, that, one, he, she, it, etc","translit":"ho","lemma":"ὁ","pron":"ho","xlit":"ho"},"G1415":{"lemma":"δυνατός","translit":"dynatós","kjv_def":"able, could, (that is) mighty (man), possible, power, strong","strongs_def":" powerful or capable (literally or figuratively); neuter possible","derivation":"from G1410 (δύναμαι);","pron":"doo-nat-os'","pos":"Adjective","thayer":"<ol><li>able, powerful, mighty, strong<ol type='a'><li>mighty in wealth and influence</li><li>strong in soul<ol><li>to bear calamities and trials with fortitude and patience</li><li>strong in Christian virtue</li></ol></li></ol><li>to be able (to do something)<ol type='a'><li>mighty, excelling in something</li><li>having power for something</li></ol></li></ol>","xlit":"dynatós"},"G4079":{"derivation":"neuter of a (presumed) derivative of (the blade of an oar;","strongs_def":" from the same as G3976 (πέδη)); a \"pedal\", i.e. helm","kjv_def":"rudder","translit":"pēdálion","lemma":"πηδάλιον","pron":"pay-dal'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a ship's rudder</li></ol>","xlit":"pēdálion"},"G4574":{"derivation":"from G4573 (σεβάζομαι);","strongs_def":" something adored, i.e. an object of worship (god, altar, etc)","kjv_def":"devotion, that is worshipped","translit":"sébasma","lemma":"σέβασμα","pron":"seb'-as-mah","pos":"Noun Neuter","thayer":"<ol><li>whatever is religiously honoured, an object of worship<ol type='a'><li>of temples, altars, statues, idolatrous images</li></ol></li></ol>","xlit":"sébasma"},"G4664":{"strongs_def":" consisting of emerald","derivation":"from G4665 (σμάραγδος);","lemma":"σμαράγδινος","translit":"smarágdinos","kjv_def":"emerald","pron":"smar-ag'-dee-nos","pos":"Adjective","thayer":"<ol><li>of emerald, made of emerald</li></ol>","xlit":"smarágdinos"},"G2533":{"kjv_def":"Caiaphas","lemma":"Καϊάφας","translit":"Kaïáphas","derivation":"of Chaldee origin;","strongs_def":" the dell; Caiaphas (i.e. Cajepha), an Israelite","pron":"kah-ee-af'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Caiaphas = \"as comely\"</p><ol><li>a high priest of the Jews appointed to that office by Valerius Gratus, governor of Judaea, after removal of Simon, son of Camith, A.D. 18, and was removed A.D. 36 by Vitellius, governor of Syria, who appointed Jonathan, son of Ananus (Annus, father-in-law of Caiaphas), his successor</li></ol>","xlit":"Kaïáphas"},"G3335":{"strongs_def":" to participate; genitive case, to accept (and use)","derivation":"from G3326 (μετά) and G2983 (λαμβάνω);","translit":"metalambánō","lemma":"μεταλαμβάνω","kjv_def":"eat, have, be partaker, receive, take","pron":"met-al-am-ban'-o","pos":"Verb","thayer":"<ol><li>to be or to be made a partner</li><li>to partake of, take [some] food</li><li>of a thing, to get, find (a whole)</li></ol>","xlit":"metalambánō"},"G2788":{"kjv_def":"harp","lemma":"κιθάρα","translit":"kithára","derivation":"of uncertain affinity;","strongs_def":" a lyre","pron":"kith-ar'-ah","pos":"Noun Feminine","thayer":"<ol><li>a harp to which praises of God are sung in heaven</li></ol>","xlit":"kithára"},"G912":{"translit":"Barabbâs","lemma":"Βαραββᾶς","kjv_def":"Barabbas","strongs_def":" son of Abba; Bar-abbas, an Israelite","derivation":"of Chaldee origin (H01347 and H05);","pron":"bar-ab-bas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Barabbas = \"son of a father or master\"</p><ol><li>the captive robber whom the Jews begged Pilate to release instead of Christ</li></ol>","xlit":"Barabbâs"},"G5192":{"kjv_def":" jacinth","lemma":"ὑάκινθος","translit":"hyákinthos","derivation":"of uncertain derivation;","strongs_def":" the \"hyacinth\" or \"jacinth\", i.e. some gem of a deep blue color, probably the zirkon","pron":"hoo-ak'-in-thos","pos":"Noun Masculine","thayer":"<ol><li>hyacinth, the name of a flower, also of a precious stone of the same colour, a dark blue verging on black</li></ol>","xlit":"hyákinthos"},"G3185":{"lemma":"μεῖζον","translit":"meîzon","kjv_def":"the more","strongs_def":" (adverbially) in greater degree","derivation":"neuter of G3187 (μείζων);","pron":"mide'-zon","pos":"Adverb","thayer":"<ol><li>of greater degree, even more</li></ol>","xlit":"meîzon"},"G3841":{"strongs_def":" the all-ruling, i.e. God (as absolute and universal sovereign)","derivation":"from G3956 (πᾶς) and G2904 (κράτος);","translit":"pantokrátōr","lemma":"παντοκράτωρ","kjv_def":"Almighty, Omnipotent","pron":"pan-tok-rat'-ore","pos":"Noun Masculine","thayer":"<ol><li>he who holds sway over all things</li><li>the ruler of all</li><li>almighty: God</li></ol>","xlit":"pantokrátōr"},"G2623":{"derivation":"from G2596 (κατά) and G2808 (κλείω);","strongs_def":" to shut down (in a dungeon), i.e. incarcerate","kjv_def":"shut up","lemma":"κατακλείω","translit":"katakleíō","pron":"kat-ak-li'-o","pos":"Verb","thayer":"<ol><li>to shut up, confine</li></ol>","xlit":"katakleíō"},"G1940":{"lemma":"ἐπικαθίζω","translit":"epikathízō","kjv_def":"set on","strongs_def":" to seat upon","derivation":"from G1909 (ἐπί) and G2523 (καθίζω);","pron":"ep-ee-kath-id'-zo","pos":"Verb","thayer":"<ol><li>to cause to sit upon, to set upon</li><li>to sit upon</li></ol>","xlit":"epikathízō"},"G5388":{"translit":"philóteknos","lemma":"φιλότεκνος","kjv_def":"love their children","strongs_def":" fond of one's children, i.e. maternal","derivation":"from G5384 (φίλος) and G5043 (τέκνον);","pron":"fil-ot'-ek-nos","pos":"Adjective","thayer":"<ol><li>loving one's offspring or children</li></ol>","xlit":"philóteknos"},"G1315":{"strongs_def":" to handle thoroughly, i.e. lay violent hands upon","derivation":"from G1223 (διά) and a derivative of G5495 (χείρ);","lemma":"διαχειρίζομαι","translit":"diacheirízomai","kjv_def":"kill, slay","pron":"dee-akh-i-rid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to move by the use of the hands, take in hand, manage, administer, govern</li><li>to lay hands on, slay, kill [with one's own hand]</li></ol>","xlit":"diacheirízomai"},"G5498":{"kjv_def":"handwriting","translit":"cheirógraphon","lemma":"χειρόγραφον","derivation":"neuter of a compound of G5495 (χείρ) and G1125 (γράφω);","strongs_def":" something hand-written (\"chirograph\"), i.e. a manuscript (specially, a legal document or bond (figuratively))","pron":"khi-rog'-raf-on","pos":"Noun Neuter","thayer":"<ol><li>a handwriting, what one has written by his own hand</li><li>a note of hand or writing in which one acknowledges that money has either been deposited with him or lent to him by another, to be returned at the appointed time</li></ol>","xlit":"cheirógraphon"},"G335":{"kjv_def":"importunity","translit":"anaídeia","lemma":"ἀναίδεια","derivation":"from a compound of G1 (Α) (as a negative particle (compare G427 (ἄνευ))) and G127 (αἰδώς);","strongs_def":" impudence, i.e. (by implication) importunity","pron":"an-ah'-ee-die-ah'","pos":"Noun Feminine","thayer":"<ol><li>shamelessness, impudence</li></ol>","xlit":"anaídeia"},"G1512":{"derivation":"from G1487 (εἰ) and G4007 (περ);","strongs_def":" if perhaps","kjv_def":"if so be (that), seeing, though","lemma":"εἴ περ","translit":"eí per","pron":"i per","pos":"Conjunction","thayer":"<ol><li>if indeed, since, if after all</li></ol>","xlit":"eí per"},"G505":{"kjv_def":"without dissimulation (hypocrisy), unfeigned","translit":"anypókritos","lemma":"ἀνυπόκριτος","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G5271 (ὑποκρίνομαι);","strongs_def":" undissembled, i.e. sincere","pron":"an-oo-pok'-ree-tos","pos":"Adjective","thayer":"<ol><li>unfeigned, undisguised, sincere</li></ol>","xlit":"anypókritos"},"G4367":{"derivation":"from G4314 (πρός) and G5021 (τάσσω);","strongs_def":" to arrange towards, i.e. (figuratively) enjoin","kjv_def":"bid, command","lemma":"προστάσσω","translit":"prostássō","pron":"pros-tas'-so","pos":"Verb","thayer":"<ol><li>to assign or ascribe to, join to</li><li>to enjoin, order, prescribe, command<ol type='a'><li>to appoint, to define</li></ol></li></ol>","xlit":"prostássō"},"G5510":{"derivation":"perhaps akin to the base of G5490 (χάσμα) (G5465 (χαλάω)) or G5494 (χειμών) (as descending or empty);","strongs_def":" snow","kjv_def":"snow","translit":"chiṓn","lemma":"χιών","pron":"khee-one'","pos":"Noun Feminine","thayer":"<ol><li>snow</li></ol>","xlit":"chiṓn"},"G1922":{"kjv_def":"(ac-)knowledge(-ing, - ment)","lemma":"ἐπίγνωσις","translit":"epígnōsis","derivation":"from G1921 (ἐπιγινώσκω);","strongs_def":" recognition, i.e. (by implication) full discernment, acknowledgement","pron":"ep-ig'-no-sis","pos":"Noun Feminine","thayer":"<ol><li>precise and correct knowledge<ol type='a'><li>used in the NT of the knowledge of things ethical and divine</li></ol></li></ol>","xlit":"epígnōsis"},"G412":{"strongs_def":" not spoken out, i.e. (by implication) unutterable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G1583 (ἐκλαλέω);","translit":"aneklálētos","lemma":"ἀνεκλάλητος","kjv_def":"unspeakable","pron":"an-ek-lal'-ay-tos","pos":"Adjective","thayer":"<ol><li>unspeakable</li></ol>","xlit":"aneklálētos"},"G2251":{"kjv_def":"our, your (by a different reading)","translit":"hēméteros","lemma":"ἡμέτερος","derivation":"from G2349 (θνητός);","strongs_def":" our","pron":"hay-met'-er-os","thayer":"<ol><li>our, your</li></ol>","xlit":"hēméteros"},"G5293":{"translit":"hypotássō","lemma":"ὑποτάσσω","kjv_def":"be under obedience (obedient), put under, subdue unto, (be, make) subject (to, unto), be (put) in subjection (to, under), submit self unto","strongs_def":" to subordinate; reflexively, to obey","derivation":"from G5259 (ὑπό) and G5021 (τάσσω);","pron":"hoop-ot-as'-so","pos":"Verb","thayer":"<ol><li>to arrange under, to subordinate</li><li>to subject, put in subjection</li><li>to subject one's self, obey</li><li>to submit to one's control</li><li>to yield to one's admonition or advice</li><li>to obey, be subject</li></ol>","xlit":"hypotássō"},"G3500":{"lemma":"νέκρωσις","translit":"nékrōsis","kjv_def":"deadness, dying","strongs_def":" decease; figuratively, impotency","derivation":"from G3499 (νεκρόω);","pron":"nek'-ro-sis","pos":"Noun Feminine","thayer":"<ol><li>putting to death, killing</li><li>being put to death</li><li>the dead state, utter sluggishness<ol type='a'><li>of bodily members and organs</li></ol></li></ol>","xlit":"nékrōsis"},"G3085":{"strongs_def":" a ransoming (figuratively)","derivation":"from G3084 (λυτρόω);","lemma":"λύτρωσις","translit":"lýtrōsis","kjv_def":"+ redeemed, redemption","pron":"loo'-tro-sis","pos":"Noun Feminine","thayer":"<ol><li>a ransoming, redemption</li><li>deliverance, especially from the penalty of sin</li></ol>","xlit":"lýtrōsis"},"G2436":{"kjv_def":"be it far, merciful","lemma":"ἵλεως","translit":"híleōs","derivation":"perhaps from the alternate form of G138 (αἱρέομαι);","strongs_def":" cheerful (as attractive), i.e. propitious; adverbially (by Hebraism) God be gracious!, i.e. (in averting some calamity) far be it","pron":"hil'-eh-oce","pos":"Adjective","thayer":"<ol><li>propitious, merciful</li></ol>","xlit":"híleōs"},"G1981":{"lemma":"ἐπισκηνόω","translit":"episkēnóō","kjv_def":"rest upon","strongs_def":" to tent upon, i.e. (figuratively) abide with ","derivation":"from G1909 (ἐπί) and G4637 (σκηνόω);","pron":"ep-ee-skay-no'-o","pos":"Verb","thayer":"<ol><li>to fix a tent or habitation on<ol type='a'><li>to take possession of and live in the houses<ol><li>of the citizens</li><li>of the power of Christ descending upon one, working within him and giving him help</li></ol></li></ol></li></ol>","xlit":"episkēnóō"},"G1765":{"derivation":"from G1722 (ἐν) and G2480 (ἰσχύω);","strongs_def":" to invigorate (transitively or reflexively)","kjv_def":"strengthen","lemma":"ἐνισχύω","translit":"enischýō","pron":"en-is-khoo'-o","pos":"Verb","thayer":"<ol><li>to grow strong, to receive strength</li><li>to make strong, to strengthen</li></ol>","xlit":"enischýō"},"G2167":{"derivation":"from the same as G2165 (εὐφραίνω);","strongs_def":" joyfulness","kjv_def":"gladness, joy","translit":"euphrosýnē","lemma":"εὐφροσύνη","pron":"yoo-fros-oo'-nay","pos":"Noun Feminine","thayer":"<ol><li>good cheer, joy, gladness</li></ol>","xlit":"euphrosýnē"},"G5366":{"strongs_def":" fond of silver (money), i.e. avaricious","derivation":"from G5384 (φίλος) and G696 (ἄργυρος);","lemma":"φιλάργυρος","translit":"philárgyros","kjv_def":"covetous","pron":"fil-ar'-goo-ros","pos":"Adjective","thayer":"<ol><li>loving money, avarice</li></ol>","xlit":"philárgyros"},"G3754":{"kjv_def":"as concerning that, as though, because (that), for (that), how (that), (in) that, though, why","translit":"hóti","lemma":"ὅτι","derivation":"neuter of G3748 (ὅστις) as conjunction;","strongs_def":" demonstrative, that (sometimes redundant); causative, because","pron":"hot'-ee","pos":"Conjunction","thayer":"<ol><li>that, because, since</li></ol>","xlit":"hóti"},"G5598":{"kjv_def":"Omega","translit":"Ō","lemma":"Ω","strongs_def":"the last letter of the Greek alphabet, i.e. (figuratively) the finality","pron":"o'-meg-ah","pos":"Noun","thayer":"<ol><li>the last letter in the Greek alphabet</li><li>the last</li></ol>","xlit":"Ō"},"G539":{"strongs_def":" delusion","derivation":"from G538 (ἀπατάω);","translit":"apátē","lemma":"ἀπάτη","kjv_def":"deceit(-ful, -fulness), deceivableness(-ving)","pron":"ap-at'-ay","pos":"Noun Feminine","thayer":"<ol><li>deceit, deceitfulness</li></ol>","xlit":"apátē"},"G4061":{"strongs_def":" circumcision (the rite, the condition or the people, literally or figuratively)","derivation":"from G4059 (περιτέμνω);","translit":"peritomḗ","lemma":"περιτομή","kjv_def":"X circumcised, circumcision","pron":"per-it-om-ay'","pos":"Noun Feminine","thayer":"<ol><li>circumcised<ol type='a'><li>the act or rite of circumcision, \"they of the circumcision\" is a term used of the Jews<ol><li>of Christians gathered from among the Jews</li><li>the state of circumcision</li></ol><li>metaphorically<ol><li>of Christians separated from the unclean multitude and truly consecrated to God</li><li>the extinction of passions and the removal of spiritual impurity</li></ol></li></ol></li></ol>","xlit":"peritomḗ"},"G1278":{"lemma":"διαπονέω","translit":"diaponéō","kjv_def":"be grieved","strongs_def":" to toil through, i.e. (passively) be worried","derivation":"from G1223 (διά) and a derivative of G4192 (πόνος);","pron":"dee-ap-on-eh'-o","pos":"Verb","thayer":"<ol><li>to work out laboriously, make complete by labour<ol type='a'><li>to exert one's self, strive</li><li>to manage with pains, accomplish with great labour</li><li>to be troubled, displeased, offended, pained, to be worked up</li></ol></li></ol>","xlit":"diaponéō"},"G5557":{"kjv_def":"gold","translit":"chrysós","lemma":"χρυσός","derivation":"perhaps from the base of G5530 (χράομαι) (through the idea of the utility of the metal);","strongs_def":" gold; by extension, a golden article, as an ornament or coin","pron":"khroo-sos'","pos":"Noun Masculine","thayer":"<ol><li>precious things made of gold, golden ornaments<ol type='a'><li>an image made of gold</li><li>stamped gold, gold coin</li></ol></li></ol>","xlit":"chrysós"},"G5294":{"strongs_def":" to place underneath, i.e. (figuratively) to hazard, (reflexively) to suggest","derivation":"from G5259 (ὑπό) and G5087 (τίθημι);","lemma":"ὑποτίθημι","translit":"hypotíthēmi","kjv_def":"lay down, put in remembrance","pron":"hoop-ot-ith'-ay-mee","pos":"Verb","thayer":"<ol><li>to place under</li><li>metaphorically to supply, suggest (supply from one's own resources)</li></ol>","xlit":"hypotíthēmi"},"G1524":{"derivation":"from G1519 (εἰς) and (to go);","strongs_def":" to enter","kjv_def":"enter (go) into","translit":"eíseimi","lemma":"εἴσειμι","pron":"ice'-i-mee","pos":"Verb","thayer":"<ol><li>to go into, enter</li></ol>","xlit":"eíseimi"},"G4617":{"strongs_def":" to riddle (figuratively)","derivation":"from (a sieve);","lemma":"σινιάζω","translit":"siniázō","kjv_def":"sift","pron":"sin-ee-ad'-zo","pos":"Verb","thayer":"<ol><li>to sift, shake in a sieve</li><li>fig. by inward agitation to try one's faith to the verge of overthrow</li></ol>","xlit":"siniázō"},"G2081":{"translit":"ésōthen","lemma":"ἔσωθεν","kjv_def":"inward(-ly), (from) within, without","strongs_def":" from inside; also used as equivalent to G2080 (ἔσω) (inside)","derivation":"from G2080 (ἔσω);","pron":"es'-o-then","pos":"Adverb","thayer":"<ol><li>from within</li><li>within, that which is within, the inside<ol type='a'><li>your soul</li></ol></li></ol>","xlit":"ésōthen"},"G2438":{"derivation":"perhaps from the same as G260 (ἅμα);","strongs_def":" a strap, i.e. (specially) the tie (of a sandal) or the lash (of a scourge)","kjv_def":"latchet, thong","translit":"himás","lemma":"ἱμάς","pron":"hee-mas'","pos":"Noun Masculine","thayer":"<ol><li>a thong of leather, a strap<ol type='a'><li>in the NT of the thongs with which captives or criminals were either bound or beaten</li><li>of the thongs or ties by which sandals were fastened to the feet</li></ol></li></ol>","xlit":"himás"},"G3653":{"kjv_def":"untimely fig","translit":"ólynthos","lemma":"ὄλυνθος","derivation":"of uncertain derivation;","strongs_def":" an unripe (because out of season) fig","pron":"ol'-oon-thos","pos":"Noun Masculine","thayer":"<ol><li>an unripe fig which grows during the winter, yet does not come to maturity but falls off in the spring</li></ol>","xlit":"ólynthos"},"G825":{"derivation":"from (a king of Pergamus);","strongs_def":" Attaleia, a place in Pamphylia","kjv_def":"Attalia","translit":"Attáleia","lemma":"Ἀττάλεια","pron":"at-tal'-i-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Attalia = \"Jah's due season\"</p><ol><li>a maritime city of Pamphylia in Asia, very near the borders of Lycia, built and named by Attalus Philadelphus, king of Pergamos, now called Antali</li></ol>","xlit":"Attáleia"},"G22":{"derivation":"from G1 (Α) (as a negative particle) and G1062 (γάμος);","strongs_def":" unmarried","kjv_def":"unmarried","lemma":"ἄγαμος","translit":"ágamos","pron":"ag'-am-os","pos":"Adjective","thayer":"<ol><li>unmarried, unwedded, single</li></ol>","xlit":"ágamos"},"G2768":{"strongs_def":" a horn (literally or figuratively)","derivation":"from a primary (the hair of the head);","translit":"kéras","lemma":"κέρας","kjv_def":"horn","pron":"ker'-as","pos":"Noun Neuter","thayer":"<ol><li>a horn<ol type='a'><li>of animals</li><li>since animals (especially bulls) defend themselves with their horns, the horn with the Hebrews (and other nations) is a symbol of strength and courage, and used as such in a variety of phrases<ol><li>a mighty and valiant helper, the author of deliverance, of the Messiah</li></ol><li>a projecting extremity in a shape like a horn, a point, apex: as of an altar</li></ol></li></ol>","xlit":"kéras"},"G3663":{"lemma":"ὁμοιοπαθής","translit":"homoiopathḗs","kjv_def":"of (subject to) like passions","strongs_def":" similarly affected","derivation":"from G3664 (ὅμοιος) and the alternate of G3958 (πάσχω);","pron":"hom-oy-op-ath-ace'","pos":"Adjective","thayer":"<ol><li>suffering the like with another, of like feelings or affections</li></ol>","xlit":"homoiopathḗs"},"G1788":{"derivation":"from G1722 (ἐν) and the base of G5157 (τροπή);","strongs_def":" to invert, i.e. (figuratively and reflexively) in a good sense, to respect; or in a bad one, to confound","kjv_def":"regard, (give) reference, shame","translit":"entrépō","lemma":"ἐντρέπω","pron":"en-trep'-o","pos":"Verb","thayer":"<ol><li>to shame one</li><li>to be ashamed</li><li>to reverence a person</li><li>to turn about</li></ol>","xlit":"entrépō"},"G197":{"strongs_def":" (adverbially) more exactly","derivation":"neuter of the comparative of the same as G196 (ἀκριβέστατος);","translit":"akribésteron","lemma":"ἀκριβέστερον","kjv_def":"more perfect(-ly)","pron":"ak-ree-bes'-ter-on","pos":"Adjective","thayer":"<ol><li>more exactly, more perfectly</li></ol>","xlit":"akribésteron"},"G2890":{"strongs_def":" Quartus, a Christian","derivation":"of Latin origin (fourth);","lemma":"Κούαρτος","translit":"Koúartos","kjv_def":"Quartus","pron":"koo'-ar-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Quartus = \"fourth\"</p><ol><li>a Roman; probably before he lived at Rome, and therefore sends his salutations to the Christians there: he is mentioned among the seventy disciples, and said to be bishop of Berytus. (Gill)</li></ol>","xlit":"Koúartos"},"G3865":{"kjv_def":"neglect","translit":"paratheōréō","lemma":"παραθεωρέω","derivation":"from G3844 (παρά) and G2334 (θεωρέω);","strongs_def":" to overlook or disregard","pron":"par-ath-eh-o-reh'-o","pos":"Verb","thayer":"<ol><li>to examine things placed beside each other, to compare</li><li>to overlook, neglect</li></ol>","xlit":"paratheōréō"},"G2217":{"kjv_def":"blackness, darkness, mist","translit":"zóphos","lemma":"ζόφος","derivation":"akin to the base of G3509 (νέφος);","strongs_def":" gloom (as shrouding like a cloud)","pron":"dzof'-os","pos":"Noun Masculine","thayer":"<ol><li>darkness, blackness<ol type='a'><li>used of the darkness of the nether world</li></ol></li></ol>","xlit":"zóphos"},"G2027":{"kjv_def":"run aground","translit":"epokéllō","lemma":"ἐποκέλλω","derivation":"from G1909 (ἐπί) and (to urge);","strongs_def":" to drive upon the shore, i.e. to beach a vessel","pron":"ep-ok-el'-lo","pos":"Verb","thayer":"<ol><li>to drive upon, strike against<ol type='a'><li>to run a ship aground</li></ol></li></ol>","xlit":"epokéllō"},"G4470":{"derivation":"from G4486 (ῥήγνυμι);","strongs_def":" a \"rag,\" i.e. piece of cloth","kjv_def":"cloth","lemma":"ῥάκος","translit":"rhákos","pron":"hrak'-os","pos":"Noun Neuter","thayer":"<ol><li>a piece torn off</li><li>a bit of cloth</li><li>cloth</li></ol>","xlit":"rhákos"},"G543":{"derivation":"from G545 (ἀπειθής);","strongs_def":" disbelief (obstinate and rebellious)","kjv_def":"disobedience, unbelief","translit":"apeítheia","lemma":"ἀπείθεια","pron":"ap-i'-thi-ah","pos":"Noun Feminine","thayer":"<ol><li>obstinacy, obstinate opposition to the divine will</li></ol>","xlit":"apeítheia"},"G1230":{"derivation":"from G1223 (διά) and G1096 (γίνομαι);","strongs_def":" to elapse meanwhile","kjv_def":"X after, be past, be spent","lemma":"διαγίνομαι","translit":"diagínomai","pron":"dee-ag-in'-om-ahee","pos":"Verb","thayer":"<ol><li>to be through, continue</li><li>to be between, intervene, used of time, to have intervened, elapsed, passed meanwhile</li></ol>","xlit":"diagínomai"},"G1953":{"kjv_def":"X forgetful","translit":"epilēsmonḗ","lemma":"ἐπιλησμονή","derivation":"from a derivative of G1950 (ἐπιλανθάνομαι);","strongs_def":" negligence","pron":"ep-ee-lace-mon-ay'","pos":"Noun Feminine","thayer":"<ol><li>forgetfulness</li></ol>","xlit":"epilēsmonḗ"},"G4170":{"kjv_def":"fight, (make) war","lemma":"πολεμέω","translit":"poleméō","derivation":"from G4171 (πόλεμος);","strongs_def":" to be (engaged) in warfare, i.e. to battle (literally or figuratively)","pron":"pol-em-eh'-o","pos":"Verb","thayer":"<ol><li>to war, carry on war</li><li>to fight</li></ol>","xlit":"poleméō"},"G5297":{"kjv_def":"bear, endure","lemma":"ὑποφέρω","translit":"hypophérō","derivation":"from G5259 (ὑπό) and G5342 (φέρω);","strongs_def":" to bear from underneath, i.e. (figuratively) to undergo hardship","pron":"hoop-of-er'-o","pos":"Verb","thayer":"<ol><li>to bear by being under, bear up (a thing placed on one's shoulders)</li><li>to bear patiently, to endure</li></ol>","xlit":"hypophérō"},"G1244":{"strongs_def":" to separate, i.e. distribute","derivation":"from G1223 (διά) and G138 (αἱρέομαι);","translit":"diairéō","lemma":"διαιρέω","kjv_def":"divide","pron":"dee-ahee-reh'-o","pos":"Verb","thayer":"<ol><li>to divide into parts, to part, to tear, cleave or cut asunder</li><li>to distribute</li></ol>","xlit":"diairéō"},"G4021":{"kjv_def":"busybody, curious arts","translit":"períergos","lemma":"περίεργος","derivation":"from G4012 (περί) and G2041 (ἔργον);","strongs_def":" working all around, i.e. officious (meddlesome, neuter plural magic)","pron":"per-ee'-er-gos","pos":"Adjective","thayer":"<ol><li>busy about trifles and neglectful of important matters<ol type='a'><li>especially busy about other folks' affairs, a busybody</li><li>of things: impertinent and superfluous<ol><li>of magic arts</li></ol></li></ol></li></ol>","xlit":"períergos"},"G3922":{"strongs_def":" to come in alongside, i.e. supervene additionally or steathily","derivation":"from G3844 (παρά) and G1525 (εἰσέρχομαι);","lemma":"παρεισέρχομαι","translit":"pareisérchomai","kjv_def":"come in privily, enter","pron":"par-ice-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to come in secretly or by stealth, or creep or steal in</li><li>to enter in addition, come in besides</li></ol>","xlit":"pareisérchomai"},"G867":{"kjv_def":"departing","lemma":"ἄφιξις","translit":"áphixis","derivation":"from G864 (ἀφικνέομαι);","strongs_def":" properly, arrival, i.e. (by implication) departure","pron":"af'-ix-is","pos":"Noun Feminine","thayer":"<ol><li>arrival</li><li>departure</li></ol>","xlit":"áphixis"},"G4570":{"lemma":"σβέννυμι","translit":"sbénnymi","kjv_def":"go out, quench","strongs_def":" to extinguish (literally or figuratively)","derivation":"a prolonged form of an apparently primary verb;","pron":"sben'-noo-mee","pos":"Verb","thayer":"<ol><li>to extinguish, quench<ol type='a'><li>of fire or things on fire<ol><li>to be quenched, to go out</li></ol><li>metaphorically to quench, to suppress, stifle<ol><li>of divine influence</li></ol></li></ol></li></ol>","xlit":"sbénnymi"},"G5101":{"kjv_def":"every man, how (much), + no(-ne, thing), what (manner, thing), where (-by, -fore, -of, -unto, - with, -withal), whether, which, who(-m, -se), why","translit":"tís","lemma":"τίς","derivation":"probably emphatic of G5100 (τὶς);","strongs_def":" an interrogative pronoun, who, which or what (in direct or indirect questions)","pron":"tis","thayer":"<ol><li>who, which, what</li></ol>","xlit":"tís"},"G2162":{"kjv_def":"good report","lemma":"εὐφημία","translit":"euphēmía","derivation":"from G2163 (εὔφημος);","strongs_def":" good language (\"euphemy\"), i.e. praise (repute)","pron":"yoo-fay-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the utterance of good or auspicious words</li><li>good report, praise</li></ol>","xlit":"euphēmía"},"G3842":{"derivation":"from G3956 (πᾶς) and G3753 (ὅτε);","strongs_def":" every when, i.e. at all times","kjv_def":"alway(-s), ever(-more)","lemma":"πάντοτε","translit":"pántote","pron":"pan'-tot-eh","pos":"Adverb","thayer":"<ol><li>at all times, always, ever</li></ol>","xlit":"pántote"},"G5483":{"strongs_def":" to grant as a favor, i.e. gratuitously, in kindness, pardon or rescue","derivation":"middle voice from G5485 (χάρις);","translit":"charízomai","lemma":"χαρίζομαι","kjv_def":"deliver, (frankly) forgive, (freely) give, grant","pron":"khar-id'-zom-ahee","pos":"Verb","thayer":"<ol><li>to do something pleasant or agreeable (to one), to do a favour to, gratify<ol type='a'><li>to show one's self gracious, kind, benevolent</li><li>to grant forgiveness, to pardon</li><li>to give graciously, give freely, bestow<ol><li>to forgive</li><li>graciously to restore one to another</li><li>to preserve for one a person in peril</li></ol></li></ol></li></ol>","xlit":"charízomai"},"G4135":{"derivation":"from G4134 (πλήρης) and G5409 (φορέω);","strongs_def":" to carry out fully (in evidence), i.e. completely assure (or convince), entirely accomplish","kjv_def":"most surely believe, fully know (persuade), make full proof of","lemma":"πληροφορέω","translit":"plērophoréō","pron":"play-rof-or-eh'-o","pos":"Verb","thayer":"<ol><li>to bear or bring full, to make full<ol type='a'><li>to cause a thing to be shown to the full<ol><li>to fulfil the ministry in every part</li></ol><li>to carry through to the end, accomplish<ol><li>things that have been accomplished</li></ol><li>to fill one with any thought, conviction, or inclination<ol><li>to make one certain, to persuade, convince one</li><li>to be persuaded, persuaded, fully convinced or assured</li><li>to render inclined or bent on</li></ol></li></ol></li></ol>","xlit":"plērophoréō"},"G4885":{"derivation":"from G4862 (σύν) and G837 (αὐξάνω);","strongs_def":" to increase (grow up) together","kjv_def":"grow together","lemma":"συναυξάνω","translit":"synauxánō","pron":"soon-owx-an'-o","pos":"Verb","thayer":"<ol><li>to cause to grow together</li><li>to grow together</li></ol>","xlit":"synauxánō"},"G1971":{"kjv_def":"(earnestly) desire (greatly), (greatly) long (after), lust","lemma":"ἐπιποθέω","translit":"epipothéō","derivation":"from G1909 (ἐπί) and potheo (to yearn);","strongs_def":" to dote upon, i.e. intensely crave possession (lawfully or wrongfully)","pron":"ep-ee-poth-eh'-o","pos":"Verb","thayer":"<ol><li>to long for, desire</li><li>to pursue with love, to long after</li><li>to lust, harbour forbidden desire</li></ol>","xlit":"epipothéō"},"G4446":{"translit":"pyretós","lemma":"πυρετός","kjv_def":"fever","strongs_def":" inflamed, i.e. (by implication) feverish (as noun, fever)","derivation":"from G4445 (πυρέσσω);","pron":"poo-ret-os'","pos":"Noun Masculine","thayer":"<ol><li>fiery heat</li><li>fever</li></ol>","xlit":"pyretós"},"G3362":{"derivation":"i.e. G1437 (ἐάν) and G3361 (μή);","strongs_def":" if not, i.e. unless","kjv_def":"X before, but, except, if, no, (if, + whosoever) not","lemma":"ἐὰν μή","translit":"eàn mḗ","pron":"eh-an' may","pos":"Conjunction","thayer":"<ol><li>if not, unless, whoever ... not</li></ol>","xlit":"eàn mḗ"},"G3819":{"kjv_def":"any while, a great while ago, (of) old, in time past","translit":"pálai","lemma":"πάλαι","derivation":"probably another form for G3825 (πάλιν) (through the idea of retrocession);","strongs_def":" (adverbially) formerly, or (by relatively) sometime since; (elliptically as adjective) ancient","pron":"pal'-ahee","pos":"Adverb","thayer":"<ol><li>of old, former</li><li>long ago</li></ol>","xlit":"pálai"},"G705":{"derivation":"from G706 (ἀριθμός);","strongs_def":" to enumerate or count","kjv_def":"number","translit":"arithméō","lemma":"ἀριθμέω","pron":"ar-ith-meh'-o","pos":"Verb","thayer":"<ol><li>to number</li></ol>","xlit":"arithméō"},"G701":{"derivation":"from G700 (ἀρέσκω);","strongs_def":" agreeable; by implication, fit","kjv_def":"(things that) please(-ing), reason","lemma":"ἀρεστός","translit":"arestós","pron":"ar-es-tos'","pos":"Adjective","thayer":"<ol><li>pleasing, agreeable</li></ol>","xlit":"arestós"},"G5418":{"derivation":"from G5420 (φράσσω);","strongs_def":" a fence, or inclosing barrier (literally or figuratively)","kjv_def":"hedge (+ round about), partition","translit":"phragmós","lemma":"φραγμός","pron":"frag-mos'","pos":"Noun Masculine","thayer":"<ol><li>a hedge, a fence</li><li>that which separates, prevents two from coming together</li></ol>","xlit":"phragmós"},"G889":{"kjv_def":"become unprofitable","translit":"achreióō","lemma":"ἀχρειόω","derivation":"from G888 (ἀχρεῖος);","strongs_def":" to render useless, i.e. spoil","pron":"akh-ri-o'-o","pos":"Verb","thayer":"<ol><li>make useless, render unserviceable<ol type='a'><li>of character</li></ol></li></ol>","xlit":"achreióō"},"G1135":{"kjv_def":"wife, woman","lemma":"γυνή","translit":"gynḗ","derivation":"probably from the base of G1096 (γίνομαι);","strongs_def":" a woman; specially, a wife","pron":"goo-nay'","pos":"Noun Feminine","thayer":"<ol><li>a woman of any age, whether a virgin, or married, or a widow</li><li>a wife<ol type='a'><li>of a betrothed woman</li></ol></li></ol>","xlit":"gynḗ"},"G4175":{"kjv_def":"conversation","lemma":"πολίτευμα","translit":"políteuma","derivation":"from G4176 (πολιτεύομαι);","strongs_def":" a community, i.e. (abstractly) citizenship (figuratively)","pron":"pol-it'-yoo-mah","pos":"Noun Neuter","thayer":"<ol><li>the administration of civil affairs or of a commonwealth</li><li>the constitution of a commonwealth, form of government and the laws by which it is administered</li><li>a state, commonwealth<ol type='a'><li>the commonwealth of citizens</li></ol></li></ol>","xlit":"políteuma"},"G719":{"strongs_def":" an articulation (of the body)","derivation":"from the same as G716 (ἅρμα);","translit":"harmós","lemma":"ἁρμός","kjv_def":"joint","pron":"har-mos'","pos":"Noun Masculine","thayer":"<ol><li>a joining, a joint</li></ol>","xlit":"harmós"},"G1622":{"strongs_def":" the exterior; figuratively (as a preposition) aside from, besides","derivation":"from G1537 (ἐκ);","lemma":"ἐκτός","translit":"ektós","kjv_def":"but, except(-ed), other than, out of, outside, unless, without","pron":"ek-tos'","pos":"Adverb","thayer":"<ol><li>outside, beyond</li><li>the outside, exterior</li><li>outside of</li><li>beyond, besides, except</li></ol>","xlit":"ektós"},"G2419":{"kjv_def":"Jerusalem","lemma":"Ἱερουσαλήμ","translit":"Hierousalḗm","derivation":"of Hebrew origin (H03389);","strongs_def":" Hierusalem (i.e. Jerushalem), the capitol of Palestine","pron":"hee-er-oo-sal-ame'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Jerusalem = \"set ye double peace\"</p><ol><li>denotes either the city itself or the inhabitants</li><li>\"the Jerusalem that now is\" , with its present religious institutions, i.e. the Mosaic system, so designated from its primary external location</li><li>\"Jerusalem that is above\" , that is existing in heaven, according to the pattern of which the earthly Jerusalem was supposed to be built<ol type='a'><li>metaphorically \"the City of God founded by Christ\" , now wearing the form of the church, but after Christ's return to put on the form of the perfected Messianic kingdom</li></ol><li>\"the heavenly Jerusalem\" , that is the heavenly abode of God, Christ, the angels, saints of the Old and New Testament periods and those Christians that are alive at Christ's return</li><li>\"the New Jerusalem\" , a splendid visible city to be let down from heaven after the renovation of the world, the future abode of the blessed</li></ol>","xlit":"Hierousalḗm"},"G1450":{"strongs_def":" pledged (as if articulated by a member), i.e. a bondsman","derivation":"from G1722 (ἐν) and (a limb);","lemma":"ἔγγυος","translit":"éngyos","kjv_def":"surety","pron":"eng'-goo-os","pos":"Adjective","thayer":"<ol><li>a surety, a sponsor</li></ol>","xlit":"éngyos"},"G1776":{"strongs_def":" to crowd in, i.e. (figuratively) to annoy","derivation":"from G1722 (ἐν) and G3791 (ὀχλέω);","lemma":"ἐνοχλέω","translit":"enochléō","kjv_def":"trouble","pron":"en-okh-leh'-o","pos":"Verb","thayer":"<ol><li>to excite, disturbance, to trouble, annoy</li></ol>","xlit":"enochléō"},"G3678":{"kjv_def":"young ass","translit":"onárion","lemma":"ὀνάριον","derivation":"neuter of a presumed derivative of G3688 (ὄνος);","strongs_def":" a little ass","pron":"on-ar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a little ass</li></ol>","xlit":"onárion"},"G1202":{"lemma":"δεσμώτης","translit":"desmṓtēs","kjv_def":"prisoner","strongs_def":" (passively) a captive","derivation":"from the same as G1201 (δεσμωτήριον);","pron":"des-mo'-tace","pos":"Noun Masculine","thayer":"<ol><li>one bound, a prisoner</li></ol>","xlit":"desmṓtēs"},"G538":{"translit":"apatáō","lemma":"ἀπατάω","kjv_def":"deceive","strongs_def":" to cheat, i.e. delude","derivation":"of uncertain derivation;","pron":"ap-at-ah'-o","pos":"Verb","thayer":"<ol><li>to cheat, beguile, deceive</li></ol>","xlit":"apatáō"},"G3722":{"strongs_def":" dawn (as sun-rise, rising of light); by extension, morn","derivation":"from the same as G3735 (ὄρος);","lemma":"ὄρθρος","translit":"órthros","kjv_def":"early in the morning","pron":"or'-thros","pos":"Noun Masculine","thayer":"<ol><li>daybreak, dawn</li><li>at early dawn, at daybreak, early in the morning</li></ol>","xlit":"órthros"},"G5607":{"derivation":"present participle of G1510 (εἰμί);","strongs_def":" being","kjv_def":"be, come, have","lemma":"ὤν","translit":"ṓn","pron":"oan","pos":"Verb","thayer":"<ol><li>being, etc.</li></ol>","xlit":"ṓn"},"G656":{"strongs_def":" excommunicated","derivation":"from G575 (ἀπό) and G4864 (συναγωγή);","translit":"aposynágōgos","lemma":"ἀποσυνάγωγος","kjv_def":"(put) out of the synagogue(-s)","pron":"ap-os-oon-ag'-o-gos","pos":"Adjective","thayer":"<ol><li>excluded from sacred assemblies of Israelites, excommunicated</li></ol>","xlit":"aposynágōgos"},"G5444":{"strongs_def":" a sprout, i.e. leaf","derivation":"from the same as G5443 (φυλή);","translit":"phýllon","lemma":"φύλλον","kjv_def":"leaf","pron":"fool'-lon","pos":"Noun Neuter","thayer":"<ol><li>a leaf</li></ol>","xlit":"phýllon"},"G4251":{"kjv_def":"Prisca","lemma":"Πρίσκα","translit":"Príska","derivation":"of Latin origin;","strongs_def":" feminine of Priscus, ancient; Priska, a Christian woman","pron":"pris'-kah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Priscilla = \"ancient\"</p><ol><li>a Christian woman, the wife of Aquila</li></ol>","xlit":"Príska"},"G5197":{"derivation":"from G5195 (ὑβρίζω);","strongs_def":" an insulter, i.e. maltreater","kjv_def":"despiteful, injurious","lemma":"ὑβριστής","translit":"hybristḗs","pron":"hoo-bris-tace'","pos":"Noun Masculine","thayer":"<ol><li>an insolent man</li><li>one who, uplifted with pride, either heaps insulting language upon others or does them some shameful act of wrong</li></ol>","xlit":"hybristḗs"},"G2673":{"translit":"katargéō","lemma":"καταργέω","kjv_def":"abolish, cease, cumber, deliver, destroy, do away, become (make) of no (none, without) effect, fail, loose, bring (come) to nought, put away (down), vanish away, make void","strongs_def":" to be (render) entirely idle (useless), literally or figuratively","derivation":"from G2596 (κατά) and G691 (ἀργέω);","pron":"kat-arg-eh'-o","pos":"Verb","thayer":"<ol><li>to render idle, unemployed, inactivate, inoperative<ol type='a'><li>to cause a person or thing to have no further efficiency</li><li>to deprive of force, influence, power</li></ol><li>to cause to cease, put an end to, do away with, annul, abolish<ol type='a'><li>to cease, to pass away, be done away</li><li>to be severed from, separated from, discharged from, loosed from any one</li><li>to terminate all intercourse with one</li></ol></li></ol>","xlit":"katargéō"},"G5108":{"kjv_def":"like, such (an one)","translit":"toioûtos","lemma":"τοιοῦτος","derivation":"(including the other inflections); from G5104 (τοί) and G3778 (οὗτος);","strongs_def":" truly this, i.e. of this sort (to denote character or individuality)","pron":"toy-oo'-tos","pos":"Adjective","thayer":"<ol><li>such as this, of this kind or sort</li></ol>","xlit":"toioûtos"},"G2884":{"strongs_def":" a cor, i.e. a specific measure","derivation":"of Hebrew origin (H03734);","lemma":"κόρος","translit":"kóros","kjv_def":"measure","pron":"kor'-os","pos":"Noun Masculine","thayer":"<ol><li>a corus or cor, the largest Hebrew dry measure (i.e, for wheat, meal etc.) about 10 to 11 bushels (350 to 400 l)</li></ol>","xlit":"kóros"},"G5163":{"derivation":"from G5164 (τροχός);","strongs_def":" a track (as a wheel-rut), i.e. (figuratively) a course of conduct","kjv_def":"path","translit":"trochiá","lemma":"τροχιά","pron":"trokh-ee-ah'","pos":"Noun Feminine","thayer":"<ol><li>a track of a wheel, a rut</li><li>a track, a path</li></ol>","xlit":"trochiá"},"G4404":{"kjv_def":"early (in the morning), (in the) morning","translit":"prōḯ","lemma":"πρωΐ","derivation":"adverb from G4253 (πρό);","strongs_def":" at dawn; by implication, the day-break watch","pron":"pro-ee'","pos":"Adverb","thayer":"<ol><li>in the morning, early</li><li>the fourth watch of the night, from 3 o'clock in the morning until 6 o'clock approximately</li></ol>","xlit":"prōḯ"},"G3446":{"kjv_def":"form","lemma":"μόρφωσις","translit":"mórphōsis","derivation":"from G3445 (μορφόω);","strongs_def":" formation, i.e. (by implication), appearance (semblance or (concretely) formula)","pron":"mor'-fo-sis","pos":"Noun Feminine","thayer":"<ol><li>a forming, shaping</li><li>form<ol type='a'><li>the mere form, semblance</li><li>the form befitting a thing or truly expressing the fact, the very form</li></ol></li></ol>","xlit":"mórphōsis"},"G1338":{"derivation":"from G1223 (διά) and the base of G2425 (ἱκανός);","strongs_def":" to reach through, i.e. penetrate","kjv_def":"pierce","translit":"diïknéomai","lemma":"διϊκνέομαι","pron":"dee-ik-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to go through, penetrate, pierce</li></ol>","xlit":"diïknéomai"},"G4939":{"strongs_def":" a fellow-nursling, i.e. comrade","derivation":"from G4862 (σύν) and G5162 (τροφός) (in a passive sense);","translit":"sýntrophos","lemma":"σύντροφος","kjv_def":"brought up with","pron":"soon'-trof-os","pos":"Adjective","thayer":"<ol><li>nourished with one</li><li>brought up with one</li><li>companion of one's childhood and youth</li></ol>","xlit":"sýntrophos"},"G4139":{"kjv_def":"near, neighbour","translit":"plēsíon","lemma":"πλησίον","derivation":"neuter of a derivative of (near);","strongs_def":" (adverbially) close by; as noun, a neighbor, i.e. fellow (as man, countryman, Christian or friend)","pron":"play-see'-on","pos":"Adverb","thayer":"<ol><li>a neighbour<ol type='a'><li>a friend</li><li>any other person, and where two are concerned, the other (thy fellow man, thy neighbour), according to the Jews, any member of the Hebrew nation and commonwealth</li><li>according to Christ, any other man irrespective of nation or religion with whom we live or whom we chance to meet</li></ol></li></ol>","xlit":"plēsíon"},"G4727":{"derivation":"from G4728 (στενός);","strongs_def":" to make (intransitively, be) in straits, i.e. (by implication) to sigh, murmur, pray inaudibly","kjv_def":"with grief, groan, grudge, sigh","lemma":"στενάζω","translit":"stenázō","pron":"sten-ad'-zo","pos":"Verb","thayer":"<ol><li>a sigh, to groan</li></ol>","xlit":"stenázō"},"G3614":{"translit":"oikía","lemma":"οἰκία","kjv_def":"home, house(-hold)","strongs_def":" properly, residence (abstractly), but usually (concretely) an abode (literally or figuratively); by implication, a family (especially domestics)","derivation":"from G3624 (οἶκος);","pron":"oy-kee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a house<ol type='a'><li>an inhabited edifice, a dwelling</li><li>the inmates of a house, the family</li><li>property, wealth, goods</li></ol></li></ol>","xlit":"oikía"},"G3530":{"lemma":"Νικόδημος","translit":"Nikódēmos","kjv_def":"Nicodemus","strongs_def":" victorious among his people; Nicodemus, an Israelite","derivation":"from G3534 (νῖκος) and G1218 (δῆμος);","pron":"nik-od'-ay-mos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nicodemus = \"conqueror\"</p><ol><li>a member of the Sanhedrin who took the part of Jesus</li></ol>","xlit":"Nikódēmos"},"G313":{"kjv_def":"beget, (bear) X (again)","translit":"anagennáō","lemma":"ἀναγεννάω","derivation":"from G303 (ἀνά) and G1080 (γεννάω);","strongs_def":" to beget or (by extension) bear (again)","pron":"an-ag-en-nah'-o","pos":"Verb","thayer":"<ol><li>to produce again, be born again, born anew</li><li>metaphorically to have one's mind changed so that he lives a new life and one conformed to the will of God</li></ol>","xlit":"anagennáō"},"G1168":{"translit":"deiliáō","lemma":"δειλιάω","kjv_def":"be afraid","strongs_def":" to be timid","derivation":"from G1167 (δειλία);","pron":"di-lee-ah'-o","pos":"Verb","thayer":"<ol><li>to be timid, fearful</li></ol>","xlit":"deiliáō"},"G3796":{"lemma":"ὀψέ","translit":"opsé","kjv_def":"(at) even, in the end","strongs_def":" (adverbially) late in the day; by extension, after the close of the day","derivation":"from the same as G3694 (ὀπίσω) (through the idea of backwardness);","pron":"op-seh'","thayer":"<ol><li>after a long time, long after, late<ol type='a'><li>late in the day, i.e. at evening</li><li>the sabbath having just passed, after the sabbath<ol><li>at the early dawn of the first day of the week</li></ol></li></ol></li></ol>","xlit":"opsé"},"G2605":{"strongs_def":" to proclaim, promulgate","derivation":"from G2596 (κατά) and the base of G32 (ἄγγελος);","lemma":"καταγγέλλω","translit":"katangéllō","kjv_def":"declare, preach, shew, speak of, teach","pron":"kat-ang-gel'-lo","pos":"Verb","thayer":"<ol><li>to announce, declare, promulgate, make known</li><li>to proclaim publicly, publish</li><li>to denounce, report, betray</li></ol>","xlit":"katangéllō"},"G2498":{"derivation":"of Hebrew origin (H03092);","strongs_def":" Josaphat (i.e. Jehoshaphat), an Israelite","kjv_def":"Josaphat","lemma":"Ἰωσαφάτ","translit":"Iōsaphát","pron":"ee-o-saf-at'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jehoshaphat = \"whom Jehovah judges\"</p><ol><li>the king of Judah, son of Asa</li></ol>","xlit":"Iōsaphát"},"G362":{"lemma":"ἀναμένω","translit":"anaménō","kjv_def":"wait for","strongs_def":" to await","derivation":"from G303 (ἀνά) and G3306 (μένω);","pron":"an-am-en'-o","pos":"Verb","thayer":"<ol><li>to wait for one (with the added notion of patience and trust)</li></ol>","xlit":"anaménō"},"G5251":{"kjv_def":"highly exalt","lemma":"ὑπερυψόω","translit":"hyperypsóō","derivation":"from G5228 (ὑπέρ) and G5312 (ὑψόω);","strongs_def":" to elevate above others, i.e. raise to the highest position","pron":"hoop-er-oop-so'-o","pos":"Verb","thayer":"<ol><li>metaphorically to exalt to the highest rank and power, raise to supreme majesty</li><li>to extol most highly</li><li>to be lifted up with pride, exalted beyond measure</li><li>to carry one's self loftily</li></ol>","xlit":"hyperypsóō"},"G2200":{"strongs_def":" boiled, i.e. (by implication) calid (figuratively, fervent)","derivation":"from G2204 (ζέω);","translit":"zestós","lemma":"ζεστός","kjv_def":"hot","pron":"dzes-tos'","pos":"Adjective","thayer":"<ol><li>boiling hot, hot</li><li>metaphorically of fervour of mind an zeal</li></ol>","xlit":"zestós"},"G4013":{"kjv_def":"compass, go (round) about, lead about","translit":"periágō","lemma":"περιάγω","derivation":"from G4012 (περί) and G71 (ἄγω);","strongs_def":" to take around (as a companion); reflexively, to walk around","pron":"per-ee-ag'-o","pos":"Verb","thayer":"<ol><li>to lead around, to lead about with one's self</li><li>to go about, walk about</li></ol>","xlit":"periágō"},"G4678":{"kjv_def":"wisdom","translit":"sophía","lemma":"σοφία","derivation":"from G4680 (σοφός);","strongs_def":" wisdom (higher or lower, worldly or spiritual)","pron":"sof-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>wisdom, broad and full of intelligence; used of the knowledge of very diverse matters<ol type='a'><li>the wisdom which belongs to men<ol><li>spec. the varied knowledge of things human and divine, acquired by acuteness and experience, and summed up in maxims and proverbs</li><li>the science and learning</li><li>the act of interpreting dreams and always giving the sagest advice</li><li>the intelligence evinced in discovering the meaning of some mysterious number or vision</li><li>skill in the management of affairs</li><li>devout and proper prudence in intercourse with men not disciples of Christ, skill and discretion in imparting Christian truth</li><li>the knowledge and practice of the requisites for godly and upright living</li></ol><li>supreme intelligence, such as belongs to God<ol><li>to Christ</li><li>the wisdom of God as evinced in forming and executing counsels in the formation and government of the world and the scriptures</li></ol></li></ol></li></ol>","xlit":"sophía"},"G342":{"strongs_def":" renovation","derivation":"from G341 (ἀνακαινόω);","lemma":"ἀνακαίνωσις","translit":"anakaínōsis","kjv_def":"renewing","pron":"an-ak-ah'-ee-no-sis","pos":"Noun Feminine","thayer":"<ol><li>a renewal, renovation, complete change for the better</li></ol>","xlit":"anakaínōsis"},"G1542":{"strongs_def":" a hundred times","derivation":"from G1540 (ἑκατόν) and a presumed derivative of G4111 (πλάσσω);","translit":"hekatontaplasíōn","lemma":"ἑκατονταπλασίων","kjv_def":"hundredfold","pron":"hek-at-on-ta-plah-sec'-own","pos":"Adjective","thayer":"<ol><li>hundredfold, a hundred times as much</li></ol>","xlit":"hekatontaplasíōn"},"G2075":{"translit":"esté","lemma":"ἐστέ","kjv_def":"be, have been, belong","strongs_def":" ye are","derivation":"second person plural present indicative of G1510 (εἰμί);","pron":"es-teh'","pos":"Verb","thayer":"<ol><li>second person plural of \"to be\"</li></ol>","xlit":"esté"},"G1133":{"derivation":"a diminutive from G1135 (γυνή);","strongs_def":" a little (i.e. foolish) woman","kjv_def":"silly woman","lemma":"γυναικάριον","translit":"gynaikárion","pron":"goo-nahee-kar'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a little woman: used contemptuously</li></ol>","xlit":"gynaikárion"},"G2195":{"strongs_def":" Zacchæus, an Israelite","derivation":"of Hebrew origin (compare H02140);","lemma":"Ζακχαῖος","translit":"Zakchaîos","kjv_def":"Zacchæus","pron":"dzak-chah'-ee-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Zacchaeus = \"pure\"</p><ol><li>a chief tax collector</li></ol>","xlit":"Zakchaîos"},"G4788":{"kjv_def":"conclude, inclose, shut up","translit":"synkleíō","lemma":"συγκλείω","derivation":"from G4862 (σύν) and G2808 (κλείω);","strongs_def":" to shut together, i.e. include or (figuratively) embrace in a common subjection to","pron":"soong-kli'-o","pos":"Verb","thayer":"<ol><li>to shut up together, enclose<ol type='a'><li>of a shoal of fishes in a net</li></ol><li>to shut up on all sides, shut up completely</li></ol>","xlit":"synkleíō"},"G168":{"strongs_def":" impurity (the state), morally","derivation":"from G169 (ἀκάθαρτος);","lemma":"ἀκαθάρτης","translit":"akathártēs","kjv_def":"filthiness","pron":"ak-ath-ar'-tace","pos":"Noun Feminine","thayer":"<ol><li>impurity, filthiness</li></ol>","xlit":"akathártēs"},"G39":{"derivation":"neuter of G40 (ἅγιος);","strongs_def":" a sacred thing (i.e. spot)","kjv_def":"holiest (of all), holy place, sanctuary","translit":"hágion","lemma":"ἅγιον","pron":"hag'-ee-on","pos":"Adjective","thayer":"<ol><li>reverend, worthy of veneration<ol type='a'><li>of things which on account of some connection with God possess a certain distinction and claim to reverence, as places sacred to God which are not to be profaned</li><li>of persons whose services God employs, for example, apostles</li></ol><li>set apart for God, to be as it were, exclusively his</li><li>services and offerings<ol type='a'><li>prepared for God with solemn rite, pure, clean</li></ol><li>in a moral sense, pure sinless upright holy</li></ol>","xlit":"hágion"},"G3557":{"kjv_def":"keep back, purloin","translit":"nosphízomai","lemma":"νοσφίζομαι","derivation":"middle voice from (apart or clandestinely);","strongs_def":" to sequestrate for oneself, i.e. embezzle","pron":"nos-fid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to set apart, separate, divide</li><li>to set apart or separate for one's self</li><li>to purloin, embezzle, withdraw covertly and appropriate to one's own use</li></ol>","xlit":"nosphízomai"},"G3449":{"kjv_def":"painfulness, travail","lemma":"μόχθος","translit":"móchthos","derivation":"from the base of G3425 (μόγις);","strongs_def":" toil, i.e. (by implication) sadness","pron":"mokh'-thos","pos":"Noun Masculine","thayer":"<ol><li>a hard and difficult labour, toil, travail, hardship, distress</li></ol>","xlit":"móchthos"},"G3558":{"translit":"nótos","lemma":"νότος","kjv_def":"south (wind)","strongs_def":" the south(-west) wind; by extension, the southern quarter itself","derivation":"of uncertain affinity;","pron":"not'-os","pos":"Noun Masculine","thayer":"<ol><li>the south wind</li><li>the south, the southern quarter</li></ol>","xlit":"nótos"},"G849":{"lemma":"αὐτόχειρ","translit":"autócheir","kjv_def":"with … own hands","strongs_def":" self-handed, i.e. doing personally","derivation":"from G846 (αὐτός) and G5495 (χείρ);","pron":"ow-tokh'-ire","pos":"Adjective","thayer":"<ol><li>doing a thing with one's own hands (Often in the tragedians and Attic orators)</li></ol>","xlit":"autócheir"},"G1820":{"strongs_def":" to be utterly at a loss, i.e. despond","derivation":"middle voice from G1537 (ἐκ) and G639 (ἀπορέω);","translit":"exaporéomai","lemma":"ἐξαπορέομαι","kjv_def":"(in) despair","pron":"ex-ap-or-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to be utterly at loss, be utterly destitute of measures or resources, to renounce all hope, be in despair</li></ol>","xlit":"exaporéomai"},"G1432":{"translit":"dōreán","lemma":"δωρεάν","kjv_def":"without a cause, freely, for naught, in vain","strongs_def":" gratuitously (literally or figuratively)","derivation":"accusative case of G1431 (δωρεά) as adverb;","pron":"do-reh-an'","pos":"Adjective","thayer":"<ol><li>freely, undeservedly</li></ol>","xlit":"dōreán"},"G292":{"strongs_def":" to ward off (for oneself), i.e. protect","derivation":"middle voice of a primary verb;","lemma":"ἀμύνομαι","translit":"amýnomai","kjv_def":"defend","pron":"am-oo'-nom-ahee","pos":"Verb","thayer":"<ol><li>defend<ol type='a'><li>to ward off, keep off</li><li>to aid or assist anyone</li><li>to defend one's self against anyone</li><li>to take vengeance on anyone</li></ol></li></ol>","xlit":"amýnomai"},"G774":{"translit":"Asianós","lemma":"Ἀσιανός","kjv_def":"of Asia","strongs_def":" an Asian (i.e. Asiatic) or an inhabitant of Asia","derivation":"from G773 (Ἀσία);","pron":"as-ee-an-os'","pos":"Adjective","thayer":"<ol><li>a native of Asia, Asian, Asiatic</li></ol>","xlit":"Asianós"},"G4295":{"strongs_def":" to lie before the view, i.e. (figuratively) to be present (to the mind), to stand forth (as an example or reward)","derivation":"from G4253 (πρό) and G2749 (κεῖμαι);","translit":"prókeimai","lemma":"πρόκειμαι","kjv_def":"be first, set before (forth)","pron":"prok'-i-mahee","pos":"Verb","thayer":"<ol><li>to lie or be placed before (a person or a thing) or in front of</li><li>to set before<ol type='a'><li>to be placed before the eyes, to lie in sight<ol><li>to stand forth</li></ol><li>to be appointed, destined</li><li>to be there, be present, be at hand</li></ol></li></ol>","xlit":"prókeimai"},"G1592":{"derivation":"from G1537 (ἐκ) and G3456 (μυκτηρίζω);","strongs_def":" to sneer outright at","kjv_def":"deride","translit":"ekmyktērízō","lemma":"ἐκμυκτηρίζω","pron":"ek-mook-ter-id'-zo","pos":"Verb","thayer":"<ol><li>to deride by turning up the nose, to sneer at, to scoff at</li></ol>","xlit":"ekmyktērízō"},"G4341":{"derivation":"middle voice from G4314 (πρός) and G2564 (καλέω);","strongs_def":" to call toward oneself, i.e. summon, invite","kjv_def":"call (for, to, unto)","translit":"proskaléomai","lemma":"προσκαλέομαι","pron":"pros-kal-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to call to</li><li>to call to one's self</li><li>to bid to come to one's self</li><li>metaphorically<ol type='a'><li>God is said to call to himself the Gentiles, aliens as they are from him, by inviting them, through the preaching of the gospel unto fellowship with himself in the Messiah's kingdom</li><li>Christ and the Holy Sprit are said to call to themselves those preachers of the gospel to whom they have decided to intrust a service having reference to the extension of the gospel</li></ol></li></ol>","xlit":"proskaléomai"},"G1769":{"translit":"enneós","lemma":"ἐννεός","kjv_def":"speechless","strongs_def":" dumb (as making signs), i.e. silent from astonishment","derivation":"from G1770 (ἐννεύω);","pron":"en-neh-os'","pos":"Adjective","thayer":"<ol><li>dumb, mute, destitute of power of speech</li><li>unable to speak for terror, struck dumb, astounded</li></ol>","xlit":"enneós"},"G1295":{"strongs_def":" to save thoroughly, i.e. (by implication or analogy) to cure, preserve, rescue, etc.","derivation":"from G1223 (διά) and G4982 (σώζω);","translit":"diasṓzō","lemma":"διασώζω","kjv_def":"bring safe, escape (safe), heal, make perfectly whole, save","pron":"dee-as-odze'-o","pos":"Verb","thayer":"<ol><li>to preserve through danger, to bring safely through<ol type='a'><li>to save, i.e. cure one who is sick, bring him through</li></ol><li>to save, keep from perishing</li><li>to save out of danger, rescue</li></ol>","xlit":"diasṓzō"},"G5526":{"strongs_def":" to fodder, i.e. (generally) to gorge (supply food in abundance)","derivation":"from G5528 (χόρτος);","translit":"chortázō","lemma":"χορτάζω","kjv_def":"feed, fill, satisfy","pron":"khor-tad'-zo","pos":"Verb","thayer":"<ol><li>to feed with herbs, grass, hay, to fill, satisfy with food, to fatten<ol type='a'><li>of animals</li></ol><li>to fill or satisfy men</li><li>to fulfil or satisfy the desire of any one</li></ol>","xlit":"chortázō"},"G3482":{"lemma":"Ναθαναήλ","translit":"Nathanaḗl","kjv_def":"Nathanael","strongs_def":" Nathanaël (i.e. Nathanel), an Israelite and Christian","derivation":"of Hebrew origin (H05417);","pron":"nath-an-ah-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nathanael = \"gift of God\"</p><ol><li>an intimate disciple of Jesus Christ, he is commonly thought to be the same person as Bartholomew</li></ol>","xlit":"Nathanaḗl"},"G1201":{"strongs_def":" a place of bondage, i.e. a dungeon","derivation":"from a derivative of G1199 (δεσμόν) (equivalent to G1196 (δεσμέω));","translit":"desmōtḗrion","lemma":"δεσμωτήριον","kjv_def":"prison","pron":"des-mo-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a prison, a jail</li></ol>","xlit":"desmōtḗrion"},"G5232":{"kjv_def":"grow exceedingly","translit":"hyperauxánō","lemma":"ὑπεραυξάνω","derivation":"from G5228 (ὑπέρ) and G837 (αὐξάνω);","strongs_def":" to increase above ordinary degree","pron":"hoop-er-owx-an'-o","pos":"Verb","thayer":"<ol><li>to increase beyond measure</li><li>to grow exceedingly</li></ol>","xlit":"hyperauxánō"},"G629":{"strongs_def":" (the act) ransom in full, i.e. (figuratively) riddance, or (specially) Christian salvation","derivation":"from a compound of G575 (ἀπό) and G3083 (λύτρον);","lemma":"ἀπολύτρωσις","translit":"apolýtrōsis","kjv_def":"deliverance, redemption","pron":"ap-ol-oo'-tro-sis","pos":"Noun Feminine","thayer":"<ol><li>a releasing effected by payment of ransom<ol type='a'><li>redemption, deliverance</li><li>liberation procured by the payment of a ransom</li></ol></li></ol>","xlit":"apolýtrōsis"},"G1610":{"kjv_def":"pluck up by the root, root up","translit":"ekrizóō","lemma":"ἐκριζόω","derivation":"from G1537 (ἐκ) and G4492 (ῥιζόω);","strongs_def":" to uproot","pron":"ek-rid-zo'-o","pos":"Verb","thayer":"<ol><li>to root out, pluck up by the roots</li></ol>","xlit":"ekrizóō"},"G1115":{"kjv_def":"Golgotha","translit":"Golgothâ","lemma":"Γολγοθᾶ","derivation":"of Chaldee origin (compare H01538);","strongs_def":" the skull; Golgotha, a knoll near Jerusalem","pron":"gol-goth-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Golgotha = \"skull\"</p><ol><li>the name of a place outside Jerusalem where Jesus was crucified; so called, apparently because its form resembled a skull</li></ol>","xlit":"Golgothâ"},"G267":{"kjv_def":"without witness","translit":"amártyros","lemma":"ἀμάρτυρος","derivation":"from G1 (Α) (as a negative particle) and a form of G3144 (μάρτυς);","strongs_def":" unattested","pron":"am-ar'-too-ros","pos":"Adjective","thayer":"<ol><li>without witness or testimony, unattested</li></ol>","xlit":"amártyros"},"G5428":{"derivation":"from G5426 (φρονέω);","strongs_def":" mental action or activity, i.e. intellectual or moral insight","kjv_def":"prudence, wisdom","translit":"phrónēsis","lemma":"φρόνησις","pron":"fron'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>understanding</li><li>knowledge and holy love of the will of God</li></ol>","xlit":"phrónēsis"},"G2201":{"lemma":"ζεῦγος","translit":"zeûgos","kjv_def":"yoke, pair","strongs_def":" a couple, i.e. a team (of oxen yoked together) or brace (of birds tied together)","derivation":"from the same as G2218 (ζυγός);","pron":"dzyoo'-gos","pos":"Noun Neuter","thayer":"<ol><li>two draught cattle (horses or mules or oxen) yoked together, a pair or yoke of beasts</li><li>a pair</li></ol>","xlit":"zeûgos"},"G365":{"kjv_def":"renew","lemma":"ἀνανεόω","translit":"ananeóō","derivation":"from G303 (ἀνά) and a derivative of G3501 (νέος);","strongs_def":" to renovate, i.e. reform","pron":"an-an-neh-o'-o","pos":"Verb","thayer":"<ol><li>to renew (in the mind)</li></ol>","xlit":"ananeóō"},"G3787":{"derivation":"from G3788 (ὀφθαλμός) and G1397 (δουλεία);","strongs_def":" sight-labor, i.e. that needs watching (remissness)","kjv_def":"eye-service","translit":"ophthalmodouleía","lemma":"ὀφθαλμοδουλεία","pron":"of-thal-mod-oo-li'-ah","pos":"Noun Feminine","thayer":"<ol><li>service performed [only] under the master's eyes<ol type='a'><li>for the master's eye usually stimulates to greater diligence</li><li>his absence, on the other hand, renders sluggish</li></ol></li></ol>","xlit":"ophthalmodouleía"},"G2968":{"lemma":"κώμη","translit":"kṓmē","kjv_def":"town, village","strongs_def":" a hamlet (as if laid down)","derivation":"from G2749 (κεῖμαι);","pron":"ko'-may","pos":"Noun Feminine","thayer":"<ol><li>the common sleeping place to which labourers in the field return, a village</li><li>the name of the city near which the villages lie and to whose municipality they belong</li><li>the inhabitants of villages</li></ol>","xlit":"kṓmē"},"G4361":{"kjv_def":"very hungry","lemma":"πρόσπεινος","translit":"próspeinos","derivation":"from G4314 (πρός) and the same as G3983 (πεινάω);","strongs_def":" hungering further, i.e. intensely hungry","pron":"pros'-pi-nos","pos":"Adjective","thayer":"<ol><li>very hungry</li></ol>","xlit":"próspeinos"},"G2434":{"lemma":"ἱλασμός","translit":"hilasmós","kjv_def":"propitiation","strongs_def":"atonement, i.e. (concretely) an expiator","pron":"hil-as-mos'","pos":"Noun Masculine","thayer":"<ol><li>an appeasing, propitiating</li><li>the means of appeasing, a propitiation</li></ol>","xlit":"hilasmós"},"G3833":{"derivation":"from a compound of G3956 (πᾶς) and G3696 (ὅπλον);","strongs_def":" full armor (\"panoply\")","kjv_def":"all (whole) armour","lemma":"πανοπλία","translit":"panoplía","pron":"pan-op-lee'-ah","pos":"Noun Feminine","thayer":"<ol><li>full armour, complete armour<ol type='a'><li>includes shield, sword, lance, helmet, greaves, and breastplate</li></ol></li></ol>","xlit":"panoplía"},"G4890":{"strongs_def":" a running together, i.e. (riotous) concourse","derivation":"from (the alternate of) G4936 (συντρέχω);","lemma":"συνδρομή","translit":"syndromḗ","kjv_def":"run together","pron":"soon-drom-ay'","pos":"Noun Feminine","thayer":"<ol><li>a running together, concourse, especially hostile or riotous</li></ol>","xlit":"syndromḗ"},"G1171":{"strongs_def":" terribly, i.e. excessively","derivation":"adverb from a derivative of the same as G1169 (δειλός);","lemma":"δεινῶς","translit":"deinōs","kjv_def":"grievously, vehemently","pron":"di-noce'","pos":"Adverb","thayer":"<ol><li>terribly, grievously</li></ol>","xlit":"deinōs"},"G3989":{"derivation":"of uncertain affinity;","strongs_def":" deep or open sea, i.e. the main","kjv_def":"depth, sea","lemma":"πέλαγος","translit":"pélagos","pron":"pel'-ag-os","pos":"Noun Neuter","thayer":"<ol><li>the sea</li><li>the high sea, the deep (where ships sail)</li></ol>","xlit":"pélagos"},"G3009":{"translit":"leitourgía","lemma":"λειτουργία","kjv_def":"ministration(-try), service","strongs_def":" public function (as priest (\"liturgy\") or almsgiver)","derivation":"from G3008 (λειτουργέω);","pron":"li-toorg-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a public office which a citizen undertakes to administer at his own expense</li><li>any service<ol type='a'><li>of military service</li><li>of the service of workmen</li><li>of that done to nature in the cohabitation of man and wife</li></ol><li>biblical usage<ol type='a'><li>a service or ministry of the priests relative to the prayers and sacrifices offered to God</li><li>a gift or benefaction for the relief of the needy</li></ol></li></ol>","xlit":"leitourgía"},"G3959":{"derivation":"probably of foreign origin;","strongs_def":" Patara, a place in Asia Minor","kjv_def":"Patara","lemma":"Πάταρα","translit":"Pátara","pron":"pat'-ar-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Patara = \"scattering, cursing\"</p><ol><li>a maritime city of Lycia, celebrated for its oracle of Apollo</li></ol>","xlit":"Pátara"},"G5380":{"kjv_def":"contentious","translit":"philóneikos","lemma":"φιλόνεικος","derivation":"from G5384 (φίλος) and (a quarrel;","strongs_def":" probably akin to G3534 (νῖκος)); fond of strife, i.e. disputatious","pron":"fil-on'-i-kos","pos":"Adjective","thayer":"<ol><li>fond of strife, contentious<ol type='a'><li>in a good sense, emulous</li></ol></li></ol>","xlit":"philóneikos"},"G2468":{"kjv_def":"+ agree, be, X give thyself wholly to","lemma":"ἴσθι","translit":"ísthi","derivation":"second person imperative present of G1510 (εἰμί);","strongs_def":" be thou","pron":"is'-thee","pos":"Verb","thayer":"<ol><li>be thou</li></ol>","xlit":"ísthi"},"G5180":{"kjv_def":"beat, smite, strike, wound","lemma":"τύπτω","translit":"týptō","derivation":"a primary verb (in a strengthened form);","strongs_def":" to \"thump\", i.e. cudgel or pummel (properly, with a stick or bastinado), but in any case by repeated blows; thus differing from G3817 (παίω) and G3960 (πατάσσω), which denote a (usually single) blow with the hand or any instrument, or G4141 (πλήσσω) with the fist (or a hammer), or G4474 (ῥαπίζω) with the palm; as well as from G5177 (τυγχάνω), an accidental collision); by implication, to punish; figuratively, to offend (the conscience)","pron":"toop'-to","pos":"Verb","thayer":"<ol><li>to strike, beat, smite<ol type='a'><li>with a staff, a whip, the fist, the hand</li><li>of mourners, to smite their breast</li></ol><li>to smite one on whom he inflicts punitive evil</li><li>to smite<ol type='a'><li>metaphorically, i.e. to wound, disquiet one's conscience</li></ol></li></ol>","xlit":"týptō"},"G4384":{"strongs_def":" to pre-arrange, i.e. prescribe","derivation":"from G4253 (πρό) and G5021 (τάσσω);","translit":"protássō","lemma":"προτάσσω","kjv_def":"before appoint","pron":"prot-as'-so","pos":"Verb","thayer":"<ol><li>to place before</li><li>to appoint before, define beforehand</li></ol>","xlit":"protássō"},"G2040":{"strongs_def":" a toiler; figuratively, a teacher","derivation":"from G2041 (ἔργον);","translit":"ergátēs","lemma":"ἐργάτης","kjv_def":"labourer, worker(-men)","pron":"er-gat'-ace","pos":"Noun Masculine","thayer":"<ol><li>a workman, a labourer<ol type='a'><li>usually one who works for hire especially an agricultural worker</li></ol><li>one who does, a worker, perpetrator</li></ol>","xlit":"ergátēs"},"G3651":{"derivation":"from G3650 (ὅλος) and G5056 (τέλος);","strongs_def":" complete to the end, i.e. absolutely perfect","kjv_def":"wholly","lemma":"ὁλοτελής","translit":"holotelḗs","pron":"hol-ot-el-ace'","pos":"Adjective","thayer":"<ol><li>perfect, complete in all respects</li></ol>","xlit":"holotelḗs"},"G733":{"lemma":"ἀρσενοκοίτης","translit":"arsenokoítēs","kjv_def":"abuser of (that defile) self with mankind","strongs_def":" a sodomite","derivation":"from G730 (ἄῤῥην) and G2845 (κοίτη);","pron":"ar-sen-ok-oy'-tace","pos":"Noun Masculine","thayer":"<ol><li>one who lies with a male as with a female, sodomite, homosexual</li></ol>","xlit":"arsenokoítēs"},"G3083":{"derivation":"from G3089 (λύω);","strongs_def":" something to loosen with, i.e. a redemption price (figuratively, atonement)","kjv_def":"ransom","translit":"lýtron","lemma":"λύτρον","pron":"loo'-tron","pos":"Noun Neuter","thayer":"<ol><li>the price for redeeming, ransom<ol type='a'><li>paid for slaves, captives</li><li>for the ransom of life</li></ol><li>to liberate many from misery and the penalty of their sins</li></ol>","xlit":"lýtron"},"G3305":{"strongs_def":" indeed though, i.e. however","derivation":"from G3203 and G5104 (τοί);","lemma":"μέντοι","translit":"méntoi","kjv_def":"also, but, howbeit, nevertheless, yet","pron":"men'-toy","thayer":"<ol><li>but yet, nevertheless, howbeit</li></ol>","xlit":"méntoi"},"G2127":{"strongs_def":" to speak well of, i.e. (religiously) to bless (thank or invoke a benediction upon, prosper)","derivation":"from a compound of G2095 (εὖ) and G3056 (λόγος);","translit":"eulogéō","lemma":"εὐλογέω","kjv_def":"bless, praise","pron":"yoo-log-eh'-o","pos":"Verb","thayer":"<ol><li>to praise, celebrate with praises</li><li>to invoke blessings</li><li>to consecrate a thing with solemn prayers<ol type='a'><li>to ask God's blessing on a thing</li><li>pray God to bless it to one's use</li><li>pronounce a consecratory blessing on</li></ol><li>of God<ol type='a'><li>to cause to prosper, to make happy, to bestow blessings on</li><li>favoured of God, blessed</li></ol></li></ol>","xlit":"eulogéō"},"G3502":{"kjv_def":"young","lemma":"νεοσσός","translit":"neossós","derivation":"from G3501 (νέος);","strongs_def":" a youngling (nestling)","pron":"neh-os-sos'","pos":"Noun Masculine","thayer":"<ol><li>a young (creature), young bird</li></ol>","xlit":"neossós"},"G380":{"derivation":"from G303 (ἀνά) (in the sense of reversal) and G4428 (πτύσσω);","strongs_def":" to unroll (a scroll or volume)","kjv_def":"open","translit":"anaptýssō","lemma":"ἀναπτύσσω","pron":"an-ap-toos'-o","pos":"Verb","thayer":"<ol><li>to unroll<ol type='a'><li>the books of the Hebrews were rolls fastened to [one or] two smooth rods and furnished with handles, so that they could be rolled up and unrolled</li></ol></li></ol>","xlit":"anaptýssō"},"G1833":{"strongs_def":" to test thoroughly (by questions), i.e. ascertain or interrogate","derivation":"from G1537 (ἐκ) and (to examine);","translit":"exetázō","lemma":"ἐξετάζω","kjv_def":"ask, enquire, search","pron":"ex-et-ad'-zo","pos":"Verb","thayer":"<ol><li>to search out<ol type='a'><li>to examine strictly, enquire</li><li>enquire of someone</li></ol></li></ol>","xlit":"exetázō"},"G4510":{"derivation":"from G4509 (ῥύπος);","strongs_def":" to soil, i.e. (intransitively) to become dirty (morally)","kjv_def":"be filthy","translit":"rhypóō","lemma":"ῥυπόω","pron":"rhoo-po'-o","pos":"Verb","thayer":"<ol><li>to make filthy, defile, soil</li><li>to be filthy (morally)</li></ol>","xlit":"rhypóō"},"G1470":{"kjv_def":"hid in","lemma":"ἐγκρύπτω","translit":"enkrýptō","derivation":"from G1722 (ἐν) and G2928 (κρύπτω);","strongs_def":" to conceal in, i.e. incorporate with","pron":"eng-kroop'-to","pos":"Verb","thayer":"<ol><li>to conceal in something</li><li>to mingle one thing with another</li></ol>","xlit":"enkrýptō"},"G4474":{"kjv_def":"smite (with the palm of the hand)","translit":"rhapízō","lemma":"ῥαπίζω","derivation":"from a derivative of a primary (to let fall, \"rap\");","strongs_def":" to slap","pron":"hrap-id'-zo","pos":"Verb","thayer":"<ol><li>to smite with a rod or staff</li><li>to smite in the face with the palm of the hand, to box the ear</li></ol>","xlit":"rhapízō"},"G3544":{"derivation":"from G3551 (νόμος);","strongs_def":" according (or pertaining) to law, i.e. legal (ceremonially); as noun, an expert in the (Mosaic) law","kjv_def":"about the law, lawyer","lemma":"νομικός","translit":"nomikós","pron":"nom-ik-os'","pos":"Adjective","thayer":"<ol><li>pertaining to the law, one learned in the law</li><li>in the NT an interpreter and teacher of the Mosaic law</li></ol>","xlit":"nomikós"},"G5091":{"lemma":"τιμάω","translit":"timáō","kjv_def":"honour, value","strongs_def":" to prize, i.e. fix a valuation upon; by implication, to revere","derivation":"from G5093 (τίμιος);","pron":"tim-ah'-o","pos":"Verb","thayer":"<ol><li>to estimate, fix the value<ol type='a'><li>for the value of something belonging to one's self</li></ol><li>to honour, to have in honour, to revere, venerate</li></ol>","xlit":"timáō"},"G3179":{"kjv_def":"put out, remove, translate, turn away","lemma":"μεθίστημι","translit":"methístēmi","derivation":"from G3326 (μετά) and G2476 (ἵστημι);","strongs_def":" to transfer, i.e. carry away, depose or (figuratively) exchange, seduce","pron":"meth-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to transpose, transfer, remove from one place to another<ol type='a'><li>of change of situation or place</li><li>to remove from the office of a steward</li><li>to depart from life, to die</li></ol></li></ol>","xlit":"methístēmi"},"G519":{"kjv_def":"hang himself","lemma":"ἀπάγχομαι","translit":"apánchomai","derivation":"from G575 (ἀπό) and (to choke;","strongs_def":" akin to the base of G43 (ἀγκάλη)); to strangle oneself off (i.e. to death)","pron":"ap-ang'-khom-ahee","pos":"Verb","thayer":"<ol><li>to throttle, strangle, in order to put out of the way or kill</li><li>to hang one's self, to end one's life by hanging</li></ol>","xlit":"apánchomai"},"G1994":{"strongs_def":" to revert (literally, figuratively or morally)","derivation":"from G1909 (ἐπί) and G4762 (στρέφω);","translit":"epistréphō","lemma":"ἐπιστρέφω","kjv_def":"come (go) again, convert, (re-)turn (about, again)","pron":"ep-ee-stref'-o","pos":"Verb","thayer":"<ol><li>transitively<ol type='a'><li>to turn to<ol><li>to the worship of the true God</li></ol><li>to cause to return, to bring back<ol><li>to the love and obedience of God</li><li>to the love for the children</li><li>to love wisdom and righteousness</li></ol></li></ol><li>intransitively<ol type='a'><li>to turn to one's self</li><li>to turn one's self about, turn back</li><li>to return, turn back, come back</li></ol></li></ol>","xlit":"epistréphō"},"G1091":{"derivation":"neuter of a (presumed) derivative of G1092 (γεωργός);","strongs_def":" cultivable, i.e. a farm","kjv_def":"husbandry","lemma":"γεώργιον","translit":"geṓrgion","pron":"gheh-ore'-ghee-on","pos":"Noun Neuter","thayer":"<ol><li>a cultivated field, husbandry, tillage</li></ol>","xlit":"geṓrgion"},"G759":{"derivation":"from G142 (αἴρω) (in the sense of sending off scent);","strongs_def":" an aromatic","kjv_def":"(sweet) spice","translit":"árōma","lemma":"ἄρωμα","pron":"ar'-o-mah","pos":"Noun Neuter","thayer":"<ol><li>spice, perfume</li></ol>","xlit":"árōma"},"G4918":{"strongs_def":" to compress, i.e. crowd on all sides","derivation":"from G4862 (σύν) and G2346 (θλίβω);","lemma":"συνθλίβω","translit":"synthlíbō","kjv_def":"throng","pron":"soon-thlee'-bo","pos":"Verb","thayer":"<ol><li>to press together, press on all sides</li></ol>","xlit":"synthlíbō"},"G5514":{"strongs_def":" \"green\"; Chloë, a Christian female","derivation":"feminine of apparently a primary word;","lemma":"Χλόη","translit":"Chlóē","kjv_def":"Chloe","pron":"khlo'-ay","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Chloe = \"a green herb\"</p><ol><li>a Christian woman of Corinth</li></ol>","xlit":"Chlóē"},"G2369":{"translit":"thymiastḗrion","lemma":"θυμιαστήριον","kjv_def":"censer","strongs_def":" a place of fumigation, i.e. the alter of incense (in the Temple)","derivation":"from a derivative of G2370 (θυμιάω);","pron":"thoo-mee-as-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>a utensil for fumigating or burning incense</li><li>an altar of incense</li></ol>","xlit":"thymiastḗrion"},"G4137":{"kjv_def":"accomplish, X after, (be) complete, end, expire, fill (up), fulfil, (be, make) full (come), fully preach, perfect, supply","lemma":"πληρόω","translit":"plēróō","derivation":"from G4134 (πλήρης);","strongs_def":" to make replete, i.e. (literally) to cram (a net), level up (a hollow), or (figuratively) to furnish (or imbue, diffuse, influence), satisfy, execute (an office), finish (a period or task), verify (or coincide with a prediction), etc.","pron":"play-ro'-o","pos":"Verb","thayer":"<ol><li>to make full, to fill up, i.e. to fill to the full<ol type='a'><li>to cause to abound, to furnish or supply liberally<ol><li>I abound, I am liberally supplied</li></ol></li></ol><li>to render full, i.e. to complete<ol type='a'><li>to fill to the top: so that nothing shall be wanting to full measure, fill to the brim</li><li>to consummate: a number<ol><li>to make complete in every particular, to render perfect</li><li>to carry through to the end, to accomplish, carry out, (some undertaking)</li></ol><li>to carry into effect, bring to realisation, realise<ol><li>of matters of duty: to perform, execute</li><li>of sayings, promises, prophecies, to bring to pass, ratify, accomplish</li><li>to fulfil, i.e. to cause God's will (as made known in the law) to be obeyed as it should be, and God's promises (given through the prophets) to receive fulfilment</li></ol></li></ol></li></ol>","xlit":"plēróō"},"G1908":{"translit":"epēreázō","lemma":"ἐπηρεάζω","kjv_def":"use despitefully, falsely accuse","strongs_def":" to insult, slander","derivation":"from a comparative of G1909 (ἐπί) and (probably) (threats);","pron":"ep-ay-reh-ad'-zo","pos":"Verb","thayer":"<ol><li>to insult</li><li>to treat abusively, use despitefully</li><li>to revile</li><li>in a forensic sense, to accuse falsely</li><li>to threaten</li></ol>","xlit":"epēreázō"},"G773":{"derivation":"of uncertain derivation;","strongs_def":" Asia, i.e. Asia Minor, or (usually) only its western shore","kjv_def":"Asia","translit":"Asía","lemma":"Ἀσία","pron":"as-ee'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Asia = \"orient\"</p><ol><li>Asia proper or proconsular Asia embracing Mysia, Lydia, Phrygia, and Caria, corresponding closely to Turkey today</li></ol>","xlit":"Asía"},"G2430":{"kjv_def":"Iconium","lemma":"Ἰκόνιον","translit":"Ikónion","derivation":"perhaps from G1504 (εἰκών);","strongs_def":" image-like; Iconium, a place in Asia Minor","pron":"ee-kon'-ee-on","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Iconium = \"little image\"</p><ol><li>a famous city of Asia Minor, which was the capital of Lycaonia</li></ol>","xlit":"Ikónion"},"G3806":{"translit":"páthos","lemma":"πάθος","kjv_def":" (inordinate) affection, lust","strongs_def":" properly, suffering (\"pathos\"), i.e. (subjectively) a passion (especially concupiscence)","derivation":"from the alternate of G3958 (πάσχω);","pron":"path'-os","pos":"Noun Neuter","thayer":"<ol><li>whatever befalls one, whether it be sad or joyous<ol type='a'><li>spec. a calamity, mishap, evil, affliction</li></ol><li>a feeling which the mind suffers<ol type='a'><li>an affliction of the mind, emotion, passion</li><li>passionate deed</li><li>used by the Greeks in either a good or bad sense</li><li>in the NT in a bad sense, depraved passion, vile passions</li></ol></li></ol>","xlit":"páthos"},"G80":{"translit":"adelphós","lemma":"ἀδελφός","kjv_def":"brother","strongs_def":" a brother (literally or figuratively) near or remote (much like G1 (Α))","derivation":"from G1 (Α) (as a connective particle) and (the womb);","pron":"ad-el-fos'","pos":"Noun Masculine","thayer":"<ol><li>a brother, whether born of the same two parents or only of the same father or mother</li><li>having the same national ancestor, belonging to the same people, or countryman</li><li>any fellow or man</li><li>a fellow believer, united to another by the bond of affection</li><li>an associate in employment or office</li><li>brethren in Christ<ol type='a'><li>his brothers by blood</li><li>all men</li><li>apostles</li><li>Christians, as those who are exalted to the same heavenly place</li></ol></li></ol>","xlit":"adelphós"},"G2629":{"derivation":"from G2596 (κατά) and G2875 (κόπτω);","strongs_def":" to chop down, i.e. mangle","kjv_def":"cut","translit":"katakóptō","lemma":"κατακόπτω","pron":"kat-ak-op'-to","pos":"Verb","thayer":"<ol><li>to cut up in pieces</li><li>to slay</li><li>to beat, bruise</li><li>to cut, gash, mangle</li></ol>","xlit":"katakóptō"},"G4912":{"strongs_def":" to hold together, i.e. to compress (the ears, with a crowd or siege) or arrest (a prisoner); figuratively, to compel, perplex, afflict, preoccupy","derivation":"from G4862 (σύν) and G2192 (ἔχω);","translit":"synéchō","lemma":"συνέχω","kjv_def":"constrain, hold, keep in, press, lie sick of, stop, be in a strait, straiten, be taken with, throng","pron":"soon-ekh'-o","pos":"Verb","thayer":"<ol><li>to hold together<ol type='a'><li>any whole, lest it fall to pieces or something fall away from it</li></ol><li>to hold together with constraint, to compress<ol type='a'><li>to press together with the hand</li><li>to hold one's ears, to shut the heavens that it may not rain</li><li>to press on every side<ol><li>of a besieged city</li><li>of a strait, that forces a ship into a narrow channel</li><li>of a cattle squeeze, that pushing in on each side, forcing the beast into a position where it cannot move so the farmer can administer medication</li></ol></li></ol><li>to hold completely<ol type='a'><li>to hold fast<ol><li>of a prisoner</li></ol><li>metaphorically<ol><li>to be held by, closely occupied with any business</li><li>in teaching the word</li><li>to constrain, oppress, of ills laying hold of one and distressing him</li><li>to be held with, afflicted with, suffering from</li><li>to urge, impel<ol type='a'><li>of the soul</li></ol></li></ol></li></ol></li></ol>","xlit":"synéchō"},"G1059":{"derivation":"of Hebrew origin (H01583);","strongs_def":" Gamaliel (i.e. Gamliel), an Israelite","kjv_def":"Gamaliel","lemma":"Γαμαλιήλ","translit":"Gamaliḗl","pron":"gam-al-ee-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Gamaliel = \"my recompenser is God\"</p><ol><li>a Pharisee and celebrated doctor of the law, who gave prudent worldly advice in the Sanhedrin respecting the treatment of the followers of Jesus of Nazareth. <a class='bible' href='#b44.5.34'>Act 5:34</a> ff. (A.D.29.) We learn from <a class='bible' href='#b44.22.3'>Act 22:3</a> that he was the preceptor of Paul. He is generally identified with the very celebrated Jewish doctor Gamaliel, grandson of Hillel, and who is referred to as authority in the Jewish Mishna.</li></ol>","xlit":"Gamaliḗl"},"G1359":{"strongs_def":" sons of Jupiter, i.e. the twins Dioscuri","derivation":"from the alternate of G2203 (Ζεύς) and a form of the base of G2877 (κοράσιον);","translit":"Dióskouroi","lemma":"Διόσκουροι","kjv_def":"Castor and Pollux","pron":"dee-os'-koo-roy","pos":"Noun Masculine","thayer":"<ol><li>Castor and Pollux, were the twin sons of Jupiter and Leda, and were regarded as the tutelary divinities of sailors</li></ol>","xlit":"Dióskouroi"},"G1400":{"translit":"doûlon","lemma":"δοῦλον","kjv_def":"servant","strongs_def":" subservient","derivation":"neuter of G1401 (δοῦλος);","pron":"doo'-lon","xlit":"doûlon"},"G347":{"translit":"anaklínō","lemma":"ἀνακλίνω","kjv_def":"lay, (make) sit down","strongs_def":" to lean back","derivation":"from G303 (ἀνά) and G2827 (κλίνω);","pron":"an-ak-lee'-no","pos":"Verb","thayer":"<ol><li>to lean against, lean upon<ol type='a'><li>to lay down</li><li>to make or bid to recline</li></ol></li></ol>","xlit":"anaklínō"},"G5261":{"lemma":"ὑπογραμμός","translit":"hypogrammós","kjv_def":"example","strongs_def":" an underwriting, i.e. copy for imitation (figuratively)","derivation":"from a compound of G5259 (ὑπό) and G1125 (γράφω);","pron":"hoop-og-ram-mos'","pos":"Noun Masculine","thayer":"<ol><li>a writing copy, including all the letters of the alphabet, given to beginners as an aid in learning to draw them</li><li>an example set before one</li></ol>","xlit":"hypogrammós"},"G2331":{"strongs_def":" a Thessalonican, i.e. inhabitant of Thessalonice","derivation":"from G2332 (Θεσσαλονίκη);","translit":"Thessalonikeús","lemma":"Θεσσαλονικεύς","kjv_def":"Thessalonian","pron":"thes-sal-on-ik-yoos'","pos":"Noun Masculine","thayer":"<ol><li>a Thessalonians</li></ol>","xlit":"Thessalonikeús"},"G5097":{"lemma":"τιμωρέω","translit":"timōréō","kjv_def":"punish","strongs_def":" properly, to protect one's honor, i.e. to avenge (inflict a penalty)","derivation":"from a comparative of G5092 (τιμή) and ouros (a guard);","pron":"tim-o-reh'-o","pos":"Verb","thayer":"<ol><li>to be a guardian or avenger of honour<ol type='a'><li>to succour, come to the help of</li></ol><li>to avenge</li><li>in the NT, to take vengeance on one, to punish</li></ol>","xlit":"timōréō"},"G4917":{"derivation":"from G4862 (σύν) and thlao (to crush);","strongs_def":" to dash together, i.e. shatter","kjv_def":"break","translit":"synthláō","lemma":"συνθλάω","pron":"soon-thlah'-o","pos":"Verb","thayer":"<ol><li>to break to pieces, shatter</li></ol>","xlit":"synthláō"},"G2683":{"kjv_def":"shadow","translit":"kataskiázō","lemma":"κατασκιάζω","derivation":"from G2596 (κατά) and a derivative of G4639 (σκιά);","strongs_def":" to overshade, i.e. cover","pron":"kat-as-kee-ad'-zo","pos":"Verb","thayer":"<ol><li>to overshadow, cover with shade</li></ol>","xlit":"kataskiázō"},"G4188":{"kjv_def":"drink","translit":"póma","lemma":"πόμα","derivation":"from the alternate of G4095 (πίνω);","strongs_def":" a beverage","pron":"pom'-ah","pos":"Noun Neuter","thayer":"<ol><li>drink</li></ol>","xlit":"póma"},"G673":{"kjv_def":"depart (asunder)","translit":"apochōrízō","lemma":"ἀποχωρίζω","derivation":"from G575 (ἀπό) and G5563 (χωρίζω);","strongs_def":" to rend apart; reflexively, to separate","pron":"ap-okh-o-rid'-zo","pos":"Verb","thayer":"<ol><li>to separate, sever</li><li>to part asunder</li><li>to separate one's self, depart from</li></ol>","xlit":"apochōrízō"},"G4567":{"derivation":"of Chaldee origin corresponding to H04566 (with the definite affix);","strongs_def":" the accuser, i.e. the devil","kjv_def":"Satan","lemma":"Σατανᾶς","translit":"Satanâs","pron":"sat-an-as'","pos":"Noun Masculine","thayer":"<ol><li>adversary (one who opposes another in purpose or act), the name given to<ol type='a'><li>the prince of evil spirits, the inveterate adversary of God and Christ<ol><li>he incites apostasy from God and to sin</li><li>circumventing men by his wiles</li><li>the worshippers of idols are said to be under his control</li><li>by his demons he is able to take possession of men and inflict them with diseases</li><li>by God's assistance he is overcome</li><li>on Christ's return from heaven he will be bound with chains for a thousand years, but when the thousand years are finished he will walk the earth in yet greater power, but shortly after will be given over to eternal punishment</li></ol><li>a Satan-like man</li></ol></li></ol>","xlit":"Satanâs"},"G868":{"kjv_def":"depart, draw (fall) away, refrain, withdraw self","lemma":"ἀφίστημι","translit":"aphístēmi","derivation":"from G575 (ἀπό) and G2476 (ἵστημι);","strongs_def":" to remove, i.e. (actively) instigate to revolt; usually (reflexively) to desist, desert, etc.","pron":"af-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to make stand off, cause to withdraw, to remove<ol type='a'><li>to excite to revolt</li></ol><li>to stand off, to stand aloof<ol type='a'><li>to go away, to depart from anyone</li><li>to desert, withdraw from one</li><li>to fall away, become faithless</li><li>to shun, flee from</li><li>to cease to vex one</li><li>to withdraw one's self from, to fall away</li><li>to keep one's self from, absent one's self from</li></ol></li></ol>","xlit":"aphístēmi"},"G5379":{"lemma":"φιλονεικία","translit":"philoneikía","kjv_def":"strife","strongs_def":" quarrelsomeness, i.e. a dispute","derivation":"from G5380 (φιλόνεικος);","pron":"fil-on-i-kee'-ah","pos":"Noun Feminine","thayer":"<ol><li>love of strife, eagerness to contend</li><li>contention<ol type='a'><li>in a good sense, emulation</li></ol></li></ol>","xlit":"philoneikía"},"G2637":{"derivation":"from G2596 (κατά) and the base of G2980 (λαλέω);","strongs_def":" talkative against, i.e. a slanderer","kjv_def":"backbiter","lemma":"κατάλαλος","translit":"katálalos","pron":"kat-al'-al-os","pos":"Adjective","thayer":"<ol><li>a defamer, evil speaker</li></ol>","xlit":"katálalos"},"G690":{"derivation":"from G688 (Ἀραβία);","strongs_def":" an Arab or native of Arabia","kjv_def":"Arabian","lemma":"Ἄραψ","translit":"Áraps","pron":"ar'-aps","pos":"Noun Masculine","thayer":"<ol><li>an Arabian</li></ol>","xlit":"Áraps"},"G2330":{"strongs_def":" properly, heat, i.e. summer","derivation":"from a primary (to heat);","translit":"théros","lemma":"θέρος","kjv_def":"summer","pron":"ther'-os","pos":"Noun Neuter","thayer":"<ol><li>summer</li></ol>","xlit":"théros"},"G628":{"strongs_def":" to wash fully, i.e. (figuratively) have remitted (reflexively)","derivation":"from G575 (ἀπό) and G3068 (λούω);","translit":"apoloúō","lemma":"ἀπολούω","kjv_def":"wash (away)","pron":"ap-ol-oo'-o","pos":"Verb","thayer":"<ol><li>to wash off or away</li></ol>","xlit":"apoloúō"},"G1022":{"lemma":"βραδύτης","translit":"bradýtēs","kjv_def":"slackness","strongs_def":" tardiness","derivation":"from G1021 (βραδύς);","pron":"brad-oo'-tace","pos":"Noun Feminine","thayer":"<ol><li>slowness, delay</li></ol>","xlit":"bradýtēs"},"G4877":{"kjv_def":"meet","lemma":"συνάντησις","translit":"synántēsis","derivation":"from G4876 (συναντάω);","strongs_def":" a meeting with","pron":"soon-an'-tay-sis","pos":"Noun Feminine","thayer":"<ol><li>a meeting with</li></ol>","xlit":"synántēsis"},"G4840":{"kjv_def":"be here present with","lemma":"συμπάρειμι","translit":"sympáreimi","derivation":"from G4862 (σύν) and G3918 (πάρειμι);","strongs_def":" to be at hand together, i.e. now present","pron":"soom-par'-i-mee","pos":"Verb","thayer":"<ol><li>to be present together</li></ol>","xlit":"sympáreimi"},"G2902":{"strongs_def":" to use strength, i.e. seize or retain (literally or figuratively)","derivation":"from G2904 (κράτος);","translit":"kratéō","lemma":"κρατέω","kjv_def":"hold (by, fast), keep, lay hand (hold) on, obtain, retain, take (by)","pron":"krat-eh'-o","pos":"Verb","thayer":"<ol><li>to have power, be powerful<ol type='a'><li>to be chief, be master of, to rule</li></ol><li>to get possession of<ol type='a'><li>to become master of, to obtain</li><li>to take hold of</li><li>to take hold of, take, seize<ol><li>to lay hands on one in order to get him into one's power</li></ol></li></ol><li>to hold<ol type='a'><li>to hold in the hand</li><li>to hold fast, i.e. not discard or let go<ol><li>to keep carefully and faithfully</li></ol><li>to continue to hold, to retain<ol><li>of death continuing to hold one</li><li>to hold in check, restrain</li></ol></li></ol></li></ol>","xlit":"kratéō"},"G4780":{"strongs_def":" to conceal altogether","derivation":"from G4862 (σύν) and G2572 (καλύπτω);","lemma":"συγκαλύπτω","translit":"synkalýptō","kjv_def":"cover","pron":"soong-kal-oop'-to","pos":"Verb","thayer":"<ol><li>to cover on all sides, to conceal entirely, to cover up completely</li></ol>","xlit":"synkalýptō"},"G234":{"derivation":"from (to soil);","strongs_def":" (ceremonially) defilement","kjv_def":"pollution","lemma":"ἀλίσγεμα","translit":"alísgema","pron":"al-is'-ghem-ah","pos":"Noun Neuter","thayer":"<ol><li>pollution, condemnation</li></ol>","xlit":"alísgema"},"G83":{"kjv_def":"X uncertain","lemma":"ἀδηλότης","translit":"adēlótēs","derivation":"from G82 (ἄδηλος);","strongs_def":" uncertainty","pron":"ad-ay-lot'-ace","pos":"Noun Feminine","thayer":"<ol><li>uncertainty</li></ol>","xlit":"adēlótēs"},"G4849":{"kjv_def":"company","lemma":"συμπόσιον","translit":"sympósion","derivation":"neuter of a derivative of the alternate of G4844 (συμπίνω);","strongs_def":" a drinking-party (\"symposium\"), i.e. (by extension) a room of guests","pron":"soom-pos'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a drinking party, entertainment<ol type='a'><li>of the party itself, the guests</li><li>rows of guests</li></ol></li></ol>","xlit":"sympósion"},"G2098":{"derivation":"from the same as G2097 (εὐαγγελίζω);","strongs_def":" a good message, i.e. the gospel","kjv_def":"gospel","lemma":"εὐαγγέλιον","translit":"euangélion","pron":"yoo-ang-ghel'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a reward for good tidings</li><li>good tidings<ol type='a'><li>the glad tidings of the kingdom of God soon to be set up, and subsequently also of Jesus the Messiah, the founder of this kingdom. After the death of Christ, the term comprises also the preaching of (concerning) Jesus Christ as having suffered death on the cross to procure eternal salvation for the men in the kingdom of God, but as restored to life and exalted to the right hand of God in heaven, thence to return in majesty to consummate the kingdom of God</li><li>the glad tidings of salvation through Christ</li><li>the proclamation of the grace of God manifest and pledged in Christ</li><li>the gospel</li><li>as the messianic rank of Jesus was proved by his words, his deeds, and his death, the narrative of the sayings, deeds, and death of Jesus Christ came to be called the gospel or glad tidings</li></ol></li></ol>","xlit":"euangélion"},"G4758":{"kjv_def":"choose to be a soldier","translit":"stratologéō","lemma":"στρατολογέω","derivation":"from a compound of the base of G4756 (στρατιά) and G3004 (λέγω) (in its original sense);","strongs_def":" to gather (or select) as a warrior, i.e. enlist in the army","pron":"strat-ol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to gather (collect) an army, to enlist soldiers<ol type='a'><li>of the commander</li></ol></li></ol>","xlit":"stratologéō"},"G5166":{"lemma":"τρυγάω","translit":"trygáō","kjv_def":"gather","strongs_def":" to collect the vintage","derivation":"from a derivative of (to dry) meaning ripe fruit (as if dry);","pron":"troo-gah'-o","pos":"Verb","thayer":"<ol><li>to gather in ripe fruits</li><li>to gather the harvest or vintage<ol type='a'><li>of fruit gathered</li></ol></li></ol>","xlit":"trygáō"},"G3050":{"derivation":"from G3056 (λόγος);","strongs_def":" rational (\"logical\")","kjv_def":"reasonable, of the word","translit":"logikós","lemma":"λογικός","pron":"log-ik-os'","pos":"Adjective","thayer":"<ol><li>pertaining to speech or speaking</li><li>pertaining to the reason or logic<ol type='a'><li>spiritual, pertaining to the soul</li><li>agreeable to reason, following reason, reasonable, logical</li></ol></li></ol>","xlit":"logikós"},"G4009":{"strongs_def":" an extremity","derivation":"from the same as G4008 (πέραν);","lemma":"πέρας","translit":"péras","kjv_def":"end, ut-(ter-)most participle ","pron":"per'-as","pos":"Noun Neuter","thayer":"<ol><li>extremity, bound, end<ol type='a'><li>of a portion of space<ol><li>boundary</li><li>frontier</li><li>the ends of the earth</li><li>the remotest lands</li></ol><li>of a thing extending through a period of time (termination)</li></ol></li></ol>","xlit":"péras"},"G5103":{"derivation":"of Latin origin but uncertain significance;","strongs_def":" Titus, a Christian","kjv_def":"Titus","translit":"Títos","lemma":"Τίτος","pron":"tee'-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Titus = \"nurse\"</p><ol><li>a Gentile Christian an Paul's companion in some of his journeys</li></ol>","xlit":"Títos"},"G1493":{"derivation":"neuter of a presumed derivative of G1497 (εἴδωλον);","strongs_def":" an image-fane","kjv_def":"idol's temple","translit":"eidōleîon","lemma":"εἰδωλεῖον","pron":"i-do-li'-on","pos":"Noun Neuter","thayer":"<ol><li>an idol's temple, temple consecrated to idols</li></ol>","xlit":"eidōleîon"},"G1572":{"kjv_def":"burn","lemma":"ἐκκαίω","translit":"ekkaíō","derivation":"from G1537 (ἐκ) and G2545 (καίω);","strongs_def":" to inflame deeply","pron":"ek-kah'-yo","pos":"Verb","thayer":"<ol><li>to burn out</li><li>to set on fire</li><li>to be kindled, to burn</li></ol>","xlit":"ekkaíō"},"G4657":{"strongs_def":" what is thrown to the dogs, i.e. refuse (ordure)","derivation":"neuter of a presumed derivative of G1519 (εἰς) and G2965 (κύων) and G906 (βάλλω);","lemma":"σκύβαλον","translit":"skýbalon","kjv_def":"dung","pron":"skoo'-bal-on","pos":"Noun Neuter","thayer":"<ol><li>any refuse, as the excrement of animals, offscourings, rubbish, dregs<ol type='a'><li>of things worthless and detestable</li></ol></li></ol>","xlit":"skýbalon"},"G4594":{"kjv_def":"this (to-)day","lemma":"σήμερον","translit":"sḗmeron","derivation":"neuter (as adverb) of a presumed compound of the article G3588 (ὁ) (t changed to s) and G2250 (ἡμέρα);","strongs_def":" on the (i.e. this) day (or night current or just passed); generally, now (i.e. at present, hitherto)","pron":"say'-mer-on","pos":"Adverb","thayer":"<ol><li>this (very) day)</li><li>what has happened today</li></ol>","xlit":"sḗmeron"},"G1076":{"translit":"genealogía","lemma":"γενεαλογία","kjv_def":"genealogy","strongs_def":" tracing by generations, i.e. \"genealogy\"","derivation":"from the same as G1075 (γενεαλογέω);","pron":"ghen-eh-al-og-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a genealogy, a record of descent or lineage</li></ol>","xlit":"genealogía"},"G287":{"translit":"amoibḗ","lemma":"ἀμοιβή","kjv_def":"requite","strongs_def":" requital","derivation":"from (to exchange);","pron":"am-oy-bay'","pos":"Noun Feminine","thayer":"<ol><li>requital, recompence</li></ol>","xlit":"amoibḗ"},"G4392":{"lemma":"πρόφασις","translit":"próphasis","kjv_def":"cloke, colour, pretence, show","strongs_def":" an outward showing, i.e. pretext","derivation":"from a compound of G4253 (πρό) and G5316 (φαίνω);","pron":"prof'-as-is","pos":"Noun Feminine","thayer":"<ol><li>a pretext (alleged reason, pretended cause)</li><li>show<ol type='a'><li>under colour as though they would do something</li><li>in pretence, ostensibly</li></ol></li></ol>","xlit":"próphasis"},"G3866":{"strongs_def":" a deposit, i.e. (figuratively) trust","derivation":"from G3908 (παρατίθημι);","lemma":"παραθήκη","translit":"parathḗkē","kjv_def":"committed unto","pron":"par-ath-ay'-kay","pos":"Noun Feminine","thayer":"<ol><li>a deposit, a trust or thing consigned to one's faithful keeping<ol type='a'><li>used of the correct knowledge and pure doctrine of the gospel, to be held firmly and faithfully, and to be conscientiously delivered unto others</li></ol></li></ol>","xlit":"parathḗkē"},"G970":{"translit":"bía","lemma":"βία","kjv_def":"violence","strongs_def":" force","derivation":"probably akin to G979 (βίος) (through the idea of vital activity);","pron":"bee'-ah","pos":"Noun Feminine","thayer":"<ol><li>strength, whether of body or mind</li><li>strength in violent action, force</li></ol>","xlit":"bía"},"G3352":{"strongs_def":" participation, i.e. intercourse","derivation":"from G3348 (μετέχω);","lemma":"μετοχή","translit":"metochḗ","kjv_def":"fellowship","pron":"met-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>a sharing, communion, fellowship</li></ol>","xlit":"metochḗ"},"G1577":{"kjv_def":"assembly, church","translit":"ekklēsía","lemma":"ἐκκλησία","derivation":"from a compound of G1537 (ἐκ) and a derivative of G2564 (καλέω);","strongs_def":" a calling out, i.e. (concretely) a popular meeting, especially a religious congregation (Jewish synagogue, or Christian community of members on earth or saints in heaven or both)","pron":"ek-klay-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>a gathering of citizens called out from their homes into some public place, an assembly<ol type='a'><li>an assembly of the people convened at the public place of the council for the purpose of deliberating</li><li>the assembly of the Israelites</li><li>any gathering or throng of men assembled by chance, tumultuously</li><li>in a Christian sense<ol><li>an assembly of Christians gathered for worship in a religious meeting</li><li>a company of Christian, or of those who, hoping for eternal salvation through Jesus Christ, observe their own religious rites, hold their own religious meetings, and manage their own affairs, according to regulations prescribed for the body for order's sake</li><li>those who anywhere, in a city, village, constitute such a company and are united into one body</li><li>the whole body of Christians scattered throughout the earth</li><li>the assembly of faithful Christians already dead and received into heaven</li></ol></li></ol></li></ol>","xlit":"ekklēsía"},"G5259":{"strongs_def":" under, i.e. (with the genitive case) of place (beneath), or with verbs (the agency or means, through); (with the accusative case) of place (whither (underneath) or where (below) or time (when (at))","derivation":"a primary preposition;","translit":"hypó","lemma":"ὑπό","kjv_def":"among, by, from, in, of, under, with","pron":"hoop-o'","pos":"Preposition","thayer":"<ol><li>by, under</li></ol>","xlit":"hypó"},"G3635":{"strongs_def":" to be slow (figuratively, loath)","derivation":"from (hesitation);","lemma":"ὀκνέω","translit":"oknéō","kjv_def":"delay","pron":"ok-neh'-o","pos":"Verb","thayer":"<ol><li>to feel loath, to be slow</li><li>to delay, hesitate</li></ol>","xlit":"oknéō"},"G1759":{"strongs_def":" properly, within, i.e. (of place) here, hither","derivation":"from a prolonged form of G1722 (ἐν);","translit":"entháde","lemma":"ἐνθάδε","kjv_def":"(t-)here, hither","pron":"en-thad'-eh","pos":"Adverb","thayer":"<ol><li>here</li><li>hither</li></ol>","xlit":"entháde"},"G4864":{"derivation":"from (the reduplicated form of) G4863 (συνάγω);","strongs_def":" an assemblage of persons; specially, a Jewish \"synagogue\" (the meeting or the place); by analogy, a Christian church","kjv_def":"assembly, congregation, synagogue","translit":"synagōgḗ","lemma":"συναγωγή","pron":"soon-ag-o-gay'","pos":"Noun Feminine","thayer":"<ol><li>a bringing together, gathering (as of fruits), a contracting</li><li>in the NT, an assembling together of men, an assembly of men</li><li>a synagogue<ol type='a'><li>an assembly of Jews formally gathered together to offer prayers and listen to the reading and expositions of the scriptures; assemblies of that sort were held every sabbath and feast day, afterwards also on the second and fifth days of every week; name transferred to an assembly of Christians formally gathered together for religious purposes</li><li>the buildings where those solemn Jewish assemblies are held. Synagogues seem to date their origin from the Babylonian exile. In the times of Jesus and the apostles every town, not only in Palestine, but also among the Gentiles if it contained a considerable number of Jewish inhabitants, had at least one synagogue, the larger towns several or even many. These were also used for trials and inflicting punishment.</li></ol></li></ol>","xlit":"synagōgḗ"},"G3357":{"kjv_def":"a little","translit":"metríōs","lemma":"μετρίως","derivation":"adverb from a derivative of G3358 (μέτρον);","strongs_def":" moderately, i.e. slightly","pron":"met-ree'-oce","pos":"Adverb","thayer":"<ol><li>in due measure</li><li>moderately, exceedingly</li></ol>","xlit":"metríōs"},"G2485":{"strongs_def":" a petty fish","derivation":"diminutive from G2486 (ἰχθύς);","lemma":"ἰχθύδιον","translit":"ichthýdion","kjv_def":"little (small) fish","pron":"ikh-thoo'-dee-on","pos":"Noun Neuter","thayer":"<ol><li>a little fish</li></ol>","xlit":"ichthýdion"},"G1302":{"lemma":"διατί","translit":"diatí","kjv_def":"wherefore, why","strongs_def":" through what cause ?, i.e. why?","derivation":"from G1223 (διά) and G5101 (τίς);","pron":"dee-at-ee'","thayer":"<ol><li>through, by, with, because of, for the sake of</li></ol>","xlit":"diatí"},"G3061":{"kjv_def":"pestilence(-t)","translit":"loimós","lemma":"λοιμός","derivation":"of uncertain affinity;","strongs_def":" a plague (literally, the disease, or figuratively, a pest)","pron":"loy'-mos","pos":"Noun Masculine","thayer":"<ol><li>pestilence</li><li>a pestilent fellow, pest, plague</li></ol>","xlit":"loimós"},"G1809":{"strongs_def":" to demand (for trial)","derivation":"middle voice from G1537 (ἐκ) and G154 (αἰτέω);","lemma":"ἐξαιτέομαι","translit":"exaitéomai","kjv_def":"desire","pron":"ex-ahee-teh'-om-ahee","pos":"Verb","thayer":"<ol><li>to ask from, demand of<ol type='a'><li>to ask or beg for one's self, to ask that one be given up to one from the power of another</li><li>in a good sense<ol><li>to beg one from another</li><li>ask for the pardon</li><li>the safety of some one</li></ol><li>in a bad sense<ol><li>for torture</li><li>for punishment</li></ol></li></ol></li></ol>","xlit":"exaitéomai"},"G5282":{"lemma":"ὑπονοέω","translit":"hyponoéō","kjv_def":"think, suppose, deem","strongs_def":" to think under (privately), i.e. to surmise or conjecture","derivation":"from G5259 (ὑπό) and G3539 (νοιέω);","pron":"hoop-on-o-eh'-o","pos":"Verb","thayer":"<ol><li>to suppose, surmise</li></ol>","xlit":"hyponoéō"},"G4951":{"lemma":"σύρω","translit":"sýrō","kjv_def":"drag, draw, hale","strongs_def":" to trail","derivation":"probably akin to G138 (αἱρέομαι);","pron":"soo'-ro","thayer":"<ol><li>to draw, drag<ol type='a'><li>of one before the judge, to prison, to punishment</li></ol></li></ol>","xlit":"sýrō"},"G1629":{"strongs_def":" to frighten utterly","derivation":"from G1537 (ἐκ) and G5399 (φοβέω);","lemma":"ἐκφοβέω","translit":"ekphobéō","kjv_def":"terrify","pron":"ek-fob-eh'-o","pos":"Verb","thayer":"<ol><li>to frighten away, to terrify</li><li>to throw into violent flight</li></ol>","xlit":"ekphobéō"},"G1613":{"lemma":"ἐκταράσσω","translit":"ektarássō","kjv_def":"exceedingly trouble","strongs_def":" to disturb wholly","derivation":"from G1537 (ἐκ) and G5015 (ταράσσω);","pron":"ek-tar-as'-so","pos":"Verb","thayer":"<ol><li>to agitate, trouble, exceedingly</li></ol>","xlit":"ektarássō"},"G1265":{"derivation":"from G1223 (διά) and G3306 (μένω);","strongs_def":" to stay constantly (in being or relation)","kjv_def":"continue, remain","translit":"diaménō","lemma":"διαμένω","pron":"dee-am-en'-o","pos":"Verb","thayer":"<ol><li>to stay permanently, remain permanently, continue</li></ol>","xlit":"diaménō"},"G4908":{"kjv_def":"prudent","lemma":"συνετός","translit":"synetós","derivation":"from G4920 (συνίημι);","strongs_def":" mentally put (or putting) together, i.e. sagacious","pron":"soon-et'-os","pos":"Adjective","thayer":"<ol><li>intelligent, having understanding, wise, learned</li></ol>","xlit":"synetós"},"G1381":{"lemma":"δοκιμάζω","translit":"dokimázō","kjv_def":"allow, discern, examine, X like, (ap-)prove, try","strongs_def":" to test (literally or figuratively); by implication, to approve","derivation":"from G1384 (δόκιμος);","pron":"dok-im-ad'-zo","pos":"Verb","thayer":"<ol><li>to test, examine, prove, scrutinise (to see whether a thing is genuine or not), as metals</li><li>to recognise as genuine after examination, to approve, deem worthy</li></ol>","xlit":"dokimázō"},"G2150":{"derivation":"from G2152 (εὐσεβής);","strongs_def":" piety; specially, the gospel scheme","kjv_def":"godliness, holiness","translit":"eusébeia","lemma":"εὐσέβεια","pron":"yoo-seb'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>reverence, respect</li><li>piety towards God, godliness</li></ol>","xlit":"eusébeia"},"G3432":{"lemma":"μοιχός","translit":"moichós","kjv_def":"adulterer","strongs_def":" a (male) paramour; figuratively, apostate","derivation":"perhaps a primary word;","pron":"moy-khos'","pos":"Noun Masculine","thayer":"<ol><li>an adulterer</li><li>metaphorically one who is faithless toward God, ungodly</li></ol>","xlit":"moichós"},"G3785":{"lemma":"ὄφελον","translit":"óphelon","kjv_def":"would (to God)","strongs_def":" I ought (wish), i.e. (interjection) oh that!","derivation":"first person singular of a past tense of G3784 (ὀφείλω);","pron":"of'-el-on","thayer":"<ol><li>would that, where one wishes that a thing had happened which has not happened or a thing be done which probably will not be done</li></ol>","xlit":"óphelon"},"G660":{"kjv_def":"shake off","lemma":"ἀποτινάσσω","translit":"apotinássō","derivation":"from G575 (ἀπό) and (to jostle);","strongs_def":" to brush off","pron":"ap-ot-in-as'-so","pos":"Verb","thayer":"<ol><li>to shake off</li></ol>","xlit":"apotinássō"},"G318":{"strongs_def":" constraint (literally or figuratively); by implication, distress","derivation":"from G303 (ἀνά) and the base of G43 (ἀγκάλη);","lemma":"ἀνάγκη","translit":"anánkē","kjv_def":"distress, must needs, (of) necessity(-sary), needeth, needful","pron":"an-ang-kay'","pos":"Noun Feminine","thayer":"<ol><li>necessity, imposed either by the circumstances, or by law of duty regarding to one's advantage, custom, argument</li><li>calamity, distress, straits</li></ol>","xlit":"anánkē"},"G886":{"strongs_def":" unmanufactured, i.e. inartificial","derivation":"from G1 (Α) (as a negative particle) and G5499 (χειροποίητος);","lemma":"ἀχειροποίητος","translit":"acheiropoíētos","kjv_def":"made without (not made with) hands","pron":"akh-i-rop-oy'-ay-tos","pos":"Adjective","thayer":"<ol><li>not made with hands</li></ol>","xlit":"acheiropoíētos"},"G1143":{"translit":"dáknō","lemma":"δάκνω","kjv_def":"bite","strongs_def":" to bite, i.e. (figuratively) thwart","derivation":"a prolonged form of a primary root;","pron":"dak'-no","pos":"Verb","thayer":"<ol><li>to bite with the teeth</li><li>metaphorically, to wound the soul, cut lacerate, rend with reproaches</li></ol>","xlit":"dáknō"},"G1916":{"derivation":"from G1909 (ἐπί) and G994 (βοάω);","strongs_def":" to exclaim against","kjv_def":"cry","translit":"epiboáō","lemma":"ἐπιβοάω","pron":"ep-ee-bo-ah'-o","pos":"Verb","thayer":"<ol><li>to cry out to, cry out</li></ol>","xlit":"epiboáō"},"G3532":{"strongs_def":" victorious over the people; Nicolaus, a heretic","derivation":"from G3534 (νῖκος) and G2994 (Λαοδικεύς);","translit":"Nikólaos","lemma":"Νικόλαος","kjv_def":"Nicolaus","pron":"nik-ol'-ah-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nicolas = \"victor of the people\"</p><ol><li>was a proselyte of Antioch and one of the seven deacons of the church at Jerusalem</li></ol>","xlit":"Nikólaos"},"G2911":{"strongs_def":" overhanging, i.e. a precipice","derivation":"from G2910 (κρεμάννυμι);","lemma":"κρημνός","translit":"krēmnós","kjv_def":"steep place","pron":"krame-nos'","pos":"Noun Masculine","thayer":"<ol><li>a steep place, a precipice</li></ol>","xlit":"krēmnós"},"G1172":{"kjv_def":"sup (X -er)","lemma":"δειπνέω","translit":"deipnéō","derivation":"from G1173 (δεῖπνον);","strongs_def":" to dine, i.e. take the principle (or evening) meal","pron":"dipe-neh'-o","pos":"Verb","thayer":"<ol><li>to sup</li></ol>","xlit":"deipnéō"},"G5033":{"derivation":"neuter plural of the superlative of G5036 (ταχύς) (as adverb);","strongs_def":" most quickly, i.e. (with G5613 (ὡς) prefixed) as soon as possible","kjv_def":"+ with all speed","lemma":"τάχιστα","translit":"táchista","pron":"takh'-is-tah","pos":"Adjective","thayer":"<ol><li>very quickly</li></ol>","xlit":"táchista"},"G386":{"lemma":"ἀνάστασις","translit":"anástasis","kjv_def":"raised to life again, resurrection, rise from the dead, that should rise, rising again","strongs_def":" a standing up again, i.e. (literally) a resurrection from death (individual, genitive case or by implication, (its author)), or (figuratively) a (moral) recovery (of spiritual truth)","derivation":"from G450 (ἀνίστημι);","pron":"an-as'-tas-is","pos":"Noun Feminine","thayer":"<ol><li>a raising up, rising (e.g. from a seat)</li><li>a rising from the dead<ol type='a'><li>that of Christ</li><li>that of all men at the end of this present age</li><li>the resurrection of certain ones history who were restored to life (<a class='bible' href='#b58.11.35'>Heb 11:35</a>)</li></ol></li></ol>","xlit":"anástasis"},"G1844":{"derivation":"from G1537 (ἐκ) and G3726 (ὁρκίζω);","strongs_def":" to exact an oath, i.e. conjure","kjv_def":"adjure","translit":"exorkízō","lemma":"ἐξορκίζω","pron":"ex-or-kid'-zo","pos":"Verb","thayer":"<ol><li>to extract an oath, to force to an oath</li><li>to adjure</li></ol>","xlit":"exorkízō"},"G1905":{"translit":"eperōtáō","lemma":"ἐπερωτάω","kjv_def":"ask (after, questions), demand, desire, question","strongs_def":" to ask for, i.e. inquire, seek","derivation":"from G1909 (ἐπί) and G2065 (ἐρωτάω);","pron":"ep-er-o-tah'-o","pos":"Verb","thayer":"<ol><li>to accost one with an enquiry, put a question to, enquiry of, ask, interrogate</li><li>to address one with a request or demand<ol type='a'><li>to ask of or demand of one</li></ol></li></ol>","xlit":"eperōtáō"},"G5345":{"derivation":"from G5346 (φημί);","strongs_def":" a saying, i.e. rumor (\"fame\")","kjv_def":"fame","translit":"phḗmē","lemma":"φήμη","pron":"fay'-may","pos":"Noun Feminine","thayer":"<ol><li>fame, report</li></ol>","xlit":"phḗmē"},"G2862":{"kjv_def":"colony","lemma":"κολωνία","translit":"kolōnía","derivation":"of Latin origin;","strongs_def":" a Roman \"colony\" for veterans","pron":"kol-o-nee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a colony<ol type='a'><li>the city of Philippi is so called, where Octavius had planted a Roman colony</li></ol></li></ol>","xlit":"kolōnía"},"G2703":{"kjv_def":"flee","translit":"katapheúgō","lemma":"καταφεύγω","derivation":"from G2596 (κατά) and G5343 (φεύγω);","strongs_def":" to flee down (away)","pron":"kat-af-yoo'-go","pos":"Verb","thayer":"<ol><li>to flee away, flee for refuge</li></ol>","xlit":"katapheúgō"},"G5147":{"kjv_def":"path","lemma":"τρίβος","translit":"tríbos","derivation":"from (to \"rub\";","strongs_def":" akin to , , and the base of G5131 (τράγος), G5134 (τραῦμα)); a rut or worn track","pron":"tree'-bos","pos":"Noun Feminine","thayer":"<ol><li>a worn way, a path</li></ol>","xlit":"tríbos"},"G4317":{"kjv_def":"bring, draw near","translit":"proságō","lemma":"προσάγω","derivation":"from G4314 (πρός) and G71 (ἄγω);","strongs_def":" to lead towards, i.e. (transitively) to conduct near (summon, present), or (intransitively) to approach","pron":"pros-ag'-o","pos":"Verb","thayer":"<ol><li>to lead, to bring<ol type='a'><li>to open a way of access, for one to God<ol><li>to render one acceptable to God</li></ol><li>in a forensic sense, to summon (to trial or punishment)</li></ol><li>to draw near to, approach<ol type='a'><li>the land which a sailor is approaching seeming to approach him</li></ol></li></ol>","xlit":"proságō"},"G5523":{"kjv_def":"Chorazin","translit":"Chorazín","lemma":"Χοραζίν","derivation":"of uncertain derivation;","strongs_def":" Chorazin, a place in Palestine","pron":"khor-ad-zin'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Chorazin = \"a furnace of smoke\"</p><ol><li>a town in Galilee</li></ol>","xlit":"Chorazín"},"G1332":{"kjv_def":"two years old","translit":"dietḗs","lemma":"διετής","derivation":"from G1364 (δίς) and G2094 (ἔτος);","strongs_def":" of two years (in age)","pron":"dee-et-ace'","pos":"Adjective","thayer":"<ol><li>of two years, two years old</li></ol>","xlit":"dietḗs"},"G4896":{"kjv_def":"gather together","translit":"sýneimi","lemma":"σύνειμι","derivation":"from G4862 (σύν) and (to go);","strongs_def":" to assemble","pron":"soon'-i-mee","pos":"Verb","thayer":"<ol><li>to come together</li></ol>","xlit":"sýneimi"},"G3355":{"derivation":"from G3354 (μετρέω);","strongs_def":" a measurer, i.e. (specially), a certain standard measure of capacity for liquids","kjv_def":"firkin","lemma":"μετρητής","translit":"metrētḗs","pron":"met-ray-tace'","pos":"Noun Masculine","thayer":"<ol><li>a measurer, the name of a utensil known as a amphora, which is a species of measure used for liquids and containing somewhat less the nine English gallons or about (40 l)</li></ol>","xlit":"metrētḗs"},"G4046":{"kjv_def":"purchase","translit":"peripoiéomai","lemma":"περιποιέομαι","derivation":"middle voice from G4012 (περί) and G4160 (ποιέω);","strongs_def":" to make around oneself, i.e. acquire (buy)","pron":"per-ee-poy-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to make to remain over</li><li>to reserve, to leave or keep safe, lay by</li><li>to make to remain for one's self</li><li>to preserve for one's self</li><li>to get for one's self, purchase</li></ol>","xlit":"peripoiéomai"},"G1567":{"kjv_def":"en- (re-)quire, seek after (carefully, diligently)","translit":"ekzētéō","lemma":"ἐκζητέω","derivation":"from G1537 (ἐκ) and G2212 (ζητέω);","strongs_def":" to search out, i.e. (figuratively)investigate, crave, demand, (by Hebraism) worship","pron":"ek-zay-teh'-o","pos":"Verb","thayer":"<ol><li>to seek out, search for</li><li>to seek out, i.e. investigate, scrutinise</li><li>to seek out for one's self, beg, crave</li><li>to demand back, require</li></ol>","xlit":"ekzētéō"},"G2525":{"strongs_def":" to place down (permanently), i.e. (figuratively) to designate, constitute, convoy","derivation":"from G2596 (κατά) and G2476 (ἵστημι);","lemma":"καθίστημι","translit":"kathístēmi","kjv_def":"appoint, be, conduct, make, ordain, set","pron":"kath-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to set, place, put<ol type='a'><li>to set one over a thing (in charge of it)</li><li>to appoint one to administer an office</li><li>to set down as, constitute, to declare, show to be</li><li>to constitute, to render, make, cause to be</li><li>to conduct or bring to a certain place</li><li>to show or exhibit one's self<ol><li>come forward as</li></ol></li></ol></li></ol>","xlit":"kathístēmi"},"G3465":{"derivation":"of uncertain origin;","strongs_def":" Mysia, a region of Asia Minor","kjv_def":"Mysia","lemma":"Μυσία","translit":"Mysía","pron":"moo-see'-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Mysia = \"land of beach trees\"</p><ol><li>a province of Asia Minor on the shore of the Aegean Sea, between Lydia and Popontis; it included the cities of Pergamos, Troas, and Assos</li></ol>","xlit":"Mysía"},"G3479":{"strongs_def":" a Nazarene, i.e. inhabitant of Nazareth","derivation":"from G3478 (Ναζαρέθ);","lemma":"Ναζαρηνός","translit":"Nazarēnós","kjv_def":"of Nazareth","pron":"nad-zar-ay-nos'","pos":"Adjective","thayer":"<ol><li>a resident of Nazareth</li></ol>","xlit":"Nazarēnós"},"G2600":{"lemma":"κατάβασις","translit":"katábasis","kjv_def":"descent","strongs_def":" a declivity","derivation":"from G2597 (καταβαίνω);","pron":"kat-ab'-as-is","pos":"Noun Feminine","thayer":"<ol><li>descent<ol type='a'><li>the act of descending</li><li>the place of descent<ol><li>that part of the mountain where the descent is made</li></ol></li></ol></li></ol>","xlit":"katábasis"},"G3489":{"translit":"nauagéō","lemma":"ναυαγέω","kjv_def":"make (suffer) shipwreck","strongs_def":" to be shipwrecked (stranded, \"navigate\"), literally or figuratively","derivation":"from a compound of G3491 (ναῦς) and G71 (ἄγω);","pron":"now-ag-eh'-o","pos":"Verb","thayer":"<ol><li>to suffer shipwreck</li></ol>","xlit":"nauagéō"},"G2775":{"kjv_def":"wound in the head","lemma":"κεφαλαιόω","translit":"kephalaióō","derivation":"from the same as G2774 (κεφάλαιον);","strongs_def":" (specially) to strike on the head","pron":"kef-al-ahee-o'-o","pos":"Verb","thayer":"<ol><li>to bring under headings, to sum up, to summarise</li><li>to smite or wound in the head, to smite on the cheek</li></ol>","xlit":"kephalaióō"},"G1086":{"strongs_def":" a Gergesene (i.e. Girgashite) or one of the aborigines of Palestine","derivation":"of Hebrew origin (H01622);","lemma":"Γεργεσηνός","translit":"Gergesēnós","kjv_def":"Gergesene","pron":"gher-ghes-ay-nos'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Gergesenes = \"a stranger drawing near\" ?</p><ol><li>also called Gadarenes, is assumed to have been located on the eastern shore of Lake Gennesaret</li></ol>","xlit":"Gergesēnós"},"G4792":{"strongs_def":" to convey together, i.e. collect or bear away in company with others","derivation":"from G4862 (σύν) and G2865 (κομίζω);","lemma":"συγκομίζω","translit":"synkomízō","kjv_def":"carry","pron":"soong-kom-id'-zo","pos":"Verb","thayer":"<ol><li>to carry or bring together, to collect<ol type='a'><li>to house crops, gather into granaries</li></ol><li>to carry with others, help in carrying out, the dead to be buried or burned<ol type='a'><li>to bury</li></ol></li></ol>","xlit":"synkomízō"},"G1223":{"strongs_def":" through (in very wide applications, local, causal, or occasional)","derivation":"a primary preposition denoting the channel of an act;","lemma":"διά","translit":"diá","kjv_def":"after, always, among, at, to avoid, because of (that), briefly, by, for (cause) … fore, from, in, by occasion of, of, by reason of, for sake, that, thereby, therefore, X though, through(-out), to, wherefore, with (-in)","pron":"dee-ah'","pos":"Preposition","thayer":"<ol><li>through<ol type='a'><li>of place<ol><li>with</li><li>in</li></ol><li>of time<ol><li>throughout</li><li>during</li></ol><li>of means<ol><li>by</li><li>by the means of</li></ol></li></ol><li>through<ol type='a'><li>the ground or reason by which something is or is not done<ol><li>by reason of</li><li>on account of</li><li>because of for this reason</li><li>therefore</li><li>on this account</li></ol></li></ol></li></ol>","xlit":"diá"},"G3415":{"strongs_def":" to bear in mind, i.e. recollect; by implication, to reward or punish","derivation":"middle voice of a derivative of G3306 (μένω) or perhaps of the base of G3145 (μασσάομαι) (through the idea of fixture in the mind or of mental grasp);","lemma":"μνάομαι","translit":"mnáomai","kjv_def":"be mindful, remember, come (have) in remembrance","pron":"mnah'-om-ahee","pos":"Verb","thayer":"<ol><li>to remind<ol type='a'><li>to be recalled or to return to one's mind, to remind one's self of, to remember</li><li>to be recalled to mind, to be remembered, had in remembrance</li><li>to remember a thing</li><li>be mindful of</li></ol></li></ol>","xlit":"mnáomai"},"G5093":{"derivation":"from G5092 (τιμή);","strongs_def":" valuable, i.e. (objectively) costly, or (subjectively) honored, esteemed, or (figuratively) beloved","kjv_def":"dear, honourable, (more, most) precious, had in reputation","translit":"tímios","lemma":"τίμιος","pron":"tim'-ee-os","pos":"Adjective","thayer":"<ol><li>as of great price, precious</li><li>held in honour, esteemed, especially dear</li></ol>","xlit":"tímios"},"G3189":{"translit":"mélas","lemma":"μέλας","kjv_def":"black","strongs_def":" black","derivation":"apparently a primary word;","pron":"mel'-as","pos":"Adjective","thayer":"<ol><li>black</li><li>black ink</li></ol>","xlit":"mélas"},"G5023":{"translit":"taûta","lemma":"ταῦτα","kjv_def":"+ afterward, follow, + hereafter, X him, the same, so, such, that, then, these, they, this, those, thus","strongs_def":" these things","derivation":"nominative or accusative case neuter plural of G3778 (οὗτος);","pron":"tow'-tah","thayer":"<ol><li>these</li></ol>","xlit":"taûta"},"G1397":{"kjv_def":"bondage","lemma":"δουλεία","translit":"douleía","derivation":"from G1398 (δουλεύω);","strongs_def":" slavery (ceremonially or figuratively)","pron":"doo-li'-ah","pos":"Noun Feminine","thayer":"<ol><li>slavery, bondage, the condition of a slave</li></ol>","xlit":"douleía"},"G3890":{"derivation":"neuter of G3889 (παραμυθία);","strongs_def":" consolation (properly, concretely)","kjv_def":"comfort","lemma":"παραμύθιον","translit":"paramýthion","pron":"par-am-oo'-thee-on","pos":"Noun Neuter","thayer":"<ol><li>persuasive address</li></ol>","xlit":"paramýthion"},"G2171":{"strongs_def":" properly, a wish, expressed as a petition to God, or in votive obligation","derivation":"from G2172 (εὔχομαι);","translit":"euchḗ","lemma":"εὐχή","kjv_def":"prayer, vow","pron":"yoo-khay'","pos":"Noun Feminine","thayer":"<ol><li>a prayer to God</li><li>a vow</li></ol>","xlit":"euchḗ"},"G5438":{"strongs_def":" a guarding or (concretely, guard), the act, the person; figuratively, the place, the condition, or (specially), the time (as a division of day or night), literally or figuratively","derivation":"from G5442 (φυλάσσω);","lemma":"φυλακή","translit":"phylakḗ","kjv_def":"cage, hold, (im-)prison(-ment), ward, watch","pron":"foo-lak-ay'","pos":"Noun Feminine","thayer":"<ol><li>guard, watch<ol type='a'><li>a watching, keeping watch<ol><li>to keep watch</li></ol><li>persons keeping watch, a guard, sentinels</li><li>of the place where captives are kept, a prison</li><li>of the time (of night) during which guard was kept, a watch, i.e. a period of time during which part of the guard was on duty, and at the end of which others relieved them. As the earlier Greeks divided the night commonly into three parts, so, previous to the exile, the Israelites also had three watches in a night; subsequently, however, after they became subject to the Romans, they adopted the Roman custom of dividing the night into four watches</li></ol></li></ol>","xlit":"phylakḗ"},"G4274":{"kjv_def":"forerunner","lemma":"πρόδρομος","translit":"pródromos","derivation":"from the alternate of G4390 (προτρέχω);","strongs_def":" a runner ahead, i.e. scout (figuratively, precursor)","pron":"prod'-rom-os","pos":"Adjective","thayer":"<ol><li>a forerunner<ol type='a'><li>especially one who is sent before to take observations or act as a spy, a scout, a light armed soldier</li><li>one who comes in advance to a place where the rest are to follow</li></ol></li></ol>","xlit":"pródromos"},"G1536":{"derivation":"from G1487 (εἰ) and G5100 (τὶς);","strongs_def":" if any","kjv_def":"he that, if a(-ny) man('s thing, from any, ought), whether any, whosoever","translit":"eí tis","lemma":"εἴ τις","pron":"i tis","thayer":"<ol><li>whoever, whatever</li></ol>","xlit":"eí tis"},"G1404":{"translit":"drákōn","lemma":"δράκων","kjv_def":"dragon","strongs_def":" a fabulous kind of serpent (perhaps as supposed to fascinate)","derivation":"probably from an alternate form of (to look);","pron":"drak'-own","pos":"Noun Masculine","thayer":"<ol><li>a dragon, a great serpent, a name for Satan</li></ol>","xlit":"drákōn"},"G1501":{"strongs_def":" a score","derivation":"of uncertain affinity;","lemma":"εἴκοσι","translit":"eíkosi","kjv_def":"twenty","pron":"i'-kos-ee","pos":"Noun","thayer":"<ol><li>twenty</li></ol>","xlit":"eíkosi"},"G4988":{"kjv_def":"Sosthenes","lemma":"Σωσθένης","translit":"Sōsthénēs","derivation":"from the base of G4982 (σώζω) and that of G4599 (σθενόω);","strongs_def":" of safe strength; Sosthenes, a Christian","pron":"soce-then'-ace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sosthenes = \"saviour of his nation\"</p><ol><li>a Jew at Corinth who was seized and beaten in the presence of Gallio</li><li>a certain Christian associate of Paul</li></ol>","xlit":"Sōsthénēs"},"G5347":{"strongs_def":" festal; Phestus (i.e. Festus), a Roman","derivation":"of Latin derivation;","lemma":"Φῆστος","translit":"Phēstos","kjv_def":"Festus","pron":"face'-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: [Porcius] Festus = \"festival\"</p><ol><li>the successor of Felix as procurator of Judea</li></ol>","xlit":"Phēstos"},"G289":{"translit":"ampelourgós","lemma":"ἀμπελουργός","kjv_def":"vine-dresser","strongs_def":" a vine-worker, i.e. pruner","derivation":"from G288 (ἄμπελος) and G2041 (ἔργον);","pron":"am-pel-oor-gos'","pos":"Noun Masculine","thayer":"<ol><li>a vinedresser</li></ol>","xlit":"ampelourgós"},"G182":{"lemma":"ἀκατάστατος","translit":"akatástatos","kjv_def":"unstable","strongs_def":" inconstant","derivation":"from G1 (Α) (as a negative particle) and a derivative of G2525 (καθίστημι);","pron":"ak-at-as'-tat-os","pos":"Adjective","thayer":"<ol><li>unstable, inconstant, restless</li></ol>","xlit":"akatástatos"},"G12":{"kjv_def":"deep, (bottomless) pit","lemma":"ἄβυσσος","translit":"ábyssos","derivation":"from G1 (Α) (as a negative particle) and a variation of G1037 (βυθός);","strongs_def":" depthless, i.e. (specially) (infernal) \"abyss\"","pron":"ab'-us-sos","pos":"Noun Feminine","thayer":"<ol><li>bottomless</li><li>unbounded</li><li>the abyss<ol type='a'><li>the pit</li><li>the immeasurable depth</li><li>of Orcus, a very deep gulf or chasm in the lowest parts of the earth used as the common receptacle of the dead and especially as the abode of demons</li></ol></li></ol>","xlit":"ábyssos"},"G4911":{"kjv_def":"rise up together","translit":"synephístēmi","lemma":"συνεφίστημι","derivation":"from G4862 (σύν) and G2186 (ἐφίστημι);","strongs_def":" to stand up together, i.e. to resist (or assault) jointly","pron":"soon-ef-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to place over or appoint together</li><li>to rise up together<ol type='a'><li>against one</li></ol></li></ol>","xlit":"synephístēmi"},"G2246":{"strongs_def":" perhaps akin to the alternate of G138 (αἱρέομαι)); the sun; by implication, light","derivation":"from (a ray;","translit":"hḗlios","lemma":"ἥλιος","kjv_def":"+ east, sun","pron":"hay'-lee-os","pos":"Noun Masculine","thayer":"<ol><li>the sun</li><li>the rays of the sun</li><li>the light of day</li></ol>","xlit":"hḗlios"},"G2993":{"lemma":"Λαοδίκεια","translit":"Laodíkeia","kjv_def":"Laodicea","strongs_def":" Laodicia, a place in Asia Minor","derivation":"from a compound of G2992 (λαός) and G1349 (δίκη);","pron":"lah-od-ik'-i-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Laodicea = \"justice of the people\"</p><ol><li>a city of Phrygia, situated on the river Lycus not far from Colosse. It was destroyed by an earthquake in 66 A.D. and rebuilt by Marcus Aurelius. It was the seat of the Christian church.</li></ol>","xlit":"Laodíkeia"},"G3045":{"lemma":"λιπαρός","translit":"liparós","kjv_def":"dainty","strongs_def":" fat, i.e. (figuratively) sumptuous","derivation":"from (grease);","pron":"lip-ar-os'","pos":"Adjective","thayer":"<ol><li>things which pertain to a sumptuous and delicate style of living</li></ol>","xlit":"liparós"},"G4878":{"derivation":"from G4862 (σύν) and G482 (ἀντιλαμβάνομαι);","strongs_def":" to take hold of opposite together, i.e. co-operate (assist)","kjv_def":"help","translit":"synantilambánomai","lemma":"συναντιλαμβάνομαι","pron":"soon-an-tee-lam-ban'-om-ahee","pos":"Verb","thayer":"<ol><li>to lay hold along with, to strive to obtain with others, help in obtaining</li><li>to take hold with another</li></ol>","xlit":"synantilambánomai"},"G4198":{"derivation":"middle voice from a derivative of the same as G3984 (πεῖρα);","strongs_def":" to traverse, i.e. travel (literally or figuratively; especially to remove (figuratively, die), live, etc.); ","kjv_def":"--depart, go (away, forth, one's way, up), (make a, take a) journey, walk","translit":"poreúomai","lemma":"πορεύομαι","pron":"por-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to lead over, carry over, transfer<ol type='a'><li>to pursue the journey on which one has entered, to continue on one's journey</li><li>to depart from life</li><li>to follow one, that is: become his adherent<ol><li>to lead or order one's life</li></ol></li></ol></li></ol>","xlit":"poreúomai"},"G4306":{"derivation":"from G4253 (πρό) and G3539 (νοιέω);","strongs_def":" to consider in advance, i.e. look out for beforehand (actively, by way of maintenance for others; middle voice by way of circumspection for oneself)","kjv_def":"provide (for)","lemma":"προνοέω","translit":"pronoéō","pron":"pron-o-eh'-o","pos":"Verb","thayer":"<ol><li>to perceive before, foresee</li><li>to provide, think of beforehand<ol type='a'><li>to provide for one</li><li>to take thought for, care for a thing</li></ol></li></ol>","xlit":"pronoéō"},"G3323":{"strongs_def":" the Messias (i.e. Mashiach), or Christ","derivation":"of Hebrew origin (H04899);","lemma":"Μεσσίας","translit":"Messías","kjv_def":"Messias","pron":"mes-see'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Messias = \"anointed\"</p><ol><li>the Greek form of Messiah</li><li>a name of Christ</li></ol>","xlit":"Messías"},"G474":{"strongs_def":" to bandy","derivation":"from G473 (ἀντί) and G906 (βάλλω);","translit":"antibállō","lemma":"ἀντιβάλλω","kjv_def":"have","pron":"an-tee-bal'-lo","pos":"Verb","thayer":"<ol><li>to throw in turn</li></ol>","xlit":"antibállō"},"G4128":{"translit":"plēthos","lemma":"πλῆθος","kjv_def":"bundle, company, multitude","strongs_def":" a fulness, i.e. a large number, throng, populace","derivation":"from G4130 (πλήθω);","pron":"play'-thos","pos":"Noun Neuter","thayer":"<ol><li>a multitude<ol type='a'><li>a great number, of men or things</li><li>the whole number, the whole multitude, the assemblage<ol><li>the multitude of the people</li></ol></li></ol></li></ol>","xlit":"plēthos"},"G1093":{"kjv_def":"country, earth(-ly), ground, land, world","translit":"gē","lemma":"γῆ","derivation":"contracted from a primary word;","strongs_def":" soil; by extension a region, or the solid part or the whole of the terrene globe (including the occupants in each application)","pron":"ghay","pos":"Noun Feminine","thayer":"<ol><li>arable land</li><li>the ground, the earth as a standing place</li><li>the main land as opposed to the sea or water</li><li>the earth as a whole<ol type='a'><li>the earth as opposed to the heavens</li><li>the inhabited earth, the abode of men and animals</li></ol><li>a country, land enclosed within fixed boundaries, a tract of land, territory, region</li></ol>","xlit":"gē"},"G60":{"strongs_def":" relating to the market-place, i.e. forensic (times); by implication, vulgar","derivation":"from G58 (ἀγορά);","translit":"agoraîos","lemma":"ἀγοραῖος","kjv_def":"baser sort, low","pron":"ag-or-ah'-yos","pos":"Adjective","thayer":"<ol><li>in, of or belonging to the market place</li><li>frequenting the market place<ol type='a'><li>hucksters, petty traffickers, retail dealers</li><li>idlers, loungers, the common sort, low, mean vulgar</li></ol><li>generally, proper to the assembly, suited to forensic speaking, business-like transactions</li></ol>","xlit":"agoraîos"},"G4324":{"strongs_def":" to menace additionally","derivation":"from G4314 (πρός) and G546 (ἀπειλέω);","lemma":"προσαπειλέω","translit":"prosapeiléō","kjv_def":"i","pron":"pros-ap-i-leh'-o","pos":"Verb","thayer":"<ol><li>to add threats, threaten further</li></ol>","xlit":"prosapeiléō"},"G5506":{"derivation":"from G5507 (χίλιοι) and G757 (ἄρχω);","strongs_def":" the commander of a thousand soldiers (\"chiliarch\"; i.e. colonel","kjv_def":"(chief, high) captain","lemma":"χιλίαρχος","translit":"chilíarchos","pron":"khil-ee'-ar-khos","pos":"Noun Masculine","thayer":"<ol><li>a chiliarch, the commander of a thousand soldiers</li><li>the commander of a Roman cohort (a military tribunal)</li><li>any military commander</li></ol>","xlit":"chilíarchos"},"G1945":{"kjv_def":"impose, be instant, (be) laid (there-, up-)on, (when) lay (on), lie (on), press upon","lemma":"ἐπίκειμαι","translit":"epíkeimai","derivation":"from G1909 (ἐπί) and G2749 (κεῖμαι);","strongs_def":" to rest upon (literally or figuratively)","pron":"ep-ik'-i-mahee","pos":"Verb","thayer":"<ol><li>to lie upon or over, rest upon, be laid or placed upon<ol type='a'><li>on the burning coals</li></ol><li>metaphorically<ol type='a'><li>of things, of the pressure of a violent tempest</li><li>of men, to press upon, to be urgent</li></ol></li></ol>","xlit":"epíkeimai"},"G610":{"derivation":"from G611 (ἀποκρίνομαι) (in its original sense of judging);","strongs_def":" a judicial decision","kjv_def":"sentence","translit":"apókrima","lemma":"ἀπόκριμα","pron":"ap-ok'-ree-mah","pos":"Noun Neuter","thayer":"<ol><li>an answer<ol type='a'><li><a class='bible' href='#b47.1.9'>2Co 1:9</a> where the meaning is \"on asking myself whether I shouldcome out safe from mortal peril, I answered 'I must die'\"</li></ol></li></ol>","xlit":"apókrima"},"G2216":{"derivation":"of Hebrew origin (H02216);","strongs_def":" Zorobabel (i.e. Zerubbabel), an Israelite","kjv_def":"Zorobabel","lemma":"Ζοροβάβελ","translit":"Zorobábel","pron":"dzor-ob-ab'-el","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Zerubbabel = \"born at Babel, i.e. Babylon\"</p><ol><li>the head of the tribe of Judah at the time of the return from Babylonish captivity in the first year of Cyrus</li></ol>","xlit":"Zorobábel"},"G962":{"lemma":"Βηθαβαρά","translit":"Bēthabará","kjv_def":"Bethabara","strongs_def":" ferry-house; Bethabara (i.e. Bethabarah), a place on the Jordan","derivation":"of Hebrew origin (H01004 and H05679);","pron":"bay-thab-ar-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethabara = \"house of the ford\"</p><ol><li>a place beyond Jordan, where John was baptising. This may correspond to Bethbarah (fords of Abarah), the ancient ford of the Jordan on the road to Gilead</li></ol>","xlit":"Bēthabará"},"G131":{"strongs_def":" to flow blood, i.e. have a hæmorrhage","derivation":"from G129 (αἷμα) and G4482 (ῥέω);","lemma":"αἱμοῤῥέω","translit":"haimorrhéō","kjv_def":"diseased with an issue of blood","pron":"hahee-mor-hreh'-o","pos":"Verb","thayer":"<ol><li>to suffer from a flow of blood, to have a discharge of blood, to lose blood</li></ol>","xlit":"haimorrhéō"},"G4717":{"translit":"stauróō","lemma":"σταυρόω","kjv_def":"crucify","strongs_def":" to impale on the cross; figuratively, to extinguish (subdue) passion or selfishness","derivation":"from G4716 (σταυρός);","pron":"stow-ro'-o","pos":"Verb","thayer":"<ol><li>to stake, drive down stakes</li><li>to fortify with driven stakes, to palisade</li><li>to crucify<ol type='a'><li>to crucify one</li><li>metaphorically to crucify the flesh, destroy its power utterly (the nature of the figure implying that the destruction is attended with intense pain)</li></ol></li></ol>","xlit":"stauróō"},"G2143":{"derivation":"from a compound of G2095 (εὖ) and G4241 (πρέπω);","strongs_def":" good suitableness, i.e. gracefulness","kjv_def":"grace","translit":"euprépeia","lemma":"εὐπρέπεια","pron":"yoo-prep'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>goodly appearance, shapeliness, beauty, comeliness</li></ol>","xlit":"euprépeia"},"G5432":{"lemma":"φρουρέω","translit":"phrouréō","kjv_def":"keep (with a garrison)","strongs_def":" to be a watcher in advance, i.e. to mount guard as a sentinel (post spies at gates); figuratively, to hem in, protect","derivation":"from a compound of G4253 (πρό) and G3708 (ὁράω);","pron":"froo-reh'-o","pos":"Verb","thayer":"<ol><li>to guard, protect by a military guard, either to prevent hostile invasion, or to keep the inhabitants of a besieged city from flight</li><li>metaphorically<ol type='a'><li>under the control of the Mosaic law, that he might not escape from its power</li><li>to protect by guarding, to keep</li><li>by watching and guarding to preserve one for the attainment of something</li></ol></li></ol>","xlit":"phrouréō"},"G65":{"derivation":"from G66 (ἄγριος) and G1636 (ἐλαία);","strongs_def":" an oleaster","kjv_def":"olive tree (which is) wild","translit":"agriélaios","lemma":"ἀγριέλαιος","pron":"ag-ree-el'-ah-yos","pos":"Adjective","thayer":"<ol><li>of or belonging to the oleaster or wild olive</li><li>the oleaster, wild olive tree</li></ol>","xlit":"agriélaios"},"G1537":{"strongs_def":" literal or figurative; direct or remote)","derivation":"a primary preposition denoting origin (the point whence action or motion proceeds), from, out (of place, time, or cause;","translit":"ek","lemma":"ἐκ","kjv_def":"after, among, X are, at, betwixt(-yond), by (the means of), exceedingly, (+ abundantly above), for(- th), from (among, forth, up), + grudgingly, + heartily, X heavenly, X hereby, + very highly, in, …ly, (because, by reason) of, off (from), on, out among (from, of), over, since, X thenceforth, through, X unto, X vehemently, with(-out)","pron":"ek","pos":"Preposition","thayer":"<ol><li>out of, from, by, away from</li></ol>","xlit":"ek"},"G9":{"derivation":"of foreign origin (compare H058);","strongs_def":" Abilene, a region of Syria","kjv_def":"Abilene","lemma":"Ἀβιληνή","translit":"Abilēnḗ","pron":"ab-ee-lay-nay'","pos":"Proper Name Location","thayer":"<strong>Thayer Definition</strong>: Abilene = \"grassy meadow\"</p><ol><li>a region of Syria between Lebanon and Hermon towards Phoenicia, 18 miles (29 km) from Damascus and 37 miles (60 km) from Heliopolis</li></ol>","xlit":"Abilēnḗ"},"G1861":{"strongs_def":" to announce upon (reflexively), i.e. (by implication) to engage to do something, to assert something respecting oneself","derivation":"from G1909 (ἐπί) and the base of G32 (ἄγγελος);","translit":"epangéllō","lemma":"ἐπαγγέλλω","kjv_def":"profess, (make) promise","pron":"ep-ang-el'-lo","pos":"Verb","thayer":"<ol><li>to announce that one is about to do or furnish something<ol type='a'><li>to promise (of one's own accord) to engage voluntarily</li></ol><li>to profess<ol type='a'><li>an art, to profess one's skill in something</li></ol></li></ol>","xlit":"epangéllō"},"G5467":{"kjv_def":"fierce, perilous","lemma":"χαλεπός","translit":"chalepós","derivation":"perhaps from G5465 (χαλάω) through the idea of reducing the strength;","strongs_def":" difficult, i.e. dangerous, or (by implication) furious","pron":"khal-ep-os'","pos":"Adjective","thayer":"<ol><li>hard to do, to take, to approach</li><li>hard to bear, troublesome, dangerous<ol type='a'><li>harsh, fierce, savage</li></ol></li></ol>","xlit":"chalepós"},"G2204":{"strongs_def":" to be hot (boil, of liquids; or glow, of solids), i.e. (figuratively) be fervid (earnest)","derivation":"a primary verb;","translit":"zéō","lemma":"ζέω","kjv_def":"be fervent","pron":"dzeh'-o","pos":"Verb","thayer":"<ol><li>to boil with heat, be hot<ol type='a'><li>used of water</li><li>metaphorically<ol><li>used of boiling anger, love, zeal, for what is good or bad etc.</li><li>fervent in spirit, said of zeal for what is good</li></ol></li></ol></li></ol>","xlit":"zéō"},"G446":{"derivation":"from G473 (ἀντί) and a superlative of G5228 (ὑπέρ);","strongs_def":" instead of the highest officer, i.e. (specially) a Roman proconsul","kjv_def":"deputy","lemma":"ἀνθύπατος","translit":"anthýpatos","pron":"anth-oo'-pat-os","pos":"Noun Masculine","thayer":"<ol><li>a proconsul<ol type='a'><li>the emperor Augustus divided the Roman provinces into senatorial and imperial. The former were governed by proconsuls; the later by legates of the emperor, sometimes called propraetors</li></ol></li></ol>","xlit":"anthýpatos"},"G2870":{"lemma":"κοπετός","translit":"kopetós","kjv_def":"lamentation","strongs_def":" mourning (properly, by beating the breast)","derivation":"from G2875 (κόπτω);","pron":"kop-et-os'","pos":"Noun Masculine","thayer":"<ol><li>lamentation with beating of the breast as a sign of grief</li></ol>","xlit":"kopetós"},"G4178":{"kjv_def":"oft(-en, -entimes, -times)","lemma":"πολλάκις","translit":"pollákis","derivation":"multiplicative adverb from G4183 (πολύς);","strongs_def":" many times, i.e. frequently","pron":"pol-lak'-is","pos":"Adverb","thayer":"<ol><li>often, frequently</li></ol>","xlit":"pollákis"},"G374":{"strongs_def":" to incite","derivation":"from G303 (ἀνά) and G3982 (πείθω);","lemma":"ἀναπείθω","translit":"anapeíthō","kjv_def":"persuade","pron":"an-ap-i'-tho","pos":"Verb","thayer":"<ol><li>to stir up by persuasion, to solicit, incite</li></ol>","xlit":"anapeíthō"},"G4697":{"translit":"splanchnízomai","lemma":"σπλαγχνίζομαι","kjv_def":"have (be moved with) compassion","strongs_def":" to have the bowels yearn, i.e. (figuratively) feel sympathy, to pity","derivation":"middle voice from G4698 (σπλάγχνον);","pron":"splangkh-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to be moved as to one's bowels, hence to be moved with compassion, have compassion (for the bowels were thought to be the seat of love and pity)</li></ol>","xlit":"splanchnízomai"},"G509":{"lemma":"ἄνωθεν","translit":"ánōthen","kjv_def":"from above, again, from the beginning (very first), the top","strongs_def":" from above; by analogy, from the first; by implication, anew","derivation":"from G507 (ἄνω);","pron":"an'-o-then","pos":"Adverb","thayer":"<ol><li>from above, from a higher place<ol type='a'><li>of things which come from heaven or God</li></ol><li>from the first, from the beginning, from the very first</li><li>anew, over again</li></ol>","xlit":"ánōthen"},"G4882":{"derivation":"from G4862 (σύν) and G649 (ἀποστέλλω);","strongs_def":" to despatch (on an errand) in company with","kjv_def":"send with","lemma":"συναποστέλλω","translit":"synapostéllō","pron":"soon-ap-os-tel'-lo","pos":"Verb","thayer":"<ol><li>to send with</li></ol>","xlit":"synapostéllō"},"G587":{"derivation":"from G588 (ἀποδέχομαι);","strongs_def":" accepted, i.e. agreeable","kjv_def":"acceptable","translit":"apódektos","lemma":"ἀπόδεκτος","pron":"ap-od'-ek-tos","pos":"Adjective","thayer":"<ol><li>accepted, acceptable, agreeable</li></ol>","xlit":"apódektos"},"G4802":{"derivation":"from G4862 (σύν) and G2212 (ζητέω);","strongs_def":" to investigate jointly, i.e. discuss, controvert, cavil","kjv_def":"dispute (with), enquire, question (with), reason (together)","lemma":"συζητέω","translit":"syzētéō","pron":"sood-zay-teh'-o","pos":"Verb","thayer":"<ol><li>to seek or examine together</li><li>in the NT to discuss, dispute, question</li></ol>","xlit":"syzētéō"},"G977":{"lemma":"βιβρώσκω","translit":"bibrṓskō","kjv_def":"eat","strongs_def":" to eat","derivation":"a reduplicated and prolonged form of an obsolete primary verb (perhaps causative of G1006 (βόσκω));","pron":"bib-ro'-sko","pos":"Verb","thayer":"<ol><li>to eat</li></ol>","xlit":"bibrṓskō"},"G4759":{"derivation":"from G4760 (στρατόπεδον) and G757 (ἄρχω);","strongs_def":" a ruler of an army, i.e. (specially), a Prætorian præfect","kjv_def":"captain of the guard","lemma":"στρατοπεδάρχης","translit":"stratopedárchēs","pron":"strat-op-ed-ar'-khace","pos":"Noun Masculine","thayer":"<ol><li>the commander of a camp and army, a military tribune</li><li>Praetorian prefect, commander of the praetorian cohorts, captain of the Roman emperor's body guard</li></ol>","xlit":"stratopedárchēs"},"G5489":{"derivation":"from the same as G5482 (χάραξ);","strongs_def":" a sheet (\"chart\") of writing-material (as to be scribbled over)","kjv_def":"paper","lemma":"χάρτης","translit":"chártēs","pron":"khar'-tace","pos":"Noun Masculine","thayer":"<ol><li>paper</li></ol>","xlit":"chártēs"},"G4924":{"derivation":"from G4862 (σύν) and G3611 (οἰκέω);","strongs_def":" to reside together (as a family)","kjv_def":"dwell together","lemma":"συνοικέω","translit":"synoikéō","pron":"soon-oy-keh'-o","pos":"Verb","thayer":"<ol><li>to dwell together<ol type='a'><li>of the domestic association</li><li>of intercourse of a husband and wife</li></ol></li></ol>","xlit":"synoikéō"},"G4482":{"strongs_def":" for some tenses of which a prolonged form is used to flow (\"run\"; as water)","derivation":"a primary verb;","lemma":"ῥέω","translit":"rhéō","kjv_def":"flow","pron":"hreh'-o","pos":"Verb","thayer":"<ol><li>to flow</li></ol>","xlit":"rhéō"},"G3354":{"lemma":"μετρέω","translit":"metréō","kjv_def":"figuratively, to estimate:--measure, mete","strongs_def":" to measure (i.e. ascertain in size by a fixed standard); by implication, to admeasure (i.e. allot by rule)","derivation":"from G3358 (μέτρον);","pron":"met-reh'-o","pos":"Verb","thayer":"<ol><li>to measure, to measure out or off<ol type='a'><li>any space or distance with a measurer's reed or rule</li><li>metaphorically to judge according to any rule or standard, to estimate</li></ol><li>to measure out, mete out to, i.e. to give by measure</li></ol>","xlit":"metréō"},"G2559":{"derivation":"from G2556 (κακός);","strongs_def":" to injure; figuratively, to exasperate","kjv_def":"make evil affected, entreat evil, harm, hurt, vex","lemma":"κακόω","translit":"kakóō","pron":"kak-o'-o","pos":"Verb","thayer":"<ol><li>to oppress, afflict, harm, maltreat</li><li>to embitter, render evil affected</li></ol>","xlit":"kakóō"},"G3309":{"translit":"merimnáō","lemma":"μεριμνάω","kjv_def":"(be, have) care(-ful), take thought","strongs_def":" to be anxious about","derivation":"from G3308 (μέριμνα);","pron":"mer-im-nah'-o","pos":"Verb","thayer":"<ol><li>to be anxious<ol type='a'><li>to be troubled with cares</li></ol><li>to care for, look out for (a thing)<ol type='a'><li>to seek to promote one's interests</li><li>caring or providing for</li></ol></li></ol>","xlit":"merimnáō"},"G3184":{"derivation":"from another form of G3178 (μέθη);","strongs_def":" to drink to intoxication, i.e. get drunk","kjv_def":"drink well, make (be) drunk(-en)","lemma":"μεθύω","translit":"methýō","pron":"meth-oo'-o","pos":"Verb","thayer":"<ol><li>to be drunken</li><li>metaphorically of one who has shed blood or murdered profusely</li></ol>","xlit":"methýō"},"G5260":{"kjv_def":"suborn","translit":"hypobállō","lemma":"ὑποβάλλω","derivation":"from G5259 (ὑπό) and G906 (βάλλω);","strongs_def":" to throw in stealthily, i.e. introduce by collusion","pron":"hoop-ob-al'-lo","pos":"Verb","thayer":"<ol><li>to throw or put under</li><li>to suggest to the mind</li><li>to instruct privately, instigate, to bribe or induce (someone) unlawfully or secretly to perform some misdeed or commit a crime</li><li>to induce (a person especially a witness) to give false testimony</li></ol>","xlit":"hypobállō"},"G2920":{"strongs_def":"decision (subjectively or objectively, for or against); by extension, a tribunal; by implication, justice (especially, divine law)","translit":"krísis","lemma":"κρίσις","kjv_def":"accusation, condemnation, damnation, judgment","pron":"kree'-sis","pos":"Noun Feminine","thayer":"<ol><li>a separating, sundering, separation<ol type='a'><li>a trial, contest</li></ol><li>selection</li><li>judgment<ol type='a'><li>opinion or decision given concerning anything<ol><li>especially concerning justice and injustice, right or wrong</li></ol><li>sentence of condemnation, damnatory judgment, condemnation and punishment</li></ol><li>the college of judges (a tribunal of seven men in the several cities of Palestine; as distinguished from the Sanhedrin, which had its seat at Jerusalem)</li><li>right, justice</li></ol>","xlit":"krísis"},"G2479":{"strongs_def":" compare , a form of G2192 (ἔχω)); forcefulness (literally or figuratively)","derivation":"from a derivative of (force;","lemma":"ἰσχύς","translit":"ischýs","kjv_def":"ability, might(-ily), power, strength","pron":"is-khoos'","pos":"Noun Feminine","thayer":"<ol><li>ability, force, strength, might</li></ol>","xlit":"ischýs"},"G301":{"lemma":"Ἀμώς","translit":"Amṓs","kjv_def":"Amos","strongs_def":" Amos, an Israelite","derivation":"of Hebrew origin (H0531);","pron":"am-oce'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Amos = \"burden\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Amṓs"},"G2847":{"derivation":"from G2848 (κόκκος) (from the kernel-shape of the insect);","strongs_def":" crimson-colored","kjv_def":"scarlet (colour, coloured)","lemma":"κόκκινος","translit":"kókkinos","pron":"kok'-kee-nos","pos":"Adjective","thayer":"<ol><li>crimson, scarlet coloured. A kernel, the grain or berry of the \"ilex coccifera\" ; these berries are the clusters of the eggs of a female insect, the \"kermes\" (resembling the cochineal), and when collected and pulverised produces a red which was used in dyeing</li><li>scarlet cloth or clothing</li></ol>","xlit":"kókkinos"},"G1395":{"kjv_def":"giver","lemma":"δότης","translit":"dótēs","derivation":"from the base of G1325 (δίδωμι);","strongs_def":" a giver","pron":"dot'-ace","pos":"Noun Masculine","thayer":"<ol><li>a giver, bestower</li></ol>","xlit":"dótēs"},"G1633":{"kjv_def":"depart out","translit":"ekchōréō","lemma":"ἐκχωρέω","derivation":"from G1537 (ἐκ) and G5562 (χωρέω);","strongs_def":" to depart","pron":"ek-kho-reh'-o","pos":"Verb","thayer":"<ol><li>to depart from</li><li>to remove from in the sense of fleeing from</li></ol>","xlit":"ekchōréō"},"G2674":{"derivation":"from G2596 (κατά) and G705 (ἀριθμέω);","strongs_def":" to reckon among","kjv_def":"number with","lemma":"καταριθμέω","translit":"katarithméō","pron":"kat-ar-ith-meh'-o","pos":"Verb","thayer":"<ol><li>to number with</li></ol>","xlit":"katarithméō"},"G4002":{"lemma":"πέντε","translit":"pénte","kjv_def":"five","strongs_def":" \"five\"","derivation":"a primary number;","pron":"pen'-teh","pos":"Noun","thayer":"<ol><li>five</li></ol>","xlit":"pénte"},"G1418":{"kjv_def":"+ hard, + grievous, etc","translit":"dys-","lemma":"δυσ-","derivation":"a primary inseparable particle of uncertain derivation;","strongs_def":" used only in composition as a prefix; hard, i.e. with difficulty","pron":"doos","thayer":"<ol><li>prefix conveying the idea of difficulty, opposition, injuriousness, similar to our \"mis-\" or \"un-\" prefixes</li></ol>","xlit":"dys-"},"G1110":{"derivation":"from G1097 (γινώσκω);","strongs_def":" well-known","kjv_def":"acquaintance, (which may be) known, notable","lemma":"γνωστός","translit":"gnōstós","pron":"gnoce-tos'","pos":"Adjective","thayer":"<ol><li>known, notable</li></ol>","xlit":"gnōstós"},"G1098":{"translit":"gleûkos","lemma":"γλεῦκος","kjv_def":"new wine","strongs_def":" sweet wine, i.e. (properly) must (fresh juice), but used of the more saccharine (and therefore highly inebriating) fermented wine","derivation":"akin to G1099 (γλυκύς);","pron":"glyoo'-kos","pos":"Noun Neuter","thayer":"<ol><li>the sweet juice pressed the grape, sweet wine</li></ol>","xlit":"gleûkos"},"G1266":{"lemma":"διαμερίζω","translit":"diamerízō","kjv_def":"cloven, divide, part","strongs_def":" to partition thoroughly (literally in distribution, figuratively in dissension)","derivation":"from G1223 (διά) and G3307 (μερίζω);","pron":"dee-am-er-id'-zo","pos":"Verb","thayer":"<ol><li>to cleave asunder, cut in pieces</li><li>to be divided into opposing parts, to be at variance, in dissension</li><li>to distribute</li></ol>","xlit":"diamerízō"},"G4254":{"derivation":"from G4253 (πρό) and G71 (ἄγω);","strongs_def":" to lead forward (magisterially); intransitively, to precede (in place or time (participle, previous))","kjv_def":"bring (forth, out), go before","translit":"proágō","lemma":"προάγω","pron":"pro-ag'-o","pos":"Verb","thayer":"<ol><li>to lead forward, lead forth<ol type='a'><li>one from a place in which he has lain hidden from view, as from a prison</li><li>in a forensic sense, to bring one forth to trial</li></ol><li>to go before<ol type='a'><li>preceding, prior in time, previous</li><li>to proceed, go forward<ol><li>in a bad sense, to go further than is right. or proper</li></ol></li></ol></li></ol>","xlit":"proágō"},"G4767":{"kjv_def":"hateful","translit":"stygnētós","lemma":"στυγνητός","derivation":"from a derivative of an obsolete apparently primary (to hate);","strongs_def":" hated, i.e. odious","pron":"stoog-nay-tos'","pos":"Adjective","thayer":"<ol><li>hated, detestable</li></ol>","xlit":"stygnētós"},"G850":{"kjv_def":"dark","lemma":"αὐχμηρός","translit":"auchmērós","derivation":"from (probably from a base akin to that of G109 (ἀήρ)) (dust, as dried by wind);","strongs_def":" properly, dirty, i.e. (by implication) obscure","pron":"owkh-may-ros'","pos":"Adjective","thayer":"<ol><li>squalid, dirty<ol type='a'><li>since dirty things are destitute of brightness: dark</li></ol></li></ol>","xlit":"auchmērós"},"G4742":{"kjv_def":"mark","translit":"stígma","lemma":"στίγμα","derivation":"from a primary (to \"stick\", i.e. prick);","strongs_def":" a mark incised or punched (for recognition of ownership), i.e. (figuratively) scar of service","pron":"stig'-mah","pos":"Noun Neuter","thayer":"<ol><li>a mark pricked in or branded upon the body. To ancient oriental usage, slaves and soldiers bore the name or the stamp of their master or commander branded or pricked (cut) into their bodies to indicate what master or general they belonged to, and there were even some devotee's who stamped themselves in this way with the token of their gods</li></ol>","xlit":"stígma"},"G4669":{"kjv_def":"mingle with myrrh","translit":"smyrnízō","lemma":"σμυρνίζω","derivation":"from G4667 (Σμύρνα);","strongs_def":" to tincture with myrrh, i.e. embitter (as a narcotic)","pron":"smoor-nid'-zo","pos":"Verb","thayer":"<ol><li>to be like myrrh</li><li>to mix and so flavour with myrrh<ol type='a'><li>wine with myrrh: i.e. wine flavoured with myrrh. The ancients used to infuse myrrh into wine to give it a more agreeable fragrance and flavour</li></ol></li></ol>","xlit":"smyrnízō"},"G4298":{"kjv_def":"increase, proceed, profit, be far spent, wax","lemma":"προκόπτω","translit":"prokóptō","derivation":"from G4253 (πρό) and G2875 (κόπτω);","strongs_def":" to drive forward (as if by beating), i.e. (figuratively and intransitively) to advance (in amount, to grow; in time, to be well along)","pron":"prok-op'-to","pos":"Verb","thayer":"<ol><li>to beat forward<ol type='a'><li>to lengthen out by hammering (as a smith forges metals)</li><li>metaphorically to promote, forward, further</li></ol><li>to go forward, advance, proceed<ol type='a'><li>of time: the night is far spent</li><li>metaphorically to increase, make progress</li></ol></li></ol>","xlit":"prokóptō"},"G5210":{"lemma":"ὑμεῖς","translit":"hymeîs","kjv_def":"ye (yourselves), you","strongs_def":" you (as subjective of verb)","derivation":"irregular plural of G4771 (σύ);","pron":"hoo-mice'","thayer":"<ol><li>you</li></ol>","xlit":"hymeîs"},"G4464":{"derivation":"from the base of G4474 (ῥαπίζω);","strongs_def":" a stick or wand (as a cudgel, a cane or a baton of royalty)","kjv_def":"rod, sceptre, staff","translit":"rhábdos","lemma":"ῥάβδος","pron":"hrab'-dos","pos":"Noun Feminine","thayer":"<ol><li>a staff, a walking stick, a twig, rod, branch</li><li>a rod with which one is beaten</li><li>a staff<ol type='a'><li>as used on a journey, or to lean upon, or by shepherds</li><li>when applied to kings<ol><li>with a rod of iron, indicates the severest, most rigorous rule</li><li>a royal sceptre</li></ol></li></ol></li></ol>","xlit":"rhábdos"},"G1849":{"translit":"exousía","lemma":"ἐξουσία","kjv_def":"authority, jurisdiction, liberty, power, right, strength","strongs_def":" privilege, i.e. (subjectively) force, capacity, competency, freedom, or (objectively) mastery (concretely, magistrate, superhuman, potentate, token of control), delegated influence","derivation":"from G1832 (ἔξεστι) (in the sense of ability);","pron":"ex-oo-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>power of choice, liberty of doing as one pleases<ol type='a'><li>leave or permission</li></ol><li>physical and mental power<ol type='a'><li>the ability or strength with which one is endued, which he either possesses or exercises</li></ol><li>the power of authority (influence) and of right (privilege)</li><li>the power of rule or government (the power of him whose will and commands must be submitted to by others and obeyed)<ol type='a'><li>universally<ol><li>authority over mankind</li></ol><li>specifically<ol><li>the power of judicial decisions</li><li>of authority to manage domestic affairs</li></ol><li>metonymically<ol><li>a thing subject to authority or rule<ol type='a'><li>jurisdiction</li></ol><li>one who possesses authority<ol type='a'><li>a ruler, a human magistrate</li><li>the leading and more powerful among created beings superior to man, spiritual potentates</li></ol></li></ol><li>a sign of the husband's authority over his wife<ol><li>the veil with which propriety required a women to cover herself</li></ol><li>the sign of regal authority, a crown</li></ol></li></ol>","xlit":"exousía"},"G1574":{"kjv_def":"pierce","translit":"ekkentéō","lemma":"ἐκκεντέω","derivation":"from G1537 (ἐκ) and the base of G2759 (κέντρον);","strongs_def":" to transfix","pron":"ek-ken-teh'-o","pos":"Verb","thayer":"<ol><li>to put out, dig out</li><li>to dig through, transfix, pierce</li></ol>","xlit":"ekkentéō"},"G1754":{"strongs_def":" to be active, efficient","derivation":"from G1756 (ἐνεργής);","translit":"energéō","lemma":"ἐνεργέω","kjv_def":"do, (be) effectual (fervent), be mighty in, shew forth self, work (effectually in)","pron":"en-erg-eh'-o","pos":"Verb","thayer":"<ol><li>to be operative, be at work, put forth power<ol type='a'><li>to work for one, aid one</li></ol><li>to effect</li><li>to display one's activity, show one's self operative</li></ol>","xlit":"energéō"},"G894":{"derivation":"of uncertain derivation;","strongs_def":" wormwood (as a type of bitterness, i.e. (figuratively) calamity)","kjv_def":"wormwood","lemma":"ἄψινθος","translit":"ápsinthos","pron":"ap'-sin-thos","pos":"Noun Feminine","thayer":"<ol><li>wormwood</li><li>the name of a star which fell into the waters and made them bitter</li></ol>","xlit":"ápsinthos"},"G4431":{"lemma":"πτῶσις","translit":"ptōsis","kjv_def":"fall","strongs_def":" a crash, i.e. downfall (literally or figuratively)","derivation":"from the alternate of G4098 (πίπτω);","pron":"pto'-sis","pos":"Noun Feminine","thayer":"<ol><li>a falling, downfall</li></ol>","xlit":"ptōsis"},"G2032":{"strongs_def":" above the sky","derivation":"from G1909 (ἐπί) and G3772 (οὐρανός);","lemma":"ἐπουράνιος","translit":"epouránios","kjv_def":"celestial, (in) heaven(-ly), high","pron":"ep-oo-ran'-ee-os","pos":"Adjective","thayer":"<ol><li>existing in heaven<ol type='a'><li>things that take place in heaven</li><li>the heavenly regions<ol><li>heaven itself, the abode of God and angels</li><li>the lower heavens, of the stars</li><li>the heavens, of the clouds</li></ol><li>the heavenly temple or sanctuary</li></ol><li>of heavenly origin or nature</li></ol>","xlit":"epouránios"},"G227":{"derivation":"from G1 (Α) (as a negative particle) and G2990 (λανθάνω);","strongs_def":" true (as not concealing)","kjv_def":"true, truly, truth","lemma":"ἀληθής","translit":"alēthḗs","pron":"al-ay-thace'","pos":"Adjective","thayer":"<ol><li>true</li><li>loving the truth, speaking the truth, truthful</li></ol>","xlit":"alēthḗs"},"G3835":{"strongs_def":" all-working, i.e. adroit (shrewd)","derivation":"from G3956 (πᾶς) and G2041 (ἔργον);","lemma":"πανοῦργος","translit":"panoûrgos","kjv_def":"crafty","pron":"pan-oor'-gos","pos":"Adjective","thayer":"<ol><li>skilful, clever<ol type='a'><li>in a good sense, fit to undertake and accomplish anything, dexterous, wise, sagacious, skilful</li><li>in a bad sense, crafty, cunning, knavish, treacherous, deceitful</li></ol></li></ol>","xlit":"panoûrgos"},"G475":{"strongs_def":" to set oneself opposite, i.e. be disputatious","derivation":"from G473 (ἀντί) and G1303 (διατίθεμαι);","translit":"antidiatíthemai","lemma":"ἀντιδιατίθεμαι","kjv_def":"that oppose themselves","pron":"an-tee-dee-at-eeth'-em-ahee","pos":"Verb","thayer":"<ol><li>to place one's self in opposition, to oppose, to dispose in turn, to take in hand in turn, to retaliate</li></ol>","xlit":"antidiatíthemai"},"G4509":{"translit":"rhýpos","lemma":"ῥύπος","kjv_def":"filth","strongs_def":" dirt, i.e. (morally) depravity","derivation":"of uncertain affinity;","pron":"hroo'-pos","pos":"Noun Masculine","thayer":"<ol><li>filthy, dirty</li></ol>","xlit":"rhýpos"},"G252":{"kjv_def":"salt","translit":"halykós","lemma":"ἁλυκός","derivation":"from G251 (ἅλς);","strongs_def":" briny","pron":"hal-oo-kos'","pos":"Adjective","thayer":"<ol><li>salt</li></ol>","xlit":"halykós"},"G1606":{"translit":"ekpnéō","lemma":"ἐκπνέω","kjv_def":"give up the ghost","strongs_def":" to expire","derivation":"from G1537 (ἐκ) and G4154 (πνέω);","pron":"ek-pneh'-o","pos":"Verb","thayer":"<ol><li>to breathe out, breathe out one's life, breathe one's last, expire</li></ol>","xlit":"ekpnéō"},"G4999":{"kjv_def":"taverns","translit":"Tabérnai","lemma":"Ταβέρναι","derivation":"plural of Latin origin;","strongs_def":" huts or wooden-walled buildings; Tabernæ","pron":"tab-er'-nahee","pos":"Noun Feminine","thayer":"<ol><li>taverns</li><li>Three Taverns, the name of a halting place on the Appian way between Rome and the Market of Appius; it was 10 miles (16 km) from the latter place and 33 miles (50 km) ) from Rome</li></ol>","xlit":"Tabérnai"},"G2128":{"strongs_def":" adorable","derivation":"from G2127 (εὐλογέω);","translit":"eulogētós","lemma":"εὐλογητός","kjv_def":"blessed","pron":"yoo-log-ay-tos'","pos":"Adjective","thayer":"<ol><li>blessed, praised</li></ol>","xlit":"eulogētós"},"G764":{"derivation":"from G765 (ἀσεβής);","strongs_def":" to be (by implied act) impious or wicked","kjv_def":"commit (live, that after should live) ungodly","translit":"asebéō","lemma":"ἀσεβέω","pron":"as-eb-eh'-o","pos":"Verb","thayer":"<ol><li>to be ungodly, act impiously</li></ol>","xlit":"asebéō"},"G4677":{"derivation":"of Hebrew origin (H07799 feminine);","strongs_def":" lily; Susannah (i.e. Shoshannah), an Israelitess","kjv_def":"Susanna","translit":"Sousánna","lemma":"Σουσάννα","pron":"soo-san'-nah","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Susanna = \"a lily\"</p><ol><li>one of the women who ministered to Christ</li></ol>","xlit":"Sousánna"},"G3399":{"strongs_def":" Miletus, a city of Asia Minor","derivation":"of uncertain origin;","translit":"Mílētos","lemma":"Μίλητος","kjv_def":"Miletus","pron":"mil'-ay-tos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Miletus = \"pure white fine wool\"</p><ol><li>a maritime city, now nearly 10 miles (16 km), from the coast of Caria or Ionia, near the mouth of the Maeander and 35 miles (55 km) from Ephesus. It was the mother of about eighty colonies, the the birth place of Thales, Anaximander, and other famous men.</li></ol>","xlit":"Mílētos"},"G3135":{"derivation":"from (a pearl-oyster);","strongs_def":" a pearl","kjv_def":"pearl","lemma":"μαργαρίτης","translit":"margarítēs","pron":"mar-gar-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>a pearl</li><li>a proverb, i.e. a word of great value</li></ol>","xlit":"margarítēs"},"G2589":{"derivation":"from G2588 (καρδία) and G1097 (γινώσκω);","strongs_def":" a heart-knower","kjv_def":"which knowest the hearts","lemma":"καρδιογνώστης","translit":"kardiognṓstēs","pron":"kar-dee-og-noce'-tace","pos":"Noun Masculine","thayer":"<ol><li>knower of the hearts</li></ol>","xlit":"kardiognṓstēs"},"G2964":{"kjv_def":"confirm","lemma":"κυρόω","translit":"kyróō","derivation":"from the same as G2962 (κύριος);","strongs_def":" to make authoritative, i.e. ratify","pron":"koo-ro'-o","pos":"Verb","thayer":"<ol><li>to make valid</li><li>to confirm publicly or solemnly, to ratify</li></ol>","xlit":"kyróō"},"G5549":{"translit":"chronízō","lemma":"χρονίζω","kjv_def":"delay, tarry","strongs_def":" to take time, i.e. linger","derivation":"from G5550 (χρόνος);","pron":"khron-id'-zo","pos":"Verb","thayer":"<ol><li>to linger, delay, tarry</li></ol>","xlit":"chronízō"},"G3934":{"kjv_def":"Parthian","translit":"Párthos","lemma":"Πάρθος","derivation":"probably of foreign origin;","strongs_def":" a Parthian, i.e. inhabitant of Parthia","pron":"par'-thos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Parthia = \"a pledge\"</p><ol><li>an inhabitant of Parthia, a district of Asia, bounded on the north by Hyrcania, on the east by Ariana, on the south by Carmania Deserta, on the west by Media</li></ol>","xlit":"Párthos"},"G344":{"derivation":"from G303 (ἀνά) and G2578 (κάμπτω);","strongs_def":" to turn back","kjv_def":"(re-)turn","translit":"anakámptō","lemma":"ἀνακάμπτω","pron":"an-ak-amp'-to","pos":"Verb","thayer":"<ol><li>to bend back, to turn back</li><li>to return</li></ol>","xlit":"anakámptō"},"G1079":{"translit":"genetḗ","lemma":"γενετή","kjv_def":"birth","strongs_def":" birth","derivation":"feminine of a presumed derivative of the base of G1074 (γενεά);","pron":"ghen-et-ay","pos":"Noun Feminine","thayer":"<ol><li>birth, from birth</li></ol>","xlit":"genetḗ"},"G1694":{"lemma":"Ἐμμανουήλ","translit":"Emmanouḗl","kjv_def":"Emmanuel","strongs_def":" God with us; Emmanuel, a name of Christ","derivation":"of Hebrew origin (H06005);","pron":"em-man-oo-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Emmanuel = \"God with us\"</p><ol><li>the title applied to the Messiah, born of the virgin, <a class='bible' href='#b40.1.23'>Mat 1:23</a>, <a class='bible' href='#b23.7.14'>Isa 7:14</a>, because Jesus was God united with man, and showed that God was dwelling with man</li></ol>","xlit":"Emmanouḗl"},"G5200":{"strongs_def":" wet (as if with rain), i.e. (by implication) sappy (fresh)","derivation":"from the base of G5205 (ὑετός);","translit":"hygrós","lemma":"ὑγρός","kjv_def":"green","pron":"hoo-gros'","pos":"Adjective","thayer":"<ol><li>damp, moist, wet</li><li>full of sap, green</li></ol>","xlit":"hygrós"},"G3483":{"lemma":"ναί","translit":"naí","kjv_def":"even so, surely, truth, verily, yea, yes","strongs_def":" yes","derivation":"a primary particle of strong affirmation;","pron":"nahee","thayer":"<ol><li>yea, verily, truly, assuredly, even so</li></ol>","xlit":"naí"},"G4443":{"lemma":"πυρά","translit":"pyrá","kjv_def":"fire","strongs_def":" a fire (concretely)","derivation":"from G4442 (πῦρ);","pron":"poo-rah'","pos":"Noun Feminine","thayer":"<ol><li>a fire, a pile of burning fuel</li></ol>","xlit":"pyrá"},"G1080":{"kjv_def":"bear, beget, be born, bring forth, conceive, be delivered of, gender, make, spring","translit":"gennáō","lemma":"γεννάω","derivation":"from a variation of G1085 (γένος);","strongs_def":" to procreate (properly, of the father, but by extension of the mother); figuratively, to regenerate","pron":"ghen-nah'-o","pos":"Verb","thayer":"<ol><li>of men who fathered children<ol type='a'><li>to be born</li><li>to be begotten<ol><li>of women giving birth to children</li></ol></li></ol><li>metaphorically<ol type='a'><li>to engender, cause to arise, excite</li><li>in a Jewish sense, of one who brings others over to his way of life, to convert someone</li><li>of God making Christ his son</li><li>of God making men his sons through faith in Christ's work</li></ol></li></ol>","xlit":"gennáō"},"G1464":{"translit":"enkopḗ","lemma":"ἐγκοπή","kjv_def":"X hinder","strongs_def":" a hindrance","derivation":"from G1465 (ἐγκόπτω);","pron":"eng-kop-ay'","pos":"Noun Feminine","thayer":"<ol><li>a cutting (made in a road to impede an enemy in pursuit)</li><li>a hindrance</li></ol>","xlit":"enkopḗ"},"G5021":{"derivation":"a prolonged form of a primary verb (which latter appears only in certain tenses);","strongs_def":" to arrange in an orderly manner, i.e. assign or dispose (to a certain position or lot)","kjv_def":"addict, appoint, determine, ordain, set","translit":"tássō","lemma":"τάσσω","pron":"tas'-so","pos":"Verb","thayer":"<ol><li>to put in order, to station<ol type='a'><li>to place in a certain order, to arrange, to assign a place, to appoint<ol><li>to assign (appoint) a thing to one</li></ol><li>to appoint, ordain, order<ol><li>to appoint on one's own responsibility or authority</li><li>to appoint mutually, i.e. agree upon</li></ol></li></ol></li></ol>","xlit":"tássō"},"G3721":{"lemma":"ὄρθριος","translit":"órthrios","kjv_def":"early","strongs_def":" in the dawn, i.e. up at day-break","derivation":"from G3722 (ὄρθρος);","pron":"or'-three-os","pos":"Adjective","thayer":"<ol><li>early</li><li>rising at the first dawn or very early in the morning</li></ol>","xlit":"órthrios"},"G152":{"translit":"aischýnē","lemma":"αἰσχύνη","kjv_def":"dishonesty, shame","strongs_def":" shame or disgrace (abstractly or concretely)","derivation":"from G153 (αἰσχύνομαι);","pron":"ahee-skhoo'-nay","pos":"Noun Feminine","thayer":"<ol><li>the confusion of one who is ashamed of anything, sense of shame</li><li>ignominy, disgrace, dishonour</li><li>a thing to be ashamed of</li></ol>","xlit":"aischýnē"},"G5118":{"strongs_def":" apparently from G3588 (ὁ) and G3739 (ὅς)) and G3778 (οὗτος) (including its variations); so vast as this, i.e. such (in quantity, amount, number of space)","derivation":"from (so much;","lemma":"τοσοῦτος","translit":"tosoûtos","kjv_def":"as large, so great (long, many, much), these many","pron":"tos-oo'-tos","pos":"Adjective","thayer":"<ol><li>of quantity: so great, so many</li><li>of time: so long</li></ol>","xlit":"tosoûtos"},"G5391":{"strongs_def":" friendly of mind, i.e. kind","derivation":"from G5384 (φίλος) and G5424 (φρήν);","lemma":"φιλόφρων","translit":"philóphrōn","kjv_def":"courteous","pron":"fil-of'-rone","pos":"Adjective","thayer":"<ol><li>friendly, kind</li></ol>","xlit":"philóphrōn"},"G4342":{"derivation":"from G4314 (πρός) and G2594 (καρτερέω);","strongs_def":" to be earnest towards, i.e. (to a thing) to persevere, be constantly diligent, or (in a place) to attend assiduously all the exercises, or (to a person) to adhere closely to (as a servitor)","kjv_def":"attend (give self) continually (upon), continue (in, instant in, with), wait on (continually)","lemma":"προσκαρτερέω","translit":"proskarteréō","pron":"pros-kar-ter-eh'-o","pos":"Verb","thayer":"<ol><li>to adhere to one, be his adherent, to be devoted or constant to one</li><li>to be steadfastly attentive unto, to give unremitting care to a thing</li><li>to continue all the time in a place</li><li>to persevere and not to faint</li><li>to show one's self courageous for</li><li>to be in constant readiness for one, wait on constantly</li></ol>","xlit":"proskarteréō"},"G4093":{"strongs_def":" a tablet (for writing on)","derivation":"diminutive of G4094 (πίναξ);","translit":"pinakídion","lemma":"πινακίδιον","kjv_def":"writing table","pron":"pin-ak-id'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a small tablet</li><li>a writing tablet</li></ol>","xlit":"pinakídion"},"G271":{"translit":"améthystos","lemma":"ἀμέθυστος","kjv_def":"amethyst","strongs_def":" the \"amethyst\" (supposed to prevent intoxication)","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3184 (μεθύω);","pron":"am-eth'-oos-tos","pos":"Noun Feminine","thayer":"<ol><li>amethyst, a precious stone of a violet and purple colour</li></ol>","xlit":"améthystos"},"G786":{"kjv_def":"implacable, truce-breaker","lemma":"ἄσπονδος","translit":"áspondos","derivation":"from G1 (Α) (as a negative particle) and a derivative of G4689 (σπένδω);","strongs_def":" literally, without libation (which usually accompanied a treaty), i.e. (by implication) truceless","pron":"as'-pon-dos","pos":"Adjective","thayer":"<ol><li>without a treaty or covenant<ol type='a'><li>of things not mutually agreed upon e.g. abstinences from hostilities</li></ol><li>that cannot be persuaded to enter into a covenant, implacable</li></ol>","xlit":"áspondos"},"G4791":{"strongs_def":" a co-participant","derivation":"from G4862 (σύν) and G2844 (κοινωνός);","lemma":"συγκοινωνός","translit":"synkoinōnós","kjv_def":"companion, partake(-r, -r with)","pron":"soong-koy-no-nos'","pos":"Noun Masculine","thayer":"<ol><li>participant with others in anything, joint partner</li></ol>","xlit":"synkoinōnós"},"G4723":{"strongs_def":" \"sterile\"","derivation":"a contraction from G4731 (στερεός) (as stiff and unnatural);","lemma":"στείρος","translit":"steíros","kjv_def":"barren","pron":"sti'-ros","pos":"Adjective","thayer":"<ol><li>hard, stiff<ol type='a'><li>of men and animals</li></ol><li>barren<ol type='a'><li>of woman who does not conceive</li></ol></li></ol>","xlit":"steíros"},"G5230":{"derivation":"from G5228 (ὑπέρ) and the base of G188 (ἀκμήν);","strongs_def":" beyond the \"acme\", i.e. figuratively (of a daughter) past the bloom (prime) of youth","kjv_def":"+ pass the flower of (her) age","lemma":"ὑπέρακμος","translit":"hypérakmos","pron":"hoop-er'-ak-mos","pos":"Adjective","thayer":"<ol><li>beyond the bloom or prime of life</li><li>overripe, plump and ripe, (and so in a greater danger of defilement)<ol type='a'><li>of a virgin</li></ol></li></ol>","xlit":"hypérakmos"},"G1583":{"strongs_def":" to divulge","derivation":"from G1537 (ἐκ) and G2980 (λαλέω);","lemma":"ἐκλαλέω","translit":"eklaléō","kjv_def":"tell","pron":"ek-lal-eh'-o","pos":"Verb","thayer":"<ol><li>to speak out, divulge</li></ol>","xlit":"eklaléō"},"G4993":{"translit":"sōphronéō","lemma":"σωφρονέω","kjv_def":"be in right mind, be sober (minded), soberly","strongs_def":" to be of sound mind, i.e. sane, (figuratively) moderate","derivation":"from G4998 (σώφρων);","pron":"so-fron-eh'-o","pos":"Verb","thayer":"<ol><li>to be of sound mind<ol type='a'><li>to be in one's right mind</li><li>to exercise self control<ol><li>to put a moderate estimate upon one's self, think of one's self soberly</li><li>to curb one's passions</li></ol></li></ol></li></ol>","xlit":"sōphronéō"},"G4495":{"strongs_def":" to toss up","derivation":"from a derivative of G4496 (ῥίπτω);","lemma":"ῥιπτέω","translit":"rhiptéō","kjv_def":"cast off","pron":"hrip-teh'-o","pos":"Verb","thayer":"<ol><li>to cast, throw</li><li>throw down</li><li>to cast forward or before</li><li>to set down (with the suggestion of haste and want of care)</li><li>to throw to the ground, prostrate</li></ol>","xlit":"rhiptéō"},"G4771":{"lemma":"σύ","translit":"sý","kjv_def":" thou","strongs_def":" thou","derivation":"the personal pronoun of the second person singular;","pron":"soo","thayer":"<ol><li>you</li></ol>","xlit":"sý"},"G934":{"strongs_def":" kingly (in nature)","derivation":"from G935 (βασιλεύς);","translit":"basíleios","lemma":"βασίλειος","kjv_def":"royal","pron":"bas-il'-i-os","pos":"Adjective","thayer":"<ol><li>royal, kingly, regal</li></ol>","xlit":"basíleios"},"G3696":{"derivation":"probably from a primary (to be busy about);","strongs_def":" an implement or utensil or tool (literally or figuratively, especially, offensive for war)","kjv_def":"armour, instrument, weapon","translit":"hóplon","lemma":"ὅπλον","pron":"hop'-lon","pos":"Noun Neuter","thayer":"<ol><li>any tool or implement for preparing a thing<ol type='a'><li>arms used in warfare, weapons</li></ol><li>an instrument</li></ol>","xlit":"hóplon"},"G2929":{"derivation":"from G2930 (κρύσταλλος);","strongs_def":" to make (i.e. intransitively, resemble) ice (\"crystallize\")","kjv_def":"be clear as crystal","lemma":"κρυσταλλίζω","translit":"krystallízō","pron":"kroos-tal-lid'-zo","pos":"Verb","thayer":"<ol><li>to be of crystalline brightness and transparency</li><li>to shine like crystal</li></ol>","xlit":"krystallízō"},"G3667":{"translit":"homoíōma","lemma":"ὁμοίωμα","kjv_def":"made like to, likeness, shape, similitude","strongs_def":" a form; abstractly, resemblance","derivation":"from G3666 (ὁμοιόω);","pron":"hom-oy'-o-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been made after the likeness of something<ol type='a'><li>a figure, image, likeness, representation</li><li>likeness, i.e. resemblance, such as amounts almost to equality or identity</li></ol></li></ol>","xlit":"homoíōma"},"G630":{"kjv_def":"(let) depart, dismiss, divorce, forgive, let go, loose, put (send) away, release, set at liberty","lemma":"ἀπολύω","translit":"apolýō","derivation":"from G575 (ἀπό) and G3089 (λύω);","strongs_def":" to free fully, i.e. (literally) relieve, release, dismiss (reflexively, depart), or (figuratively) let die, pardon or (specially) divorce","pron":"ap-ol-oo'-o","pos":"Verb","thayer":"<ol><li>to set free</li><li>to let go, dismiss, (to detain no longer)<ol type='a'><li>a petitioner to whom liberty to depart is given by a decisive answer</li><li>to bid depart, send away</li></ol><li>to let go free, release<ol type='a'><li>a captive, i.e. to loose his bonds and bid him depart, to give him liberty to depart</li><li>to acquit one accused of a crime and set him at liberty</li><li>indulgently to grant a prisoner leave to depart</li><li>to release a debtor, i.e. not to press one's claim against him, to remit his debt</li></ol><li>used of divorce, to dismiss from the house, to repudiate. The wife of a Greek or Roman may divorce her husband.</li><li>to send one's self away, to depart</li></ol>","xlit":"apolýō"},"G2936":{"strongs_def":" to fabricate, i.e. found (form originally)","derivation":"probably akin to G2932 (κτάομαι) (through the idea of proprietorship of the manufacturer);","translit":"ktízō","lemma":"κτίζω","kjv_def":"create, Creator, make","pron":"ktid'-zo","pos":"Verb","thayer":"<ol><li>to make habitable, to people, a place, region, island<ol type='a'><li>to found a city, colony, state</li></ol><li>to create<ol type='a'><li>of God creating the worlds</li><li>to form, shape, i.e. to completely change or transform</li></ol></li></ol>","xlit":"ktízō"},"G5175":{"lemma":"Τρωγύλλιον","translit":"Trōgýllion","kjv_def":"Trogyllium","strongs_def":" Trogyllium, a place in Asia Minor","derivation":"of uncertain derivation;","pron":"tro-gool'-lee-on","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Trogyllium = \"a cache\"</p><ol><li>the name of a town and a promontory of Ionia, not far from the island of Samos, at the foot of Mt. Mycale between Ephesus and the mouth of the river Maeander</li></ol>","xlit":"Trōgýllion"},"G449":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G3538 (νίπτω);","strongs_def":" without ablution","kjv_def":"unwashen","translit":"ániptos","lemma":"ἄνιπτος","pron":"an'-ip-tos","pos":"Adjective","thayer":"<ol><li>unwashed</li></ol>","xlit":"ániptos"},"G2160":{"strongs_def":" witticism, i.e. (in a vulgar sense) ribaldry","derivation":"from a compound of G2095 (εὖ) and a derivative of the base of G5157 (τροπή) (meaning well-turned, i.e. ready at repartee, jocose);","lemma":"εὐτραπελία","translit":"eutrapelía","kjv_def":"jesting","pron":"yoo-trap-el-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>pleasantry, humour, facetiousness</li><li>in a bad sense<ol type='a'><li>scurrility, ribaldry, low jesting</li></ol></li></ol>","xlit":"eutrapelía"},"G216":{"kjv_def":"dumb","translit":"álalos","lemma":"ἄλαλος","derivation":"from G1 (Α) (as a negative particle) and G2980 (λαλέω);","strongs_def":" mute","pron":"al'-al-os","pos":"Adjective","thayer":"<ol><li>speechless, dumb, wanting the faculty of speech</li></ol>","xlit":"álalos"},"G523":{"translit":"apaitéō","lemma":"ἀπαιτέω","kjv_def":"ask again, require","strongs_def":" to demand back","derivation":"from G575 (ἀπό) and G154 (αἰτέω);","pron":"ap-ah'-ee-teh-o","xlit":"apaitéō"},"G4886":{"strongs_def":" a joint tie, i.e. ligament, (figuratively) uniting principle, control","derivation":"from G4862 (σύν) and G1199 (δεσμόν);","translit":"sýndesmos","lemma":"σύνδεσμος","kjv_def":"band, bond","pron":"soon'-des-mos","pos":"Noun Masculine","thayer":"<ol><li>that which binds together, a band, bond<ol type='a'><li>of ligaments by which the members of the human body are united together</li></ol><li>that which is bound together, a bundle</li></ol>","xlit":"sýndesmos"},"G173":{"lemma":"ἄκανθα","translit":"ákantha","kjv_def":"thorn","strongs_def":" a thorn","derivation":"probably from the same as G188 (ἀκμήν);","pron":"ak'-an-thah","pos":"Noun Feminine","thayer":"<ol><li>thorn, bramble</li><li>bush, brier, a thorny plant</li></ol>","xlit":"ákantha"},"G1898":{"lemma":"ἐπεισαγωγή","translit":"epeisagōgḗ","kjv_def":"bringing in","strongs_def":" a superintroduction","derivation":"from a compound of G1909 (ἐπί) and G1521 (εἰσάγω);","pron":"ep-ice-ag-o-gay'","pos":"Noun Feminine","thayer":"<ol><li>a bringing in besides or in addition to what is or has been brought in<ol type='a'><li>used of the introduction of a new wife in the place of one repudiated</li><li>to come in besides or to those who are already within<ol><li>to enter afterwards</li></ol><li>to come in upon, come upon by entering<ol><li>to enter against</li></ol></li></ol></li></ol>","xlit":"epeisagōgḗ"},"G3197":{"derivation":"of Hebrew origin (H04428 with pronominal suffix, my king);","strongs_def":" Melchi (i.e. Malki), the name of two Israelites","kjv_def":"Melchi","translit":"Melchí","lemma":"Μελχί","pron":"mel-khee'","pos":"Noun Masculine","thayer":"<ol><li>the son of Janna in the genealogy of Christ</li><li>Melchi was the son of Addi in the genealogy of Christ</li></ol>","xlit":"Melchí"},"G460":{"derivation":"adverb from G459 (ἄνομος);","strongs_def":" lawlessly, i.e. (specially) not amenable to (the Jewish) law","kjv_def":"without law","lemma":"ἀνόμως","translit":"anómōs","pron":"an-om'-oce","pos":"Adverb","thayer":"<ol><li>without the law, without the knowledge of the law</li><li>to sin in ignorance of the Mosaic law</li><li>live ignorant of law and discipline</li></ol>","xlit":"anómōs"},"G1551":{"translit":"ekdéchomai","lemma":"ἐκδέχομαι","kjv_def":"expect, look (tarry) for, wait (for)","strongs_def":" to accept from some source, i.e. (by implication) to await","derivation":"from G1537 (ἐκ) and G1209 (δέχομαι);","pron":"ek-dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive, accept</li><li>to look for, expect, wait for, await</li></ol>","xlit":"ekdéchomai"},"G1334":{"kjv_def":"declare, shew, tell","lemma":"διηγέομαι","translit":"diēgéomai","derivation":"from G1223 (διά) and G2233 (ἡγέομαι);","strongs_def":" to relate fully","pron":"dee-ayg-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to lead or carry a narration through to the end</li><li>set forth, recount, relate in full, describe</li></ol>","xlit":"diēgéomai"},"G4472":{"lemma":"ῥαντίζω","translit":"rhantízō","kjv_def":" sprinkle","strongs_def":" to render besprinkled, i.e. asperse (ceremonially or figuratively)","derivation":"from a derivative of (to sprinkle);","pron":"hran-tid'-zo","pos":"Verb","thayer":"<ol><li>to sprinkle</li><li>to cleanse by sprinkling, hence to purify, cleanse</li></ol>","xlit":"rhantízō"},"G4437":{"kjv_def":"often(-er)","lemma":"πυκνός","translit":"pyknós","derivation":"from the same as G4635 (σκηνοποιός);","strongs_def":" clasped (thick), i.e. (figuratively) frequent; neuter plural (as adverb) frequently","pron":"pook-nos'","pos":"Adjective","thayer":"<ol><li>thick, dense, compact<ol type='a'><li>in reference to time<ol><li>frequently, often, recurring</li></ol><li>vigorously, diligently</li><li>often, more frequently, the oftener</li></ol></li></ol>","xlit":"pyknós"},"G1466":{"translit":"enkráteia","lemma":"ἐγκράτεια","kjv_def":"temperance","strongs_def":" self-control (especially continence)","derivation":"from G1468 (ἐγκρατής);","pron":"eng-krat'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>self-control (the virtue of one who masters his desires and passions, especially his sensual appetites)</li></ol>","xlit":"enkráteia"},"G4666":{"translit":"smýrna","lemma":"σμύρνα","kjv_def":"myrrh","strongs_def":" myrrh","derivation":"apparently strengthened for G3464 (μύρον);","pron":"smoor'-nah","pos":"Noun Feminine","thayer":"<ol><li>myrrh, a bitter gum and costly perfume which exudes from a certain tree or shrub in Arabia and Ethiopia, or is obtained by incisions made in the bark: as an antiseptic it was used for embalming</li></ol>","xlit":"smýrna"},"G1239":{"strongs_def":" to give throughout a crowd, i.e. deal out; also to deliver over (as to a successor)","derivation":"from G1223 (διά) and G1325 (δίδωμι);","lemma":"διαδίδωμι","translit":"diadídōmi","kjv_def":"(make) distribute(-ion), divide, give","pron":"dee-ad-id'-o-mee","pos":"Verb","thayer":"<ol><li>to distribute, divide among several</li><li>to give over, deliver</li></ol>","xlit":"diadídōmi"},"G3336":{"lemma":"μετάλημψις","translit":"metálēmpsis","kjv_def":"taking","strongs_def":" participation","derivation":"from G3335 (μεταλαμβάνω);","pron":"met-al'-ape-sis","pos":"Noun Feminine","thayer":"<ol><li>a taking, participation</li></ol>","xlit":"metálēmpsis"},"G4196":{"strongs_def":" apparently \"popular\"; Poplius (i.e. Publius), a Roman","derivation":"of Latin origin;","lemma":"Πόπλιος","translit":"Póplios","kjv_def":"Publius","pron":"pop'-lee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Publius = \"popular\"</p><ol><li>the chief magistrate of the island of Melita</li></ol>","xlit":"Póplios"},"G4340":{"derivation":"from G4314 (πρός) and G2540 (καιρός);","strongs_def":" for the occasion only, i.e. temporary","kjv_def":"dur-(eth) for awhile, endure for a time, for a season, temporal","translit":"próskairos","lemma":"πρόσκαιρος","pron":"pros'-kahee-ros","pos":"Adjective","thayer":"<ol><li>for a season</li><li>enduring only for a while</li><li>temporary</li></ol>","xlit":"próskairos"},"G3066":{"kjv_def":"Lucius","translit":"Loúkios","lemma":"Λούκιος","derivation":"of Latin origin;","strongs_def":" illuminative; Lucius, a Christian","pron":"loo'-kee-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lucius = \"light: bright: white\"</p><ol><li>a man from Cyrene who was a prophet and a teacher of the church in Antioch (<a class='bible' href='#b44.13.1'>Act 13:1</a>), perhaps the same one as mentioned in <a class='bible' href='#b45.16.21'>Rom 16:21</a></li></ol>","xlit":"Loúkios"},"G2685":{"strongs_def":" a reconnoiterer","derivation":"from G2596 (κατά) (intensive) and G4649 (σκοπός) (in the sense of a watcher);","lemma":"κατάσκοπος","translit":"katáskopos","kjv_def":"spy","pron":"kat-as'-kop-os","pos":"Noun Masculine","thayer":"<ol><li>an inspector, a spy</li></ol>","xlit":"katáskopos"},"G4055":{"derivation":"comparative of G4053 (περισσός);","strongs_def":" more superabundant (in number, degree or character)","kjv_def":"more abundant, greater (much) more, overmuch","lemma":"περισσότερος","translit":"perissóteros","pron":"per-is-sot'-er-os","xlit":"perissóteros"},"G2512":{"kjv_def":"cleansing, + purge, purification(-fying)","translit":"katharismós","lemma":"καθαρισμός","derivation":"from G2511 (καθαρίζω);","strongs_def":" a washing off, i.e. (ceremonially) ablution, (morally) expiation","pron":"kath-ar-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a cleansing, purification, a ritual purgation or washing<ol type='a'><li>of the washing of the Jews before and after their meals</li><li>of levitical purification of women after childbirth</li><li>a cleansing from the guilt of sins wrought by the expiatory sacrifice of Christ</li></ol></li></ol>","xlit":"katharismós"},"G4144":{"translit":"plóos","lemma":"πλόος","kjv_def":"course, sailing, voyage","strongs_def":" a sail, i.e. navigation","derivation":"from G4126 (πλέω);","pron":"plo'-os","pos":"Noun Masculine","thayer":"<ol><li>a voyage</li></ol>","xlit":"plóos"},"G4381":{"translit":"prosōpolḗptēs","lemma":"προσωπολήπτης","kjv_def":"respecter of persons","strongs_def":" an accepter of a face (individual), i.e. (specially), one exhibiting partiality","derivation":"from G4383 (πρόσωπον) and G2983 (λαμβάνω);","pron":"pros-o-pol-ape'-tace","pos":"Noun Masculine","thayer":"<ol><li>an acceptor of persons</li><li>one who discriminates</li></ol>","xlit":"prosōpolḗptēs"},"G2924":{"kjv_def":"discerner","translit":"kritikós","lemma":"κριτικός","derivation":"from G2923 (κριτής);","strongs_def":" decisive (\"critical\"), i.e. discriminative","pron":"krit-ee-kos'","pos":"Adjective","thayer":"<ol><li>relating to judging, fit for judging, skilled in judging</li></ol>","xlit":"kritikós"},"G4551":{"kjv_def":"Sapphira","translit":"Sappheírē","lemma":"Σαπφείρη","derivation":"feminine of G4552 (σάπφειρος);","strongs_def":" Sapphire, an Israelitess","pron":"sap-fi'-ray","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Sapphira = \"a sapphire\"</p><ol><li>the wife of Ananias</li></ol>","xlit":"Sappheírē"},"G4914":{"strongs_def":" mutual habituation, i.e. usage","derivation":"from a compound of G4862 (σύν) and G2239 (ἦθος);","lemma":"συνήθεια","translit":"synḗtheia","kjv_def":"custom","pron":"soon-ay'-thi-ah","pos":"Noun Feminine","thayer":"<ol><li>intercourse (with one), intimacy</li><li>custom</li><li>a being used to, accustomed</li></ol>","xlit":"synḗtheia"},"G4773":{"translit":"syngenḗs","lemma":"συγγενής","kjv_def":"cousin, kin(-sfolk, -sman)","strongs_def":" a relative (by blood); by extension, a fellow countryman","derivation":"from G4862 (σύν) and G1085 (γένος);","pron":"soong-ghen-ace'","pos":"Adjective","thayer":"<ol><li>of the same kin, akin to, related by blood</li><li>in a wider sense, of the same nation, a fellow countryman</li></ol>","xlit":"syngenḗs"},"G4927":{"strongs_def":" to border together, i.e. adjoin","derivation":"from G4862 (σύν) and a derivative of a compound of the base of 3674 and the base of G3725 (ὅριον);","translit":"synomoréō","lemma":"συνομορέω","kjv_def":"join hard","pron":"soon-om-or-eh'-o","pos":"Verb","thayer":"<ol><li>to border on, be contiguous to<ol type='a'><li>of a thing</li></ol></li></ol>","xlit":"synomoréō"},"G1308":{"translit":"diaphérō","lemma":"διαφέρω","kjv_def":"be better, carry, differ from, drive up and down, be (more) excellent, make matter, publish, be of more value","strongs_def":" to bear through, i.e. (literally) transport; usually to bear apart, i.e. (objectively) to toss about (figuratively, report); subjectively, to \"differ\", or (by implication) surpass","derivation":"from G1223 (διά) and G5342 (φέρω);","pron":"dee-af-er'-o","xlit":"diaphérō"},"G847":{"kjv_def":"(t-)here","translit":"autoû","lemma":"αὐτοῦ","derivation":"genitive (i.e. possessive) of G846 (αὐτός), used as an adverb of location;","strongs_def":" properly, belonging to the same spot, i.e. in this (or that) place","pron":"ow-too'","pos":"Adverb","thayer":"<ol><li>in that place, there, here</li></ol>","xlit":"autoû"},"G2147":{"lemma":"εὑρίσκω","translit":"heurískō","kjv_def":"find, get, obtain, perceive, see","strongs_def":" to find (literally or figuratively)","derivation":"a prolonged form of a primary , which (together with another cognate form) is used for it in all the tenses except the present and imperfect;","pron":"hyoo-ris'-ko","pos":"Verb","thayer":"<ol><li>to come upon, hit upon, to meet with<ol type='a'><li>after searching, to find a thing sought</li><li>without previous search, to find (by chance), to fall in with</li><li>those who come or return to a place</li></ol><li>to find by enquiry, thought, examination, scrutiny, observation, to find out by practice and experience<ol type='a'><li>to see, learn, discover, understand</li><li>to be found, i.e. to be seen, be present</li><li>to be discovered, recognised, detected, to show one's self out, of one's character or state as found out by others (men, God, or both)</li><li>to get knowledge of, come to know, God</li></ol><li>to find out for one's self, to acquire, get, obtain, procure</li></ol>","xlit":"heurískō"},"G3762":{"lemma":"οὐδείς","translit":"oudeís","kjv_def":"any (man), aught, man, neither any (thing), never (man), no (man), none (+ of these things), not (any, at all, -thing), nought","strongs_def":" not even one (man, woman or thing), i.e. none, nobody, nothing","derivation":"from G3761 (οὐδέ) and G1520 (εἷς);","pron":"oo-dice'","thayer":"<ol><li>no one, nothing</li></ol>","xlit":"oudeís"},"G3652":{"derivation":"probably a contraction from (Olympian-bestowed, i.e. heaven-descended);","strongs_def":" Olympas, a Christian","kjv_def":"Olympas","translit":"Olympâs","lemma":"Ὀλυμπᾶς","pron":"ol-oom-pas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Olympas = \"heavenly\"</p><ol><li>a Christian at Rome</li></ol>","xlit":"Olympâs"},"G136":{"strongs_def":" properly, a story, but used in the sense of G1868 (ἔπαινος); praise (of God)","derivation":"apparently a prime word;","translit":"aînos","lemma":"αἶνος","kjv_def":"praise","pron":"ah'-ee-nos","pos":"Noun Masculine","thayer":"<ol><li>a saying, proverb</li><li>praise, laudatory discourse</li></ol>","xlit":"aînos"},"G901":{"kjv_def":"deep, very early","translit":"bathýs","lemma":"βαθύς","derivation":"from the base of G939 (βάσις);","strongs_def":" profound (as going down), literally or figuratively","pron":"bath-oos'","pos":"Adjective","thayer":"<ol><li>deep</li></ol>","xlit":"bathýs"},"G4820":{"lemma":"συμβάλλω","translit":"symbállō","kjv_def":"confer, encounter, help, make, meet with, ponder","strongs_def":" to combine, i.e. (in speaking) to converse, consult, dispute, (mentally) to consider, (by implication) to aid, (personally) to join, attack","derivation":"from G4862 (σύν) and G906 (βάλλω);","pron":"soom-bal'-lo","pos":"Verb","thayer":"<ol><li>to throw together, to bring together<ol type='a'><li>to converse</li><li>to bring together in one's mind, confer with one's self</li><li>to come together, meet<ol><li>to encounter in a hostile sense</li><li>to fight with one</li><li>to bring together of one's property, to contribute, aid, help</li></ol></li></ol></li></ol>","xlit":"symbállō"},"G4535":{"derivation":"probably from the base of G4525 (σαίνω);","strongs_def":" a vibration, i.e. (specially), billow","kjv_def":"wave","lemma":"σάλος","translit":"sálos","pron":"sal'-os","pos":"Noun Masculine","thayer":"<ol><li>the tossing or swell of the sea</li></ol>","xlit":"sálos"},"G5128":{"strongs_def":" these (persons, as objective of verb or preposition)","derivation":"accusative case plural masculine of G3778 (οὗτος);","lemma":"τούτους","translit":"toútous","kjv_def":"such, them, these, this","pron":"too'-tooce","thayer":"<ol><li>these</li></ol>","xlit":"toútous"},"G1777":{"strongs_def":" liable to (a condition, penalty or imputation)","derivation":"from G1758 (ἐνέχω);","translit":"énochos","lemma":"ἔνοχος","kjv_def":"in danger of, guilty of, subject to","pron":"en'-okh-os","pos":"Adjective","thayer":"<ol><li>bound, under obligation, subject to, liable<ol type='a'><li>used of one who is held by, possessed with love, and zeal for anything</li><li>in a forensic sense, denoting the connection of a person either with his crime, or with the penalty or trial, or with that against whom or which he has offended<ol><li>guilty, worthy of punishment</li><li>guilty of anything</li><li>of the crime</li><li>of the penalty</li><li>liable to this or that tribunal, i.e. the punishment to by imposed by this or that tribunal</li><li>of the place where punishment is to be suffered</li></ol></li></ol></li></ol>","xlit":"énochos"},"G1166":{"strongs_def":" to show (literally or figuratively)","derivation":"a prolonged form of an obsolete primary of the same meaning;","lemma":"δεικνύω","translit":"deiknýō","kjv_def":"shew","pron":"dike-noo'-o","pos":"Verb","thayer":"<ol><li>to show, expose to the eyes</li><li>metaphorically<ol type='a'><li>to give evidence or proof of a thing</li><li>to show by words or teach</li></ol></li></ol>","xlit":"deiknýō"},"G5189":{"derivation":"from a derivative of G5188 (τύφω);","strongs_def":" stormy (as if smoky)","kjv_def":"tempestuous","translit":"typhōnikós","lemma":"τυφωνικός","pron":"too-fo-nee-kos'","pos":"Adjective","thayer":"<ol><li>like a whirlwind, tempestuous</li></ol>","xlit":"typhōnikós"},"G2397":{"kjv_def":"countenance","lemma":"ἰδέα","translit":"idéa","derivation":"from G1492 (εἴδω);","strongs_def":" a sight (comparative figuratively \"idea\"), i.e. aspect","pron":"id-eh'-ah","pos":"Noun Feminine","thayer":"<ol><li>form, external appearance</li><li>aspect, look</li></ol>","xlit":"idéa"},"G895":{"lemma":"ἄψυχος","translit":"ápsychos","kjv_def":"without life","strongs_def":" lifeless, i.e. inanimate (mechanical)","derivation":"from G1 (Α) (as a negative particle) and G5590 (ψυχή);","pron":"ap'-soo-khos","pos":"Adjective","thayer":"<ol><li>without a soul, lifeless</li></ol>","xlit":"ápsychos"},"G1805":{"kjv_def":"redeem","lemma":"ἐξαγοράζω","translit":"exagorázō","derivation":"from G1537 (ἐκ) and G59 (ἀγοράζω);","strongs_def":" to buy up, i.e. ransom; figuratively, to rescue from loss (improve opportunity)","pron":"ex-ag-or-ad'-zo","pos":"Verb","thayer":"<ol><li>to redeem<ol type='a'><li>by payment of a price to recover from the power of another, to ransom, buy off</li><li>metaphorically of Christ freeing the elect from the dominion of the Mosaic Law at the price of his vicarious death</li></ol><li>to buy up, to buy up for one's self, for one's use<ol type='a'><li>to make wise and sacred use of every opportunity for doing good, so that zeal and well doing are as it were the purchase money by which we make the time our own</li></ol></li></ol>","xlit":"exagorázō"},"G1440":{"kjv_def":"seventy, three score and ten","translit":"hebdomḗkonta","lemma":"ἑβδομήκοντα","derivation":"from G1442 (ἕβδομος) and a modified form of G1176 (δέκα);","strongs_def":" seventy","pron":"heb-dom-ay'-kon-tah","pos":"Noun","thayer":"<ol><li>seventy<ol type='a'><li>the seventy disciples whom Jesus sent out in addition to the twelve apostles</li></ol></li></ol>","xlit":"hebdomḗkonta"},"G1241":{"lemma":"διαζώννυμι","translit":"diazṓnnymi","kjv_def":"gird","strongs_def":" to gird tightly","derivation":"from G1223 (διά) and G2224 (ζώννυμι);","pron":"dee-az-own'-noo-mee","pos":"Verb","thayer":"<ol><li>to bind or gird all around</li><li>to gird one's self with a thing, gird a thing around one's self</li></ol>","xlit":"diazṓnnymi"},"G1949":{"strongs_def":" to seize (for help, injury, attainment, or any other purpose; literally or figuratively)","derivation":"middle voice from G1909 (ἐπί) and G2983 (λαμβάνω);","lemma":"ἐπιλαμβάνομαι","translit":"epilambánomai","kjv_def":"catch, lay hold (up-)on, take (by, hold of, on)","pron":"ep-ee-lam-ban'-om-ahee","pos":"Verb","thayer":"<ol><li>to take in addition, to lay hold of, take possession of, overtake, attain, attain to<ol type='a'><li>to lay hold of or to seize upon anything with the hands, to take hold of, lay hold of</li><li>metaphorically to rescue one from peril, to help, succour</li></ol></li></ol>","xlit":"epilambánomai"},"G2631":{"derivation":"from G2632 (κατακρίνω);","strongs_def":" an adverse sentence (the verdict)","kjv_def":"condemnation","lemma":"κατάκριμα","translit":"katákrima","pron":"kat-ak'-ree-mah","pos":"Noun Neuter","thayer":"<ol><li>damnatory sentence, condemnation</li></ol>","xlit":"katákrima"},"G269":{"kjv_def":"not a brawler","lemma":"ἄμαχος","translit":"ámachos","derivation":"from G1 (Α) (as a negative particle) and G3163 (μάχη);","strongs_def":" peaceable","pron":"am'-akh-os","pos":"Adjective","thayer":"<ol><li>not to be withstood, invincible</li><li>not contentious</li><li>abstaining from fighting</li></ol>","xlit":"ámachos"},"G2976":{"strongs_def":" Lazarus (i.e. Elazar), the name of two Israelites (one imaginary)","derivation":"probably of Hebrew origin (H0499);","translit":"Lázaros","lemma":"Λάζαρος","kjv_def":"Lazarus","pron":"lad'-zar-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Lazarus = \"whom God helps\" (a form of the Hebrew name Eleazar)</p><ol><li>an inhabitant of Bethany, beloved by Christ and raised from the dead by him</li><li>a very poor and wretched person to whom Jesus referred to in <a class='bible' href='#b42.16.20-25'>Luk 16:20-25</a></li></ol>","xlit":"Lázaros"},"G1365":{"kjv_def":"doubt","translit":"distázō","lemma":"διστάζω","derivation":"from G1364 (δίς);","strongs_def":" properly, to duplicate, i.e. (mentally) to waver (in opinion)","pron":"dis-tad'-zo","pos":"Verb","thayer":"<ol><li>to doubt, waiver</li></ol>","xlit":"distázō"},"G2918":{"derivation":"perhaps a prim word;","strongs_def":" a lily","kjv_def":"lily","lemma":"κρίνον","translit":"krínon","pron":"kree'-non","pos":"Noun Neuter","thayer":"<ol><li>a flower, the lily</li></ol>","xlit":"krínon"},"G2753":{"kjv_def":"bid, (at, give) command(-ment)","translit":"keleúō","lemma":"κελεύω","derivation":"from a primary (to urge on);","strongs_def":" \"hail\"; to incite by word, i.e. order","pron":"kel-yoo'-o","pos":"Verb","thayer":"<ol><li>to command, to order</li></ol>","xlit":"keleúō"},"G5317":{"translit":"Phálek","lemma":"Φάλεκ","kjv_def":"Phalec","strongs_def":" Phalek (i.e. Peleg), a patriarch","derivation":"of Hebrew origin (H06389);","pron":"fal'-ek","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Peleg = \"division\"</p><ol><li>the son of Eber</li></ol>","xlit":"Phálek"},"G5381":{"strongs_def":" hospitableness","derivation":"from G5382 (φιλόξενος);","translit":"philonexía","lemma":"φιλονεξία","kjv_def":"entertain stranger, hospitality","pron":"fil-on-ex-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>love to strangers, hospitality</li></ol>","xlit":"philonexía"},"G5427":{"strongs_def":" (mental) inclination or purpose","derivation":"from G5426 (φρονέω);","lemma":"φρόνημα","translit":"phrónēma","kjv_def":"(be, + be carnally, + be spiritually) mind(-ed)","pron":"fron'-ay-mah","pos":"Noun Neuter","thayer":"<ol><li>what one has in the mind, the thoughts and purposes</li></ol>","xlit":"phrónēma"},"G464":{"strongs_def":" to struggle against (figuratively) (\"antagonize\")","derivation":"from G473 (ἀντί) and G75 (ἀγωνίζομαι);","translit":"antagōnízomai","lemma":"ἀνταγωνίζομαι","kjv_def":"strive against","pron":"an-tag-o-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to struggle, fight</li></ol>","xlit":"antagōnízomai"},"G4626":{"strongs_def":" to dig","derivation":"apparently a primary verb;","lemma":"σκάπτω","translit":"skáptō","kjv_def":"dig","pron":"skap'-to","pos":"Verb","thayer":"<ol><li>to dig</li></ol>","xlit":"skáptō"},"G4705":{"strongs_def":" prompt, energetic, earnest","derivation":"from G4710 (σπουδή);","translit":"spoudaîos","lemma":"σπουδαῖος","kjv_def":"diligent","pron":"spoo-dah'-yos","pos":"Adjective","thayer":"<ol><li>active, diligent, zealous, earnest</li><li>very diligent</li></ol>","xlit":"spoudaîos"},"G1674":{"derivation":"feminine of G1672 (Ἕλλην);","strongs_def":" a Grecian (i.e. non-Jewish) woman","kjv_def":"Greek","translit":"Hellēnís","lemma":"Ἑλληνίς","pron":"hel-lay-nis'","pos":"Noun Feminine","thayer":"<ol><li>a Greek women</li><li>a Gentile women, not a Jewess</li></ol>","xlit":"Hellēnís"},"G4269":{"derivation":"from G4266 (προγίνομαι);","strongs_def":" an ancestor, (grand-)parent","kjv_def":"forefather, parent","translit":"prógonos","lemma":"πρόγονος","pron":"prog'-on-os","pos":"Adjective","thayer":"<ol><li>born before, older<ol type='a'><li>of ancestors</li><li>of a mother</li><li>of grandparents</li><li>of great-grand parents (if they are still alive)</li></ol></li></ol>","xlit":"prógonos"},"G458":{"derivation":"from G459 (ἄνομος);","strongs_def":" illegality, i.e. violation of law or (genitive case) wickedness","kjv_def":"iniquity, X transgress(-ion of) the law, unrighteousness","translit":"anomía","lemma":"ἀνομία","pron":"an-om-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the condition of without law<ol type='a'><li>because ignorant of it</li><li>because of violating it</li></ol><li>contempt and violation of law, iniquity, wickedness</li></ol>","xlit":"anomía"},"G393":{"lemma":"ἀνατέλλω","translit":"anatéllō","kjv_def":"(a-, make to) rise, at the rising of, spring (up), be up","strongs_def":" to (cause to) arise","derivation":"from G303 (ἀνά) and the base of G5056 (τέλος);","pron":"an-at-el'-lo","pos":"Verb","thayer":"<ol><li>rise<ol type='a'><li>to cause to rise<ol><li>of the earth bring forth plants</li></ol><li>to rise, arise, to rise from, be descended from<ol><li>of sun moon and stars)</li></ol></li></ol></li></ol>","xlit":"anatéllō"},"G3127":{"strongs_def":" Manaën, a Christian","derivation":"of uncertain origin;","lemma":"Μαναήν","translit":"Manaḗn","kjv_def":"Manaen","pron":"man-ah-ane'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Manaen = \"comforter\"</p><ol><li>one of the teachers and prophets in the church at Antioch</li></ol>","xlit":"Manaḗn"},"G3358":{"translit":"métron","lemma":"μέτρον","kjv_def":" measure","strongs_def":" a measure (\"metre\"), literally or figuratively; by implication, a limited portion (degree)","derivation":"an apparently primary word;","pron":"met'-ron","pos":"Noun Neuter","thayer":"<ol><li>measure, an instrument for measuring<ol type='a'><li>a vessel for receiving and determining the quantity of things, whether dry or liquid</li><li>a graduated staff for measuring, a measuring rod</li><li>proverbially, the rule or standard of judgment</li></ol><li>determined extent, portion measured off, measure or limit<ol type='a'><li>the required measure, the due, fit, measure</li></ol></li></ol>","xlit":"métron"},"G5062":{"strongs_def":" forty","derivation":"the decade of G5064 (τέσσαρες);","translit":"tessarákonta","lemma":"τεσσαράκοντα","kjv_def":"forty","pron":"tes-sar-ak'-on-tah","pos":"Adjective","thayer":"<ol><li>forty</li></ol>","xlit":"tessarákonta"},"G2491":{"derivation":"of Hebrew origin (H03110);","strongs_def":" Joannes (i.e. Jochanan), the name of four Israelites","kjv_def":"John","translit":"Iōánnēs","lemma":"Ἰωάννης","pron":"ee-o-an'-nace","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: John = \"Jehovah is a gracious giver\"</p><ol><li>John the Baptist was the son of Zacharias and Elisabeth, the forerunner of Christ. By order of Herod Antipas he was cast into prison and afterwards beheaded.</li><li>John the apostle, the writer of the Fourth Gospel, son of Zebedee and Salome, brother of James the elder. He is that disciple who</li><li>John surnamed Mark, the companion of Barnabas and Paul. <a class='bible' href='#b44.12.12'>Act 12:12</a></li><li>John a certain man, a member of the Sanhedrin <a class='bible' href='#b44.5.6'>Act 5:6</a></li></ol>","xlit":"Iōánnēs"},"G513":{"derivation":"probably from (to break;","strongs_def":" compare G4486 (ῥήγνυμι)); an axe","kjv_def":"axe","translit":"axínē","lemma":"ἀξίνη","pron":"ax-ee'-nay","pos":"Noun Feminine","thayer":"<ol><li>an axe</li></ol>","xlit":"axínē"},"G785":{"strongs_def":" a buckler (or round shield); used of a serpent (as coiling itself), probably the \"asp\"","derivation":"of uncertain derivation;","lemma":"ἀσπίς","translit":"aspís","kjv_def":"asp","pron":"as-pece'","pos":"Noun Masculine","thayer":"<ol><li>an asp, a small and most venomous serpent, the bite of which is fatal unless the part bitten be immediately cut away</li></ol>","xlit":"aspís"},"G776":{"translit":"asitía","lemma":"ἀσιτία","kjv_def":"abstinence","strongs_def":" fasting (the state)","derivation":"from G777 (ἄσιτος);","pron":"as-ee-tee'-ah","pos":"Noun Feminine","thayer":"<ol><li>abstinence from food (whether voluntary or enforced)</li></ol>","xlit":"asitía"},"G2435":{"kjv_def":"mercyseat, propitiation","lemma":"ἱλαστήριον","translit":"hilastḗrion","derivation":"neuter of a derivative of G2433 (ἱλάσκομαι);","strongs_def":" an expiatory (place or thing), i.e. (concretely) an atoning victim, or (specially) the lid of the Ark (in the Temple)","pron":"hil-as-tay'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>relating to an appeasing or expiating, having placating or expiating force, expiatory; a means of appeasing or expiating, a propitiation<ol type='a'><li>used of the cover of the ark of the covenant in the Holy of Holies, which was sprinkled with the blood of the expiatory victim on the annual day of atonement (this rite signifying that the life of the people, the loss of which they had merited by their sins, was offered to God in the blood as the life of the victim, and that God by this ceremony was appeased and their sins expiated); hence the lid of expiation, the propitiatory</li><li>an expiatory sacrifice</li><li>a expiatory victim</li></ol></li></ol>","xlit":"hilastḗrion"},"G2306":{"derivation":"from G2303 (θεῖον) and 1491;","strongs_def":" sulphur-like, i.e. sulphurous","kjv_def":"brimstone","lemma":"θειώδης","translit":"theiṓdēs","pron":"thi-o'-dace","pos":"Adjective","thayer":"<ol><li>of brimstone, sulphurous</li></ol>","xlit":"theiṓdēs"},"G1560":{"derivation":"from G1537 (ἐκ) and a derivative of G1325 (δίδωμι);","strongs_def":" given out or over, i.e. surrendered","kjv_def":"delivered","translit":"ékdotos","lemma":"ἔκδοτος","pron":"ek'-dot-os","pos":"Adjective","thayer":"<ol><li>given over, delivered up<ol type='a'><li>to enemies, or to the power, the will, of some one</li></ol></li></ol>","xlit":"ékdotos"},"G213":{"translit":"alazṓn","lemma":"ἀλαζών","kjv_def":"boaster","strongs_def":" braggart","derivation":"from (vagrancy);","pron":"al-ad-zone'","pos":"Noun Masculine","thayer":"<ol><li>an empty pretender, a boaster</li></ol>","xlit":"alazṓn"},"G3430":{"derivation":"from G3431 (μοιχεύω);","strongs_def":" adultery","kjv_def":"adultery","translit":"moicheía","lemma":"μοιχεία","pron":"moy-khi'-ah","pos":"Noun Feminine","thayer":"<ol><li>adultery</li></ol>","xlit":"moicheía"},"G1903":{"derivation":"from G1902 (ἐπενδύομαι);","strongs_def":" a wrapper, i.e. outer garment","kjv_def":"fisher's coat","lemma":"ἐπενδύτης","translit":"ependýtēs","pron":"ep-en-doo'-tace","pos":"Noun Masculine","thayer":"<ol><li>an upper garment<ol type='a'><li><a class='bible' href='#b43.21.7'>Joh 21:7</a> seems to denote a kind of linen blouse or frock which fishermen used to wear at their work</li></ol></li></ol>","xlit":"ependýtēs"},"G284":{"strongs_def":" Aminadab, an Israelite","derivation":"of Hebrew origin (H05992);","translit":"Aminadáb","lemma":"Ἀμιναδάβ","kjv_def":"Aminadab","pron":"am-ee-nad-ab'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Amminadab = \"one of the prince's people\"</p><ol><li>an ancestor of Christ</li></ol>","xlit":"Aminadáb"},"G1910":{"strongs_def":" to walk upon, i.e. mount, ascend, embark, arrive","derivation":"from G1909 (ἐπί) and the base of G939 (βάσις);","lemma":"ἐπιβαίνω","translit":"epibaínō","kjv_def":"come (into), enter into, go abroad, sit upon, take ship","pron":"ep-ee-bah'-ee-no","pos":"Verb","thayer":"<ol><li>to get upon, mount<ol type='a'><li>to embark in</li><li>to go aboard (a ship)</li></ol><li>to set foot in, enter</li></ol>","xlit":"epibaínō"},"G4893":{"derivation":"from a prolonged form of G4894 (συνείδω);","strongs_def":" co-perception, i.e. moral consciousness","kjv_def":"conscience","translit":"syneídēsis","lemma":"συνείδησις","pron":"soon-i'-day-sis","pos":"Noun Feminine","thayer":"<ol><li>the consciousness of anything</li><li>the soul as distinguishing between what is morally good and bad, prompting to do the former and shun the latter, commending one, condemning the other<ol type='a'><li>the conscience</li></ol></li></ol>","xlit":"syneídēsis"},"G4610":{"kjv_def":"Silvanus","lemma":"Σιλουανός","translit":"Silouanós","derivation":"of Latin origin;","strongs_def":" \"silvan\"; Silvanus, a Christian","pron":"sil-oo-an-os'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Silas = \"woody\"</p><ol><li>a Roman citizen, the companion of the apostle Paul on several of his missionary journeys</li></ol>","xlit":"Silouanós"},"G622":{"translit":"apóllymi","lemma":"ἀπόλλυμι","kjv_def":"destroy, die, lose, mar, perish","strongs_def":" to destroy fully (reflexively, to perish, or lose), literally or figuratively","derivation":"from G575 (ἀπό) and the base of G3639 (ὄλεθρος);","pron":"ap-ol'-loo-mee","pos":"Verb","thayer":"<ol><li>to destroy<ol type='a'><li>to put out of the way entirely, abolish, put an end to ruin</li><li>render useless</li><li>to kill</li><li>to declare that one must be put to death</li><li>metaphorically to devote or give over to eternal misery in hell</li><li>to perish, to be lost, ruined, destroyed</li></ol><li>to destroy<ol type='a'><li>to lose</li></ol></li></ol>","xlit":"apóllymi"},"G2561":{"translit":"kákōsis","lemma":"κάκωσις","kjv_def":"affliction","strongs_def":" maltreatment","derivation":"from G2559 (κακόω);","pron":"kak'-o-sis","pos":"Noun Feminine","thayer":"<ol><li>ill treatment, ill usage</li></ol>","xlit":"kákōsis"},"G3839":{"derivation":"adverb (of manner) from G3956 (πᾶς);","strongs_def":" wholly","kjv_def":"always","translit":"pántē","lemma":"πάντη","pron":"pan'-tay","pos":"Adverb","thayer":"<ol><li>everywhere, wholly, in all respects, in every way</li></ol>","xlit":"pántē"},"G2996":{"kjv_def":"Lasea","lemma":"Λασαία","translit":"Lasaía","derivation":"of uncertain origin;","strongs_def":" Lasæa, a place in Crete","pron":"las-ah'-yah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Lasea = \"shaggy\"</p><ol><li>a city in Crete on the coast near Fair Havens</li></ol>","xlit":"Lasaía"},"G3597":{"lemma":"ὁδοιπορία","translit":"hodoiporía","kjv_def":"journey(-ing)","strongs_def":" travel","derivation":"from the same as G3596 (ὁδοιπορέω);","pron":"hod-oy-por-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a journey, journeying</li></ol>","xlit":"hodoiporía"},"G4987":{"lemma":"σωρεύω","translit":"sōreúō","kjv_def":"heap, load","strongs_def":" to pile up (literally or figuratively)","derivation":"from another form of G4673 (σορός);","pron":"sore-yoo'-o","pos":"Verb","thayer":"<ol><li>to heap together, to heap up</li><li>to overwhelm one with a heap of anything</li><li>metaphorically to load one with the consciousness of many sins</li></ol>","xlit":"sōreúō"},"G2319":{"kjv_def":"hater of God","translit":"theostygḗs","lemma":"θεοστυγής","derivation":"from G2316 (θεός) and the base of G4767 (στυγνητός);","strongs_def":" hateful to God, i.e. impious","pron":"theh-os-too-gace'","pos":"Adjective","thayer":"<ol><li>hateful to God, exceptionally impious and wicked</li></ol>","xlit":"theostygḗs"},"G3984":{"derivation":"from the base of G4008 (πέραν) (through the idea of piercing);","strongs_def":" a test, i.e. attempt, experience","kjv_def":"assaying, trial","translit":"peîra","lemma":"πεῖρα","pron":"pi'-rah","pos":"Noun Feminine","thayer":"<ol><li>a trial, experience, attempt</li><li>to attempt a thing, to make trial of a thing or of a person</li><li>to have a trial of a thing</li><li>to experience, learn to know by experience</li></ol>","xlit":"peîra"},"G3569":{"kjv_def":"(but) now","lemma":"τανῦν","translit":"tanŷn","derivation":"from neuter plural of G3588 (ὁ) and G3568 (νῦν);","strongs_def":" the things now, i.e. (adverbially) at present","pron":"tan-oon'","pos":"Adverb","thayer":"<ol><li>now, the present</li></ol>","xlit":"tanŷn"},"G1814":{"kjv_def":"leap up","lemma":"ἐξάλλομαι","translit":"exállomai","derivation":"from G1537 (ἐκ) and G242 (ἅλλομαι);","strongs_def":" to spring forth ","pron":"ex-al'-lom-ahee","pos":"Verb","thayer":"<ol><li>to leap up</li></ol>","xlit":"exállomai"},"G4506":{"kjv_def":"deliver(-er)","lemma":"ῥύομαι","translit":"rhýomai","derivation":"middle voice of an obsolete verb, akin to G4482 (ῥέω) (through the idea of a current;","strongs_def":" compare G4511 (ῥύσις)); to rush or draw (for oneself), i.e. rescue","pron":"rhoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to draw to one's self, to rescue, to deliver</li><li>the deliverer</li></ol>","xlit":"rhýomai"},"G4813":{"lemma":"συλάω","translit":"syláō","kjv_def":"rob","strongs_def":" probably akin to G138 (αἱρέομαι); compare G4661 (σκῦλον)); to despoil","derivation":"from a derivative of (to strip;","pron":"soo-lah'-o","pos":"Verb","thayer":"<ol><li>to rob, despoil</li></ol>","xlit":"syláō"},"G3472":{"derivation":"from G3474 (μωρός);","strongs_def":" silliness, i.e. absurdity","kjv_def":"foolishness","translit":"mōría","lemma":"μωρία","pron":"mo-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>foolishness</li></ol>","xlit":"mōría"},"G928":{"translit":"basanízō","lemma":"βασανίζω","kjv_def":"pain, toil, torment, toss, vex","strongs_def":" to torture","derivation":"from G931 (βάσανος);","pron":"bas-an-id'-zo","pos":"Verb","thayer":"<ol><li>to test (metals) by the touchstone, which is a black siliceous stone used to test the purity of gold or silver by the colour of the streak produced on it by rubbing it with either metal</li><li>to question by applying torture</li><li>to torture</li><li>to vex with grievous pains (of body or mind), to torment</li><li>to be harassed, distressed<ol type='a'><li>of those who at sea are struggling with a head wind</li></ol></li></ol>","xlit":"basanízō"},"G1854":{"derivation":"adverb from G1537 (ἐκ);","strongs_def":" out(-side, of doors), literally or figuratively","kjv_def":"away, forth, (with-)out (of, -ward), strange","lemma":"ἔξω","translit":"éxō","pron":"ex'-o","pos":"Adverb","thayer":"<ol><li>without, out of doors</li></ol>","xlit":"éxō"},"G1522":{"lemma":"εἰσακούω","translit":"eisakoúō","kjv_def":"hear","strongs_def":" to listen to","derivation":"from G1519 (εἰς) and G191 (ἀκούω);","pron":"ice-ak-oo'-o","pos":"Verb","thayer":"<ol><li>to give heed to, comply with admonition, to obey</li><li>to listen to, assent to, a request, to be heard, have request granted<ol type='a'><li>of persons offering prayers to God</li><li>of prayers offered up</li></ol></li></ol>","xlit":"eisakoúō"},"G5004":{"translit":"talaipōría","lemma":"ταλαιπωρία","kjv_def":"misery","strongs_def":" wretchedness, i.e. calamity","derivation":"from G5005 (ταλαίπωρος);","pron":"tal-ahee-po-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>hardship, trouble, calamity, misery</li></ol>","xlit":"talaipōría"},"G2250":{"translit":"hēméra","lemma":"ἡμέρα","kjv_def":"age, + alway, (mid-)day (by day, (-ly)), + for ever, judgment, (day) time, while, years","strongs_def":" day, i.e. (literally) the time space between dawn and dark, or the whole 24 hours (but several days were usually reckoned by the Jews as inclusive of the parts of both extremes); figuratively, a period (always defined more or less clearly by the context)","derivation":"feminine (with G5610 (ὥρα) implied) of a derivative of (to sit; akin to the base of G1476 (ἑδραῖος)) meaning tame, i.e. gentle;","pron":"hay-mer'-ah","pos":"Noun Feminine","thayer":"<ol><li>the day, used of the natural day, or the interval between sunrise and sunset, as distinguished from and contrasted with the night<ol type='a'><li>in the daytime</li><li>metaphorically, \"the day\" is regarded as the time for abstaining from indulgence, vice, crime, because acts of the sort are perpetrated at night and in darkness</li></ol><li>of the civil day, or the space of twenty four hours (thus including the night)<ol type='a'><li>Eastern usage of this term differs from our western usage. Any part of a day is counted as a whole day, hence the expression \"three days and three nights\" does not mean literally three whole days, but at least one whole day plus part of two other days.</li></ol><li>of the last day of this present age, the day Christ will return from heaven, raise the dead, hold the final judgment, and perfect his kingdom</li><li>used of time in general, i.e. the days of his life.</li></ol>","xlit":"hēméra"},"G1650":{"derivation":"from G1651 (ἐλέγχω);","strongs_def":" proof, conviction","kjv_def":"evidence, reproof","lemma":"ἔλεγχος","translit":"élenchos","pron":"el'-eng-khos","pos":"Noun Masculine","thayer":"<ol><li>a proof, that by which a thing is proved or tested</li><li>conviction</li></ol>","xlit":"élenchos"},"G3333":{"derivation":"from G3326 (μετά) and G2564 (καλέω);","strongs_def":" to call elsewhere, i.e. summon","kjv_def":"call (for, hither)","translit":"metakaléō","lemma":"μετακαλέω","pron":"met-ak-al-eh'-o","pos":"Verb","thayer":"<ol><li>to call from one place to another, to summon</li><li>to call one's self</li></ol>","xlit":"metakaléō"},"G2971":{"strongs_def":" a mosquito (from its stinging proboscis)","derivation":"apparently a derivative of the base of G2759 (κέντρον) and a derivative of G3700 (ὀπτάνομαι);","translit":"kṓnōps","lemma":"κώνωψ","kjv_def":"gnat","pron":"ko'-nopes","pos":"Noun Masculine","thayer":"<ol><li>a wine gnat or midge that is bred in fermenting and evaporating wine</li></ol>","xlit":"kṓnōps"},"G5089":{"derivation":"perhaps akin to the alternate of G138 (αἱρέομαι), and thus to G4951 (σύρω);","strongs_def":" to pull off","kjv_def":"pluck","translit":"tíllō","lemma":"τίλλω","pron":"til'-lo","pos":"Verb","thayer":"<ol><li>to pluck, pluck off</li></ol>","xlit":"tíllō"},"G2751":{"lemma":"κείρω","translit":"keírō","kjv_def":"shear(-er)","strongs_def":" to shear","derivation":"a primary verb;","pron":"ki'-ro","pos":"Verb","thayer":"<ol><li>to sheer: a sheep</li><li>to get or let be shorn</li><li>of shearing or cutting short the hair of the head</li></ol>","xlit":"keírō"},"G4902":{"kjv_def":"accompany","translit":"synépomai","lemma":"συνέπομαι","derivation":"middle voice from G4862 (σύν) and a primary (to follow);","strongs_def":" to attend (travel) in company with","pron":"soon-ep'-om-ahee","pos":"Verb","thayer":"<ol><li>to follow with, to accompany</li></ol>","xlit":"synépomai"},"G5359":{"translit":"Philadélpheia","lemma":"Φιλαδέλφεια","kjv_def":"Philadelphia","strongs_def":" Philadelphia, a place in Asia Minor","derivation":"from (the same as G5361 (φιλάδελφος)), a king of Pergamos;","pron":"fil-ad-el'-fee-ah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Philadelphia = \"brotherly love\"</p><ol><li>a city of Lydia in Asia Minor, situated near the eastern base of of Mount Tmolus, founded and named by the Pergamene king, Attalus II Philadelphus. After the death of Attalus III Philometor, 133 BC, it together with his entire kingdom came by his will under the jurisdiction of the Romans.</li></ol>","xlit":"Philadélpheia"},"G2997":{"kjv_def":"burst asunder","translit":"láschō","lemma":"λάσχω","derivation":"a strengthened form of a primary verb, which only occurs in this and another prolonged form as alternate in certain tenses;","strongs_def":" to crack open (from a fall)","pron":"las'-kho","pos":"Verb","thayer":"<ol><li>to crack, crackle, crash</li><li>to burst asunder with a crack, crack open</li></ol>","xlit":"láschō"},"G1846":{"derivation":"from G1537 (ἐκ) and G3736 (ὀρύσσω);","strongs_def":" to dig out, i.e. (by extension) to extract (an eye), remove (roofing)","kjv_def":"break up, pluck out","lemma":"ἐξορύσσω","translit":"exorýssō","pron":"ex-or-oos'-so","pos":"Verb","thayer":"<ol><li>to dig out, to pluck out (the eyes)</li><li>to dig through</li></ol>","xlit":"exorýssō"},"G3027":{"kjv_def":"robber, thief","lemma":"λῃστής","translit":"lēistḗs","derivation":"from (to plunder);","strongs_def":" a brigand","pron":"lace-tace'","pos":"Noun Masculine","thayer":"<ol><li>a robber, plunderer, freebooter, brigand</li></ol>","xlit":"lēistḗs"},"G2974":{"kjv_def":"deaf, dumb, speechless","lemma":"κωφός","translit":"kōphós","derivation":"from G2875 (κόπτω);","strongs_def":" blunted, i.e. (figuratively) of hearing (deaf) or speech (dumb)","pron":"ko-fos'","pos":"Adjective","thayer":"<ol><li>blunted, dull<ol type='a'><li>blunted (or lamed) in tongue, dumb</li><li>blunted, dull in hearing</li><li>deaf</li></ol></li></ol>","xlit":"kōphós"},"G1850":{"translit":"exousiázō","lemma":"ἐξουσιάζω","kjv_def":"exercise authority upon, bring under the (have) power of","strongs_def":" to control","derivation":"from G1849 (ἐξουσία);","pron":"ex-oo-see-ad'-zo","pos":"Verb","thayer":"<ol><li>to have power or authority, use power<ol type='a'><li>to be master of any one, exercise authority over one</li><li>to be master of the body<ol><li>to have full and entire authority over the body</li><li>to hold the body subject to one's will</li></ol><li>to be brought under the power of anyone</li></ol></li></ol>","xlit":"exousiázō"},"G1411":{"strongs_def":" force (literally or figuratively); specially, miraculous power (usually by implication, a miracle itself)","derivation":"from G1410 (δύναμαι);","lemma":"δύναμις","translit":"dýnamis","kjv_def":"ability, abundance, meaning, might(-ily, -y, -y deed), (worker of) miracle(-s), power, strength, violence, mighty (wonderful) work","pron":"doo'-nam-is","pos":"Noun Feminine","thayer":"<ol><li>strength power, ability<ol type='a'><li>inherent power, power residing in a thing by virtue of its nature, or which a person or thing exerts and puts forth</li><li>power for performing miracles</li><li>moral power and excellence of soul</li><li>the power and influence which belong to riches and wealth</li><li>power and resources arising from numbers</li><li>power consisting in or resting upon armies, forces, hosts</li></ol></li></ol>","xlit":"dýnamis"},"G5323":{"kjv_def":"Phanuel","translit":"Phanouḗl","lemma":"Φανουήλ","derivation":"of Hebrew origin (H06439);","strongs_def":" Phanuel (i.e. Penuel), an Israelite","pron":"fan-oo-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Phanuel = \"the face of God\"</p><ol><li>the father of Anna, the prophetess of the tribe of Asher</li></ol>","xlit":"Phanouḗl"},"G703":{"derivation":"from the same as G730 (ἄῤῥην);","strongs_def":" properly, manliness (valor), i.e. excellence (intrinsic or attributed)","kjv_def":"praise, virtue","lemma":"ἀρέτη","translit":"arétē","pron":"ar-et'-ay","pos":"Noun Feminine","thayer":"<ol><li>a virtuous course of thought, feeling and action<ol type='a'><li>virtue, moral goodness</li></ol><li>any particular moral excellence, as modesty, purity</li></ol>","xlit":"arétē"},"G2711":{"lemma":"καταψύχω","translit":"katapsýchō","kjv_def":"cool","strongs_def":" to cool down (off), i.e. refresh","derivation":"from G2596 (κατά) and G5594 (ψύχω);","pron":"kat-ap-soo'-kho","pos":"Verb","thayer":"<ol><li>to cool off, make cool</li></ol>","xlit":"katapsýchō"},"G766":{"derivation":"from a compound of G1 (Α) (as a negative particle) and a presumed (of uncertain derivation, but apparently meaning continent);","strongs_def":" licentiousness (sometimes including other vices)","kjv_def":"filthy, lasciviousness, wantonness","lemma":"ἀσέλγεια","translit":"asélgeia","pron":"as-elg'-i-a","pos":"Noun Feminine","thayer":"<ol><li>unbridled lust, excess, licentiousness, lasciviousness, wantonness, outrageousness, shamelessness, insolence</li></ol>","xlit":"asélgeia"},"G2832":{"strongs_def":" Clopas, an Israelite","derivation":"of Chaldee origin (corresponding to H0256);","translit":"Klōpâs","lemma":"Κλωπᾶς","kjv_def":"Cleophas","pron":"klo-pas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cleophas = \"my exchanges\"</p><ol><li>the father of James the less, the husband of Mary the sister of the mother of Jesus</li></ol>","xlit":"Klōpâs"},"G3387":{"derivation":"from G3361 (μή) and G5100 (τὶς);","strongs_def":" whether any","kjv_def":"any (sometimes unexpressed except by the simple interrogative form of the sentence)","lemma":"μήτις","translit":"mḗtis","pron":"may'-tis","thayer":"<ol><li>let no one</li><li>hath any one</li></ol>","xlit":"mḗtis"},"G4707":{"strongs_def":" more prompt, more earnest","derivation":"comparative of G4705 (σπουδαῖος);","lemma":"σπουδαιότερος","translit":"spoudaióteros","kjv_def":"more diligent (forward)","pron":"spoo-dah-yot'-er-os","pos":"Adjective","thayer":"<ol><li>active, diligent, zealous, earnest</li><li>very diligent</li></ol>","xlit":"spoudaióteros"},"G4851":{"lemma":"συμφέρω","translit":"symphérō","kjv_def":"be better for, bring together, be expedient (for), be good, (be) profit(-able for)","strongs_def":" to bear together (contribute), i.e. (literally) to collect, or (figuratively) to conduce; especially (neuter participle as a noun) advantage","derivation":"from G4862 (σύν) and G5342 (φέρω) (including its alternate);","pron":"soom-fer'-o","pos":"Verb","thayer":"<ol><li>to bear or bring together</li><li>to bear together or at the same time<ol type='a'><li>to carry with others</li><li>to collect or contribute in order to help</li><li>to help, be profitable, be expedient</li></ol></li></ol>","xlit":"symphérō"},"G2233":{"derivation":"middle voice of a (presumed) strengthened form of G71 (ἄγω);","strongs_def":" to lead, i.e. command (with official authority); figuratively, to deem, i.e. consider","kjv_def":"account, (be) chief, count, esteem, governor, judge, have the rule over, suppose, think","translit":"hēgéomai","lemma":"ἡγέομαι","pron":"hayg-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to lead<ol type='a'><li>to go before</li><li>to be a leader<ol><li>to rule, command</li><li>to have authority over</li><li>a prince, of regal power, governor, viceroy, chief, leading as respects influence, controlling in counsel, overseers or leaders of the churches</li><li>used of any kind of leader, chief, commander</li><li>the leader in speech, chief, spokesman</li></ol></li></ol><li>to consider, deem, account, think</li></ol>","xlit":"hēgéomai"},"G2080":{"strongs_def":" inside (as preposition or adjective)","derivation":"from G1519 (εἰς);","translit":"ésō","lemma":"ἔσω","kjv_def":" (with-)in(-ner, -to, -ward)","pron":"es'-o","pos":"Adverb","thayer":"<ol><li>to within, into</li><li>within<ol type='a'><li>the internal inner man</li><li>the soul, conscience</li></ol></li></ol>","xlit":"ésō"},"G1038":{"lemma":"βυρσεύς","translit":"byrseús","kjv_def":"tanner","strongs_def":" a tanner","derivation":"from (a hide);","pron":"boorce-yooce'","pos":"Noun Masculine","thayer":"<ol><li>a tanner</li></ol>","xlit":"byrseús"},"G3353":{"derivation":"from G3348 (μετέχω);","strongs_def":" participant, i.e. (as noun) a sharer; by implication, an associate","kjv_def":"fellow, partaker, partner","translit":"métochos","lemma":"μέτοχος","pron":"met'-okh-os","pos":"Adjective","thayer":"<ol><li>sharing in, partaking</li><li>a partner (in a work, office, dignity)</li></ol>","xlit":"métochos"},"G5622":{"derivation":"from a derivative of the base of G5624 (ὠφέλιμος);","strongs_def":" usefulness, i.e. benefit","kjv_def":"advantage, profit","lemma":"ὠφέλεια","translit":"ōphéleia","pron":"o-fel'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>usefulness, advantage, profit</li></ol>","xlit":"ōphéleia"},"G2144":{"kjv_def":"acceptable(-ted)","translit":"euprósdektos","lemma":"εὐπρόσδεκτος","derivation":"from G2095 (εὖ) and a derivative of G4327 (προσδέχομαι);","strongs_def":" well-received, i.e. approved, favorable","pron":"yoo-pros'-dek-tos","pos":"Adjective","thayer":"<ol><li>well received, accepted, acceptable</li></ol>","xlit":"euprósdektos"},"G3381":{"kjv_def":"lest (by any means, by some means, haply, perhaps)","translit":"mḗpōs","lemma":"μήπως","derivation":"from G3361 (μή) and G4458 (-πώς);","strongs_def":" lest somehow","pron":"may'-pos","pos":"Conjunction","thayer":"<ol><li>lest, lest somehow, that perhaps</li></ol>","xlit":"mḗpōs"},"G1841":{"strongs_def":" an exit, i.e. (figuratively) death","derivation":"from G1537 (ἐκ) and G3598 (ὁδός);","translit":"éxodos","lemma":"ἔξοδος","kjv_def":"decease, departing","pron":"ex'-od-os","pos":"Noun Masculine","thayer":"<ol><li>exit, i.e. departure</li><li>the close of one's career, one's final fate</li><li>departure from life, decease</li></ol>","xlit":"éxodos"},"G3426":{"strongs_def":" a modius, i.e. certain measure for things dry (the quantity or the utensil)","derivation":"of Latin origin;","lemma":"μόδιος","translit":"módios","kjv_def":"bushel","pron":"mod'-ee-os","pos":"Noun Masculine","thayer":"<ol><li>a dry measure holding 16 sextarii (or 1/6 of the Attic medimnus), about a peck (9 litres)</li></ol>","xlit":"módios"},"G731":{"translit":"árrhētos","lemma":"ἄῤῥητος","kjv_def":"unspeakable","strongs_def":" unsaid, i.e. (by implication) inexpressible","derivation":"from G1 (Α) (as a negative particle) and the same as G4490 (ῥητῶς);","pron":"ar'-hray-tos","pos":"Adjective","thayer":"<ol><li>unsaid, unspoken</li><li>unspeakable (on account of its sacredness)</li></ol>","xlit":"árrhētos"},"G1425":{"derivation":"from G1418 (δυσ-) and a derivative of G3539 (νοιέω);","strongs_def":" difficult of perception","kjv_def":"hard to be understood","lemma":"δυσνόητος","translit":"dysnóētos","pron":"doos-no'-ay-tos","pos":"Adjective","thayer":"<ol><li>hard to be understood</li></ol>","xlit":"dysnóētos"},"G4857":{"lemma":"συμφώνησις","translit":"symphṓnēsis","kjv_def":"concord","strongs_def":" accordance","derivation":"from G4856 (συμφωνέω);","pron":"soom-fo'-nay-sis","pos":"Noun Feminine","thayer":"<ol><li>concord, agreement</li></ol>","xlit":"symphṓnēsis"},"G1191":{"strongs_def":" Derbe, a place in Asia Minor","derivation":"of foreign origin;","translit":"Dérbē","lemma":"Δέρβη","kjv_def":"Derbe","pron":"der-bay'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Derbe = \"tanner: tanner of skin: coverer with skin\"</p><ol><li>a city of Lycaonia, on the confines of Isauria</li></ol>","xlit":"Dérbē"},"G3022":{"kjv_def":"white","lemma":"λευκός","translit":"leukós","derivation":"from (\"light\");","strongs_def":" white","pron":"lyoo-kos'","pos":"Adjective","thayer":"<ol><li>light, bright, brilliant<ol type='a'><li>brilliant from whiteness, (dazzling) white<ol><li>of the garments of angels, and of those exalted to the splendour of the heavenly state</li><li>shining or white garments worn on festive or state occasions</li><li>of white garments as the sign of innocence and purity of the soul</li></ol><li>dead white<ol><li>of the whitening colour of ripening grain</li></ol></li></ol></li></ol>","xlit":"leukós"},"G1540":{"derivation":"of uncertain affinity;","strongs_def":" a hundred","kjv_def":"hundred","lemma":"ἑκατόν","translit":"hekatón","pron":"hek-at-on'","pos":"Noun","thayer":"<ol><li>a hundred</li></ol>","xlit":"hekatón"},"G3749":{"strongs_def":" earthen-ware, i.e. clayey; by implication, frail","derivation":"from (\"oyster\") (a tile, i.e. terra cotta);","translit":"ostrákinos","lemma":"ὀστράκινος","kjv_def":"of earth, earthen","pron":"os-tra'-kin-os","pos":"Adjective","thayer":"<ol><li>earthen, clay<ol type='a'><li>with the added suggestion of frailty</li></ol></li></ol>","xlit":"ostrákinos"},"G5365":{"derivation":"from G5366 (φιλάργυρος);","strongs_def":" avarice","kjv_def":"love of money","translit":"philargyría","lemma":"φιλαργυρία","pron":"fil-ar-goo-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>love of money, avarice</li></ol>","xlit":"philargyría"},"G3493":{"kjv_def":"Nachor","translit":"Nachṓr","lemma":"Ναχώρ","derivation":"of Hebrew origin (H05152);","strongs_def":" Nachor, the grandfather of Abraham","pron":"nakh-ore'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nahor = \"snorting\"</p><ol><li>was the name of two persons in the family of Abraham, an ancestor of Christ</li></ol>","xlit":"Nachṓr"},"G233":{"translit":"halízō","lemma":"ἁλίζω","kjv_def":"salt","strongs_def":" to salt","derivation":"from G251 (ἅλς);","pron":"hal-id'-zo","pos":"Verb","thayer":"<ol><li>to salt, season with salt, sprinkle with salt</li></ol>","xlit":"halízō"},"G4613":{"strongs_def":" Simon (i.e. Shimon), the name of nine Israelites","derivation":"of Hebrew origin (H08095);","translit":"Símōn","lemma":"Σίμων","kjv_def":"Simon","pron":"see'-mone","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Peter = \"a rock or stone\"</p><ol><li>Peter was one of the apostles</li><li>Simon called Zelotes or the Kanaites</li><li>Simon, father of Judas who betrayed Jesus.</li><li>Simon Magus, the Samaritan wizard</li><li>Simon the tanner, Ac. 10</li><li>Simon the Pharisee, <a class='bible' href='#b42.7.40-44'>Luk 7:40-44</a></li><li>Simon of Cyrene who carried the cross of Christ</li><li>Simon the cousin of Jesus, the son of Cleophas</li><li>Simon the leper, so called to distinguish him from others of the same name</li></ol>","xlit":"Símōn"},"G1102":{"derivation":"by variation for a derivative from (to tease cloth);","strongs_def":" a cloth-dresser","kjv_def":"fuller","lemma":"γναφεύς","translit":"gnapheús","pron":"gnaf-yuce'","pos":"Noun Masculine","thayer":"<ol><li>a fuller</li></ol>","xlit":"gnapheús"},"G1064":{"kjv_def":"belly, + with child, womb","lemma":"γαστήρ","translit":"gastḗr","derivation":"of uncertain derivation;","strongs_def":" the stomach; by analogy, the matrix; figuratively, a gourmand","pron":"gas-tare'","pos":"Noun Feminine","thayer":"<ol><li>the belly</li><li>the womb</li><li>the stomach<ol type='a'><li>a glutton, gormandiser, a man who is as it were all stomach</li></ol></li></ol>","xlit":"gastḗr"},"G4316":{"kjv_def":"call","translit":"prosagoreúō","lemma":"προσαγορεύω","derivation":"from G4314 (πρός) and a derivative of G58 (ἀγορά) (mean to harangue);","strongs_def":" to address, i.e. salute by name","pron":"pros-ag-or-yoo'-o","pos":"Verb","thayer":"<ol><li>to speak to, to address, accost, salute</li><li>especially to address or accost by some name, call by name</li><li>to give a name in public, to style</li></ol>","xlit":"prosagoreúō"},"G1667":{"derivation":"a form of G1507 (εἱλίσσω);","strongs_def":" to coil or wrap","kjv_def":"fold up","lemma":"ἑλίσσω","translit":"helíssō","pron":"hel-is'-so","pos":"Verb","thayer":"<ol><li>to roll up, fold together</li></ol>","xlit":"helíssō"},"G682":{"derivation":"probably of foreign origin;","strongs_def":" Apphia, a woman of Collosæ","kjv_def":"Apphia","lemma":"Ἀπφία","translit":"Apphía","pron":"ap-fee'-a","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Apphia = \"fruitful\"</p><ol><li>a Christian member of Philemon's household</li></ol>","xlit":"Apphía"},"G5367":{"kjv_def":"lover of own self","lemma":"φίλαυτος","translit":"phílautos","derivation":"from G5384 (φίλος) and G846 (αὐτός);","strongs_def":" fond of self, i.e. selfish","pron":"fil'-ow-tos","pos":"Adjective","thayer":"<ol><li>loving one's self</li><li>too intent on one's interest, selfish</li></ol>","xlit":"phílautos"},"G5448":{"strongs_def":" to inflate, i.e. (figuratively) make proud (haughty)","derivation":"from G5449 (φύσις) in the primary sense of blowing;","lemma":"φυσιόω","translit":"physióō","kjv_def":"puff up","pron":"foo-see-o'-o","pos":"Verb","thayer":"<ol><li>to make natural, to cause a thing to pass into nature</li><li>to inflate, blow up, to cause to swell up<ol type='a'><li>to puff up, make proud</li><li>to be puffed up, to bear one's self loftily, be proud</li></ol></li></ol>","xlit":"physióō"},"G1000":{"strongs_def":" a throw (as a measure of distance)","derivation":"from G906 (βάλλω);","lemma":"βολή","translit":"bolḗ","kjv_def":"cast","pron":"bol-ay'","pos":"Noun Feminine","thayer":"<ol><li>a throw</li></ol>","xlit":"bolḗ"},"G325":{"kjv_def":"deliver","translit":"anadídōmi","lemma":"ἀναδίδωμι","derivation":"from G303 (ἀνά) and G1325 (δίδωμι);","strongs_def":" to hand over","pron":"an-ad-eed'-om-ee","pos":"Verb","thayer":"<ol><li>to give forth, send up, so the earth producing plants, yielding fruit etc.</li><li>to deliver up, hand over</li></ol>","xlit":"anadídōmi"},"G2313":{"strongs_def":" to resist deity","derivation":"from G2314 (θεομάχος);","lemma":"θεομαχέω","translit":"theomachéō","kjv_def":"fight against God","pron":"theh-o-makh-eh'-o","pos":"Verb","thayer":"<ol><li>to fight against God</li></ol>","xlit":"theomachéō"},"G2221":{"kjv_def":"take captive, catch","lemma":"ζωγρέω","translit":"zōgréō","derivation":"from the same as G2226 (ζῶον) and G64 (ἀγρεύω);","strongs_def":" to take alive (make a prisoner of war), i.e. (figuratively) to capture or ensnare","pron":"dzogue-reh'-o","pos":"Verb","thayer":"<ol><li>to take alive</li><li>to take, catch, capture</li></ol>","xlit":"zōgréō"},"G5223":{"kjv_def":"goods, substance","lemma":"ὕπαρξις","translit":"hýparxis","derivation":"from G5225 (ὑπάρχω);","strongs_def":" existency or proprietorship, i.e. (concretely) property, wealth","pron":"hoop'-arx-is","pos":"Noun Feminine","thayer":"<ol><li>possessions, goods, wealth, property</li></ol>","xlit":"hýparxis"},"G1990":{"kjv_def":"endued with knowledge","translit":"epistḗmōn","lemma":"ἐπιστήμων","derivation":"from G1987 (ἐπίσταμαι);","strongs_def":" intelligent","pron":"ep-ee-stay'-mone","pos":"Adjective","thayer":"<ol><li>intelligent, experienced, one having the knowledge of an expert</li></ol>","xlit":"epistḗmōn"},"G4554":{"strongs_def":" Sardis, a place in Asia Minor","derivation":"plural of uncertain derivation;","lemma":"Σάρδεις","translit":"Sárdeis","kjv_def":"Sardis","pron":"sar'-dice","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Sardis = \"red ones\"</p><ol><li>a luxurious city in Asia Minor, the capital of Lydia</li></ol>","xlit":"Sárdeis"},"G1412":{"kjv_def":"strengthen","lemma":"δυναμόω","translit":"dynamóō","derivation":"from G1411 (δύναμις);","strongs_def":" to enable","pron":"doo-nam-o'-o","pos":"Verb","thayer":"<ol><li>to make strong, confirm, strengthen</li></ol>","xlit":"dynamóō"},"G1530":{"strongs_def":" to rush in","derivation":"from G1519 (εἰς) and (to leap);","translit":"eispēdáō","lemma":"εἰσπηδάω","kjv_def":"run (spring) in","pron":"ice-pay-dah'-o","pos":"Verb","thayer":"<ol><li>to spring in, to rush in impetuously</li></ol>","xlit":"eispēdáō"},"G743":{"translit":"archángelos","lemma":"ἀρχάγγελος","kjv_def":"archangel","strongs_def":" a chief angel","derivation":"from G757 (ἄρχω) and G32 (ἄγγελος);","pron":"ar-khang'-el-os","pos":"Noun Masculine","thayer":"<ol><li>archangel, or chief of the angels</li></ol>","xlit":"archángelos"},"G2442":{"kjv_def":"be affectionately desirous","translit":"himeíromai","lemma":"ἱμείρομαι","derivation":"middle voice from (a yearning;","strongs_def":" of uncertain affinity); to long for","pron":"him-i'-rom-ahee","pos":"Verb","thayer":"<ol><li>to desire, long for, especially the longing of love</li></ol>","xlit":"himeíromai"},"G5537":{"translit":"chrēmatízō","lemma":"χρηματίζω","kjv_def":"be called, be admonished (warned) of God, reveal, speak","strongs_def":" to utter an oracle (compare the original sense of G5530 (χράομαι)), i.e. divinely intimate; by implication, (compare the secular sense of G5532 (χρεία)) to constitute a firm for business, i.e. (generally) bear as a title","derivation":"from G5536 (χρῆμα);","pron":"khray-mat-id'-zo","pos":"Verb","thayer":"<ol><li>to transact business, especially to manage public affairs<ol type='a'><li>to advise or consult with one about public affairs</li><li>to make answer to those who ask for advice, present enquiries or requests, etc.<ol><li>of judges, magistrates, rulers, kings</li></ol></li></ol><li>to give a response to those consulting an oracle, to give a divine command or admonition, to teach from heaven<ol type='a'><li>to be divinely commanded, admonished, instructed</li><li>to be the mouthpiece of divine revelations, to promulgate the commands of God</li></ol><li>to assume or take to one's self a name from one's public business<ol type='a'><li>to receive a name or title, be called</li></ol></li></ol>","xlit":"chrēmatízō"},"G1803":{"translit":"héx","lemma":"ἕξ","kjv_def":"six","strongs_def":" six","derivation":"a primary numeral;","pron":"hex","pos":"Noun","thayer":"<ol><li>six</li></ol>","xlit":"héx"},"G3769":{"kjv_def":"tail","lemma":"οὐρά","translit":"ourá","derivation":"apparently a primary word;","strongs_def":" a tail","pron":"oo-rah'","pos":"Noun Feminine","thayer":"<ol><li>a tail</li></ol>","xlit":"ourá"},"G2511":{"kjv_def":"(make) clean(-se), purge, purify","translit":"katharízō","lemma":"καθαρίζω","derivation":"from G2513 (καθαρός);","strongs_def":" to cleanse (literally or figuratively)","pron":"kath-ar-id'-zo","pos":"Verb","thayer":"<ol><li>to make clean, cleanse<ol type='a'><li>from physical stains and dirt<ol><li>utensils, food</li><li>a leper, to cleanse by curing</li><li>to remove by cleansing</li></ol><li>in a moral sense<ol><li>to free from defilement of sin and from faults</li><li>to purify from wickedness</li><li>to free from guilt of sin, to purify</li><li>to consecrate by cleansing or purifying</li><li>to consecrate, dedicate</li></ol></li></ol><li>to pronounce clean in a levitical sense</li></ol>","xlit":"katharízō"},"G1562":{"kjv_def":"strip, take off from, unclothe","translit":"ekdýō","lemma":"ἐκδύω","derivation":"from G1537 (ἐκ) and the base of G1416 (δύνω);","strongs_def":" to cause to sink out of, i.e. (specially as of clothing) to divest","pron":"ek-doo'-o","pos":"Verb","thayer":"<ol><li>to take off<ol type='a'><li>to strip one of his garments</li></ol><li>to take off from one's self, to put off the one's raiments</li><li>fig., to put off the body, the clothing of the soul</li></ol>","xlit":"ekdýō"},"G2240":{"kjv_def":"come","translit":"hḗkō","lemma":"ἥκω","derivation":"a primary verb;","strongs_def":" to arrive, i.e. be present (literally or figuratively)","pron":"hay'-ko","pos":"Verb","thayer":"<ol><li>to have come, have arrived, be present</li><li>metaphorically<ol type='a'><li>to come to one, i.e. to seek an intimacy with one, become his follower: to come upon one (unexpectedly)</li><li>to come upon one, of things endured</li></ol></li></ol>","xlit":"hḗkō"},"G520":{"derivation":"from G575 (ἀπό) and G71 (ἄγω);","strongs_def":" to take off (in various senses)","kjv_def":"bring, carry away, lead (away), put to death, take away","translit":"apágō","lemma":"ἀπάγω","pron":"ap-ag'-o","pos":"Verb","thayer":"<ol><li>to lead away<ol type='a'><li>especially of those who are led off to trial, prison, or punishment</li></ol></li></ol>","xlit":"apágō"},"G428":{"strongs_def":" not well set, i.e. inconvenient","derivation":"from G1 (Α) (as a negative particle) and G2111 (εὔθετος);","lemma":"ἀνεύθετος","translit":"aneúthetos","kjv_def":"not commodious","pron":"an-yoo'-the-tos","pos":"Adjective","thayer":"<ol><li>not convenient, not commodious, not fit</li></ol>","xlit":"aneúthetos"},"G4608":{"strongs_def":" an intoxicant, i.e. intensely fermented liquor","derivation":"of Hebrew origin (H07941);","translit":"síkera","lemma":"σίκερα","kjv_def":"strong drink","pron":"sik'-er-ah","pos":"Noun Neuter","thayer":"<ol><li>strong drink, an intoxicating beverage, different from wine; it was a artificial product, made of a mixture of sweet ingredients, whether derived from grain and vegetables, or from the juice of fruits (dates), or a decoction of honey</li></ol>","xlit":"síkera"},"G2818":{"kjv_def":"heir","translit":"klēronómos","lemma":"κληρονόμος","derivation":"from G2819 (κλῆρος) and the base of G3551 (νόμος) (in its original sense of partitioning, i.e. (reflexively) getting by apportionment);","strongs_def":" a sharer by lot, i.e. inheritor (literally or figuratively); by implication, a possessor","pron":"klay-ron-om'-os","pos":"Noun Masculine","thayer":"<ol><li>one who receives by lot, an heir<ol type='a'><li>an heir</li><li>in Messianic usage, one who receives his allotted possession by right of sonship</li></ol><li>one who has acquired or obtained the portion allotted to him</li></ol>","xlit":"klēronómos"},"G2905":{"derivation":"from G2906 (κραυγή);","strongs_def":" to clamor","kjv_def":"cry out","translit":"kraugázō","lemma":"κραυγάζω","pron":"krow-gad'-zo","pos":"Verb","thayer":"<ol><li>to cry out, cry aloud, to shout, to cry out to one</li></ol>","xlit":"kraugázō"},"G4327":{"kjv_def":"accept, allow, look (wait) for, take","lemma":"προσδέχομαι","translit":"prosdéchomai","derivation":"from G4314 (πρός) and G1209 (δέχομαι);","strongs_def":" to admit (to intercourse, hospitality, credence, or (figuratively) endurance); by implication, to await (with confidence or patience)","pron":"pros-dekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to receive to one's self, to admit, to give access to one's self<ol type='a'><li>to admit one, receive one into intercourse and companionship</li><li>to receive one (coming from some place)</li><li>to accept (not to reject) a thing offered</li></ol><li>to expect: the fulfilment of promises</li></ol>","xlit":"prosdéchomai"},"G2174":{"derivation":"from a compound of G2095 (εὖ) and G5590 (ψυχή);","strongs_def":" to be in good spirits, i.e. feel encouraged","kjv_def":"be of good comfort","lemma":"εὐψυχέω","translit":"eupsychéō","pron":"yoo-psoo-kheh'-o","pos":"Verb","thayer":"<ol><li>to be of good courage, to be of a cheerful spirit</li></ol>","xlit":"eupsychéō"},"G3632":{"strongs_def":" an overflow (or surplus) of wine, i.e. vinolency (drunkenness)","derivation":"from G3631 (οἶνος) and a form of the base of G5397 (φλύαρος);","translit":"oinophlygía","lemma":"οἰνοφλυγία","kjv_def":"excess of wine","pron":"oy-nof-loog-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>drunkenness</li></ol>","xlit":"oinophlygía"},"G4015":{"strongs_def":" to flash all around, i.e. envelop in light","derivation":"from G4012 (περί) and G797 (ἀστράπτω);","translit":"periastráptō","lemma":"περιαστράπτω","kjv_def":"shine round (about)","pron":"per-ee-as-trap'-to","pos":"Verb","thayer":"<ol><li>to flash around, shine about</li></ol>","xlit":"periastráptō"},"G2392":{"kjv_def":"cure, heal(-ing)","translit":"íasis","lemma":"ἴασις","derivation":"from G2390 (ἰάομαι);","strongs_def":" curing (the act)","pron":"ee'-as-is","pos":"Noun Feminine","thayer":"<ol><li>a healing, cure</li></ol>","xlit":"íasis"},"G2490":{"derivation":"a form of G2491 (Ἰωάννης);","strongs_def":" Joannas, an Israelite","kjv_def":"Joannas","translit":"Iōannâs","lemma":"Ἰωαννᾶς","pron":"ee-o-an-nas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Joanna = \"grace or gift of God\"</p><ol><li>one of the ancestors of Christ</li></ol>","xlit":"Iōannâs"},"G4351":{"kjv_def":"roll (to)","translit":"proskylíō","lemma":"προσκυλίω","derivation":"from G4314 (πρός) and G2947 (κυλιόω);","strongs_def":" to roll towards, i.e. block against","pron":"pros-koo-lee'-o","pos":"Verb","thayer":"<ol><li>to roll to</li></ol>","xlit":"proskylíō"},"G2552":{"translit":"kakopátheia","lemma":"κακοπάθεια","kjv_def":"suffering affliction","strongs_def":" hardship","derivation":"from a compound of G2256 (ἡμιώριον) and G3806 (πάθος);","pron":"kak-op-ath'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>the suffering of evil, i.e. trouble, distress, afflicted</li></ol>","xlit":"kakopátheia"},"G4623":{"strongs_def":" properly, muteness, i.e. involuntary stillness, or inability to speak; and thus differing from G4602 (σιγή), which is rather a voluntary refusal or indisposition to speak, although the terms are often used synonymously); to be dumb (but not deaf also, like 2974 properly); figuratively, to be calm (as quiet water)","derivation":"from (silence, i.e. a hush;","lemma":"σιωπάω","translit":"siōpáō","kjv_def":"dumb, (hold) peace","pron":"see-o-pah'-o","pos":"Verb","thayer":"<ol><li>to be silent, hold one's peace<ol type='a'><li>used of one's silence because dumb</li></ol><li>metaphorically of a calm, quiet sea</li></ol>","xlit":"siōpáō"},"G4985":{"strongs_def":" corporeally or physically","derivation":"adverb from G4984 (σωματικός);","lemma":"σωματικῶς","translit":"sōmatikōs","kjv_def":"bodily","pron":"so-mat-ee-koce'","pos":"Adverb","thayer":"<ol><li>bodily, corporally<ol type='a'><li>of the exalted spiritual body, visible only to the inhabitants of heaven</li></ol></li></ol>","xlit":"sōmatikōs"},"G5597":{"derivation":"prolongation from the same base as G5567 (ψάλλω);","strongs_def":" to triturate, i.e. (by analogy) to rub out (kernels from husks with the fingers or hand)","kjv_def":"rub","translit":"psṓchō","lemma":"ψώχω","pron":"pso'-kho","pos":"Verb","thayer":"<ol><li>to rub, to rub to pieces</li></ol>","xlit":"psṓchō"},"G997":{"derivation":"from G998 (βοηθός);","strongs_def":" to aid or relieve","kjv_def":"help, succor","lemma":"βοηθέω","translit":"boēthéō","pron":"bo-ay-theh'-o","pos":"Verb","thayer":"<ol><li>to help, succour, bring aid</li></ol>","xlit":"boēthéō"},"G5165":{"kjv_def":"dish","translit":"trýblion","lemma":"τρύβλιον","derivation":"neuter of a presumed derivative of uncertain affinity;","strongs_def":" a bowl","pron":"troob'-lee-on","pos":"Noun Neuter","thayer":"<ol><li>a dish, a deep dish</li></ol>","xlit":"trýblion"},"G557":{"kjv_def":"nought","lemma":"ἀπελεγμός","translit":"apelegmós","derivation":"from a compound of G575 (ἀπό) and G1651 (ἐλέγχω);","strongs_def":" refutation, i.e. (by implication) contempt","pron":"ap-el-eg-mos'","pos":"Noun Masculine","thayer":"<ol><li>censure, repudiation of a thing shown to be worthless</li></ol>","xlit":"apelegmós"},"G4793":{"strongs_def":" to judge of one thing in connection with another, i.e. combine (spiritual ideas with appropriate expressions) or collate (one person with another by way of contrast or resemblance)","derivation":"from G4862 (σύν) and G2919 (κρίνω);","lemma":"συγκρίνω","translit":"synkrínō","kjv_def":"compare among (with)","pron":"soong-kree'-no","pos":"Verb","thayer":"<ol><li>to joint together fitly, compound, combine</li><li>to interpret</li><li>to compare</li></ol>","xlit":"synkrínō"},"G3103":{"strongs_def":" Mathusala (i.e. Methushelach), an antediluvian","derivation":"of Hebrew origin (H04968);","lemma":"Μαθουσάλα","translit":"Mathousála","kjv_def":"Mathusala","pron":"math-oo-sal'-ah","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Methuselah = \"when he dies, there shall be an emission\"</p><ol><li>the son of Enoch, grandfather of Noah, lived longer than anyone else to 969 years</li></ol>","xlit":"Mathousála"},"G3451":{"strongs_def":" \"musical\", i.e. (as noun) a minstrel","derivation":"from (a Muse);","lemma":"μουσικός","translit":"mousikós","kjv_def":"musician","pron":"moo-sik-os'","thayer":"<ol><li>devoted to and skilled in the arts sacred to the muses</li><li>accomplished in the liberal arts</li><li>specifically, skilled in music</li><li>playing on musical instruments</li></ol>","xlit":"mousikós"},"G2359":{"strongs_def":" of uncertain derivation; hair","derivation":"genitive case , etc.;","translit":"thríx","lemma":"θρίξ","kjv_def":"hair","pron":"threeks","pos":"Noun Feminine","thayer":"<ol><li>the hair of the head</li><li>the hair of animals</li></ol>","xlit":"thríx"},"G4103":{"strongs_def":" objectively, trustworthy; subjectively, trustful","derivation":"from G3982 (πείθω);","translit":"pistós","lemma":"πιστός","kjv_def":"believe(-ing, -r), faithful(-ly), sure, true","pron":"pis-tos'","pos":"Adjective","thayer":"<ol><li>trusty, faithful<ol type='a'><li>of persons who show themselves faithful in the transaction of business, the execution of commands, or the discharge of official duties</li><li>one who kept his plighted faith, worthy of trust</li><li>that can be relied on</li></ol><li>easily persuaded<ol type='a'><li>believing, confiding, trusting</li><li>in the NT one who trusts in God's promises<ol><li>one who is convinced that Jesus has been raised from the dead</li><li>one who has become convinced that Jesus is the Messiah and author of salvation</li></ol></li></ol></li></ol>","xlit":"pistós"},"G2326":{"kjv_def":"harvest","lemma":"θερισμός","translit":"therismós","derivation":"from G2325 (θερίζω);","strongs_def":" reaping, i.e. the crop","pron":"ther-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>harvest, the act of reaping<ol type='a'><li>fig. of the gathering of men into the kingdom of God</li><li>referring to time of reaping, the final judgment, when the righteous are gathered into the kingdom of God and the wicked are cast into hell for ever</li></ol></li></ol>","xlit":"therismós"},"G3156":{"derivation":"a shorter form of G3164 (μάχομαι);","strongs_def":" Matthæus (i.e. Matthitjah), an Israelite and a Christian","kjv_def":"Matthew","lemma":"Ματθαῖος","translit":"Matthaîos","pron":"mat-thah'-yos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Matthew = \"gift of Jehovah\"</p><ol><li>son of Alphaeus, one of the 12 disciples</li></ol>","xlit":"Matthaîos"},"G887":{"strongs_def":" dimness of sight, i.e. (probably) a cataract","derivation":"of uncertain derivation;","translit":"achlýs","lemma":"ἀχλύς","kjv_def":"mist","pron":"akh-looce'","pos":"Noun Feminine","thayer":"<ol><li>mist, dimness</li></ol>","xlit":"achlýs"},"G1965":{"derivation":"from G1909 (ἐπί) and G3727 (ὅρκος);","strongs_def":" on oath, i.e. (falsely) a forswearer","kjv_def":"perjured person","lemma":"ἐπίορκος","translit":"epíorkos","pron":"ep-ee'-or-kos","pos":"Adjective","thayer":"<ol><li>a false swearer, a perjurer</li></ol>","xlit":"epíorkos"},"G5160":{"derivation":"from G5142 (τρέφω);","strongs_def":" nourishment (literally or figuratively); by implication, rations (wages)","kjv_def":"food, meat","lemma":"τροφή","translit":"trophḗ","pron":"trof-ay'","pos":"Noun Feminine","thayer":"<ol><li>food, nourishment</li></ol>","xlit":"trophḗ"},"G4935":{"translit":"syntómōs","lemma":"συντόμως","kjv_def":"a few words","strongs_def":" concisely (briefly)","derivation":"adverb from a derivative of G4932 (συντέμνω);","pron":"soon-tom'-oce","pos":"Adverb","thayer":"<ol><li>concisely, briefly, in a few words</li></ol>","xlit":"syntómōs"},"G4130":{"lemma":"πλήθω","translit":"plḗthō","kjv_def":"accomplish, full (…come), furnish","strongs_def":" to \"fill\" (literally or figuratively (imbue, influence, supply)); specially, to fulfil (time)","derivation":"a prolonged form of a primary (which appears only as an alternate in certain tenses and in the reduplicated form pimplemi);","pron":"play'-tho","pos":"Verb","thayer":"<ol><li>to fill</li><li>to be fulfilled, to be filled</li></ol>","xlit":"plḗthō"},"G542":{"lemma":"ἀπείδω","translit":"apeídō","kjv_def":"see","strongs_def":" to see fully","derivation":"from G575 (ἀπό) and the same as G1492 (εἴδω);","pron":"ap-i'-do","pos":"Verb","thayer":"<ol><li>to look away from one thing and at another</li><li>to look at from somewhere, either from a distance or from a certain present condition of things</li><li>to perceive</li></ol>","xlit":"apeídō"},"G99":{"derivation":"from (a place near its shore);","strongs_def":" the Adriatic sea (including the Ionian)","kjv_def":"Adria","lemma":"Ἀδρίας","translit":"Adrías","pron":"ad-ree'-as","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Adriatic = \"without wood\"</p><ol><li>Adriatic Sea, Adrias, the sea between Greece and Italy</li></ol>","xlit":"Adrías"},"G5373":{"kjv_def":"friendship","translit":"philía","lemma":"φιλία","derivation":"from G5384 (φίλος);","strongs_def":" fondness","pron":"fil-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>friendship</li></ol>","xlit":"philía"},"G4299":{"translit":"prókrima","lemma":"πρόκριμα","kjv_def":"prefer one before another","strongs_def":" a prejudgment (prejudice), i.e. prepossession","derivation":"from a compound of G4253 (πρό) and G2919 (κρίνω);","pron":"prok'-ree-mah","pos":"Noun Neuter","thayer":"<ol><li>an opinion formed before the facts are known</li><li>a prejudgment, a prejudice</li></ol>","xlit":"prókrima"},"G2841":{"strongs_def":" to share with others (objectively or subjectively)","derivation":"from G2844 (κοινωνός);","translit":"koinōnéō","lemma":"κοινωνέω","kjv_def":"communicate, distribute, be partaker","pron":"koy-no-neh'-o","pos":"Verb","thayer":"<ol><li>to come into communion or fellowship with, to become a sharer, be made a partner</li><li>to enter into fellowship, join one's self to an associate, make one's self a sharer or partner</li></ol>","xlit":"koinōnéō"},"G1042":{"lemma":"γαββαθά","translit":"gabbathá","kjv_def":" Gabbatha","strongs_def":" the knoll; gabbatha, a vernacular term for the Roman tribunal in Jerusalem","derivation":"of Chaldee origin (compare H01355);","pron":"gab-bath-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gabbatha = \"elevated or a platform\"</p><ol><li>a raised place, elevation. In the Greek was called Lithostrotos, or the pavement of stones, as the Syrian version renders it: it is thought to be the room Gazith, in which the Sanhedrin sat in the temple when they tried capital causes; and it was so called, because it was paved with smooth, square hewn stones: \"it was in the north part; half of it was holy, and half of it was common: and it had two doors, one for that part which was holy, and another for that part that was common; and in that half that was common the sanhedrin sat.\" So that into this part of it, and by this door, Pilate, though a Gentile, might enter. This place, in the language of the Jews, who at that time spoke Syrian, was Gabbatha, from its height, as it should seem; though the Syrian and Persian versions read Gaphiphtha, which signifies a fence or enclosure. Mention is made in the Talmud of the upper Gab in the mountain of the house; but whether the same with this Gabbatha, and whether this is the same with the chamber Gazith, is not certain. The Septuagint uses the same word as John here does, and calls by the same name the pavement of the temple on which Israelites fell and worshipped God. (<a class='bible' href='#b14.7.3'>2Ch 7:3</a>) (Gill) The Hebrew word for Pavement occurs only once in the Old Testament. In <a class='bible' href='#b12.16.17'>2Ki 16:17</a> we read, \"King Ahaz cut off the borders of the bases, and removed the laver from off them; and took down the sea from off the brazen oxen that were under it, and put it upon the pavement of stones.\" In Ahaz's case his act was the conclusive token of his abject apostasy. So here of Pilate coming down to the apostate Jews. In the former case it was a Jewish ruler dominated by a Gentile idolater; in the latter, a Gentile idolater dominated by Jews who had rejected the Messiah! (AWP <a class='bible' href='#b43.19.13'>Joh 19:13</a>)</li></ol>","xlit":"gabbathá"},"G3797":{"derivation":"from G3796 (ὀψέ);","strongs_def":" later, i.e. vernal (showering)","kjv_def":"latter","lemma":"ὄψιμος","translit":"ópsimos","pron":"op'-sim-os","pos":"Adjective","thayer":"<ol><li>late, later<ol type='a'><li>of the time of subsidence of the waters of the Nile</li><li>the latter or vernal rain, which falls chiefly in the months of March and April just before the harvest</li></ol></li></ol>","xlit":"ópsimos"},"G3725":{"derivation":"neuter of a derivative of an apparently primary (a bound or limit);","strongs_def":" a boundary-line, i.e. (by implication) a frontier (region)","kjv_def":"border, coast","lemma":"ὅριον","translit":"hórion","pron":"hor'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>boundaries<ol type='a'><li>for a region, district, land, territory</li></ol></li></ol>","xlit":"hórion"},"G1069":{"strongs_def":" a neighbour (as adjoining one's ground); by implication, a friend","derivation":"from G1093 (γῆ);","lemma":"γείτων","translit":"geítōn","kjv_def":"neighbour","pron":"ghi'-tone","pos":"Noun","thayer":"<ol><li>a neighbour</li></ol>","xlit":"geítōn"},"G125":{"kjv_def":"Egypt","lemma":"Αἴγυπτος","translit":"Aígyptos","derivation":"of uncertain derivation;","strongs_def":" Ægyptus, the land of the Nile","pron":"ah'-ee-goop-tos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Egypt = \"double straits\"</p><ol><li>a country occupying the northeast angle of Africa</li><li>metaphorically Jerusalem, for the Jews persecuting the Christ and his followers, and so to be likened to the Egyptians treating the Jews</li></ol>","xlit":"Aígyptos"},"G4312":{"kjv_def":"heady, rash(-ly)","lemma":"προπετής","translit":"propetḗs","derivation":"from a compound of G4253 (πρό) and G4098 (πίπτω);","strongs_def":" falling forward, i.e. headlong (figuratively, precipitate)","pron":"prop-et-ace'","pos":"Adjective","thayer":"<ol><li>to fall forwards, headlong, sloping, precipitously</li><li>precipitate, rash, reckless</li></ol>","xlit":"propetḗs"},"G5158":{"kjv_def":"(even) as, conversation, (+ like) manner, (+ by any) means, way","translit":"trópos","lemma":"τρόπος","derivation":"from the same as G5157 (τροπή);","strongs_def":" a turn, i.e. (by implication) mode or style (especially with preposition or relative prefix as adverb, like); figuratively, deportment or character","pron":"trop'-os","pos":"Noun Masculine","thayer":"<ol><li>a manner, way, fashion<ol type='a'><li>as, even as, like as</li></ol><li>manner of life, character, deportment</li></ol>","xlit":"trópos"},"G1624":{"derivation":"from G1537 (ἐκ) and the base of G5157 (τροπή);","strongs_def":" to deflect, i.e. turn away (literally or figuratively)","kjv_def":"avoid, turn (aside, out of the way)","translit":"ektrépō","lemma":"ἐκτρέπω","pron":"ek-trep'-o","pos":"Verb","thayer":"<ol><li>to turn or twist out<ol type='a'><li>in a medical sense used of dislocated limbs</li></ol><li>to turn off or aside</li><li>to be turned aside</li><li>to turn aside</li><li>to turn away from, to shun a thing, to avoid meeting or associating with one</li></ol>","xlit":"ektrépō"},"G3541":{"derivation":"of uncertain affinity;","strongs_def":" a spurious or illegitimate son","kjv_def":"bastard","lemma":"νόθος","translit":"nóthos","pron":"noth'-os","pos":"Adjective","thayer":"<ol><li>illegitimate, bastard</li><li>one born, not in lawful wedlock, but of a concubine or female slave</li></ol>","xlit":"nóthos"},"G838":{"derivation":"from G837 (αὐξάνω);","strongs_def":" growth","kjv_def":"increase","translit":"aúxēsis","lemma":"αὔξησις","pron":"owx'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>increase, growth</li></ol>","xlit":"aúxēsis"},"G3873":{"translit":"parákeimai","lemma":"παράκειμαι","kjv_def":"be present","strongs_def":" to lie near, i.e. be at hand (figuratively, be prompt or easy)","derivation":"from G3844 (παρά) and G2749 (κεῖμαι);","pron":"par-ak'-i-mahee","pos":"Verb","thayer":"<ol><li>to lie beside, to be near</li><li>to be present, at hand</li></ol>","xlit":"parákeimai"},"G2373":{"derivation":"from G2372 (θυμός);","strongs_def":" to put in a passion, i.e. enrage","kjv_def":"be wroth","translit":"thymóō","lemma":"θυμόω","pron":"tho-mo'-o","pos":"Verb","thayer":"<ol><li>to cause one to become incensed, to provoke to anger</li><li>to be wroth</li></ol>","xlit":"thymóō"},"G4186":{"kjv_def":"very costly, of great price","lemma":"πολύτιμος","translit":"polýtimos","derivation":"from G4183 (πολύς) and G5092 (τιμή);","strongs_def":" extremely valuable","pron":"pol-oot'-ee-mos","pos":"Adjective","thayer":"<ol><li>very valuable, of great price</li></ol>","xlit":"polýtimos"},"G1783":{"derivation":"from G1793 (ἐντυγχάνω);","strongs_def":" an interview, i.e. (specially) supplication","kjv_def":"intercession, prayer","translit":"énteuxis","lemma":"ἔντευξις","pron":"ent'-yook-sis","pos":"Noun Feminine","thayer":"<ol><li>a falling in with, meeting with<ol type='a'><li>an interview<ol><li>a coming together</li><li>to visit</li><li>converse or for any other cause</li></ol><li>that for which an interview is held<ol><li>a conference or conversation</li><li>a petition, supplication</li></ol></li></ol></li></ol>","xlit":"énteuxis"},"G3183":{"strongs_def":" tipsy, i.e. (as noun) a sot","derivation":"from G3184 (μεθύω);","translit":"méthysos","lemma":"μέθυσος","kjv_def":"drunkard","pron":"meth'-oo-sos","pos":"Noun Masculine","thayer":"<ol><li>drunken, intoxicated</li></ol>","xlit":"méthysos"},"G1141":{"derivation":"from G1140 (δαιμόνιον) and G1142 (δαίμων);","strongs_def":" dæmon-like","kjv_def":"devilish","lemma":"δαιμονιώδης","translit":"daimoniṓdēs","pron":"dahee-mon-ee-o'-dace","pos":"Adjective","thayer":"<ol><li>resembling or proceeding from an evil spirit, demon-like</li></ol>","xlit":"daimoniṓdēs"},"G846":{"derivation":"from the particle (perhaps akin to the base of G109 (ἀήρ) through the idea of a baffling wind) (backward);","strongs_def":" the reflexive pronoun self, used (alone or in the comparative G1438 (ἑαυτοῦ)) of the third person , and (with the proper personal pronoun) of the other persons","kjv_def":"her, it(-self), one, the other, (mine) own, said, (self-), the) same, ((him-, my-, thy- )self, (your-)selves, she, that, their(-s), them(-selves), there(-at, - by, -in, -into, -of, -on, -with), they, (these) things, this (man), those, together, very, which","lemma":"αὐτός","translit":"autós","pron":"ow-tos'","thayer":"<ol><li>himself, herself, themselves, itself</li><li>he, she, it</li><li>the same</li></ol>","xlit":"autós"},"G1291":{"translit":"diastéllomai","lemma":"διαστέλλομαι","kjv_def":"charge, that which was (give) commanded(-ment)","strongs_def":" to set (oneself) apart (figuratively, distinguish), i.e. (by implication) to enjoin","derivation":"middle voice from G1223 (διά) and G4724 (στέλλω);","pron":"dee-as-tel'-lom-ahee","pos":"Verb","thayer":"<ol><li>to draw asunder, divide, distinguish, dispose, order</li><li>to open one's self, i.e. one's mind, to set forth distinctly</li><li>to admonish, order, charge</li></ol>","xlit":"diastéllomai"},"G798":{"derivation":"neuter from G792 (ἀστήρ);","strongs_def":" properly, a constellation; put for a single star (natural or artificial)","kjv_def":"star","lemma":"ἄστρον","translit":"ástron","pron":"as'-tron","pos":"Noun Neuter","thayer":"<ol><li>a group of stars, a constellation</li><li>a star</li></ol>","xlit":"ástron"},"G5422":{"strongs_def":" to be a mind-misleader, i.e. delude","derivation":"from G5423 (φρεναπάτης);","lemma":"φρεναπατάω","translit":"phrenapatáō","kjv_def":"deceive","pron":"fren-ap-at-ah'-o","pos":"Verb","thayer":"<ol><li>to deceive any one's mind</li></ol>","xlit":"phrenapatáō"},"G5469":{"kjv_def":"bit, bridle","translit":"chalinós","lemma":"χαλινός","derivation":"from G5465 (χαλάω);","strongs_def":" a curb or head-stall (as curbing the spirit)","pron":"khal-ee-nos'","pos":"Noun Masculine","thayer":"<ol><li>a bridle</li></ol>","xlit":"chalinós"},"G317":{"lemma":"ἀναγκαστῶς","translit":"anankastōs","kjv_def":"by constraint","strongs_def":" compulsorily","derivation":"adverb from a derivative of G315 (ἀναγκάζω);","pron":"an-ang-kas-toce'","pos":"Adverb","thayer":"<ol><li>by force or constrain</li></ol>","xlit":"anankastōs"},"G3015":{"strongs_def":" scaly, i.e. leprous (a leper)","derivation":"from the same as G3014 (λέπρα);","translit":"leprós","lemma":"λεπρός","kjv_def":"leper","pron":"lep-ros'","pos":"Adjective","thayer":"<ol><li>scaly, rough</li><li>leprous, affected with leprosy</li></ol>","xlit":"leprós"},"G3192":{"translit":"méli","lemma":"μέλι","kjv_def":"honey","strongs_def":" honey","derivation":"apparently a primary word;","pron":"mel'-ee","pos":"Noun Neuter","thayer":"<ol><li>honey</li></ol>","xlit":"méli"},"G295":{"derivation":"from the base of G297 (ἀμφότερος) and G4172 (πόλις);","strongs_def":" a city surrounded by a river; Amphipolis, a place in Macedonia","kjv_def":"Amphipolis","translit":"Amphípolis","lemma":"Ἀμφίπολις","pron":"am-fip'-ol-is","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Amphipolis = \"a city surrounded by the sea\"</p><ol><li>a city in Macedonia Prima, so called because the Strymon flowed around it</li></ol>","xlit":"Amphípolis"},"G3081":{"translit":"lysiteleî","lemma":"λυσιτελεῖ","kjv_def":"it is better","strongs_def":" impersonally, it answers the purpose, i.e. is advantageous","derivation":"third person singular present indicative active of a derivative of a compound of G3080 (λύσις) and G5056 (τέλος);","pron":"loo-sit-el-i'","pos":"Verb","thayer":"<ol><li>to pay the taxes</li><li>to return expenses</li><li>to be useful, advantageous, it profits</li></ol>","xlit":"lysiteleî"},"G2024":{"lemma":"ἐπιχορηγία","translit":"epichorēgía","kjv_def":"supply","strongs_def":" contribution","derivation":"from G2023 (ἐπιχορηγέω);","pron":"ep-ee-khor-ayg-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a supplying, supply</li></ol>","xlit":"epichorēgía"},"G3689":{"derivation":"adverb of the oblique cases of G5607 (ὤν);","strongs_def":" really","kjv_def":"certainly, clean, indeed, of a truth, verily","lemma":"ὄντως","translit":"óntōs","pron":"on'-toce","pos":"Adverb","thayer":"<ol><li>truly, in reality, in point of fact, as opp. to what is pretended, fictitious, false, conjectural</li><li>that which is truly etc., that which is indeed</li></ol>","xlit":"óntōs"},"G4253":{"strongs_def":" \"fore\", i.e. in front of, prior (figuratively, superior) to","derivation":"a primary preposition;","translit":"pró","lemma":"πρό","kjv_def":"above, ago, before, or ever","pron":"pro","pos":"Preposition","thayer":"<ol><li>before</li></ol>","xlit":"pró"},"G3608":{"strongs_def":" a linen bandage","derivation":"neuter of a presumed derivative of G3607 (ὀθόνη);","lemma":"ὀθόνιον","translit":"othónion","kjv_def":"linen clothes","pron":"oth-on'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>a piece of linen, small linen cloth</li><li>strips of linen cloth for swathing the dead</li></ol>","xlit":"othónion"},"G421":{"strongs_def":" not tracked out, i.e. (by implication) untraceable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of a compound of G1537 (ἐκ) and a derivative of G2487 (ἴχνος);","lemma":"ἀνεξιχνίαστος","translit":"anexichníastos","kjv_def":"past finding out; unsearchable","pron":"an-ex-ikh-nee'-as-tos","pos":"Adjective","thayer":"<ol><li>that cannot be searched out, that cannot be comprehended</li></ol>","xlit":"anexichníastos"},"G1288":{"kjv_def":"pluck asunder, pull in pieces","translit":"diaspáō","lemma":"διασπάω","derivation":"from G1223 (διά) and G4685 (σπάω);","strongs_def":" to draw apart, i.e. sever or dismember","pron":"dee-as-pah'-o","pos":"Verb","thayer":"<ol><li>to rend asunder, break asunder<ol type='a'><li>of a man, to tear in pieces</li></ol></li></ol>","xlit":"diaspáō"},"G4352":{"strongs_def":" to fawn or crouch to, i.e. (literally or figuratively) prostrate oneself in homage (do reverence to, adore)","derivation":"from G4314 (πρός) and a probable derivative of G2965 (κύων) (meaning to kiss, like a dog licking his master's hand);","translit":"proskynéō","lemma":"προσκυνέω","kjv_def":"worship","pron":"pros-koo-neh'-o","pos":"Verb","thayer":"<ol><li>to kiss the hand to (towards) one, in token of reverence</li><li>among the Orientals, especially the Persians, to fall upon the knees and touch the ground with the forehead as an expression of profound reverence</li><li>in the NT by kneeling or prostration to do homage (to one) or make obeisance, whether in order to express respect or to make supplication<ol type='a'><li>used of homage shown to men and beings of superior rank<ol><li>to the Jewish high priests</li><li>to God</li><li>to Christ</li><li>to heavenly beings</li><li>to demons</li></ol></li></ol></li></ol>","xlit":"proskynéō"},"G2422":{"lemma":"Ἰεφθάε","translit":"Iephtháe","kjv_def":"Jephthah","strongs_def":" Jephthaë (i.e. Jiphtach), an Israelite","derivation":"of Hebrew origin (H03316);","pron":"ee-ef-thah'-eh","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Jephthah = \"whom God sets free\"</p><ol><li>son of Gilead, and a judge in Israel</li></ol>","xlit":"Iephtháe"},"G2086":{"derivation":"from a compound of G2087 (ἕτερος) and G2218 (ζυγός);","strongs_def":" to yoke up differently, i.e. (figuratively) to associate discordantly","kjv_def":"unequally yoke together with","translit":"heterozygéō","lemma":"ἑτεροζυγέω","pron":"het-er-od-zoog-eh'-o","pos":"Verb","thayer":"<ol><li>to come under an unequal or different yoke, to be unequally yoked<ol type='a'><li>to have fellowship with one who is not an equal: <a class='bible' href='#b47.6.14'>2Co 6:14</a>, where the apostle is forbidding Christians to have intercourse with idolaters</li></ol></li></ol>","xlit":"heterozygéō"},"G3564":{"kjv_def":"Nymphas","lemma":"Νυμφᾶς","translit":"Nymphâs","derivation":"probably contracted for a compound of G3565 (νύμφη) and G1435 (δῶρον);","strongs_def":" nymph-given (i.e. -born); Nymphas, a Christian","pron":"noom-fas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Nymphas = \"bridegroom\"</p><ol><li>a wealthy and zealous Christian in Laodicea</li></ol>","xlit":"Nymphâs"},"G4080":{"derivation":"a quantitative form (the feminine) of the base of G4225 (πού);","strongs_def":" how much (as an indefinite), i.e. in size or (figuratively) dignity","kjv_def":"how great (large)","translit":"pēlíkos","lemma":"πηλίκος","pron":"pay-lee'-kos","thayer":"<ol><li>how great, how large<ol type='a'><li>in a material reference (denoting geometrical magnitude as distinguished from arithmetical)</li><li>in an ethical sense: how distinguished</li></ol></li></ol>","xlit":"pēlíkos"},"G1882":{"strongs_def":" a straightening up again, i.e. (figuratively) rectification (reformation)","derivation":"from a compound of G1909 (ἐπί) and G461 (ἀνορθόω);","translit":"epanórthōsis","lemma":"ἐπανόρθωσις","kjv_def":" correction","pron":"ep-an-or'-tho-sis","pos":"Noun Feminine","thayer":"<ol><li>restoration to an upright or right state</li><li>correction, improvement of life or character</li></ol>","xlit":"epanórthōsis"},"G1112":{"translit":"gongysmós","lemma":"γογγυσμός","kjv_def":"grudging, murmuring","strongs_def":" a grumbling","derivation":"from G1111 (γογγύζω);","pron":"gong-goos-mos'","pos":"Noun Masculine","thayer":"<ol><li>a murmur, murmuring, muttering<ol type='a'><li>a secret debate</li><li>a secret displeasure not openly avowed</li></ol></li></ol>","xlit":"gongysmós"},"G1290":{"translit":"diasporá","lemma":"διασπορά","kjv_def":"(which are) scattered (abroad)","strongs_def":" dispersion, i.e. (specially and concretely) the (converted) Israelite resident in Gentile countries","derivation":"from G1289 (διασπείρω);","pron":"dee-as-por-ah'","pos":"Noun Feminine","thayer":"<ol><li>a scattering, dispersion<ol type='a'><li>of Israelites dispersed among foreign nations</li><li>of the Christians scattered abroad among the Gentiles</li></ol></li></ol>","xlit":"diasporá"},"G2279":{"translit":"ēchos","lemma":"ἦχος","kjv_def":"fame, sound","strongs_def":" a loud or confused noise (\"echo\"), i.e. roar; figuratively, a rumor","derivation":"of uncertain affinity;","pron":"ay'-khos","pos":"Noun Masculine","thayer":"<ol><li>a sound, noise<ol type='a'><li>spoken of the roar of the sea waves</li></ol><li>rumour, report</li></ol>","xlit":"ēchos"},"G1348":{"derivation":"from a derivative of G1349 (δίκη);","strongs_def":" a judger","kjv_def":"judge","lemma":"δικαστής","translit":"dikastḗs","pron":"dik-as-tace'","pos":"Noun Masculine","thayer":"<ol><li>a judge, arbitrator, umpire</li></ol>","xlit":"dikastḗs"},"G845":{"derivation":"from G846 (αὐτός) and G3700 (ὀπτάνομαι);","strongs_def":" self-seeing, i.e. an eye-witness","kjv_def":"eye-witness","lemma":"αὐτόπτης","translit":"autóptēs","pron":"ow-top'-tace","pos":"Noun Masculine","thayer":"<ol><li>seeing with one's own eye, an eye-witness<ol type='a'><li>a medical term: autopsy, a detailed examination</li></ol></li></ol>","xlit":"autóptēs"},"G2510":{"derivation":"from G2596 (κατά) and G680 (ἅπτομαι);","strongs_def":" to seize upon","kjv_def":"fasten on","lemma":"καθάπτω","translit":"katháptō","pron":"kath-ap'-to","pos":"Verb","thayer":"<ol><li>to fit or fasten to, bind on</li><li>to lay hold of, fasten on (hostilely)</li></ol>","xlit":"katháptō"},"G5520":{"kjv_def":"be angry","translit":"choláō","lemma":"χολάω","derivation":"from G5521 (χολή);","strongs_def":" to be bilious, i.e. (by implication) irritable (enraged, \"choleric\")","pron":"khol-ah'-o","pos":"Verb","thayer":"<ol><li>to be atrabilious</li><li>to be mad</li><li>to be angry, enraged</li></ol>","xlit":"choláō"},"G2342":{"translit":"thēríon","lemma":"θηρίον","kjv_def":"(venomous, wild) beast","strongs_def":" a dangerous animal","derivation":"diminutive from the same as G2339 (θήρα);","pron":"thay-ree'-on","pos":"Noun Neuter","thayer":"<ol><li>an animal</li><li>a wild animal, wild beast, beast</li><li>metaphorically a brutal, bestial man, savage, ferocious</li></ol>","xlit":"thēríon"},"G3941":{"strongs_def":" having a home near, i.e. (as noun) a by-dweller (alien resident)","derivation":"from G3844 (παρά) and G3624 (οἶκος);","translit":"pároikos","lemma":"πάροικος","kjv_def":"foreigner, sojourn, stranger","pron":"par'-oy-kos","pos":"Adjective","thayer":"<ol><li>dwelling near, neighbouring</li><li>in the NT, a stranger, a foreigner, one who lives in a place without the right of citizenship</li><li>metaphorically<ol type='a'><li>without citizenship in God's kingdom</li><li>one who lives on earth as a stranger, a sojourner on the earth</li><li>of Christians whose home is in heaven</li></ol></li></ol>","xlit":"pároikos"},"G3729":{"strongs_def":" to start, spur or urge on, i.e. (reflexively) to dash or plunge","derivation":"from G3730 (ὁρμή);","lemma":"ὁρμάω","translit":"hormáō","kjv_def":"run (violently), rush","pron":"hor-mah'-o","pos":"Verb","thayer":"<ol><li>to set in rapid motion, stir up, incite, urge on</li><li>to start forward impetuously, to rush</li></ol>","xlit":"hormáō"},"G2004":{"strongs_def":" to arrange upon, i.e. order","derivation":"from G1909 (ἐπί) and G5021 (τάσσω);","lemma":"ἐπιτάσσω","translit":"epitássō","kjv_def":"charge, command, injoin","pron":"ep-ee-tas'-so","pos":"Verb","thayer":"<ol><li>to enjoin upon, order, command, charge</li></ol>","xlit":"epitássō"},"G4932":{"derivation":"from G4862 (σύν) and the base of G5114 (τομώτερος);","strongs_def":" to contract by cutting, i.e. (figuratively) do concisely (speedily)","kjv_def":"(cut) short","translit":"syntémnō","lemma":"συντέμνω","pron":"soon-tem'-no","pos":"Verb","thayer":"<ol><li>to cut in pieces</li><li>to cut short</li><li>metaphorically<ol type='a'><li>to dispatch briefly, execute or finish quickly</li><li>to hasten</li><li>a short word, i.e. an expedited prophecy or decree</li></ol></li></ol>","xlit":"syntémnō"},"G3708":{"lemma":"ὁράω","translit":"horáō","kjv_def":"behold, perceive, see, take heed","strongs_def":" by extension, to attend to; by Hebraism, to experience; passively, to appear","derivation":"properly, to stare at (compare G3700 (ὀπτάνομαι)), i.e. (by implication) to discern clearly (physically or mentally);","pron":"hor-ah'-o","pos":"Verb","thayer":"<ol><li>to see with the eyes</li><li>to see with the mind, to perceive, know</li><li>to see, i.e. become acquainted with by experience, to experience</li><li>to see, to look to<ol type='a'><li>to take heed, beware</li><li>to care for, pay heed to</li></ol><li>I was seen, showed myself, appeared</li></ol>","xlit":"horáō"},"G486":{"strongs_def":" to rail in reply","derivation":"from G473 (ἀντί) and G3058 (λοιδορέω);","translit":"antiloidoréō","lemma":"ἀντιλοιδορέω","kjv_def":"revile again","pron":"an-tee-loy-dor-eh'-o","pos":"Verb","thayer":"<ol><li>to revile in turn, to retort railing</li></ol>","xlit":"antiloidoréō"},"G2970":{"derivation":"from G2749 (κεῖμαι);","strongs_def":" a carousal (as if letting loose)","kjv_def":"revelling, rioting","lemma":"κῶμος","translit":"kōmos","pron":"ko'-mos","pos":"Noun Masculine","thayer":"<ol><li>a revel, carousal<ol type='a'><li>a nocturnal and riotous procession of half drunken and frolicsome fellows who after supper parade through the streets with torches and music in honour of Bacchus or some other deity, and sing and play before houses of male and female friends; hence used generally of feasts and drinking parties that are protracted till late at night and indulge in revelry</li></ol></li></ol>","xlit":"kōmos"},"G1634":{"translit":"ekpsýchō","lemma":"ἐκψύχω","kjv_def":"give (yield) up the ghost","strongs_def":" to expire","derivation":"from G1537 (ἐκ) and G5594 (ψύχω);","pron":"ek-psoo'-kho","pos":"Verb","thayer":"<ol><li>to expire, to breathe out one's life</li></ol>","xlit":"ekpsýchō"},"G204":{"strongs_def":" belonging to the extreme corner","derivation":"from G206 (ἄκρον) and G1137 (γωνία);","lemma":"ἀκρογωνιαῖος","translit":"akrogōniaîos","kjv_def":"chief corner","pron":"ak-rog-o-nee-ah'-yos","pos":"Adjective","thayer":"<ol><li>placed at an extreme corner, the corner foundation stone</li></ol>","xlit":"akrogōniaîos"},"G941":{"lemma":"βαστάζω","translit":"bastázō","kjv_def":"bear, carry, take up","strongs_def":" to lift, literally or figuratively (endure, declare, sustain, receive, etc.)","derivation":"perhaps remotely derived from the base of G939 (βάσις) (through the idea of removal);","pron":"bas-tad'-zo","pos":"Verb","thayer":"<ol><li>to take up with the hands</li><li>to take up in order to carry or bear, to put upon one's self<ol type='a'><li>to bear what is burdensome</li></ol><li>to bear, to carry<ol type='a'><li>to carry on one's person</li><li>to sustain, i.e. uphold, support</li></ol><li>to bear away, carry off</li></ol>","xlit":"bastázō"},"G2975":{"kjv_def":"his lot be, cast lots, obtain","lemma":"λαγχάνω","translit":"lanchánō","derivation":"a prolonged form of a primary verb, which is only used as an alternate in certain tenses;","strongs_def":" to lot, i.e. determine (by implication, receive) especially by lot","pron":"lang-khan'-o","pos":"Verb","thayer":"<ol><li>to obtain by lot<ol type='a'><li>to receive by divine allotment, obtain</li></ol><li>to cast lots, determine by lot</li></ol>","xlit":"lanchánō"},"G2709":{"kjv_def":"under the earth","translit":"katachthónios","lemma":"καταχθόνιος","derivation":"from G2596 (κατά) and (the ground);","strongs_def":" subterranean, i.e. infernal (belonging to the world of departed spirits)","pron":"kat-akh-thon'-ee-os","pos":"Adjective","thayer":"<ol><li>subterranean<ol type='a'><li>refers to those who dwell in the world below, departed souls</li></ol></li></ol>","xlit":"katachthónios"},"G1306":{"translit":"diaugázō","lemma":"διαυγάζω","kjv_def":"dawn","strongs_def":" to glimmer through, i.e. break (as day)","derivation":"from G1223 (διά) and G826 (αὐγάζω);","pron":"dee-ow-gad'-zo","pos":"Verb","thayer":"<ol><li>to shine through, to dawn<ol type='a'><li>of daylight breaking through the darkness of night</li></ol></li></ol>","xlit":"diaugázō"},"G2088":{"kjv_def":"otherwise","lemma":"ἑτέρως","translit":"hetérōs","derivation":"adverb from G2087 (ἕτερος);","strongs_def":" differently","pron":"het-er'-oce","pos":"Adverb","thayer":"<ol><li>otherwise, differently</li></ol>","xlit":"hetérōs"},"G3559":{"strongs_def":" calling attention to, i.e. (by implication) mild rebuke or warning","derivation":"from G3563 (νοῦς) and a derivative of G5087 (τίθημι);","lemma":"νουθεσία","translit":"nouthesía","kjv_def":"admonition","pron":"noo-thes-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>admonition, exhortation</li></ol>","xlit":"nouthesía"},"G727":{"kjv_def":"extortion, ravening","lemma":"ἅρπαξ","translit":"hárpax","derivation":"from G726 (ἁρπάζω);","strongs_def":" rapacious","pron":"har'-pax","pos":"Adjective","thayer":"<ol><li>rapacious, ravenous</li><li>a extortioner, a robber</li></ol>","xlit":"hárpax"},"G2610":{"strongs_def":" to struggle against, i.e. (by implication) to overcome","derivation":"from G2596 (κατά) and G75 (ἀγωνίζομαι);","lemma":"καταγωνίζομαι","translit":"katagōnízomai","kjv_def":"subdue","pron":"kat-ag-o-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to struggle against</li><li>to overcome</li></ol>","xlit":"katagōnízomai"},"G3159":{"kjv_def":"Matthias","lemma":"Ματθίας","translit":"Matthías","derivation":"apparently a shortened form of G3161 (Ματταθίας);","strongs_def":" Matthias (i.e. Mattithjah), an Israelite","pron":"mat-thee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Matthias = \"gift of God\"</p><ol><li>the apostle elected to fill the place of the traitor Judas</li></ol>","xlit":"Matthías"},"G5396":{"strongs_def":" to be a babbler or trifler, i.e. (by implication) to berate idly or mischievously","derivation":"from G5397 (φλύαρος);","lemma":"φλυαρέω","translit":"phlyaréō","kjv_def":"prate against","pron":"floo-ar-eh'-o","pos":"Verb","thayer":"<ol><li>to utter nonsense, talk idly, prate</li><li>to bring forward idle accusations, make empty charges</li><li>to accuse one falsely with malicious words</li></ol>","xlit":"phlyaréō"},"G1662":{"strongs_def":" Eliakim, an Israelite","derivation":"of Hebrew origin (H0471);","lemma":"Ἐλιακείμ","translit":"Eliakeím","kjv_def":"Eliakim","pron":"el-ee-ak-ime'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Eliakim = \"raising up by God\"</p><ol><li>the eldest son of Abiud or Judah, bother of Joseph, and father of Azor <a class='bible' href='#b40.1.13'>Mat 1:13</a></li><li>son of Melea, and father of Jonan <a class='bible' href='#b42.3.30'>Luk 3:30</a>,<a class='bible' href='#b42.3.31'>Luk 3:31</a></li></ol>","xlit":"Eliakeím"},"G4507":{"derivation":"from G4508 (ῥυπαρός);","strongs_def":" dirtiness (morally)","kjv_def":"turpitude","lemma":"ῥυπαρία","translit":"rhyparía","pron":"hroo-par-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>to make filthy, befoul</li><li>to defile, dishonour</li><li>to make filthy</li></ol>","xlit":"rhyparía"},"G834":{"kjv_def":"minstrel, piper","lemma":"αὐλητής","translit":"aulētḗs","derivation":"from G832 (αὐλέω);","strongs_def":" a flute-player","pron":"ow-lay-tace'","pos":"Noun Masculine","thayer":"<ol><li>a flute player</li></ol>","xlit":"aulētḗs"},"G976":{"translit":"bíblos","lemma":"βίβλος","kjv_def":"book","derivation":"properly, the inner bark of the papyrus plant, i.e. (by implication) a sheet or scroll of writing","pron":"bib'-los","pos":"Noun Neuter","thayer":"<ol><li>a written book, a roll, a scroll</li></ol>","xlit":"bíblos"},"G5315":{"lemma":"φάγω","translit":"phágō","kjv_def":"eat, meat","strongs_def":" to eat (literally or figuratively)","derivation":"a primary verb (used as an alternate of G2068 (ἐσθίω) in certain tenses);","pron":"fag'-o","pos":"Verb","thayer":"<ol><li>to eat</li><li>to eat (consume) a thing<ol type='a'><li>to take food, eat a meal</li><li>metaphorically to devour, consume</li></ol></li></ol>","xlit":"phágō"},"G411":{"strongs_def":" not expounded in full, i.e. indescribable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G1555 (ἐκδιηγέομαι);","translit":"anekdiḗgētos","lemma":"ἀνεκδιήγητος","kjv_def":"unspeakable","pron":"an-ek-dee-ay'-gay-tos","pos":"Adjective","thayer":"<ol><li>the unspeakable, indescribable</li></ol>","xlit":"anekdiḗgētos"},"G2268":{"translit":"Hēsaḯas","lemma":"Ἡσαΐας","kjv_def":"Esaias","strongs_def":" Hesaias (i.e. Jeshajah), an Israelite","derivation":"of Hebrew origin (H03470);","pron":"hay-sah-ee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Isaiah = \"Jehovah's help\"</p><ol><li>a famous Hebrew prophet who prophesied in the reigns of Uzziah, Jotham, Ahaz, and Hezekiah</li></ol>","xlit":"Hēsaḯas"},"G4343":{"derivation":"from G4342 (προσκαρτερέω);","strongs_def":" persistancy","kjv_def":"perseverance","lemma":"προσκαρτέρησις","translit":"proskartérēsis","pron":"pros-kar-ter'-ay-sis","pos":"Noun Feminine","thayer":"<ol><li>perseverance</li></ol>","xlit":"proskartérēsis"},"G1131":{"derivation":"of uncertain affinity;","strongs_def":" nude (absolute or relative, literal or figurative)","kjv_def":"naked","translit":"gymnós","lemma":"γυμνός","pron":"goom-nos'","pos":"Adjective","thayer":"<ol><li>properly<ol type='a'><li>unclad, without clothing, the naked body</li><li>ill clad</li><li>clad in undergarments only (the outer garments or cloak being laid aside)</li><li>of the soul, whose garment is the body, stripped of the body, without a body</li></ol><li>metaphorically<ol type='a'><li>naked, i.e. open, lay bare</li><li>only, mere, bare, i.e. mere grain not the plant itself</li></ol></li></ol>","xlit":"gymnós"},"G2819":{"derivation":"probably from G2806 (κλάω) (through the idea of using bits of wood, etc., for the purpose;","strongs_def":" a die (for drawing chances); by implication, a portion (as if so secured); by extension, an acquisition (especially a patrimony, figuratively)","kjv_def":"heritage, inheritance, lot, part","lemma":"κλῆρος","translit":"klēros","pron":"klay'-ros","pos":"Noun Masculine","thayer":"<ol><li>an object used in casting or drawing lots, which was either a pebble, or a potsherd, or a bit of wood<ol type='a'><li>the lots of several persons concerned, inscribed with their names, were thrown together into a vase, which was then shaken, and he whose lot fell out first upon the ground was the one chosen</li></ol><li>what is obtained by lot, allotted portion<ol type='a'><li>a portion of the ministry common to the apostles</li><li>used of the part which one will have in eternal salvation<ol><li>of salvation itself</li><li>the eternal salvation which God has assigned to the saints</li></ol><li>of persons<ol><li>those whose care and oversight has been assigned to one [allotted charge], used of Christian churches, the administration of which falls to the lot of presbyters</li></ol></li></ol></li></ol>","xlit":"klēros"},"G4371":{"strongs_def":" something eaten in addition to bread, i.e. a relish (specially, fish; compare G3795 (ὀψάριον))","derivation":"neuter of a presumed derivative of a compound of G4314 (πρός) and G5315 (φάγω);","translit":"prosphágion","lemma":"προσφάγιον","kjv_def":"meat","pron":"pros-fag'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>anything eaten with bread<ol type='a'><li>spoken of fish boiled or broiled</li></ol></li></ol>","xlit":"prosphágion"},"G332":{"kjv_def":"(bind under a) curse, bind with an oath","lemma":"ἀναθεματίζω","translit":"anathematízō","derivation":"from G331 (ἀνάθεμα);","strongs_def":" to declare or vow under penalty of execration","pron":"an-ath-em-at-id'-zo","pos":"Verb","thayer":"<ol><li>to devote to destruction</li><li>to declare one's self liable to the severest divine penalties</li></ol>","xlit":"anathematízō"},"G2294":{"lemma":"θάρσος","translit":"thársos","kjv_def":"courage","strongs_def":" boldness (subjectively)","derivation":"akin (by transposition) to (daring);","pron":"thar'-sos","pos":"Noun Neuter","thayer":"<ol><li>courage, confidence</li></ol>","xlit":"thársos"},"G108":{"kjv_def":"Azotus","lemma":"Ἄζωτος","translit":"Ázōtos","derivation":"of Hebrew origin (H0795);","strongs_def":" Azotus (i.e. Ashdod), a place in Palestine","pron":"ad'-zo-tos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Ashdod or Azotus = \"a stronghold\"</p><ol><li>one of the five chief cities of the Philistines, lying between Ashkelon and Jamnia and near the Mediterranean</li></ol>","xlit":"Ázōtos"},"G945":{"strongs_def":" to stutter, i.e. (by implication) to prate tediously","derivation":"from (a proverbial stammerer) and G3056 (λόγος);","translit":"battologéō","lemma":"βαττολογέω","kjv_def":"use vain repetitions","pron":"bat-tol-og-eh'-o","pos":"Verb","thayer":"<ol><li>to stammer</li><li>to repeat the same things over and over, to use many idle words, to babble, prate. Some suppose the word derived from Battus, a king of Cyrene, who is said to have stuttered; others from Battus, an author of tedious and wordy poems.</li></ol>","xlit":"battologéō"},"G3602":{"derivation":"from a derivative of the base of G1416 (δύνω);","strongs_def":" moaning, i.e. lamentation","kjv_def":"mourning","lemma":"ὀδυρμός","translit":"odyrmós","pron":"od-oor-mos'","pos":"Noun Masculine","thayer":"<ol><li>wailing, lamentation, mourning</li></ol>","xlit":"odyrmós"},"G1263":{"derivation":"from G1223 (διά) and G3140 (μαρτυρέω);","strongs_def":" to attest or protest earnestly, or (by implication) hortatively","kjv_def":"charge, testify (unto), witness","lemma":"διαμαρτύρομαι","translit":"diamartýromai","pron":"dee-am-ar-too'-rom-ahee","pos":"Verb","thayer":"<ol><li>to testify<ol type='a'><li>earnestly, religiously to charge</li></ol><li>to attest, testify to, solemnly affirm<ol type='a'><li>to give solemn testimony to one</li><li>to confirm a thing by testimony, to testify, cause it to be believed</li></ol></li></ol>","xlit":"diamartýromai"},"G4466":{"derivation":"of Hebrew origin (H07466);","strongs_def":" Ragau (i.e. Reu), a patriarch","kjv_def":"Ragau","lemma":"Ῥαγαῦ","translit":"Rhagaû","pron":"hrag-ow'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Reu = \"associate ye: feed ye\"</p><ol><li>one of the ancestors of Christ</li></ol>","xlit":"Rhagaû"},"G930":{"translit":"basanistḗs","lemma":"βασανιστής","kjv_def":"tormentor","strongs_def":" a torturer","derivation":"from G928 (βασανίζω);","pron":"bas-an-is-tace'","pos":"Noun Masculine","thayer":"<ol><li>one who elicits the truth by the use of the rack<ol type='a'><li>an inquisitor, torturer also used of a jailer doubtless because the business of torturing was also assigned to him</li></ol></li></ol>","xlit":"basanistḗs"},"G992":{"translit":"blētéos","lemma":"βλητέος","kjv_def":"must be put","strongs_def":" fit to be cast (i.e. applied)","derivation":"from G906 (βάλλω);","pron":"blay-teh'-os","pos":"Adjective","thayer":"<ol><li>which must be thrown or put</li></ol>","xlit":"blētéos"},"G5586":{"strongs_def":" a pebble (as worn smooth by handling), i.e. (by implication, of use as a counter or ballot) a verdict (of acquittal) or ticket (of admission); a vote","derivation":"from the same as G5584 (ψηλαφάω);","lemma":"ψῆφος","translit":"psēphos","kjv_def":"stone, voice","pron":"psay'-fos","pos":"Noun Feminine","thayer":"<ol><li>a small worn smooth stone, a pebble<ol type='a'><li>in the ancient courts of justice the accused were condemned by black pebbles and the acquitted by white</li></ol><li>a vote (on account of the use of pebbles in voting)</li></ol>","xlit":"psēphos"},"G1107":{"derivation":"from a derivative of G1097 (γινώσκω);","strongs_def":" to make known; subjectively, to know","kjv_def":"certify, declare, make known, give to understand, do to wit, wot","lemma":"γνωρίζω","translit":"gnōrízō","pron":"gno-rid'-zo","pos":"Verb","thayer":"<ol><li>to make known<ol type='a'><li>to become known, be recognised</li></ol><li>to know, to gain knowledge of, have thorough knowledge of<ol type='a'><li>in earlier Greek it means \"to gain a knowledge of\" or \"have thorough knowledge of\"</li></ol></li></ol>","xlit":"gnōrízō"},"G2145":{"kjv_def":"X attend upon","translit":"euprósedros","lemma":"εὐπρόσεδρος","derivation":"from G2095 (εὖ) and the same as G4332 (προσεδρεύω);","strongs_def":" sitting well towards, i.e. (figuratively) assiduous (neuter, diligent service)","pron":"yoo-pros'-ed-ros","pos":"Adjective","thayer":"<ol><li>sitting constantly by, devoted</li></ol>","xlit":"euprósedros"},"G4634":{"strongs_def":" the Festival of Tabernacles (so called from the custom of erecting booths for temporary homes)","derivation":"from G4636 (σκῆνος) and G4078 (πήγνυμι);","lemma":"σκηνοπηγία","translit":"skēnopēgía","kjv_def":"tabernacles","pron":"skay-nop-ayg-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>the construction of a tabernacle or tabernacles</li><li>the feast of tabernacles; this festival was observed by the Jews yearly for seven days, beginning with the 15th of the month Tisri</li></ol>","xlit":"skēnopēgía"},"G5336":{"derivation":"from (to eat);","strongs_def":" a crib (for fodder)","kjv_def":"manager, stall","lemma":"φάτνη","translit":"phátnē","pron":"fat'-nay","pos":"Noun Feminine","thayer":"<ol><li>a crib, a manger</li></ol>","xlit":"phátnē"},"G2398":{"derivation":"of uncertain affinity;","strongs_def":" pertaining to self, i.e. one's own; by implication, private or separate","kjv_def":"X his acquaintance, when they were alone, apart, aside, due, his (own, proper, several), home, (her, our, thine, your) own (business), private(-ly), proper, severally, their (own)","lemma":"ἴδιος","translit":"ídios","pron":"id'-ee-os","pos":"Adjective","thayer":"<ol><li>pertaining to one's self, one's own, belonging to one's self</li></ol>","xlit":"ídios"},"G4992":{"strongs_def":" defender or (by implication) defence","derivation":"neuter of the same as G4991 (σωτηρία) as (properly, concretely) noun;","translit":"sōtḗrion","lemma":"σωτήριον","kjv_def":"salvation","pron":"so-tay'-ree-on","pos":"Adjective","thayer":"<ol><li>saving, bringing salvation</li><li>he who embodies this salvation, or through whom God is about to achieve it</li><li>the hope of (future) salvation</li></ol>","xlit":"sōtḗrion"},"G4541":{"strongs_def":" a Samarite, i.e. inhabitant of Samaria","derivation":"from G4540 (Σαμάρεια);","translit":"Samareítēs","lemma":"Σαμαρείτης","kjv_def":"Samaritan","pron":"sam-ar-i'-tace","pos":"Noun Masculine","thayer":"<ol><li>a Samaritan<ol type='a'><li>an inhabitant of the city of Samaria</li><li>an inhabitant of the region of Samaria</li></ol></li></ol>","xlit":"Samareítēs"},"G4036":{"strongs_def":" grieved all around, i.e. intensely sad","derivation":"from G4012 (περί) and G3077 (λύπη);","translit":"perílypos","lemma":"περίλυπος","kjv_def":"exceeding (very) sorry(-owful)","pron":"per-il'-oo-pos","pos":"Adjective","thayer":"<ol><li>very sad, exceedingly sorrowful</li><li>overcome with sorrow so much as to cause one's death</li></ol>","xlit":"perílypos"},"G4940":{"translit":"syntynchánō","lemma":"συντυγχάνω","kjv_def":"come at","strongs_def":" to chance together, i.e. meet with (reach)","derivation":"from G4862 (σύν) and G5177 (τυγχάνω);","pron":"soon-toong-khan'-o","pos":"Verb","thayer":"<ol><li>to meet with, come</li></ol>","xlit":"syntynchánō"},"G4028":{"lemma":"περικαλύπτω","translit":"perikalýptō","kjv_def":"blindfold, cover, overlay","strongs_def":" to cover all around, i.e. entirely (the face, a surface)","derivation":"from G4012 (περί) and G2572 (καλύπτω);","pron":"per-ee-kal-oop'-to","pos":"Verb","thayer":"<ol><li>to cover all around, to cover up, cover over</li></ol>","xlit":"perikalýptō"},"G3968":{"strongs_def":" a father-land, i.e. native town; (figuratively) heavenly home","derivation":"from G3902 (παράσημος);","translit":"patrís","lemma":"πατρίς","kjv_def":"(own) country","pron":"pat-rece'","pos":"Noun Feminine","thayer":"<ol><li>one's native country<ol type='a'><li>one's fatherland, one's own country, a fixed abode or home</li><li>one's own native place, i.e. a city</li></ol></li></ol>","xlit":"patrís"},"G89":{"strongs_def":" uninterruptedly, i.e. without omission (on an appropriate occasion)","derivation":"adverb from G88 (ἀδιάλειπτος);","lemma":"ἀδιαλείπτως","translit":"adialeíptōs","kjv_def":"without ceasing","pron":"ad-ee-al-ipe'-toce","pos":"Adverb","thayer":"<ol><li>without intermission, incessantly, without ceasing</li></ol>","xlit":"adialeíptōs"},"G1936":{"kjv_def":"laying (putting) on","translit":"epíthesis","lemma":"ἐπίθεσις","derivation":"from G2007 (ἐπιτίθημι);","strongs_def":" an imposition (of hands officially)","pron":"ep-ith'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a laying on, imposition</li></ol>","xlit":"epíthesis"},"G360":{"lemma":"ἀναλύω","translit":"analýō","kjv_def":"depart, return","strongs_def":" to break up, i.e. depart (literally or figuratively)","derivation":"from G303 (ἀνά) and G3089 (λύω);","pron":"an-al-oo'-o","pos":"Verb","thayer":"<ol><li>to unloose, undo again</li><li>to depart, break up, to depart from life, to return</li></ol>","xlit":"analýō"},"G1490":{"kjv_def":"(or) else, if (not, otherwise), otherwise","lemma":"εἰ δὲ μή(γε)","translit":"ei dè mḗ(ge)","derivation":"from G1487 (εἰ), G1161 (δέ), and G3361 (μή) (sometimes with G1065 (γέ) added);","strongs_def":" but if not","pron":"i deh may'-(gheh)","pos":"Conjunction","thayer":"<ol><li>otherwise, but if not</li></ol>","xlit":"ei dè mḗ(ge)"},"G4982":{"strongs_def":" to save, i.e. deliver or protect (literally or figuratively)","derivation":"from a primary (contraction for obsolete , \"safe\");","lemma":"σώζω","translit":"sṓzō","kjv_def":"heal, preserve, save (self), do well, be (make) whole","pron":"sode'-zo","pos":"Verb","thayer":"<ol><li>to save, keep safe and sound, to rescue from danger or destruction<ol type='a'><li>one (from injury or peril)<ol><li>to save a suffering one (from perishing), i.e. one suffering from disease, to make well, heal, restore to health</li><li>to preserve one who is in danger of destruction, to save or rescue</li></ol><li>to save in the technical biblical sense<ol><li>negatively<ol type='a'><li>to deliver from the penalties of the Messianic judgment</li><li>to save from the evils which obstruct the reception of the Messianic deliverance</li></ol></li></ol></li></ol></li></ol>","xlit":"sṓzō"},"G2626":{"strongs_def":" to dash (wash) down, i.e. (by implication) to deluge","derivation":"from G2596 (κατά) and the base of G2830 (κλύδων);","lemma":"κατακλύζω","translit":"kataklýzō","kjv_def":"overflow","pron":"kat-ak-lood'-zo","pos":"Verb","thayer":"<ol><li>to overwhelm with water, to submerge, deluge</li></ol>","xlit":"kataklýzō"},"G4172":{"strongs_def":" a town (properly, with walls, of greater or less size)","derivation":"probably from the same as G4171 (πόλεμος), or perhaps from G4183 (πολύς);","translit":"pólis","lemma":"πόλις","kjv_def":"city","pron":"pol'-is","pos":"Noun Feminine","thayer":"<ol><li>a city<ol type='a'><li>one's native city, the city in which one lives</li><li>the heavenly Jerusalem<ol><li>the abode of the blessed in heaven</li><li>of the visible capital in the heavenly kingdom, to come down to earth after the renovation of the world by fire</li></ol><li>the inhabitants of a city</li></ol></li></ol>","xlit":"pólis"},"G892":{"translit":"áchyron","lemma":"ἄχυρον","kjv_def":"chaff","strongs_def":" chaff (as diffusive)","derivation":"perhaps remotely from (to shed forth);","pron":"akh'-oo-ron","pos":"Noun Neuter","thayer":"<ol><li>a stalk of grain from which the kernels have been beaten out</li><li>straw broken up by a threshing machine, chaff</li></ol>","xlit":"áchyron"},"G2662":{"kjv_def":"trample, tread (down, underfoot)","translit":"katapatéō","lemma":"καταπατέω","derivation":"from G2596 (κατά) and G3961 (πατέω);","strongs_def":" to trample down; figuratively, to reject with disdain","pron":"kat-ap-at-eh'-o","pos":"Verb","thayer":"<ol><li>to tread down, trample under foot, to trample on</li><li>metaphorically to treat with rudeness and insult<ol type='a'><li>to spurn, treat with insulting neglect</li></ol></li></ol>","xlit":"katapatéō"},"G3693":{"strongs_def":" from G3700 (ὀπτάνομαι)) with enclitic of source; from the rear (as a secure aspect), i.e. at the back (adverb and preposition of place or time)","derivation":"from (regard;","translit":"ópisthen","lemma":"ὄπισθεν","kjv_def":"after, backside, behind","pron":"op'-is-then","pos":"Adjective","thayer":"<ol><li>from behind, on the back, behind, after</li></ol>","xlit":"ópisthen"},"G674":{"strongs_def":" to breathe out, i.e. faint","derivation":"from G575 (ἀπό) and G5594 (ψύχω);","translit":"apopsýchō","lemma":"ἀποψύχω","kjv_def":"hearts failing","pron":"ap-ops-oo'-kho","pos":"Verb","thayer":"<ol><li>to breathe out life, expire</li><li>to faint or swoon away</li></ol>","xlit":"apopsýchō"},"G2940":{"derivation":"from (a \"cube\", i.e. die for playing);","strongs_def":" gambling, i.e. (figuratively) artifice or fraud","kjv_def":"sleight","translit":"kybeía","lemma":"κυβεία","pron":"koo-bi'-ah","pos":"Noun Feminine","thayer":"<ol><li>dice playing</li><li>metaphorically the deception of men, because dice players sometimes cheated and defrauded their fellow players</li></ol>","xlit":"kybeía"},"G1652":{"derivation":"from G1656 (ἔλεος);","strongs_def":" pitiable","kjv_def":"miserable","translit":"eleeinós","lemma":"ἐλεεινός","pron":"el-eh-i-nos'","pos":"Adjective","thayer":"<ol><li>to be pitied, miserable</li></ol>","xlit":"eleeinós"},"G463":{"kjv_def":"forbearance","translit":"anochḗ","lemma":"ἀνοχή","derivation":"from G430 (ἀνέχομαι);","strongs_def":" self-restraint, i.e. tolerance","pron":"an-okh-ay'","pos":"Noun Feminine","thayer":"<ol><li>toleration, forbearance</li></ol>","xlit":"anochḗ"},"G2370":{"kjv_def":"burn incense","lemma":"θυμιάω","translit":"thymiáō","derivation":"from a derivative of G2380 (θύω) (in the sense of smoking);","strongs_def":" to fumigate, i.e. offer aromatic fumes","pron":"thoo-mee-ah'-o","pos":"Verb","thayer":"<ol><li>to burn incense</li></ol>","xlit":"thymiáō"},"G4721":{"derivation":"strengthened from a primary (a \"thatch\" or \"deck\" of a building);","strongs_def":" a roof","kjv_def":"roof","lemma":"στέγη","translit":"stégē","pron":"steg'-ay","pos":"Noun Feminine","thayer":"<ol><li>a roof: of a house</li></ol>","xlit":"stégē"},"G1960":{"derivation":"adverb from a derivative of G1959 (ἐπιμελέομαι);","strongs_def":" carefully","kjv_def":"diligently","lemma":"ἐπιμελῶς","translit":"epimelōs","pron":"ep-ee-mel-oce'","pos":"Adverb","thayer":"<ol><li>diligently, carefully</li></ol>","xlit":"epimelōs"},"G567":{"translit":"apéchomai","lemma":"ἀπέχομαι","kjv_def":"abstain","strongs_def":" to hold oneself off, i.e. refrain","derivation":"middle voice (reflexively) of G568 (ἀπέχω);","pron":"ap-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to hold one's self off, refrain, abstain</li></ol>","xlit":"apéchomai"},"G4315":{"kjv_def":"day before the sabbath","lemma":"προσάββατον","translit":"prosábbaton","derivation":"from G4253 (πρό) and G4521 (σάββατον);","strongs_def":" a fore-sabbath, i.e. the Sabbath-eve","pron":"pros-ab'-bat-on","pos":"Noun Neuter","thayer":"<ol><li>the day before the sabbath</li></ol>","xlit":"prosábbaton"},"G5226":{"strongs_def":" to surrender","derivation":"from G5259 (ὑπό) and (to yield, be \"weak\");","translit":"hypeíkō","lemma":"ὑπείκω","kjv_def":"submit self","pron":"hoop-i'-ko","pos":"Verb","thayer":"<ol><li>to resist no longer, but to give way, yield (of combatants)</li><li>metaphorically to yield to authority and admonition, to submit</li></ol>","xlit":"hypeíkō"},"G4961":{"translit":"systratiṓtēs","lemma":"συστρατιώτης","kjv_def":"fellowsoldier","strongs_def":" a co-campaigner, i.e. (figuratively) an associate in Christian toil","derivation":"from G4862 (σύν) and G4757 (στρατιώτης);","pron":"soos-trat-ee-o'-tace","pos":"Noun Masculine","thayer":"<ol><li>a fellow soldier</li><li>an associate in labours and conflicts for the cause of Christ</li></ol>","xlit":"systratiṓtēs"},"G2002":{"lemma":"ἐπισωρεύω","translit":"episōreúō","kjv_def":"heap","strongs_def":" to accumulate further, i.e. (figuratively) seek additionally","derivation":"from G1909 (ἐπί) and G4987 (σωρεύω);","pron":"ep-ee-so-ryoo'-o","pos":"Verb","thayer":"<ol><li>to heap up, accumulate in piles</li></ol>","xlit":"episōreúō"},"G3199":{"kjv_def":"(take) care","lemma":"μέλω","translit":"mélō","derivation":"a primary verb;","strongs_def":" to be of interest to, i.e. to concern (only third person singular present indicative used impersonally, it matters)","pron":"mel'-o","pos":"Verb","thayer":"<ol><li>to care about</li></ol>","xlit":"mélō"},"G620":{"lemma":"ἀπολείπω","translit":"apoleípō","kjv_def":"leave, remain","strongs_def":" to leave behind (passively, remain); by implication, to forsake","derivation":"from G575 (ἀπό) and G3007 (λείπω);","pron":"ap-ol-ipe'-o","pos":"Verb","thayer":"<ol><li>to leave, to leave behind</li><li>to desert or forsake</li></ol>","xlit":"apoleípō"},"G1817":{"lemma":"ἐξανίστημι","translit":"exanístēmi","kjv_def":"raise (rise) up","strongs_def":" objectively, to produce, i.e. (figuratively) beget; subjectively, to arise, i.e. (figuratively) object","derivation":"from G1537 (ἐκ) and G450 (ἀνίστημι);","pron":"ex-an-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to make to rise up, to rise up, to produce</li><li>to rise (in an assembly to speak)</li></ol>","xlit":"exanístēmi"},"G5603":{"derivation":"from G103 (ᾄδω);","strongs_def":" a chant or \"ode\" (the general term for any words sung; while G5215 (ὕμνος) denotes especially a religious metrical composition, and G5568 (ψαλμός) still more specially, a Hebrew cantillation)","kjv_def":"song","lemma":"ᾠδή","translit":"ōidḗ","pron":"o-day'","pos":"Noun Feminine","thayer":"<ol><li>a song, lay, ode</li></ol>","xlit":"ōidḗ"},"G2954":{"strongs_def":" Cyprus, an island in the Mediterranean","derivation":"of uncertain origin;","lemma":"Κύπρος","translit":"Kýpros","kjv_def":"Cyprus","pron":"koo'-pros","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Cyprus = \"love: a blossom\"</p><ol><li>a very fertile and delightful island of the Mediterranean, lying between Cilicia and Syria</li></ol>","xlit":"Kýpros"},"G2828":{"translit":"klisía","lemma":"κλισία","kjv_def":"company","strongs_def":" properly, reclination, i.e. (concretely and specially), a party at a meal","derivation":"from a derivative of G2827 (κλίνω);","pron":"klee-see'-ah","pos":"Noun Feminine","thayer":"<ol><li>a hut erected to pass the night in</li><li>a tent</li><li>anything to recline on<ol type='a'><li>a chair in which to lean back the head</li><li>a reclining chair</li></ol><li>a company reclining<ol type='a'><li>a row or party of persons reclining at meal</li></ol></li></ol>","xlit":"klisía"},"G4049":{"derivation":"from G4012 (περί) and G4685 (σπάω);","strongs_def":" to drag all around, i.e. (figuratively) to distract (with care)","kjv_def":"cumber","lemma":"περισπάω","translit":"perispáō","pron":"per-ee-spah'-o","pos":"Verb","thayer":"<ol><li>to draw around, to draw away, distract</li><li>metaphorically<ol type='a'><li>to be driven about mentally, to be distracted</li><li>to be over-occupied, too busy, about a thing</li></ol></li></ol>","xlit":"perispáō"},"G4231":{"translit":"pragmateúomai","lemma":"πραγματεύομαι","kjv_def":"occupy","strongs_def":" to busy oneself with, i.e. to trade","derivation":"from G4229 (πρᾶγμα);","pron":"prag-mat-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to be occupied in anything</li><li>to carry on a business</li><li>to carry on the business of a banker or a trader</li></ol>","xlit":"pragmateúomai"},"G3325":{"derivation":"from G3324 (μεστός);","strongs_def":" to replenish, i.e. (by implication) to intoxicate","kjv_def":"fill","translit":"mestóō","lemma":"μεστόω","pron":"mes-to'-o","pos":"Verb","thayer":"<ol><li>to fill, be full</li></ol>","xlit":"mestóō"},"G2863":{"derivation":"from G2864 (κόμη);","strongs_def":" to wear tresses of hair","kjv_def":"have long hair","translit":"komáō","lemma":"κομάω","pron":"kom-ah'-o","pos":"Verb","thayer":"<ol><li>to let the hair grow, have long hair</li></ol>","xlit":"komáō"},"G472":{"derivation":"from G473 (ἀντί) and the middle voice of G2192 (ἔχω);","strongs_def":" to hold oneself opposite to, i.e. (by implication) adhere to; by extension to care for","kjv_def":"hold fast, hold to, support","translit":"antéchomai","lemma":"ἀντέχομαι","pron":"an-tekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to hold before or against, hold back, withstand, endure</li><li>to keep one's self directly opposite to any one, hold to him firmly, cleave to, paying heed to him</li></ol>","xlit":"antéchomai"},"G1525":{"kjv_def":"X arise, come (in, into), enter in(-to), go in (through)","lemma":"εἰσέρχομαι","translit":"eisérchomai","derivation":"from G1519 (εἰς) and G2064 (ἔρχομαι);","strongs_def":" to enter (literally or figuratively)","pron":"ice-er'-khom-ahee","pos":"Verb","thayer":"<ol><li>to go out or come in: to enter<ol type='a'><li>of men or animals, as into a house or a city</li><li>of Satan taking possession of the body of a person</li><li>of things: as food, that enters into the eater's mouth</li></ol><li>metaphorically<ol type='a'><li>of entrance into any condition, state of things, society, employment<ol><li>to arise, come into existence, begin to be</li><li>of men, to come before the public</li><li>to come into life</li></ol><li>of thoughts that come into the mind</li></ol></li></ol>","xlit":"eisérchomai"},"G1587":{"strongs_def":" to omit, i.e. (by implication) cease (die)","derivation":"from G1537 (ἐκ) and G3007 (λείπω);","lemma":"ἐκλείπω","translit":"ekleípō","kjv_def":"fail","pron":"ek-li'-po","pos":"Verb","thayer":"<ol><li>fail<ol type='a'><li>to leave out, omit, pass by</li><li>to leave, quit</li></ol><li>to fail<ol type='a'><li>to leave off, cease, stop</li><li>of the failing or eclipse of the light of the sun and the moon</li></ol></li></ol>","xlit":"ekleípō"},"G4511":{"derivation":"from G4506 (ῥύομαι) in the sense of its congener G4482 (ῥέω);","strongs_def":" a flux (of blood)","kjv_def":"issue","translit":"rhýsis","lemma":"ῥύσις","pron":"hroo'-sis","pos":"Noun Feminine","thayer":"<ol><li>a flowing issue</li></ol>","xlit":"rhýsis"},"G4017":{"derivation":"from G4012 (περί) and G991 (βλέπω);","strongs_def":" to look all around","kjv_def":"look (round) about (on)","lemma":"περιβλέπω","translit":"periblépō","pron":"per-ee-blep'-o","pos":"Verb","thayer":"<ol><li>to look around</li><li>to look around about one's self</li><li>to look round on one (i.e. to look for one's self at one near by)</li></ol>","xlit":"periblépō"},"G3056":{"derivation":"from G3004 (λέγω);","strongs_def":" something said (including the thought); by implication, a topic (subject of discourse), also reasoning (the mental faculty) or motive; by extension, a computation; specially, (with the article in John) the Divine Expression (i.e. Christ)","kjv_def":"account, cause, communication, X concerning, doctrine, fame, X have to do, intent, matter, mouth, preaching, question, reason, + reckon, remove, say(-ing), shew, X speaker, speech, talk, thing, + none of these things move me, tidings, treatise, utterance, word, work","lemma":"λόγος","translit":"lógos","pron":"log'-os","pos":"Noun Masculine","thayer":"<ol><li>of speech<ol type='a'><li>a word, uttered by a living voice, embodies a conception or idea</li><li>what someone has said<ol><li>a word</li><li>the sayings of God</li><li>decree, mandate or order</li><li>of the moral precepts given by God</li><li>Old Testament prophecy given by the prophets</li><li>what is declared, a thought, declaration, aphorism, a weighty saying, a dictum, a maxim</li></ol><li>discourse<ol><li>the act of speaking, speech</li><li>the faculty of speech, skill and practice in speaking</li><li>a kind or style of speaking</li><li>a continuous speaking discourse - instruction</li></ol><li>doctrine, teaching</li><li>anything reported in speech; a narration, narrative</li><li>matter under discussion, thing spoken of, affair, a matter in dispute, case, suit at law</li><li>the thing spoken of or talked about; event, deed</li></ol><li>its use as respect to the MIND alone<ol type='a'><li>reason, the mental faculty of thinking, meditating, reasoning, calculating</li><li>account, i.e. regard, consideration</li><li>account, i.e. reckoning, score</li><li>account, i.e. answer or explanation in reference to judgment</li><li>relation, i.e. with whom as judge we stand in relation<ol><li>reason would</li></ol><li>reason, cause, ground</li></ol><li>In John, denotes the essential Word of God, Jesus Christ, the personal wisdom and power in union with God, his minister in creation and government of the universe, the cause of all the world's life both physical and ethical, which for the procurement of man's salvation put on human nature in the person of Jesus the Messiah, the second person in the Godhead, and shone forth conspicuously from His words and deeds.</li></ol>","xlit":"lógos"},"G3605":{"kjv_def":"stink","lemma":"ὄζω","translit":"ózō","derivation":"a primary verb (in a strengthened form);","strongs_def":" to scent (usually an ill \"odor\")","pron":"od'-zo","pos":"Verb","thayer":"<ol><li>to give out an odour (either good or bad), to smell, emit a smell<ol type='a'><li>of a decaying corpse</li></ol></li></ol>","xlit":"ózō"},"G4089":{"lemma":"πικρός","translit":"pikrós","kjv_def":"bitter","strongs_def":" sharp (pungent), i.e. acrid (literally or figuratively)","derivation":"perhaps from G4078 (πήγνυμι) (through the idea of piercing);","pron":"pik-ros'","pos":"Adjective","thayer":"<ol><li>bitter</li><li>metaphorically harsh, virulent</li></ol>","xlit":"pikrós"},"G2821":{"kjv_def":"calling","lemma":"κλῆσις","translit":"klēsis","derivation":"from a shorter form of G2564 (καλέω);","strongs_def":" an invitation (figuratively)","pron":"klay'-sis","pos":"Noun Feminine","thayer":"<ol><li>a calling, calling to</li><li>a call, invitation<ol type='a'><li>to a feast</li><li>of the divine invitation to embrace salvation of God</li></ol></li></ol>","xlit":"klēsis"},"G4053":{"lemma":"περισσός","translit":"perissós","kjv_def":"exceeding abundantly above, more abundantly, advantage, exceedingly, very highly, beyond measure, more, superfluous, vehement(-ly)","strongs_def":" superabundant (in quantity) or superior (in quality); by implication, excessive; adverbially (with G1537 (ἐκ)) violently; neuter (as noun) preeminence","derivation":"from G4012 (περί) (in the sense of beyond);","pron":"per-is-sos'","pos":"Adjective","thayer":"<ol><li>exceeding some number or measure or rank or need<ol type='a'><li>over and above, more than is necessary, superadded<ol><li>exceeding abundantly, supremely</li><li>something further, more, much more than all, more plainly</li></ol><li>superior, extraordinary, surpassing, uncommon<ol><li>pre-eminence, superiority, advantage, more eminent, more remarkable, more excellent</li></ol></li></ol></li></ol>","xlit":"perissós"},"G4301":{"lemma":"προλαμβάνω","translit":"prolambánō","kjv_def":"come aforehand, overtake, take before","strongs_def":" to take in advance, i.e. (literally) eat before others have an opportunity; (figuratively) to anticipate, surprise","derivation":"from G4253 (πρό) and G2983 (λαμβάνω);","pron":"prol-am-ban'-o","pos":"Verb","thayer":"<ol><li>to take before</li><li>to anticipate, to forestall</li><li>to take one by forestalling (him, i.e. before he can flee or conceal his crime)<ol type='a'><li>surprise, detect</li></ol></li></ol>","xlit":"prolambánō"},"G589":{"lemma":"ἀποδημέω","translit":"apodēméō","kjv_def":"go (travel) into a far country, journey","strongs_def":" to go abroad, i.e. visit a foreign land","derivation":"from G590 (ἀπόδημος);","pron":"ap-od-ay-meh'-o","pos":"Verb","thayer":"<ol><li>to go away into foreign parts, go abroad</li></ol>","xlit":"apodēméō"},"G3026":{"kjv_def":"idle tale","lemma":"λῆρος","translit":"lēros","derivation":"apparently a primary word;","strongs_def":" twaddle, i.e. an incredible story","pron":"lay'-ros","pos":"Noun Masculine","thayer":"<ol><li>idle talk, nonsense</li></ol>","xlit":"lēros"},"G4513":{"derivation":"from G4514 (Ῥωμαῖος);","strongs_def":" Romaic, i.e. Latin","kjv_def":"Latin","translit":"Rhōmaïkós","lemma":"Ῥωμαϊκός","pron":"rho-mah-ee-kos'","pos":"Adjective","thayer":"<strong>Thayer Definition</strong>: Latin = \"of Rome's strength\"</p><ol><li>the language spoken by the Romans</li></ol>","xlit":"Rhōmaïkós"},"G2427":{"kjv_def":"make able (meet)","translit":"hikanóō","lemma":"ἱκανόω","derivation":"from G2425 (ἱκανός);","strongs_def":" to enable, i.e. qualify","pron":"hik-an-o'-o","pos":"Verb","thayer":"<ol><li>to make sufficient, render fit<ol type='a'><li>to equip one with adequate power to perform duties of one</li></ol></li></ol>","xlit":"hikanóō"},"G1392":{"derivation":"from G1391 (δόξα);","strongs_def":" to render (or esteem) glorious (in a wide application)","kjv_def":"(make) glorify(-ious), full of (have) glory, honour, magnify","lemma":"δοξάζω","translit":"doxázō","pron":"dox-ad'-zo","pos":"Verb","thayer":"<ol><li>to think, suppose, be of opinion</li><li>to praise, extol, magnify, celebrate</li><li>to honour, do honour to, hold in honour</li><li>to make glorious, adorn with lustre, clothe with splendour<ol type='a'><li>to impart glory to something, render it excellent</li><li>to make renowned, render illustrious<ol><li>to cause the dignity and worth of some person or thing to become manifest and acknowledged</li></ol></li></ol></li></ol>","xlit":"doxázō"},"G3705":{"strongs_def":" something gazed at, i.e. a spectacle (especially supernatural)","derivation":"from G3708 (ὁράω);","lemma":"ὅραμα","translit":"hórama","kjv_def":"sight, vision","pron":"hor'-am-ah","pos":"Noun Neuter","thayer":"<ol><li>that which is seen, spectacle</li><li>a sight divinely granted in an ecstasy or in a sleep, a vision</li></ol>","xlit":"hórama"},"G3976":{"derivation":"ultimately from G4228 (πούς);","strongs_def":" a shackle for the feet","kjv_def":"fetter","lemma":"πέδη","translit":"pédē","pron":"ped'-ay","pos":"Noun Feminine","thayer":"<ol><li>a fetter, shackle for the feet</li></ol>","xlit":"pédē"},"G3406":{"derivation":"from G3409 (μισθόω) and G591 (ἀποδίδωμι);","strongs_def":" a renumerator","kjv_def":"rewarder","translit":"misthapodótēs","lemma":"μισθαποδότης","pron":"mis-thap-od-ot'-ace","pos":"Noun Masculine","thayer":"<ol><li>one who pays wages, a rewarder</li></ol>","xlit":"misthapodótēs"},"G613":{"derivation":"from G575 (ἀπό) and G2928 (κρύπτω);","strongs_def":" to conceal away (i.e. fully); figuratively, to keep secret","kjv_def":"hide","lemma":"ἀποκρύπτω","translit":"apokrýptō","pron":"ap-ok-roop'-to","pos":"Verb","thayer":"<ol><li>to hide</li><li>concealing, keeping secret</li></ol>","xlit":"apokrýptō"},"G1327":{"lemma":"διέξοδος","translit":"diéxodos","kjv_def":"highway","strongs_def":" an outlet through, i.e. probably an open square (from which roads diverge)","derivation":"from G1223 (διά) and G1841 (ἔξοδος);","pron":"dee-ex'-od-os","pos":"Noun Feminine","thayer":"<ol><li>a way out through, outlet, exit<ol type='a'><li>literally the ways through which ways go out</li><li>the places before the city where the roads from the country terminate, therefore outlets of the country highways, also entrances into the city</li><li>of boundaries of countries</li></ol></li></ol>","xlit":"diéxodos"},"G712":{"derivation":"apparently neuter of a superlative from the same as G730 (ἄῤῥην);","strongs_def":" the best meal (or breakfast; perhaps from (\"early\")), i.e. luncheon","kjv_def":"dinner","translit":"áriston","lemma":"ἄριστον","pron":"ar'-is-ton","pos":"Noun Neuter","thayer":"<ol><li>the first food taken early in the morning before work, breakfast</li><li>later usage: dinner</li></ol>","xlit":"áriston"},"G2243":{"strongs_def":" Helias (i.e. Elijah), an Israelite","derivation":"of Hebrew origin (H0452);","lemma":"Ἡλίας","translit":"Hēlías","kjv_def":"Elias","pron":"hay-lee'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Elijah = \"my God is Jehovah\"</p><ol><li>a prophet born at Thisbe, the unflinching champion of the theocracy in the reigns of the idolatrous kings Ahab and Ahaziah. He was taken up to heaven without dying, whence the Jews expected he would return just before the advent of the Messiah, whom he would prepare the minds of the Israelites to receive.</li></ol>","xlit":"Hēlías"},"G2901":{"strongs_def":" to empower, i.e. (passively) increase in vigor","derivation":"from G2900 (κραταιός);","lemma":"κραταιόω","translit":"krataióō","kjv_def":"be strengthened, be (wax) strong","pron":"krat-ah-yo'-o","pos":"Verb","thayer":"<ol><li>to strengthen, make strong</li><li>to be made strong, to increase in strength, to grow strong</li></ol>","xlit":"krataióō"},"G3666":{"kjv_def":"be (make) like, (in the) liken(-ess), resemble","lemma":"ὁμοιόω","translit":"homoióō","derivation":"from G3664 (ὅμοιος);","strongs_def":" to assimilate, i.e. compare; passively, to become similar","pron":"hom-oy-o'-o","pos":"Verb","thayer":"<ol><li>to be made like</li><li>to liken, compare<ol type='a'><li>illustrate by comparisons</li></ol></li></ol>","xlit":"homoióō"},"G247":{"kjv_def":"otherwise","translit":"állōs","lemma":"ἄλλως","derivation":"adverb from G243 (ἄλλος);","strongs_def":" differently","pron":"al'-loce","pos":"Adverb","thayer":"<ol><li>otherwise</li></ol>","xlit":"állōs"},"G4045":{"lemma":"περιπίπτω","translit":"peripíptō","kjv_def":"fall among (into)","strongs_def":" to fall into something that is all around, i.e. light among or upon, be surrounded with","derivation":"from G4012 (περί) and G4098 (πίπτω);","pron":"per-ee-pip'-to","pos":"Verb","thayer":"<ol><li>so to fall into as to be encompassed</li></ol>","xlit":"peripíptō"},"G2320":{"strongs_def":" divinity (abstractly)","derivation":"from G2316 (θεός);","translit":"theótēs","lemma":"θεότης","kjv_def":"godhead","pron":"theh-ot'-ace","pos":"Noun Feminine","thayer":"<ol><li>deity<ol type='a'><li>the state of being God, Godhead</li></ol></li></ol>","xlit":"theótēs"},"G1797":{"derivation":"middle voice from G1798 (ἐνύπνιον);","strongs_def":" to dream","kjv_def":"dream(-er)","translit":"enypniázomai","lemma":"ἐνυπνιάζομαι","pron":"en-oop-nee-ad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to dream (divinely suggested) dreams</li><li>metaphorically, to be beguiled with sensual images and carried away to an impious course of conduct</li></ol>","xlit":"enypniázomai"},"G1676":{"kjv_def":"Greek","lemma":"Ἑλληνιστί","translit":"Hellēnistí","derivation":"adverb from the same as G1675 (Ἑλληνιστής);","strongs_def":" Hellenistically, i.e. in the Grecian language","pron":"hel-lay-nis-tee'","pos":"Adverb","thayer":"<ol><li>in Greek, the Greek language</li></ol>","xlit":"Hellēnistí"},"G832":{"derivation":"from G836 (αὐλός);","strongs_def":" to play the flute","kjv_def":"pipe","translit":"auléō","lemma":"αὐλέω","pron":"ow-leh'-o","pos":"Verb","thayer":"<ol><li>to play on the flute, to pipe</li></ol>","xlit":"auléō"},"G3859":{"translit":"paradiatribḗ","lemma":"παραδιατριβή","kjv_def":"perverse disputing","strongs_def":" misemployment, i.e. meddlesomeness","derivation":"from a compound of G3844 (παρά) and G1304 (διατρίβω);","pron":"par-ad-ee-at-ree-bay'","pos":"Noun Feminine","thayer":"<ol><li>useless occupation, empty business, misemployment</li></ol>","xlit":"paradiatribḗ"},"G3692":{"kjv_def":"cave, place","lemma":"ὀπή","translit":"opḗ","derivation":"probably from G3700 (ὀπτάνομαι);","strongs_def":" a hole (as if for light), i.e. cavern; by analogy, a spring (of water)","pron":"op-ay'","pos":"Noun Feminine","thayer":"<ol><li>through which one can see, an opening, an aperture<ol type='a'><li>of a window</li><li>of fissures in the earth</li><li>of caves in rocks or mountains, holes</li></ol></li></ol>","xlit":"opḗ"},"G5007":{"derivation":"neuter of a presumed derivative of the original form of (to bear;","strongs_def":" equivalent to G5342 (φέρω)); a balance (as supporting weights), i.e. (by implication) a certain weight (and thence a coin or rather sum of money) or \"talent\"","kjv_def":"talent","lemma":"τάλαντον","translit":"tálanton","pron":"tal'-an-ton","pos":"Noun Neuter","thayer":"<ol><li>the scale of a balance, a balance, a pair of scales</li><li>that which is weighed, a talent<ol type='a'><li>a weight varying in different places and times</li><li>a sum of money weighing a talent and varying in different states and according to the changes in the laws regulating currency<ol><li>the Attic talent was equal to 60 Attic minae or 6000 drachmae</li><li>a talent of silver in Israel weighed about 100 pounds (45 kg)</li><li>a talent of gold in Israel weighed about 200 pounds (91 kg)</li></ol></li></ol></li></ol>","xlit":"tálanton"},"G298":{"lemma":"ἀμώμητος","translit":"amṓmētos","kjv_def":"blameless","strongs_def":" unblamable","derivation":"from G1 (Α) (as a negative particle) and a derivative of G3469 (μωμάομαι);","pron":"am-o'-may-tos","pos":"Adjective","thayer":"<ol><li>that cannot be censured, blameless</li></ol>","xlit":"amṓmētos"},"G1784":{"strongs_def":" valued (figuratively)","derivation":"from G1722 (ἐν) and G5092 (τιμή);","translit":"éntimos","lemma":"ἔντιμος","kjv_def":"dear, more honourable, precious, in reputation","pron":"en'-tee-mos","pos":"Adjective","thayer":"<ol><li>held in honour, prized, precious</li></ol>","xlit":"éntimos"},"G1407":{"derivation":"from (to pluck);","strongs_def":" a gathering hook (especially for harvesting)","kjv_def":"sickle","lemma":"δρέπανον","translit":"drépanon","pron":"drep'-an-on","pos":"Noun Neuter","thayer":"<ol><li>a sickle, a pruning-hook, a hooked vine knife, such as reapers and vinedressers use</li></ol>","xlit":"drépanon"},"G3032":{"strongs_def":" a Roman freedman","derivation":"of Latin origin;","lemma":"Λιβερτῖνος","translit":"Libertînos","kjv_def":"Libertine","pron":"lib-er-tee'-nos","pos":"Noun Masculine","thayer":"<ol><li>one who has been liberated from slavery, a freedman, or the son of a freed man</li><li>Libertine, denotes Jews (according to Philo) who had been made captives of the Romans under Pompey but were afterwards set free; and who although they had fixed their abode in Rome, had built at their own expense a synagogue at Jerusalem which they frequented when in that city, The name Libertines adhered to them to distinguish them from free born Jews who had subsequently taken up their residence at Rome. Evidence seems to have been discovered of the existence of a \"synagogue of the Libertines\" at Pompeii.</li></ol>","xlit":"Libertînos"},"G84":{"strongs_def":" uncertainly","derivation":"adverb from G82 (ἄδηλος);","lemma":"ἀδήλως","translit":"adḗlōs","kjv_def":"uncertainly","pron":"ad-ay'-loce","pos":"Adverb","thayer":"<ol><li>uncertainly</li></ol>","xlit":"adḗlōs"},"G2767":{"strongs_def":" to mingle, i.e. (by implication) to pour out (for drinking)","derivation":"prolonged form of a more primary (which is used in certain tenses);","lemma":"κεράννυμι","translit":"keránnymi","kjv_def":"fill, pour out","pron":"ker-an'-noo-mee","pos":"Verb","thayer":"<ol><li>to mix, mingle</li><li>to mix wine, water</li><li>to pour out for drinking.</li></ol>","xlit":"keránnymi"},"G363":{"strongs_def":" to remind; (reflexively) to recollect","derivation":"from G303 (ἀνά) and G3403 (μιμνήσκω);","translit":"anamimnḗskō","lemma":"ἀναμιμνήσκω","kjv_def":"call to mind, (bring to , call to, put in), remember(-brance)","pron":"an-am-im-nace'-ko","pos":"Verb","thayer":"<ol><li>to call to remembrance, to remind, to admonish</li><li>to remember, to remember and weigh well and consider</li></ol>","xlit":"anamimnḗskō"},"G4492":{"strongs_def":" to root (figuratively, become stable)","derivation":"from G4491 (ῥίζα);","translit":"rhizóō","lemma":"ῥιζόω","kjv_def":"root","pron":"hrid-zo'-o","pos":"Verb","thayer":"<ol><li>to cause to strike root, to strengthen with roots, to render firm, to fix, establish, cause a person or a thing to be thoroughly grounded</li></ol>","xlit":"rhizóō"},"G4323":{"lemma":"προσανατίθημι","translit":"prosanatíthēmi","kjv_def":"in conference add, confer","strongs_def":" to lay up in addition, i.e. (middle voice and figuratively) to impart or (by implication) to consult","derivation":"from G4314 (πρός) and G394 (ἀνατίθεμαι);","pron":"pros-an-at-ith'-ay-mee","pos":"Verb","thayer":"<ol><li>to lay upon in addition to</li><li>to lay upon one's self in addition<ol type='a'><li>to undertake besides</li><li>to put one's self upon another by going to him</li><li>to commit or betake one's self to another for the purpose of consulting him</li><li>to consult, to take one into counsel</li><li>to add from one's store</li></ol><li>to communicate, impart</li></ol>","xlit":"prosanatíthēmi"},"G431":{"strongs_def":" properly, akin, i.e. (specially) a cousin","derivation":"from G1 (Α) (as a particle of union) and an obsolete (a brood);","lemma":"ἀνεψιός","translit":"anepsiós","kjv_def":"sister's son","pron":"an-eps'-ee-os","pos":"Noun Masculine","thayer":"<ol><li>a cousin</li></ol>","xlit":"anepsiós"},"G1311":{"derivation":"from G1225 (διαβάλλω) and G5351 (φθείρω);","strongs_def":" to rot thoroughly, i.e. (by implication) to ruin (passively, decay utterly, figuratively, pervert)","kjv_def":"corrupt, destroy, perish","translit":"diaphtheírō","lemma":"διαφθείρω","pron":"dee-af-thi'-ro","pos":"Verb","thayer":"<ol><li>to change for the worse, to corrupt<ol type='a'><li>of minds, morals</li></ol><li>to destroy, ruin<ol type='a'><li>to consume<ol><li>of bodily vigour and strength</li><li>of the worm or moth that eats provisions, clothing, etc.</li></ol><li>to destroy, to kill</li></ol></li></ol>","xlit":"diaphtheírō"},"G4229":{"kjv_def":"business, matter, thing, work","translit":"prâgma","lemma":"πρᾶγμα","derivation":"from G4238 (πράσσω);","strongs_def":" a deed; by implication, an affair; by extension, an object (material)","pron":"prag'-mah","pos":"Noun Neuter","thayer":"<ol><li>that which has been done, a deed, an accomplished fact</li><li>what is done or being accomplished<ol type='a'><li>spec. business, a commercial transaction</li></ol><li>a matter, question, affair<ol type='a'><li>spec. in a forensic sense, a matter at law, case, suit</li></ol><li>that which is or exists, a thing</li></ol>","xlit":"prâgma"},"G158":{"kjv_def":"cause, fault","lemma":"αἴτιον","translit":"aítion","derivation":"neuter of G159 (αἴτιος);","strongs_def":" a reason or crime (like G156 (αἰτία))","pron":"ah'-ee-tee-on","pos":"Noun Neuter","thayer":"<ol><li>cause, fault</li></ol>","xlit":"aítion"},"G35":{"derivation":"from G1 (Α) (as negative particle) and G1075 (γενεαλογέω);","strongs_def":" unregistered as to birth","kjv_def":"without descent","lemma":"ἀγενεαλόγητος","translit":"agenealógētos","pron":"ag-en-eh-al-og'-ay-tos","pos":"Adjective","thayer":"<ol><li>one whose descent there is no record of, without genealogy</li></ol>","xlit":"agenealógētos"},"G3326":{"kjv_def":"after(-ward), X that he again, against, among, X and, + follow, hence, hereafter, in, of, (up-)on, + our, X and setting, since, (un-)to, + together, when, with (+ -out)","lemma":"μετά","translit":"metá","derivation":"a primary preposition (often used adverbially);","strongs_def":" properly, denoting accompaniment; \"amid\" (local or causal); modified variously according to the case (genitive association, or accusative succession) with which it is joined; occupying an intermediate position between G575 (ἀπό) or G1537 (ἐκ) and G1519 (εἰς) or G4314 (πρός); less intimate than G1722 (ἐν) and less close than G4862 (σύν))","pron":"met-ah'","pos":"Preposition","thayer":"<ol><li>with, after, behind</li></ol>","xlit":"metá"},"G4246":{"strongs_def":" an old man","derivation":"from the same as G4245 (πρεσβύτερος);","translit":"presbýtēs","lemma":"πρεσβύτης","kjv_def":"aged (man), old man","pron":"pres-boo'-tace","pos":"Noun Masculine","thayer":"<ol><li>an old man, an aged man</li><li>ambassador</li></ol>","xlit":"presbýtēs"},"G4930":{"kjv_def":"end","lemma":"συντέλεια","translit":"syntéleia","derivation":"from G4931 (συντελέω);","strongs_def":" entire completion, i.e. consummation (of a dispensation)","pron":"soon-tel'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>completion, consummation, end</li></ol>","xlit":"syntéleia"},"G448":{"derivation":"from G1 (Α) (as a negative particle) and G2436 (ἵλεως);","strongs_def":" inexorable","kjv_def":"without mercy","translit":"aníleōs","lemma":"ἀνίλεως","pron":"an-ee'-leh-oce","pos":"Adjective","thayer":"<ol><li>without mercy, merciless</li></ol>","xlit":"aníleōs"},"G5611":{"translit":"hōraîos","lemma":"ὡραῖος","kjv_def":"beautiful","strongs_def":" belonging to the right hour or season (timely), i.e. (by implication) flourishing (beauteous (figuratively))","derivation":"from G5610 (ὥρα);","pron":"ho-rah'-yos","pos":"Adjective","thayer":"<ol><li>blooming, beautiful (used of the human body)</li></ol>","xlit":"hōraîos"},"G1485":{"kjv_def":"custom, manner, be wont","lemma":"ἔθος","translit":"éthos","derivation":"from G1486 (ἔθω);","strongs_def":" a usage (prescribed by habit or law)","pron":"eth'-os","pos":"Noun Neuter","thayer":"<ol><li>custom</li><li>usage prescribed by law, institute, prescription, rite</li></ol>","xlit":"éthos"},"G4971":{"strongs_def":" very much","derivation":"adverb from the same as G4970 (σφόδρα);","translit":"sphodrōs","lemma":"σφοδρῶς","kjv_def":"exceedingly","pron":"sfod-roce'","pos":"Adverb","thayer":"<ol><li>exceedingly</li></ol>","xlit":"sphodrōs"},"G545":{"strongs_def":" unpersuadable, i.e. contumacious","derivation":"from G1 (Α) (as a negative particle) and G3982 (πείθω);","translit":"apeithḗs","lemma":"ἀπειθής","kjv_def":"disobedient","pron":"ap-i-thace'","pos":"Adjective","thayer":"<ol><li>impersuasible, not compliant, disobedient, contumacious</li></ol>","xlit":"apeithḗs"},"G2860":{"strongs_def":" to plunge into water","derivation":"from (a diver);","translit":"kolymbáō","lemma":"κολυμβάω","kjv_def":"swim","pron":"kol-oom-bah'-o","pos":"Verb","thayer":"<ol><li>to dive, to swim</li></ol>","xlit":"kolymbáō"},"G4525":{"kjv_def":"move","translit":"saínō","lemma":"σαίνω","derivation":"akin to G4579 (σείω);","strongs_def":" to wag (as a dog its tail fawningly), i.e. (generally) to shake (figuratively, disturb)","pron":"sah'-ee-no","pos":"Verb","thayer":"<ol><li>to wag the tail<ol type='a'><li>of dogs</li></ol><li>metaphorically<ol type='a'><li>to flatter, fawn upon</li><li>to move (the mind of one)<ol><li>agreeably</li><li>to agitate, disturb, trouble</li></ol></li></ol></li></ol>","xlit":"saínō"},"G809":{"derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G2192 (ἔχω) (in the sense of its congener G4976 (σχῆμα));","strongs_def":" properly, shapeless, i.e. (figuratively) inelegant","kjv_def":"uncomely","translit":"aschḗmōn","lemma":"ἀσχήμων","pron":"as-kay'-mone","pos":"Adjective","thayer":"<ol><li>deformed</li><li>indecent, unseemly</li></ol>","xlit":"aschḗmōn"},"G4138":{"kjv_def":"which is put in to fill up, piece that filled up, fulfilling, full, fulness","translit":"plḗrōma","lemma":"πλήρωμα","derivation":"from G4137 (πληρόω);","strongs_def":" repletion or completion, i.e. (subjectively) what fills (as contents, supplement, copiousness, multitude), or (objectively) what is filled (as container, performance, period)","pron":"play'-ro-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is (has been) filled<ol type='a'><li>a ship inasmuch as it is filled (i.e. manned) with sailors, rowers, and soldiers</li><li>in the NT, the body of believers, as that which is filled with the presence, power, agency, riches of God and of Christ</li></ol><li>that which fills or with which a thing is filled<ol type='a'><li>of those things which a ship is filled, freight and merchandise, sailors, oarsmen, soldiers</li><li>completeness or fulness of time</li></ol><li>fulness, abundance</li><li>a fulfilling, keeping</li></ol>","xlit":"plḗrōma"},"G1748":{"strongs_def":" to lurk, i.e. (figuratively) plot assassination","derivation":"from G1747 (ἐνέδρα);","lemma":"ἐνεδρεύω","translit":"enedreúō","kjv_def":"lay wait for","pron":"en-ed-ryoo'-o","pos":"Verb","thayer":"<ol><li>to lie in wait for, to lay wait for, prepare a trap for</li></ol>","xlit":"enedreúō"},"G3554":{"strongs_def":" a malady (rarely figuratively, of moral disability)","derivation":"of uncertain affinity;","lemma":"νόσος","translit":"nósos","kjv_def":"disease, infirmity, sickness","pron":"nos'-os","pos":"Noun Feminine","thayer":"<ol><li>disease, sickness</li></ol>","xlit":"nósos"},"G4222":{"lemma":"ποτίζω","translit":"potízō","kjv_def":"give (make) to drink, feed, water","strongs_def":" to furnish drink, irrigate","derivation":"from a derivative of the alternate of G4095 (πίνω);","pron":"pot-id'-zo","pos":"Verb","thayer":"<ol><li>to give to drink, to furnish drink</li><li>to water, irrigate (plants, fields etc.)</li><li>metaphorically to imbue, saturate one's mind</li></ol>","xlit":"potízō"},"G456":{"strongs_def":" to rebuild","derivation":"from G303 (ἀνά) and G3618 (οἰκοδομέω);","translit":"anoikodoméō","lemma":"ἀνοικοδομέω","kjv_def":"build again","pron":"an-oy-kod-om-eh'-o","pos":"Verb","thayer":"<ol><li>to build again</li></ol>","xlit":"anoikodoméō"},"G2795":{"kjv_def":"(re-)move(-r), way","lemma":"κινέω","translit":"kinéō","derivation":"from (poetic for , to go);","strongs_def":" to stir (transitively), literally or figuratively","pron":"kin-eh'-o","pos":"Verb","thayer":"<ol><li>to cause to go, i.e. to move, set in motion<ol type='a'><li>to be moved, move: of that motion which is evident in life</li><li>to move from a place, to remove</li></ol><li>metaphorically<ol type='a'><li>to move excite</li><li>a riot, disturbance</li><li>to throw into commotion</li></ol></li></ol>","xlit":"kinéō"},"G2053":{"kjv_def":"wool","translit":"érion","lemma":"ἔριον","derivation":"of obscure affinity;","strongs_def":" wool","pron":"er'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>wool</li></ol>","xlit":"érion"},"G1931":{"kjv_def":"go down","translit":"epidýō","lemma":"ἐπιδύω","derivation":"from G1909 (ἐπί) and G1416 (δύνω);","strongs_def":" to set fully (as the sun)","pron":"ep-ee-doo'-o","pos":"Verb","thayer":"<ol><li>to go down, set (of the sun)</li></ol>","xlit":"epidýō"},"G3813":{"derivation":"neuter diminutive of G3816 (παῖς);","strongs_def":" a childling (of either sex), i.e. (properly), an infant, or (by extension) a half-grown boy or girl; figuratively, an immature Christian","kjv_def":"(little, young) child, damsel","translit":"paidíon","lemma":"παιδίον","pron":"pahee-dee'-on","pos":"Noun Neuter","thayer":"<ol><li>a young child, a little boy, a little girl<ol type='a'><li>infants</li><li>children, little ones</li><li>an infant<ol><li>of a (male) child just recently born</li></ol><li>of a more advanced child; of a mature child</li><li>metaphorically children (like children) in intellect</li></ol></li></ol>","xlit":"paidíon"},"G5006":{"strongs_def":" talent-like in weight","derivation":"from G5007 (τάλαντον);","translit":"talantiaîos","lemma":"ταλαντιαῖος","kjv_def":"weight of a talent","pron":"tal-an-tee-ah'-yos","pos":"Adjective","thayer":"<ol><li>a weight or worth of a talent<ol type='a'><li>a talent of silver weighed about 100 pounds (45 kg)</li><li>a talent of gold, 200 pounds (91 kg)</li></ol></li></ol>","xlit":"talantiaîos"},"G4370":{"strongs_def":" to run towards, i.e. hasten to meet or join","derivation":"from G4314 (πρός) and G5143 (τρέχω) (including its alternate);","lemma":"προστρέχω","translit":"prostréchō","kjv_def":"run (thither to, to)","pron":"pros-trekh'-o","pos":"Verb","thayer":"<ol><li>to run to</li></ol>","xlit":"prostréchō"},"G1160":{"derivation":"from (to devour);","strongs_def":" expense (as consuming)","kjv_def":"cost","translit":"dapánē","lemma":"δαπάνη","pron":"dap-an'-ay","pos":"Noun Feminine","thayer":"<ol><li>expense, cost</li></ol>","xlit":"dapánē"},"G5545":{"kjv_def":"anointing, unction","lemma":"χρῖσμα","translit":"chrîsma","derivation":"from G5548 (χρίω);","strongs_def":" an unguent or smearing, i.e. (figuratively) the special endowment (\"chrism\") of the Holy Spirit","pron":"khris'-mah","pos":"Noun Neuter","thayer":"<ol><li>anything smeared on, unguent, ointment, usually prepared by the Hebrews from oil and aromatic herbs. Anointing was the inaugural ceremony for priests</li></ol>","xlit":"chrîsma"},"G3543":{"kjv_def":" suppose, thing, be wont","lemma":"νομίζω","translit":"nomízō","derivation":"from G3551 (νόμος);","strongs_def":" properly, to do by law (usage), i.e. to accustom (passively, be usual); by extension, to deem or regard","pron":"nom-id'-zo","pos":"Verb","thayer":"<ol><li>to hold by custom or usage, own as a custom or usage, to follow a custom or usage<ol type='a'><li>it is the custom, it is the received usage</li></ol><li>to deem, think, suppose</li></ol>","xlit":"nomízō"},"G972":{"lemma":"βίαιος","translit":"bíaios","kjv_def":"mighty","strongs_def":" violent","derivation":"from G970 (βία);","pron":"bee'-ah-yos","pos":"Adjective","thayer":"<ol><li>violent, forcible</li></ol>","xlit":"bíaios"},"G5606":{"derivation":"perhaps from the alternate of G5342 (φέρω);","strongs_def":" the shoulder (as that on which burdens are borne)","kjv_def":"shoulder","translit":"ōmos","lemma":"ὦμος","pron":"o'-mos","pos":"Noun Masculine","thayer":"<ol><li>a shoulder</li></ol>","xlit":"ōmos"},"G4286":{"lemma":"πρόθεσις","translit":"próthesis","kjv_def":"purpose, shew(-bread)","strongs_def":" a setting forth, i.e. (figuratively) proposal (intention); specially, the show-bread (in the Temple) as exposed before God","derivation":"from G4388 (προτίθεμαι);","pron":"proth'-es-is","pos":"Noun Feminine","thayer":"<ol><li>a setting forth of a thing, placing of it in view, the shewbread<ol type='a'><li>twelve loaves of wheaten bread, corresponding to the number of the tribes of Israel, which loaves were offered to God every Sabbath, and separated into two rows, lay for seven days upon a table placed in the sanctuary or front portion of the tabernacle, and afterwards of the temple</li></ol><li>a purpose</li></ol>","xlit":"próthesis"},"G5409":{"translit":"phoréō","lemma":"φορέω","kjv_def":"bear, wear","strongs_def":" to have a burden, i.e. (by analogy) to wear as clothing or a constant accompaniment","derivation":"from G5411 (φόρος);","pron":"for-eh'-o","pos":"Verb","thayer":"<ol><li>to bear constantly, wear<ol type='a'><li>of clothing, garments, armour</li></ol></li></ol>","xlit":"phoréō"},"G3695":{"strongs_def":" to equip (with weapons (middle voice and figuratively))","derivation":"from G3696 (ὅπλον);","translit":"hoplízō","lemma":"ὁπλίζω","kjv_def":"arm self","pron":"hop-lid'-zo","pos":"Verb","thayer":"<ol><li>to arm, furnish with arms</li><li>to provide</li><li>to furnish one's self with a thing (as with arms)</li><li>metaphorically take on the same mind</li></ol>","xlit":"hoplízō"},"G696":{"strongs_def":" silver (the metal, in the articles or coin)","derivation":"from (shining);","translit":"árgyros","lemma":"ἄργυρος","kjv_def":"silver","pron":"ar'-goo-ros","pos":"Noun Masculine","thayer":"<ol><li>silver<ol type='a'><li><a class='bible' href='#b46.3.12'>1Co 3:12</a> refers to the silver with which the columns of noble buildings were covered and the rafters adorned</li><li>things made of silver<ol><li>vessels</li><li>images of gods</li></ol></li></ol></li></ol>","xlit":"árgyros"},"G3728":{"strongs_def":" asseveration on oath","derivation":"from a compound of G3727 (ὅρκος) and a derivative of G3660 (ὀμνύω);","translit":"horkōmosía","lemma":"ὁρκωμοσία","kjv_def":"oath","pron":"hor-ko-mos-ee'ah","pos":"Noun Feminine","thayer":"<ol><li>affirmation made on oath, the taking of an oath, an oath</li></ol>","xlit":"horkōmosía"},"G1866":{"translit":"Epaínetos","lemma":"Ἐπαίνετος","kjv_def":"Epenetus","strongs_def":" praised; Epænetus, a Christian","derivation":"from G1867 (ἐπαινέω);","pron":"ep-a'-hee-net-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Epaenetus = \"praiseworthy\"</p><ol><li>a Christian at Rome, greeted by the Paul in <a class='bible' href='#b45.16.5'>Rom 16:5</a></li></ol>","xlit":"Epaínetos"},"G3093":{"kjv_def":"Magdala","lemma":"Μαγδαλά","translit":"Magdalá","derivation":"of Chaldee origin (compare H04026);","strongs_def":" the tower; Magdala (i.e. Migdala), a place in Palestine","pron":"mag-dal-ah'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Magdala = \"a tower\"</p><ol><li>a place on the western shore of the Lake of Galilee, about 3 miles</li></ol>","xlit":"Magdalá"},"G4556":{"derivation":"properly, an adjective from an uncertain base;","strongs_def":" sardian (3037 being implied), i.e. (as noun) the gem so called","kjv_def":"sardius","translit":"sárdios","lemma":"σάρδιος","pron":"sar'-dee-os","pos":"Adjective","thayer":"<ol><li>a sardius, a precious stone of which there are two types, the former is called a carnelian (because flesh coloured) and the latter a sard</li></ol>","xlit":"sárdios"},"G1158":{"strongs_def":" Daniel, an Israelite","derivation":"of Hebrew origin (H01840);","translit":"Daniḗl","lemma":"Δανιήλ","kjv_def":"Daniel","pron":"dan-ee-ale'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Daniel = \"judgment of God\"</p><ol><li>the name of a Jewish prophet, noted for his wisdom and prophecies</li></ol>","xlit":"Daniḗl"},"G2428":{"translit":"hiketēría","lemma":"ἱκετηρία","kjv_def":"supplication","strongs_def":" intreaty","derivation":"from a derivative of the base of G2425 (ἱκανός) (through the idea of approaching for a favor);","pron":"hik-et-ay-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>an olive branch<ol type='a'><li>for suppliants approached the one whose aid they would implore holding an olive branch entwined with white wool and fillets, to signify that they came as suppliants</li></ol><li>supplication</li></ol>","xlit":"hiketēría"},"G2109":{"kjv_def":"do good","lemma":"εὐεργετέω","translit":"euergetéō","derivation":"from G2110 (εὐεργέτης);","strongs_def":" to be philanthropic","pron":"yoo-erg-et-eh'-o","pos":"Verb","thayer":"<ol><li>to do good, bestow benefits</li></ol>","xlit":"euergetéō"},"G3376":{"strongs_def":" a month","derivation":"a primary word;","translit":"mḗn","lemma":"μήν","kjv_def":"month","pron":"mane","pos":"Noun Masculine","thayer":"<ol><li>a month</li><li>the time of the new moon, new moon (the first day of each month, when the new moon appeared was a festival among the Hebrews)</li></ol>","xlit":"mḗn"},"G744":{"derivation":"from G746 (ἀρχή);","strongs_def":" original or primeval","kjv_def":"(them of) old (time)","lemma":"ἀρχαῖος","translit":"archaîos","pron":"ar-khah'-yos","pos":"Adjective","thayer":"<ol><li>that has been from the beginning, original, primal, old ancient<ol type='a'><li>of men, things, times, conditions</li></ol></li></ol>","xlit":"archaîos"},"G4891":{"derivation":"from G4862 (σύν) and G1453 (ἐγείρω);","strongs_def":" to rouse (from death) in company with, i.e. (figuratively) to revivify (spirtually) in resemblance to","kjv_def":"raise up together, rise with","lemma":"συνεγείρω","translit":"synegeírō","pron":"soon-eg-i'-ro","pos":"Verb","thayer":"<ol><li>to raise together, to cause to raise together</li><li>to raise up together from mortal death to a new and blessed life dedicated to God</li></ol>","xlit":"synegeírō"},"G5248":{"strongs_def":" to super-abound","derivation":"from G5228 (ὑπέρ) and G4052 (περισσεύω);","translit":"hyperperisseúō","lemma":"ὑπερπερισσεύω","kjv_def":"abound much more, exceeding","pron":"hoop-er-per-is-syoo'-o","pos":"Verb","thayer":"<ol><li>to abound beyond measure, abound exceedingly</li><li>to overflow, to enjoy abundantly</li></ol>","xlit":"hyperperisseúō"},"G967":{"strongs_def":" fig-house; Beth-phage, a place in Palestine","derivation":"of Chaldee origin (compare H01004 and H06291);","lemma":"Βηθφαγή","translit":"Bēthphagḗ","kjv_def":"Bethphage","pron":"bayth-fag-ay'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Bethphage = \"house of unripe figs\"</p><ol><li>the name of a hamlet between Jericho and Jerusalem, close to Bethany</li></ol>","xlit":"Bēthphagḗ"},"G1618":{"strongs_def":" intent","derivation":"from G1614 (ἐκτείνω);","lemma":"ἐκτενής","translit":"ektenḗs","kjv_def":"without ceasing, fervent","pron":"ek-ten-ace'","pos":"Adjective","thayer":"<ol><li>stretched out</li><li>metaphorically intent, earnestly, assiduously</li></ol>","xlit":"ektenḗs"},"G5452":{"translit":"phyteúō","lemma":"φυτεύω","kjv_def":"plant","strongs_def":" to set out in the earth, i.e. implant; figuratively, to instil doctrine","derivation":"from a derivative of G5453 (φύω);","pron":"foot-yoo'-o","pos":"Verb","thayer":"<ol><li>to plant</li></ol>","xlit":"phyteúō"},"G3456":{"derivation":"from a derivative of the base of G3455 (μυκάομαι) (meaning snout, as that whence lowing proceeds);","strongs_def":" to make mouths at, i.e. ridicule","kjv_def":"mock","translit":"myktērízō","lemma":"μυκτηρίζω","pron":"mook-tay-rid'-zo","pos":"Verb","thayer":"<ol><li>to turn up the nose or sneer at</li><li>to mock, deride</li></ol>","xlit":"myktērízō"},"G1838":{"kjv_def":"use","translit":"héxis","lemma":"ἕξις","derivation":"from G2192 (ἔχω);","strongs_def":" habit, i.e. (by implication) practice","pron":"hex'-is","pos":"Noun Feminine","thayer":"<ol><li>a habit whether of body or mind</li><li>a power acquired by custom, practice, use</li></ol>","xlit":"héxis"},"G693":{"derivation":"from G696 (ἄργυρος);","strongs_def":" made of silver","kjv_def":"(of) silver","lemma":"ἀργύρεος","translit":"argýreos","pron":"ar-goo'-reh-os","pos":"Adjective","thayer":"<ol><li>of silver, silvery</li></ol>","xlit":"argýreos"},"G3359":{"kjv_def":"forehead","translit":"métōpon","lemma":"μέτωπον","derivation":"from G3326 (μετά) and ops (the face);","strongs_def":" the forehead (as opposite the countenance)","pron":"met'-o-pon","pos":"Noun Neuter","thayer":"<ol><li>the space between the eyes, the forehead</li></ol>","xlit":"métōpon"},"G586":{"kjv_def":"(give, pay, take) tithe","translit":"apodekatóō","lemma":"ἀποδεκατόω","derivation":"from G575 (ἀπό) and G1183 (δεκατόω);","strongs_def":" to tithe (as debtor or creditor)","pron":"ap-od-ek-at-o'-o","pos":"Verb","thayer":"<ol><li>to give, pay a tithe of anything</li><li>to exact receive a tenth from anyone</li></ol>","xlit":"apodekatóō"},"G699":{"kjv_def":"pleasing","translit":"areskeía","lemma":"ἀρεσκεία","derivation":"from a derivative of G700 (ἀρέσκω);","strongs_def":" complaisance","pron":"ar-es'-ki-ah","pos":"Noun Feminine","thayer":"<ol><li>desire to please</li></ol>","xlit":"areskeía"},"G5576":{"derivation":"from G5575 (ψευδομάρτυρ);","strongs_def":" to be an untrue testifier, i.e. offer falsehood in evidence","kjv_def":"be a false witness","lemma":"ψευδομαρτυρέω","translit":"pseudomartyréō","pron":"psyoo-dom-ar-too-reh'-o","pos":"Verb","thayer":"<ol><li>to utter falsehoods in giving testimony, to testify falsely, to bear false witness</li></ol>","xlit":"pseudomartyréō"},"G2931":{"lemma":"κρυφῆ","translit":"kryphē","kjv_def":"in secret","strongs_def":" privately","derivation":"adverb from G2928 (κρύπτω);","pron":"kroo-fay'","pos":"Adverb","thayer":"<ol><li>secretly, in secret</li></ol>","xlit":"kryphē"},"G1384":{"strongs_def":" properly, acceptable (current after assayal), i.e. approved","derivation":"from G1380 (δοκέω);","lemma":"δόκιμος","translit":"dókimos","kjv_def":"approved, tried","pron":"dok'-ee-mos","pos":"Adjective","thayer":"<ol><li>accepted, particularly of coins and money.</li><li>accepted, pleasing, acceptable</li></ol>","xlit":"dókimos"},"G2265":{"strongs_def":" Herodians, i.e. partisans of Herod","derivation":"plural of a derivative of G2264 (Ἡρώδης);","lemma":"Ἡρωδιανοί","translit":"Hērōdianoí","kjv_def":"Herodians","pron":"hay-ro-dee-an-oy'","pos":"Noun Masculine","thayer":"<ol><li>Herodians, i.e. Herod's partisans. See note on <u><a class='dict' href='#sG2264'>G2264</a></u>.</li></ol>","xlit":"Hērōdianoí"},"G694":{"derivation":"neuter of a presumed derivative of G696 (ἄργυρος);","strongs_def":" silvery, i.e. (by implication) cash; specially, a silverling (i.e. drachma or shekel)","kjv_def":"money, (piece of) silver (piece)","lemma":"ἀργύριον","translit":"argýrion","pron":"ar-goo'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>silver</li><li>money</li><li>a silver coin, silver piece, a shekel</li></ol>","xlit":"argýrion"},"G2547":{"derivation":"from G2532 (καί) and G1564 (ἐκεῖθεν);","strongs_def":" likewise from that place (or time)","kjv_def":"and afterward (from) (thence), thence also","lemma":"κἀκεῖθεν","translit":"kakeîthen","pron":"kak-i'-then","pos":"Adverb","thayer":"<ol><li>of place<ol type='a'><li>and from thence, and thence</li></ol><li>of time<ol type='a'><li>and thereafter, and afterward</li></ol></li></ol>","xlit":"kakeîthen"},"G1539":{"kjv_def":"always","lemma":"ἑκάστοτε","translit":"hekástote","derivation":"as if from G1538 (ἕκαστος) and G5119 (τότε);","strongs_def":" at every time","pron":"hek-as'-tot-eh","pos":"Adverb","thayer":"<ol><li>at every time, always</li></ol>","xlit":"hekástote"},"G3316":{"strongs_def":" a go-between, i.e. (simply) an internunciator, or (by implication) a reconciler (intercessor)","derivation":"from G3319 (μέσος);","translit":"mesítēs","lemma":"μεσίτης","kjv_def":"mediator","pron":"mes-ee'-tace","pos":"Noun Masculine","thayer":"<ol><li>one who intervenes between two, either in order to make or restore peace and friendship, or form a compact, or for ratifying a covenant</li><li>a medium of communication, arbitrator</li></ol>","xlit":"mesítēs"},"G5095":{"kjv_def":"Timotheus, Timothy","lemma":"Τιμόθεος","translit":"Timótheos","derivation":"from G5092 (τιμή) and G2316 (θεός);","strongs_def":" dear to God; Timotheus, a Christian","pron":"tee-moth'-eh-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Timothy = \"honouring God\"</p><ol><li>a resident of Lystra, apparently, whose father was a Greek and mother a Jewess; he was Paul's travelling companion and fellow labourer</li></ol>","xlit":"Timótheos"},"G603":{"strongs_def":" intense anticipation","derivation":"from a comparative of G575 (ἀπό) and a compound of (the head) and G1380 (δοκέω) (in the sense of watching);","translit":"apokaradokía","lemma":"ἀποκαραδοκία","kjv_def":"earnest expectation","pron":"ap-ok-ar-ad-ok-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>anxious and persistent expectation</li></ol>","xlit":"apokaradokía"},"G2520":{"derivation":"from G2596 (κατά) and G2240 (ἥκω);","strongs_def":" to reach to, i.e. (neuter of present active participle, figuratively as adjective) becoming","kjv_def":" convenient, fit","translit":"kathḗkō","lemma":"καθήκω","pron":"kath-ay'-ko","pos":"Verb","thayer":"<ol><li>to come down</li><li>to come to, reach to<ol type='a'><li>it is becoming</li><li>it is fit</li></ol></li></ol>","xlit":"kathḗkō"},"G5034":{"derivation":"from the same as G5036 (ταχύς);","strongs_def":" a brief space (of time), i.e. (with G1722 (ἐν) prefixed) in haste","kjv_def":"+ quickly, + shortly, + speedily","translit":"táchos","lemma":"τάχος","pron":"takh'-os","pos":"Noun Neuter","thayer":"<ol><li>quickness, speed</li></ol>","xlit":"táchos"},"G1941":{"kjv_def":"appeal (unto), call (on, upon), surname","translit":"epikaléomai","lemma":"ἐπικαλέομαι","derivation":"middle voice from G1909 (ἐπί) and G2564 (καλέω);","strongs_def":" to entitle; by implication, to invoke (for aid, worship, testimony, decision, etc.)","pron":"ep-ee-kal-eh'-om-ahee","pos":"Verb","thayer":"<ol><li>to put a name upon, to surname<ol type='a'><li>to permit one's self to be surnamed</li></ol><li>to be named after someone</li><li>to call something to one<ol type='a'><li>to cry out upon or against one</li><li>to charge something to one as a crime or reproach</li><li>to summon one on any charge, prosecute one for a crime</li><li>to blame one for, accuse one of</li></ol><li>to invoke<ol type='a'><li>to call upon for one's self, in one's behalf<ol><li>any one as a helper</li><li>as my witness</li><li>as my judge</li><li>to appeal unto</li></ol></li></ol><li>to call upon by pronouncing the name of Jehovah<ol type='a'><li>an expression finding its explanation in the fact that prayers addressed to God ordinarily began with an invocation of the divine name</li></ol></li></ol>","xlit":"epikaléomai"},"G5592":{"derivation":"from G5594 (ψύχω);","strongs_def":" coolness","kjv_def":"cold","lemma":"ψύχος","translit":"psýchos","pron":"psoo'-khos","pos":"Noun Neuter","thayer":"<ol><li>cold</li></ol>","xlit":"psýchos"},"G3572":{"strongs_def":" to prick (\"nudge\")","derivation":"apparently a primary word;","translit":"nýssō","lemma":"νύσσω","kjv_def":"pierce","pron":"noos'-so","pos":"Verb","thayer":"<ol><li>pierce</li><li>to pierce through, transfix<ol type='a'><li>often of severe or even deadly wounds given one</li></ol></li></ol>","xlit":"nýssō"},"G3462":{"strongs_def":" to apply (perfumed) unguent to","derivation":"from G3464 (μύρον);","translit":"myrízō","lemma":"μυρίζω","kjv_def":"anoint","pron":"moo-rid'-zo","pos":"Verb","thayer":"<ol><li>to anoint</li></ol>","xlit":"myrízō"},"G559":{"derivation":"of Latin origin;","strongs_def":" Apelles, a Christian","kjv_def":"Apelles","lemma":"Ἀπελλῆς","translit":"Apellēs","pron":"ap-el-lace'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Apelles = \"called\"</p><ol><li>a certain Christian</li></ol>","xlit":"Apellēs"},"G3616":{"derivation":"from G3617 (οἰκοδεσπότης);","strongs_def":" to be the head of (i.e. rule) a family","kjv_def":"guide the house","translit":"oikodespotéō","lemma":"οἰκοδεσποτέω","pron":"oy-kod-es-pot-eh'-o","pos":"Verb","thayer":"<ol><li>to be master (or head) of a house</li><li>to rule a household, manage family affairs</li></ol>","xlit":"oikodespotéō"},"G4287":{"kjv_def":"time appointed","translit":"prothésmios","lemma":"προθέσμιος","derivation":"from G4253 (πρό) and a derivative of G5087 (τίθημι);","strongs_def":" fixed beforehand, i.e. (feminine with G2250 (ἡμέρα) implied) a designated day","pron":"proth-es'-mee-os","pos":"Adjective","thayer":"<ol><li>set beforehand, appointed or determined beforehand, prearranged</li></ol>","xlit":"prothésmios"},"G2596":{"derivation":"a primary particle;","strongs_def":" (prepositionally) down (in place or time), in varied relations (according to the case (genitive, dative or accusative) with which it is joined)","kjv_def":"about, according as (to), after, against, (when they were) X alone, among, and, X apart, (even, like) as (concerning, pertaining to touching), X aside, at, before, beyond, by, to the charge of, (charita-)bly, concerning, + covered, (dai-)ly, down, every, (+ far more) exceeding, X more excellent, for, from … to, godly, in(-asmuch, divers, every, -to, respect of), … by, after the manner of, + by any means, beyond (out of) measure, X mightily, more, X natural, of (up-)on (X part), out (of every), over against, (+ your) X own, + particularly, so, through(-oughout, -oughout every), thus, (un-)to(-gether, -ward), X uttermost, where(-by), with","lemma":"κατά","translit":"katá","pron":"kat-ah'","pos":"Preposition","thayer":"<ol><li>down from, through out</li><li>according to, toward, along</li></ol>","xlit":"katá"},"G952":{"translit":"bébēlos","lemma":"βέβηλος","kjv_def":"profane (person)","strongs_def":" accessible (as by crossing the door-way), i.e. (by implication, of Jewish notions) heathenish, wicked","derivation":"from the base of G939 (βάσις) and (a threshold);","pron":"beb'-ay-los","pos":"Adjective","thayer":"<ol><li>accessible, lawful to be trodden<ol type='a'><li>of places</li></ol><li>profane<ol type='a'><li>unhallowed, common, public place</li><li>of men, ungodly</li></ol></li></ol>","xlit":"bébēlos"},"G3303":{"kjv_def":"even, indeed, so, some, truly, verily","lemma":"μέν","translit":"mén","derivation":"a primary particle;","strongs_def":" properly, indicative of affirmation or concession (in fact); usually followed by a contrasted clause with G1161 (δέ) (this one, the former, etc.)","pron":"men","thayer":"<ol><li>truly, certainly, surely, indeed</li></ol>","xlit":"mén"},"G2858":{"strongs_def":" a Colossæan, (i.e. inhabitant of Colossæ","derivation":"from G2857 (Κολοσσαί);","translit":"Kolossaeús","lemma":"Κολοσσαεύς","kjv_def":"Colossian","pron":"kol-os-sayoos'","pos":"Noun Masculine","thayer":"<ol><li>a Colossian</li></ol>","xlit":"Kolossaeús"},"G576":{"strongs_def":" literally, to disembark; figuratively, to eventuate","derivation":"from G575 (ἀπό) and the base of G939 (βάσις);","translit":"apobaínō","lemma":"ἀποβαίνω","kjv_def":"become, go out, turn","pron":"ap-ob-ah'-ee-no","pos":"Verb","thayer":"<ol><li>to come down from, i.e. a ship</li><li>to turn out, result, to be the outcome</li></ol>","xlit":"apobaínō"},"G3957":{"derivation":"of Chaldee origin (compare H06453);","strongs_def":" the Passover (the meal, the day, the festival or the special sacrifices connected with it)","kjv_def":"Easter, Passover","translit":"páscha","lemma":"πάσχα","pron":"pas'-khah","pos":"Noun Neuter","thayer":"<ol><li>the paschal sacrifice (which was accustomed to be offered for the people's deliverance of old from Egypt)</li><li>the paschal lamb, i.e. the lamb the Israelites were accustomed to slay and eat on the fourteenth day of the month of Nisan (the first month of their year) in memory of the day on which their fathers, preparing to depart from Egypt, were bidden by God to slay and eat a lamb, and to sprinkle their door posts with its blood, that the destroying angel, seeing the blood, might pass over their dwellings; Christ crucified is likened to the slain paschal lamb</li><li>the paschal supper</li><li>the paschal feast, the feast of the Passover, extending from the 14th to the 20th day of the month Nisan</li></ol>","xlit":"páscha"},"G4440":{"strongs_def":" a gate-way, door-way of a building or city; by implication, a portal or vestibule","derivation":"from G4439 (πύλη);","lemma":"πυλών","translit":"pylṓn","kjv_def":"gate, porch","pron":"poo-lone'","pos":"Noun Masculine","thayer":"<ol><li>a large gate: of a palace</li><li>the front part of a house, into which one enters through the gate, porch</li></ol>","xlit":"pylṓn"},"G320":{"derivation":"from G314 (ἀναγινώσκω);","strongs_def":" (the act of) reading","kjv_def":"reading","translit":"anágnōsis","lemma":"ἀνάγνωσις","pron":"an-ag'-no-sis","xlit":"anágnōsis"},"G2857":{"derivation":"apparently feminine plural of kolossos (\"colossal\");","strongs_def":" Colossæ, a place in Asia Minor","kjv_def":"Colosse","lemma":"Κολοσσαί","translit":"Kolossaí","pron":"kol-os-sah'-ee","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Colosse = \"monstrosities\"</p><ol><li>anciently a large and flourishing city, but in Strabo's time a small town of Phrygia Major situated on the Lycus not far from its junction with the Maeander and in the neighbourhood of Laodicea and Hierapolis</li></ol>","xlit":"Kolossaí"},"G4291":{"derivation":"from G4253 (πρό) and G2476 (ἵστημι);","strongs_def":" to stand before, i.e. (in rank) to preside, or (by implication) to practise","kjv_def":"maintain, be over, rule","lemma":"προΐστημι","translit":"proḯstēmi","pron":"pro-is'-tay-mee","pos":"Verb","thayer":"<ol><li>to set or place before<ol type='a'><li>to set over</li><li>to be over, to superintend, preside over</li><li>to be a protector or guardian<ol><li>to give aid</li></ol><li>to care for, give attention to<ol><li>profess honest occupations</li></ol></li></ol></li></ol>","xlit":"proḯstēmi"},"G221":{"derivation":"from (the city so called);","strongs_def":" an Alexandreian or inhabitant of Alexandria","kjv_def":"of Alexandria, Alexandrian","lemma":"Ἀλεξανδρεύς","translit":"Alexandreús","pron":"al-ex-and-reuce'","pos":"Noun Masculine","thayer":"<ol><li>a native or resident of Alexandria in Egypt</li></ol>","xlit":"Alexandreús"},"G5538":{"strongs_def":" a divine response or revelation","derivation":"from G5537 (χρηματίζω);","lemma":"χρηματισμός","translit":"chrēmatismós","kjv_def":"answer of God","pron":"khray-mat-is-mos'","pos":"Noun Masculine","thayer":"<ol><li>a divine response, an oracle</li></ol>","xlit":"chrēmatismós"},"G3853":{"kjv_def":"(give in) charge, (give) command(-ment), declare","lemma":"παραγγέλλω","translit":"parangéllō","derivation":"from G3844 (παρά) and the base of G32 (ἄγγελος);","strongs_def":" to transmit a message, i.e. (by implication) to enjoin","pron":"par-ang-gel'-lo","pos":"Verb","thayer":"<ol><li>to transmit a message along from one to another, to declare, announce</li><li>to command, order, charge</li></ol>","xlit":"parangéllō"},"G2014":{"kjv_def":"appear, give light","lemma":"ἐπιφαίνω","translit":"epiphaínō","derivation":"from G1909 (ἐπί) and G5316 (φαίνω);","strongs_def":" to shine upon, i.e. become (literally) visible or (figuratively) known","pron":"ep-ee-fah'-ee-no","pos":"Verb","thayer":"<ol><li>to show to or upon<ol type='a'><li>to bring to light</li></ol><li>to appear, become visible<ol type='a'><li>of stars</li></ol><li>to become clearly known, to show one's self</li></ol>","xlit":"epiphaínō"},"G2140":{"strongs_def":" well-doing, i.e. beneficence","derivation":"from a compound of G2095 (εὖ) and G4160 (ποιέω);","translit":"eupoiḯa","lemma":"εὐποιΐα","kjv_def":"to do good","pron":"yoo-poy-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>adoring good, beneficence</li></ol>","xlit":"eupoiḯa"},"G312":{"kjv_def":"declare, rehearse, report, show, speak, tell","translit":"anangéllō","lemma":"ἀναγγέλλω","derivation":"from G303 (ἀνά) and the base of G32 (ἄγγελος);","strongs_def":" to announce (in detail)","pron":"an-ang-el'-lo","pos":"Verb","thayer":"<ol><li>to announce, make known</li><li>to report, bring back tidings, rehearse</li></ol>","xlit":"anangéllō"},"G702":{"kjv_def":"Aretas","lemma":"Ἀρέτας","translit":"Arétas","derivation":"of foreign origin;","strongs_def":" Aretas, an Arabian","pron":"ar-et'-as","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Aretes = \"graver\"</p><ol><li>An Arabian king</li></ol>","xlit":"Arétas"},"G323":{"strongs_def":" (the act of) exhibition","derivation":"from G322 (ἀναδείκνυμι);","lemma":"ἀνάδειξις","translit":"anádeixis","kjv_def":"shewing","pron":"an-ad'-ike-sis","pos":"Noun Feminine","thayer":"<ol><li>a pointing out, a public showing forth</li><li>a proclaiming, announcing, inaugurating of such as are elected to office</li></ol>","xlit":"anádeixis"},"G1495":{"kjv_def":"idolatry","lemma":"εἰδωλολατρεία","translit":"eidōlolatreía","derivation":"from G1497 (εἴδωλον) and G2999 (λατρεία);","strongs_def":" image-worship (literally or figuratively)","pron":"i-do-lol-at-ri'-ah","pos":"Noun Feminine","thayer":"<ol><li>the worship of false gods, idolatry<ol type='a'><li>of the formal sacrificial feats held in honour of false gods</li><li>of avarice, as a worship of Mammon</li></ol><li>in the plural, the vices springing from idolatry and peculiar to it</li></ol>","xlit":"eidōlolatreía"},"G1048":{"translit":"Gáza","lemma":"Γάζα","kjv_def":"Gaza","strongs_def":" Gazah (i.e. Azzah), a place in Palestine","derivation":"of Hebrew origin (H05804);","pron":"gad'-zah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Gaza = \"the fortified; the strong\"</p><ol><li>one of the five chief cities of the Philistines in Palestine</li></ol>","xlit":"Gáza"},"G239":{"strongs_def":" praise ye Jah!, an adoring exclamation","derivation":"of Hebrew origin (imperative of H01984 and H03050);","lemma":"ἀλληλουϊα","translit":"allēlouïa","kjv_def":"alleluiah","pron":"al-lay-loo'-ee-ah","thayer":"<ol><li>praise ye the Lord, Hallelujah</li></ol>","xlit":"allēlouïa"},"G805":{"kjv_def":"make fast (sure)","lemma":"ἀσφαλίζω","translit":"asphalízō","derivation":"from G804 (ἀσφαλής);","strongs_def":" to render secure","pron":"as-fal-id'-zo","pos":"Verb","thayer":"<ol><li>to make firm, to make secure (against harm)</li><li>to be made secure</li></ol>","xlit":"asphalízō"},"G3055":{"strongs_def":" disputation about trifles (\"logomachy\")","derivation":"from the same as G3054 (λογομαχέω);","translit":"logomachía","lemma":"λογομαχία","kjv_def":"strife of words","pron":"log-om-akh-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>to contend about words</li><li>to wrangle about empty and trifling matters</li></ol>","xlit":"logomachía"},"G2675":{"lemma":"καταρτίζω","translit":"katartízō","kjv_def":"fit, frame, mend, (make) perfect(-ly join together), prepare, restore","strongs_def":" to complete thoroughly, i.e. repair (literally or figuratively) or adjust","derivation":"from G2596 (κατά) and a derivative of G739 (ἄρτιος);","pron":"kat-ar-tid'-zo","pos":"Verb","thayer":"<ol><li>to render, i.e. to fit, sound, complete<ol type='a'><li>to mend (what has been broken or rent), to repair<ol><li>to complete</li></ol><li>to fit out, equip, put in order, arrange, adjust<ol><li>to fit or frame for one's self, prepare</li></ol><li>ethically: to strengthen, perfect, complete, make one what he ought to be</li></ol></li></ol>","xlit":"katartízō"},"G1280":{"kjv_def":"(be in) doubt, be (much) perplexed","translit":"diaporéō","lemma":"διαπορέω","derivation":"from G1223 (διά) and G639 (ἀπορέω);","strongs_def":" to be thoroughly nonplussed","pron":"dee-ap-or-eh'-o","pos":"Verb","thayer":"<ol><li>to be entirely at loss, to be in perplexity</li></ol>","xlit":"diaporéō"},"G2912":{"strongs_def":" a Cretan, i.e. inhabitant of Crete","derivation":"from G2914 (Κρήτη);","translit":"Krḗs","lemma":"Κρής","kjv_def":"Crete, Cretian","pron":"krace","pos":"Noun Masculine","thayer":"<ol><li>a Cretan, an inhabitant of the island of Crete</li></ol>","xlit":"Krḗs"},"G1097":{"strongs_def":" to \"know\" (absolutely) in a great variety of applications and with many implications (as follow, with others not thus clearly expressed)","derivation":"a prolonged form of a primary verb;","lemma":"γινώσκω","translit":"ginṓskō","kjv_def":"allow, be aware (of), feel, (have) know(-ledge), perceived, be resolved, can speak, be sure, understand","pron":"ghin-oce'-ko","pos":"Verb","thayer":"<ol><li>to learn to know, come to know, get a knowledge of perceive, feel<ol type='a'><li>to become known</li></ol><li>to know, understand, perceive, have knowledge of<ol type='a'><li>to understand</li><li>to know</li></ol><li>Jewish idiom for sexual intercourse between a man and a woman</li><li>to become acquainted with, to know</li></ol>","xlit":"ginṓskō"},"G4054":{"translit":"perissóteron","lemma":"περισσότερον","kjv_def":"more abundantly, a great deal, far more","strongs_def":" in a more superabundant way","derivation":"neuter of G4055 (περισσότερος) (as adverb);","pron":"per-is-sot'-er-on","xlit":"perissóteron"},"G5068":{"kjv_def":"foursquare","translit":"tetrágōnos","lemma":"τετράγωνος","derivation":"from G5064 (τέσσαρες) and G1137 (γωνία);","strongs_def":" four-cornered, i.e. square","pron":"tet-rag'-o-nos","pos":"Adjective","thayer":"<ol><li>quadrangular, square</li></ol>","xlit":"tetrágōnos"},"G3342":{"strongs_def":" betwixt (of place or person); (of time) as adjective, intervening, or (by implication) adjoining","derivation":"from G3326 (μετά) and a form of G4862 (σύν);","translit":"metaxý","lemma":"μεταξύ","kjv_def":"between, mean while, next","pron":"met-ax-oo'","pos":"Verb","thayer":"<ol><li>between<ol type='a'><li>meanwhile, in the mean time</li></ol><li>after, afterwards</li></ol>","xlit":"metaxý"},"G5563":{"strongs_def":" to place room between, i.e. part; reflexively, to go away","derivation":"from G5561 (χώρα);","lemma":"χωρίζω","translit":"chōrízō","kjv_def":"depart, put asunder, separate","pron":"kho-rid'-zo","pos":"Verb","thayer":"<ol><li>to separate, divide, part, put asunder, to separate one's self from, to depart<ol type='a'><li>to leave a husband or wife</li><li>of divorce</li><li>to depart, go away</li></ol></li></ol>","xlit":"chōrízō"},"G3460":{"strongs_def":" Myra, a place in Asia Minor","derivation":"of uncertain derivation;","translit":"Mýra","lemma":"Μύρα","kjv_def":"Myra","pron":"moo'-rah","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Myra = \"myrrh: myrtle juice\"</p><ol><li>an important town in Lycia, on the southwest coast of Asia Minor, on the river Andriacus, 2.5 miles (4 km) from the mouth</li></ol>","xlit":"Mýra"},"G1914":{"kjv_def":"look upon, regard, have respect to","translit":"epiblépō","lemma":"ἐπιβλέπω","derivation":"from G1909 (ἐπί) and G991 (βλέπω);","strongs_def":" to gaze at (with favor, pity or partiality)","pron":"ep-ee-blep'-o","pos":"Verb","thayer":"<ol><li>to turn the eyes upon, to look upon, gaze upon</li><li>to look up to, regard</li><li>to have regard for, to regard</li></ol>","xlit":"epiblépō"},"G4661":{"kjv_def":"spoil","translit":"skŷlon","lemma":"σκῦλον","derivation":"neuter from G4660 (σκύλλω);","strongs_def":" something stripped (as a hide), i.e. booty","pron":"skoo'-lon","pos":"Noun Neuter","thayer":"<ol><li>a (beast's) skin stripped off, a pelt</li><li>the weapons and valuables stripped off from an enemy, spoils</li></ol>","xlit":"skŷlon"},"G566":{"strongs_def":" it is sufficient","derivation":"third person singular present indicative active of G568 (ἀπέχω) used impersonally;","lemma":"ἀπέχει","translit":"apéchei","kjv_def":"it is enough","pron":"ap-ekh'-i","pos":"Verb","thayer":"<ol><li>it is sufficient, it is enough</li></ol>","xlit":"apéchei"},"G2466":{"translit":"Isachár","lemma":"Ἰσαχάρ","kjv_def":"Issachar","strongs_def":" Isachar (i.e. Jissaskar), a son of Jacob (figuratively, his descendant)","derivation":"of Hebrew origin (H03485);","pron":"ee-sakh-ar'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Issachar = \"reward\"</p><ol><li>the ninth son of Jacob and the fifth of Leah</li></ol>","xlit":"Isachár"},"G3911":{"strongs_def":" to bear along or aside, i.e. carry off (literally or figuratively); by implication, to avert","derivation":"from G3844 (παρά) and G5342 (φέρω) (including its alternate forms);","translit":"paraphérō","lemma":"παραφέρω","kjv_def":"remove, take away","pron":"par-af-er'-o","pos":"Verb","thayer":"<ol><li>to bear to, bring to, put before</li><li>to lead aside from the right course or path, to carry away</li><li>to carry past, lead past<ol type='a'><li>to cause to pass by, to remove</li></ol></li></ol>","xlit":"paraphérō"},"G1180":{"translit":"dekatéssares","lemma":"δεκατέσσαρες","kjv_def":"fourteen","strongs_def":" ten and four, i.e. fourteen","derivation":"from G1176 (δέκα) and G5064 (τέσσαρες);","pron":"dek-at-es'-sar-es","pos":"Noun","thayer":"<ol><li>fourteen</li></ol>","xlit":"dekatéssares"},"G2135":{"strongs_def":" a castrated person (such being employed in Oriental bed-chambers); by extension an impotent or unmarried man; by implication, a chamberlain (state-officer)","derivation":"from (a bed) and G2192 (ἔχω);","lemma":"εὐνοῦχος","translit":"eunoûchos","kjv_def":"eunuch","pron":"yoo-noo'-khos","pos":"Noun Masculine","thayer":"<ol><li>a bed keeper, bed guard, superintendent of the bedchamber, chamberlain<ol type='a'><li>in the palace of oriental monarchs who support numerous wives the superintendent of the women's apartment or harem, an office held by eunuchs</li><li>an emasculated man, a eunuch<ol><li>eunuchs in oriental courts held by other offices of greater, held by the Ethiopian eunuch mentioned in <a class='bible' href='#b44.8.27-39'>Act 8:27-39</a>.</li></ol><li>one naturally incapacitated<ol><li>for marriage</li><li>begetting children</li></ol><li>one who voluntarily abstains from marriage</li></ol></li></ol>","xlit":"eunoûchos"},"G4517":{"translit":"rhṓnnymi","lemma":"ῥώννυμι","kjv_def":"farewell","strongs_def":" probably akin to G4506 (ῥύομαι)); to strengthen, i.e. (impersonal passive) have health (as a parting exclamation, good-bye)","derivation":"prolongation from (to dart;","pron":"hrone'-noo-mee","pos":"Verb","thayer":"<ol><li>to make strong, strengthen</li><li>to be strong, to thrive, prosper</li><li>in the usual formula in closing of a letter, farewell</li></ol>","xlit":"rhṓnnymi"},"G4195":{"strongs_def":" a sea; Pontus, a region of Asia Minor","derivation":"of Latin origin;","lemma":"Πόντος","translit":"Póntos","kjv_def":"Pontus","pron":"pon'-tos","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Pontus = \"the sea\"</p><ol><li>a region of eastern Asia Minor, bounded by the Euxine Sea, Armenia, Cappadocia, Galatia, Paphlagonia</li></ol>","xlit":"Póntos"},"G3191":{"kjv_def":"imagine, (pre-)meditate","lemma":"μελετάω","translit":"meletáō","derivation":"from a presumed derivative of G3199 (μέλω);","strongs_def":" to take care of, i.e. (by implication) revolve in the mind","pron":"mel-et-ah'-o","pos":"Verb","thayer":"<ol><li>to care for, attend to carefully, practise</li><li>to meditate, i.e. to devise, contrive<ol type='a'><li>used of the Greeks of the meditative pondering and the practice of orators and rhetoricians</li></ol></li></ol>","xlit":"meletáō"},"G1864":{"translit":"epagōnízomai","lemma":"ἐπαγωνίζομαι","kjv_def":"earnestly contend for","strongs_def":" to struggle for","derivation":"from G1909 (ἐπί) and G75 (ἀγωνίζομαι);","pron":"ep-ag-o-nid'-zom-ahee","pos":"Verb","thayer":"<ol><li>to contend</li></ol>","xlit":"epagōnízomai"},"G1461":{"kjv_def":"graff in(-to)","lemma":"ἐγκεντρίζω","translit":"enkentrízō","derivation":"from G1722 (ἐν) and a derivative of G2759 (κέντρον);","strongs_def":" to prick in, i.e. ingraft","pron":"eng-ken-trid'-zo","pos":"Verb","thayer":"<ol><li>to cut into for the sake of inserting a scion</li><li>to inoculate, ingraft, graft in</li></ol>","xlit":"enkentrízō"},"G1030":{"strongs_def":" a grating (of the teeth)","derivation":"from G1031 (βρύχω);","translit":"brygmós","lemma":"βρυγμός","kjv_def":"gnashing","pron":"broog-mos'","pos":"Noun Masculine","thayer":"<ol><li>a gnashing of teeth<ol type='a'><li>used to denote extreme anguish and utter despair of men consigned to eternal punishment in hell</li></ol><li>snarling, growling: in the sense of biting</li></ol>","xlit":"brygmós"},"G5585":{"derivation":"from G5586 (ψῆφος);","strongs_def":" to use pebbles in enumeration, i.e. (generally) to compute","kjv_def":"count","lemma":"ψηφίζω","translit":"psēphízō","pron":"psay-fid'-zo","pos":"Verb","thayer":"<ol><li>to count with pebbles, to compute, calculate, reckon</li><li>to give one's vote by casting a pebble into the urn</li><li>to decide by voting</li></ol>","xlit":"psēphízō"},"G4218":{"kjv_def":"afore-(any, some-)time(-s), at length (the last), (+ n- )ever, in the old time, in time past, once, when","translit":"poté","lemma":"ποτέ","derivation":"from the base of G4225 (πού) and G5037 (τέ);","strongs_def":" indefinite adverb, at some time, ever","pron":"pot-eh'","thayer":"<ol><li>once, i.e. formerly, aforetime, at some time</li></ol>","xlit":"poté"},"G1284":{"lemma":"διαῤῥήσσω","translit":"diarrhḗssō","kjv_def":"break, rend","strongs_def":" to tear asunder","derivation":"from G1223 (διά) and G4486 (ῥήγνυμι);","pron":"dee-ar-hrayce'-so","pos":"Verb","thayer":"<ol><li>to break asunder, burst through, rend asunder</li><li>to rend, which was done by the Jews to their clothes in cases of extreme indignation or in deep grief</li></ol>","xlit":"diarrhḗssō"},"G3347":{"translit":"metépeita","lemma":"μετέπειτα","kjv_def":"afterward","strongs_def":" thereafter","derivation":"from G3326 (μετά) and G1899 (ἔπειτα);","pron":"met-ep'-i-tah","pos":"Adverb","thayer":"<ol><li>afterwards, after that</li></ol>","xlit":"metépeita"},"G3134":{"kjv_def":"Maran-atha","lemma":"μαρὰν ἀθά","translit":"maràn athá","derivation":"of Chaldee origin (meaning our Lord has come);","strongs_def":" maranatha, i.e. an exclamation of the approaching divine judgment","pron":"mar'-an ath'-ah","thayer":"<ol><li>our Lord cometh or will come</li></ol>","xlit":"maràn athá"},"G48":{"kjv_def":"purify (self)","lemma":"ἁγνίζω","translit":"hagnízō","derivation":"from G53 (ἁγνός);","strongs_def":" to make clean, i.e. (figuratively) sanctify (ceremonially or morally)","pron":"hag-nid'-zo","pos":"Verb","thayer":"<ol><li>ceremonially<ol type='a'><li>to make pure, purify, cleanse</li></ol><li>morally</li></ol>","xlit":"hagnízō"},"G4970":{"kjv_def":" exceeding(-ly), greatly, sore, very","translit":"sphódra","lemma":"σφόδρα","derivation":"neuter plural of (violent;","strongs_def":" of uncertain derivation) as adverb; vehemently, i.e. in a high degree, much","pron":"sfod'-rah","pos":"Adverb","thayer":"<ol><li>exceedingly, greatly</li></ol>","xlit":"sphódra"},"G3004":{"strongs_def":" properly, to \"lay\" forth, i.e. (figuratively) relate (in words (usually of systematic or set discourse; whereas G2036 (ἔπω) and G5346 (φημί) generally refer to an individual expression or speech respectively; while G4483 (ῥέω) is properly to break silence merely, and G2980 (λαλέω) means an extended or random harangue)); by implication, to mean","derivation":"a primary verb;","translit":"légō","lemma":"λέγω","kjv_def":"ask, bid, boast, call, describe, give out, name, put forth, say(-ing, on), shew, speak, tell, utter","pron":"leg'-o","pos":"Verb","thayer":"<ol><li>to say, to speak<ol type='a'><li>affirm over, maintain</li><li>to teach</li><li>to exhort, advise, to command, direct</li><li>to point out with words, intend, mean, mean to say</li><li>to call by name, to call, name</li><li>to speak out, speak of, mention</li></ol></li></ol>","xlit":"légō"},"G1421":{"strongs_def":" difficult of explanation","derivation":"from G1418 (δυσ-) and a presumed derivative of G2059 (ἑρμηνεύω);","lemma":"δυσερμήνευτος","translit":"dysermḗneutos","kjv_def":"hard to be uttered","pron":"doos-er-mane'-yoo-tos","pos":"Adjective","thayer":"<ol><li>hard to interpret, difficult to explain</li></ol>","xlit":"dysermḗneutos"},"G349":{"strongs_def":" to scream up (aloud)","derivation":"from G303 (ἀνά) and G2896 (κράζω);","lemma":"ἀνακράζω","translit":"anakrázō","kjv_def":"cry out","pron":"an-ak-rad'-zo","pos":"Verb","thayer":"<ol><li>to raise a cry from the depth of the throat, to cry out</li></ol>","xlit":"anakrázō"},"G2238":{"strongs_def":" a sweet-scented plant, i.e. mint","derivation":"neuter of the compound of the same as G2234 (ἡδέως) and G3744 (ὀσμή);","lemma":"ἡδύοσμον","translit":"hēdýosmon","kjv_def":"mint","pron":"hay-doo'-os-mon","pos":"Noun Neuter","thayer":"<ol><li>sweet smelling, garden mint<ol type='a'><li>a kind of small odoriferous herb, with which the Jews used to scatter on the floors of their houses and synagogues</li></ol></li></ol>","xlit":"hēdýosmon"},"G3029":{"kjv_def":"exceeding, great(-ly), sore, very (+ chiefest)","lemma":"λίαν","translit":"lían","derivation":"of uncertain affinity;","strongs_def":" much (adverbially)","pron":"lee'-an","pos":"Adverb","thayer":"<ol><li>greatly, exceedingly, exceedingly beyond measure</li></ol>","xlit":"lían"},"G819":{"derivation":"from G820 (ἄτιμος);","strongs_def":" infamy, i.e. (subjectively) comparative indignity, (objectively) disgrace","kjv_def":"dishonour, reproach, shame, vile","lemma":"ἀτιμία","translit":"atimía","pron":"at-ee-mee'-ah","pos":"Noun Feminine","thayer":"<ol><li>dishonour, ignominy, disgrace</li></ol>","xlit":"atimía"},"G2634":{"derivation":"from G2596 (κατά) and G2961 (κυριεύω);","strongs_def":" to lord against, i.e. control, subjugate","kjv_def":"exercise dominion over (lordship), be lord over, overcome","translit":"katakyrieúō","lemma":"κατακυριεύω","pron":"kat-ak-oo-ree-yoo'-o","pos":"Verb","thayer":"<ol><li>to bring under one's power, to subject one's self, to subdue, master</li><li>to hold in subjection, to be master of, exercise lordship over</li></ol>","xlit":"katakyrieúō"},"G2051":{"lemma":"ἐρίζω","translit":"erízō","kjv_def":"strive","strongs_def":" to wrangle","derivation":"from G2054 (ἔρις);","pron":"er-id'-zo","pos":"Verb","thayer":"<ol><li>to wrangle, engage in strife<ol type='a'><li>used to describe the calm temper of Jesus in contrast with the vehemence of the Jewish doctors wrangling together about tenets and practices</li></ol></li></ol>","xlit":"erízō"},"G5112":{"lemma":"τολμηρότερον","translit":"tolmēróteron","kjv_def":"the more boldly","strongs_def":" more daringly, i.e. with greater confidence than otherwise","derivation":"neuter of the compound of a derivative of the base of 5111 (as adverb);","pron":"tol-may-rot'-er-on","pos":"Adjective","thayer":"<ol><li>more boldly</li></ol>","xlit":"tolmēróteron"},"G1113":{"strongs_def":" a grumbler","derivation":"from G1111 (γογγύζω);","lemma":"γογγυστής","translit":"gongystḗs","kjv_def":"murmurer","pron":"gong-goos-tace'","pos":"Noun Masculine","thayer":"<ol><li>a murmurer, one who discontentedly complains (against God)</li></ol>","xlit":"gongystḗs"},"G4687":{"kjv_def":"sow(- er), receive seed","lemma":"σπείρω","translit":"speírō","derivation":"probably strengthened from G4685 (σπάω) (through the idea of extending);","strongs_def":" to scatter, i.e. sow (literally or figuratively)","pron":"spi'-ro","pos":"Verb","thayer":"<ol><li>to sow, scatter, seed</li><li>metaphorically of proverbial sayings</li></ol>","xlit":"speírō"},"G4812":{"kjv_def":"spoil","translit":"sylagōgéō","lemma":"συλαγωγέω","derivation":"from the base of G4813 (συλάω) and (the reduplicated form of) G71 (ἄγω);","strongs_def":" to lead away as booty, i.e. (figuratively) seduce","pron":"soo-lag-ogue-eh'-o","pos":"Verb","thayer":"<ol><li>to carry off booty<ol type='a'><li>to carry one off as a captive (and slave)</li><li>to lead away from the truth and subject to one's sway</li></ol></li></ol>","xlit":"sylagōgéō"},"G2211":{"lemma":"Ζηνᾶς","translit":"Zēnâs","kjv_def":"Zenas","strongs_def":" Jove-given; Zenas, a Christian","derivation":"probably contracted from a poetic form of G2203 (Ζεύς) and G1435 (δῶρον);","pron":"dzay-nas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Zenas = \"Jupiter\"</p><ol><li>a teacher of the Jewish law and afterwards a Christian</li></ol>","xlit":"Zēnâs"},"G2185":{"kjv_def":"reach","lemma":"ἐφικνέομαι","translit":"ephiknéomai","derivation":"from G1909 (ἐπί) and a cognate of G2240 (ἥκω);","strongs_def":" to arrive upon, i.e. extend to","pron":"ef-ik-neh'-om-ahee","pos":"Verb","thayer":"<ol><li>to come to</li></ol>","xlit":"ephiknéomai"},"G8":{"strongs_def":" Abiathar, an Israelite","derivation":"of Hebrew origin (H054);","translit":"Abiathár","lemma":"Ἀβιαθάρ","kjv_def":"Abiathar","pron":"ab-ee-ath'-ar","pos":"Proper Name Masculine","thayer":"<strong>Thayer Definition</strong>: Abiathar = \"father of abundance\"</p><ol><li>the name of a high priest</li></ol>","xlit":"Abiathár"},"G4559":{"kjv_def":"carnal, fleshly","lemma":"σαρκικός","translit":"sarkikós","derivation":"from G4561 (σάρξ);","strongs_def":" pertaining to flesh, i.e. (by extension) bodily, temporal, or (by implication) animal, unregenerate","pron":"sar-kee-kos'","pos":"Adjective","thayer":"<ol><li>fleshly, carnal<ol type='a'><li>having the nature of flesh, i.e. under the control of the animal appetites<ol><li>governed by mere human nature not by the Spirit of God</li><li>having its seat in the animal nature or aroused by the animal nature</li><li>human: with the included idea of depravity</li></ol><li>pertaining to the flesh<ol><li>to the body: related to birth, linage, etc</li></ol></li></ol></li></ol>","xlit":"sarkikós"},"G1527":{"strongs_def":" severally","derivation":"from G1520 (εἷς) repeated with G2596 (κατά) inserted;","translit":"heîs kath’ heîs","lemma":"εἷς καθ’ εἷς","kjv_def":"one by one","pron":"hice kath hice","xlit":"heîs kath’ heîs"},"G46":{"strongs_def":" properly, unfulled, i.e. (by implication) new (cloth)","derivation":"from G1 (Α) (as a negative particle) and the same as G1102 (γναφεύς);","translit":"ágnaphos","lemma":"ἄγναφος","kjv_def":"new","pron":"ag'-naf-os","pos":"Adjective","thayer":"<ol><li>unmilled, unfulled, undressed, unprocessed, new</li></ol>","xlit":"ágnaphos"},"G4735":{"strongs_def":" a chaplet (as a badge of royalty, a prize in the public games or a symbol of honor generally; but more conspicuous and elaborate than the simple fillet, G1238 (διάδημα)), literally or figuratively","derivation":"from an apparently primary (to twine or wreathe);","translit":"stéphanos","lemma":"στέφανος","kjv_def":"crown","pron":"stef'-an-os","pos":"Noun Masculine","thayer":"<ol><li>a crown<ol type='a'><li>a mark of royal or (in general) exalted rank<ol><li>the wreath or garland which was given as a prize to victors in public games</li></ol><li>metaphorically the eternal blessedness which will be given as aprize to the genuine servants of God and Christ: the crown (wreath) which is the reward of the righteousness</li><li>that which is an ornament and honour to one</li></ol></li></ol>","xlit":"stéphanos"},"G3512":{"kjv_def":"youthful","lemma":"νεωτερικός","translit":"neōterikós","derivation":"from the comparative of G3501 (νέος);","strongs_def":" appertaining to younger persons, i.e. juvenile","pron":"neh-o-ter'-ik-os","pos":"Adjective","thayer":"<ol><li>peculiar to an age, of youth, youthful, younger<ol type='a'><li>younger (than now)</li><li>young, youthful</li><li>younger (by birth)</li><li>an attendant, servant, inferiority in rank</li></ol></li></ol>","xlit":"neōterikós"},"G4595":{"derivation":"apparently a primary verb;","strongs_def":" to putrefy, i.e. (figuratively) perish","kjv_def":"be corrupted","lemma":"σήπω","translit":"sḗpō","pron":"say'-po","pos":"Verb","thayer":"<ol><li>to make corrupt, to destroy</li><li>to become corrupt, corrupted, rotten</li></ol>","xlit":"sḗpō"},"G1526":{"lemma":"εἰσί","translit":"eisí","kjv_def":"agree, are, be, dure, X is, were","strongs_def":" they are","derivation":"3rd person plural present indicative of G1510 (εἰμί);","pron":"i-see'","pos":"Verb","thayer":"<ol><li>are, be, were, etc.</li></ol>","xlit":"eisí"},"G4834":{"strongs_def":" to feel \"sympathy\" with, i.e. (by implication) to commiserate","derivation":"from G4835 (συμπαθής);","lemma":"συμπαθέω","translit":"sympathéō","kjv_def":"have compassion, be touched with a feeling of","pron":"soom-path-eh'-o","pos":"Verb","thayer":"<ol><li>to be affected with the same feeling as another, to sympathise with</li><li>to feel for, have compassion on</li></ol>","xlit":"sympathéō"},"G2178":{"kjv_def":"(at) once (for all)","lemma":"ἐφάπαξ","translit":"ephápax","derivation":"from G1909 (ἐπί) and G530 (ἅπαξ);","strongs_def":" upon one occasion (only)","pron":"ef-ap'-ax","pos":"Adverb","thayer":"<ol><li>once, at once<ol type='a'><li>all at once</li><li>once for all</li></ol></li></ol>","xlit":"ephápax"},"G1428":{"derivation":"from G1427 (δώδεκα);","strongs_def":" twelfth","kjv_def":"twelfth","lemma":"δωδέκατος","translit":"dōdékatos","pron":"do-dek'-at-os","pos":"Adjective","thayer":"<ol><li>twelfth</li></ol>","xlit":"dōdékatos"},"G1362":{"derivation":"from G1364 (δίς) and (probably) the base of G4119 (πλείων);","strongs_def":" two-fold","kjv_def":"double, two-fold more","lemma":"διπλοῦς","translit":"diploûs","pron":"dip-looce'","pos":"Adjective","thayer":"<ol><li>twofold, double</li></ol>","xlit":"diploûs"},"G2388":{"strongs_def":" Janna, an Israelite","derivation":"probably of Hebrew origin (compare H03238);","lemma":"Ἰαννά","translit":"Ianná","kjv_def":"Janna","pron":"ee-an-nah'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Janna = \"flourishing\"</p><ol><li>son of Joseph and the father of Melchi, in the genealogy of Christ</li></ol>","xlit":"Ianná"},"G3862":{"strongs_def":" transmission, i.e. (concretely) a precept; specially, the Jewish traditionary law","derivation":"from G3860 (παραδίδωμι);","translit":"parádosis","lemma":"παράδοσις","kjv_def":"ordinance, tradition","pron":"par-ad'-os-is","pos":"Noun Feminine","thayer":"<ol><li>giving up, giving over<ol type='a'><li>the act of giving up</li><li>the surrender of cities</li></ol><li>a giving over which is done by word of mouth or in writing, i.e. tradition by instruction, narrative, precept, etc.<ol type='a'><li>objectively, that which is delivered, the substance of a teaching</li><li>of the body of precepts, especially ritual, which in the opinion of the later Jews were orally delivered by Moses and orally transmitted in unbroken succession to subsequent generations, which precepts, both illustrating and expanding the written law, as they did were to be obeyed with equal reverence</li></ol></li></ol>","xlit":"parádosis"},"G3943":{"derivation":"from G3844 (παρά) and G3631 (οἶνος);","strongs_def":" staying near wine, i.e. tippling (a toper)","kjv_def":"given to wine","lemma":"πάροινος","translit":"pároinos","pron":"par'-oy-nos","pos":"Adjective","thayer":"<ol><li>given to wine, drunken</li></ol>","xlit":"pároinos"},"G1792":{"kjv_def":"sporting selves","translit":"entrypháō","lemma":"ἐντρυφάω","derivation":"from G1722 (ἐν) and G5171 (τρυφάω);","strongs_def":" to revel in","pron":"en-troo-fah'-o","pos":"Verb","thayer":"<ol><li>to live in luxury, live delicately or luxuriously, to revel in</li><li>to take delight in</li></ol>","xlit":"entrypháō"},"G5479":{"strongs_def":" cheerfulness, i.e. calm delight","derivation":"from G5463 (χαίρω);","lemma":"χαρά","translit":"chará","kjv_def":"gladness, X greatly, (X be exceeding) joy(-ful, -fully, -fulness, -ous)","pron":"khar-ah'","pos":"Noun Feminine","thayer":"<ol><li>joy, gladness<ol type='a'><li>the joy received from you</li><li>the cause or occasion of joy<ol><li>of persons who are one's joy</li></ol></li></ol></li></ol>","xlit":"chará"},"G2283":{"strongs_def":" Thamar (i.e. Tamar), an Israelitess","derivation":"of Hebrew origin (H08559);","translit":"Thámar","lemma":"Θάμαρ","kjv_def":"Thamar","pron":"tham'-ar","pos":"Noun Feminine","thayer":"<strong>Thayer Definition</strong>: Tamar = \"palm tree\"</p><ol><li>the wife of the two sons of Judah, Er and Onan.</li></ol>","xlit":"Thámar"},"G5237":{"strongs_def":" to overlook, i.e. not punish","derivation":"from G5228 (ὑπέρ) and G1492 (εἴδω);","translit":"hypereídō","lemma":"ὑπερείδω","kjv_def":"wink at","pron":"hoop-er-i'-do","pos":"Verb","thayer":"<ol><li>to overlook, take no notice of, not attend to</li></ol>","xlit":"hypereídō"},"G3520":{"kjv_def":"island, isle","translit":"nēsos","lemma":"νῆσος","derivation":"probably from the base of G3491 (ναῦς);","strongs_def":" an island","pron":"nay'-sos","pos":"Noun Feminine","thayer":"<ol><li>an island</li></ol>","xlit":"nēsos"},"G1796":{"derivation":"from G1722 (ἐν) and G5195 (ὑβρίζω);","strongs_def":" to insult","kjv_def":"do despite unto","lemma":"ἐνυβρίζω","translit":"enybrízō","pron":"en-oo-brid'-zo","pos":"Verb","thayer":"<ol><li>to insult</li></ol>","xlit":"enybrízō"},"G4989":{"strongs_def":" Sosipatrus, a Christian","derivation":"prolongation for G4986 (Σώπατρος);","translit":"Sōsípatros","lemma":"Σωσίπατρος","kjv_def":"Sosipater","pron":"so-sip'-at-ros","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Sosipater = \"saviour of his father\"</p><ol><li>a kinsman or fellow tribesman of Paul</li></ol>","xlit":"Sōsípatros"},"G3875":{"strongs_def":"an intercessor, consoler","lemma":"παράκλητος","translit":"paráklētos","kjv_def":"advocate, comforter","pron":"par-ak'-lay-tos","pos":"Noun Masculine","thayer":"<ol><li>summoned, called to one's side, especially called to one's aid<ol type='a'><li>one who pleads another's cause before a judge, a pleader, counsel for defense, legal assistant, an advocate</li><li>one who pleads another's cause with one, an intercessor<ol><li>of Christ in his exaltation at God's right hand, pleading with God the Father for the pardon of our sins</li></ol><li>in the widest sense, a helper, succourer, aider, assistant<ol><li>of the Holy Spirit destined to take the place of Christ with the apostles (after his ascension to the Father), to lead them to a deeper knowledge of the gospel truth, and give them divine strength needed to enable them to undergo trials and persecutions on behalf of the divine kingdom</li></ol></li></ol></li></ol>","xlit":"paráklētos"},"G5616":{"strongs_def":" as if","derivation":"from G5613 (ὡς) and G1487 (εἰ);","translit":"hōseí","lemma":"ὡσεί","kjv_def":"about, as (it had been, it were), like (as)","pron":"ho-si'","pos":"Adverb","thayer":"<ol><li>as it were, (had been), as though, as, like as, like</li><li>about, nearly<ol type='a'><li>before numerals</li><li>before a measure of time</li></ol></li></ol>","xlit":"hōseí"},"G5423":{"derivation":"from G5424 (φρήν) and G539 (ἀπάτη);","strongs_def":" a mind-misleader, i.e. seducer","kjv_def":"deceiver","translit":"phrenapátēs","lemma":"φρεναπάτης","pron":"fren-ap-at'-ace","pos":"Noun Masculine","thayer":"<ol><li>a mind deceiver, a seducer</li></ol>","xlit":"phrenapátēs"},"G4183":{"derivation":"including the forms from the alternate ;","strongs_def":" (singular) much (in any respect) or (plural) many; neuter (singular) as adverbial, largely; neuter (plural) as adverb or noun often, mostly, largely","kjv_def":"abundant, + altogether, common, + far (passed, spent), (+ be of a) great (age, deal, -ly, while), long, many, much, oft(-en (-times)), plenteous, sore, straitly","lemma":"πολύς","translit":"polýs","pron":"pol-oos'","pos":"Adjective","thayer":"<ol><li>many, much, large</li></ol>","xlit":"polýs"},"G2599":{"kjv_def":"burden","translit":"katabaréō","lemma":"καταβαρέω","derivation":"from G2596 (κατά) and G916 (βαρέω);","strongs_def":" to impose upon","pron":"kat-ab-ar-eh'-o","pos":"Verb","thayer":"<ol><li>to press down by an imposing weight</li><li>to weigh down</li><li>metaphorically to burden</li></ol>","xlit":"katabaréō"},"G4602":{"derivation":"apparently from (to hiss, i.e. hist or hush);","strongs_def":" silence","kjv_def":"silence","translit":"sigḗ","lemma":"σιγή","pron":"see-gay'","pos":"Noun Feminine","thayer":"<ol><li>silence</li></ol>","xlit":"sigḗ"},"G3506":{"lemma":"νεύω","translit":"neúō","kjv_def":"beckon","strongs_def":" to \"nod\", i.e. (by analogy), signal","derivation":"apparently a primary verb;","pron":"nyoo'-o","pos":"Verb","thayer":"<ol><li>to give a nod</li><li>to signify by a nod (of what one wishes to be done)</li></ol>","xlit":"neúō"},"G1812":{"strongs_def":" six hundred","derivation":"plural ordinal from G1803 (ἕξ) and G1540 (ἑκατόν);","lemma":"ἑξακόσιοι","translit":"hexakósioi","kjv_def":"six hundred","pron":"hex-ak-os'-ee-oy","pos":"Adjective","thayer":"<ol><li>six hundred</li></ol>","xlit":"hexakósioi"},"G3396":{"kjv_def":"mingle","translit":"mígnymi","lemma":"μίγνυμι","derivation":"a primary verb;","strongs_def":" to mix","pron":"mig'-noo-mee","pos":"Verb","thayer":"<ol><li>to mix, mingle</li></ol>","xlit":"mígnymi"},"G3849":{"derivation":"from G3844 (παρά) and the middle voice of G971 (βιάζω);","strongs_def":" to force contrary to (nature), i.e. compel (by entreaty)","kjv_def":"constrain","lemma":"παραβιάζομαι","translit":"parabiázomai","pron":"par-ab-ee-ad'-zom-ahee","pos":"Verb","thayer":"<ol><li>to employ force contrary to nature and right</li><li>to compel by employing force</li><li>to constrain one by entreaties</li></ol>","xlit":"parabiázomai"},"G1915":{"translit":"epíblēma","lemma":"ἐπίβλημα","kjv_def":"piece","strongs_def":" a patch","derivation":"from G1911 (ἐπιβάλλω);","pron":"ep-ib'-lay-mah","pos":"Noun Neuter","thayer":"<ol><li>that which is thrown or put upon a thing, or that which is added to it<ol type='a'><li>an addition</li><li>that which is sewed on to cover a rent, a patch</li></ol></li></ol>","xlit":"epíblēma"},"G3596":{"derivation":"from a compound of G3598 (ὁδός) and G4198 (πορεύομαι);","strongs_def":" to be a wayfarer, i.e. travel","kjv_def":"go on a journey","translit":"hodoiporéō","lemma":"ὁδοιπορέω","pron":"hod-oy-por-eh'-o","pos":"Verb","thayer":"<ol><li>to travel, journey</li></ol>","xlit":"hodoiporéō"},"G876":{"strongs_def":" froth, i.e. slaver","derivation":"apparently a primary word;","lemma":"ἀφρός","translit":"aphrós","kjv_def":"foaming","pron":"af-ros'","pos":"Noun Masculine","thayer":"<ol><li>foam</li></ol>","xlit":"aphrós"},"G3710":{"lemma":"ὀργίζω","translit":"orgízō","kjv_def":"be angry (wroth)","strongs_def":" to provoke or enrage, i.e. (passively) become exasperated","derivation":"from G3709 (ὀργή);","pron":"or-gid'-zo","pos":"Verb","thayer":"<ol><li>to provoke, to arouse to anger</li><li>to be provoked to anger, be angry, be wroth</li></ol>","xlit":"orgízō"},"G1060":{"kjv_def":"marry (a wife)","lemma":"γαμέω","translit":"gaméō","derivation":"from G1062 (γάμος);","strongs_def":" to wed (of either sex)","pron":"gam-eh'-o","pos":"Verb","thayer":"<ol><li>to lead in marriage, take to wife<ol type='a'><li>to get married, to marry</li><li>to give one's self in marriage</li></ol><li>to give a daughter in marriage</li></ol>","xlit":"gaméō"},"G4122":{"strongs_def":" to be covetous, i.e. (by implication) to over-reach","derivation":"from G4123 (πλεονέκτης);","lemma":"πλεονεκτέω","translit":"pleonektéō","kjv_def":"get an advantage, defraud, make a gain","pron":"pleh-on-cek-teh'-o","pos":"Verb","thayer":"<ol><li>to have more, or a greater part or share<ol type='a'><li>to be superior, excel, surpass, have an advantage over</li></ol><li>to gain or take advantage of another, to overreach</li></ol>","xlit":"pleonektéō"},"G5025":{"derivation":"dative case and accusative case feminine plural respectively of G3778 (οὗτος);","strongs_def":" (to or with or by, etc.) these","kjv_def":"hence, that, then, these, those","translit":"taútais","lemma":"ταύταις","pron":"tow'-taheece","thayer":"<ol><li>those, these</li></ol>","xlit":"taútais"},"G1342":{"kjv_def":"just, meet, right(-eous)","lemma":"δίκαιος","translit":"díkaios","derivation":"from G1349 (δίκη);","strongs_def":" equitable (in character or act); by implication, innocent, holy (absolutely or relatively)","pron":"dik'-ah-yos","pos":"Adjective","thayer":"<ol><li>righteous, observing divine laws<ol type='a'><li>in a wide sense, upright, righteous, virtuous, keeping the commands of God<ol><li>of those who seem to themselves to be righteous, who pride themselves to be righteous, who pride themselves in their virtues, whether real or imagined</li><li>innocent, faultless, guiltless</li><li>used of him whose way of thinking, feeling, and acting is wholly conformed to the will of God, and who therefore needs no rectification in the heart or life<ol type='a'><li>only Christ truly</li></ol><li>approved of or acceptable of God</li></ol><li>in a narrower sense, rendering to each his due and that in a judicial sense, passing just judgment on others, whether expressed in words or shown by the manner of dealing with them</li></ol></li></ol>","xlit":"díkaios"},"G717":{"derivation":"of Hebrew origin (H02022 and H04023);","strongs_def":" Armageddon (or Har-Meggiddon), a symbolic name","kjv_def":"Armageddon","lemma":"Ἀρμαγεδδών","translit":"Armageddṓn","pron":"ar-mag-ed-dohn'","pos":"Noun Location","thayer":"<strong>Thayer Definition</strong>: Armageddon = \"the hill or city of Megiddo\"</p><ol><li>In <a class='bible' href='#b66.16.16'>Rev 16:16</a> the scene of a the struggle of good and evil is suggested by that battle plain of Esdraelon, which was famous for two great victories, of Barak over the Canaanites, and of Gideon over the Midianites; and for two great disasters, the deaths of Saul and Josiah. Hence in Revelation a place of great slaughter, the scene of a terrible retribution upon the wicked. The RSV translates the name as Har-Magedon, i.e. the hill (as Ar is the city) of Megiddo.</li></ol>","xlit":"Armageddṓn"},"G1747":{"lemma":"ἐνέδρα","translit":"enédra","kjv_def":"lay wait","strongs_def":" an ambuscade, i.e. (figuratively) murderous purpose","derivation":"feminine from G1722 (ἐν) and the base of G1476 (ἑδραῖος);","pron":"en-ed'-rah","pos":"Noun Feminine","thayer":"<ol><li>a lying in wait, an ambush</li></ol>","xlit":"enédra"},"G368":{"strongs_def":" indisputable","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of a compound of G473 (ἀντί) and G4483 (ῥέω);","lemma":"ἀναντίῤῥητος","translit":"anantírrhētos","kjv_def":"cannot be spoken against","pron":"an-an-tir'-hray-tos","pos":"Adjective","thayer":"<ol><li>not to be contradicted, undeniable</li></ol>","xlit":"anantírrhētos"},"G2604":{"lemma":"καταγγελεύς","translit":"katangeleús","kjv_def":"setter forth","strongs_def":" a proclaimer","derivation":"from G2605 (καταγγέλλω);","pron":"kat-ang-gel-yooce'","pos":"Noun Masculine","thayer":"<ol><li>announcer, proclaimer</li></ol>","xlit":"katangeleús"},"G2973":{"translit":"Kōsám","lemma":"Κωσάμ","kjv_def":"Cosam","strongs_def":" Cosam (i.e. Kosam) an Israelite","derivation":"of Hebrew origin (compare H07081);","pron":"ko-sam'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Cosam = \"divining\"</p><ol><li>ancestor of Christ's</li></ol>","xlit":"Kōsám"},"G2792":{"translit":"kinámōmon","lemma":"κινάμωμον","kjv_def":"cinnamon","strongs_def":" cinnamon","derivation":"of foreign origin (compare H07076);","pron":"kin-am'-o-mon","pos":"Noun Neuter","thayer":"<ol><li>cinnamon was a well known aromatic substance, the rind of \"Laurus cinnamonum\" called \"Korunda-gauhah\" in Ceylon</li></ol>","xlit":"kinámōmon"},"G5072":{"translit":"tetrámēnon","lemma":"τετράμηνον","kjv_def":"four months","strongs_def":" a four months' space","derivation":"neuter of a compound of G5064 (τέσσαρες) and G3376 (μήν);","pron":"tet-ram'-ay-non","pos":"Adjective","thayer":"<ol><li>of four months, lasting four months</li></ol>","xlit":"tetrámēnon"},"G2137":{"kjv_def":"(have a) prosper(-ous journey)","lemma":"εὐοδόω","translit":"euodóō","derivation":"from a compound of G2095 (εὖ) and G3598 (ὁδός);","strongs_def":" to help on the road, i.e. (passively) succeed in reaching; figuratively, to succeed in business affairs","pron":"yoo-od-o'-o","pos":"Verb","thayer":"<ol><li>to grant a prosperous and expeditious journey, to lead by a direct and easy way</li><li>to grant a successful issue, to cause to prosper</li><li>to prosper, be successful</li></ol>","xlit":"euodóō"},"G1214":{"kjv_def":"Demas","lemma":"Δημᾶς","translit":"Dēmâs","derivation":"probably for G1216 (Δημήτριος);","strongs_def":" Demas, a Christian","pron":"day-mas'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Demas = \"governor of the people\"</p><ol><li>a companion of Paul, who deserted the apostle when he was a prisoner at Rome and returned to Thessalonica</li></ol>","xlit":"Dēmâs"},"G986":{"kjv_def":"Blastus","translit":"Blástos","lemma":"Βλάστος","derivation":"perhaps the same as the base of G985 (βλαστάνω);","strongs_def":" Blastus, an officer of Herod Agrippa","pron":"blas'-tos","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Blastus = \"sprout\"</p><ol><li>the chamberlain of Herod Agrippa I</li></ol>","xlit":"Blástos"},"G4402":{"kjv_def":"Prochorus","lemma":"Πρόχορος","translit":"Próchoros","derivation":"from G4253 (πρό) and G5525 (χορός);","strongs_def":" before the dance; Prochorus, a Christian","pron":"prokh'-or-os","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Prochorus = \"leader of the chorus\"</p><ol><li>one of the seven deacons chosen by the church at Jerusalem</li></ol>","xlit":"Próchoros"},"G5008":{"translit":"talithá","lemma":"ταλιθά","kjv_def":"talitha","strongs_def":" the fresh, i.e. young girl; talitha (O maiden)","derivation":"of Chaldee origin (compare H02924);","pron":"tal-ee-thah'","pos":"Noun Feminine","thayer":"<ol><li>damsel, maiden</li></ol>","xlit":"talithá"},"G1681":{"derivation":"of foreign origin;","strongs_def":" Elymas, a wizard","kjv_def":"Elymas","lemma":"Ἐλύμας","translit":"Elýmas","pron":"el-oo'-mas","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Elymas = \"a wise man\"</p><ol><li>the Arabic name of the Jewish magnus or sorcerer Barjesus, Act <a class='bible' href='#b58.13.6'>Heb 13:6</a></li></ol>","xlit":"Elýmas"},"G4176":{"kjv_def":"let conversation be, live","translit":"politeúomai","lemma":"πολιτεύομαι","derivation":"middle voice of a derivative of G4177 (πολίτης);","strongs_def":" to behave as a citizen (figuratively)","pron":"pol-it-yoo'-om-ahee","pos":"Verb","thayer":"<ol><li>to be a citizen</li><li>to administer civil affairs, manage the state</li><li>to make or create a citizen<ol type='a'><li>to be a citizen</li><li>to behave as a citizen<ol><li>to avail one's self of or recognise the laws</li><li>to conduct one's self as pledged to some law of life</li></ol></li></ol></li></ol>","xlit":"politeúomai"},"G1298":{"strongs_def":" to disturb wholly, i.e. agitate (with alarm)","derivation":"from G1223 (διά) and G5015 (ταράσσω);","lemma":"διαταράσσω","translit":"diatarássō","kjv_def":"trouble","pron":"dee-at-ar-as'-so","pos":"Verb","thayer":"<ol><li>to agitate greatly, trouble greatly</li></ol>","xlit":"diatarássō"},"G5137":{"derivation":"probably from G5143 (τρέχω) (through the idea of mobility);","strongs_def":" the throat (neck), i.e. (figuratively) life","kjv_def":"neck","lemma":"τράχηλος","translit":"tráchēlos","pron":"trakh'-ay-los","pos":"Noun Masculine","thayer":"<ol><li>to be ready to incur the most imminent peril to life</li></ol>","xlit":"tráchēlos"},"G4702":{"derivation":"from G4703 (σπόρος);","strongs_def":" sown, i.e. (neuter plural) a planted field","kjv_def":"corn(-field)","translit":"spórimos","lemma":"σπόριμος","pron":"spor'-ee-mos","pos":"Adjective","thayer":"<ol><li>fit for sowing, sown</li><li>sown fields, growing crops</li></ol>","xlit":"spórimos"},"G3118":{"lemma":"μακροχρόνιος","translit":"makrochrónios","kjv_def":"live long","strongs_def":" long-timed, i.e. long-lived","derivation":"from G3117 (μακρός) and G5550 (χρόνος);","pron":"mak-rokh-ron'-ee-os","pos":"Adjective","thayer":"<ol><li>long lived</li></ol>","xlit":"makrochrónios"},"G5098":{"kjv_def":"punishment","translit":"timōría","lemma":"τιμωρία","derivation":"from G5097 (τιμωρέω);","strongs_def":" vindication, i.e. (by implication) a penalty","pron":"tee-mo-ree'-ah","pos":"Noun Feminine","thayer":"<ol><li>a rendering help</li><li>assistance</li><li>vengeance, punishment, penalty</li></ol>","xlit":"timōría"},"G3788":{"derivation":"from G3700 (ὀπτάνομαι);","strongs_def":" the eye (literally or figuratively); by implication, vision; figuratively, envy (from the jealous side-glance)","kjv_def":"eye, sight","translit":"ophthalmós","lemma":"ὀφθαλμός","pron":"of-thal-mos'","pos":"Noun Masculine","thayer":"<ol><li>the eye</li><li>metaphorically the eyes of the mind, the faculty of knowing</li></ol>","xlit":"ophthalmós"},"G2868":{"lemma":"κονιορτός","translit":"koniortós","kjv_def":"dust","strongs_def":" pulverulence (as blown about)","derivation":"from the base of G2867 (κονιάω) and ornumi (to \"rouse\");","pron":"kon-ee-or-tos'","pos":"Noun Masculine","thayer":"<ol><li>raised dust, flying dust</li><li>dust</li></ol>","xlit":"koniortós"},"G4755":{"translit":"stratēgós","lemma":"στρατηγός","kjv_def":"captain, magistrate","strongs_def":" a general, i.e. (by implication or analogy) a (military) governor (prætor), the chief (præfect) of the (Levitical) temple-wardens","derivation":"from the base of G4756 (στρατιά) and G71 (ἄγω) or G2233 (ἡγέομαι);","pron":"strat-ay-gos'","pos":"Noun Masculine","thayer":"<ol><li>the commander of an army</li><li>in the NT a civic commander, a governor<ol type='a'><li>the name the highest magistrate in the municipia or colonies; they had the power of administering justice in the less important cases</li><li>of civil magistrates</li></ol><li>captain of the temple, i.e. the commander of the Levites who kept guard in and around the temple</li></ol>","xlit":"stratēgós"},"G3036":{"kjv_def":"stone, cast stones","translit":"lithoboléō","lemma":"λιθοβολέω","derivation":"from a compound of G3037 (λίθος) and G906 (βάλλω);","strongs_def":" to throw stones, i.e. lapidate","pron":"lith-ob-ol-eh'-o","pos":"Verb","thayer":"<ol><li>to kill by stoning, to stone</li><li>to pelt one with stones</li></ol>","xlit":"lithoboléō"},"G2003":{"strongs_def":" an injunction or decree; by implication, authoritativeness","derivation":"from G2004 (ἐπιτάσσω);","lemma":"ἐπιταγή","translit":"epitagḗ","kjv_def":"authority, commandment","pron":"ep-ee-tag-ay'","pos":"Noun Feminine","thayer":"<ol><li>an injunction, mandate, command</li></ol>","xlit":"epitagḗ"},"G254":{"derivation":"of uncertain derivation;","strongs_def":" a fetter or manacle","kjv_def":"bonds, chain","lemma":"ἅλυσις","translit":"hálysis","pron":"hal'-oo-sis","pos":"Noun Feminine","thayer":"<ol><li>a chain, bond by which the body or any part of it (hands, feet) is bound</li></ol>","xlit":"hálysis"},"G2651":{"strongs_def":" according to sole places, i.e. (adverbially) separately","derivation":"from G2596 (κατά) and accusative case plural feminine of G3441 (μόνος) (with G5561 (χώρα) implied);","translit":"katamónas","lemma":"καταμόνας","kjv_def":"alone","pron":"kat-am-on'-as","pos":"Adjective","thayer":"<ol><li>apart, alone</li></ol>","xlit":"katamónas"},"G5270":{"derivation":"from G5259 (ὑπό) and G2736 (κάτω);","strongs_def":" down under, i.e. beneath","kjv_def":"under","translit":"hypokátō","lemma":"ὑποκάτω","pron":"hoop-ok-at'-o","pos":"Verb","thayer":"<ol><li>under, underneath</li></ol>","xlit":"hypokátō"},"G1183":{"derivation":"from G1181 (δεκάτη);","strongs_def":" to tithe, i.e. to give or take a tenth","kjv_def":"pay (receive) tithes","translit":"dekatóō","lemma":"δεκατόω","pron":"dek-at-o'-o","pos":"Verb","thayer":"<ol><li>to exact or receive the tenth part</li><li>to pay tithes</li></ol>","xlit":"dekatóō"},"G1125":{"lemma":"γράφω","translit":"gráphō","kjv_def":"describe, write(-ing, -ten)","strongs_def":" to \"grave\", especially to write; figuratively, to describe","derivation":"a primary verb;","pron":"graf'-o","pos":"Verb","thayer":"<ol><li>to write, with reference to the form of the letters<ol type='a'><li>to delineate (or form) letters on a tablet, parchment, paper, or other material</li></ol><li>to write, with reference to the contents of the writing<ol type='a'><li>to express in written characters</li><li>to commit to writing (things not to be forgotten), write down, record</li><li>used of those things which stand written in the sacred books (of the OT)</li><li>to write to one, i.e. by writing (in a written epistle) to give information, directions</li></ol><li>to fill with writing</li><li>to draw up in writing, compose</li></ol>","xlit":"gráphō"},"G2413":{"strongs_def":" sacred","derivation":"of uncertain affinity;","lemma":"ἱερός","translit":"hierós","kjv_def":"holy","pron":"hee-er-os'","pos":"Adjective","thayer":"<ol><li>sacred, consecrated to the deity, pertaining to God<ol type='a'><li>sacred Scriptures, because inspired by God, treating of divine things and therefore to be devoutly revered</li></ol></li></ol>","xlit":"hierós"},"G96":{"translit":"adókimos","lemma":"ἀδόκιμος","kjv_def":"castaway, rejected, reprobate","strongs_def":" unapproved, i.e. rejected; by implication, worthless (literally or morally)","derivation":"from G1 (Α) (as a negative particle) and G1384 (δόκιμος);","pron":"ad-ok'-ee-mos","pos":"Adjective","thayer":"<ol><li>not standing the test, not approved<ol type='a'><li>properly used of metals and coins</li></ol><li>that which does not prove itself such as it ought<ol type='a'><li>unfit for, unproved, spurious, reprobate</li></ol></li></ol>","xlit":"adókimos"},"G4763":{"strongs_def":" to be luxurious","derivation":"from a presumed derivative of G4764 (στρῆνος);","lemma":"στρηνιάω","translit":"strēniáō","kjv_def":"live deliciously","pron":"stray-nee-ah'-o","pos":"Verb","thayer":"<ol><li>to be wanton, to live luxuriously</li></ol>","xlit":"strēniáō"},"G4232":{"derivation":"of Latin origin;","strongs_def":" the prætorium or governor's courtroom (sometimes including the whole edifice and camp)","kjv_def":"(common, judgment) hall (of judgment), palace, prætorium","lemma":"πραιτώριον","translit":"praitṓrion","pron":"prahee-to'-ree-on","pos":"Noun Neuter","thayer":"<ol><li>\"head-quarters\" in a Roman camp, the tent of the commander-in-chief</li><li>the palace in which the governor or procurator of a province resided, to which use the Romans were accustomed to appropriate the palaces already existing, and formerly dwelt in by kings or princes; at Jerusalem it was a magnificent palace which Herod the Great had built for himself, and which the Roman procurators seemed to have occupied whenever they came from Caesarea to Jerusalem to transact public business</li><li>the camp of the Praetorian soldiers established by Tiberius</li></ol>","xlit":"praitṓrion"},"G942":{"strongs_def":" a brier shrub","derivation":"of uncertain derivation;","translit":"bátos","lemma":"βάτος","kjv_def":"bramble, bush","pron":"bat'-os","pos":"Noun Masculine","thayer":"<ol><li>a thorn or bramble bush</li></ol>","xlit":"bátos"},"G2937":{"derivation":"from G2936 (κτίζω);","strongs_def":" original formation (properly, the act; by implication, the thing, literally or figuratively)","kjv_def":"building, creation, creature, ordinance","translit":"ktísis","lemma":"κτίσις","pron":"ktis'-is","pos":"Noun Feminine","thayer":"<ol><li>the act of founding, establishing, building etc<ol type='a'><li>the act of creating, creation</li><li>creation, i.e. thing created<ol><li>of individual things, beings, a creature, a creation<ol type='a'><li>anything created</li><li>after a rabbinical usage (by which a man converted from idolatry to Judaism was called)</li><li>the sum or aggregate of things created</li></ol></li></ol><li>institution, ordinance</li></ol></li></ol>","xlit":"ktísis"},"G829":{"strongs_def":" self-pleasing, i.e. arrogant","derivation":"from G846 (αὐτός) and the base of G2237 (ἡδονή);","lemma":"αὐθάδης","translit":"authádēs","kjv_def":"self-willed","pron":"ow-thad'-ace","pos":"Adjective","thayer":"<ol><li>self-pleasing, self-willed, arrogant</li></ol>","xlit":"authádēs"},"G3915":{"kjv_def":"winter in","translit":"paracheimasía","lemma":"παραχειμασία","derivation":"from G3914 (παραχειμάζω);","strongs_def":" a wintering over","pron":"par-akh-i-mas-ee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a passing the winter, wintering</li></ol>","xlit":"paracheimasía"},"G5052":{"kjv_def":"bring fruit to perfection","lemma":"τελεσφορέω","translit":"telesphoréō","derivation":"from a compound of G5056 (τέλος) and G5342 (φέρω);","strongs_def":" to be a bearer to completion (maturity), i.e. to ripen fruit (figuratively)","pron":"tel-es-for-eh'-o","pos":"Verb","thayer":"<ol><li>to bring to (perfection or) maturity<ol type='a'><li>of fruits</li><li>of pregnant women</li><li>of animals bringing their young to maturity</li></ol></li></ol>","xlit":"telesphoréō"},"G958":{"strongs_def":" Benjamin, an Israelite","derivation":"of Hebrew origin (H01144);","lemma":"Βενιαμίν","translit":"Beniamín","kjv_def":"Benjamin","pron":"ben-ee-am-een'","pos":"Noun Masculine","thayer":"<strong>Thayer Definition</strong>: Benjamin = \"son of the right hand\" or, \"son of good fortune\"</p><ol><li>Jacob's twelfth son</li><li>the tribe of Benjamin</li></ol>","xlit":"Beniamín"},"G2015":{"kjv_def":"appearing, brightness","translit":"epipháneia","lemma":"ἐπιφάνεια","derivation":"from G2016 (ἐπιφανής);","strongs_def":" a manifestation, i.e. (specially) the advent of Christ (past or future)","pron":"ep-if-an'-i-ah","pos":"Noun Feminine","thayer":"<ol><li>an appearing, appearance</li></ol>","xlit":"epipháneia"},"G741":{"lemma":"ἀρτύω","translit":"artýō","kjv_def":"season","strongs_def":" to prepare, i.e. spice (with stimulating condiments)","derivation":"from a presumed derivative of G142 (αἴρω);","pron":"ar-too'-o","pos":"Verb","thayer":"<ol><li>to prepare, arrange, with respect to food</li><li>to season, make savory</li></ol>","xlit":"artýō"},"G4110":{"derivation":"from G4111 (πλάσσω);","strongs_def":" something moulded","kjv_def":"thing formed","translit":"plásma","lemma":"πλάσμα","pron":"plas'-mah","pos":"Noun Neuter","thayer":"<ol><li>what has been moulded or formed, as from wax</li><li>the thing formed by a potter, earthen vessel</li></ol>","xlit":"plásma"},"G4960":{"strongs_def":" to file together (as soldiers in ranks), i.e. (figuratively) to correspond to","derivation":"from G4862 (σύν) and G4748 (στοιχέω);","translit":"systoichéō","lemma":"συστοιχέω","kjv_def":"answer to","pron":"soos-toy-kheh'-o","pos":"Verb","thayer":"<ol><li>to stand or march in the same row (file) with<ol type='a'><li>of soldiers</li><li>to stand over against, be parallel with</li><li>to answer to, resemble<ol><li>so once of a type in the OT which answers to the antitype in the NT</li></ol></li></ol></li></ol>","xlit":"systoichéō"},"G1177":{"kjv_def":"twelve","lemma":"δεκαδύο","translit":"dekadýo","derivation":"from G1176 (δέκα) and G1417 (δύο);","strongs_def":" two and ten, i.e. twelve","pron":"dek-ad-oo'-o","pos":"Noun","thayer":"<ol><li>twelve</li></ol>","xlit":"dekadýo"},"G765":{"kjv_def":" ungodly (man)","lemma":"ἀσεβής","translit":"asebḗs","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G4576 (σέβομαι);","strongs_def":" irreverent, i.e. (by extension) impious or wicked","pron":"as-eb-ace'","pos":"Adjective","thayer":"<ol><li>destitute of reverential awe towards God, condemning God, impious</li></ol>","xlit":"asebḗs"},"G3182":{"derivation":"a prolonged (transitive) form of G3184 (μεθύω);","strongs_def":" to intoxicate","kjv_def":"be drunk(-en)","lemma":"μεθύσκω","translit":"methýskō","pron":"meth-oos'-ko","pos":"Verb","thayer":"<ol><li>to intoxicate, make drunk</li><li>to get drunk, become intoxicated</li></ol>","xlit":"methýskō"},"G3576":{"kjv_def":"dull, slothful","lemma":"νωθρός","translit":"nōthrós","derivation":"from a derivative of G3541 (νόθος);","strongs_def":" sluggish, i.e. (literally) lazy, or (figuratively) stupid","pron":"no-thros'","pos":"Adjective","thayer":"<ol><li>slow, sluggish, indolent, dull, languid</li></ol>","xlit":"nōthrós"},"G4441":{"kjv_def":"ask, demand, enquire, understand","translit":"pynthánomai","lemma":"πυνθάνομαι","derivation":"middle voice prolonged from a primary (which occurs only as an alternate in certain tenses);","strongs_def":" to question, i.e. ascertain by inquiry (as a matter of information merely; and thus differing from G2065 (ἐρωτάω), which properly means a request as a favor; and from G154 (αἰτέω), which is strictly a demand for something due; as well as from G2212 (ζητέω), which implies a search for something hidden; and from G1189 (δέομαι), which involves the idea of urgent need); by implication, to learn (by casual intelligence)","pron":"poon-than'-om-ahee","pos":"Verb","thayer":"<ol><li>to enquire, ask</li><li>to ascertain, by enquiry</li></ol>","xlit":"pynthánomai"},"G2376":{"translit":"thyrís","lemma":"θυρίς","kjv_def":"window","strongs_def":" an aperture, i.e. window","derivation":"from G2374 (θύρα);","pron":"thoo-rece'","pos":"Noun Feminine","thayer":"<ol><li>a window</li></ol>","xlit":"thyrís"},"G381":{"lemma":"ἀνάπτω","translit":"anáptō","kjv_def":"kindle, light","strongs_def":" to enkindle","derivation":"from G303 (ἀνά) and G681 (ἅπτω);","pron":"an-ap'-to","pos":"Verb","thayer":"<ol><li>to light up, kindle</li></ol>","xlit":"anáptō"},"G3314":{"strongs_def":" midday; by implication, the south","derivation":"from G3319 (μέσος) and G2250 (ἡμέρα);","lemma":"μεσημβρία","translit":"mesēmbría","kjv_def":"noon, south","pron":"mes-ame-bree'-ah","pos":"Noun Feminine","thayer":"<ol><li>as respects to time: noon</li><li>as respects to locality<ol type='a'><li>the south</li></ol></li></ol>","xlit":"mesēmbría"},"G1372":{"derivation":"from a variation of G1373 (δίψος);","strongs_def":" to thirst for (literally or figuratively)","kjv_def":"(be, be a-)thirst(-y)","translit":"dipsáō","lemma":"διψάω","pron":"dip-sah'-o","pos":"Verb","thayer":"<ol><li>to suffer thirst, suffer from thirst<ol type='a'><li>figuratively, those who are said to thirst who painfully feel their want of, and eagerly long for, those things by which the soul is refreshed, supported, strengthened</li></ol></li></ol>","xlit":"dipsáō"},"G4445":{"derivation":"from G4443 (πυρά);","strongs_def":" to be on fire, i.e. (specially), to have a fever","kjv_def":"be sick of a fever","translit":"pyréssō","lemma":"πυρέσσω","pron":"poo-res'-so","pos":"Verb","thayer":"<ol><li>to be sick with a fever</li></ol>","xlit":"pyréssō"},"G5123":{"lemma":"τουτέστι","translit":"toutésti","kjv_def":"that is (to say)","strongs_def":" that is","derivation":"contraction for G5124 (τοῦτο) and G2076 (ἐστί);","pron":"toot-es'-tee","pos":"Conjunction","thayer":"<ol><li>that is</li></ol>","xlit":"toutésti"},"G306":{"strongs_def":" to put off (for oneself)","derivation":"middle voice from G303 (ἀνά) and G906 (βάλλω);","lemma":"ἀναβάλλομαι","translit":"anabállomai","kjv_def":"defer","pron":"an-ab-al'-lom-ahee","pos":"Verb","thayer":"<ol><li>to throw or toss up</li><li>to put back or off, delay, postpone</li></ol>","xlit":"anabállomai"},"G5340":{"strongs_def":" abstemiously, i.e. stingily","derivation":"adverb from participle of G5339 (φείδομαι);","translit":"pheidoménōs","lemma":"φειδομένως","kjv_def":"sparingly","pron":"fi-dom-en'-oce","pos":"Adverb","thayer":"<ol><li>sparingly</li></ol>","xlit":"pheidoménōs"},"G1383":{"strongs_def":" a testing; by implication, trustworthiness","derivation":"neuter of a presumed derivative of G1382 (δοκιμή);","translit":"dokímion","lemma":"δοκίμιον","kjv_def":"trial, trying","pron":"dok-im'-ee-on","pos":"Noun Neuter","thayer":"<ol><li>the proving</li><li>that by which something is tried or proved, a test</li></ol>","xlit":"dokímion"},"G4271":{"strongs_def":" plain before all men, i.e. obvious","derivation":"from G4253 (πρό) and G1212 (δῆλος);","translit":"pródēlos","lemma":"πρόδηλος","kjv_def":"evident, manifest (open) beforehand","pron":"prod'-ay-los","pos":"Adjective","thayer":"<ol><li>openly evident, known to all, manifest</li></ol>","xlit":"pródēlos"},"G1018":{"strongs_def":" to arbitrate, i.e. (genitive case) to govern (figuratively, prevail)","derivation":"from the same as G1017 (βραβεῖον);","translit":"brabeúō","lemma":"βραβεύω","kjv_def":"rule","pron":"brab-yoo'-o","pos":"Verb","thayer":"<ol><li>to be an umpire</li><li>to decide, determine</li><li>to direct, control, rule</li></ol>","xlit":"brabeúō"},"G430":{"translit":"anéchomai","lemma":"ἀνέχομαι","kjv_def":"bear with, endure, forbear, suffer","strongs_def":" to hold oneself up against, i.e. (figuratively) put up with","derivation":"middle voice from G303 (ἀνά) and G2192 (ἔχω);","pron":"an-ekh'-om-ahee","pos":"Verb","thayer":"<ol><li>to hold up</li><li>to hold one's self erect and firm</li><li>to sustain, to bear, to endure</li></ol>","xlit":"anéchomai"},"G215":{"derivation":"from G1 (Α) (as a negative particle) and a derivative of G2980 (λαλέω);","strongs_def":" unspeakable","kjv_def":"unutterable, which cannot be uttered","lemma":"ἀλάλητος","translit":"alálētos","pron":"al-al'-ay-tos","pos":"Adjective","thayer":"<ol><li>not to be uttered, not expressed in words</li></ol>","xlit":"alálētos"},"G64":{"strongs_def":" to hunt, i.e. (figuratively) to entrap","derivation":"from G61 (ἄγρα);","translit":"agreúō","lemma":"ἀγρεύω","kjv_def":"catch","pron":"ag-rew'-o","pos":"Verb","thayer":"<ol><li>to hunt, to take by hunting, catch</li><li>metaphorically to hunt after, pursue eagerly</li></ol>","xlit":"agreúō"},"G4129":{"strongs_def":" to increase (transitively or intransitively)","derivation":"from another form of G4128 (πλῆθος);","translit":"plēthýnō","lemma":"πληθύνω","kjv_def":"abound, multiply","pron":"play-thoo'-no","pos":"Verb","thayer":"<ol><li>to increase, to multiply<ol type='a'><li>to be increased, (be multiplied) multiply</li></ol><li>to be increased, to multiply</li></ol>","xlit":"plēthýnō"},"G3080":{"lemma":"λύσις","translit":"lýsis","kjv_def":"to be loosed","strongs_def":" a loosening, i.e. (specially), divorce","derivation":"from G3089 (λύω);","pron":"loo'-sis","pos":"Noun Feminine","thayer":"<ol><li>a loosing, setting free<ol type='a'><li>of a prisoner</li><li>of the bond of marriage, divorce</li></ol><li>release, ransoming, deliverance<ol type='a'><li>of liquidating a debt</li></ol><li>means or power of releasing or loosing</li></ol>","xlit":"lýsis"},"G153":{"kjv_def":"be ashamed","lemma":"αἰσχύνομαι","translit":"aischýnomai","derivation":"from (disfigurement, i.e. disgrace);","strongs_def":" to feel shame (for oneself)","pron":"ahee-skhoo'-no","pos":"Verb","thayer":"<ol><li>to disfigure</li><li>to dishonour</li><li>to suffuse with shame, make ashamed, be ashamed</li></ol>","xlit":"aischýnomai"},"G479":{"strongs_def":" to invite in return","derivation":"from G473 (ἀντί) and G2564 (καλέω);","translit":"antikaléō","lemma":"ἀντικαλέω","kjv_def":"bid again","pron":"an-tee-kal-eh'-o","pos":"Verb","thayer":"<ol><li>to invite in turn</li></ol>","xlit":"antikaléō"},"G4494":{"strongs_def":" to breeze up, i.e. (by analogy) to agitate (into waves)","derivation":"from a derivative of G4496 (ῥίπτω) (meaning a fan or bellows);","translit":"rhipízō","lemma":"ῥιπίζω","kjv_def":"toss","pron":"hrip-id'-zo","pos":"Verb","thayer":"<ol><li>to raise a breeze, put air in motion, whether for the sake of kindling a fire or cooling one's self<ol type='a'><li>to blow up a fire</li><li>to fan, i.e. cool with a fan</li></ol><li>to toss to and fro, to agitate<ol type='a'><li>of the wind</li><li>of persons whose mind wavers in uncertainty between hope and fear, between doing and not doing a thing</li></ol></li></ol>","xlit":"rhipízō"},"G279":{"lemma":"ἀμετανόητος","translit":"ametanóētos","kjv_def":"impenitent","strongs_def":" unrepentant","derivation":"from G1 (Α) (as a negative particle) and a presumed derivative of G3340 (μετανοέω);","pron":"am-et-an-o'-ay-tos","pos":"Adjective","thayer":"<ol><li>admitting no change of mind, unrepented, impenitent</li></ol>","xlit":"ametanóētos"},"G910":{"derivation":"from G907 (βαπτίζω);","strongs_def":" a baptizer, as an epithet of Christ's forerunner","kjv_def":"Baptist","lemma":"Βαπτιστής","translit":"Baptistḗs","pron":"bap-tis-tace'","pos":"Noun Masculine","thayer":"<ol><li>a baptiser</li><li>one who administers the rite of baptism</li><li>the surname of John, the forerunner of Christ</li></ol>","xlit":"Baptistḗs"},"G352":{"strongs_def":" to unbend, i.e. rise; figuratively, be elated","derivation":"from G303 (ἀνά) (in the sense of reversal) and G2955 (κύπτω);","translit":"anakýptō","lemma":"ἀνακύπτω","kjv_def":"lift up, look up","pron":"an-ak-oop'-to","pos":"Verb","thayer":"<ol><li>to raise or lift one's self up<ol type='a'><li>one's body</li><li>one's soul<ol><li>to be elated or exalted</li></ol></li></ol></li></ol>","xlit":"anakýptō"},"G5412":{"kjv_def":"lade, by heavy laden","lemma":"φορτίζω","translit":"phortízō","derivation":"from G5414 (φόρτος);","strongs_def":" to load up (properly, as a vessel or animal), i.e. (figuratively) to overburden with ceremony (or spiritual anxiety)","pron":"for-tid'-zo","pos":"Verb","thayer":"<ol><li>to place a burden upon, to load</li><li>metaphorically to load one with a burden (of rites and unwarranted precepts)</li></ol>","xlit":"phortízō"},"G370":{"strongs_def":" unfit","derivation":"from G1 (Α) (as a negative particle) and G514 (ἄξιος);","lemma":"ἀνάξιος","translit":"anáxios","kjv_def":"unworthy","pron":"an-ax'-ee-os","pos":"Adjective","thayer":"<ol><li>unworthy, unfit for a thing</li></ol>","xlit":"anáxios"},"G1084":{"strongs_def":" born","derivation":"from G1080 (γεννάω);","translit":"gennētós","lemma":"γεννητός","kjv_def":"they that are born","pron":"ghen-nay-tos'","pos":"Adjective","thayer":"<ol><li>begotten, born</li></ol>","xlit":"gennētós"},"G5353":{"derivation":"from G5350 (φθέγγομαι);","strongs_def":" utterance, i.e. a musical note (vocal or instrumental)","kjv_def":"sound","lemma":"φθόγγος","translit":"phthóngos","pron":"ftong'-gos","pos":"Noun Masculine","thayer":"<ol><li>musical sound, whether vocal or instrumental</li></ol>","xlit":"phthóngos"},"G1731":{"kjv_def":"do, show (forth)","lemma":"ἐνδείκνυμι","translit":"endeíknymi","derivation":"from G1722 (ἐν) and G1166 (δεικνύω);","strongs_def":" to indicate (by word or act)","pron":"en-dike'-noo-mee","pos":"Verb","thayer":"<ol><li>to point out<ol type='a'><li>to show, demonstrate, prove, whether by arguments or by acts</li></ol><li>to manifest, display, put forth</li></ol>","xlit":"endeíknymi"},"G5070":{"translit":"tetrakischílioi","lemma":"τετρακισχίλιοι","kjv_def":"four thousand","strongs_def":" four times a thousand","derivation":"from the multiplicative adverb of G5064 (τέσσαρες) and G5507 (χίλιοι);","pron":"tet-rak-is-khil'-ee-oy","pos":"Adjective","thayer":"<ol><li>four thousand</li></ol>","xlit":"tetrakischílioi"},"G489":{"derivation":"from a compound of G473 (ἀντί) and G3408 (μισθός);","strongs_def":" requital, correspondence","kjv_def":"recompense","translit":"antimisthía","lemma":"ἀντιμισθία","pron":"an-tee-mis-thee'-ah","pos":"Noun Feminine","thayer":"<ol><li>a reward given in compensation, requital, recompence</li></ol>","xlit":"antimisthía"}};

